# ---------- Modo trabajo (mantenimiento activable por dirección) ----------
_MAINT_CACHE = {"v": None, "t": 0.0}


def _get_app_setting(key: str, default=None):
    s = db()
    try:
        row = s.get(AppSetting, key)
        return row.value if (row and row.value is not None) else default
    except Exception:
        return default
    finally:
        try:
            s.close()
        except Exception:
            pass


def _set_app_setting(key: str, value: str):
    s = db()
    try:
        row = s.get(AppSetting, key)
        if row:
            row.value = value
            row.updated_at = datetime.utcnow()
        else:
            s.add(AppSetting(key=key, value=value))
        s.commit()
    except Exception:
        try:
            s.rollback()
        except Exception:
            pass
    finally:
        try:
            s.close()
        except Exception:
            pass


def _maintenance_active() -> bool:
    """¿La app está en «modo trabajo»? Cacheado ~8 s por worker (barato y propaga los cambios rápido)."""
    now = time.time()
    if _MAINT_CACHE["v"] is not None and (now - _MAINT_CACHE["t"]) < 8:
        return _MAINT_CACHE["v"]
    val = (_get_app_setting("maintenance_mode", "0") or "0").strip() == "1"
    _MAINT_CACHE["v"] = val
    _MAINT_CACHE["t"] = now
    return val


def _set_maintenance(active: bool):
    _set_app_setting("maintenance_mode", "1" if active else "0")
    _MAINT_CACHE["v"] = bool(active)
    _MAINT_CACHE["t"] = time.time()


def _current_is_direccion() -> bool:
    """True si el usuario logueado es DIRECCIÓN (rol real 10). Con impersonación cuenta el rol del
    impersonador (dirección), no el del impersonado."""
    if not session.get("user_id"):
        return False
    if session.get("impersonator_id"):
        try:
            return int(session.get("impersonator_role") or 0) == 10
        except Exception:
            return False
    try:
        return int(session.get("role") or 0) == 10
    except Exception:
        return False


# Endpoints que SIEMPRE funcionan aunque la app esté en modo trabajo (login de dirección, salir, el
# propio interruptor, estáticos, health y la página de mantenimiento).
_MAINT_ALLOWED_ENDPOINTS = {
    "static", "healthz", "maintenance_preview", "admin_login", "admin_logout",
    "direccion_toggle_maintenance", "landing", "password_forgot", "password_set",
}


@app.before_request
def _maintenance_gate():
    """Con el modo trabajo activo, todo el que NO sea dirección ve la página de «app en
    mantenimiento». Dirección trabaja con normalidad. Los anónimos pasan (los redirige el login,
    que muestra el aviso y solo deja entrar a dirección)."""
    if not _maintenance_active():
        return
    if (request.endpoint or "") in _MAINT_ALLOWED_ENDPOINTS:
        return
    if _current_is_direccion():
        return
    if session.get("user_id"):
        return _render_maintenance_page(503)
    return


@app.errorhandler(RequestEntityTooLarge)
def _handle_request_entity_too_large(exc):
    # La app no limita el tamaño de subida (MAX_CONTENT_LENGTH = None). Si aun así llega un 413,
    # suele venir de un proxy/servidor delante; se informa sin culpar al usuario.
    flash("La subida no se pudo completar por una limitación del servidor. Si el archivo es muy grande, inténtalo de nuevo; si vuelve a fallar, avísanos.", "danger")
    return redirect(request.referrer or url_for("discografica_view", section="canciones"))


def _error_back_url():
    """URL a la que apunta el botón «Volver» de las pantallas de error: la pantalla anterior
    (referrer del mismo host, distinta de la actual) o el inicio como último recurso."""
    ref = request.referrer
    try:
        if ref and ref.startswith(request.host_url) and ref != request.url:
            return ref
    except Exception:
        pass
    try:
        return url_for("home")
    except Exception:
        return "/"


def _is_xhr_request() -> bool:
    """¿La petición viene de un XHR/fetch del propio front? (cabecera `X-Requested-With`).

    Es DISTINTO de `_wants_json_response()`, que mira si el cliente PIDE json (`Accept` / `is_json`).
    Antes había dos funciones llamadas `_wants_json_response` con estas dos semánticas y, como en
    Python la última `def` pisa a la anterior, esta de aquí no se ejecutaba nunca: quien dependía de
    la cabecera se llevaba una respuesta HTML sin enterarse. Ahora cada cosa tiene su nombre.
    """
    return request.headers.get("X-Requested-With") == "XMLHttpRequest"


def _render_error_page(code: int, title: str, default_message: str):
    """Página de error con botón «Volver». Para peticiones AJAX/JSON devuelve JSON."""
    # Si venía un flash de error (p. ej. de forbid()), se usa como mensaje concreto.
    message = default_message
    try:
        flashed = [m for cat, m in get_flashed_messages(with_categories=True) if cat in ("danger", "warning", "error")]
        if flashed:
            message = flashed[-1]
    except Exception:
        pass
    if _wants_json_response():
        return jsonify({"ok": False, "error": code, "message": message}), code
    try:
        return render_template("error.html", code=code, title=title, message=message, back_url=_error_back_url()), code
    except Exception:
        # Fallback ultra-defensivo: nunca dejar sin salida (evita recursión si falla el render).
        return (
            f"<!doctype html><meta charset='utf-8'><title>{code}</title>"
            f"<div style='font-family:sans-serif;max-width:520px;margin:15vh auto;text-align:center'>"
            f"<h1>{code}</h1><p>{message}</p>"
            f"<p><a href='javascript:history.back()'>&larr; Volver</a> · <a href='/'>Inicio</a></p></div>"
        ), code


def _render_maintenance_page(code: int = 503):
    """Página animada de «estamos trabajando» (colores corporativos + iconos de música/fiesta/verano/
    conciertos) para cuando la web está caída o da un error de servidor. Es AUTÓNOMA
    (`static/maintenance.html`: banner e iconos embebidos, sin CDN ni /static) para que se vea aunque
    falle todo. Para peticiones AJAX/JSON devuelve JSON, para no romper el front."""
    if _wants_json_response():
        return jsonify({"ok": False, "error": code,
                        "message": "Estamos trabajando en la web. Inténtalo de nuevo en un rato."}), code
    try:
        resp = app.send_static_file("maintenance.html")
        resp.status_code = code
        resp.headers["Cache-Control"] = "no-store"      # no cachear una respuesta de error
        return resp
    except Exception:
        return _render_error_page(code, "Estamos trabajando",
                                  "Estamos trabajando en cosas muy chulas. Inténtalo de nuevo en un rato.")


@app.get("/mantenimiento", endpoint="maintenance_preview")
def maintenance_preview():
    """Vista pública de la página de «estamos trabajando» (para previsualizarla y para poder
    apuntar ahí la página de mantenimiento del proveedor si se quiere)."""
    return app.send_static_file("maintenance.html")


@app.errorhandler(403)
def _handle_403(e):
    return _render_error_page(403, "Acceso no permitido", "No tienes permiso para acceder a esta página.")


@app.errorhandler(404)
def _handle_404(e):
    return _render_error_page(404, "Página no encontrada", "La página que buscas no existe o se ha movido.")


@app.errorhandler(500)
def _handle_500(e):
    # Ante un error del servidor mostramos la página animada de «estamos trabajando» (la web se
    # percibe como "caída"), con reintento automático.
    return _render_maintenance_page(500)


