def _parse_share_pairs(ids_list, pct_list):
    """Normaliza y DEDUPLICA: el último gana; % en [0..100]."""
    dedup = {}
    for sid, pct in zip(ids_list or [], pct_list or []):
        sid = (sid or "").strip()
        if not sid:
            continue
        try:
            v = int(pct)
        except Exception:
            v = 0
        v = max(0, min(100, v))
        dedup[sid] = v
    return list(dedup.items())

def _replace_concert_shares(session, concert_id, promoter_pairs, company_pairs):
    """Reemplaza participaciones evitando UNIQUE (DELETE -> FLUSH -> INSERT)."""
    session.query(ConcertPromoterShare).filter_by(concert_id=concert_id).delete(synchronize_session=False)
    session.query(ConcertCompanyShare).filter_by(concert_id=concert_id).delete(synchronize_session=False)
    session.flush()
    for pid, pct in promoter_pairs:
        session.add(ConcertPromoterShare(concert_id=concert_id, promoter_id=to_uuid(pid), pct=pct))
    for gid, pct in company_pairs:
        session.add(ConcertCompanyShare(concert_id=concert_id, company_id=to_uuid(gid), pct=pct))

def _parse_optional_positive_int(value):
    """
    Devuelve un int > 0 o None si vacío/0/no-numérico.
    """
    try:
        n = int((value or "").strip())
        return n if n > 0 else None
    except Exception:
        return None
    
# ---------- context ----------
def _asset_version() -> str:
    """La versión de los ficheros estáticos: la FECHA del más reciente (CSS y JS).

    ⚠️⚠️ Antes era la hora de ARRANQUE, y eso rompía la caché del navegador todo el rato: cada
    worker de gunicorn arranca en un instante distinto, así que la MISMA página servía
    `styles.css?v=…` con un número u otro según a qué worker cayera. El navegador no podía cachear
    nada y **se descargaba el CSS entero en cada carga** — de ahí el parpadeo de ver la página SIN
    ESTILOS un segundo, y que todo tardara más (bug real, con captura).
    Con la fecha de los ficheros, todos los workers dan lo MISMO y solo cambia cuando el CSS o el JS
    cambian de verdad, que es justo lo que hace falta para romper la caché en un despliegue."""
    ultimo = 0.0
    try:
        base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "static")
        for carpeta in ("css", "js"):
            ruta = os.path.join(base, carpeta)
            if not os.path.isdir(ruta):
                continue
            for nombre in os.listdir(ruta):
                if nombre.endswith((".css", ".js")):
                    ultimo = max(ultimo, os.path.getmtime(os.path.join(ruta, nombre)))
    except Exception:
        pass
    return str(int(ultimo)) if ultimo else str(int(time.time()))


_ASSET_VERSION = _asset_version()        # la fecha del CSS/JS más reciente (igual en todos los workers)


@app.context_processor
def inject_globals():
    def has_endpoint(name: str) -> bool:
        # permite: {% if has_endpoint('mi_vista') %} ...
        return name in app.view_functions

    def _artist_photo_src(photo_url=None):
        return photo_url or url_for("static", filename="img/logo.png")

    def artist_avatar(photo_url=None, name="", cls="artist-avatar-inline", artist_id=None):
        # Solo la foto del artista en círculo (sin nombre); para ponerla delante de un nombre ya escrito.
        # Si se pasa artist_id, se marca con data-artist-link para que al pincharla lleve a su ficha
        # (lo enlaza artist_links.js; no cambia el aspecto, solo añade el cursor de mano).
        link = (Markup(' data-artist-link="%s"') % str(artist_id)) if artist_id else Markup("")
        return Markup('<img class="%s"%s src="%s" alt="" title="%s" loading="lazy">') % (
            cls, link, _artist_photo_src(photo_url), (name or ""),
        )

    def artist_chip(name, photo_url=None, artist_id=None):
        # Foto en círculo + nombre en una cápsula (.artist-chip). Devuelve '' si no hay nombre.
        # Con artist_id, la cápsula entera enlaza a la ficha del artista (data-artist-link).
        name = (name or "").strip()
        if not name:
            return Markup("")
        link = (Markup(' data-artist-link="%s"') % str(artist_id)) if artist_id else Markup("")
        return Markup('<span class="artist-chip"%s><img src="%s" alt="" loading="lazy">%s</span>') % (
            link, _artist_photo_src(photo_url), name,
        )

    def _company_bits(company=None, name=None, logo_url=None):
        nombre = (name if name is not None else getattr(company, "name", "")) or ""
        logo = (logo_url if logo_url is not None else getattr(company, "logo_url", "")) or ""
        return str(nombre).strip(), str(logo).strip().rstrip("?")

    def one_stop_badge(cls=""):
        """La etiqueta **ONE-STOP**, igual en TODA la app.

        ⚠️ Punto único a propósito: estaba escrita a mano en tres plantillas y en una llevaba `fa`
        en vez de `fa-solid`, así que **salía sin icono** (bug real). Con un global no se pueden
        desparejar."""
        return Markup(
            '<span class="badge badge-onestop %s" title="One-stop: el máster es 100%% nuestro, no '
            'hay intérpretes de fuera y la autoría es toda de Plataforma Musical. Se puede licenciar '
            'para una sincronización sin pedir permiso a nadie.">'
            '<i class="fa-solid fa-clapperboard"></i>One-stop</span>') % (cls or "")

    def explicit_badge(cls=""):
        """La etiqueta **EXPLÍCITO**, igual en TODA la app (y con el MISMO texto en el correo, el
        PDF y los enlaces, que la componen con `EXPLICIT_LABEL`).

        ⚠️ Solo se pinta cuando la canción ES explícita: si no lo es —o no se ha decidido— no se
        enseña nada. En Syncros va DESPUÉS de las etiquetas de género y con su propio color, para no
        confundirla con ellas."""
        return Markup('<span class="badge badge-explicit %s" title="Contenido explícito">'
                      '<i class="fa-solid fa-e"></i>%s</span>') % (cls or "", EXPLICIT_LABEL)

    def company_logo(company=None, name=None, logo_url=None, size=40, cls="co-logo"):
        """El LOGO de una empresa del grupo y, si todavía no tiene, un ICONO de empresa.

        ⚠️ Antes se caía al logo de Treinta y Tres / PIES, que es peor que no enseñar nada: una
        empresa nueva aparecía con el logo de OTRA. El hueco se conserva (no se omite) para que la
        fila no se descoloque, con el icono dentro."""
        nombre, logo = _company_bits(company, name, logo_url)
        px = int(size or 40)
        if logo:
            # ⚠️ SIN `background:#fff`: el logo se integra con el fondo de donde esté. Y se sirve por
            # `_logo_clean_url`, que le quita el fondo blanco a los PNG que lo traen horneado.
            return Markup('<img class="%s" src="%s" alt="%s" title="%s" loading="lazy" '
                          'style="width:%dpx;height:%dpx;object-fit:contain;">') % (
                cls, _logo_clean_url(logo), nombre, nombre, px, px)
        return Markup('<span class="%s co-logo--empty" title="%s" '
                      'style="width:%dpx;height:%dpx;font-size:%dpx;">'
                      '<i class="fa fa-building"></i></span>') % (cls, nombre, px, px, max(12, px // 2))

    def company_chip(company=None, name=None, logo_url=None, size=28):
        """Logo (o icono) + NOMBRE de la empresa del grupo, en una cápsula."""
        nombre, logo = _company_bits(company, name, logo_url)
        if not nombre:
            return Markup("")
        return Markup('<span class="co-chip">%s<span class="co-chip__name">%s</span></span>') % (
            company_logo(name=nombre, logo_url=logo, size=size, cls="co-chip__logo"), nombre)

    return dict(
        BRAND_PRIMARY=settings.BRAND_PRIMARY,
        BRAND_ACCENT=settings.BRAND_ACCENT,
        company_logo=company_logo,
        one_stop_badge=one_stop_badge,
        explicit_badge=explicit_badge,
        company_chip=company_chip,
        IS_ADMIN=bool(session.get("user_id")),
        has_endpoint=has_endpoint,
        # Versión de ESTÁTICOS (cambia en cada arranque/deploy): rompe la caché del navegador de
        # css/js — sin esto, Flask cachea 12 h y los usuarios no ven los cambios recién subidos.
        ASSET_V=_ASSET_VERSION,
        artist_chip=artist_chip,
        artist_avatar=artist_avatar,
        # La imagen de la previsualización de un enlace interno (el icono de la casa a 1200×630).
        OG_DEFAULT_IMAGE=_external_url_for("og_default_image"),
        # El icono de un tipo de proyecto discográfico («Single + Videoclip» son dos iconos y un +).
        disco_kind_icon=_disco_kind_icon_html,
        # CARTELERÍA: de qué es un cartel (IMAGE | VIDEO | PDF), para pintarlo como toca.
        artwork_kind=_artwork_kind_of,
        artwork_category=_artwork_asset_category,
        linked_mini=linked_mini,
        # DIRECCIÓN FISCAL: se pide en piezas (Holded las necesita separadas) y se muestra junta.
        fiscal_parts=_fiscal_parts_for_form,
        fiscal_address_text=_fiscal_address_text,
        # Una dirección cualquiera: junta para mostrarla y en piezas cuando hace falta el municipio,
        # la provincia o el país por separado.
        address_text=_address_text,
        address_parts=_address_parts,
        CONCERT_CONTACT_ROLES=CONCERT_CONTACT_ROLES,
        AGENDA_KIND_ORDER=AGENDA_KIND_ORDER,
        AGENDA_KIND_META=AGENDA_KIND_META,
        SIM_EXPENSE_CATEGORIES=SIM_EXPENSE_CATEGORIES,
        SIM_EXPENSE_CATEGORY_LABELS=SIM_EXPENSE_CATEGORY_LABELS,
        SIM_EXPENSE_CATEGORY_ICONS=SIM_EXPENSE_CATEGORY_ICONS,
        SIM_EXPENSE_QTY_CATEGORIES=SIM_EXPENSE_QTY_CATEGORIES,
        ROLE=current_role(),
        ROLE_LABEL=ROLE_LABELS.get(current_role(), str(current_role())),
        CAN_VIEW_ECON=can_view_economics(),
        CAN_EDIT_RADIO=can_edit_radio(),
        CAN_EDIT_SALES=can_edit_sales(),
        CAN_EDIT_CONCERTS=can_edit_concerts(),
        # Sacar a la venta es de TICKETING: su propio permiso, no el de editar la actividad.
        CAN_SET_ONSALE=can_set_concert_onsale(),
        CAN_VIEW_CONCERT_CONTRACTS=can_view_concert_contracts(),
        CAN_EDIT_CATALOGS=can_edit_catalogs(),
        CAN_EDIT_SONGS_PROMOTERS=(can_edit_catalogs() or can_edit_discografica()),
        CAN_EDIT_DISCOGRAFICA=can_edit_discografica(),
        CAN_EDIT_SYNCROS=can_edit_syncros(),
        CAN_EDIT_ARTISTS_STATIONS=can_edit_artists_stations(),
        IS_MASTER=is_master()
    )

# ---------- health check ----------
@app.get("/healthz")
def healthz():
    # Health check para Render (Settings → Health Check Path = /healthz): responde AL INSTANTE y
    # SIN tocar la BD. Así el balanceador distingue «instancia viva» de «threads ocupados», reinicia
    # solo instancias realmente colgadas y valida los deploys contra algo fiable (no contra páginas
    # que dependen de la BD).
    #
    # ⚠️ Mientras se está APLICANDO EL ESQUEMA responde 503: Render entonces NO manda tráfico a esta
    # instancia y la gente sigue en la vieja, que funciona. Es lo que hace que subir algo no se note
    # (antes la instancia decía «estoy bien» a los 2 segundos y atendía a medio migrar).
    if not _schema_is_ready():
        return ("aplicando la actualizacion", 503,
                {"Content-Type": "text/plain", "Cache-Control": "no-store", "Retry-After": "10"})
    return ("ok", 200, {"Content-Type": "text/plain", "Cache-Control": "no-store"})


