def _serialize_promoter_contact(row: PromoterContact | None) -> dict:
    if not row:
        return {}
    return {
        'id': str(row.id),
        'title': (row.title or '').strip(),
        'first_name': (row.first_name or '').strip(),
        'last_name': (row.last_name or '').strip(),
        'email': (row.email or '').strip(),
        'phone': (row.phone or '').strip(),
        'mobile': (row.mobile or '').strip(),
    }


def _contact_display_name(contact: PromoterContact | None) -> str:
    if not contact:
        return ''
    return ' '.join([x for x in [(contact.first_name or '').strip(), (contact.last_name or '').strip()] if x]).strip()


def _contact_share_text(contact: PromoterContact | None, promoter: Promoter | None = None) -> str:
    if not contact:
        return ''
    lines = []
    if promoter and getattr(promoter, 'nick', None):
        lines.append(f'Tercero: {promoter.nick}')
    if getattr(contact, 'title', None):
        lines.append(f'Título: {contact.title}')
    name = _contact_display_name(contact)
    if name:
        lines.append(f'Contacto: {name}')
    if getattr(contact, 'email', None):
        lines.append(f'Email: {contact.email}')
    if getattr(contact, 'phone', None):
        lines.append(f'Teléfono fijo: {contact.phone}')
    if getattr(contact, 'mobile', None):
        lines.append(f'Teléfono móvil: {contact.mobile}')
    return '\n'.join(lines)


def _smtp_enabled() -> bool:
    return bool((os.getenv('SMTP_HOST') or '').strip())


def _html_to_text(html: str) -> str:
    """La versión en TEXTO de un correo HTML: lo que dice, con los enlaces a la vista.

    Un correo cuya parte de texto no dice lo mismo que el HTML (o es un «este mensaje contiene una
    versión HTML») puntúa como spam en Gmail y en Outlook. Esto no pretende ser un navegador: quita
    el marcado, saca los `href` entre paréntesis y deja los saltos donde tocan."""
    txt = (html or "")
    txt = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", txt)
    # Un enlace se convierte en «texto (url)», que es lo que se puede leer y pinchar en texto plano.
    txt = re.sub(r'(?is)<a\b[^>]*href=["\']([^"\']+)["\'][^>]*>(.*?)</a>',
                 lambda m: "%s (%s)" % (re.sub(r"(?s)<[^>]+>", "", m.group(2)).strip(), m.group(1).strip()),
                 txt)
    txt = re.sub(r"(?i)<br\s*/?>", "\n", txt)
    txt = re.sub(r"(?i)</(p|div|tr|h[1-6]|li|table)>", "\n", txt)
    txt = re.sub(r"(?i)<li[^>]*>", "· ", txt)
    txt = re.sub(r"(?s)<[^>]+>", " ", txt)
    txt = unescape(txt)
    txt = re.sub(r"[ \t\xa0]+", " ", txt)
    txt = re.sub(r" +([.,;:!?)])", r"\1", txt)      # «el lunes .» → «el lunes.» (el hueco de la etiqueta)
    txt = re.sub(r"\n\s*\n\s*\n+", "\n\n", txt)
    lineas = [l.strip() for l in txt.split("\n")]
    return "\n".join(lineas).strip() or "Abre este mensaje en un cliente que muestre HTML."


def _send_optional_email(
    to_email: str | list[str] | tuple[str, ...] | set[str],
    subject: str,
    html_body: str,
    text_body: str | None = None,
    reply_to: str | None = None,
    attachments: list[dict] | None = None,
) -> tuple[bool, str | None]:
    raw_recipients: list[str] = []
    if isinstance(to_email, (list, tuple, set)):
        iterable = list(to_email)
    else:
        iterable = [to_email]

    for value in iterable:
        for chunk in re.split(r'[;,\n]+', str(value or '')):
            email = chunk.strip()
            if email:
                raw_recipients.append(email)

    recipients: list[str] = []
    seen: set[str] = set()
    for email in raw_recipients:
        key = email.lower()
        if key in seen:
            continue
        seen.add(key)
        recipients.append(email)

    if not recipients:
        return False, 'No se indicó email destino.'
    host = (os.getenv('SMTP_HOST') or '').strip()
    if not host:
        return False, 'SMTP_HOST no configurado.'

    port = int((os.getenv('SMTP_PORT') or '587').strip() or '587')
    username = (os.getenv('SMTP_USERNAME') or '').strip()
    password = (os.getenv('SMTP_PASSWORD') or '').strip()
    sender = (os.getenv('SMTP_FROM_EMAIL') or username or '').strip()
    # ⚠️ El nombre que se ve. Sin variable puesta era «Radio Spins App», una marca que el que lo
    # recibe no conoce: eso solo puede ayudar a que parezca phishing.
    sender_name = (os.getenv('SMTP_FROM_NAME') or '33 Producciones').strip()
    use_ssl = _truthy(os.getenv('SMTP_SSL'))
    use_tls = not use_ssl if os.getenv('SMTP_TLS') is None else _truthy(os.getenv('SMTP_TLS'))

    effective_reply_to = (reply_to or _current_user_email() or '').strip()
    reply_to_header = ''
    if effective_reply_to:
        reply_name = effective_reply_to.split('@', 1)[0].strip() if '@' in effective_reply_to else effective_reply_to
        reply_to_header = formataddr((reply_name, effective_reply_to)) if reply_name else effective_reply_to

    # ⚠️ El DOMINIO del Message-ID y del From tienen que ser el mismo para que DKIM/DMARC cuadren.
    dominio_from = (sender.split('@', 1)[1].strip() if '@' in (sender or '') else '') or None

    def _compone(destinatario: str) -> EmailMessage:
        """UN correo para UNA persona (ver arriba por qué no se manda uno para todos)."""
        msg = EmailMessage()
        msg['Subject'] = subject
        msg['From'] = formataddr((sender_name, sender)) if sender else sender_name
        msg['To'] = destinatario
        if reply_to_header:
            msg['Reply-To'] = reply_to_header
        # Cabeceras que los filtros ESPERAN encontrar: sin Date y sin Message-ID el correo puntúa
        # como sospechoso (muchos relés los añaden, pero no todos).
        msg['Date'] = formatdate(localtime=True)
        msg['Message-ID'] = make_msgid(domain=dominio_from)
        # Es un aviso de una máquina: así los servidores no le contestan con autorespuestas ni lo
        # tratan como correo escrito a mano.
        msg['Auto-Submitted'] = 'auto-generated'
        msg['X-Auto-Response-Suppress'] = 'All'
        # La versión de TEXTO se saca del propio HTML: un correo cuya parte de texto no dice lo mismo
        # (o es un «este mensaje contiene una versión HTML») es una señal clásica de spam.
        msg.set_content(text_body or _html_to_text(html_body))
        msg.add_alternative(html_body, subtype='html')
        for attachment in attachments or []:
            if not isinstance(attachment, dict):
                continue
            data = attachment.get('data')
            if not data:
                continue
            filename = (attachment.get('filename') or 'adjunto').strip() or 'adjunto'
            mimetype = (attachment.get('mimetype') or 'application/octet-stream').strip()
            maintype, _sep, subtype = mimetype.partition('/')
            maintype = maintype or 'application'
            subtype = subtype or 'octet-stream'
            msg.add_attachment(data, maintype=maintype, subtype=subtype, filename=filename)
        return msg

    # ⚠️ UN CORREO POR PERSONA, no uno con veinte direcciones en el «Para». Meterlas todas juntas
    # (a) parece un envío masivo y va derecho a spam, (b) le enseña a cada uno la dirección de los
    # demás y (c) si una rebota, castiga a todo el envío. Se manda por UNA sola conexión SMTP, así
    # que no es más lento en la práctica.
    try:
        if use_ssl:
            smtp = smtplib.SMTP_SSL(host, port, timeout=30)
        else:
            smtp = smtplib.SMTP(host, port, timeout=30)
        with smtp:
            if not use_ssl and use_tls:
                smtp.starttls()
            if username:
                smtp.login(username, password)
            fallos = []
            for destinatario in recipients:
                try:
                    smtp.send_message(_compone(destinatario), to_addrs=[destinatario])
                except Exception as exc:
                    fallos.append('%s: %s' % (destinatario, exc))
        if fallos and len(fallos) == len(recipients):
            return False, '; '.join(fallos)[:500]
        if fallos:
            # Salió para unos y no para otros: se dice, no se da por bueno del todo.
            app.logger.warning('[correo] no salió para %s', '; '.join(fallos)[:300])
            return True, 'No salió para: ' + '; '.join(fallos)[:300]
        return True, None
    except Exception as exc:
        return False, str(exc)


def _public_base_url() -> str:
    """Base ABSOLUTA (https://dominio) para TODO enlace que se comparte o sale por correo.

    Manda el **dominio canónico** (`CANONICAL_HOST`, hoy `app.33producciones.es`) — el mismo al que
    redirige la app — y solo si no lo hubiera se usa `EXTERNAL_BASE_URL` y, en último caso, el host de
    la petición.
    ⚠️ Antes ganaba `EXTERNAL_BASE_URL`, así que una variable de entorno olvidada en el servidor con
    el dominio ANTIGUO hacía salir TODOS los enlaces compartidos con ese dominio (bug real). Con este
    orden, cambiar de dominio es cambiar UNA variable (`CANONICAL_HOST`), la misma que decide la
    redirección, y no pueden quedar desparejadas.
    ⚠️ La URL vieja de Render (`*.onrender.com`) nunca vale para un enlace que se comparte."""
    def _limpia(valor: str) -> str:
        valor = (valor or "").strip().rstrip("/")
        if not valor:
            return ""
        return "" if ".onrender.com" in valor.lower() else valor

    if _CANONICAL_HOST:
        base = _limpia("https://" + _CANONICAL_HOST)
        if base:
            return base
    base = _limpia(os.getenv("EXTERNAL_BASE_URL") or "")
    if base:
        return base
    try:
        return _limpia(request.url_root) or (request.url_root or "").strip().rstrip("/")
    except Exception:
        return ""


def _external_url_for(endpoint: str, **values) -> str:
    # Base fija (host canónico o EXTERNAL_BASE_URL) para enlaces que se comparten / salen por correo:
    # el dominio no depende de la cabecera Host de la petición (evita dominios equivocados y
    # suplantación). Ver _public_base_url.
    return _public_base_url() + url_for(endpoint, **values)


def _absolute_media_url(url: str) -> str:
    """Convierte una URL en absoluta (https). Necesario para las imágenes de previsualización
    (og:image de WhatsApp/SMS): una ruta relativa (p. ej. /static/...) no se previsualiza.
    También recorta el «?» final vacío que storage3 0.7.x dejaba en las URLs públicas guardadas
    (algunos clientes de correo/previsualizadores lo digieren mal)."""
    url = (url or "").strip().rstrip("?")
    if not url:
        return ""
    if url.startswith(("http://", "https://")):
        return url
    if url.startswith("//"):
        return "https:" + url
    base = _public_base_url()
    return base + (url if url.startswith('/') else '/' + url)


def _parse_uuid_list(values) -> list[str]:
    out = []
    seen = set()
    for raw in values or []:
        raw = (raw or '').strip()
        if not raw:
            continue
        try:
            val = str(to_uuid(raw))
        except Exception:
            continue
        if val in seen:
            continue
        seen.add(val)
        out.append(val)
    return out


# Qué es cada cartel. ⚠️ Un cartel puede ser un VÍDEO: los anuncios de redes lo son casi siempre.
ARTWORK_VIDEO_EXTS = {'.mp4', '.mov', '.webm', '.m4v', '.avi', '.mkv', '.mpeg', '.mpg'}
# Piezas que NO se pintan y solo se descargan: el vectorial de imprenta de un logo y los paquetes.
ARTWORK_FILE_EXTS = {'.ai', '.eps', '.zip', '.psd', '.indd'}


def _artwork_asset_kind(filename: str, mime: str = '') -> str:
    """IMAGE | VIDEO | PDF | FILE, por la extensión (y por el mimetype como respaldo).

    **FILE** es lo que no se puede pintar y solo se descarga: el vectorial de imprenta de un logo
    (.ai, .eps) o un paquete con todos sus formatos (.zip). Se ve con su icono y **no puede ser el
    principal** (`_artwork_can_be_primary` exige IMAGE).
    ⚠️ Vale igual con un nombre de archivo o con una URL: se le quita la cola (`?…`), que en las de
    Storage siempre está —`get_public_url` deja incluso el «?» suelto— y dejaría la extensión sin
    reconocer."""
    fname = (filename or '').lower().strip().split('?', 1)[0].split('#', 1)[0]
    ext = os.path.splitext(fname)[1]
    if ext == '.pdf' or (mime or '').strip().lower() == 'application/pdf':
        return 'PDF'
    if ext in ARTWORK_VIDEO_EXTS or (mime or '').strip().lower().startswith('video/'):
        return 'VIDEO'
    if ext in ARTWORK_FILE_EXTS:
        return 'FILE'
    return 'IMAGE'


def _upload_artwork_file(file_storage):
    """Sube UN cartel y devuelve (url, mime, kind).

    ⚠️ Un VÍDEO no puede pasar por `upload_image` (convierte y valida como imagen): va por
    `upload_file`, que lo guarda tal cual y admite archivos grandes sin cargarlos en memoria."""
    if not file_storage or not getattr(file_storage, 'filename', ''):
        return None, None, 'IMAGE'
    fname = (file_storage.filename or '').lower().strip()
    mime = (getattr(file_storage, 'mimetype', '') or '').strip() or None
    kind = _artwork_asset_kind(fname, mime or '')
    if kind == 'PDF':
        return upload_pdf(file_storage, 'concert_artwork'), 'application/pdf', 'PDF'
    if kind == 'VIDEO':
        return (upload_file(file_storage, 'concert_artwork',
                            allowed_extensions=ARTWORK_VIDEO_EXTS), mime, 'VIDEO')
    if kind == 'FILE':
        # Un logo vectorial (.ai/.eps) o un paquete (.zip): se guarda tal cual para descargarlo.
        return (upload_file(file_storage, 'concert_artwork',
                            allowed_extensions=ARTWORK_FILE_EXTS), mime, 'FILE')
    return upload_image(file_storage, 'concert_artwork'), mime, 'IMAGE'


def _artwork_kind_of(asset) -> str:
    """IMAGE | VIDEO | PDF | FILE de un cartel YA guardado (punto único; global `artwork_kind`).

    ⚠️ Manda la columna `kind`, pero los carteles ANTERIORES a esa columna salen todos como IMAGE
    (es su valor por defecto), así que si el nombre o el mimetype dicen otra cosa, mandan ellos."""
    kind = (getattr(asset, 'kind', '') or '').strip().upper()
    if kind in ('VIDEO', 'PDF', 'FILE'):
        return kind
    return _artwork_asset_kind((getattr(asset, 'original_name', None) or getattr(asset, 'file_url', None) or ''),
                               getattr(asset, 'mime_type', None) or '')


def _artwork_image_src(asset) -> str:
    """La URL del cartel que se puede usar COMO IMAGEN (miniatura, previsualización de un enlace).

    Un vídeo no es una imagen: se usa su miniatura, y si todavía no la tiene, no hay imagen."""
    if asset is None:
        return ''
    kind = _artwork_kind_of(asset)
    if kind == 'VIDEO':
        return (getattr(asset, 'poster_url', None) or '').strip()
    if kind == 'PDF':
        return ''
    return (getattr(asset, 'file_url', None) or '').strip()


def _artwork_can_be_primary(asset) -> bool:
    """El cartel PRINCIPAL representa la actividad (miniatura del enlace, avisos): es una IMAGEN."""
    return _artwork_kind_of(asset) == 'IMAGE'


def _concert_artwork_snapshot(concert: Concert | None) -> dict:
    if not concert:
        return {}
    return {
        'date': concert.date.isoformat() if getattr(concert, 'date', None) else '',
        'venue': _concert_venue_name(concert),
        'municipality': _concert_city(concert),
        'province': _concert_province_value(concert),
        'show_time': '' if getattr(concert, 'show_time_tbc', False) else ((getattr(concert, 'show_time', None) or '').strip()),
        'doors_time': '' if getattr(concert, 'doors_time_tbc', False) else ((getattr(concert, 'doors_time', None) or '').strip()),
    }


def _archive_current_artwork_assets(row: ConcertArtworkRequest | None):
    if not row:
        return 0
    now = datetime.now(ZoneInfo('Europe/Madrid'))
    archived = 0
    for asset in list(getattr(row, 'assets', None) or []):
        if bool(getattr(asset, 'is_archived', False)):
            continue
        asset.is_archived = True
        asset.archived_at = now
        archived += 1
    return archived


def _build_artwork_request_email(concert: Concert, row: ConcertArtworkRequest, selected_company_names: list[str], selected_ticketer_names: list[str], upload_url: str, is_update: bool = False) -> tuple[str, str, str]:
    logo_html = ''
    if concert.billing_company and getattr(concert.billing_company, 'logo_url', None):
        logo_html = f'<div style="margin-bottom:20px;"><img src="{concert.billing_company.logo_url}" style="max-height:64px;max-width:220px;"></div>'
    artist_photo = ''
    if concert.artist and getattr(concert.artist, 'photo_url', None):
        artist_photo = f'<img src="{concert.artist.photo_url}" style="width:74px;height:74px;object-fit:cover;border-radius:50%;">'
    deadline_txt = row.delivery_deadline.strftime('%d/%m/%Y') if row.delivery_deadline else 'Sin fecha máxima indicada'
    logos_txt = ', '.join(selected_company_names) if selected_company_names else 'No se han marcado logos de empresas del grupo'
    ticketers_txt = ', '.join(selected_ticketer_names) if selected_ticketer_names else 'No se han marcado ticketeras'
    format_labels = _artwork_requested_format_labels(row)
    formats_txt = ', '.join(format_labels) if format_labels else 'Formatos habituales (no se marcaron formatos concretos)'
    _vfmt = _artwork_video_format_labels(row)
    video_txt = ''
    if getattr(row, 'video_requested', False):
        video_txt = 'Sí · ' + (', '.join(_vfmt) if _vfmt else 'formato por concretar')
        if getattr(row, 'video_notes', None):
            video_txt += ' — ' + (row.video_notes or '')
    mod_html = '<p><span style="display:inline-block;background:#f59e0b;color:#111827;padding:4px 10px;border-radius:999px;font-weight:700;">MODIFICACIONES</span></p>' if is_update else ''
    mod_text = 'Solicitud actualizada de cartelería' if is_update else 'Solicitud de cartelería'
    html_body = (
        f'<div style="font-family:Arial,sans-serif;color:#1f2937;">{logo_html}'
        f'<h2 style="margin:0 0 16px;">Solicitud de cartelería</h2>{mod_html}'
        f'<div style="border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:18px;">'
        f'<div style="display:flex;gap:16px;align-items:center;"><div>{artist_photo}</div><div>'
        f'<div style="font-size:18px;font-weight:700;">{concert.artist.name if concert.artist else "Concierto"}</div>'
        f'<div>Fecha: {concert.date.strftime("%d/%m/%Y") if concert.date else "—"}</div>'
        f'<div>{_concert_venue_name(concert) or "Recinto pendiente"}</div>'
        f'<div>{_concert_city(concert)} {("· " + _concert_province_value(concert)) if _concert_province_value(concert) else ""}</div>'
        f'<div>Hora show: {concert.show_time or ("TBC" if concert.show_time_tbc else "—")}</div>'
        f'<div>Hora puertas: {concert.doors_time or ("TBC" if concert.doors_time_tbc else "—")}</div>'
        f'</div></div></div>'
        f'<p><strong>Formatos solicitados:</strong> {formats_txt}</p>'
        + (f'<p><strong>Vídeo promocional:</strong> {escape(video_txt)}</p>' if video_txt else '')
        + f'<p><strong>Logos empresas del grupo:</strong> {logos_txt}</p>'
        f'<p><strong>Notas de logos:</strong> {row.logo_notes or "—"}</p>'
        f'<p><strong>Ticketeras:</strong> {ticketers_txt}</p>'
        f'<p><strong>Notas de ticketeras:</strong> {row.ticketer_notes or "—"}</p>'
        f'<p><strong>Otras notas:</strong> {row.other_notes or "—"}</p>'
        f'<p><strong>Fecha máxima de entrega:</strong> {deadline_txt}</p>'
        f'<p><a href="{upload_url}" style="display:inline-block;background:#0d6efd;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none;">Subir carteles</a></p>'
        f'</div>'
    )
    subject = f"{mod_text} · {concert.artist.name if concert.artist else 'concierto'}"
    return subject, html_body, upload_url


def _send_artwork_request_email(concert: Concert, row: ConcertArtworkRequest, is_update: bool = False) -> tuple[bool, str | None]:
    temp_session = db()
    try:
        all_companies = {str(x.id): x for x in temp_session.query(GroupCompany).order_by(GroupCompany.name.asc()).all()}
        all_ticketers = {str(x.id): x for x in temp_session.query(Ticketer).order_by(Ticketer.name.asc()).all()}
    finally:
        temp_session.close()
    selected_company_names = [all_companies[x].name for x in (row.group_company_ids or []) if x in all_companies]
    selected_ticketer_names = [all_ticketers[x].name for x in (row.ticketer_ids or []) if x in all_ticketers]
    upload_url = _external_url_for('concert_artwork_public_upload', token=row.public_token)
    subject, html_body, text_body = _build_artwork_request_email(
        concert,
        row,
        selected_company_names,
        selected_ticketer_names,
        upload_url,
        is_update=is_update,
    )
    # AVISO dentro de la app al departamento de DISEÑO (además del correo de siempre).
    try:
        aviso_db = db()
        try:
            _notify_users(
                aviso_db, _department_user_ids(aviso_db, "Diseño"), "DISENO",
                ("Cambios en una solicitud de diseño" if is_update else "Nueva solicitud de diseño"),
                "%s%s" % (((getattr(concert, "festival_name", None) or "").strip()
                           or (getattr(getattr(concert, "artist", None), "name", "") or "Actividad")),
                          (" · " + concert.date.strftime("%d/%m/%Y")) if getattr(concert, "date", None) else ""),
                url_for("diseno_view"), ref_type="ARTWORK", ref_id=str(getattr(row, "id", "") or ""),
                commit=True)
        finally:
            aviso_db.close()
    except Exception:
        app.logger.exception("[avisos] no se pudo avisar a Diseño de la solicitud de cartelería")
    return _send_optional_email('grafico@33producciones.es', subject, html_body, text_body=text_body)


def _artwork_request_status(row: ConcertArtworkRequest | None) -> str:
    if not row:
        return 'NONE'
    return (getattr(row, 'status', None) or 'DRAFT').strip().upper() or 'DRAFT'


def _artwork_request_has_event_changes(row: ConcertArtworkRequest | None, concert: Concert | None) -> bool:
    """¿Cambiaron fecha/recinto/horarios desde la última solicitud? Aplica tanto a carteles
    hechos por nosotros (OURS) como por el PROMOTOR: en ambos casos hay que rehacerlos."""
    if not row or not concert:
        return False
    if _artwork_request_status(row) in ('NONE', 'DRAFT'):
        return False
    baseline = dict(getattr(row, 'event_snapshot', None) or {})
    if not baseline:
        return False
    current = _concert_artwork_snapshot(concert)
    keys = ('date', 'venue', 'municipality', 'province', 'show_time', 'doors_time')
    for key in keys:
        if str((baseline.get(key) or '')).strip() != str((current.get(key) or '')).strip():
            return True
    return False


def _concert_email_header_html(concert: Concert, title: str) -> str:
    """Cabecera común de los correos de actividad: logo de la empresa del grupo arriba a la
    DERECHA, título centrado y tarjeta con la cabecera del evento (foto del artista + datos)."""
    logo_html = ''
    company = getattr(concert, 'billing_company', None) or getattr(concert, 'group_company', None)
    if company and getattr(company, 'logo_url', None):
        logo_html = f'<div style="text-align:right;margin-bottom:8px;"><img src="{company.logo_url}" style="max-height:56px;max-width:200px;"></div>'
    artist_photo = ''
    if concert.artist and getattr(concert.artist, 'photo_url', None):
        artist_photo = f'<img src="{concert.artist.photo_url}" style="width:70px;height:70px;object-fit:cover;border-radius:50%;">'
    date_txt = concert.date.strftime('%d/%m/%Y') if concert.date else '—'
    prov = _concert_province_value(concert)
    return (
        f'{logo_html}'
        f'<h2 style="margin:0 0 16px;text-align:center;">{title}</h2>'
        f'<div style="border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:18px;">'
        f'<div style="display:flex;gap:16px;align-items:center;"><div>{artist_photo}</div><div>'
        f'<div style="font-size:18px;font-weight:700;">{concert.artist.name if concert.artist else "Actividad"}</div>'
        f'<div>Fecha: {date_txt}</div>'
        f'<div>{_concert_venue_name(concert) or "Recinto pendiente"}</div>'
        f'<div>{_concert_city(concert)} {("· " + prov) if prov else ""}</div>'
        f'<div>Hora show: {concert.show_time or ("TBC" if concert.show_time_tbc else "—")}</div>'
        f'</div></div></div>'
    )


def _artwork_logo_lines_html(row: ConcertArtworkRequest) -> str:
    """Logos que debe llevar el cartel (empresas del grupo con imagen + notas de logos)."""
    temp_session = db()
    try:
        all_companies = {str(x.id): x for x in temp_session.query(GroupCompany).all()}
    finally:
        temp_session.close()
    chips = []
    for cid in (row.group_company_ids or []):
        co = all_companies.get(str(cid))
        if not co:
            continue
        img = f'<img src="{co.logo_url}" style="width:26px;height:26px;object-fit:contain;vertical-align:middle;margin-right:6px;">' if co.logo_url else ''
        chips.append(f'<span style="display:inline-block;border:1px solid #e5e7eb;border-radius:999px;padding:5px 12px;margin:0 6px 6px 0;">{img}{co.name}</span>')
    html = ''
    if chips:
        html += f'<p style="margin-bottom:6px;"><strong>Logos que deben incluirse:</strong></p><div>{"".join(chips)}</div>'
    if row.logo_notes:
        html += f'<p><strong>Otros logos / notas:</strong> {row.logo_notes}</p>'
    fmts = _artwork_requested_format_labels(row)
    if fmts:
        html += f'<p><strong>Formatos:</strong> {", ".join(fmts)}</p>'
    if getattr(row, 'video_requested', False):
        vfmt = _artwork_video_format_labels(row)
        html += ('<p><strong>Vídeo promocional:</strong> '
                 + (', '.join(vfmt) if vfmt else 'formato por concretar') + '</p>')
        if getattr(row, 'video_notes', None):
            html += f'<p style="white-space:pre-wrap;">{escape(row.video_notes)}</p>'
    if row.delivery_deadline:
        html += f'<p><strong>Fecha máxima de entrega:</strong> {row.delivery_deadline.strftime("%d/%m/%Y")}</p>'
    return html


def _send_promoter_artwork_email(concert: Concert, row: ConcertArtworkRequest, kind: str = 'REQUEST', note: str = '') -> tuple[bool, str | None]:
    """Correo al PROMOTOR para pedir/corregir los carteles del evento. kind:
    REQUEST (solicitud inicial) · CHANGES (los datos del evento cambiaron) · REJECTED (correcciones)."""
    recipients = [x for x in (row.recipients_json or []) if x]
    if not recipients:
        return False, 'Sin destinatarios guardados en la solicitud.'
    upload_url = _external_url_for('concert_artwork_public_upload', token=row.public_token)
    intro = {
        'REQUEST': '<p>Necesitamos que subas los <strong>carteles del evento</strong> con los datos y logos indicados.</p>',
        'CHANGES': '<p style="background:#fef3c7;border-radius:8px;padding:10px 12px;"><strong>Se ha realizado un cambio en los datos del evento</strong> y es necesario realizar carteles nuevos con la información actualizada.</p>',
        'REJECTED': '<p style="background:#fee2e2;border-radius:8px;padding:10px 12px;"><strong>Los carteles no han sido aprobados.</strong> Por favor, realiza los siguientes cambios y vuelve a subirlos:</p>'
                    + (f'<p style="white-space:pre-line;">{note}</p>' if note else ''),
    }.get((kind or 'REQUEST').upper(), '')
    style_guide_url = (os.environ.get('ARTWORK_STYLE_GUIDE_URL') or '').strip()
    guide_html = ''
    if style_guide_url:
        guide_html = f'<p><a href="{style_guide_url}" style="display:inline-block;background:#fff;color:#111827;border:1px solid #d1d5db;padding:10px 16px;border-radius:8px;text-decoration:none;">Descargar guía de estilo y materiales</a></p>'
    html_body = (
        '<div style="font-family:Arial,sans-serif;color:#1f2937;max-width:640px;">'
        + _concert_email_header_html(concert, 'Solicitud de carteles')
        + intro
        + _artwork_logo_lines_html(row)
        + guide_html
        + f'<p><a href="{upload_url}" style="display:inline-block;background:#E33D48;color:#fff;padding:12px 18px;border-radius:8px;text-decoration:none;font-weight:700;">Subir los carteles</a></p>'
        + '</div>'
    )
    subject = {
        'REQUEST': f'Solicitud de carteles · {concert.artist.name if concert.artist else "actividad"}',
        'CHANGES': f'Carteles: cambio en los datos del evento · {concert.artist.name if concert.artist else "actividad"}',
        'REJECTED': f'Carteles: correcciones necesarias · {concert.artist.name if concert.artist else "actividad"}',
    }.get((kind or 'REQUEST').upper())
    return _send_optional_email(recipients, subject, html_body, text_body=upload_url)


def _artwork_notify_resolve_if_done(session_db, row) -> None:
    """El aviso de «nueva solicitud de diseño» se cierra solo en cuanto la solicitud ya tiene
    cartelería APROBADA: a partir de ahí no espera a nadie."""
    try:
        if row is None:
            return
        hay = any((not a.is_archived) and (a.validation_status or "APPROVED") == "APPROVED"
                  for a in (row.assets or []))
        if hay:
            _notify_resolve(session_db, "ARTWORK", str(row.id))
    except Exception:
        app.logger.exception("[avisos] no se pudo cerrar el aviso de la solicitud de diseño")


def _artwork_pick_primary_by_squareness(row: ConcertArtworkRequest, category: str = "POSTER") -> None:
    """Si ninguna pieza vigente de esa categoría es principal, marca la MÁS CUADRADA (por dimensiones
    medidas en el navegador al subir; sin dimensiones cuenta como poco cuadrado).

    ⚠️ **Por CATEGORÍA**: los carteles y los logotipos comparten solicitud, así que sin acotarlo un
    logo podía quedarse como cartel principal de la gira (y al revés)."""
    cat = _artwork_category_arg(category)
    vigentes = [a for a in (row.assets or [])
                if not getattr(a, 'is_archived', False) and _artwork_asset_category(a) == cat]
    if not vigentes or any(getattr(a, 'is_primary', False) for a in vigentes):
        return
    # ⚠️ Solo una IMAGEN puede ser el principal: es la que representa a la actividad (la miniatura
    # del enlace, el aviso de salida a la venta). Un vídeo o un PDF no valen ahí.
    assets = [a for a in vigentes if _artwork_can_be_primary(a)]
    if not assets:
        return

    def squareness(a):
        try:
            w, h = float(a.width or 0), float(a.height or 0)
            if w > 0 and h > 0:
                return abs(math.log(w / h))
        except Exception:
            pass
        return 999.0

    best = min(assets, key=squareness)
    for a in assets:
        a.is_primary = (a is best)


def _sync_artwork_request_refresh_flag(concert: Concert | None) -> bool:
    if not concert or not getattr(concert, 'artwork_request', None):
        return False
    changed = _artwork_request_has_event_changes(concert.artwork_request, concert)
    concert.artwork_request.needs_refresh = bool(changed)
    return changed


def _artwork_request_badge(row: ConcertArtworkRequest | None, concert: Concert | None = None):
    st = _artwork_request_status(row)
    handled = (getattr(row, 'handled_by', None) or 'OURS').strip().upper() if row else 'OURS'
    if st == 'PROMOTER':
        return {'label': 'Cartelería promotor', 'class': 'bg-secondary'}
    if st == 'REQUESTED':
        return {'label': ('Solicitado al Promotor' if handled == 'PROMOTER' else 'Solicitado a Diseño'), 'class': 'bg-warning text-dark'}
    if st == 'REVIEW':
        return {'label': 'Pendiente de validación', 'class': 'bg-warning text-dark'}
    if st == 'CORRECTIONS':
        return {'label': 'Pendiente de correcciones', 'class': 'bg-danger'}
    if st == 'UPLOADED':
        return {'label': 'Carteles subidos', 'class': 'bg-success'}
    if st == 'DRAFT':
        return {'label': 'Solicitud de carteles pendiente', 'class': 'bg-light text-dark border'}
    return None


# --- Catálogos del asistente de actividad (cartelería / gastos que cubre el promotor) ---

# Formatos habituales de cartelería con su proporción (representación gráfica en el
# asistente de actividad y en la pestaña Cartelería). key → (etiqueta, aspect-ratio CSS).
ARTWORK_FORMAT_CHOICES = [
    ("CUADRADO", "Cuadrado (feed)", "1 / 1"),
    ("STORY", "Story (9:16)", "9 / 16"),
    ("CARTEL", "Cartel impresión (A3)", "1 / 1.414"),
    ("HORIZONTAL", "Horizontal (16:9)", "16 / 9"),
    ("MUPI", "MUPI / marquesina", "2 / 3"),
    ("BANNER", "Banner web", "4 / 1"),
]
ARTWORK_FORMAT_LABELS = {key: label for key, label, _aspect in ARTWORK_FORMAT_CHOICES}

# Vídeo promocional pedido a diseño: mismo tipo de tarjeta con la proporción dibujada.
ARTWORK_VIDEO_FORMAT_CHOICES = [
    ("VERTICAL", "Vertical (9:16)", "9 / 16"),
    ("HORIZONTAL", "Horizontal (16:9)", "16 / 9"),
]
ARTWORK_VIDEO_FORMAT_LABELS = {key: label for key, label, _a in ARTWORK_VIDEO_FORMAT_CHOICES}


def _parse_artwork_video(form) -> dict:
    """Bloque de vídeo del formulario de cartelería (asistente y ficha)."""
    keys = {k for k, _l, _a in ARTWORK_VIDEO_FORMAT_CHOICES}
    formats = [(v or "").strip().upper() for v in form.getlist("artwork_video_formats[]")]
    return {
        "requested": _truthy(form.get("artwork_video")),
        "notes": (form.get("artwork_video_notes") or "").strip() or None,
        "formats": [k for k in ARTWORK_VIDEO_FORMAT_LABELS if k in formats] if keys else [],
    }


def _artwork_video_format_labels(row) -> list[str]:
    return [ARTWORK_VIDEO_FORMAT_LABELS.get(k, k) for k in (getattr(row, "video_formats", None) or [])]


def _artwork_requested_format_labels(row) -> list[str]:
    out = []
    for key in list(getattr(row, "requested_formats", None) or []):
        raw = str(key or "").strip()
        if not raw:
            continue
        # Claves del catálogo → etiqueta; formatos PERSONALIZADOS → tal cual se escribieron.
        out.append(ARTWORK_FORMAT_LABELS.get(raw.upper(), raw))
    return out


def _parse_artwork_formats(form) -> list[str]:
    """Formatos de cartelería marcados: claves del catálogo + formatos PERSONALIZADOS
    (chips `artwork_formats_custom[]` del asistente o texto separado por comas de la ficha)."""
    out = []
    for k in form.getlist("artwork_formats[]"):
        key = (k or "").strip().upper()
        if key in ARTWORK_FORMAT_LABELS and key not in out:
            out.append(key)
    customs = list(form.getlist("artwork_formats_custom[]"))
    raw_text = (form.get("artwork_formats_custom_text") or "").strip()
    if raw_text:
        customs += [p for p in raw_text.split(",")]
    seen = {c.casefold() for c in out}
    for c in customs:
        c = (c or "").strip()[:80]
        if not c or c.casefold() in seen or c.upper() in ARTWORK_FORMAT_LABELS:
            continue
        seen.add(c.casefold())
        out.append(c)
    return out


# Gastos que puede cubrir el promotor además del caché (paso de caché del asistente y
# sección Cachés de la ficha). key → (etiqueta, icono Font Awesome).
PROMOTER_COST_ITEMS = [
    ("HOTELES", "Hoteles", "fa-hotel"),
    ("TRASLADOS", "Traslados", "fa-van-shuttle"),
    ("VIATICOS", "Viáticos", "fa-utensils"),
    ("SUELDOS", "Sueldos", "fa-money-bill-wave"),
    ("TODOS", "Cubre todos los gastos", "fa-circle-check"),
]
PROMOTER_COST_LABELS = {key: label for key, label, _icon in PROMOTER_COST_ITEMS}


def _parse_promoter_costs_form(form) -> dict:
    """Parsea el módulo «El promotor cubre otros gastos» (asistente y ficha).

    Cada opción marcada lleva nota (qué cubre), quién lo gestiona (US = lo gestionamos
    nosotros y lo facturamos | PROMOTER = lo gestiona el promotor) e importe máximo opcional."""
    enabled = _truthy(form.get("promoter_costs_enabled"))
    items = []
    if enabled:
        for key in form.getlist("promoter_cost_item[]"):
            key = (key or "").strip().upper()
            if key not in PROMOTER_COST_LABELS:
                continue
            if any(x["key"] == key for x in items):
                continue
            managed = (form.get(f"promoter_cost_managed_{key}") or "").strip().upper()
            if managed not in ("US", "PROMOTER"):
                managed = "PROMOTER"
            max_amount = _parse_optional_decimal(form.get(f"promoter_cost_max_{key}"))
            items.append({
                "key": key,
                "label": PROMOTER_COST_LABELS[key],
                "note": (form.get(f"promoter_cost_note_{key}") or "").strip(),
                "managed_by": managed,
                "max_amount": float(max_amount) if max_amount is not None else None,
            })
    return {"enabled": bool(items), "items": items}


def _concert_entradas_ticket_rows(concert) -> list[dict]:
    """Filas de la sección «Entradas y venta» de la ficha: parte de los ConcertTicketType
    REALES (no ET) para no pisar tipos configurados fuera del asistente, y completa las
    invitaciones pactadas desde el ticketing_payload (casadas por nombre)."""
    payload = getattr(concert, "ticketing_payload", None) or {}
    payload = payload if isinstance(payload, dict) else {}
    inv_by_name = {}
    for r in (payload.get("ticket_types") or []):
        if isinstance(r, dict) and r.get("name"):
            inv_by_name[str(r["name"]).casefold()] = int(r.get("invites_total") or 0)
    # ⚠️ Si se ha VOLCADO la configuración de Enterticket, el payload ES la verdad de esta sección:
    # los `ConcertTicketType` de ET están marcados `et_managed` y se saltan más abajo, así que sin
    # esto la ficha seguiría enseñando los tipos manuales viejos mientras el resto de la pantalla ya
    # habla de los de Enterticket.
    if payload.get("et_dump") and (payload.get("ticket_types") or []):
        return [r for r in payload["ticket_types"] if isinstance(r, dict)]
    rows = []
    for t in (getattr(concert, "ticket_types", None) or []):
        if getattr(t, "et_managed", False):
            continue
        name = (t.name or "").strip()
        rows.append({
            "name": name,
            "price": float(t.price or 0),
            "qty_for_sale": int(t.qty_for_sale or 0),
            "invites_total": inv_by_name.get(name.casefold(), 0),
        })
    if not rows:
        rows = [r for r in (payload.get("ticket_types") or []) if isinstance(r, dict)]
    return rows


def _promoter_costs_rows(payload) -> list[dict]:
    """Filas normalizadas del payload «El promotor cubre otros gastos» para mostrarlas."""
    data = payload if isinstance(payload, dict) else {}
    rows = []
    for raw in list(data.get("items") or []):
        if not isinstance(raw, dict):
            continue
        key = (raw.get("key") or "").strip().upper()
        rows.append({
            "key": key,
            "label": raw.get("label") or PROMOTER_COST_LABELS.get(key, key.title() or "Gasto"),
            "note": (raw.get("note") or "").strip(),
            "managed_by": (raw.get("managed_by") or "PROMOTER").strip().upper(),
            "max_amount": raw.get("max_amount"),
        })
    return rows


def _payment_term_status(row: dict | None) -> str:
    row = row or {}
    if row.get('collected_at') or _truthy(row.get('is_collected')):
        return 'COLLECTED'
    if row.get('invoice_url') or row.get('invoiced_at') or _truthy(row.get('is_invoiced')):
        return 'PENDING_COLLECTION'
    return 'PENDING_INVOICE'


def _payment_term_badge(row: dict | None):
    st = _payment_term_status(row)
    if st == 'PENDING_COLLECTION':
        return {'label': 'Pendiente de cobrar', 'class': 'bg-primary'}
    if st == 'COLLECTED':
        return {'label': 'Cobrado', 'class': 'bg-success'}
    return {'label': 'Pendiente de facturar', 'class': 'bg-warning text-dark'}


def _normalize_payment_term(row: dict | None, idx: int = 0) -> dict:
    data = dict(row or {})
    amount = 0.0
    try:
        amount = float(data.get('amount') or 0)
    except Exception:
        amount = 0.0
    due_date = (data.get('due_date') or '').strip() if isinstance(data.get('due_date'), str) else data.get('due_date')
    badge = _payment_term_badge(data)
    status = _payment_term_status(data)
    return {
        'idx': idx,
        'concept': (data.get('concept') or 'Pago').strip() if isinstance(data.get('concept'), str) else 'Pago',
        'amount': amount,
        'due_date': due_date or None,
        'cache_ref': data.get('cache_ref'),
        'invoice_url': data.get('invoice_url'),
        'invoice_name': data.get('invoice_name') or data.get('invoice_original_name') or 'Factura',
        'invoiced_at': data.get('invoiced_at'),
        'collected_at': data.get('collected_at'),
        'status': status,
        'badge': badge,
        'can_upload_invoice': status == 'PENDING_INVOICE',
        'can_mark_collected': status == 'PENDING_COLLECTION',
        # ¿Hay factura subida? Entonces se puede sustituir o eliminar (los tres puntitos).
        'has_invoice': bool(data.get('invoice_url')),
    }


def _concert_payment_rows(concert: Concert | None, pending_only: bool = False) -> list[dict]:
    rows = []
    for idx, row in enumerate(getattr(concert, 'payment_terms_json', None) or []):
        item = _normalize_payment_term(row, idx)
        if pending_only and item['status'] == 'COLLECTED':
            continue
        rows.append(item)
    return rows


def _concert_payment_total(concert: Concert | None, pending_only: bool = False) -> float:
    rows = _concert_payment_rows(concert, pending_only=pending_only)
    return sum(float(x.get('amount') or 0) for x in rows)


# ---------- Facturación de Contratación: estados de pago, agrupación y contador anual ----------
BILLING_PAYMENT_STATUS_CHOICES = [
    ("PENDING_INVOICE", "Por facturar", "fa-file-circle-plus"),
    ("PENDING_COLLECTION", "Por cobrar", "fa-hourglass-half"),
    ("COLLECTED", "Cobrado", "fa-circle-check"),
]
BILLING_PAYMENT_STATUSES = {k for k, _l, _i in BILLING_PAYMENT_STATUS_CHOICES}


def _billing_group_by_artist(items: list[dict]) -> list[dict]:
    """Agrupa las actividades por ARTISTA, como el listado de cuadrantes."""
    groups: dict = {}
    for it in items:
        c = it["concert"]
        artist = getattr(c, "artist", None)
        key = str(getattr(c, "artist_id", "") or "sin")
        g = groups.get(key)
        if not g:
            g = {
                "artist_id": (str(c.artist_id) if getattr(c, "artist_id", None) else ""),
                "artist_name": (getattr(artist, "name", None) or "Sin artista"),
                "artist_photo": (getattr(artist, "photo_url", None) or ""),
                "items": [], "pending_total": 0.0, "shown_total": 0.0,
            }
            groups[key] = g
        g["items"].append(it)
        g["pending_total"] += float(it.get("pending_total") or 0)
        g["shown_total"] += float(it.get("shown_total") or 0)
    out = list(groups.values())
    out.sort(key=lambda g: (g["artist_name"] or "").lower())
    return out


def _billing_year_by_company(session_db, year: int) -> list[dict]:
    """Total FACTURADO en el año por empresa del grupo: los pagos que ya se han facturado
    (esperando cobro o ya cobrados) de las actividades de ese año."""
    concerts = (
        session_db.query(Concert)
        .options(joinedload(Concert.billing_company))
        .filter(func.extract("year", Concert.date) == year)
        .filter(Concert.billing_company_id.isnot(None))
        .all()
    )
    acc: dict = {}
    for c in concerts:
        company = getattr(c, "billing_company", None)
        if company is None:
            continue
        key = str(company.id)
        slot = acc.setdefault(key, {
            "id": key, "name": company.name or "", "logo_url": company.logo_url or "",
            "invoiced": 0.0, "collected": 0.0,
        })
        for row in _concert_payment_rows(c, pending_only=False):
            if row["status"] in ("PENDING_COLLECTION", "COLLECTED"):
                slot["invoiced"] += float(row.get("amount") or 0)
            if row["status"] == "COLLECTED":
                slot["collected"] += float(row.get("amount") or 0)
    out = [v for v in acc.values() if v["invoiced"]]
    out.sort(key=lambda x: -x["invoiced"])
    return out


def _concert_billing_sort_key(concert: Concert | None, today: date | None = None):
    today = today or today_local()
    if not concert or not getattr(concert, 'date', None):
        return (2, date.max)
    if concert.date <= today:
        return (0, -concert.date.toordinal())
    return (1, concert.date.toordinal())


def _parse_invitation_rows(form) -> list[dict]:
    rows = []
    cats = form.getlist('invitation_category[]')
    artist_qtys = form.getlist('invitation_artist_qty[]')
    office_qtys = form.getlist('invitation_office_qty[]')
    for i, cat in enumerate(cats or []):
        cat = (cat or '').strip()
        if not cat:
            continue
        artist_qty = _parse_optional_positive_int((artist_qtys[i] if i < len(artist_qtys) else '') or '') or 0
        office_qty = _parse_optional_positive_int((office_qtys[i] if i < len(office_qtys) else '') or '') or 0
        rows.append({'category': cat, 'artist_qty': artist_qty, 'office_qty': office_qty, 'total_qty': artist_qty + office_qty})
    return rows


def _parse_payment_terms_rows(form) -> list[dict]:
    rows = []
    concepts = form.getlist('payment_concept[]')
    amounts = form.getlist('payment_amount[]')
    due_dates = form.getlist('payment_due_date[]')
    cache_refs = form.getlist('payment_cache_ref[]')
    for i, concept in enumerate(concepts or []):
        concept = (concept or '').strip()
        amount = _parse_optional_decimal(amounts[i] if i < len(amounts) else None)
        due_date = parse_optional_date(due_dates[i] if i < len(due_dates) else None)
        cache_ref = (cache_refs[i] if i < len(cache_refs) else '').strip() or None
        if not concept and not amount and not due_date:
            continue
        rows.append({
            'concept': concept or 'Pago',
            'amount': float(amount or 0),
            'due_date': due_date.isoformat() if due_date else None,
            'cache_ref': cache_ref,
            'invoice_url': None,
            'invoice_name': None,
            'invoiced_at': None,
            'collected_at': None,
        })
    return rows


def _dedupe_keep_order(valores) -> list:
    """Sin repetidos y conservando el orden en que se eligieron (comparando sin mayúsculas)."""
    vistos, salida = set(), []
    for v in (valores or []):
        clave = str(v or "").strip().casefold()
        if not clave or clave in vistos:
            continue
        vistos.add(clave)
        salida.append(str(v).strip())
    return salida


