def _looks_like_email_address(value: str | None) -> bool:
    email = (value or '').strip()
    if not email or len(email) > 254:
        return False
    return bool(re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', email))


def _current_user_row(session_db=None) -> User | None:
    user_id = session.get("user_id")
    if not user_id:
        return None

    close_session = False
    if session_db is None:
        session_db = db()
        close_session = True

    try:
        return session_db.get(User, to_uuid(user_id)) if user_id else None
    except Exception:
        return None
    finally:
        if close_session:
            session_db.close()


def _royalty_public_serializer() -> URLSafeTimedSerializer:
    return URLSafeTimedSerializer(app.secret_key, salt="royalty-liquidation-public")


def _make_public_royalty_liquidation_token(kind: str, bid: str, sem_key: str) -> str:
    return _royalty_public_serializer().dumps({
        "kind": (kind or "").strip().upper(),
        "bid": str(bid or "").strip(),
        "s": (sem_key or "").strip(),
    })


def _parse_public_royalty_liquidation_token(token: str | None, max_age: int = 315360000) -> dict | None:
    """Lee el token del enlace de facturación de una liquidación de royalties.

    ⚠️ UN ENLACE ANTIGUO NO SE TIRA. Antes caducaba al año y, cuando eso pasaba, el enlace se
    comportaba como la landing genérica: el proveedor subía su factura, la app le decía que todo
    bien… y la factura quedaba SIN VINCULAR a la liquidación, así que no aparecía en «pendiente de
    liquidar» y nadie se enteraba (bug real: gente que había facturado y no nos llegaba).
    Ahora el margen es de 10 años y, si aun así hubiera caducado, se recupera el contenido: que un
    token sea VIEJO no es que sea falso — `SignatureExpired` solo se lanza DESPUÉS de comprobar la
    firma, así que el contenido es de fiar.
    """
    token = (token or "").strip()
    if not token:
        return None
    serializer = _royalty_public_serializer()
    try:
        data = serializer.loads(token, max_age=max_age)
    except SignatureExpired as caducado:
        try:
            data = serializer.load_payload(caducado.payload)
        except Exception:
            return None
    except BadSignature:
        return None
    if not isinstance(data, dict):
        return None
    return data


_COUNTRY_CHOICES_CACHE = None
_AUDIO_UPLOAD_EXTENSIONS = {".wav", ".wave"}


def _song_public_serializer() -> URLSafeTimedSerializer:
    return URLSafeTimedSerializer(app.secret_key, salt="song-public-share")


def _make_public_song_share_token(kind: str, song_id: str, ref: str | None = None, fmt: str | None = None) -> str:
    return _song_public_serializer().dumps({
        "kind": (kind or "").strip().upper(),
        "sid": str(song_id or "").strip(),
        "ref": (ref or "").strip(),
        "fmt": (fmt or "").strip().lower(),
    })


def _parse_public_song_share_token(token: str | None, max_age: int = 31536000) -> dict | None:
    token = (token or "").strip()
    if not token:
        return None
    try:
        data = _song_public_serializer().loads(token, max_age=max_age)
    except (BadSignature, SignatureExpired):
        return None
    return data if isinstance(data, dict) else None


def _format_equivalent_copies(value) -> str:
    try:
        amount = int(round(float(value or 0)))
    except Exception:
        amount = 0
    return f"{amount:,}".replace(",", ".")


def _safe_download_filename(value: str | None, fallback: str = "archivo") -> str:
    raw = (value or "").strip() or fallback
    raw = raw.replace("/", "-").replace("\\", "-")
    allowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_ .()"
    cleaned = "".join(ch for ch in raw if ch in allowed)
    cleaned = " ".join(cleaned.split()).strip(" ._")
    return cleaned or fallback


def _certification_catalog(media_kind: str = "SONG") -> dict[str, dict]:
    media_kind = (media_kind or "SONG").strip().upper()
    equivalents = {
        "SONG": {
            "GOLD": 50000,
            "PLATINUM": 100000,
            "DIAMOND": 1000000,
            "URANIUM": 50000000,
        },
        "ALBUM": {
            "GOLD": 20000,
            "PLATINUM": 40000,
            "DIAMOND": 1000000,
            "URANIUM": 50000000,
        },
    }
    base = {
        "GOLD": {
            "title": "Disco de Oro",
            "plural_title": "Discos de Oro",
            "image": "img/certifications/disco_oro_recortado.png",
            "order": 1,
        },
        "PLATINUM": {
            "title": "Disco de Platino",
            "plural_title": "Discos de Platino",
            "image": "img/certifications/disco_platino_recortado.png",
            "order": 2,
        },
        "DIAMOND": {
            "title": "Disco de Diamante",
            "plural_title": "Discos de Diamante",
            "image": "img/certifications/disco_diamante_recortado.png",
            "order": 3,
        },
        "URANIUM": {
            "title": "Disco de Uranio",
            "plural_title": "Discos de Uranio",
            "image": "img/certifications/disco_uranio_recortado.png",
            "order": 4,
        },
    }
    selected = equivalents.get(media_kind, equivalents["SONG"])
    out = {}
    for key, meta in base.items():
        equivalent_copies = int(selected.get(key) or 0)
        row = dict(meta)
        row["equivalent_copies"] = equivalent_copies
        row["copies_label"] = f"Equivalente a {_format_equivalent_copies(equivalent_copies)} copias"
        out[key] = row
    return out


def _country_flag_emoji(country_code: str | None) -> str:
    code = (country_code or "").strip().upper()
    if len(code) != 2 or not code.isalpha():
        return ""
    return chr(127397 + ord(code[0])) + chr(127397 + ord(code[1]))


def _country_choices() -> list[dict]:
    global _COUNTRY_CHOICES_CACHE
    if _COUNTRY_CHOICES_CACHE is not None:
        return _COUNTRY_CHOICES_CACHE

    out = []
    seen = set()
    if PYCOUNTRY_AVAILABLE:
        for item in pycountry.countries:
            code = (getattr(item, "alpha_2", None) or "").strip().upper()
            name = (getattr(item, "name", None) or getattr(item, "official_name", None) or "").strip()
            if not code or not name or code in seen:
                continue
            aliases = {name.casefold()}
            for attr in ("official_name", "common_name"):
                val = (getattr(item, attr, None) or "").strip()
                if val:
                    aliases.add(val.casefold())
            out.append({
                "code": code,
                "name": name,
                "flag": _country_flag_emoji(code),
                "aliases": sorted(aliases),
            })
            seen.add(code)
    if not out:
        for code, name in [("ES", "España"), ("MX", "México"), ("AR", "Argentina"), ("US", "Estados Unidos")]:
            out.append({"code": code, "name": name, "flag": _country_flag_emoji(code), "aliases": [name.casefold()]})
    out.sort(key=lambda row: row["name"].casefold())
    _COUNTRY_CHOICES_CACHE = out
    return out


def _resolve_country_choice(raw_value: str | None) -> dict | None:
    raw = " ".join(((raw_value or "").replace("/", " ").split())).strip()
    if not raw:
        return None
    choices = _country_choices()
    if len(raw) == 2 and raw.isalpha():
        code = raw.upper()
        for item in choices:
            if item["code"] == code:
                return item
    norm = raw.casefold()
    for item in choices:
        if norm == item["name"].casefold() or norm in set(item.get("aliases") or []):
            return item
    return None


def _certification_group_title(meta: dict, count: int) -> str:
    count = max(1, int(count or 1))
    if count <= 1:
        return meta.get("title") or "Certificación"
    return f"{count} {meta.get('plural_title') or meta.get('title') or 'Certificaciones'}"


def _group_certifications(rows, media_kind: str = "SONG") -> list[dict]:
    catalog = _certification_catalog(media_kind)
    grouped = {}
    for row in rows or []:
        cert_type = (getattr(row, "certification_type", None) or "").strip().upper()
        country_code = (getattr(row, "country_code", None) or "").strip().upper()
        country_name = (getattr(row, "country_name", None) or "").strip() or country_code
        if cert_type not in catalog or not country_code:
            continue
        key = f"{cert_type}|{country_code}"
        payload = grouped.setdefault(key, {
            "group_key": key,
            "certification_type": cert_type,
            "country_code": country_code,
            "country_name": country_name,
            "count": 0,
            "rows": [],
        })
        payload["count"] += 1
        payload["rows"].append(row)

    out = []
    for payload in grouped.values():
        meta = catalog[payload["certification_type"]]
        count = max(1, int(payload["count"] or 1))
        equivalent_unit = int(meta.get("equivalent_copies") or 0)
        equivalent_total = equivalent_unit * count
        flag = _country_flag_emoji(payload["country_code"])
        country_label = ((flag + " ") if flag else "") + (payload.get("country_name") or payload.get("country_code") or "")
        payload.update({
            "media_kind": (media_kind or "SONG").strip().upper(),
            "title": meta["title"],
            "plural_title": meta["plural_title"],
            "display_title": _certification_group_title(meta, count),
            "display_title_short": meta["title"] if count == 1 else f"{count} {meta['plural_title']}",
            "copies_label": meta["copies_label"],
            "equivalent_copies_unit": equivalent_unit,
            "equivalent_copies_total": equivalent_total,
            "equivalent_copies_total_label": f"Equivalente a {_format_equivalent_copies(equivalent_total)} copias",
            "image_url": _external_url_for("static", filename=meta["image"]),
            "flag": flag,
            "stack_count": min(max(count, 1), 6),
            "summary": f"{_certification_group_title(meta, count)} · Equivalente a {_format_equivalent_copies(equivalent_total)} copias · {country_label}",
            "sort_order": (meta["order"], payload["country_name"].casefold()),
        })
        out.append(payload)

    out.sort(key=lambda item: item["sort_order"])
    return out




# Caché en memoria de las empresas del grupo (nombre+logo) para los context processors de marca.
# Los logos salen en TODAS las páginas: sin caché, CADA render hacía una consulta a BD (sesión
# nueva incluida) y, con la BD lenta o bloqueada, hasta la página de login se colgaba (probes del
# escáner de Render incluidas). TTL corto; si la BD falla se sirve el último valor conocido.
_GROUP_BRAND_CACHE: dict = {"rows": None, "ts": 0.0}
_GROUP_BRAND_TTL_SECONDS = 300.0


def _group_company_brand_rows(session_db=None) -> list[dict]:
    import time as _time
    now = _time.monotonic()
    cached = _GROUP_BRAND_CACHE["rows"]
    if cached is not None and (now - _GROUP_BRAND_CACHE["ts"]) < _GROUP_BRAND_TTL_SECONDS:
        return cached
    own_session = False
    rows_out = list(cached or [])
    try:
        if session_db is None:
            session_db = db()
            own_session = True
        rows = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        rows_out = [
            {"name": (getattr(r, "name", None) or ""), "logo_url": (getattr(r, "logo_url", None) or "")}
            for r in rows
        ]
        _GROUP_BRAND_CACHE["rows"] = rows_out
        _GROUP_BRAND_CACHE["ts"] = now
    except Exception:
        # BD no disponible: no bloquear la página. Se congela el último valor conocido (o vacío)
        # durante el TTL para no reintentar la consulta en cada render mientras dura el problema.
        _GROUP_BRAND_CACHE["rows"] = rows_out
        _GROUP_BRAND_CACHE["ts"] = now
    finally:
        if own_session and session_db is not None:
            try:
                session_db.close()
            except Exception:
                pass
    return rows_out


def _group_company_brand_assets(session_db=None, *, matcher=None, fallback_name: str = '', fallback_static_filename: str = '') -> dict:
    """Devuelve nombre/logo de una empresa del grupo, priorizando el logo configurado en BBDD.
    Lee del caché en memoria (_group_company_brand_rows): nada de consultas por render."""
    group_company = None
    for row in _group_company_brand_rows(session_db):
        key = _norm_text_key(row.get('name') or '')
        if matcher and matcher(key, row):
            group_company = row
            break

    logo_url = ((group_company or {}).get('logo_url') or '').strip().rstrip('?')
    if not logo_url and fallback_static_filename:
        try:
            logo_url = _external_url_for('static', filename=fallback_static_filename)
        except Exception:
            try:
                logo_url = _external_url_for('static', filename=fallback_static_filename)
            except Exception:
                logo_url = ''

    return {
        'company_name': ((group_company or {}).get('name') or fallback_name or '').strip(),
        'logo_url': logo_url,
    }


def _pies_brand_assets(session_db=None) -> dict:
    return _group_company_brand_assets(
        session_db,
        matcher=lambda key, row: 'pies' in key,
        fallback_name='PIES',
        fallback_static_filename='img/logo.png',
    )


def _treinta_y_tres_brand_assets(session_db=None) -> dict:
    return _group_company_brand_assets(
        session_db,
        matcher=lambda key, row: (('treinta' in key and 'tres' in key) or ('33' in key and 'produccion' in key)),
        fallback_name='Treinta y Tres Producciones',
        # Sin fallback al antiguo logo estático para evitar volver a usar el arte incorrecto.
        fallback_static_filename='',
    )


def _treinta_y_tres_logo_url(session_db=None) -> str:
    return (_treinta_y_tres_brand_assets(session_db).get('logo_url') or '').strip()


@app.context_processor
def _inject_group_brand_assets():
    try:
        return {'TT_PRODUCCIONES_LOGO_URL': _treinta_y_tres_logo_url()}
    except Exception:
        return {'TT_PRODUCCIONES_LOGO_URL': ''}


def _artist_email_delivery_data(session_db, artist: Artist | None) -> dict:
    if not artist or not getattr(artist, 'id', None):
        return {
            'is_group': False,
            'primary_email': '',
            'default_recipients': [],
            'suggested_recipients': [],
            'email_options': [],
        }

    primary_email = (getattr(artist, 'email', None) or '').strip()
    people_count = session_db.query(ArtistPerson).filter(ArtistPerson.artist_id == artist.id).count()
    is_group = people_count > 1
    # ⚠️ QUIÉN RECIBE lo DISCOGRÁFICO (una certificación de disco de oro, por ejemplo) lo manda el
    # módulo «Notificaciones» de la ficha del artista. Sin nadie configurado, como antes.
    canal_disc = []
    try:
        canal_disc = _artist_notification_emails(session_db, artist.id, "DISCOGRAFICA", fallback=False)
    except Exception:
        canal_disc = []
    extra_rows = (
        session_db.query(ArtistEmail)
        .filter(ArtistEmail.artist_id == artist.id)
        .order_by(ArtistEmail.created_at.asc(), ArtistEmail.concept.asc())
        .all()
    )

    ordered_emails = []
    if primary_email:
        ordered_emails.append((primary_email, 'Principal'))
    for row in extra_rows or []:
        email = (getattr(row, 'email', None) or '').strip()
        if not email:
            continue
        ordered_emails.append((email, (getattr(row, 'concept', None) or 'Otro correo').strip() or 'Otro correo'))

    deduped = []
    seen = set()
    for email, label in ordered_emails:
        if not _looks_like_email_address(email):
            continue
        key = email.lower()
        if key in seen:
            continue
        seen.add(key)
        deduped.append((email, label))

    default_limit = 2 if is_group else 1
    # Si hay gente configurada en el canal DISCOGRÁFICA, esos son los destinatarios por defecto.
    if canal_disc:
        default_recipients = list(canal_disc)
        for correo in canal_disc:
            if correo.lower() not in {e.lower() for e, _l in deduped}:
                deduped.append((correo, 'Notificaciones discográficas'))
    else:
        default_recipients = [email for email, _ in deduped[:default_limit]]
    suggested_recipients = [email for email, _ in deduped]
    email_options = []
    for idx, (email, label) in enumerate(deduped):
        email_options.append({
            'email': email,
            'label': label,
            'checked': email in default_recipients,
            'is_default': idx < default_limit,
        })

    return {
        'is_group': is_group,
        'primary_email': primary_email,
        'default_recipients': _dedupe_valid_email_addresses(default_recipients),
        'suggested_recipients': _dedupe_valid_email_addresses(suggested_recipients),
        'email_options': email_options,
    }


def _all_user_emails(session_db) -> list[str]:
    """Correos del equipo ACTUAL: no se escribe a quien ya está eliminado o bloqueado."""
    _inactive = _inactive_user_ids(session_db)
    rows = session_db.query(User.id, User.email).filter(User.email.isnot(None)).all()
    return _dedupe_valid_email_addresses([email for (uid, email) in rows if uid not in _inactive])


def _song_primary_artist(session_db, song: Song | None) -> Artist | None:
    if not song:
        return None
    artists = list(getattr(song, 'artists', None) or [])
    if artists:
        return artists[0]
    return (
        session_db.query(Artist)
        .join(SongArtist, SongArtist.artist_id == Artist.id)
        .filter(SongArtist.song_id == song.id)
        .order_by(Artist.name.asc())
        .first()
    )


def _build_song_certification_delivery(session_db, song: Song) -> dict:
    artist = _song_primary_artist(session_db, song)
    delivery = _artist_email_delivery_data(session_db, artist)
    delivery['artist'] = artist
    delivery['team_recipients'] = _all_user_emails(session_db)
    return delivery


def _build_album_certification_delivery(session_db, album: Album) -> dict:
    artist = session_db.get(Artist, getattr(album, 'artist_id', None)) if getattr(album, 'artist_id', None) else None
    delivery = _artist_email_delivery_data(session_db, artist)
    delivery['artist'] = artist
    delivery['team_recipients'] = _all_user_emails(session_db)
    return delivery


def _certification_notification_subject(media_label: str, title: str) -> str:
    if title:
        return f"¡Enhorabuena! {title} ya ha sido certificado"
    return f"¡Enhorabuena! Nueva certificación de {media_label}"


def _build_certification_notification_email(session_db, media_kind: str, item, cert_group: dict, artist: Artist | None) -> dict:
    media_kind = (media_kind or 'SONG').strip().upper()
    brand = _pies_brand_assets(session_db)
    cover_url = (getattr(item, 'cover_url', None) or '').strip()
    if not cover_url:
        try:
            cover_url = _external_url_for('static', filename='img/logo.png')
        except Exception:
            cover_url = ''

    if media_kind == 'SONG':
        media_label = 'Canción'
        interpreters_label = _song_interpreters_label(session_db, item)
    else:
        media_label = 'Álbum'
        interpreters_label = (getattr(artist, 'name', None) or '').strip() or '—'

    title = (getattr(item, 'title', None) or '').strip() or 'Lanzamiento'
    publication_label = getattr(item, 'release_date', None).strftime('%d/%m/%Y') if getattr(item, 'release_date', None) else '—'
    cert_title = cert_group.get('display_title_short') or cert_group.get('display_title') or cert_group.get('title') or 'Certificación'
    total_copies = cert_group.get('equivalent_copies_total') or 0
    icon_url = cert_group.get('image_url') or ''
    icon_count = min(max(int(cert_group.get('count') or 1), 1), 6)
    icon_html = ''.join(
        f'<img src="{html.escape(icon_url)}" alt="{html.escape(cert_group.get("title") or "Certificación")}" style="width:62px;height:62px;object-fit:contain;display:block;">'
        for _ in range(icon_count)
    ) if icon_url else ''
    confetti_html = ""
    logo_html = ''
    if brand.get('logo_url'):
        logo_html = f'<img src="{html.escape(brand.get("logo_url") or "")}" alt="{html.escape(brand.get("company_name") or "PIES")}" style="display:block;max-width:180px;max-height:64px;object-fit:contain;">'
    cover_html = ''
    if cover_url:
        cover_html = f'<img src="{html.escape(cover_url)}" alt="{html.escape(title)}" style="display:block;width:118px;height:118px;object-fit:cover;border-radius:16px;border:1px solid #e5e7eb;background:#fff;">'

    html_body = f"""
    <div style="margin:0;padding:24px;background:#f5f7fb;font-family:Arial,Helvetica,sans-serif;color:#111827;">
      <div style="max-width:760px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:22px;overflow:hidden;">
        <div style="position:relative;padding:28px 30px 18px;background:linear-gradient(180deg,#fff7ed 0%,#ffffff 100%);">
          {confetti_html}
          {logo_html}
          <div style="margin-top:18px;font-size:34px;line-height:1.1;font-weight:800;color:#111827;">¡ENHORABUENA!</div>
        </div>
        <div style="padding:18px 30px 30px;">
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">
            <tr>
              <td width="136" valign="top">{cover_html}</td>
              <td valign="top" style="padding-left:18px;">
                <div style="font-size:24px;line-height:1.2;font-weight:700;color:#111827;">{html.escape(title)}</div>
                <div style="margin-top:8px;font-size:14px;color:#4b5563;">{html.escape(interpreters_label)}</div>
                <div style="margin-top:12px;display:flex;flex-wrap:wrap;gap:10px;">
                  <span style="display:inline-block;padding:6px 10px;border-radius:999px;background:#eef2ff;color:#3730a3;font-size:13px;">{html.escape(media_label)}</span>
                  <span style="display:inline-block;padding:6px 10px;border-radius:999px;background:#f3f4f6;color:#111827;font-size:13px;">Publicación: {html.escape(publication_label)}</span>
                </div>
              </td>
            </tr>
          </table>
          <div style="margin-top:24px;font-size:15px;color:#374151;">Ha sido certificado con:</div>
          <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin-top:14px;border-collapse:collapse;">
            <tr>
              <td width="210" valign="middle">
                <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">{icon_html}</div>
              </td>
              <td valign="middle" style="padding-left:10px;">
                <div style="font-size:24px;font-weight:800;color:#111827;">{html.escape(cert_title)}</div>
                <div style="margin-top:8px;font-size:15px;color:#374151;">Por haber superado el equivalente a {html.escape(_format_equivalent_copies(total_copies))} copias.</div>
              </td>
            </tr>
          </table>
        </div>
      </div>
    </div>
    """
    text_body = (
        f"¡ENHORABUENA!\n\n"
        f"{title} · {media_label}\n"
        f"Intérpretes: {interpreters_label}\n"
        f"Fecha de publicación: {publication_label}\n\n"
        f"Ha sido certificado con {cert_title}.\n"
        f"Por haber superado el equivalente a {_format_equivalent_copies(total_copies)} copias.\n"
    )
    return {
        'subject': _certification_notification_subject(media_label, title),
        'html_body': html_body,
        'text_body': text_body,
    }


def _song_label_copy_share_token(song_id, editorial: bool = False) -> str:
    """Token del LC público. ⚠️ Con `editorial` se comparte el LC **con el reparto editorial** (el
    reparto entre el autor y Plataforma Musical): el LC normal NUNCA lo lleva."""
    payload = {'kind': 'LABEL_COPY_PDF', 'sid': str(song_id)}
    if editorial:
        payload['ed'] = 1
    return _song_public_serializer().dumps(payload)


def _song_contract_share_token(song_id, contract_id) -> str:
    return _song_public_serializer().dumps({'kind': 'PRODUCTION_CONTRACT', 'sid': str(song_id), 'ref': str(contract_id)})


def _album_public_serializer() -> URLSafeTimedSerializer:
    return URLSafeTimedSerializer(app.secret_key, salt='album-share')


def _album_label_copy_share_token(album_id) -> str:
    return _album_public_serializer().dumps({'kind': 'LABEL_COPY_PDF', 'aid': str(album_id)})


def _album_contract_share_token(album_id, contract_id) -> str:
    return _album_public_serializer().dumps({'kind': 'PRODUCTION_CONTRACT', 'aid': str(album_id), 'ref': str(contract_id)})


def _parse_public_album_share_token(token: str | None, max_age: int = 31536000) -> dict | None:
    token = (token or '').strip()
    if not token:
        return None
    try:
        data = _album_public_serializer().loads(token, max_age=max_age)
    except (BadSignature, SignatureExpired):
        return None
    return data if isinstance(data, dict) else None


def _album_producers_list(album: Album | None) -> list[str]:
    values = getattr(album, 'producers', None) or []
    out = []
    seen = set()
    for value in values:
        name = (value or '').strip()
        if not name:
            continue
        key = _norm_text_key(name)
        if key in seen:
            continue
        seen.add(key)
        out.append(name)
    return out


def _contract_list_for_item(session_db, item, media_kind: str) -> list:
    media_kind = (media_kind or 'SONG').strip().upper()
