def _resolve_or_create_promoter_for_contract(session_db, nick: str, tax_id: str = '', contact_email: str = '', contact_phone: str = '') -> Promoter:
    nickname = (nick or '').strip()
    promoter = None
    if nickname:
        promoter = (
            session_db.query(Promoter)
            .filter(func.lower(Promoter.nick) == nickname.lower())
            .first()
        )
    if not promoter:
        promoter = Promoter(nick=nickname or 'Beneficiario')
        session_db.add(promoter)
        session_db.flush()
    if nickname:
        promoter.nick = nickname
    if tax_id:
        promoter.tax_id = tax_id
    if contact_email:
        promoter.contact_email = contact_email
    if contact_phone:
        promoter.contact_phone = contact_phone
    session_db.add(promoter)
    return promoter


def _save_contract_royalty_rows(session_db, media_kind: str, item_id, rows_payload: list[dict]):
    media_kind = (media_kind or 'SONG').strip().upper()
    created = []
    for row in rows_payload or []:
        nick = (row.get('nick') or '').strip()
        if not nick:
            continue
        promoter = _resolve_or_create_promoter_for_contract(
            session_db,
            nick=nick,
            tax_id=(row.get('tax_id') or '').strip(),
            contact_email=(row.get('contact_email') or '').strip(),
            contact_phone=(row.get('contact_phone') or '').strip(),
        )
        pct = _parse_pct(row.get('pct'))
        base = _norm_contract_base(row.get('base'))
        profit_scope = _norm_profit_scope(row.get('profit_scope')) if base == 'PROFIT' else None
        if media_kind == 'ALBUM':
            rec = (
                session_db.query(AlbumRoyaltyBeneficiary)
                .filter(AlbumRoyaltyBeneficiary.album_id == item_id)
                .filter(AlbumRoyaltyBeneficiary.promoter_id == promoter.id)
                .first()
            )
            if not rec:
                rec = AlbumRoyaltyBeneficiary(album_id=item_id, promoter_id=promoter.id)
                session_db.add(rec)
        else:
            rec = (
                session_db.query(SongRoyaltyBeneficiary)
                .filter(SongRoyaltyBeneficiary.song_id == item_id)
                .filter(SongRoyaltyBeneficiary.promoter_id == promoter.id)
                .first()
            )
            if not rec:
                rec = SongRoyaltyBeneficiary(song_id=item_id, promoter_id=promoter.id)
                session_db.add(rec)
        rec.promoter_id = promoter.id
        rec.pct = pct
        rec.base = base
        rec.profit_scope = profit_scope
        rec.updated_at = datetime.now(TZ_MADRID)
        session_db.add(rec)
        created.append(rec)
    return created

def _song_material_slot_label(category: str | None, slot_key: str | None, display_name: str | None = None) -> str:
    cat = (category or "").strip().upper()
    slot = (slot_key or "DEFAULT").strip().upper()
    if cat == "COVER":
        if slot == "COVER_PROVISIONAL":
            return "Portada provisional"
        return "Portada"
    if cat == "MASTER":
        if slot == "MASTER_48":
            return "Master 48 bits"
        if slot == "MASTER_24":
            return "Master 24 bits"
        if slot == "MASTER_16":
            return "Master 16 bits"
        return (display_name or "").strip() or "Subproducto"
    if cat == "INSTRUMENTAL":
        if slot == "DEFAULT":
            return "Instrumental"
        return (display_name or "").strip() or "Subproducto"
    if cat == "TV_TRACK":
        if slot == "DEFAULT":
            return "TV Track"
        return (display_name or "").strip() or "Subproducto"
    if cat == "STEMS":
        return (display_name or "").strip() or "Stems"
    if cat == "VIDEOCLIP":
        if slot == "DEFAULT":
            return "Videoclip"
        return (display_name or "").strip() or "Subproducto"
    if cat == "VIDEO_THUMB":
        return (display_name or "").strip() or "Miniatura"
    if cat == "VIDEO_RIGHTS":
        return (display_name or "").strip() or "Cesión de derechos de imagen"
    return (display_name or "").strip() or "Archivo"


def _download_remote_content(file_url: str, timeout: int = 30) -> tuple[bytes, str | None]:
    target_url = (file_url or "").strip()
    if not target_url:
        raise ValueError("No hay URL de archivo.")
    req = Request(target_url, headers={"User-Agent": "Mozilla/5.0"})
    with urlopen(req, timeout=timeout) as resp:
        data = resp.read()
        guessed = getattr(resp, "headers", {}).get_content_type() if getattr(resp, "headers", None) else None
    return data, guessed


def _safe_zip_member_name(name: str | None, existing: set[str], fallback: str) -> str:
    raw = (name or "").replace("\\", "/").lstrip("/")
    parts = [part for part in raw.split("/") if part not in ("", ".", "..")]
    candidate = "/".join(parts).strip() or fallback
    if candidate not in existing:
        existing.add(candidate)
        return candidate
    stem = Path(candidate).stem or Path(fallback).stem or "archivo"
    suffix = Path(candidate).suffix
    idx = 2
    while True:
        alt = f"{stem}_{idx}{suffix}"
        if alt not in existing:
            existing.add(alt)
            return alt
        idx += 1


def _convert_image_content(data: bytes, target_format: str) -> tuple[bytes, str, str]:
    fmt = (target_format or "").strip().lower()
    if fmt not in {"jpg", "jpeg", "png"}:
        raise ValueError("Formato de imagen no válido.")
    if not PILLOW_AVAILABLE:
        raise RuntimeError("Pillow no está disponible para convertir imágenes.")
    with PILImage.open(BytesIO(data)) as img:
        out = BytesIO()
        if fmt == "png":
            img.save(out, format="PNG")
            return out.getvalue(), "image/png", ".png"
        if img.mode not in ("RGB", "L"):
            if "A" in img.getbands():
                bg = PILImage.new("RGB", img.size, (255, 255, 255))
                bg.paste(img, mask=img.getchannel("A"))
                img = bg
            else:
                img = img.convert("RGB")
        elif img.mode == "L":
            img = img.convert("RGB")
        img.save(out, format="JPEG", quality=95)
        return out.getvalue(), "image/jpeg", ".jpg"


def _convert_audio_content_to_mp3(data: bytes, source_ext: str | None = None) -> tuple[bytes, str, str]:
    if not PYDUB_AVAILABLE:
        raise RuntimeError("pydub no está disponible para convertir audio.")
    # ⚠️ pydub busca `ffmpeg` en el PATH y en el servidor no está: se le apunta al binario estático de
    # imageio-ffmpeg (el mismo que usa el póster de los vídeos). Sin esto la exportación a MP3 falla.
    try:
        _exe = _ffmpeg_exe()
        if _exe:
            AudioSegment.converter = _exe
            AudioSegment.ffmpeg = _exe
    except Exception:
        pass
    fmt = (source_ext or "").lower().lstrip(".") or None
    seg = AudioSegment.from_file(BytesIO(data), format=fmt or None)
    out = BytesIO()
    seg.export(out, format="mp3", bitrate="320k")
    return out.getvalue(), "audio/mpeg", ".mp3"


def _convert_video_content(data: bytes, target_format: str, source_ext: str | None = None) -> tuple:
    """Pasa un vídeo a MOV o a MP4. Devuelve (bytes, mimetype, extensión).

    MOV y MP4 son el MISMO códec en otro contenedor, así que se REMUXA (`-c copy`): es casi
    instantáneo y no toca la calidad. Solo si el remux falla se recodifica, que sí es caro.
    ⚠️ ffmpeg no está en el PATH del servidor: se usa el binario de imageio-ffmpeg (`_ffmpeg_exe`),
    el mismo del póster de los vídeos."""
    fmt = (target_format or "").strip().lower()
    if fmt not in {"mov", "mp4"}:
        raise ValueError("Formato de vídeo no válido.")
    mimetype = "video/quicktime" if fmt == "mov" else "video/mp4"
    src_ext = (source_ext or "").lower()
    if src_ext.lstrip(".") == fmt:
        return data, mimetype, f".{fmt}"
    exe = _ffmpeg_exe()
    if not exe:
        raise RuntimeError("ffmpeg no está disponible para convertir el vídeo.")
    with tempfile.TemporaryDirectory() as tmp:
        entrada = os.path.join(tmp, f"in{src_ext or '.bin'}")
        salida = os.path.join(tmp, f"out.{fmt}")
        with open(entrada, "wb") as fh:
            fh.write(data)
        base = [exe, "-hide_banner", "-loglevel", "error", "-y", "-i", entrada]
        extra = ["-movflags", "+faststart"] if fmt == "mp4" else []
        for args in ([*base, "-c", "copy", *extra, salida],
                     [*base, "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
                      "-c:a", "aac", "-b:a", "192k", *extra, salida]):
            try:
                r = subprocess.run(args, capture_output=True, timeout=900)
            except Exception:
                continue
            if r.returncode == 0 and os.path.exists(salida) and os.path.getsize(salida) > 0:
                with open(salida, "rb") as fh:
                    return fh.read(), mimetype, f".{fmt}"
            try:
                os.remove(salida)
            except Exception:
                pass
    raise RuntimeError("No se pudo convertir el vídeo.")


def _song_video_poster_schedule(material_id, url) -> None:
    """Saca la miniatura de un videoclip en 2º plano y la guarda en `SongMaterial.poster_url`.

    Mismo motor que el póster de las fotos (`_video_generate_poster_bytes`, que lee por RANGO y no
    se descarga el vídeo entero). Best-effort: si no sale, el hueco se queda con el icono."""
    if not material_id or not url or not _ffmpeg_exe():
        return

    def _trabajo():
        try:
            data = _video_generate_poster_bytes(url)
            if not data:
                return
            poster = _upload_bytes(data, "song_materials/posters/%s.jpg" % str(material_id),
                                   "image/jpeg", upsert=True)
            if not poster:
                return
            s2 = db()
            try:
                row = s2.get(SongMaterial, to_uuid(material_id))
                if row and not (getattr(row, "poster_url", None) or "").strip():
                    row.poster_url = poster
                    s2.commit()
            except Exception:
                s2.rollback()
            finally:
                s2.close()
        except Exception:
            pass

    try:
        threading.Thread(target=_trabajo, daemon=True).start()
    except Exception:
        pass


def _artwork_poster_schedule(asset_id, url) -> None:
    """La MINIATURA de un cartel en VÍDEO, en 2º plano, guardada en `ConcertArtworkAsset.poster_url`.

    ⚠️ Mismo motor que el póster de un videoclip o de un vídeo de la galería
    (`_video_generate_poster_bytes`, que lee por RANGO y no se baja el vídeo entero). Best-effort: si
    no sale, el hueco se queda con el icono de vídeo."""
    if not asset_id or not url or not _ffmpeg_exe():
        return

    def _trabajo():
        try:
            data = _video_generate_poster_bytes(url)
            if not data:
                return
            poster = _upload_bytes(data, "concert_artwork/posters/%s.jpg" % str(asset_id),
                                   "image/jpeg", upsert=True)
            if not poster:
                return
            s2 = db()
            try:
                row = s2.get(ConcertArtworkAsset, to_uuid(asset_id))
                if row is not None and not (getattr(row, "poster_url", None) or "").strip():
                    row.poster_url = poster
                    s2.commit()
            except Exception:
                s2.rollback()
            finally:
                s2.close()
        except Exception:
            app.logger.exception("[carteleria] no se pudo sacar la miniatura del vídeo")

    try:
        threading.Thread(target=_trabajo, daemon=True).start()
    except Exception:
        pass


def _song_material_completion_meta(song: Song, material_rows: list[SongMaterial]) -> dict:
    # Audios obligatorios para considerar la canción "completa":
    #  - MASTER: basta con UNO cualquiera de los formatos (48/24/16); los demás son opcionales.
    #  - INSTRUMENTAL, TV_TRACK y STEMS: obligatorios.
    # (La portada se controla aparte, en cover_principal.)
    basics = {
        "MASTER": False,
        "INSTRUMENTAL": False,
        "TV_TRACK": False,
        "STEMS": False,
    }
    any_non_cover = False
    has_pending = False   # algún material recibido por entrega aún sin validar
    last_cover_at = None
    last_material_at = None
    cover_principal = False   # portada PRINCIPAL (slot COVER); la provisional NO pone el icono en verde
    any_cover_material = False

    for row in material_rows or []:
        category = (getattr(row, "category", None) or "").strip().upper()
        slot = (getattr(row, "slot_key", None) or "DEFAULT").strip().upper()
        dt = getattr(row, "updated_at", None) or getattr(row, "created_at", None)
        if category == "COVER":
            any_cover_material = True
            if slot != "COVER_PROVISIONAL":
                cover_principal = True
            if dt and (last_cover_at is None or dt > last_cover_at):
                last_cover_at = dt
            continue
        any_non_cover = True
        if dt and (last_material_at is None or dt > last_material_at):
            last_material_at = dt
        vstatus = (getattr(row, "validation_status", None) or "VALIDATED").strip().upper()
        if vstatus == "PENDING":
            has_pending = True
            continue
        if category == "MASTER" and slot in ("MASTER_48", "MASTER_24", "MASTER_16"):
            basics["MASTER"] = True
        elif category == "INSTRUMENTAL" and slot == "DEFAULT":
            basics["INSTRUMENTAL"] = True
        elif category == "TV_TRACK" and slot == "DEFAULT":
            basics["TV_TRACK"] = True
        elif category == "STEMS":
            basics["STEMS"] = True

    # Legacy: cover_url sin material COVER asociado → se considera portada principal.
    if not any_cover_material and bool(getattr(song, "cover_url", None)):
        cover_principal = True

    completed_basics = sum(1 for value in basics.values() if value)
    # Mientras haya algún material pendiente de validar, el estado NO puede ser "completo" (queda amarillo).
    if completed_basics == len(basics) and not has_pending:
        state = "complete"
    elif completed_basics > 0 or any_non_cover or has_pending:
        state = "partial"
    else:
        state = "none"

    return {
        "cover_done": cover_principal,
        "last_cover_at": last_cover_at,
        "last_material_at": last_material_at,
        "completed_basics": completed_basics,
        "total_basics": len(basics),
        "state": state,
        "text_class": "text-success" if state == "complete" else ("text-warning" if state == "partial" else "text-danger"),
        "badge_class": "text-bg-success" if state == "complete" else ("text-bg-warning text-dark" if state == "partial" else "text-bg-danger"),
    }


def _ensure_song_cover_material_row(session_db, song: Song | None) -> None:
    if not song or not getattr(song, "id", None):
        return
    cover_url = (getattr(song, "cover_url", None) or "").strip()
    if not cover_url:
        return
    exists = (
        session_db.query(SongMaterial)
        .filter(SongMaterial.song_id == song.id)
        .filter(func.upper(SongMaterial.category) == "COVER")
        .first()
    )
    if exists:
        return
    mime_type = mimetypes.guess_type(cover_url.split("?", 1)[0])[0] or None
    session_db.add(
        SongMaterial(
            song_id=song.id,
            category="COVER",
            slot_key="COVER",
            display_name="Portada",
            file_name="portada",
            file_url=cover_url,
            mime_type=mime_type,
        )
    )
    session_db.flush()


def _resolve_song_cover_url(session_db, song: Song, material_rows: list[SongMaterial] | None = None) -> None:
    """Recalcula Song.cover_url: portada principal (slot COVER) si existe; si no, la provisional."""
    if not song or not getattr(song, "id", None):
        return
    if material_rows is None:
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .filter(func.upper(SongMaterial.category) == "COVER")
            .all()
        )
    principal = None
    provisional = None
    for row in material_rows or []:
        if (getattr(row, "category", None) or "").strip().upper() != "COVER":
            continue
        slot = (getattr(row, "slot_key", None) or "COVER").strip().upper()
        if slot == "COVER_PROVISIONAL":
            if provisional is None:
                provisional = row
        elif principal is None:
            principal = row
    chosen = principal or provisional
    if chosen is not None:
        song.cover_url = (getattr(chosen, "file_url", None) or "").strip() or None
    else:
        song.cover_url = None
    session_db.add(song)


def _refresh_song_material_status(session_db, song_or_id, material_rows: list[SongMaterial] | None = None, status_obj: SongStatus | None = None) -> dict:
    song = song_or_id if isinstance(song_or_id, Song) else session_db.get(Song, to_uuid(song_or_id))
    if not song:
        return {"state": "none", "text_class": "text-danger", "badge_class": "text-bg-danger"}
    if material_rows is None:
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )
    meta = _song_material_completion_meta(song, material_rows)
    st = status_obj or _ensure_song_status_row(session_db, song.id)
    now_dt = datetime.now(TZ_MADRID)
    st.cover_done = bool(meta["cover_done"])
    st.cover_updated_at = meta["last_cover_at"] or (st.cover_updated_at if meta["cover_done"] else None)
    st.materials_done = meta["state"] == "complete"
    st.materials_updated_at = meta["last_material_at"]
    st.updated_at = now_dt
    session_db.add(st)
    return meta


def _album_material_completion_meta(album: Album, material_rows: list[AlbumMaterial]) -> dict:
    required = {
        "DDP": False,
        "BODEGON": False,
    }
    if bool(getattr(album, "physical_cd", False)) or bool(getattr(album, "physical_vinyl", False)):
        required["PHYSICAL_DESIGN"] = False

    any_non_cover = False
    last_cover_at = None
    last_material_at = None
    cover_exists = bool((getattr(album, "cover_url", None) or "").strip())

    for row in material_rows or []:
        category = (getattr(row, "category", None) or "").strip().upper()
        dt = getattr(row, "created_at", None)
        if category == "COVER":
            cover_exists = True
            if dt and (last_cover_at is None or dt > last_cover_at):
                last_cover_at = dt
            continue
        any_non_cover = True
        if dt and (last_material_at is None or dt > last_material_at):
            last_material_at = dt
        if category in required:
            required[category] = True

    completed_required = sum(1 for value in required.values() if value)
    total_required = len(required)
    if total_required and completed_required == total_required:
        state = "complete"
    elif completed_required > 0 or any_non_cover:
        state = "partial"
    else:
        state = "none"

    return {
        "cover_done": cover_exists,
        "last_cover_at": last_cover_at,
        "last_material_at": last_material_at,
        "completed_required": completed_required,
        "total_required": total_required,
        "state": state,
        "text_class": "text-success" if state == "complete" else ("text-warning" if state == "partial" else "text-danger"),
        "badge_class": "text-bg-success" if state == "complete" else ("text-bg-warning text-dark" if state == "partial" else "text-bg-danger"),
    }


def _ensure_album_status_row(session_db, album_or_id) -> AlbumStatus:
    if isinstance(album_or_id, Album):
        album = album_or_id
        aid = album.id
    else:
        aid = album_or_id
        album = session_db.get(Album, aid) if aid else None

    st = session_db.get(AlbumStatus, aid) if aid else None
    if not st and aid:
        st = AlbumStatus(album_id=aid)
        if album is not None:
            st.cover_done = bool((getattr(album, "cover_url", None) or "").strip())
            if st.cover_done:
                st.cover_updated_at = datetime.now(TZ_MADRID)
        session_db.add(st)
        session_db.flush()
    return st


def _refresh_album_material_status(session_db, album_or_id, material_rows: list[AlbumMaterial] | None = None, status_obj: AlbumStatus | None = None) -> dict:
    album = album_or_id if isinstance(album_or_id, Album) else session_db.get(Album, to_uuid(album_or_id))
    if not album:
        return {"state": "none", "text_class": "text-danger", "badge_class": "text-bg-danger"}
    if material_rows is None:
        material_rows = (
            session_db.query(AlbumMaterial)
            .filter(AlbumMaterial.album_id == album.id)
            .order_by(AlbumMaterial.created_at.asc())
            .all()
        )
    meta = _album_material_completion_meta(album, material_rows)
    st = status_obj or _ensure_album_status_row(session_db, album.id)
    now_dt = datetime.now(TZ_MADRID)
    st.cover_done = bool(meta["cover_done"])
    st.cover_updated_at = meta["last_cover_at"] or (st.cover_updated_at if meta["cover_done"] else None)
    st.materials_done = meta["state"] == "complete"
    st.materials_updated_at = meta["last_material_at"]
    st.updated_at = now_dt
    session_db.add(st)
    return meta


def _mark_album_agedi_registered(session_db, album_id) -> AlbumStatus:
    aid = to_uuid(album_id) if not isinstance(album_id, UUID) else album_id
    st = _ensure_album_status_row(session_db, aid)
    st.agedi_done = True
    st.agedi_updated_at = datetime.now(TZ_MADRID)
    st.updated_at = datetime.now(TZ_MADRID)
    session_db.add(st)
    return st


def _build_song_material_context(session_db, song: Song, material_rows: list[SongMaterial] | None = None) -> dict:
    if material_rows is None:
        material_rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )

    def row_payload(row: SongMaterial) -> dict:
        category = (getattr(row, "category", None) or "").strip().upper()
        slot_key = (getattr(row, "slot_key", None) or "DEFAULT").strip().upper()
        display_name = (getattr(row, "display_name", None) or "").strip() or None
        raw_name = (getattr(row, "file_name", None) or display_name or "archivo").replace("\\", "/")
        base_name = Path(raw_name).name or "archivo"
        # Lo que se COMPARTE es la página de previsualización, no el fichero (ver _material_share_url).
        share_url = _material_share_url("MATERIAL", song.id, ref=str(row.id))
        payload = {
            "id": str(row.id),
            "category": category,
            "slot_key": slot_key,
            "bundle_key": (getattr(row, "bundle_key", None) or "").strip(),
            "label": _song_material_slot_label(category, slot_key, display_name),
            "display_name": display_name,
            "file_name": raw_name,
            "base_name": base_name,
            "file_url": (getattr(row, "file_url", None) or "").strip(),
            "mime_type": (getattr(row, "mime_type", None) or "").strip(),
            "created_at": getattr(row, "created_at", None),
            "share_url": share_url,
            "download_original_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="original"),
            "download_jpg_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="jpg") if category == "COVER" else "",
            "download_png_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="png") if category == "COVER" else "",
            "download_wav_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="wav") if category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} else "",
            "download_mp3_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="mp3") if category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} else "",
            "download_mov_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="mov") if category in SONG_VIDEO_CATEGORIES else "",
            "download_mp4_url": url_for("discografica_song_material_download", song_id=song.id, material_id=row.id, format="mp4") if category in SONG_VIDEO_CATEGORIES else "",
            "is_audio": category in {"MASTER", "INSTRUMENTAL", "TV_TRACK", "STEMS"},
            "is_video": category in SONG_VIDEO_CATEGORIES,
            "poster_url": (getattr(row, "poster_url", None) or "").strip(),
            "is_pending": (getattr(row, "validation_status", None) or "VALIDATED").strip().upper() == "PENDING",
        }
        return payload

    cover_principal = None
    cover_provisional = None
    masters_default = {"MASTER_48": None, "MASTER_24": None, "MASTER_16": None}
    master_subproducts = []
    instrumental_default = None
    instrumental_subproducts = []
    tv_track_default = None
    tv_track_subproducts = []
    videoclip_default = None
    videoclip_subproducts = []
    video_thumbs: dict[str, list] = {}      # id del videoclip -> miniaturas subidas a mano
    video_rights: list = []                 # cesiones de derechos de imagen del videoclip
    stems_map: dict[str, dict] = {}

    for row in material_rows or []:
        category = (getattr(row, "category", None) or "").strip().upper()
        slot_key = (getattr(row, "slot_key", None) or "DEFAULT").strip().upper()
        payload = row_payload(row)
        if category == "COVER":
            if slot_key == "COVER_PROVISIONAL":
                if cover_provisional is None:
                    cover_provisional = payload
            elif cover_principal is None:
                cover_principal = payload
            continue
        if category == "MASTER":
            if slot_key in masters_default and masters_default[slot_key] is None:
                masters_default[slot_key] = payload
            else:
                master_subproducts.append(payload)
            continue
        if category == "INSTRUMENTAL":
            if slot_key == "DEFAULT" and instrumental_default is None:
                instrumental_default = payload
            else:
                instrumental_subproducts.append(payload)
            continue
        if category == "TV_TRACK":
            if slot_key == "DEFAULT" and tv_track_default is None:
                tv_track_default = payload
            else:
                tv_track_subproducts.append(payload)
            continue
        if category == "VIDEOCLIP":
            if slot_key == "DEFAULT" and videoclip_default is None:
                videoclip_default = payload
            else:
                videoclip_subproducts.append(payload)
            continue
        if category == "VIDEO_THUMB":
            # La miniatura sabe de qué vídeo es por su bundle_key (el id del videoclip).
            video_thumbs.setdefault(payload["bundle_key"] or "", []).append(payload)
            continue
        if category == "VIDEO_RIGHTS":
            video_rights.append(payload)
            continue
        if category == "STEMS":
            bundle_key = payload["bundle_key"] or payload["id"]
            group = stems_map.setdefault(bundle_key, {
                "bundle_key": bundle_key,
                "label": payload["display_name"] or "Stems",
                "rows": [],
                "created_at": payload["created_at"],
            })
            group["rows"].append(payload)
            if payload["created_at"] and (group["created_at"] is None or payload["created_at"] > group["created_at"]):
                group["created_at"] = payload["created_at"]

    if cover_principal is None and (getattr(song, "cover_url", None) or "").strip():
        cover_principal = {
            "id": "",
            "category": "COVER",
            "slot_key": "COVER",
            "bundle_key": "",
            "label": "Portada",
            "display_name": "Portada",
            "file_name": "portada",
            "base_name": "portada",
            "file_url": (song.cover_url or "").strip(),
            "mime_type": mimetypes.guess_type((song.cover_url or "").split("?", 1)[0])[0] or "",
            "created_at": getattr(song, "created_at", None),
            # Sin fila de material, la portada sale de Song.cover_url: aun así se comparte por
            # NUESTRO enlace (kind SONG_COVER), no por la URL cruda de Storage.
            "share_url": _material_share_url("SONG_COVER", song.id),
            "download_original_url": "",
            "download_jpg_url": "",
            "download_png_url": "",
            "download_wav_url": "",
            "download_mp3_url": "",
        }

    stem_groups = []
    for bundle_key, group in stems_map.items():
        share_url = _material_share_url("STEMS_BUNDLE", song.id, ref=bundle_key)
        group.update({
            "label": group["label"],
            "file_count": len(group["rows"]),
            "is_pending": any(r.get("is_pending") for r in group["rows"]),
            "share_url": share_url,
            "download_zip_url": url_for("discografica_song_stems_bundle_download", song_id=song.id, bundle_key=bundle_key),
        })
        stem_groups.append(group)
    stem_groups.sort(key=lambda item: item.get("created_at") or datetime.min.replace(tzinfo=TZ_MADRID), reverse=True)

    # Cada videoclip se lleva sus miniaturas y la que se enseña (la subida a mano manda sobre la
    # que saca ffmpeg; si no hay ninguna, el hueco enseña el icono).
    for item in [videoclip_default] + videoclip_subproducts:
        if not item:
            continue
        propias = video_thumbs.get(item["id"], [])
        item["thumbs"] = propias
        item["preview_url"] = (propias[0]["file_url"] if propias else item.get("poster_url") or "")

    completion = _song_material_completion_meta(song, material_rows or [])
    return {
        "cover_item": cover_principal,
        "cover_principal": cover_principal,
        "cover_provisional": cover_provisional,
        "masters_default": masters_default,
        "master_subproducts": master_subproducts,
        "instrumental_default": instrumental_default,
        "instrumental_subproducts": instrumental_subproducts,
        "tv_track_default": tv_track_default,
        "tv_track_subproducts": tv_track_subproducts,
        "videoclip_default": videoclip_default,
        "videoclip_subproducts": videoclip_subproducts,
        "video_rights": video_rights,
        "stem_groups": stem_groups,
        "completion": completion,
    }


# ---------------------------------------------------------------------------
# COMPARTIR MATERIALES (canción y álbum) · un solo enlace y una sola tarjeta
# ---------------------------------------------------------------------------
# Lo que se manda por correo/WhatsApp/SMS NUNCA es el fichero ni la URL de Storage:
# es SIEMPRE `public_material_view`, servida desde el dominio de la casa
# (_external_url_for → CANONICAL_HOST). Así la previsualización es idéntica en los
# tres canales: la PORTADA de imagen, «<Artista> · <Canción o Álbum>» de título y
# «Descarga · <tipo de material>» de subtítulo.
# ⚠️ Antes cada sitio compartía una cosa distinta —canción, el endpoint de descarga
# (un fichero: sin nada que previsualizar); álbum, el `file_url` crudo de Supabase
# (dominio ajeno)—, que es justo lo que había que unificar.
MATERIAL_SHARE_KINDS = {"MATERIAL", "STEMS_BUNDLE", "SONG_COVER", "ALBUM_MATERIAL"}

# Materiales de VÍDEO de una canción: el videoclip (y sus subproductos) y las miniaturas que se
# suben a mano para él. El audio sigue siendo .wav; el vídeo admite los contenedores de siempre.
SONG_VIDEO_CATEGORIES = {"VIDEOCLIP"}
# Cesiones de derechos de imagen del videoclip (documentos: PDF o foto).
SONG_VIDEO_RIGHTS_CATEGORY = "VIDEO_RIGHTS"
SONG_VIDEO_EXTENSIONS = {".mov", ".mp4", ".m4v", ".mkv", ".webm", ".avi"}
# En qué formatos se ofrece la descarga de un videoclip.
SONG_VIDEO_DOWNLOAD_FORMATS = (("mov", "MOV"), ("mp4", "MP4"))

ALBUM_MATERIAL_LABELS = {
    "COVER": "Portada",
    "DDP": "DDP",
    "BODEGON": "Bodegón",
    "PHYSICAL_DESIGN": "Diseño físico",
}


def _album_material_label(category: str | None, display_name: str | None = None) -> str:
    cat = (category or "").strip().upper()
    return ALBUM_MATERIAL_LABELS.get(cat) or ((display_name or "").strip() or "Archivo")


def _material_share_url(kind: str, owner_id, ref: str | None = None) -> str:
    """El enlace que se COMPARTE de un material: siempre la página de previsualización."""
    token = _make_public_song_share_token(kind, str(owner_id), ref=ref or "", fmt="")
    return _external_url_for("public_material_view", token=token)


def _album_cover_url(session_db, album) -> str:
    """Portada del álbum: la suya y, si todavía no la tiene, su material de portada."""
    url = (getattr(album, "cover_url", None) or "").strip()
    if url:
        return url
    row = (
        session_db.query(AlbumMaterial)
        .filter(AlbumMaterial.album_id == album.id)
        .filter(func.upper(AlbumMaterial.category) == "COVER")
        .order_by(AlbumMaterial.created_at.desc())
        .first()
    )
    return (getattr(row, "file_url", None) or "").strip()


def _material_share_context(session_db, payload: dict) -> dict | None:
    """La tarjeta de un material compartido (de canción o de álbum): lo que necesitan la
    página pública, su og:image y el botón de descargar. None si el enlace no vale."""
    kind = (payload or {}).get("kind") or ""
    kind = kind.strip().upper()
    if kind not in MATERIAL_SHARE_KINDS:
        return None
    owner_raw = (payload.get("sid") or "").strip()
    ref = (payload.get("ref") or "").strip()
    try:
        owner_id = to_uuid(owner_raw)
    except Exception:
        return None
    # El token se rehace igual que el recibido: el botón de descargar apunta al endpoint
    # de fichero con el MISMO token, así el enlace compartido sigue siendo uno solo.
    token = _make_public_song_share_token(kind, owner_raw, ref=ref, fmt=(payload.get("fmt") or ""))
    qs = "?token=" + quote_plus(token)

    if kind == "ALBUM_MATERIAL":
        album = session_db.get(Album, owner_id)
        if not album:
            return None
        try:
            row = session_db.get(AlbumMaterial, to_uuid(ref))
        except Exception:
            row = None
        if not row or str(row.album_id) != str(album.id):
            return None
        artist = session_db.get(Artist, album.artist_id) if getattr(album, "artist_id", None) else None
        cover = _album_cover_url(session_db, album)
        if (row.category or "").strip().upper() == "COVER" and not cover:
            cover = (row.file_url or "").strip()
        return {
            "kind": kind,
            "artist_name": (getattr(artist, "name", None) or "").strip() or "Artista",
            "artist_photo": (getattr(artist, "photo_url", None) or "").strip(),
            "release_title": (getattr(album, "title", None) or "").strip() or "—",
            "release_kind": _album_kind_label(album),
            "release_date": getattr(album, "release_date", None),
            "material_label": _album_material_label(row.category, row.file_name),
            "file_name": Path((row.file_name or "").replace("\\", "/")).name,
            "cover_url": cover,
            "download_url": _external_url_for("public_album_material_download") + qs,
        }

    song = session_db.get(Song, owner_id)
    if not song:
        return None
    artist = _song_primary_artist(session_db, song)
    ctx = {
        "kind": kind,
        "artist_name": (getattr(artist, "name", None) or "").strip() or "Artista",
        "artist_photo": (getattr(artist, "photo_url", None) or "").strip(),
        "release_title": (getattr(song, "title", None) or "").strip() or "—",
        "release_kind": "Single",
        "release_date": getattr(song, "release_date", None),
        "cover_url": (getattr(song, "cover_url", None) or "").strip(),
        "material_label": "Archivo",
        "file_name": "",
        "download_url": "",
    }

    if kind == "SONG_COVER":
        if not ctx["cover_url"]:
            return None
        ctx["material_label"] = "Portada"
        ctx["download_url"] = _external_url_for("public_song_material_download") + qs
        return ctx

    if kind == "STEMS_BUNDLE":
        rows = (
            session_db.query(SongMaterial)
            .filter(SongMaterial.song_id == song.id)
            .filter(SongMaterial.bundle_key == ref)
            .order_by(SongMaterial.created_at.asc())
            .all()
        )
        if not rows:
            return None
        n = len(rows)
        ctx["material_label"] = (getattr(rows[0], "display_name", None) or "").strip() or "Stems"
        ctx["file_name"] = f"{n} archivo{'' if n == 1 else 's'} (.zip)"
        ctx["download_url"] = _external_url_for("public_song_material_bundle_download") + qs
        return ctx

    try:
        row = session_db.get(SongMaterial, to_uuid(ref))
    except Exception:
        row = None
    if not row or str(row.song_id) != str(song.id):
        return None
    ctx["material_label"] = _song_material_slot_label(row.category, row.slot_key, row.display_name)
    ctx["file_name"] = Path((row.file_name or "").replace("\\", "/")).name
    ctx["download_url"] = _external_url_for("public_song_material_download") + qs
    if (row.category or "").strip().upper() == "COVER" and not ctx["cover_url"]:
        ctx["cover_url"] = (row.file_url or "").strip()
    return ctx


def _material_download_name(label: str, title: str, artist_name: str, ext: str = "") -> str:
    """El nombre con el que se baja un material: **«Tipo_Título_Artista»**
    (p. ej. «Master 48 bits_Nombre de la canción_Nombre del artista.wav»).

    Antes se bajaba con el nombre que traía el archivo subido («master_final_v3.wav»), que no dice
    de quién es: entregando material a un tercero eso era un problema real."""
    partes = [p for p in [(label or "").strip(), (title or "").strip(), (artist_name or "").strip()] if p]
    base = _safe_download_filename("_".join(partes) or "archivo", "archivo")
    return f"{base}{ext or ''}"


def _song_material_download_payload(session_db, row, fmt: str = "original") -> tuple:
    """(bytes, mimetype, nombre) de un material de canción, ya convertido al formato pedido.

    Punto ÚNICO de los DOS caminos de descarga —el interno de la ficha y el enlace público—, para
    que el archivo se llame igual se baje por donde se baje."""
    song = session_db.get(Song, row.song_id)
    artist = _song_primary_artist(session_db, song) if song else None
    label = _song_material_slot_label(row.category, row.slot_key, row.display_name)
    titulo = (getattr(song, "title", None) or "").strip()
    artista = (getattr(artist, "name", None) or "").strip()

    data, guessed = _download_remote_content(row.file_url)
    original_suffix = Path((row.file_name or "").replace("\\", "/")).suffix.lower()
    mimetype = (row.mime_type or guessed
                or mimetypes.guess_type((row.file_url or "").split("?", 1)[0])[0]
                or "application/octet-stream")
    ext = original_suffix or mimetypes.guess_extension(mimetype or "") or ""
    category = (row.category or "").strip().upper()
    fmt = (fmt or "original").strip().lower()
    try:
        if category == "COVER" and fmt in {"jpg", "jpeg", "png"}:
            data, mimetype, ext = _convert_image_content(data, fmt)
        elif category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} and fmt == "mp3":
            data, mimetype, ext = _convert_audio_content_to_mp3(data, original_suffix)
        elif category in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} and fmt == "wav":
            mimetype = mimetype or "audio/wav"
            ext = original_suffix or ".wav"
        elif category in SONG_VIDEO_CATEGORIES and fmt in {"mov", "mp4"}:
            data, mimetype, ext = _convert_video_content(data, fmt, original_suffix)
    except Exception:
        pass
    return data, mimetype, _material_download_name(label, titulo, artista, ext)


def _stems_archive_label(session_db, song, rows) -> str:
    """Nombre del ZIP de un grupo de stems: «Stems_Canción_Artista» (misma regla que el resto)."""
    etiqueta = (getattr((rows or [None])[0], "display_name", None) or "Stems").strip() or "Stems"
    artist = _song_primary_artist(session_db, song) if song else None
    return _material_download_name(etiqueta, (getattr(song, "title", None) or "").strip(),
                                   (getattr(artist, "name", None) or "").strip())


def _album_material_rows_payload(session_db, album, rows) -> list[dict]:
    """Los materiales de un álbum con su enlace de compartir (la página, no el fichero)."""
    out = []
    for row in rows or []:
        out.append({
            "id": str(row.id),
            "category": (row.category or "").strip().upper(),
            "label": _album_material_label(row.category, row.file_name),
            "file_name": (row.file_name or "").strip(),
            "file_url": (row.file_url or "").strip(),
            "mime_type": (row.mime_type or "").strip(),
            "share_url": _material_share_url("ALBUM_MATERIAL", album.id, ref=str(row.id)),
        })
    return out


def _bundle_song_material_rows_to_zip(rows: list[SongMaterial], archive_label: str | None = None) -> tuple[bytes, str]:
    buf = BytesIO()
    used = set()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for idx, row in enumerate(rows or [], start=1):
            content, _ctype = _download_remote_content(getattr(row, "file_url", None))
            fallback = f"archivo_{idx}"
            member_name = _safe_zip_member_name(getattr(row, "file_name", None), used, fallback)
            zf.writestr(member_name, content)
    filename_root = (archive_label or "stems").strip() or "stems"
    filename_root = filename_root.replace("/", "-").replace("\\", "-")
    return buf.getvalue(), f"{filename_root}.zip"


def _song_lyrics_meta(session_db, song: Song) -> dict:
    shares = (
        session_db.query(SongEditorialShare)
        .options(joinedload(SongEditorialShare.promoter))
        .filter(SongEditorialShare.song_id == song.id)
        .order_by(SongEditorialShare.created_at.asc())
        .all()
    )
    authors = []
    composers = []
    for sh in shares:
        promoter = getattr(sh, "promoter", None)
        full_name = " ".join([x for x in [
            (getattr(promoter, "first_name", None) or "").strip(),
            (getattr(promoter, "last_name", None) or "").strip(),
        ] if x]).strip()
        full_name = full_name or (getattr(promoter, "nick", None) or "").strip() or "—"
        role = (getattr(sh, "role", None) or "").strip().upper()
        if role == "AUTHOR":
            authors.append(full_name)
        elif role == "COMPOSER":
            composers.append(full_name)
        else:
            authors.append(full_name)
            composers.append(full_name)

    interpreters = [
        (getattr(row, "name", None) or "").strip()
        for row in (
            session_db.query(SongInterpreter)
            .filter(SongInterpreter.song_id == song.id)
            .order_by(SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc())
            .all()
        )
        if (getattr(row, "name", None) or "").strip()
    ]
    if not interpreters:
        interpreters = [a.name for a in (getattr(song, "artists", []) or []) if getattr(a, "name", None)]

    combined = bool(authors) and bool(composers) and authors == composers
    return {
        "authors": authors,
        "composers": composers,
        "interpreters": interpreters,
        "combined": combined,
    }


def _build_song_lyrics_pdf_bytes(session_db, song_id, *, include_logo: bool = True) -> tuple[bytes, str]:
    song = session_db.get(Song, to_uuid(song_id))
    if not song or not (getattr(song, "lyrics_text", None) or "").strip():
        raise LookupError("La canción no tiene letra guardada.")

    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm

    meta = _song_lyrics_meta(session_db, song)
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "SongLyricsTitle",
        parent=styles["Heading1"],
        fontName="Helvetica-Bold",
        fontSize=18,
        leading=22,
        spaceAfter=12,
        textColor=colors.HexColor("#1f2937"),
    )
    meta_label_style = ParagraphStyle(
        "SongLyricsMetaLabel",
        parent=styles["BodyText"],
        fontName="Helvetica-Bold",
        fontSize=9.5,
        leading=12,
        textColor=colors.HexColor("#111827"),
        spaceAfter=3,
    )
    meta_text_style = ParagraphStyle(
        "SongLyricsMetaText",
        parent=styles["BodyText"],
        fontSize=10,
        leading=13,
        textColor=colors.HexColor("#374151"),
        spaceAfter=6,
    )
    lyrics_style = ParagraphStyle(
        "SongLyricsBody",
        parent=styles["BodyText"],
        fontSize=10.5,
        leading=16,
        alignment=TA_JUSTIFY,
        textColor=colors.HexColor("#111827"),
        spaceAfter=10,
    )

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=2.1*cm, rightMargin=2.1*cm, topMargin=1.8*cm, bottomMargin=1.8*cm)
    story = []

    brand = _pies_brand_assets(session_db)
    logo = _rl_image_flowable_from_url(brand.get('logo_url'), 3.3, 1.05)
    if include_logo and logo:
        logo.hAlign = 'LEFT'
        story.append(logo)
        story.append(Spacer(1, 0.4*cm))

    story.append(Paragraph(f"Letra: {html.escape(song.title)}", title_style))

    if meta["combined"]:
        story.append(Paragraph("Autores y compositores", meta_label_style))
        story.append(Paragraph(html.escape(", ".join(meta["authors"]) or "—"), meta_text_style))
    else:
        story.append(Paragraph("Autores", meta_label_style))
        story.append(Paragraph(html.escape(", ".join(meta["authors"]) or "—"), meta_text_style))
        story.append(Paragraph("Compositores", meta_label_style))
        story.append(Paragraph(html.escape(", ".join(meta["composers"]) or "—"), meta_text_style))

    story.append(Paragraph("Intérpretes", meta_label_style))
    story.append(Paragraph(html.escape(", ".join(meta["interpreters"]) or "—"), meta_text_style))
    story.append(Spacer(1, 0.35*cm))

    lyrics_text = (song.lyrics_text or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    paragraphs = [chunk.strip() for chunk in lyrics_text.split("\n\n") if chunk.strip()] or [lyrics_text]
    for chunk in paragraphs:
        safe_chunk = html.escape(chunk).replace("\n", "<br/>")
        story.append(Paragraph(safe_chunk, lyrics_style))

    doc.build(story)
    filename = f"Letra - {song.title}".replace("/", "-").replace("\\", "-").strip() or "Letra"
    return buf.getvalue(), f"{filename}.pdf"




def _rl_image_flowable_from_url(file_url: str | None, width_cm: float, height_cm: float):
    if not file_url:
        return None
    try:
        from reportlab.lib.units import cm
        target = (file_url or "").strip()
        # ReportLab puede leer rutas locales directamente; esto evita depender
        # de que el servidor pueda descargarse a sí mismo los assets estáticos.
        if target.startswith("/static/") or target.startswith("static/"):
            rel = target.lstrip("/")
            local_path = Path(app.root_path) / rel
            if local_path.exists():
                return RLImage(str(local_path), width=width_cm * cm, height=height_cm * cm)
        if not re.match(r"^https?://", target, flags=re.I):
            local_path = Path(target)
            if not local_path.is_absolute():
                local_path = Path(app.root_path) / target
            if local_path.exists():
                return RLImage(str(local_path), width=width_cm * cm, height=height_cm * cm)
        data, _ = _download_remote_content(target)
        return RLImage(BytesIO(data), width=width_cm * cm, height=height_cm * cm)
    except Exception:
        return None


# El ALCANCE de un cambio de editorial de un autor.
PUBLISHER_SCOPE_ONE = "ONE"          # solo en esta canción (el snapshot del registro)
PUBLISHER_SCOPE_FORWARD = "FORWARD"  # y en su ficha, para las canciones de aquí en adelante


def _publisher_change_info(session_db, promoter, editorial) -> dict | None:
    """¿Este autor CAMBIA de editorial? Devuelve el aviso (`antes`/`ahora`) o None si no cambia.

    ⚠️ La editorial de un autor puede cambiar a partir de una fecha o de un tema, así que el cambio
    **hay que preguntarlo**: puntual (solo esta canción) o de aquí en adelante. Punto único: lo usan
    la ficha, la entrega de masters y las demos."""
    if promoter is None or editorial is None:
        return None
    actual = getattr(promoter, "publishing_company_id", None)
    if actual and str(actual) == str(editorial.id):
        return None                       # no cambia nada
    antes = session_db.get(PublishingCompany, actual) if actual else None
    return {
        "promoter_id": str(promoter.id),
        "promoter_name": _promoter_display_name(promoter) or "—",
        "before_id": (str(actual) if actual else ""),
        "before_name": ((getattr(antes, "name", "") or "").strip() or "sin editorial"),
        "after_id": str(editorial.id),
        "after_name": (editorial.name or "").strip(),
    }


def _publisher_apply_change(session_db, promoter, editorial, scope: str) -> None:
    """Aplica el cambio de editorial de un autor según su ALCANCE.

    · `ONE` → **solo esta canción**: el registro guarda su snapshot y la ficha del autor no se toca.
    · `FORWARD` → además se cambia en su ficha, así que vale **de aquí en adelante**.
    ⚠️ En ninguno de los dos casos se tocan los registros ANTERIORES: cada uno conserva la editorial
    que tenía congelada el día que se guardó (`SongEditorialShare.publishing_company_id`).
    """
    if promoter is None or editorial is None:
        return
    if (scope or "").strip().upper() == PUBLISHER_SCOPE_FORWARD:
        promoter.publishing_company_id = editorial.id
        session_db.add(promoter)


def _share_publisher(share):
    """Editorial efectiva de un registro de autoría.

    Devuelve el snapshot guardado en el propio registro (`SongEditorialShare`) y, si no lo
    tiene (registros antiguos), la editorial actual del tercero (compatibilidad hacia atrás).
    """
    pub = getattr(share, "publishing_company", None)
    if pub is not None:
        return pub
    promoter = getattr(share, "promoter", None)
    return getattr(promoter, "publishing_company", None) if promoter else None


# ============================ REPARTO EDITORIAL (autor de Plataforma ↔ Plataforma Musical) =========
# La parte autoral que le corresponde a un autor NUESTRO (editorial «Plataforma Musical») no es toda
# suya: se reparte con nosotros según el compromiso **EDITORIAL** de su contrato («oficina» =
# Plataforma Musical). Ejemplo: si el autor tiene el 60% de la obra y el contrato editorial es 50/50,
# sobre el conjunto de la obra le quedan un 30% al autor y un 30% a Plataforma.
#
# Manda lo VIGENTE EL DÍA DEL REGISTRO (por si las condiciones cambian): al registrar la obra en SGAE
# el reparto se **congela** en el propio registro de autoría. Con «reparto especial» se fija a mano
# (los dos porcentajes suman siempre 100 sobre la parte del autor) y eso pisa al contrato.
EDITORIAL_CONTRACT_CONCEPTS = ["editorial", "editoriales", "edición", "edicion",
                              "editorial musical", "derechos editoriales", "publishing"]
PLATFORM_PUBLISHER_NAME = "plataforma musical"


# ============ COMUNICACIONES DE UN ARTISTA: quién recibe qué (módulo «Notificaciones») ============
# Se configura en la ficha del artista y manda en TODA la app de ese momento en adelante: quien esté
# marcado en un canal es quien recibe los correos de ese concepto.
ARTIST_NOTIFICATION_CHANNELS = [
    # ⚠️ Los dos primeros son los que se usan para AVISAR AL ARTISTA DE UNA ACTIVIDAD antes de
    # confirmarla: si la actividad lleva caché se avisa a los de ACTIVIDADES_CACHE y si no a los de
    # ACTIVIDADES_SIN_CACHE (punto único `_activity_notification_channel`).
    ("ACTIVIDADES_CACHE", "Nuevas actividades con caché", "fa-calendar-check"),
    ("ACTIVIDADES_SIN_CACHE", "Actividades sin caché", "fa-calendar-day"),
    ("LIQUIDACIONES", "Liquidaciones", "fa-file-invoice-dollar"),
    ("PRODUCCION", "Producción", "fa-screwdriver-wrench"),
    ("DISCOGRAFICA", "Discográfica", "fa-compact-disc"),
    ("EDITORIAL", "Editorial", "fa-pen-nib"),
    ("PROMOCION", "Promoción", "fa-bullhorn"),
    ("INVITACIONES", "Invitaciones", "fa-envelope-open-text"),
    # Los avisos de CONTENIDOS y publicaciones (el cronograma del plan de lanzamiento y el
    # recordatorio de cada publicación).
    ("CONTENIDOS", "Contenidos y publicaciones", "fa-photo-film"),
    # Quién más tiene que APROBAR la mezcla final, los materiales o la portada (además de los
    # integrantes del artista y de los colaboradores, que salen solos).
    ("APROBACIONES", "Aprobación de mezclas y materiales", "fa-thumbs-up"),
]
# Los canales de aviso de una actividad, por si lleva caché o no.
ACTIVITY_NOTIFICATION_CHANNELS = ("ACTIVIDADES_CACHE", "ACTIVIDADES_SIN_CACHE")
ARTIST_NOTIFICATION_CHANNEL_KEYS = [k for k, _l, _i in ARTIST_NOTIFICATION_CHANNELS]
ARTIST_NOTIFICATION_CHANNEL_LABELS = {k: l for k, l, _i in ARTIST_NOTIFICATION_CHANNELS}
ARTIST_NOTIFICATION_CHANNEL_ICONS = {k: i for k, _l, i in ARTIST_NOTIFICATION_CHANNELS}


def _artist_liquidation_concepts(session_db, artist_id) -> list[str]:
    """Los CONCEPTOS de ingreso que tiene configurados el contrato del artista (discográfico,
    editorial, catálogo, distribución…). Son las liquidaciones que puede recibir cada persona."""
    aid = to_uuid(str(artist_id or ""))
    if not aid:
        return []
    salida, vistos = [], set()
    try:
        filas = (session_db.query(ArtistContractCommitment.concept)
                 .join(ArtistContract, ArtistContract.id == ArtistContractCommitment.contract_id)
                 .filter(ArtistContract.artist_id == aid).all())
    except Exception:
        filas = []
    for (concepto,) in filas:
        texto = (concepto or "").strip()
        clave = _norm_text_key(texto)
        if not texto or clave in vistos:
            continue
        vistos.add(clave)
        salida.append(texto)
    # Los royalties se liquidan siempre (es la liquidación por excelencia), aunque el contrato no los
    # nombre con esa palabra.
    if "royalties" not in {_norm_text_key(x) for x in salida}:
        salida.insert(0, "Royalties")
    return salida


def _artist_notification_contacts(session_db, artist_id) -> list:
    """Los contactos de comunicaciones de un artista (los de su módulo «Notificaciones»)."""
    aid = to_uuid(str(artist_id or ""))
    if not aid:
        return []
    return (session_db.query(ArtistNotificationContact)
            .options(joinedload(ArtistNotificationContact.promoter))
            .filter(ArtistNotificationContact.artist_id == aid)
            .order_by(ArtistNotificationContact.created_at.asc()).all())


def _contact_email(contact) -> str:
    """El correo de un contacto: el que se puso a mano o el de la ficha del tercero."""
    directo = (getattr(contact, "email", None) or "").strip()
    if directo:
        return directo
    prom = getattr(contact, "promoter", None)
    return (getattr(prom, "contact_email", None) or "").strip()


def _contact_phone(contact) -> str:
    """El teléfono de un contacto (para WhatsApp / SMS): el que se puso a mano o el de su ficha."""
    directo = (getattr(contact, "phone", None) or "").strip()
    if directo:
        return directo
    prom = getattr(contact, "promoter", None)
    return (getattr(prom, "contact_phone", None) or "").strip()


def _contact_name(contact) -> str:
    nombre = (getattr(contact, "name", None) or "").strip()
    if nombre:
        return nombre
    prom = getattr(contact, "promoter", None)
    return (_promoter_display_name(prom) or (getattr(prom, "nick", None) or "").strip() or "Contacto")


def _artist_notification_emails(session_db, artist_id, channel, *, concept=None,
                                fallback=True) -> list[str]:
    """A QUIÉN se le manda una comunicación de este artista por ese canal.

    Es el punto ÚNICO que usa toda la app: lo que se configure en el módulo «Notificaciones» de la
    ficha manda de ese momento en adelante. En LIQUIDACIONES, si se dice el `concept` solo reciben
    quienes lo tengan marcado (o quienes no hayan marcado ninguno: eso significa «todas»).
    Con `fallback` (por defecto) y sin nadie configurado, se cae al correo del artista y a sus correos
    adicionales, que es lo que había antes: así no deja de llegar nada por no haberlo configurado."""
    aid = to_uuid(str(artist_id or ""))
    canal = (channel or "").strip().upper()
    if not aid or canal not in ARTIST_NOTIFICATION_CHANNEL_KEYS:
        return []
    salida, vistos = [], set()
    for c in _artist_notification_contacts(session_db, aid):
        canales = {str(x).strip().upper() for x in (getattr(c, "channels", None) or [])}
        if canal not in canales:
            continue
        if canal == "LIQUIDACIONES" and concept:
            marcados = {_norm_text_key(x) for x in (getattr(c, "liquidation_concepts", None) or [])}
            if marcados and _norm_text_key(concept) not in marcados:
                continue
        correo = _contact_email(c)
        clave = correo.lower()
        if correo and "@" in correo and clave not in vistos:
            vistos.add(clave)
            salida.append(correo)
    if salida or not fallback:
        return salida
    # Nada configurado: como antes (correo principal del artista + sus correos adicionales).
    try:
        artist = session_db.get(Artist, aid)
        principal = (getattr(artist, "email", None) or "").strip()
        if principal and "@" in principal:
            salida.append(principal)
            vistos.add(principal.lower())
        for row in (session_db.query(ArtistEmail)
                    .filter(ArtistEmail.artist_id == aid).all()):
            correo = (getattr(row, "email", None) or "").strip()
            if correo and "@" in correo and correo.lower() not in vistos:
                vistos.add(correo.lower())
                salida.append(correo)
    except Exception:
        pass
    return salida


def _artist_notification_recipients(session_db, artist_id, channel, *, fallback=True) -> list[dict]:
    """A QUIÉN se avisa por ese canal, con nombre, correo y TELÉFONO.

    Hermano de `_artist_notification_emails` para los avisos que también salen por WhatsApp o SMS
    (el aviso de una actividad). Devuelve [{'name', 'email', 'phone'}] en el orden configurado.
    ⚠️ Con `fallback` y sin nadie marcado se cae al correo del artista: mejor eso que no avisar a
    nadie. Del teléfono no hay fallback posible (el artista no tiene columna de teléfono)."""
    aid = to_uuid(str(artist_id or ""))
    canal = (channel or "").strip().upper()
    if not aid or canal not in ARTIST_NOTIFICATION_CHANNEL_KEYS:
        return []
    filas, vistos = [], set()
    for c in _artist_notification_contacts(session_db, aid):
        canales = {str(x).strip().upper() for x in (getattr(c, "channels", None) or [])}
        if canal not in canales:
            continue
        correo = _contact_email(c)
        telefono = _contact_phone(c)
        clave = (correo.lower(), telefono)
        if not (correo or telefono) or clave in vistos:
            continue
        vistos.add(clave)
        filas.append({"name": _contact_name(c), "email": correo, "phone": telefono})
    if filas or not fallback:
        return filas
    for correo in _artist_notification_emails(session_db, aid, canal, fallback=True):
        filas.append({"name": "", "email": correo, "phone": ""})
    return filas


def _publisher_is_platform(publisher) -> bool:
    """¿Esta editorial somos NOSOTROS (Plataforma Musical)?

    ⚠️ Se compara con TOLERANCIA: el nombre lo escribe una persona al dar de alta la editorial, así
    que en la base aparece como «Plataforma Musical», «Plataforma Musical S.L.», «PLATAFORMA MUSICAL
    SL»… Con una igualdad exacta, cualquiera de esas variantes dejaba de ser «nuestra» y el autor se
    quedaba **sin su reparto editorial y sin que se pintara nada** en la ficha (el bloque entero
    cuelga de `is_platform`). Basta con que el nombre CONTENGA «plataforma musical»."""
    nombre = _norm_text_key(getattr(publisher, "name", "") or "")
    if not nombre:
        return False
    patron = _norm_text_key(PLATFORM_PUBLISHER_NAME)
    return nombre == patron or (bool(patron) and patron in nombre)


def _share_split_frozen(share) -> bool:
    """¿Este registro de autoría YA tiene su reparto fijado (a mano o congelado al registrar)?"""
    if bool(getattr(share, "special_split", False)) and (
            getattr(share, "special_pct_author", None) is not None
            or getattr(share, "special_pct_platform", None) is not None):
        return True
    return getattr(share, "split_pct_author", None) is not None


def _share_split_applies_live(share) -> bool:
    """¿Se le puede CALCULAR hoy el reparto a esta parte autoral?

    Manda la editorial **DEL REGISTRO** (la que quedó congelada en `SongEditorialShare` el día que se
    guardó): eso es lo pactado para ESA obra, y es la regla de la casa desde que la editorial se
    congela por registro.

    ⚠️⚠️ Antes se exigía ADEMÁS que la ficha del tercero tuviera hoy editorial de Plataforma, y eso
    se convirtió en un fallo en cuanto el cambio de editorial pasó a ser **«solo en esta canción»**
    por defecto: la ficha del autor ya no se toca al guardarlo, así que se quedaba sin editorial y
    **el reparto dejaba de aplicarse aunque el registro dijera Plataforma** (caso real: un integrante
    con contrato editorial al que no se le aplicaba nada). La ficha del tercero solo decide en los
    registros ANTIGUOS, que no llevan editorial propia y se caen a la suya."""
    if not _publisher_is_platform(_share_publisher(share)):
        return False
    if getattr(share, "publishing_company_id", None):
        return True                      # el registro trae su editorial: es lo pactado para la obra
    promoter = getattr(share, "promoter", None)
    return _publisher_is_platform(getattr(promoter, "publishing_company", None) if promoter else None)


def _song_registration_date(session_db, song, status=None):
    """Día en que se REGISTRA la obra (el registro en SGAE). Mientras no esté registrada devuelve
    None: se enseña el reparto que tocaría hoy, que es una previsión."""
    if song is None:
        return None
    st = status if status is not None else session_db.get(SongStatus, getattr(song, "id", None))
    if not st or not bool(getattr(st, "sgae_done", False)):
        return None
    when = getattr(st, "sgae_updated_at", None)
    try:
        return when.date() if when is not None else None
    except Exception:
        return None


def _artist_editorial_split(session_db, artist_id, *, as_of=None, material_date=None) -> dict:
    """Reparto editorial del contrato del artista vigente en `as_of` (hoy si no se dice otra cosa)."""
    salida = {"found": False, "pct_author": None, "pct_platform": None,
              "contract_name": "", "signed_date": None}
    if not artist_id:
        return salida
    try:
        commitment, contract = _pick_artist_commitment(
            session_db, to_uuid(str(artist_id)), EDITORIAL_CONTRACT_CONCEPTS,
            material_date=material_date, as_of_date=(as_of or today_local()))
    except Exception:
        # ⚠️ Sin log, un fallo aquí (p. ej. comparar fechas con y sin zona horaria al ordenar los
        # compromisos) sale por pantalla como «este artista no tiene contrato editorial», que es
        # indistinguible de la verdad y manda a buscar el problema donde no está.
        app.logger.exception("No se pudo resolver el contrato editorial del artista %s", artist_id)
        return salida
    if commitment is None:
        return salida
    autor = float(getattr(commitment, "pct_artist", 0) or 0)
    plataforma = float(getattr(commitment, "pct_office", 0) or 0)
    return {
        "found": True,
        "pct_author": round(autor, 2),
        "pct_platform": round(plataforma, 2),
        "contract_name": (getattr(contract, "name", "") or "").strip(),
        "signed_date": getattr(contract, "signed_date", None),
    }


def _promoter_member_artist_ids(session_db, promoter_id) -> list[str]:
    """De qué ARTISTAS es INTEGRANTE este tercero (`ArtistPerson.promoter_id`).

    Un autor de una canción casi nunca es «el artista»: es una persona que forma parte de él (el
    cantante del grupo, el guitarrista). El contrato se firma con el ARTISTA, así que para saber qué
    contrato le toca a un autor hay que subir del integrante a su artista."""
    pid = to_uuid(str(promoter_id or ""))
    if not pid:
        return []
    # ⚠️ El caché vive en `g`, que SOLO existe dentro de una petición: esto se llama también desde
    # el relleno del arranque y desde un hilo, y ahí `getattr(g, ...)` revienta con «Working
    # outside of application context» (bug real). Sin contexto simplemente no se cachea.
    cache = None
    try:
        cache = getattr(g, "_member_artist_cache", None)
        if cache is None:
            cache = {}
            g._member_artist_cache = cache
    except Exception:
        cache = {}
    clave = str(pid)
    if clave in cache:
        return cache[clave]
    try:
        filas = (session_db.query(ArtistPerson.artist_id)
                 .filter(ArtistPerson.promoter_id == pid).all())
        salida = [str(x[0]) for x in filas if x and x[0]]
    except Exception:
        salida = []
    cache[clave] = salida
    return salida


def _editorial_split_for_author(session_db, song, share, *, as_of=None, material_date=None) -> dict:
    """El reparto editorial que le toca a ESTE autor.

    ⚠️ El contrato se configura con el **ARTISTA**, y los autores son sus **INTEGRANTES**: por eso se
    busca el contrato del artista del que el autor forma parte (`ArtistPerson`). Si el autor está en
    varios artistas se prefiere el de la propia canción; y si no es integrante de ninguno, se cae al
    artista principal de la canción (el caso de un solista que figura como autor de su propia obra).
    Antes se usaba SIEMPRE el artista de la canción, así que a los integrantes no se les detectaba el
    contrato (bug real)."""
    principal = _song_primary_artist(session_db, song)
    pid_principal = str(getattr(principal, "id", "") or "")
    candidatos = []
    del_autor = _promoter_member_artist_ids(session_db, getattr(share, "promoter_id", None))
    if pid_principal and pid_principal in del_autor:
        candidatos.append(pid_principal)          # es integrante del artista de la canción
    candidatos.extend([x for x in del_autor if x != pid_principal])
    if pid_principal and pid_principal not in candidatos:
        candidatos.append(pid_principal)          # último recurso: el artista de la canción
    for aid in candidatos:
        info = _artist_editorial_split(session_db, aid, as_of=as_of, material_date=material_date)
        if info["found"]:
            return info
    return {"found": False, "pct_author": None, "pct_platform": None,
            "contract_name": "", "signed_date": None}


def _song_editorial_split_map(session_db, song, shares=None, status=None) -> dict:
    """Cómo se reparte la parte de CADA autor de Plataforma, por id de registro de autoría.

    Cada entrada trae la parte autoral del autor en la obra (`pct`), los porcentajes del reparto de
    ESA parte (`pct_author`/`pct_platform`, que suman 100) y lo que supone cada uno **sobre el
    conjunto de la obra** (`final_author`/`final_platform`)."""
    if song is None:
        return {}
    if shares is None:
        shares = (
            session_db.query(SongEditorialShare)
            .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company),
                     joinedload(SongEditorialShare.publishing_company))
            .filter(SongEditorialShare.song_id == song.id)
            .order_by(SongEditorialShare.created_at.asc())
            .all()
        )
    reg_date = _song_registration_date(session_db, song, status=status)
    salida = {}
    for share in shares or []:
        # Lo que ya está FIJADO (congelado al registrar o a mano) se enseña siempre, aunque el autor
        # haya dejado de ser de Plataforma: lo anterior se mantiene. Lo que no está fijado solo se
        # calcula mientras el autor siga siendo nuestro.
        if not (_share_split_frozen(share) or _share_split_applies_live(share)):
            continue
        # El contrato es del ARTISTA del que este autor es INTEGRANTE (no el de la canción a secas).
        contrato = _editorial_split_for_author(
            session_db, song, share,
            as_of=reg_date, material_date=getattr(song, "release_date", None))
        pct = float(getattr(share, "pct", 0) or 0)
        autor = plataforma = None
        fuente = "none"
        if bool(getattr(share, "special_split", False)):
            autor = getattr(share, "special_pct_author", None)
            plataforma = getattr(share, "special_pct_platform", None)
            if autor is not None or plataforma is not None:
                fuente = "special"
        if fuente == "none" and getattr(share, "split_pct_author", None) is not None:
            # Congelado el día del registro: no se mueve aunque cambie el contrato.
            autor = getattr(share, "split_pct_author", None)
            plataforma = getattr(share, "split_pct_platform", None)
            fuente = "frozen"
        if fuente == "none" and contrato["found"]:
            autor, plataforma = contrato["pct_author"], contrato["pct_platform"]
            fuente = "contract"
        if fuente == "none":
            salida[str(share.id)] = {"pct": round(pct, 2), "source": "none", "contract": contrato,
                                     "registration_date": reg_date}
            continue
        autor = float(autor or 0)
        plataforma = float(plataforma or 0)
        total = autor + plataforma
        if total <= 0:
            autor, plataforma, total = 100.0, 0.0, 100.0
        elif abs(total - 100.0) > 0.01:
            # El reparto de la parte del autor SIEMPRE suma 100: si un contrato antiguo trae otra cosa
            # (p. ej. 50/25), se normaliza en vez de inventar un porcentaje de la obra que no cuadra.
            autor, plataforma = autor * 100.0 / total, plataforma * 100.0 / total
        salida[str(share.id)] = {
            "pct": round(pct, 2),
            "pct_author": round(autor, 2),
            "pct_platform": round(plataforma, 2),
            "final_author": round(pct * autor / 100.0, 2),
            "final_platform": round(pct * plataforma / 100.0, 2),
            "source": fuente,
            "contract": contrato,
            "registration_date": reg_date,
        }
    return salida


def _freeze_song_editorial_split(session_db, song, shares=None) -> None:
    """Congela en cada parte de autor de Plataforma el reparto del contrato vigente HOY (el día del
    registro). Solo se congela lo que no lo estaba: lo ya registrado no se reescribe."""
    if song is None:
        return
    if shares is None:
        shares = (
            session_db.query(SongEditorialShare)
            .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company),
                     joinedload(SongEditorialShare.publishing_company))
            .filter(SongEditorialShare.song_id == song.id)
            .all()
        )
    for share in shares or []:
        # Si el autor ya no es de Plataforma no se congela nada nuevo: de ahí en adelante no se aplican
        # porcentajes (lo que se registró cuando era nuestro ya está congelado y se mantiene).
        if not _share_split_applies_live(share):
            continue
        if bool(getattr(share, "special_split", False)):
            continue
        if getattr(share, "split_pct_author", None) is not None:
            continue
        # Cada autor con el contrato de SU artista (el que lo tiene como integrante).
        contrato = _editorial_split_for_author(
            session_db, song, share,
            as_of=today_local(), material_date=getattr(song, "release_date", None))
        if not contrato["found"]:
            continue
        share.split_pct_author = contrato["pct_author"]
        share.split_pct_platform = contrato["pct_platform"]
        share.split_frozen_at = datetime.now(TZ_MADRID)
        session_db.add(share)


# ---- Relleno PUNTUAL del reparto editorial de las obras que ya estaban registradas ----------------
# ⚠️ Esto NO es la norma. La norma es la de arriba: el reparto se congela **al registrar** la obra en
# SGAE. Esto es un relleno de UNA SOLA VEZ (marca en `AppSetting`) para poner al día las obras que ya
# estaban registradas antes de que existiera el reparto, respetando las dos reglas de siempre:
#   · manda el contrato editorial VIGENTE EL DÍA DE SU REGISTRO — si después se firmó otro con
#     porcentajes distintos, ese solo vale de su firma en adelante (`as_of_date` + `material_scope`);
#   · si el autor ya no es de Plataforma Musical (le cambiaron la editorial o se la quitaron), de ahí
#     en adelante no se le aplica nada, y lo anterior se queda como estaba.
# Las obras que AÚN NO están registradas no se tocan a propósito: su reparto se decide el día que se
# registren, y hasta entonces la ficha ya lo enseña calculado con el contrato de hoy.
EDITORIAL_SPLIT_BACKFILL_KEY = "editorial_split_backfill_v1"


def _editorial_split_backfill(session_db=None) -> dict:
    """Congela el reparto editorial de las obras YA REGISTRADAS que no lo tenían. Devuelve el recuento."""
    propia = session_db is None
    if propia:
        session_db = db()
    salida = {"revisadas": 0, "congeladas": 0, "ya_fijadas": 0,
              "sin_registrar": 0, "sin_contrato": 0, "obras": 0, "error": False}
    try:
        plataforma = (session_db.query(PublishingCompany)
                      .filter(func.lower(PublishingCompany.name) == PLATFORM_PUBLISHER_NAME)
                      .first())
        if plataforma is None:
            return salida
        # Partes de autoría que son de Plataforma: por el snapshot del propio registro o, en los
        # registros antiguos que no lo tienen, por la editorial actual del tercero.
        shares = (
            session_db.query(SongEditorialShare)
            .join(Promoter, Promoter.id == SongEditorialShare.promoter_id)
            .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company),
                     joinedload(SongEditorialShare.publishing_company))
            .filter(or_(SongEditorialShare.publishing_company_id == plataforma.id,
                        and_(SongEditorialShare.publishing_company_id.is_(None),
                             Promoter.publishing_company_id == plataforma.id)))
            .all()
        )
        if not shares:
            return salida
        song_ids = sorted({sh.song_id for sh in shares if sh.song_id}, key=lambda x: str(x))
        canciones = {c.id: c for c in (session_db.query(Song)
                                       .options(selectinload(Song.artists))
                                       .filter(Song.id.in_(song_ids)).all())}
        estados = {r.song_id: r for r in (session_db.query(SongStatus)
                                          .filter(SongStatus.song_id.in_(song_ids)).all())
                   if r and r.song_id}
        ahora = datetime.now(TZ_MADRID)
        tocadas = set()
        for share in shares:
            salida["revisadas"] += 1
            if _share_split_frozen(share):
                salida["ya_fijadas"] += 1
                continue
            song = canciones.get(share.song_id)
            estado = estados.get(share.song_id)
            if song is None or not bool(getattr(estado, "sgae_done", False)):
                salida["sin_registrar"] += 1
                continue
            # El día que se registró la obra: es el que decide qué condiciones se le aplican. Si no
            # quedó apuntado, se usa su fecha de publicación (nunca un contrato posterior).
            registrado = getattr(estado, "sgae_updated_at", None)
            try:
                fecha = registrado.date() if registrado is not None else None
            except Exception:
                fecha = None
            fecha = fecha or getattr(song, "release_date", None) or today_local()
            contrato = _editorial_split_for_author(
                session_db, song, share,
                as_of=fecha, material_date=getattr(song, "release_date", None))
            if not contrato["found"]:
                salida["sin_contrato"] += 1
                continue
            share.split_pct_author = contrato["pct_author"]
            share.split_pct_platform = contrato["pct_platform"]
            share.split_frozen_at = ahora
            session_db.add(share)
            salida["congeladas"] += 1
            tocadas.add(str(share.song_id))
        salida["obras"] = len(tocadas)
        session_db.commit()
    except Exception:
        session_db.rollback()
        salida["error"] = True
        app.logger.exception("_editorial_split_backfill")
    finally:
        if propia:
            session_db.close()
    return salida


def _editorial_split_backfill_once():
    """El relleno de arriba, UNA SOLA VEZ (marca en `AppSetting`). No se repite en cada arranque."""
    if (_get_app_setting(EDITORIAL_SPLIT_BACKFILL_KEY) or "").strip() == "done":
        return
    # `_promoter_member_artist_ids` cachea en `g`, así que hace falta contexto de aplicación (esto
    # corre en el hilo del arranque, fuera de una petición).
    with app.app_context():
        datos = _editorial_split_backfill()
    if datos.get("error"):
        # Si se ha caído a medias NO se marca: así el siguiente arranque lo vuelve a intentar en vez
        # de dejar las obras antiguas sin poner al día para siempre.
        return
    _set_app_setting(EDITORIAL_SPLIT_BACKFILL_KEY, "done")
    app.logger.info("Reparto editorial puesto al día: %s partes de autoría congeladas en %s obras "
                    "(%s ya lo tenían, %s sin registrar en SGAE, %s sin contrato editorial), de %s "
                    "revisadas.", datos["congeladas"], datos["obras"], datos["ya_fijadas"],
                    datos["sin_registrar"], datos["sin_contrato"], datos["revisadas"])


def _song_editorial_split_rows(session_db, song, status=None) -> list[dict]:
    """El reparto editorial listo para pintar (PDF del LC de reparto editorial y correos)."""
    shares = (
        session_db.query(SongEditorialShare)
        .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company),
                 joinedload(SongEditorialShare.publishing_company))
        .filter(SongEditorialShare.song_id == song.id)
        .order_by(SongEditorialShare.created_at.asc())
        .all()
    )
    mapa = _song_editorial_split_map(session_db, song, shares=shares, status=status)
    filas = []
    for share in shares:
        info = mapa.get(str(share.id))
        if not info or info.get("source") == "none":
            continue
        filas.append({
            "author_name": _promoter_display_name(getattr(share, "promoter", None)) or "—",
            "pct": info["pct"],
            "pct_author": info["pct_author"],
            "pct_platform": info["pct_platform"],
            "final_author": info["final_author"],
            "final_platform": info["final_platform"],
            "special": info["source"] == "special",
        })
    return filas


def _song_label_copy_author_rows(session_db, song: Song) -> tuple[list[list[str]], float]:
    shares = (
        session_db.query(SongEditorialShare)
        .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company))
        .filter(SongEditorialShare.song_id == song.id)
        .order_by(SongEditorialShare.created_at.asc())
        .all()
    )
    role_labels = {
        'AUTHOR': 'Autor',
        'COMPOSER': 'Compositor',
        'AUTHOR_COMPOSER': 'Autor y Compositor',
    }
    rows = []
    total_pct = 0.0
    for share in shares or []:
        promoter = share.promoter
        publisher = _share_publisher(share)
        pct = float(getattr(share, 'pct', 0) or 0)
        total_pct += pct
        rows.append([
            _promoter_display_name(promoter) or '—',
            role_labels.get((getattr(share, 'role', None) or '').strip().upper(), '—'),
            (getattr(publisher, 'name', None) or '').strip() or '—',
            f"{pct:.2f}%",
        ])
    return rows, round(total_pct, 2)


def _song_label_copy_isrc_lines(session_db, song: Song) -> list[str]:
    rows = (
        session_db.query(SongISRCCode)
        .filter(SongISRCCode.song_id == song.id)
        .order_by(SongISRCCode.kind.asc(), SongISRCCode.is_primary.desc(), SongISRCCode.created_at.asc())
        .all()
    )
    lines = []
    seen = set()
    for row in rows or []:
        code = _norm_isrc(getattr(row, 'code', None))
        if not code or code in seen:
            continue
        seen.add(code)
        kind = (getattr(row, 'kind', None) or '').strip().upper()
        lines.append(f"{'Vídeo' if kind == 'VIDEO' else 'Audio'}: {code}")
    main_isrc = _norm_isrc(getattr(song, 'isrc', None))
    if main_isrc and main_isrc not in seen:
        lines.insert(0, f"Audio: {main_isrc}")
    return lines


def _platform_links_for_item(item) -> list[dict]:
    specs = [
        ('spotify', 'Spotify', 'fa-brands fa-spotify', 'spotify_url', 'platform-spotify', 'img/platforms/spotify.png'),
        ('apple_music', 'Apple Music', 'fa-brands fa-apple', 'apple_music_url', 'platform-apple', 'img/platforms/apple_music.png'),
        ('amazon_music', 'Amazon Music', 'fa-brands fa-amazon', 'amazon_music_url', 'platform-amazon', 'img/platforms/amazon_music.png'),
        ('tiktok', 'TikTok', 'fa-brands fa-tiktok', 'tiktok_url', 'platform-tiktok', 'img/platforms/tiktok.png'),
        ('youtube', 'YouTube', 'fa-brands fa-youtube', 'youtube_url', 'platform-youtube', 'img/platforms/youtube.png'),
    ]
    out = []
    for key, label, icon, field, css_class, asset in specs:
        url = (getattr(item, field, None) or '').strip() if item is not None else ''
        if not url:
            continue
        if not url.startswith(('http://', 'https://')):
            url = 'https://' + url
        try:
            asset_url = _external_url_for('static', filename=asset)
            asset_path = str(Path(app.root_path) / 'static' / asset.replace('img/', 'img/'))
        except Exception:
            asset_url = ''
            asset_path = str(Path('static') / asset)
        out.append({
            'key': key,
            'label': label,
            'icon': icon,
            'class': css_class,
            'css_class': css_class,
            'asset': asset,
            'asset_url': asset_url,
            'asset_path': asset_path,
            'url': url,
        })
    return out


def _song_platform_links(song: Song | None) -> list[dict]:
    return _platform_links_for_item(song)


def _album_platform_links(album: Album | None) -> list[dict]:
    return _platform_links_for_item(album)


class _LinkedRLImage(RLImage if REPORTLAB_AVAILABLE else object):
    """Imagen clicable para PDFs ReportLab."""
    def __init__(self, filename, width=None, height=None, link_url=None, **kwargs):
        if not REPORTLAB_AVAILABLE:
            return
        super().__init__(filename, width=width, height=height, **kwargs)
        self.link_url = link_url

    def drawOn(self, canv, x, y, _sW=0):
        super().drawOn(canv, x, y, _sW)
        if getattr(self, 'link_url', None):
            try:
                canv.linkURL(self.link_url, (x, y, x + self.drawWidth, y + self.drawHeight), relative=0, thickness=0)
            except Exception:
                pass


def _platform_link_icon_flowable(link: dict, size_cm: float = 0.58):
    if not REPORTLAB_AVAILABLE:
        return None
    try:
        from reportlab.lib.units import cm
        asset_path = Path(link.get('asset_path') or '')
        if not asset_path.exists():
            asset = (link.get('asset') or '').lstrip('/')
            asset_path = Path(app.root_path) / 'static' / asset
        if not asset_path.exists():
            return None
        img = _LinkedRLImage(str(asset_path), width=size_cm * cm, height=size_cm * cm, link_url=link.get('url'))
        img.hAlign = 'LEFT'
        return img
    except Exception:
        return None


def _platform_links_pdf_table(item):
    if not REPORTLAB_AVAILABLE:
        return None
    try:
        from reportlab.lib.units import cm
        cells = []
        widths = []
        for link in _platform_links_for_item(item):
            icon = _platform_link_icon_flowable(link)
            if not icon:
                continue
            cells.append(icon)
            widths.append(0.74 * cm)
        if not cells:
            return None
        table = Table([cells], colWidths=widths, hAlign='LEFT')
        table.setStyle(TableStyle([
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('LEFTPADDING', (0,0), (-1,-1), 0),
            ('RIGHTPADDING', (0,0), (-1,-1), 4),
            ('TOPPADDING', (0,0), (-1,-1), 2),
            ('BOTTOMPADDING', (0,0), (-1,-1), 2),
        ]))
        return table
    except Exception:
        return None


def _platform_links_pdf_html(item) -> str:
    """Compatibilidad para plantillas antiguas: HTML con iconos imagen clicables."""
    links = []
    for link in _platform_links_for_item(item):
        url = html.escape(link.get('url') or '', quote=True)
        src = html.escape(link.get('asset_url') or '', quote=True)
        label = html.escape(link.get('label') or 'Enlace')
        if src:
            links.append(f'<a href="{url}"><img src="{src}" alt="{label}" style="width:22px;height:22px;object-fit:contain;display:inline-block;margin-right:8px;"></a>')
    return ''.join(links)


def _song_platform_links_pdf_html(song: Song | None) -> str:
    return _platform_links_pdf_html(song)


def _album_platform_links_pdf_html(album: Album | None) -> str:
    return _platform_links_pdf_html(album)


def _song_label_copy_public_context(session_db, song: Song) -> dict:
    artist = _song_primary_artist(session_db, song)
    artist_name = (getattr(artist, 'name', None) or '').strip() or 'Artista'
    interpreters_label = _song_interpreters_label(session_db, song)
    isrc_lines = _song_label_copy_isrc_lines(session_db, song)
    author_rows, author_total = _song_label_copy_author_rows(session_db, song)
    musicians = []
    for row in (getattr(song, 'musicians', None) or []):
        instrument = (row.get('instrument') or '').strip() if isinstance(row, dict) else ''
        name = (row.get('name') or '').strip() if isinstance(row, dict) else ''
        if instrument or name:
            musicians.append((f"{instrument}: " if instrument else '') + name)

    info_rows = []
    def add_row(label, value):
        value = value if isinstance(value, str) else ('' if value is None else str(value))
        value = value.strip()
        if value:
            info_rows.append({'label': label, 'value': value})

    add_row('Título', song.title)
    add_row('Intérpretes', interpreters_label)
    add_row('Versión', song.version)
    add_row('Fecha de publicación', song.release_date.strftime('%d/%m/%Y') if song.release_date else '')
    add_row('Códigos ISRC', '\n'.join(isrc_lines))
    add_row('Duración (Timing)', _seconds_to_timecode(getattr(song, 'duration_seconds', None)))
    add_row('Inicio en Tik Tok', _seconds_to_timecode(getattr(song, 'tiktok_start_seconds', None)))
    add_row('BPM', str(song.bpm or ''))
    add_row('Género', song.genre)
    # CONTENIDO EXPLÍCITO: se dice justo detrás del género, y SOLO si lo es (si no, no se pinta la
    # fila: `add_row` se salta lo vacío).
    add_row('Contenido', EXPLICIT_LABEL if _song_is_explicit(song) else '')
    add_row('Copyright', song.copyright_text)
    add_row('Productor', ', '.join([x for x in (song.producers or []) if (x or '').strip()]))
    add_row('Ingeniero de grabación', song.recording_engineer)
    add_row('Estudio de grabación', song.studio)
    add_row('Fecha de grabación', song.recording_date.strftime('%d/%m/%Y') if song.recording_date else '')
    add_row('Ingeniero de mezcla', song.mixing_engineer)
    add_row('Ingeniero de mastering', song.mastering_engineer)
    add_row('Arreglista', ', '.join([x for x in (song.arrangers or []) if (x or '').strip()]))
    add_row('Músicos', '\n'.join(musicians))
    return {
        'song': song,
        'artist': artist,
        'artist_name': artist_name,
        'interpreters_label': interpreters_label,
        'brand': _pies_brand_assets(session_db),
        'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
        'platform_links': _song_platform_links(song),
        'info_rows': info_rows,
        'author_rows': author_rows,
        'author_total': author_total,
    }


