# ---------------------------------------------------------------------------
# ISRC · el repertorio de códigos y su configurador
# ---------------------------------------------------------------------------
# ⚠️ Esta pantalla VIVE EN REGISTROS (`/registros?tab=isrc`), que es donde se trabaja con AGEDI y
# SGAE; antes era una pestaña de Discográfica y se movió en ago 2026 (el enlace antiguo
# `/discografica?section=isrc` redirige aquí). El PERMISO sigue siendo `discografica.isrc`: no se
# renombra a propósito, porque `_sync_access_resources` poda los huérfanos en cascada y se llevaría
# por delante los permisos ya concedidos.
def _isrc_panel_context(session_db, *, isrc_tab: str = "repertorio", artist_id=None, year=None,
                        config_subtab: str = "isrc") -> dict:
    """Todo lo que necesita la pantalla de ISRC (repertorio, pendientes de AGEDI y configurador)."""
    # ⚠️ Solo estas dos, como antes: la rama «pendientes» del cuerpo es código muerto que ya lo era
    # en Discográfica (el `isrc_tab` se normalizaba igual), y se conserva tal cual para no cambiar
    # nada al mover la pantalla.
    if isrc_tab not in ("repertorio", "configurador"):
        isrc_tab = "repertorio"
    artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
    contract_artist_ids = _artist_ids_with_discography_contracts(session_db)
    contract_artists = [a for a in artists if a.id in contract_artist_ids]

    isrc_artist_blocks: list = []
    isrc_years: list = []
    isrc_config = None
    isrc_artist_settings: dict = {}
    isrc_contract_artists: list = []
    isrc_filter_artists: list = []
    isrc_current_filter_artists: list = []
    isrc_pending_songs: list = []
    isrc_pending_filter_artists: list = []
    product_code_config = None
    current_product_code_series = None
    product_code_series_rows: list = []
    f_artist_id = _safe_uuid(artist_id) if artist_id else None
    try:
        f_year = int(year) if year else None
    except Exception:
        f_year = None

    # filtros
    f_artist_id = to_uuid((request.args.get("artist_id") or "").strip())
    f_year = None
    try:
        f_year = int((request.args.get("year") or "").strip())
    except Exception:
        f_year = None

    # Solo mostramos repertorio ISRC de canciones que tengan ISRC
    # y cumplan: master_ownership_pct > 1% o es distribución.
    ownership_cond = (
        (func.coalesce(Song.master_ownership_pct, 0) > 1)
        | (func.coalesce(Song.is_distribution, False) == True)  # noqa: E712
    )

    # años disponibles (release_date) SOLO de canciones con ISRC y filtro de propiedad
    years_rows = (
        session_db.query(func.extract("year", Song.release_date).label("y"))
        .join(SongISRCCode, SongISRCCode.song_id == Song.id)
        .filter(ownership_cond)
        .distinct()
        .order_by(func.extract("year", Song.release_date).desc())
        .all()
    )
    isrc_years = [int(r.y) for r in years_rows if r and r.y]

    # Artistas con canciones con ISRC (y filtro de propiedad)
    arows = (
        session_db.query(SongArtist.artist_id)
        .join(Song, Song.id == SongArtist.song_id)
        .join(SongISRCCode, SongISRCCode.song_id == Song.id)
        .filter(ownership_cond)
        .distinct()
        .all()
    )
    a_set = {r.artist_id for r in arows if r and r.artist_id}
    isrc_filter_artists = [a for a in artists if a.id in a_set]
    isrc_current_filter_artists = list(isrc_filter_artists)

    if isrc_tab == "repertorio":
        # Repertorio ISRC agrupado por artista.
        # - Solo canciones con ISRC
        # - Solo si master_ownership_pct > 1% o es distribución
        # - ⚠️ Ordenado por FECHA DE PUBLICACIÓN: la más próxima arriba y de ahí hacia abajo (antes se
        #   ordenaba por el código ISRC, que no es lo que se busca al mirar el repertorio).

        artists_iter = [a for a in isrc_filter_artists if (not f_artist_id) or a.id == f_artist_id]

        # subquery: máximo código por canción (se enseña y sirve para buscar)
        max_code_sq = (
            session_db.query(
                SongISRCCode.song_id.label("song_id"),
                func.max(SongISRCCode.code).label("max_code"),
            )
            .group_by(SongISRCCode.song_id)
            .subquery()
        )

        songs_by_artist: dict = {}
        all_song_ids: list = []
        for a in artists_iter:
            q = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .join(max_code_sq, max_code_sq.c.song_id == Song.id)
                .filter(SongArtist.artist_id == a.id)
                .filter(ownership_cond)
            )
            if f_year:
                q = q.filter(func.extract("year", Song.release_date) == f_year)

            songs = q.order_by(Song.release_date.desc().nullslast(),
                               max_code_sq.c.max_code.desc()).all()
            songs_by_artist[a.id] = songs
            all_song_ids.extend([s.id for s in songs])

        # QUÉ CÓDIGOS ESTÁN YA REGISTRADOS en AGEDI (verde) y cuáles siguen pendientes (amarillo).
        registrados_por_song: dict = {}
        if all_song_ids:
            try:
                for st in (session_db.query(SongStatus)
                           .filter(SongStatus.song_id.in_(all_song_ids)).all()):
                    registrados_por_song[st.song_id] = set(
                        _norm_isrc_list(getattr(st, "agedi_registered_isrcs", []) or []))
            except Exception:
                app.logger.exception("[isrc] no se pudo leer el estado de registro en AGEDI")

        # Prefetch TODOS los ISRCs (incl. subproductos), ordenados por código desc
        codes_by_song = {}
        if all_song_ids:
            rows = (
                session_db.query(SongISRCCode)
                .filter(SongISRCCode.song_id.in_(all_song_ids))
                .order_by(SongISRCCode.code.desc())
                .all()
            )
            for r in rows:
                codes_by_song.setdefault(r.song_id, []).append(r)

        for a in artists_iter:
            songs = songs_by_artist.get(a.id) or []
            enriched = []
            for s in songs:
                codes = codes_by_song.get(s.id) or []

                def _split(kind: str):
                    kind = (kind or "").upper()
                    prim = None
                    subs = []
                    for c in codes:
                        if (c.kind or "").upper() != kind:
                            continue
                        if c.is_primary and prim is None:
                            prim = c
                        elif not c.is_primary:
                            subs.append(c)
                    return prim, subs

                audio_p, audio_subs = _split("AUDIO")
                video_p, video_subs = _split("VIDEO")

                # key de orden (max code ya viene por query, pero lo guardamos)
                max_code = codes[0].code if codes else None
                _reg = registrados_por_song.get(s.id) or set()

                def _pinta(code, nombre=None):
                    """Cada código con su estado: registrado en AGEDI (verde) o pendiente (amarillo)."""
                    codigo = _norm_isrc(code)
                    return {"code": codigo, "name": (nombre or ""), "registered": codigo in _reg}

                enriched.append(
                    {
                        "song": s,
                        # La PORTADA de cada tema (la que resuelve `Song.cover_url`).
                        "cover_url": (getattr(s, "cover_url", None) or ""),
                        "audio_primary": _norm_isrc(audio_p.code) if audio_p else None,
                        "video_primary": _norm_isrc(video_p.code) if video_p else None,
                        "audio_primary_registered": bool(audio_p and _norm_isrc(audio_p.code) in _reg),
                        "video_primary_registered": bool(video_p and _norm_isrc(video_p.code) in _reg),
                        "audio_subs": [(_norm_isrc(c.code), c.subproduct_name) for c in audio_subs],
                        "video_subs": [(_norm_isrc(c.code), c.subproduct_name) for c in video_subs],
                        # Los subproductos, con su estado (mismo criterio que los principales).
                        "audio_sub_rows": [_pinta(c.code, c.subproduct_name) for c in audio_subs],
                        "video_sub_rows": [_pinta(c.code, c.subproduct_name) for c in video_subs],
                        "max_code": _norm_isrc(max_code),
                    }
                )

            isrc_artist_blocks.append((a, enriched))

        # Los BLOQUES también van de la publicación más próxima hacia abajo: así lo primero que se ve
        # en la pantalla es el lanzamiento más cercano, sea de quien sea.
        def _mas_proxima(par):
            fechas = [getattr(it["song"], "release_date", None) for it in (par[1] or [])]
            fechas = [f for f in fechas if f]
            return (0 if fechas else 1, -(max(fechas).toordinal() if fechas else 0),
                    (par[0].name or "").lower())
        isrc_artist_blocks.sort(key=_mas_proxima)

        isrc_current_filter_artists = [artist for artist, rows in isrc_artist_blocks if rows]

    elif isrc_tab == "pendientes":
        song_rows = (
            session_db.query(Song)
            .join(SongArtist, Song.id == SongArtist.song_id)
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .options(selectinload(Song.artists))
            .order_by(Song.release_date.desc(), Song.title.asc())
            .all()
        )
        if f_artist_id:
            song_rows = [s for s in song_rows if any(getattr(a, 'id', None) == f_artist_id for a in (s.artists or []))]
        if f_year:
            song_rows = [s for s in song_rows if getattr(s, 'release_date', None) and s.release_date.year == f_year]

        song_ids = [s.id for s in song_rows]
        status_map = {}
        if song_ids:
            status_map = {
                row.song_id: row
                for row in session_db.query(SongStatus).filter(SongStatus.song_id.in_(song_ids)).all()
                if row and row.song_id
            }

        codes_by_song = defaultdict(list)
        if song_ids:
            rows = (
                session_db.query(SongISRCCode)
                .filter(SongISRCCode.song_id.in_(song_ids))
                .order_by(SongISRCCode.is_primary.desc(), SongISRCCode.code.asc())
                .all()
            )
            for row in rows:
                codes_by_song[row.song_id].append(row)

        pending_artist_ids = set()
        for song in song_rows:
            st = status_map.get(song.id) or _ensure_song_status_row(session_db, song)
            _sync_song_agedi_state(session_db, song.id, st)
            current_codes = _current_song_isrcs(session_db, song.id, include_song_field=True)
            if not current_codes:
                continue
            registered_codes = set(_norm_isrc_list(getattr(st, 'agedi_registered_isrcs', []) or []))
            pending_codes = [code for code in current_codes if code not in registered_codes]
            if not pending_codes and bool(getattr(st, 'agedi_done', False)):
                continue
            for art in (song.artists or []):
                if art and getattr(art, 'id', None):
                    pending_artist_ids.add(art.id)
            isrc_pending_songs.append({
                'song': song,
                'artists_label': ", ".join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or '—',
                'registered_codes': [code for code in current_codes if code in registered_codes],
                'pending_codes': pending_codes if pending_codes else current_codes,
                'all_codes': [
                    {
                        'code': code,
                        'registered': code in registered_codes,
                        'pending': code not in registered_codes,
                    }
                    for code in current_codes
                ],
                'status': st,
            })
        isrc_pending_filter_artists = [a for a in artists if a.id in pending_artist_ids]
        isrc_current_filter_artists = list(isrc_pending_filter_artists)
        session_db.commit()

    else:
        # Configurador
        isrc_config = session_db.get(ISRCConfig, 1)
        if not isrc_config:
            isrc_config = ISRCConfig(id=1)
            session_db.add(isrc_config)
            session_db.commit()

        # Ajustes por artista
        settings_rows = session_db.query(ArtistISRCSetting).all()
        isrc_artist_settings = {r.artist_id: r for r in settings_rows}
        product_code_config = session_db.get(ProductCodeConfig, 1)
        if not product_code_config:
            product_code_config = ProductCodeConfig(id=1)
            session_db.add(product_code_config)
            session_db.commit()
        current_product_code_series = _active_product_code_series(session_db, create_if_missing=True)
        product_code_series_rows = _product_code_series_rows(session_db)
        # Artistas con contrato discográfico / catálogo / distribución.
        # Reutilizamos el cálculo robusto (sin acentos) para evitar listas vacías por variantes.
        isrc_contract_artists = contract_artists

    return {
        "isrc_tab": isrc_tab,
        "isrc_config_subtab": config_subtab,
        "isrc_years": isrc_years,
        "isrc_artist_blocks": isrc_artist_blocks,
        "isrc_filter_artists": isrc_filter_artists,
        "isrc_current_filter_artists": isrc_current_filter_artists,
        "isrc_pending_songs": isrc_pending_songs,
        "isrc_pending_filter_artists": isrc_pending_filter_artists,
        "isrc_config": isrc_config,
        "isrc_artist_settings": isrc_artist_settings,
        "isrc_contract_artists": isrc_contract_artists,
        "product_code_config": product_code_config,
        "current_product_code_series": current_product_code_series,
        "product_code_series_rows": product_code_series_rows,
        "artists": artists,
        "selected_artist_id": (str(f_artist_id) if f_artist_id else ""),
        "selected_year": (str(f_year) if f_year else ""),
    }


# ═══════════════════════════════════════════════════════════════════════════════════════════════
# FLECHAS de ANTERIOR / SIGUIENTE en las fichas de CANCIÓN y de ÁLBUM
# -----------------------------------------------------------------------------------------------
# Se abre una ficha desde un listado y se quiere ir a la siguiente sin volver atrás. La flecha
# depende de DE DÓNDE SE VIENE (el repertorio discográfico, los lanzamientos o el repertorio de
# Syncros), así que el listado viaja en la URL (`?nav=…`) y sus filtros con él (`nav_*`).
# ⚠️ Se conserva la PESTAÑA en la que se está: si estás viendo «Editorial», la siguiente ficha se
#    abre también en «Editorial» (y si esa pestaña no existe en el destino —de una canción a un
#    álbum— se cae a «Información»).
# ⚠️ En el primero solo sale la flecha de siguiente y en el último solo la de anterior.
# ═══════════════════════════════════════════════════════════════════════════════════════════════
SONG_DETAIL_TABS = {
    "informacion", "editorial", "materiales", "royalties", "ingresos",
    "gastos", "promocion", "marketing", "radio", "playlisting",
}
ALBUM_DETAIL_TABS = {"informacion", "canciones", "materiales", "beneficiarios", "promocion", "marketing"}

# Lo que define el listado de origen. `nav` dice cuál es y el resto son SUS filtros.
FICHA_NAV_PARAMS = ("nav", "nav_artista", "nav_q", "nav_onestop")
FICHA_NAV_KINDS = {"repertorio", "repertorio_albumes", "lanzamientos", "syncros"}


def _ficha_nav_args(args=None) -> dict:
    """Los parámetros de navegación que hay que ARRASTRAR (a las pestañas y a la ficha siguiente)."""
    src = args if args is not None else request.args
    fuera = {}
    for k in FICHA_NAV_PARAMS:
        v = (src.get(k) or "").strip()
        if v:
            fuera[k] = v
    if fuera.get("nav") not in FICHA_NAV_KINDS:
        return {}
    return fuera


def _ficha_nav_back_url(args: dict) -> str:
    """A dónde vuelve la flecha de «Volver»: el listado del que se venía."""
    nav = args.get("nav")
    try:
        if nav == "lanzamientos":
            return url_for("discografica_view", section="lanzamientos")
        if nav == "repertorio_albumes":
            return url_for("discografica_view", section="canciones", rep_tab="albumes")
        if nav == "syncros":
            return url_for("syncros_view", section="repertorio",
                           artista=(args.get("nav_artista") or None),
                           q=(args.get("nav_q") or None),
                           onestop=(1 if _truthy(args.get("nav_onestop")) else None))
        if nav == "repertorio":
            return url_for("discografica_view", section="canciones", rep_tab="canciones")
    except Exception:
        app.logger.exception("[ficha-nav] no se pudo construir el enlace de volver")
    return ""


def _ficha_nav_items(session_db, args: dict) -> list[dict]:
    """La lista ORDENADA del listado de origen: [{kind, id, title}] (kind = SONG | ALBUM).

    ⚠️ Tiene que salir en el MISMO orden en el que se ve la pantalla: si no, «el siguiente» no es
    el que está debajo."""
    nav = args.get("nav")
    aid = _safe_uuid((args.get("nav_artista") or "").strip())

    if nav == "repertorio":
        q = (session_db.query(Song.id, Song.title, Artist.name)
             .join(SongArtist, Song.id == SongArtist.song_id)
             .join(Artist, Artist.id == SongArtist.artist_id))
        if aid:
            q = q.filter(SongArtist.artist_id == aid)
        filas = q.order_by(Artist.name.asc(), Song.release_date.desc(), Song.title.asc()).all()
        return [{"kind": "SONG", "id": str(sid), "title": (title or "").strip()}
                for sid, title, _an in filas]

    if nav == "repertorio_albumes":
        q = (session_db.query(Album.id, Album.title, Artist.name)
             .join(Artist, Artist.id == Album.artist_id))
        if aid:
            q = q.filter(Album.artist_id == aid)
        filas = q.order_by(Artist.name.asc(), Album.release_date.desc(), Album.title.asc()).all()
        return [{"kind": "ALBUM", "id": str(alid), "title": (title or "").strip()}
                for alid, title, _an in filas]

    if nav == "lanzamientos":
        return [{"kind": it.get("kind") or "SONG", "id": str(it.get("item_id") or ""),
                 "title": (it.get("title") or "").strip()}
                for it in _disco_launch_items(session_db)]

    if nav == "syncros":
        filas = _sync_repertoire_filtered(
            session_db,
            artista_id=aid,
            q=(args.get("nav_q") or "").strip(),
            solo_os=_truthy(args.get("nav_onestop")),
        )[0]
        return [{"kind": "SONG", "id": f["id"], "title": f["title"]} for f in filas]

    return []


def _ficha_nav_url(item: dict, tab: str, args: dict) -> str:
    """El enlace a una ficha del listado, CONSERVANDO la pestaña (si el destino la tiene)."""
    extra = {k: v for k, v in (args or {}).items()}
    if (item.get("kind") or "").upper() == "ALBUM":
        return url_for("discografica_album_detail", album_id=item["id"],
                       tab=(tab if tab in ALBUM_DETAIL_TABS else "informacion"), **extra)
    return url_for("discografica_song_detail", song_id=item["id"],
                   tab=(tab if tab in SONG_DETAIL_TABS else "informacion"), **extra)


def _ficha_nav(session_db, *, kind: str, item_id, tab: str) -> dict | None:
    """Las flechas de la ficha: a dónde va la anterior y la siguiente (o None si no hay listado).

    Devuelve además `args` (lo que hay que arrastrar en los enlaces de las PESTAÑAS: sin eso, al
    cambiar de pestaña se perdería el listado y las flechas desaparecerían)."""
    args = _ficha_nav_args()
    if not args:
        return None
    try:
        items = _ficha_nav_items(session_db, args)
    except Exception:
        app.logger.exception("[ficha-nav] no se pudo reconstruir el listado de origen")
        return None
    kind = (kind or "SONG").upper()
    sid = str(item_id)
    idx = next((n for n, it in enumerate(items)
                if it["id"] == sid and (it["kind"] or "SONG").upper() == kind), None)
    if idx is None:
        # La ficha ya no está en ese listado (le han cambiado la fecha, ha salido del filtro…):
        # mejor no enseñar flechas que llevar a cualquier sitio.
        return {"args": args, "prev_url": "", "next_url": "", "prev_title": "", "next_title": "",
                "index": 0, "total": len(items), "back_url": _ficha_nav_back_url(args)}
    prev_it = items[idx - 1] if idx > 0 else None
    next_it = items[idx + 1] if (idx + 1) < len(items) else None
    return {
        "args": args,
        "prev_url": (_ficha_nav_url(prev_it, tab, args) if prev_it else ""),
        "prev_title": (prev_it or {}).get("title") or "",
        "next_url": (_ficha_nav_url(next_it, tab, args) if next_it else ""),
        "next_title": (next_it or {}).get("title") or "",
        "index": idx + 1,
        "total": len(items),
        "back_url": _ficha_nav_back_url(args),
    }


def _disco_launch_items(session_db, contract_artist_ids=None) -> list[dict]:
    """Los LANZAMIENTOS de la pestaña de Discográfica, ya ordenados.

    ⚠️ Punto único: lo usan la pantalla y las FLECHAS de anterior/siguiente de las fichas de
    canción y de álbum, así que «el siguiente lanzamiento» es exactamente el que se ve debajo
    en el listado (canciones y álbumes mezclados, en el mismo orden)."""
    launches_items: list[dict] = []
    if contract_artist_ids is None:
        contract_artist_ids = _artist_ids_with_discography_contracts(session_db)
    today = today_local()
    launch_window_start = today - timedelta(days=7)
    launch_window_end = today + timedelta(days=180)

    launch_song_rows = []
    if contract_artist_ids:
        launch_song_rows = (
            session_db.query(Song)
            .join(SongArtist, Song.id == SongArtist.song_id)
            .filter(SongArtist.artist_id.in_(list(contract_artist_ids)))
            .filter(Song.release_date >= launch_window_start)
            .filter(Song.release_date <= launch_window_end)
            .distinct()
            .options(selectinload(Song.artists))
            .order_by(Song.release_date.asc(), Song.title.asc())
            .all()
        )
    _annotate_song_display_fields(session_db, launch_song_rows, persist=True)
    seen_launch_song_ids = set()
    for song in launch_song_rows:
        if not song or song.id in seen_launch_song_ids:
            continue
        seen_launch_song_ids.add(song.id)
        release_date = getattr(song, 'release_date', None)
        if not release_date:
            continue
        days_remaining = (release_date - today).days
        is_new = release_date <= today and release_date >= (today - timedelta(days=7))
        if days_remaining < 0 and not is_new:
            continue
        artist_label = ", ".join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or "—"
        launches_items.append({
            'item_id': str(song.id),
            'kind': 'SONG',
            'kind_label': 'Canción',
            'title': getattr(song, 'title', None) or '—',
            'artist_label': artist_label,
            'collaborator': (getattr(song, 'display_collaborator', None) or getattr(song, 'collaborator', None) or '').strip(),
            'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
            'release_date': release_date,
            'days_remaining': days_remaining,
            'is_new': is_new,
            # PROVISIONAL: lo está preparando un proyecto discográfico (se ve igual que en su
            # ficha: el fondo rayado y su etiqueta).
            'is_provisional': bool(getattr(song, 'is_provisional', False)),
            # `nav`: las FLECHAS de la ficha recorren el listado de LANZAMIENTOS (canciones y
            # álbumes mezclados, en este mismo orden).
            'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion',
                                  nav='lanzamientos'),
        })

    launch_album_rows = []
    if contract_artist_ids:
        launch_album_rows = (
            session_db.query(Album)
            .options(joinedload(Album.artist))
            .filter(Album.artist_id.in_(list(contract_artist_ids)))
            .filter(Album.release_date >= launch_window_start)
            .filter(Album.release_date <= launch_window_end)
            .order_by(Album.release_date.asc(), Album.title.asc())
            .all()
        )
    for album in launch_album_rows:
        release_date = getattr(album, 'release_date', None)
        if not release_date:
            continue
        days_remaining = (release_date - today).days
        is_new = release_date <= today and release_date >= (today - timedelta(days=7))
        if days_remaining < 0 and not is_new:
            continue
        launches_items.append({
            'item_id': str(album.id),
            'kind': 'ALBUM',
            'kind_label': 'EP' if (getattr(album, 'album_type', None) or '').strip().upper() == 'EP' else 'Disco',
            'title': getattr(album, 'title', None) or '—',
            'artist_label': (getattr(getattr(album, 'artist', None), 'name', None) or '').strip() or '—',
            'collaborator': '',
            'cover_url': (getattr(album, 'cover_url', None) or '').strip(),
            'release_date': release_date,
            'days_remaining': days_remaining,
            'is_new': is_new,
            'is_provisional': bool(getattr(album, 'is_provisional', False)),
            'detail_url': url_for('discografica_album_detail', album_id=album.id, tab='informacion',
                                  nav='lanzamientos'),
        })

    def _launch_sort_key(item: dict):
        release_date = item.get('release_date') or date.max
        ordinal = release_date.toordinal() if hasattr(release_date, 'toordinal') else 0
        days_remaining = item.get('days_remaining')
        is_future = days_remaining is not None and days_remaining >= 0
        return (
            0 if is_future else 1,
            ordinal if is_future else -ordinal,
            0 if item.get('kind') == 'SONG' else 1,
            (item.get('title') or '').casefold(),
        )

    launches_items.sort(key=_launch_sort_key)
    return launches_items



@app.get("/discografica")
@admin_required
def discografica_view():
    """Pestaña principal Discográfica.

    Agrupa (por ahora):
    - Canciones (Repertorio)
    - Royalties (próximamente)
    - Editorial (próximamente)
    - Ingresos
    """

    section = (request.args.get("section") or "lanzamientos").lower().strip()
    if section == "repertorio":
        section = "canciones"
    # La pantalla de ISRC se MOVIÓ a Registros (ago 2026): los enlaces antiguos siguen valiendo.
    if section == "isrc":
        return redirect(url_for("registros_view", tab="isrc",
                                isrc_tab=(request.args.get("isrc_tab") or "repertorio"),
                                config_tab=(request.args.get("config_tab") or None),
                                artist_id=(request.args.get("artist_id") or None),
                                year=(request.args.get("year") or None)))

    # Context (solo se usa cuando section == 'ingresos')
    income_view = request.args.get("view") or "month"  # 'month' | 'semester'
    if income_view not in ("month", "semester"):
        income_view = "month"

    income_period_label = ""
    income_period_type = "MONTH"
    income_period_key = ""
    income_period_start_iso = ""

    income_month_tabs: list[dict] = []
    income_month_prev_url: str | None = None
    income_month_next_url: str | None = None

    income_semester_tabs: list[dict] = []

    income_artist_blocks: list[tuple] = []
    repertorio_tab = (request.args.get("rep_tab") or "canciones").lower().strip()
    if repertorio_tab not in ("canciones", "albumes"):
        repertorio_tab = "canciones"
    editorial_pending_songs: list[Song] = []
    editorial_registered_songs: list[Song] = []
    editorial_filter_artists: list[Artist] = []
    isrc_config_subtab = (request.args.get("config_tab") or "isrc").lower().strip()
    if isrc_config_subtab not in ("isrc", "album_refs"):
        isrc_config_subtab = "isrc"

    registros_tab = (request.args.get("registros_tab") or "sgae").lower().strip()
    if registros_tab not in ("sgae", "agedi", "ritmonet"):
        registros_tab = "sgae"
    registros_upcoming_releases: list[dict] = []
    registros_sgae_pending_songs: list[Song] = []
    registros_agedi_items: list[dict] = []
    registros_ritmonet_songs: list[dict] = []
    registros_filter_artists: list[Artist] = []
    registros_filter_years: list[int] = []
    registros_selected_artist_id = ""
    registros_selected_year = ""

    launches_items: list[dict] = []
    launches_calendar_months: list[dict] = []

    # Context (solo se usa cuando section == 'royalties')
    royalty_period_label = ""
    royalty_semester_key = ""
    royalty_semester_tabs: list[dict] = []
    royalty_beneficiaries_artists: list[dict] = []
    royalty_beneficiaries_others: list[dict] = []
    royalty_filter_artists: list[Artist] = []
    royalty_selected_artist_id = ""
    royalty_selected_statuses: list[str] = []
    royalty_pending_generate = 0      # liquidaciones aún sin generar (botón «Generar todas»)
    royalty_pending_send = 0          # generadas/descargadas sin enviar («Descargar/Enviar todas»)
    royalty_tab = "liquidaciones"
    afavor_groups: list[dict] = []
    afavor_total = Decimal("0")
    royalty_semester_start_iso = ""

    # Para redirecciones tras POST
    income_next_url = _update_url_query(request.full_path.rstrip("?"), {"upload_report": None, "import_review": None})

    # Opciones para el modal del informe
    income_report_months: list[dict] = []
    income_report_semesters: list[dict] = []
    income_report_months_selected: list[str] = []
    income_report_semesters_selected: list[str] = []
    income_upload_report = None
    income_import_review = None

    # ⚠️ Una sección NUEVA hay que añadirla a esta lista blanca: si no, cae en «canciones» y la
    #    pestaña sale marcada pero se pinta otra cosa (bug real de la épica de demos).
    if section not in ("lanzamientos", "canciones", "royalties", "editorial", "registros", "ingresos",
                       "isrc", "adelantos", "demos", "playlists", "proyectos"):
        section = "canciones"
    if section == "registros":
        legacy_tab = (request.args.get("registros_tab") or request.args.get("tab") or "pendiente").strip().lower()
        tab = "sgae" if legacy_tab == "sgae" else "pendiente"
        return redirect(url_for("registros_view", tab=tab))

    editorial_tab = (request.args.get("editorial_tab") or "repertorio").lower().strip()
    if editorial_tab == "pendientes":
        return redirect(url_for("discografica_view", section="registros", registros_tab="sgae"))
    if editorial_tab != "repertorio":
        editorial_tab = "repertorio"

    # (Las subpestañas de ISRC viven en Registros desde ago 2026: ver `_isrc_panel_context`. El
    #  `?section=isrc` de arriba redirige allí, así que aquí ya no hay nada que normalizar.)

    if section == "ingresos":
        income_upload_report = _load_income_import_payload(request.args.get("upload_report"))
        income_import_review = _load_income_import_payload(request.args.get("import_review"))

    session_db = db()
    artists = session_db.query(Artist).order_by(Artist.name.asc()).all()

    # DEMOS: el listado solo se calcula cuando se está mirando esa sección.
    demos_ctx = _demos_context(session_db) if section == "demos" else None

    # PLAYLIST: igual, solo cuando se está mirando esa sección.
    playlist_rows = _playlist_rows(session_db) if section == "playlists" else None

    # PROYECTOS discográficos: los artistas con proyectos activos y, al entrar, los suyos. El
    # asistente necesita además el repertorio y los proyectos en marcha (para un videoclip).
    projects_ctx = _disco_projects_context(session_db) if section == "proyectos" else None
    project_wizard = _disco_project_wizard_context(session_db) if section == "proyectos" else None
    # El catálogo de GÉNEROS lo sugiere el paso obligatorio del asistente de proyectos y el editor
    # de la ficha de la canción (es una ayuda: el campo admite cualquiera y lo crea al vuelo).
    song_genre_catalog = _song_genre_catalog(session_db) if section in ("proyectos", "canciones") else []

    # Solo artistas con contrato Discográfico / Catálogo / Distribución (para alta de canciones)
    contract_artist_ids = _artist_ids_with_discography_contracts(session_db)
    contract_artists = [a for a in artists if a.id in contract_artist_ids]

    artist_blocks = []
    song_audio_isrc_map = {}
    album_blocks = []
    product_code_config = None
    current_product_code_series = None

    if section == "canciones":
        if repertorio_tab == "canciones":
            for a in artists:
                songs = (
                    session_db.query(Song)
                    .join(SongArtist, Song.id == SongArtist.song_id)
                    .filter(SongArtist.artist_id == a.id)
                    .order_by(Song.release_date.desc())
                    .all()
                )
                for s in songs:
                    _ = s.artists
                if songs:
                    artist_blocks.append((a, songs))

            # Prefetch ISRC AUDIO principal por canción (song_isrc_codes),
            # para mostrarlo en el repertorio.
            all_song_ids = [s.id for _, ss in artist_blocks for s in (ss or [])]
            if all_song_ids:
                rows = (
                    session_db.query(SongISRCCode.song_id, SongISRCCode.code)
                    .filter(SongISRCCode.song_id.in_(all_song_ids))
                    .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                    .filter(SongISRCCode.is_primary == True)  # noqa: E712
                    .all()
                )
                for sid, code in rows:
                    if sid and code:
                        song_audio_isrc_map[sid] = code
        else:
            for a in artists:
                albums = (
                    session_db.query(Album)
                    .filter(Album.artist_id == a.id)
                    .order_by(Album.release_date.desc(), Album.title.asc())
                    .all()
                )
                if albums:
                    album_blocks.append((a, albums))



    if section == "lanzamientos":
        today = today_local()
        launches_items = _disco_launch_items(session_db, contract_artist_ids)

        cal_items_by_date: dict[date, list[dict]] = defaultdict(list)
        months_with_launches: set[date] = set()
        for item in launches_items:
            rd = item.get('release_date')
            if not rd:
                continue
            first = date(rd.year, rd.month, 1)
            months_with_launches.add(first)
            cal_items_by_date.setdefault(rd, []).append(item)

        for first_day in sorted(months_with_launches):
            next_month = _add_months(first_day, 1)
            last_day = next_month - timedelta(days=1)
            if first_day.year == today.year and first_day.month == today.month:
                # En el mes en curso solo se pinta desde la semana actual para ahorrar espacio.
                week_start = today - timedelta(days=today.weekday())
                start_day = max(first_day - timedelta(days=first_day.weekday()), week_start)
            else:
                start_day = first_day - timedelta(days=first_day.weekday())
            end_day = last_day + timedelta(days=(6 - last_day.weekday()))
            weeks = []
            cursor = start_day
            while cursor <= end_day:
                week = []
                for _ in range(7):
                    day_items = list(cal_items_by_date.get(cursor, []))
                    week.append({
                        'date': cursor,
                        'in_month': cursor.month == first_day.month,
                        'items': day_items,
                    })
                    cursor += timedelta(days=1)
                weeks.append(week)
            launches_calendar_months.append({
                'key': first_day.strftime('%Y-%m'),
                'label': _month_label(first_day),
                'weeks': weeks,
            })



    if section in ("editorial", "registros"):
        plataforma = (
            session_db.query(PublishingCompany)
            .filter(func.lower(PublishingCompany.name) == "plataforma musical")
            .first()
        )
        plataforma_id = getattr(plataforma, "id", None)

        if plataforma_id:
            song_rows = (
                session_db.query(Song)
                .join(SongEditorialShare, SongEditorialShare.song_id == Song.id)
                .join(Promoter, Promoter.id == SongEditorialShare.promoter_id)
                .filter(Promoter.publishing_company_id == plataforma_id)
                .options(selectinload(Song.artists))
                .order_by(Song.release_date.desc(), Song.title.asc())
                .all()
            )

            dedup = []
            seen = set()
            for song in song_rows:
                if not song or song.id in seen:
                    continue
                seen.add(song.id)
                dedup.append(song)

            status_map = {}
            if dedup:
                status_map = {
                    row.song_id: row
                    for row in (
                        session_db.query(SongStatus)
                        .filter(SongStatus.song_id.in_([s.id for s in dedup]))
                        .all()
                    )
                    if row and row.song_id
                }

            editorial_artist_ids = set()
            for song in dedup:
                setattr(song, "editorial_artists_str", ", ".join([a.name for a in getattr(song, "artists", [])]) or "—")
                song_status = status_map.get(song.id)
                setattr(song, "editorial_registered", bool(getattr(song_status, "sgae_done", False)))
                setattr(song, "editorial_modification_pending", bool(getattr(song_status, "sgae_modification_pending", False)))
                for art in (getattr(song, "artists", []) or []):
                    if art and getattr(art, "id", None):
                        editorial_artist_ids.add(art.id)

            editorial_pending_songs = [
                s for s in dedup
                if (not getattr(s, "editorial_registered", False)) or bool(getattr(s, "editorial_modification_pending", False))
            ]
            editorial_registered_songs = [s for s in dedup if getattr(s, "editorial_registered", False)]
            editorial_filter_artists = [a for a in artists if a.id in editorial_artist_ids]


    if section == "royalties":
        today = today_local()
        parsed_sem = _parse_semester_key((request.args.get("s") or "").strip())
        if parsed_sem is None:
            if today.month <= 6:
                sem_year, sem_half = today.year - 1, 2
            else:
                sem_year, sem_half = today.year, 1
        else:
            sem_year, sem_half = parsed_sem

        royalty_tab = (request.args.get("roy_tab") or "liquidaciones").strip().lower()
        if royalty_tab not in ("liquidaciones", "resumen", "afavor"):
            royalty_tab = "liquidaciones"

        royalty_semester_key = _semester_key(sem_year, sem_half)
        sem_start, sem_end = _semester_range(sem_year, sem_half)
        royalty_period_label = _semester_label(sem_year, sem_half)
        royalty_selected_artist_id = (request.args.get("artist") or "").strip()
        selected_artist_uuid = to_uuid(royalty_selected_artist_id) if royalty_selected_artist_id else None
        if royalty_selected_artist_id and not selected_artist_uuid:
            royalty_selected_artist_id = ""

        allowed_royalty_statuses = list(ROYALTY_STATUS_FLOW)
        royalty_selected_statuses = [(value or "").strip().upper() for value in request.args.getlist("roy_status") if (value or "").strip()]
        royalty_selected_statuses = [value for value in royalty_selected_statuses if value in allowed_royalty_statuses]
        if not royalty_selected_statuses:
            royalty_selected_statuses = list(allowed_royalty_statuses)

        royalty_semester_tabs = []
        for y, h in _royalty_available_semesters(session_db, sem_start):
            k = _semester_key(y, h)
            royalty_semester_tabs.append(
                {
                    "key": k,
                    "label": _semester_label(y, h),
                    "is_active": k == royalty_semester_key,
                    "url": url_for(
                        "discografica_view",
                        section="royalties",
                        s=k,
                        roy_tab=royalty_tab,
                        artist=royalty_selected_artist_id or None,
                    ),
                }
            )

        royalty_payload = _build_royalty_beneficiaries(
            session_db,
            sem_start,
            sem_end,
            selected_artist_id=selected_artist_uuid,
        )
        royalty_beneficiaries_artists = royalty_payload.get("artists") or []
        royalty_beneficiaries_others = royalty_payload.get("others") or []
        royalty_filter_artists = royalty_payload.get("filter_artists") or []

        def _match_royalty_status(bucket: dict) -> bool:
            bucket_status = (bucket.get("liquidation_status") or "PENDING").upper()
            return bucket_status in set(royalty_selected_statuses or [])

        # Antes de filtrar: cuántas quedan por GENERAR y cuántas sin enviar (para los botones de
        # acción en bloque: primero «Generar todas» y, cuando ya están todas, «Descargar todas»).
        _all_buckets = list(royalty_beneficiaries_artists) + list(royalty_beneficiaries_others)
        royalty_pending_generate = sum(
            1 for b in _all_buckets if (b.get("liquidation_status") or "PENDING").upper() == "PENDING")
        royalty_pending_send = sum(
            1 for b in _all_buckets
            if (b.get("liquidation_status") or "PENDING").upper() in ROYALTY_NOT_SENT_STATUSES)

        royalty_beneficiaries_artists = [bucket for bucket in royalty_beneficiaries_artists if _match_royalty_status(bucket)]
        royalty_beneficiaries_others = [bucket for bucket in royalty_beneficiaries_others if _match_royalty_status(bucket)]

        # Pestaña «A favor»: lo que cobramos nosotros por colaboraciones externas.
        _afavor = _build_afavor_groups(session_db, sem_start, selected_artist_uuid) if royalty_tab == "afavor" else {"groups": [], "total": Decimal("0")}
        afavor_groups = _afavor["groups"]
        afavor_total = _afavor["total"]
        royalty_semester_start_iso = sem_start.isoformat()

    if section == "ingresos":

        # 1) Selección de periodos (meses / semestres)
        today = today_local()
        current_month_start = date(today.year, today.month, 1)
        prev_month_start = _add_months(current_month_start, -1)

        # Mes seleccionado (YYYY-MM)
        sel_month_start = _parse_month_key((request.args.get("m") or "").strip()) or prev_month_start
        if sel_month_start > prev_month_start:
            sel_month_start = prev_month_start
        sel_month_key = _month_key(sel_month_start)

        # Cursor para pestañas de meses (ventana de 12)
        cursor_start = _parse_month_key((request.args.get("mc") or "").strip()) or sel_month_start
        if cursor_start > prev_month_start:
            cursor_start = prev_month_start
        cursor_key = _month_key(cursor_start)

        # Semestre seleccionado (YYYY-S1 / YYYY-S2)
        parsed_sem = _parse_semester_key((request.args.get("s") or "").strip())
        if parsed_sem is None:
            # Semestre anterior "cerrado"
            if today.month <= 6:
                sem_year, sem_half = today.year - 1, 2
            else:
                sem_year, sem_half = today.year, 1
        else:
            sem_year, sem_half = parsed_sem
        sem_key = _semester_key(sem_year, sem_half)
        sem_start, sem_end = _semester_range(sem_year, sem_half)

        # 2) Construcción de pestañas
        # Meses (12 últimos meses, empezando desde el cursor)
        income_month_tabs = []
        for i in range(12):
            d = _add_months(cursor_start, -i)
            key = _month_key(d)
            income_month_tabs.append(
                {
                    "key": key,
                    "label": _month_label(d),
                    "is_active": key == sel_month_key,
                    "url": url_for(
                        "discografica_view",
                        section="ingresos",
                        view="month",
                        m=key,
                        mc=cursor_key,
                        s=sem_key,
                    ),
                }
            )

        # Flechas meses
        left_cursor = _add_months(cursor_start, -1)
        income_month_prev_url = url_for(
            "discografica_view",
            section="ingresos",
            view="month",
            m=_month_key(left_cursor),
            mc=_month_key(left_cursor),
            s=sem_key,
        )
        if cursor_start < prev_month_start:
            right_cursor = _add_months(cursor_start, 1)
            income_month_next_url = url_for(
                "discografica_view",
                section="ingresos",
                view="month",
                m=_month_key(right_cursor),
                mc=_month_key(right_cursor),
                s=sem_key,
            )
        else:
            income_month_next_url = None

        # Semestres (últimos 12 semestres desde el seleccionado)
        income_semester_tabs = []
        for i in range(12):
            y, h = _add_semesters(sem_year, sem_half, -i)
            k = _semester_key(y, h)
            income_semester_tabs.append(
                {
                    "key": k,
                    "label": _semester_label(y, h),
                    "is_active": k == sem_key,
                    "url": url_for(
                        "discografica_view",
                        section="ingresos",
                        view="semester",
                        s=k,
                        m=sel_month_key,
                        mc=cursor_key,
                    ),
                }
            )

        # 3) Periodo activo (el que se está mostrando en el listado)
        if income_view == "semester":
            income_period_type = "SEMESTER"
            income_period_key = sem_key
            period_start = sem_start
            period_end = sem_end
            income_period_label = _semester_label(sem_year, sem_half)
            income_period_start_iso = period_start.isoformat()
            income_report_semesters_selected = [sem_key]
        else:
            income_period_type = "MONTH"
            income_period_key = sel_month_key
            period_start = sel_month_start
            period_end = _month_end(sel_month_start)
            income_period_label = _month_label(sel_month_start)
            income_period_start_iso = period_start.isoformat()
            income_report_months_selected = [sel_month_key]

        # 4) Opciones para informe (últimos 24 meses / 12 semestres)
        income_report_months = [
            {"key": _month_key(_add_months(prev_month_start, -i)), "label": _month_label(_add_months(prev_month_start, -i))}
            for i in range(24)
        ]

        base_sem_year, base_sem_half = (today.year - 1, 2) if today.month <= 6 else (today.year, 1)
        income_report_semesters = [
            {
                "key": _semester_key(*_add_semesters(base_sem_year, base_sem_half, -i)),
                "label": _semester_label(*_add_semesters(base_sem_year, base_sem_half, -i)),
            }
            for i in range(12)
        ]

        # 5) Canciones publicadas hasta el fin del periodo (ordenadas por artista)
        tmp_blocks: list[tuple[Artist, list[Song]]] = []
        for a in artists:
            songs = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .filter(SongArtist.artist_id == a.id)
                .filter(Song.release_date <= period_end)
                .order_by(Song.release_date.desc())
                .all()
            )
            for s in songs:
                _ = s.artists
            if songs:
                tmp_blocks.append((a, songs))

        all_song_ids = [s.id for _, ss in tmp_blocks for s in (ss or [])]

        # Prefetch intérpretes (si no hay, usamos artistas del tema)
        interpreters_by_song: dict[str, list[str]] = {}
        if all_song_ids:
            irows = (
                session_db.query(SongInterpreter.song_id, SongInterpreter.name)
                .filter(SongInterpreter.song_id.in_(all_song_ids))
                .order_by(SongInterpreter.is_main.desc(), SongInterpreter.created_at.asc(), SongInterpreter.name.asc())
                .all()
            )
            for sid, name in irows:
                if sid and name:
                    interpreters_by_song.setdefault(str(sid), []).append(name)

        # Prefetch ISRC principal (AUDIO) o fallback a Song.isrc
        isrc_by_song: dict[str, str] = {}
        if all_song_ids:
            r_isrc = (
                session_db.query(SongISRCCode.song_id, SongISRCCode.code, SongISRCCode.is_primary)
                .filter(SongISRCCode.song_id.in_(all_song_ids))
                .filter(func.upper(SongISRCCode.kind) == "AUDIO")
                .order_by(SongISRCCode.is_primary.desc(), SongISRCCode.code.desc())
                .all()
            )
            for sid, code, _prim in r_isrc:
                sid_s = str(sid)
                if sid_s not in isrc_by_song and code:
                    isrc_by_song[sid_s] = code

        # Prefetch ingresos
        entries_by_song_period: dict[tuple[str, str, date], list[SongRevenueEntry]] = {}
        sem_month_starts: list[date] = []
        if income_view == "semester":
            sem_month_starts = [_add_months(date(sem_start.year, sem_start.month, 1), i) for i in range(6)]

        if all_song_ids:
            if income_view == "month":
                q = (
                    session_db.query(SongRevenueEntry)
                    .filter(SongRevenueEntry.song_id.in_(all_song_ids))
                    .filter(SongRevenueEntry.period_type == "MONTH")
                    .filter(SongRevenueEntry.period_start == period_start)
                )
            else:
                q = (
                    session_db.query(SongRevenueEntry)
                    .filter(SongRevenueEntry.song_id.in_(all_song_ids))
                    .filter(
                        or_(
                            and_(SongRevenueEntry.period_type == "SEMESTER", SongRevenueEntry.period_start == sem_start),
                            and_(SongRevenueEntry.period_type == "MONTH", SongRevenueEntry.period_start.in_(sem_month_starts)),
                        )
                    )
                )

            erows = q.order_by(SongRevenueEntry.is_base.desc(), SongRevenueEntry.created_at.asc()).all()
            for e in erows:
                entries_by_song_period.setdefault((str(e.song_id), e.period_type, e.period_start), []).append(e)

        def _money_input(v: Decimal | None) -> str:
            if v is None:
                return ""
            try:
                return str(Decimal(v).quantize(Decimal("0.01")))
            except Exception:
                return str(v)

        # 6) Construimos bloques enriquecidos para la plantilla
        income_artist_blocks = []
        for a, songs in tmp_blocks:
            rows = []
            for s in songs:
                sid = str(s.id)

                # intérpretes
                inames = interpreters_by_song.get(sid)
                if not inames:
                    inames = [ar.name for ar in (s.artists or []) if ar and ar.name]
                interpreters_str = ", ".join(inames) if inames else ""

                # isrc
                isrc = _norm_isrc(isrc_by_song.get(sid) or s.isrc)

                # entradas del periodo
                if income_view == "month":
                    entries = entries_by_song_period.get((sid, "MONTH", period_start), [])
                    base = next((x for x in entries if x.is_base), None)
                    extras = [x for x in entries if not x.is_base]

                    total_gross = sum((Decimal(x.gross or 0) for x in entries), Decimal("0"))
                    total_net = sum((Decimal(x.net or 0) for x in entries), Decimal("0"))

                    status = {"label": "Completo" if entries else "Sin datos", "class": "text-bg-success" if entries else "text-bg-danger"}

                    rows.append(
                        {
                            "song": s,
                            "cover_url": s.cover_url,
                            "interpreters": interpreters_str,
                            "isrc": isrc,
                            "status": status,
                            "base_entry_id": str(base.id) if base else "",
                            "base_gross": _money_input(base.gross) if base else "",
                            "base_net": _money_input(base.net) if base else "",
                            "extra_entries": [
                                {"id": str(x.id), "name": x.name, "gross": x.gross or 0, "net": x.net or 0}
                                for x in extras
                            ],
                            "show_total": len(extras) > 0,
                            "total_gross": total_gross,
                            "total_net": total_net,
                            "semester_sum_gross": Decimal("0"),
                            "semester_sum_net": Decimal("0"),
                            "semester_missing_months": None,
                            "semester_has_manual": False,
                        }
                    )

                else:
                    sem_entries = entries_by_song_period.get((sid, "SEMESTER", sem_start), [])
                    base = next((x for x in sem_entries if x.is_base), None)
                    extras = [x for x in sem_entries if not x.is_base]

                    # suma de meses
                    months_with_data = 0
                    sum_gross = Decimal("0")
                    sum_net = Decimal("0")
                    for ms in sem_month_starts:
                        mentries = entries_by_song_period.get((sid, "MONTH", ms), [])
                        if mentries:
                            months_with_data += 1
                        sum_gross += sum((Decimal(x.gross or 0) for x in mentries), Decimal("0"))
                        sum_net += sum((Decimal(x.net or 0) for x in mentries), Decimal("0"))

                    missing = 6 - months_with_data

                    # estado
                    if months_with_data == 0 and not sem_entries:
                        status = {"label": "Sin datos", "class": "text-bg-danger"}
                    elif missing == 0:
                        status = {"label": "Completo", "class": "text-bg-success"}
                    else:
                        status = {"label": "Incompleto", "class": "text-bg-warning"}

                    display_gross = base.gross if base else sum_gross
                    display_net = base.net if base else sum_net

                    extras_gross = sum((Decimal(x.gross or 0) for x in extras), Decimal("0"))
                    extras_net = sum((Decimal(x.net or 0) for x in extras), Decimal("0"))

                    # Total mostrado (base manual o auto + extras) solo cuando hay más de un ingreso (extras).
                    total_gross = Decimal(display_gross or 0) + extras_gross
                    total_net = Decimal(display_net or 0) + extras_net

                    rows.append(
                        {
                            "song": s,
                            "cover_url": s.cover_url,
                            "interpreters": interpreters_str,
                            "isrc": isrc,
                            "status": status,
                            "base_entry_id": str(base.id) if base else "",
                            "base_gross": _money_input(display_gross),
                            "base_net": _money_input(display_net),
                            "extra_entries": [
                                {"id": str(x.id), "name": x.name, "gross": x.gross or 0, "net": x.net or 0}
                                for x in extras
                            ],
                            "show_total": len(extras) > 0,
                            "total_gross": total_gross,
                            "total_net": total_net,
                            "semester_sum_gross": sum_gross,
                            "semester_sum_net": sum_net,
                            "semester_missing_months": missing,
                            "semester_has_manual": bool(base),
                        }
                    )

            income_artist_blocks.append((a, rows))

    if section == "registros":
        f_artist_id = to_uuid((request.args.get("artist_id") or "").strip())
        f_year = None
        try:
            f_year = int((request.args.get("year") or "").strip())
        except Exception:
            f_year = None

        registros_selected_artist_id = str(f_artist_id) if f_artist_id else ""
        registros_selected_year = str(f_year) if f_year else ""

        ownership_cond = (
            (func.coalesce(Song.master_ownership_pct, 0) > 1)
            | (func.coalesce(Song.is_distribution, False) == True)  # noqa: E712
        )
        today = today_local()

        upcoming_song_rows = []
        if contract_artist_ids:
            upcoming_song_rows = (
                session_db.query(Song)
                .join(SongArtist, Song.id == SongArtist.song_id)
                .filter(SongArtist.artist_id.in_(list(contract_artist_ids)))
                .filter(Song.release_date >= today)
                .distinct()
                .options(selectinload(Song.artists))
                .order_by(Song.release_date.asc(), Song.title.asc())
                .all()
            )
        seen_song_ids = set()
        for song in upcoming_song_rows:
            if not song or song.id in seen_song_ids:
                continue
            seen_song_ids.add(song.id)
            artist_names = [
                (getattr(artist, 'name', None) or '').strip()
                for artist in (song.artists or [])
                if (getattr(artist, 'name', None) or '').strip()
            ]
            days_remaining = None
            if getattr(song, 'release_date', None):
                try:
                    days_remaining = (song.release_date - today).days
                except Exception:
                    days_remaining = None
            registros_upcoming_releases.append(
                {
                    'item_id': str(song.id),
                    'kind': 'SONG',
                    'kind_label': 'Canción',
                    'title': getattr(song, 'title', None) or '—',
                    'artist_label': ', '.join(artist_names) or '—',
                    'collaborator': (getattr(song, 'collaborator', None) or '').strip(),
                    'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                    'release_date': getattr(song, 'release_date', None),
                    'days_remaining': days_remaining,
                    'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
                }
            )

        upcoming_album_rows = []
        if contract_artist_ids:
            upcoming_album_rows = (
                session_db.query(Album)
                .options(joinedload(Album.artist))
                .filter(Album.artist_id.in_(list(contract_artist_ids)))
                .filter(Album.release_date >= today)
                .order_by(Album.release_date.asc(), Album.title.asc())
                .all()
            )
        for album in upcoming_album_rows:
            days_remaining = None
            if getattr(album, 'release_date', None):
                try:
                    days_remaining = (album.release_date - today).days
                except Exception:
                    days_remaining = None
            registros_upcoming_releases.append(
                {
                    'kind': 'ALBUM',
                    'kind_label': 'EP' if (getattr(album, 'album_type', None) or '').upper() == 'EP' else 'Disco',
                    'title': getattr(album, 'title', None) or '—',
                    'artist_label': (getattr(getattr(album, 'artist', None), 'name', None) or '').strip() or '—',
                    'collaborator': '',
                    'cover_url': (getattr(album, 'cover_url', None) or '').strip(),
                    'release_date': getattr(album, 'release_date', None),
                    'days_remaining': days_remaining,
                    'detail_url': url_for('discografica_album_detail', album_id=album.id, tab='informacion'),
                }
            )
        registros_upcoming_releases.sort(
            key=lambda item: (
                item.get('release_date') or date.max,
                0 if item.get('kind') == 'SONG' else 1,
                (item.get('title') or '').casefold(),
            )
        )

        registros_sgae_pending_songs = list(editorial_pending_songs or [])

        agedi_song_rows = (
            session_db.query(Song)
            .join(SongArtist, Song.id == SongArtist.song_id)
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .options(selectinload(Song.artists))
            .order_by(Song.release_date.desc(), Song.title.asc())
            .all()
        )
        if f_artist_id:
            agedi_song_rows = [
                song
                for song in agedi_song_rows
                if any(getattr(artist, 'id', None) == f_artist_id for artist in (song.artists or []))
            ]
        if f_year:
            agedi_song_rows = [
                song
                for song in agedi_song_rows
                if getattr(song, 'release_date', None) and song.release_date.year == f_year
            ]

        agedi_song_ids = [song.id for song in agedi_song_rows]
        agedi_status_map = {}
        if agedi_song_ids:
            agedi_status_map = {
                row.song_id: row
                for row in session_db.query(SongStatus).filter(SongStatus.song_id.in_(agedi_song_ids)).all()
                if row and row.song_id
            }

        registros_artist_ids = set()
        registros_year_set = set()
        for song in agedi_song_rows:
            st = agedi_status_map.get(song.id) or _ensure_song_status_row(session_db, song)
            _sync_song_agedi_state(session_db, song.id, st)
            current_codes = _current_song_isrcs(session_db, song.id, include_song_field=True)
            if not current_codes:
                continue
            registered_codes = set(_norm_isrc_list(getattr(st, 'agedi_registered_isrcs', []) or []))
            pending_codes = [code for code in current_codes if code not in registered_codes]
            if not pending_codes and bool(getattr(st, 'agedi_done', False)):
                continue
            for artist in (song.artists or []):
                if artist and getattr(artist, 'id', None):
                    registros_artist_ids.add(artist.id)
            if getattr(song, 'release_date', None):
                registros_year_set.add(song.release_date.year)
            registros_agedi_items.append(
                {
                    'kind': 'SONG',
                    'song': song,
                    'item_id': str(song.id),
                    'title': getattr(song, 'title', None) or '—',
                    'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                    'artists_label': ', '.join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or '—',
                    'artist_ids': [str(a.id) for a in (song.artists or []) if getattr(a, 'id', None)],
                    'collaborator': (getattr(song, 'collaborator', None) or '').strip(),
                    'release_date': getattr(song, 'release_date', None),
                    'all_codes': [
                        {
                            'code': code,
                            'registered': code in registered_codes,
                            'pending': code not in registered_codes,
                        }
                        for code in current_codes
                    ],
                    'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
                    'register_url': url_for('discografica_song_agedi_register', song_id=song.id),
                    'album_kind_label': '',
                }
            )

        agedi_album_rows = (
            session_db.query(Album)
            .options(joinedload(Album.artist))
            .filter(Album.artist_id.in_(list(contract_artist_ids)) if contract_artist_ids else text('1=0'))
            .order_by(Album.release_date.desc(), Album.title.asc())
            .all()
        ) if contract_artist_ids else []
        if f_artist_id:
            agedi_album_rows = [album for album in agedi_album_rows if getattr(album, 'artist_id', None) == f_artist_id]
        if f_year:
            agedi_album_rows = [
                album
                for album in agedi_album_rows
                if getattr(album, 'release_date', None) and album.release_date.year == f_year
            ]
        agedi_album_ids = [album.id for album in agedi_album_rows]
        agedi_album_status_map = {}
        if agedi_album_ids:
            agedi_album_status_map = {
                row.album_id: row
                for row in session_db.query(AlbumStatus).filter(AlbumStatus.album_id.in_(agedi_album_ids)).all()
                if row and row.album_id
            }
        for album in agedi_album_rows:
            st = agedi_album_status_map.get(album.id) or _ensure_album_status_row(session_db, album)
            if bool(getattr(st, 'agedi_done', False)):
                continue
            artist = getattr(album, 'artist', None)
            if artist and getattr(artist, 'id', None):
                registros_artist_ids.add(artist.id)
            if getattr(album, 'release_date', None):
                registros_year_set.add(album.release_date.year)
            registros_agedi_items.append(
                {
                    'kind': 'ALBUM',
                    'album': album,
                    'item_id': str(album.id),
                    'title': getattr(album, 'title', None) or '—',
                    'cover_url': (getattr(album, 'cover_url', None) or '').strip(),
                    'artists_label': (getattr(artist, 'name', None) or '').strip() or '—',
                    'artist_ids': [str(getattr(artist, 'id', None) or '')] if getattr(artist, 'id', None) else [],
                    'collaborator': '',
                    'release_date': getattr(album, 'release_date', None),
                    'all_codes': [],
                    'detail_url': url_for('discografica_album_detail', album_id=album.id, tab='informacion'),
                    'register_url': url_for('discografica_album_status_toggle', album_id=album.id),
                    'album_kind_label': 'EP' if (getattr(album, 'album_type', None) or '').upper() == 'EP' else 'Disco',
                }
            )

        registros_agedi_items.sort(
            key=lambda item: (
                item.get('release_date') or date.min,
                (item.get('title') or '').casefold(),
            ),
            reverse=True,
        )

        ritmonet_song_rows = (
            session_db.query(Song)
            .join(SongArtist, Song.id == SongArtist.song_id)
            .join(SongISRCCode, SongISRCCode.song_id == Song.id)
            .filter(ownership_cond)
            .distinct()
            .options(selectinload(Song.artists))
            .order_by(Song.release_date.desc(), Song.title.asc())
            .all()
        )
        if f_artist_id:
            ritmonet_song_rows = [
                song
                for song in ritmonet_song_rows
                if any(getattr(artist, 'id', None) == f_artist_id for artist in (song.artists or []))
            ]
        if f_year:
            ritmonet_song_rows = [
                song
                for song in ritmonet_song_rows
                if getattr(song, 'release_date', None) and song.release_date.year == f_year
            ]
        ritmonet_song_ids = [song.id for song in ritmonet_song_rows]
        ritmonet_status_map = {}
        if ritmonet_song_ids:
            ritmonet_status_map = {
                row.song_id: row
                for row in session_db.query(SongStatus).filter(SongStatus.song_id.in_(ritmonet_song_ids)).all()
                if row and row.song_id
            }
        ritmonet_artist_ids = set()
        ritmonet_year_set = set()
        for song in ritmonet_song_rows:
            st = ritmonet_status_map.get(song.id) or _ensure_song_status_row(session_db, song)
            current_codes = _current_song_isrcs(session_db, song.id, include_song_field=True)
            if not current_codes or bool(getattr(st, 'ritmonet_done', False)):
                continue
            for artist in (song.artists or []):
                if artist and getattr(artist, 'id', None):
                    ritmonet_artist_ids.add(artist.id)
            if getattr(song, 'release_date', None):
                ritmonet_year_set.add(song.release_date.year)
            registros_ritmonet_songs.append(
                {
                    'song': song,
                    'item_id': str(song.id),
                    'title': getattr(song, 'title', None) or '—',
                    'cover_url': (getattr(song, 'cover_url', None) or '').strip(),
                    'artists_label': ', '.join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or '—',
                    'artist_ids': [str(a.id) for a in (song.artists or []) if getattr(a, 'id', None)],
                    'collaborator': (getattr(song, 'collaborator', None) or '').strip(),
                    'release_date': getattr(song, 'release_date', None),
                    'all_codes': [{'code': code} for code in current_codes],
                    'detail_url': url_for('discografica_song_detail', song_id=song.id, tab='informacion'),
                }
            )

        if registros_tab == 'sgae':
            registros_filter_artists = list(editorial_filter_artists or [])
            registros_filter_years = []
        elif registros_tab == 'agedi':
            registros_filter_artists = [artist for artist in artists if artist.id in registros_artist_ids]
            registros_filter_years = sorted(registros_year_set, reverse=True)
        else:
            registros_filter_artists = [artist for artist in artists if artist.id in ritmonet_artist_ids]
            registros_filter_years = sorted(ritmonet_year_set, reverse=True)

        session_db.commit()

    display_song_rows: list[Song] = []
    display_song_ids: set[str] = set()

    def _collect_display_song(song_row):
        sid = str(getattr(song_row, 'id', '') or '')
        if not sid or sid in display_song_ids:
            return
        display_song_ids.add(sid)
        display_song_rows.append(song_row)

    for _artist, rows in (artist_blocks or []):
        for song_row in rows or []:
            _collect_display_song(song_row)
    for song_row in (editorial_pending_songs or []):
        _collect_display_song(song_row)
    for song_row in (editorial_registered_songs or []):
        _collect_display_song(song_row)
    for row in (registros_agedi_items or []):
        if row.get('song') is not None:
            _collect_display_song(row.get('song'))
    for row in (registros_ritmonet_songs or []):
        if row.get('song') is not None:
            _collect_display_song(row.get('song'))

    extra_song_ids: list[UUID] = []
    for collection in (registros_upcoming_releases or [], launches_items or []):
        for row in collection:
            if (row.get('kind') or '').upper() != 'SONG':
                continue
            sid = to_uuid(row.get('item_id'))
            if sid and str(sid) not in display_song_ids:
                extra_song_ids.append(sid)
                display_song_ids.add(str(sid))
    if extra_song_ids:
        extra_rows = (
            session_db.query(Song)
            .options(selectinload(Song.artists))
            .filter(Song.id.in_(extra_song_ids))
            .all()
        )
        display_song_rows.extend(extra_rows)

    song_display_map = _annotate_song_display_fields(session_db, display_song_rows, persist=True)
    # Etiqueta ONE-STOP (máster 100% nuestro + sin intérpretes de fuera + autoría 100% de
    # Plataforma): se calcula EN BLOQUE para todo el listado y se cuelga en cada fila.
    _song_one_stop_map(session_db, display_song_rows)

    def _apply_display_collaborator(collection):
        for row in collection or []:
            sid = ''
            if isinstance(row, dict):
                sid = str(row.get('item_id') or getattr(row.get('song'), 'id', '') or '')
            if sid and sid in song_display_map:
                row['collaborator'] = song_display_map[sid].get('collaborator') or ''

    _apply_display_collaborator(registros_upcoming_releases)
    _apply_display_collaborator(registros_agedi_items)
    _apply_display_collaborator(registros_ritmonet_songs)
    _apply_display_collaborator(launches_items)

    # Distribuidoras (selectores de alta y edición en bloque) + pestaña Adelantos.
    distributors_all = session_db.query(Distributor).order_by(Distributor.name.asc()).all()
    distributor_by_id = {str(d.id): d for d in distributors_all}
    adelantos_ctx = _build_distributor_advances_context(session_db) if section == "adelantos" else None

    response = render_template(
        "discografica.html",
        section=section,
        # DEMOS: solo se calcula cuando se está mirando esa sección.
        demos_ctx=demos_ctx,
        projects_ctx=projects_ctx,
        project_wizard=project_wizard,
        song_genre_catalog=song_genre_catalog,
        # PLAYLIST: el listado (una debajo de otra), solo en su pestaña.
        playlist_rows=playlist_rows,
        demo_origins=DEMO_ORIGINS,
        demo_statuses=DEMO_STATUSES,
        demo_rating_filters=DEMO_RATING_FILTERS,
        demo_author_roles=DEMO_AUTHOR_ROLES,
        distributors=distributors_all,
        distributor_by_id=distributor_by_id,
        adelantos_ctx=adelantos_ctx,
        launches_items=launches_items,
        launches_calendar_months=launches_calendar_months,
        repertorio_tab=repertorio_tab,
        artists=artists,
        contract_artists=contract_artists,
        explicit_choices=EXPLICIT_CHOICES,
        artist_blocks=artist_blocks,
        album_blocks=album_blocks,
        song_audio_isrc_map=song_audio_isrc_map,
        editorial_tab=editorial_tab,
        editorial_pending_songs=editorial_pending_songs,
        editorial_registered_songs=editorial_registered_songs,
        editorial_filter_artists=editorial_filter_artists,
        # ISRC
        # (La pantalla de ISRC se movió a Registros: su contexto lo monta `_isrc_panel_context`.)
        # Ingresos
        income_view=income_view,
        income_period_label=income_period_label,
        income_period_type=income_period_type,
        income_period_key=income_period_key,
        income_period_start_iso=income_period_start_iso,
        income_month_tabs=income_month_tabs,
        income_month_prev_url=income_month_prev_url,
        income_month_next_url=income_month_next_url,
        income_semester_tabs=income_semester_tabs,
        income_artist_blocks=income_artist_blocks,
        income_next_url=income_next_url,
        income_upload_report=income_upload_report,
        income_import_review=income_import_review,
        income_report_months=income_report_months,
        income_report_semesters=income_report_semesters,
        income_report_months_selected=income_report_months_selected,
        income_report_semesters_selected=income_report_semesters_selected,
        # Royalties
        royalty_period_label=royalty_period_label,
        royalty_semester_key=royalty_semester_key,
        royalty_semester_tabs=royalty_semester_tabs,
        royalty_beneficiaries_artists=royalty_beneficiaries_artists,
        royalty_beneficiaries_others=royalty_beneficiaries_others,
        royalty_filter_artists=royalty_filter_artists,
        royalty_selected_artist_id=royalty_selected_artist_id,
        royalty_selected_statuses=royalty_selected_statuses,
        royalty_pending_generate=royalty_pending_generate,
        royalty_pending_send=royalty_pending_send,
        royalty_tab=royalty_tab,
        afavor_groups=afavor_groups,
        afavor_total=afavor_total,
        royalty_semester_start_iso=royalty_semester_start_iso,
        # Registros
        registros_tab=registros_tab,
        registros_upcoming_releases=registros_upcoming_releases,
        registros_sgae_pending_songs=registros_sgae_pending_songs,
        registros_agedi_items=registros_agedi_items,
        registros_ritmonet_songs=registros_ritmonet_songs,
        registros_filter_artists=registros_filter_artists,
        registros_filter_years=registros_filter_years,
        registros_selected_artist_id=registros_selected_artist_id,
        registros_selected_year=registros_selected_year,
    )
    session_db.close()
    return response


@app.post("/discografica/isrc/config/update")
@admin_required
def discografica_isrc_config_update():
    """Guardar configuración global de ISRC (país + matrices audio/video)."""

    if not can_edit_discografica():
        return forbid("No tienes permisos para editar la configuración ISRC.")

    country_code = (request.form.get("country_code") or "ES").strip().upper()[:2] or "ES"
    audio_matrix = (request.form.get("audio_matrix") or "").strip()
    video_matrix = (request.form.get("video_matrix") or "").strip()

    # Normalizar: solo dígitos y padding
    def norm_digits(v: str, length: int) -> str:
        v = "".join([c for c in (v or "") if c.isdigit()])
        if not v:
            return "0" * length
        return v.zfill(length)[-length:]

    audio_matrix = norm_digits(audio_matrix, 3)
    video_matrix = norm_digits(video_matrix, 3)

    session_db = db()
    try:
        cfg = session_db.get(ISRCConfig, 1)
        if not cfg:
            cfg = ISRCConfig(id=1)
            session_db.add(cfg)
        cfg.country_code = country_code
        cfg.audio_matrix = audio_matrix
        cfg.video_matrix = video_matrix
        cfg.updated_at = datetime.now(tz=ZoneInfo("Europe/Madrid"))
        session_db.commit()
        flash("Configuración ISRC guardada.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando configuración ISRC: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("registros_view", tab="isrc", isrc_tab="configurador"))


@app.post("/discografica/isrc/artist/<artist_id>/set")
@admin_required
def discografica_isrc_artist_set(artist_id):
    """Guardar número matriz ISRC del artista (2 dígitos)."""

    if not can_edit_discografica():
        return forbid("No tienes permisos para editar ISRC por artista.")

    matrix = (request.form.get("artist_matrix") or "").strip()
    matrix = "".join([c for c in matrix if c.isdigit()]).zfill(2)[-2:] if matrix else None

    session_db = db()
    try:
        aid = to_uuid(artist_id)
        artist = session_db.get(Artist, aid)
        if not artist:
            flash("Artista no encontrado.", "warning")
            return redirect(url_for("registros_view", tab="isrc", isrc_tab="configurador"))

        rec = session_db.get(ArtistISRCSetting, aid)
        if not rec:
            rec = ArtistISRCSetting(artist_id=aid)
            session_db.add(rec)
        rec.artist_matrix = matrix
        rec.updated_at = datetime.now(tz=ZoneInfo("Europe/Madrid"))
        session_db.commit()
        flash(f"ISRC del artista guardado: {artist.name}", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando ISRC del artista: {e}", "danger")
    finally:
        session_db.close()

    return redirect(url_for("registros_view", tab="isrc", isrc_tab="configurador"))


@app.post("/discografica/canciones/<song_id>/explicito", endpoint="discografica_song_explicit_save")
@admin_required
def discografica_song_explicit_save(song_id):
    """Marca si la canción tiene CONTENIDO EXPLÍCITO (o no). Hay que decirlo en todas."""
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar canciones.")
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))
        valor = _explicit_from_form(request.form.get("is_explicit"))
        if valor is None:
            flash("Dinos si tiene contenido explícito o no.", "warning")
        else:
            song.is_explicit = valor
            session_db.commit()
            flash("Marcada como %s." % ("explícita" if valor else "no explícita"), "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("discografica_song_detail", song_id=song_id, tab="informacion")))


@app.post("/discografica/canciones/bulk-update", endpoint="discografica_songs_bulk_update")
@admin_required
def discografica_songs_bulk_update():
    """Edición EN BLOQUE de canciones del repertorio (distribuidora, categoría, catálogo,
    explícita). Solo aplica los campos con valor; distribuidora/categoría/catálogo se saltan
    las colaboraciones externas (van por su compañía colaboradora)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar canciones.")
    ids = [to_uuid(x) for x in request.form.getlist("song_ids[]")]
    ids = [x for x in ids if x]
    if not ids:
        flash("No hay canciones seleccionadas.", "warning")
        return redirect(url_for("discografica_view", section="canciones", rep_tab="canciones"))
    dist_raw = (request.form.get("distributor_id") or "").strip()
    ownership = (request.form.get("ownership_type") or "").strip().lower()
    catalog_raw = (request.form.get("is_catalog") or "").strip()
    explicit_raw = (request.form.get("is_explicit") or "").strip()
    session_db = db()
    try:
        dist_id = None
        if dist_raw and dist_raw != "__none__":
            dist_id = to_uuid(dist_raw)
            if not dist_id or not session_db.get(Distributor, dist_id):
                flash("Distribuidora no válida.", "warning")
                return redirect(url_for("discografica_view", section="canciones", rep_tab="canciones"))
        songs = session_db.query(Song).filter(Song.id.in_(ids)).all()
        changed = 0
        skipped_external = 0
        for sng in songs:
            touched = False
            if sng.is_external_collab and (dist_raw or ownership or catalog_raw):
                skipped_external += 1
            if not sng.is_external_collab:
                if dist_raw == "__none__" and sng.distributor_id is not None:
                    sng.distributor_id = None; touched = True
                elif dist_id and sng.distributor_id != dist_id:
                    sng.distributor_id = dist_id; touched = True
                if ownership in ("own", "distribution"):
                    new_dist = ownership == "distribution"
                    if bool(sng.is_distribution) != new_dist:
                        sng.is_distribution = new_dist
                        if new_dist:
                            sng.master_ownership_pct = Decimal("0")
                        touched = True
                if catalog_raw in ("0", "1"):
                    new_cat = catalog_raw == "1"
                    if bool(sng.is_catalog) != new_cat:
                        sng.is_catalog = new_cat; touched = True
            if explicit_raw in ("0", "1"):
                # ⚠️ Se compara con `is not`: `is_explicit` tiene TRES estados y `bool(None)` es
                # False, así que con `bool(...)` no se distinguía «sin decidir» de «no explícita» y
                # marcarlas «No explícita» en bloque no cambiaba nada.
                new_exp = explicit_raw == "1"
                if sng.is_explicit is not new_exp:
                    sng.is_explicit = new_exp; touched = True
            if touched:
                changed += 1
        session_db.commit()
        msg = f"Cambios aplicados a {changed} canción(es)."
        if skipped_external:
            msg += f" {skipped_external} colaboración(es) externa(s) no se tocaron (distribuidora/categoría no aplican)."
        flash(msg, "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error aplicando los cambios en bloque: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_view", section="canciones", rep_tab="canciones"))


# ===================== Discográfica · ADELANTOS de distribuidoras =====================
# Un adelanto se RECUPERA con los ingresos del contenido distribuido con su distribuidora,
# según sus condiciones ({%, base bruto/neto, contenido desde/hasta fecha, solo ciertos
# artistas}) y sus excepciones (artistas o canciones que no amortizan). Todo lo que no va a
# amortización es nuestro. Nada se guarda calculado: se recalcula con los ingresos actuales.

def _song_income_periods(session_db, song_ids):
    """Apuntes de ingresos POR PERIODO y canción, deduplicados como en royalties (la fila de
    SEMESTRE prevalece sobre los meses que cubre): {song_id(str): [{'start','end','ptype',
    'gross','net'}]} ordenados por fecha. Alimenta la liquidación de adelantos por
    mes/semestre/año además del total."""
    out = {}
    if not song_ids:
        return out
    sem_ranges = {}
    rows = (
        session_db.query(SongRevenueEntry)
        .filter(SongRevenueEntry.song_id.in_(song_ids))
        .all()
    )
    for r in rows:
        if (r.period_type or "").upper() == "SEMESTER" and r.period_start and r.period_end:
            sem_ranges.setdefault(str(r.song_id), []).append((r.period_start, r.period_end))
    def _dec(v):
        try:
            return Decimal(str(v)) if v is not None else Decimal("0")
        except (InvalidOperation, ValueError):
            return Decimal("0")
    for r in rows:
        sid = str(r.song_id)
        ptype = (r.period_type or "").upper() or "MONTH"
        if ptype == "MONTH":
            covered = any(a <= (r.period_start or date.min) <= b for a, b in sem_ranges.get(sid, []))
            if covered:
                continue
        out.setdefault(sid, []).append({
            "start": r.period_start, "end": r.period_end, "ptype": ptype,
            "gross": _dec(r.gross), "net": _dec(r.net),
        })
    for sid in out:
        out[sid].sort(key=lambda e: (e["start"] or date.min))
    return out


def _add_months(d, months):
    """Suma meses a una fecha ajustando el día al último del mes destino si hace falta."""
    m = d.month - 1 + int(months)
    y = d.year + m // 12
    m = m % 12 + 1
    last = _cal.monthrange(y, m)[1]
    return date(y, m, min(d.day, last))


def _advance_rule_matches(rule, song, song_artist_ids):
    """¿Cubre esta condición a la canción? Fecha de publicación dentro del rango; si limita
    artistas, alguno de los de la canción está en la lista; y si tiene CARENCIA, solo cuando
    ya han pasado N meses desde la publicación de la canción (hasta entonces no amortiza)."""
    if rule.date_from and (not song.release_date or song.release_date < rule.date_from):
        return False
    if rule.date_until and (not song.release_date or song.release_date > rule.date_until):
        return False
    if rule.min_age_months:
        if not song.release_date:
            return False
        if _add_months(song.release_date, int(rule.min_age_months)) > today_local():
            return False
    scope = [str(x) for x in (rule.artist_ids or [])]
    if scope and not (set(scope) & set(song_artist_ids)):
        return False
    return True


def _advance_matching_rule(adv, song, song_artist_ids):
    """Primera condición del adelanto que cubre la canción (o None). Las excepciones del
    adelanto (canción o cualquiera de sus artistas) la excluyen del todo."""
    for exc in (adv.exceptions or []):
        tid = str(exc.target_id)
        if (exc.kind or "").upper() == "SONG" and tid == str(song.id):
            return None
        if (exc.kind or "").upper() == "ARTIST" and tid in song_artist_ids:
            return None
    for rule in (adv.rules or []):
        if _advance_rule_matches(rule, song, song_artist_ids):
            return rule
    return None


_ADV_INCOMES_READY = False


def _build_distributor_advances_context(session_db):
    """Contexto completo de la pestaña Adelantos: por distribuidora, sus adelantos con estado
    de recuperación y la liquidación artista por artista (nº canciones, generado por canción,
    neto, parte que amortiza y parte nuestra). Cada canción amortiza en el PRIMER adelanto
    (por fecha) cuyas condiciones la cubren, hasta agotar su importe."""
    # Blindaje: si el esquema de 2º plano aún no ha creado la tabla de ingresos adicionales
    # (carrera justo tras un deploy), NO reventamos la página — se tratan como vacíos hasta
    # que exista (se cachea en cuanto aparece). Evita el 500 que dejaría «caída» la sección.
    global _ADV_INCOMES_READY
    incomes_ready = _ADV_INCOMES_READY or _table_exists(session_db, "public.distributor_advance_incomes")
    _ADV_INCOMES_READY = incomes_ready
    distributors = session_db.query(Distributor).order_by(Distributor.name.asc()).all()
    _adv_opts = [selectinload(DistributorAdvance.rules),
                 selectinload(DistributorAdvance.exceptions),
                 selectinload(DistributorAdvance.corrections)]
    if incomes_ready:
        _adv_opts.append(selectinload(DistributorAdvance.additional_incomes))
    advances = (
        session_db.query(DistributorAdvance)
        .options(*_adv_opts)
        .order_by(DistributorAdvance.advance_date.asc().nullslast(), DistributorAdvance.created_at.asc())
        .all()
    )
    # Autores de las correcciones e ingresos adicionales (nick + foto, como en el resto de la app).
    corr_user_ids = {str(c.created_by_user_id) for adv in advances for c in (adv.corrections or []) if c.created_by_user_id}
    if incomes_ready:
        corr_user_ids |= {str(i.created_by_user_id) for adv in advances for i in (adv.additional_incomes or []) if i.created_by_user_id}
    corr_authors = {}
    if corr_user_ids:
        for up in session_db.query(UserProfile).filter(UserProfile.user_id.in_([to_uuid(x) for x in corr_user_ids])).all():
            corr_authors[str(up.user_id)] = {"nick": up.nick or "", "photo_url": up.photo_url or ""}
    adv_by_dist = {}
    for adv in advances:
        adv_by_dist.setdefault(str(adv.distributor_id), []).append(adv)

    artists_all = session_db.query(Artist).order_by(Artist.name.asc()).all()
    artist_by_id = {str(a.id): a for a in artists_all}

    blocks = []
    for dist in distributors:
        dist_advs = adv_by_dist.get(str(dist.id), [])
        songs = (
            session_db.query(Song)
            .filter(Song.distributor_id == dist.id, Song.is_external_collab.is_(False))
            .order_by(Song.title.asc())
            .all()
        )
        song_ids = [sng.id for sng in songs]
        sa_rows = (
            session_db.query(SongArtist.song_id, SongArtist.artist_id)
            .filter(SongArtist.song_id.in_(song_ids)).all()
        ) if song_ids else []
        artists_of_song = {}
        for sid, aid in sa_rows:
            artists_of_song.setdefault(str(sid), []).append(str(aid))
        income_periods = _song_income_periods(session_db, song_ids)

        # Cada APUNTE amortiza en orden CRONOLÓGICO (lo cobrado antes recupera antes) en el
        # primer adelanto ACTIVO que: (a) cubre la canción por sus condiciones, y (b) cuyo
        # acuerdo ya estaba FIRMADO — solo cuentan los ingresos generados DESDE la fecha de la
        # firma (advance_date; el periodo que contiene la firma, incluido), NUNCA los ingresos
        # anteriores de esas canciones. Por eso en la liquidación de un adelanto solo aparecen
        # los meses/semestres/años dentro del acuerdo. Si varios adelantos cubren un apunte,
        # gana el primero con importe pendiente (si todos están recuperados, el primero).
        remaining = {}
        corr_total_by_adv = {}
        income_views_by_adv = {}
        income_amort_by_adv = {}
        for adv in dist_advs:
            try:
                amt0 = Decimal(str(adv.amount or 0))
            except (InvalidOperation, ValueError):
                amt0 = Decimal("0")
            corr_total = Decimal("0")
            for c in (adv.corrections or []):
                try:
                    corr_total += Decimal(str(c.amount or 0))
                except (InvalidOperation, ValueError):
                    pass
            corr_total_by_adv[str(adv.id)] = corr_total
            # Ingresos ADICIONALES: cada uno amortiza aplicando su condición de recuperación
            # (base × pct: NET usa el neto, GROSS usa el bruto). Si no tiene regla asignada se
            # aplica la primera del adelanto (al crear, si solo hay una se asigna sola).
            rules_by_id = {str(r.id): r for r in (adv.rules or [])}
            inc_views = []
            inc_amort_total = Decimal("0")
            for inc in ((adv.additional_incomes or []) if incomes_ready else []):
                try:
                    inc_net = Decimal(str(inc.amount_net or 0))
                except (InvalidOperation, ValueError):
                    inc_net = Decimal("0")
                try:
                    inc_gross = Decimal(str(inc.amount_gross or 0))
                except (InvalidOperation, ValueError):
                    inc_gross = Decimal("0")
                rule = rules_by_id.get(str(inc.rule_id)) if inc.rule_id else None
                if rule is None and (adv.rules or []):
                    rule = (adv.rules or [])[0]
                if rule is not None:
                    base = (rule.base or "NET").upper()
                    base_amt = inc_gross if base == "GROSS" else inc_net
                    try:
                        rpct = Decimal(str(rule.pct or 0))
                    except (InvalidOperation, ValueError):
                        rpct = Decimal("0")
                else:
                    base, base_amt, rpct = "NET", inc_net, Decimal("100")
                inc_amort = (base_amt * rpct / Decimal("100")).quantize(Decimal("0.01"))
                inc_amort_total += inc_amort
                # Lo que NO amortiza del ingreso (neto − amortizado) es NUESTRO.
                inc_ours = (inc_net - inc_amort)
                inc_views.append({
                    "id": str(inc.id),
                    "label": inc.label or "Ingreso adicional",
                    "net": inc_net, "gross": inc_gross,
                    "base": base, "pct": rpct, "amort": inc_amort, "ours": inc_ours,
                    "date": inc.income_date,
                    "note": (inc.note or "").strip(),
                    "rule_text": _advance_rule_pdf_text(rule, artist_by_id) if rule is not None else "Sin condición aplicable",
                    "author": corr_authors.get(str(inc.created_by_user_id)) if inc.created_by_user_id else None,
                })
            income_views_by_adv[str(adv.id)] = inc_views
            income_amort_by_adv[str(adv.id)] = inc_amort_total
            # Las correcciones manuales (±) y lo amortizado por los ingresos adicionales entran en
            # la CUENTA GENERAL de amortización: reducen lo pendiente del adelanto.
            remaining[str(adv.id)] = amt0 - corr_total - inc_amort_total
        rows_by_adv = {str(adv.id): [] for adv in dist_advs}
        unassigned_rows = []
        # Para las canciones SIN ingresos (fila a cero en la vista «Todo»): primer adelanto
        # activo que las cubre por condiciones (sin mirar la ventana del acuerdo).
        assign_map = {}
        for sng in songs:
            sid = str(sng.id)
            aids = artists_of_song.get(sid, [])
            chosen = None
            for adv in dist_advs:
                if (adv.status or "ACTIVO").upper() != "ACTIVO":
                    continue
                rule = _advance_matching_rule(adv, sng, aids)
                if rule:
                    chosen = (adv, rule)
                    break
            assign_map[sid] = chosen
        events = []
        for sng in songs:
            for e in income_periods.get(str(sng.id), []):
                events.append((e["start"] or date.min, (sng.title or "").lower(), sng, e))
        events.sort(key=lambda t: (t[0], t[1]))
        for _st, _tt, sng, e in events:
            sid = str(sng.id)
            aids = artists_of_song.get(sid, [])
            row = {
                "song": sng, "artist_ids": aids,
                "start": e["start"], "end": e["end"], "ptype": e["ptype"],
                "gross": e["gross"], "net": e["net"],
                "amort": Decimal("0"), "ours": e["net"],
            }
            period_close = e["end"] or e["start"]
            candidates = []
            for adv in dist_advs:
                if (adv.status or "ACTIVO").upper() != "ACTIVO":
                    continue
                # Fuera del acuerdo: el periodo terminó ANTES de la firma → no retroactivo.
                if adv.advance_date and period_close and period_close < adv.advance_date:
                    continue
                rule = _advance_matching_rule(adv, sng, aids)
                if rule:
                    candidates.append((adv, rule))
            chosen = None
            for adv, rule in candidates:
                if remaining[str(adv.id)] > 0:
                    chosen = (adv, rule)
                    break
            if not chosen and candidates:
                chosen = candidates[0]
            if chosen:
                adv, rule = chosen
                base_amt = e["gross"] if (rule.base or "NET").upper() == "GROSS" else e["net"]
                try:
                    pct = Decimal(str(rule.pct or 0))
                except (InvalidOperation, ValueError):
                    pct = Decimal("0")
                amort_full = (base_amt * pct / Decimal("100")).quantize(Decimal("0.01"))
                take = min(amort_full, max(Decimal("0"), remaining[str(adv.id)]))
                remaining[str(adv.id)] -= take
                row["amort"] = take
                row["ours"] = e["net"] - take
                rows_by_adv[str(adv.id)].append(row)
            else:
                unassigned_rows.append(row)
        # Canciones sin ingresos todavía: fila a cero para que se vean en la vista «Todo».
        for sng in songs:
            sid = str(sng.id)
            if income_periods.get(sid):
                continue
            row = {
                "song": sng, "artist_ids": artists_of_song.get(sid, []),
                "start": None, "end": None, "ptype": None,
                "gross": Decimal("0"), "net": Decimal("0"),
                "amort": Decimal("0"), "ours": Decimal("0"),
            }
            chosen = assign_map.get(sid)
            if chosen:
                rows_by_adv[str(chosen[0].id)].append(row)
            else:
                unassigned_rows.append(row)

        adv_views = []
        for adv in dist_advs:
            try:
                amount = Decimal(str(adv.amount or 0))
            except (InvalidOperation, ValueError):
                amount = Decimal("0")
            rem = max(Decimal("0"), remaining.get(str(adv.id), Decimal("0")))
            recovered = amount - rem
            pct_rec = float(recovered / amount * 100) if amount > 0 else 0.0
            if (adv.status or "ACTIVO").upper() != "ACTIVO":
                state, state_class = "ARCHIVADO", "secondary"
            elif amount > 0 and recovered >= amount:
                state, state_class = "RECUPERADO", "success"
            elif recovered > 0:
                state, state_class = "AMORTIZANDO", "warning"
            else:
                state, state_class = "PENDIENTE", "danger"
            # Agrupar por artista y canción (total histórico, para el PDF y los totales; una
            # canción con varios artistas cuenta en el primero) + filas POR PERIODO para la
            # vista por mes/semestre/año (se agregan en el navegador).
            by_artist = {}
            rows_payload = []
            for row in rows_by_adv.get(str(adv.id), []):
                aid = row["artist_ids"][0] if row["artist_ids"] else ""
                art = artist_by_id.get(aid)
                g = by_artist.setdefault(aid, {
                    "artist": art,
                    "by_song": {},
                    "net": Decimal("0"), "gross": Decimal("0"),
                    "amort": Decimal("0"), "ours": Decimal("0"),
                })
                sk = str(row["song"].id)
                sg = g["by_song"].setdefault(sk, {
                    "song": row["song"],
                    "net": Decimal("0"), "gross": Decimal("0"),
                    "amort": Decimal("0"), "ours": Decimal("0"),
                })
                for k in ("net", "gross", "amort", "ours"):
                    sg[k] += row[k]
                    g[k] += row[k]
                rows_payload.append({
                    "aid": aid,
                    "an": (art.name if art else "Sin artista") or "Sin artista",
                    "ap": (art.photo_url or "") if art else "",
                    "sid": sk,
                    "st": row["song"].title or "",
                    "su": url_for("discografica_song_detail", song_id=row["song"].id),
                    "cv": row["song"].cover_url or "",
                    "ps": row["start"].isoformat() if row["start"] else None,
                    "pt": row["ptype"],
                    "net": float(row["net"]), "gross": float(row["gross"]),
                    "am": float(row["amort"]), "ours": float(row["ours"]),
                })
            artist_groups = []
            for g in by_artist.values():
                g["songs"] = sorted(g.pop("by_song").values(), key=lambda s: (s["song"].title or "").lower())
                artist_groups.append(g)
            artist_groups.sort(key=lambda g: (g["artist"].name.lower() if g["artist"] else "zzz"))
            totals = {
                "songs": sum(len(g["songs"]) for g in artist_groups),
                "net": sum((g["net"] for g in artist_groups), Decimal("0")),
                "amort": sum((g["amort"] for g in artist_groups), Decimal("0")),
                "ours": sum((g["ours"] for g in artist_groups), Decimal("0")),
            }
            corrections_view = []
            for c in sorted((adv.corrections or []), key=lambda x: (x.correction_date or date.min, x.created_at or datetime.min.replace(tzinfo=TZ_MADRID))):
                try:
                    c_amt = Decimal(str(c.amount or 0))
                except (InvalidOperation, ValueError):
                    c_amt = Decimal("0")
                corrections_view.append({
                    "id": str(c.id),
                    "label": c.label or "Corrección",
                    "amount": c_amt,
                    "date": c.correction_date,
                    "note": (c.note or "").strip(),
                    "author": corr_authors.get(str(c.created_by_user_id)) if c.created_by_user_id else None,
                })
            inc_views = income_views_by_adv.get(str(adv.id), [])
            inc_net_sum = sum((iv["net"] for iv in inc_views), Decimal("0"))
            inc_amort_sum = income_amort_by_adv.get(str(adv.id), Decimal("0"))
            inc_ours_sum = sum((iv["ours"] for iv in inc_views), Decimal("0"))
            # El ingreso adicional forma parte de la cuenta: su neto suma al ingreso, lo que
            # amortiza suma a «Amortiza» y el resto (neto − amortizado) suma a «Nuestro».
            totals["net"] += inc_net_sum
            totals["amort"] += inc_amort_sum
            totals["ours"] += inc_ours_sum
            # Filas sintéticas para las vistas por periodo (KPIs/PDF): NO son canciones (inc=1),
            # se filtran del desglose por artista pero cuentan en los totales del periodo.
            for iv in inc_views:
                rows_payload.append({
                    "aid": "__inc__", "an": "Ingresos adicionales", "ap": "",
                    "sid": "inc:" + iv["id"], "st": iv["label"], "su": "", "cv": "",
                    "ps": iv["date"].isoformat() if iv["date"] else None, "pt": None,
                    "net": float(iv["net"]), "gross": float(iv["gross"]),
                    "am": float(iv["amort"]), "ours": float(iv["ours"]),
                    "inc": 1,
                })
            adv_views.append({
                "adv": adv,
                "amount": amount,
                "recovered": recovered,
                "remaining": rem,
                "pct": max(0.0, min(100.0, pct_rec)),
                "state": state,
                "state_class": state_class,
                "artist_groups": artist_groups,
                "totals": totals,
                "rows": rows_payload,
                "corrections": corrections_view,
                "corrections_total": corr_total_by_adv.get(str(adv.id), Decimal("0")),
                "additional_incomes": inc_views,
                "additional_incomes_amort": inc_amort_sum,
                "additional_incomes_net": inc_net_sum,
                "additional_incomes_ours": inc_ours_sum,
            })
        blocks.append({
            "distributor": dist,
            "advances": adv_views,
            "songs": songs,
            "n_songs": len(songs),
            "unassigned": unassigned_rows,
        })
    return {
        "blocks": blocks,
        "distributors": distributors,
        "artists": artists_all,
        "artist_by_id": artist_by_id,
        "has_advances": any(b["advances"] for b in blocks),
    }


@app.post("/discografica/adelantos/crear", endpoint="discografica_advance_create")
@admin_required
def discografica_advance_create():
    if not can_edit_discografica():
        return forbid("No tienes permisos para crear adelantos.")
    session_db = db()
    try:
        dist_id = to_uuid((request.form.get("distributor_id") or "").strip())
        if not dist_id or not session_db.get(Distributor, dist_id):
            flash("Debes seleccionar la distribuidora del adelanto.", "warning")
            return redirect(url_for("discografica_view", section="adelantos"))
        amount = _parse_money_decimal(request.form.get("amount"))
        if amount <= 0:
            flash("El importe del adelanto debe ser mayor que cero.", "warning")
            return redirect(url_for("discografica_view", section="adelantos"))
        contract = request.files.get("contract")
        contract_url = upload_pdf(contract, "distributor_advances") if contract and getattr(contract, "filename", "") else None
        adv = DistributorAdvance(
            distributor_id=dist_id,
            label=(request.form.get("label") or "").strip() or None,
            amount=amount,
            advance_date=parse_optional_date(request.form.get("advance_date")),
            contract_url=contract_url,
            notes=(request.form.get("notes") or "").strip() or None,
        )
        session_db.add(adv)
        session_db.flush()
        session_db.add(_advance_rule_from_form(adv.id, request.form))
        session_db.commit()
        flash("Adelanto creado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error creando el adelanto: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_view", section="adelantos"))


def _advance_rule_from_form(advance_id, form, sort_order=0):
    """Construye una condición de recuperación desde el formulario (wizard o «añadir condición»)."""
    try:
        pct = Decimal((form.get("rule_pct") or "100").strip().replace(",", "."))
    except (InvalidOperation, ValueError):
        pct = Decimal("100")
    pct = max(Decimal("0"), min(Decimal("100"), pct))
    base = (form.get("rule_base") or "NET").strip().upper()
    if base not in ("NET", "GROSS"):
        base = "NET"
    scope = (form.get("rule_scope") or "all").strip().lower()
    date_from = parse_optional_date(form.get("rule_date_from")) if scope == "from" else None
    date_until = parse_optional_date(form.get("rule_date_until")) if scope == "until" else None
    artists_mode = (form.get("rule_artists_mode") or "all").strip().lower()
    artist_ids = None
    if artists_mode == "some":
        artist_ids = [str(to_uuid(x)) for x in form.getlist("rule_artist_ids[]") if to_uuid(x)]
        artist_ids = artist_ids or None
    # Carencia: cada canción amortiza solo cuando pasan N meses/años desde SU publicación.
    min_age_months = None
    if (form.get("rule_age_mode") or "now").strip().lower() == "age":
        try:
            n = int((form.get("rule_age_num") or "0").strip() or "0")
        except ValueError:
            n = 0
        unit = (form.get("rule_age_unit") or "months").strip().lower()
        if unit in ("years", "anios", "años"):
            n *= 12
        min_age_months = n if n > 0 else None
    return DistributorAdvanceRule(
        advance_id=advance_id, pct=pct, base=base,
        date_from=date_from, date_until=date_until,
        artist_ids=artist_ids, min_age_months=min_age_months, sort_order=sort_order,
    )


def _get_advance_or_redirect(session_db, aid):
    adv = session_db.get(DistributorAdvance, to_uuid(aid))
    return adv


@app.post("/discografica/adelantos/<aid>/actualizar", endpoint="discografica_advance_update")
@admin_required
def discografica_advance_update(aid):
    if not can_edit_discografica():
        return forbid("No tienes permisos para editar adelantos.")
    session_db = db()
    try:
        adv = _get_advance_or_redirect(session_db, aid)
        if not adv:
            flash("Adelanto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="adelantos"))
        if request.form.get("label") is not None:
            adv.label = (request.form.get("label") or "").strip() or None
        if (request.form.get("amount") or "").strip():
            amt = _parse_money_decimal(request.form.get("amount"))
            if amt > 0:
                adv.amount = amt
        if request.form.get("advance_date") is not None:
            adv.advance_date = parse_optional_date(request.form.get("advance_date"))
        if request.form.get("notes") is not None:
            adv.notes = (request.form.get("notes") or "").strip() or None
        status = (request.form.get("status") or "").strip().upper()
        if status in ("ACTIVO", "ARCHIVADO"):
            adv.status = status
        contract = request.files.get("contract")
        if contract and getattr(contract, "filename", ""):
            adv.contract_url = upload_pdf(contract, "distributor_advances")
        adv.updated_at = datetime.utcnow()
        session_db.commit()
        flash("Adelanto actualizado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error actualizando el adelanto: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_view", section="adelantos"))


