@app.get("/discografica/royalties/liquidacion/preview")
@admin_required
def discografica_royalties_liquidation_preview():
    kind = (request.args.get('kind') or '').strip().upper()
    bid_raw = (request.args.get('bid') or '').strip()
    sem_key = (request.args.get('s') or '').strip()

    if kind not in ('ARTIST', 'PROMOTER'):
        return jsonify({'ok': False, 'message': 'Beneficiario inválido.'}), 400

    parsed_sem = _parse_semester_key(sem_key)
    if not parsed_sem:
        return jsonify({'ok': False, 'message': 'Semestre inválido.'}), 400
    sem_year, sem_half = parsed_sem
    sem_start, sem_end = _semester_range(sem_year, sem_half)

    try:
        beneficiary_uuid = uuid.UUID(bid_raw)
    except Exception:
        return jsonify({'ok': False, 'message': 'Beneficiario inválido.'}), 400

    with get_db() as session_db:
        try:
            _pdf_bytes, _filename, beneficiary = _build_royalty_liquidation_pdf_bytes(
                session_db,
                kind,
                beneficiary_uuid,
                sem_year,
                sem_half,
                touch_liquidation=False,
            )
        except LookupError:
            return jsonify({'ok': False, 'message': 'No hay datos para esta liquidación.'}), 404
        except Exception as exc:
            return jsonify({'ok': False, 'message': f'No se pudo preparar la liquidación: {exc}'}), 400

        delivery = _beneficiary_email_delivery_data(session_db, kind, beneficiary_uuid)
        rec = _royalty_liquidation_record(session_db, kind, beneficiary_uuid, sem_start)

        period_label = _royalty_liquidation_period_label_from_dates(sem_start, sem_end)
        logo_url, photo_url = _royalty_liquidation_brand_assets(session_db, beneficiary)
        subject = _royalty_liquidation_subject(sem_year, sem_half)
        public_token = _make_public_royalty_liquidation_token(kind, str(beneficiary_uuid), sem_key)
        download_url = _external_url_for('public_royalty_liquidation_pdf') + f'?token={quote_plus(public_token)}'
        upload_url = _external_url_for('public_royalty_liquidation_view', token=public_token)
        html_body, _text_body = _build_royalty_liquidation_email_body(beneficiary, period_label, download_url, logo_url, photo_url, upload_url=upload_url)

        current_snapshot = _royalty_liquidation_snapshot(beneficiary, sem_start, sem_end)
        current_signature = _royalty_liquidation_snapshot_signature(current_snapshot)

        previous_snapshot = _ensure_snapshot_defaults(getattr(rec, 'last_sent_snapshot', None) if rec else None, beneficiary)
        previous_signature = (getattr(rec, 'last_sent_signature', None) or '').strip() if rec else ''
        if not previous_signature and previous_snapshot.get('items'):
            previous_signature = _royalty_liquidation_snapshot_signature(previous_snapshot)
        previous_html_body = ''
        can_send_previous = bool(rec and getattr(rec, 'last_sent_pdf_url', None) and previous_snapshot.get('items'))
        if can_send_previous:
            prev_start = parse_date(str(previous_snapshot.get('period_start') or '').strip()) or sem_start
            prev_end = parse_date(str(previous_snapshot.get('period_end') or '').strip()) or sem_end
            prev_label = _royalty_liquidation_period_label_from_dates(prev_start, prev_end) or period_label
            previous_html_body, _previous_text_body = _build_royalty_liquidation_email_body(
                previous_snapshot,
                prev_label,
                (getattr(rec, 'last_sent_pdf_url', None) or '').strip() or download_url,
                logo_url,
                (previous_snapshot.get('photo_url') or photo_url),
            )

        default_recipients = list(delivery.get('default_recipients') or [])
        suggested_recipients = list(delivery.get('suggested_recipients') or [])
        if not default_recipients and suggested_recipients:
            default_recipients = suggested_recipients[:1]

        return jsonify({
            'ok': True,
            'subject': subject,
            'html_body': html_body,
            'previous_html_body': previous_html_body,
            'default_recipients': default_recipients,
            'suggested_recipients': suggested_recipients,
            'has_changes': bool(can_send_previous and previous_signature and previous_signature != current_signature),
            'can_send_previous': can_send_previous,
            'last_sent_at_label': _format_madrid_datetime_label(getattr(rec, 'last_sent_at', None) if rec else None),
            'last_sent_to': list(getattr(rec, 'last_sent_to', None) or []) if rec else [],
            'last_sent_pdf_url': (getattr(rec, 'last_sent_pdf_url', None) or '').strip() if rec else '',
        })


@app.get("/discografica/royalties/liquidacion/comparar", endpoint="royalty_liquidation_compare")
@admin_required
def royalty_liquidation_compare():
    """Antes de generar una liquidación NUEVA sobre una que ya existe: qué cambia respecto a la
    anterior, para poder aceptarla o conservar la que había."""
    kind = (request.args.get('kind') or '').strip().upper()
    bid_raw = (request.args.get('bid') or '').strip()
    parsed_sem = _parse_semester_key((request.args.get('s') or '').strip())
    if kind not in ('ARTIST', 'PROMOTER') or not parsed_sem:
        return jsonify({'ok': False, 'message': 'Datos inválidos.'}), 400
    sem_year, sem_half = parsed_sem
    sem_start, _sem_end = _semester_range(sem_year, sem_half)
    try:
        bid = uuid.UUID(bid_raw)
    except Exception:
        return jsonify({'ok': False, 'message': 'Beneficiario inválido.'}), 400
    with get_db() as session_db:
        rec = _royalty_liquidation_record(session_db, kind, bid, sem_start)
        anterior = _royalty_frozen_beneficiary(rec)
        try:
            nueva, _s, _e, _b = _get_royalty_liquidation_beneficiary_data(
                session_db, kind, bid, sem_year, sem_half, apply_frozen=False)
        except Exception:
            return jsonify({'ok': False, 'message': 'No hay datos de royalties para este periodo.'}), 404
        if not anterior:
            return jsonify({'ok': True, 'first_time': True,
                            'nueva': {'total': format_eur(_money_or_zero(nueva.get('total_amount'))), 'lineas': len(nueva.get('items') or [])}})

        def _idx(datos):
            fuera = {}
            for it in (datos.get('items') or []):
                if isinstance(it, dict):
                    fuera[str(it.get('id') or it.get('title') or '')] = it
            return fuera
        ant_idx, nue_idx = _idx(anterior), _idx(nueva)
        filas = []
        for clave in sorted(set(ant_idx) | set(nue_idx)):
            a, n = ant_idx.get(clave), nue_idx.get(clave)
            imp_a = _money_or_zero((a or {}).get('amount'))
            imp_n = _money_or_zero((n or {}).get('amount'))
            if a is not None and n is not None and imp_a == imp_n:
                continue                                   # sin cambios: no se enseña
            filas.append({
                'titulo': ((n or a) or {}).get('title') or clave,
                'antes': (format_eur(imp_a) if a is not None else '—'),
                'ahora': (format_eur(imp_n) if n is not None else '—'),
                'estado': ('nueva' if a is None else ('quitada' if n is None else 'cambia')),
            })
        return jsonify({
            'ok': True,
            'first_time': False,
            'anterior': {'total': format_eur(_money_or_zero(anterior.get('total_amount'))),
                         'generada': _format_madrid_datetime_label(getattr(rec, 'generated_at', None)),
                         'lineas': len(anterior.get('items') or [])},
            'nueva': {'total': format_eur(_money_or_zero(nueva.get('total_amount'))),
                      'lineas': len(nueva.get('items') or [])},
            'cambios': filas[:60],
            'sin_cambios': not filas,
        })


@app.get("/discografica/royalties/liquidacion/info")
@admin_required
def discografica_royalties_liquidation_info():
    kind = (request.args.get('kind') or '').strip().upper()
    bid_raw = (request.args.get('bid') or '').strip()
    sem_key = (request.args.get('s') or '').strip()

    if kind not in ('ARTIST', 'PROMOTER'):
        return jsonify({'ok': False, 'message': 'Beneficiario inválido.'}), 400
    parsed_sem = _parse_semester_key(sem_key)
    if not parsed_sem:
        return jsonify({'ok': False, 'message': 'Semestre inválido.'}), 400
    sem_year, sem_half = parsed_sem
    sem_start, _sem_end = _semester_range(sem_year, sem_half)

    try:
        beneficiary_uuid = uuid.UUID(bid_raw)
    except Exception:
        return jsonify({'ok': False, 'message': 'Beneficiario inválido.'}), 400

    with get_db() as session_db:
        rec = _royalty_liquidation_record(session_db, kind, beneficiary_uuid, sem_start)
        if not rec:
            return jsonify({'ok': True, 'has_info': False})
        # Trazabilidad COMPLETA de esos royalties: cuándo se generó (y su PDF), cuándo y a quién se
        # envió, cuándo llegó la factura (con enlace para verla) y cuándo se pagó.
        factura = None
        inv_id = getattr(rec, 'invoice_id', None)
        if inv_id:
            inv = session_db.get(SupplierInvoice, inv_id)
            if inv is not None:
                factura = {
                    'url': (inv.file_url or ''),
                    'name': (inv.original_name or 'Factura'),
                    'number': (inv.invoice_number or ''),
                    'status': (inv.status or ''),
                    'uploaded_at_label': _format_madrid_datetime_label(getattr(rec, 'invoice_uploaded_at', None) or inv.created_at),
                }
        live = None
        try:
            live, _s2, _e2, _b2 = _get_royalty_liquidation_beneficiary_data(
                session_db, kind, beneficiary_uuid, sem_year, sem_half, apply_frozen=False)
        except Exception:
            live = None
        # Quién hizo cada paso (del historial), para enseñarlo en su bloque.
        quien = {}
        for ev in (getattr(rec, 'history', None) or []):
            if isinstance(ev, dict) and ev.get('kind') and ev.get('by'):
                quien[str(ev['kind']).upper()] = ev['by']
        veces_generada = sum(1 for ev in (getattr(rec, 'history', None) or [])
                             if isinstance(ev, dict) and str(ev.get('kind') or '').upper() in ('GENERATED', 'REGENERATED'))
        return jsonify({
            'ok': True,
            'has_info': True,
            'status': (rec.status or 'PENDING'),
            'status_label': _royalty_status_meta(rec.status)[0],
            'generated_at_label': _format_madrid_datetime_label(getattr(rec, 'generated_at', None)),
            'generated_pdf_url': (getattr(rec, 'snapshot_pdf_url', None) or '').strip(),
            'is_generated': bool(_royalty_frozen_beneficiary(rec)),
            'needs_regeneration': bool(live and _royalty_needs_regeneration(rec, live)),
            'total': (format_eur(_money_or_zero((_royalty_frozen_beneficiary(rec) or {}).get('total_amount')))
                      if (_royalty_frozen_beneficiary(rec) or {}).get('total_amount') not in (None, '') else ''),
            'sent_at_label': _format_madrid_datetime_label(getattr(rec, 'last_sent_at', None)),
            'sent_to': list(getattr(rec, 'last_sent_to', None) or []),
            'pdf_url': (getattr(rec, 'last_sent_pdf_url', None) or '').strip(),
            'invoice': factura,
            'paid_at_label': _format_madrid_datetime_label(getattr(rec, 'paid_at', None)),
            'generated_by': quien.get('REGENERATED') or quien.get('GENERATED') or '',
            'generated_times': veces_generada,
            'sent_by': quien.get('SENT') or '',
            'paid_by': quien.get('PAID') or '',
            'timeline': _royalty_timeline(rec),
        })


@app.get("/liquidacion/<token>", endpoint="public_royalty_liquidation_view")
def public_royalty_liquidation_view(token):
    """Landing pública de una liquidación de royalties: la muestra tal cual el PDF y abajo el botón
    de SUBIR FACTURA (mismo proceso de facturación, con el logo y los datos de la empresa del
    grupo). Al subirla queda vinculada a la liquidación y pasa a «facturada»."""
    payload = _parse_public_royalty_liquidation_token(token)
    if not payload:
        abort(404)
    kind = (payload.get("kind") or "").strip().upper()
    bid_raw = (payload.get("bid") or "").strip()
    parsed_sem = _parse_semester_key((payload.get("s") or "").strip())
    if kind not in ("ARTIST", "PROMOTER") or not bid_raw or not parsed_sem:
        abort(404)
    sem_year, sem_half = parsed_sem
    sem_start, sem_end = _semester_range(sem_year, sem_half)
    with get_db() as session_db:
        beneficiary_uuid = to_uuid(bid_raw)
        if not beneficiary_uuid:
            abort(404)
        rec = _royalty_liquidation_record(session_db, kind, beneficiary_uuid, sem_start)
        # ⚠️ LO QUE SE LE ENVIÓ, y SIN recalcular nada: si la liquidación está generada se enseña su
        # congelado tal cual. El cálculo en vivo solo se hace si no hay nada congelado; antes se
        # calculaba siempre primero, así que si los ingresos habían cambiado (o ya no existían) el
        # enlace enseñaba otros importes o daba «no hay datos».
        beneficiary, _esta_congelada = _royalty_effective_beneficiary(
            session_db, rec, kind, beneficiary_uuid, sem_year, sem_half)
        if not beneficiary:
            abort(404)
        # Las liquidaciones de royalties se facturan A NOMBRE DE PIES (el sello), no de la primera
        # empresa del grupo por orden alfabético (que era 33 Producciones).
        company = None
        try:
            company = _pies_group_company(session_db)
        except Exception:
            company = None
        # El proveedor de la factura: el propio beneficiario si es un tercero.
        provider = session_db.get(Promoter, beneficiary_uuid) if kind == "PROMOTER" else None
        invoices = (session_db.query(SupplierInvoice)
                    .filter(SupplierInvoice.royalty_liquidation_id == (rec.id if rec else None))
                    .order_by(SupplierInvoice.created_at.desc()).all()) if rec else []
        return render_template(
            "public_royalty_liquidation.html",
            token=token,
            beneficiary=beneficiary,
            # El mismo cálculo que en la validación y en el pago: base + IVA.
            invoice_totals=_royalty_invoice_totals(beneficiary),
            # ¿Lo que se ve es lo CONGELADO? Si la liquidación existe y no lo está, se dice, para que
            # nadie dé por bueno un importe que todavía puede moverse.
            is_frozen=bool(_esta_congelada),
            generated_at_label=_format_madrid_datetime_label(getattr(rec, "generated_at", None)),
            period_label=_royalty_liquidation_period_label_from_dates(sem_start, sem_end),
            liquidation=rec,
            company=company,
            provider=provider,
            provider_payload=(_billing_profile_payload(session_db, provider) if provider else None),
            invoices=invoices,
            pdf_url=(_external_url_for("public_royalty_liquidation_pdf") + f"?token={quote_plus(token)}"),
            cert_docs=INVOICE_CERT_DOCS,
        )


def _royalty_pending_buckets(session_db, sem_start, sem_end, statuses=("GENERATED",)) -> list:
    """Beneficiarios del semestre cuya liquidación está en uno de esos estados (por defecto, las
    GENERADAS que todavía no se han enviado)."""
    payload = _build_royalty_beneficiaries(session_db, sem_start, sem_end)
    want = {str(x).upper() for x in statuses}
    out = []
    for bucket in list(payload.get("artists") or []) + list(payload.get("others") or []):
        st = (bucket.get("liquidation_status") or "PENDING").upper()
        if st in want:
            out.append(bucket)
    return out


