@app.route("/ids-plataforma/<token>", methods=["GET", "POST"], endpoint="public_song_platform_ids")
def public_song_platform_ids(token):
    """Página pública donde el ARTISTA sube los IDs de plataforma que se le han pedido."""
    session_db = db()
    try:
        peticion = (session_db.query(SongPlatformIdRequest)
                    .filter(SongPlatformIdRequest.token == (token or "").strip()).first())
        if peticion is None:
            abort(404)
        cancion = session_db.get(Song, peticion.song_id)
        if cancion is None:
            abort(404)
        artista = _song_primary_artist(session_db, cancion)
        estado = _song_platform_ids(session_db, cancion.id)
        pedidas = [p for p in (peticion.platforms or [])]
        filas = [f for f in estado["rows"] if f["platform"] in pedidas] or estado["rows"]
        if request.method == "POST":
            subidas = 0
            for clave in pedidas:
                fs = request.files.get("file_%s" % clave)
                if not (fs and getattr(fs, "filename", "")):
                    continue
                fila = (session_db.query(SongPlatformId)
                        .filter(SongPlatformId.song_id == cancion.id,
                                SongPlatformId.platform == clave).first())
                if fila is None:
                    fila = SongPlatformId(song_id=cancion.id, platform=clave,
                                          label=SONG_PLATFORM_ID_LABELS.get(clave, clave),
                                          project_id=peticion.project_id)
                    session_db.add(fila)
                    session_db.flush()
                try:
                    fila.file_url = upload_file(fs, "song_platform_ids")
                    fila.file_name = fs.filename
                    fila.not_needed = False
                    fila.uploaded_at = _now_madrid()
                    fila.uploaded_by_nick = "artista"
                    subidas += 1
                except Exception as exc:
                    app.logger.exception("[ids] fallo al subir")
                    flash("No se pudo subir el de %s: %s"
                          % (SONG_PLATFORM_ID_LABELS.get(clave, clave), exc), "warning")
            if subidas:
                nuevo = _song_platform_ids(session_db, cancion.id)
                if all(f["done"] for f in nuevo["rows"] if f["platform"] in pedidas):
                    peticion.status = "ENTREGADA"
                    peticion.submitted_at = _now_madrid()
                # Aquí no hay proyecto a mano (la petición es de la CANCIÓN): se avisa a quien del
                # sello lleva a su artista y, si no consta nadie, a Registros.
                _proyecto = (session_db.get(DiscoProject, peticion.project_id)
                             if peticion.project_id else None)
                _destino = (_disco_project_owner_ids(session_db, _proyecto) if _proyecto is not None
                            else (_pitch_sello_user_ids(session_db, getattr(artista, "id", None))
                                  or _registros_user_ids(session_db)))
                _notify_users(session_db, _destino, "DISCOGRAFICA",
                              "IDs subidos: %s" % (cancion.title or "canción"),
                              "%d ID(s) de plataforma." % subidas,
                              url=url_for("discografica_song_detail", song_id=cancion.id,
                                          tab="materiales"),
                              ref_type="SONG_IDS", ref_id=str(cancion.id))
            session_db.commit()
            flash("Subidos %d ID(s). ¡Gracias!" % subidas, "success")
            return redirect(url_for("public_song_platform_ids", token=token))
        return render_template("public_song_platform_ids.html", song=cancion, artist=artista,
                               rows=filas, req=peticion, brand=_pies_brand_assets(session_db))
    finally:
        session_db.close()


# =========================================================
# PLAN DE LANZAMIENTO · la tarea clave del proyecto
# ---------------------------------------------------------
# Vive en su propia pestaña, con la estética de las BOLSAS (una sección por bocadillo):
#   Estrategia · Acciones · Marketing · Promoción · Contenidos · Cronograma
# ⚠️ No se da por hecho hasta que **dirección Y sello** dan el OK. Y cuando está aprobado aparece la
# tarea de **activar los recordatorios de publicación**.
# =========================================================
DISCO_PLAN_SECTIONS = (
    ("estrategia", "Estrategia", "fa-chess"),
    ("acciones", "Acciones", "fa-list-check"),
    ("marketing", "Marketing", "fa-bullhorn"),
    ("promocion", "Promoción", "fa-microphone-lines"),
    ("contenidos", "Contenidos", "fa-photo-film"),
    ("cronograma", "Cronograma", "fa-calendar-days"),
)
DISCO_PLAN_ACTION_DATE_KINDS = (
    ("DATE", "Un día", "fa-calendar-day"),
    ("RANGE", "Una franja", "fa-calendar-week"),
    ("NONE", "Sin fecha concreta", "fa-calendar-xmark"),
)
# Las REDES donde se publica un contenido (con su logo).
DISCO_CONTENT_NETWORKS = (
    ("IG_POST", "Instagram · Post", "fa-instagram"),
    ("IG_STORY", "Instagram · Historia", "fa-instagram"),
    ("IG_SHARED", "Instagram · Post compartido", "fa-instagram"),
    ("TIKTOK", "TikTok", "fa-tiktok"),
    ("FACEBOOK", "Facebook", "fa-facebook"),
    ("X", "X", "fa-x-twitter"),
    ("YOUTUBE", "YouTube", "fa-youtube"),
    ("YT_SHORTS", "YouTube Shorts", "fa-youtube"),
)
DISCO_CONTENT_NETWORK_LABELS = {k: l for k, l, _i in DISCO_CONTENT_NETWORKS}
DISCO_PLAN_REMINDER_DEFAULT_MINUTES = 10


def _disco_plan(session_db, project, *, create: bool = False):
    """El plan de lanzamiento del proyecto (uno por proyecto)."""
    if project is None:
        return None
    fila = (session_db.query(DiscoReleasePlan)
            .filter(DiscoReleasePlan.project_id == project.id).first())
    if fila is None and create:
        fila = DiscoReleasePlan(project_id=project.id,
                               reminder_minutes=DISCO_PLAN_REMINDER_DEFAULT_MINUTES,
                               public_token=_uuid_token())
        session_db.add(fila)
        session_db.flush()
    return fila


def _disco_plan_content_rows(plan) -> list[dict]:
    """Los CONTENIDOS del plan, listos para pintar (miniatura, cuándo, copy, menciones, redes)."""
    salida = []
    for c in (getattr(plan, "contents", None) or []):
        cuando = c.publish_at
        salida.append({
            "id": str(c.id), "title": (c.title or "Contenido"),
            "description": (c.description or ""),
            "file_url": (c.file_url or ""), "file_name": (c.file_name or ""),
            "thumb_url": (c.thumb_url or c.file_url or ""),
            "uploaded": bool(c.file_url),
            # PEDIDO A DISEÑO: se ve rayado en amarillo y se puede programar igual.
            "design_asked": bool(getattr(c, "design_requested_at", None) and not c.file_url),
            "design_asked_label": (c.design_requested_at.astimezone(TZ_MADRID).strftime("%d/%m/%Y")
                                   if getattr(c, "design_requested_at", None) else ""),
            "design_notes": (getattr(c, "design_notes", None) or ""),
            # Se arrastra al CRONOGRAMA para ponerle día (subido o no).
            "can_drag": True,
            "publish_at": cuando,
            "date_value": (cuando.astimezone(TZ_MADRID).strftime("%Y-%m-%d") if cuando else ""),
            "time_value": (cuando.astimezone(TZ_MADRID).strftime("%H:%M") if cuando else ""),
            "when_label": (cuando.astimezone(TZ_MADRID).strftime("%d/%m/%Y %H:%M") if cuando else "Sin fecha"),
            "copy_text": (c.copy_text or ""),
            "mentions": list(c.mentions or []),
            "hashtags": list(c.hashtags or []),
            "networks": list(c.networks or []),
            "networks_label": " · ".join([DISCO_CONTENT_NETWORK_LABELS.get(x, x)
                                          for x in (c.networks or [])]),
            "active": bool(c.active),
            "reminder_at": c.reminder_at,
        })
    return salida


def _disco_plan_missing(estado: dict) -> list[str]:
    """QUÉ LE FALTA AL PLAN para poder pedirle el OK a dirección.

    ⚠️⚠️ El OK **no se pide con el plan a medias**: dirección y el sello repasan un plan entero, así
    que hasta que lo esté, el botón sale desactivado diciendo qué falta y el endpoint lo rebota
    (esconder el botón no basta). Punto único: lo usan la pantalla, la tarea del proyecto y
    `disco_plan_review`.
    Se exige lo que ES el plan: la estrategia, al menos una acción, al menos un contenido y que todo
    lleve FECHA (sin fechas no hay cronograma que aprobar). El marketing y la promoción NO se exigen:
    son de otros departamentos y un lanzamiento pequeño puede no llevar campaña de pago.
    """
    estado = estado or {}
    if not estado.get("exists"):
        return ["el plan está vacío"]
    faltan = []
    if not (estado.get("strategy_text") or "").strip():
        faltan.append("la estrategia")
    acciones = estado.get("actions") or []
    if not acciones:
        faltan.append("al menos una acción")
    elif any(not (a.get("has_date")) for a in acciones):
        faltan.append("la fecha de todas las acciones")
    contenidos = estado.get("contents") or []
    if not contenidos:
        faltan.append("al menos un contenido")
    elif any(not c.get("publish_at") for c in contenidos):
        # ⚠️ `when_label` pone «Sin fecha» cuando no la hay: comprobarlo por el texto no detectaba nada.
        faltan.append("el día y la hora de todas las publicaciones")
    return faltan


def _disco_plan_marketing_subject(session_db, project, release=None) -> dict:
    """De qué va el marketing del plan: el LANZAMIENTO del proyecto y, si aún no existe, el ARTISTA.

    Es lo que rellena el pop-up de «Añadir acción de marketing» del plan, así que la campaña se crea
    ya colgada de la misma canción o del mismo álbum que se ve en la sección Marketing (el mismo
    dato: lo que se toque en un sitio se ve en el otro)."""
    if release is None:
        release = _disco_project_release(session_db, project)
    artista = None
    try:
        artista = session_db.get(Artist, project.artist_id) if getattr(project, "artist_id", None) else None
    except Exception:
        artista = None
    artist_ids = [str(artista.id)] if artista is not None else []
    if release and release.get("id"):
        return {
            "type": ("ALBUM" if release.get("kind") == "ALBUM" else "SONG"),
            "id": str(release["id"]),
            "title": (release.get("title") or "El lanzamiento"),
            "subtitle": (getattr(artista, "name", None) or ""),
            "cover_url": (release.get("cover_url") or ""),
            "artist_ids": artist_ids,
            "kind_label": ("Álbum / EP" if release.get("kind") == "ALBUM" else "Canción"),
        }
    if artista is not None:
        return {"type": "ARTIST", "id": str(artista.id),
                "title": (artista.name or "El artista"), "subtitle": "",
                "cover_url": (getattr(artista, "photo_url", None) or ""),
                "artist_ids": artist_ids, "kind_label": "Artista"}
    return {}


def _disco_plan_state(session_db, project) -> dict:
    """Todo lo que necesita la pestaña del plan (y su tarea): secciones, aprobación y recordatorios."""
    plan = _disco_plan(session_db, project)
    if plan is None:
        return {"plan": None, "exists": False, "approved": False, "actions": [], "contents": [],
                "marketing": [], "promos": [], "subject": {}, "total_cost": 0, "ok_direccion": False,
                "missing": ["el plan está vacío"], "complete": False,
                "missing_label": "el plan está vacío",
                "ok_sello": False, "reminders": False, "public_url": ""}
    acciones = []
    total = Decimal("0")
    for a in (plan.actions or []):
        importe = _money_or_zero(a.amount)
        if (a.cost_mode or "").upper() == "COST":
            total += importe
        acciones.append({
            "id": str(a.id), "title": (a.title or ""), "description": (a.description or ""),
            "cost_mode": (a.cost_mode or ""), "amount": (a.amount if a.amount is not None else ""),
            "amount_label": (format_eur(a.amount) if a.amount is not None else ""),
            "date_kind": (a.date_kind or "NONE"),
            "start_date": (a.start_date.isoformat() if a.start_date else ""),
            "end_date": (a.end_date.isoformat() if a.end_date else ""),
            "when_label": (("%s → %s" % (a.start_date.strftime("%d/%m/%Y"),
                                          a.end_date.strftime("%d/%m/%Y")))
                           if (a.date_kind or "").upper() == "RANGE" and a.start_date and a.end_date
                           else (a.start_date.strftime("%d/%m/%Y") if a.start_date else "Sin fecha")),
            # ¿Tiene fecha? Lo usa `_disco_plan_missing`: sin fechas no hay cronograma que aprobar.
            "has_date": bool(a.start_date),
        })
    # MARKETING y PROMOCIÓN: lo que ya está vinculado al LANZAMIENTO (su canción o su álbum), que es
    # lo mismo que se ve en Marketing y en Promoción. No se duplica nada: es el mismo dato.
    release = _disco_project_release(session_db, project)
    tipo = ("ALBUM" if release.get("kind") == "ALBUM" else "SONG") if release else ""
    marketing, promos = [], []
    if release and release.get("id"):
        try:
            marketing = _promotion_entity_promotions(session_db, tipo, release["id"])
            marketing = [_promotion_display_promotion(r) for r in marketing]
        except Exception:
            app.logger.exception("[plan] no se pudo leer el marketing del lanzamiento")
        try:
            promos = _promo_rows_for_subject(session_db, tipo, release["id"])
        except Exception:
            app.logger.exception("[plan] no se pudieron leer las promociones")
    contenidos = _disco_plan_content_rows(plan)
    estado = {
        "plan": plan, "exists": True,
        "strategy_text": (plan.strategy_text or ""),
        "actions": acciones,
        "total_cost": total,
        "total_cost_label": format_eur(total),
        "marketing": marketing,
        # DE QUÉ es el marketing: el lanzamiento del proyecto (su canción o su álbum) y, mientras no
        # exista, el propio ARTISTA — así la campaña se puede crear desde aquí sin esperar a nada, y
        # es el MISMO dato que se ve en la sección Marketing.
        "subject": _disco_plan_marketing_subject(session_db, project, release),
        "promos": promos,
        "contents": contenidos,
        "contents_uploaded": len([c for c in contenidos if c["uploaded"]]),
        "ok_direccion": bool(plan.ok_direccion_at),
        "ok_direccion_by": (plan.ok_direccion_by_nick or ""),
        "ok_sello": bool(plan.ok_sello_at),
        "ok_sello_by": (plan.ok_sello_by_nick or ""),
        "approved": bool(plan.ok_direccion_at and plan.ok_sello_at),
        "reminders": bool(plan.reminders_enabled),
        "reminder_minutes": int(plan.reminder_minutes or DISCO_PLAN_REMINDER_DEFAULT_MINUTES),
        "reminder_email": bool(plan.reminder_email),
        "reminder_sms": bool(plan.reminder_sms),
        "reminder_recipients": list(plan.reminder_recipients or []),
        "public_url": (_external_url_for("public_disco_plan", token=plan.public_token)
                       if plan.public_token else ""),
        # EL PLAN DE PROMOCIÓN que se le pide a promoción (queda incluido en este).
        **_disco_plan_extra_state(session_db, project, plan),
    }
    # ⚠️ QUÉ LE FALTA para poder pedir el OK: se calcula UNA vez y lo leen la pantalla, la tarea del
    # proyecto y el propio endpoint (punto único `_disco_plan_missing`).
    estado["missing"] = _disco_plan_missing(estado)
    estado["complete"] = not estado["missing"]
    estado["missing_label"] = " · ".join(estado["missing"])
    return estado


def _disco_plan_extra_state(session_db, project, plan) -> dict:
    """Lo que se le añade al plan y no vive en su tabla: el **plan de promoción** que se le pide a
    promoción, el **rechazo** de la aprobación y el **aviso al artista** (con sus alertas)."""
    fila = _disco_prod(project)
    promo = dict(fila.get("plan_promo") or {})
    revision = dict(fila.get("plan_review") or {})
    aviso = dict(fila.get("plan_notice") or {})
    # Cuándo EMPIEZA el plan: la primera fecha de sus acciones o contenidos (y si no, el lanzamiento).
    fechas = [a.start_date for a in (plan.actions or []) if getattr(a, "start_date", None)]
    for c in (plan.contents or []):
        if getattr(c, "publish_at", None):
            fechas.append(c.publish_at.date() if hasattr(c.publish_at, "date") else c.publish_at)
    inicio = min(fechas) if fechas else getattr(project, "release_date", None)
    dias = ((inicio - today_local()).days if inicio else None)
    return {
        "promo_asked": bool(promo.get("asked_at")),
        "promo_asked_label": _iso_date_label(promo.get("asked_at")),
        "promo_note": (promo.get("note") or ""),
        "promo_goals": (promo.get("goals") or ""),
        "promo_file_url": (promo.get("file_url") or ""),
        "promo_file_name": (promo.get("file_name") or ""),
        "promo_done": bool(promo.get("file_url")),
        "promo_done_by": (promo.get("done_by") or ""),
        "rejected": bool(revision.get("rejected_at")),
        "rejected_note": (revision.get("note") or ""),
        "rejected_by": (revision.get("by") or ""),
        "rejected_label": _iso_date_label(revision.get("rejected_at")),
        "review_asked": bool(revision.get("asked_at")),
        "notice_sent": bool(aviso.get("sent_at")),
        "notice_label": _iso_date_label(aviso.get("sent_at")),
        "notice_by": (aviso.get("by") or ""),
        "starts_on": inicio,
        "starts_label": (inicio.strftime("%d/%m/%Y") if inicio else ""),
        "days_to_start": dias,
    }


def _disco_plan_agenda(session_db, project, plan_state) -> dict:
    """El CRONOGRAMA: el calendario de la casa con TODO lo del plan (el lanzamiento, las acciones,
    las promociones, el marketing y cada contenido con su hora).

    ⚠️ Se reutiliza el componente de agenda (`_agenda_calendar.html`) con un payload propio y **sin
    `artist_id`**: así las flechas se mueven dentro de lo cargado y no se le piden ventanas al
    servidor (el cronograma son SUS fechas, no la agenda del artista).
    ⚠️ Y **sin `item_id`** en nada que no sea un ítem de agenda de verdad: ese campo activa en el
    lateral una papelera que borraría otra cosa."""
    hoy = today_local()
    actividades = []
    fechas = [hoy]

    def añade(dia, kind, titulo, subtitulo="", imagen="", extra=None):
        if not dia:
            return
        fechas.append(dia)
        fila = {"date": dia.isoformat(), "end_date": dia.isoformat(), "kind": kind,
                "title": titulo, "subtitle": subtitulo, "artist_id": "plan",
                "artist_name": _disco_project_title(project)}
        if imagen:
            fila["artist_photo"] = imagen
        if extra:
            fila.update(extra)
        actividades.append(fila)

    release = _disco_project_release(session_db, project)
    portada = (release.get("cover_url") or "") if release else ""
    if getattr(project, "release_date", None):
        añade(project.release_date, "lanzamiento", "Lanzamiento · %s" % _disco_project_title(project),
              "Fecha de publicación", portada)
    for a in (plan_state.get("actions") or []):
        dia = _parse_iso_date_safe(a.get("start_date"))
        if dia:
            añade(dia, "otro", a.get("title") or "Acción",
                  " · ".join([x for x in [a.get("amount_label") or "", a.get("description") or ""] if x])[:90])
    for m in (plan_state.get("marketing") or []):
        dia = None
        for clave in ("start_date", "starts_on", "date"):
            dia = dia or _parse_iso_date_safe(m.get(clave) if isinstance(m, dict) else None)
        if dia:
            añade(dia, "promocion", (m.get("title") if isinstance(m, dict) else "") or "Marketing",
                  "Marketing")
    for p in (plan_state.get("promos") or []):
        dia = _parse_iso_date_safe(p.get("start_date") or p.get("date")) if isinstance(p, dict) else None
        if dia:
            añade(dia, "promocion", (p.get("title") if isinstance(p, dict) else "") or "Promoción",
                  "Promoción")
    for c in (plan_state.get("contents") or []):
        cuando = c.get("publish_at")
        if not cuando:
            continue
        dia = cuando.astimezone(TZ_MADRID).date()
        añade(dia, "contenido", c.get("title") or "Contenido",
              " · ".join([x for x in [cuando.astimezone(TZ_MADRID).strftime("%H:%M"),
                                      c.get("networks_label") or ""] if x]),
              c.get("thumb_url") or portada,
              # ⚠️ `move_url` (y NO `item_id`): con él el calendario deja ARRASTRARLO y lo guarda en
              # ESE endpoint. Poner `item_id` en algo que no es un ítem de agenda haría que el
              # lateral pintara una papelera que borraría otra cosa.
              {"move_url": url_for("disco_plan_content_move", project_id=project.id,
                                   content_id=c.get("id")),
               "content_id": c.get("id")})
    ini, fin = min(fechas), max(fechas)
    # ⚠️⚠️ Los TIPOS hay que emitirlos: el calendario filtra con `activeKinds`, que sale de esta
    # lista, así que con `kinds: []` **no se pinta nada** (bug real: el cronograma salía vacío).
    usados = []
    for a in actividades:
        if a["kind"] not in usados:
            usados.append(a["kind"])
        meta = AGENDA_KIND_META.get(a["kind"], {})
        a.setdefault("icon", meta.get("icon", "fa-circle"))
        a.setdefault("kind_color", meta.get("color", "#6c757d"))
        a.setdefault("kind_label", meta.get("label", ""))
        a.setdefault("artist_ids", [])
        a.setdefault("artist_color", AGENDA_MINE_COLOR)
        a.setdefault("status_label", "")
        a.setdefault("status_class", "")
        a.setdefault("cover_url", "")
        a.setdefault("url", "")
    return {"activities": actividades, "artists": [],
            "kinds": [{"key": k, "label": AGENDA_KIND_META.get(k, {}).get("label", k),
                       "icon": AGENDA_KIND_META.get(k, {}).get("icon", "fa-circle"),
                       "color": AGENDA_KIND_META.get(k, {}).get("color", "#6c757d")}
                      for k in AGENDA_KIND_ORDER if k in usados],
            "holidays": [],
            "today": hoy.isoformat(),
            "start": (ini - timedelta(days=ini.weekday())).isoformat(),
            "end": (fin + timedelta(days=7)).isoformat()}


def _disco_plan_row_or_none(session_db, project, model, row_id):
    """Una fila del plan (acción o contenido) **de este proyecto**.

    ⚠️ Sin esta comprobación, el id de otro proyecto se aceptaba tal cual: quien puede editar
    discográfica podía tocar (o borrar) lo de un proyecto que no está mirando."""
    try:
        fila = session_db.get(model, to_uuid(row_id)) if row_id else None
    except Exception:
        return None
    if fila is None or project is None:
        return None
    plan = session_db.get(DiscoReleasePlan, fila.plan_id)
    if plan is None or str(plan.project_id) != str(project.id):
        return None
    return fila


@app.post("/discografica/proyectos/<project_id>/plan", endpoint="disco_plan_save")
@admin_required
def disco_plan_save(project_id):
    """Guarda la ESTRATEGIA del plan (el resto de secciones tienen su propio endpoint)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        plan = _disco_plan(session_db, project, create=True)
        plan.strategy_text = (request.form.get("strategy_text") or "").strip() or None
        plan.updated_at = _now_madrid()
        session_db.commit()
        flash("Estrategia guardada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/plan/accion", endpoint="disco_plan_action_save")
@admin_required
def disco_plan_action_save(project_id):
    """Añade o edita una ACCIÓN del plan. Si tiene coste, el importe se lleva a la BOLSA del proyecto
    (y si se cambia aquí, se actualiza allí)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        plan = _disco_plan(session_db, project, create=True)
        f = request.form
        aid = (f.get("action_id") or "").strip()
        fila = _disco_plan_row_or_none(session_db, project, DiscoReleasePlanAction, aid)
        if fila is None:
            n = len(plan.actions or [])
            fila = DiscoReleasePlanAction(plan_id=plan.id, position=n)
            session_db.add(fila)
        titulo = (f.get("title") or "").strip()
        if not titulo:
            flash("Ponle título a la acción.", "warning")
            return redirect(destino)
        fila.title = titulo[:250]
        fila.description = (f.get("description") or "").strip() or None
        modo = (f.get("cost_mode") or "NONE").strip().upper()
        fila.cost_mode = ("COST" if modo == "COST" else "NONE")
        fila.amount = (_parse_optional_decimal(f.get("amount")) if fila.cost_mode == "COST" else None)
        kind = (f.get("date_kind") or "NONE").strip().upper()
        fila.date_kind = kind if kind in ("DATE", "RANGE", "NONE") else "NONE"
        fila.start_date = (parse_optional_date(f.get("start_date")) if fila.date_kind != "NONE" else None)
        fila.end_date = (parse_optional_date(f.get("end_date")) if fila.date_kind == "RANGE" else None)
        session_db.flush()
        _disco_plan_action_sync_bag(session_db, project, fila)
        session_db.commit()
        flash("Acción guardada.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo guardar la acción")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


def _disco_artwork_sync_bag(session_db, project, fila) -> None:
    """El COSTE DE LA PORTADA va a la BOLSA del proyecto, en su categoría, y se mantiene al día.

    Es la misma regla que las acciones del plan: **una tarea con gasto se ve en la bolsa** sin que
    nadie lo apunte dos veces. Si deja de tener coste, el gasto se retira."""
    try:
        con_coste = ((fila.cost_mode or "").upper() == "AMOUNT" and fila.amount is not None)
        if not con_coste:
            if getattr(fila, "bag_expense_id", None):
                gasto = session_db.get(BagExpense, fila.bag_expense_id)
                if gasto is not None:
                    session_db.delete(gasto)
                fila.bag_expense_id = None
            return
        bag = _ensure_project_bag(session_db, project)
        if bag is None:
            return
        gasto = (session_db.get(BagExpense, fila.bag_expense_id)
                 if getattr(fila, "bag_expense_id", None) else None)
        if gasto is None:
            gasto = BagExpense(bag_id=bag.id, category="MARKETING",
                               created_by_nick=((_current_user_state() or {}).get("nick") or None))
            session_db.add(gasto)
            session_db.flush()
            fila.bag_expense_id = gasto.id
        gasto.concept = "Portada · %s" % (_disco_artwork_who_name(session_db, fila) or "diseño")
        gasto.amount_net = fila.amount
        gasto.amount_gross = fila.amount
    except Exception:
        app.logger.exception("[portada] no se pudo sincronizar el gasto de la portada")


def _disco_plan_action_sync_bag(session_db, project, fila) -> None:
    """El coste de una acción del plan va a la BOLSA del proyecto y se mantiene al día.

    ⚠️ Es el MISMO dinero visto desde dos sitios: si se cambia aquí, se cambia el gasto; si la acción
    deja de tener coste, el gasto se retira."""
    try:
        if (fila.cost_mode or "").upper() != "COST" or fila.amount is None:
            if fila.bag_expense_id:
                gasto = session_db.get(BagExpense, fila.bag_expense_id)
                if gasto is not None:
                    session_db.delete(gasto)
                fila.bag_expense_id = None
            return
        bag = _ensure_project_bag(session_db, project)
        if bag is None:
            return
        gasto = (session_db.get(BagExpense, fila.bag_expense_id) if fila.bag_expense_id else None)
        if gasto is None:
            gasto = BagExpense(bag_id=bag.id, category="MARKETING",
                               created_by_nick=((_current_user_state() or {}).get("nick") or None))
            session_db.add(gasto)
            session_db.flush()
            fila.bag_expense_id = gasto.id
        gasto.concept = "Plan de lanzamiento · %s" % (fila.title or "acción")
        gasto.amount_net = fila.amount
        gasto.amount_gross = fila.amount
    except Exception:
        app.logger.exception("[plan] no se pudo sincronizar el gasto de la acción")


@app.post("/discografica/proyectos/<project_id>/plan/accion/<action_id>/eliminar",
          endpoint="disco_plan_action_delete")
@admin_required
def disco_plan_action_delete(project_id, action_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    try:
        fila = _disco_plan_row_or_none(session_db, _disco_project_or_404(session_db, project_id),
                                       DiscoReleasePlanAction, action_id)
        if fila is not None:
            if fila.bag_expense_id:
                gasto = session_db.get(BagExpense, fila.bag_expense_id)
                if gasto is not None:
                    session_db.delete(gasto)
            session_db.delete(fila)
            session_db.commit()
            flash("Acción eliminada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo eliminar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("disco_project_detail", project_id=project_id,
                                         tab="lanzamiento")))


def _disco_plan_design_contents(session_db, project) -> list:
    """Los CONTENIDOS del plan que están pedidos a diseño y todavía sin archivo."""
    try:
        plan = (session_db.query(DiscoReleasePlan)
                .filter(DiscoReleasePlan.project_id == project.id).first())
        if plan is None:
            return []
        return (session_db.query(DiscoReleaseContent)
                .filter(DiscoReleaseContent.plan_id == plan.id)
                .filter(DiscoReleaseContent.design_requested_at.isnot(None))
                .filter(func.coalesce(DiscoReleaseContent.file_url, "") == "")
                .order_by(DiscoReleaseContent.publish_at.asc().nullslast()).all())
    except Exception:
        app.logger.exception("[plan] no se pudieron leer los contenidos pedidos a diseño")
        return []


def _disco_plan_design_link(session_db, project, content=None) -> str:
    """El enlace por el que DISEÑO sube lo que se le pide de este proyecto.

    ⚠️ Es el MISMO de las creatividades (`DiscoProjectDesignRequest` → `public_disco_creatives`): no
    se inventa otro sitio para subir lo mismo. Si el proyecto no tiene un encargo abierto, se crea
    uno; su fecha máxima es la de la publicación más próxima que esté pedida."""
    try:
        peticion = (session_db.query(DiscoProjectDesignRequest)
                    .filter(DiscoProjectDesignRequest.project_id == project.id)
                    .filter(func.upper(func.coalesce(DiscoProjectDesignRequest.status, "")) != "ENTREGADA")
                    .order_by(DiscoProjectDesignRequest.requested_at.desc()).first())
        if peticion is None:
            estado = _current_user_state() or {}
            vence = None
            if content is not None and getattr(content, "publish_at", None):
                vence = content.publish_at.astimezone(TZ_MADRID).date()
            peticion = DiscoProjectDesignRequest(
                project_id=project.id, due_date=vence, token=_uuid_token(), status="SOLICITADA",
                requested_by_user_id=_safe_uuid(estado.get("user_id")),
                requested_by_nick=(estado.get("nick") or None))
            session_db.add(peticion)
            session_db.flush()
        elif (content is not None and getattr(content, "publish_at", None)
              and (peticion.due_date is None
                   or content.publish_at.astimezone(TZ_MADRID).date() < peticion.due_date)):
            # La fecha máxima es la de la publicación más próxima de las pedidas.
            peticion.due_date = content.publish_at.astimezone(TZ_MADRID).date()
        return _external_url_for("public_disco_creatives", token=peticion.token)
    except Exception:
        app.logger.exception("[plan] no se pudo preparar el enlace de diseño")
        return ""


@app.post("/discografica/proyectos/<project_id>/plan/contenido", endpoint="disco_plan_content_save")
@admin_required
def disco_plan_content_save(project_id):
    """Añade o edita un CONTENIDO del plan: su archivo, cuándo se publica (con hora), el copy, las
    menciones obligatorias (solo el @), los hashtags y en qué redes va."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        plan = _disco_plan(session_db, project, create=True)
        f = request.form
        cid = (f.get("content_id") or "").strip()
        fila = _disco_plan_row_or_none(session_db, project, DiscoReleaseContent, cid)
        if fila is None:
            fila = DiscoReleaseContent(plan_id=plan.id, position=len(plan.contents or []))
            session_db.add(fila)
        fila.title = ((f.get("title") or "").strip() or "Contenido")[:250]
        fila.description = (f.get("description") or "").strip() or None
        fila.copy_text = (f.get("copy_text") or "").strip() or None
        # Las MENCIONES se guardan con su @ (y solo el @: ni URLs ni nombres largos).
        fila.mentions = [("@" + x.strip().lstrip("@")) for x in
                         (f.get("mentions") or "").replace(",", " ").split() if x.strip().strip("@")]
        fila.hashtags = [("#" + x.strip().lstrip("#")) for x in
                         (f.get("hashtags") or "").replace(",", " ").split() if x.strip().strip("#")]
        fila.networks = [x.strip().upper() for x in f.getlist("networks[]")
                         if x.strip().upper() in DISCO_CONTENT_NETWORK_LABELS]
        antes = fila.publish_at
        dia = parse_optional_date(f.get("publish_date"))
        hora = (f.get("publish_time") or "").strip()
        if dia:
            try:
                hh, mm = [int(x) for x in (hora or "12:00").split(":")[:2]]
            except Exception:
                hh, mm = 12, 0
            fila.publish_at = datetime.combine(dia, dtime(hour=hh, minute=mm), tzinfo=TZ_MADRID)
        elif not cid:
            fila.publish_at = None
        # ⚠️ Si CAMBIA el día o la hora, el recordatorio se reprograma sobre lo de AHORA: si no, un
        # contenido movido no volvería a avisar (o avisaría con la hora vieja).
        if fila.publish_at != antes:
            fila.reminder_at = None
        fs = request.files.get("file")
        if fs and getattr(fs, "filename", ""):
            try:
                fila.file_url = upload_file(fs, "disco_contents")
                fila.file_name = fs.filename
                # Miniatura: si es imagen, la propia imagen.
                if (fs.mimetype or "").startswith("image/"):
                    fila.thumb_url = fila.file_url
            except Exception as exc:
                flash("No se pudo subir el contenido: %s" % exc, "warning")
        fila.active = not _truthy(f.get("inactive"))
        # ¿LO SUBIMOS O SE LO PEDIMOS A DISEÑO? Si se les pide, el contenido se puede programar igual
        # y se queda RAYADO en amarillo hasta que llegue el archivo.
        pedir = (f.get("source") or "US").strip().upper() == "DESIGN"
        if pedir and not fila.file_url:
            estado = _current_user_state() or {}
            nota = (f.get("design_notes") or "").strip() or None
            nuevo_encargo = fila.design_requested_at is None
            fila.design_notes = nota
            if nuevo_encargo:
                fila.design_requested_at = _now_madrid()
                fila.design_requested_by_nick = (estado.get("nick") or estado.get("email") or None)
            session_db.flush()
            if nuevo_encargo:
                enlace = _disco_plan_design_link(session_db, project, fila)
                _notify_users(session_db, _department_user_ids(session_db, "Diseño"), "DISENO",
                              "Contenido por preparar: %s" % _disco_project_title(project),
                              "%s%s" % (fila.title or "Contenido",
                                        (" · %s" % nota) if nota else ""),
                              url=url_for("disco_project_detail", project_id=project.id,
                                          tab="lanzamiento"),
                              ref_type="DISCO_PLAN_CONTENT", ref_id=str(fila.id))
                if enlace:
                    flash(Markup("Pedido a diseño. Suben el archivo aquí: "
                                 "<a href='%s'>%s</a>" % (escape(enlace), escape(enlace))), "info")
        elif fila.file_url and fila.design_requested_at and not fila.design_done_at:
            # Ya está subido: el encargo queda cerrado y su aviso deja de esperar.
            fila.design_done_at = _now_madrid()
            _notify_resolve(session_db, "DISCO_PLAN_CONTENT", str(fila.id))
        elif not pedir and fila.design_requested_at and not fila.file_url:
            # ⚠️ Se DESHACE el encargo: si se vuelve a «lo subimos nosotros», diseño deja de tenerlo
            # pendiente (y su aviso se cierra). Sin esto, el contenido se quedaba «en diseño» para
            # siempre y seguía saliendo en su enlace.
            fila.design_requested_at = None
            fila.design_requested_by_nick = None
            fila.design_done_at = None
            _notify_resolve(session_db, "DISCO_PLAN_CONTENT", str(fila.id))
        session_db.commit()
        flash("Contenido guardado.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo guardar el contenido")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


