@app.post("/discografica/proyectos/<project_id>/plan/contenido/<content_id>/mover",
          endpoint="disco_plan_content_move")
@admin_required
def disco_plan_content_move(project_id, content_id):
    """ARRASTRAR un contenido al cronograma: le pone el DÍA (y la hora, si se dice).

    ⚠️ Arrastrando DENTRO del calendario se conserva la hora que tenía (mover un contenido es
    cambiarle el día, no la hora). Arrastrándolo desde el LISTADO de contenidos —donde puede que
    todavía no tenga fecha— se pregunta **solo la hora** y llega en `time`.
    Responde JSON (lo llama el calendario sin recargar)."""
    if not can_edit_discografica():
        return jsonify({"ok": False, "error": "Sin permisos."}), 403
    session_db = db()
    try:
        fila = _disco_plan_row_or_none(session_db, _disco_project_or_404(session_db, project_id),
                                       DiscoReleaseContent, content_id)
        if fila is None:
            return jsonify({"ok": False, "error": "Ese contenido ya no existe."}), 404
        crudo = (request.form.get("date") or "").strip()
        if not crudo and request.is_json:
            crudo = ((request.get_json(silent=True) or {}).get("date") or "")
        dia = parse_optional_date(crudo)
        if not dia:
            return jsonify({"ok": False, "error": "Falta la fecha."}), 400
        antigua = fila.publish_at
        hora = (antigua.astimezone(TZ_MADRID).time() if antigua else dtime(hour=12, minute=0))
        # La HORA solo se toca si llega: es lo único que se pregunta al soltarlo desde el listado.
        crudo_hora = (request.form.get("time") or "").strip()
        if not crudo_hora and request.is_json:
            crudo_hora = ((request.get_json(silent=True) or {}).get("time") or "")
        if crudo_hora:
            try:
                hh, mm = [int(x) for x in crudo_hora.split(":")[:2]]
                hora = dtime(hour=max(0, min(23, hh)), minute=max(0, min(59, mm)))
            except (TypeError, ValueError):
                pass
        fila.publish_at = datetime.combine(dia, hora, tzinfo=TZ_MADRID)
        # ⚠️ Si se mueve, el recordatorio se recalcula sobre la fecha NUEVA (se borra el enviado).
        fila.reminder_at = None
        session_db.commit()
        return jsonify({"ok": True, "when": fila.publish_at.astimezone(TZ_MADRID).strftime("%d/%m/%Y %H:%M")})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo mover el contenido")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post("/discografica/proyectos/<project_id>/plan/promocion", endpoint="disco_plan_promo_request")
@admin_required
def disco_plan_promo_request(project_id):
    """PEDIRLE A PROMOCIÓN que prepare el plan de promoción (con indicaciones y objetivos).

    Le queda como tarea pendiente hasta que lo sube, y lo que sube queda **dentro** de este plan."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        prod = _disco_prod(project)
        fila = dict(prod.get("plan_promo") or {})
        fila["asked_at"] = _now_madrid().isoformat()
        fila["asked_by"] = ((_current_user_state() or {}).get("nick") or "")
        fila["note"] = (request.form.get("note") or "").strip()
        fila["goals"] = (request.form.get("goals") or "").strip()
        prod["plan_promo"] = fila
        project.production_payload = prod
        cuerpo = " · ".join([x for x in [fila["note"], ("Objetivos: %s" % fila["goals"])
                                        if fila["goals"] else ""] if x])
        _notify_users(session_db, _disco_press_people(session_db, "text"), "TAREA",
                      "Preparar el plan de promoción: %s" % _disco_project_title(project),
                      (cuerpo or "Hay que preparar el plan de promoción del lanzamiento.")[:600],
                      url_for("disco_project_detail", project_id=project.id, tab="lanzamiento"),
                      ref_type="DISCO_PLAN_PROMO", ref_id=str(project.id))
        session_db.commit()
        flash("Se le ha pedido el plan de promoción a promoción.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo pedir el plan de promoción")
        flash("No se pudo pedir: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/plan/promocion/subir", endpoint="disco_plan_promo_upload")
@admin_required
def disco_plan_promo_upload(project_id):
    """PROMOCIÓN sube su plan: queda incluido en el plan de lanzamiento.

    ⚠️ Aquí no se exige `can_edit_discografica()`: lo sube promoción."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        yo = str((_current_user_state() or {}).get("user_id") or "")
        if not (is_master() or can_edit_discografica()
                or yo in _disco_press_people(session_db, "text")):
            return forbid("Esto lo sube promoción.")
        fs_ = request.files.get("file")
        if not fs_ or not getattr(fs_, "filename", ""):
            flash("Elige el archivo del plan.", "warning")
            return redirect(safe_next_or(destino))
        url = upload_file(fs_, "disco_plans")
        prod = _disco_prod(project)
        fila = dict(prod.get("plan_promo") or {})
        fila["file_url"] = url
        fila["file_name"] = (fs_.filename or "").replace("\\", "/")
        fila["done_at"] = _now_madrid().isoformat()
        fila["done_by"] = ((_current_user_state() or {}).get("nick") or "")
        prod["plan_promo"] = fila
        project.production_payload = prod
        _notify_resolve(session_db, "DISCO_PLAN_PROMO", str(project.id))
        _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                      "Plan de promoción subido: %s" % _disco_project_title(project),
                      "Lo ha subido %s. Ya está dentro del plan de lanzamiento."
                      % (fila["done_by"] or "promoción"),
                      url_for("disco_project_detail", project_id=project.id, tab="lanzamiento"),
                      ref_type="DISCO_PLAN", ref_id=str(project.id))
        session_db.commit()
        flash("Plan de promoción subido.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo subir el plan de promoción")
        flash("No se pudo subir: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/plan/revision", endpoint="disco_plan_review")
@admin_required
def disco_plan_review(project_id):
    """PEDIR EL REPASO del plan a quien es dirección y sello, o RECHAZARLO con una nota.

    · `action=ask` → les llega como tarea pendiente (el plan y sus gastos).
    · `action=reject` → el plan vuelve al sello con la nota de qué hay que cambiar (y se quitan los OK)."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        plan = _disco_plan(session_db, project, create=True)
        accion = (request.form.get("action") or "ask").strip().lower()
        prod = _disco_prod(project)
        fila = dict(prod.get("plan_review") or {})
        yo = (_current_user_state() or {})
        if accion == "ask":
            # ⚠️⚠️ EL OK SOLO SE PIDE CON EL PLAN CUMPLIMENTADO: dirección y el sello repasan un plan
            # entero, no uno a medias. Se comprueba AQUÍ además de en la pantalla (un POST directo, o
            # una pantalla vieja abierta, se colarían).
            faltan = _disco_plan_missing(_disco_plan_state(session_db, project))
            if faltan:
                flash("Todavía no se puede pedir el OK: falta %s." % " · ".join(faltan), "warning")
                return redirect(destino)
        if accion == "reject":
            if str(yo.get("user_id") or "") not in _direccion_sello_user_ids(session_db):
                return forbid("El plan lo repasa quien es dirección y sello.")
            nota = (request.form.get("note") or "").strip()
            if not nota:
                flash("Dinos qué hay que cambiar.", "warning")
                return redirect(safe_next_or(destino))
            fila.update({"rejected_at": _now_madrid().isoformat(),
                         "by": (yo.get("nick") or ""), "note": nota, "asked_at": ""})
            plan.ok_direccion_at = None
            plan.ok_direccion_by_nick = None
            plan.ok_sello_at = None
            plan.ok_sello_by_nick = None
            _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                          "Plan de lanzamiento RECHAZADO: %s" % _disco_project_title(project),
                          "%s: %s" % (yo.get("nick") or "Dirección", nota[:300]),
                          url_for("disco_project_detail", project_id=project.id, tab="lanzamiento"),
                          ref_type="DISCO_PLAN", ref_id=str(project.id))
            _notify_resolve(session_db, "DISCO_PLAN_REVIEW", str(project.id))
        else:
            if not can_edit_discografica():
                return forbid("No tienes permisos.")
            fila.update({"asked_at": _now_madrid().isoformat(), "asked_by": (yo.get("nick") or ""),
                         "rejected_at": "", "note": ""})
            estado = _disco_plan_state(session_db, project)
            _notify_users(session_db, _direccion_sello_user_ids(session_db), "TAREA",
                          "Repasar y aprobar el plan de lanzamiento: %s"
                          % _disco_project_title(project),
                          "Hay %d acción(es) y %s de gasto previsto."
                          % (len(estado["actions"]), estado["total_cost_label"]),
                          url_for("disco_project_detail", project_id=project.id, tab="lanzamiento"),
                          ref_type="DISCO_PLAN_REVIEW", ref_id=str(project.id))
        prod["plan_review"] = fila
        project.production_payload = prod
        session_db.commit()
        flash("Plan devuelto al sello." if accion == "reject" else
              "Pedido el repaso a dirección y sello.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo gestionar el repaso")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/plan/notificar", endpoint="disco_plan_notify_artist")
@admin_required
def disco_plan_notify_artist(project_id):
    """NOTIFICARLE EL PLAN AL ARTISTA (y a los colaboradores si los hay).

    ⚠️ Solo cuando está **aprobado** (dirección y sello), y **antes de que empiece**. El correo lleva
    el plan **por secciones** y el enlace al **cronograma online**, que se ve siempre al día. No lleva
    **nada de economía**: eso no se comparte."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        estado = _disco_plan_state(session_db, project)
        if not estado.get("approved"):
            flash("El plan tiene que estar aprobado por dirección y sello antes de mandarlo.",
                  "warning")
            return redirect(safe_next_or(destino))
        plan = estado["plan"]
        if plan is not None and not plan.public_token:
            plan.public_token = _uuid_token()
            session_db.flush()
        enlace = (_external_url_for("public_disco_plan", token=plan.public_token)
                  if plan is not None and plan.public_token else "")
        cuerpo = _disco_plan_artist_email_body(session_db, project, estado, enlace,
                                               nota=(request.form.get("note") or ""))
        html_correo = _disco_project_email_shell(
            session_db, project, title="Plan de lanzamiento", body_html=cuerpo,
            button_label="Ver el plan", button_url=enlace)
        filas = _notify_apply_prefs(session_db,
                                   _artist_notification_recipients(session_db, project.artist_id,
                                                                   "DISCOGRAFICA") or [])
        salieron = []
        for f in filas:
            ok, _err = _notify_send_row(
                session_db, f,
                subject="Plan de lanzamiento · %s" % _disco_project_title(project),
                html=html_correo,
                sms_text="Ya tienes el plan de lanzamiento de %s · %s"
                         % (_disco_project_title(project), enlace),
                kind="DISCOGRAFICA")
            if ok:
                salieron.append(f.get("name") or f.get("email"))
        prod = _disco_prod(project)
        fila = dict(prod.get("plan_notice") or {})
        if salieron:
            fila["sent_at"] = _now_madrid().isoformat()
            fila["by"] = ((_current_user_state() or {}).get("nick") or "")
            fila["to"] = [str(x) for x in salieron]
            prod["plan_notice"] = fila
            project.production_payload = prod
            _notify_resolve(session_db, "DISCO_PLAN_NOTICE", str(project.id))
        session_db.commit()
        if salieron:
            flash("Plan mandado a %s." % ", ".join([str(x) for x in salieron]), "success")
        else:
            flash(Markup("No se pudo avisar al artista. Puedes mandarle este enlace: "
                         "<a href='%s'>%s</a>" % (escape(enlace), escape(enlace))), "warning")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudo notificar el plan")
        flash("No se pudo mandar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


def _disco_plan_artist_email_body(session_db, project, estado, enlace, *, nota: str = "") -> str:
    """EL PLAN POR SECCIONES para el artista. ⚠️ **Sin nada de economía**: ni costes ni presupuestos.

    Va la estrategia, las acciones (con sus fechas), el marketing, la promoción y las publicaciones —
    y el enlace, que se ve siempre al día."""
    esc = lambda v: html.escape("" if v is None else str(v))
    partes = []
    if (nota or "").strip():
        partes.append('<p style="margin:0 0 14px;">%s</p>' % esc(nota.strip()).replace("\n", "<br/>"))
    partes.append('<p style="margin:0 0 14px;">Ya tenemos el <strong>plan de lanzamiento</strong>. '
                  'Esto es lo que hay, y en el enlace lo ves siempre al día.</p>')

    def seccion(titulo, filas):
        if not filas:
            return
        partes.append('<div style="margin:0 0 16px;">'
                      '<div style="font-size:13px;font-weight:700;text-transform:uppercase;'
                      'letter-spacing:.06em;color:#6b7280;margin-bottom:6px;">%s</div>'
                      '<ul style="margin:0;padding-left:18px;font-size:14px;line-height:1.7;">%s</ul>'
                      '</div>' % (esc(titulo), "".join("<li>%s</li>" % x for x in filas)))

    if (estado.get("strategy_text") or "").strip():
        partes.append('<div style="margin:0 0 16px;font-size:14px;line-height:1.7;">%s</div>'
                      % esc(estado["strategy_text"]).replace("\n", "<br/>"))
    seccion("Acciones", ["%s%s" % (esc(a["title"]),
                                   (" — %s" % esc(a["when_label"])) if a.get("when_label") else "")
                         for a in (estado.get("actions") or [])])
    seccion("Marketing", [esc(m.get("title") or m.get("name") or "—")
                          for m in (estado.get("marketing") or [])])
    seccion("Promoción", [esc(p.get("title") or p.get("name") or "—")
                          for p in (estado.get("promos") or [])])
    seccion("Publicaciones", ["%s%s" % (esc(c.get("title") or "Publicación"),
                                        (" — %s" % esc(c.get("when_label")))
                                        if c.get("when_label") else "")
                              for c in (estado.get("contents") or [])])
    if estado.get("promo_file_url"):
        partes.append('<p style="margin:0 0 14px;font-size:14px;">Y el <strong>plan de promoción</strong> '
                      'va con el resto en el enlace.</p>')
    return "".join(partes)


@app.post("/discografica/proyectos/<project_id>/plan/ok", endpoint="disco_plan_ok")
@admin_required
def disco_plan_ok(project_id):
    """El OK de DIRECCIÓN o del SELLO al plan. ⚠️ Hacen falta LOS DOS para darlo por aprobado."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        plan = _disco_plan(session_db, project, create=True)
        cual = (request.form.get("which") or "").strip().lower()
        estado = _current_user_state() or {}
        quien = (estado.get("nick") or estado.get("email") or "")
        deshacer = _truthy(request.form.get("undo"))
        if cual == "direccion":
            if not is_master():
                return forbid("El OK de dirección solo lo puede dar dirección.")
            plan.ok_direccion_at = (None if deshacer else _now_madrid())
            plan.ok_direccion_by_nick = (None if deshacer else quien)
        elif cual == "sello":
            if not (is_master() or can_edit_discografica()):
                return forbid("El OK del sello lo da el sello.")
            plan.ok_sello_at = (None if deshacer else _now_madrid())
            plan.ok_sello_by_nick = (None if deshacer else quien)
        else:
            flash("No sé de quién es el OK.", "warning")
            return redirect(destino)
        plan.updated_at = _now_madrid()
        # ⚠️ Un OK BORRA el rechazo anterior: si lo aprueban, ya no está devuelto.
        if not deshacer:
            prod = _disco_prod(project)
            revision = dict(prod.get("plan_review") or {})
            if revision.get("rejected_at"):
                revision["rejected_at"] = ""
                revision["note"] = ""
                prod["plan_review"] = revision
                project.production_payload = prod
        session_db.flush()
        # Con los DOS OK, el plan queda liberado: se le dice al jefe de producto.
        if plan.ok_direccion_at and plan.ok_sello_at and not deshacer:
            _notify_resolve(session_db, "DISCO_PLAN_REVIEW", str(project.id))
            _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                          "Plan de lanzamiento aprobado: %s" % _disco_project_title(project),
                          "Lo tienes liberado: ya se le puede mandar al artista.",
                          url_for("disco_project_detail", project_id=project.id, tab="lanzamiento"),
                          ref_type="DISCO_PLAN", ref_id=str(project.id))
        session_db.commit()
        flash("Anotado.", "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo anotar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


# ---------------------------------------------------------
# RECORDATORIOS DE PUBLICACIÓN del plan de lanzamiento
# ---------------------------------------------------------
# Se activan cuando el plan está aprobado. Primero sale UN correo (o SMS) con el CRONOGRAMA y, después,
# un aviso antes de cada publicación con el contenido listo para copiar y pegar.
# ⚠️ Solo se avisa de lo que **está subido** y sigue **activo**: no se recuerda algo que no se puede
# publicar. Y si se cambia la fecha o la hora, el aviso se recalcula sobre lo de AHORA.
def _disco_plan_reminder_candidates(session_db, project, plan) -> list[dict]:
    """A QUIÉN se le pueden mandar los recordatorios de publicación.

    · el ARTISTA, por su canal de **CONTENIDOS** (y si no lo tiene configurado, por el discográfico),
    · los COLABORADORES (los demás intérpretes del lanzamiento) y los integrantes del artista,
    · quien lleve **digital** en la oficina (departamento «Redes sociales»),
    · y quien se añada a mano."""
    salida, vistos = [], set()

    def añade(nombre, correo, telefono, papel, foto=""):
        clave = (correo or "").strip().lower() or (telefono or "").strip()
        if not clave or clave in vistos:
            return
        vistos.add(clave)
        salida.append({"name": (nombre or "").strip() or (correo or telefono or ""),
                       "email": (correo or "").strip(), "phone": (telefono or "").strip(),
                       "role": papel, "photo_url": (foto or "")})

    artista = getattr(project, "artist", None) or (
        session_db.get(Artist, project.artist_id) if project.artist_id else None)
    if artista is not None:
        filas = (_artist_notification_recipients(session_db, artista.id, "CONTENIDOS", fallback=False)
                 or _artist_notification_recipients(session_db, artista.id, "DISCOGRAFICA") or [])
        for f in filas:
            añade(f.get("name") or artista.name, f.get("email"), f.get("phone"), "ARTISTA",
                  (artista.photo_url or ""))
        try:
            for persona in (session_db.query(ArtistPerson)
                            .filter(ArtistPerson.artist_id == artista.id).all()):
                p = (session_db.get(Promoter, persona.promoter_id) if persona.promoter_id else None)
                correo_i, tel_i = _promoter_email_phone(p)
                añade(_artist_person_full_name(persona), correo_i, tel_i, "INTEGRANTE",
                      (getattr(p, "logo_url", "") or ""))
        except Exception:
            app.logger.exception("[plan] integrantes del artista")
    # COLABORADORES: los otros intérpretes del lanzamiento.
    try:
        release = _disco_project_release(session_db, project)
        if release and release.get("kind") == "SONG":
            cancion = session_db.get(Song, to_uuid(release["id"]))
            # ⚠️ `_song_interpreter_rows_map` devuelve objetos ORM (`SongInterpreter`), NO dicts:
            # tratarlos con `.get()` reventaba y los colaboradores no entraban nunca.
            for fila in (_song_interpreter_rows_map(session_db, [cancion.id]).get(str(cancion.id), [])
                         if cancion else []):
                otro = (getattr(fila, "artist", None) or getattr(fila, "promoter", None))
                nombre = (getattr(otro, "name", None) or getattr(otro, "nick", None)
                          or getattr(fila, "name", None) or "").strip()
                if not nombre or nombre == getattr(artista, "name", ""):
                    continue
                correo_c, tel_c = _promoter_email_phone(getattr(fila, "promoter", None))
                añade(nombre, correo_c, tel_c, "COLABORADOR",
                      (getattr(otro, "photo_url", None) or getattr(otro, "logo_url", None) or ""))
    except Exception:
        app.logger.exception("[plan] colaboradores del lanzamiento")
    # DIGITAL de la casa (departamento «Redes sociales»).
    try:
        for uid in _department_user_ids(session_db, "Redes sociales"):
            prof = (session_db.query(UserProfile).filter(UserProfile.user_id == to_uuid(uid)).first())
            u = session_db.get(User, to_uuid(uid))
            añade((getattr(prof, "nick", "") or getattr(u, "email", "")), getattr(u, "email", ""),
                  _user_sms_phone(session_db, uid), "DIGITAL",
                  (getattr(prof, "photo_url", "") or ""))
    except Exception:
        app.logger.exception("[plan] personal de digital")
    return _notify_apply_prefs(session_db, salida)


def _disco_plan_content_email_html(session_db, project, plan, contenido, *, intro: bool = False,
                                   contents=None, jefe=None) -> str:
    """Los correos de los recordatorios.

    · `intro=True` → **Cronograma de publicaciones**: la cabecera del lanzamiento, el texto de la
      casa, con quién hablar para no recibirlos (el jefe de producto, con su foto) y el cronograma
      entero, con el botón que lleva a verlo online.
    · si no → **Aviso de publicación**: «es el momento de publicar», con la miniatura, el copy, las
      menciones y los hashtags listos para copiar."""
    ctx = _disco_project_email_ctx(session_db, project)
    esc = lambda v: html.escape("" if v is None else str(v))
    marca = ctx.get("brand") or {}
    logo = _absolute_media_url(marca.get("logo_url") or "")
    logo_html = ("" if not logo else
                 '<div style="text-align:right;"><img src="%s" alt="" '
                 'style="max-height:56px;max-width:180px;object-fit:contain;"></div>' % esc(logo))
    portada = _absolute_media_url(ctx.get("cover_url") or "")
    cabecera = ('<div style="margin:16px 0;border:1px solid #e5e7eb;border-radius:16px;padding:16px;'
                'background:#fcfcfd;"><table role="presentation" cellspacing="0" cellpadding="0"><tr>'
                + ("" if not portada else
                   '<td width="110" valign="top"><img src="%s" alt="" style="width:92px;height:92px;'
                   'object-fit:cover;border-radius:12px;border:1px solid #e5e7eb;"></td>' % esc(portada))
                + '<td valign="top" style="%s"><div style="font-size:20px;font-weight:700;">%s</div>'
                  '<div style="font-size:14px;color:#4b5563;margin-top:6px;">%s · %s</div></td>'
                  '</tr></table></div>'
                % (("padding-left:14px;" if portada else ""), esc(ctx.get("title")),
                   esc(ctx.get("artist_name")), esc(ctx.get("release_label"))))
    url_publico = (_external_url_for("public_disco_plan", token=plan.public_token)
                   if getattr(plan, "public_token", None) else "")
    if intro:
        filas = []
        for c in (contents or []):
            filas.append(
                '<tr><td style="padding:8px 10px 8px 0;font-size:14px;white-space:nowrap;">%s</td>'
                '<td style="padding:8px 0;font-size:14px;">%s<div style="color:#6b7280;font-size:13px;">%s</div></td></tr>'
                % (esc(c.get("when_label")), esc(c.get("title")), esc(c.get("networks_label"))))
        jefe_html = ""
        if jefe:
            foto = _absolute_media_url(jefe.get("photo_url") or "")
            jefe_html = ('<div style="margin:14px 0;font-size:14px;color:#374151;">Si no quieres '
                         'recibir los avisos, habla con %s<a href="mailto:%s" style="color:#E33D48;'
                         'font-weight:700;text-decoration:none;">%s</a>.</div>'
                         % (("" if not foto else
                            '<img src="%s" alt="" style="width:26px;height:26px;border-radius:50%%;'
                            'object-fit:cover;vertical-align:middle;margin-right:6px;">' % esc(foto)),
                            esc(jefe.get("email") or ""), esc(jefe.get("name") or "")))
        cuerpo = ('<div style="font-size:20px;font-weight:700;margin:0 0 10px;">Cronograma de publicaciones</div>'
                  '<p style="font-size:15px;line-height:1.7;">Te compartimos el cronograma de '
                  'publicaciones para el lanzamiento. Te iremos avisando antes de cada publicación '
                  'con el contenido que hay que publicar.</p>' + jefe_html
                  + '<table style="border-collapse:collapse;width:100%%;">%s</table>' % "".join(filas))
        titulo = "Cronograma de publicaciones"
        boton = ("" if not url_publico else
                 '<div style="margin-top:22px;text-align:right;"><a href="%s" '
                 'style="display:inline-block;padding:13px 22px;border-radius:999px;background:#E33D48;'
                 'color:#fff;font-weight:700;text-decoration:none;">Ver el cronograma</a></div>'
                 % esc(url_publico))
    else:
        mini = _absolute_media_url(contenido.get("thumb_url") or "")
        detalle = []
        if contenido.get("description"):
            detalle.append('<div style="margin-top:8px;color:#374151;">%s</div>'
                           % esc(contenido["description"]))
        if contenido.get("copy_text"):
            detalle.append('<div style="margin-top:10px;"><strong>Copy:</strong><div style="white-space:pre-wrap;">%s</div></div>'
                           % esc(contenido["copy_text"]))
        if contenido.get("mentions"):
            detalle.append('<div style="margin-top:8px;"><strong>Menciones:</strong> %s</div>'
                           % esc(" ".join(contenido["mentions"])))
        if contenido.get("hashtags"):
            detalle.append('<div style="margin-top:8px;"><strong>Hashtags:</strong> %s</div>'
                           % esc(" ".join(contenido["hashtags"])))
        if contenido.get("networks_label"):
            detalle.append('<div style="margin-top:8px;"><strong>Dónde:</strong> %s</div>'
                           % esc(contenido["networks_label"]))
        # ⚠️ Este trozo NO pasa por el operador `%` (va concatenado), así que aquí el porcentaje va
        # SIMPLE: con `%%` salía literal en el correo.
        cuerpo = ('<div style="font-size:20px;font-weight:700;margin:0 0 10px;">Es el momento de publicar</div>'
                  '<table role="presentation" cellspacing="0" cellpadding="0" style="width:100%;"><tr>'
                  + ("" if not mini else
                     '<td width="130" valign="top"><a href="%s"><img src="%s" alt="" '
                     'style="width:112px;height:112px;object-fit:cover;border-radius:12px;'
                     'border:1px solid #e5e7eb;"></a></td>' % (esc(contenido.get("file_url") or mini), esc(mini)))
                  + '<td valign="top" style="%s"><div style="font-size:17px;font-weight:700;">%s</div>'
                    '<div style="color:#6b7280;font-size:13px;">%s</div>%s</td></tr></table>'
                  % (("padding-left:14px;" if mini else ""), esc(contenido.get("title")),
                     esc(contenido.get("when_label")), "".join(detalle)))
        titulo = "Aviso de publicación"
        boton = ("" if not contenido.get("file_url") else
                 '<div style="margin-top:22px;text-align:right;"><a href="%s" '
                 'style="display:inline-block;padding:13px 22px;border-radius:999px;background:#E33D48;'
                 'color:#fff;font-weight:700;text-decoration:none;">Descargar el contenido</a></div>'
                 % esc(contenido["file_url"]))
    return """
    <div style="margin:0;padding:24px;background:#f5f7fb;font-family:Arial,Helvetica,sans-serif;color:#111827;">
      <div style="max-width:720px;margin:0 auto;background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:24px 30px;">
        %s
        <div style="margin-top:10px;font-size:24px;font-weight:700;text-align:center;">%s</div>
        %s
        %s
        %s
      </div>
    </div>
    """ % (logo_html, esc(titulo), cabecera, cuerpo, boton)


def _disco_plan_product_manager(session_db, project) -> dict:
    """El JEFE DE PRODUCTO del artista (quien del SELLO lo lleva): es a quien se le dice que hable si
    no quiere recibir los avisos."""
    try:
        for prof in session_db.query(UserProfile).all():
            asignados = [str(x) for x in (getattr(prof, "assigned_artist_ids_sello", None) or [])]
            if str(project.artist_id) in asignados:
                u = session_db.get(User, prof.user_id)
                return {"name": (prof.nick or getattr(u, "email", "") or ""),
                        "email": (getattr(u, "email", "") or ""),
                        "photo_url": (prof.photo_url or "")}
    except Exception:
        app.logger.exception("[plan] no se pudo resolver el jefe de producto")
    return {}


@app.post("/discografica/proyectos/<project_id>/plan/recordatorios", endpoint="disco_plan_reminders")
@admin_required
def disco_plan_reminders(project_id):
    """ACTIVA (o cambia) los recordatorios de publicación: a quién, por dónde y con cuánta antelación.

    Al activarlos sale el correo del CRONOGRAMA; los avisos de cada publicación los manda el cron."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="lanzamiento")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        plan = _disco_plan(session_db, project, create=True)
        f = request.form
        if _truthy(f.get("undo")):
            plan.reminders_enabled = False
            session_db.commit()
            flash("Recordatorios desactivados.", "success")
            return redirect(safe_next_or(destino))
        if not (plan.ok_direccion_at and plan.ok_sello_at):
            flash("El plan tiene que estar aprobado por dirección y por el sello.", "warning")
            return redirect(destino)
        # A QUIÉN: lo marcado de los candidatos + los correos escritos a mano.
        marcados = {x.strip().lower() for x in f.getlist("to[]") if (x or "").strip()}
        gente = [c for c in _disco_plan_reminder_candidates(session_db, project, plan)
                 if (c.get("email") or "").lower() in marcados or (c.get("phone") or "") in marcados]
        for correo in [x.strip() for x in (f.get("extra_emails") or "").replace(";", ",").split(",")
                       if x.strip()]:
            gente.append({"name": "", "email": correo, "phone": "", "role": "OTRO",
                          "channel": "EMAIL"})
        if not gente:
            flash("Marca a quién se le avisa.", "warning")
            return redirect(destino)
        try:
            minutos = max(1, min(1440, int((f.get("minutes") or DISCO_PLAN_REMINDER_DEFAULT_MINUTES))))
        except Exception:
            minutos = DISCO_PLAN_REMINDER_DEFAULT_MINUTES
        plan.reminder_minutes = minutos
        plan.reminder_email = _truthy(f.get("by_email")) or not _truthy(f.get("by_sms"))
        plan.reminder_sms = _truthy(f.get("by_sms"))
        plan.reminder_recipients = [{"name": c.get("name") or "", "email": c.get("email") or "",
                                     "phone": c.get("phone") or "", "role": c.get("role") or "",
                                     "channel": (c.get("channel") or "EMAIL")} for c in gente]
        plan.reminders_enabled = True
        # Los contenidos que NO se quieren avisar se desactivan (se pueden volver a activar).
        # ⚠️ Se manda SIEMPRE la lista completa de contenidos (`content_all[]`), así que lo que no
        # venga marcado está DESMARCADO a propósito: con «si no hay ninguno, todos» desmarcarlos
        # todos los reactivaba.
        avisar = {x.strip() for x in f.getlist("content[]") if (x or "").strip()}
        for c in (plan.contents or []):
            c.active = str(c.id) in avisar
        if not plan.public_token:
            plan.public_token = _uuid_token()
        session_db.flush()
        # El primer correo: el CRONOGRAMA.
        contenidos = [c for c in _disco_plan_content_rows(plan) if c["active"]]
        jefe = _disco_plan_product_manager(session_db, project)
        cuerpo = _disco_plan_content_email_html(session_db, project, plan, None, intro=True,
                                                contents=contenidos, jefe=jefe)
        asunto = "Recordatorio publicaciones · %s" % _disco_project_title(project)
        sms = ("Cronograma de publicaciones de %s: %s"
               % (_disco_project_title(project),
                  _external_url_for("public_disco_plan", token=plan.public_token)))
        salieron = []
        for c in gente:
            fila = dict(c)
            if plan.reminder_sms and not plan.reminder_email:
                fila["channel"] = "SMS"
            elif plan.reminder_email and not plan.reminder_sms:
                fila["channel"] = "EMAIL"
            ok, _err = _notify_send_row(session_db, fila, subject=asunto, html=cuerpo,
                                        sms_text=sms, kind="DISCOGRAFICA")
            if ok:
                salieron.append(fila.get("name") or fila.get("email") or fila.get("phone"))
            # Con las DOS marcadas se manda por los dos canales.
            if plan.reminder_email and plan.reminder_sms and (fila.get("channel") or "") != "SMS":
                otra = dict(fila, channel="SMS")
                _notify_send_row(session_db, otra, subject=asunto, html=cuerpo, sms_text=sms,
                                 kind="DISCOGRAFICA")
        plan.reminders_intro_at = _now_madrid()
        session_db.commit()
        flash("Recordatorios activados%s." % ((" · avisados %s" % ", ".join([str(x) for x in salieron]))
                                              if salieron else ""), "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[plan] no se pudieron activar los recordatorios")
        flash("No se pudo activar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


def _disco_plan_reminder_sweep() -> dict:
    """El aviso de CADA PUBLICACIÓN, `reminder_minutes` antes de su hora.

    ⚠️ Solo de lo que está **subido** y **activo** (no se avisa de algo que no se puede publicar) y
    **una vez** por contenido (`reminder_at`). Si se le cambia la fecha o la hora, ese sello se borra
    y el aviso se vuelve a programar sobre lo de AHORA."""
    session_db = db()
    salida = {"mirados": 0, "avisos": 0}
    try:
        ahora = _now_madrid()
        planes = (session_db.query(DiscoReleasePlan)
                  .filter(DiscoReleasePlan.reminders_enabled.is_(True)).all())
        for plan in planes:
            project = session_db.get(DiscoProject, plan.project_id)
            if project is None:
                continue
            gente = list(plan.reminder_recipients or [])
            if not gente:
                continue
            for c in (plan.contents or []):
                salida["mirados"] += 1
                if not (c.active and c.file_url and c.publish_at) or c.reminder_at:
                    continue
                cuando = c.publish_at
                if cuando.tzinfo is None:
                    cuando = cuando.replace(tzinfo=TZ_MADRID)
                falta = (cuando - ahora).total_seconds() / 60.0
                if falta > (plan.reminder_minutes or DISCO_PLAN_REMINDER_DEFAULT_MINUTES):
                    continue          # todavía no toca
                if falta < -120:
                    continue          # ya pasó hace rato: no se avisa de algo que ya tocaba
                fila = [x for x in _disco_plan_content_rows(plan) if str(x["id"]) == str(c.id)]
                if not fila:
                    continue
                cuerpo = _disco_plan_content_email_html(session_db, project, plan, fila[0])
                asunto = "Es el momento de publicar · %s" % (c.title or "contenido")
                sms = "Toca publicar «%s». %s %s" % (
                    (c.title or "contenido"),
                    " ".join(list(c.mentions or [])[:4]), " ".join(list(c.hashtags or [])[:4]))
                alguno = False
                for destinatario in gente:
                    ok, _err = _notify_send_row(session_db, dict(destinatario), subject=asunto,
                                                html=cuerpo, sms_text=sms, kind="DISCOGRAFICA")
                    alguno = alguno or bool(ok)
                if alguno:
                    c.reminder_at = _now_madrid()
                    salida["avisos"] += 1
        session_db.commit()
    except Exception:
        session_db.rollback()
        app.logger.exception("[plan] barrido de recordatorios de publicación")
    finally:
        session_db.close()
    return salida


@app.get("/cron/publicaciones", endpoint="cron_disco_plan_reminders")
def cron_disco_plan_reminders():
    """Cron de los recordatorios de publicación (conviene que corra cada pocos minutos: los avisos
    van con `reminder_minutes` de antelación)."""
    clave = (request.args.get("key") or "").strip()
    esperada = (os.getenv("DOCS_CRON_KEY") or os.getenv("EXPENSE_CRON_KEY")
                or os.getenv("CHARTMETRIC_CRON_KEY") or "").strip()
    if not esperada or clave != esperada:
        abort(404)
    return jsonify({"ok": True, **_disco_plan_reminder_sweep()})


@app.get("/cronograma/<token>", endpoint="public_disco_plan")
def public_disco_plan(token):
    """El CRONOGRAMA online: lo que ve quien recibe los recordatorios.

    A la izquierda los contenidos con su hora, sus menciones y su copy (se copian con un clic) y a la
    derecha el calendario. Siempre **al día**: se pinta con lo que hay ahora mismo."""
    session_db = db()
    try:
        plan = (session_db.query(DiscoReleasePlan)
                .filter(DiscoReleasePlan.public_token == (token or "").strip()).first())
        if plan is None:
            abort(404)
        project = session_db.get(DiscoProject, plan.project_id)
        if project is None:
            abort(404)
        estado = _disco_plan_state(session_db, project)
        agenda = _disco_plan_agenda(session_db, project, estado)
        # ⚠️ Fuera de casa NO se arrastra nada: sin `move_url`, el calendario no lo deja mover (y no
        # se ofrece un gesto que acabaría en un 403).
        for a in agenda.get("activities", []):
            a.pop("move_url", None)
        return render_template("public_disco_plan.html",
                               ctx=_disco_project_email_ctx(session_db, project),
                               project=project, plan=plan, state=estado,
                               agenda_data=agenda,
                               manager=_disco_plan_product_manager(session_db, project))
    finally:
        session_db.close()


@app.post("/discografica/proyectos/<project_id>/produccion", endpoint="disco_project_production_save")
@admin_required
def disco_project_production_save(project_id):
    """Guarda la PRODUCCIÓN del proyecto, sección a sección (`section`): quién produce, quién mezcla,
    quién masteriza y quién graba las voces.

    Lo pactado vive en `DiscoProject.production_payload`; quien produce es una columna porque es a
    quien se le reclaman los materiales."""
    if not can_edit_discografica():
        return forbid("No tienes permisos para configurar la producción.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        seccion = (request.form.get("section") or "producer").strip().lower()
        prod = _disco_prod(project)
        f = request.form

        def _pk(campo):
            return _safe_uuid((f.get(campo) or "").strip())

        def _importe(campo):
            d = _parse_optional_decimal(f.get(campo))
            return (str(d) if d is not None else "")

        if seccion == "producer":
            _productor_antes = getattr(project, "producer_promoter_id", None)
            project.producer_promoter_id = _pk("producer_promoter_id")
            modo = (f.get("fee_mode") or "").strip().upper()
            prod["fee_mode"] = modo if modo in dict((k, 1) for k, _l, _i in DISCO_PROD_FEE_MODES) else ""
            prod["fee_amount"] = (_importe("fee_amount") if prod["fee_mode"] == "FEE" else "")
            prod["budget_amount"] = (_importe("budget_amount") if prod["fee_mode"] == "BUDGET" else "")
            pct_modo = (f.get("pct_mode") or "").strip().upper()
            prod["pct_mode"] = pct_modo if pct_modo in dict((k, 1) for k, _l, _i in DISCO_PROD_PCT_MODES) else ""
            prod["pct"] = (_importe("pct") if prod["pct_mode"] == "PCT" else "")
        elif seccion in ("mix", "master"):
            modo = (f.get("mode") or "").strip().upper()
            coste = (f.get("cost_mode") or "").strip().upper()
            # El MÁSTER admite además «El mezclador» y, con él, «incluido en su fee».
            quienes = DISCO_MASTER_WHO_MODES if seccion == "master" else DISCO_PROD_WHO_MODES
            costes = (tuple(DISCO_PROD_COST_MODES) + tuple(DISCO_MASTER_COST_EXTRA)
                      if seccion == "master" else DISCO_PROD_COST_MODES)
            prod[seccion] = {
                "mode": modo if modo in dict((k, 1) for k, _l, _i in quienes) else "",
                "promoter_id": (str(_pk("promoter_id")) if modo in ("THIRD", "THIRD_VIA_PRODUCER")
                                and _pk("promoter_id") else ""),
                "cost_mode": coste if coste in dict((k, 1) for k, _l, _i in costes) else "",
                "amount": (_importe("amount") if coste == "AMOUNT" else ""),
            }
        elif seccion == "vocals":
            modo = (f.get("mode") or "").strip().upper()
            coste = (f.get("cost_mode") or "").strip().upper()
            lugar = (f.get("place_mode") or "").strip().upper()
            logistica = _truthy(f.get("logistics"))
            prod["vocals"] = {
                "mode": modo if modo in dict((k, 1) for k, _l, _i in DISCO_VOCALS_MODES) else "",
                "promoter_id": (str(_pk("promoter_id")) if modo == "THIRD" and _pk("promoter_id") else ""),
                "cost_mode": coste if coste in dict((k, 1) for k, _l, _i in DISCO_PROD_COST_MODES) else "",
                "amount": (_importe("amount") if coste == "AMOUNT" else ""),
                "date": ((parse_optional_date(f.get("date")) or "") and
                         parse_optional_date(f.get("date")).isoformat()),
                "place_mode": lugar if lugar in dict((k, 1) for k, _l, _i in DISCO_VOCALS_PLACES) else "",
                "place_name": ((f.get("place_name") or "").strip() if lugar == "OTHER" else ""),
                "place_address": ((f.get("place_address") or "").strip() if lugar == "OTHER" else ""),
                "logistics": logistica,
                "logistics_note": ((f.get("logistics_note") or "").strip() if logistica else ""),
                "logistics_address": ((f.get("logistics_address") or "").strip() if logistica else ""),
                "logistics_user_id": ((f.get("logistics_user_id") or "").strip() if logistica else ""),
            }
        else:
            flash("No sé qué parte de la producción guardar.", "warning")
            return redirect(destino)
        project.production_payload = prod
        project.updated_at = _now_madrid()
        # ⚠️ Con el PRODUCTOR configurado, a REGISTROS+SELLO les toca mandarle su CONTRATO: se les
        # pide aquí (una sola vez). Si se cambia de productor, el contrato vuelve a estar pendiente.
        if seccion == "producer":
            if _productor_antes and str(_productor_antes) != str(project.producer_promoter_id or ""):
                prod.pop("producer_contract", None)
                project.production_payload = prod
            if _disco_producer_contract_ask(session_db, project):
                prod = _disco_prod(project)
        # LOGÍSTICA de la grabación: le sale como tarea a quien se elija de producción.
        # ⚠️ Es la MISMA logística del proyecto (no hay dos): lo que se pide aquí se vuelca en
        # `production_payload['logistics']`, que es lo que leen la tarea, el módulo de Inicio de esa
        # persona, la hoja de ruta y la bolsa.
        if seccion == "vocals":
            voces = prod.get("vocals") or {}
            if voces.get("logistics") and voces.get("logistics_user_id"):
                prod["logistics"] = _disco_logistics_from_vocals(project, voces)
                project.production_payload = prod
                _disco_logistics_request(session_db, project, voces["logistics_user_id"],
                                         _disco_vocals_logistics_text(project, voces))
            else:
                _notify_resolve(session_db, "DISCO_VOCALS", str(project.id))
        session_db.commit()
        flash("Producción guardada.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[proyectos] no se pudo guardar la producción")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/mezcla/pedir", endpoint="disco_project_mix_ask")
@admin_required
def disco_project_mix_ask(project_id):
    """Pedirle al PRODUCTOR la MEZCLA FINAL, con su plazo (el del calendario de entregas).

    ⚠️ Si el plazo se sale de las 4 semanas —o se quiere saltar el paso— hace falta una EXCEPCIÓN
    aprobada por quien sea **dirección y sello**: aquí se le pide con el motivo y, mientras, la tarea
    se queda pendiente."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        estado = _disco_mix_state(session_db, project)
        productor = estado["producer"]
        if productor is None:
            flash("Antes hay que decir quién produce: es a quien se le pide la mezcla.", "warning")
            return redirect(safe_next_or(destino))
        prod = _disco_prod(project)
        fila = dict(prod.get("mix") or {})
        if not (fila.get("token") or "").strip():
            fila["token"] = _uuid_token()
        plazo = parse_optional_date(request.form.get("due_date")) or estado["due_date"]
        if plazo:
            fila["due_date"] = plazo.isoformat()
        tope = estado["limit"]
        # ¿Hace falta la excepción? (fecha pasada del tope o saltarse el paso)
        salta = _truthy(request.form.get("skip"))
        motivo = (request.form.get("waiver_reason") or "").strip()
        excepcion = bool(salta or (plazo and tope and plazo > tope))
        fila["skipped"] = salta
        prod["mix"] = fila
        project.production_payload = prod
        session_db.flush()
        if excepcion and not fila.get("waiver_ok_at"):
            fila["waiver_reason"] = motivo
            fila["waiver_asked_at"] = _now_madrid().isoformat()
            prod["mix"] = fila
            project.production_payload = prod
            _notify_users(session_db, _direccion_sello_user_ids(session_db), "TAREA",
                          "Aprobar una excepción de la mezcla final: %s"
                          % _disco_project_title(project),
                          ("%s%s" % (("Se pide saltarse el paso. " if salta else
                                      ("Se pide entregarla el %s (el tope era el %s). "
                                       % (plazo.strftime("%d/%m/%Y") if plazo else "—",
                                          tope.strftime("%d/%m/%Y") if tope else "—"))),
                                     ("Motivo: %s" % motivo) if motivo else ""))[:600],
                          url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                          ref_type="DISCO_MIX_WAIVER", ref_id=str(project.id))
            session_db.commit()
            flash("Pedida la aprobación de la excepción a dirección y sello.", "warning")
            return redirect(safe_next_or(destino))
        # Sin excepción (o ya aprobada): se le pide al productor.
        enlace = _disco_mix_url(project)
        correo, telefono = _promoter_email_phone(productor)
        cuerpo = ('<p style="margin:0;">Necesitamos la <strong>mezcla final</strong> para que las '
                  'partes la aprueben antes de masterizar%s. Súbela en el enlace.</p>'
                  % ((" (como muy tarde el <strong>%s</strong>)" % html.escape(plazo.strftime("%d/%m/%Y")))
                     if plazo else ""))
        html_correo = _disco_project_email_shell(
            session_db, project, title="Mezcla final", body_html=cuerpo,
            button_label="Subir la mezcla final", button_url=enlace,
            note=(request.form.get("note") or ""))
        ok, _err = _send_optional_email(correo, "Mezcla final · %s"
                                        % _disco_project_title(project), html_correo)
        if not ok and telefono:
            ok, _err = _send_optional_sms(session_db, telefono,
                                          "Sube la mezcla final de %s%s · %s"
                                          % (_disco_project_title(project),
                                             (" (antes del %s)" % plazo.strftime("%d/%m")) if plazo else "",
                                             enlace))
        if ok:
            fila["asked_at"] = _now_madrid().isoformat()
            fila["asked_by"] = ((_current_user_state() or {}).get("nick") or "")
            prod["mix"] = fila
            project.production_payload = prod
        session_db.commit()
        if ok:
            flash("Le hemos pedido la mezcla final a %s." % _promoter_display_name(productor), "success")
        else:
            flash(Markup("No se pudo avisar al productor. Puedes mandarle este enlace: "
                         "<a href='%s'>%s</a>" % (escape(enlace), escape(enlace))), "warning")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[mezcla] no se pudo pedir la mezcla final")
        flash("No se pudo pedir: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/mezcla/excepcion", endpoint="disco_project_mix_waiver")
@admin_required
def disco_project_mix_waiver(project_id):
    """Dirección+sello aprueba (o no) la EXCEPCIÓN del plazo de la mezcla final."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        yo = str((_current_user_state() or {}).get("user_id") or "")
        if yo not in _direccion_sello_user_ids(session_db):
            return forbid("Esto lo aprueba quien es dirección y sello.")
        prod = _disco_prod(project)
        fila = dict(prod.get("mix") or {})
        aprueba = not _truthy(request.form.get("reject"))
        if aprueba:
            fila["waiver_ok_at"] = _now_madrid().isoformat()
            fila["waiver_ok_by"] = ((_current_user_state() or {}).get("nick") or "")
        else:
            fila["waiver_ok_at"] = ""
            fila["waiver_ok_by"] = ""
            fila["waiver_asked_at"] = ""
            fila["skipped"] = False
        prod["mix"] = fila
        project.production_payload = prod
        _notify_resolve(session_db, "DISCO_MIX_WAIVER", str(project.id))
        _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                      ("Excepción de la mezcla final aprobada: %s" if aprueba else
                       "Excepción de la mezcla final RECHAZADA: %s") % _disco_project_title(project),
                      ((_current_user_state() or {}).get("nick") or "Dirección")
                      + (" lo ha aprobado." if aprueba else " dice que no: hay que ajustar el plazo."),
                      url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                      ref_type="DISCO_MIX", ref_id=str(project.id))
        session_db.commit()
        flash("Excepción aprobada." if aprueba else "Excepción rechazada.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[mezcla] no se pudo decidir la excepción")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/mezcla/aprobacion", endpoint="disco_project_mix_approval")
@admin_required
def disco_project_mix_approval(project_id):
    """El JEFE DE PRODUCTO pide la aprobación de la mezcla final a las partes (en cadena)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        estado = _disco_mix_state(session_db, project)
        if not estado["file_url"]:
            flash("Todavía no hay mezcla final que aprobar.", "warning")
            return redirect(safe_next_or(destino))
        # QUIÉN entra: los candidatos que siguen marcados (se puede quitar a alguien en este paso) y
        # los añadidos ahora —que quedan guardados en el proyecto y, si se marca, como preferencia
        # del artista—. Punto único para todas las aprobaciones: `_disco_approval_pick`.
        elegidos, nuevos = _disco_approval_pick(session_db, project, request.form)
        fila = _disco_approval_open(session_db, project, "MIX",
                                    file_url=estado["file_url"], file_name=estado["file_name"],
                                    note=(request.form.get("note") or ""),
                                    due_date=estado["due_date"], voters=elegidos)
        # La cadena empieza por la etapa más baja que tenga gente.
        etapas = sorted({int(v.stage or 1) for v in (fila.voters or [])})
        salieron = _disco_approval_notify(session_db, project, fila, etapas[0]) if etapas else []
        session_db.commit()
        if not etapas:
            flash("No hay a quién pedirle la aprobación: revisa los integrantes del artista.",
                  "warning")
        elif salieron:
            flash("Aprobación pedida a %s." % ", ".join([str(x) for x in salieron]), "success")
        else:
            flash("Aprobación creada, pero no se pudo avisar a nadie: comparte sus enlaces a mano.",
                  "warning")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[mezcla] no se pudo pedir la aprobación")
        flash("No se pudo pedir: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.route("/mezcla-final/<token>", methods=["GET", "POST"], endpoint="public_disco_mix_upload")
def public_disco_mix_upload(token):
    """Página pública donde el PRODUCTOR sube la mezcla final para que la aprueben."""
    session_db = db()
    try:
        token = (token or "").strip()
        project = None
        if token:
            for p in (session_db.query(DiscoProject)
                      .filter(DiscoProject.production_payload.isnot(None)).all()):
                if (_disco_mix(p).get("token") or "") == token:
                    project = p
                    break
        if project is None:
            abort(404)
        ctx = _disco_project_email_ctx(session_db, project)
        estado = _disco_mix_state(session_db, project)
        if request.method == "POST":
            fs = request.files.get("file")
            if not fs or not getattr(fs, "filename", ""):
                return render_template("public_disco_mix.html", mode="form", ctx=ctx,
                                       project=project, state=estado,
                                       error="Elige el archivo de la mezcla.")
            url = upload_file(fs, "song_materials", allowed_extensions={".wav", ".wave", ".mp3"})
            prod = _disco_prod(project)
            fila = dict(prod.get("mix") or {})
            fila["file_url"] = url
            fila["file_name"] = (fs.filename or "").replace("\\", "/")
            fila["file_at"] = _now_madrid().isoformat()
            prod["mix"] = fila
            project.production_payload = prod
            # Al JEFE DE PRODUCTO: ya se puede pedir la aprobación.
            _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                          "Mezcla final subida: %s" % _disco_project_title(project),
                          "Ya se le puede pedir la aprobación a las partes.",
                          url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                          ref_type="DISCO_MIX", ref_id=str(project.id))
            session_db.commit()
            return render_template("public_disco_mix.html", mode="done", ctx=ctx, project=project,
                                   state=_disco_mix_state(session_db, project))
        return render_template("public_disco_mix.html", mode="form", ctx=ctx, project=project,
                               state=estado)
    finally:
        session_db.close()


@app.route("/aprobacion/<token>", methods=["GET", "POST"], endpoint="public_disco_approval")
def public_disco_approval(token):
    """Página pública de UNA persona para aprobar (verde) o rechazar (rojo).

    Enseña lo que hay que aprobar (la mezcla se escucha aquí mismo) y **a los demás con su foto y su
    estado**, para saber quién falta."""
    session_db = db()
    try:
        voter = (session_db.query(DiscoApprovalVoter)
                 .options(joinedload(DiscoApprovalVoter.approval))
                 .filter(DiscoApprovalVoter.token == (token or "").strip()).first())
        if voter is None or voter.approval is None:
            abort(404)
        fila = voter.approval
        project = session_db.get(DiscoProject, fila.project_id)
        if project is None:
            abort(404)
        ctx = _disco_project_email_ctx(session_db, project)
        # ELEGIR ENTRE VARIAS FOTOS: solo la ETAPA 1 elige; el colaborador ya aprueba la elegida.
        opciones = (_disco_photo_options(fila) if (fila.kind or "").upper() == "COVER_PHOTO" else [])
        elige = bool(opciones) and len(opciones) > 1 and int(voter.stage or 1) == 1 \
            and not (fila.payload or {}).get("picked")
        # ⚠️ LA ELECCIÓN VA EN DOS PASOS: primero se APRUEBAN las que gusten y, de esas, se elige la
        # DEFINITIVA (que es la que se comunica para hacer la portada).
        gustan = _disco_photo_liked(fila)
        paso = "like" if (elige and not gustan) else "pick"
        pintar = lambda modo, err="", **kw: render_template(
            "public_disco_approval.html", mode=modo, ctx=ctx, project=project, voter=voter,
            options=kw.pop("options", opciones), choose=kw.pop("choose", elige),
            step=kw.pop("step", paso), liked=kw.pop("liked", gustan),
            state=_disco_approval_state(session_db, project, fila.kind), error=err, **kw)
        if request.method == "POST" and (voter.status or "").upper() == "PENDIENTE":
            # Paso 1: las que le gustan (todavía no decide nada).
            if elige and (request.form.get("step") or "").strip() == "like":
                marcadas = _disco_photo_like(session_db, fila, request.form.getlist("liked"))
                if not marcadas:
                    return pintar("form", "Marca al menos una foto que te valga.", step="like", liked=[])
                session_db.commit()
                return pintar("form", step="pick", liked=marcadas)
            aprueba = (request.form.get("decision") or "").strip().upper() == "OK"
            nota = (request.form.get("note") or "").strip()
            if not aprueba and not nota:
                return pintar("form", "Dinos qué hay que cambiar.")
            if aprueba and elige:
                pedida = (request.form.get("option") or "").strip()
                if gustan and pedida not in gustan:
                    return pintar("form", "Elige una de las que has aprobado.", step="pick")
                if not _disco_photo_pick(session_db, fila, pedida):
                    return pintar("form", "Elige una de las fotos.", step="pick")
                # QUIEN LLEVA EL PROYECTO se entera de que ya hay foto elegida.
                _disco_photo_notify_picked(session_db, project, _disco_photo_picked_url(fila))
            _disco_approval_decide(session_db, voter, aprueba, nota)
            session_db.commit()
            return pintar("done", options=_disco_photo_options(fila), choose=False, step="pick")
        return pintar("done" if (voter.status or "").upper() != "PENDIENTE" else "form")
    finally:
        session_db.close()


@app.post("/discografica/proyectos/<project_id>/fecha/notificar", endpoint="disco_project_date_notify")
@admin_required
def disco_project_date_notify(project_id):
    """NOTIFICARLE AL ARTISTA QUE YA HAY FECHA, con el calendario de plazos.

    Solo cuando **Registros la ha confirmado**. Van la fecha y **todos los plazos** del calendario de
    entregas — y si el lanzamiento lleva **videoclip**, también los suyos."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        fechas = _disco_date_state(session_db, project)
        if not fechas.get("confirmed"):
            flash("Antes tiene que confirmar la fecha Registros.", "warning")
            return redirect(safe_next_or(destino))
        entregas = _disco_delivery_state(session_db, project)
        esc = lambda v: html.escape("" if v is None else str(v))
        filas = "".join(
            '<tr><td style="padding:6px 10px;border-bottom:1px solid #eef0f4;">%s</td>'
            '<td style="padding:6px 10px;border-bottom:1px solid #eef0f4;text-align:right;'
            'font-weight:700;">%s</td></tr>'
            % (esc(f["label"]), esc(f["date_label"] or ("antes del %s" % f["limit_label"])
                                    if (f["date_label"] or f["limit_label"]) else "—"))
            for f in (entregas.get("rows") or []))
        cuerpo = ('<p style="margin:0 0 14px;">Ya tenemos <strong>fecha de lanzamiento</strong>: '
                  '<strong>%s</strong>.</p>' % esc(fechas.get("date_long") or fechas.get("date_label")))
        if (request.form.get("note") or "").strip():
            cuerpo += ('<p style="margin:0 0 14px;">%s</p>'
                       % esc(request.form["note"].strip()).replace("\n", "<br/>"))
        if filas:
            cuerpo += ('<div style="margin:0 0 6px;font-size:13px;font-weight:700;'
                       'text-transform:uppercase;letter-spacing:.06em;color:#6b7280;">Plazos</div>'
                       '<table role="presentation" width="100%%" style="border-collapse:collapse;'
                       'font-size:14px;">%s</table>' % filas)
        html_correo = _disco_project_email_shell(
            session_db, project, title="Fecha de lanzamiento", body_html=cuerpo)
        recibieron = []
        for f in _notify_apply_prefs(session_db,
                                    _artist_notification_recipients(session_db, project.artist_id,
                                                                    "DISCOGRAFICA") or []):
            ok, _err = _notify_send_row(
                session_db, f,
                subject="Fecha de lanzamiento · %s" % _disco_project_title(project),
                html=html_correo,
                sms_text="%s sale el %s" % (_disco_project_title(project),
                                            fechas.get("date_label") or ""),
                kind="DISCOGRAFICA")
            if ok:
                recibieron.append(f.get("name") or f.get("email"))
        if recibieron:
            prod = _disco_prod(project)
            prod["date_notice"] = {"sent_at": _now_madrid().isoformat(),
                                   "by": ((_current_user_state() or {}).get("nick") or ""),
                                   "to": [str(x) for x in recibieron]}
            project.production_payload = prod
        session_db.commit()
        if recibieron:
            flash("Fecha notificada a %s." % ", ".join([str(x) for x in recibieron]), "success")
        else:
            flash("No se pudo avisar al artista: revisa sus contactos de comunicaciones.", "warning")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[proyectos] no se pudo notificar la fecha")
        flash("No se pudo mandar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/calendario-entregas", endpoint="disco_project_delivery_save")
@admin_required
def disco_project_delivery_save(project_id):
    """Guarda el CALENDARIO DE ENTREGAS (lo que se ha arrastrado a cada día).

    ⚠️ Los topes se comprueban aquí también: el calendario del navegador no puede ser la única
    barrera. Y cada plazo se escribe donde ya vivía (el del máster es el `materials_due_date` del
    proyecto y el de la portada el de su solicitud), así que se ve en su tarea y en sus correos."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        if not getattr(project, "release_date", None):
            flash("Antes hace falta la fecha de lanzamiento: los plazos se cuentan desde ella.",
                  "warning")
            return redirect(safe_next_or(destino))
        fechas = {clave: (request.form.get("date_%s" % clave) or "").strip()
                  for clave, _l, _i, _s in DISCO_DELIVERY_MILESTONES
                  if ("date_%s" % clave) in request.form}
        problemas = _disco_delivery_apply(session_db, project, fechas)
        session_db.commit()
        if problemas:
            flash("Calendario guardado, menos: " + " · ".join(problemas), "warning")
        else:
            flash("Calendario de entregas guardado.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[calendario] no se pudo guardar el calendario de entregas")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/nota-prensa/solicitar", endpoint="disco_project_press_request")
@admin_required
def disco_project_press_request(project_id):
    """SOLICITAR la nota de prensa: sale a la vez a PROMOCIÓN (redactarla) y a DISEÑO (maquetarla).

    ⚠️ No se puede pedir sin el pitch, la fecha y el focus single decidido: es lo que la nota cuenta
    (lo comprueba el servidor, no solo el botón)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        estado = _disco_press_state(session_db, project)
        if not estado["can_request"]:
            flash("Todavía no se puede pedir la nota de prensa: falta %s."
                  % " y ".join(estado["missing"]), "warning")
            return redirect(safe_next_or(destino))
        prod = _disco_prod(project)
        fila = dict(prod.get("press") or {})
        fila["requested_at"] = (fila.get("requested_at") or _now_madrid().isoformat())
        fila["requested_by"] = (fila.get("requested_by")
                                or (_current_user_state() or {}).get("nick") or "")
        fila["note"] = (request.form.get("note") or "").strip()
        prod["press"] = fila
        project.production_payload = prod
        project.updated_at = _now_madrid()
        session_db.flush()
        plazo = estado["due_label"]
        cuerpo = ("Hay que tenerla lista para el %s." % plazo) if plazo else "Hay que prepararla."
        if fila["note"]:
            cuerpo += " Indicaciones: %s" % fila["note"][:300]
        for clave, etiqueta, _d, _i in DISCO_PRESS_PARTS:
            _notify_users(session_db, _disco_press_people(session_db, clave), "TAREA",
                          "%s: %s" % (etiqueta, _disco_project_title(project)), cuerpo,
                          url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                          ref_type=("DISCO_PRESS_%s" % clave.upper()), ref_id=str(project.id))
        session_db.commit()
        flash("Nota de prensa solicitada a promoción y a diseño.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[nota de prensa] no se pudo solicitar")
        flash("No se pudo solicitar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/nota-prensa/subir", endpoint="disco_project_press_upload")
@admin_required
def disco_project_press_upload(project_id):
    """Sube su parte quien la hace: **promoción** el texto y **diseño** el gráfico.

    ⚠️ Aquí no se exige `can_edit_discografica()`: lo suben promoción y diseño, que no tienen por qué
    poder editar discográfica. Se comprueba que es de su departamento (o dirección)."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        parte = (request.form.get("part") or "text").strip().lower()
        if parte not in DISCO_PRESS_PART_LABELS:
            flash("No sé qué parte de la nota subes.", "warning")
            return redirect(safe_next_or(destino))
        yo = str((_current_user_state() or {}).get("user_id") or "")
        if not (is_master() or can_edit_discografica()
                or yo in _disco_press_people(session_db, parte)):
            return forbid("Esta parte de la nota la sube otro departamento.")
        fs = request.files.get("file")
        if not fs or not getattr(fs, "filename", ""):
            flash("Elige el archivo.", "warning")
            return redirect(safe_next_or(destino))
        url = upload_file(fs, "press_releases")
        prod = _disco_prod(project)
        fila = dict(prod.get("press") or {})
        fila["%s_url" % parte] = url
        fila["%s_name" % parte] = (fs.filename or "").replace("\\", "/")
        fila["%s_at" % parte] = _now_madrid().isoformat()
        fila["%s_by" % parte] = ((_current_user_state() or {}).get("nick") or "")
        prod["press"] = fila
        project.production_payload = prod
        project.updated_at = _now_madrid()
        # Su tarea deja de esperar a nadie…
        _notify_resolve(session_db, "DISCO_PRESS_%s" % parte.upper(), str(project.id))
        # …y al estar el TEXTO, a promoción le queda enviarla.
        if parte == "text":
            _notify_users(session_db, _disco_press_people(session_db, "text"), "TAREA",
                          "Enviar la nota de prensa: %s" % _disco_project_title(project),
                          "Ya está redactada: hay que mandarla a los medios.",
                          url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                          ref_type="DISCO_PRESS_SEND", ref_id=str(project.id))
        _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                      "%s: %s" % (DISCO_PRESS_DONE_LABELS.get(parte, "Nota de prensa"),
                                  _disco_project_title(project)),
                      "La ha subido %s." % ((_current_user_state() or {}).get("nick") or "alguien"),
                      url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                      ref_type="DISCO_PRESS", ref_id=str(project.id))
        session_db.commit()
        flash("%s." % DISCO_PRESS_DONE_LABELS.get(parte, "Archivo subido"), "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[nota de prensa] no se pudo subir")
        flash("No se pudo subir: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/nota-prensa/enviada", endpoint="disco_project_press_sent")
@admin_required
def disco_project_press_sent(project_id):
    """«Ya está enviada»: lo marca PROMOCIÓN y con eso la nota de prensa queda terminada."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        yo = str((_current_user_state() or {}).get("user_id") or "")
        if not (is_master() or can_edit_discografica()
                or yo in _disco_press_people(session_db, "text")):
            return forbid("Esto lo marca promoción.")
        prod = _disco_prod(project)
        fila = dict(prod.get("press") or {})
        if not fila.get("text_url"):
            flash("Todavía no hay nota de prensa que enviar.", "warning")
            return redirect(safe_next_or(destino))
        deshacer = _truthy(request.form.get("undo"))
        fila["sent_at"] = ("" if deshacer else _now_madrid().isoformat())
        fila["sent_by"] = ("" if deshacer else ((_current_user_state() or {}).get("nick") or ""))
        prod["press"] = fila
        project.production_payload = prod
        project.updated_at = _now_madrid()
        if deshacer:
            _notify_users(session_db, _disco_press_people(session_db, "text"), "TAREA",
                          "Enviar la nota de prensa: %s" % _disco_project_title(project),
                          "Vuelve a estar pendiente de enviar.",
                          url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                          ref_type="DISCO_PRESS_SEND", ref_id=str(project.id))
        else:
            _notify_resolve(session_db, "DISCO_PRESS_SEND", str(project.id))
        session_db.commit()
        flash("Nota de prensa pendiente de enviar otra vez." if deshacer else
              "Nota de prensa enviada.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[nota de prensa] no se pudo marcar el envío")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/pitch/pedir", endpoint="disco_project_pitch_ask")
@admin_required
def disco_project_pitch_ask(project_id):
    """Pedirle al ARTISTA un texto o una inspiración para poder escribir el pitch (su propio enlace)."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        prod = _disco_prod(project)
        fila = dict(prod.get("pitch") or {})
        if not (fila.get("token") or "").strip():
            fila["token"] = _uuid_token()
        prod["pitch"] = fila
        project.production_payload = prod
        session_db.flush()
        enlace = _disco_pitch_url(project)
        nota = (request.form.get("note") or "").strip()
        cuerpo = ('<p style="margin:0;">Estamos preparando el lanzamiento y nos hace falta tu ayuda '
                  'para escribir el <strong>pitch</strong>: cuéntanos de qué habla la canción, de '
                  'dónde salió o cualquier cosa que nos sirva de inspiración. No hace falta que '
                  'quede bonito: con eso lo redactamos nosotros.</p>')
        cuerpo_html = _disco_project_email_shell(
            session_db, project, title="Inspiración para el pitch", body_html=cuerpo,
            button_label="Contar mi inspiración", button_url=enlace, note=nota)
        filas = _notify_apply_prefs(session_db,
                                   _artist_notification_recipients(session_db, project.artist_id,
                                                                   "DISCOGRAFICA") or [])
        salieron = []
        for f in filas:
            ok, _err = _notify_send_row(
                session_db, f, subject="Inspiración para el pitch · %s" % _disco_project_title(project),
                html=cuerpo_html,
                sms_text="%s: cuéntanos algo para escribir el pitch · %s"
                         % (_disco_project_title(project), enlace),
                kind="DISCOGRAFICA")
            if ok:
                salieron.append(f.get("name") or f.get("email"))
        if salieron:
            fila["asked_at"] = _now_madrid().isoformat()
            fila["asked_by"] = ((_current_user_state() or {}).get("nick") or "")
            prod["pitch"] = fila
            project.production_payload = prod
        session_db.commit()
        if salieron:
            flash("Le hemos pedido la inspiración a %s." % ", ".join([str(x) for x in salieron]),
                  "success")
        else:
            flash(Markup("No se pudo escribir al artista. Puedes mandarle este enlace: "
                         "<a href='%s'>%s</a>" % (escape(enlace), escape(enlace))), "warning")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[pitch] no se pudo pedir la inspiración")
        flash("No se pudo pedir: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/pitch", endpoint="disco_project_pitch_save")
@admin_required
def disco_project_pitch_save(project_id):
    """Guarda el PITCH del lanzamiento. Se queda en la ficha de la CANCIÓN, que es donde vive."""
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        cancion = _disco_project_release_song(session_db, project)
        if cancion is None:
            flash("Este proyecto no tiene una canción de lanzamiento.", "warning")
            return redirect(safe_next_or(destino))
        texto = _pitch_clean_html(request.form.get("pitch_text") or "")
        if not _pitch_plain_text(texto):
            flash("Escribe el pitch.", "warning")
            return redirect(safe_next_or(destino))
        cancion.pitch_title = (request.form.get("pitch_title") or "").strip() or None
        cancion.pitch_text = texto
        cancion.pitch_updated_at = _now_madrid()
        session_db.add(cancion)
        # El aviso de «falta el pitch» deja de esperar a nadie.
        _notify_resolve(session_db, "SONG", str(cancion.id))
        session_db.commit()
        flash("Pitch guardado en la ficha de la canción.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[pitch] no se pudo guardar el pitch")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


