@app.post("/discografica/proyectos/<project_id>/radio", endpoint="disco_project_radio_request")
@admin_required
def disco_project_radio_request(project_id):
    """SOLICITAR la presentación a radio: se marcan las emisoras y contesta PROMOCIÓN.

    ⚠️ No se puede pedir sin la fecha de lanzamiento y sin máster (o al menos una maqueta): es lo que
    hay que mandarle a la emisora."""
    if not can_edit_discografica():
        return forbid("No tienes permisos para configurar el proyecto.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        cancion = _disco_project_release_song(session_db, project)
        if cancion is None:
            flash("Este proyecto no tiene una canción de lanzamiento.", "warning")
            return redirect(safe_next_or(destino))
        if not bool(getattr(cancion, "focus_single", False)):
            flash("Solo se presenta a radio un focus single.", "warning")
            return redirect(safe_next_or(destino))
        listo = _disco_radio_ready(session_db, project, cancion)
        if not listo["ready"]:
            flash("Todavía no se puede mandar a radio: falta %s." % " y ".join(listo["missing"]),
                  "warning")
            return redirect(safe_next_or(destino))
        ids = [x for x in request.form.getlist("media_ids") if (x or "").strip()]
        if not ids:
            flash("Marca al menos una emisora.", "warning")
            return redirect(safe_next_or(destino))
        yo = (_current_user_state() or {})
        nuevas = 0
        for mid in ids:
            pk = _safe_uuid(mid)
            if not pk:
                continue
            # Ya presentada a esa emisora: no se duplica (y si estaba contestada, se respeta).
            existe = (session_db.query(SongRadioPitch)
                      .filter(SongRadioPitch.song_id == cancion.id,
                              SongRadioPitch.media_id == pk).first())
            if existe is not None:
                continue
            session_db.add(SongRadioPitch(
                song_id=cancion.id, project_id=project.id, media_id=pk, status="PENDING",
                requested_by_user_id=_safe_uuid(yo.get("user_id")),
                requested_by_nick=(yo.get("nick") or ""), requested_at=_now_madrid()))
            nuevas += 1
        session_db.flush()
        if nuevas:
            _notify_users(session_db, _disco_radio_deciders(session_db), "TAREA",
                          "Presentar a radio: «%s»" % (cancion.title or ""),
                          "%d emisora(s) por contestar. Di si entra en rotación y desde cuándo."
                          % nuevas,
                          url_for("home"), ref_type="SONG_RADIO", ref_id=str(cancion.id))
        session_db.commit()
        flash("Presentación a radio solicitada." if nuevas else
              "Esas emisoras ya estaban solicitadas.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[proyectos] no se pudo solicitar la presentación a radio")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/radio/presentacion/<pitch_id>/decidir", endpoint="song_radio_pitch_decide")
@admin_required
def song_radio_pitch_decide(pitch_id):
    """PROMOCIÓN (o dirección con función de sello) contesta por esa emisora.

    · **Sí va a entrar** → con su fecha prevista de entrada en rotación, que se anota en el PLAN DE
      LANZAMIENTO como una acción («Presentación a radio · <emisora>»).
    · **No va a entrar** → se avisa a quien lo pidió de que la emisora la ha rechazado y la subtarea
      queda terminada. En el plan no se anota nada.
    ⚠️ Aquí no se exige `can_edit_discografica()`: contesta PROMOCIÓN. Se comprueba que es de quien
    le toca (o dirección)."""
    session_db = db()
    try:
        fila = session_db.get(SongRadioPitch, to_uuid(pitch_id))
        if fila is None:
            flash("Esa presentación no existe.", "warning")
            return redirect(url_for("home"))
        yo = (_current_user_state() or {})
        puede = (is_master() or str(yo.get("user_id") or "") in _disco_radio_deciders(session_db)
                 or can_edit_discografica())
        if not puede:
            return forbid("Esto lo contesta promoción.")
        cancion = session_db.get(Song, fila.song_id)
        medio = session_db.get(MediaOutlet, fila.media_id)
        nombre_medio = (getattr(medio, "name", "") or "la emisora")
        decision = (request.form.get("decision") or "").strip().upper()
        fila.decided_by_user_id = _safe_uuid(yo.get("user_id"))
        fila.decided_by_nick = (yo.get("nick") or "")
        fila.decided_at = _now_madrid()
        fila.updated_at = _now_madrid()
        if decision == "YES":
            fecha = parse_optional_date(request.form.get("start_date"))
            if not fecha:
                flash("Dinos desde cuándo entra en rotación.", "warning")
                return redirect(safe_next_or(url_for("home")))
            fila.status = "ACCEPTED"
            fila.start_date = fecha
            fila.note = (request.form.get("note") or "").strip() or None
            _song_radio_plan_action(session_db, fila, cancion, nombre_medio)
            if fila.requested_by_user_id:
                _notify_user(session_db, fila.requested_by_user_id, "TAREA",
                             "%s va a poner «%s»" % (nombre_medio, (cancion.title if cancion else "")),
                             "Entra en rotación el %s. Ya está apuntado en el plan de lanzamiento."
                             % fecha.strftime("%d/%m/%Y"),
                             _song_radio_project_url(session_db, fila),
                             ref_type="SONG_RADIO", ref_id=str(fila.song_id))
        elif decision == "NO":
            fila.status = "REJECTED"
            fila.start_date = None
            fila.note = (request.form.get("note") or "").strip() or None
            if fila.requested_by_user_id:
                _notify_user(session_db, fila.requested_by_user_id, "TAREA",
                             "%s no va a poner «%s»" % (nombre_medio,
                                                        (cancion.title if cancion else "")),
                             "La emisora ha rechazado la petición: de momento no entra en rotación."
                             + ((" Motivo: %s" % fila.note) if fila.note else ""),
                             _song_radio_project_url(session_db, fila),
                             ref_type="SONG_RADIO", ref_id=str(fila.song_id))
        else:
            flash("Dinos si va a entrar en rotación o no.", "warning")
            return redirect(safe_next_or(url_for("home")))
        session_db.add(fila)
        session_db.flush()
        # Si ya han contestado TODAS, el aviso de «presentar a radio» deja de esperar a nadie.
        if not (session_db.query(func.count(SongRadioPitch.id))
                .filter(SongRadioPitch.song_id == fila.song_id,
                        func.upper(SongRadioPitch.status) == "PENDING").scalar() or 0):
            _notify_resolve(session_db, "SONG_RADIO", str(fila.song_id))
        session_db.commit()
        flash("Anotado: entra en rotación." if decision == "YES" else
              "Anotado: la emisora la ha rechazado.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[radio] no se pudo guardar la decisión")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("home")))


def _song_radio_project_url(session_db, fila) -> str:
    """A dónde lleva el aviso: al proyecto si se pidió desde uno, y si no a la ficha de la canción."""
    try:
        if getattr(fila, "project_id", None):
            return url_for("disco_project_detail", project_id=fila.project_id, tab="calendario")
        return url_for("discografica_song_detail", song_id=fila.song_id, tab="informacion")
    except Exception:
        return url_for("home")


def _song_radio_plan_action(session_db, fila, cancion, nombre_medio) -> None:
    """Anota en el PLAN DE LANZAMIENTO la acción «Presentación a radio · <emisora>».

    Solo cuando la emisora dice que sí (un rechazo no se anota en el plan). Si ya existía la acción de
    esa emisora, se actualiza la fecha en vez de duplicarla."""
    if not getattr(fila, "project_id", None):
        return
    try:
        project = session_db.get(DiscoProject, fila.project_id)
        if project is None:
            return
        plan = _disco_plan(session_db, project, create=True)
        accion = None
        if getattr(fila, "plan_action_id", None):
            accion = session_db.get(DiscoReleasePlanAction, fila.plan_action_id)
        if accion is None:
            accion = DiscoReleasePlanAction(plan_id=plan.id,
                                            position=len(plan.actions or []))
            session_db.add(accion)
        accion.title = ("Presentación a radio · %s" % nombre_medio)[:250]
        accion.description = ("Fecha prevista de entrada en rotación: %s"
                              % fila.start_date.strftime("%d/%m/%Y"))
        accion.cost_mode = (accion.cost_mode or "NONE")
        accion.date_kind = "DATE"
        accion.start_date = fila.start_date
        accion.end_date = None
        session_db.flush()
        fila.plan_action_id = accion.id
    except Exception:
        app.logger.exception("[radio] no se pudo anotar la acción en el plan")


@app.post("/discografica/proyectos/<project_id>/logistica", endpoint="disco_project_logistics_save")
@admin_required
def disco_project_logistics_save(project_id):
    """¿Hace falta logística? Y si hace falta, SOLICITARLA a una persona de producción.

    Al solicitarla: le llega el aviso, entra en la HOJA DE RUTA del proyecto y se crea la BOLSA si no
    existía (es donde va a apuntar los gastos). A partir de ahí la tarea es SUYA."""
    if not can_edit_discografica():
        return forbid("No tienes permisos para configurar el proyecto.")
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        f = request.form
        prod = _disco_prod(project)
        antes = _disco_logistics(project)
        necesita = (f.get("needed") or "").strip().upper()
        if necesita not in ("YES", "NO"):
            flash("Dinos si hace falta logística o no.", "warning")
            return redirect(safe_next_or(destino))
        fila = {"needed": necesita}
        avisar = None
        if necesita == "YES":
            for clave, _lbl, _ico, _ph in DISCO_LOGISTICS_NOTES:
                fila[clave] = (f.get(clave) or "").strip()
            uid = (f.get("user_id") or "").strip()
            fila["user_id"] = uid
            # Se conserva lo ya pedido; si se cambia de persona, se vuelve a pedir.
            mismo = (str(antes.get("user_id") or "") == uid)
            fila["requested_at"] = (antes.get("requested_at") if (mismo and antes.get("requested_at"))
                                    else (_now_madrid().isoformat() if uid else ""))
            fila["requested_by"] = (antes.get("requested_by") if (mismo and antes.get("requested_at"))
                                    else ((_current_user_state() or {}).get("nick") or ""))
            # Si se le pide a otra persona, vuelve a estar pendiente.
            fila["done_at"] = (antes.get("done_at") if mismo else "")
            fila["done_by"] = (antes.get("done_by") if mismo else "")
            if uid and not fila["done_at"]:
                avisar = uid
        prod["logistics"] = fila
        # ⚠️ Lo guardado dentro de la grabación de voces NO se borra: ahí solo queda lo PROPIO de esa
        # grabación (la dirección) y el pop-up de voces lee el estado de ESTA logística, que es la
        # única. `_disco_logistics` solo cae a lo de voces cuando aquí no hay nada, así que no puede
        # haber dos verdades.
        project.production_payload = prod
        project.updated_at = _now_madrid()
        if necesita == "NO" or not fila.get("user_id"):
            _notify_resolve(session_db, "DISCO_LOGISTICS", str(project.id))
            _notify_resolve(session_db, "DISCO_VOCALS", str(project.id))
        if avisar:
            notas = " · ".join(["%s: %s" % (lbl, (fila.get(k) or "").strip())
                                for k, lbl, _i, _p in DISCO_LOGISTICS_NOTES if (fila.get(k) or "").strip()])
            _disco_logistics_request(session_db, project, avisar, notas)
        session_db.commit()
        flash("Logística guardada." if necesita == "NO" or not avisar else "Logística solicitada.",
              "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[proyectos] no se pudo guardar la logística")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/contrato-productor", endpoint="disco_project_producer_contract")
@admin_required
def disco_project_producer_contract(project_id):
    """SUBIR EL CONTRATO DEL PRODUCTOR (lo hace Registros y Sello). Al subirlo, la tarea queda hecha
    para todos: para quien lo manda y para el sello que lleva el proyecto.

    ⚠️ No se exige `can_edit_discografica()`: lo hace Registros, que no tiene por qué poder editar
    discográfica. Se comprueba que sea de quien le toca (o dirección)."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        yo = str((_current_user_state() or {}).get("user_id") or "")
        if not (is_master() or can_edit_discografica()
                or yo in _registros_sello_user_ids(session_db)):
            return forbid("Este contrato lo manda Registros.")
        prod = _disco_prod(project)
        fila = dict(prod.get("producer_contract") or {})
        if _truthy(request.form.get("undo")):
            fila.pop("done_at", None); fila.pop("done_by", None)
            fila.pop("file_url", None); fila.pop("file_name", None)
            prod["producer_contract"] = fila
            project.production_payload = prod
            session_db.commit()
            flash("El contrato vuelve a estar pendiente.", "success")
            return redirect(safe_next_or(destino))
        doc = request.files.get("contract")
        if doc is not None and getattr(doc, "filename", ""):
            try:
                fila["file_url"] = upload_file(doc, "contratos-productor")
                fila["file_name"] = (doc.filename or "").strip()
            except Exception as exc:
                flash("No se pudo subir el contrato: %s" % exc, "danger")
                return redirect(safe_next_or(destino))
        estado = _current_user_state() or {}
        fila["done_at"] = _now_madrid().isoformat()
        fila["done_by"] = (estado.get("nick") or "")
        fila.setdefault("asked_at", _now_madrid().isoformat())
        prod["producer_contract"] = fila
        project.production_payload = prod
        _notify_resolve(session_db, "DISCO_PRODUCER_CONTRACT", str(project.id))
        # Quien lleva el proyecto se entera de que ya está mandado.
        try:
            _notify_users(session_db, _disco_project_owner_ids(session_db, project), "DISCOGRAFICA",
                          "Contrato de productor enviado · %s" % _disco_project_title(project),
                          "Ya está el contrato del productor.",
                          destino, ref_type="DISCO_PRODUCER_CONTRACT_OK", ref_id=str(project.id))
        except Exception:
            app.logger.exception("[proyectos] no se pudo avisar del contrato subido")
        session_db.commit()
        flash("Contrato del productor guardado.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[proyectos] no se pudo guardar el contrato del productor")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


@app.post("/discografica/proyectos/<project_id>/logistica/hecha", endpoint="disco_project_logistics_done")
@admin_required
def disco_project_logistics_done(project_id):
    """«Ya está montada»: lo marca QUIEN LA LLEVA (o el sello, o dirección) y el aviso se cierra solo.

    ⚠️ La persona de producción no tiene por qué poder editar discográfica, así que aquí no se exige
    `can_edit_discografica()`: se comprueba que es SUYA (o que es del sello o de dirección)."""
    session_db = db()
    destino = url_for("disco_project_detail", project_id=project_id, tab="calendario")
    try:
        project = _disco_project_or_404(session_db, project_id)
        if project is None:
            flash("Proyecto no encontrado.", "warning")
            return redirect(url_for("discografica_view", section="proyectos"))
        estado = _disco_logistics_state(session_db, project)
        yo = str((_current_user_state() or {}).get("user_id") or "")
        if not (estado["user_id"] == yo or is_master() or can_edit_discografica()):
            return forbid("Esta logística la lleva otra persona.")
        prod = _disco_prod(project)
        fila = dict(_disco_logistics(project))
        deshacer = _flag_arg("undo")
        fila["done_at"] = ("" if deshacer else _now_madrid().isoformat())
        fila["done_by"] = ("" if deshacer else ((_current_user_state() or {}).get("nick") or ""))
        prod["logistics"] = fila
        project.production_payload = prod
        project.updated_at = _now_madrid()
        if deshacer:
            if fila.get("user_id"):
                _notify_user(session_db, fila["user_id"], "PRODUCCION",
                             "Logística de %s" % _disco_project_title(project),
                             "Vuelve a estar pendiente.",
                             url_for("disco_project_detail", project_id=project.id, tab="calendario"),
                             ref_type="DISCO_LOGISTICS", ref_id=str(project.id))
        else:
            _notify_resolve(session_db, "DISCO_LOGISTICS", str(project.id))
        session_db.commit()
        flash("Logística pendiente otra vez." if deshacer else "Logística montada.", "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[proyectos] no se pudo marcar la logística")
        flash("No se pudo guardar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(destino))


