@app.post("/discografica/playlists/<playlist_id>/enviar", endpoint="playlist_send_email")
@admin_required
def playlist_send_email(playlist_id):
    """Manda la playlist por correo: asunto «Playlist <nombre>» y, dentro, su cabecera y ESCUCHAR."""
    session_db = db()
    try:
        pl = _playlist_or_404(session_db, playlist_id)
        destino = url_for("playlist_detail_view", playlist_id=pl.id)
        correos = (request.form.get("emails") or "").strip()
        if not correos:
            flash("Indica a quién se la mandamos.", "warning")
            return redirect(destino)
        ctx = _playlist_context(session_db, pl)
        session_db.commit()
        ok, error = _send_optional_email(correos, ctx["share_subject"],
                                         _playlist_email_html(ctx, note=(request.form.get("note") or "")))
        flash("Playlist enviada." if ok else "No se pudo enviar: %s" % (error or "error desconocido"),
              "success" if ok else "danger")
        return redirect(destino)
    except Exception as e:
        session_db.rollback()
        flash("No se pudo enviar la playlist: %s" % e, "danger")
        return redirect(url_for("discografica_view", section="playlists"))
    finally:
        session_db.close()


# ---------- Enlace público ----------

def _playlist_by_token(session_db, token):
    token = (token or "").strip()
    if not token:
        abort(404)
    pl = session_db.query(Playlist).filter(Playlist.public_token == token).first()
    if not pl:
        abort(404)
    return pl


@app.get("/playlist/<token>", endpoint="public_playlist_view")
def public_playlist_view(token):
    """La playlist por su enlace público (lo que se manda por correo, WhatsApp o SMS)."""
    with get_db() as session_db:
        pl = _playlist_by_token(session_db, token)
        ctx = _playlist_context(session_db, pl, token=token)
        ctx["og_image_url"] = _external_url_for("public_playlist_og_image", token=token)
        # Título y sublínea de la previsualización (mismo punto único que al compartir una demo).
        ctx["share_preview"] = _share_preview_meta(ctx.get("pl"), ctx.get("items"), is_demo=False)
        return render_template("public_playlist.html", **ctx)


@app.get("/playlist/<token>/audio/<item_id>", endpoint="public_playlist_audio")
def public_playlist_audio(token, item_id):
    with get_db() as session_db:
        pl = _playlist_by_token(session_db, token)
        item = _playlist_item_or_404(session_db, pl, item_id)
        url, _nombre = _playlist_item_audio_source(session_db, item)
    return _playlist_audio_response(url)


@app.get("/playlist/<token>/descargar/<item_id>", endpoint="public_playlist_download")
def public_playlist_download(token, item_id):
    with get_db() as session_db:
        pl = _playlist_by_token(session_db, token)
        item = _playlist_item_or_404(session_db, pl, item_id)
        return _playlist_download_response(session_db, pl, item, request.args.get("fmt"))


def _share_preview_meta(pl: dict | None, items: list | None, *, is_demo: bool) -> dict:
    """Qué se ve al compartir un enlace de PLAYLIST o de DEMO (título y sublínea).

    Punto único: lo usan la página pública (sus `og:`) y su miniatura, así que **la tarjeta de
    WhatsApp, la del SMS y el título del navegador dicen siempre lo mismo**.
    · demo     → «Demo · <nombre>» y debajo el ARTISTA (si se sabe).
    · playlist → «Playlist · <nombre>» y debajo CUÁNTOS TEMAS lleva.
    """
    pl = pl or {}
    items = items or []
    nombre = (pl.get("name") or "").strip()
    if is_demo:
        artista = ""
        for it in items:
            artista = (it.get("artist_name") or "").strip()
            if artista:
                break
        return {"title": ("Demo · %s" % nombre) if nombre else "Demo",
                "subtitle": artista}
    n = int(pl.get("songs_count") or 0)
    return {"title": ("Playlist · %s" % nombre) if nombre else "Playlist",
            "subtitle": ("%d tema%s" % (n, "" if n == 1 else "s")) if n else ""}


def _share_og_image_response(fuentes: list[str]):
    """Sirve la primera imagen que se pueda leer y, si ninguna vale, el LOGO del back office.

    ⚠️ Nunca un 404: en WhatsApp un 404 se ve como un enlace pelado."""
    for fuente in (fuentes or []):
        data = _og_image_jpeg_bytes(fuente)
        if data:
            return Response(data, mimetype="image/jpeg",
                            headers={"Cache-Control": "public, max-age=86400"})
    return redirect(url_for("og_default_image"))


@app.get("/playlist/<token>/og.jpg", endpoint="public_playlist_og_image")
def public_playlist_og_image(token):
    """La miniatura del enlace: la PORTADA de la playlist, la de sus temas, la FOTO DEL ARTISTA y,
    si no hay nada, el LOGO del back office (punto único `_share_og_image_response`)."""
    with get_db() as session_db:
        pl = _playlist_by_token(session_db, token)
        fuentes, song_ids, demo_ids = [], [], []
        portada = (pl.cover_url or "").strip()
        if portada:
            fuentes.append(portada)
        for item in _playlist_items_ordered(session_db, pl):
            tipo = (item.kind or "").strip().upper()
            if tipo == "SONG" and item.song_id:
                song_ids.append(item.song_id)
            elif tipo == "DEMO" and getattr(item, "demo_id", None):
                demo_ids.append(item.demo_id)

        def anadir(v):
            v = (v or "").strip()
            if v and v not in fuentes:
                fuentes.append(v)

        # ⚠️ En BLOQUE: una playlist puede tener decenas de temas y una consulta por cada uno para
        # la miniatura sería inaceptable. ⚠️ `Song` NO tiene `artist_id`: su artista va por
        # `SongArtist` (N:M).
        if song_ids:
            for (cover,) in session_db.query(Song.cover_url).filter(Song.id.in_(song_ids)).all():
                anadir(cover)
            for (foto,) in (session_db.query(Artist.photo_url)
                            .join(SongArtist, SongArtist.artist_id == Artist.id)
                            .filter(SongArtist.song_id.in_(song_ids)).all()):
                anadir(foto)
        if demo_ids:
            artist_ids = []
            for cover, aid in (session_db.query(SongDemo.cover_url, SongDemo.artist_id)
                               .filter(SongDemo.id.in_(demo_ids)).all()):
                anadir(cover)
                if aid:
                    artist_ids.append(aid)
            if artist_ids:
                for (foto,) in session_db.query(Artist.photo_url).filter(Artist.id.in_(artist_ids)).all():
                    anadir(foto)
    return _share_og_image_response(fuentes)


SONG_DELIVERY_SECTIONS = [
    ("PRODUCTION", "Información de producción"),
    ("AUTHORAL", "Información autoral"),
    ("LYRICS", "Letra"),
    # El TEXTO PARA EL PITCH: se puede pedir en el enlace, pero nace DESACTIVADO (no es lo normal).
    ("PITCH", "Texto para el pitch"),
    ("MASTERS", "Masters / materiales"),
]
SONG_DELIVERY_SECTION_KEYS = {k for k, _ in SONG_DELIVERY_SECTIONS}
SONG_DELIVERY_AUTHOR_ROLES = [("AUTHOR", "Autor"), ("COMPOSER", "Compositor"), ("AUTHOR_COMPOSER", "Autor y compositor")]
# Campos de producción: (clave, etiqueta, obligatorio)
SONG_DELIVERY_PRODUCTION_FIELDS = [
    ("duration", "Duración (Timing)", True),
    ("bpm", "BPM", True),
    ("recording_date", "Fecha de grabación", True),
    ("studio", "Estudio de grabación", True),
    ("producer", "Productor", True),
    ("arranger", "Arreglista", False),
    ("recording_engineer", "Ingeniero de grabación", True),
    ("mixing_engineer", "Ingeniero de mezcla", False),
    ("mastering_engineer", "Ingeniero de masterización", True),
    ("musicians", "Músicos (instrumento y nombre)", False),
]
SONG_DELIVERY_MATERIAL_SPECS = [
    ("master_48", "MASTER", "MASTER_48"),
    ("master_24", "MASTER", "MASTER_24"),
    ("master_16", "MASTER", "MASTER_16"),
    ("instrumental", "INSTRUMENTAL", "DEFAULT"),
    ("tv_track", "TV_TRACK", "DEFAULT"),
]
# Módulos de material solicitables (claves en materials_json); incluye stems aparte de los slots fijos.
# ⚠️ La PORTADA es una IMAGEN, no un .wav: va aquí para poder pedirla, pero se sube y se valida por su
# propio camino (no entra en `SONG_DELIVERY_MATERIAL_SPECS`, que es la lista de audios) y nace
# DESACTIVADA.
SONG_DELIVERY_MATERIAL_MODULES = [
    ("cover", "Portada"),
    ("master_48", "Master 48 bits"),
    ("master_24", "Master 24 bits"),
    ("master_16", "Master 16 bits"),
    ("instrumental", "Instrumental"),
    ("tv_track", "TV Track"),
    ("stems", "Stems"),
]
SONG_DELIVERY_MATERIAL_MODULE_KEYS = {k for k, _ in SONG_DELIVERY_MATERIAL_MODULES}
# Módulos que se pedían ANTES de que existieran los nuevos: es lo que se le supone a un enlace
# antiguo (sin `materials_json`), para que se comporte exactamente como se generó.
SONG_DELIVERY_LEGACY_MATERIALS = ["master_48", "master_24", "master_16", "instrumental", "tv_track", "stems"]
# Los que NACEN DESACTIVADOS al generar un enlace (se piden solo si se marcan a mano).
SONG_DELIVERY_OFF_BY_DEFAULT = {"mat.cover", "pitch"}
# Imágenes válidas para la portada.
SONG_DELIVERY_COVER_EXTS = {".jpg", ".jpeg", ".png", ".webp"}


# ---------------------------------------------------------------------------
# ENTREGA DE MASTERS · QUÉ se pide y QUÉ es obligatorio (campo a campo)
# ---------------------------------------------------------------------------
# Catálogo ÚNICO de lo que se puede pedir en el enlace. Lo usan la pantalla de configuración (una
# fila por campo con «se pide» y «obligatorio»), el formulario público y su validación: añadir un
# campo aquí lo añade en los tres sitios.
def _song_delivery_askable() -> list[dict]:
    filas = []
    for key, label, req in SONG_DELIVERY_PRODUCTION_FIELDS:
        filas.append({"key": "prod." + key, "section": "PRODUCTION", "label": label,
                      "ask": True, "required": bool(req)})
    filas.append({"key": "authoral", "section": "AUTHORAL", "label": "Autores, roles y porcentajes",
                  "ask": True, "required": True})
    filas.append({"key": "lyrics", "section": "LYRICS", "label": "Letra de la canción",
                  "ask": True, "required": True})
    # TEXTO PARA EL PITCH: desactivado por defecto.
    filas.append({"key": "pitch", "section": "PITCH", "label": "Texto para el pitch",
                  "ask": False, "required": False})
    for key, label in SONG_DELIVERY_MATERIAL_MODULES:
        apagado = ("mat." + key) in SONG_DELIVERY_OFF_BY_DEFAULT
        filas.append({"key": "mat." + key, "section": "MASTERS", "label": label,
                      "ask": not apagado,
                      "required": (key != "stems") and not apagado})
    return filas


def _song_delivery_prefill(session_db, song, conf) -> tuple[dict, dict]:
    """Lo que YA ESTÁ en la ficha, para que el formulario de entrega salga relleno.

    Devuelve `(form, hecho)`: los valores con los nombres que espera la plantilla y qué está ya
    cumplimentado (para marcarlo a la vista). ⚠️ **Solo de lo que ESE enlace pide**: lo que no se
    haya marcado al crearlo ni se muestra ni se rellena, como hasta ahora."""
    form, hecho = {}, {}
    pide = lambda k: bool((conf.get(k) or {}).get("ask"))

    def pon(clave, valor):
        v = ("" if valor is None else str(valor)).strip()
        # ⚠️ «—» es lo que devuelven los formateadores de la casa cuando NO hay dato
        # (`_seconds_to_timecode(None)`): eso no es un valor y no puede salir en el formulario.
        if v in ("—", "-"):
            v = ""
        if v:
            form[clave] = v
        return bool(v)

    # ---- Producción: lo que ya tiene la canción en su ficha ----
    if pide("prod.duration"):
        hecho["prod.duration"] = pon("prod_duration",
                                     _seconds_to_timecode(getattr(song, "duration_seconds", None)))
    if pide("prod.bpm"):
        hecho["prod.bpm"] = pon("prod_bpm", getattr(song, "bpm", None) or "")
    if pide("prod.recording_date"):
        rd = getattr(song, "recording_date", None)
        hecho["prod.recording_date"] = pon("prod_recording_date", rd.isoformat() if rd else "")
    for clave, campo in (("prod.studio", "studio"),
                         ("prod.recording_engineer", "recording_engineer"),
                         ("prod.mixing_engineer", "mixing_engineer"),
                         ("prod.mastering_engineer", "mastering_engineer")):
        if pide(clave):
            hecho[clave] = pon("prod_" + clave[5:], getattr(song, campo, None))
    for clave, campo in (("prod.producer", "producers"), ("prod.arranger", "arrangers"),
                         ("prod.musicians", "musicians")):
        if pide(clave):
            lista = [x for x in (getattr(song, campo, None) or []) if (x or "").strip()]
            sep = "\n" if clave == "prod.musicians" else ", "
            hecho[clave] = pon("prod_" + clave[5:], sep.join(lista))
    # El PRODUCTOR es un tercero: si su ficha lo tiene apuntado, se deja elegido.
    if pide("prod.producer"):
        try:
            pid = getattr(song, "producer_promoter_id", None)
            if pid:
                pr = session_db.get(Promoter, pid)
                if pr is not None:
                    form["prod_producer"] = _delivery_promoter_label(pr)
                    form["prod_producer_promoter_id"] = str(pr.id)
                    hecho["prod.producer"] = True
        except Exception:
            pass

    # ---- Letra y pitch ----
    if pide("lyrics"):
        hecho["lyrics"] = pon("lyrics", getattr(song, "lyrics_text", None))
    if pide("pitch"):
        # ⚠️ El pitch puede llevar formato (negrita…): en un `<textarea>` va SIN él.
        hecho["pitch"] = pon("pitch", _pitch_plain_text(getattr(song, "pitch_text", None) or ""))

    # ---- Autoría: los autores que ya están registrados ----
    autores = []
    if pide("authoral"):
        try:
            for sh in (session_db.query(SongEditorialShare)
                       .options(joinedload(SongEditorialShare.promoter))
                       .filter(SongEditorialShare.song_id == song.id)
                       .order_by(SongEditorialShare.pct.desc()).all()):
                ed = _share_publisher(sh)
                autores.append({
                    "name": _promoter_display_name(getattr(sh, "promoter", None)) or "",
                    "promoter_id": (str(sh.promoter_id) if getattr(sh, "promoter_id", None) else ""),
                    "editorial": (getattr(ed, "name", "") or ""),
                    "publishing_id": (str(getattr(ed, "id", "")) if ed is not None else ""),
                    "role": (getattr(sh, "role", "") or ""),
                    "pct": _fmt_pct_es(getattr(sh, "pct", 0)),
                })
        except Exception:
            app.logger.exception("[entrega] no se pudieron leer los autores ya registrados")
        hecho["authoral"] = bool(autores)
    form["_authors"] = autores

    # ---- Materiales ya subidos (un `<input file>` no se puede rellenar: se DICE que ya está) ----
    try:
        subidos = {}
        for m in (session_db.query(SongMaterial)
                  .filter(SongMaterial.song_id == song.id).all()):
            cat = (getattr(m, "category", "") or "").upper()
            slot = (getattr(m, "slot_key", "") or "").upper()
            if not (getattr(m, "file_url", None) or "").strip():
                continue
            subidos[(cat, slot)] = (getattr(m, "file_name", None) or "").strip() or "Ya subido"
        for campo, cat, slot in SONG_DELIVERY_MATERIAL_SPECS:
            if pide("mat." + campo) and (cat, slot) in subidos:
                hecho["mat." + campo] = subidos[(cat, slot)]
        if pide("mat.stems") and any(c == "STEMS" for c, _s in subidos):
            hecho["mat.stems"] = "Ya subidos"
        if pide("mat.cover") and ((getattr(song, "cover_url", None) or "").strip()
                                  or ("COVER", "COVER") in subidos):
            hecho["mat.cover"] = "Ya subida"
    except Exception:
        app.logger.exception("[entrega] no se pudieron leer los materiales ya subidos")
    return form, hecho


def _song_delivery_config(link) -> dict:
    """Qué se pide y qué es obligatorio en ESTE enlace: {clave: {"ask", "required", ...}}.

    Los enlaces ANTIGUOS no traen `fields_json`: se reconstruye de sus secciones y materiales, con lo
    que se comportan exactamente como antes."""
    guardado = _json_dict(getattr(link, "fields_json", None)) if link is not None else {}
    secciones = set(getattr(link, "sections_json", None) or []) if link is not None else set()
    materiales = list(getattr(link, "materials_json", None) or []) if link is not None else []
    if "MASTERS" in secciones and not materiales:
        # Compat enlaces antiguos: pedían los materiales que existían entonces (la portada NO).
        materiales = list(SONG_DELIVERY_LEGACY_MATERIALS)
    out = {}
    for fila in _song_delivery_askable():
        conf = dict(fila)
        crudo = guardado.get(fila["key"]) if isinstance(guardado, dict) else None
        if isinstance(crudo, dict):
            conf["ask"] = bool(crudo.get("ask"))
            conf["required"] = bool(crudo.get("required")) and conf["ask"]
        else:
            # Sin configuración por campo: manda lo que se pidió por secciones/materiales.
            if fila["section"] not in secciones:
                conf["ask"] = False
            elif fila["key"].startswith("mat."):
                conf["ask"] = fila["key"][4:] in materiales
            conf["required"] = bool(conf["required"]) and conf["ask"]
        out[fila["key"]] = conf
    return out


def _song_delivery_config_from_form(form) -> tuple[dict, list, list]:
    """Lee la configuración del formulario de creación y devuelve
    (fields_json, secciones, módulos de material) — las tres cosas coherentes entre sí."""
    conf, secciones, materiales = {}, [], []
    for fila in _song_delivery_askable():
        # El interruptor de TRES posiciones manda un solo valor: 0 no se pide · 1 se pide ·
        # 2 obligatorio. (Se siguen aceptando las dos casillas de antes por si queda alguna
        # pantalla vieja abierta en un navegador.)
        crudo = (form.get("mode_" + fila["key"]) or "").strip()
        if crudo:
            modo = _safe_int(crudo)
            pide, obliga = modo >= 1, modo >= 2
        else:
            pide = bool(form.get("ask_" + fila["key"]))
            obliga = pide and bool(form.get("req_" + fila["key"]))
        conf[fila["key"]] = {"ask": pide, "required": obliga}
        if not pide:
            continue
        if fila["section"] not in secciones:
            secciones.append(fila["section"])
        if fila["key"].startswith("mat."):
            materiales.append(fila["key"][4:])
    # Se respeta el orden del catálogo de secciones (la pantalla pública lo usa).
    secciones = [k for k, _ in SONG_DELIVERY_SECTIONS if k in secciones]
    return conf, secciones, materiales


# ═════════════════════════════════════════════════════════════════════════════
# ENTREGA DE MASTERS · REVISAR Y VALIDAR lo que ha llegado
#
# Cuando un tercero entrega los materiales por su enlace, eso es TRABAJO para dentro: hay que
# revisarlos y validarlos uno a uno. Por eso al recibirlos:
#   · se avisa (campanita + push + SMS si está encendido) a **REGISTROS y al SELLO** diciendo QUIÉN
#     ha subido los masters de QUÉ canción, con su foto o su logo; y
#   · les sale la **tarea pendiente** en Inicio, que **no se cierra hasta que la entrega está
#     COMPLETA**: si se rechaza un material, sigue faltando y la tarea se queda.
#
# Punto ÚNICO del estado: `_song_delivery_review_state`. Lo usan el módulo de Inicio, el cuadro de
# dirección y los cuatro caminos que revisan (validar un material, validar los stems, consolidar una
# sección y descartarla), que es donde se cierra el aviso solo (la regla de `_notify_resolve`).
# ⚠️ El estado se MIRA, no se guarda: así no puede quedar desparejado del material de verdad.
# ═════════════════════════════════════════════════════════════════════════════

# Las secciones de DATOS que pueden quedar por consolidar (viven en `link.data` y se van al
# consolidarlas o descartarlas).
SONG_DELIVERY_DATA_SECTIONS = (
    ("production", "Información de producción"),
    ("authoral", "Información autoral"),
    ("lyrics", "Letra"),
    ("pitch", "Texto para el pitch"),
)
# (categoría, slot) → módulo del enlace, para saber QUÉ se ha rechazado.
_SONG_DELIVERY_FIELD_BY_SLOT = {(cat, slot): field for field, cat, slot in SONG_DELIVERY_MATERIAL_SPECS}
SONG_DELIVERY_MATERIAL_MODULE_LABELS = dict(SONG_DELIVERY_MATERIAL_MODULES)


def _song_delivery_material_field(material) -> str:
    """Qué módulo del enlace es este material («master_48», «cover», «stems»…), o "" si no es de
    ninguno (un subproducto, p. ej.)."""
    cat = (getattr(material, "category", "") or "").upper()
    slot = (getattr(material, "slot_key", "") or "DEFAULT").upper()
    if cat == "COVER":
        return "cover"
    if cat == "STEMS":
        return "stems"
    return _SONG_DELIVERY_FIELD_BY_SLOT.get((cat, slot), "")


def _song_delivery_field_has_validated(session_db, song_id, field: str) -> bool:
    """¿Hay YA un material VALIDADO de ese módulo en la canción? (o sea: el rechazo está resuelto)."""
    field = (field or "").strip()
    if not field:
        return True
    if field == "cover":
        pares = [("COVER", None)]
    elif field == "stems":
        pares = [("STEMS", None)]
    else:
        pares = [(cat, slot) for f, cat, slot in SONG_DELIVERY_MATERIAL_SPECS if f == field]
    for cat, slot in pares:
        q = (session_db.query(func.count(SongMaterial.id))
             .filter(SongMaterial.song_id == song_id)
             .filter(func.upper(SongMaterial.category) == cat)
             .filter(func.upper(func.coalesce(SongMaterial.validation_status, "VALIDATED")) != "PENDING"))
        if slot:
            q = q.filter(func.upper(func.coalesce(SongMaterial.slot_key, "DEFAULT")) == slot)
        if int(q.scalar() or 0) > 0:
            return True
    return False


def _song_delivery_mark_rejected(session_db, material) -> None:
    """Apunta en la ENTREGA que ese material se ha rechazado.

    ⚠️ Sin esto, rechazar un master haría desaparecer la tarea (ya no queda nada «pendiente de
    validar») cuando en realidad falta justo eso. Se apunta en el enlace, no en la canción, para no
    resucitar trabajo de entregas viejas ya cerradas."""
    link_id = getattr(material, "delivery_link_id", None)
    if not link_id:
        return
    try:
        link = session_db.get(SongMasterDeliveryLink, link_id)
        if link is None:
            return
        field = _song_delivery_material_field(material)
        if not field:
            return
        data = dict(link.data or {})
        rechazados = dict(data.get("rejected") or {})
        rechazados[field] = {
            "label": SONG_DELIVERY_MATERIAL_MODULE_LABELS.get(field, field),
            "at": _now_madrid().isoformat(),
            "by": ((_current_user_state() or {}).get("nick") or ""),
        }
        data["rejected"] = rechazados
        link.data = data
        session_db.add(link)
    except Exception:
        app.logger.exception("[entrega-masters] no se pudo apuntar el rechazo del material")


def _song_delivery_review_state(session_db, link, *, pending_map=None) -> dict:
    """QUÉ QUEDA por revisar de una entrega. Punto único.

    Devuelve `pending` (materiales sin validar), `sections` (datos sin consolidar), `rejected` (lo que
    se rechazó y todavía no se ha repuesto), `missing_labels` y `done`.
    `pending_map` es el recuento de TODAS las entregas hecho de una vez (`_song_delivery_pending_map`):
    con él, mirar 50 entregas no son 50 consultas."""
    vacio = {"pending": 0, "sections": [], "rejected": [], "missing_labels": [], "done": True}
    if link is None:
        return vacio
    if pending_map is not None:
        pendientes = int(pending_map.get(str(link.id), 0))
    else:
        try:
            pendientes = int(session_db.query(func.count(SongMaterial.id))
                             .filter(SongMaterial.delivery_link_id == link.id)
                             .filter(func.upper(func.coalesce(SongMaterial.validation_status, "VALIDATED"))
                                     == "PENDING").scalar() or 0)
        except Exception:
            pendientes = 0
    data = link.data if isinstance(link.data, dict) else {}
    secciones = []
    for clave, etiqueta in SONG_DELIVERY_DATA_SECTIONS:
        valor = data.get(clave)
        if isinstance(valor, str):
            valor = valor.strip()
        if valor:
            secciones.append({"key": clave, "label": etiqueta})
    rechazados = []
    for field, info in (data.get("rejected") or {}).items():
        if _song_delivery_field_has_validated(session_db, link.song_id, field):
            continue          # ya se ha vuelto a subir y validar: resuelto
        rechazados.append({"field": field,
                           "label": (info or {}).get("label") or
                                    SONG_DELIVERY_MATERIAL_MODULE_LABELS.get(field, field)})
    etiquetas = []
    if pendientes:
        etiquetas.append("%d archivo%s por validar" % (pendientes, "" if pendientes == 1 else "s"))
    if rechazados:
        etiquetas.append("falta " + ", ".join(r["label"] for r in rechazados))
    if secciones:
        etiquetas.append("%d dato%s por consolidar" % (len(secciones), "" if len(secciones) == 1 else "s"))
    return {"pending": pendientes, "sections": secciones, "rejected": rechazados,
            "missing_labels": etiquetas,
            "done": not (pendientes or secciones or rechazados)}


def _song_delivery_pending_map(session_db) -> dict:
    """Cuántos materiales SIN VALIDAR tiene cada entrega, en UNA consulta agrupada."""
    try:
        filas = (session_db.query(SongMaterial.delivery_link_id, func.count(SongMaterial.id))
                 .filter(SongMaterial.delivery_link_id.isnot(None))
                 .filter(func.upper(func.coalesce(SongMaterial.validation_status, "VALIDATED"))
                         == "PENDING")
                 .group_by(SongMaterial.delivery_link_id).all())
        return {str(lid): int(n or 0) for lid, n in filas}
    except Exception:
        app.logger.exception("[entrega-masters] no se pudo contar lo pendiente de validar")
        return {}


def _song_delivery_open_links(session_db, song_id=None):
    """Las entregas RECIBIDAS que todavía tienen algo por revisar (todas, o las de una canción)."""
    q = (session_db.query(SongMasterDeliveryLink)
         .filter(SongMasterDeliveryLink.status == "SUBMITTED"))
    if song_id is not None:
        q = q.filter(SongMasterDeliveryLink.song_id == song_id)
    pendientes = _song_delivery_pending_map(session_db)
    salida = []
    for link in q.order_by(SongMasterDeliveryLink.submitted_at.desc().nullslast()).limit(300).all():
        estado = _song_delivery_review_state(session_db, link, pending_map=pendientes)
        if not estado["done"]:
            salida.append((link, estado))
    return salida


def _song_delivery_review_close(session_db, link) -> bool:
    """Si la entrega ya está COMPLETA, su aviso deja de esperar a nadie y se cierra solo."""
    if link is None:
        return False
    estado = _song_delivery_review_state(session_db, link)
    if estado["done"]:
        _notify_resolve(session_db, "SONG_DELIVERY", str(link.id))
        return True
    return False


def _song_delivery_review_close_for_song(session_db, song_id) -> None:
    """Lo mismo, para TODAS las entregas de una canción (al validar un material no se sabe de cuál
    era si venía de una entrega antigua)."""
    try:
        for link in (session_db.query(SongMasterDeliveryLink)
                     .filter(SongMasterDeliveryLink.song_id == song_id,
                             SongMasterDeliveryLink.status == "SUBMITTED").all()):
            _song_delivery_review_close(session_db, link)
    except Exception:
        app.logger.exception("[entrega-masters] no se pudo cerrar el aviso de la entrega")


def _song_delivery_submitter(session_db, link, data) -> dict:
    """QUIÉN ha entregado: nombre y foto (o logo) para que el aviso enseñe su cara.

    Manda lo que se APUNTÓ AL RECIBIRLA (`data['submitted_by']`); si no, el PRODUCTOR indicado en la
    entrega (es un tercero de la base, así que tiene ficha y foto), a quien se le mandó el enlace
    (`target_name`) y, en último caso, el artista.
    ⚠️ Se apunta al recibirla porque los datos de producción SE VAN al consolidarlos: sin eso, en
    cuanto alguien consolida la sección, el aviso y la tarea dejaban de decir quién había subido los
    masters (bug real, lo sacó la prueba).
    ⚠️ Un tercero NO tiene `photo_url` ni `name`: son `logo_url` y `nick`/`first_name`+`last_name`."""
    guardado = (data or {}).get("submitted_by") if isinstance(data, dict) else None
    if isinstance(guardado, dict) and (guardado.get("name") or "").strip():
        return {"name": guardado["name"].strip(), "photo_url": (guardado.get("photo_url") or "").strip()}
    nombre, foto = "", ""
    try:
        prod = ((data or {}).get("production") or {}) if isinstance(data, dict) else {}
        pid = (prod.get("producer_promoter_id") or "").strip() if isinstance(prod, dict) else ""
        if pid:
            pr = session_db.get(Promoter, to_uuid(pid))
            if pr is not None:
                nombre = _promoter_display_name(pr)
                # ⚠️ Un tercero NO tiene `photo_url`: su foto (o su logo, si es empresa) es `logo_url`.
                foto = (getattr(pr, "logo_url", None) or "").strip()
        if not nombre and isinstance(prod, dict):
            nombre = (prod.get("producer") or "").strip()
    except Exception:
        app.logger.exception("[entrega-masters] no se pudo resolver quién ha entregado")
    if not nombre:
        nombre = (getattr(link, "target_name", None) or "").strip()
    if not nombre:
        try:
            song = session_db.get(Song, link.song_id)
            nombre = _song_artist_names_str(song) if song else ""
        except Exception:
            nombre = ""
    return {"name": (nombre or "Alguien de fuera"), "photo_url": foto}


def _song_delivery_review_recipients(session_db, song) -> list[str]:
    """A quién le toca revisar: **REGISTROS y el SELLO**.

    Del sello, quien lleve a ese artista en su faceta (`assigned_artist_ids_sello`) y, si no lo tiene
    nadie apuntado, todo el departamento — mejor que lo miren varios que dejarlo sin dueño (el mismo
    criterio que el pitch)."""
    quienes = list(_registros_user_ids(session_db) or [])
    try:
        artista = _song_primary_artist(session_db, song)
        if artista is not None:
            quienes += list(_pitch_sello_user_ids(session_db, artista.id) or [])
        else:
            quienes += list(_department_user_ids(session_db, "Sello") or [])
    except Exception:
        app.logger.exception("[entrega-masters] no se pudo resolver a quién avisar")
    return list(dict.fromkeys([str(x) for x in quienes if x]))


def _song_delivery_notify_submitted(session_db, link, song, data) -> int:
    """«X ha subido los masters de «Canción»» → a Registros y al Sello, con la cara de quien ha sido.

    El aviso queda atado a la entrega (`ref_type='SONG_DELIVERY'`), así que se cierra solo en cuanto
    la revisión está completa."""
    try:
        quien = _song_delivery_submitter(session_db, link, data)
        estado = _song_delivery_review_state(session_db, link)
        titulo = "%s ha subido los masters de «%s»" % (quien["name"], (song.title or "").strip())
        cuerpo = "Hay que revisarlos y validarlos"
        if estado["missing_labels"]:
            cuerpo += ": " + " · ".join(estado["missing_labels"])
        cuerpo += "."
        return _notify_users(
            session_db, _song_delivery_review_recipients(session_db, song), "MATERIALES",
            titulo, cuerpo,
            url_for("discografica_song_detail", song_id=song.id, tab="materiales"),
            ref_type="SONG_DELIVERY", ref_id=str(link.id),
            actor_name=quien["name"], actor_photo=quien["photo_url"],
        )
    except Exception:
        app.logger.exception("[entrega-masters] no se pudo avisar de la entrega recibida")
        return 0


def _song_delivery_share_context(session_db, song) -> dict:
    """Lo que enseña la PREVISUALIZACIÓN del enlace de entrega (WhatsApp, correo, redes): la portada,
    el título «Entrega de masters», el nombre de la canción y, debajo, el artista — con los
    INTÉRPRETES si hay alguno más aparte del artista."""
    artistas = _song_artist_names_str(song)
    nombres = [artistas] if artistas and artistas != "—" else []
    try:
        filas = _song_interpreter_rows_map(session_db, [song.id]).get(str(song.id)) or []
        conocidos = {(_norm_person_name_key(n) if n else "") for n in
                     [getattr(a, "name", "") for a in (getattr(song, "artists", None) or [])]}
        extra = [f.name for f in filas
                 if (f.name or "").strip() and _norm_person_name_key(f.name) not in conocidos]
        if extra:
            nombres.append(", ".join(dict.fromkeys(extra)))
    except Exception:
        pass
    colab = (getattr(song, "collaborator", None) or "").strip()
    if colab:
        nombres.append("con " + colab)
    portada = (getattr(song, "cover_url", None) or "").strip()
    if not portada:
        for a in (getattr(song, "artists", None) or []):
            if (getattr(a, "photo_url", None) or "").strip():
                portada = a.photo_url.strip()
                break
    return {
        "title": "Entrega de masters · %s" % (song.title or "").strip(),
        "subtitle": " · ".join([x for x in nombres if x]),
        "cover_url": portada,
    }


_SONG_DELIVERY_OG_CACHE: dict = {}


@app.get("/entrega-masters/<token>/og.jpg", endpoint="public_song_delivery_og_image")
def public_song_delivery_og_image(token):
    """Miniatura del enlace de entrega: la PORTADA de la canción (y si no hay, la foto del artista),
    a 1200×630 y servida desde NUESTRO dominio, como el resto de previsualizaciones."""
    session_db = db()
    try:
        link = session_db.query(SongMasterDeliveryLink).filter(
            SongMasterDeliveryLink.token == (token or "").strip()).first()
        song = session_db.get(Song, link.song_id) if link else None
        if not song:
            abort(404)
        ctx = _song_delivery_share_context(session_db, song)
        src = (ctx.get("cover_url") or "").strip() or url_for("static", filename="img/logo.png")
    finally:
        session_db.close()
    guardado = _SONG_DELIVERY_OG_CACHE.get(token)
    data = guardado[1] if (guardado and guardado[0] == src) else None
    if data is None:
        data = _og_image_jpeg_bytes(src if src.startswith("/static/") else _absolute_media_url(src))
        if data:
            if len(_SONG_DELIVERY_OG_CACHE) > 200:
                _SONG_DELIVERY_OG_CACHE.clear()
            _SONG_DELIVERY_OG_CACHE[token] = (src, data)
    if not data:
        return redirect(_absolute_media_url(src))
    resp = send_file(BytesIO(data), mimetype="image/jpeg")
    resp.headers["Cache-Control"] = "public, max-age=21600"
    return resp


def _song_delivery_public_url(link) -> str:
    return _external_url_for("public_song_master_delivery", token=link.token)


def _song_artist_names_str(song) -> str:
    names = [getattr(a, "name", None) for a in (getattr(song, "artists", None) or [])]
    return ", ".join([n for n in names if n]) or "—"


@app.post("/discografica/canciones/<song_id>/entrega/crear")
@admin_required
def discografica_song_delivery_create(song_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para generar enlaces de entrega.")
    # QUÉ se pide y QUÉ es obligatorio, campo a campo (la pantalla enseña una fila por campo con sus
    # dos casillas). De ahí salen también las secciones y los materiales, para que todo cuadre.
    conf_campos, sections, materials = _song_delivery_config_from_form(request.form)
    if not sections:
        flash("Marca al menos un dato o material que quieras pedir.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))
        # Un único enlace activo por canción: anula los anteriores.
        for old in session_db.query(SongMasterDeliveryLink).filter(
            SongMasterDeliveryLink.song_id == song.id, SongMasterDeliveryLink.status == "ACTIVE"
        ).all():
            old.status = "CANCELLED"
            old.cancelled_at = datetime.now(TZ_MADRID)
            session_db.add(old)
        uid = session.get("user_id")
        link = SongMasterDeliveryLink(
            song_id=song.id,
            token=uuid.uuid4().hex,
            sections_json=sections,
            materials_json=materials,
            fields_json=conf_campos,
            status="ACTIVE",
            data={},
            requested_by_user_id=to_uuid(uid) if uid else None,
            requested_by_nick=(_current_user_state() or {}).get("nick"),
            target_name=(request.form.get("target_name") or "").strip() or None,
            target_email=(request.form.get("target_email") or "").strip() or None,
        )
        session_db.add(link)
        session_db.commit()
        pub = _song_delivery_public_url(link)
        flash(Markup('Enlace de entrega generado. Cópialo o envíalo por correo abajo.'), "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error generando el enlace: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales", delivery_created=1))


@app.post("/discografica/canciones/<song_id>/entrega/<link_id>/anular")
@admin_required
def discografica_song_delivery_cancel(song_id, link_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    session_db = db()
    try:
        link = session_db.get(SongMasterDeliveryLink, to_uuid(link_id))
        if link and str(link.song_id) == str(to_uuid(song_id)):
            link.status = "CANCELLED"
            link.cancelled_at = datetime.now(TZ_MADRID)
            session_db.add(link)
            session_db.commit()
            flash("Enlace de entrega anulado.", "success")
        else:
            flash("Enlace no encontrado.", "warning")
    except Exception as e:
        session_db.rollback()
        flash(f"Error anulando el enlace: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


@app.get("/api/promoters/<promoter_id>/emails", endpoint="api_promoter_emails")
@admin_required
def api_promoter_emails(promoter_id):
    session_db = db()
    try:
        p = session_db.get(Promoter, to_uuid(promoter_id))
        if not p:
            return jsonify([])
        out, seen = [], set()

        def _add(email, label):
            email = (email or "").strip()
            if not email or email.lower() in seen:
                return
            seen.add(email.lower())
            out.append({"email": email, "label": label})

        _add(getattr(p, "contact_email", None), "Principal")
        for e in session_db.query(PromoterEmail).filter(PromoterEmail.promoter_id == p.id).order_by(PromoterEmail.created_at.asc()).all():
            _add(getattr(e, "email", None), (getattr(e, "concept", None) or "Email"))
        for c in session_db.query(PromoterContact).filter(PromoterContact.promoter_id == p.id, PromoterContact.email.isnot(None)).order_by(PromoterContact.created_at.asc()).all():
            _add(getattr(c, "email", None), _promoter_contact_name(c) or "Contacto")
        return jsonify(out)
    finally:
        session_db.close()


# ==================== CONTACTOS DE LA ACTIVIDAD (producción / ticketing / comunicación) ====================
# La persona de contacto es un `PromoterContact`: al asignarla a una actividad queda vinculada a su
# tercero. Una misma persona puede cubrir varias funciones — se guarda UNA fila con varios roles.

CONCERT_CONTACT_ROLES = [
    ("PRODUCCION", "Producción", "fa-sliders"),
    ("TICKETING", "Ticketing", "fa-ticket"),
    ("COMUNICACION", "Comunicación", "fa-bullhorn"),
]
CONCERT_CONTACT_ROLE_KEYS = [k for k, _l, _i in CONCERT_CONTACT_ROLES]
CONCERT_CONTACT_ROLE_META = {k: {"label": l, "icon": i} for k, l, i in CONCERT_CONTACT_ROLES}


def _promoter_email_phone(promoter) -> tuple[str, str]:
    """El CORREO y el TELÉFONO de un tercero. Punto único.

    ⚠️⚠️ En `Promoter` esos campos se llaman **`contact_email`** y **`contact_phone`**: `p.email` y
    `p.phone` **no existen**, así que un `getattr(p, "email", "")` devuelve siempre "" y el aviso no
    le llega a nadie **sin dar ningún error** (bug real: el productor no recibía el plazo de entrega
    y al tercero de la portada no se le mandaba la solicitud)."""
    if promoter is None:
        return "", ""
    correo = (getattr(promoter, "contact_email", None) or getattr(promoter, "email", None) or "").strip()
    telefono = (getattr(promoter, "contact_phone", None) or getattr(promoter, "phone", None) or "").strip()
    return correo, telefono


def _promoter_contact_name(contact) -> str:
    if contact is None:
        return ""
    parts = [(getattr(contact, "first_name", None) or "").strip(),
             (getattr(contact, "last_name", None) or "").strip()]
    name = " ".join([p for p in parts if p]).strip()
    return name or (getattr(contact, "title", None) or "").strip()


def _promoter_contact_payload(contact, promoter=None) -> dict:
    promoter = promoter if promoter is not None else getattr(contact, "promoter", None)
    return {
        "id": str(contact.id),
        "name": _promoter_contact_name(contact),
        "title": (getattr(contact, "title", None) or "").strip(),
        "email": (getattr(contact, "email", None) or "").strip(),
        "phone": (getattr(contact, "phone", None) or getattr(contact, "mobile", None) or "").strip(),
        "promoter_id": (str(contact.promoter_id) if contact.promoter_id else ""),
        "promoter_name": ((getattr(promoter, "nick", None) or "").strip() if promoter is not None else ""),
    }


def _promoter_contacts_for(session_db, promoter_id) -> list[dict]:
    if not promoter_id:
        return []
    rows = (
        session_db.query(PromoterContact)
        .filter(PromoterContact.promoter_id == promoter_id)
        .order_by(PromoterContact.created_at.asc())
        .all()
    )
    return [_promoter_contact_payload(c) for c in rows]


def _similar_promoter_contacts(session_db, name: str, email: str = "", phone: str = "",
                               limit: int = 6) -> list[dict]:
    """Personas que se parecen a la que se va a crear, para no duplicar.

    Se mira en TODOS los terceros, no solo en el de la actividad: la misma persona puede estar ya
    dada de alta colgando de otra empresa y lo que interesa es poder reutilizarla."""
    name_key = _norm_text_key(name)
    email_key = (email or "").strip().lower()
    phone_key = re.sub(r"\D+", "", phone or "")
    if not name_key and not email_key and not phone_key:
        return []
    conds = []
    if email_key:
        conds.append(func.lower(func.coalesce(PromoterContact.email, "")) == email_key)
    if name_key:
        # Primer apellido/nombre suelto ya vale como pista; el filtro fino se hace en Python.
        for token in name_key.split()[:2]:
            if len(token) >= 3:
                conds.append(_sa_contains_text(PromoterContact.first_name, token))
                conds.append(_sa_contains_text(PromoterContact.last_name, token))
    if not conds:
        conds.append(PromoterContact.phone.isnot(None))
    rows = (
        session_db.query(PromoterContact)
        .options(joinedload(PromoterContact.promoter))
        .filter(or_(*conds))
        .limit(60)
        .all()
    )
    out = []
    for c in rows:
        cand_name = _norm_text_key(_promoter_contact_name(c))
        cand_email = (c.email or "").strip().lower()
        cand_phone = re.sub(r"\D+", "", (c.phone or "") + (c.mobile or ""))
        same_email = bool(email_key and cand_email == email_key)
        same_phone = bool(phone_key and len(phone_key) >= 6 and phone_key in cand_phone)
        similar_name = bool(
            name_key and cand_name
            and (name_key == cand_name
                 or name_key in cand_name
                 or cand_name in name_key
                 or SequenceMatcher(None, name_key, cand_name).ratio() >= 0.82)
        )
        if same_email or same_phone or similar_name:
            payload = _promoter_contact_payload(c)
            payload["why"] = ("mismo correo" if same_email else
                              "mismo teléfono" if same_phone else "nombre parecido")
            out.append(payload)
        if len(out) >= limit:
            break
    return out


def _concert_contact_rows(concert) -> list[dict]:
    """Contactos de la ficha: una entrada por PERSONA con todas sus etiquetas de función."""
    rows = []
    for link in (getattr(concert, "contacts", None) or []):
        contact = getattr(link, "contact", None)
        if contact is None:
            continue
        raw_roles = link.roles if isinstance(link.roles, list) else []
        roles = [CONCERT_CONTACT_ROLE_META[r] | {"key": r} for r in CONCERT_CONTACT_ROLE_KEYS if r in raw_roles]
        if not roles:
            continue
        payload = _promoter_contact_payload(contact)
        payload["roles"] = roles
        rows.append(payload)
    order = {k: n for n, k in enumerate(CONCERT_CONTACT_ROLE_KEYS)}
    rows.sort(key=lambda r: min(order.get(x["key"], 99) for x in r["roles"]))
    return rows


def _concert_contacts_selected_map(concert) -> dict:
    """{ROL: contact_id} para rellenar el selector de la ficha al editar."""
    out = {}
    for link in (getattr(concert, "contacts", None) or []):
        for role in (link.roles if isinstance(link.roles, list) else []):
            if role in CONCERT_CONTACT_ROLE_KEYS and role not in out:
                out[role] = str(link.contact_id)
    return out


def _parse_concert_contacts_form(form) -> dict:
    """Del formulario (asistente o ficha) al mapa persona → roles.

    Llega un campo por función (`contact_<rol>_id`); si se repite la misma persona en varias, se
    acumulan sus etiquetas en una sola entrada."""
    by_contact: dict = {}
    for key in CONCERT_CONTACT_ROLE_KEYS:
        raw = (form.get(f"contact_{key.lower()}_id") or "").strip()
        cid = to_uuid(raw) if raw else None
        if not cid:
            continue
        by_contact.setdefault(cid, [])
        if key not in by_contact[cid]:
            by_contact[cid].append(key)
    return by_contact


def _replace_concert_contacts(session_db, concert_id, by_contact: dict) -> None:
    session_db.query(ConcertContact).filter_by(concert_id=concert_id).delete(synchronize_session=False)
    session_db.flush()
    for cid, roles in by_contact.items():
        if not roles:
            continue
        session_db.add(ConcertContact(concert_id=concert_id, contact_id=cid, roles=list(roles)))


@app.get("/api/promoters/<promoter_id>/contactos", endpoint="api_promoter_contacts")
@admin_required
def api_promoter_contacts(promoter_id):
    """Personas ya vinculadas a un tercero, para elegirlas sin volver a teclearlas."""
    session_db = db()
    try:
        pid = to_uuid(promoter_id) if promoter_id else None
        return jsonify({"contacts": _promoter_contacts_for(session_db, pid) if pid else []})
    finally:
        session_db.close()


@app.post("/api/contactos/crear", endpoint="api_promoter_contact_create")
@admin_required
def api_promoter_contact_create():
    """Crea una persona de contacto vinculada al tercero.

    Antes de crearla avisa de las que se le parecen (mismo correo, mismo teléfono o nombre
    parecido) para poder VINCULAR la que ya existe en vez de duplicarla. Con `force=1` se crea
    igualmente (el usuario ha dicho que no es la misma persona)."""
    data = request.get_json(silent=True) or request.form
    name = (data.get("name") or "").strip()
    email = (data.get("email") or "").strip()
    phone = (data.get("phone") or "").strip()
    promoter_id = to_uuid((data.get("promoter_id") or "").strip() or None)
    force = _truthy(data.get("force"))
    if not name:
        return jsonify({"ok": False, "error": "Indica al menos el nombre de la persona."}), 400
    if not promoter_id:
        return jsonify({"ok": False, "error": "Elige antes el promotor: la persona queda vinculada a él."}), 400
    session_db = db()
    try:
        promoter = session_db.get(Promoter, promoter_id)
        if not promoter:
            return jsonify({"ok": False, "error": "El promotor ya no existe."}), 404
        if not force:
            dups = _similar_promoter_contacts(session_db, name, email, phone)
            if dups:
                return jsonify({"ok": False, "duplicates": dups})
        parts = name.split()
        contact = PromoterContact(
            promoter_id=promoter.id,
            title="Contacto",
            first_name=parts[0],
            last_name=(" ".join(parts[1:]) or None),
            email=(email or None),
            phone=(phone or None),
        )
        session_db.add(contact)
        session_db.commit()
        return jsonify({"ok": True, "contact": _promoter_contact_payload(contact, promoter)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[contactos] no se pudo crear la persona")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


def _song_delivery_email_html(song, title_artist, url_pub, cover_url, note=None, recordatorio=False) -> str:
    logo = _external_url_for("static", filename="img/logo.png")
    cover_img = ('<img src="%s" alt="" style="width:64px;height:64px;object-fit:cover;border-radius:8px;border:1px solid #eee;margin-right:12px;">' % escape(cover_url)) if cover_url else ""
    note_html = ('<div style="border-left:3px solid #E33D48;padding:8px 12px;margin:16px 0;color:#444;white-space:pre-wrap;">%s</div>' % escape(note)) if (note or "").strip() else ""
    return (
        '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#1e2530;">'
        '<div style="text-align:right;margin-bottom:12px;"><img src="%s" alt="PIES Records" style="height:38px;"></div>'
        '<h2 style="margin:0 0 4px;text-align:center;">Solicitud de entrega de masters</h2>'
        '<p style="color:#555;text-align:center;">%s</p>'
        '<div style="border:1px solid #eee;border-radius:8px;padding:12px;display:flex;align-items:center;">'
        '%s<div><div style="font-weight:600;">%s</div><div style="color:#666;font-size:14px;">%s</div></div></div>'
        '%s'
        '<div style="text-align:center;margin:24px 0;"><a href="%s" style="background:#E33D48;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-weight:600;display:inline-block;">Subir masters e información</a></div>'
        '<p style="color:#888;font-size:12px;">Si el botón no funciona, copia este enlace:<br>%s</p>'
        '</div>'
    ) % (escape(logo),
         ("Aún no hemos recibido esta entrega. Te la recordamos:"
          if recordatorio else
          "Se solicita la entrega de información y materiales de la siguiente canción:"),
         cover_img, escape(song.title or ""), escape(title_artist), note_html, escape(url_pub), escape(url_pub))


@app.post("/discografica/canciones/<song_id>/entrega/<link_id>/enviar-correo")
@admin_required
def discografica_song_delivery_send_email(song_id, link_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos.")
    recipients = [e.strip() for e in request.form.getlist("recipients") if e.strip()]
    extra = (request.form.get("extra_email") or "").strip()
    if extra:
        recipients.append(extra)
    recipients = list(dict.fromkeys(recipients))  # dedupe conservando orden
    note = (request.form.get("note") or "").strip()
    if not recipients:
        flash("Indica al menos un destinatario.", "warning")
        return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        link = session_db.get(SongMasterDeliveryLink, to_uuid(link_id))
        if not song or not link or link.song_id != song.id or link.status != "ACTIVE":
            flash("Enlace de entrega no válido.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
        artist = _song_artist_names_str(song)
        collab = (getattr(song, "collaborator", None) or "").strip()
        title_artist = artist + (" (con %s)" % collab if collab else "")
        subject = "Solicitud entrega masters · %s · %s" % (title_artist, song.title or "")
        url_pub = _song_delivery_public_url(link)
        html = _song_delivery_email_html(song, title_artist, url_pub, (song.cover_url or "").strip(), note=note)
        ok, err = _send_optional_email(recipients, subject, html, text_body="Solicitud de entrega de masters. Enlace: " + url_pub, reply_to=_current_user_email())
        if ok:
            link.target_email = ", ".join(recipients)
            # Mandado por correo → se insiste UNA VEZ AL DÍA hasta que se cumplimente (o se anule).
            link.reminders_enabled = True
            link.reminder_last_at = _now_madrid()
            link.reminder_count = 0
            session_db.add(link)
            session_db.commit()
            flash("Correo de solicitud enviado a %s. Se recordará cada día hasta que lo rellenen."
                  % ", ".join(recipients), "success")
        else:
            flash("No se pudo enviar el correo: %s" % (err or "revisa la configuración SMTP"), "danger")
    except Exception as e:
        session_db.rollback()
        flash(f"Error enviando el correo: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


def _song_delivery_active_link(session_db, token):
    return session_db.query(SongMasterDeliveryLink).filter(
        SongMasterDeliveryLink.token == (token or "").strip(),
        SongMasterDeliveryLink.status == "ACTIVE",
    ).first()


def _delivery_promoter_label(p):
    fn = (getattr(p, "first_name", None) or "").strip()
    ln = (getattr(p, "last_name", None) or "").strip()
    return (fn + " " + ln).strip() or (getattr(p, "nick", None) or "").strip() or "—"


@app.get("/entrega-masters/<token>/api/autores", endpoint="public_song_delivery_authors")
def public_song_delivery_authors(token):
    session_db = db()
    try:
        if not _song_delivery_active_link(session_db, token):
            return jsonify([])
        q = (request.args.get("q") or "").strip()
        if len(q) < 1:
            return jsonify([])
        rows = (
            session_db.query(Promoter)
            .options(joinedload(Promoter.publishing_company))
            .filter(or_(
                _sa_contains_text(Promoter.nick, q),
                _sa_contains_text(Promoter.first_name, q),
                _sa_contains_text(Promoter.last_name, q),
                _sa_contains_text(func.concat(Promoter.first_name, ' ', Promoter.last_name), q),
            ))
            .order_by(Promoter.nick.asc()).limit(10).all()
        )
        out = []
        for p in rows:
            pc = getattr(p, "publishing_company", None)
            out.append({
                "id": str(p.id),
                "name": _delivery_promoter_label(p),
                "logo_url": (getattr(p, "logo_url", None) or ""),
                "email": (getattr(p, "contact_email", None) or ""),
                "publishing_company_id": str(p.publishing_company_id) if getattr(p, "publishing_company_id", None) else "",
                "publishing_company_name": (pc.name if pc else ""),
            })
        return jsonify(out)
    finally:
        session_db.close()


