@app.post("/entrega-masters/<token>/api/crear-autor", endpoint="public_song_delivery_create_author")
def public_song_delivery_create_author(token):
    session_db = db()
    try:
        if not _song_delivery_active_link(session_db, token):
            return jsonify({"error": "Enlace no válido"}), 400
        first = (request.form.get("first_name") or "").strip()
        last = (request.form.get("last_name") or "").strip()
        nick = (first + " " + last).strip() or (request.form.get("name") or "").strip()
        if not nick:
            return jsonify({"error": "Indica el nombre del autor"}), 400
        pc = None
        pc_id = (request.form.get("publishing_company_id") or "").strip()
        pc_name = (request.form.get("publishing_company_name") or "").strip()
        if pc_id:
            pc = session_db.get(PublishingCompany, to_uuid(pc_id))
        if not pc and pc_name:
            pc = _delivery_get_or_create_publishing(session_db, pc_name)
        correo = (request.form.get("email") or "").strip()
        pr = Promoter(nick=_intake_unique_nick(session_db, nick), first_name=first or None, last_name=last or None,
                      contact_email=correo or None, publishing_company_id=(pc.id if pc else None))
        session_db.add(pr)
        session_db.flush()
        result = {
            "id": str(pr.id), "name": nick, "logo_url": "", "email": correo,
            "publishing_company_id": str(pc.id) if pc else "",
            "publishing_company_name": (pc.name if pc else ""),
        }
        session_db.commit()
        return jsonify(result)
    except Exception as e:
        session_db.rollback()
        return jsonify({"error": str(e)}), 500
    finally:
        session_db.close()


SONG_DELIVERY_DIRECT_EXTS = {".wav", ".wave", ".zip"}


@app.post("/entrega-masters/<token>/api/subida-directa", endpoint="public_song_delivery_sign")
def public_song_delivery_sign(token):
    """Prepara la subida DIRECTA de un archivo del navegador a Storage.

    ⚠️ Los masters son archivos GRANDES: mandarlos al servidor dentro del formulario se comía el
    tiempo (y la memoria) de la petición y la entrega moría con un **502** sin guardar nada — el
    mismo caso que ya se resolvió con los vídeos. Con esto el archivo va del navegador a Storage y al
    servidor solo le llega su dirección."""
    session_db = db()
    try:
        if not _song_delivery_active_link(session_db, token):
            return jsonify({"ok": False, "error": "El enlace ya no está activo."}), 400
    finally:
        session_db.close()
    datos = request.get_json(silent=True) or {}
    nombre = (datos.get("filename") or "").strip()
    ext = os.path.splitext(nombre.lower())[1]
    if ext not in SONG_DELIVERY_DIRECT_EXTS:
        return jsonify({"ok": False, "error": "Solo .wav (o .zip para los stems)."}), 400
    try:
        info = create_signed_upload_url_for("song_materials", ext)
    except Exception as e:
        return jsonify({"ok": False, "error": "No se pudo preparar la subida: " + str(e)[:200]}), 502
    if not info.get("signed_url"):
        return jsonify({"ok": False, "error": "No se pudo preparar la subida."}), 502
    return jsonify({"ok": True, "key": info["key"], "upload_url": info["signed_url"]})


@app.route("/entrega-masters/<token>", methods=["GET", "POST"], endpoint="public_song_master_delivery")
def public_song_master_delivery(token):
    session_db = db()
    try:
        link = session_db.query(SongMasterDeliveryLink).filter(SongMasterDeliveryLink.token == (token or "").strip()).first()
        if not link:
            abort(404)
        song = session_db.get(Song, link.song_id)
        if not song:
            abort(404)
        sections = [k for k, _ in SONG_DELIVERY_SECTIONS if k in (link.sections_json or [])]
        req_materials = list(link.materials_json or [])
        if "MASTERS" in sections and not req_materials:
            req_materials = list(SONG_DELIVERY_LEGACY_MATERIALS)   # compat enlaces antiguos
        # Qué se pide y qué es obligatorio en ESTE enlace (campo a campo).
        conf = _song_delivery_config(link)
        pedido = {k: v for k, v in conf.items() if v.get("ask")}
        sections = [k for k, _ in SONG_DELIVERY_SECTIONS if any(v["section"] == k for v in pedido.values())]
        req_materials = [k[4:] for k in pedido if k.startswith("mat.")]
        base_ctx = dict(
            link=link, song=song, sections=sections, conf=conf,
            section_labels=dict(SONG_DELIVERY_SECTIONS),
            # Solo los campos de producción que se piden, con su obligatoriedad de este enlace.
            production_fields=[(k[5:], v["label"], v["required"]) for k, v in conf.items()
                               if k.startswith("prod.") and v.get("ask")],
            author_roles=SONG_DELIVERY_AUTHOR_ROLES,
            material_specs=[(f, _song_material_slot_label(c, s), conf.get("mat." + f, {}).get("required", True))
                            for f, c, s in SONG_DELIVERY_MATERIAL_SPECS if f in req_materials],
            show_stems=("stems" in req_materials),
            stems_required=conf.get("mat.stems", {}).get("required", False),
            # PORTADA (imagen) y TEXTO PARA EL PITCH: solo si se han pedido en este enlace.
            show_cover=("cover" in req_materials),
            cover_required=conf.get("mat.cover", {}).get("required", False),
            pitch_required=conf.get("pitch", {}).get("required", False),
            artist_names=_song_artist_names_str(song),
            # Para las etiquetas og: (portada, «Entrega de masters · canción» y, debajo, artista e
            # intérpretes) — así la previsualización es igual en WhatsApp, correo y redes.
            share=_song_delivery_share_context(session_db, song),
            og_image=_external_url_for("public_song_delivery_og_image", token=link.token),
        )
        if link.status != "ACTIVE":
            return render_template("public_song_master_delivery.html", state="closed", **base_ctx)

        if request.method == "POST":
            data, errors = {}, []
            if "PRODUCTION" in sections:
                prod = {}
                for key, lbl, req in base_ctx["production_fields"]:
                    prod[key] = (request.form.get("prod_" + key) or "").strip()
                    if req and not prod.get(key):
                        errors.append("Producción: falta «%s»." % lbl)
                # EL PRODUCTOR es un tercero de la base de datos: se guarda a quién se ha elegido y,
                # si su ficha no tenía correo y lo han escrito aquí, se le apunta en la ficha.
                _prod_pid = _safe_uuid(request.form.get("prod_producer_promoter_id"))
                _prod_mail = (request.form.get("prod_producer_email") or "").strip()
                if _prod_pid:
                    _pr = session_db.get(Promoter, _prod_pid)
                    if _pr is not None:
                        prod["producer"] = _delivery_promoter_label(_pr)
                        prod["producer_promoter_id"] = str(_pr.id)
                        if _prod_mail and not (getattr(_pr, "contact_email", None) or "").strip():
                            _pr.contact_email = _prod_mail
                            session_db.add(_pr)
                        prod["producer_email"] = (getattr(_pr, "contact_email", None) or _prod_mail or "")
                elif _prod_mail:
                    prod["producer_email"] = _prod_mail
                _pconf = conf.get("prod.producer") or {}
                if _pconf.get("ask"):
                    if _pconf.get("required") and not (prod.get("producer") or "").strip():
                        errors.append("Producción: elige el productor en la base de datos.")
                    elif (prod.get("producer") or "").strip() and not (prod.get("producer_email") or "").strip():
                        errors.append("Producción: falta el correo de contacto del productor.")
                data["production"] = prod
            if "AUTHORAL" in sections:
                names = request.form.getlist("author_name")
                editorials = request.form.getlist("author_editorial")
                roles = request.form.getlist("author_role")
                pcts = request.form.getlist("author_pct")
                promoter_ids = request.form.getlist("author_promoter_id")
                publishing_ids = request.form.getlist("author_publishing_id")
                # El ALCANCE del cambio de editorial de cada autor (puntual o de aquí en adelante).
                scopes = request.form.getlist("author_publisher_scope")
                authors, total = [], 0.0
                for i, nm in enumerate(names):
                    nm = (nm or "").strip()
                    if not nm:
                        continue
                    role = (roles[i] if i < len(roles) else "").strip().upper()
                    try:
                        pct = float((pcts[i] if i < len(pcts) else "0").replace(",", "."))
                    except ValueError:
                        pct = 0.0
                    authors.append({
                        "name": nm,
                        "editorial": (editorials[i] if i < len(editorials) else "").strip(),
                        "role": role, "pct": pct,
                        "promoter_id": (promoter_ids[i] if i < len(promoter_ids) else "").strip(),
                        "publishing_company_id": (publishing_ids[i] if i < len(publishing_ids) else "").strip(),
                        "publisher_scope": (scopes[i] if i < len(scopes) else "").strip().upper(),
                    })
                    total += pct
                if not authors and conf.get("authoral", {}).get("required"):
                    errors.append("Autoral: añade al menos un autor.")
                elif any(a["role"] not in {"AUTHOR", "COMPOSER", "AUTHOR_COMPOSER"} for a in authors):
                    errors.append("Autoral: indica el rol de cada autor.")
                elif abs(total - 100.0) > 0.01:
                    errors.append("Autoral: los porcentajes deben sumar 100%% (actual: %.2f%%)." % total)
                data["authoral"] = authors
            if "LYRICS" in sections:
                lyrics = (request.form.get("lyrics") or "").strip()
                if not lyrics and conf.get("lyrics", {}).get("required"):
                    errors.append("La letra es obligatoria.")
                data["lyrics"] = lyrics
            if "PITCH" in sections:
                pitch = (request.form.get("pitch") or "").strip()
                if not pitch and conf.get("pitch", {}).get("required"):
                    errors.append("El texto para el pitch es obligatorio.")
                data["pitch"] = pitch
            uploads = []
            # Lo que el navegador ya ha subido DIRECTAMENTE a Storage llega como
            # {campo: [{key, name}]} — el fichero no pasa por aquí (ver public_song_delivery_sign).
            subidos = _json_dict(request.form.get("uploaded_json"))
            def _ya_subido(campo):
                filas = subidos.get(campo)
                if isinstance(filas, dict):
                    filas = [filas]
                return [f for f in (filas or []) if isinstance(f, dict) and (f.get("key") or "").strip()]
            if "MASTERS" in sections:
                for field, cat, slot in SONG_DELIVERY_MATERIAL_SPECS:
                    if field not in req_materials:
                        continue
                    directos = _ya_subido(field)
                    if directos:
                        uploads.append((directos[0], cat, slot))
                        continue
                    fs = request.files.get(field)
                    if not fs or not getattr(fs, "filename", ""):
                        if conf.get("mat." + field, {}).get("required"):
                            errors.append("Materiales: falta «%s» (.wav)." % _song_material_slot_label(cat, slot))
                        continue
                    if Path((fs.filename or "").replace("\\", "/")).suffix.lower() not in {".wav", ".wave"}:
                        errors.append("Materiales: «%s» debe ser .wav." % _song_material_slot_label(cat, slot))
                        continue
                    uploads.append((fs, cat, slot))
                stems = ([fs for fs in request.files.getlist("stems") if fs and getattr(fs, "filename", "")]
                         + _ya_subido("stems")) if "stems" in req_materials else []
                # PORTADA: es una imagen y pesa poco, así que va por el servidor (la subida directa a
                # Storage solo admite .wav / .zip).
                if "cover" in req_materials:
                    _cf = request.files.get("cover")
                    if not _cf or not getattr(_cf, "filename", ""):
                        if conf.get("mat.cover", {}).get("required"):
                            errors.append("Materiales: falta la portada.")
                    elif Path((_cf.filename or "").replace("\\", "/")).suffix.lower() not in SONG_DELIVERY_COVER_EXTS:
                        errors.append("Materiales: la portada debe ser una imagen (jpg, png o webp).")
                    else:
                        uploads.append((_cf, "COVER", "COVER"))
            else:
                stems = []

            if errors:
                return render_template("public_song_master_delivery.html", state="form", errors=errors, form=request.form, **base_ctx)

            stems_bundle = uuid.uuid4().hex
            def _url_de_subido(fs):
                try:
                    return public_url_for_key((fs.get("key") or "").strip())
                except Exception:
                    app.logger.exception("[entrega-masters] no se pudo resolver la URL del archivo subido")
                    return ""

            for fs, cat, slot in uploads:
                if isinstance(fs, dict):          # ya está en Storage: solo se apunta dónde
                    file_url = _url_de_subido(fs)
                    if not file_url:
                        errors.append("No se pudo registrar «%s». Vuelve a intentarlo." % (fs.get("name") or "el archivo"))
                        continue
                    nombre = (fs.get("name") or "audio.wav").replace("\\", "/")
                    tipo = None
                else:
                    # La portada es una IMAGEN; el resto, audio.
                    _es_portada = (cat or "").upper() == "COVER"
                    file_url = upload_file(
                        fs, "song_materials",
                        allowed_extensions=(SONG_DELIVERY_COVER_EXTS if _es_portada else {".wav", ".wave"}))
                    nombre = (fs.filename or ("portada.jpg" if _es_portada else "audio.wav")).replace("\\", "/")
                    tipo = (getattr(fs, "mimetype", "") or "").strip() or None
                session_db.add(SongMaterial(
                    song_id=song.id, category=cat, slot_key=slot,
                    file_name=nombre, file_url=file_url, mime_type=tipo,
                    validation_status="PENDING", delivery_link_id=link.id,
                ))
            for fs in stems:
                if isinstance(fs, dict):
                    # Stem ya subido directamente a Storage: se apunta tal cual (un ZIP subido así no
                    # se descomprime aquí; entra como un archivo más del paquete).
                    session_db.add(SongMaterial(
                        song_id=song.id, category="STEMS", slot_key="BUNDLE", bundle_key=stems_bundle,
                        display_name="Stems (entrega)",
                        file_name=(fs.get("name") or "stem").replace("\\", "/"),
                        file_url=_url_de_subido(fs),
                        validation_status="PENDING", delivery_link_id=link.id,
                    ))
                    continue
                _sfn = (fs.filename or "stem").replace("\\", "/")
                if Path(_sfn).suffix.lower() == ".zip":
                    # Carpeta comprimida: se descomprime y cada archivo interno entra como un stem del bundle.
                    try:
                        _zf = zipfile.ZipFile(BytesIO(fs.read()))
                    except Exception:
                        continue
                    for info in _zf.infolist():
                        if info.is_dir():
                            continue
                        inner_name = Path(info.filename.replace("\\", "/")).name
                        if not inner_name or inner_name.startswith(".") or "__MACOSX/" in info.filename:
                            continue
                        data_bytes = _zf.read(info)
                        if not data_bytes:
                            continue
                        inner_suffix = Path(inner_name).suffix.lower()
                        key = f"song_materials/{uuid.uuid4().hex}{inner_suffix}"
                        content_type = mimetypes.guess_type(inner_name)[0] or "application/octet-stream"
                        file_url = _upload_bytes(data_bytes, key, content_type)
                        session_db.add(SongMaterial(
                            song_id=song.id, category="STEMS", slot_key="BUNDLE", bundle_key=stems_bundle,
                            display_name="Stems (entrega)", file_name=inner_name, file_url=file_url,
                            mime_type=content_type,
                            validation_status="PENDING", delivery_link_id=link.id,
                        ))
                else:
                    file_url = upload_file(fs, "song_materials")
                    session_db.add(SongMaterial(
                        song_id=song.id, category="STEMS", slot_key="BUNDLE", bundle_key=stems_bundle,
                        display_name="Stems (entrega)", file_name=_sfn, file_url=file_url,
                        mime_type=(getattr(fs, "mimetype", "") or "").strip() or None,
                        validation_status="PENDING", delivery_link_id=link.id,
                    ))
            if errors:
                # Algo no se pudo registrar (p. ej. un archivo subido cuya dirección no se resuelve):
                # se deshace todo y se dice, en vez de dar la entrega por buena a medias.
                session_db.rollback()
                return render_template("public_song_master_delivery.html", state="form",
                                       errors=errors, form=request.form, **base_ctx)
            # QUIÉN la ha entregado se apunta AHORA en la propia entrega: los datos de producción
            # se van al consolidarlos y con ellos se perdía el nombre y la foto de quien la subió.
            data["submitted_by"] = _song_delivery_submitter(session_db, link, data)
            link.data = data
            link.status = "SUBMITTED"
            link.submitted_at = datetime.now(TZ_MADRID)
            session_db.add(link)
            session_db.flush()
            # Lo entregado es TRABAJO para dentro: se avisa a Registros y al Sello (con la cara de
            # quien lo ha subido) y les queda la tarea hasta que esté todo validado.
            _song_delivery_notify_submitted(session_db, link, song, data)
            session_db.commit()
            return render_template("public_song_master_delivery.html", state="submitted", **base_ctx)

        # LO QUE YA ESTÁ sale RELLENO (y se puede corregir si está mal). Solo de lo que este enlace
        # pide: lo que no se marcó al crearlo ni se muestra ni se rellena.
        prefill, hecho = _song_delivery_prefill(session_db, song, conf)
        return render_template("public_song_master_delivery.html", state="form",
                               form=prefill, prefilled=hecho,
                               prefill_authors=prefill.get("_authors") or [], **base_ctx)
    finally:
        session_db.close()


def _parse_timing_to_seconds(txt):
    txt = (txt or "").strip()
    if not txt:
        return None
    if ":" in txt:
        try:
            parts = [int(p) for p in txt.split(":")]
        except ValueError:
            return None
        if len(parts) == 2:
            return parts[0] * 60 + parts[1]
        if len(parts) == 3:
            return parts[0] * 3600 + parts[1] * 60 + parts[2]
        return None
    try:
        return int(txt)
    except ValueError:
        return None


def _delivery_get_or_create_promoter(session_db, name):
    name = (name or "").strip()
    if not name:
        return None
    existing = session_db.query(Promoter).filter(func.lower(Promoter.nick) == name.lower()).first()
    if existing:
        return existing
    pr = Promoter(nick=name)
    session_db.add(pr)
    session_db.flush()
    return pr


def _delivery_get_or_create_publishing(session_db, name):
    name = (name or "").strip()
    if not name:
        return None
    existing = session_db.query(PublishingCompany).filter(func.lower(PublishingCompany.name) == name.lower()).first()
    if existing:
        return existing
    pc = PublishingCompany(name=name)
    session_db.add(pc)
    session_db.flush()
    return pc


@app.post("/discografica/canciones/<song_id>/materials/<material_id>/validate")
@admin_required
def discografica_song_material_validate(song_id, material_id):
    if not can_edit_discografica():
        return forbid("No tienes permisos para validar materiales.")
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        row = session_db.get(SongMaterial, to_uuid(material_id))
        if not song or not row or row.song_id != song.id:
            flash("Material no encontrado.", "warning")
            return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))
        cat = (row.category or "").upper()
        slot = (row.slot_key or "DEFAULT").upper()
        # Al validar un slot fijo, sustituye al material validado previo de ese mismo slot.
        if cat in {"MASTER", "INSTRUMENTAL", "TV_TRACK"} and slot != "SUBPRODUCT":
            for other in session_db.query(SongMaterial).filter(
                SongMaterial.song_id == song.id,
                func.upper(SongMaterial.category) == cat,
                func.upper(SongMaterial.slot_key) == slot,
                SongMaterial.id != row.id,
                func.upper(func.coalesce(SongMaterial.validation_status, "VALIDATED")) != "PENDING",
            ).all():
                session_db.delete(other)
        row.validation_status = "VALIDATED"
        row.updated_at = datetime.now(TZ_MADRID)
        session_db.add(row)
        session_db.flush()
        _refresh_song_material_status(session_db, song)
        # ⚠️ El aviso de «materiales por revisar» se cierra SOLO cuando la entrega está completa: si
        # queda algo pendiente (o algo rechazado sin reponer), sigue esperando.
        _song_delivery_review_close_for_song(session_db, song.id)
        session_db.commit()
        flash("Material validado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error validando el material: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("discografica_song_detail", song_id=song_id, tab="materiales"))


