@app.post("/tocadas/posiciones/guardar", endpoint="plays_positions_save")
@admin_required
def plays_positions_save():
    """Guarda DE UNA VEZ las posiciones por emisora y las del ranking nacional de esa semana."""
    if not can_edit_radio():
        return forbid("No tienes permisos para modificar tocadas de radio.")
    session_db = db()
    week_start = monday_of(parse_date(request.form["week_start"]))
    try:
        ensure_week(session_db, week_start)

        def _pos(valor):
            valor = (valor or "").strip()
            if not valor:
                return None
            try:
                n = int(valor)
            except ValueError:
                return None
            return n if n > 0 else None

        # Posiciones por emisora: se escriben sobre las tocadas que YA existen (no se inventa una
        # fila para una canción que esa semana no ha sonado en esa emisora).
        cambios = {}
        for key, val in request.form.items():
            if not key.startswith("pos_"):
                continue
            try:
                _p, station_id, song_id = key.split("_", 2)
            except ValueError:
                continue
            st = _safe_uuid(station_id)
            sg = _safe_uuid(song_id)
            if not st or not sg:
                continue
            cambios[(sg, st)] = _pos(val)

        tocadas = 0
        if cambios:
            filas = (session_db.query(Play)
                     .filter(Play.week_start == week_start)
                     .filter(Play.song_id.in_({sg for sg, _st in cambios}))
                     .all())
            for p in filas:
                clave = (p.song_id, p.station_id)
                if clave in cambios:
                    p.position = cambios[clave]
                    tocadas += 1

        # Ranking NACIONAL de la semana.
        nacionales = 0
        info_map = {str(si.song_id): si for si in
                    session_db.query(SongWeekInfo).filter(SongWeekInfo.week_start == week_start).all()}
        for key, val in request.form.items():
            if not key.startswith("nat_"):
                continue
            sg = _safe_uuid(key.split("_", 1)[1])
            if not sg:
                continue
            valor = _pos(val)
            fila = info_map.get(str(sg))
            if fila is None:
                if valor is None:
                    continue
                session_db.add(SongWeekInfo(song_id=sg, week_start=week_start, national_rank=valor))
            else:
                fila.national_rank = valor
            nacionales += 1

        session_db.commit()
        flash("Posiciones guardadas (%d por emisora y %d del ranking nacional)." % (tocadas, nacionales),
              "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error guardando las posiciones: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("plays_positions_view", week=week_start.isoformat()))


# ---------- IMPORTAR TOCADAS DESDE EXCEL ----------
def _radio_channel_key(name) -> str:
    """Clave normalizada del nombre de emisora/canal (minúsculas, espacios colapsados)."""
    return " ".join((str(name) if name is not None else "").strip().lower().split())


def _radio_song_options(session_db):
    """[{id, label}] de todas las canciones (para los selectores de vinculación)."""
    from collections import defaultdict
    amap = defaultdict(list)
    for sid, aname in (
        session_db.query(SongArtist.song_id, Artist.name)
        .join(Artist, Artist.id == SongArtist.artist_id)
        .all()
    ):
        if aname:
            amap[str(sid)].append(aname)
    out = []
    for sid, title in session_db.query(Song.id, Song.title).order_by(Song.title.asc()).all():
        artists = ", ".join(amap.get(str(sid), []))
        label = f"{title} — {artists}" if artists else (title or "(sin título)")
        out.append({"id": str(sid), "label": label})
    return out


def _radio_build_isrc_song_map(session_db):
    """norm_isrc -> song_id(str). Song.isrc legacy + SongISRCCode + alias manuales (prioritarios).
    Los ISRC ambiguos (varias canciones) se descartan salvo que un alias los resuelva."""
    m: dict[str, str] = {}
    ambiguous: set[str] = set()

    def reg(code, sid):
        k = _norm_isrc(code)
        if not k:
            return
        sid = str(sid)
        if k in ambiguous:
            return
        cur = m.get(k)
        if cur and cur != sid:
            ambiguous.add(k)
            m.pop(k, None)
            return
        m[k] = sid

    for sid, code in session_db.query(Song.id, Song.isrc).all():
        reg(code, sid)
    for sid, code in session_db.query(SongISRCCode.song_id, SongISRCCode.code).all():
        reg(code, sid)
    # Alias manuales: prioridad total (resuelven ambigüedad y correcciones).
    for isrc, sid in session_db.query(RadioIsrcAlias.isrc, RadioIsrcAlias.song_id).all():
        k = _norm_isrc(isrc)
        if k:
            m[k] = str(sid)
            ambiguous.discard(k)
    return m, ambiguous


def _radio_build_station_map(session_db):
    """channel_key -> station_id(str). Nombre de RadioStation + alias aprendidos."""
    m: dict[str, str] = {}
    for sid, name in session_db.query(RadioStation.id, RadioStation.name).all():
        k = _radio_channel_key(name)
        if k:
            m[k] = str(sid)
    for alias, sid in session_db.query(RadioStationAlias.alias, RadioStationAlias.station_id).all():
        k = _radio_channel_key(alias)
        if k:
            m[k] = str(sid)
    return m


def _radio_parse_plays_xlsx(file_storage):
    """Lee la PRIMERA hoja del Excel de tocadas. Detecta la fila de cabecera (con «isrc» y
    «channel»), agrega el nº de tocadas por (ISRC, canal) y devuelve metadatos."""
    try:
        import openpyxl
    except Exception:
        raise ValueError("Falta la dependencia openpyxl para leer archivos Excel.")
    from io import BytesIO
    from collections import defaultdict
    try:
        wb = openpyxl.load_workbook(BytesIO(file_storage.read()), read_only=True, data_only=True)
    except Exception:
        raise ValueError("No se pudo leer el archivo. Asegúrate de subir un Excel (.xlsx).")
    ws = wb[wb.sheetnames[0]]  # SOLO la primera hoja
    all_rows = list(ws.iter_rows(values_only=True))
    header_idx = None
    header = None
    for i, r in enumerate(all_rows):
        vals = [(str(c).strip().lower() if c is not None else "") for c in r]
        if "isrc" in vals and "channel" in vals:
            header_idx = i
            header = vals
            break
    if header_idx is None:
        raise ValueError("No se encuentra la fila de cabecera con las columnas «isrc» y «channel» en la primera hoja.")

    def col(name):
        return header.index(name) if name in header else None

    ci, ii, ti, ai, di = col("channel"), col("isrc"), col("track"), col("artist"), col("date")
    pair = defaultdict(int)
    isrc_meta = {}
    channel_meta = {}
    dates = []

    def cell(r, idx):
        if idx is None or idx >= len(r):
            return None
        return r[idx]

    for r in all_rows[header_idx + 1:]:
        if not r or not any(c is not None for c in r):
            continue
        norm = _norm_isrc(cell(r, ii))
        ckey = _radio_channel_key(cell(r, ci))
        if not norm or not ckey:
            continue
        pair[(norm, ckey)] += 1
        if norm not in isrc_meta:
            isrc_meta[norm] = {
                "track": (str(cell(r, ti)).strip() if cell(r, ti) is not None else ""),
                "artist": (str(cell(r, ai)).strip() if cell(r, ai) is not None else ""),
            }
        if ckey not in channel_meta:
            channel_meta[ckey] = str(cell(r, ci)).strip()
        dv = cell(r, di)
        if dv is not None:
            try:
                dates.append(dv.date() if hasattr(dv, "date") else parse_date(str(dv)[:10]))
            except Exception:
                pass
    return pair, isrc_meta, channel_meta, dates


@app.post("/tocadas/importar/analizar", endpoint="plays_import_analyze")
@admin_required
def plays_import_analyze():
    if not can_edit_radio():
        return jsonify({"ok": False, "error": "Sin permisos para actualizar tocadas."}), 403
    f = request.files.get("file")
    if not f or not getattr(f, "filename", ""):
        return jsonify({"ok": False, "error": "Sube un archivo Excel (.xlsx)."}), 400
    session_db = db()
    try:
        try:
            week = monday_of(parse_date(request.form.get("week_start")))
        except Exception:
            week = monday_of(today_local()) - timedelta(days=7)
        try:
            pair, isrc_meta, channel_meta, dates = _radio_parse_plays_xlsx(f)
        except ValueError as e:
            return jsonify({"ok": False, "error": str(e)}), 400
        if not pair:
            return jsonify({"ok": False, "error": "El archivo no contiene tocadas con ISRC y canal."}), 400

        song_map, ambiguous = _radio_build_isrc_song_map(session_db)
        station_map = _radio_build_station_map(session_db)
        song_options = _radio_song_options(session_db)
        opt_label = {o["id"]: o["label"] for o in song_options}
        all_stations = [
            {"id": str(s.id), "name": s.name}
            for s in session_db.query(RadioStation).order_by(RadioStation.name.asc()).all()
        ]
        st_label = {s["id"]: s["name"] for s in all_stations}

        from collections import defaultdict
        isrc_total, chan_total = defaultdict(int), defaultdict(int)
        for (isrc, ck), n in pair.items():
            isrc_total[isrc] += n
            chan_total[ck] += n

        songs = []
        for isrc in sorted(isrc_meta):
            sid = song_map.get(isrc)
            songs.append({
                "isrc": isrc,
                "track": isrc_meta[isrc]["track"],
                "artist": isrc_meta[isrc]["artist"],
                "spins": isrc_total[isrc],
                "song_id": sid,
                "song_label": opt_label.get(sid, ""),
                "matched": bool(sid),
                "ambiguous": isrc in ambiguous,
            })
        stations = []
        for ck in sorted(channel_meta):
            sid = station_map.get(ck)
            stations.append({
                "channel_key": ck,
                "channel": channel_meta[ck],
                "spins": chan_total[ck],
                "station_id": sid,
                "station_name": st_label.get(sid, ""),
                "matched": bool(sid),
            })
        cells = [{"isrc": i, "channel_key": c, "spins": n} for (i, c), n in pair.items()]

        detected_range = ""
        detected_week = ""
        if dates:
            detected_range = f"{min(dates).strftime('%d/%m/%Y')} - {max(dates).strftime('%d/%m/%Y')}"
            detected_week = monday_of(min(dates)).isoformat()
        return jsonify({
            "ok": True,
            "week_start": week.isoformat(),
            "week_label": week_label_range(week),
            "detected_range": detected_range,
            "week_mismatch": bool(detected_week and detected_week != week.isoformat()),
            "songs": songs,
            "stations": stations,
            "cells": cells,
            "song_options": song_options,
            "all_stations": all_stations,
            "counts": {"rows": sum(pair.values()), "songs": len(songs), "stations": len(stations)},
        })
    finally:
        session_db.close()


def _radio_upsert_station_alias(session_db, alias_key, station_id):
    a = session_db.query(RadioStationAlias).filter(RadioStationAlias.alias == alias_key).first()
    if a:
        a.station_id = station_id
    else:
        session_db.add(RadioStationAlias(alias=alias_key, station_id=station_id))


def _radio_upsert_isrc_alias(session_db, isrc, song_id):
    a = session_db.query(RadioIsrcAlias).filter(RadioIsrcAlias.isrc == isrc).first()
    if a:
        a.song_id = song_id
    else:
        session_db.add(RadioIsrcAlias(isrc=isrc, song_id=song_id))


@app.post("/tocadas/importar/aplicar", endpoint="plays_import_apply")
@admin_required
def plays_import_apply():
    if not can_edit_radio():
        return jsonify({"ok": False, "error": "Sin permisos para actualizar tocadas."}), 403
    payload = request.get_json(silent=True) or {}
    _semana = parse_optional_date(payload.get("week_start"))
    if not _semana:
        # Es un endpoint AJAX: sin semana se contesta en JSON, que es lo que el front sabe leer
        # (antes petaba con un 500 y el navegador se quedaba sin respuesta que entender).
        return jsonify({"ok": False, "error": "Falta la semana que se está importando."}), 400
    session_db = db()
    try:
        week = monday_of(_semana)
        ensure_week(session_db, week)

        # Mapa automático de ISRC (para decidir si un enlace de canción es manual y hay que recordarlo).
        auto_song_map, _amb = _radio_build_isrc_song_map(session_db)

        # 1) Resolver emisoras (enlazar / crear / descartar) y aprender alias de los enlaces manuales.
        chan_to_station = {}
        created_stations = 0
        for st in (payload.get("stations") or []):
            if st.get("discard"):
                continue
            ck = _radio_channel_key(st.get("channel_key") or st.get("channel"))
            sid = st.get("station_id")
            if not sid and st.get("create"):
                name = (st.get("name") or "").strip()
                if not name:
                    continue
                existing = session_db.query(RadioStation).filter(func.lower(RadioStation.name) == name.lower()).first()
                if existing:
                    sid = str(existing.id)
                else:
                    newst = RadioStation(name=name)
                    session_db.add(newst)
                    session_db.flush()
                    sid = str(newst.id)
                    created_stations += 1
            if not sid or not ck:
                continue
            chan_to_station[ck] = sid
            st_obj = session_db.get(RadioStation, to_uuid(sid))
            if st_obj and _radio_channel_key(st_obj.name) != ck:
                _radio_upsert_station_alias(session_db, ck, to_uuid(sid))

        # 2) Resolver canciones (enlazar / descartar) y recordar alias de los enlaces manuales.
        isrc_to_song = {}
        for so in (payload.get("songs") or []):
            if so.get("discard"):
                continue
            isrc = _norm_isrc(so.get("isrc"))
            sid = so.get("song_id")
            if not isrc or not sid:
                continue
            isrc_to_song[isrc] = sid
            if auto_song_map.get(isrc) != str(sid):
                _radio_upsert_isrc_alias(session_db, isrc, to_uuid(sid))

        # 3) Agregar por (canción, emisora) y fijar las tocadas de la semana (reemplaza el valor).
        from collections import defaultdict
        agg = defaultdict(int)
        for c in (payload.get("cells") or []):
            isrc = _norm_isrc(c.get("isrc"))
            ck = _radio_channel_key(c.get("channel_key") or c.get("channel"))
            sid = isrc_to_song.get(isrc)
            stid = chan_to_station.get(ck)
            if not sid or not stid:
                continue
            try:
                n = int(c.get("spins") or 0)
            except Exception:
                n = 0
            agg[(sid, stid)] += n

        applied = 0
        for (sid, stid), n in agg.items():
            p = (session_db.query(Play)
                 .filter_by(song_id=to_uuid(sid), station_id=to_uuid(stid), week_start=week)
                 .first())
            if p:
                p.spins = n
            else:
                session_db.add(Play(song_id=to_uuid(sid), station_id=to_uuid(stid), week_start=week, spins=n))
            applied += 1

        session_db.commit()
        return jsonify({
            "ok": True,
            "applied": applied,
            "created_stations": created_stations,
            "songs": len(isrc_to_song),
            "stations": len(chan_to_station),
        })
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


# ---------- RESUMEN (ADMIN y PÚBLICO) ----------
def build_summary_context(base_week: date):
    session_db = db()

    prev_w, base_w, next_w = week_tabs(base_week)
    current_week = monday_of(today_local())
    latest_with_data = week_with_latest_data(session_db)

    week_end = base_week + timedelta(days=6)
    week_label = f"{base_week.strftime('%d/%m/%Y')} - {week_end.strftime('%d/%m/%Y')}"

    artists = session_db.query(Artist).order_by(Artist.name.asc()).all()

    totals = {sid: int(total) for sid, total in (
        session_db.query(Play.song_id, func.sum(Play.spins))
        .filter(Play.week_start == base_week)
        .group_by(Play.song_id).all()
    )}
    prev_week = base_week - timedelta(days=7)
    totals_prev = {sid: int(total) for sid, total in (
        session_db.query(Play.song_id, func.sum(Play.spins))
        .filter(Play.week_start == prev_week)
        .group_by(Play.song_id).all()
    )}

    by_station = {}
    for row in (session_db.query(Play.song_id, Play.station_id, Play.spins, Play.position)
                .filter(Play.week_start == base_week).all()):
        by_station.setdefault(row.song_id, {})[row.station_id] = (row.spins, row.position)

    by_station_prev = {}
    for row in (session_db.query(Play.song_id, Play.station_id, Play.spins, Play.position)
                .filter(Play.week_start == prev_week).all()):
        by_station_prev.setdefault(row.song_id, {})[row.station_id] = (row.spins, row.position)

    # Orden + filtro: solo emisoras con > 1 tocada
    by_station_sorted = {}
    for song_id, st_dict in by_station.items():
        filtered = {st_id: pair for st_id, pair in st_dict.items() if (pair[0] or 0) > 0}
        by_station_sorted[song_id] = sorted(filtered.items(), key=lambda kv: kv[1][0], reverse=True)

    stations = session_db.query(RadioStation).order_by(RadioStation.name.asc()).all()
    stations_map = {s.id: s for s in stations}

    song_ids_this_week = set(totals.keys())
    songs = []
    if song_ids_this_week:
        songs = (session_db.query(Song)
                 .filter(Song.id.in_(song_ids_this_week))
                 .order_by(Song.release_date.desc())
                 .all())
        for s in songs: _ = s.artists

    ranks = {r.song_id: r.national_rank for r in
             session_db.query(SongWeekInfo).filter_by(week_start=base_week).all()}

    # Por artista: canciones ordenadas de MÁS a MENOS tocadas + último lanzamiento (release_date
    # más reciente entre las del artista que aparecen en el reporte).
    songs_by_artist = {}
    latest_release_by_artist = {}
    for a in artists:
        a_songs = [s for s in songs if a in s.artists]
        if not a_songs:
            continue
        a_songs.sort(key=lambda s: totals.get(s.id, 0), reverse=True)
        songs_by_artist[a.id] = a_songs
        _dates = [s.release_date for s in a_songs if s.release_date]
        latest_release_by_artist[a.id] = max(_dates) if _dates else None

    session_db.close()
    return dict(
        base_week=base_week,
        songs_by_artist=songs_by_artist,
        latest_release_by_artist=latest_release_by_artist,
        prev_w=prev_w, next_w=next_w,
        current_week=current_week,
        latest_with_data=latest_with_data,
        week_end=week_end,
        week_label=week_label,
        artists=artists,
        songs=songs,
        totals=totals, totals_prev=totals_prev,
        by_station=by_station, by_station_prev=by_station_prev,
        by_station_sorted=by_station_sorted,
        stations_map=stations_map,
        ranks=ranks
    )

@app.route("/resumen")
def summary_view():
    requested = request.args.get("week")
    base_week = monday_of(parse_date(requested)) if requested else week_with_latest_data(db())
    ctx = build_summary_context(base_week)
    # endpoint para tabs (admin)
    ctx.update(PUBLIC_MODE=False, summary_endpoint="summary_view")
    return render_template("summary.html", **ctx)

@app.route("/public/resumen")
def public_summary():
    requested = request.args.get("week")
    base_week = monday_of(parse_date(requested)) if requested else week_with_latest_data(db())
    ctx = build_summary_context(base_week)
    # endpoint para tabs (público)
    ctx.update(PUBLIC_MODE=True, summary_endpoint="public_summary")
    return render_template("summary.html", **ctx)

# ---------- RESUMEN POR EMISORA ----------
@app.route("/resumen/cadena/<station_id>")
def station_summary(station_id):
    """
    Resumen de una emisora: canciones ordenadas por artista con las tocadas de ESA cadena,
    navegable por semanas. Robusto ante IDs inválidos y falta de datos.
    """
    # 1) Validar/converter el parámetro
    try:
        stid = to_uuid(station_id)
    except Exception:
        flash("Identificador de emisora inválido.", "danger")
        return redirect(url_for("summary_view"))

    session_db = db()
    try:
        # 2) Obtener la emisora
        station = session_db.get(RadioStation, stid)
        if not station:
            flash("Emisora no encontrada.", "warning")
            return redirect(url_for("summary_view"))

        # 3) Determinar semana base (si no hay datos de esta emisora,
        #    usamos la semana actual-7 como fallback coherente)
        requested = request.args.get("week")
        if requested:
            base_week = monday_of(parse_date(requested))
        else:
            latest_for_station = week_with_latest_data(session_db, stid)
            # Si no hay datos en esa emisora, toma semana anterior a la actual (coherente con Tocadas)
            if latest_for_station is None or latest_for_station == monday_of(date.today()):
                base_week = monday_of(date.today()) - timedelta(days=7)
            else:
                base_week = latest_for_station

        # 4) Asegurar semanas prev/actual/next en tabla weeks
        prev_w, base_w, next_w = week_tabs(base_week)
        ensure_week(session_db, prev_w)
        ensure_week(session_db, base_w)
        ensure_week(session_db, next_w)
        session_db.commit()

        # 5) Cargar plays de ESA emisora en la semana base (>0 para no mostrar vacíos)
        plays = (session_db.query(Play)
                 .filter(Play.week_start == base_week,
                         Play.station_id == stid,
                         Play.spins > 0)
                 .all())

        # 6) Canciones involucradas y sus artistas (orden por lanzamiento desc)
        song_ids = {p.song_id for p in plays}
        songs = []
        if song_ids:
            songs = (session_db.query(Song)
                     .filter(Song.id.in_(song_ids))
                     .order_by(Song.release_date.desc())
                     .all())
            # carga ansiosa de artistas para agrupar por bloque
            for s in songs:
                _ = s.artists

        # 7) Mapas actual y previo para diffs
        by_song = {p.song_id: (p.spins, p.position) for p in plays}
        prev_week = base_week - timedelta(days=7)
        prev_plays = (session_db.query(Play)
                      .filter(Play.week_start == prev_week, Play.station_id == stid)
                      .all())
        by_song_prev = {p.song_id: (p.spins, p.position) for p in prev_plays}

        # 8) Agrupar por artista (solo artistas con canciones en la lista)
        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
        artist_blocks = []
        if songs:
            for a in artists:
                ss = [s for s in songs if a in s.artists]
                if ss:
                    artist_blocks.append((a, ss))

        # 9) Utilidades de navegación
        weeks_list = [w[0] for w in session_db.query(Week.week_start)
                      .order_by(Week.week_start.desc()).all()]
        week_end = base_week + timedelta(days=6)
        week_label = f"{base_week.strftime('%d/%m/%Y')} - {week_end.strftime('%d/%m/%Y')}"

        # 10) Pasar el id como string para evitar problemas en url_for/Jinja
        station_id_str = str(stid)

        return render_template(
            "station_summary.html",
            station=station,
            station_id_str=station_id_str,
            base_week=base_week,
            prev_w=prev_w, next_w=next_w,
            week_label=week_label,
            artist_blocks=artist_blocks,
            by_song=by_song, by_song_prev=by_song_prev,
            weeks_list=weeks_list,
            PUBLIC_MODE=not bool(session.get("user_id"))
        )

    except Exception as e:
        session_db.rollback()
        # Mostramos un mensaje en la UI en vez del 500 en blanco.
        flash(f"Error al mostrar el resumen de la emisora: {e}", "danger")
        return redirect(url_for("summary_view"))
    finally:
        session_db.close()

# ---------- API ----------
@app.get("/api/plays_json")
def api_plays_json():
    song_id = to_uuid(request.args.get("song_id"))
    station_id_param = request.args.get("station_id")
    station_id = to_uuid(station_id_param) if station_id_param else None

    session_db = db()
    q = session_db.query(Play.week_start, func.sum(Play.spins)).filter(Play.song_id == song_id)
    if station_id:
        q = q.filter(Play.station_id == station_id)
    q = q.group_by(Play.week_start).order_by(Play.week_start.asc())
    data = q.all()
    session_db.close()
    labels = [w.strftime("%Y-%m-%d") for (w, _) in data]
    values = [int(v) for (_, v) in data]
    return jsonify({"labels": labels, "values": values})

@app.get("/api/song_meta")
def api_song_meta():
    sid = request.args.get("song_id")
    try:
        sid_uuid = to_uuid(sid)
    except Exception:
        return jsonify({"error": "bad id"}), 400
    session_db = db()
    s = session_db.get(Song, sid_uuid)
    if not s:
        session_db.close()
        return jsonify({"error": "not found"}), 404
    artists = [{"id": str(a.id), "name": a.name, "photo_url": a.photo_url} for a in s.artists]
    payload = {"song_id": str(s.id), "title": s.title, "cover_url": s.cover_url, "artists": artists}
    session_db.close()
    return jsonify(payload)

# ----------- PROMOTORES ------------
@app.route("/promotores", methods=["GET", "POST"])
@admin_required
def promoters_view():
    session = db()
    try:
        if request.method == "POST":
            nick = (request.form.get("nick") or "").strip()
            first_name = (request.form.get("first_name") or "").strip()
            last_name = (request.form.get("last_name") or "").strip()
            contact_email = (request.form.get("contact_email") or "").strip()
            logo = request.files.get("logo")
            # Nick por defecto = nombre oficial (útil al dar de alta desde un DNI/pasaporte).
            if not nick:
                nick = " ".join([x for x in (first_name, last_name) if x]).strip()
            try:
                if not nick:
                    raise ValueError("Indica un nick (o el nombre del documento).")
                logo_url = upload_image(logo, "promoters") if (logo and getattr(logo, "filename", "")) else None
                kind = (request.form.get("kind") or "").strip().lower()
                if kind not in ("empresa", "institucion"):
                    kind = None
                p = Promoter(
                    nick=nick,
                    logo_url=logo_url,
                    tax_id=(request.form.get("tax_id") or "").strip() or None,
                    contact_email=contact_email or None,
                    contact_phone=(request.form.get("contact_phone") or "").strip() or None,
                    kind=kind,
                    first_name=first_name or None,
                    last_name=last_name or None,
                    address=(request.form.get("address") or "").strip() or None,
                )
                session.add(p)
                session.flush()
                _person_document_create_from_intake(session, "PROMOTER", p)
                linked_embargos = _auto_link_embargo_orders_for_promoter(session, p) if "_auto_link_embargo_orders_for_promoter" in globals() else 0
                session.commit()
                flash("Tercero creado.", "success")
                if linked_embargos:
                    flash(f"Se han vinculado {linked_embargos} orden(es) de embargo pendientes a este tercero.", "warning")
            except Exception as e:
                session.rollback()
                flash(f"Error creando tercero: {e}", "danger")
            return redirect(url_for("promoters_view"))

        promoters = session.query(Promoter).order_by(func.lower(Promoter.nick).asc(), Promoter.nick.asc()).all()
        royalty_ids = {pid for (pid,) in (session.query(SongRoyaltyBeneficiary.promoter_id).filter(SongRoyaltyBeneficiary.promoter_id.isnot(None)).distinct().all()) if pid}
        royalty_ids.update({pid for (pid,) in (session.query(AlbumRoyaltyBeneficiary.promoter_id).filter(AlbumRoyaltyBeneficiary.promoter_id.isnot(None)).distinct().all()) if pid})
        promoter_ids = {pid for (pid,) in (session.query(Concert.promoter_id).filter(Concert.promoter_id.isnot(None)).distinct().all()) if pid}
        promoter_ids.update({pid for (pid,) in (session.query(ConcertPromoterShare.promoter_id).filter(ConcertPromoterShare.promoter_id.isnot(None)).distinct().all()) if pid})
        author_ids = {pid for (pid,) in (session.query(SongEditorialShare.promoter_id).filter(SongEditorialShare.promoter_id.isnot(None)).distinct().all()) if pid}

        promoter_tag_tabs: list[str] = []
        for promoter in promoters:
            tags: list[str] = []
            pid = getattr(promoter, 'id', None)
            if pid in royalty_ids:
                tags.append('Beneficiarios de royalties')
            if pid in promoter_ids:
                tags.append('Promotores')
            if pid in author_ids:
                tags.append('Autores / compositores')
            setattr(promoter, 'display_tags', tags)
            promoter_tag_tabs.extend(tags)

        promoter_tag_tabs = sorted(set(promoter_tag_tabs), key=lambda value: value.casefold())
        return render_template(
            "promoters.html",
            promoters=promoters,
            promoter_tag_tabs=promoter_tag_tabs,
            import_fields=[{"key": k, "label": l} for k, l, _kind, _al in promoter_import.FIELDS],
            import_target_ignore=promoter_import.TARGET_IGNORE,
            import_target_alt=promoter_import.TARGET_ALT,
        )
    finally:
        session.close()


# ==================== IMPORTAR TERCEROS DESDE UN FICHERO ====================
# Excel o CSV. El motor puro (leer el fichero y reconocer sus columnas) está en `promoter_import.py`;
# aquí solo se decide quién existe ya, qué se crea y cómo se fusiona.
# Flujo: analizar (columnas) → preparar (nuevos vs. ya existentes, con el diff campo a campo) →
# crear los nuevos → fusionar los existentes UNO A UNO en pantalla partida.

def _promoter_alt_value_rows(session_db, promoter) -> list[dict]:
    """Los datos con nombre de un tercero, para la ficha. El que además está en la ficha se marca
    como **principal** (no se repite dos veces la misma dirección con y sin nombre)."""
    if not promoter:
        return []
    filas = []
    for row in (session_db.query(PromoterAltValue)
                .filter(PromoterAltValue.promoter_id == promoter.id)
                .order_by(PromoterAltValue.created_at.asc()).all()):
        campo = (getattr(row, "field", None) or "").strip()
        actual = (getattr(promoter, campo, None) or "").strip() if campo else ""
        filas.append({
            "id": str(row.id),
            "field": campo,
            "field_label": promoter_import.FIELD_LABELS.get(campo, ""),
            "label": (row.label or "").strip(),
            "value": (row.value or "").strip(),
            "is_primary": bool(actual and _norm_text_key(actual) == _norm_text_key(row.value or "")),
        })
    return filas


def _promoter_import_can_edit() -> bool:
    return bool(is_master() or has_access_key("third_parties", edit=True, include_descendants=True))


def _promoter_import_indexes(session_db) -> dict:
    """Índices para saber si un tercero del fichero ya está: por DNI/NIF (también el de sus
    sociedades), por nick y por nombre y apellidos."""
    por_doc, por_nick, por_nombre = {}, {}, {}
    for p in session_db.query(Promoter).all():
        pid = str(p.id)
        doc = _prl_norm_dni(getattr(p, "tax_id", None) or "")
        if doc:
            por_doc.setdefault(doc, pid)
        nick_key = _norm_text_key(getattr(p, "nick", None) or "")
        if nick_key:
            por_nick.setdefault(nick_key, pid)
        nombre = _norm_text_key(" ".join([x for x in [(getattr(p, "first_name", None) or ""),
                                                      (getattr(p, "last_name", None) or "")] if x]))
        if nombre:
            por_nombre.setdefault(nombre, pid)
    for row in session_db.query(PromoterCompany).all():
        doc = _prl_norm_dni(getattr(row, "tax_id", None) or "")
        if doc and getattr(row, "promoter_id", None):
            por_doc.setdefault(doc, str(row.promoter_id))
    return {"doc": por_doc, "nick": por_nick, "name": por_nombre}


def _promoter_import_match(indexes: dict, values: dict) -> tuple[str | None, str]:
    """(id del tercero, por qué se ha reconocido). El DNI/NIF manda: es el único dato que no se
    repite. Luego el nick exacto y, por último, el nombre y los apellidos."""
    doc = _prl_norm_dni(values.get("tax_id") or "")
    if doc and doc in indexes["doc"]:
        return indexes["doc"][doc], "por su DNI / NIF"
    nick_key = _norm_text_key(values.get("nick") or "")
    if nick_key and nick_key in indexes["nick"]:
        return indexes["nick"][nick_key], "por el nick"
    nombre = _norm_text_key(" ".join([x for x in [(values.get("first_name") or ""),
                                                  (values.get("last_name") or "")] if x]))
    if nombre:
        if nombre in indexes["name"]:
            return indexes["name"][nombre], "por el nombre y los apellidos"
        if nombre in indexes["nick"]:
            return indexes["nick"][nombre], "por el nombre"
    return None, ""


def _promoter_import_nick(values: dict) -> str:
    """El nick con el que se da de alta: el del fichero, o el nombre completo, o el DNI/NIF."""
    for candidato in (values.get("nick"),
                      " ".join([x for x in [(values.get("first_name") or ""),
                                            (values.get("last_name") or "")] if x]),
                      values.get("tax_id")):
        texto = re.sub(r"\s+", " ", str(candidato or "")).strip()
        if texto:
            return texto
    return ""


def _promoter_import_label(session_db, promoter) -> dict:
    return {
        "id": str(promoter.id),
        "nick": (getattr(promoter, "nick", None) or "").strip(),
        "name": _promoter_display_name(promoter),
        "logo_url": (getattr(promoter, "logo_url", None) or "").strip(),
        "tax_id": (getattr(promoter, "tax_id", None) or "").strip(),
        "url": url_for("promoter_detail_view", pid=promoter.id),
    }


def _promoter_import_apply_values(session_db, promoter, values: dict, *, only_empty: bool) -> list[str]:
    """Escribe los campos en el tercero. Con `only_empty` solo rellena lo que está vacío."""
    tocados = []
    for campo, valor in (values or {}).items():
        if campo not in promoter_import.FIELD_LABELS or campo == "nick":
            continue
        valor = (valor or "").strip()
        if not valor:
            continue
        actual = (getattr(promoter, campo, None) or "").strip()
        if only_empty and actual:
            continue
        if actual == valor:
            continue
        setattr(promoter, campo, valor)
        tocados.append(campo)
    return tocados


def _promoter_import_add_alt(session_db, promoter, field, label, value) -> bool:
    """Guarda un dato alternativo con nombre (sin repetir el mismo par nombre+valor).
    Los correos van a `PromoterEmail`, que es donde los busca el resto de la app."""
    label = re.sub(r"\s+", " ", str(label or "")).strip() or "Otro dato"
    value = re.sub(r"\s+", " ", str(value or "")).strip()
    if not value:
        return False
    if field == "contact_email":
        ya = (session_db.query(PromoterEmail.id)
              .filter(PromoterEmail.promoter_id == promoter.id,
                      func.lower(PromoterEmail.email) == value.lower()).first())
        if ya:
            return False
        session_db.add(PromoterEmail(promoter_id=promoter.id, concept=label[:120], email=value))
        return True
    ya = (session_db.query(PromoterAltValue.id)
          .filter(PromoterAltValue.promoter_id == promoter.id,
                  PromoterAltValue.label == label[:120],
                  PromoterAltValue.value == value).first())
    if ya:
        return False
    session_db.add(PromoterAltValue(promoter_id=promoter.id, field=(field or None),
                                    label=label[:120], value=value))
    return True


@app.post("/promotores/importar/analizar", endpoint="promoters_import_analyze")
@admin_required
def promoters_import_analyze():
    """Lee el fichero y devuelve SUS COLUMNAS con el campo que se les ha reconocido. Lo que no se
    reconoce se devuelve sin campo para que la pantalla pregunte a qué corresponde."""
    if not _promoter_import_can_edit():
        return jsonify({"ok": False, "error": "No tienes permisos para añadir terceros."}), 403
    f = request.files.get("file")
    if not f or not getattr(f, "filename", ""):
        return jsonify({"ok": False, "error": "Sube un fichero de Excel (.xlsx) o CSV."}), 400
    try:
        data = f.read()
        if not data:
            return jsonify({"ok": False, "error": "El fichero está vacío."}), 400
        parsed = promoter_import.parse_file(data, getattr(f, "filename", ""))
    except ValueError as e:
        return jsonify({"ok": False, "error": str(e)}), 400
    except Exception as e:
        return jsonify({"ok": False, "error": f"No se pudo leer el fichero: {e}"}), 400
    if not parsed["rows"]:
        return jsonify({"ok": False, "error": "El fichero no tiene ninguna fila con datos."}), 400
    return jsonify({
        "ok": True,
        "filename": getattr(f, "filename", ""),
        "columns": parsed["columns"],
        "rows": parsed["rows"],
        "count": parsed["sheet_rows"],
        "unknown": sum(1 for c in parsed["columns"] if not c["field"]),
    })


@app.post("/promotores/importar/preparar", endpoint="promoters_import_prepare")
@admin_required
def promoters_import_prepare():
    """Con las columnas ya asignadas: quién es NUEVO y quién YA ESTABA (con el diff campo a campo)."""
    if not _promoter_import_can_edit():
        return jsonify({"ok": False, "error": "No tienes permisos para añadir terceros."}), 403
    payload = request.get_json(silent=True) or {}
    fichas = promoter_import.apply_mapping(payload.get("rows") or [], payload.get("mapping") or {})
    if not fichas:
        return jsonify({"ok": False, "error": "Con las columnas elegidas no queda ningún dato que importar."}), 400
    session_db = db()
    try:
        indexes = _promoter_import_indexes(session_db)
        nuevos, existentes, sin_nombre = [], [], 0
        for i, ficha in enumerate(fichas):
            values = ficha["values"]
            pid, motivo = _promoter_import_match(indexes, values)
            if pid:
                p = session_db.get(Promoter, to_uuid(pid))
                if not p:
                    pid = None
            if pid and p:
                campos = []
                for campo in promoter_import.FIELD_KEYS:
                    entra = (values.get(campo) or "").strip()
                    if not entra:
                        continue
                    actual = (getattr(p, campo, None) or "").strip()
                    campos.append({
                        "key": campo,
                        "label": promoter_import.FIELD_LABELS[campo],
                        "current": actual,
                        "incoming": entra,
                        "same": _norm_text_key(actual) == _norm_text_key(entra),
                    })
                existentes.append({
                    "row": i,
                    "promoter": _promoter_import_label(session_db, p),
                    "match_reason": motivo,
                    "values": values,
                    "alt": ficha["alt"],
                    "fields": campos,
                    "diff": sum(1 for c in campos if not c["same"]),
                })
                continue
            nick = _promoter_import_nick(values)
            if not nick:
                sin_nombre += 1
                continue
            nuevos.append({"row": i, "nick": nick, "values": values, "alt": ficha["alt"]})
        return jsonify({
            "ok": True,
            "new": nuevos,
            "existing": existentes,
            "skipped_no_name": sin_nombre,
            "counts": {"new": len(nuevos), "existing": len(existentes), "skipped": sin_nombre},
        })
    finally:
        session_db.close()


@app.post("/promotores/importar/crear", endpoint="promoters_import_create")
@admin_required
def promoters_import_create():
    """Da de alta los terceros nuevos. Cada uno en su savepoint: si uno falla, los demás entran."""
    if not _promoter_import_can_edit():
        return jsonify({"ok": False, "error": "No tienes permisos para añadir terceros."}), 403
    payload = request.get_json(silent=True) or {}
    filas = payload.get("rows") or []
    if not filas:
        return jsonify({"ok": False, "error": "No hay terceros nuevos que crear."}), 400
    session_db = db()
    creados, errores = [], []
    try:
        for fila in filas:
            values = (fila or {}).get("values") or {}
            alt = (fila or {}).get("alt") or []
            nick = _promoter_import_nick(values)
            if not nick:
                errores.append("Una fila no tiene ni nombre ni DNI/NIF: no se puede dar de alta.")
                continue
            try:
                with session_db.begin_nested():
                    p = Promoter(nick=_intake_unique_nick(session_db, nick))
                    session_db.add(p)
                    session_db.flush()
                    _promoter_import_apply_values(session_db, p, values, only_empty=False)
                    for extra in alt:
                        _promoter_import_add_alt(session_db, p, None,
                                                 (extra or {}).get("label"), (extra or {}).get("value"))
                    if "_auto_link_embargo_orders_for_promoter" in globals():
                        _auto_link_embargo_orders_for_promoter(session_db, p)
                    creados.append({"id": str(p.id), "nick": p.nick})
            except Exception as e:
                errores.append(f"{nick}: {e}")
        session_db.commit()
        return jsonify({"ok": True, "created": creados, "errors": errores})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": f"No se pudieron crear los terceros: {e}"}), 400
    finally:
        session_db.close()


@app.post("/promotores/<pid>/importar/fusionar", endpoint="promoters_import_merge")
@admin_required
def promoters_import_merge(pid):
    """Actualiza un tercero que ya existía con lo que trae el fichero, campo a campo.

    Por cada campo: `current` (se queda lo nuestro), `incoming` (manda el fichero) o `both`
    (**conservar los dos**: uno se queda en la ficha y el otro se guarda como dato con nombre —el
    ejemplo de Dani: dos direcciones, «casa de Madrid» y «casa de Cádiz»—)."""
    if not _promoter_import_can_edit():
        return jsonify({"ok": False, "error": "No tienes permisos para editar terceros."}), 403
    payload = request.get_json(silent=True) or {}
    decisiones = payload.get("decisions") or {}
    values = payload.get("values") or {}
    alt = payload.get("alt") or []
    session_db = db()
    try:
        p = session_db.get(Promoter, to_uuid(pid))
        if not p:
            return jsonify({"ok": False, "error": "Tercero no encontrado."}), 404
        cambios, extras = 0, 0
        for campo, decision in decisiones.items():
            if campo not in promoter_import.FIELD_LABELS:
                continue
            decision = decision if isinstance(decision, dict) else {"choice": str(decision or "")}
            eleccion = (decision.get("choice") or "").strip().lower()
            entra = (values.get(campo) or "").strip()
            actual = (getattr(p, campo, None) or "").strip()
            if not entra or eleccion in ("", "current"):
                continue
            if eleccion == "incoming":
                if campo == "nick":
                    nuevo = _intake_unique_nick(session_db, entra, exclude_id=p.id)
                    if nuevo != actual:
                        p.nick = nuevo
                        cambios += 1
                elif actual != entra:
                    setattr(p, campo, entra)
                    cambios += 1
                continue
            if eleccion == "both":
                principal = (decision.get("primary") or "current").strip().lower()
                et_actual = (decision.get("label_current") or "").strip()
                et_nueva = (decision.get("label_incoming") or "").strip()
                # Uno se queda en la ficha y el otro pasa a «otros datos» con su nombre.
                if principal == "incoming":
                    valor_ficha, valor_otro = entra, actual
                    et_ficha, et_otro = et_nueva, et_actual
                else:
                    valor_ficha, valor_otro = actual, entra
                    et_ficha, et_otro = et_actual, et_nueva
                if valor_ficha != actual:
                    if campo == "nick":
                        p.nick = _intake_unique_nick(session_db, valor_ficha, exclude_id=p.id)
                    else:
                        setattr(p, campo, valor_ficha)
                    cambios += 1
                # ⚠️ El que NO se queda en la ficha se guarda SIEMPRE (con un nombre por defecto si
                # no se le puso ninguno): la idea de «conservar los dos» es no perder nada.
                if valor_otro and _promoter_import_add_alt(
                        session_db, p, campo,
                        et_otro or f"Otro/a {promoter_import.FIELD_LABELS[campo].lower()}", valor_otro):
                    extras += 1
                # El de la ficha solo se apunta si se le ha puesto nombre (así se sabe cuál es cuál:
                # «casa de Madrid» / «casa de Cádiz»). En la ficha sale marcado como principal.
                if valor_ficha and et_ficha and _promoter_import_add_alt(session_db, p, campo, et_ficha, valor_ficha):
                    extras += 1
        for extra in alt:
            if _promoter_import_add_alt(session_db, p, None, (extra or {}).get("label"), (extra or {}).get("value")):
                extras += 1
        session_db.commit()
        return jsonify({"ok": True, "changed": cambios, "extras": extras,
                        "promoter": {"id": str(p.id), "nick": p.nick}})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": f"No se pudo actualizar: {e}"}), 400
    finally:
        session_db.close()


