@app.post("/promotores/<pid>/update")
@admin_required
def promoter_update(pid):
    session = db()
    p = session.get(Promoter, to_uuid(pid))
    next_url = (request.form.get("next") or "").strip() or url_for("promoters_view")
    if not p:
        flash("Promotor no encontrado.", "warning")
        session.close()
        return redirect(next_url)
    p.nick = request.form.get("nick", p.nick).strip()
    # NOMBRE Y APELLIDOS (una persona los tiene además del nick: el nick es como la llamamos).
    if "first_name" in request.form:
        p.first_name = (request.form.get("first_name") or "").strip() or None
    if "last_name" in request.form:
        p.last_name = (request.form.get("last_name") or "").strip() or None
    p.tax_id = (request.form.get("tax_id") or p.tax_id or "").strip() or None
    p.contact_email = (request.form.get("contact_email") or p.contact_email or "").strip() or None
    p.contact_phone = (request.form.get("contact_phone") or p.contact_phone or "").strip() or None
    if "address" in request.form:
        p.address = (request.form.get("address") or "").strip() or None
    # DIRECCIÓN FISCAL en piezas (calle, CP, municipio, provincia, país): es la que se manda a Holded
    # al crear el proveedor. Solo se toca si el formulario la trae, para no pisarla desde otras
    # pantallas que también guardan terceros.
    if "fiscal_address" in request.form or "fiscal_postal_code" in request.form:
        _apply_fiscal_address(p, _fiscal_form_values(request.form))
    if "hotel_notes" in request.form:
        p.hotel_notes = (request.form.get("hotel_notes") or "").strip() or None
    # Necesidades de viaje (solo si el formulario las trae, para no pisarlas desde otras pantallas).
    if request.form.get("travel_prefs_present"):
        p.travel_notes = (request.form.get("travel_notes") or "").strip() or None
        p.travel_prefs = _parse_travel_prefs_form(request.form)
        p.travel_departure_flight = (request.form.get("travel_departure_flight") or "").strip() or None
        p.travel_departure_train = (request.form.get("travel_departure_train") or "").strip() or None
    if "kind" in request.form:
        _kind = (request.form.get("kind") or "").strip().lower()
        p.kind = _kind if _kind in ("empresa", "institucion") else None
    # PREFERENCIA de comunicación (correo o SMS). ⚠️ Solo tiene sentido con las DOS cosas puestas: si
    # se queda con una sola, se borra (no hay nada que preferir y no se preguntará más).
    if "notify_channel" in request.form:
        _pref = _notify_pref_clean(request.form.get("notify_channel"))
        p.notify_channel = _pref or None
    if not ((p.contact_email or "").strip() and (p.contact_phone or "").strip()):
        p.notify_channel = None
    # Redes sociales (para menciones): solo se tocan si el formulario incluye esos campos.
    if any(("social_" + _k) in request.form for _k, _l, _i in PROMOTER_SOCIAL_PLATFORMS):
        p.social_links = _promoter_social_links_from_form(request.form)
    logo = request.files.get("logo")
    try:
        if logo and logo.filename:
            p.logo_url = upload_image(logo, "promoters")
        linked_embargos = _auto_link_embargo_orders_for_promoter(session, p) if "_auto_link_embargo_orders_for_promoter" in globals() else 0
        # El correo y el teléfono de la ficha son DATOS DE CONTACTO: se cruzan con su pestaña.
        _promoter_sync_contact_rows(session, p)
        # Propaga el nuevo email/teléfono a sus invitaciones aún no enviadas (envío al último dato).
        _invitation_sync_contact_for_entity(session, promoter_id=p.id, email=p.contact_email, phone=p.contact_phone)
        session.commit()
        flash("Tercero actualizado.", "success")
        if linked_embargos:
            flash(f"Se han vinculado {linked_embargos} orden(es) de embargo pendientes a este tercero.", "warning")
    except Exception as e:
        session.rollback()
        flash(f"Error actualizando: {e}", "danger")
    finally:
        session.close()
    return redirect(next_url)

