@app.post("/recintos/<vid>/ticketing", endpoint="venue_ticketing_save")
@admin_required
def venue_ticketing_save(vid):
    """Guarda la plantilla de ticketing del recinto (categorías y aforos, sin precio)."""
    if not can_edit_catalogs():
        flash("No tienes permisos para editar el recinto.", "warning")
        return redirect(url_for("venue_detail_view", vid=vid, tab="ticketing"))
    s = db()
    try:
        venue = s.get(Venue, to_uuid(vid))
        if not venue:
            abort(404)
        try:
            data = json.loads(request.form.get("ticketing_json") or "[]")
        except Exception:
            data = []
        if not isinstance(data, list):
            data = []
        # FORMATO al que pertenece este ticketing (subpestaña): se reemplazan SOLO sus categorías.
        sm = _venue_seatmap_resolve(s, venue.id, request.form.get("map_id"))
        for c in _venue_ticket_categories_for(s, venue.id, sm):
            s.delete(c)
        s.flush()
        for i, row in enumerate(data):
            if not isinstance(row, dict):
                continue
            zone = str(row.get("zone") or "PISTA").upper()
            # OTROS = categorías (p. ej. venidas del mapa) aún sin clasificar; se arrastran luego.
            if zone not in ("PISTA", "GRADA", "PALCO", "OTROS"):
                zone = "PISTA"
            cat = VenueTicketCategory(
                venue_id=venue.id, seat_map_id=(sm.id if sm is not None else None), zone=zone,
                name=str(row.get("name") or "").strip(),
                quantity=_sim_int(row.get("qty")), invitations=_sim_int(row.get("inv")),
                sort_order=i,
            )
            s.add(cat)
            s.flush()
            for j, ex in enumerate(row.get("extras") or []):
                if not isinstance(ex, dict):
                    continue
                nm = str(ex.get("name") or "").strip()
                if not nm:
                    continue
                s.add(VenueTicketExtra(category_id=cat.id, name=nm, amount_gross=_sim_d(ex.get("amount")), sort_order=j))
        s.commit()
        flash("Ticketing del recinto guardado.", "success")
    except Exception as e:
        s.rollback()
        flash(f"Error guardando el ticketing del recinto: {e}", "danger")
    finally:
        s.close()
    return redirect(url_for("venue_detail_view", vid=vid, tab="ticketing", map=(request.form.get("map_id") or None)))


def _venue_seatmap_default(session_db, venue_id):
    """FORMATO principal del recinto (mapa por defecto, o None): el que se ofrece en simulaciones,
    conciertos e invitaciones."""
    return (
        session_db.query(VenueSeatMap)
        .filter(VenueSeatMap.venue_id == venue_id)
        .order_by(VenueSeatMap.is_default.desc(), VenueSeatMap.created_at.asc())
        .first()
    )


def _concert_seatmap(session_db, concert):
    """FORMATO del recinto que usa ESTA actividad.

    Un recinto puede tener varios formatos («Formato 360», «Escenario central»…). Si la actividad
    tiene uno elegido (`Concert.seat_map_id`) y sigue siendo de su recinto, manda ese; si no, el
    principal. Punto ÚNICO: lo usan las invitaciones sobre el plano, el asignador y el plano en vivo
    de Enterticket, así que las tres pantallas casan las butacas contra el mismo mapa."""
    venue_id = getattr(concert, "venue_id", None)
    if not venue_id:
        return None
    chosen_id = getattr(concert, "seat_map_id", None)
    if chosen_id:
        sm = session_db.get(VenueSeatMap, chosen_id)
        # Si alguien cambió el recinto de la actividad, el formato viejo ya no vale.
        if sm is not None and str(sm.venue_id) == str(venue_id):
            return sm
    return _venue_seatmap_default(session_db, venue_id)


def _venue_seatmap_all(session_db, venue_id):
    """Todos los FORMATOS de ticketing del recinto (subpestañas): el principal primero."""
    return (
        session_db.query(VenueSeatMap)
        .filter(VenueSeatMap.venue_id == venue_id)
        .order_by(VenueSeatMap.is_default.desc(), VenueSeatMap.created_at.asc())
        .all()
    )


def _venue_seatmap_resolve(session_db, venue_id, map_id):
    """Formato pedido (?map=… / map_id) si pertenece al recinto; si no, el principal."""
    if map_id:
        sm = session_db.get(VenueSeatMap, _safe_uuid(map_id))
        if sm is not None and str(sm.venue_id) == str(venue_id):
            return sm
    return _venue_seatmap_default(session_db, venue_id)


def _venue_ticket_categories_for(session_db, venue_id, sm):
    """Categorías clásicas (plantilla de aforos) del recinto PARA UN FORMATO: las ligadas a ese
    mapa y, si el formato es el principal (o el recinto no tiene mapas), también las legado sin
    formato (seat_map_id NULL)."""
    q = (
        session_db.query(VenueTicketCategory)
        .options(selectinload(VenueTicketCategory.extras))
        .filter(VenueTicketCategory.venue_id == venue_id)
    )
    if sm is None:
        q = q.filter(VenueTicketCategory.seat_map_id.is_(None))
    elif sm.is_default:
        q = q.filter(or_(VenueTicketCategory.seat_map_id == sm.id, VenueTicketCategory.seat_map_id.is_(None)))
    else:
        q = q.filter(VenueTicketCategory.seat_map_id == sm.id)
    return q.order_by(VenueTicketCategory.zone.asc(), VenueTicketCategory.sort_order.asc()).all()


def _venue_seatmap_payload(sm) -> dict:
    """Payload del mapa para embeber en la ficha (id/version para el bloqueo optimista)."""
    if not sm:
        return {"id": None, "name": "Principal", "version": 0, "layout": {}, "assignments": {}}
    return {
        "id": str(sm.id),
        "name": sm.name or "Principal",
        "version": int(sm.version or 0),
        "layout": sm.layout_json or {},
        "assignments": sm.assignments_json or {},
    }


_VENUE_MAP_INV_SENTISH = {"SENT", "DELIVERED", "PICKED_UP", "PRINTED", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA", "ENTREGADAS_MANO"}


def _invitation_venue_map_payload(sm, ticket_payloads) -> dict | None:
    """Payload del VISOR del mapa del recinto para la página del evento de invitaciones: casa las
    entradas subidas (sector/fila/asiento del PDF) con el mapa por nombre+alias (seatmap_calc) y
    pinta cada butaca casada con el color de su INVITADO (categorías sintéticas: el JS del mapa
    las trata como categorías normales → tooltip con el nombre y bloques nombre+raya al acercar).
    Devuelve {payload, matched, unmatched} o None si no hay nada que casar."""
    layout = sm.layout_json or {}
    if not (layout.get("sections") or []):
        return None
    lookup = seatmap_calc.seat_lookup(layout)
    assigned_states = {"ASSIGNED"} | _VENUE_MAP_INV_SENTISH
    guest_cats: dict[str, dict] = {}
    assignments: dict = {}
    matched = unmatched = 0
    by_cat: dict[str, dict] = {}     # por categoría de invitación: casadas / sin casar
    unmatched_secs: dict[str, int] = {}   # sectores de los PDF que no casan (para la alerta)
    for t in (ticket_payloads or []):
        if not (t.get("seat_number") or "").strip():
            continue   # sin numerar: no se casan con el plano
        _cstat = by_cat.setdefault(str(t.get("category_id") or ""), {"matched": 0, "unmatched": 0})
        key = seatmap_calc.match_ticket(lookup, t.get("sector"), t.get("row_label"), t.get("seat_number"))
        if not key:
            unmatched += 1
            _cstat["unmatched"] += 1
            _sec = (t.get("sector") or "").strip() or "(sin sector)"
            unmatched_secs[_sec] = unmatched_secs.get(_sec, 0) + 1
            continue
        matched += 1
        _cstat["matched"] += 1
        status = (t.get("status") or "").upper()
        if status not in assigned_states:
            continue   # disponible: se ve como butaca libre
        gkey = (t.get("assignee_key") or "").strip() or "__asignada"
        if gkey not in guest_cats:
            color = INVITATION_ASSIGNEE_COLORS[len(guest_cats) % len(INVITATION_ASSIGNEE_COLORS)] if gkey != "__asignada" else "#e0a800"
            guest_cats[gkey] = {
                "id": gkey,
                "name": (t.get("assignee_name") or "").strip() or "Asignada",
                "color": color, "kind": "guest",
            }
        sec, row, slot = key.split("|")
        assignments.setdefault(sec, {}).setdefault(row, []).append([int(slot), int(slot), gkey])
    if not matched:
        return None
    view_layout = dict(layout)
    view_layout["categories"] = list(guest_cats.values())
    return {
        "payload": {"id": str(sm.id), "name": sm.name or "", "version": int(sm.version or 0),
                    "layout": view_layout, "assignments": assignments},
        "matched": matched,
        "unmatched": unmatched,
        "by_cat": by_cat,
        "unmatched_secs": sorted(unmatched_secs, key=lambda k: -unmatched_secs[k])[:6],
    }


@app.post("/recintos/<vid>/mapa", endpoint="venue_seatmap_save")
@admin_required
def venue_seatmap_save(vid):
    """Guarda el mapa de butacas del recinto (layout paramétrico en JSONB). Upsert del mapa por
    defecto con BLOQUEO OPTIMISTA: el cliente manda la `version` que leyó; si en BD ya hay otra,
    se devuelve 409 y el front avisa (evita pisar en silencio la edición de otra persona)."""
    if not can_edit_catalogs():
        return jsonify({"ok": False, "error": "Sin permisos para editar el recinto."}), 403
    s = db()
    try:
        venue = s.get(Venue, to_uuid(vid))
        if not venue:
            abort(404)
        data = request.get_json(silent=True) or {}
        layout = data.get("layout")
        if not isinstance(layout, dict):
            return jsonify({"ok": False, "error": "Layout inválido."}), 400
        client_version = _safe_int(data.get("version"))
        # Con map_id se guarda ESE formato (subpestaña); sin él, el principal (compatibilidad).
        _map_id = str(data.get("map_id") or "").strip()
        if _map_id:
            sm = s.get(VenueSeatMap, _safe_uuid(_map_id))
            if sm is None or str(sm.venue_id) != str(venue.id):
                return jsonify({"ok": False, "error": "Formato no encontrado."}), 404
        else:
            sm = _venue_seatmap_default(s, venue.id)
        if sm is None:
            sm = VenueSeatMap(
                venue_id=venue.id,
                name=(str(data.get("name") or "").strip() or "Principal"),
                is_default=True,
                created_by_user_id=_safe_uuid(session.get("user_id")),
                created_by_nick=_current_user_email(),
            )
            s.add(sm)
        elif int(sm.version or 0) != client_version:
            return jsonify({
                "ok": False, "conflict": True,
                "error": "Otra persona ha guardado este mapa mientras lo editabas. Recarga la página para no pisar sus cambios.",
            }), 409
        sm.layout_json = layout
        # Asignación butaca→categoría (rangos por fila). Opcional: si no viene, se conserva la
        # actual; si viene con un tipo raro, mejor avisar que ignorarla en silencio.
        assignments = data.get("assignments")
        if assignments is not None and not isinstance(assignments, dict):
            return jsonify({"ok": False, "error": "Asignaciones inválidas."}), 400
        if isinstance(assignments, dict):
            sm.assignments_json = assignments
        sm.version = int(sm.version or 0) + 1
        sm.updated_at = _now_madrid()
        s.flush()
        # EL MAPA MANDA: si el plano tiene categorías con butacas asignadas (o zonas de pie), la
        # tabla de ticketing de ESTE formato se reemplaza por lo configurado en el plano (el
        # front avisa antes de guardar). Sin asignaciones no se toca lo escrito a mano.
        _venue_sync_ticketing_from_map(s, venue, sm)
        s.commit()
        return jsonify({"ok": True, "id": str(sm.id), "version": int(sm.version)})
    except Exception as exc:
        s.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        s.close()


def _venue_sync_ticketing_from_map(s, venue, sm) -> None:
    """Vuelca las categorías del MAPA a la tabla de ticketing del formato (VenueTicketCategory).

    Cantidades: butacas asignadas a cada categoría (rangos de assignments_json) + aforo de las
    zonas DE PIE asignadas (__floor). Zona: por el nombre de la categoría o de sus secciones
    (pista/grada/palco); si no se identifica, va a OTROS (en la tabla se arrastra a su tipo).
    Las categorías de tipo invitaciones/bloqueo cuentan su cupo como invitaciones reservadas."""
    layout = sm.layout_json if isinstance(sm.layout_json, dict) else {}
    assignments = sm.assignments_json if isinstance(sm.assignments_json, dict) else {}
    cats = [c for c in (layout.get("categories") or []) if isinstance(c, dict) and c.get("id")]
    if not cats or not assignments:
        return
    sections = {str(sec.get("id")): sec for sec in (layout.get("sections") or []) if isinstance(sec, dict)}
    counts: dict = {}      # cat_id -> nº butacas
    sec_names: dict = {}   # cat_id -> [nombres de sección donde está]
    sec_kinds: dict = {}   # cat_id -> set(kinds)
    for sec_id, rows in assignments.items():
        if not isinstance(rows, dict):
            continue
        sec = sections.get(str(sec_id)) or {}
        for rkey, ranges in rows.items():
            if rkey == "__floor":
                cid = str(ranges)
                counts[cid] = counts.get(cid, 0) + max(_safe_int(sec.get("cap")), 0)
                sec_names.setdefault(cid, []).append(str(sec.get("name") or ""))
                sec_kinds.setdefault(cid, set()).add("floor")
                continue
            if not isinstance(ranges, list):
                continue
            for rg in ranges:
                if not (isinstance(rg, list) and len(rg) >= 3):
                    continue
                cid = str(rg[2])
                counts[cid] = counts.get(cid, 0) + max(_safe_int(rg[1]) - _safe_int(rg[0]) + 1, 0)
                sec_names.setdefault(cid, []).append(str(sec.get("name") or ""))
                sec_kinds.setdefault(cid, set()).add(str(sec.get("kind") or ""))
    if not counts:
        return

    def _zone_for(cat, cid):
        blob = " ".join([str(cat.get("name") or "")] + sec_names.get(cid, [])).lower()
        if "palco" in blob:
            return "PALCO"
        if "pista" in blob or "ruedo" in blob or "arena" in blob:
            return "PISTA"
        if "grada" in blob or "tendido" in blob or "anfiteatro" in blob or "tribuna" in blob:
            return "GRADA"
        kinds = sec_kinds.get(cid, set())
        if kinds == {"floor"}:
            return "PISTA"
        if kinds == {"box"}:
            return "PALCO"
        return "OTROS"

    # En el formato PRINCIPAL se reemplazan también las filas legado sin formato (seat_map_id NULL),
    # que representan la misma tabla; si no, quedarían duplicadas al resolver el ticketing.
    _flt = (or_(VenueTicketCategory.seat_map_id == sm.id, VenueTicketCategory.seat_map_id.is_(None))
            if getattr(sm, "is_default", False) else (VenueTicketCategory.seat_map_id == sm.id))
    s.query(VenueTicketCategory).filter(VenueTicketCategory.venue_id == venue.id, _flt).delete(synchronize_session=False)
    order = 0
    for cat in cats:
        cid = str(cat.get("id"))
        qty = counts.get(cid, 0)
        if qty <= 0:
            continue
        is_inv = (str(cat.get("kind") or "").lower() in ("invitaciones", "bloqueo", "reserva"))
        s.add(VenueTicketCategory(
            venue_id=venue.id, seat_map_id=sm.id, zone=_zone_for(cat, cid),
            name=str(cat.get("name") or "Categoría").strip(),
            quantity=qty, invitations=(qty if is_inv else 0), sort_order=order,
        ))
        order += 1


@app.post("/recintos/<vid>/mapa/fondo", endpoint="venue_seatmap_bg_upload")
@admin_required
def venue_seatmap_bg_upload(vid):
    """Sube un PLANO (imagen) para usarlo como capa de fondo/guía del editor del mapa del recinto
    (calcar y, más adelante, autodetectar asientos). Solo sube el archivo y devuelve la URL; la
    posición/escala/opacidad se guardan en el propio layout del mapa al pulsar «Guardar mapa»."""
    if not can_edit_catalogs():
        return jsonify({"ok": False, "error": "Sin permisos para editar el recinto."}), 403
    s = db()
    try:
        venue = s.get(Venue, to_uuid(vid))
        if not venue:
            abort(404)
        f = request.files.get("image")
        if not f or not getattr(f, "filename", ""):
            return jsonify({"ok": False, "error": "No se ha recibido ninguna imagen."}), 400
        url = upload_image(f, "seatmaps")
        if not url:
            return jsonify({"ok": False, "error": "No se pudo subir la imagen."}), 400
        return jsonify({"ok": True, "url": _absolute_media_url(url)})
    except ValueError as ve:
        return jsonify({"ok": False, "error": str(ve)}), 400
    except Exception as exc:
        s.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        s.close()


@app.post("/recintos/<vid>/mapa/importar-excel", endpoint="venue_seatmap_import_xlsx")
@admin_required
def venue_seatmap_import_xlsx(vid):
    """Importa un plano de butacas «dibujado» en un Excel (cada celda con número = una butaca con
    ese número; blanco = hueco/pasillo; textos = títulos/sectores/etiquetas de fila). Solo PARSEA
    (no almacena el archivo) y devuelve los bloques (motor puro seatmap_import.py); venue_map.js
    los convierte en secciones grid y las coloca en el lienzo — el mapa se guarda después con el
    «Guardar mapa» normal. Se puede llamar varias veces para ir AÑADIENDO bloques al recinto."""
    if not can_edit_catalogs():
        return jsonify({"ok": False, "error": "Sin permisos para editar el recinto."}), 403
    s = db()
    try:
        venue = s.get(Venue, to_uuid(vid))
        if not venue:
            abort(404)
    finally:
        s.close()
    f = request.files.get("file")
    if not f or not getattr(f, "filename", ""):
        return jsonify({"ok": False, "error": "No se ha recibido ningún archivo."}), 400
    try:
        import seatmap_import
        plan = seatmap_import.parse_seatmap_workbook(f.read())
    except ValueError as ve:
        return jsonify({"ok": False, "error": str(ve)}), 400
    except Exception:
        return jsonify({"ok": False, "error": "No se pudo interpretar el archivo."}), 400
    plan["ok"] = True
    return jsonify(plan)


