@app.get("/contratacion", endpoint="contracting_view")
@admin_required
def contracting_view():
    section = (request.args.get("section") or "conciertos").strip().lower()
    if section == "conciertos":
        return redirect(url_for("concerts_view", tab="vista"))
    if section == "facturacion":
        return redirect(url_for("concerts_view", tab="facturacion"))
    if section == "cuadrantes":
        return redirect(url_for("quadrantes_view"))
    valid_sections = {"peticiones", "giras-compradas", "festivales-ciclos", "eventos",
                      "otras-actividades", "simulaciones"}
    if section not in valid_sections:
        section = "giras-compradas"
    if section == "simulaciones":
        return _render_simulations_list()
    if section == "peticiones":
        return _render_booking_requests()
    if section == "giras-compradas":
        return _render_purchased_tours()
    if section == "festivales-ciclos":
        return _render_cycle_festivals()
    if section == "eventos":
        # Por defecto, las ACTIVIDADES agrupadas por evento (como la pestaña de conciertos). Con
        # `?contenedores=1`, la lista de contenedores de evento (para crearlos y ver su ficha).
        if _truthy(request.args.get("contenedores")):
            return _render_cycle_festivals(only_events=True)
        return _render_event_activities()
    session_db = db()
    try:
        show_past_activities = _truthy(request.args.get("pasadas"))
        query = session_db.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue)).order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
        if section == "giras-compradas":
            query = query.filter(or_(func.upper(func.coalesce(Concert.sale_type, "")) == "GIRAS_COMPRADAS", func.upper(func.coalesce(Concert.activity_type, "")) == "GIRA"))
            title = "Giras compradas"
            subtitle = "Actividades/conciertos clasificados como gira comprada."
            empty = "No hay giras compradas registradas todavía."
        elif section == "festivales-ciclos":
            query = query.filter(or_(func.upper(func.coalesce(Concert.activity_type, "")) == "FESTIVAL", func.upper(func.coalesce(Concert.sale_type, "")) == "CADIZ", _sa_contains_text(Concert.festival_name, "festival"), _sa_contains_text(Concert.festival_name, "ciclo")))
            title = "Festivales / Ciclos"
            subtitle = "Festivales, ciclos y eventos agrupados fuera de conciertos estándar."
            empty = "No hay festivales o ciclos registrados todavía."
        elif section == "otras-actividades":
            query = query.filter(func.upper(func.coalesce(Concert.activity_type, "CONCIERTO")).in_(["EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS"]))
            # ⚠️ Por defecto, SOLO lo que está por venir (mismo criterio que Conciertos y que la
            # pestaña de Eventos): así el número de cada artista o evento de la rejilla es el de lo
            # que se va a ver al entrar. Con `?pasadas=1` se ven también las ya celebradas.
            if not show_past_activities:
                query = query.filter(or_(Concert.date.is_(None), Concert.date >= today_local()))
            title = "Otras actividades"
            subtitle = "Eventos promocionales, televisión, acciones con marca y otras actividades."
            empty = "No hay otras actividades registradas todavía."
        else:
            query = query.filter(text("1=0"))
            title = "Simulaciones"
            subtitle = "Espacio preparado para simulaciones de contratación."
            empty = "Las simulaciones se desarrollarán sobre esta sección."
        rows = query.limit(300).all()
        tour_groups = _tour_groups_from_concerts(rows) if section == "giras-compradas" else []
        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()

        # «Otras actividades» funciona como Conciertos: debajo de las tareas, los FILTROS POR TIPO de
        # actividad (etiquetas con su icono) y el filtro por SUJETO —artistas y eventos— con el nº de
        # actividades de cada uno; al pinchar uno, sus actividades.
        artist_groups, drill_artist = [], None
        subject_groups, drill_subject, type_chips, activity_rows = [], None, [], []
        if section == "otras-actividades":
            _mine = _contracting_task_artist_ids()
            if _mine:
                rows = [c for c in rows if str(getattr(c, "artist_id", "") or "") in _mine]
            # Etiquetas de TIPO: se cuentan sobre lo que se está VIENDO (lo que puede ver esta persona
            # y, si ha entrado en un artista o evento, solo lo suyo), sin aplicar el propio filtro de
            # tipo. Solo se ofrece el filtro de los tipos que TIENEN actividades.
            tipos_sel = {(_activity_kind_key(x) or "") for x in request.args.getlist("tipo") if (x or "").strip()}
            tipos_sel = {t for t in tipos_sel if t in OTHER_ACTIVITY_TYPE_KEYS}
            _sel_art = (request.args.get("artist") or "").strip()
            _sel_ev = (request.args.get("event") or "").strip()

            def _en_sujeto(c):
                if _sel_ev:
                    return str(getattr(c, "event_id", "") or "") == _sel_ev
                if _sel_art:
                    return (not getattr(c, "event_id", None)) and str(getattr(c, "artist_id", "") or "") == _sel_art
                return True

            cuenta_tipos = {}
            for c in rows:
                if not _en_sujeto(c):
                    continue
                k = _activity_kind_key(c.activity_type) or "OTROS"
                cuenta_tipos[k] = cuenta_tipos.get(k, 0) + 1
            for k in OTHER_ACTIVITY_TYPE_KEYS:
                if not cuenta_tipos.get(k, 0) and k not in tipos_sel:
                    continue
                otros = sorted(tipos_sel - {k}) if k in tipos_sel else sorted(tipos_sel | {k})
                type_chips.append({
                    "key": k,
                    "label": _activity_kind_label(k),
                    "icon": QUAD_ACTIVITY_ICONS.get(k, "fa-calendar-day"),
                    "count": cuenta_tipos.get(k, 0),
                    "active": k in tipos_sel,
                    "url": url_for("contracting_view", section="otras-actividades", tipo=otros,
                                   pasadas=(1 if show_past_activities else None),
                                   **({"artist": request.args.get("artist")} if request.args.get("artist") else {}),
                                   **({"event": request.args.get("event")} if request.args.get("event") else {})),
                })
            if tipos_sel:
                rows = [c for c in rows if (_activity_kind_key(c.activity_type) or "OTROS") in tipos_sel]
            # SUJETO de cada actividad: el EVENTO si lo tiene (su artista es un espejo que no se
            # debe ver), y si no, el artista.
            eventos = {str(e.id): e for e in session_db.query(AppEvent).all()} if any(
                getattr(c, "event_id", None) for c in rows) else {}
            by_id = {a.id: a for a in artists}
            grupos = {}
            for c in rows:
                if getattr(c, "event_id", None):
                    ev = eventos.get(str(c.event_id))
                    clave = ("event", str(c.event_id))
                    nombre = (getattr(ev, "name", "") or "Evento")
                    foto = (getattr(ev, "logo_url", "") or "")
                else:
                    art = by_id.get(c.artist_id)
                    if art is None:
                        continue
                    clave = ("artist", str(c.artist_id))
                    nombre = (art.name or "")
                    foto = (getattr(art, "photo_url", "") or "")
                g = grupos.setdefault(clave, {"kind": clave[0], "id": clave[1], "name": nombre,
                                              "photo_url": foto, "count": 0})
                g["count"] += 1
            for g in grupos.values():
                g["url"] = url_for("contracting_view", section="otras-actividades",
                                   tipo=sorted(tipos_sel),
                                   pasadas=(1 if show_past_activities else None),
                                   **({"event": g["id"]} if g["kind"] == "event" else {"artist": g["id"]}))
            subject_groups = sorted(grupos.values(), key=lambda x: (x["name"] or "").lower())
            # Compatibilidad: la rejilla antigua solo tenía artistas.
            artist_groups = [{"artist": by_id[to_uuid(g["id"])], "count": g["count"]}
                             for g in subject_groups
                             if g["kind"] == "artist" and to_uuid(g["id"]) in by_id]
            _drill_art = to_uuid(request.args.get("artist") or "")
            _drill_ev = to_uuid(request.args.get("event") or "")
            _subject_total = sum(cuenta_tipos.values())
            if _drill_ev:
                rows = [c for c in rows if str(getattr(c, "event_id", "") or "") == str(_drill_ev)]
                ev = eventos.get(str(_drill_ev)) or session_db.get(AppEvent, _drill_ev)
                drill_subject = {"kind": "event", "id": str(_drill_ev),
                                 "name": (getattr(ev, "name", "") or "Evento"),
                                 "photo_url": (getattr(ev, "logo_url", "") or ""), "count": _subject_total,
                                 "url": (url_for("event_detail_view", eid=_drill_ev) if ev else "")}
            elif _drill_art:
                rows = [c for c in rows if c.artist_id == _drill_art and not getattr(c, "event_id", None)]
                drill_artist = by_id.get(_drill_art)
                drill_subject = {"kind": "artist", "id": str(_drill_art),
                                 "name": (getattr(drill_artist, "name", "") or ""),
                                 "photo_url": (getattr(drill_artist, "photo_url", "") or ""), "count": _subject_total,
                                 "url": (url_for("artist_detail_view", artist_id=_drill_art) if drill_artist else "")}
            # El LISTADO no lleva nombre ni foto de artista: manda QUÉ es la actividad.
            for c in rows:
                st_label, st_badge = _concert_status_meta(c.status)
                kind = _activity_kind_key(c.activity_type) or "OTROS"
                activity_rows.append({
                    "id": str(c.id),
                    "url": url_for("concert_detail_view", cid=c.id),
                    "icon": QUAD_ACTIVITY_ICONS.get(kind, "fa-calendar-day"),
                    "type_label": _activity_kind_label(kind),
                    "title": ((c.festival_name or "").strip() or _activity_kind_label(kind)),
                    "has_name": bool((c.festival_name or "").strip()),
                    "municipality": _concert_city(c),
                    "province": _concert_province_value(c),
                    "date_label": (c.date.strftime("%d/%m/%Y") if c.date else "Sin fecha"),
                    "venue": (_concert_venue_name(c) or "Sin recinto"),
                    "cache_label": _activity_cache_label(c.sale_type, c.activity_type),
                    "status_label": st_label,
                    "status_badge": st_badge,
                })
        promoters = session_db.query(Promoter).options(selectinload(Promoter.companies)).order_by(Promoter.nick.asc()).all()
        companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        type_choices = [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER]
        all_concert_tags = _collect_all_concert_tags(session_db)
        promoters_payload = [
            {
                "id": str(p.id),
                "nick": (p.nick or "").strip(),
                "logo_url": (p.logo_url or "").strip(),
                "companies": [_serialize_promoter_company(x) for x in (p.companies or [])],
            }
            for p in promoters
        ]
        return render_template(
            "contratacion.html",
            section=section,
            show_past=show_past_activities,
            title=title,
            subtitle=subtitle,
            empty_message=empty,
            rows=rows,
            tour_groups=tour_groups,
            artist_groups=artist_groups,
            drill_artist=drill_artist,
            subject_groups=subject_groups,
            drill_subject=drill_subject,
            type_chips=type_chips,
            activity_rows=activity_rows,
            artists=artists,
            promoters=promoters,
            promoters_payload=promoters_payload,
            companies=companies,
            type_choices=type_choices,
            all_concert_tags=all_concert_tags,
            wizard_tours=_wizard_group_options(session_db)[0],
            wizard_cycles=_wizard_group_options(session_db)[1],
            CAN_EDIT_CONCERTS=can_edit_concerts(),
        )
    finally:
        session_db.close()


# ============================ PETICIONES (buzón de contratación) ============================
# Buzón de peticiones ENTRANTES: se registra lo que llega a la oficina (artista, fecha aprox.,
# contacto, recinto/ciudad, importe orientativo) y se tramita hasta convertirse en concierto o
# descartarse. Modelo BookingRequest. Sección en Contratación (contratacion.peticiones).
BOOKING_STATUS_ORDER = ["NUEVA", "EN_TRAMITE", "CONVERTIDA", "DESCARTADA"]
BOOKING_STATUS_META = {
    "NUEVA": ("Pendiente", "text-bg-warning text-dark"),
    "EN_TRAMITE": ("Negociando", "text-bg-info text-dark"),
    "CONVERTIDA": ("Aprobada", "text-bg-success"),
    "DESCARTADA": ("Descartada", "text-bg-secondary"),
}
# Estados que siguen "abiertos" (aparecen en el módulo de pendientes); el resto van a archivadas.
BOOKING_OPEN_STATUSES = {"NUEVA", "EN_TRAMITE"}
BOOKING_SOURCE_CHOICES = [
    ("EMAIL", "Email"), ("TELEFONO", "Teléfono"), ("WEB", "Web / formulario"),
    ("PRESENCIAL", "Presencial"), ("OTRO", "Otro"),
]


def _booking_status_meta(status):
    return BOOKING_STATUS_META.get((status or "NUEVA").upper(), ("Nueva", "text-bg-danger"))


def _booking_request_row(r):
    st = (r.status or "NUEVA").upper()
    label, badge = _booking_status_meta(st)
    art = r.artist
    if r.requested_date:
        dlabel = r.requested_date.strftime("%d/%m/%Y")
    else:
        dlabel = (r.date_text or "").strip()
    return {
        "id": str(r.id),
        "subject": (r.subject or "").strip(),
        "artist_id": (str(r.artist_id) if r.artist_id else ""),
        "artist_name": (art.name if art else ""),
        "artist_photo": ((getattr(art, "photo_url", "") or "") if art else ""),
        "date_label": dlabel,
        "requested_date": (r.requested_date.isoformat() if r.requested_date else ""),
        "date_text": (r.date_text or ""),
        "contact_name": (r.contact_name or ""),
        "contact_email": (r.contact_email or ""),
        "contact_phone": (r.contact_phone or ""),
        "municipality": (r.municipality or ""),
        "province": (r.province or ""),
        # Cómo se lee el lugar: «Municipio, Provincia» (y el país solo si no es España).
        "place_label": _place_label(r.municipality or "", r.province or "",
                                    ((r.payload or {}).get("country") or "")),
        "fee_text": (r.fee_text or ""),
        "source": (r.source or ""),
        "notes": (r.notes or ""),
        "status": st,
        "status_label": label,
        "status_badge": badge,
        "rejection_reason": (r.rejection_reason or ""),
        "concert_id": (str(r.concert_id) if r.concert_id else ""),
        # Todo lo que hace falta para EDITARLA con el mismo asistente con el que se creó.
        "edit": _peticion_edit_payload(object_session(r) or db(), r),
        "created_by": (r.created_by_nick or ""),
        "received_label": (r.received_at.strftime("%d/%m/%Y") if r.received_at else (r.created_at.strftime("%d/%m/%Y") if r.created_at else "")),
        # QUÉ se pide, con su icono: se lee igual que el tipo de una actividad.
        "kind_label": _activity_kind_label((r.payload or {}).get("activity_type")),
        "icon": QUAD_ACTIVITY_ICONS.get(_activity_kind_key((r.payload or {}).get("activity_type")),
                                        "fa-calendar-day"),
    }


def _booking_in_department(r, dept: str) -> bool:
    """¿Esta petición pertenece a `dept`? Se lee de payload['departments']; las
    peticiones antiguas sin departamento se consideran de Contratación."""
    pay = r.payload if isinstance(getattr(r, "payload", None), dict) else {}
    depts = pay.get("departments")
    if isinstance(depts, list) and depts:
        return dept.upper() in [str(d).strip().upper() for d in depts]
    return dept.upper() == "CONTRATACION"


def _render_booking_requests():
    s = db()
    try:
        status_filter = (request.args.get("status") or "").strip().upper()
        rows_all = (
            s.query(BookingRequest)
            .options(joinedload(BookingRequest.artist), joinedload(BookingRequest.promoter), joinedload(BookingRequest.venue))
            .order_by(BookingRequest.received_at.desc().nullslast(), BookingRequest.created_at.desc())
            .limit(500).all()
        )
        # Peticiones de Contratación (con caché o legado sin departamento).
        mine = [r for r in rows_all if _booking_in_department(r, "CONTRATACION")]
        pending = [r for r in mine if (r.status or "NUEVA").upper() in BOOKING_OPEN_STATUSES]
        archived = [r for r in mine if (r.status or "NUEVA").upper() not in BOOKING_OPEN_STATUSES]
        counts = {k: sum(1 for r in mine if (r.status or "NUEVA").upper() == k) for k in BOOKING_STATUS_ORDER}
        # Por defecto se muestran las PENDIENTES; «Archivadas» muestra aprobadas/descartadas.
        if status_filter == "ARCHIVED":
            rows = archived
        elif status_filter in BOOKING_STATUS_META:
            rows = [r for r in mine if (r.status or "NUEVA").upper() == status_filter]
        else:
            rows = pending
        payload = [_booking_request_row(r) for r in rows]
        artists = s.query(Artist).order_by(Artist.name.asc()).all()
        return render_template(
            "peticiones.html",
            section="peticiones",
            # «Pedir promoción» sale también aquí: lo puede hacer cualquiera de la empresa.
            promo_creator_datasets=_promo_creator_datasets(s),
            booking_rows=payload,
            booking_counts=counts,
            booking_total=len(mine),
            booking_pending_total=len(pending),
            booking_archived_total=len(archived),
            status_filter=status_filter,
            booking_status_order=BOOKING_STATUS_ORDER,
            booking_status_meta=BOOKING_STATUS_META,
            booking_source_choices=BOOKING_SOURCE_CHOICES,
            artists=artists,
            CAN_EDIT_CONCERTS=can_edit_concerts(),
        )
    finally:
        s.close()


def _booking_apply_form(r, form):
    r.subject = (form.get("subject") or "").strip() or None
    aid = (form.get("artist_id") or "").strip()
    r.artist_id = to_uuid(aid) if aid else None
    r.artist_ids = [aid] if aid else []
    r.requested_date = parse_optional_date(form.get("requested_date"))
    r.date_text = (form.get("date_text") or "").strip() or None
    r.contact_name = (form.get("contact_name") or "").strip() or None
    r.contact_email = (form.get("contact_email") or "").strip() or None
    r.contact_phone = (form.get("contact_phone") or "").strip() or None
    r.municipality = (form.get("municipality") or "").strip() or None
    r.province = (form.get("province") or "").strip() or None
    r.fee_text = (form.get("fee_text") or "").strip() or None
    r.source = (form.get("source") or "").strip().upper() or None
    r.notes = (form.get("notes") or "").strip() or None


@app.post("/contratacion/peticiones/crear", endpoint="booking_request_create")
@admin_required
def booking_request_create():
    s = db()
    try:
        r = BookingRequest(status="NUEVA")
        _booking_apply_form(r, request.form)
        if not (r.subject or r.artist_id or r.contact_name):
            flash("Indica al menos un artista, un contacto o un asunto para la petición.", "warning")
            return redirect(url_for("contracting_view", section="peticiones"))
        st = _current_user_state()
        r.created_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        r.created_by_nick = st.get("nick") or None
        s.add(r)
        s.commit()
        flash("Petición registrada en el buzón.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo registrar la petición: {exc}", "danger")
    finally:
        s.close()
    return redirect(url_for("contracting_view", section="peticiones"))


@app.post("/contratacion/peticiones/<rid>/editar", endpoint="booking_request_update")
@admin_required
def booking_request_update(rid):
    s = db()
    try:
        r = s.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        _booking_apply_form(r, request.form)
        s.commit()
        flash("Petición actualizada.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo actualizar: {exc}", "danger")
    finally:
        s.close()
    return redirect(url_for("contracting_view", section="peticiones"))


@app.post("/contratacion/peticiones/<rid>/estado", endpoint="booking_request_status")
@admin_required
def booking_request_status(rid):
    s = db()
    try:
        r = s.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        new = (request.form.get("status") or "").strip().upper()
        if new not in BOOKING_STATUS_META:
            raise ValueError("Estado no válido.")
        r.status = new
        r.rejection_reason = ((request.form.get("rejection_reason") or "").strip() or None) if new == "DESCARTADA" else None
        st = _current_user_state()
        r.reviewed_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        r.reviewed_by_nick = st.get("nick") or None
        s.commit()
        flash("Estado de la petición actualizado.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo cambiar el estado: {exc}", "danger")
    finally:
        s.close()
    return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))


@app.post("/contratacion/peticiones/<rid>/tramitar", endpoint="booking_request_convert")
@admin_required
def booking_request_convert(rid):
    """Marca la petición EN_TRAMITE y abre el asistente de concierto prefiltrado por su artista."""
    s = db()
    aid = ""
    try:
        r = s.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        if (r.status or "NUEVA").upper() == "NUEVA":
            r.status = "EN_TRAMITE"
            s.commit()
        aid = str(r.artist_id) if r.artist_id else ""
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo tramitar: {exc}", "danger")
        return redirect(url_for("contracting_view", section="peticiones"))
    finally:
        s.close()
    return redirect(url_for("concerts_view", tab="vista", open_wizard=1, wizard_artist=aid))


@app.post("/contratacion/peticiones/<rid>/eliminar", endpoint="booking_request_delete")
@admin_required
def booking_request_delete(rid):
    s = db()
    try:
        r = s.get(BookingRequest, to_uuid(rid))
        if r:
            # La borra QUIEN LA HIZO (desde «Mis peticiones»), quien gestiona su bandeja o dirección.
            estado = _current_user_state() or {}
            propia = str(r.created_by_user_id or "") == str(estado.get("user_id") or "")
            gestiona = any(_booking_in_department(r, d) for d in _current_user_peticion_departments())
            if not (propia or gestiona or is_master()):
                flash("Esa petición no es tuya ni de tu departamento.", "warning")
                return redirect(request.form.get("next") or url_for("home"))
            s.delete(r)
            s.commit()
            flash("Petición eliminada.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo eliminar: {exc}", "danger")
    finally:
        s.close()
    return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))


def _place_label(municipality: str = "", province: str = "", country: str = "",
                 *, venue: str = "") -> str:
    """Cómo se escribe un lugar: **«Municipio, Provincia»** —con una coma, que es como se escribe una
    dirección— y el PAÍS solo cuando NO es España. Lo compone `address_utils`, el mismo motor que las
    direcciones enteras, así que el formato es UNO en toda la app.

    Con `venue` delante queda «Recinto · Municipio, Provincia»: el recinto es otra cosa."""
    texto = address_utils.place_label(municipality or "", province or "", country or "")
    recinto = " ".join((venue or "").split())
    if recinto:
        return " · ".join([x for x in [recinto, texto] if x])
    return texto


def _peticion_requester_chip(session_db, r) -> dict | None:
    """QUIÉN HACE LA PETICIÓN, con su FOTO o su LOGO: en la ficha se ve como en el asistente.

    El que pide puede ser de varios tipos (`payload['requester_type']`): un tercero, una empresa, una
    institución, un artista, un medio, un recinto o alguien de la oficina. Cada uno tiene su imagen en
    su sitio, así que se resuelve aquí y no en la plantilla."""
    pay = r.payload if isinstance(r.payload, dict) else {}
    tipo = (pay.get("requester_type") or "").strip().lower()
    rid = (pay.get("requester_id") or "").strip()
    nombre = (pay.get("requester_name") or r.contact_name or "").strip()
    etiquetas = {"promoter": "Tercero", "empresa": "Empresa", "institucion": "Institución",
                 "artist": "Artista", "media": "Medio", "venue": "Recinto", "personal": "Oficina"}
    logo, icono = "", "fa-user"
    fila = None
    try:
        pk = to_uuid(rid) if rid else None
    except Exception:
        pk = None
    try:
        if tipo in ("promoter", "empresa", "institucion"):
            fila = (session_db.get(Promoter, pk) if pk else None) or \
                (session_db.get(Promoter, r.promoter_id) if r.promoter_id else None)
            logo = (getattr(fila, "logo_url", "") or "")
            icono = "fa-building" if tipo in ("empresa", "institucion") else "fa-user"
        elif tipo == "artist" and pk:
            fila = session_db.get(Artist, pk)
            logo = (getattr(fila, "photo_url", "") or "")
            icono = "fa-guitar"
        elif tipo == "media" and pk:
            fila = session_db.get(MediaOutlet, pk)
            logo = (getattr(fila, "logo_url", "") or "")
            icono = "fa-newspaper"
        elif tipo == "venue" and pk:
            fila = session_db.get(Venue, pk)
            logo = (getattr(fila, "photo_url", "") or "")
            icono = "fa-location-dot"
        elif tipo == "personal" and pk:
            fila = (session_db.query(UserProfile)
                    .filter(UserProfile.user_id == pk).first())
            logo = (getattr(fila, "photo_url", "") or "")
            icono = "fa-user-tie"
        elif r.promoter_id:                     # peticiones antiguas: solo quedó el tercero
            fila = session_db.get(Promoter, r.promoter_id)
            logo = (getattr(fila, "logo_url", "") or "")
            tipo = tipo or "promoter"
    except Exception:
        app.logger.exception("[peticiones] no se pudo resolver quién la pide")
    if fila is not None and not nombre:
        nombre = (getattr(fila, "name", None) or getattr(fila, "nick", None) or "").strip()
    if not nombre:
        return None
    contacto = " · ".join([x for x in [(r.contact_email or ""), (r.contact_phone or "")] if x])
    return {"name": nombre, "logo_url": logo, "icon": icono,
            "kind_label": etiquetas.get(tipo, "Quién lo pide"), "contact": contacto}


def _booking_request_detail(session_db, r) -> dict:
    """Todo lo que se sabe de una petición, para su ficha: datos, quién la pide, contexto y
    los departamentos a los que va."""
    pay = r.payload if isinstance(r.payload, dict) else {}
    dept_labels = {"CONTRATACION": "Contratación", "SELLO": "Sello", "PROMO": "Promoción", "DISENO": "Diseño"}
    depts = [str(d).strip().upper() for d in (pay.get("departments") or ["CONTRATACION"])]
    label, badge = _booking_status_meta(r.status)
    fecha = ""
    if r.requested_date:
        fecha = r.requested_date.strftime("%d/%m/%Y")
    elif (r.date_text or "").strip():
        fecha = (r.date_text or "").strip()
    elif pay.get("range_start"):
        fecha = f"Entre {pay.get('range_start')} y {pay.get('range_end') or '—'}"
    elif pay.get("month"):
        fecha = f"Durante {pay.get('month')}"
    venue = session_db.get(Venue, r.venue_id) if r.venue_id else None
    promoter = session_db.get(Promoter, r.promoter_id) if r.promoter_id else None
    lugar = _place_label(r.municipality or "", r.province or "", (pay.get("country") or ""),
                         venue=(venue.name if venue else ""))
    act_type = (pay.get("activity_type") or "CONCIERTO").strip().upper()
    act_kind = _activity_kind_key(act_type) or act_type
    concierto = session_db.get(Concert, r.concert_id) if r.concert_id else None
    gastos = (pay.get("promoter_costs") or {})
    gastos_label = " · ".join(
        "%s%s" % (it.get("label") or it.get("key"),
                  (" (%s)" % it.get("note")) if (it.get("note") or "").strip() else "")
        for it in (gastos.get("items") or []))

    # ---- LA FICHA SE LEE COMO LA DE UNA ACTIVIDAD: cabecera + pestañas + secciones, y en cada
    # sección SOLO lo que corresponde a este tipo de actividad y a cómo se configuró la petición
    # (nada de huecos vacíos: un campo sin valor no se pinta).
    def _rows(*filas):
        return [{"label": l, "value": v, "icon": i}
                for l, v, i in filas if str(v or "").strip()]

    place_kind = (pay.get("place_kind")
                  or ("VENUE" if r.venue_id else ("CITY" if r.municipality else "NONE"))).upper()
    date_kind = (pay.get("date_kind") or ("EXACT" if r.requested_date else "UNKNOWN")).upper()
    lugar_txt = lugar or {"NONE": "Todavía no se sabe dónde"}.get(place_kind, "")
    secciones_datos = [
        {"title": "Qué se pide", "icon": "fa-clipboard-question", "rows": _rows(
            ("Tipo de actividad", QUAD_ACTIVITY_LABELS.get(act_type, "Actividad"),
             QUAD_ACTIVITY_ICONS.get(act_kind, "fa-calendar-day")),
            ("Asunto", (r.subject or "").strip(), "fa-tag"),
            ("Artista", (r.artist.name if r.artist else ""), "fa-guitar"),
            ("Caché", ("Sin caché" if pay.get("no_cache") else "Con caché"), "fa-euro-sign"),
            ("Departamentos", " · ".join(dept_labels.get(d, d) for d in depts), "fa-people-group"),
            ("¿Cómo llegó?", dict(BOOKING_SOURCE_CHOICES).get((r.source or "").upper(), (r.source or "")),
             "fa-inbox"),
            ("La registró", (r.created_by_nick or ""), "fa-user-pen"),
            ("Recibida el", (r.received_at.strftime("%d/%m/%Y") if r.received_at else ""), "fa-clock"),
        )},
        {"title": "Cuándo", "icon": "fa-calendar-day", "rows": _rows(
            ("Fecha pedida", (fecha or "Todavía no se sabe"), "fa-calendar-day"),
            ("Cómo se pidió", {"EXACT": "Día concreto", "RANGE": "Una franja de días",
                               "MONTH": "Un mes", "UNKNOWN": "Sin definir"}.get(date_kind, ""),
             "fa-hourglass-half"),
        )},
        {"title": "Dónde", "icon": "fa-location-dot", "rows": _rows(
            ("Recinto", (venue.name if venue else ""), "fa-location-dot"),
            ("Lugar", lugar_txt, "fa-map-location-dot"),
            ("Aforo del recinto", (format_thousands(venue.capacity)
                                   if (venue is not None and getattr(venue, "capacity", None)) else ""),
             "fa-people-group"),
        )},
    ]
    if (r.notes or "").strip():
        secciones_datos.append({"title": "Notas", "icon": "fa-note-sticky", "rows": [],
                                "text": (r.notes or "").strip()})

    tabs = [{"key": "datos", "label": "Datos de la petición", "icon": "fa-circle-info",
             "sections": [x for x in secciones_datos if x["rows"] or x.get("text")]}]
    # ECONÓMICO: solo si hay algo que decir (una petición sin caché no tiene esta pestaña).
    filas_econ = _rows(
        ("Importe orientativo", (r.fee_text or "").strip(), "fa-euro-sign"),
        ("Cubren gastos", gastos_label, "fa-hand-holding-heart"),
    )
    if filas_econ:
        tabs.append({"key": "economico", "label": "Económico", "icon": "fa-euro-sign",
                     "sections": [{"title": "Lo que se habló", "icon": "fa-euro-sign",
                                   "rows": filas_econ}]})
    # ACTIVIDAD: solo cuando ya se aceptó (la petición pasó a ser la actividad).
    if concierto is not None:
        tabs.append({"key": "actividad", "label": "Actividad", "icon": "fa-guitar",
                     "url": url_for("concert_detail_view", cid=concierto.id),
                     "sections": [{"title": "La actividad que se creó", "icon": "fa-guitar",
                                   "rows": _rows(
                                       ("Tipo", _activity_kind_label(_activity_kind_key(concierto.activity_type)), "fa-calendar-day"),
                                       ("Estado", _concert_status_meta(concierto.status)[0], "fa-circle-half-stroke"),
                                       ("Fecha", (concierto.date.strftime("%d/%m/%Y") if concierto.date else ""), "fa-calendar-day"),
                                       ("Lugar", _place_label(_concert_city(concierto) or "",
                                                              _concert_province_value(concierto) or "",
                                                              venue=(_concert_venue_name(concierto) or "")),
                                        "fa-location-dot"),
                                       ("Producción", _concert_production_owner_name(session_db, concierto), "fa-user-gear"),
                                   )}]})
    return {
        "tabs": tabs,
        "concert": concierto,
        "row": r,
        "status_label": label,
        "status_badge": badge,
        "is_open": (r.status or "NUEVA").upper() in BOOKING_OPEN_STATUSES,
        "departments": [dept_labels.get(d, d) for d in depts],
        "activity_type": act_type,
        "activity_label": QUAD_ACTIVITY_LABELS.get(act_type, "Actividad"),
        "no_cache": bool(pay.get("no_cache")),
        "activity_icon": QUAD_ACTIVITY_ICONS.get(act_kind, "fa-calendar-day"),
        "date_label": fecha,
        "place_label": lugar,
        # QUIÉN LO PIDE va aparte: se enseña con su foto o su logo, no como una línea de texto.
        "requester": _peticion_requester_chip(session_db, r),
        # Cerrada y todavía sin comunicar a quien la pidió: la petición no está terminada.
        "rejection_pending": bool((r.status or "").upper() == "DESCARTADA"
                                  and not r.rejection_notified_at),
        # Aceptada: en qué fase va la ACTIVIDAD (las mismas que en Inicio, punto único). Aquí se
        # enseñan como estado —el trabajo se hace en la ficha de la actividad, que es lo que ya es—.
        "accept_tasks": _peticion_accept_tasks(
            session_db, r, for_user=((_current_user_state() or {}).get("user_id") or "")),
        # Lo que necesita el asistente para EDITARLA desde los tres puntitos de la ficha.
        "edit_payload": _peticion_edit_payload(session_db, r),
        "artist": r.artist,
        "venue": venue,
        "promoter": promoter,
        "notes": (r.notes or "").strip(),
    }


@app.get("/peticiones/<rid>", endpoint="booking_request_detail_view")
@admin_required
def booking_request_detail_view(rid):
    """Ficha de una petición: los datos que haya y las acciones para gestionarla (cerrarla con
    su motivo o convertirla en la actividad que corresponda)."""
    session_db = db()
    try:
        r = (
            session_db.query(BookingRequest)
            .options(joinedload(BookingRequest.artist))
            .filter(BookingRequest.id == to_uuid(rid))
            .first()
        )
        if not r:
            abort(404)
        # La ve quien lleva alguno de sus departamentos, dirección y —⚠️ esto faltaba— QUIEN LA
        # PIDIÓ: es su petición, y al pinchar la suya en Inicio se comía un «es de otro
        # departamento» y volvía a la portada.
        depts = _current_user_peticion_departments()
        _propia = str(r.created_by_user_id or "") == str((_current_user_state() or {}).get("user_id") or "")
        if not is_master() and not _propia and not any(_booking_in_department(r, d) for d in depts):
            flash("Esta petición es de otro departamento.", "warning")
            return redirect(url_for("home"))
        detalle = _booking_request_detail(session_db, r)
        # CONFIGURAR EL EVENTO: se abre aquí mismo el asistente de actividad (los mismos pasos que al
        # añadir una nueva) con lo de la petición ya puesto. Al terminarlo, la actividad queda creada
        # y ligada a esta petición.
        puede_configurar = bool(r.accepted_at and not r.concert_id)
        wizard_ctx = {}
        wizard_prefill = None
        if puede_configurar:
            try:
                wizard_ctx = _concert_wizard_context(session_db)
                wizard_ctx.pop("artists", None)      # la ficha ya pasa `artists` (misma lista)
                wizard_prefill = _peticion_wizard_prefill(session_db, r)
                wizard_prefill["autoopen"] = bool(_truthy(request.args.get("configurar")))
            except Exception:
                app.logger.exception("[peticiones] no se pudo preparar el asistente")
                wizard_ctx, wizard_prefill = {}, None
        # Pestañas SERVIDAS (?tab=), como en la ficha de una actividad: solo las que tienen algo que
        # enseñar, y si se pide una que no existe se cae a la primera.
        claves = [t["key"] for t in detalle["tabs"]]
        tab = (request.args.get("tab") or "").strip().lower()
        if tab not in claves:
            tab = claves[0] if claves else "datos"
        return render_template(
            "peticion_detail.html",
            **detalle,
            **wizard_ctx,
            tab=tab,
            can_configure=puede_configurar,
            wizard_available=bool(wizard_ctx),
            # El asistente SIEMPRE se abre cumplimentado; lo que decide `?configurar=1` (el botón de
            # la tarea) es si se abre SOLO al entrar o si hay que pulsar «Configurar evento».
            wizard_prefill=wizard_prefill,
            activity_choices=QUAD_ACTIVITY_CHOICES,
            # El asistente de peticiones se incluye aquí (los tres puntitos la EDITAN con el mismo
            # con el que se creó) y necesita la lista de artistas.
            artists=(session_db.query(Artist).filter(Artist.event_id.is_(None))
                     .order_by(Artist.name.asc()).all()),
            back_url=safe_next_or(url_for("contracting_view", section="peticiones")),
        )
    finally:
        session_db.close()


@app.post("/peticiones/<rid>/cerrar", endpoint="booking_request_close")
@admin_required
def booking_request_close(rid):
    """Cerrar una petición dejando por escrito POR QUÉ se cierra."""
    session_db = db()
    next_url = safe_next_or(url_for("booking_request_detail_view", rid=rid))
    try:
        r = session_db.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        # La cierra quien lleva alguno de sus departamentos (o dirección), igual que la ficha.
        if not is_master() and not any(_booking_in_department(r, d) for d in _current_user_peticion_departments()):
            flash("Esta petición es de otro departamento.", "warning")
            return redirect(url_for("home"))
        note = (request.form.get("close_note") or "").strip()
        if not note:
            flash("Escribe por qué se cierra la petición.", "warning")
            return redirect(next_url)
        st = _current_user_state()
        r.status = "DESCARTADA"
        r.rejection_reason = note
        r.reviewed_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        r.reviewed_by_nick = st.get("nick") or st.get("email") or ""
        r.rejection_notified_at = None
        r.rejection_notified_by_nick = None
        # ⚠️ Cerrarla NO la termina: hay que DECÍRSELO a quien la hizo. Se le avisa y le queda la
        # tarea «notificar el rechazo» hasta que marque que ya lo ha hecho.
        if r.created_by_user_id:
            _notify_user(session_db, r.created_by_user_id, "TAREA",
                         "Notifica el rechazo de una petición",
                         "«%s» se ha cerrado: %s" % ((r.subject or "Petición"), note[:160]),
                         url_for("booking_request_detail_view", rid=str(r.id)),
                         ref_type="peticion_rechazo", ref_id=str(r.id))
        session_db.commit()
        flash("Petición cerrada. Se ha avisado a quien la hizo para que se lo comunique.", "success")
        return redirect(next_url)
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo cerrar la petición: {exc}", "danger")
        return redirect(next_url)
    finally:
        session_db.close()


@app.post("/peticiones/<rid>/rechazo-notificado", endpoint="booking_request_rejection_notified")
@admin_required
def booking_request_rejection_notified(rid):
    """«Ya se lo he dicho»: la petición rechazada queda terminada y el aviso se cierra solo.

    Lo marca QUIEN LA HIZO (es su tarea) o dirección."""
    session_db = db()
    next_url = safe_next_or(url_for("booking_request_detail_view", rid=rid))
    try:
        r = session_db.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        estado = _current_user_state() or {}
        propia = str(r.created_by_user_id or "") == str(estado.get("user_id") or "")
        if not (propia or is_master()):
            flash("Esa petición no la has hecho tú.", "danger")
            return redirect(url_for("home"))
        r.rejection_notified_at = _now_madrid()
        r.rejection_notified_by_nick = estado.get("nick") or estado.get("email") or ""
        # La tarea ya está hecha: el aviso deja de esperar a nadie.
        _notify_resolve(session_db, "peticion_rechazo", str(r.id))
        session_db.commit()
        flash("Anotado: ya está comunicado y la petición queda terminada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo marcar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


def _peticion_rejection_email_html(session_db, r, chip: dict | None = None) -> str:
    """El correo con el que se le dice a quien pidió algo que NO se puede hacer.

    Estilo de la casa: el logo arriba a la DERECHA, el título centrado, la cabecera de lo que se pidió
    y el motivo tal cual lo escribió contratación (es lo que hay que contarle, no un resumen).
    ⚠️ Estilos EN LÍNEA: los clientes de correo se comen las hojas de estilo."""
    def esc(v) -> str:
        return str(escape("" if v is None else v))

    pay = r.payload if isinstance(r.payload, dict) else {}
    logo = (_treinta_y_tres_logo_url(session_db)
            or _external_url_for("static", filename="img/logo_33_producciones.png"))
    art = session_db.get(Artist, r.artist_id) if r.artist_id else None
    venue = session_db.get(Venue, r.venue_id) if r.venue_id else None
    lugar = _place_label(r.municipality or "", r.province or "", (pay.get("country") or ""),
                         venue=(venue.name if venue else ""))
    fecha = (r.requested_date.strftime("%d/%m/%Y") if r.requested_date
             else ((r.date_text or "").strip()))
    act = (pay.get("activity_type") or "CONCIERTO").strip().upper()
    filas = [(k, v) for k, v in [
        ("Qué se pidió", QUAD_ACTIVITY_LABELS.get(act, "Actividad")),
        ("Artista", (getattr(art, "name", "") or "")),
        ("Fecha", fecha),
        ("Lugar", lugar),
    ] if (v or "").strip()]
    datos = "".join(
        '<tr><td style="padding:3px 10px 3px 0;color:#6b7280;font-size:13px;white-space:nowrap;">%s</td>'
        '<td style="padding:3px 0;font-size:14px;">%s</td></tr>' % (esc(k), esc(v))
        for k, v in filas)
    quien = ((chip or {}).get("name") or (r.contact_name or "")).strip()
    partes = ['<div style="font-family:Arial,Helvetica,sans-serif;color:#212529;max-width:660px;margin:0 auto;">']
    partes.append('<div style="text-align:right;margin-bottom:6px;">'
                  '<img src="%s" alt="33 Producciones" style="max-height:54px;max-width:190px;"></div>' % esc(logo))
    partes.append('<h2 style="text-align:center;font-size:22px;margin:0 0 14px;">Sobre tu petición</h2>')
    partes.append('<div style="font-size:15px;line-height:1.7;margin:0 0 14px;">'
                  + ("Hola %s:<br>" % esc(quien) if quien else "")
                  + 'Gracias por contar con nosotros. Hemos estudiado tu petición y '
                    '<strong>esta vez no vamos a poder llevarla a cabo</strong>.</div>')
    if datos:
        partes.append('<table style="border-collapse:collapse;margin:0 0 14px;">%s</table>' % datos)
    if (r.rejection_reason or "").strip():
        partes.append('<div style="margin:0 0 14px;padding:12px 14px;border-radius:12px;background:#f8fafc;'
                      'border:1px solid #e6e8eb;font-size:14px;line-height:1.7;color:#374151;'
                      'white-space:pre-line;">' + esc((r.rejection_reason or "").strip()) + '</div>')
    partes.append('<div style="font-size:15px;line-height:1.7;margin:0 0 14px;">'
                  'Seguimos a tu disposición para lo que venga.</div>')
    partes.append('<div style="color:#6b7280;font-size:13px;">33 Producciones</div></div>')
    return "".join(partes)


@app.post("/peticiones/<rid>/comunicar-rechazo", endpoint="booking_request_rejection_send")
@admin_required
def booking_request_rejection_send(rid):
    """COMUNICA el rechazo a quien pidió algo (correo o SMS, por su canal) y da la tarea por hecha.

    Es el atajo de «Mis peticiones»: comunicar y marcar son la misma cosa vista de dos formas, así
    que si el aviso sale, la petición queda terminada y desaparece del módulo."""
    session_db = db()
    next_url = safe_next_or(url_for("home"))
    try:
        r = session_db.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        estado = _current_user_state() or {}
        propia = str(r.created_by_user_id or "") == str(estado.get("user_id") or "")
        if not (propia or is_master()):
            flash("Esa petición no la has hecho tú.", "danger")
            return redirect(url_for("home"))
        chip = _peticion_requester_chip(session_db, r) or {}
        correo = (r.contact_email or "").strip()
        telefono = (r.contact_phone or "").strip()
        if not correo and r.promoter_id:
            p = session_db.get(Promoter, r.promoter_id)
            correo_p, tel_p = _promoter_email_phone(p)
            correo = correo_p
            telefono = telefono or tel_p
        if not correo and not telefono:
            flash("No hay correo ni teléfono de quien la pidió: comunícaselo tú y marca la tarea.",
                  "warning")
            return redirect(next_url)
        fila = (_notify_apply_prefs(session_db, [{
            "name": (chip.get("name") or r.contact_name or ""),
            "email": correo, "phone": telefono,
        }]) or [{}])[0]
        asunto = "Sobre tu petición · %s" % (r.subject or "Petición")
        html_cuerpo = _peticion_rejection_email_html(session_db, r, chip)
        sms = "%s: no vamos a poder llevarla a cabo. %s" % (
            (r.subject or "Tu petición"), ((r.rejection_reason or "").strip()[:110]))
        ok, err = _notify_send_row(session_db, fila, subject=asunto, html=html_cuerpo,
                                   sms_text=sms, kind="PETICION")
        if not ok:
            flash("No se pudo comunicar: %s" % (err or "el aviso no salió"), "danger")
            return redirect(next_url)
        # Ha salido: la tarea está hecha y la petición se archiva.
        r.rejection_notified_at = _now_madrid()
        r.rejection_notified_by_nick = estado.get("nick") or estado.get("email") or ""
        _notify_resolve(session_db, "peticion_rechazo", str(r.id))
        session_db.commit()
        flash("Comunicado por %s. La petición queda terminada." % (
            "SMS" if (fila.get("channel") or "EMAIL") == "SMS" else "correo"), "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[peticiones] no se pudo comunicar el rechazo")
        flash(f"No se pudo comunicar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


# ================= ACEPTAR UNA PETICIÓN TAMPOCO LA TERMINA =========================================
# ⚠️ Cuando el departamento ACEPTA una petición (p. ej. contratación acepta un evento promocional),
# a QUIEN LA PIDIÓ le quedan tres cosas por hacer, así que la petición vuelve a su Inicio como TAREA
# PENDIENTE con esas tres subtareas hasta que estén las tres. Es la misma regla del rechazo: es la
# misma petición en otro momento de su vida, no otro módulo.
# ⚠️⚠️ Cuando el departamento la APRUEBA, la petición vuelve a QUIEN LA PIDIÓ y **pasa a ser la
# ACTIVIDAD**: primero la CONFIGURA (el asistente de siempre, con lo de la petición ya puesto) y a
# partir de ahí el trabajo es de la actividad y va POR FASES, todas de quien la creó.
# Las fases van EN ORDEN y cada una está BLOQUEADA hasta que la anterior esté hecha:
#   1 Configurar el evento  →  2 Confirmar CON EL ARTISTA (la fecha y que lo quiere hacer)
#   →  3 Confirmar al promotor  →  4 Activar producción + Informar al artista (las dos a la vez).
# ⚠️ Lo IMPORTANTE del orden: **no se le confirma nada al promotor sin que el artista haya dicho que
# sí**; y el aviso formal al artista va al final, cuando ya está todo comprometido.
# ⚠️ Al activar la producción el evento sigue su curso en las tareas de PRODUCCIÓN, y deja de estar
# en las de quien lo pidió (la fase desaparece sola en cuanto hay responsable).
PETICION_ACCEPT_PHASES = (
    # clave        nº  etiqueta                        icono            de quién es
    ("configurar",  1, "Configurar el evento",         "fa-sliders",     "REQUESTER"),
    ("artista_ok",  2, "Confirmar con el artista",     "fa-user-check",  "REQUESTER"),
    ("promotor",    3, "Confirmar al promotor",        "fa-handshake",   "REQUESTER"),
    # Las dos ÚLTIMAS van a la par: se abren juntas al confirmar al promotor.
    ("produccion",  4, "Activar producción",           "fa-user-gear",   "REQUESTER"),
    ("informar",    4, "Informar al artista",          "fa-bell",        "REQUESTER"),
)

def _peticion_accept_contact(session_db, r, concert=None) -> dict:
    """A QUIÉN se le confirma que la actividad sale adelante: quien la pidió (que en un evento
    promocional es el propio promotor), con su correo o su teléfono; si su ficha no los tiene, los
    del promotor de la actividad."""
    chip = _peticion_requester_chip(session_db, r) or {}
    nombre = (chip.get("name") or r.contact_name or "").strip()
    correo = (r.contact_email or "").strip()
    telefono = (r.contact_phone or "").strip()
    for pk in (r.promoter_id, getattr(concert, "promoter_id", None)):
        if correo and telefono:
            break
        if not pk:
            continue
        p = session_db.get(Promoter, pk)
        if p is None:
            continue
        correo_p, tel_p = _promoter_email_phone(p)
        correo = correo or correo_p
        telefono = telefono or tel_p
        nombre = nombre or (getattr(p, "name", "") or getattr(p, "nick", "") or "").strip()
    return {"name": nombre, "email": correo, "phone": telefono,
            "logo_url": (chip.get("logo_url") or ""), "icon": (chip.get("icon") or "fa-user"),
            "contact": " · ".join([x for x in [correo, telefono] if x])}


def _peticion_artist_notice_pending(session_db, concert) -> bool:
    """¿Falta AVISAR AL ARTISTA de esta actividad? (fase 1).

    Con las mismas excepciones que la compuerta de confirmar: un EVENTO no es de ningún artista y el
    histórico no genera trabajo."""
    if concert is None:
        return False
    try:
        if not getattr(concert, "artist_id", None) or getattr(concert, "event_id", None):
            return False
        if _concert_is_legacy(concert):
            return False
        return not _concert_notice_state(session_db, concert).get("notified")
    except Exception:
        app.logger.exception("[peticiones] no se pudo mirar el aviso al artista")
        return False


def _peticion_accept_tasks(session_db, r, concert=None, *, for_user=None) -> list[dict]:
    """LAS FASES que le quedan a una petición ya APROBADA, en orden. Punto ÚNICO: lo usan el módulo
    de Inicio, la ficha de la actividad y la ficha de la petición, así que los tres dicen lo mismo.

    Todas son de QUIEN LA PIDIÓ (contratación acaba su parte al aprobarla) y cada una se decide
    mirando el estado DE VERDAD, no una marca aparte, así que **desaparece sola** al hacerse:
      · 1 **Configurar el evento** → mientras no exista la actividad (`concert_id`). El botón abre el
        asistente de siempre con lo de la petición ya puesto; al terminarlo, la actividad existe.
      · 2 **Confirmar con el artista** (la fecha y que lo quiere hacer) → `artist_agreed_at`. Es una
        conversación, así que se marca a mano. Bloqueada hasta que esté configurada.
      · 3 **Confirmar al promotor** → `acceptance_notified_at`. ⚠️ BLOQUEADA hasta que el artista haya
        dicho que sí: no se compromete una fecha con nadie de fuera antes.
      · 4 **Activar producción** (`_concert_production_pending`) y **Informar al artista**
        (`_concert_notice_state`, el aviso formal), las dos a la vez y bloqueadas hasta la 3. Al
        activar la producción el evento pasa a las tareas de PRODUCCIÓN y deja de estar aquí.

    ⚠️ Solo las peticiones aprobadas DESDE que esto existe (`accepted_at`) generan trabajo: las de
    antes no van a reclamar hoy algo que se hizo en su día."""
    if r is None or not getattr(r, "accepted_at", None):
        return []
    if (r.status or "").upper() != "CONVERTIDA":
        return []
    if concert is None and r.concert_id:
        concert = session_db.get(Concert, r.concert_id)
    meta = {k: (n, lbl, ico, dueño) for k, n, lbl, ico, dueño in PETICION_ACCEPT_PHASES}
    yo = str(for_user or "")
    # ⚠️ Quién es DIRECCIÓN se lee del estado (`role`), no con `is_master()`: ese saca el rol de la
    # sesión y **sin sesión cae a 10**, así que fuera de una petición de usuario todo saldría «mío».
    direccion = ((_current_user_state() or {}).get("role") == 10)
    dueños = {
        "CONTRATACION": (str(r.reviewed_by_user_id or ""), (r.reviewed_by_nick or "contratación")),
        "REQUESTER": (str(r.created_by_user_id or ""), (r.created_by_nick or "quien la pidió")),
    }
    filas = []

    def añade(key, **extra):
        n, lbl, ico, dueño = meta[key]
        uid, nick = dueños.get(dueño, ("", ""))
        # Si no consta quién es, la fase no es «de nadie»: la ve cualquiera que llegue a ella.
        mia = bool(yo) and (uid == yo or not uid or direccion)
        filas.append(dict({"key": key, "phase": n, "label": lbl, "icon": ico,
                           "owner": dueño, "owner_nick": nick, "owner_user_id": uid,
                           "mine": mia, "blocked": False, "blocked_reason": ""}, **extra))

    # ---- 1 · CONFIGURAR EL EVENTO (mientras no exista la actividad).
    if concert is None:
        añade("configurar",
              badge="Petición aprobada",
              action_label="Configurar evento",
              url=url_for("booking_request_detail_view", rid=str(r.id), configurar=1))
        return filas          # hasta que no esté configurada, no hay nada más que hacer

    # ---- 2 · CONFIRMAR CON EL ARTISTA (la fecha y que lo quiere hacer).
    falta_artista_ok = not getattr(r, "artist_agreed_at", None)
    if falta_artista_ok:
        añade("artista_ok",
              hint="La fecha y que lo quiere hacer",
              done_url=url_for("booking_request_artist_agreed", rid=str(r.id)))
    # ---- 3 · CONFIRMAR AL PROMOTOR. ⚠️ Bloqueada hasta que el artista haya dicho que sí.
    falta_promotor = not getattr(r, "acceptance_notified_at", None)
    if falta_promotor:
        quien = _peticion_accept_contact(session_db, r, concert)
        libre = not falta_artista_ok
        añade("promotor", who=quien.get("name") or "", contact=quien.get("contact") or "",
              blocked=bool(falta_artista_ok),
              blocked_reason=("Primero tiene que confirmar el artista." if falta_artista_ok else ""),
              send_url=(url_for("booking_request_acceptance_send", rid=str(r.id))
                        if (libre and (quien.get("email") or quien.get("phone"))) else ""),
              done_url=(url_for("booking_request_acceptance_notified", rid=str(r.id)) if libre else ""))
    # ---- 4 · LAS DOS ÚLTIMAS, a la par: se abren al confirmar al promotor.
    bloqueo4 = bool(falta_promotor or falta_artista_ok)
    motivo4 = ("Primero hay que confirmar al promotor." if bloqueo4 else "")
    try:
        falta_produccion = _concert_production_pending(concert)
    except Exception:
        app.logger.exception("[peticiones] no se pudo mirar la producción")
        falta_produccion = False
    if falta_produccion:
        añade("produccion", blocked=bloqueo4, blocked_reason=motivo4,
              url=("" if bloqueo4 else url_for("concert_detail_view", cid=concert.id)),
              action_label="Activar producción")
    if _peticion_artist_notice_pending(session_db, concert):
        try:
            avisado = _concert_notice_state(session_db, concert)
        except Exception:
            avisado = {}
        añade("informar", blocked=bloqueo4, blocked_reason=motivo4,
              url=("" if bloqueo4 else url_for("concert_artist_notice_view", cid=concert.id)),
              note=("hay cambios desde el último aviso" if avisado.get("stale") else ""))
    filas.sort(key=lambda f: f["phase"])
    return filas


def _peticion_of_concert(session_db, concert_id):
    """La petición de la que salió una actividad (si salió de una)."""
    if not concert_id:
        return None
    try:
        return (session_db.query(BookingRequest)
                .filter(BookingRequest.concert_id == concert_id)
                .order_by(BookingRequest.created_at.desc()).first())
    except Exception:
        app.logger.exception("[peticiones] no se pudo resolver la petición de la actividad")
        return None


def _concert_peticion_phases(session_db, concert) -> dict | None:
    """Las FASES de la petición de la que salió esta actividad, para la barra de botones de su ficha.

    Devuelve `{request_id, artist_ok, promotor}` con lo que hay que hacer (o `done` si ya está), y
    None si la actividad no viene de una petición aprobada. El resto de fases (activar producción e
    informar al artista) ya tienen su botón en esa barra: aquí no se repiten."""
    if concert is None:
        return None
    r = _peticion_of_concert(session_db, concert.id)
    if r is None or not getattr(r, "accepted_at", None):
        return None
    yo = (_current_user_state() or {}).get("user_id") or ""
    tareas = {t["key"]: t for t in _peticion_accept_tasks(session_db, r, concert, for_user=yo)}

    def hecho(at, nick):
        return {"done": True, "by": (nick or ""),
                "at_label": (at.astimezone(TZ_MADRID).strftime("%d/%m/%Y %H:%M") if at else "")}

    return {
        "request_id": str(r.id),
        "request_url": url_for("booking_request_detail_view", rid=str(r.id)),
        "artist_ok": (tareas.get("artista_ok")
                      or hecho(r.artist_agreed_at, r.artist_agreed_by_nick)),
        "promotor": (tareas.get("promotor")
                     or hecho(r.acceptance_notified_at, r.acceptance_notified_by_nick)),
    }


def _concert_task_board(session_db, concert) -> dict:
    """LAS TAREAS de una actividad, **paso a paso**, para su pestaña «Inicio» (el mismo patrón que
    las tareas pendientes de un proyecto discográfico).

    Devuelve todas las fases en orden con su estado (`done` / `todo` / `blocked`), de quién es cada
    una y —cuando la tiene otra persona— con qué reclamársela. Las fases que no aplican a esta
    actividad (p. ej. producción en una fecha que no produce la casa) no se pintan.

    ⚠️ El estado se mira SIEMPRE de verdad (`_peticion_accept_tasks` para lo pendiente), así que una
    tarea desaparece de lo pendiente en cuanto se hace, sin que nadie la marque dos veces."""
    if concert is None:
        return {"rows": [], "pending": 0, "total": 0}
    yo = str((_current_user_state() or {}).get("user_id") or "")
    r = _peticion_of_concert(session_db, concert.id)
    pendientes = {}
    if r is not None and getattr(r, "accepted_at", None):
        pendientes = {t["key"]: t for t in _peticion_accept_tasks(session_db, r, concert, for_user=yo)}

    def _hecha(key, n, label, icon, *, at=None, by="", nota=""):
        return {"key": key, "phase": n, "label": label, "icon": icon, "state": "done",
                "at_label": (at.astimezone(TZ_MADRID).strftime("%d/%m/%Y %H:%M") if at else ""),
                "by": (by or ""), "note": nota}

    filas = []
    for key, n, label, icon, _dueño in PETICION_ACCEPT_PHASES:
        t = pendientes.get(key)
        if t is not None:
            fila = dict(t)
            fila["state"] = "blocked" if t.get("blocked") else "todo"
            # A quién se le puede reclamar: a quien la tiene, si no soy yo.
            fila["nudge_url"] = (url_for("concert_task_nudge", cid=concert.id, key=key)
                                 if (t.get("owner_user_id") and t.get("owner_user_id") != yo
                                     and not t.get("blocked")) else "")
            filas.append(fila)
            continue
        if r is None or not getattr(r, "accepted_at", None):
            continue                      # la actividad no viene de una petición: no hay fases
        # No está pendiente: o ya está hecha, o no aplica a esta actividad.
        if key == "configurar":
            filas.append(_hecha(key, n, label, icon, at=r.accepted_at))
        elif key == "artista_ok":
            filas.append(_hecha(key, n, label, icon, at=r.artist_agreed_at,
                                by=(r.artist_agreed_by_nick or "")))
        elif key == "promotor":
            filas.append(_hecha(key, n, label, icon, at=r.acceptance_notified_at,
                                by=(r.acceptance_notified_by_nick or "")))
        elif key == "produccion":
            quien = _concert_production_owner_name(session_db, concert)
            if quien or getattr(concert, "production_owner_user_id", None):
                filas.append(_hecha(key, n, label, icon, nota=("La lleva %s" % quien if quien else "")))
        elif key == "informar":
            est = _concert_notice_state(session_db, concert)
            if est.get("notified"):
                filas.append(_hecha(key, n, label, icon, at=est.get("at"),
                                    by=(est.get("by") or ""),
                                    nota=("a %s" % est["to_label"] if est.get("to_label") else "")))
    # ---- Y LO PROPIO DE LA ACTIVIDAD (valga o no de una petición): lo mismo que reclaman las
    # pestañas de Contratación, para que esta pantalla sea el estado real de la actividad.
    # Estas no son de nadie en concreto (son del departamento), así que no llevan campanita.
    hechas = {f["key"] for f in filas}
    extra = []

    def suelta(key, n, label, icon, url=""):
        if key in hechas:
            return
        extra.append({"key": key, "phase": n, "label": label, "icon": icon, "state": "todo",
                      "mine": False, "blocked": False, "blocked_reason": "", "owner_nick": "",
                      "owner_user_id": "", "nudge_url": "", "url": url, "generic": True})

    try:
        confirmada = (getattr(concert, "status", None) or "BORRADOR").upper() == "CONFIRMADO"
        if not confirmada:
            suelta("confirmar", 5, "Pendiente de confirmar", "fa-circle-question")
        else:
            if not session_db.query(ConcertContract.id).filter(
                    ConcertContract.concert_id == concert.id).first():
                suelta("contrato", 6, "Sin contrato", "fa-file-signature")
            if (not getattr(concert, "announcement_date", None)
                    and not getattr(concert, "do_not_announce", False)):
                suelta("anuncio", 7, "Pendiente de anunciar", "fa-bullhorn")
            if _concert_sale_state(session_db, concert)["needs_activation"]:
                suelta("venta", 8, "Sin activar la venta", "fa-ticket")
        # Si la actividad NO viene de una petición, sus dos tareas de siempre también salen aquí.
        if not pendientes and (r is None or not getattr(r, "accepted_at", None)):
            if _concert_production_pending(concert):
                suelta("produccion", 4, "Activar producción", "fa-user-gear")
            if _peticion_artist_notice_pending(session_db, concert):
                suelta("informar", 4, "Informar al artista", "fa-bell",
                       url=url_for("concert_artist_notice_view", cid=concert.id))
    except Exception:
        app.logger.exception("[tareas] no se pudieron calcular las tareas propias de la actividad")
    filas += extra
    filas.sort(key=lambda f: f["phase"])
    pend = sum(1 for f in filas if f["state"] != "done")
    return {"rows": filas, "pending": pend, "total": len(filas),
            "request_id": (str(r.id) if r is not None else ""),
            "request_url": (url_for("booking_request_detail_view", rid=str(r.id))
                            if r is not None else "")}


@app.post("/conciertos/<cid>/tareas/<key>/reclamar", endpoint="concert_task_nudge")
@admin_required
def concert_task_nudge(cid, key):
    """RECLAMAR una tarea pendiente a quien la tiene (el botón de la campanita).

    Le llega un aviso diciendo QUIÉN se lo pide y QUÉ tarea es. No cambia nada de la actividad: solo
    avisa (y a uno mismo no se le reclama)."""
    session_db = db()
    next_url = safe_next_or(url_for("concert_detail_view", cid=cid, tab="inicio"))
    try:
        c = session_db.get(Concert, to_uuid(cid))
        if c is None:
            abort(404)
        tablero = _concert_task_board(session_db, c)
        fila = next((f for f in tablero["rows"] if f["key"] == (key or "").strip().lower()), None)
        if fila is None or fila.get("state") == "done":
            flash("Esa tarea ya no está pendiente.", "info")
            return redirect(next_url)
        destino = fila.get("owner_user_id") or ""
        estado = _current_user_state() or {}
        quien = (estado.get("nick") or estado.get("email") or "Alguien").strip()
        if not destino:
            flash("Esa tarea todavía no tiene a nadie asignado: no hay a quién reclamársela.",
                  "warning")
            return redirect(next_url)
        if str(destino) == str(estado.get("user_id") or ""):
            flash("Esa tarea es tuya.", "info")
            return redirect(next_url)
        titulo = "%s te reclama una tarea" % quien
        cuerpo = ("%s te pide que por favor termines «%s», que está pendiente." % (quien, fila["label"]))
        _notify_user(session_db, destino, "TAREA", titulo, cuerpo,
                     url_for("concert_detail_view", cid=c.id, tab="inicio"),
                     ref_type="concert_task", ref_id="%s:%s" % (c.id, fila["key"]))
        session_db.commit()
        flash("Avisado: %s tiene la tarea «%s»." % (fila.get("owner_nick") or "quien la tiene",
                                                    fila["label"]), "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[tareas] no se pudo reclamar la tarea")
        flash(f"No se pudo avisar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


def _peticion_acceptance_email_html(session_db, r, chip: dict | None = None, concert=None) -> str:
    """El correo con el que se le CONFIRMA a quien pidió algo que sale adelante.

    Estilo de la casa: el logo arriba a la DERECHA, el título centrado y la cabecera de la actividad
    tal como se ve en su ficha (`_contract_sheet_hero_rows`), que es lo que hay que confirmarle.
    ⚠️ Estilos EN LÍNEA: los clientes de correo se comen las hojas de estilo."""
    def esc(v) -> str:
        return str(escape("" if v is None else v))

    pay = r.payload if isinstance(r.payload, dict) else {}
    company = (getattr(concert, "billing_company", None) or getattr(concert, "group_company", None)) if concert is not None else None
    logo = ((getattr(company, "logo_url", "") or "").strip()
            or _treinta_y_tres_logo_url(session_db)
            or _external_url_for("static", filename="img/logo_33_producciones.png"))
    art = (getattr(concert, "artist", None) if concert is not None else None) or \
          (session_db.get(Artist, r.artist_id) if r.artist_id else None)
    act = ((getattr(concert, "activity_type", None) or pay.get("activity_type") or "CONCIERTO")).strip().upper()
    filas = [("Qué es", QUAD_ACTIVITY_LABELS.get(act, "Actividad")),
             ("Artista", (getattr(art, "name", "") or ""))]
    if concert is not None:
        filas += [(lbl, val) for _ico, lbl, val in _contract_sheet_hero_rows(concert)]
    else:
        venue = session_db.get(Venue, r.venue_id) if r.venue_id else None
        filas += [("Fecha", (r.requested_date.strftime("%d/%m/%Y") if r.requested_date else (r.date_text or ""))),
                  ("Lugar", _place_label(r.municipality or "", r.province or "",
                                         (pay.get("country") or ""), venue=(venue.name if venue else "")))]
    datos = "".join(
        '<tr><td style="padding:3px 10px 3px 0;color:#6b7280;font-size:13px;white-space:nowrap;">%s</td>'
        '<td style="padding:3px 0;font-size:14px;">%s</td></tr>' % (esc(k), esc(v))
        for k, v in filas if str(v or "").strip())
    quien = ((chip or {}).get("name") or (r.contact_name or "")).strip()
    partes = ['<div style="font-family:Arial,Helvetica,sans-serif;color:#212529;max-width:660px;margin:0 auto;">']
    partes.append('<div style="text-align:right;margin-bottom:6px;">'
                  '<img src="%s" alt="33 Producciones" style="max-height:54px;max-width:190px;"></div>' % esc(logo))
    partes.append('<h2 style="text-align:center;font-size:22px;margin:0 0 14px;">Confirmación de la actividad</h2>')
    partes.append('<div style="font-size:15px;line-height:1.7;margin:0 0 14px;">'
                  + ("Hola %s:<br>" % esc(quien) if quien else "")
                  + 'Gracias por contar con nosotros. Te confirmamos que '
                    '<strong>la actividad sale adelante</strong>.</div>')
    if datos:
        partes.append('<table style="border-collapse:collapse;margin:0 0 14px;">%s</table>' % datos)
    if (r.notes or "").strip():
        partes.append('<div style="margin:0 0 14px;padding:12px 14px;border-radius:12px;background:#f8fafc;'
                      'border:1px solid #e6e8eb;font-size:14px;line-height:1.7;color:#374151;'
                      'white-space:pre-line;">' + esc((r.notes or "").strip()) + '</div>')
    partes.append('<div style="font-size:15px;line-height:1.7;margin:0 0 14px;">'
                  'Te iremos contando los detalles. Cualquier cosa, nos dices.</div>')
    partes.append('<div style="color:#6b7280;font-size:13px;">33 Producciones</div></div>')
    return "".join(partes)


def _peticion_accept_owner_or_403(session_db, r):
    """La tarea es de QUIEN PIDIÓ la petición (o de dirección). Devuelve el estado si puede."""
    estado = _current_user_state() or {}
    propia = str(r.created_by_user_id or "") == str(estado.get("user_id") or "")
    if not (propia or is_master()):
        return None
    return estado


@app.post("/peticiones/<rid>/artista-confirmado", endpoint="booking_request_artist_agreed")
@admin_required
def booking_request_artist_agreed(rid):
    """«El artista lo confirma»: la fecha está hablada con él y quiere hacerlo (fase 2).

    Es una CONVERSACIÓN, no un correo: se marca a mano. Hasta que esto no está, no se le puede
    confirmar nada al promotor. Lo marca quien lleva la actividad (quien la pidió) o dirección."""
    session_db = db()
    next_url = safe_next_or(url_for("home"))
    try:
        r = session_db.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        estado = _peticion_accept_owner_or_403(session_db, r)
        if estado is None:
            flash("Esa petición no la has hecho tú.", "danger")
            return redirect(url_for("home"))
        if not r.concert_id:
            flash("Configura primero la actividad.", "warning")
            return redirect(url_for("booking_request_detail_view", rid=str(r.id), configurar=1))
        r.artist_agreed_at = _now_madrid()
        r.artist_agreed_by_nick = estado.get("nick") or estado.get("email") or ""
        session_db.commit()
        flash("Anotado: el artista ha confirmado la fecha. Ya puedes confirmárselo al promotor.",
              "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo marcar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/peticiones/<rid>/confirmar-promotor", endpoint="booking_request_acceptance_send")
@admin_required
def booking_request_acceptance_send(rid):
    """CONFIRMA al promotor (por su canal: correo o SMS) que la actividad sale adelante, y da la
    subtarea por hecha. Comunicar y marcar son la misma cosa vista de dos formas: si el aviso sale,
    la subtarea desaparece."""
    session_db = db()
    next_url = safe_next_or(url_for("home"))
    try:
        r = session_db.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        estado = _peticion_accept_owner_or_403(session_db, r)
        if estado is None:
            flash("Esa petición no la has hecho tú.", "danger")
            return redirect(url_for("home"))
        concert = session_db.get(Concert, r.concert_id) if r.concert_id else None
        # ⚠️ PRIMERO EL ARTISTA: no se le confirma nada al promotor sin que el artista haya dicho que
        # sí a la fecha. Lo comprueba el SERVIDOR (esconder el botón no basta).
        if not getattr(r, "artist_agreed_at", None):
            flash("Antes de confirmar al promotor tiene que confirmar el artista.", "warning")
            return redirect(next_url)
        quien = _peticion_accept_contact(session_db, r, concert)
        if not quien.get("email") and not quien.get("phone"):
            flash("No hay correo ni teléfono de quien la pidió: confírmaselo tú y marca la tarea.",
                  "warning")
            return redirect(next_url)
        fila = (_notify_apply_prefs(session_db, [{
            "name": quien.get("name") or "", "email": quien.get("email") or "",
            "phone": quien.get("phone") or "",
        }]) or [{}])[0]
        asunto = "Confirmada · %s" % (r.subject or "Tu petición")
        html_cuerpo = _peticion_acceptance_email_html(session_db, r, quien, concert)
        fecha = ((concert.date.strftime("%d/%m/%Y") if getattr(concert, "date", None) else "")
                 or (r.requested_date.strftime("%d/%m/%Y") if r.requested_date else ""))
        sms = "%s: confirmado, sale adelante%s." % ((r.subject or "Tu petición"),
                                                    (" (%s)" % fecha if fecha else ""))
        ok, err = _notify_send_row(session_db, fila, subject=asunto, html=html_cuerpo,
                                   sms_text=sms, kind="PETICION")
        if not ok:
            flash("No se pudo confirmar: %s" % (err or "el aviso no salió"), "danger")
            return redirect(next_url)
        r.acceptance_notified_at = _now_madrid()
        r.acceptance_notified_by_nick = estado.get("nick") or estado.get("email") or ""
        _notify_resolve(session_db, "peticion_aceptada", str(r.id))
        session_db.commit()
        flash("Confirmado por %s." % (
            "SMS" if (fila.get("channel") or "EMAIL") == "SMS" else "correo"), "success")
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[peticiones] no se pudo confirmar al promotor")
        flash(f"No se pudo confirmar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/peticiones/<rid>/promotor-confirmado", endpoint="booking_request_acceptance_notified")
@admin_required
def booking_request_acceptance_notified(rid):
    """«Ya se lo he confirmado»: la subtarea de avisar al promotor queda hecha (se le habrá dicho por
    teléfono). Lo marca QUIEN LA PIDIÓ o dirección."""
    session_db = db()
    next_url = safe_next_or(url_for("home"))
    try:
        r = session_db.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        estado = _peticion_accept_owner_or_403(session_db, r)
        if estado is None:
            flash("Esa petición no la has hecho tú.", "danger")
            return redirect(url_for("home"))
        if not getattr(r, "artist_agreed_at", None):
            flash("Antes de confirmar al promotor tiene que confirmar el artista.", "warning")
            return redirect(next_url)
        r.acceptance_notified_at = _now_madrid()
        r.acceptance_notified_by_nick = estado.get("nick") or estado.get("email") or ""
        _notify_resolve(session_db, "peticion_aceptada", str(r.id))
        session_db.commit()
        flash("Anotado: el promotor ya está confirmado.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo marcar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/peticiones/<rid>/aprobar", endpoint="booking_request_approve")
@admin_required
def booking_request_approve(rid):
    """APROBAR una petición: el departamento da el visto bueno y la devuelve a QUIEN LA PIDIÓ para
    que **configure la actividad**.

    ⚠️⚠️ Aquí ya NO se crea ningún borrador: la actividad la crea el asistente al terminar de
    configurarla (con los datos de la petición ya puestos), que es donde se dicen la fecha, el
    recinto, el caché, las entradas… Antes se creaba un borrador con una fecha inventada
    (`today_local()`) que luego había que arreglar a mano.
    Mientras no esté configurada, a quien la pidió le sale como tarea con la etiqueta **«Petición
    aprobada»** y el botón **«Configurar evento»**."""
    s = db()
    try:
        r = s.get(BookingRequest, to_uuid(rid))
        if not r:
            abort(404)
        if r.concert_id:
            return redirect(url_for("concert_detail_view", cid=r.concert_id))
        if not r.artist_id:
            flash("Añade un artista a la petición antes de aprobarla (edítala).", "warning")
            return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))
        pay = dict(r.payload or {})
        # El tipo puede venir del botón «en qué se convierte» de la ficha; si no, el de la petición.
        _wanted = (request.form.get("activity_type") or "").strip().upper()
        activity_type = (_wanted if _wanted in QUAD_ACTIVITY_LABELS
                         else (pay.get("activity_type") or "CONCIERTO").strip().upper())
        pay["activity_type"] = activity_type
        r.payload = pay
        st = _current_user_state()
        r.status = "CONVERTIDA"
        r.accepted_at = _now_madrid()
        r.reviewed_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        r.reviewed_by_nick = st.get("nick") or st.get("email") or ""
        url_configurar = url_for("booking_request_detail_view", rid=str(r.id), configurar=1)
        # A quien la pidió: lo primero es CONFIGURAR la actividad (el asistente se abre con lo que ya
        # se sabe). De ahí en adelante el trabajo va por fases y es suyo.
        if r.created_by_user_id:
            _notify_user(s, r.created_by_user_id, "TAREA",
                         "Petición aprobada · %s" % QUAD_ACTIVITY_LABELS.get(activity_type, "Actividad"),
                         "«%s» está aprobada: configura la actividad para crearla."
                         % (r.subject or "Petición"),
                         url_configurar,
                         ref_type="peticion_aceptada", ref_id=str(r.id))
        s.commit()
        quien = (r.created_by_nick or "").strip()
        # Si la aprueba la MISMA persona que la pidió, se le lleva directamente a configurarla.
        if str(r.created_by_user_id or "") == str(st.get("user_id") or ""):
            flash("Petición aprobada. Configura la actividad para crearla.", "success")
            return redirect(url_configurar)
        flash("Petición aprobada%s: le sale como tarea para configurar la actividad."
              % ((" · avisado %s" % quien) if quien else ""), "success")
        return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo aprobar la petición: {exc}", "danger")
        return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))
    finally:
        s.close()


# ================= ASISTENTE NUEVO DE PETICIONES (multipaso) =================
# Departamentos a los que se reparte una petición (payload['departments']).
PETICION_DEPARTMENTS = {"CONTRATACION", "SELLO", "PROMO", "DISENO"}


def _peticion_departments(activity_type, no_cache, explicit=None):
    """Departamentos que ven la petición:
    - Con caché → Contratación; sin caché → Sello.
    - Actividad de TV → además Promoción (aparece en los dos).
    - ``explicit`` (del botón global «¿para qué es?») fuerza un departamento concreto.
    """
    at = (activity_type or "").strip().upper()
    depts = []
    e = (explicit or "").strip().upper()
    if e in PETICION_DEPARTMENTS:
        depts.append(e)
    if e not in ("PROMO", "DISENO"):
        base = "SELLO" if no_cache else "CONTRATACION"
        if base not in depts:
            depts.append(base)
    if at == "TV" and "PROMO" not in depts:
        depts.append("PROMO")
    return depts or ["CONTRATACION"]


def _peticion_month_label(ym):
    try:
        y, m = (ym or "").split("-")
        return f"{MONTHS_ES[int(m) - 1]} {y}"
    except Exception:
        return ym or ""


@app.get("/api/municipios", endpoint="api_city_search")
@admin_required
def api_city_search():
    """CIUDADES para rellenar un formulario, con SU PROVINCIA: al escribirla salen las opciones y la
    provincia se pone sola.

    ⚠️ Se busca primero en NUESTROS datos (los municipios de los recintos y de las actividades): son
    pares ciudad+provincia ya curados por la casa, salen al instante y no dependen de nadie. Solo si
    hay pocos se pregunta al buscador de direcciones, y de ahí la provincia sale del CÓDIGO POSTAL
    (la tabla de `geo_utils`), nunca de la comunidad autónoma que devuelve el proveedor.
    """
    q = (request.args.get("q") or "").strip()
    if len(q) < 2:
        return jsonify({"ok": True, "rows": []})
    clave = _norm_text_key(q)
    filas, vistos = [], set()

    def añade(ciudad, provincia, pais=""):
        ciudad = (ciudad or "").strip()
        if not ciudad:
            return
        k = _norm_text_key(ciudad)
        if k in vistos:
            return
        vistos.add(k)
        provincia = (provincia or "").strip()
        pais = (pais or "").strip()
        filas.append({"city": ciudad, "province": provincia, "country": pais,
                      # Cómo se lee: «Municipio, Provincia» y el país solo si no es España.
                      "label": _place_label(ciudad, provincia, pais)})

    s = db()
    try:
        # Recintos y actividades: lo que la casa ya escribe todos los días.
        for ciudad, provincia in (s.query(Venue.municipality, Venue.province)
                                  .filter(_sa_contains_text(Venue.municipality, q))
                                  .order_by(Venue.municipality.asc()).limit(40).all()):
            añade(ciudad, provincia)
        if len(filas) < 8:
            for ciudad, provincia in (s.query(Concert.manual_municipality, Concert.manual_province)
                                      .filter(_sa_contains_text(Concert.manual_municipality, q))
                                      .order_by(Concert.manual_municipality.asc()).limit(40).all()):
                añade(ciudad, provincia)
    except Exception:
        app.logger.exception("[municipios] no se pudo buscar en nuestros datos")
    finally:
        s.close()
    # Lo que empieza por lo escrito, primero.
    filas.sort(key=lambda f: (0 if _norm_text_key(f["city"]).startswith(clave) else 1,
                              _norm_text_key(f["city"])))
    if len(filas) < 6:
        # Primero sesgado a España (que es el 99% de lo que se pide) y, si sigue habiendo poco, el
        # término a secas: así también salen las ciudades de FUERA, con su país.
        try:
            import geo_utils
            for termino in ("%s España" % q, q):
                for f in geo_utils.search_addresses(termino, limit=8):
                    añade(f.get("city"), f.get("province"), f.get("country"))
                # ⚠️ Se cuentan solo las que CASAN con lo escrito: la vuelta sesgada a España
                # devuelve seis ciudades de aquí que no tienen nada que ver, y contándolas no se
                # llegaba a preguntar por el término a secas (así «Lisboa» no salía).
                if sum(1 for f in filas if clave in _norm_text_key(f["city"])) >= 6:
                    break
        except Exception:
            pass          # el buscador es una AYUDA: si falla, se escribe a mano
    # ⚠️ El buscador de direcciones devuelve lo que tiene CERCA aunque no se parezca a lo escrito
    # («Toulouse» → Zaragoza): en un selector de ciudades eso es ruido, así que solo se queda lo que
    # de verdad casa con lo que se ha escrito, y lo que EMPIEZA por ello va primero.
    filas = [f for f in filas if clave in _norm_text_key(f["city"])]
    filas.sort(key=lambda f: (0 if _norm_text_key(f["city"]).startswith(clave) else 1,
                              _norm_text_key(f["city"])))
    return jsonify({"ok": True, "rows": filas[:12]})


def _peticion_edit_payload(session_db, r) -> dict:
    """Los datos de una petición tal como los espera el asistente para EDITARLA."""
    pay = r.payload or {}
    venue = session_db.get(Venue, r.venue_id) if r.venue_id else None
    sub = ""
    if venue is not None:
        sub = ", ".join([x for x in [(venue.municipality or ""), (venue.province or "")] if x])
    requester_logo, requester_sub = "", ""
    if r.promoter_id:
        p = session_db.get(Promoter, r.promoter_id)
        if p is not None:
            requester_logo = (getattr(p, "logo_url", "") or "")
            requester_sub = (getattr(p, "tax_id", "") or "")
    # ⚠️ `url_for` necesita contexto de aplicación y esta fila se monta también desde sitios que no
    # son una petición (un cron, un hilo en 2º plano): si no lo hay, se pone la ruta a mano.
    try:
        edit_url = url_for("peticion_wizard_update", rid=str(r.id))
    except Exception:
        edit_url = "/peticiones/%s/editar" % r.id
    return {
        "id": str(r.id),
        "edit_url": edit_url,
        "department": ((pay.get("departments") or [None]) or [None])[0] or "",
        "activity_type": (pay.get("activity_type") or "CONCIERTO"),
        "artist_id": (str(r.artist_id) if r.artist_id else ""),
        "venue_id": (str(r.venue_id) if r.venue_id else ""),
        "venue_name": (getattr(venue, "name", "") or ""),
        "venue_sub": sub,
        "venue_photo": (getattr(venue, "photo_url", "") or ""),
        "municipality": (r.municipality or ""),
        "province": (r.province or ""),
        "country": (pay.get("country") or "España"),
        "date_kind": (pay.get("date_kind") or ("EXACT" if r.requested_date else "UNKNOWN")),
        "requested_date": (r.requested_date.strftime("%Y-%m-%d") if r.requested_date else ""),
        "range_start": (pay.get("range_start") or ""),
        "range_end": (pay.get("range_end") or ""),
        "month": (pay.get("month") or ""),
        "requester_type": (pay.get("requester_type") or "promoter"),
        "requester_id": (pay.get("requester_id") or ""),
        "requester_name": (pay.get("requester_name") or (r.contact_name or "")),
        "requester_sub": requester_sub,
        "requester_logo": requester_logo,
        "requester_email": (r.contact_email or ""),
        "requester_phone": (r.contact_phone or ""),
        "no_cache": bool(pay.get("no_cache")),
        "promoter_costs": (pay.get("promoter_costs") or {"enabled": False, "items": []}),
        "fee_text": (r.fee_text or ""),
        "description": (pay.get("description") or r.notes or ""),
    }


PETICION_STUB_BACKFILL_FLAG = "peticion_stub_backfill_v1"


def _concert_is_untouched_stub(session_db, c) -> bool:
    """¿Esta actividad es un BORRADOR VACÍO de los que creaba el aprobado antiguo?

    El aprobado de antes creaba un `Concert` con una fecha inventada y nada más. Se reconoce porque
    sigue en BORRADOR, **no ha pasado por el asistente** (`contracting_payload` vacío) y no tiene
    NADA colgando: ni bolsa, ni entradas, ni cachés, ni contratos, ni cartelería, ni pagos, ni hoja
    de ruta, ni invitaciones. Con cualquiera de esas cosas ya no se toca (alguien ha trabajado en
    ella)."""
    if c is None:
        return False
    if (getattr(c, "status", "") or "").upper() != "BORRADOR":
        return False
    for campo in ("contracting_payload", "ticketing_payload", "equipment_payload",
                  "promoter_costs_payload", "payment_terms_json", "invitations_json",
                  "roadmap_payload"):
        if getattr(c, campo, None):
            return False
    try:
        if (session_db.query(ConcertTicketType.id).filter(ConcertTicketType.concert_id == c.id).first()
                or session_db.query(ConcertCache.id).filter(ConcertCache.concert_id == c.id).first()
                or session_db.query(ConcertContract.id).filter(ConcertContract.concert_id == c.id).first()
                or session_db.query(ConcertArtworkRequest.id).filter(ConcertArtworkRequest.concert_id == c.id).first()
                or session_db.query(ConcertBudgetItem.id).filter(ConcertBudgetItem.concert_id == c.id).first()
                or session_db.query(WorkflowBag.id).filter(WorkflowBag.linked_type.in_(("CONCERT", "concert")),
                                                           WorkflowBag.linked_id == c.id).first()):
            return False
    except Exception:
        app.logger.exception("[peticiones] no se pudo comprobar si el borrador está vacío")
        return False
    return True


def _peticion_stub_backfill():
    """⚠️ ARREGLO PUNTUAL de las peticiones que YA se habían aprobado: que sigan los pasos.

    El aprobado antiguo creaba un BORRADOR vacío (con una fecha inventada) y no dejaba constancia de
    la aprobación, así que esas peticiones **no reclamaban nada**: ni salían con «Petición aprobada»
    ni pedían configurar el evento. Este relleno las devuelve al camino nuevo:
      · si su actividad es un borrador vacío (`_concert_is_untouched_stub`), se **borra** y la
        petición vuelve a «pendiente de configurar»;
      · y a las aprobadas sin `accepted_at` **que no tienen actividad de verdad** se les sella la
        fecha, que es lo que hace que aparezcan las fases.
    ⚠️ Lo que ya está configurado NO se toca: una actividad con trabajo hecho no vuelve atrás."""
    s = db()
    tocadas, borradas = 0, 0
    try:
        filas = (s.query(BookingRequest)
                 .filter(func.upper(func.coalesce(BookingRequest.status, "")) == "CONVERTIDA")
                 .all())
        for r in filas:
            c = s.get(Concert, r.concert_id) if r.concert_id else None
            if c is not None and _concert_is_untouched_stub(s, c):
                r.concert_id = None
                try:
                    s.delete(c)
                    borradas += 1
                except Exception:
                    app.logger.exception("[peticiones] no se pudo borrar el borrador vacío %s", c.id)
                    s.rollback()
                    continue
                c = None
            if c is None and not r.accepted_at:
                # Aprobada antes de que existiera la marca: se sella para que salgan sus fases.
                r.accepted_at = (r.updated_at or r.created_at or _now_madrid())
                tocadas += 1
        s.commit()
        app.logger.info("[peticiones] arreglo de aprobadas: %s borradores vacíos retirados, "
                        "%s peticiones devueltas al proceso", borradas, tocadas)
    except Exception:
        s.rollback()
        app.logger.exception("[peticiones] no se pudo arreglar las aprobadas")
    finally:
        s.close()


def _peticion_stub_backfill_once():
    """Corre el arreglo UNA vez (marca en `AppSetting`)."""
    if (_get_app_setting(PETICION_STUB_BACKFILL_FLAG) or "").strip():
        return
    _peticion_stub_backfill()
    _set_app_setting(PETICION_STUB_BACKFILL_FLAG, _now_madrid().isoformat())


def _peticion_wizard_prefill(session_db, r) -> dict:
    """Lo que la petición ya sabe, en el formato que entiende el ASISTENTE de actividad.

    Con esto, «Configurar evento» abre el asistente de siempre (los mismos pasos que al añadir una
    actividad nueva) pero **ya cumplimentado** con lo que se pidió: artista, tipo, fecha, sitio,
    quién lo pide como promotor, si lleva caché (y su importe si era un número), lo que cubre el
    promotor y la descripción. Lo que no se sepa se deja en blanco para rellenarlo ahí."""
    pay = r.payload if isinstance(r.payload, dict) else {}
    venue = session_db.get(Venue, r.venue_id) if r.venue_id else None
    etiqueta_recinto = ""
    if venue is not None:
        etiqueta_recinto = " · ".join([x for x in [
            (venue.name or ""),
            ", ".join([y for y in [(venue.municipality or ""), (venue.province or "")] if y]),
        ] if x])
    # La fecha: la pedida y, si no había día concreto, el principio de la franja o del mes.
    fecha = r.requested_date
    if not fecha:
        kind = (pay.get("date_kind") or "").upper()
        if kind == "RANGE" and pay.get("range_start"):
            fecha = parse_optional_date(pay.get("range_start"))
        elif kind == "MONTH" and pay.get("month"):
            fecha = parse_optional_date(str(pay.get("month")) + "-01")
    # QUIÉN LO PIDE hace de promotor en la actividad (si es un tercero: una persona de la oficina no).
    promotor, promotor_nombre, promotor_logo = "", "", ""
    if r.promoter_id:
        p = session_db.get(Promoter, r.promoter_id)
        if p is not None:
            promotor = str(p.id)
            promotor_nombre = (p.nick or p.name or "").strip()
            promotor_logo = (p.logo_url or "").strip()
    # El importe orientativo es texto libre («3.000 € + IVA»): solo se vuelca si es un número.
    importe = ""
    try:
        _d = _parse_optional_decimal(r.fee_text)
        if _d is not None and _d > 0:
            importe = format(_d.normalize(), "f")
    except Exception:
        importe = ""
    return {
        "enabled": True,
        "peticion_id": str(r.id),
        "artist_id": (str(r.artist_id) if r.artist_id else ""),
        "activity_type": (pay.get("activity_type") or "CONCIERTO").strip().upper(),
        "date": (fecha.strftime("%Y-%m-%d") if fecha else ""),
        "venue_id": (str(r.venue_id) if r.venue_id else ""),
        "venue_label": etiqueta_recinto,
        "municipality": (r.municipality or ""),
        "province": (r.province or ""),
        "promoter_id": promotor,
        "promoter_name": promotor_nombre,
        "promoter_logo": promotor_logo,
        "has_cache": (0 if pay.get("no_cache") else 1),
        "fee_amount": importe,
        "fee_text": (r.fee_text or ""),
        "promoter_costs": (pay.get("promoter_costs") or {"enabled": False, "items": []}),
        "description": (pay.get("description") or r.notes or ""),
    }


def _peticion_apply_form(session_db, r, f, *, editing: bool = False) -> str:
    """Vuelca el formulario del asistente en la petición. Devuelve el asunto calculado.

    Es el punto ÚNICO: lo usan crear y editar, así que una petición editada queda EXACTAMENTE como si
    se hubiera creado así (nada de dos sitios que se desincronizan)."""
    activity_type = (f.get("activity_type") or "CONCIERTO").strip().upper()
    no_cache = _truthy(f.get("no_cache"))
    explicit_dept = (f.get("department") or "").strip().upper() or None

    aid = (f.get("artist_id") or "").strip()
    r.artist_id = to_uuid(aid) if aid else None
    r.artist_ids = [aid] if aid else []

    # ¿Se sabe dónde? NO TODAVÍA / el recinto / la ciudad. Lo que no se elige se limpia: una petición
    # no puede quedarse con un recinto de antes y una ciudad nueva a la vez.
    place_kind = (f.get("place_kind") or "").strip().upper()
    vid = (f.get("venue_id") or "").strip()
    muni = (f.get("municipality") or "").strip()
    if not place_kind:                    # formularios antiguos: se deduce de lo que llega
        place_kind = "VENUE" if vid else ("CITY" if muni else "NONE")
    r.venue_id = to_uuid(vid) if (place_kind == "VENUE" and vid) else None
    r.municipality = muni or None if place_kind == "CITY" else None
    r.province = ((f.get("province") or "").strip() or None) if place_kind == "CITY" else None
    country = (f.get("country") or "").strip() or "España"

    kind = (f.get("date_kind") or "EXACT").strip().upper()
    pay = dict(r.payload or {}) if editing else {}
    r.requested_date = None
    r.date_text = None
    if kind == "EXACT":
        r.requested_date = parse_optional_date(f.get("requested_date"))
        if not r.requested_date:
            kind = "UNKNOWN"
    if kind == "RANGE":
        rs = (f.get("range_start") or "").strip()
        re_ = (f.get("range_end") or "").strip()
        pay["range_start"] = rs
        pay["range_end"] = re_
        r.date_text = f"Franja: {rs or '?'} → {re_ or '?'}"
    elif kind == "MONTH":
        ym = (f.get("month") or "").strip()
        pay["month"] = ym
        r.date_text = f"Mes: {_peticion_month_label(ym)}"
    elif kind == "UNKNOWN":
        r.date_text = "Fecha sin definir"
    pay["date_kind"] = kind

    req_type = (f.get("requester_type") or "").strip().lower()
    req_id = (f.get("requester_id") or "").strip()
    req_name = (f.get("requester_name") or "").strip()
    r.contact_name = req_name or None
    r.contact_email = (f.get("requester_email") or "").strip() or None
    r.contact_phone = (f.get("requester_phone") or "").strip() or None
    r.promoter_id = (to_uuid(req_id) if (req_type in ("promoter", "empresa", "institucion") and req_id)
                     else None)

    r.fee_text = None if no_cache else ((f.get("fee_text") or "").strip() or None)
    r.notes = (f.get("description") or "").strip() or None

    subject = (f.get("subject") or "").strip()
    if not subject:
        art = session_db.get(Artist, r.artist_id) if r.artist_id else None
        parts = [QUAD_ACTIVITY_LABELS.get(activity_type, activity_type.title())]
        if art:
            parts.append(art.name)
        if r.municipality:
            parts.append(r.municipality)
        subject = " · ".join([p for p in parts if p])
    r.subject = subject or "Petición"

    # ¿CUBREN GASTOS? El mismo módulo que en el asistente de actividad (mismos nombres de campo, así
    # que lo lee el mismo parser). Sin caché no se pregunta, y por tanto no se guarda.
    gastos = ({"enabled": False, "items": []} if no_cache
              else _parse_promoter_costs_form(f) if hasattr(f, "getlist")
              else {"enabled": False, "items": []})
    pay.update({
        "activity_type": activity_type,
        "country": country,
        "no_cache": no_cache,
        "promoter_costs": gastos,
        "departments": _peticion_departments(activity_type, no_cache, explicit_dept),
        "place_kind": place_kind,
        "requester_type": req_type,
        "requester_id": req_id,
        "requester_name": req_name,
        "description": r.notes or "",
    })
    r.payload = pay
    return r.subject


@app.post("/peticiones/<rid>/editar", endpoint="peticion_wizard_update")
@admin_required
def peticion_wizard_update(rid):
    """Edita una petición ya creada con el MISMO asistente con el que se creó."""
    s = db()
    try:
        r = s.get(BookingRequest, to_uuid(rid))
        if r is None:
            flash("Esa petición ya no existe.", "warning")
            return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))
        # ⚠️ La edita QUIEN LA HIZO (para eso está en «Mis peticiones») o quien gestiona su bandeja.
        estado = _current_user_state() or {}
        propia = str(r.created_by_user_id or "") == str(estado.get("user_id") or "")
        if not (propia or is_master() or has_access_key("contratacion.peticiones", edit=True,
                                                        include_descendants=True)):
            flash("Esa petición no la has hecho tú.", "danger")
            return redirect(request.form.get("next") or url_for("home"))
        _peticion_apply_form(s, r, request.form, editing=True)
        r.updated_at = func.now()
        s.commit()
        flash("Petición actualizada.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo guardar la petición: {exc}", "danger")
    finally:
        s.close()
    return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))


def _home_activity_phase_tasks(limit: int = 12) -> list[dict]:
    """LO QUE FALTA en lo que se ha aprobado, leído **como la ACTIVIDAD**: al aprobar la petición, lo
    que hay es el evento (promocional, de TV, lo que sea) y el trabajo es suyo, no de la petición.

    Va **por fases y en orden** (`_peticion_accept_tasks`): configurar el evento → confirmar con el
    artista → confirmar al promotor → activar producción e informar al artista. Mientras no esté
    configurada, la fila se monta con los datos de la PETICIÓN y sale con la etiqueta «Petición
    aprobada» y el botón «Configurar evento»."""
    estado = _current_user_state() or {}
    uid = str(estado.get("user_id") or "")
    if not uid:
        return []
    s = db()
    try:
        pk = to_uuid(uid)
        consulta = (s.query(BookingRequest)
                    .options(joinedload(BookingRequest.artist))
                    .filter(BookingRequest.accepted_at.isnot(None),
                            func.upper(func.coalesce(BookingRequest.status, "")) == "CONVERTIDA"))
        # ⚠️ DIRECCIÓN lo ve TODO (también tiene su módulo de tareas en Inicio); el resto, lo que
        # pidió o lo que aprobó.
        if (estado.get("role") != 10):
            consulta = consulta.filter(or_(BookingRequest.created_by_user_id == pk,
                                           BookingRequest.reviewed_by_user_id == pk))
        peticiones = consulta.order_by(BookingRequest.accepted_at.desc()).limit(80).all()
        if not peticiones:
            return []
        ids = [r.concert_id for r in peticiones if r.concert_id]
        conciertos = {}
        if ids:
            for c in (s.query(Concert)
                      .options(joinedload(Concert.artist), joinedload(Concert.venue))
                      .filter(Concert.id.in_(ids)).all()):
                conciertos[str(c.id)] = c
        salida = []
        for r in peticiones:
            c = conciertos.get(str(r.concert_id)) if r.concert_id else None
            tareas = _peticion_accept_tasks(s, r, c, for_user=uid)
            if not tareas:
                continue
            pay = r.payload if isinstance(r.payload, dict) else {}
            if c is not None:
                # YA CONFIGURADA: la fila es la actividad.
                kind = _activity_kind_key(c.activity_type) or "CONCIERTO"
                fila = {
                    "id": str(c.id),
                    "url": url_for("concert_detail_view", cid=c.id),
                    "artist": (c.artist.name if c.artist else ""),
                    "artist_photo": ((c.artist.photo_url or "") if c.artist else ""),
                    "title": ((c.festival_name or "").strip() or (c.artist.name if c.artist else "")
                              or _activity_kind_label(kind)),
                    "date_label": (c.date.strftime("%d/%m/%Y") if c.date else "Sin fecha"),
                    "place_label": _place_label(_concert_city(c) or "", _concert_province_value(c) or "",
                                                venue=(_concert_venue_name(c) or "")),
                    "status_label": _concert_status_meta(c.status)[0],
                    "status_badge": _concert_status_meta(c.status)[1],
                    "cache_label": _activity_cache_label(c.sale_type, c.activity_type),
                }
            else:
                # TODAVÍA SIN CONFIGURAR: la fila se monta con lo de la petición.
                kind = _activity_kind_key(pay.get("activity_type")) or "CONCIERTO"
                fecha = (r.requested_date.strftime("%d/%m/%Y") if r.requested_date
                         else ((r.date_text or "").strip() or "Sin fecha"))
                fila = {
                    "id": str(r.id),
                    "url": url_for("booking_request_detail_view", rid=str(r.id), configurar=1),
                    "artist": (r.artist.name if r.artist else ""),
                    "artist_photo": ((r.artist.photo_url or "") if r.artist else ""),
                    "title": ((r.artist.name if r.artist else "") or (r.subject or "")
                              or _activity_kind_label(kind)),
                    "date_label": fecha,
                    "place_label": _place_label(r.municipality or "", r.province or "",
                                                (pay.get("country") or "")),
                    "status_label": "Petición aprobada",
                    "status_badge": "text-bg-success",
                    "cache_label": ("Sin caché" if pay.get("no_cache") else "Con caché"),
                }
            fila.update({
                "request_id": str(r.id),
                "icon": QUAD_ACTIVITY_ICONS.get(kind, "fa-calendar-day"),
                "type_label": _activity_kind_label(kind),
                "configured": c is not None,
                "tasks": tareas,
                # Lo que puedo hacer YO va primero: si tengo algo que hacer, la fila sube.
                "mine": any(t.get("mine") and not t.get("blocked") for t in tareas),
            })
            salida.append(fila)
            if len(salida) >= limit:
                break
        salida.sort(key=lambda f: (0 if f.get("mine") else 1, 0 if not f.get("configured") else 1))
        return salida
    except Exception:
        app.logger.exception("[inicio] no se pudieron cargar las fases de las actividades")
        return []
    finally:
        s.close()


def _home_my_peticiones(limit: int = 12) -> list[dict]:
    """MIS PETICIONES: las que ha hecho esta persona, para ver cómo van sin buscarlas.

    Solo las VIVAS y las resueltas hace poco: una petición de hace un año no es seguimiento.

    ⚠️ Una petición RECHAZADA sale aquí mismo como **pendiente de comunicar** (con sus dos botones:
    comunicarlo desde la app o decir que ya se ha dicho), no en otro módulo: es la misma petición en
    otro momento de su vida. Cuando se comunica, se archiva y desaparece."""
    estado = _current_user_state() or {}
    uid = estado.get("user_id")
    if not uid:
        return []
    s = db()
    try:
        desde = datetime.now(TZ_MADRID) - timedelta(days=120)
        filas = (s.query(BookingRequest)
                 .options(joinedload(BookingRequest.artist), joinedload(BookingRequest.venue))
                 .filter(BookingRequest.created_by_user_id == to_uuid(str(uid)))
                 .order_by(BookingRequest.created_at.desc())
                 .limit(60).all())
        salida = []
        for r in filas:
            est = (r.status or "NUEVA").upper()
            # RECHAZADA y ya comunicada = archivada: la tarea está hecha y deja de estar aquí.
            if est == "DESCARTADA" and r.rejection_notified_at:
                continue
            # ⚠️ Una petición APROBADA con trabajo pendiente NO sale aquí: está en el módulo
            # «Actividades por cerrar» (ya es la actividad, con sus fases). Aquí se queda solo
            # cuando ya no hay nada que hacer, como seguimiento, y por poco tiempo.
            if est == "CONVERTIDA" and r.accepted_at and _peticion_accept_tasks(s, r):
                continue
            if est in ("CONVERTIDA", "DESCARTADA"):
                creada = r.created_at
                if creada is not None and creada.tzinfo is None:
                    creada = creada.replace(tzinfo=TZ_MADRID)
                if creada is not None and creada < desde:
                    continue
            pay = r.payload or {}
            etiqueta, clase = _booking_status_meta(est)
            lugar = ((r.venue.name if r.venue else "") or (r.municipality or ""))
            chip = _peticion_requester_chip(s, r) or {}
            pendiente = bool(est == "DESCARTADA" and not r.rejection_notified_at)
            salida.append({
                "id": str(r.id),
                "subject": (r.subject or "Petición"),
                "artist": (r.artist.name if r.artist else ""),
                "artist_photo": ((r.artist.photo_url or "") if r.artist else ""),
                "place": lugar,
                # Pendiente de COMUNICAR el rechazo: se resuelve en esta misma fila.
                "rejection_pending": pendiente,
                # Al pinchar una petición se abre SU FICHA (la ve también quien la pidió).
                "detail_url": url_for("booking_request_detail_view", rid=str(r.id)),
                # La actividad en la que se convirtió (si se aceptó), para poder ir a ella.
                "activity_url": (url_for("concert_detail_view", cid=str(r.concert_id))
                                 if r.concert_id else ""),
                "reason": (r.rejection_reason or ""),
                "send_url": (url_for("booking_request_rejection_send", rid=str(r.id))
                             if pendiente else ""),
                "done_url": (url_for("booking_request_rejection_notified", rid=str(r.id))
                             if pendiente else ""),
                "who": (chip.get("name") or ""),
                "who_logo": (chip.get("logo_url") or ""),
                "who_icon": (chip.get("icon") or "fa-user"),
                "contact": (chip.get("contact") or ""),
                "date_label": (r.requested_date.strftime("%d/%m/%Y") if r.requested_date
                               else (r.date_text or "Sin fecha")),
                "status": est, "status_label": etiqueta, "status_class": clase,
                "kind_label": _activity_kind_label(pay.get("activity_type")),
                "icon": QUAD_ACTIVITY_ICONS.get(_activity_kind_key(pay.get("activity_type")),
                                                "fa-calendar-day"),
                "departments": [str(d).title() for d in (pay.get("departments") or [])],
                # ⚠️ La bandeja es de Contratación: a quien no la tenga no se le ofrece el enlace
                # (sería un 403). Su tarea se resuelve en la propia fila.
                "url": (url_for("contracting_view", section="peticiones")
                        if has_access_key("contratacion", include_descendants=True) else ""),
                "edit": _peticion_edit_payload(s, r),
            })
            if len(salida) >= limit:
                break
        # Lo que hay que HACER va primero: comunicar un rechazo es una tarea, no un seguimiento.
        salida.sort(key=lambda f: 0 if f.get("rejection_pending") else 1)
        return salida
    except Exception:
        app.logger.exception("[inicio] no se pudieron cargar mis peticiones")
        return []
    finally:
        s.close()


@app.post("/peticiones/crear", endpoint="peticion_wizard_create")
@admin_required
def peticion_wizard_create():
    """Crea una petición desde el asistente multipaso. Los campos que no tiene el modelo (tipo de
    actividad, país, franja/mes, sin caché, departamentos, quién pide) se guardan en ``payload``
    (JSONB) para no tocar el esquema. El volcado del formulario es el MISMO que al editarla
    (`_peticion_apply_form`)."""
    s = db()
    try:
        r = BookingRequest(status="NUEVA")
        _peticion_apply_form(s, r, request.form)
        r.source = "OTRO"
        st = _current_user_state()
        r.created_by_user_id = to_uuid(st.get("user_id")) if st.get("user_id") else None
        r.created_by_nick = st.get("nick") or st.get("email") or ""
        s.add(r)
        s.commit()
        flash("Petición creada.", "success")
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo crear la petición: {exc}", "danger")
    finally:
        s.close()
    return redirect(request.form.get("next") or url_for("contracting_view", section="peticiones"))


# ================= SECCIONES PROMOCIÓN / DISEÑO (bandejas de peticiones por departamento) =========
# Secciones nuevas del menú (aparte de "Marketing"). Cada una es la bandeja de peticiones que le
# corresponden a ese departamento. ⚠️ El reparto vive en payload['departments'] (LISTA: una petición
# puede tocar a varios) y se lee SIEMPRE con `_booking_in_department`; no hay ningún campo singular.
def _render_department_inbox(dept_key: str, title: str, icon: str, subtitle: str,
                             promo_tab: str = "activas", promo_vista: str = "lista",
                             promo_sujeto: str = ""):
    s = db()
    try:
        try:
            rows_all = (
                s.query(BookingRequest)
                .options(joinedload(BookingRequest.artist))
                .order_by(BookingRequest.received_at.desc().nullslast(), BookingRequest.created_at.desc())
                .limit(500)
                .all()
            )
            mine = [r for r in rows_all if _booking_in_department(r, dept_key)]
        except Exception:
            mine = []
        pending = [r for r in mine if (r.status or "NUEVA").upper() in {"NUEVA", "EN_TRAMITE"}]
        archived = [r for r in mine if (r.status or "NUEVA").upper() in {"CONVERTIDA", "DESCARTADA"}]
        artists = s.query(Artist).order_by(Artist.name.asc()).all()
        # PROMOCIÓN es además la sección donde viven las promociones de prensa (entrevistas y
        # planes): la bandeja de peticiones es solo su primera pestaña.
        promo_active, promo_archived = [], []
        if dept_key == "PROMO":
            promo_rows = (s.query(Promotion).options(joinedload(Promotion.company))
                          .filter(func.upper(func.coalesce(Promotion.kind, 'MARKETING')) == PROMO_KIND)
                          .order_by(Promotion.starts_on.desc().nullslast(), Promotion.created_at.desc())
                          .limit(400).all())
            counts = _promo_activity_counts(s, [r.id for r in promo_rows])
            # Fechas y sujeto de cada promoción: la lista va de la MÁS PRÓXIMA en adelante y se puede
            # ver agrupada por artista / gira / evento / festival.
            fechas = _promo_dates_map(s, [r.id for r in promo_rows])
            for row in promo_rows:
                info = counts.get(str(row.id)) or {}
                item = _promo_display(row, activity_count=info.get("total", 0), pending_count=info.get("pending", 0))
                item.update(_promo_sort_and_subject(row, fechas.get(str(row.id)) or []))
                (promo_archived if item["archived"] else promo_active).append(item)
            promo_active.sort(key=lambda x: (x["sort_key"], (x.get("title") or "").casefold()))
            promo_archived.sort(key=lambda x: (x["sort_key"], (x.get("title") or "").casefold()))
        # Rejilla por SUJETO (artista, gira, evento, festival…) con promociones activas, y el
        # filtrado cuando se ha entrado en uno.
        promo_subjects, promo_subject_label, promo_subject_photo = [], "", ""
        if dept_key == "PROMO":
            vistos = {}
            for item in promo_active:
                clave = item.get("group_id") or ""
                if not clave:
                    continue
                ficha = vistos.setdefault(clave, {"id": clave, "kind": item.get("group_kind") or "",
                                                  "label": item.get("group_label") or "—",
                                                  "photo": item.get("group_photo") or "", "count": 0})
                ficha["count"] += 1
                if not ficha["photo"] and item.get("group_photo"):
                    ficha["photo"] = item["group_photo"]
            promo_subjects = sorted(vistos.values(), key=lambda x: (x["label"] or "").casefold())
            if promo_sujeto:
                promo_active = [x for x in promo_active if (x.get("group_id") or "") == promo_sujeto]
                promo_archived = [x for x in promo_archived if (x.get("group_id") or "") == promo_sujeto]
                _ficha = vistos.get(promo_sujeto) or {}
                promo_subject_label = _ficha.get("label") or ""
                promo_subject_photo = _ficha.get("photo") or ""
        return render_template(
            "department_inbox.html",
            dept_key=dept_key,
            promo_vista=promo_vista,
            promo_sujeto=promo_sujeto,
            promo_subjects=promo_subjects,
            promo_subject_label=promo_subject_label,
            promo_subject_photo=promo_subject_photo,
            title=title,
            icon=icon,
            subtitle=subtitle,
            pending_rows=[_booking_request_row(r) for r in pending],
            archived_rows=[_booking_request_row(r) for r in archived],
            booking_status_meta=BOOKING_STATUS_META,
            artists=artists,
            # Promoción lleva además el botón de MARKETING (campañas de pago, otra sección) y el
            # asistente propio de «+ Promoción».
            promotion_creator_datasets=(_promotion_creator_datasets(s) if dept_key == "PROMO" else {}),
            can_edit_promocion=(can_edit_marketing() if dept_key == "PROMO" else False),
            promo_tab=promo_tab,
            promo_active=promo_active,
            promo_archived=promo_archived,
            # Los asistentes de PEDIR promoción o marketing salen en todas las bandejas: pedirlos lo
            # puede hacer cualquiera, no solo quien lleva la sección.
            promo_creator_datasets=_promo_creator_datasets(s),
            promo_modalities=PROMO_MODALITIES,
            promo_formations=PROMO_FORMATIONS,
            promoter_cost_items=PROMOTER_COST_ITEMS,
            # ⚠️ El asistente de promoción se incluye en TODAS las bandejas (pedir promoción lo
            # puede hacer cualquiera): si estos datos solo se pasaran en la de Promoción, al marcar
            # «requiere logística» la lista de producción saldría VACÍA (bug real).
            production_people=_production_people(s),
            office_people=_promo_office_people(s),
            can_edit_promo=(can_edit_promo() if dept_key == "PROMO" else False),
        )
    finally:
        s.close()


@app.get("/promocion-peticiones", endpoint="promo_view")
@admin_required
def promo_view():
    # Una sola pantalla: las PETICIONES son un módulo arriba (solo si las hay) y debajo las
    # promociones activas, de la más próxima en adelante. `?archivadas=1` enseña las archivadas y
    # `?vista=sujetos` la rejilla por artista / gira / evento / festival.
    tab = (request.args.get("tab") or "activas").strip().lower()
    if _truthy(request.args.get("archivadas")):
        tab = "archivadas"
    if tab not in {"activas", "archivadas"}:
        tab = "activas"
    return _render_department_inbox(
        "PROMO", "Promoción", "fa-microphone-lines",
        "Entrevistas, junts de prensa y phoners: las promociones y las peticiones que llegan.",
        promo_tab=tab,
        promo_vista=("sujetos" if (request.args.get("vista") or "").strip().lower() == "sujetos" else "lista"),
        promo_sujeto=(request.args.get("sujeto") or "").strip(),
    )


