def _current_user_peticion_departments():
    """Departamentos de peticiones que ve el usuario actual (según sus accesos)."""
    depts = set()
    try:
        if has_access_key("contratacion", include_descendants=True):
            depts.add("CONTRATACION")
        if has_access_key("discografica", include_descendants=True):
            depts.add("SELLO")
        if has_access_key("promo", include_descendants=True):
            depts.add("PROMO")
        if has_access_key("diseno", include_descendants=True):
            depts.add("DISENO")
    except Exception:
        pass
    return depts


def _home_produccion_pending(limit=12):
    """Tareas pendientes · Producción: actividades CONFIRMADAS (futuras) de los artistas
    asignados al usuario (faceta producción) cuya producción aún no ha arrancado (sin bolsa).
    Dirección y usuarios sin artistas asignados ven todas."""
    uid = session.get("user_id")
    if not uid:
        return []
    s = db()
    try:
        assigned = []
        if not is_master():
            prof = s.query(UserProfile).filter(UserProfile.user_id == to_uuid(uid)).first()
            assigned = [x for x in ((getattr(prof, "assigned_artist_ids_produccion", None) or []) or (getattr(prof, "assigned_artist_ids", None) or [])) if x]
        q = (s.query(Concert)
             .options(joinedload(Concert.artist), joinedload(Concert.venue))
             .filter(func.upper(func.coalesce(Concert.status, '')) == 'CONFIRMADO')
             .filter(Concert.date >= today_local()))
        if not is_master():
            # ⚠️ LO SUYO, no lo de todo el departamento: las actividades que le han ASIGNADO
            # (`production_owner_user_id`) y las de SUS artistas. Antes, quien no tenía artistas
            # asignados veía TODAS, así que el módulo era el trabajo de otros.
            assigned_uuids = [x for x in (to_uuid(a) for a in assigned) if x]
            condiciones = [Concert.production_owner_user_id == to_uuid(uid)]
            if assigned_uuids:
                condiciones.append(Concert.artist_id.in_(assigned_uuids))
            q = q.filter(or_(*condiciones))
        rows = q.order_by(Concert.date.asc()).limit(60).all()
        # Solo las que NO tienen bolsa abierta (producción sin arrancar).
        out = []
        for c in rows:
            # Las fechas de gira comprada que NO promueve una empresa del grupo no generan aviso de
            # producción (mismo criterio que `_ensure_production_request_for_concert` y el listado).
            if not _concert_needs_production(c, s):
                continue
            has_bag = (s.query(WorkflowBag.id)
                       .filter(WorkflowBag.linked_type.in_(("CONCERT", "concert")), WorkflowBag.linked_id == c.id)
                       .first()) is not None
            if has_bag:
                continue
            out.append({
                "id": str(c.id),
                "artist_name": (c.artist.name if c.artist else ""),
                "artist_photo": ((c.artist.photo_url or "") if c.artist else ""),
                "date_label": c.date.strftime("%d/%m/%Y") if c.date else "",
                "venue": (c.venue.name if c.venue else (c.manual_venue_name or c.manual_municipality or "")),
                "activity_label": QUAD_ACTIVITY_LABELS.get((c.activity_type or '').strip().upper(), 'Concierto'),
                "url": url_for("concert_detail_view", cid=c.id, tab="produccion"),
            })
            if len(out) >= limit:
                break
        # Promociones de prensa que piden producción: le tocan a quien se le encargó (y dirección o
        # quien no tiene reparto las ve todas), igual que el resto del módulo.
        promo_q = (s.query(Promotion)
                   .filter(func.upper(func.coalesce(Promotion.kind, 'MARKETING')) == PROMO_KIND)
                   .filter(Promotion.production_needed.is_(True))
                   .filter(func.upper(func.coalesce(Promotion.status, 'ACTIVE')) == 'ACTIVE'))
        if not is_master():
            promo_q = promo_q.filter(or_(Promotion.production_owner_user_id == to_uuid(uid),
                                         Promotion.production_owner_user_id.is_(None)))
        for promo in promo_q.order_by(Promotion.starts_on.asc().nullslast()).limit(30).all():
            if len(out) >= limit:
                break
            request_row = s.get(ProductionRequest, promo.production_request_id) if promo.production_request_id else None
            if request_row is not None and (getattr(request_row, "status", "") or "").upper() not in {"REQUESTED", "APPROVED"}:
                continue
            artists = _artists_from_ids(s, _promotion_normalized_artist_ids(getattr(promo, "artist_ids", None) or []))
            when = getattr(promo, "starts_on", None) or getattr(promo, "target_date", None)
            out.append({
                "id": str(promo.id),
                "artist_name": _artist_label_from_rows(artists),
                "artist_photo": ((getattr(artists[0], "photo_url", None) or "") if artists else ""),
                "date_label": when.strftime("%d/%m/%Y") if when else "",
                "venue": _promo_title(promo),
                "activity_label": "Promoción",
                "url": url_for("promo_detail_view", promotion_id=promo.id),
            })
        return out
    except Exception:
        return []
    finally:
        s.close()


def _home_pending_peticiones(limit=12):
    """Peticiones abiertas (pendientes/negociando) de los departamentos del usuario, para el
    módulo de Inicio. Añade días transcurridos desde que se solicitó y sus departamentos."""
    depts = _current_user_peticion_departments()
    if not depts:
        return []
    s = db()
    try:
        rows = (
            s.query(BookingRequest)
            .options(joinedload(BookingRequest.artist))
            .filter(func.upper(func.coalesce(BookingRequest.status, "NUEVA")).in_(list(BOOKING_OPEN_STATUSES)))
            .order_by(BookingRequest.received_at.desc().nullslast(), BookingRequest.created_at.desc())
            .limit(200)
            .all()
        )
        today = today_local()
        dept_labels = {"CONTRATACION": "Contratación", "SELLO": "Sello", "PROMO": "Promoción", "DISENO": "Diseño"}
        out = []
        for r in rows:
            if not any(_booking_in_department(r, d) for d in depts):
                continue
            row = _booking_request_row(r)
            base = getattr(r, "received_at", None) or getattr(r, "created_at", None)
            days = None
            if base:
                try:
                    days = (today - base.date()).days
                except Exception:
                    days = None
            row["days_since"] = days
            pay = r.payload if isinstance(r.payload, dict) else {}
            _pet_depts = [str(d).strip().upper() for d in (pay.get("departments") or ["CONTRATACION"])]
            row["dept_labels"] = [dept_labels.get(d, d) for d in _pet_depts]
            # Al pinchar se abre la FICHA de la petición: allí están los datos disponibles y las
            # acciones (cerrarla con su motivo o convertirla en la actividad que toque).
            row["manage_url"] = url_for("booking_request_detail_view", rid=r.id)
            out.append(row)
            if len(out) >= limit:
                break
        return out
    finally:
        s.close()


# ================= GIRAS COMPRADAS · CICLOS / FESTIVALES (entidades operativas) =================
# Agrupan conciertos reales por FK (Concert.purchased_tour_id / cycle_festival_id). Ficha estilo
# simulación: Resumen + Producción general (adelanto prorrateado + gastos generales) + Fechas (o
# Artistas en festival). Economía detallada por fecha vive en la ficha de cada concierto.
CONCERT_STATUS_META = {
    "BORRADOR": ("Borrador", "text-bg-light border text-dark"),
    "HABLADO": ("Hablado", "text-bg-secondary"),
    "RESERVADO": ("Reservado", "text-bg-info text-dark"),
    "CONFIRMADO": ("Confirmado", "text-bg-success"),
}
GROUP_STATUS_META = {
    "ACTIVA": ("Activa", "text-bg-success"), "ACTIVO": ("Activo", "text-bg-success"),
    "ARCHIVADA": ("Archivada", "text-bg-secondary"), "ARCHIVADO": ("Archivado", "text-bg-secondary"),
}


def _concert_status_meta(status):
    return CONCERT_STATUS_META.get((status or "BORRADOR").upper(), ("Borrador", "text-bg-light border text-dark"))


def _group_status_meta(status):
    return GROUP_STATUS_META.get((status or "").upper(), ((status or "—"), "text-bg-light border text-dark"))


def _group_general(group):
    """Normaliza el bloque «Producción general» del payload del grupo."""
    p = dict(group.payload or {})
    gen = p.get("general") or {}
    items = []
    for it in (gen.get("expenses") or []):
        items.append({"concept": (it.get("concept") or ""), "amount": float(_money_or_zero(it.get("amount")))})
    partners = [{"name": (x.get("name") or ""), "pct": float(_money_or_zero(x.get("pct")))} for x in (gen.get("partners") or []) if (x.get("name") or "").strip()]
    commissioners = [{"name": (x.get("name") or ""), "pct": float(_money_or_zero(x.get("pct")))} for x in (gen.get("commissioners") or []) if (x.get("name") or "").strip()]
    fee_mode = (gen.get("fee_mode") or "ADVANCE").upper()
    return {
        "advance": float(_money_or_zero(gen.get("advance"))),
        "fee_mode": ("FEE_PER_DATE" if fee_mode == "FEE_PER_DATE" else "ADVANCE"),
        "fee_exempt": bool(gen.get("fee_exempt")),
        "expenses": items,
        "notes": (gen.get("notes") or ""),
        "simulation_ids": list(gen.get("simulation_ids") or []),
        "partners": partners,
        "commissioners": commissioners,
    }


def _parse_group_economics(form, gen):
    """Lee del formulario (alta o Producción general) el modo de caché, el exento, los socios y
    los comisionistas de toda la gira/ciclo, y los escribe en el dict `gen` (payload.general)."""
    mode = (form.get("fee_mode") or "ADVANCE").strip().upper()
    gen["fee_mode"] = "FEE_PER_DATE" if mode == "FEE_PER_DATE" else "ADVANCE"
    gen["fee_exempt"] = bool(form.get("fee_exempt"))
    partners = []
    for nm, pc in zip(form.getlist("partner_name"), form.getlist("partner_pct")):
        nm = (nm or "").strip()
        if nm:
            partners.append({"name": nm, "pct": float(_money_or_zero(pc))})
    gen["partners"] = partners
    commissioners = []
    for nm, pc in zip(form.getlist("commissioner_name"), form.getlist("commissioner_pct")):
        nm = (nm or "").strip()
        if nm:
            commissioners.append({"name": nm, "pct": float(_money_or_zero(pc))})
    gen["commissioners"] = commissioners
    return gen


def _apply_group_create_economics(group, form):
    """Persiste en el ALTA la economía de toda la gira/ciclo (adelanto global si el modo es
    ADVANCE, exento, socios y comisionistas) en payload.general."""
    gen = dict((group.payload or {}).get("general") or {})
    if (form.get("fee_mode") or "").strip().upper() == "ADVANCE":
        gen["advance"] = float(_money_or_zero(form.get("fee_amount")))
    _parse_group_economics(form, gen)
    p = dict(group.payload or {})
    p["general"] = gen
    group.payload = p


def _group_general_save(group, form):
    concepts = form.getlist("gen_concept")
    amounts = form.getlist("gen_amount")
    expenses = []
    for c, a in zip(concepts, amounts):
        c = (c or "").strip()
        if not c and not (a or "").strip():
            continue
        expenses.append({"concept": c, "amount": float(_money_or_zero(a))})
    p = dict(group.payload or {})
    gen = dict(p.get("general") or {})
    gen["advance"] = float(_money_or_zero(form.get("advance")))
    gen["expenses"] = expenses
    gen["notes"] = (form.get("notes") or "").strip()
    _parse_group_economics(form, gen)  # fee_mode, fee_exempt, partners, comisionistas
    p["general"] = gen
    group.payload = p


def _group_toggle_sim(group, form):
    """Añade/quita una simulación vinculada al grupo (guardada en payload.general.simulation_ids)."""
    p = dict(group.payload or {})
    gen = dict(p.get("general") or {})
    ids = [str(x) for x in (gen.get("simulation_ids") or [])]
    add = (form.get("simulation_id") or "").strip()
    rem = (form.get("remove_simulation_id") or "").strip()
    if add and add not in ids:
        ids.append(add)
    if rem and rem in ids:
        ids.remove(rem)
    gen["simulation_ids"] = ids
    p["general"] = gen
    group.payload = p


def _group_linked_sims(s, general):
    out = []
    for sid in (general.get("simulation_ids") or []):
        try:
            sim = s.get(Simulation, to_uuid(sid))
        except Exception:
            sim = None
        if sim:
            out.append({
                "id": str(sim.id), "kind": (sim.kind or ""),
                "title": (sim.title or (sim.artist.name if sim.artist else (sim.event.name if sim.event else "Simulación"))),
            })
    return out


def _wizard_group_options(s):
    """Giras compradas + ciclos/festivales ACTIVOS para el paso del asistente de concierto."""
    tours = [
        {"id": str(t.id), "name": t.name, "logo": (t.logo_url or ""), "artist_id": (str(t.artist_id) if t.artist_id else "")}
        for t in s.query(PurchasedTour).filter(func.upper(func.coalesce(PurchasedTour.status, "ACTIVA")) == "ACTIVA").order_by(PurchasedTour.created_at.desc()).limit(100).all()
    ]
    # La etiqueta sale del catálogo: con el ternario de antes, la gira de un evento salía «Ciclo».
    cycles = [
        {"id": str(cf.id), "name": cf.name, "logo": (cf.logo_url or ""),
         "event_id": (str(cf.event_id) if cf.event_id else ""),
         "kind_label": CYCLE_FESTIVAL_KIND_LABELS.get((cf.kind or "FESTIVAL").upper(), "Ciclo")}
        for cf in s.query(CycleFestival).filter(func.upper(func.coalesce(CycleFestival.status, "ACTIVO")) == "ACTIVO").order_by(CycleFestival.created_at.desc()).limit(100).all()
    ]
    return tours, cycles


def _concert_wizard_context(session_db):
    """Contexto que necesita el asistente de concierto (_concert_wizard_modal.html) para poder
    incluirlo en CUALQUIER página (Inicio, ficha de artista…) y abrirlo in situ, sin navegar a
    /conciertos. El recinto es un Select2 AJAX autocontenido y `activity_options` se define en la
    propia plantilla, así que solo hacen falta estas listas (mismas que usa `contratacion`)."""
    promoters = (
        session_db.query(Promoter).options(selectinload(Promoter.companies))
        .order_by(Promoter.nick.asc()).all()
    )
    tours, cycles = _wizard_group_options(session_db)
    return {
        # El espejo de un EVENTO no es un artista de verdad: el asistente lo elige en su paso de
        # «¿de quién es la actividad?» (artista o evento), así que aquí no debe salir.
        "artists": (session_db.query(Artist).filter(Artist.event_id.is_(None))
                    .order_by(Artist.name.asc()).all()),
        # DISCOGRÁFICAS: los tipos que se despliegan en su tarjeta del paso 1.
        "disc_activity_choices": [(k, QUAD_ACTIVITY_LABELS.get(k, k), QUAD_ACTIVITY_ICONS.get(k, "fa-compact-disc"))
                                  for k in DISCOGRAFICA_ACTIVITY_TYPES],
        # Quién puede llevar la producción (paso de logística de las actividades cortas).
        "production_people_wizard": _production_people(session_db),
        "promoters": promoters,
        "promoters_payload": [
            {
                "id": str(p.id),
                "nick": (p.nick or "").strip(),
                "logo_url": (p.logo_url or "").strip(),
                "companies": [_serialize_promoter_company(x) for x in (p.companies or [])],
            }
            for p in promoters
        ],
        "companies": session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all(),
        "type_choices": [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER],
        "all_concert_tags": _collect_all_concert_tags(session_db),
        "wizard_tours": tours,
        "wizard_cycles": cycles,
    }


def _group_general_roadmap(concerts):
    """Hoja de ruta GENERAL de una gira/ciclo/festival: agrega la agenda (roadmap v2) de todos los
    conciertos vinculados en una vista coordinada de solo lectura, ordenada por día y hora."""
    cat = _roadmap_kind_catalog()
    out = []
    for c in concerts:
        data = _json_loads_safe(getattr(c, "roadmap_payload", None), {})
        if not isinstance(data, dict):
            continue
        clabel = ((c.date.strftime("%d/%m") + " · ") if getattr(c, "date", None) else "") + (
            (c.venue.name if getattr(c, "venue", None) else None) or (c.artist.name if getattr(c, "artist", None) else None) or "Concierto")
        for it in (data.get("agenda") or []):
            k = (it.get("kind") or "OTROS").upper()
            meta = cat.get(k, {})
            _day = (it.get("day") or "")
            try:
                _day_label = datetime.strptime(_day[:10], "%Y-%m-%d").strftime("%d/%m/%Y") if _day else "Sin fecha"
            except Exception:
                _day_label = _day or "Sin fecha"
            out.append({
                "day": _day, "day_label": _day_label, "time": (it.get("time") or ""), "end_time": (it.get("end_time") or ""),
                "title": (it.get("title") or meta.get("label") or k),
                "kind_label": meta.get("label", k), "icon": meta.get("icon", "fa-circle-dot"), "color": meta.get("color", "#6c757d"),
                "concert_id": str(c.id), "concert_label": clabel,
            })
    out.sort(key=lambda x: (x["day"] or "9999-99-99", x["time"] or "99:99"))
    return out


def _group_result_context(s, concerts, general):
    """Resultado AGREGADO de la gira/ciclo: suma la serie 0–100% de cada concierto (adaptador
    Concert→sim_calc), resta los gastos generales (adelanto + gastos generales) y prepara el
    módulo de socios (sim_partners.js) con los socios de TODA la gira para repartir el resultado."""
    extra_fixed = float(general.get("advance") or 0) + sum((x.get("amount") or 0) for x in (general.get("expenses") or []))
    agg = None
    total_sellable = 0
    for c in concerts:
        try:
            calc = sim_calc.compute(_concert_build_calc_data(s, c))
        except Exception:
            continue
        total_sellable += int(calc["ticketing"]["sellable"] or 0)
        fine = calc.get("series_fine") or []
        if agg is None:
            agg = [{"pct": p.get("pct"), "tickets": 0, "ingresos": 0.0, "gastos": 0.0, "resultado": 0.0, "g": {}, "com": []} for p in fine]
        for i, p in enumerate(fine):
            if i >= len(agg):
                break
            agg[i]["tickets"] += p["tickets"]; agg[i]["ingresos"] += p["ingresos"]
            agg[i]["gastos"] += p["gastos"]; agg[i]["resultado"] += p["resultado"]
    if not agg:
        return None
    comm_pct = sum(float(x.get("pct") or 0) for x in (general.get("commissioners") or [])) / 100.0
    for p in agg:
        p["gastos"] = round(p["gastos"] + extra_fixed, 2)
        p["resultado"] = round(p["resultado"] - extra_fixed, 2)
        # Comisionistas de toda la gira: se llevan su % del resultado positivo (antes del reparto).
        if comm_pct > 0 and p["resultado"] > 0:
            _com = p["resultado"] * comm_pct
            p["gastos"] = round(p["gastos"] + _com, 2)
            p["resultado"] = round(p["resultado"] - _com, 2)
        p["ingresos"] = round(p["ingresos"], 2)
    be_pct = be_tickets = None
    for p in agg:
        if p["resultado"] >= 0:
            be_pct = p["pct"]; be_tickets = p["tickets"]; break
    partners = [{"name": (pr.get("name") or "Socio"), "logo": "", "pct": float(pr.get("pct") or 0),
                 "company_id": "", "promoter_id": "", "label": "", "no_loss": False} for pr in (general.get("partners") or [])]
    module = {"mode": "activity", "labels": SIM_EXPENSE_CATEGORY_LABELS,
              "activities": [{"label": "General", "partners": partners, "commissions": [], "series": agg,
                              "sellable": total_sellable, "break_even_pct": be_pct, "break_even_tickets": be_tickets}]}
    return {"at100": (agg[-1] if agg else {}), "series": agg, "module": module,
            "break_even_pct": be_pct, "break_even_tickets": be_tickets, "sellable": total_sellable, "has_partners": bool(partners)}


def _group_concert_row(c):
    label, badge = _concert_status_meta(c.status)
    _es_concierto = (_activity_kind_key(c.activity_type) or "CONCIERTO") in CONCERT_LIKE_ACTIVITY_TYPES
    _cache_lbl = _activity_cache_label(c.sale_type, c.activity_type)
    _promo_meta = _GROUP_PROMO_META.get(
        (c.sale_type or "").upper(),
        (CONCERT_SALE_TYPE_LABELS.get((c.sale_type or "").upper(), c.sale_type or "—"), "text-bg-light border"))
    return {
        "id": str(c.id),
        "title": (c.festival_name or (c.artist.name if c.artist else "Concierto")),
        "artist_name": (c.artist.name if c.artist else ""),
        "artist_photo": ((c.artist.photo_url or "") if c.artist else ""),
        "artist_id": (str(c.artist_id) if c.artist_id else ""),
        "date": c.date,
        "date_label": (c.date.strftime("%d/%m/%Y") if c.date else "Sin fecha"),
        "venue_name": (c.venue.name if c.venue else (c.manual_venue_name or "")),
        "municipality": (c.venue.municipality if c.venue else (c.manual_municipality or "")),
        "status": (c.status or "BORRADOR").upper(),
        "status_label": label,
        "status_badge": badge,
        "sale_type_label": _sale_type_label(c.sale_type, c.activity_type),
        # «Promovido / Vendido / Participado / Gratuito» habla de conciertos: en una actividad que no
        # lo es se dice si lleva caché, que es lo que significa ahí su `sale_type`.
        "promo_label": (_promo_meta[0] if _es_concierto else (_cache_lbl or "—")),
        "promo_badge": (_promo_meta[1] if _es_concierto else "text-bg-light border"),
    }


# Distingue en las fechas de gira/ciclo: promovido por empresa del grupo vs vendido.
_GROUP_PROMO_META = {
    "EMPRESA": ("Promovido", "text-bg-success"),
    "VENDIDO": ("Vendido", "text-bg-info text-dark"),
    "PARTICIPADOS": ("Participado", "text-bg-warning text-dark"),
    "GRATUITO": ("Gratuito", "text-bg-secondary"),
}


def _group_concert_econ(s, c):
    """Economía @100% de un concierto para la sub-pestaña de fecha/artista (motor sim_calc)."""
    try:
        calc = sim_calc.compute(_concert_build_calc_data(s, c))
        at = calc.get("at_100") or {}
        return {
            "ingresos": float((at.get("ingresos") or {}).get("total", 0.0)),
            "gastos": float((at.get("gastos") or {}).get("total", 0.0)),
            "resultado": float(at.get("resultado", 0.0)),
            "sellable": int(calc["ticketing"]["sellable"] or 0),
        }
    except Exception:
        return {"ingresos": 0.0, "gastos": 0.0, "resultado": 0.0, "sellable": 0}


