@app.post("/contratacion/simulaciones/<sid>/ticketing", endpoint="simulation_ticketing_save")
@admin_required
def simulation_ticketing_save(sid):
    if not can_edit_simulations():
        flash("No tienes permisos para editar la simulación.", "warning")
        return redirect(url_for("simulation_detail_view", sid=sid, tab="ticketing", act=request.form.get("activity_id") or None))
    s = db()
    try:
        sim = (
            s.query(Simulation)
            .options(selectinload(Simulation.activities).selectinload(SimulationActivity.ticket_categories))
            .filter(Simulation.id == _sim_safe_uuid(sid))
            .first()
        )
        if not sim:
            flash("Simulación no encontrada.", "warning")
            return redirect(url_for("contracting_view", section="simulaciones"))
        acts = sorted(sim.activities or [], key=lambda a: a.sort_order or 0)
        activity_id = _sim_safe_uuid(request.form.get("activity_id"))
        act = next((a for a in acts if a.id == activity_id), None) or (acts[0] if acts else None)
        if act is None:
            act = SimulationActivity(simulation_id=sim.id, sort_order=0)
            s.add(act)
            s.flush()
        try:
            data = json.loads(request.form.get("ticketing_json") or "[]")
        except Exception:
            data = []
        if not isinstance(data, list):
            data = []
        # Config fiscal (rueda): IVA entradas / IVA complementos / SGAE (porcentajes).
        try:
            tax = json.loads(request.form.get("tax_json") or "{}")
        except Exception:
            tax = {}
        if isinstance(tax, dict):
            clean_tax = {}
            for k in ("iva_ticket", "iva_extra", "sgae"):
                v = tax.get(k)
                if v not in (None, ""):
                    try:
                        clean_tax[k] = float(v)
                    except Exception:
                        pass
            settings_d = dict(act.settings or {})
            if clean_tax:
                settings_d["tax"] = clean_tax
            else:
                settings_d.pop("tax", None)
            act.settings = settings_d
        # Reemplazo total de las categorías de esta actividad (cascade borra extras).
        for c in list(act.ticket_categories or []):
            s.delete(c)
        s.flush()
        for i, row in enumerate(data):
            if not isinstance(row, dict):
                continue
            zone = str(row.get("zone") or "PISTA").upper()
            if zone not in ("PISTA", "GRADA", "PALCO"):
                zone = "PISTA"
            cat = SimulationTicketCategory(
                activity_id=act.id,
                zone=zone,
                name=(str(row.get("name") or "")).strip(),
                price_net=_sim_d(row.get("price")),
                quantity=_sim_int(row.get("qty")),
                invitations=_sim_int(row.get("inv")),
                sort_order=i,
            )
            s.add(cat)
            s.flush()
            for j, ex in enumerate(row.get("extras") or []):
                if not isinstance(ex, dict):
                    continue
                nm = (str(ex.get("name") or "")).strip()
                if not nm:
                    continue
                s.add(SimulationTicketExtra(
                    category_id=cat.id, name=nm,
                    amount_gross=_sim_d(ex.get("amount")), sort_order=j,
                ))
        # Sincronización opcional con el recinto: actualizar su plantilla (de aquí en adelante).
        # Solo toca el FORMATO PRINCIPAL del recinto (los demás formatos no se pisan).
        if _truthy(request.form.get("apply_to_venue")) and act.venue_id:
            _sm_v = _venue_seatmap_default(s, act.venue_id)
            for vc in _venue_ticket_categories_for(s, act.venue_id, _sm_v):
                s.delete(vc)
            s.flush()
            for i, row in enumerate(data):
                if not isinstance(row, dict):
                    continue
                zone = str(row.get("zone") or "PISTA").upper()
                if zone not in ("PISTA", "GRADA", "PALCO"):
                    zone = "PISTA"
                vcat = VenueTicketCategory(
                    venue_id=act.venue_id, seat_map_id=(_sm_v.id if _sm_v is not None else None), zone=zone,
                    name=str(row.get("name") or "").strip(),
                    quantity=_sim_int(row.get("qty")), invitations=_sim_int(row.get("inv")),
                    sort_order=i,
                )
                s.add(vcat)
                s.flush()
                for j, ex in enumerate(row.get("extras") or []):
                    if not isinstance(ex, dict):
                        continue
                    nm = str(ex.get("name") or "").strip()
                    if not nm:
                        continue
                    s.add(VenueTicketExtra(category_id=vcat.id, name=nm, amount_gross=_sim_d(ex.get("amount")), sort_order=j))
        s.commit()
        flash("Ticketing guardado." + (" Plantilla del recinto actualizada." if _truthy(request.form.get("apply_to_venue")) and act.venue_id else ""), "success")
    except Exception as e:
        s.rollback()
        flash(f"Error guardando el ticketing: {e}", "danger")
    finally:
        s.close()
    return redirect(url_for("simulation_detail_view", sid=sid, tab="ticketing", act=request.form.get("activity_id") or None))


@app.post("/contratacion/simulaciones/<sid>/ingresos", endpoint="simulation_income_save")
@admin_required
def simulation_income_save(sid):
    if not can_edit_simulations():
        flash("No tienes permisos para editar la simulación.", "warning")
        return redirect(url_for("simulation_detail_view", sid=sid, tab="ingresos", act=request.form.get("activity_id") or None))
    s = db()
    try:
        sim = (
            s.query(Simulation)
            .options(selectinload(Simulation.activities).selectinload(SimulationActivity.income_items))
            .filter(Simulation.id == _sim_safe_uuid(sid))
            .first()
        )
        if not sim:
            flash("Simulación no encontrada.", "warning")
            return redirect(url_for("contracting_view", section="simulaciones"))
        acts = sorted(sim.activities or [], key=lambda a: a.sort_order or 0)
        activity_id = _sim_safe_uuid(request.form.get("activity_id"))
        act = next((a for a in acts if a.id == activity_id), None) or (acts[0] if acts else None)
        if act is None:
            act = SimulationActivity(simulation_id=sim.id, sort_order=0)
            s.add(act)
            s.flush()
        for it in list(act.income_items or []):
            s.delete(it)
        s.flush()

        def _add(kind, names, amounts, statuses):
            for i, nm in enumerate(names):
                nm = (nm or "").strip()
                amt = _sim_d(amounts[i]) if i < len(amounts) else Decimal("0")
                if not nm and amt == 0:
                    continue
                st = ((statuses[i] if i < len(statuses) else "") or "ACTIVE").strip().upper()
                if st not in ("ACTIVE", "OMIT", "NA"):
                    st = "ACTIVE"
                s.add(SimulationIncomeItem(
                    activity_id=act.id, kind=kind,
                    name=nm or ("Subvención" if kind == "SUBVENCION" else "Patrocinio"),
                    amount_net=amt, status=st, sort_order=i,
                ))
        _add("SUBVENCION", request.form.getlist("subv_name[]"), request.form.getlist("subv_amount[]"), request.form.getlist("subv_status[]"))
        _add("PATROCINIO", request.form.getlist("patro_name[]"), request.form.getlist("patro_amount[]"), request.form.getlist("patro_status[]"))

        # Omitir / no aplica en las líneas CALCULADAS (ticketing, rebate, barras…): en settings.
        try:
            ov = json.loads(request.form.get("income_overrides_json") or "{}")
        except Exception:
            ov = {}
        if isinstance(ov, dict):
            clean = {
                k: str(v).upper() for k, v in ov.items()
                if str(v).upper() in ("OMIT", "NA")
                and k in ("ticketing", "complementos", "rebate", "barras", "incentivos")
            }
            settings_d = dict(act.settings or {})
            settings_d["income_overrides"] = clean
            act.settings = settings_d
        s.commit()
        _ok, _msg = True, "Ingresos guardados."
        _figs = _sim_live_figures(sim, act)
    except Exception as e:
        s.rollback()
        _ok, _msg, _figs = False, f"Error guardando ingresos: {e}", {}
    finally:
        s.close()
    if request.headers.get("X-Requested-With") == "XMLHttpRequest":
        return jsonify({"ok": _ok, "message": _msg, "figures": _figs})
    flash(_msg, "success" if _ok else "danger")
    return redirect(url_for("simulation_detail_view", sid=sid, tab="ingresos", act=request.form.get("activity_id") or None))


def _sim_cost_common(row):
    """Campos comunes de un coste (caché/comisión) desde el JSON del editor."""
    return dict(
        mode=str(row.get("mode") or "FIXED").upper(),
        amount=_sim_d(row.get("amount")),
        includes_iva=bool(row.get("includes_iva")),
        includes_retention=bool(row.get("includes_retention")),
        retention_exempt=bool(row.get("retention_exempt")),
        var_type=(row.get("var_type") or None),
        var_value=_sim_d(row.get("var_value")),
        var_threshold_type=(row.get("var_threshold_type") or None),
        var_threshold_value=_sim_d(row.get("var_threshold_value")),
        artist_ids=[str(x) for x in (row.get("artist_ids") or []) if x],
    )


def _sim_live_figures(sim, act):
    """Break-even + cifras @100% de una actividad (con prorrateo de generales), para actualizar el
    punto de empate «en tiempo real» tras cada autoguardado de gastos/ingresos. Best-effort."""
    try:
        all_acts = list(sim.activities or [])
        artist_intl_map = {str(a.id): bool(getattr(a, "is_international", False)) for a in all_acts}
        activities = [a for a in all_acts if not getattr(a, "is_shared", False)]
        shared = next((a for a in all_acts if getattr(a, "is_shared", False)), None)
        is_multi = (sim.kind or "").upper() in ("TOUR", "CYCLE", "FESTIVAL")
        general_net = 0.0
        if is_multi and shared is not None:
            general_net = sim_calc.compute(_sim_build_calc_data(sim, shared, artist_intl_map))["at_100"]["gastos"]["total"]
        general_share = (general_net / (len(activities) or 1)) if (is_multi and activities) else 0.0
        prorateo = general_share if (act is not None and not getattr(act, "is_shared", False)) else 0.0
        calc = sim_calc.compute(_sim_build_calc_data(sim, act, artist_intl_map, prorateo=prorateo))
        at = calc.get("at_100") or {}
        return {
            "break_even_tickets": calc.get("break_even_tickets"),
            "break_even_pct": calc.get("break_even_pct"),
            "ingresos": (at.get("ingresos") or {}).get("total"),
            "gastos": (at.get("gastos") or {}).get("total"),
            "resultado": at.get("resultado"),
        }
    except Exception:
        return {}


@app.post("/contratacion/simulaciones/<sid>/gastos", endpoint="simulation_expenses_save")
@admin_required
def simulation_expenses_save(sid):
    if not can_edit_simulations():
        flash("No tienes permisos para editar la simulación.", "warning")
        return redirect(url_for("simulation_detail_view", sid=sid, tab="gastos", act=request.form.get("activity_id") or None))
    s = db()
    try:
        sim = (
            s.query(Simulation)
            .options(
                selectinload(Simulation.activities).selectinload(SimulationActivity.caches),
                selectinload(Simulation.activities).selectinload(SimulationActivity.commissions),
                selectinload(Simulation.activities).selectinload(SimulationActivity.production_items),
            )
            .filter(Simulation.id == _sim_safe_uuid(sid))
            .first()
        )
        if not sim:
            flash("Simulación no encontrada.", "warning")
            return redirect(url_for("contracting_view", section="simulaciones"))
        acts = sorted(sim.activities or [], key=lambda a: a.sort_order or 0)
        activity_id = _sim_safe_uuid(request.form.get("activity_id"))
        act = next((a for a in acts if a.id == activity_id), None) or (acts[0] if acts else None)
        if act is None:
            act = SimulationActivity(simulation_id=sim.id, sort_order=0)
            s.add(act)
            s.flush()

        def _json(field):
            try:
                d = json.loads(request.form.get(field) or "[]")
                return d if isinstance(d, list) else []
            except Exception:
                return []

        for c in list(act.caches or []):
            s.delete(c)
        for c in list(act.commissions or []):
            s.delete(c)
        for p in list(act.production_items or []):
            s.delete(p)
        s.flush()

        for i, row in enumerate(_json("caches_json")):
            if not isinstance(row, dict):
                continue
            s.add(SimulationCache(activity_id=act.id, label=(row.get("label") or None), sort_order=i, **_sim_cost_common(row)))

        for i, row in enumerate(_json("commissions_json")):
            if not isinstance(row, dict):
                continue
            common = _sim_cost_common(row)
            s.add(SimulationCommission(
                activity_id=act.id,
                promoter_id=_sim_safe_uuid(row.get("promoter_id")),
                media_outlet_id=_sim_safe_uuid(row.get("media_outlet_id")),
                name=(row.get("name") or None),
                exempt_amount=_sim_d(row.get("exempt_amount")),
                sort_order=i, **common,
            ))

        production_rows = [r for r in _json("production_json") if isinstance(r, dict)]
        for i, row in enumerate(production_rows):
            s.add(SimulationProductionItem(
                activity_id=act.id, category=_sim_expense_cat(row.get("category")),
                concept=str(row.get("concept") or "").strip(),
                amount_net=_sim_d(row.get("amount_net")),
                quantity=(_sim_d(row.get("quantity")) if row.get("quantity") not in (None, "") else Decimal("1")),
                iva_pct=_sim_d(row.get("iva_pct") if row.get("iva_pct") not in (None, "") else 21),
                includes_iva=bool(row.get("includes_iva")),
                iva_exempt=bool(row.get("iva_exempt")),
                is_variable=bool(row.get("is_variable")),
                var_type=(row.get("var_type") or None),
                var_value=_sim_d(row.get("var_value")),
                var_threshold_type=(row.get("var_threshold_type") or None),
                var_threshold_value=_sim_d(row.get("var_threshold_value")),
                cond_under_tickets=(_sim_d(row.get("cond_under_tickets")) if row.get("cond_under_tickets") not in (None, "") else None),
                sort_order=i,
            ))

        # «Vincular gastos» como PLANTILLA del recinto / artista / evento (con nombre y categorías).
        tpl_msg = ""
        tpl_raw = (request.form.get("template_save_json") or "").strip()
        if tpl_raw:
            try:
                tpl_cfg = json.loads(tpl_raw)
            except Exception:
                tpl_cfg = None
            if isinstance(tpl_cfg, dict) and (tpl_cfg.get("name") or "").strip():
                owner_kind = str(tpl_cfg.get("owner") or "").strip().upper()
                owner_id = None
                if owner_kind == "VENUE":
                    owner_id = act.venue_id
                elif owner_kind == "ARTIST":
                    owner_id = act.artist_id or sim.artist_id
                elif owner_kind == "EVENT":
                    owner_id = sim.event_id
                cats = {_sim_expense_cat(c) for c in (tpl_cfg.get("categories") or [])}
                if owner_id:
                    rows_tpl = [
                        r for r in production_rows
                        if (not cats) or (_sim_expense_cat(r.get("category")) in cats)
                    ]
                    name = str(tpl_cfg.get("name")).strip()
                    tpl = (
                        s.query(ExpenseTemplate)
                        .filter(ExpenseTemplate.owner_type == owner_kind,
                                ExpenseTemplate.owner_id == owner_id,
                                func.lower(ExpenseTemplate.name) == name.lower())
                        .first()
                    )
                    if tpl:
                        for it in list(tpl.items or []):
                            s.delete(it)
                        tpl.updated_at = datetime.utcnow()
                    else:
                        tpl = ExpenseTemplate(owner_type=owner_kind, owner_id=owner_id, name=name)
                        s.add(tpl)
                    s.flush()
                    for j, r in enumerate(rows_tpl):
                        s.add(ExpenseTemplateItem(
                            template_id=tpl.id,
                            category=_sim_expense_cat(r.get("category")),
                            concept=str(r.get("concept") or "").strip(),
                            amount_net=_sim_d(r.get("amount_net")),
                            quantity=(_sim_d(r.get("quantity")) if r.get("quantity") not in (None, "") else Decimal("1")),
                            iva_pct=_sim_d(r.get("iva_pct") if r.get("iva_pct") not in (None, "") else 21),
                            includes_iva=bool(r.get("includes_iva")),
                            iva_exempt=bool(r.get("iva_exempt")),
                            is_variable=bool(r.get("is_variable")),
                            var_type=(r.get("var_type") or None),
                            var_value=_sim_d(r.get("var_value")),
                            var_threshold_type=(r.get("var_threshold_type") or None),
                            var_threshold_value=_sim_d(r.get("var_threshold_value")),
                            cond_under_tickets=(_sim_d(r.get("cond_under_tickets")) if r.get("cond_under_tickets") not in (None, "") else None),
                            sort_order=j,
                        ))
                    tpl_msg = f" Plantilla «{name}» guardada ({len(rows_tpl)} líneas)."
        s.commit()
        _ok, _msg = True, "Gastos guardados." + tpl_msg
        _figs = _sim_live_figures(sim, act)   # break-even recomputado para actualizar en vivo
    except Exception as e:
        s.rollback()
        _ok, _msg, _figs = False, f"Error guardando los gastos: {e}", {}
    finally:
        s.close()
    # Autoguardado / «Vincular presupuesto» van por fetch: responder JSON (sin recargar la página).
    if request.headers.get("X-Requested-With") == "XMLHttpRequest":
        return jsonify({"ok": _ok, "message": _msg, "figures": _figs})
    flash(_msg, "success" if _ok else "danger")
    return redirect(url_for("simulation_detail_view", sid=sid, tab="gastos", act=request.form.get("activity_id") or None))


# ---------- LISTAR / CREAR (Contratación: Conciertos + Facturación) ----------
@app.route("/conciertos", methods=["GET", "POST"], endpoint="concerts_view")
@admin_required
def concerts_page():
    s = db()
    try:
        # Sin los espejos de EVENTO: no son artistas de verdad y sus actividades viven en la pestaña
        # Eventos (el asistente los elige en su propio paso).
        artists = s.query(Artist).filter(Artist.event_id.is_(None)).order_by(Artist.name.asc()).all()
        venues = s.query(Venue).order_by(Venue.name.asc()).all()
        promoters = s.query(Promoter).options(selectinload(Promoter.companies)).order_by(Promoter.nick.asc()).all()
        companies = s.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        all_concert_tags = _collect_all_concert_tags(s)
        type_choices = [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER]

        active_tab = (request.args.get("tab") or "vista").lower()
        # El formulario clásico desaparece: cualquier acceso antiguo a alta vuelve al listado.
        if active_tab == "alta" or active_tab not in ("vista", "facturacion"):
            active_tab = "vista"

        f_artist_ids_raw = request.args.getlist("artist") or []
        f_sale_types_raw = request.args.getlist("type") or []
        f_statuses_raw = request.args.getlist("status") or []
        f_when_raw = request.args.getlist("when") or []
        f_announcements_raw = request.args.getlist('announcement') or []
        f_concert_tags = _dedupe_concert_tags(request.args.getlist("concert_tag") or request.args.getlist("hashtag") or [])

        f_artist_ids = []
        for x in f_artist_ids_raw:
            x = (x or "").strip()
            if not x:
                continue
            try:
                f_artist_ids.append(to_uuid(x))
            except Exception:
                pass

        f_sale_types = [(x or "").strip().upper() for x in f_sale_types_raw if (x or "").strip()]
        f_statuses = [(x or "").strip().upper() for x in f_statuses_raw if (x or "").strip()]
        f_announcements = [(x or '').strip().upper() for x in f_announcements_raw if (x or '').strip()]

        f_when = {(x or "").strip().upper() for x in f_when_raw if (x or "").strip()}
        allowed_when = {"PAST", "FUTURE"}
        f_when = {x for x in f_when if x in allowed_when}
        if not f_when:
            f_when = {"PAST", "FUTURE"} if active_tab == 'facturacion' else {"FUTURE"}

        allowed_sale_types = CONCERT_SALE_TYPES_ALL_SET
        allowed_statuses = {"BORRADOR", "HABLADO", "RESERVADO", "CONFIRMADO"}
        allowed_announcements = {'NO_ANNOUNCE', 'UPCOMING', 'ANNOUNCED', 'NONE'}

        f_sale_types = [x for x in f_sale_types if x in allowed_sale_types]
        f_statuses = [x for x in f_statuses if x in allowed_statuses]
        f_announcements = [x for x in f_announcements if x in allowed_announcements]

        if request.method == "POST":
            try:
                sale_type = (request.form.get("sale_type") or "EMPRESA").strip().upper()
                if sale_type not in allowed_sale_types:
                    sale_type = "EMPRESA"

                venue_raw = (request.form.get("venue_id") or "").strip()
                if not venue_raw:
                    raise ValueError("Debes seleccionar un recinto de la lista (o crearlo desde el botón +).")

                be_val = _parse_optional_positive_int((request.form.get("break_even_ticket") or "").strip())
                promoter_raw = (request.form.get("promoter_id") or "").strip()
                billing_company_raw = (request.form.get("billing_company_id") or "").strip()
                concert_tags = _dedupe_concert_tags(request.form.getlist("concert_tags[]"))

                c = Concert(
                    date=parse_date(request.form.get("date") or ""),
                    festival_name=(request.form.get("festival_name") or "").strip() or None,
                    venue_id=to_uuid(venue_raw),
                    sale_type=sale_type,
                    promoter_id=(to_uuid(promoter_raw) if sale_type in ("VENDIDO", "GRATUITO", "GIRAS_COMPRADAS") and promoter_raw else None),
                    group_company_id=None,
                    billing_company_id=(to_uuid(billing_company_raw) if billing_company_raw else None),
                    artist_id=to_uuid((request.form.get("artist_id") or "").strip()),
                    capacity=int(request.form.get("capacity") or 0),
                    sale_start_date=parse_concert_sale_start_date(request.form.get("sale_start_date"), sale_type),
                    break_even_ticket=(None if sale_type in ("VENDIDO", "GRATUITO") else be_val),
                    sold_out=False,
                    status=_norm_status(request.form.get("status")),
                    hashtags=concert_tags,
                )

                s.add(c)
                s.flush()

                # COMPUERTA del aviso al artista (misma regla que en el asistente: se deja RESERVADA
                # en vez de tirar el alta). Esta ruta ya no tiene pantalla, pero sigue viva.
                if (c.status or "").upper() == "CONFIRMADO" and _concert_notice_gate(s, c, "CONFIRMADO"):
                    c.status = "RESERVADO"
                    flash("La actividad se ha creado como RESERVADA: antes de confirmarla hay que "
                          "avisar al artista desde su ficha.", "warning")

                if sale_type != "VENDIDO":
                    p_rows = _parse_share_rows(
                        request.form.getlist("promoter_share_id[]"),
                        request.form.getlist("promoter_share_pct[]"),
                        request.form.getlist("promoter_share_pct_base[]"),
                        request.form.getlist("promoter_share_amount[]"),
                        request.form.getlist("promoter_share_amount_base[]"),
                    )
                    _replace_concert_promoter_shares(s, c.id, p_rows)

                    g_rows = _parse_share_rows(
                        request.form.getlist("company_share_id[]"),
                        request.form.getlist("company_share_pct[]"),
                        request.form.getlist("company_share_pct_base[]"),
                        request.form.getlist("company_share_amount[]"),
                        request.form.getlist("company_share_amount_base[]"),
                    )
                    _replace_concert_company_shares(s, c.id, g_rows)

                    z_rows = _parse_zone_rows(
                        request.form.getlist("zone_promoter_id[]"),
                        request.form.getlist("zone_commission_mode[]"),
                        request.form.getlist("zone_commission_pct[]"),
                        request.form.getlist("zone_commission_base[]"),
                        request.form.getlist("zone_commission_amount[]"),
                        request.form.getlist("zone_exempt_amount[]"),
                        request.form.getlist("zone_concept[]"),
                    )
                    _replace_concert_zone_agents(s, c.id, z_rows)
                else:
                    _replace_concert_promoter_shares(s, c.id, [])
                    _replace_concert_company_shares(s, c.id, [])
                    _replace_concert_zone_agents(s, c.id, [])

                cache_rows = _parse_cache_rows(
                    request.form.getlist("cache_kind[]"),
                    request.form.getlist("cache_concept[]"),
                    request.form.getlist("cache_amount[]"),
                    request.form.getlist("cache_var_mode[]"),
                    request.form.getlist("cache_var_option[]"),
                    request.form.getlist("cache_from_ticket[]"),
                    request.form.getlist("cache_min_tickets[]"),
                    request.form.getlist("cache_min_revenue[]"),
                    request.form.getlist("cache_pct[]"),
                    request.form.getlist("cache_pct_base[]"),
                    request.form.getlist("cache_ticket_type[]"),
                )
                _replace_concert_caches(s, c.id, cache_rows)

                _add_contracts_from_request(s, c.id)
                _add_concert_notes_from_request(s, c.id)
                _upsert_equipment_from_request(s, c.id)
                _add_equipment_docs_from_request(s, c.id)
                _add_equipment_notes_from_request(s, c.id)

                s.commit()
                flash("Concierto creado.", "success")
                target_when = "PAST" if (c.date and c.date < today_local()) else "FUTURE"
                return redirect(url_for("concerts_view", tab="vista", when=target_when) + f"#concert-{c.id}")

            except Exception as e:
                s.rollback()
                flash(f"Error creando concierto: {e}", "danger")
                return redirect(url_for("concerts_view", tab="vista"))

        q = (
            s.query(Concert)
            .options(
                joinedload(Concert.artist),
                joinedload(Concert.venue),
                joinedload(Concert.promoter),
                joinedload(Concert.promoter_company),
                joinedload(Concert.group_company),
                joinedload(Concert.billing_company),
                selectinload(Concert.promoter_shares).joinedload(ConcertPromoterShare.promoter),
                selectinload(Concert.promoter_shares).joinedload(ConcertPromoterShare.promoter_company),
                selectinload(Concert.company_shares).joinedload(ConcertCompanyShare.company),
                selectinload(Concert.zone_agents).joinedload(ConcertZoneAgent.promoter),
                selectinload(Concert.zone_agents).joinedload(ConcertZoneAgent.promoter_company),
                selectinload(Concert.caches),
                selectinload(Concert.contracts),
                selectinload(Concert.contract_sheet),
                selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets),
                selectinload(Concert.notes),
                selectinload(Concert.equipment),
                selectinload(Concert.equipment_documents),
                selectinload(Concert.equipment_notes),
                selectinload(Concert.ticket_types),
            )
        )

        if active_tab == "vista":
            q = q.filter(
                ~func.upper(func.coalesce(Concert.sale_type, "")).in_(["GIRAS_COMPRADAS", "CADIZ"]),
                # ⚠️ FESTIVAL **NO** se excluye: una actividad de tipo festival es el CONCIERTO del
                # artista DENTRO del festival de otro, así que es un concierto y va en este listado
                # (con su etiqueta «Festival»). Lo que es nuestro festival o ciclo es un
                # `CycleFestival` y vive en su pestaña; sus fechas se enganchan por
                # `cycle_festival_id`, no por el tipo de actividad.
                ~func.upper(func.coalesce(Concert.activity_type, "CONCIERTO")).in_(["GIRA", "EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS"]),
                # Las actividades de un EVENTO viven en su propia pestaña, no aquí.
                Concert.event_id.is_(None),
            )
        if f_artist_ids:
            q = q.filter(Concert.artist_id.in_(f_artist_ids))
        if f_sale_types:
            q = q.filter(Concert.sale_type.in_(f_sale_types))
        if f_statuses:
            q = q.filter(Concert.status.in_(f_statuses))

        today = today_local()
        want_past = "PAST" in f_when
        want_future = "FUTURE" in f_when
        if want_past and not want_future:
            q = q.filter(Concert.date < today)
        elif want_future and not want_past:
            q = q.filter(Concert.date >= today)

        concerts = q.order_by(Concert.date.asc()).all()
        # Quien tiene artistas asignados solo ve los conciertos de SUS artistas (como principal o
        # como co-artista del JSONB); el resto de usuarios —y dirección— ven todos.
        _assigned_set = {str(x) for x in (_current_user_state().get("assigned_artist_ids") or []) if x}
        if _assigned_set and not is_master():
            concerts = [
                c for c in concerts
                if str(getattr(c, "artist_id", "") or "") in _assigned_set
                or any(str(x) in _assigned_set for x in (getattr(c, "artist_ids", None) or []))
            ]
        if f_concert_tags:
            concerts = [c for c in concerts if _concert_matches_any_tag(c, f_concert_tags)]
        if f_announcements:
            concerts = [c for c in concerts if _announcement_state(c, today) in f_announcements]

        for c in concerts:
            setattr(c, "tags_clean", _concert_tags(c))
            setattr(c, "sale_type_label", _sale_type_label(c.sale_type, c.activity_type))
            setattr(c, 'announcement_badge', _announcement_badge(c, today))
            setattr(c, 'announcement_state', _announcement_state(c, today))
            setattr(c, 'contract_sheet_badge', _contract_sheet_badge(getattr(c, 'contract_sheet', None)))
            setattr(c, 'contract_sheet_status', _contract_sheet_status(getattr(c, 'contract_sheet', None)))
            setattr(c, 'location_summary', _concert_location_summary(c))

        # ---------- FACTURACIÓN ----------
        # Filtros propios de la pestaña: estado del pago y empresa del grupo que factura.
        f_pay_status = [(x or '').strip().upper() for x in request.args.getlist('pstatus') if (x or '').strip()]
        f_pay_status = [x for x in f_pay_status if x in BILLING_PAYMENT_STATUSES]
        if not f_pay_status:
            f_pay_status = ['PENDING_INVOICE', 'PENDING_COLLECTION']   # lo que hay por hacer
        f_bill_companies = [x for x in (to_uuid(v) for v in request.args.getlist('bcompany') if (v or '').strip()) if x]

        billing_items = []
        for c in concerts:
            if f_bill_companies and getattr(c, 'billing_company_id', None) not in f_bill_companies:
                continue
            rows = [r for r in _concert_payment_rows(c, pending_only=False) if r['status'] in f_pay_status]
            if not rows:
                continue
            billing_items.append({
                'concert': c,
                'payment_rows': rows,
                'pending_total': sum(float(x.get('amount') or 0) for x in rows if x['status'] != 'COLLECTED'),
                'shown_total': sum(float(x.get('amount') or 0) for x in rows),
                'income_total': _concert_payment_total(c, pending_only=False),
            })
        billing_items.sort(key=lambda item: _concert_billing_sort_key(item['concert'], today))
        billing_groups = _billing_group_by_artist(billing_items)
        billing_year = today.year
        billing_company_totals = _billing_year_by_company(s, billing_year)
        billing_companies = s.query(GroupCompany).order_by(GroupCompany.name.asc()).all()

        sections = {k: [] for k in CONCERTS_SECTION_ORDER}
        for c in concerts:
            sections.setdefault(c.sale_type or "EMPRESA", []).append(c)

        for k in sections:
            sections[k].sort(key=lambda x: (x.date or date.max, x.artist.name if x.artist else ""))

        promoters_payload = [
            {
                'id': str(p.id),
                'nick': (p.nick or '').strip(),
                'logo_url': (p.logo_url or '').strip(),
                'companies': [_serialize_promoter_company(x) for x in (p.companies or [])],
            }
            for p in promoters
        ]

        # --- Vista rediseñada: rejilla de artistas (con nº de conciertos) → detalle por artista/todos ---
        vista_mode = "list"
        artist_groups = []
        drill_artist = None
        show_all = request.args.get("all") == "1"
        type_counts = {}
        if active_tab == "vista":
            count_q = (
                s.query(Concert.artist_id, func.count(Concert.id))
                .filter(
                    ~func.upper(func.coalesce(Concert.sale_type, "")).in_(["GIRAS_COMPRADAS", "CADIZ"]),
                    # Mismo criterio que el listado: las de FESTIVAL son conciertos (ver arriba).
                    ~func.upper(func.coalesce(Concert.activity_type, "CONCIERTO")).in_(["GIRA", "EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS"]),
                    Concert.event_id.is_(None),      # los eventos tienen su pestaña
                )
            )
            # ⚠️ EL NÚMERO DE CADA ARTISTA ES EL DE LO QUE VA A VER AL ENTRAR: se le aplica el MISMO
            # filtro de fechas que al listado (que por defecto enseña solo lo que está por venir).
            # Contando también lo pasado, la tarjeta decía «12 conciertos» y dentro había tres.
            if want_past and not want_future:
                count_q = count_q.filter(Concert.date < today)
            elif want_future and not want_past:
                count_q = count_q.filter(Concert.date >= today)
            count_rows = count_q.group_by(Concert.artist_id).all()
            count_map = {aid: int(n) for aid, n in count_rows}
            for a in artists:
                n = count_map.get(a.id, 0)
                if n <= 0:
                    continue
                if _assigned_set and not is_master() and str(a.id) not in _assigned_set:
                    continue
                artist_groups.append({"artist": a, "count": n})
            artist_groups.sort(key=lambda x: (x["artist"].name or "").lower())
            if len(f_artist_ids) == 1:
                drill_artist = next((a for a in artists if a.id == f_artist_ids[0]), None)
            filters_active = bool(f_sale_types or f_statuses or f_concert_tags or f_announcements or drill_artist or show_all)
            vista_mode = "list" if filters_active else "grid"
            for c in concerts:
                type_counts[c.sale_type] = type_counts.get(c.sale_type, 0) + 1

        _wizard_tours, _wizard_cycles = _wizard_group_options(s)

        # Las peticiones pendientes ya NO se listan aquí: viven en su propia pestaña (la primera de
        # Contratación) y lo que abre esta es el módulo de TAREAS pendientes (`CONTRACTING_TASKS`).
        return render_template(
            "concerts_vista.html" if active_tab == "vista" else "concerts.html",
            active_tab=active_tab,
            booking_status_meta=BOOKING_STATUS_META,
            vista_mode=vista_mode,
            artist_groups=artist_groups,
            drill_artist=drill_artist,
            show_all=show_all,
            type_counts=type_counts,
            wizard_tours=_wizard_tours,
            wizard_cycles=_wizard_cycles,
            artists=artists,
            venues=venues,
            promoters=promoters,
            promoters_payload=promoters_payload,
            companies=companies,
            concerts=concerts,
            billing_items=billing_items,
            billing_groups=billing_groups,
            billing_year=billing_year,
            billing_company_totals=billing_company_totals,
            billing_companies=billing_companies,
            billing_payment_status_choices=BILLING_PAYMENT_STATUS_CHOICES,
            f_pay_status=f_pay_status,
            f_bill_companies=[str(x) for x in f_bill_companies],
            sections=sections,
            order=CONCERTS_SECTION_ORDER,
            titles=CONCERTS_SECTION_TITLE,
            type_choices=type_choices,
            all_concert_tags=all_concert_tags,
            f_concert_tags=f_concert_tags,
            f_artist_ids=[str(x) for x in f_artist_ids],
            f_sale_types=f_sale_types,
            f_statuses=f_statuses,
            f_when=sorted(list(f_when)),
            f_announcements=f_announcements,
        )
    finally:
        s.close()




# ---------- FICHA CONCIERTO ----------
@app.get("/conciertos/<cid>", endpoint="concert_detail_view")
@admin_required
def concert_detail_view(cid):
    session = db()
    try:
        c = (
            session.query(Concert)
            .options(
                joinedload(Concert.artist),
                joinedload(Concert.venue),
                joinedload(Concert.promoter),
                joinedload(Concert.promoter_company),
                joinedload(Concert.group_company),
                joinedload(Concert.billing_company),
                selectinload(Concert.promoter_shares).joinedload(ConcertPromoterShare.promoter),
                selectinload(Concert.promoter_shares).joinedload(ConcertPromoterShare.promoter_company),
                selectinload(Concert.company_shares).joinedload(ConcertCompanyShare.company),
                selectinload(Concert.zone_agents).joinedload(ConcertZoneAgent.promoter),
                selectinload(Concert.zone_agents).joinedload(ConcertZoneAgent.promoter_company),
                selectinload(Concert.caches),
                selectinload(Concert.contracts),
                selectinload(Concert.contract_sheet),
                selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets),
                selectinload(Concert.notes),
                selectinload(Concert.equipment),
                selectinload(Concert.equipment_documents),
                selectinload(Concert.equipment_notes),
                selectinload(Concert.ticket_types),
                selectinload(Concert.ticketers).joinedload(ConcertTicketer.ticketer),
                joinedload(Concert.sales_config),
            )
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not c:
            flash("Concierto no encontrado.", "warning")
            return redirect(url_for("concerts_view", tab="vista"))

        setattr(c, "tags_clean", _concert_tags(c))
        setattr(c, "sale_type_label", _sale_type_label(c.sale_type, c.activity_type))

        today = today_local()
        totals_map, today_map, last_map, gross_map, gross_today_map = sales_maps_unified(session, today, [c.id])
        capacity_sale = _concert_capacity_from_ticket_types(c)
        sold_total = int(totals_map.get(c.id, 0) or 0)
        sold_today = int(today_map.get(c.id, 0) or 0)
        gross_total = float(gross_map.get(c.id, 0.0) or 0.0)
        gross_today = float(gross_today_map.get(c.id, 0.0) or 0.0)
        sales_pct = round((sold_total * 100.0 / capacity_sale), 1) if capacity_sale else 0.0
        remaining_tickets = max(0, int(capacity_sale or 0) - sold_total)

        sales_cfg = getattr(c, "sales_config", None)
        vat_pct = float(getattr(sales_cfg, "vat_pct", 0) or 0) if sales_cfg else 0.0
        sgae_pct = float(getattr(sales_cfg, "sgae_pct", 0) or 0) if sales_cfg else 0.0
        net_breakdown = _sales_net_breakdown(gross_total, vat_pct, sgae_pct)

        # ⚠️ «ficha» ya NO es una pestaña: la ficha del promotor duplicaba la de contratación y se
        # retiró. Los enlaces antiguos con ?tab=ficha caen a «general», que es donde está la ficha.
        tab = (request.args.get("tab") or "general").strip().lower()
        # ⚠️ Una pestaña NUEVA hay que meterla en esta lista blanca: si no, cae en «general» y su
        # panel no se pinta (sin dar ningún error).
        if tab not in {"inicio", "general", "invitations", "ticketing", "menores", "carteleria",
                       "produccion", "resultado", "promocion", "marketing", "fotos", "repertorio"}:
            tab = "general"

        sheet = c.contract_sheet
        contract_sheet_data = _contract_sheet_prefill(c, sheet) if sheet else {}
        # Siempre calculadas (con {} si aún no hay sheet) para poder previsualizar en la solicitud.
        contract_sheet_sections = _contract_sheet_sections(contract_sheet_data)
        invitation_rows = list(getattr(c, 'invitations_json', None) or [])
        invitation_totals = {
            'artist': sum(int(x.get('artist_qty') or 0) for x in invitation_rows),
            'office': sum(int(x.get('office_qty') or 0) for x in invitation_rows),
        }
        invitation_totals['total'] = invitation_totals['artist'] + invitation_totals['office']
        invitation_open_for_requests = _invitation_event_is_active_for_requests(c) if '_invitation_event_is_active_for_requests' in globals() else True
        try:
            invitation_counts = _invitation_event_counts(session, c)
            invitation_categories_summary = [_invitation_category_payload(cat) for cat in _invitation_get_categories(session, c, ensure_defaults=False)]
        except Exception:
            invitation_counts = {'configured': invitation_totals['total'], 'committed': 0, 'requested': 0, 'result': invitation_totals['total']}
            invitation_categories_summary = []
        invitation_can_manage = False
        invitation_ficha_groups = []
        invitation_guests_commitments = []
        invitation_guests_grouped = []
        if tab in ('invitations', 'ticketing'):
            try:
                invitation_can_manage = _user_can_manage_invitations(c, session_db=session)
                invitation_ficha_groups = _invitation_ficha_overview(session, c, _invitation_get_categories(session, c, ensure_defaults=False))
            except Exception:
                invitation_can_manage = False
                invitation_ficha_groups = []
            # Lista de invitados idéntica a la de gestión de invitaciones (compromisos + peticiones
            # agrupadas por categoría con sus colores), para mostrarla también en actividades pasadas.
            if tab == 'invitations':
                try:
                    invitation_guests_commitments, invitation_guests_grouped = _invitation_ficha_guests(session, c)
                except Exception:
                    invitation_guests_commitments, invitation_guests_grouped = [], []
        # Ticketing: ¿el recinto tiene una plantilla de categorías guardada para precargar?
        venue_saved_ticket_count = 0
        if tab == 'ticketing' and c.venue_id:
            try:
                venue_saved_ticket_count = session.query(VenueTicketCategory).filter(VenueTicketCategory.venue_id == c.venue_id).count()
            except Exception:
                venue_saved_ticket_count = 0
        # FORMATOS del recinto: si tiene más de uno («Formato 360», «Escenario central»…) hay que
        # poder decir cuál usa ESTA actividad, porque de él dependen el casado de las invitaciones,
        # el asignador y el plano en vivo. Con uno solo no se pregunta nada.
        venue_seat_maps = []
        concert_seat_map = None
        if tab == 'ticketing' and c.venue_id:
            try:
                venue_seat_maps = [m for m in _venue_seatmap_all(session, c.venue_id)
                                   if (m.layout_json or {}).get('sections')]
                concert_seat_map = _concert_seatmap(session, c)
            except Exception:
                venue_seat_maps, concert_seat_map = [], None
        # Ticketing: integración Enterticket (informe de venta en tiempo casi real / candidatos).
        et_event = None
        et_ctx = None
        et_buyers = None          # None = sin permiso (databases.buyers); lista = con permiso
        et_buyers_total = 0
        et_candidates = []
        et_venue_map = None
        if tab == 'ticketing':
            try:
                et_event = _et_concert_event(session, c.id)
                if et_event:
                    _et_maybe_sync_event(et_event)  # refresco en segundo plano si está viejo
                    et_ctx = _et_ticketing_context(session, et_event)
                    # Los datos personales de compradores se gatean con su recurso propio.
                    if has_access_key('databases.buyers'):
                        et_buyers = _et_event_buyers(session, et_event)
                        et_buyers_total = (session.query(func.count(BuyerEvent.id))
                                           .filter(BuyerEvent.event_id == et_event.id).scalar() or 0)
                    et_venue_map = _et_venue_map_payload(session, c, et_event)
                elif et_api.enterticket_configured() and _concert_is_group_promoted(session, c):
                    et_candidates = _et_concert_link_candidates(session, c)
            except Exception:
                et_event = None
                et_ctx = None
        # Ticketing: SIN pestaña si el evento es gratuito (entrada FREE o sale_type GRATUITO).
        show_ticketing_tab = not _concert_is_free_event(c)
        # Menores: solo donde promovemos NOSOTROS (es nuestra política de menores la que se aplica).
        show_menores_tab = _concert_is_ours(session, c)
        minor_ctx = _minor_auth_tab_context(session, c) if (show_menores_tab and tab == 'menores') else {}
        # Repertorio: solo conciertos/festivales o actividades donde se marcó que el artista canta.
        show_repertorio_tab = _concert_has_singing(c)
        sale_channels = _concert_sale_channel_rows(c)
        sale_channel_request = session.query(ConcertSaleChannelRequest).filter_by(concert_id=c.id).first()
        sale_seller = _concert_sale_seller(c)
        payment_terms = _concert_payment_rows(c, pending_only=False)
        payment_pending = _concert_payment_total(c, pending_only=True)
        payment_total_configured = _concert_payment_total(c, pending_only=False)

        artwork_request = getattr(c, 'artwork_request', None)
        artwork_needs_refresh = _artwork_request_has_event_changes(artwork_request, c) if artwork_request else False
        if artwork_request:
            artwork_request.needs_refresh = bool(artwork_needs_refresh or getattr(artwork_request, 'needs_refresh', False))
        artwork_assets = list(getattr(artwork_request, 'assets', None) or []) if artwork_request else []
        current_artwork_assets = sorted([x for x in artwork_assets if not bool(getattr(x, 'is_archived', False))], key=lambda x: getattr(x, 'created_at', None) or datetime.min, reverse=True)
        archived_artwork_assets = sorted([x for x in artwork_assets if bool(getattr(x, 'is_archived', False))], key=lambda x: getattr(x, 'archived_at', None) or getattr(x, 'created_at', None) or datetime.min, reverse=True)
        artwork_company_ids = set(str(x) for x in ((artwork_request.group_company_ids if artwork_request else None) or []))
        artwork_ticketer_ids = set(str(x) for x in ((artwork_request.ticketer_ids if artwork_request else None) or []))
        artwork_companies = session.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        artwork_ticketers = session.query(Ticketer).order_by(Ticketer.name.asc()).all()
        artwork_edit = _truthy(request.args.get('edit_artwork'))
        # ENLACE PÚBLICO de la cartelería: es lo que se comparte con el artista y con el promotor
        # (ellos no tienen usuario). Solo se crea el token si de verdad hay carteles aprobados.
        artwork_share_url = ""
        if tab == "carteleria" and _concert_artwork_share_assets(session, c):
            artwork_share_url = _concert_artwork_share_url(session, c)

        promotion_requests_display = []
        promotion_entries_display = []
        promo_entity_rows = []
        promo_spend = {"rows": [], "total": 0}
        promotion_source_snapshot = _promotion_request_snapshot_from_source(session, "CONCERT", c.id)
        if tab in {"promocion", "marketing"}:
            promotion_requests_display = [_promotion_display_request(row) for row in _promotion_entity_requests(session, "CONCERT", c.id)]
            promotion_entries_display = [_promotion_display_promotion(row) for row in _promotion_entity_promotions(session, "CONCERT", c.id)]
            promo_entity_rows = _promo_rows_for_subject(session, "CONCERT", c.id)
            promo_spend = _promo_spend_rows(session, subject_type="CONCERT", subject_id=c.id)

        contracting_general_rows = _concert_contracting_general_rows(session, c)
        promoter_email_suggestions = _concert_promoter_email_suggestions(session, c)
        production_panel = _concert_production_panel(session, c)
        roadmap_ctx = _roadmap_context(session, "concert", c)
        result_ctx = _concert_result_context(session, c) if tab == "resultado" else None
        # Punto de empate (solo donde se enseña: pestaña Resultado): manda lo que puso contratación;
        # si no, los gastos CONSOLIDADOS de la bolsa; y si tampoco, el presupuesto. El aviso salta
        # únicamente cuando el de contratación NO cuadra con el calculado.
        # Carteles de TODA la gira/ciclo/evento al que pertenece la fecha: se ven aquí en su propio
        # módulo, aparte de los carteles de esta fecha.
        grupo_art = {}
        grupos_art = []
        if tab == "carteleria":
            # ⚠️ Puede haber MÁS DE UNA general: la del EVENTO (común a todas sus fechas) y la de su
            # gira o ciclo. Cada una en su módulo, y debajo las de esta fecha.
            for _gk, _gid in _concert_group_refs(c):
                if _gk and _gid:
                    grupos_art.append(_artwork_group_context(session, _gk, _gid))
            grupo_art = grupos_art[0] if grupos_art else {}
        # ACTIVAR LA PRODUCCIÓN = decir QUIÉN de producción se encarga. Hace falta en TODA actividad
        # que va a producción y no tiene responsable: mientras no lo tenga, nadie la está
        # produciendo y le sale como tarea pendiente a quien la creó.
        needs_prod_owner = False
        try:
            needs_prod_owner = _concert_production_pending(c)
        except Exception:
            needs_prod_owner = False
        # Se pregunta SOLA (al entrar o al confirmar) en los casos en los que antes ya se hacía;
        # en el resto se activa con el botón de la cabecera.
        ask_prod_owner = False
        try:
            ask_prod_owner = needs_prod_owner and _concert_needs_production_owner(session, c)
        except Exception:
            ask_prod_owner = False
        break_even_info = None
        if tab == "resultado":
            try:
                break_even_info = _concert_break_even_info(session, c)
            except Exception:
                break_even_info = None
        fotos_ctx = _build_fotos_context(session, "CONCERT", c.id) if tab == "fotos" else None
        setlist_ctx = _build_setlist_context(session, "CONCERT", c.id, concert=c) if tab == "repertorio" else None

        # Listas para la edición inline (solo en la pestaña general).
        edit_artists = edit_venues = edit_promoters = edit_companies = []
        edit_type_choices = []
        all_concert_tags = []
        activity_songs = []
        # El bloque «Actividad» (qué tiene que hacer el artista) se enseña donde el asistente lo
        # pregunta: promocionales, ensayos y discográficas.
        is_promo_activity = _activity_has_performance_detail(c.activity_type)
        if tab == "general" and (is_master() or can_edit_concerts()):
            edit_artists = session.query(Artist).order_by(Artist.name.asc()).all()
            edit_venues = session.query(Venue).order_by(Venue.name.asc()).all()
            edit_promoters = session.query(Promoter).order_by(Promoter.nick.asc()).all()
            edit_companies = session.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
            all_concert_tags = _collect_all_concert_tags(session)
            edit_type_choices = [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER]
            if is_promo_activity:
                try:
                    activity_songs = _repertoire_songs_for_artists(session, [c.artist_id])
                except Exception:
                    activity_songs = []

        # Bolsa INTEGRADA en la pestaña Producción: mismo panel/contexto que /bolsas/<id>.
        bag_panel_ctx = {}
        if tab == "produccion" and production_panel.get("bag"):
            bag_panel_ctx = _bag_panel_context(session, production_panel["bag"])
            bag_panel_ctx.pop("today", None)  # ya lo pasa la ficha
            _bag_artists_catalog = bag_panel_ctx.pop("artists", [])
            _bag_companies_catalog = bag_panel_ctx.pop("companies", [])
            if not edit_artists:
                edit_artists = _bag_artists_catalog
            if not edit_companies:
                edit_companies = _bag_companies_catalog
        session.commit()

        # A quién se le ha comunicado ya la actividad (para el pop-up de «Eliminar actividad»).
        _notified = _concert_notified_parties(session, c)

        return render_template(
            "concert_detail.html",
            concert=c,
            tab=tab,
            setlist=setlist_ctx,
            today=today,
            capacity_sale=capacity_sale,
            sold_total=sold_total,
            sold_today=sold_today,
            gross_total=gross_total,
            gross_today=gross_today,
            sales_pct=sales_pct,
            remaining_tickets=remaining_tickets,
            last_sales_day=last_map.get(c.id),
            net_breakdown=net_breakdown,
            sale_type_label=_sale_type_label(c.sale_type, c.activity_type),
            announcement_badge=_announcement_badge(c, today),
            contract_sheet_badge=_contract_sheet_badge(sheet),
            contract_sheet_status=_contract_sheet_status(sheet),
            contract_sheet_data=contract_sheet_data,
            contract_sheet_sections=contract_sheet_sections,
            # ¿El promotor ha cumplimentado la ficha y todavía no se ha revisado? Entonces sale el
            # aviso amarillo con el botón de comparar sus datos con los nuestros.
            promoter_sheet_pending=bool(sheet is not None
                                        and (getattr(sheet, 'promoter_data', None) or {})
                                        and not getattr(sheet, 'promoter_reviewed_at', None)),
            invitation_rows=invitation_rows,
            invitation_totals=invitation_totals,
            invitation_counts=invitation_counts,
            invitation_categories_summary=invitation_categories_summary,
            invitation_group_promoted=_concert_is_group_promoted(session, c),
            invitation_open_for_requests=invitation_open_for_requests,
            invitation_can_manage=invitation_can_manage,
            invitation_ficha_groups=invitation_ficha_groups,
            invitation_guests_commitments=invitation_guests_commitments,
            invitation_guests_grouped=invitation_guests_grouped,
            category_types=INVITATION_CATEGORY_TYPES,
            guest_list_modes=INVITATION_GUEST_LIST_MODES,
            payment_terms=payment_terms,
            payment_pending=payment_pending,
            payment_total_configured=payment_total_configured,
            concert_contacts=_concert_contact_rows(c),
            concert_contacts_selected=_concert_contacts_selected_map(c),
            artwork_request=artwork_request,
            artwork_badge=_artwork_request_badge(artwork_request, c),
            artwork_assets=artwork_assets,
            current_artwork_assets=current_artwork_assets,
            archived_artwork_assets=archived_artwork_assets,
            artwork_companies=artwork_companies,
            artwork_ticketers=artwork_ticketers,
            artwork_company_ids=artwork_company_ids,
            artwork_ticketer_ids=artwork_ticketer_ids,
            artwork_needs_refresh=artwork_needs_refresh,
            artwork_edit=artwork_edit,
            location_summary=_concert_location_summary(c),
            artwork_upload_url=_external_url_for('concert_artwork_public_upload', token=artwork_request.public_token) if artwork_request else None,
            artwork_share_url=artwork_share_url,
            promotion_requests_display=promotion_requests_display,
            promotion_entries_display=promotion_entries_display,
            promo_entity_rows=promo_entity_rows,
            promo_spend=promo_spend,
            promotion_source_type="CONCERT",
            promotion_source_id=str(c.id),
            promotion_source_snapshot=promotion_source_snapshot,
            contracting_general_rows=contracting_general_rows,
            promoter_email_suggestions=promoter_email_suggestions,
            production_panel=production_panel,
            roadmap_ctx=roadmap_ctx,
            break_even_info=break_even_info,
            needs_production_owner=needs_prod_owner,
            ask_production_owner=ask_prod_owner,
            # AVISO AL ARTISTA: si está avisado (y sigue valiendo), la barra enseña la etiqueta
            # «Notificado» con a quién y cuándo; si no, el botón para avisarle.
            artist_notice=_concert_notice_state(session, c),
            # FASES de la petición de la que salió (si salió de una): confirmar con el artista y
            # confirmar al promotor, en ese orden. Las otras dos ya tienen su botón en la barra.
            peticion_phases=_concert_peticion_phases(session, c),
            # PESTAÑA «INICIO»: las tareas de la actividad paso a paso (solo se calcula en su
            # pestaña; recorre el estado de la actividad y de su petición).
            task_board=(_concert_task_board(session, c) if tab == "inicio" else None),
            # SALIDA A LA VENTA: activar la venta (contratación) y comunicarla (ticketing) son dos
            # funciones distintas de la producción, cada una con su botón.
            sale_state=_concert_sale_state(session, c),
            # ELIMINAR LA ACTIVIDAD (rueda de la cabecera): a quién se le había comunicado ya, para
            # poder avisar de la cancelación antes de borrarla.
            notified_parties=_notified,
            # ¿Se le puede mandar el aviso de cancelación? Si a quien lo sabe no le consta un correo
            # (p. ej. solo estaba «marcado a mano»), no se ofrece un botón que no podría enviar nada.
            notified_can_email=any("@" in (p.get("email") or "") for p in _notified),
            concert_delete_word=CONCERT_DELETE_WORD,
            # ⚠️ SIEMPRE, no solo cuando falta responsable: el selector también sirve para CAMBIARLO
            # (rueda de la cabecera), y si la lista llegaba vacía no salía nadie que elegir.
            production_people=_production_people(session),
            production_owner_name=_concert_production_owner_name(session, c),
            **grupo_art,
            # Todas las cartelerías GENERALES que le tocan a esta fecha (evento, gira, ciclo): una
            # puede tener varias, y cada una se pinta en su módulo.
            artwork_groups=grupos_art,
            result_calc=(result_ctx["calc"] if result_ctx else None),
            result_module=(result_ctx["module"] if result_ctx else None),
            result_et_income=(result_ctx.get("et_income") if result_ctx else False),
            venue_saved_ticket_count=venue_saved_ticket_count,
            venue_seat_maps=venue_seat_maps,
            concert_seat_map=concert_seat_map,
            show_ticketing_tab=show_ticketing_tab,
            show_menores_tab=show_menores_tab,
            **minor_ctx,
            show_repertorio_tab=show_repertorio_tab,
            sale_channels=sale_channels,
            sale_channel_request=sale_channel_request,
            sale_seller=sale_seller,
            all_ticketers=(session.query(Ticketer).order_by(Ticketer.name.asc()).all() if tab == 'ticketing' else []),
            can_validate_artwork=_can_validate_artwork(),
            invitation_header_counts=(_invitation_ficha_header_counts(session, c) if tab == 'invitations' else None),
            et_event=et_event,
            et_ctx=et_ctx,
            et_buyers=et_buyers,
            et_buyers_total=et_buyers_total,
            et_candidates=et_candidates,
            et_venue_map=et_venue_map,
            fotos_ctx=fotos_ctx,
            artists=edit_artists,
            venues=edit_venues,
            companies=edit_companies,
            promoters=edit_promoters,
            type_choices=edit_type_choices,
            all_concert_tags=all_concert_tags,
            is_promo_activity=is_promo_activity,
            activity_type_label=_activity_kind_label(c.activity_type),
            # En una actividad que no es un concierto, el tipo de venta solo dice si lleva caché.
            activity_cache_label=_activity_cache_label(c.sale_type, c.activity_type),
            is_concert_like=(_activity_kind_key(c.activity_type) in CONCERT_LIKE_ACTIVITY_TYPES
                             or not (c.activity_type or '').strip()),
            activity_songs=activity_songs,
            entradas_ticket_rows=_concert_entradas_ticket_rows(c),
            promoter_costs_rows=_promoter_costs_rows(getattr(c, "promoter_costs_payload", None)),
            artwork_requested_format_labels=_artwork_requested_format_labels(artwork_request) if artwork_request else [],
            # ¿Promueve el evento una empresa del grupo? (decide si se enseña el «compartido con el promotor»)
            artwork_group_promoted=_concert_is_group_promoted(session, c),
            bag_embed=True,
            **bag_panel_ctx,
        )
    finally:
        session.close()



@app.post('/conciertos/<cid>/carteleria/guardar', endpoint='concert_artwork_save')
@admin_required
def concert_artwork_save(cid):
    if not (is_master() or can_edit_concerts()):
        return forbid('Tu usuario no tiene permisos para gestionar cartelería.')
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(
                joinedload(Concert.artist),
                joinedload(Concert.venue),
                joinedload(Concert.billing_company),
                selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets),
            )
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not concert:
            flash('Concierto no encontrado.', 'warning')
            return redirect(url_for('concerts_view', tab='vista'))

        handled_by = (request.form.get('handled_by') or 'OURS').strip().upper()
        if handled_by not in {'OURS', 'PROMOTER'}:
            handled_by = 'OURS'

        row = getattr(concert, 'artwork_request', None)
        if not row:
            row = ConcertArtworkRequest(concert_id=concert.id, public_token=uuid.uuid4().hex)
            session.add(row)
            session.flush()

        now = datetime.now(ZoneInfo('Europe/Madrid'))
        was_requested = bool(getattr(row, 'requested_at', None) or getattr(row, 'uploaded_at', None))
        force_resend = _truthy(request.form.get('force_resend'))
        row.handled_by = handled_by
        row.updated_at = now

        if handled_by == 'PROMOTER':
            row.status = 'PROMOTER'
            row.logo_notes = None
            row.ticketer_notes = None
            row.other_notes = None
            row.delivery_deadline = None
            row.group_company_ids = []
            row.ticketer_ids = []
            row.event_snapshot = _concert_artwork_snapshot(concert)
            row.needs_refresh = False
            session.commit()
            flash('Cartelería configurada: la realiza el promotor.', 'success')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))

        row.group_company_ids = _parse_uuid_list(request.form.getlist('group_company_ids[]'))
        row.ticketer_ids = _parse_uuid_list(request.form.getlist('ticketer_ids[]'))
        row.requested_formats = _parse_artwork_formats(request.form)
        _vid = _parse_artwork_video(request.form)
        row.video_requested = _vid["requested"]
        row.video_notes = _vid["notes"]
        row.video_formats = _vid["formats"]
        row.logo_notes = (request.form.get('logo_notes') or '').strip() or None
        row.ticketer_notes = (request.form.get('ticketer_notes') or '').strip() or None
        row.other_notes = (request.form.get('other_notes') or '').strip() or None
        row.delivery_deadline = parse_optional_date(request.form.get('delivery_deadline'))
        send_as_update = bool(force_resend or was_requested or getattr(row, 'needs_refresh', False) or _artwork_request_has_event_changes(row, concert))
        if send_as_update:
            _archive_current_artwork_assets(row)
        row.status = 'REQUESTED'
        row.requested_at = now
        row.event_snapshot = _concert_artwork_snapshot(concert)
        row.needs_refresh = False
        session.commit()

        ok, error = _send_artwork_request_email(concert, row, is_update=send_as_update)
        if ok:
            flash('Solicitud de cartelería reenviada a grafico@33producciones.es.' if send_as_update else 'Solicitud de cartelería enviada a grafico@33producciones.es.', 'success')
        else:
            flash(f'Cartelería guardada, pero no se pudo enviar el correo automáticamente: {error}', 'warning')
        return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
    except Exception as exc:
        session.rollback()
        flash(f'Error gestionando cartelería: {exc}', 'danger')
        return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
    finally:
        session.close()


@app.route('/carteleria/<token>', methods=['GET', 'POST'], endpoint='concert_artwork_public_upload')
def concert_artwork_public_upload(token):
    session = db()
    try:
        row = (
            session.query(ConcertArtworkRequest)
            .options(selectinload(ConcertArtworkRequest.assets))
            .filter(ConcertArtworkRequest.public_token == token)
            .first()
        )
        if not row:
            return abort(404)
        concert = (
            session.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company))
            .filter(Concert.id == row.concert_id)
            .first()
        )
        if not concert:
            return abort(404)

        all_companies = session.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        all_ticketers = session.query(Ticketer).order_by(Ticketer.name.asc()).all()
        selected_company_ids = set(str(x) for x in (row.group_company_ids or []))
        selected_ticketer_ids = set(str(x) for x in (row.ticketer_ids or []))
        selected_companies = [x for x in all_companies if str(x.id) in selected_company_ids]
        selected_ticketers = [x for x in all_ticketers if str(x.id) in selected_ticketer_ids]

        is_promoter_flow = (row.handled_by or 'OURS').strip().upper() == 'PROMOTER'
        wants_json = _truthy(request.form.get('ajax')) or (request.headers.get('X-Requested-With') == 'XMLHttpRequest')

        if request.method == 'POST':
            labels = request.form.getlist('asset_format[]')
            files = request.files.getlist('asset_file[]')
            widths = request.form.getlist('asset_width[]')
            heights = request.form.getlist('asset_height[]')
            uploaded = 0
            for i, fs in enumerate(files or []):
                if not fs or not getattr(fs, 'filename', ''):
                    continue
                label = (labels[i] if i < len(labels) else '').strip() or Path(fs.filename).stem
                file_url, mime_type, kind = _upload_artwork_file(fs)
                if not file_url:
                    continue
                for existing in list(row.assets or []):
                    if bool(getattr(existing, 'is_archived', False)):
                        continue
                    if (existing.format_label or '').strip().lower() == label.lower():
                        session.delete(existing)
                session.add(ConcertArtworkAsset(
                    artwork_request_id=row.id,
                    format_label=label,
                    file_url=file_url,
                    original_name=fs.filename,
                    mime_type=mime_type,
                    kind=kind,
                    width=_parse_optional_positive_int((widths[i] if i < len(widths) else '') or ''),
                    height=_parse_optional_positive_int((heights[i] if i < len(heights) else '') or ''),
                    # Lo que sube el PROMOTOR queda pendiente de validar por diseño.
                    validation_status='PENDING' if is_promoter_flow else 'APPROVED',
                ))
                uploaded += 1
            if uploaded <= 0:
                if wants_json:
                    return jsonify({'ok': False, 'error': 'Debes subir al menos un archivo de cartelería.'}), 400
                flash('Debes subir al menos un archivo de cartelería.', 'warning')
            else:
                now = datetime.now(ZoneInfo('Europe/Madrid'))
                if is_promoter_flow:
                    # Los archivos quedan subidos; el envío definitivo lo hace el botón «Enviar»
                    # (concert_artwork_public_submit), que avisa a diseño para validar.
                    row.updated_at = now
                else:
                    row.status = 'UPLOADED'
                    row.uploaded_at = now
                    row.updated_at = now
                    row.event_snapshot = _concert_artwork_snapshot(concert)
                    row.needs_refresh = False
                    _artwork_pick_primary_by_squareness(row)
                session.commit()
                if wants_json:
                    return jsonify({'ok': True, 'uploaded': uploaded})
                flash('Cartelería subida correctamente.', 'success')
                return redirect(url_for('concert_artwork_public_upload', token=token))

        return render_template(
            'concert_artwork_public.html',
            concert=concert,
            artwork_request=row,
            artwork_badge=_artwork_request_badge(row, concert),
            selected_companies=selected_companies,
            selected_ticketers=selected_ticketers,
            is_promoter_flow=is_promoter_flow,
            style_guide_url=(os.environ.get('ARTWORK_STYLE_GUIDE_URL') or '').strip(),
            artwork_assets=sorted([x for x in (row.assets or []) if not bool(getattr(x, 'is_archived', False))], key=lambda x: getattr(x, 'created_at', None) or datetime.min, reverse=True),
            upload_action=url_for('concert_artwork_public_upload', token=token),
            submit_action=url_for('concert_artwork_public_submit', token=token),
        )
    finally:
        session.close()


@app.post('/carteleria/<token>/enviar', endpoint='concert_artwork_public_submit')
def concert_artwork_public_submit(token):
    """El promotor pulsa «Enviar» tras subir sus carteles: pasan a REVIEW y se avisa a diseño
    gráfico para que los valide o rechace."""
    session = db()
    try:
        row = (
            session.query(ConcertArtworkRequest)
            .options(selectinload(ConcertArtworkRequest.assets))
            .filter(ConcertArtworkRequest.public_token == token)
            .first()
        )
        if not row:
            return abort(404)
        concert = (
            session.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company))
            .filter(Concert.id == row.concert_id)
            .first()
        )
        if not concert:
            return abort(404)
        pending = [a for a in (row.assets or []) if not a.is_archived and (a.validation_status or 'APPROVED') == 'PENDING']
        if not pending:
            flash('Sube al menos un cartel antes de enviar.', 'warning')
            return redirect(url_for('concert_artwork_public_upload', token=token))
        now = datetime.now(ZoneInfo('Europe/Madrid'))
        row.status = 'REVIEW'
        row.uploaded_at = now
        row.updated_at = now
        row.event_snapshot = _concert_artwork_snapshot(concert)
        row.needs_refresh = False
        session.commit()
        # Alerta a diseño gráfico para validar.
        ficha_url = _external_url_for('concert_detail_view', cid=concert.id, tab='carteleria')
        html_body = (
            '<div style="font-family:Arial,sans-serif;color:#1f2937;max-width:640px;">'
            + _concert_email_header_html(concert, 'Carteles pendientes de validación')
            + f'<p>El promotor ha subido <strong>{len(pending)}</strong> cartel(es). Revísalos y valídalos o recházalos desde la ficha.</p>'
            + f'<p><a href="{ficha_url}" style="display:inline-block;background:#E33D48;color:#fff;padding:12px 18px;border-radius:8px;text-decoration:none;font-weight:700;">Revisar carteles</a></p>'
            + '</div>'
        )
        try:
            _send_optional_email('grafico@33producciones.es', f'Carteles pendientes de validación · {concert.artist.name if concert.artist else "actividad"}', html_body, text_body=ficha_url)
        except Exception:
            pass
        flash('Carteles enviados. Quedan pendientes de validación por nuestro equipo de diseño.', 'success')
        return redirect(url_for('concert_artwork_public_upload', token=token))
    except Exception as exc:
        session.rollback()
        flash(f'Error enviando los carteles: {exc}', 'danger')
        return redirect(url_for('concert_artwork_public_upload', token=token))
    finally:
        session.close()


@app.post('/conciertos/<cid>/carteleria/solicitar-promotor', endpoint='concert_artwork_promoter_request')
@admin_required
def concert_artwork_promoter_request(cid):
    """Solicitar al PROMOTOR que suba los carteles del evento (correo con la cabecera del evento,
    los logos necesarios, la guía de estilo y el botón de subida)."""
    if not (is_master() or can_edit_concerts()):
        return forbid('Tu usuario no tiene permisos para gestionar cartelería.')
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company),
                     selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets))
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        if not concert:
            flash('Concierto no encontrado.', 'warning')
            return redirect(url_for('concerts_view', tab='vista'))
        emails = []
        for raw in request.form.getlist('to_email') + [request.form.get('extra_emails')]:
            for chunk in re.split(r'[;,\n]+', str(raw or '')):
                email = chunk.strip()
                if email and email.lower() not in [x.lower() for x in emails]:
                    emails.append(email)
        if not emails:
            flash('Añade al menos un destinatario para solicitar los carteles.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
        row = getattr(concert, 'artwork_request', None)
        if not row:
            row = ConcertArtworkRequest(concert_id=concert.id, public_token=uuid.uuid4().hex)
            session.add(row)
            session.flush()
        now = datetime.now(ZoneInfo('Europe/Madrid'))
        if _artwork_request_status(row) in ('REVIEW', 'UPLOADED'):
            _archive_current_artwork_assets(row)
        row.handled_by = 'PROMOTER'
        row.status = 'REQUESTED'
        row.recipients_json = emails
        row.group_company_ids = _parse_uuid_list(request.form.getlist('group_company_ids[]'))
        row.requested_formats = _parse_artwork_formats(request.form)
        _vid = _parse_artwork_video(request.form)
        row.video_requested = _vid["requested"]
        row.video_notes = _vid["notes"]
        row.video_formats = _vid["formats"]
        row.logo_notes = (request.form.get('logo_notes') or '').strip() or None
        row.other_notes = (request.form.get('other_notes') or '').strip() or None
        row.delivery_deadline = parse_optional_date(request.form.get('delivery_deadline'))
        row.requested_at = now
        row.updated_at = now
        row.event_snapshot = _concert_artwork_snapshot(concert)
        row.needs_refresh = False
        session.commit()
        ok, error = _send_promoter_artwork_email(concert, row, kind='REQUEST')
        if ok:
            flash('Solicitud de carteles enviada al promotor.', 'success')
        else:
            flash(f'Solicitud registrada, pero el correo no se pudo enviar: {error}', 'warning')
        return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
    except Exception as exc:
        session.rollback()
        flash(f'Error solicitando carteles al promotor: {exc}', 'danger')
        return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
    finally:
        session.close()


def _can_validate_artwork() -> bool:
    """Aprobar carteles es COSA DE DISEÑO (y de dirección). Al resto —contratación incluida— los
    carteles que sube alguien que no es diseño le aparecen como «pendientes de aprobación», sin
    botones para darles el OK."""
    try:
        return bool(is_master() or has_access_key('diseno', include_descendants=True))
    except Exception:
        return False


def _artwork_ensure_request(session_db, concert):
    """La solicitud de cartelería de la actividad (se crea vacía si hace falta, para poder colgar de
    ella los carteles subidos a mano)."""
    row = getattr(concert, 'artwork_request', None)
    if row is None:
        row = ConcertArtworkRequest(concert_id=concert.id, public_token=uuid.uuid4().hex,
                                    handled_by='OURS', status='DRAFT')
        session_db.add(row)
        session_db.flush()
    return row


# ---------------------------------------------------------------------------
#  CARTELERÍA DE TODO UN GRUPO (gira comprada · ciclo/festival · evento)
#  Una sola solicitud para todas sus fechas. Sus carteles se ven además en cada fecha, en un módulo
#  aparte del de la fecha, para que se sepa cuál es cuál. Mismo circuito: subir a mano → aprobación
#  de diseño uno a uno → compartir/descargar.
# ---------------------------------------------------------------------------
# ⚠️ Un EVENTO (el sujeto, `AppEvent`) también tiene cartelería GENERAL: la común de todas sus
# actividades, sea cual sea el contenedor de cada una. Se ve en su ficha y, en cada actividad de ese
# evento, en su pestaña de Cartelería junto a la particular de esa fecha.
ARTWORK_GROUP_KINDS = {"TOUR": "gira", "CYCLE": "ciclo", "EVENT": "evento"}

# QUÉ ES cada pieza de la cartelería de un grupo. Van en la MISMA solicitud (así se reutilizan la
# subida, la aprobación de diseño, las miniaturas de vídeo y el compartir) pero **no se mezclan**:
# cada una tiene su sección en el panel y todo lo que SALE de casa (el ZIP, el enlace público de
# cartelería, el aviso de salida a la venta) es solo `POSTER`.
ARTWORK_ASSET_CATEGORIES = {"POSTER": "Cartel", "LOGO": "Logotipo / imagen de marca"}

# Formatos que se sugieren al subir una pieza de marca (se puede escribir cualquier otro).
ARTWORK_BRAND_FORMATS = [
    "Logo principal", "Logo horizontal", "Logo vertical", "Isotipo / símbolo",
    "Logo en negativo (blanco)", "Logo en negro", "Logo sobre fondo", "Imagen de marca",
    "Cabecera para redes", "Foto de perfil", "Paleta de color", "Tipografías",
    "Manual de marca", "Pack con todos los formatos",
]

# La imagen de marca principal ES la imagen del grupo: se aplica a esta columna, que es la que ya
# pinta toda la app (la cabecera de la ficha, los listados, el one-sheet…).
ARTWORK_GROUP_IMAGE_FIELD = "logo_url"


def _artwork_asset_category(asset) -> str:
    """POSTER | LOGO de una pieza ya guardada (punto único; global de plantilla `artwork_category`).

    ⚠️ Las piezas ANTERIORES a la columna no la traen: todas son carteles (POSTER)."""
    cat = (getattr(asset, "category", "") or "").strip().upper()
    return cat if cat in ARTWORK_ASSET_CATEGORIES else "POSTER"


def _artwork_category_arg(value: str | None) -> str:
    """Normaliza la categoría que llega por formulario o por la URL (por defecto, cartel)."""
    cat = (value or "").strip().upper()
    return cat if cat in ARTWORK_ASSET_CATEGORIES else "POSTER"


def _artwork_group_apply_brand_image(session_db, kind: str, gid, asset) -> bool:
    """La imagen de marca PRINCIPAL pasa a ser **la imagen de la gira/ciclo/evento**.

    Es el mismo patrón que la portada de un proyecto discográfico (`_disco_artwork_apply_to_release`):
    no se guarda un dato paralelo, se escribe el campo donde esa imagen ya vivía (`logo_url`), que es
    el que pinta la cabecera de la ficha, los listados y el one-sheet.
    ⚠️ Solo una IMAGEN puede representar al grupo (`_artwork_can_be_primary`): un .ai o un .zip no.
    """
    grupo, _n = _artwork_group_owner(session_db, kind, gid)
    if grupo is None or asset is None or not _artwork_can_be_primary(asset):
        return False
    url = (getattr(asset, "file_url", "") or "").strip()
    if not url:
        return False
    setattr(grupo, ARTWORK_GROUP_IMAGE_FIELD, url)
    return True


def _artwork_group_owner(session_db, kind: str, gid):
    """(objeto del grupo, etiqueta legible) para TOUR (gira comprada) o CYCLE (ciclo/festival/evento)."""
    k = (kind or "").strip().upper()
    gid = to_uuid(str(gid or "")) or None
    if not gid:
        return None, ""
    if k == "TOUR":
        row = session_db.get(PurchasedTour, gid)
        return row, (getattr(row, "name", "") or "Gira")
    if k == "CYCLE":
        row = session_db.get(CycleFestival, gid)
        etiqueta = CYCLE_FESTIVAL_KIND_LABELS.get((getattr(row, "kind", "") or "").upper(), "Ciclo")
        return row, (getattr(row, "name", "") or etiqueta)
    if k == "EVENT":
        row = session_db.get(AppEvent, gid)
        return row, (getattr(row, "name", "") or "Evento")
    return None, ""


def _artwork_group_sync_brand_image(session_db, kind: str, gid, row, clear_if_empty: bool = False) -> None:
    """Deja la imagen del grupo igual a su pieza de marca PRINCIPAL aprobada.

    Punto único llamado desde los cuatro caminos que la pueden cambiar (subir, aprobar, marcar
    principal y borrar), así que la imagen de la gira y la sección de marca **no se pueden
    desparejar**. Con `clear_if_empty` (al borrar) se limpia si ya no queda ninguna: mejor sin
    imagen que apuntando a un archivo que no existe.
    """
    if row is None:
        return
    principal = None
    for a in (row.assets or []):
        if getattr(a, "is_archived", False) or _artwork_asset_category(a) != "LOGO":
            continue
        if (a.validation_status or "APPROVED") != "APPROVED" or not a.is_primary:
            continue
        if _artwork_can_be_primary(a):
            principal = a
            break
    if principal is not None:
        _artwork_group_apply_brand_image(session_db, kind, gid, principal)
        return
    if clear_if_empty:
        grupo, _n = _artwork_group_owner(session_db, kind, gid)
        if grupo is not None:
            setattr(grupo, ARTWORK_GROUP_IMAGE_FIELD, None)


def _artwork_group_request(session_db, kind: str, gid, create: bool = False):
    """La solicitud de cartelería del grupo (se crea vacía si hace falta)."""
    k = (kind or "").strip().upper()
    gid = to_uuid(str(gid or "")) or None
    if k not in ARTWORK_GROUP_KINDS or not gid:
        return None
    row = (session_db.query(ConcertArtworkRequest)
           .filter(ConcertArtworkRequest.group_kind == k, ConcertArtworkRequest.group_id == gid)
           .first())
    if row is None and create:
        row = ConcertArtworkRequest(concert_id=None, group_kind=k, group_id=gid,
                                    public_token=uuid.uuid4().hex, handled_by="OURS", status="DRAFT")
        session_db.add(row)
        session_db.flush()
    return row


def _artwork_group_assets(session_db, kind: str, gid, only_approved: bool = True,
                          category: str = "POSTER") -> list:
    """Piezas del grupo (por defecto los CARTELES aprobados, que son los que se pueden usar).

    ⚠️ `category` es obligatorio de facto: los carteles y los logotipos viven en la misma solicitud,
    así que sin filtrar se colarían los logos en el ZIP, en el enlace público y en los avisos."""
    row = _artwork_group_request(session_db, kind, gid)
    if row is None:
        return []
    cat = _artwork_category_arg(category)
    salida = []
    for a in (row.assets or []):
        if getattr(a, "is_archived", False):
            continue
        if _artwork_asset_category(a) != cat:
            continue
        if only_approved and (a.validation_status or "APPROVED") != "APPROVED":
            continue
        salida.append(a)
    return sorted(salida, key=lambda x: (not bool(x.is_primary), x.created_at or datetime.min))


def _concert_group_refs(concert) -> list[tuple[str, object]]:
    """TODOS los grupos cuya cartelería GENERAL vale para esta actividad, del más amplio al más
    concreto: su EVENTO (la común de todas sus fechas), su gira comprada y su ciclo/festival.

    ⚠️ Son compatibles: una fecha de un evento puede estar además en un ciclo, y en su pestaña de
    Cartelería se ven las dos generales (cada una en su módulo) más las suyas."""
    salida = []
    if getattr(concert, "event_id", None):
        salida.append(("EVENT", concert.event_id))
    if getattr(concert, "purchased_tour_id", None):
        salida.append(("TOUR", concert.purchased_tour_id))
    if getattr(concert, "cycle_festival_id", None):
        salida.append(("CYCLE", concert.cycle_festival_id))
    return salida


# Del grupo más CONCRETO al más amplio (lo usan la cartelería que se comparte y `_concert_group_ref`).
ARTWORK_GROUP_SHARE_ORDER = ("CYCLE", "TOUR", "EVENT")


def _concert_group_ref(concert):
    """(kind, id) del grupo MÁS CONCRETO de una actividad (compatibilidad: el primero de los suyos)."""
    refs = _concert_group_refs(concert)
    if not refs:
        return None, None
    # El más concreto: el ciclo o la gira antes que el evento.
    for k in ARTWORK_GROUP_SHARE_ORDER:
        for kind, gid in refs:
            if kind == k:
                return kind, gid
    return refs[0]


def _artwork_group_context(session_db, kind: str, gid) -> dict:
    """Contexto del panel de cartelería de un grupo (mismo panel en la ficha del grupo y, en modo
    solo lectura, en cada fecha)."""
    grupo, nombre = _artwork_group_owner(session_db, kind, gid)
    row = _artwork_group_request(session_db, kind, gid)
    todos = [a for a in ((row.assets if row else None) or []) if not a.is_archived]

    def _por(cat, estado):
        """Las piezas de una categoría en un estado, la PRINCIPAL primero."""
        filas = [a for a in todos
                 if _artwork_asset_category(a) == cat
                 and (a.validation_status or "APPROVED") == estado]
        return sorted(filas, key=lambda x: (not bool(x.is_primary), x.created_at or datetime.min))

    return {
        "gk_kind": (kind or "").upper(),
        "gk_id": str(gid) if gid else "",
        "gk_name": nombre,
        "gk_request": row,
        # CARTELES
        "gk_assets": _por("POSTER", "APPROVED"),
        "gk_pending": _por("POSTER", "PENDING"),
        "gk_rejected": _por("POSTER", "REJECTED"),
        # LOGOTIPOS E IMAGEN DE MARCA (sección propia, al principio del panel)
        "gk_brand": _por("LOGO", "APPROVED"),
        "gk_brand_pending": _por("LOGO", "PENDING"),
        "gk_brand_rejected": _por("LOGO", "REJECTED"),
        "gk_brand_formats": ARTWORK_BRAND_FORMATS,
        # La imagen que representa hoy al grupo (la que pinta su ficha y los listados).
        "gk_image_url": (getattr(grupo, ARTWORK_GROUP_IMAGE_FIELD, None) or "").strip() if grupo else "",
    }


@app.post('/conciertos/<cid>/responsable-produccion', endpoint='concert_production_owner_save')
@admin_required
def concert_production_owner_save(cid):
    """Quién de producción se encarga de esta actividad (eventos y fechas sin artista de la casa)."""
    session_db = db()
    try:
        c = session_db.get(Concert, to_uuid(cid))
        if c is None:
            return jsonify({"ok": False, "error": "Actividad no encontrada."}), 404
        # Activar la producción = decir quién se encarga. Lo hace contratación, PRODUCCIÓN (desde su
        # listado de «pendientes de asignar») o **quien creó la actividad**, que es de quien es la
        # tarea; si no, el botón de su Inicio moría en un 403.
        _yo = str((_current_user_state() or {}).get("user_id") or "")
        _soy_creador = bool(_yo and str(getattr(c, "created_by_user_id", "") or "") == _yo)
        if not (can_edit_concerts()
                or has_access_key("produccion", edit=True, include_descendants=True)
                or _soy_creador):
            return jsonify({"ok": False, "error": "Sin permiso."}), 403
        uid = to_uuid((request.form.get("user_id") or "").strip() or "")
        pid = to_uuid((request.form.get("promoter_id") or "").strip() or "")
        extra = {}
        if pid:
            # LA PRODUCE UN TERCERO. Se le crea (o reutiliza) su usuario ESPEJO y su acceso externo,
            # y se le manda el enlace: entra con su correo y un número de verificación, y gestiona
            # SOLO esta actividad. Ver el bloque de «producción externa».
            promoter = session_db.get(Promoter, pid)
            if promoter is None:
                return jsonify({"ok": False, "error": "Ese tercero no existe."}), 404
            espejo = _external_prod_shadow_user(session_db, promoter)
            acceso = _external_prod_access(session_db, c, promoter,
                                           created_by=to_uuid(_yo) if _yo else None)
            c.production_owner_promoter_id = promoter.id
            c.production_owner_user_id = espejo.id
            c.production_activated_at = _now_madrid()
            session_db.commit()
            ok_mail, err_mail = _external_prod_notify(session_db, acceso, concert=c)
            extra = {"external": True, "url": _external_prod_url(acceso),
                     "email": (acceso.email or ""), "mail_ok": bool(ok_mail),
                     "mail_error": ("" if ok_mail else (err_mail or "El correo no salió."))}
            nombre = _promoter_display_name(promoter)
            if request.headers.get("X-Requested-With") == "XMLHttpRequest":
                return jsonify({"ok": True, "name": nombre, **extra})
            flash(("Producción asignada a %s." % nombre)
                  + (" Se le ha mandado su enlace de acceso." if ok_mail
                     else " ⚠️ El correo no salió: cópiale el enlace desde la ficha."), "success")
            return redirect(request.form.get("next") or url_for("concert_detail_view", cid=cid))
        # Personal de la casa: si antes lo llevaba un tercero, su enlace deja de valer.
        if c.production_owner_promoter_id:
            for a in (session_db.query(ExternalProductionAccess)
                      .filter(ExternalProductionAccess.concert_id == c.id).all()):
                a.status = "REVOCADO"
            c.production_owner_promoter_id = None
        c.production_owner_user_id = uid
        # Se apunta CUÁNDO se activó la producción: con responsable, ya hay alguien produciéndola.
        c.production_activated_at = (_now_madrid() if uid else None)
        if uid:
            # AVISO a quien se le asigna: le acaba de entrar una producción.
            _kind = _activity_kind_key(getattr(c, "activity_type", None)) or "CONCIERTO"
            _que = ((getattr(c, "festival_name", None) or "").strip()
                    or (getattr(getattr(c, "artist", None), "name", "") or "")
                    or _activity_kind_label(_kind))
            _notify_user(session_db, uid, "PRODUCCION",
                         "Nueva producción asignada",
                         "%s · %s%s" % (_que,
                                        (c.date.strftime("%d/%m/%Y") if getattr(c, "date", None) else "sin fecha"),
                                        (" · " + _concert_venue_name(c)) if _concert_venue_name(c) else ""),
                         url_for("concert_detail_view", cid=c.id, tab="produccion"),
                         ref_type="CONCERT", ref_id=str(c.id))
        session_db.commit()
        nombre = _concert_production_owner_name(session_db, c)
        if request.headers.get("X-Requested-With") == "XMLHttpRequest":
            return jsonify({"ok": True, "name": nombre})
        flash(f"Responsable de producción: {nombre or 'sin asignar'}.", "success")
        return redirect(request.form.get("next") or url_for("concert_detail_view", cid=cid))
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post('/carteleria-grupo/<gkind>/<gid>/subir', endpoint='group_artwork_upload_direct')
@admin_required
def group_artwork_upload_direct(gkind, gid):
    """Sube carteles de TODA la gira/evento (arrastrando archivos o carpetas). Igual que en una
    fecha: quedan pendientes del OK de diseño salvo que los suba diseño."""
    session_db = db()
    try:
        grupo, _n = _artwork_group_owner(session_db, gkind, gid)
        if grupo is None:
            return jsonify({"ok": False, "error": "Grupo no encontrado."}), 404
        if not can_edit_concerts():
            return jsonify({"ok": False, "error": "Sin permiso para subir carteles."}), 403
        row = _artwork_group_request(session_db, gkind, gid, create=True)
        estado = _current_user_state()
        aprobado_ya = _can_validate_artwork()
        # CARTEL o pieza de MARCA (logotipo): misma solicitud, secciones distintas.
        categoria = _artwork_category_arg(request.form.get("category"))
        ficheros = request.files.getlist("files") or request.files.getlist("file")
        etiquetas = request.form.getlist("labels")
        anchos, altos = request.form.getlist("widths"), request.form.getlist("heights")
        subidos, fallidos = [], []
        for i, fs in enumerate(ficheros):
            if not fs or not getattr(fs, "filename", ""):
                continue
            try:
                file_url, mime_type, kind = _upload_artwork_file(fs)
            except Exception as exc_f:
                # ⚠️ Un archivo que no se admite (un .heic, un .txt que venía en la carpeta) NO puede
                # tumbar el lote: antes reventaba el bucle, se deshacía TODO y los ya subidos se
                # quedaban en Storage sin fila. Se apunta y se sigue con los demás.
                app.logger.exception("[carteleria] no se pudo subir un archivo")
                fallidos.append("%s (%s)" % (getattr(fs, 'filename', 'archivo'), exc_f))
                continue
            if not file_url:
                fallidos.append(getattr(fs, 'filename', 'archivo'))
                continue
            nombre = (etiquetas[i] if i < len(etiquetas) else "") or fs.filename or "Cartel"
            nombre = os.path.basename(str(nombre).replace("\\", "/")).strip() or "Cartel"
            asset = ConcertArtworkAsset(
                artwork_request_id=row.id, format_label=os.path.splitext(nombre)[0][:120],
                file_url=file_url, original_name=nombre[:200], mime_type=mime_type, kind=kind,
                width=_parse_optional_positive_int((anchos[i] if i < len(anchos) else "") or ""),
                height=_parse_optional_positive_int((altos[i] if i < len(altos) else "") or ""),
                validation_status=("APPROVED" if aprobado_ya else "PENDING"),
                category=categoria,
                uploaded_by_user_id=to_uuid(estado.get("user_id")),
                uploaded_by_nick=(estado.get("nick") or "").strip() or None,
            )
            session_db.add(asset)
            session_db.flush()
            # Un cartel en VÍDEO se ve con su miniatura: la saca ffmpeg en 2º plano.
            if kind == "VIDEO":
                _artwork_poster_schedule(asset.id, asset.file_url)
            subidos.append({"id": str(asset.id), "label": asset.format_label})
        if not subidos:
            return jsonify({"ok": False,
                            "error": ("No se pudo subir ningún archivo."
                                      + (" Se han quedado fuera: " + ", ".join(fallidos[:5]) if fallidos else ""))}), 400
        hay_pendientes = any((a.validation_status or "APPROVED") == "PENDING"
                             for a in (row.assets or []) if not a.is_archived)
        row.status = "REVIEW" if hay_pendientes else "UPLOADED"
        if not hay_pendientes:
            # ⚠️ Por CATEGORÍA: si no, la primera pieza de marca podía quedarse como cartel principal.
            _artwork_pick_primary_by_squareness(row, categoria)
            if categoria == "LOGO":
                _artwork_group_sync_brand_image(session_db, gkind, gid, row)
        row.updated_at = datetime.now(ZoneInfo('Europe/Madrid'))
        session_db.commit()
        return jsonify({"ok": True, "assets": subidos, "count": len(subidos),
                        # Lo que no ha entrado NO se calla: el modal lo dice.
                        "skipped": fallidos[:5], "skipped_count": len(fallidos)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("group_artwork_upload_direct")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post('/carteleria-grupo/<gkind>/<gid>/assets/<asset_id>/revisar', endpoint='group_artwork_asset_review')
@admin_required
def group_artwork_asset_review(gkind, gid, asset_id):
    """Diseño aprueba o rechaza UN cartel de la gira/evento (con su nota de qué cambiar)."""
    if not _can_validate_artwork():
        return jsonify({"ok": False, "error": "Solo diseño puede aprobar carteles."}), 403
    session_db = db()
    try:
        row = _artwork_group_request(session_db, gkind, gid)
        asset = session_db.get(ConcertArtworkAsset, to_uuid(asset_id))
        if row is None or asset is None or str(asset.artwork_request_id) != str(row.id):
            return jsonify({"ok": False, "error": "Cartel no encontrado."}), 404
        decision = (request.form.get("decision") or "").strip().upper()
        nota = (request.form.get("note") or "").strip()
        ahora = datetime.now(ZoneInfo('Europe/Madrid'))
        if decision == "APPROVE":
            asset.validation_status, asset.rejection_note = "APPROVED", None
        elif decision == "REJECT":
            if not nota:
                return jsonify({"ok": False, "error": "Escribe qué hay que cambiar."}), 400
            asset.validation_status, asset.rejection_note, asset.is_primary = "REJECTED", nota, False
        else:
            return jsonify({"ok": False, "error": "Decisión no válida."}), 400
        asset.reviewed_at = ahora
        asset.reviewed_by_nick = (_current_user_state().get("nick") or "").strip() or None
        pendientes = [a for a in (row.assets or [])
                      if not a.is_archived and (a.validation_status or "APPROVED") == "PENDING"]
        aprobados = [a for a in (row.assets or [])
                     if not a.is_archived and (a.validation_status or "APPROVED") == "APPROVED"]
        if not pendientes:
            row.status = "UPLOADED" if aprobados else "CORRECTIONS"
        if aprobados:
            for _cat in ARTWORK_ASSET_CATEGORIES:
                _artwork_pick_primary_by_squareness(row, _cat)
        # Un logotipo recién aprobado que es el principal ES la imagen del grupo.
        _artwork_group_sync_brand_image(session_db, gkind, gid, row)
        row.updated_at = ahora
        session_db.commit()
        return jsonify({"ok": True, "status": asset.validation_status, "pending": len(pendientes)})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post('/carteleria-grupo/<gkind>/<gid>/assets/<asset_id>/principal', endpoint='group_artwork_asset_primary')
@admin_required
def group_artwork_asset_primary(gkind, gid, asset_id):
    session_db = db()
    try:
        row = _artwork_group_request(session_db, gkind, gid)
        asset = session_db.get(ConcertArtworkAsset, to_uuid(asset_id))
        if row is not None and asset is not None and str(asset.artwork_request_id) == str(row.id):
            categoria = _artwork_asset_category(asset)
            if not _artwork_can_be_primary(asset):
                flash('La pieza principal tiene que ser una imagen: es la que representa a la '
                      'gira en las cabeceras, los enlaces y los avisos.', 'warning')
            else:
                # ⚠️ Solo dentro de SU categoría: marcar un logotipo no puede desmarcar el cartel
                # principal (comparten solicitud).
                for otro in (row.assets or []):
                    if _artwork_asset_category(otro) == categoria:
                        otro.is_primary = (otro.id == asset.id)
                if categoria == "LOGO":
                    _artwork_group_apply_brand_image(session_db, gkind, gid, asset)
                    session_db.commit()
                    flash('Imagen de la gira actualizada: es la que se ve en su ficha y en los '
                          'listados.', 'success')
                else:
                    session_db.commit()
                    flash('Cartel principal de la gira actualizado.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo marcar el principal: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(request.form.get('next') or request.referrer or url_for('home'))


@app.post('/carteleria-grupo/<gkind>/<gid>/assets/<asset_id>/eliminar', endpoint='group_artwork_asset_delete')
@admin_required
def group_artwork_asset_delete(gkind, gid, asset_id):
    session_db = db()
    try:
        row = _artwork_group_request(session_db, gkind, gid)
        asset = session_db.get(ConcertArtworkAsset, to_uuid(asset_id))
        if row is not None and asset is not None and str(asset.artwork_request_id) == str(row.id):
            categoria = _artwork_asset_category(asset)
            era_principal = bool(getattr(asset, "is_primary", False))
            session_db.delete(asset)
            session_db.flush()
            if categoria == "LOGO" and era_principal:
                # Se ha borrado la imagen del grupo: pasa a serlo la siguiente pieza de marca (y si
                # no queda ninguna, el grupo se queda sin imagen en vez de apuntar a un archivo
                # borrado).
                _artwork_pick_primary_by_squareness(row, "LOGO")
                _artwork_group_sync_brand_image(session_db, gkind, gid, row, clear_if_empty=True)
            session_db.commit()
            flash('Pieza eliminada.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo eliminar: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(request.form.get('next') or request.referrer or url_for('home'))


@app.get('/carteleria-grupo/<gkind>/<gid>/descargar-todos', endpoint='group_artwork_download_all')
@admin_required
def group_artwork_download_all(gkind, gid):
    """Todas las piezas aprobadas de la gira/evento en un ZIP (carteles o, con `?category=LOGO`,
    los logotipos e imagen de marca)."""
    session_db = db()
    try:
        _grupo, nombre = _artwork_group_owner(session_db, gkind, gid)
        categoria = _artwork_category_arg(request.args.get('category'))
        assets = _artwork_group_assets(session_db, gkind, gid, only_approved=True, category=categoria)
        if not assets:
            flash('No hay %s aprobados que descargar.'
                  % ('logotipos' if categoria == 'LOGO' else 'carteles'), 'warning')
            return redirect(request.referrer or url_for('home'))
        buf, usados = BytesIO(), set()
        with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
            for a in assets:
                fichero = (a.original_name or a.format_label or 'cartel').strip()
                base, ext = os.path.splitext(fichero)
                n = 1
                while fichero.lower() in usados:
                    n += 1
                    fichero = f"{base} ({n}){ext}"
                usados.add(fichero.lower())
                try:
                    req = Request(a.file_url, headers={'User-Agent': 'Mozilla/5.0'})
                    with urlopen(req, timeout=25) as resp:
                        zf.writestr(fichero, resp.read())
                except Exception:
                    continue
        buf.seek(0)
        etiqueta = re.sub(r"[\\/:*?\"<>|]+", " ", (nombre or "Carteleria")).strip() or "Carteleria"
        return send_file(buf, mimetype="application/zip", as_attachment=True,
                         download_name=f"Carteles {etiqueta}.zip")
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/carteleria/subir', endpoint='concert_artwork_upload_direct')
@admin_required
def concert_artwork_upload_direct(cid):
    """Subida de carteles A MANO desde la ficha (arrastrando archivos o carpetas enteras).

    Quedan **pendientes de aprobación por diseño**: se ven pero no se pueden usar hasta que diseño
    les dé el OK uno a uno (igual que las fotos). Devuelve JSON para el modal.
    """
    session_db = db()
    try:
        concert = (session_db.query(Concert)
                   .options(selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets))
                   .filter(Concert.id == to_uuid(cid)).first())
        if concert is None:
            return jsonify({"ok": False, "error": "Actividad no encontrada."}), 404
        if not can_edit_concerts():
            return jsonify({"ok": False, "error": "Sin permiso para subir carteles."}), 403
        row = _artwork_ensure_request(session_db, concert)
        estado = _current_user_state()
        ficheros = request.files.getlist("files") or request.files.getlist("file")
        etiquetas = request.form.getlist("labels")
        anchos = request.form.getlist("widths")
        altos = request.form.getlist("heights")
        subidos, fallidos = [], []
        for i, fs in enumerate(ficheros):
            if not fs or not getattr(fs, "filename", ""):
                continue
            try:
                file_url, mime_type, kind = _upload_artwork_file(fs)
            except Exception as exc_f:
                # ⚠️ Un archivo que no se admite (un .heic, un .txt que venía en la carpeta) NO puede
                # tumbar el lote: antes reventaba el bucle, se deshacía TODO y los ya subidos se
                # quedaban en Storage sin fila. Se apunta y se sigue con los demás.
                app.logger.exception("[carteleria] no se pudo subir un archivo")
                fallidos.append("%s (%s)" % (getattr(fs, 'filename', 'archivo'), exc_f))
                continue
            if not file_url:
                fallidos.append(getattr(fs, 'filename', 'archivo'))
                continue
            # De una carpeta llega la ruta completa: la etiqueta es el nombre del archivo.
            nombre = (etiquetas[i] if i < len(etiquetas) else "") or fs.filename or "Cartel"
            nombre = os.path.basename(str(nombre).replace("\\", "/")).strip() or "Cartel"
            asset = ConcertArtworkAsset(
                artwork_request_id=row.id,
                format_label=os.path.splitext(nombre)[0][:120],
                file_url=file_url,
                original_name=nombre[:200],
                mime_type=mime_type,
                kind=kind,
                width=_parse_optional_positive_int((anchos[i] if i < len(anchos) else "") or ""),
                height=_parse_optional_positive_int((altos[i] if i < len(altos) else "") or ""),
                # Lo que sube DISEÑO (o dirección) ya está aprobado; lo que sube cualquier otro
                # queda pendiente de su OK y no se puede usar hasta entonces.
                validation_status=('APPROVED' if _can_validate_artwork() else 'PENDING'),
                uploaded_by_user_id=to_uuid(estado.get("user_id")),
                uploaded_by_nick=(estado.get("nick") or "").strip() or None,
            )
            session_db.add(asset)
            session_db.flush()
            # Un cartel en VÍDEO se ve con su miniatura: la saca ffmpeg en 2º plano.
            if kind == "VIDEO":
                _artwork_poster_schedule(asset.id, asset.file_url)
            subidos.append({"id": str(asset.id), "label": asset.format_label, "url": asset.file_url})
        if not subidos:
            return jsonify({"ok": False,
                            "error": ("No se pudo subir ningún archivo."
                                      + (" Se han quedado fuera: " + ", ".join(fallidos[:5]) if fallidos else ""))}), 400
        # Solo se marca «en revisión» si de verdad queda algo pendiente de aprobar.
        hay_pendientes = any((a.validation_status or 'APPROVED') == 'PENDING'
                             for a in (row.assets or []) if not a.is_archived)
        if hay_pendientes and (row.status or 'DRAFT').upper() in ('DRAFT', 'PROMOTER', 'REQUESTED', 'CORRECTIONS', 'UPLOADED'):
            row.status = 'REVIEW'
        elif not hay_pendientes and (row.status or 'DRAFT').upper() in ('DRAFT', 'REVIEW'):
            row.status = 'UPLOADED'
            _artwork_pick_primary_by_squareness(row)
        row.updated_at = datetime.now(ZoneInfo('Europe/Madrid'))
        _artwork_notify_resolve_if_done(session_db, row)
        session_db.commit()
        return jsonify({"ok": True, "assets": subidos, "count": len(subidos),
                        # Lo que no ha entrado NO se calla: el modal lo dice.
                        "skipped": fallidos[:5], "skipped_count": len(fallidos)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("concert_artwork_upload_direct")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/carteleria/assets/<asset_id>/revisar', endpoint='concert_artwork_asset_review')
@admin_required
def concert_artwork_asset_review(cid, asset_id):
    """Diseño da el OK (o lo rechaza con una nota) a UN cartel. Los aprobados ya se pueden usar; los
    rechazados se quedan a la vista con su aviso y se le reclaman a quien los subió."""
    if not _can_validate_artwork():
        return jsonify({"ok": False, "error": "Tu usuario no puede validar cartelería."}), 403
    session_db = db()
    try:
        concert = (session_db.query(Concert)
                   .options(joinedload(Concert.artist),
                            selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets))
                   .filter(Concert.id == to_uuid(cid)).first())
        row = getattr(concert, 'artwork_request', None) if concert else None
        asset = session_db.get(ConcertArtworkAsset, to_uuid(asset_id))
        if row is None or asset is None or str(asset.artwork_request_id) != str(row.id):
            return jsonify({"ok": False, "error": "Cartel no encontrado."}), 404
        decision = (request.form.get("decision") or "").strip().upper()
        nota = (request.form.get("note") or "").strip()
        ahora = datetime.now(ZoneInfo('Europe/Madrid'))
        estado = _current_user_state()
        if decision == "APPROVE":
            asset.validation_status = "APPROVED"
            asset.rejection_note = None
        elif decision == "REJECT":
            if not nota:
                return jsonify({"ok": False, "error": "Escribe qué hay que cambiar."}), 400
            asset.validation_status = "REJECTED"
            asset.rejection_note = nota
            asset.is_primary = False
        else:
            return jsonify({"ok": False, "error": "Decisión no válida."}), 400
        asset.reviewed_at = ahora
        asset.reviewed_by_nick = (estado.get("nick") or "").strip() or None
        # Cuando ya no queda ninguno pendiente, la solicitud deja de estar «en revisión».
        pendientes = [a for a in (row.assets or [])
                      if not a.is_archived and (a.validation_status or 'APPROVED') == 'PENDING']
        aprobados = [a for a in (row.assets or [])
                     if not a.is_archived and (a.validation_status or 'APPROVED') == 'APPROVED']
        if not pendientes:
            row.status = 'UPLOADED' if aprobados else 'CORRECTIONS'
        row.updated_at = ahora
        if aprobados:
            _artwork_pick_primary_by_squareness(row)
        _artwork_notify_resolve_if_done(session_db, row)
        session_db.commit()
        return jsonify({"ok": True, "status": asset.validation_status,
                        "pending": len(pendientes), "approved": len(aprobados)})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


def _home_artwork_rejected(user_id=None) -> list:
    """Carteles que subió esta persona y que diseño ha RECHAZADO: salen en sus tareas pendientes de
    Inicio con la nota de qué hay que cambiar."""
    uid = to_uuid(user_id or session.get("user_id") or "")
    if not uid:
        return []
    session_db = db()
    try:
        filas = (session_db.query(ConcertArtworkAsset, ConcertArtworkRequest, Concert)
                 .join(ConcertArtworkRequest, ConcertArtworkAsset.artwork_request_id == ConcertArtworkRequest.id)
                 .join(Concert, ConcertArtworkRequest.concert_id == Concert.id)
                 .filter(ConcertArtworkAsset.uploaded_by_user_id == uid,
                         ConcertArtworkAsset.validation_status == "REJECTED")
                 .order_by(ConcertArtworkAsset.reviewed_at.desc().nullslast())
                 .limit(20).all())
        out = []
        for asset, _row, concert in filas:
            out.append({
                "id": str(asset.id),
                "label": asset.format_label or (asset.original_name or "Cartel"),
                "note": asset.rejection_note or "",
                "url": url_for("concert_detail_view", cid=concert.id, tab="carteleria"),
                "event": " · ".join([x for x in [(concert.artist.name if concert.artist else ""),
                                                 (concert.date.strftime("%d/%m/%Y") if concert.date else "")] if x]),
            })
        return out
    except Exception:
        return []
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/carteleria/validar', endpoint='concert_artwork_validate')
@admin_required
def concert_artwork_validate(cid):
    if not _can_validate_artwork():
        return forbid('Tu usuario no puede validar cartelería.')
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(joinedload(Concert.artist), selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets))
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        row = getattr(concert, 'artwork_request', None) if concert else None
        if not row:
            flash('No hay solicitud de cartelería.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
        now = datetime.now(ZoneInfo('Europe/Madrid'))
        for a in (row.assets or []):
            if not a.is_archived and (a.validation_status or 'APPROVED') == 'PENDING':
                a.validation_status = 'APPROVED'
        row.status = 'UPLOADED'
        row.correction_notes = None
        row.updated_at = now
        _artwork_pick_primary_by_squareness(row)
        session.commit()
        flash('Carteles validados: ya aparecen en la ficha del evento.', 'success')
    except Exception as exc:
        session.rollback()
        flash(f'Error validando carteles: {exc}', 'danger')
    finally:
        session.close()
    return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))


@app.post('/conciertos/<cid>/carteleria/rechazar', endpoint='concert_artwork_reject')
@admin_required
def concert_artwork_reject(cid):
    if not _can_validate_artwork():
        return forbid('Tu usuario no puede validar cartelería.')
    session = db()
    try:
        concert = (
            session.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company),
                     selectinload(Concert.artwork_request).selectinload(ConcertArtworkRequest.assets))
            .filter(Concert.id == to_uuid(cid))
            .first()
        )
        row = getattr(concert, 'artwork_request', None) if concert else None
        if not row:
            flash('No hay solicitud de cartelería.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
        note = (request.form.get('reason') or '').strip()
        if not note:
            flash('Indica qué debe corregirse antes de rechazar.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))
        now = datetime.now(ZoneInfo('Europe/Madrid'))
        for a in (row.assets or []):
            if not a.is_archived and (a.validation_status or 'APPROVED') == 'PENDING':
                a.validation_status = 'REJECTED'
                a.is_archived = True
                a.archived_at = now
        row.status = 'CORRECTIONS'
        row.correction_notes = note
        row.updated_at = now
        session.commit()
        ok, error = _send_promoter_artwork_email(concert, row, kind='REJECTED', note=note)
        if ok:
            flash('Carteles rechazados: se ha pedido al promotor que los corrija y vuelva a subirlos.', 'warning')
        else:
            flash(f'Carteles rechazados, pero el correo no se pudo enviar: {error}', 'warning')
    except Exception as exc:
        session.rollback()
        flash(f'Error rechazando carteles: {exc}', 'danger')
    finally:
        session.close()
    return redirect(url_for('concert_detail_view', cid=cid, tab='carteleria'))


# ---------- Canales de venta (links de venta cuando vende un promotor externo) ----------

def _concert_is_free_event(concert) -> bool:
    """¿El evento es gratuito? (entrada FREE del asistente o sale_type GRATUITO)."""
    payload = getattr(concert, 'ticketing_payload', None) or {}
    entry_mode = (payload.get('entry_mode') or '').strip().upper() if isinstance(payload, dict) else ''
    return entry_mode == 'FREE' or (concert.sale_type or '').strip().upper() == 'GRATUITO'


def _concert_sale_seller(concert) -> dict:
    payload = getattr(concert, 'ticketing_payload', None) or {}
    seller = payload.get('sale_seller') if isinstance(payload, dict) else None
    return seller if isinstance(seller, dict) else {}


def _concert_sale_channel_rows(concert) -> list[dict]:
    """Canales de venta configurados (ConcertTicketer): ticketera + link + aforo."""
    rows = []
    for ct in (getattr(concert, 'ticketers', None) or []):
        t = getattr(ct, 'ticketer', None)
        rows.append({
            'id': str(ct.ticketer_id),
            'name': (t.name if t else 'Ticketera'),
            'logo_url': (t.logo_url if t else '') or '',
            'sale_url': (ct.sale_url or '').strip(),
            'capacity_for_sale': int(ct.capacity_for_sale or 0),
        })
    rows.sort(key=lambda r: r['name'].casefold())
    return rows


def _ensure_ticketer_by_name(session, name: str):
    name = (name or '').strip()
    if not name:
        return None
    existing = session.query(Ticketer).filter(func.lower(Ticketer.name) == name.lower()).first()
    if existing:
        return existing
    t = Ticketer(name=name)
    session.add(t)
    session.flush()
    return t


def _send_sale_channels_email(concert: Concert, req: ConcertSaleChannelRequest, kind: str = 'REQUEST') -> tuple[bool, str | None]:
    """Correo al promotor «Actualizar canales de venta»: configura TODOS los links de venta."""
    recipients = [x for x in (req.recipients_json or []) if x]
    if not recipients:
        return False, 'Sin destinatarios guardados en la petición.'
    public_url = _external_url_for('public_sale_channels', token=req.public_token)
    reminder = ''
    if (kind or '').upper() == 'REMINDER':
        reminder = '<p style="background:#fef3c7;border-radius:8px;padding:10px 12px;">Recordatorio automático: aún no tenemos los links de venta de este evento.</p>'
    html_body = (
        '<div style="font-family:Arial,sans-serif;color:#1f2937;max-width:640px;">'
        + _concert_email_header_html(concert, 'Actualizar canales de venta')
        + reminder
        + '<p>Necesitamos que configures <strong>todos los links de venta</strong> del evento (puedes añadir varias ticketeras).</p>'
        + f'<p><a href="{public_url}" style="display:inline-block;background:#E33D48;color:#fff;padding:12px 18px;border-radius:8px;text-decoration:none;font-weight:700;">Añadir links de venta</a></p>'
        + '</div>'
    )
    subject = f'Actualizar canales de venta · {concert.artist.name if concert.artist else "actividad"}'
    return _send_optional_email(recipients, subject, html_body, text_body=public_url)


@app.post('/conciertos/<cid>/canales-venta/guardar', endpoint='concert_sale_channel_save')
@admin_required
def concert_sale_channel_save(cid):
    if not (is_master() or can_edit_concerts()):
        return forbid('Tu usuario no tiene permisos para editar el ticketing.')
    session = db()
    try:
        concert = session.get(Concert, to_uuid(cid))
        if not concert:
            flash('Concierto no encontrado.', 'warning')
            return redirect(url_for('concerts_view', tab='vista'))
        ticketer_id = to_uuid((request.form.get('ticketer_id') or '').strip() or None)
        if not ticketer_id:
            t = _ensure_ticketer_by_name(session, request.form.get('new_ticketer_name'))
            ticketer_id = t.id if t else None
        if not ticketer_id:
            flash('Elige una ticketera o escribe el nombre de una nueva.', 'warning')
            return redirect(url_for('concert_detail_view', cid=cid, tab='ticketing'))
        row = (session.query(ConcertTicketer)
               .filter(ConcertTicketer.concert_id == concert.id, ConcertTicketer.ticketer_id == ticketer_id)
               .first())
        if not row:
            row = ConcertTicketer(concert_id=concert.id, ticketer_id=ticketer_id)
            session.add(row)
        sale_url = (request.form.get('sale_url') or '').strip()
        if sale_url and not re.match(r'^https?://', sale_url, re.I):
            sale_url = 'https://' + sale_url
        row.sale_url = sale_url or None
        cap = _parse_optional_positive_int(request.form.get('capacity_for_sale'))
        if cap is not None:
            row.capacity_for_sale = cap
        # Si ya hay link, la petición al promotor queda satisfecha.
        req = session.query(ConcertSaleChannelRequest).filter_by(concert_id=concert.id).first()
        if req and sale_url and req.status == 'ACTIVE':
            req.status = 'DONE'
            req.updated_at = datetime.now(ZoneInfo('Europe/Madrid'))
        session.commit()
        flash('Canal de venta guardado.', 'success')
    except Exception as exc:
        session.rollback()
        flash(f'Error guardando el canal de venta: {exc}', 'danger')
    finally:
        session.close()
    return redirect(url_for('concert_detail_view', cid=cid, tab='ticketing'))


