        row['invoice_name'] = fs.filename
        row['invoiced_at'] = datetime.now(ZoneInfo('Europe/Madrid')).isoformat()
        rows[payment_idx] = row
        concert.payment_terms_json = rows
        session.commit()
        flash('Factura subida correctamente.', 'success')
