@app.post("/conciertos/<cid>/seccion/<section>", endpoint="concert_section_update")
@admin_required
def concert_section_update_handler(cid, section):
    """Guardado PARCIAL por sección de la ficha de concierto (edición inline).

    Actualiza solo los campos de la sección indicada, reutilizando los mismos helpers que
    `concert_update` para no alterar la lógica económica. Las secciones no tocadas quedan intactas.
    """
    session = db()
    c = session.get(Concert, to_uuid(cid))
    if not c:
        flash("Concierto no encontrado.", "warning")
        session.close()
        return redirect(url_for("concerts_view", tab="vista"))
    try:
        if section == "datos":
            sale_type = (request.form.get("sale_type") or c.sale_type or "EMPRESA").strip().upper()
            if sale_type not in CONCERT_SALE_TYPES_ALL_SET:
                sale_type = "EMPRESA"
            venue_raw = (request.form.get("venue_id") or "").strip()
            if not venue_raw:
                raise ValueError("Debes seleccionar un recinto de la lista (o crearlo desde el botón +).")
            c.date = parse_date(request.form["date"])
            c.festival_name = (request.form.get("festival_name") or "").strip() or None
            c.venue_id = to_uuid(venue_raw)
            c.sale_type = sale_type
            c.artist_id = to_uuid(request.form["artist_id"])
            c.billing_company_id = to_uuid(request.form.get("billing_company_id") or None)
            requested_capacity = max(0, int(request.form.get("capacity") or 0))
            previous_effective_capacity = _concert_capacity_from_ticket_types(c)
            c.capacity = requested_capacity
            c.sale_start_date = parse_concert_sale_start_date(request.form.get("sale_start_date"), sale_type)
            c.break_even_ticket = None if sale_type in ("VENDIDO", "GRATUITO") else _parse_optional_positive_int((request.form.get("break_even_ticket") or "").strip())
            # COMPUERTA: confirmar exige haber avisado al artista. Si falta el aviso NO se tira todo
            # el guardado: se queda el resto de cambios y el estado se deja como estaba, con el
            # enlace para avisar en ese momento.
            _nuevo_estado = _norm_status(request.form.get("status"))
            _puerta = _concert_notice_gate(session, c, _nuevo_estado)
            if _puerta:
                flash(Markup(
                    '%s <a class="alert-link" href="%s">%s</a>.'
                    % (escape(_puerta["reason"]), _puerta["notify_url"],
                       ('Avisar al artista o marcar que ya fue informado'
                        if _puerta.get("can_ack") else 'Avisar al artista ahora'))), "warning")
            else:
                c.status = _nuevo_estado
            c.promoter_id = to_uuid(request.form.get("promoter_id") or None) if sale_type in ("VENDIDO", "GRATUITO", "GIRAS_COMPRADAS") else None
            c.hashtags = _dedupe_concert_tags(request.form.getlist("concert_tags[]"))
            # Anuncio (solo si el formulario lo incluye, para no pisar datos desde forms antiguos).
            if request.form.get("announcement_present"):
                c.do_not_announce = _truthy(request.form.get("do_not_announce"))
                c.announcement_date = None if c.do_not_announce else parse_optional_date(request.form.get("announcement_date"))
                _cp = dict(c.contracting_payload or {})
                _cp["announcement_note"] = (request.form.get("announcement_note") or "").strip()
                c.contracting_payload = _cp
            # Coherencia: si pasa a VENDIDO no hay colaboradores/comisionistas.
            if sale_type == "VENDIDO":
                _replace_concert_promoter_shares(session, c.id, [])
                _replace_concert_company_shares(session, c.id, [])
                _replace_concert_zone_agents(session, c.id, [])
            if requested_capacity != previous_effective_capacity:
                _sync_concert_capacity_after_manual_edit(session, c.id, requested_capacity)
            # Reenvío de cartelería si cambiaron fecha/recinto/horarios (igual que concert_update).
            artwork_row = getattr(c, 'artwork_request', None)
            session.flush()
            try:
                session.expire(c, ['venue'])
            except Exception:
                pass
            artwork_resend = None  # None | 'OURS' | 'PROMOTER'
            artwork_handled = (getattr(artwork_row, 'handled_by', None) or 'OURS').strip().upper() if artwork_row else 'OURS'
            if artwork_row and _artwork_request_has_event_changes(artwork_row, c):
                # Cambian fecha/recinto/horarios → los carteles se ANULAN (pasan a antiguos) y se
                # genera automáticamente una nueva petición (a diseño o al promotor, según quién los haga).
                _archive_current_artwork_assets(artwork_row)
                now = datetime.now(ZoneInfo('Europe/Madrid'))
                artwork_row.status = 'REQUESTED'
                artwork_row.requested_at = now
                artwork_row.updated_at = now
                artwork_row.needs_refresh = False
                artwork_row.event_snapshot = _concert_artwork_snapshot(c)
                artwork_resend = artwork_handled
            else:
                _sync_artwork_request_refresh_flag(c)
            session.commit()
            if artwork_resend == 'OURS' and artwork_row:
                _send_artwork_request_email(c, artwork_row, is_update=True)
            elif artwork_resend == 'PROMOTER' and artwork_row:
                _send_promoter_artwork_email(c, artwork_row, kind='CHANGES')
            flash("Datos de la actividad actualizados.", "success")
        elif section == "colaboradores":
            if (c.sale_type or "").strip().upper() == "VENDIDO":
                raise ValueError("Un concierto vendido no admite colaboradores.")
            p_rows = _parse_share_rows(
                request.form.getlist("promoter_share_id[]"),
                request.form.getlist("promoter_share_pct[]"),
                request.form.getlist("promoter_share_pct_base[]"),
                request.form.getlist("promoter_share_amount[]"),
                request.form.getlist("promoter_share_amount_base[]"),
            )
            _replace_concert_promoter_shares(session, c.id, p_rows)
            g_rows = _parse_share_rows(
                request.form.getlist("company_share_id[]"),
                request.form.getlist("company_share_pct[]"),
                request.form.getlist("company_share_pct_base[]"),
                request.form.getlist("company_share_amount[]"),
                request.form.getlist("company_share_amount_base[]"),
            )
            _replace_concert_company_shares(session, c.id, g_rows)
            session.commit()
            flash("Colaboradores actualizados.", "success")
        elif section == "comisionistas":
            if (c.sale_type or "").strip().upper() == "VENDIDO":
                raise ValueError("Un concierto vendido no admite comisionistas.")
            z_rows = _parse_zone_rows(
                request.form.getlist("zone_promoter_id[]"),
                request.form.getlist("zone_commission_mode[]"),
                request.form.getlist("zone_commission_pct[]"),
                request.form.getlist("zone_commission_base[]"),
                request.form.getlist("zone_commission_amount[]"),
                request.form.getlist("zone_exempt_amount[]"),
                request.form.getlist("zone_concept[]"),
            )
            _replace_concert_zone_agents(session, c.id, z_rows)
            session.commit()
            flash("Comisionistas actualizados.", "success")
        elif section == "caches":
            cache_rows = _parse_cache_rows(
                request.form.getlist("cache_kind[]"),
                request.form.getlist("cache_concept[]"),
                request.form.getlist("cache_amount[]"),
                request.form.getlist("cache_var_mode[]"),
                request.form.getlist("cache_var_option[]"),
                request.form.getlist("cache_from_ticket[]"),
                request.form.getlist("cache_min_tickets[]"),
                request.form.getlist("cache_min_revenue[]"),
                request.form.getlist("cache_pct[]"),
                request.form.getlist("cache_pct_base[]"),
                request.form.getlist("cache_ticket_type[]"),
            )
            _replace_concert_caches(session, c.id, cache_rows)
            # «El promotor cubre otros gastos» (solo si el formulario incluye el módulo).
            if request.form.get("promoter_costs_present"):
                c.promoter_costs_payload = _parse_promoter_costs_form(request.form)
            session.commit()
            flash("Cachés actualizados.", "success")
        elif section == "actividad":
            # Detalle de eventos promocionales/TV/marca/otros: descripción + actuación.
            is_promo = _activity_has_performance_detail(c.activity_type)
            payload = dict(c.contracting_payload or {})
            # El detalle (descripción/actuación) solo se toca si el formulario lo trae: la sección
            # M&G de los conciertos postea a esta misma sección sin esos campos.
            if "activity_description" in request.form:
                payload["description"] = (request.form.get("activity_description") or "").strip()
                performance = _wizard_performance_payload(session, request.form, is_promo)
                payload["performance"] = performance
                formation_label = _performance_formation_label(performance)
                if formation_label or performance.get("sings") is not None:
                    payload["formation"] = formation_label
            # Meet & Greet (solo llega si el formulario lo incluye, para no pisar desde forms antiguos).
            if request.form.get("meet_greet_present"):
                payload["meet_greet"] = {
                    "enabled": _truthy(request.form.get("meet_greet")),
                    "quantity": (request.form.get("meet_greet_quantity") or "").strip(),
                    "moment": (request.form.get("meet_greet_moment") or "").strip(),
                }
            c.contracting_payload = payload
            _sync_meet_greet_roadmap(c)
            session.commit()
            flash("Detalle de la actividad actualizado.", "success")
        elif section == "entradas":
            # Entrada y venta: gratuito/venta, aforo, quién vende, tipos, salida e invitaciones.
            payload = dict(c.ticketing_payload or {})
            entry_mode = (request.form.get("entry_mode") or "").strip().upper()
            if entry_mode not in ("FREE", "SALE"):
                entry_mode = "FREE"
            ticket_type_rows = _parse_wizard_ticket_types(request.form)
            if entry_mode == "FREE":
                c.no_capacity = _truthy(request.form.get("free_capacity_unlimited"))
                c.capacity = 0 if c.no_capacity else (_parse_optional_positive_int(request.form.get("free_capacity")) or 0)
                c.sale_start_tbc = False
                c.sale_start_date = None
                ticket_type_rows = []
                payload["sale_seller"] = None
                payload["sale_owner"] = ""
            else:
                c.no_capacity = False
                qty_sum = sum(int(r.get("qty_for_sale") or 0) for r in ticket_type_rows)
                c.capacity = _parse_optional_positive_int(request.form.get("capacity")) or qty_sum or 0
                c.sale_start_tbc = _truthy(request.form.get("sale_start_tbc"))
                c.sale_start_date = None if c.sale_start_tbc else parse_optional_date(request.form.get("sale_start_date"))
                seller = _parse_wizard_sale_seller(
                    session, request.form,
                    billing_company_id=c.billing_company_id,
                    promoter_id=c.promoter_id,
                    venue_id=c.venue_id,
                )
                payload["sale_seller"] = seller
                payload["sale_owner"] = (seller.get("label") if seller else "") or ""
            payload["entry_mode"] = entry_mode
            payload["free_capacity_unlimited"] = bool(entry_mode == "FREE" and c.no_capacity)
            payload["ticket_types"] = ticket_type_rows
            invitations_mode = (request.form.get("invitations_mode") or "").strip().upper()
            invitation_rows = []
            if invitations_mode == "TOTAL":
                inv_total = _parse_optional_positive_int(request.form.get("invitations_total")) or 0
                if inv_total:
                    invitation_rows = [{"category": "Invitaciones por contrato", "artist_qty": 0, "office_qty": inv_total, "total_qty": inv_total}]
                payload["invitations_total"] = inv_total
            elif invitations_mode == "BY_TYPE":
                for r in ticket_type_rows:
                    inv_total = int(r.get("invites_total") or 0)
                    if inv_total:
                        invitation_rows.append({"category": r["name"], "artist_qty": 0, "office_qty": inv_total, "total_qty": inv_total})
            if invitations_mode:
                payload["invitations_mode"] = invitations_mode
                c.invitations_json = invitation_rows
            c.ticketing_payload = payload
            _replace_concert_ticket_types_manual(session, c.id, ticket_type_rows)
            session.commit()
            flash("Entradas y venta actualizadas.", "success")
        elif section == "equipamiento":
            _upsert_equipment_from_request(session, c.id)
            _add_equipment_docs_from_request(session, c.id)
            _add_equipment_notes_from_request(session, c.id)
            session.commit()
            flash("Equipamiento actualizado.", "success")
        elif section == "contratos":
            if not can_view_concert_contracts():
                raise ValueError("Los contratos solo los gestionan dirección, contratación y administración.")
            _add_contracts_from_request(session, c.id)
            session.commit()
            flash("Contratos actualizados.", "success")
        elif section == "notas":
            _add_concert_notes_from_request(session, c.id)
            session.commit()
            flash("Notas actualizadas.", "success")
        elif section == "contactos":
            _replace_concert_contacts(session, c.id, _parse_concert_contacts_form(request.form))
            session.commit()
            flash("Contactos actualizados.", "success")
        else:
            raise ValueError("Sección no reconocida.")
    except Exception as e:
        session.rollback()
        flash(f"Error actualizando: {e}", "danger")
    finally:
        session.close()
    return redirect(url_for("concert_detail_view", cid=cid, tab="general"))


# ---------- BORRAR ----------
# La palabra que hay que escribir para borrar una actividad: es la única red de seguridad de una
# acción que no se puede deshacer.
CONCERT_DELETE_WORD = "ELIMINAR"


@app.post("/conciertos/<cid>/delete", endpoint="concert_delete")
@admin_required
def concert_delete_handler(cid):
    """Elimina la actividad y TODO lo que cuelga de ella.

    Se pide a mano (rueda de la cabecera de la ficha → «Eliminar actividad») y hace falta escribir
    ELIMINAR. Si la actividad ya se había comunicado fuera (al artista, al promotor, a diseño), el
    pop-up lo dice con las fotos y los nombres y deja elegir:
    · `notify=1` → se manda el aviso de CANCELACIÓN (con la nota que se escriba) y se borra. Si el
      correo NO sale, NO se borra: así se puede volver a intentar.
    · sin `notify` → se borra sin avisar a nadie."""
    session = db()
    try:
        concert_uuid = to_uuid(cid)
        if not concert_uuid:
            raise ValueError("ID de concierto inválido")

        if not can_edit_concerts():
            return forbid("No tienes permisos para eliminar una actividad.")

        _c_prev = session.get(Concert, concert_uuid)
        if _c_prev is None:
            flash("Esa actividad ya no existe.", "warning")
            return redirect(url_for("concerts_view", tab="vista"))

        # LA PALABRA. Sin ella no se borra nada (ni desde la ficha ni con un POST a mano).
        palabra = (request.form.get("confirm_word") or "").strip().upper()
        if palabra != CONCERT_DELETE_WORD:
            flash(f"Para eliminar la actividad hay que escribir «{CONCERT_DELETE_WORD}».", "warning")
            return redirect(url_for("concert_detail_view", cid=cid, tab="general"))

        # ¿A quién se le había comunicado ya? Si hay alguien y se ha pedido avisar, se manda el aviso
        # de cancelación ANTES de borrar (después ya no se podría componer: no habría actividad).
        avisados = _concert_notified_parties(session, _c_prev)
        if avisados and _truthy(request.form.get("notify")):
            nota = (request.form.get("note") or "").strip()
            ok, error = _activity_cancellation_notify(
                session, _c_prev, nota, [p.get("email") for p in avisados])
            if not ok:
                # ⚠️ Si no ha salido el correo NO se borra: si no, se perdería la actividad sin que
                # nadie se hubiera enterado de la cancelación.
                session.rollback()
                flash("No se ha podido avisar de la cancelación (%s): la actividad NO se ha eliminado."
                      % (error or "error desconocido"), "danger")
                return redirect(url_for("concert_detail_view", cid=cid, tab="general"))
            flash("Aviso de cancelación enviado a %d destinatario(s)." % len(
                {(p.get("email") or "").lower() for p in avisados if "@" in (p.get("email") or "")}), "success")

        # Los avisos de esta actividad («producción asignada», «cartelería»…) dejan de tener sentido:
        # si no, se quedan en la campanita llevando a una ficha que ya no existe.
        _notify_resolve(session, "CONCERT", concert_uuid)
        # limpia hijos (por si los FKs no tienen ON DELETE CASCADE)
        session.query(TicketSale).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        # Ventas V2
        session.query(TicketSaleDetail).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertTicketer).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertTicketType).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertSalesConfig).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertPromoterShare).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertCompanyShare).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertZoneAgent).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertCache).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertContract).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertNote).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertEquipmentDocument).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertEquipmentNote).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        session.query(ConcertEquipment).filter_by(concert_id=concert_uuid).delete(synchronize_session=False)
        # ⚠️ Las FOTOS y los VÍDEOS son polimórficos (`owner_type`/`owner_id`, SIN clave ajena), así
        # que el borrado en cascada no las toca y se quedaban colgadas de una actividad que ya no
        # existe. Sus notas, álbumes y aprobaciones sí cascadean desde la foto.
        session.query(Photo).filter(Photo.owner_type == "CONCERT",
                                    Photo.owner_id == concert_uuid).delete(synchronize_session=False)
        session.flush()

        c = session.get(Concert, concert_uuid)
        if c:
            session.delete(c)

        session.commit()
        flash("Actividad eliminada.", "success")

    except Exception as e:
        session.rollback()
        flash(f"Error borrando la actividad: {e}", "danger")

    finally:
        session.close()

    return redirect(url_for("concerts_view", tab="vista"))


# ----------- API: crear Recinto / Tercero (modal) -----------

@app.post("/api/venues/create", endpoint="api_create_venue")
@admin_required
def api_create_venue():
    session_db = db()
    try:
        payload = request.get_json(silent=True) if request.is_json else None
        payload = payload or request.form

        name = (payload.get("name") or "").strip()
        if not name:
            return jsonify({"error": "El nombre del recinto es obligatorio."}), 400

        municipality = (payload.get("municipality") or "").strip() or None
        province = (payload.get("province") or "").strip() or None
        country = (payload.get("country") or "").strip() or "España"
        address = (payload.get("address") or "").strip() or None
        force_new = _truthy(payload.get("force_new"))
        photo = request.files.get("photo") or request.files.get("logo") if not request.is_json else None
        photo_url = upload_image(photo, "venues") if photo and getattr(photo, "filename", "") else None

        covered_value = payload.get("covered")
        if isinstance(covered_value, bool):
            covered = covered_value
        else:
            covered = str(covered_value or "").strip().lower() in ("1", "true", "yes", "on", "si", "sí")
        allows_bars = _truthy(payload.get("allows_bars"))

        rows = []
        for row in session_db.query(Venue).order_by(Venue.name.asc()).all():
            label = (row.name or '').strip()
            if row.municipality or row.province:
                label = f"{label} — {(row.municipality or '').strip()} ({(row.province or '').strip()})".strip()
            rows.append({"id": str(row.id), "label": label, "name": (row.name or '').strip(), "photo_url": (getattr(row, 'photo_url', None) or '').strip()})

        exact = None
        for row in session_db.query(Venue).all():
            if _norm_text_key(row.name or '') == _norm_text_key(name) and (_norm_text_key(row.municipality or '') == _norm_text_key(municipality or '') or not municipality):
                exact = row
                break
        similar = _build_similarity_rows(name, rows, threshold=0.76)
        if exact and not force_new:
            similar = [{"id": str(exact.id), "label": f"{(exact.name or '').strip()} — {(exact.municipality or '').strip()} ({(exact.province or '').strip()})".strip(), "score": 1.0, "photo_url": (getattr(exact, 'photo_url', None) or '').strip()}]
        if similar and not force_new:
            return jsonify({"error": "Parece que ya existe un recinto similar.", "similar": similar}), 409

        v = Venue(
            name=name,
            covered=covered,
            allows_bars=allows_bars,
            address=address,
            municipality=municipality,
            province=province,
            country=country,
            photo_url=photo_url,
        )
        session_db.add(v)
        session_db.commit()

        mun = (v.municipality or "").strip()
        prov = (v.province or "").strip()
        text_label = f"{v.name} — {mun} ({prov})".strip()
        if not mun and not prov:
            text_label = v.name
        elif mun and not prov:
            text_label = f"{v.name} — {mun}"
        elif not mun and prov:
            text_label = f"{v.name} ({prov})"

        return jsonify({
            "id": str(v.id),
            "name": (v.name or "").strip(),
            "municipality": mun,
            "province": prov,
            "country": (v.country or "").strip(),
            "label": text_label,
            "text": text_label,
            "photo_url": (v.photo_url or ""),
            "logo_url": (v.photo_url or ""),
            "allows_bars": bool(v.allows_bars),
        })

    except Exception as e:
        session_db.rollback()
        return jsonify({"error": str(e)}), 400

    finally:
        session_db.close()

PROMOTER_SOCIAL_PLATFORMS = [
    ("instagram", "Instagram", "fa-instagram"),
    ("tiktok", "TikTok", "fa-tiktok"),
    ("twitter", "X (Twitter)", "fa-x-twitter"),
    ("facebook", "Facebook", "fa-facebook"),
    ("youtube", "YouTube", "fa-youtube"),
]


def _promoter_social_links_from_form(form) -> dict:
    """Recoge las redes sociales (opcionales) del tercero desde el formulario (name="social_<red>")."""
    out = {}
    for key, _label, _icon in PROMOTER_SOCIAL_PLATFORMS:
        val = (form.get("social_" + key) or "").strip()
        if val:
            out[key] = val
    return out


@app.post("/api/promoters/create", endpoint="api_create_promoter")
@admin_required
def api_create_promoter():
    session = db()
    try:
        nick = (request.form.get("nick") or "").strip()
        contact_email = (request.form.get("contact_email") or "").strip()
        if not nick:
            return jsonify({"error": "El nick del tercero es obligatorio."}), 400
        force_new = _truthy(request.form.get("force_new"))
        rows = []
        for row in session.query(Promoter).order_by(Promoter.nick.asc()).all():
            rows.append({
                "id": str(row.id),
                "label": (row.nick or '').strip(),
                "logo_url": (row.logo_url or '').strip(),
            })
        similar = _build_similarity_rows(nick, rows, threshold=0.76)
        exact = session.query(Promoter).filter(func.lower(Promoter.nick) == nick.lower()).first()
        if exact and not force_new:
            similar = [{"id": str(exact.id), "label": (exact.nick or '').strip(), "score": 1.0, "logo_url": (exact.logo_url or '').strip()}]
        if similar and not force_new:
            return jsonify({"error": "Ya existe un tercero similar.", "similar": similar}), 409

        logo = request.files.get("logo") or request.files.get("photo")
        logo_url = upload_image(logo, "promoters") if logo and getattr(logo, "filename", "") else None

        kind = (request.form.get("kind") or "").strip().lower()
        if kind not in ("empresa", "institucion"):
            kind = None

        p = Promoter(
            nick=nick,
            logo_url=logo_url,
            tax_id=(request.form.get("tax_id") or "").strip() or None,
            contact_email=contact_email or None,
            contact_phone=(request.form.get("contact_phone") or "").strip() or None,
            kind=kind,
            social_links=_promoter_social_links_from_form(request.form),
        )
        session.add(p)
        session.flush()
        linked_embargos = _auto_link_embargo_orders_for_promoter(session, p) if "_auto_link_embargo_orders_for_promoter" in globals() else 0
        session.commit()
        return jsonify(
            {
                "id": str(p.id),
                "nick": p.nick,
                "label": p.nick,
                "text": p.nick,
                "logo_url": p.logo_url,
                "tax_id": (p.tax_id or ""),
                "contact_email": (p.contact_email or ""),
                "contact_phone": (p.contact_phone or ""),
                "kind": (p.kind or ""),
                "social_links": (p.social_links or {}),
                "companies": [],
                "active_embargos_linked": linked_embargos,
            }
        )

    except Exception as e:
        session.rollback()
        return jsonify({"error": str(e)}), 400

    finally:
        session.close()

