# ----------- API: crear Artista (modal) -----------

@app.post("/api/artists/create", endpoint="api_create_artist")
@admin_required
def api_create_artist():
    session = db()
    try:
        name = (request.form.get("name") or "").strip()
        if not name:
            return jsonify({"error": "El nombre del artista es obligatorio."}), 400

        force_new = _truthy(request.form.get("force_new"))
        rows = []
        for row in session.query(Artist).order_by(Artist.name.asc()).all():
            rows.append({"id": str(row.id), "label": (row.name or '').strip(), "photo_url": (row.photo_url or '').strip()})
        exact = session.query(Artist).filter(func.lower(Artist.name) == name.lower()).first()
        similar = _build_similarity_rows(name, rows, threshold=0.78)
        if exact and not force_new:
            similar = [{"id": str(exact.id), "label": (exact.name or '').strip(), "score": 1.0, "photo_url": (exact.photo_url or '').strip()}]
        if similar and not force_new:
            return jsonify({"error": "Ya existe un artista similar.", "similar": similar}), 409

        photo = request.files.get("photo")
        photo_url = upload_png(photo, "artists") if photo and getattr(photo, "filename", "") else None

        a = Artist(
            name=name, photo_url=photo_url,
            is_international=_truthy(request.form.get("is_international")),
            is_group=_truthy(request.form.get("is_group")),
            birth_date=parse_optional_date(request.form.get("birth_date")),
        )
        session.add(a)
        session.commit()
        return jsonify({
            "id": str(a.id), "label": a.name, "text": a.name, "name": a.name,
            "photo_url": a.photo_url, "is_international": bool(a.is_international),
            "is_group": bool(a.is_group),
        })

    except Exception as e:
        session.rollback()
        return jsonify({"error": str(e)}), 400

    finally:
        session.close()

# ----------- API: cambio rápido de estado (vista conciertos) -----------



# ----------- API: cambio rápido de estado (vista conciertos) -----------

@app.post("/conciertos/<cid>/status", endpoint="concert_quick_status")
@admin_required
def concert_quick_status(cid):
    session = db()
    try:
        c = session.get(Concert, to_uuid(cid))
        if not c:
            return jsonify({"error": "not found"}), 404

        new_status = request.form.get("status")
        if not new_status and request.is_json:
            payload = request.get_json(silent=True) or {}
            new_status = payload.get("status")

        # COMPUERTA: no se confirma una actividad sin habérsela comunicado al artista.
        puerta = _concert_notice_gate(session, c, _norm_status(new_status))
        if puerta:
            # `can_ack`/`ack_url` solo vienen si la actividad YA HA PASADO: entonces el cliente ofrece
            # además «el artista ya fue informado», que apunta el aviso y sigue con el estado.
            return jsonify({"ok": False, "error": puerta["reason"],
                            "needs_artist_notice": True,
                            "can_ack": bool(puerta.get("can_ack")),
                            "ack_url": puerta.get("ack_url") or "",
                            "status": _norm_status(new_status),
                            "notify_url": puerta["notify_url"]}), 409

        c.status = _norm_status(new_status)
        if c.status in {"RESERVADO", "CONFIRMADO"}:
            _ensure_production_request_for_concert(session, c)
        # Al CONFIRMAR una actividad que no es de un artista de la casa (un evento, o una fecha de
        # gira comprada que promueve una empresa nuestra) hay que decir quién de producción se
        # encarga: el cliente abre el selector con lo que se devuelve aquí.
        pedir_responsable = False
        if c.status == "CONFIRMADO" and not getattr(c, "production_owner_user_id", None):
            try:
                pedir_responsable = _concert_needs_production_owner(session, c)
            except Exception:
                pedir_responsable = False
        session.commit()
        return jsonify({"ok": True, "status": c.status, "needs_production_owner": pedir_responsable})

    except Exception as e:
        session.rollback()
        return jsonify({"error": str(e)}), 400

    finally:
        session.close()


# --------- ANUNCIO y SALIDA A LA VENTA: se cambian PINCHANDO su etiqueta en la cabecera ----------
# Son dos datos que se consultan y se cambian todo el rato, así que tienen su propia acción en vez de
# obligar a abrir la sección y guardar la ficha entera.
# ⚠️ NO se pasa por `concert_section_update`: la sección «datos» exige la fecha de salida a la venta
# (revienta con ValueError si llega vacía) y la sección «entradas» BORRA toda la configuración de
# venta si no le llega `entry_mode`. Aquí se escriben solo las dos columnas que toca.
@app.post("/conciertos/<cid>/anuncio", endpoint="concert_announcement_set")
@admin_required
def concert_announcement_set(cid):
    """Anuncio de la actividad: anunciado (hoy), no anunciar, o la fecha en que se anuncia."""
    if not can_edit_concerts():
        return forbid("No tienes permisos para editar actividades.")
    next_url = safe_next_or(request.form.get("next") or url_for("concert_detail_view", cid=cid, tab="general"))
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(cid) or uuid.uuid4())
        if concert is None:
            flash("Actividad no encontrada.", "warning")
            return redirect(next_url)
        modo = (request.form.get("mode") or "").strip().upper()
        if modo == "NONE":
            concert.do_not_announce = True
            concert.announcement_date = None
            aviso = "Esta actividad no se anuncia."
        elif modo == "DONE":
            concert.do_not_announce = False
            # «Anunciado» sin fecha guardada = se anunció hoy (la fecha anterior se conserva si ya
            # había pasado: lo que se anunció ayer no se anunció hoy).
            if not (concert.announcement_date and concert.announcement_date <= today_local()):
                concert.announcement_date = today_local()
            aviso = "Anunciado."
        elif modo == "DATE":
            fecha = parse_optional_date(request.form.get("announcement_date"))
            if not fecha:
                flash("Esa fecha de anuncio no vale.", "warning")
                return redirect(next_url)
            concert.do_not_announce = False
            concert.announcement_date = fecha
            aviso = "Se anuncia el %s." % fecha.strftime("%d/%m/%Y")
        else:
            flash("No se ha entendido qué hacer con el anuncio.", "warning")
            return redirect(next_url)
        concert.updated_at = _now_madrid()
        session_db.commit()
        flash(aviso, "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo cambiar el anuncio: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(next_url)


@app.post("/conciertos/<cid>/salida-venta", endpoint="concert_onsale_set")
@admin_required
def concert_onsale_set(cid):
    """Salida a la venta: ya está a la venta (hoy), por confirmar, o el día (y la HORA) en que sale.

    Lo hace TICKETING, así que el permiso es `can_set_concert_onsale` y no el de editar la
    actividad. La HORA es la que sale en el aviso de la salida a la venta."""
    if not can_set_concert_onsale():
        return forbid("No tienes permisos para cambiar la salida a la venta.")
    next_url = safe_next_or(request.form.get("next") or url_for("concert_detail_view", cid=cid, tab="general"))
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(cid) or uuid.uuid4())
        if concert is None:
            flash("Actividad no encontrada.", "warning")
            return redirect(next_url)
        modo = (request.form.get("mode") or "").strip().upper()
        # La HORA de salida a la venta (opcional): se guarda igual en «a la venta» y en «sale el día».
        hora = (request.form.get("sale_start_time") or "").strip()[:5]
        if modo == "TBC":
            concert.sale_start_tbc = True
            concert.sale_start_date = None
            aviso = "Salida a la venta por confirmar."
        elif modo == "NOW":
            concert.sale_start_tbc = False
            if not (concert.sale_start_date and concert.sale_start_date <= today_local()):
                concert.sale_start_date = today_local()
            aviso = "A la venta."
        elif modo == "DATE":
            fecha = parse_optional_date(request.form.get("sale_start_date"))
            if not fecha:
                flash("Esa fecha de salida a la venta no vale.", "warning")
                return redirect(next_url)
            concert.sale_start_tbc = False
            concert.sale_start_date = fecha
            aviso = "Sale a la venta el %s." % fecha.strftime("%d/%m/%Y")
        else:
            flash("No se ha entendido qué hacer con la salida a la venta.", "warning")
            return redirect(next_url)
        if hora:
            concert.sale_start_time = hora
        concert.updated_at = _now_madrid()
        # Ya tiene fecha: el aviso de «sacar a la venta» está hecho y se cierra solo. Lo que queda es
        # NOTIFICAR la salida, que es la otra tarea de Ticketing.
        if concert.sale_start_date:
            _notify_resolve(session_db, "CONCERT_SALE", str(concert.id))
        session_db.commit()
        flash(aviso, "success")
        if concert.sale_start_date and not getattr(concert, "sale_notice_at", None):
            flash("Falta comunicar la salida a la venta.", "warning")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo cambiar la salida a la venta: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(next_url)


