@app.route("/empresas", methods=["GET", "POST"])
@admin_required
def companies_view():
    session = db()

    # filtros (solo para vista)
    f_artist_ids = request.args.getlist("artist") or []
    f_sale_types = request.args.getlist("type") or []
    f_statuses = request.args.getlist("status") or []

    f_artist_ids = [to_uuid(x) for x in f_artist_ids if (x or "").strip()]
    f_sale_types = [(x or "").strip().upper() for x in f_sale_types if (x or "").strip()]
    f_statuses = [(x or "").strip().upper() for x in f_statuses if (x or "").strip()]

    # sanitizar
    f_sale_types = [x for x in f_sale_types if x in CONCERT_SALE_TYPES_ALL_SET]
    f_statuses = [x for x in f_statuses if x in ("BORRADOR", "HABLADO", "RESERVADO", "CONFIRMADO")]

    if request.method == "POST":
        name = request.form.get("name","").strip()
        tax_info = request.form.get("tax_info","").strip()
        logo = request.files.get("logo")
        try:
            logo_url = upload_png(logo, "companies") if logo else None
            co = GroupCompany(name=name, tax_info=tax_info, logo_url=logo_url)
            session.add(co)
            session.commit()
            flash("Empresa creada.", "success")
        except Exception as e:
            session.rollback()
            flash(f"Error creando empresa: {e}", "danger")
        finally:
            session.close()
        return redirect(url_for("companies_view"))
    companies = session.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    # Resumen de documentación por empresa (para la pastilla de «caducados» del listado).
    doc_summary = {}
    try:
        for co in companies:
            rows = _company_doc_rows(session, co.id)
            doc_summary[str(co.id)] = {
                "total": len(rows),
                "expired": len([r for r in rows if r["state"] == "EXPIRED"]),
            }
    except Exception:
        doc_summary = {}
    session.close()
    return render_template("companies.html", companies=companies, COMPANY_DOC_SUMMARY=doc_summary)

@app.post("/empresas/<cid>/update")
@admin_required
def company_update(cid):
    session = db()
    co = session.get(GroupCompany, to_uuid(cid))
    if not co:
        flash("Empresa no encontrada.", "warning")
        session.close(); return redirect(url_for("companies_view"))
    co.name = request.form.get("name", co.name).strip()
    co.tax_info = request.form.get("tax_info", co.tax_info or "").strip()
    # NOMBRE ABREVIADO PARA EL SMS: es lo que ve en el móvil quien recibe un envío de esta empresa.
    # ⚠️ Se valida con `sms_utils.sender_is_valid`, el MISMO límite que el remitente de
    # Integraciones → SMS (11 caracteres y sin símbolos raros): si no, la pasarela lo rechaza.
    # ⚠️ Y se puede dejar VACÍO a propósito (en España un remitente con letras hay que registrarlo;
    # sin él, el SMS sale con el número de la pasarela).
    if "sms_sender" in request.form:
        remitente = (request.form.get("sms_sender") or "").strip()
        if not remitente:
            co.sms_sender = None
        else:
            valido, motivo = sms_utils.sender_is_valid(remitente)
            if valido:
                co.sms_sender = remitente
            else:
                flash("El nombre abreviado para SMS no vale: %s" % motivo, "warning")
    logo = request.files.get("logo")
    try:
        if logo and logo.filename:
            co.logo_url = upload_png(logo, "companies")
        session.commit()
        flash("Empresa actualizada.", "success")
    except Exception as e:
        session.rollback()
        flash(f"Error actualizando: {e}", "danger")
    finally:
        session.close()
    return redirect(url_for("companies_view"))

