@app.get("/api/search/autores", endpoint="api_search_authors")
@admin_required
def api_search_authors():
    """Buscador de AUTORES: terceros **y** integrantes de artistas.

    ⚠️ Un autor casi siempre es un integrante de un artista, y de ahí salen las condiciones de su
    contrato (editorial, royalties). Buscando solo en terceros, a quien estaba dado de alta como
    integrante y no como tercero había que crearlo otra vez —y esa ficha nueva, al no ser de ningún
    integrante, se quedaba sin contrato (bug real)—. Aquí salen los dos, y al elegir un integrante
    sin ficha se le crea la suya vinculada (`artist_person_id`)."""
    q = (request.args.get("q") or request.args.get("term") or "").strip()
    session = db()
    try:
        salida, vistos = [], set()

        def artista_de(promoter_id):
            ids = _promoter_member_artist_ids(session, promoter_id)
            if not ids:
                return None
            art = session.get(Artist, to_uuid(ids[0]) or uuid.uuid4())
            return art if (art is not None and not art.event_id) else None

        query = session.query(Promoter).options(joinedload(Promoter.publishing_company))
        clause = _promoter_search_clause(session, q)
        if clause is not None:
            query = query.filter(clause)
        for p in query.order_by(Promoter.nick.asc()).limit(20).all():
            art = artista_de(p.id)
            pub = p.publishing_company
            salida.append({
                "id": str(p.id),
                "label": _promoter_display_name(p) or (p.nick or "Sin nombre"),
                "first_name": (p.first_name or "").strip(),
                "last_name": (p.last_name or "").strip(),
                "publishing_company_id": str(pub.id) if pub else "",
                "publishing_company_name": (pub.name or "") if pub else "",
                "logo_url": (p.logo_url or "") or _default_avatar_url(),
                "artist_name": (art.name if art is not None else ""),
                "sub": ("Integrante de " + art.name) if art is not None else (p.contact_email or "").strip(),
            })
            vistos.add(str(p.id))

        # Integrantes que TODAVÍA no tienen ficha de tercero: se les crea al elegirlos.
        if q:
            try:
                cond = _sa_contains_text(
                    func.concat(func.coalesce(ArtistPerson.first_name, ""), " ",
                                func.coalesce(ArtistPerson.last_name, "")), q)
                for person in (session.query(ArtistPerson)
                               .options(joinedload(ArtistPerson.artist))
                               .filter(cond).limit(20).all()):
                    if person.promoter_id and str(person.promoter_id) in vistos:
                        continue
                    if person.promoter_id:
                        continue                     # ya está arriba (o no casa la búsqueda): no se repite
                    art = getattr(person, "artist", None)
                    if art is not None and art.event_id:
                        continue
                    salida.append({
                        "id": "",
                        "artist_person_id": str(person.id),
                        "label": _artist_person_full_name(person) or "Sin nombre",
                        "first_name": (person.first_name or "").strip(),
                        "last_name": (person.last_name or "").strip(),
                        "publishing_company_id": "", "publishing_company_name": "",
                        "logo_url": (getattr(art, "photo_url", "") or "") or _default_avatar_url(),
                        "artist_name": (art.name if art is not None else ""),
                        "sub": ("Integrante de " + art.name) if art is not None else "Integrante",
                    })
            except Exception:
                app.logger.exception("Buscador de autores: fallo con los integrantes")
        return jsonify(salida[:25])
    finally:
        session.close()


@app.get("/api/vinculaciones/search", endpoint="api_entity_link_search")
@admin_required
def api_entity_link_search():
    entity_type = _entity_link_type(request.args.get("type"))
    q = (request.args.get("q") or request.args.get("term") or "").strip()
    session_db = db()
    try:
        if not entity_type:
            return jsonify([])
        rows = []
        # Excluir la propia ficha de los resultados (no autovincularse) cuando se busca en su misma
        # «familia» de modelo (p. ej. tercero/empresa/institución comparten la tabla de terceros).
        _fam = {"promoter": "P", "empresa": "P", "institucion": "P", "artist": "A", "media": "M",
                "venue": "V", "ticketer": "T", "publishing": "PUB", "personal": "U", "event": "EV"}
        _ex_id = _safe_uuid(request.args.get("exclude_id"))
        _ex_type = _entity_link_type(request.args.get("exclude_type"))
        _same_fam = bool(_ex_id) and _fam.get(entity_type) and _fam.get(entity_type) == _fam.get(_ex_type)
        if entity_type in ("promoter", "empresa", "institucion"):
            query = session_db.query(Promoter).options(joinedload(Promoter.publishing_company), selectinload(Promoter.companies))
            # "Tercero" muestra los terceros genéricos (sin clasificar); "Empresa"/"Institución"
            # muestran solo los terceros de ese tipo.
            if entity_type == "promoter":
                query = query.filter(or_(Promoter.kind.is_(None), Promoter.kind.notin_(["empresa", "institucion"])))
            else:
                query = query.filter(Promoter.kind == entity_type)
            _clause = _promoter_search_clause(session_db, q)
            if _clause is not None:
                query = query.filter(_clause)
            if _same_fam:
                query = query.filter(Promoter.id != _ex_id)
            for item in query.order_by(Promoter.nick.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, entity_type, item.id)
                if payload:
                    payload["link_summary"] = _promoter_link_summary(session_db, item)
                    rows.append(payload)
        elif entity_type == "artist":
            query = session_db.query(Artist)
            if q:
                query = query.filter(_sa_contains_text(Artist.name, q))
            if _same_fam:
                query = query.filter(Artist.id != _ex_id)
            for item in query.order_by(Artist.name.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "artist", item.id)
                if payload:
                    rows.append(payload)
        elif entity_type == "event":
            query = session_db.query(AppEvent)
            if q:
                query = query.filter(_sa_contains_text(AppEvent.name, q))
            if _same_fam:
                query = query.filter(AppEvent.id != _ex_id)
            for item in query.order_by(AppEvent.name.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "event", item.id)
                if payload:
                    rows.append(payload)
        elif entity_type == "media":
            query = session_db.query(MediaOutlet)
            if q:
                query = query.filter(_sa_contains_text(MediaOutlet.name, q) | _sa_contains_text(MediaOutlet.media_type, q) | _sa_contains_text(MediaOutlet.address, q) | _sa_contains_text(MediaOutlet.country_name, q))
            if _same_fam:
                query = query.filter(MediaOutlet.id != _ex_id)
            for item in query.order_by(MediaOutlet.name.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "media", item.id)
                if payload:
                    rows.append(payload)
        elif entity_type == "venue":
            query = session_db.query(Venue)
            if q:
                query = query.filter(_sa_contains_text(Venue.name, q) | _sa_contains_text(Venue.address, q) | _sa_contains_text(Venue.municipality, q) | _sa_contains_text(Venue.province, q))
            if _same_fam:
                query = query.filter(Venue.id != _ex_id)
            for item in query.order_by(Venue.name.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "venue", item.id)
                if payload:
                    rows.append(payload)
        elif entity_type == "ticketer":
            query = session_db.query(Ticketer)
            if q:
                query = query.filter(_sa_contains_text(Ticketer.name, q) | _sa_contains_text(Ticketer.link_url, q))
            if _same_fam:
                query = query.filter(Ticketer.id != _ex_id)
            for item in query.order_by(Ticketer.name.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "ticketer", item.id)
                if payload:
                    rows.append(payload)
        elif entity_type == "publishing":
            query = session_db.query(PublishingCompany)
            if q:
                query = query.filter(_sa_contains_text(PublishingCompany.name, q))
            if _same_fam:
                query = query.filter(PublishingCompany.id != _ex_id)
            for item in query.order_by(PublishingCompany.name.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "publishing", item.id)
                if payload:
                    rows.append(payload)
        elif entity_type == "personal":
            # Personal de la oficina (User + UserProfile). Solo el ACTUAL: ni eliminados ni bloqueados.
            query = session_db.query(User, UserProfile).outerjoin(UserProfile, UserProfile.user_id == User.id)
            _inactive = _inactive_user_ids(session_db)
            if _inactive:
                query = query.filter(~User.id.in_(list(_inactive)))
            if q:
                query = query.filter(or_(
                    _sa_contains_text(User.email, q),
                    _sa_contains_text(UserProfile.nick, q),
                    _sa_contains_text(UserProfile.first_name, q),
                    _sa_contains_text(UserProfile.last_name, q),
                ))
            if _same_fam:
                query = query.filter(User.id != _ex_id)
            for user, _profile in query.order_by(User.email.asc()).limit(30).all():
                payload = _entity_link_payload(session_db, "personal", user.id)
                if payload:
                    rows.append(payload)
        return jsonify(rows)
    finally:
        session_db.close()


@app.post("/api/media/create", endpoint="api_create_media_outlet")
@admin_required
def api_create_media_outlet():
    session_db = db()
    try:
        name = (request.form.get("name") or "").strip()
        media_type = (request.form.get("media_type") or "OTRO").strip().upper() or "OTRO"
        if not name:
            return jsonify({"error": "El nombre del medio es obligatorio."}), 400
        logo = request.files.get("logo") or request.files.get("photo")
        logo_url = upload_image(logo, "media_outlets") if logo and getattr(logo, "filename", "") else None
        country_code, country_name = _country_payload_from_form(request.form)
        existing = session_db.query(MediaOutlet).filter(func.lower(MediaOutlet.name) == name.lower(), MediaOutlet.media_type == media_type).first()
        if existing:
            payload = _entity_link_payload(session_db, "media", existing.id)
            return jsonify(payload or {"id": str(existing.id), "label": existing.name, "logo_url": existing.logo_url})
        row = MediaOutlet(name=name, media_type=media_type, logo_url=logo_url, country_code=country_code, country_name=country_name, address=(request.form.get("address") or "").strip() or None)
        session_db.add(row)
        session_db.commit()
        return jsonify(_entity_link_payload(session_db, "media", row.id))
    except Exception as exc:
        session_db.rollback()
        return jsonify({"error": str(exc)}), 400
    finally:
        session_db.close()


def _media_contact_row(c) -> dict:
    name = " ".join([x for x in [(c.first_name or "").strip(), (c.last_name or "").strip()] if x]).strip()
    return {
        "id": str(c.id),
        "name": name or (c.program or "Contacto"),
        "role": (c.role or c.program or "").strip(),
        "phone": (c.phone or "").strip(),
        "email": (c.email or "").strip(),
    }


