# =========================
# CUADRANTES
# =========================

MONTHS_ES = [
    "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
    "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
]
DOW_ES = ["L", "M", "X", "J", "V", "S", "D"]  # lunes..domingo


def _build_year_calendar(year: int):
    """Estructura de 12 meses con semanas (monthdayscalendar)."""
    cal = _cal.Calendar(firstweekday=0)  # 0 = lunes
    months = []
    for m in range(1, 13):
        months.append({
            "num": m,
            "name": MONTHS_ES[m - 1],
            "weeks": cal.monthdayscalendar(year, m),  # list[list[int]] con 0 para padding
        })
    return months


def _table_exists(session_db, full_name: str) -> bool:
    """
    full_name ejemplo: 'public.concert_caches'
    """
    try:
        r = session_db.execute(text("select to_regclass(:t)"), {"t": full_name}).scalar()
        return r is not None
    except Exception:
        return False


def _cache_summary(cache_rows: list) -> str:
    """
    Devuelve un resumen cortito de cachés para el cuadrante.
    Si no hay tabla cachés o no hay datos: '—'
    """
    if not cache_rows:
        return "—"

    parts = []
    for r in cache_rows:
        # amount
        if getattr(r, "amount", None) not in (None, ""):
            try:
                parts.append(f"{float(r.amount):g}€")
            except Exception:
                parts.append(f"{r.amount}€")
            continue

        # pct
        if getattr(r, "pct", None) not in (None, ""):
            try:
                parts.append(f"{float(r.pct):g}%")
            except Exception:
                parts.append(f"{r.pct}%")
            continue

        # concept / kind
        if getattr(r, "concept", None):
            parts.append(str(r.concept))
        elif getattr(r, "kind", None):
            parts.append(str(r.kind))

    if not parts:
        return "—"

    if len(parts) > 3:
        return " + ".join(parts[:3]) + f" (+{len(parts) - 3})"
    return " + ".join(parts)


def _cache_amount_total(cache_rows: list) -> float:
    """Suma de los importes fijos de caché de una actividad (para 'Caché total')."""
    total = 0.0
    for r in (cache_rows or []):
        amt = getattr(r, "amount", None)
        if amt in (None, ""):
            continue
        try:
            total += float(amt)
        except Exception:
            pass
    return total


# ============ Límite de facturación por empresa del grupo y año ============
# Aviso al crear una actividad con caché: si la empresa que factura ya tiene comprometidos
# 3.500.000 € ese año (o se acerca), hay que verlo ANTES de cerrar la fecha, con la opción de
# cambiar de empresa. El «previsto» es la suma de los cachés fijos de sus actividades del año
# (incluidas las que están en borrador: es justo lo que hay comprometido).
COMPANY_BILLING_LIMIT = Decimal("3500000")
COMPANY_BILLING_WARN_MARGIN = Decimal("200000")


def _company_year_billing_forecast(session_db, company_id, year: int) -> Decimal:
    """Facturación PREVISTA de una empresa del grupo en un año: la suma de TODOS los cachés de sus
    actividades (fijos y variables con importe), que es lo que se contrasta con el límite."""
    if not company_id or not year:
        return Decimal("0")
    rows = (
        session_db.query(ConcertCache.amount)
        .join(Concert, Concert.id == ConcertCache.concert_id)
        .filter(Concert.billing_company_id == company_id)
        .filter(func.extract("year", Concert.date) == year)
        .all()
    )
    total = Decimal("0")
    for (amount,) in rows:
        if amount in (None, ""):
            continue
        try:
            total += Decimal(str(amount))
        except Exception:
            pass
    return total


def _company_billing_limit_state(session_db, company_id, year: int, extra=Decimal("0")) -> dict:
    """Estado del límite para una empresa y año, contando además el caché que se va a añadir."""
    company = session_db.get(GroupCompany, company_id) if company_id else None
    if not company or not year:
        return {"state": "ok", "total": 0.0, "limit": float(COMPANY_BILLING_LIMIT), "company": ""}
    extra = extra if isinstance(extra, Decimal) else Decimal(str(extra or 0))
    total = _company_year_billing_forecast(session_db, company.id, year) + extra
    if total >= COMPANY_BILLING_LIMIT:
        state = "over"
    elif total >= (COMPANY_BILLING_LIMIT - COMPANY_BILLING_WARN_MARGIN):
        state = "near"
    else:
        state = "ok"
    return {
        "state": state,
        "total": float(total),
        "limit": float(COMPANY_BILLING_LIMIT),
        "remaining": float(max(COMPANY_BILLING_LIMIT - total, Decimal("0"))),
        "company": company.name or "",
        "year": year,
    }


@app.get("/api/empresas/<company_id>/limite-facturacion", endpoint="api_company_billing_limit")
@admin_required
def api_company_billing_limit(company_id):
    """¿La empresa que factura se pasa (o se acerca) del límite anual con este caché?"""
    try:
        year = int((request.args.get("year") or "").strip() or today_local().year)
    except Exception:
        year = today_local().year
    extra = _money_or_zero(request.args.get("extra") or 0)
    session_db = db()
    try:
        return jsonify(_company_billing_limit_state(session_db, to_uuid(company_id) if company_id else None, year, extra))
    finally:
        session_db.close()


def _promoter_display(concert: Concert):
    """Promotora/empresa principal visible en cuadrantes."""
    if getattr(concert, "promoter", None):
        return (
            getattr(concert.promoter, "logo_url", None),
            getattr(concert.promoter, "nick", None),
        )
    if getattr(concert, "billing_company", None):
        return (
            getattr(concert.billing_company, "logo_url", None),
            getattr(concert.billing_company, "name", None),
        )
    if getattr(concert, "group_company", None):
        return (
            getattr(concert.group_company, "logo_url", None),
            getattr(concert.group_company, "name", None),
        )
    return (None, None)


@app.get("/api/geocode")
@admin_required
def api_geocode():
    """
    Geocoding server-side (Nominatim) para evitar CORS en el navegador.
    Devuelve lat/lng aproximados para (city, province).
    """
    city = (request.args.get("city") or "").strip()
    province = (request.args.get("province") or "").strip()

    if not city:
        return jsonify({"ok": False, "error": "city is required"}), 400

    q = f"{city}, {province}, España" if province else f"{city}, España"
    url = "https://nominatim.openstreetmap.org/search?format=json&limit=1&q=" + quote_plus(q)

    try:
        req = Request(url, headers={
            "User-Agent": "radio-spins-app/1.0 (cuadrantes)"
        })
        with urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read().decode("utf-8"))

        if not data:
            return jsonify({"ok": False, "error": "not found"}), 404

        lat = float(data[0]["lat"])
        lng = float(data[0]["lon"])
        return jsonify({"ok": True, "lat": lat, "lng": lng})

    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


def _quadrantes_effective_sale_type(concert) -> str:
    """Tipo usado en cuadrantes, tolerante con actividades antiguas o creadas desde +Actividad.

    Algunos registros creados por el asistente guardan principalmente
    ``activity_type``/``activity_subtype`` y dejan ``sale_type`` vacío o con una
    etiqueta no incluida en los filtros clásicos. Si filtramos en SQL por
    ``sale_type`` esos conciertos desaparecen. Además, algunas versiones antiguas
    guardaron valores singulares o alias visuales; los normalizamos aquí.
    """
    aliases = {
        "PARTICIPADO": "PARTICIPADOS",
        "PARTICIPADA": "PARTICIPADOS",
        "CONCIERTO_PARTICIPADO": "PARTICIPADOS",
        "GIRA_COMPRADA": "GIRAS_COMPRADAS",
        "GIRA": "GIRAS_COMPRADAS",
        "FESTIVAL": "CADIZ",
        "CICLO": "CADIZ",
        "CADIZ_MUSIC_STADIUM": "CADIZ",
        "CÁDIZ MUSIC STADIUM": "CADIZ",
        "CONCIERTO_EMPRESA": "EMPRESA",
        "EMPRESAS": "EMPRESA",
        "VENDIDOS": "VENDIDO",
    }

    def norm(value):
        value = (value or "").strip().upper()
        return aliases.get(value, value)

    sale_type = norm(getattr(concert, "sale_type", None))
    if sale_type in CONCERT_SALE_TYPES_ALL_SET:
        return sale_type
    subtype = norm(getattr(concert, "activity_subtype", None))
    if subtype in CONCERT_SALE_TYPES_ALL_SET:
        return subtype
    activity = norm(getattr(concert, "activity_type", None))
    if activity in CONCERT_SALE_TYPES_ALL_SET:
        return activity
    if activity == "CONCIERTO" or not activity:
        return "EMPRESA" if sale_type == "" else sale_type
    return sale_type or activity


def _concert_participant_artist_ids(concert) -> set[str]:
    """Devuelve todos los artistas vinculados a un concierto/actividad.

    Mantiene compatibilidad con el campo histórico ``artist_id`` y con el nuevo
    ``artist_ids`` JSONB de actividades multiarista para que cuadrantes no oculte
    conciertos cuando el artista seleccionado no es el artista principal.
    """
    ids: set[str] = set()
    try:
        if getattr(concert, "artist_id", None):
            ids.add(str(concert.artist_id))
    except Exception:
        pass
    raw = getattr(concert, "artist_ids", None) or []
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = [raw]
    if isinstance(raw, (list, tuple, set)):
        for val in raw:
            if not val:
                continue
            if isinstance(val, dict):
                val = val.get("id") or val.get("artist_id")
            if val:
                ids.add(str(val))
    return {x for x in ids if x}


def _concert_show_format(concert) -> str:
    """Formato del show (Banda completa, Acústico, DJ set…).

    Se toma de la ficha de contratación (``ConcertContractSheet``), que es donde
    Producción registra el ``show_format``; primero de los datos consolidados y,
    si no, del payload de la petición.
    """
    sheet = getattr(concert, "contract_sheet", None)
    if not sheet:
        return ""
    for src in (getattr(sheet, "data", None), getattr(sheet, "request_payload", None)):
        if isinstance(src, dict):
            val = (src.get("show_format") or "").strip()
            if val:
                return val
    return ""


def _concert_schedule_label(concert) -> str:
    """Horario legible: 'Apertura HH:MM · Show HH:MM' (tolerante a TBC/vacíos)."""
    doors = (getattr(concert, "doors_time", None) or "").strip()
    show = (getattr(concert, "show_time", None) or "").strip()
    if not doors and getattr(concert, "doors_time_tbc", False):
        doors = "TBC"
    if not show and getattr(concert, "show_time_tbc", False):
        show = "TBC"
    parts = []
    if doors:
        parts.append(f"Apertura {doors}")
    if show:
        parts.append(f"Show {show}")
    return " · ".join(parts)


# Concepto (tipo de actividad) de cuadrantes: se filtra por CONCIERTO / FESTIVAL /
# EVENTO_PROMOCIONAL / TV / MARCA / OTROS. El "Tipo" (venta: empresa/gratuito/…) es
# un segundo nivel que solo aplica cuando la actividad tiene un sale_type real.
QUAD_ACTIVITY_CHOICES = [
    ("CONCIERTO", "Concierto", "fa-guitar"),
    ("FESTIVAL", "Festival", "fa-star"),
    ("EVENTO_PROMOCIONAL", "Evento promocional", "fa-bullhorn"),
    ("TV", "Programa de TV", "fa-tv"),
    ("MARCA", "Acción con marca", "fa-tags"),
    ("ENSAYO", "Ensayos", "fa-drum"),
    # DISCOGRÁFICAS: todo lo que hace el artista para el sello (antes «acciones»). Son actividades
    # como las demás: tienen su ficha, su hoja de ruta, su bolsa y su producción.
    ("DISC_PREMIOS", "Premios", "fa-trophy"),
    ("DISC_FIRMA", "Firma de discos", "fa-pen-fancy"),
    ("DISC_AUDIO", "Grabación de audio", "fa-microphone-lines"),
    ("DISC_VIDEO", "Grabación de vídeo", "fa-video"),
    ("DISC_FOTOS", "Sesión de fotos", "fa-camera-retro"),
    ("DISC_COMPOSICION", "Sesión de composición", "fa-pen-nib"),
    ("DISC_REUNION", "Reunión", "fa-users"),
    ("OTROS", "Otros", "fa-calendar-day"),
]
# Las DISCOGRÁFICAS se eligen dentro de su propia tarjeta en el asistente.
DISCOGRAFICA_ACTIVITY_TYPES = ["DISC_PREMIOS", "DISC_FIRMA", "DISC_AUDIO", "DISC_VIDEO",
                              "DISC_FOTOS", "DISC_COMPOSICION", "DISC_REUNION"]
# Tipos que NO son de contratación (no se venden ni tienen promotor): el asistente les hace las
# preguntas cortas (nombre, días, sitio, qué tiene que hacer, caché y logística).
SIMPLE_ACTIVITY_TYPES = ["ENSAYO"] + DISCOGRAFICA_ACTIVITY_TYPES
# ¿Canta el artista? Solo se pregunta donde tiene sentido.
SINGING_ACTIVITY_TYPES = ["DISC_PREMIOS", "DISC_FIRMA"]
# Las actividades PROMOCIONALES (no de contratación, pero con promotor y entradas).
PROMO_LIKE_ACTIVITY_TYPES = ("EVENTO_PROMOCIONAL", "TV", "MARCA", "OTROS")


def _activity_has_performance_detail(activity_type) -> bool:
    """¿A esta actividad se le pregunta QUÉ TIENE QUE HACER el artista?

    (la descripción, si canta, el repertorio y la formación).
    ⚠️ El asistente enseña ese panel también en los ENSAYOS y en las DISCOGRÁFICAS, pero el servidor
    solo lo guardaba en las promocionales: en una firma de discos o en unos premios se tiraba a la
    basura lo de «canta», las canciones y la formación (bug real, lo destapó el aviso al artista)."""
    tipo = (activity_type or "").strip().upper()
    return tipo in PROMO_LIKE_ACTIVITY_TYPES or tipo in set(SIMPLE_ACTIVITY_TYPES)
QUAD_ACTIVITY_LABELS = {k: l for k, l, _i in QUAD_ACTIVITY_CHOICES}
QUAD_ACTIVITY_ICONS = {k: i for k, _l, i in QUAD_ACTIVITY_CHOICES}
QUAD_ACTIVITY_ALIASES = {
    "CONCIERTO": "CONCIERTO",
    "FESTIVAL": "FESTIVAL", "CADIZ": "FESTIVAL", "CICLO": "FESTIVAL",
    "EVENTO_PROMOCIONAL": "EVENTO_PROMOCIONAL", "PROMOCIONAL": "EVENTO_PROMOCIONAL", "PROMOCION": "EVENTO_PROMOCIONAL",
    "TV": "TV", "PROGRAMA_TV": "TV",
    "MARCA": "MARCA", "ACCION_MARCA": "MARCA",
    "GIRA": "CONCIERTO", "GIRA_COMPRADA": "CONCIERTO", "GIRAS_COMPRADAS": "CONCIERTO",
    "ENSAYO": "ENSAYO", "ENSAYOS": "ENSAYO",
    "DISC_PREMIOS": "DISC_PREMIOS", "PREMIOS": "DISC_PREMIOS",
    "DISC_FIRMA": "DISC_FIRMA", "FIRMA_DISCOS": "DISC_FIRMA",
    "DISC_AUDIO": "DISC_AUDIO", "GRABACION_AUDIO": "DISC_AUDIO",
    "DISC_VIDEO": "DISC_VIDEO", "GRABACION_VIDEO": "DISC_VIDEO",
    "DISC_FOTOS": "DISC_FOTOS", "SESION_FOTOS": "DISC_FOTOS",
    "DISC_COMPOSICION": "DISC_COMPOSICION", "SESION_COMPOSICION": "DISC_COMPOSICION",
    "DISC_REUNION": "DISC_REUNION", "REUNION": "DISC_REUNION",
    "OTROS": "OTROS",
}
# Para el recuento de las pastillas: qué conceptos cuentan como "concierto" (vs
# "actividad" no concierto: evento promocional / TV / marca / otros).
QUAD_CONCERT_CONCEPTS = {"CONCIERTO", "FESTIVAL"}
# Tipos que viven en «Otras actividades» (los que NO son un concierto). Un evento promocional es un
# evento promocional: aquí se filtra por lo que ES cada actividad, no por cómo se vende.
OTHER_ACTIVITY_TYPE_KEYS = (["EVENTO_PROMOCIONAL", "TV", "MARCA"]
                            + ["ENSAYO"] + DISCOGRAFICA_ACTIVITY_TYPES + ["OTROS"])
# Etiquetas de tipo de la sección ACTIVIDADES (todo lo que hay: los tipos de actividad + acciones).
# Las «acciones» de antes se han fusionado en actividades: la etiqueta ACCION se conserva para las
# `CompanyAction` que ya existían (siguen saliendo en el listado con su icono).
ACTIVITIES_TYPE_KEYS = ["CONCIERTO", "FESTIVAL"] + OTHER_ACTIVITY_TYPE_KEYS + ["ACCION"]


def _concert_activity_concept(concert) -> str:
    """Normaliza ``activity_type`` a uno de los conceptos de cuadrantes.

    Por defecto CONCIERTO (para actividades antiguas sin ``activity_type``).
    """
    raw = (getattr(concert, "activity_type", None) or "").strip().upper()
    return QUAD_ACTIVITY_ALIASES.get(raw, "CONCIERTO")


@app.get("/cuadrantes", endpoint="quadrantes_view")
@admin_required
def quadrantes_view():
    """Vista Cuadrantes."""
    session_db = db()
    try:
        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
        all_concert_tags = _collect_all_concert_tags(session_db)
        type_choices = [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER]

        raw_ids = request.args.getlist("artist_id")
        selected_uuids = []
        for rid in raw_ids:
            try:
                u = to_uuid(rid)
                if u:
                    selected_uuids.append(u)
            except Exception:
                pass

        concert_tags_by_artist = defaultdict(list)
        tag_rows = (
            session_db.query(Concert)
            .filter(or_(Concert.artist_id.isnot(None), Concert.artist_ids.isnot(None)))
            .all()
        )
        for tag_concert in tag_rows:
            raw_tags = tag_concert.hashtags
            values = []
            if isinstance(raw_tags, list):
                values = [x for x in raw_tags if x]
            elif isinstance(raw_tags, str):
                values = [x for x in raw_tags.split(',') if x]
            clean_values = _dedupe_concert_tags(values)
            if not clean_values:
                continue
            for artist_id in _concert_participant_artist_ids(tag_concert):
                concert_tags_by_artist[str(artist_id)].extend(clean_values)
        concert_tags_by_artist = {
            key: sorted(_dedupe_concert_tags(values), key=lambda x: _norm_text_key(x))
            for key, values in concert_tags_by_artist.items()
        }
        available_concert_tags = sorted(
            _dedupe_concert_tags([tag for sid in selected_uuids for tag in concert_tags_by_artist.get(str(sid), [])]),
            key=lambda x: _norm_text_key(x),
        ) if selected_uuids else []

        years_rows = (
            session_db.query(func.extract("year", Concert.date))
            .distinct()
            .order_by(func.extract("year", Concert.date))
            .all()
        )
        year_options = sorted({int(r[0]) for r in years_rows if r and r[0] is not None})
        if not year_options:
            year_options = [today_local().year]

        # AÑO(S): el selector admite varios, para sacar un cuadrante que cruce el cambio de año
        # (p. ej. una gira de octubre a marzo). Sin nada elegido, el año en curso.
        years = []
        for raw in request.args.getlist("year"):
            try:
                y = int((raw or "").strip())
            except Exception:
                continue
            if 1900 <= y <= 2999 and y not in years:
                years.append(y)
        years.sort()
        if not years:
            years = [today_local().year]
        year = years[0]  # año «principal»: nombre del PDF y compatibilidad de plantilla

        # CUÁNDO: por defecto TODO el periodo; se puede acotar a lo ya celebrado o a lo que viene.
        when = (request.args.get("when") or "all").strip().lower()
        if when not in ("all", "past", "future"):
            when = "all"

        calendar_years = [{"year": y, "months": _build_year_calendar(y)} for y in years]
        months = calendar_years[0]["months"]  # compatibilidad
        years_label = " · ".join(str(y) for y in years)
        period_label = years_label + {"past": " · pasadas", "future": " · próximas"}.get(when, "")

        allowed_status = {"BORRADOR", "HABLADO", "RESERVADO", "CONFIRMADO"}
        f_statuses = [s for s in request.args.getlist("status") if s in allowed_status]
        if not f_statuses:
            f_statuses = ["BORRADOR", "HABLADO", "RESERVADO", "CONFIRMADO"]

        allowed_activities = {k for k, _l, _i in QUAD_ACTIVITY_CHOICES}
        f_activity_types = [
            (a or "").strip().upper()
            for a in (request.args.getlist("activity") or [])
            if (a or "").strip()
        ]
        f_activity_types = [a for a in f_activity_types if a in allowed_activities]
        if not f_activity_types:
            f_activity_types = [k for k, _l, _i in QUAD_ACTIVITY_CHOICES]

        allowed_types = CONCERT_SALE_TYPES_ALL_SET
        f_sale_types_raw = request.args.getlist("type") or []
        f_sale_types = [(t or "").strip().upper() for t in f_sale_types_raw if (t or "").strip()]
        f_sale_types = [t for t in f_sale_types if t in allowed_types]
        if not f_sale_types:
            f_sale_types = list(CONCERT_SALE_TYPES_ALL)

        # ⚠️ «NONE» (sin fecha de anuncio) TIENE que estar: `_announcement_state` lo devuelve para
        # toda actividad a la que no se le ha puesto anuncio, que es lo normal. Al no estar en la
        # lista, el filtro por defecto las descartaba TODAS y no aparecían nunca en el cuadrante.
        allowed_announcements = {"NONE", "NO_ANNOUNCE", "UPCOMING", "ANNOUNCED"}
        f_announcements = [
            (a or "").strip().upper()
            for a in (request.args.getlist("announcement") or [])
            if (a or "").strip()
        ]
        f_announcements = [a for a in f_announcements if a in allowed_announcements]
        if not f_announcements:
            f_announcements = ["NONE", "NO_ANNOUNCE", "UPCOMING", "ANNOUNCED"]

        def _flag(name: str, default: bool = True) -> bool:
            vals = request.args.getlist(name)
            if not vals:
                return default
            return "1" in vals or "true" in vals or "on" in vals

        concert_tag_enabled = _flag("concert_tag_enabled", False)
        concert_tag_text = (request.args.get("concert_tag_text") or "").strip()
        if concert_tag_text:
            raw_tag_candidates = re.split(r"[\n,;]+", concert_tag_text)
        else:
            raw_tag_candidates = request.args.getlist("concert_tag") or request.args.getlist("hashtag") or []
        requested_concert_tags = _dedupe_concert_tags(raw_tag_candidates)
        if not selected_uuids:
            concert_tag_enabled = False
        f_concert_tags = requested_concert_tags if concert_tag_enabled else []
        if not concert_tag_text and requested_concert_tags:
            concert_tag_text = ", ".join([f"#{tag}" for tag in requested_concert_tags])

        show_calendar = _flag("show_calendar", True)
        show_map = _flag("show_map", True)
        show_date = _flag("show_date", True)
        show_concept = _flag("show_concept", True)
        show_festival = _flag("show_festival", True)
        show_sale_type = _flag("show_sale_type", True)
        show_status = _flag("show_status", True)
        show_province = _flag("show_province", True)
        show_municipality = _flag("show_municipality", True)
        show_venue = _flag("show_venue", True)
        show_capacity = _flag("show_capacity", True)
        show_cache = _flag("show_cache", True)
        show_format = _flag("show_format", True)
        show_schedule = _flag("show_schedule", False)
        show_equipment = _flag("show_equipment", True)
        show_promoter = _flag("show_promoter", True)
        show_hashtag = _flag("show_hashtag", True)
        show_announcement = _flag("show_announcement", True)

        selected_artists = []
        events_by_artist = []
        events_flat = []
        marks_by_date = {}
        stats = None

        if selected_uuids:
            selected_artists = (
                session_db.query(Artist)
                .filter(Artist.id.in_(selected_uuids))
                .order_by(Artist.name.asc())
                .all()
            )

            selected_id_set = {str(u) for u in selected_uuids}
            concerts = (
                session_db.query(Concert)
                .options(
                    joinedload(Concert.artist),
                    joinedload(Concert.venue),
                    joinedload(Concert.promoter),
                    joinedload(Concert.group_company),
                    joinedload(Concert.billing_company),
                    joinedload(Concert.contract_sheet),
                )
                .filter(func.extract("year", Concert.date).in_(years))
                .order_by(Concert.date.asc())
                .all()
            )
            if when != "all":
                _hoy = today_local()
                concerts = [
                    c for c in concerts
                    if c.date and ((c.date < _hoy) if when == "past" else (c.date >= _hoy))
                ]
            # Filtro en dos niveles (no en SQL, porque el tipo de actividades
            # multiartista se deriva de varios campos):
            #  1) CONCEPTO (tipo de actividad): concierto / evento / TV / marca…
            #  2) TIPO (venta): empresa / gratuito / vendido…, que SOLO descarta
            #     cuando la actividad tiene un sale_type reconocido y está deseleccionado.
            #     Así una actividad promocional no desaparece por el filtro de venta.
            def _quad_keep(c):
                if not selected_id_set.intersection(_concert_participant_artist_ids(c)):
                    return False
                if _concert_activity_concept(c) not in f_activity_types:
                    return False
                st_eff = _quadrantes_effective_sale_type(c)
                if st_eff in CONCERT_SALE_TYPES_ALL_SET and st_eff not in f_sale_types:
                    return False
                return True

            concerts = [c for c in concerts if _quad_keep(c)]

            if f_concert_tags:
                concerts = [c for c in concerts if _concert_matches_any_tag(c, f_concert_tags)]
            if f_announcements:
                concerts = [c for c in concerts if _announcement_state(c) in f_announcements]

            concert_ids = [c.id for c in concerts]

            caches_map = {}
            if concert_ids and _table_exists(session_db, "public.concert_caches"):
                try:
                    cache_rows = (
                        session_db.query(ConcertCache)
                        .filter(ConcertCache.concert_id.in_(concert_ids))
                        .all()
                    )
                    for r in cache_rows:
                        caches_map.setdefault(r.concert_id, []).append(r)
                except Exception:
                    caches_map = {}

            palette = [
                "#0d6efd",
                "#198754",
                "#6f42c1",
                "#fd7e14",
                "#d63384",
                "#20c997",
                "#0dcaf0",
                "#dc3545",
            ]
            artist_color = {str(a.id): palette[i % len(palette)] for i, a in enumerate(selected_artists)}
            artist_by_id = {str(a.id): a for a in selected_artists}

            equip_ids = set()
            try:
                if concert_ids and _table_exists(session_db, "public.concert_equipments"):
                    rows = (
                        session_db.query(ConcertEquipment.concert_id)
                        .filter(ConcertEquipment.concert_id.in_(concert_ids))
                        .all()
                    )
                    equip_ids.update({r[0] for r in rows if r and r[0]})
                if concert_ids and _table_exists(session_db, "public.concert_equipment_documents"):
                    rows = (
                        session_db.query(ConcertEquipmentDocument.concert_id)
                        .filter(ConcertEquipmentDocument.concert_id.in_(concert_ids))
                        .all()
                    )
                    equip_ids.update({r[0] for r in rows if r and r[0]})
                if concert_ids and _table_exists(session_db, "public.concert_equipment_notes"):
                    rows = (
                        session_db.query(ConcertEquipmentNote.concert_id)
                        .filter(ConcertEquipmentNote.concert_id.in_(concert_ids))
                        .all()
                    )
                    equip_ids.update({r[0] for r in rows if r and r[0]})
            except Exception:
                equip_ids = set()

            per_artist = {str(a.id): [] for a in selected_artists}

            for c in concerts:
                st = (c.status or "BORRADOR")
                if st not in f_statuses:
                    continue

                has_cache = bool(caches_map.get(c.id))
                has_equip = (c.id in equip_ids)
                cap = int(c.capacity or 0)
                dstr = c.date.isoformat()
                cache_txt = _cache_summary(caches_map.get(c.id, []))
                cache_amt = _cache_amount_total(caches_map.get(c.id, []))
                show_format_txt = _concert_show_format(c)
                schedule_txt = _concert_schedule_label(c)
                activity_concept = _concert_activity_concept(c)
                pro_logo, pro_name = _promoter_display(c)
                tags_clean = _concert_tags(c)
                announcement_state = _announcement_state(c)
                announcement_badge = _announcement_badge(c)
                effective_sale_type = _quadrantes_effective_sale_type(c) or (c.sale_type or "")

                for aid in sorted(selected_id_set.intersection(_concert_participant_artist_ids(c))):
                    artist_obj = artist_by_id.get(aid) or c.artist
                    per_artist.setdefault(aid, []).append({
                        "concert_id": str(c.id),
                        "date": dstr,
                        "date_es": c.date.strftime("%d/%m/%Y"),
                        "artist_id": aid,
                        "artist_name": artist_obj.name if artist_obj else (c.artist.name if c.artist else ""),
                        "artist_photo": artist_obj.photo_url if artist_obj else (c.artist.photo_url if c.artist else ""),
                        "artist_color": artist_color.get(aid, "#0d6efd"),
                        "festival_name": (c.festival_name or ""),
                        "activity_type": activity_concept,
                        "activity_label": QUAD_ACTIVITY_LABELS.get(activity_concept, "Concierto"),
                        "activity_icon": QUAD_ACTIVITY_ICONS.get(activity_concept, "fa-guitar"),
                        "sale_type": effective_sale_type,
                        "sale_type_label": _sale_type_label(effective_sale_type, activity_concept),
                        # Solo un CONCIERTO tiene tipo de venta; en el resto lo que dice es si lleva
                        # caché, y así se pinta (la columna «Concepto» ya dice qué es la actividad).
                        "is_concert_like": activity_concept in CONCERT_LIKE_ACTIVITY_TYPES,
                        "cache_label": _activity_cache_label(effective_sale_type, activity_concept),
                        "status": st,
                        "province": _concert_province_value(c),
                        "municipality": _concert_city(c),
                        "venue_name": _concert_venue_name(c),
                        "venue_id": str(c.venue_id) if getattr(c, "venue_id", None) else "",
                        "capacity": cap,
                        "capacity_label": "Sin aforo" if getattr(c, "no_capacity", False) else cap,
                        "cache": cache_txt,
                        "cache_amount": cache_amt,
                        "has_cache": has_cache,
                        "show_format": show_format_txt,
                        "schedule_label": schedule_txt,
                        "has_equipment": has_equip,
                        "promoter_name": pro_name or "",
                        "promoter_logo": pro_logo or "",
                        "hashtags": tags_clean,
                        "hashtags_text": " · ".join([f"#{x}" for x in tags_clean]),
                        "announcement_state": announcement_state,
                        "announcement_badge": announcement_badge,
                    })

            for a in selected_artists:
                aid = str(a.id)
                evs = sorted(per_artist.get(aid, []), key=lambda x: x.get("date") or "")
                for i, e in enumerate(evs, start=1):
                    e["n"] = i
                    events_flat.append(e)

                    marks_by_date.setdefault(e["date"], []).append({
                        "n": i,
                        "status": e.get("status") or "BORRADOR",
                        "artist_id": aid,
                        "artist_name": e.get("artist_name") or a.name,
                        "artist_color": e.get("artist_color") or artist_color.get(aid, "#0d6efd"),
                        "title": f"{e.get('artist_name') or a.name} · {e.get('venue_name') or ''} · {e.get('municipality') or ''} · {e.get('date_es') or ''}",
                    })

                n_conc = sum(1 for e in evs if e.get("activity_type") in QUAD_CONCERT_CONCEPTS)
                cap_total = sum(
                    int(e.get("capacity") or 0)
                    for e in evs
                    if e.get("capacity_label") != "Sin aforo"
                )
                cache_total = sum(float(e.get("cache_amount") or 0) for e in evs)
                events_by_artist.append({
                    "artist_id": aid,
                    "artist_name": a.name,
                    "artist_photo": a.photo_url or "",
                    "artist_color": artist_color.get(aid, "#0d6efd"),
                    "events": evs,
                    "year": period_label,
                    "n_conc": n_conc,
                    "n_other": len(evs) - n_conc,
                    "capacity_total": cap_total,
                    "cache_total": int(round(cache_total)),
                })

            # KPIs de cabecera (estética simulaciones)
            total_capacity = sum(
                int(e.get("capacity") or 0)
                for e in events_flat
                if e.get("capacity_label") != "Sin aforo"
            )
            provinces = {
                (e.get("province") or "").strip()
                for e in events_flat
                if (e.get("province") or "").strip()
            }
            stats = {
                "total": len(events_flat),
                "confirmed": sum(1 for e in events_flat if (e.get("status") == "CONFIRMADO")),
                "artists": len(selected_artists),
                "capacity": total_capacity,
                "provinces": len(provinces),
            }

        return render_template(
            "cuadrantes.html",
            artists=artists,
            selected_artist_ids=[str(u) for u in selected_uuids],
            selected_artists=selected_artists,
            year=year,
            years=years,
            when=when,
            years_label=years_label,
            period_label=period_label,
            year_options=year_options,
            months=months,
            calendar_years=calendar_years,
            dow=DOW_ES,
            marks_by_date=marks_by_date,
            events_by_artist=events_by_artist,
            events=events_flat,
            type_choices=type_choices,
            all_concert_tags=all_concert_tags,
            available_concert_tags=available_concert_tags,
            concert_tags_by_artist=concert_tags_by_artist,
            concert_tag_enabled=concert_tag_enabled,
            concert_tag_text=concert_tag_text,
            f_concert_tags=f_concert_tags,
            f_announcements=f_announcements,
            f_statuses=f_statuses,
            f_sale_types=f_sale_types,
            activity_type_choices=QUAD_ACTIVITY_CHOICES,
            f_activity_types=f_activity_types,
            stats=stats,
            show_calendar=show_calendar,
            show_map=show_map,
            show_date=show_date,
            show_concept=show_concept,
            show_festival=show_festival,
            show_sale_type=show_sale_type,
            show_status=show_status,
            show_province=show_province,
            show_municipality=show_municipality,
            show_venue=show_venue,
            show_capacity=show_capacity,
            show_cache=show_cache,
            show_format=show_format,
            show_schedule=show_schedule,
            show_equipment=show_equipment,
            show_promoter=show_promoter,
            show_hashtag=show_hashtag,
            show_announcement=show_announcement,
        )

    finally:
        session_db.close()


