# ============================ REGISTROS · material para registrar (AGEDI / SGAE) ==================
# Un solo clic baja TODO lo que hay que presentar, en una carpeta con el nombre que espera la
# sociedad: AGEDI_<Artista>_<Canción> / SGAE_<Artista>_<Canción>.
#  · AGEDI: master en MP3 + portada en JPG + el PDF del Label Copy.
#  · SGAE: lo mismo, pero el LC es el de **reparto editorial** y va además la letra en su formato de
#    editorial (sin logo).
# Lo que no se pueda incluir (no hay master, no hay letra…) NO se calla: va un LEEME dentro diciendo
# qué falta, que es mejor que entregar una carpeta incompleta sin saberlo.
# AGEDI_VIDEO: el material para registrar el VIDEOCLIP (el LC con los datos del vídeo y el vídeo
# en MP4). Se ofrece cuando el single ya está registrado y lo único pendiente es el videoclip.
REGISTROS_PACK_KINDS = ("AGEDI", "SGAE", "AGEDI_VIDEO")


def _registros_pack_cover_jpeg(data: bytes) -> bytes:
    """Portada en JPG de calidad para registrar, sin que pese de más: hasta 2000 px de lado, calidad
    85 y optimizada."""
    if not PILLOW_AVAILABLE:
        raise RuntimeError('Pillow no está disponible para convertir la portada.')
    lanczos = getattr(getattr(PILImage, 'Resampling', PILImage), 'LANCZOS', None)
    with PILImage.open(BytesIO(data)) as src:
        img = src
        if img.mode not in ('RGB', 'L'):
            if 'A' in img.getbands():
                bg = PILImage.new('RGB', img.size, (255, 255, 255))
                bg.paste(img, mask=img.getchannel('A'))
                img = bg
            else:
                img = img.convert('RGB')
        elif img.mode == 'L':
            img = img.convert('RGB')
        if lanczos is not None:
            img.thumbnail((2000, 2000), lanczos)
        else:
            img.thumbnail((2000, 2000))
        out = BytesIO()
        img.save(out, format='JPEG', quality=85, optimize=True, progressive=True)
    return out.getvalue()


def _registros_pack_path_part(value: str | None, fallback: str) -> str:
    """Trozo de nombre de carpeta/fichero: sin barras ni caracteres que rompan un ZIP."""
    txt = re.sub(r'[\\/:*?"<>|\r\n\t]+', ' ', (value or '')).strip()
    txt = re.sub(r'\s{2,}', ' ', txt)
    return txt or fallback


def _registros_song_master_material(session_db, song: Song):
    """El master de la canción (el de mejor calidad disponible)."""
    return (
        session_db.query(SongMaterial)
        .filter(SongMaterial.song_id == song.id)
        .filter(func.upper(SongMaterial.category) == 'MASTER')
        .order_by(SongMaterial.slot_key.desc(), SongMaterial.created_at.desc())
        .first()
    )


def _registros_song_pack_zip(session_db, song: Song, kind: str) -> tuple[bytes, str]:
    kind = (kind or 'AGEDI').strip().upper()
    if kind not in REGISTROS_PACK_KINDS:
        raise ValueError('Registro no válido.')
    artist = _song_primary_artist(session_db, song)
    artist_name = _registros_pack_path_part(getattr(artist, 'name', None), 'Artista')
    song_title = _registros_pack_path_part(getattr(song, 'title', None), 'Cancion')
    carpeta = f"{kind}_{artist_name}_{song_title}"
    faltan = []
    piezas: list[tuple[str, bytes]] = []

    # ---- VIDEOCLIP: el LC con los datos del vídeo + el vídeo en MP4 --------------------------
    # Se mantienen el nombre del single y sus intérpretes (lo pide AGEDI así); lo que cambia son
    # los ISRC, las fechas y el director, que son los del videoclip.
    if kind == 'AGEDI_VIDEO':
        carpeta = f"AGEDI_VIDEOCLIP_{artist_name}_{song_title}"
        try:
            pdf, _n = _build_song_label_copy_pdf_bytes(session_db, song.id, video=True)
            piezas.append(('Label Copy - videoclip.pdf', pdf))
        except Exception as exc:
            faltan.append(f'El PDF del Label Copy del videoclip ({exc}).')
        clip = (session_db.query(SongMaterial)
                .filter(SongMaterial.song_id == song.id)
                .filter(func.upper(SongMaterial.category) == 'VIDEOCLIP')
                .order_by(SongMaterial.slot_key.asc(), SongMaterial.created_at.desc())
                .first())
        if clip is None or not (getattr(clip, 'file_url', None) or '').strip():
            faltan.append('El videoclip (no hay ningún vídeo subido en Materiales).')
        else:
            try:
                data, _ctype = _download_remote_content(clip.file_url)
                suffix = Path((clip.file_name or '').replace('\\', '/')).suffix.lower()
                mp4, _mime, _ext = _convert_video_content(data, 'mp4', suffix)
                piezas.append((f"{artist_name} - {song_title}.mp4", mp4))
            except Exception as exc:
                faltan.append(f'El videoclip en MP4 (no se pudo convertir: {exc}).')
        return _registros_pack_finish(carpeta, piezas, faltan)

    # 1) Master en MP3.
    master = _registros_song_master_material(session_db, song)
    if master is None or not (getattr(master, 'file_url', None) or '').strip():
        faltan.append('El master de audio (no hay ningún master subido en Materiales).')
    else:
        try:
            data, _ctype = _download_remote_content(master.file_url)
            suffix = Path((master.file_name or '').replace('\\', '/')).suffix.lower()
            mp3, _mime, _ext = _convert_audio_content_to_mp3(data, suffix)
            piezas.append((f"{artist_name} - {song_title}.mp3", mp3))
        except Exception as exc:
            faltan.append(f'El master en MP3 (no se pudo convertir: {exc}).')

    # 2) Portada en JPG.
    cover_url = ''
    cover_material = (
        session_db.query(SongMaterial)
        .filter(SongMaterial.song_id == song.id)
        .filter(func.upper(SongMaterial.category) == 'COVER')
        .order_by(SongMaterial.slot_key.asc(), SongMaterial.created_at.desc())
        .first()
    )
    if cover_material is not None:
        cover_url = (getattr(cover_material, 'file_url', None) or '').strip()
    if not cover_url:
        cover_url = (getattr(song, 'cover_url', None) or '').strip()
    if not cover_url:
        faltan.append('La portada (la canción no tiene portada).')
    else:
        try:
            data, _ctype = _download_remote_content(cover_url)
            piezas.append((f"Portada_{artist_name}_{song_title}.jpg", _registros_pack_cover_jpeg(data)))
        except Exception as exc:
            faltan.append(f'La portada en JPG (no se pudo convertir: {exc}).')

    # 3) Label Copy (en SGAE, el de reparto editorial).
    try:
        pdf, _name = _build_song_label_copy_pdf_bytes(session_db, song.id, editorial=(kind == 'SGAE'))
        piezas.append((('Label Copy - reparto editorial.pdf' if kind == 'SGAE' else 'Label Copy.pdf'), pdf))
    except Exception as exc:
        faltan.append(f'El PDF del Label Copy ({exc}).')

    # 4) Solo SGAE: la letra en formato de editorial (sin logo).
    if kind == 'SGAE':
        try:
            pdf, _name = _build_song_lyrics_pdf_bytes(session_db, song.id, include_logo=False)
            piezas.append(('Letra.pdf', pdf))
        except LookupError:
            faltan.append('El PDF de la letra (la canción no tiene letra guardada).')
        except Exception as exc:
            faltan.append(f'El PDF de la letra ({exc}).')

    if not piezas:
        raise LookupError('No hay nada que descargar: ' + ' '.join(faltan))

    buf = BytesIO()
    with zipfile.ZipFile(buf, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
        for nombre, contenido in piezas:
            zf.writestr(f"{carpeta}/{nombre}", contenido)
        if faltan:
            aviso = ('En esta carpeta FALTA lo siguiente:\n\n- ' + '\n- '.join(faltan)
                     + '\n\nRevísalo antes de presentar el registro.\n')
            zf.writestr(f"{carpeta}/LEEME - falta material.txt", aviso.encode('utf-8'))
    return buf.getvalue(), _safe_download_filename(f"{carpeta}.zip", f"{kind}.zip")


# =========================================================
# LISTADO DE CÓDIGOS ISRC · descarga en Excel y en PDF
# =========================================================
# Se exporta EXACTAMENTE lo que se está viendo: los filtros del formulario (artista y año) llegan en
# la URL como siempre, y los del navegador —el chip de artista y el buscador— viajan también
# (`filtro_artista` y `q`) y se vuelven a aplicar aquí con el MISMO criterio que el JS del panel.

ISRC_EXPORT_TITLE = "Listado Códigos ISRC"


def _isrc_export_blocks(session_db) -> list:
    """Los bloques (artista, temas) que se están viendo, ya con los filtros del navegador aplicados."""
    ctx = _isrc_panel_context(session_db, isrc_tab="repertorio")
    bloques = ctx.get("isrc_artist_blocks") or []

    elegido = (request.args.get("filtro_artista") or "all").strip()
    q = _norm_text_key(request.args.get("q") or "")

    salida = []
    for artista, filas in bloques:
        vivas = []
        for item in filas or []:
            song = item.get("song")
            if song is None:
                continue
            # Mismo criterio que `data-isrc-artists` del panel: los artistas de la canción o, si no
            # los tuviera, el artista del bloque.
            ids = [str(a.id) for a in (getattr(song, "artists", None) or [])] or [str(artista.id)]
            if elegido and elegido != "all" and elegido not in ids:
                continue
            if q:
                # Mismo pajar que `data-isrc-search`.
                pajar = _norm_text_key(" ".join([
                    (getattr(song, "title", None) or ""),
                    (getattr(artista, "name", None) or ""),
                    (getattr(song, "display_collaborator", None) or getattr(song, "collaborator", None) or ""),
                    (item.get("audio_primary") or ""),
                    (item.get("video_primary") or ""),
                    (item.get("max_code") or ""),
                ]))
                if q not in pajar:
                    continue
            vivas.append(item)
        if vivas:
            salida.append((artista, vivas))
    return salida


def _isrc_export_filename(bloques: list, ext: str) -> str:
    """«Listado Códigos ISRC_<artista>» y, con varios, todos sus nombres separados por comas."""
    nombres = [(getattr(a, "name", None) or "").strip() for a, _ in bloques]
    nombres = [n for n in nombres if n]
    base = ISRC_EXPORT_TITLE + ("_" + ", ".join(nombres) if nombres else "")
    base = re.sub(r"[\\/:*?\"<>|]+", "-", base).strip() or ISRC_EXPORT_TITLE
    return "%s.%s" % (base, ext)


def _isrc_export_song_cells(artista, item) -> list:
    """Una fila del listado, con lo MISMO que se ve en la pantalla."""
    song = item.get("song")
    dur = getattr(song, "duration_seconds", None)
    tipo = ("Distribución" if getattr(song, "is_distribution", False)
            else ("Catálogo" if getattr(song, "is_catalog", False) else "Discográfica"))
    return [
        (getattr(song, "title", None) or "").strip() or "—",
        tipo,
        (getattr(artista, "name", None) or "").strip() or "—",
        (getattr(song, "display_collaborator", None) or getattr(song, "collaborator", None) or "—"),
        ("%d:%02d" % (dur // 60, dur % 60)) if dur else "—",
        (song.release_date.strftime("%d/%m/%Y") if getattr(song, "release_date", None) else "—"),
    ]


def _isrc_export_codes_text(item, kind: str) -> tuple:
    """(principal, subproductos) de un tipo de código, para las celdas de la exportación."""
    principal = item.get("%s_primary" % kind) or ""
    subs = []
    for c in (item.get("%s_sub_rows" % kind) or []):
        etiqueta = (c.get("name") or "").strip()
        subs.append(("%s (%s)" % (c.get("code") or "", etiqueta)) if etiqueta else (c.get("code") or ""))
    return principal, subs


@app.get('/registros/isrc/listado.xlsx', endpoint='registros_isrc_export_xlsx')
@admin_required
def registros_isrc_export_xlsx():
    """El listado de códigos ISRC en Excel (solo lo que se está viendo)."""
    session_db = db()
    try:
        bloques = _isrc_export_blocks(session_db)
        from openpyxl import Workbook
        from openpyxl.styles import Alignment, Font, PatternFill
        wb = Workbook()
        ws = wb.active
        ws.title = "ISRC"
        ws.append([ISRC_EXPORT_TITLE])
        ws["A1"].font = Font(bold=True, size=14)
        ws.append([])
        cabecera = ["Artista", "Canción", "Tipo", "Intérprete", "Colaboradores", "Duración",
                    "Publicación", "ISRC audio", "Subproductos audio", "ISRC vídeo",
                    "Subproductos vídeo", "Registrado en AGEDI"]
        ws.append(cabecera)
        for celda in ws[3]:
            celda.font = Font(bold=True)
            celda.fill = PatternFill("solid", fgColor="F1F3F5")
        for artista, filas in bloques:
            for item in filas:
                base = _isrc_export_song_cells(artista, item)
                audio, audio_subs = _isrc_export_codes_text(item, "audio")
                video, video_subs = _isrc_export_codes_text(item, "video")
                registrado = []
                if audio:
                    registrado.append("audio: " + ("sí" if item.get("audio_primary_registered") else "no"))
                if video:
                    registrado.append("vídeo: " + ("sí" if item.get("video_primary_registered") else "no"))
                ws.append([(getattr(artista, "name", None) or "—")] + base[:1] + base[1:] +
                          [audio or "—", " · ".join(audio_subs) or "", video or "—",
                           " · ".join(video_subs) or "", " · ".join(registrado)])
        anchos = [22, 30, 14, 20, 22, 10, 13, 20, 26, 20, 26, 24]
        for i, ancho in enumerate(anchos, start=1):
            ws.column_dimensions[ws.cell(row=3, column=i).column_letter].width = ancho
        for fila in ws.iter_rows(min_row=4):
            for celda in fila:
                celda.alignment = Alignment(vertical="top", wrap_text=True)
        buf = BytesIO()
        wb.save(buf)
        return send_file(BytesIO(buf.getvalue()),
                         mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                         as_attachment=True, download_name=_isrc_export_filename(bloques, "xlsx"))
    finally:
        session_db.close()


@app.get('/registros/isrc/listado.pdf', endpoint='registros_isrc_export_pdf')
@admin_required
def registros_isrc_export_pdf():
    """El listado de códigos ISRC en PDF: logo de PIES arriba a la derecha, «Listado Códigos ISRC»
    centrado y, debajo, cada artista con su foto y sus canciones tal como se ven. Nada más; las
    páginas van numeradas x/x abajo a la derecha."""
    if not REPORTLAB_AVAILABLE:
        abort(503, "Generación de PDF no disponible en el servidor.")
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import mm
    from reportlab.lib.utils import ImageReader
    from reportlab.pdfgen import canvas as rl_canvas
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle,
                                    Image as RLImage, KeepTogether)

    session_db = db()
    try:
        bloques = _isrc_export_blocks(session_db)
        empresa = _pies_group_company(session_db)
        logo_url = (getattr(empresa, "logo_url", None) or "").strip() or url_for(
            "static", filename="img/logo.png")
        filas_datos = []
        for artista, filas in bloques:
            filas_datos.append({
                "name": (getattr(artista, "name", None) or "—"),
                "photo": (getattr(artista, "photo_url", None) or "").strip(),
                "songs": [{
                    "cells": _isrc_export_song_cells(artista, item),
                    "cover": (item.get("cover_url") or "").strip(),
                    "audio": _isrc_export_codes_text(item, "audio"),
                    "video": _isrc_export_codes_text(item, "video"),
                    "audio_ok": bool(item.get("audio_primary_registered")),
                    "video_ok": bool(item.get("video_primary_registered")),
                    "audio_subs_ok": [bool(c.get("registered")) for c in (item.get("audio_sub_rows") or [])],
                    "video_subs_ok": [bool(c.get("registered")) for c in (item.get("video_sub_rows") or [])],
                } for item in filas],
            })
        nombre = _isrc_export_filename(bloques, "pdf")
    finally:
        session_db.close()

    page_w, page_h = landscape(A4)          # horizontal: así el listado entra sin cortarse
    margin = 12 * mm
    usable_w = page_w - 2 * margin
    VERDE = colors.HexColor("#198754")
    AMBAR = colors.HexColor("#ffc107")
    GRIS_T = colors.HexColor("#6b7683")

    _cache_img: dict = {}

    def _bytes_de(url):
        """Los BYTES de una imagen (remota o del propio servidor), cacheados. None si no se puede."""
        clave = str(url or "")
        if clave in _cache_img:
            return _cache_img[clave]
        datos = None
        try:
            if clave.lower().startswith("http"):
                datos = urlopen(Request(clave, headers={"User-Agent": "Mozilla/5.0"}), timeout=6).read()
            elif clave.startswith("/static/"):
                with open(os.path.join(app.static_folder, clave[len("/static/"):]), "rb") as fh:
                    datos = fh.read()
        except Exception:
            datos = None
        _cache_img[clave] = datos
        return datos

    def _flowable(url, lado_mm):
        """La imagen como elemento del documento (para las tablas). Si falla, no se pinta nada.
        ⚠️ `RLImage` NO admite un `ImageReader`: hay que darle una ruta o un fichero en memoria."""
        datos = _bytes_de(url)
        if not datos:
            return None
        try:
            return RLImage(BytesIO(datos), width=lado_mm * mm, height=lado_mm * mm)
        except Exception:
            return None

    def _reader(url):
        """La imagen para pintarla directamente en el lienzo (el logo)."""
        datos = _bytes_de(url)
        if not datos:
            return None
        try:
            return ImageReader(BytesIO(datos))
        except Exception:
            return None

    est_titulo = ParagraphStyle("t", fontName="Helvetica-Bold", fontSize=17, leading=21,
                                alignment=1, textColor=colors.HexColor("#111827"))
    est_artista = ParagraphStyle("a", fontName="Helvetica-Bold", fontSize=12.5, leading=15)
    est_th = ParagraphStyle("th", fontName="Helvetica-Bold", fontSize=7.6, leading=9.5,
                            textColor=GRIS_T)
    est_td = ParagraphStyle("td", fontName="Helvetica", fontSize=8, leading=10)
    est_td_b = ParagraphStyle("tdb", fontName="Helvetica-Bold", fontSize=8.4, leading=10.5)
    est_sub = ParagraphStyle("sub", fontName="Helvetica", fontSize=6.8, leading=8.4, textColor=GRIS_T)
    est_code = ParagraphStyle("code", fontName="Helvetica-Bold", fontSize=8, leading=10)

    # Los MISMOS anchos para todos los artistas: así todas las columnas quedan alineadas.
    pesos = [0.055, 0.20, 0.135, 0.135, 0.055, 0.085, 0.1725, 0.1625]
    cols = [usable_w * p for p in pesos]

    def celda_codigo(codigo, ok, subs, subs_ok):
        if not codigo and not subs:
            return Paragraph('<font color="#9aa2ad">—</font>', est_td)
        trozos = []
        if codigo:
            color = "#198754" if ok else "#8a6d00"
            trozos.append('<font color="%s">%s</font>' % (color, html.escape(codigo)))
        partes = [Paragraph("".join(trozos), est_code)] if trozos else []
        for i, s in enumerate(subs or []):
            color = "#198754" if (subs_ok[i] if i < len(subs_ok) else False) else "#8a6d00"
            partes.append(Paragraph('<font color="%s">%s</font>' % (color, html.escape(s)), est_sub))
        return partes if len(partes) > 1 else partes[0]

    story = [Spacer(1, 2 * mm), Paragraph(ISRC_EXPORT_TITLE, est_titulo), Spacer(1, 6 * mm)]
    if not filas_datos:
        story.append(Paragraph("No hay canciones para los filtros seleccionados.", est_td))

    for bloque in filas_datos:
        # Cabecera del artista: su foto y su nombre.
        foto = _flowable(bloque["photo"], 11) if bloque["photo"] else None
        cabecera_cells = [foto if foto is not None else ""]
        cabecera_cells.append(Paragraph(html.escape(bloque["name"]), est_artista))
        cab = Table([cabecera_cells], colWidths=[13 * mm, usable_w - 13 * mm])
        cab.setStyle(TableStyle([
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("LEFTPADDING", (0, 0), (-1, -1), 0),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ]))

        datos = [[Paragraph(t, est_th) for t in
                  ["", "Nombre", "Intérprete", "Colaboradores", "Duración", "Publicación",
                   "ISRC audio", "ISRC vídeo"]]]
        for s in bloque["songs"]:
            titulo, tipo, interprete, colabora, duracion, publicacion = s["cells"]
            portada = _flowable(s["cover"], 10) if s["cover"] else None
            datos.append([
                (portada if portada is not None else ""),
                [Paragraph(html.escape(titulo), est_td_b), Paragraph(html.escape(tipo), est_sub)],
                Paragraph(html.escape(interprete), est_td),
                Paragraph(html.escape(colabora), est_td),
                Paragraph(html.escape(duracion), est_td),
                Paragraph(html.escape(publicacion), est_td),
                celda_codigo(s["audio"][0], s["audio_ok"], s["audio"][1], s["audio_subs_ok"]),
                celda_codigo(s["video"][0], s["video_ok"], s["video"][1], s["video_subs_ok"]),
            ])
        tabla = Table(datos, colWidths=cols, repeatRows=1)
        tabla.setStyle(TableStyle([
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#f1f3f5")),
            ("LINEBELOW", (0, 0), (-1, 0), 0.5, colors.HexColor("#dfe3e8")),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#fbfcfd")]),
            ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#e9ecef")),
            ("TOPPADDING", (0, 0), (-1, -1), 3),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ]))
        # El artista y su primera fila no se separan del salto de página.
        story.append(KeepTogether([cab, tabla]) if len(datos) <= 6 else cab)
        if len(datos) > 6:
            story.append(tabla)
        story.append(Spacer(1, 6 * mm))

    class _Numerada(rl_canvas.Canvas):
        """Numera las páginas x/x abajo a la derecha (hay que saber el total: dos pasadas)."""

        def __init__(self, *a, **kw):
            super().__init__(*a, **kw)
            self._paginas = []

        def showPage(self):
            self._paginas.append(dict(self.__dict__))
            self._startPage()

        def save(self):
            total = len(self._paginas)
            for estado in self._paginas:
                self.__dict__.update(estado)
                self._pinta(total)
                super().showPage()
            super().save()

        def _pinta(self, total):
            self.setFont("Helvetica", 7)
            self.setFillColor(GRIS_T)
            self.drawRightString(page_w - margin, 8 * mm, "%d/%d" % (self._pageNumber, total))

    def _logo(canv, doc):
        """El logo de PIES, arriba a la DERECHA (en todas las páginas)."""
        img = _reader(logo_url)
        if img is None:
            # Si el logo de la empresa no se puede leer, el de la casa: aquí SIEMPRE tiene que salir
            # una marca (es un documento que se manda fuera).
            img = _reader(url_for("static", filename="img/logo.png"))
        if img is None:
            return
        try:
            iw, ih = img.getSize()
            alto = 13 * mm
            ancho = alto * (iw / float(ih or 1))
            tope = 45 * mm
            if ancho > tope:
                ancho = tope
                alto = ancho * (ih / float(iw or 1))
            canv.drawImage(img, page_w - margin - ancho, page_h - margin - alto,
                           width=ancho, height=alto, mask="auto")
        except Exception:
            pass

    buf = BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(A4),
                            leftMargin=margin, rightMargin=margin,
                            topMargin=margin + 15 * mm, bottomMargin=margin + 4 * mm,
                            title=ISRC_EXPORT_TITLE)
    doc.build(story, onFirstPage=_logo, onLaterPages=_logo, canvasmaker=_Numerada)
    return send_file(BytesIO(buf.getvalue()), mimetype="application/pdf",
                     as_attachment=True, download_name=nombre)


@app.get('/registros/canciones/<song_id>/material', endpoint='registros_song_pack')
@admin_required
def registros_song_pack(song_id):
    """Descarga en un ZIP todo el material que hace falta para registrar la canción."""
    kind = (request.args.get('kind') or 'AGEDI').strip().upper()
    nxt = safe_next_or(request.args.get('next') or url_for('registros_view', tab='pendiente'))
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            flash('Canción no encontrada.', 'warning')
            return redirect(nxt)
        data, filename = _registros_song_pack_zip(session_db, song, kind)
        return send_file(BytesIO(data), mimetype='application/zip', as_attachment=True, download_name=filename)
    except LookupError as exc:
        flash(str(exc), 'warning')
        return redirect(nxt)
    except Exception as exc:
        flash(f'No se pudo preparar el material: {exc}', 'danger')
        return redirect(nxt)
    finally:
        session_db.close()


@app.post('/registros/canciones/<song_id>/declaracion-firmada', endpoint='registros_song_declaration_signed')
@admin_required
def registros_song_declaration_signed(song_id):
    """Sube la DECLARACIÓN DE OBRA ya firmada; queda en la ficha, en «Declaración de obra»."""
    if not (can_edit_discografica() or is_master()):
        return forbid('No tienes permisos para subir la declaración de obra.')
    nxt = safe_next_or(request.form.get('next') or url_for('registros_view', tab='pendiente'))
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            flash('Canción no encontrada.', 'warning')
            return redirect(nxt)
        url = upload_pdf(request.files.get('declaration_pdf'), 'song_declarations')
        if not url:
            flash('Selecciona el PDF de la declaración de obra firmada.', 'warning')
            return redirect(nxt)
        song.work_declaration_url = url
        song.work_declaration_uploaded_at = datetime.now(TZ_MADRID)
        song.work_declaration_signed = True
        session_db.add(song)
        session_db.commit()
        flash('Declaración de obra firmada subida.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'Error subiendo la declaración: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(nxt)


@app.get('/registros/sgae/repertorio/link', endpoint='registros_repertoire_link')
@admin_required
def registros_repertoire_link():
    author_id = to_uuid(request.args.get('author_id') or '')
    if not author_id:
        return jsonify({'ok': False, 'message': 'Autor no válido.'}), 400
    filters = {
        'status': (request.args.get('status') or '').strip().lower(),
        'own100': '1' if _truthy(request.args.get('own100')) else '',
        'year': (request.args.get('year') or '').strip(),
        'start_date': (request.args.get('start_date') or '').strip(),
        'end_date': (request.args.get('end_date') or '').strip(),
        'allow_download': '1' if _truthy(request.args.get('allow_download')) else '',
    }
    token = _registros_public_repertoire_token(author_id, filters)
    return jsonify({'ok': True, 'url': _external_url_for('public_registros_repertoire', token=token)})


@app.get('/public/registros/repertorio/<token>', endpoint='public_registros_repertoire')
def public_registros_repertoire(token):
    payload = _parse_registros_public_repertoire_token(token)
    if not payload:
        abort(404)
    author_id = to_uuid(payload.get('author_id') or '')
    filters = payload.get('filters') if isinstance(payload.get('filters'), dict) else {}
    if not author_id:
        abort(404)
    with get_db() as session_db:
        promoter = session_db.get(Promoter, author_id)
        if not promoter:
            abort(404)
        sgae = _build_registros_sgae_dataset(session_db, filters={**filters})
        author_block = None
        for block in sgae.get('authors') or []:
            if str(block.get('id')) == str(author_id):
                author_block = block
                break
        if not author_block:
            author_block = {
                'id': str(author_id),
                'name': _promoter_display_name(promoter) or getattr(promoter, 'nick', None) or '—',
                'photo_url': (getattr(promoter, 'logo_url', None) or '').strip(),
                'songs': [],
            }
        # Enriquecemos acciones públicas de repertorio.
        for card in author_block.get('songs') or []:
            song = card.get('song')
            if song:
                card['master_links'] = _registros_song_master_links(session_db, song)
        return render_template('public_registros_repertoire.html', brand=sgae.get('brand'), author=author_block, filters=filters, allow_download=_truthy(filters.get('allow_download')))


