# ---------------------------------------------------------------------------
#  PRL / ALTAS — documentación de riesgos laborales y altas en la Seguridad
#  Social del personal de los eventos (subpestaña PRL del Personal de la hoja
#  de ruta, pestaña «Alta y PRL» del tercero, PRL del personal propio y
#  pestaña «Altas» de Administración con los ITA de las empresas del grupo).
# ---------------------------------------------------------------------------

PRL_WORKER_TYPES = [
    ("AUTONOMO", "Autónomo", "fa-user-tie", "Recibo de autónomos del mes anterior + PRL"),
    ("PUNTUAL", "Alta temporal", "fa-user-clock", "Alta puntual en la Seguridad Social para el evento + PRL"),
    ("EMPRESA", "Empleado de empresa", "fa-building-user", "Empresa con ITA en vigor + PRL"),
]
PRL_WORKER_TYPE_LABELS = {k: v for k, v, _i, _d in PRL_WORKER_TYPES}
# El personal PROPIO de la oficina no elige tipo (no es un tercero), pero sí tiene etiqueta.
PRL_WORKER_TYPE_LABELS["OFICINA"] = "Personal de la oficina"
PRL_DOC_LABELS = {
    "AUTONOMO_RECIBO": "Recibo de autónomos",
    "ALTA_SS": "Alta en la Seguridad Social",
    "ITA": "Informe de trabajadores en alta (ITA)",
    "PRL_FORMACION": "PRL · Formación",
    "PRL_INFORMACION": "PRL · Información de riesgos",
    # Entrega de EPIs: sin caducidad. Renuncia al examen médico: caduca al año de su emisión y
    # solo se le pide a quien va por cuenta ajena (alta puntual y personal de la oficina).
    "EPIS": "Entrega de EPIs",
    "RENUNCIA_MEDICO": "Renuncia al examen médico",
    # Un alta PUNTUAL (por cuenta ajena) tiene que traer también su BAJA: es lo que cierra el
    # periodo de alta. Sin caducidad propia: vale la fecha de efectos que se detecte.
    "BAJA_SS": "Baja en la Seguridad Social",
    # Certificados de facturación: CADUCAN CADA MES (solo valen para el mes en vigor).
    "CERT_AEAT": "Certificado de la Agencia Tributaria",
    "CERT_SS": "Certificado de corriente de pagos con la Seguridad Social",
}
# Certificados que exige facturación, con el enlace oficial para obtenerlos y a quién se le piden.
INVOICE_CERT_DOCS = [
    ("CERT_AEAT", "Certificado de la Agencia Tributaria", "fa-landmark", "empresa",
     "https://www2.agenciatributaria.gob.es/wlpl/BUCV-JDIT/AutenticaDniNieContrasteh?ref=%2Fwlpl%2FOVCT%2DCXEW%2FSelectorAcceso%3Fref%3D%252Fwlpl%252FEMCE%2DJDIT%252FECOTInternetCiudadanosServlet%26aut%3DCP"),
    ("CERT_SS", "Certificado de corriente de pagos con la Seguridad Social", "fa-shield-halved", "ambos",
     "https://idp.seg-social.es/PGIS/Login"),
]
# Estos certificados solo valen el MES en vigor.
INVOICE_MONTHLY_CERTS = {"CERT_AEAT", "CERT_SS"}
# Documento de «alta» que corresponde a cada tipo de trabajador.
PRL_ALTA_DOC_BY_TYPE = {"AUTONOMO": "AUTONOMO_RECIBO", "PUNTUAL": "ALTA_SS", "EMPRESA": "ITA"}
# Tipo de «trabajador» del personal PROPIO de la oficina (no es un tercero: va por cuenta ajena
# con nosotros y su alta la cubre el ITA de la empresa del grupo).
PRL_OWN_STAFF_TYPE = "OFICINA"
# La renuncia al examen médico y la entrega de EPIs solo se piden a quien va por CUENTA AJENA: alta
# puntual y el personal propio de la oficina. A autónomos y a empleados de otra empresa, NO.
PRL_MEDICAL_WAIVER_TYPES = {"PUNTUAL", PRL_OWN_STAFF_TYPE}
PRL_EPIS_TYPES = {"PUNTUAL", PRL_OWN_STAFF_TYPE}
# La BAJA solo la trae el alta puntual (es la que cierra su periodo de alta).
PRL_BAJA_TYPES = {"PUNTUAL"}
_PRL_MESES_ES = {"enero": 1, "febrero": 2, "marzo": 3, "abril": 4, "mayo": 5, "junio": 6,
                 "julio": 7, "agosto": 8, "septiembre": 9, "setiembre": 9, "octubre": 10,
                 "noviembre": 11, "diciembre": 12}


def _prl_month_end(year: int, month: int) -> date:
    return date(year, month, _cal.monthrange(year, month)[1])


def _pdf_extract_text_bytes(data: bytes) -> str:
    """Texto plano de un PDF (mejor esfuerzo; '' si no es PDF o no hay texto)."""
    try:
        from pypdf import PdfReader
        reader = PdfReader(BytesIO(data))
        parts = []
        for page in reader.pages[:6]:
            try:
                parts.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(parts)
    except Exception:
        return ""


def _prl_norm_dni(value: str) -> str:
    """Normaliza un DNI/NIE para comparar (mayúsculas, sin separadores ni ceros a la izquierda)."""
    v = re.sub(r"[^0-9A-Za-z]", "", (value or "")).upper()
    if v and v[0] not in "XYZ":
        v = v.lstrip("0")
    return v


def _ita_extract_workers(text: str) -> list:
    """Extrae los trabajadores de un ITA: líneas con APELLIDOS Y NOMBRE + NAF + IPF (DNI/NIE)."""
    workers = []
    for line in (text or "").splitlines():
        line = line.strip()
        m_ipf = re.search(r"\b(0?\d{8}[A-Z]|\d{7,8}[A-Z]|[XYZ]\d{7}[A-Z])\b", line)
        m_name = re.match(r"^([A-ZÁÉÍÓÚÑÜ][A-ZÁÉÍÓÚÑÜ\s\.'\-]{3,70}?)\s+\d{1,2}\s*[\s/]\s*\d{6,12}", line)
        if not m_name:
            m_name = re.match(r"^([A-ZÁÉÍÓÚÑÜ][A-ZÁÉÍÓÚÑÜ\s\.'\-]{3,70}?)\s+\d{2}\s+\d{6,12}", line)
        if m_ipf and m_name:
            name = re.sub(r"\s+", " ", m_name.group(1)).strip()
            if len(name.split()) >= 2:
                workers.append({"name": name, "ipf": _prl_norm_dni(m_ipf.group(1))})
    return workers


def _prl_detect(doc_type: str, text: str, event_date) -> dict:
    """Detecta las fechas de validez de un documento de alta/PRL a partir de su texto.
    Devuelve {valid_from, valid_until, meta} (fechas date o None)."""
    out = {"valid_from": None, "valid_until": None, "meta": {"detected": False}}
    t = text or ""
    if doc_type == "AUTONOMO_RECIBO":
        # «PERIODO LIQUIDACION: 05/2025-05/2025» → válido durante el mes SIGUIENTE al del recibo.
        m = re.search(r"PERIODO\s+LIQUIDACION[:\s]*([01]?\d)\s*/\s*(\d{4})", t, re.IGNORECASE)
        if m:
            mm, yy = int(m.group(1)), int(m.group(2))
            if 1 <= mm <= 12:
                nm, ny = (1, yy + 1) if mm == 12 else (mm + 1, yy)
                out["valid_from"] = date(yy, mm, 1)
                out["valid_until"] = _prl_month_end(ny, nm)
                out["meta"] = {"detected": True, "periodo": f"{mm:02d}/{yy}"}
    elif doc_type == "ITA":
        # «INFORME DE TRABAJADORES EN ALTA A FECHA: 19 06 2026» → válido durante ese mes.
        m = re.search(r"EN\s+ALTA\s+A\s+FECHA[:\s]*(\d{1,2})[\s\-/]+(\d{1,2})[\s\-/]+(\d{4})", t, re.IGNORECASE)
        if m:
            dd, mm, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if 1 <= mm <= 12:
                out["valid_from"] = date(yy, mm, 1)
                out["valid_until"] = _prl_month_end(yy, mm)
                out["meta"] = {"detected": True, "fecha": f"{dd:02d}/{mm:02d}/{yy}"}
        mrs = re.search(r"RAZ[OÓ]N\s+SOCIAL[:\s]*(.+)", t, re.IGNORECASE)
        if mrs:
            out["meta"]["razon_social"] = mrs.group(1).strip()[:120]
        workers = _ita_extract_workers(t)
        if workers:
            out["meta"]["workers"] = workers
    elif doc_type == "ALTA_SS":
        # «La fecha de efectos con que se reconoce el alta es ... 12 de febrero de 2026»
        detected = None
        m = re.search(r"fecha\s+de\s+efectos[^0-9]{0,80}?(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(\d{4})", t, re.IGNORECASE)
        if m and _PRL_MESES_ES.get(m.group(2).lower()):
            try:
                detected = date(int(m.group(3)), _PRL_MESES_ES[m.group(2).lower()], int(m.group(1)))
            except ValueError:
                detected = None
        if not detected:
            m = re.search(r"FECHA[:\s]*(\d{1,2})[\-/](\d{1,2})[\-/](\d{4})", t)
            if m:
                try:
                    detected = date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
                except ValueError:
                    detected = None
        # BAJA: un alta puntual puede ser de varios días. Si el documento trae la fecha de baja,
        # el alta cubre TODO el periodo (y sirve para cualquier evento que caiga dentro).
        baja = None
        mb = re.search(r"baja[^0-9]{0,80}?(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(\d{4})", t, re.IGNORECASE)
        if mb and _PRL_MESES_ES.get(mb.group(2).lower()):
            try:
                baja = date(int(mb.group(3)), _PRL_MESES_ES[mb.group(2).lower()], int(mb.group(1)))
            except ValueError:
                baja = None
        if not baja:
            mb = re.search(r"baja[^0-9]{0,60}?(\d{1,2})[\-/](\d{1,2})[\-/](\d{4})", t, re.IGNORECASE)
            if mb:
                try:
                    baja = date(int(mb.group(3)), int(mb.group(2)), int(mb.group(1)))
                except ValueError:
                    baja = None
        if detected:
            out["valid_from"] = detected
            out["valid_until"] = baja if (baja and baja >= detected) else detected
            out["meta"] = {"detected": True, "fecha_efectos": detected.isoformat()}
            if baja and baja >= detected:
                out["meta"]["fecha_baja"] = baja.isoformat()
            if event_date:
                # Cuadra si la fecha del evento cae DENTRO del periodo de alta, no solo si es el
                # mismo día: un alta de varios días cubre todo lo que pase en ese rango.
                out["meta"]["match_event"] = (out["valid_from"] <= event_date <= out["valid_until"])
    elif doc_type == "BAJA_SS":
        # «La fecha de efectos de la baja es … 15 de junio de 2026» (o dd/mm/aaaa).
        baja = None
        m = re.search(r"(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(\d{4})", t, re.IGNORECASE)
        if m and _PRL_MESES_ES.get(m.group(2).lower()):
            try:
                baja = date(int(m.group(3)), _PRL_MESES_ES[m.group(2).lower()], int(m.group(1)))
            except ValueError:
                baja = None
        if not baja:
            m = re.search(r"(\d{1,2})[\-/](\d{1,2})[\-/](\d{4})", t)
            if m:
                try:
                    baja = date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
                except ValueError:
                    baja = None
        if baja:
            # La baja no «caduca»: certifica el final del periodo de alta. Se guarda su fecha para
            # poder cuadrarla con el alta y con la fecha del evento.
            out["valid_from"] = baja
            out["meta"] = {"detected": True, "fecha_baja": baja.isoformat()}
    elif doc_type == "RENUNCIA_MEDICO":
        # Caduca al año de la fecha de emisión que se detecte en el documento.
        emitido = None
        m = re.search(r"(\d{1,2})\s+de\s+([a-záéíóú]+)\s+de\s+(\d{4})", t, re.IGNORECASE)
        if m and _PRL_MESES_ES.get(m.group(2).lower()):
            try:
                emitido = date(int(m.group(3)), _PRL_MESES_ES[m.group(2).lower()], int(m.group(1)))
            except ValueError:
                emitido = None
        if not emitido:
            m = re.search(r"(\d{1,2})[\-/](\d{1,2})[\-/](\d{4})", t)
            if m:
                try:
                    emitido = date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
                except ValueError:
                    emitido = None
        if emitido:
            out["valid_from"] = emitido
            out["valid_until"] = _add_months(emitido, 12) - timedelta(days=1)
            out["meta"] = {"detected": True, "emitido": emitido.isoformat()}
    # Formación/Información/EPIs: sin caducidad (valid_until NULL).
    return out


def _prl_doc_valid_on(doc, on_date) -> bool:
    if (doc.status or "APPROVED") != "APPROVED":
        return False
    if doc.valid_until and on_date and doc.valid_until < on_date:
        return False
    if doc.valid_from and on_date and doc.valid_from > on_date:
        return False
    return True


def _prl_company_ita_docs(session_db):
    return (session_db.query(PersonComplianceDoc)
            .filter(PersonComplianceDoc.owner_type == "COMPANY", PersonComplianceDoc.doc_type == "ITA")
            .order_by(PersonComplianceDoc.created_at.desc()).all())


def _prl_doc_json(doc) -> dict:
    return {
        "id": str(doc.id),
        "doc_type": doc.doc_type,
        "label": PRL_DOC_LABELS.get(doc.doc_type, doc.doc_type),
        "file_url": doc.file_url,
        "status": doc.status,
        "reject_reason": doc.reject_reason or "",
        "valid_from": doc.valid_from.isoformat() if doc.valid_from else None,
        "valid_until": doc.valid_until.isoformat() if doc.valid_until else None,
        "created_at": doc.created_at.strftime("%d/%m/%Y") if doc.created_at else "",
    }


def _prl_person_status(session_db, concert, person: dict, event_date, ita_docs=None) -> dict:
    """Estado de alta y PRL de una persona del personal del evento: tipo de trabajador y
    3 semáforos (alta / información / formación) con sus documentos."""
    info = _rooming_person_info(session_db, person)
    kind = (person.get("kind") or "").upper()
    promoter = None
    if kind == "PROMOTER" and to_uuid(person.get("ref_id") or ""):
        promoter = session_db.get(Promoter, to_uuid(person.get("ref_id")))
    # PERSONAL PROPIO DE LA OFICINA: no es un tercero, pero también va por cuenta ajena, así que se
    # le piden información, formación, EPIs y renuncia al examen médico. Sus documentos cuelgan del
    # usuario (`PersonComplianceDoc` owner_type='USER') y su alta la cubre el ITA de la empresa.
    own_user = None
    if kind == "USER" and to_uuid(person.get("ref_id") or ""):
        own_user = session_db.get(User, to_uuid(person.get("ref_id")))
    row = {
        "personnel_id": person.get("id") or "",
        "name": info["name"], "full_name": info["full_name"], "role": info["role"],
        "phone": info["phone"], "email": info["email"], "photo_url": info["photo_url"],
        "dni": info["dni"],
        "promoter_id": str(promoter.id) if promoter else "",
        "worker_type": (getattr(promoter, "prl_type", None) or "") if promoter else "",
        "worker_type_label": "",
        "alta": {"ok": False, "doc": None}, "informacion": {"ok": False, "doc": None},
        "formacion": {"ok": False, "doc": None},
        # EPIs y renuncia al examen médico: solo a quien va por CUENTA AJENA (alta puntual y
        # personal de la oficina). La BAJA, solo al alta puntual.
        "epis": {"ok": False, "doc": None, "required": False},
        "renuncia_medico": {"ok": False, "doc": None, "required": False},
        "baja": {"ok": False, "doc": None, "required": False},
        "docs": [],
    }
    if own_user is not None:
        row["promoter_id"] = ""
        row["worker_type"] = PRL_OWN_STAFF_TYPE
    row["worker_type_label"] = PRL_WORKER_TYPE_LABELS.get(row["worker_type"], "")
    if not promoter and own_user is None:
        return row
    owner_type = "PROMOTER" if promoter is not None else "USER"
    owner_id = promoter.id if promoter is not None else own_user.id
    docs = (session_db.query(PersonComplianceDoc)
            .filter(PersonComplianceDoc.owner_type == owner_type, PersonComplianceDoc.owner_id == owner_id)
            .order_by(PersonComplianceDoc.created_at.desc()).all())
    row["docs"] = [_prl_doc_json(d) for d in docs]
    for slot, dt in (("informacion", "PRL_INFORMACION"), ("formacion", "PRL_FORMACION"),
                     ("epis", "EPIS"), ("renuncia_medico", "RENUNCIA_MEDICO"),
                     ("baja", "BAJA_SS")):
        for d in docs:
            if d.doc_type == dt:
                if _prl_doc_valid_on(d, event_date):
                    row[slot] = {"ok": True, "doc": _prl_doc_json(d)}
                elif not row[slot]["doc"]:
                    row[slot] = {"ok": False, "doc": _prl_doc_json(d)}
                if row[slot]["ok"]:
                    break
    wt = row["worker_type"]
    row["renuncia_medico"]["required"] = wt in PRL_MEDICAL_WAIVER_TYPES
    row["epis"]["required"] = wt in PRL_EPIS_TYPES
    row["baja"]["required"] = wt in PRL_BAJA_TYPES
    if wt == PRL_OWN_STAFF_TYPE:
        # Su alta la cubre el ITA de la empresa del grupo (Administración → Altas): se busca por
        # vínculo o por DNI, igual que con los empleados de una empresa.
        dni_norm = _prl_norm_dni(info["dni"])
        uid_txt = str(own_user.id) if own_user is not None else ""
        for d in (ita_docs if ita_docs is not None else _prl_company_ita_docs(session_db)):
            linked = [str(x) for x in (d.linked_person_ids or [])]
            by_link = bool(uid_txt) and (f"USER:{uid_txt}" in linked or uid_txt in linked)
            by_dni = bool(dni_norm) and any(_prl_norm_dni(w.get("ipf") or "") == dni_norm
                                            for w in ((d.detected_meta or {}).get("workers") or []))
            if (by_link or by_dni) and _prl_doc_valid_on(d, event_date):
                row["alta"] = {"ok": True, "doc": _prl_doc_json(d)}
                break
    if wt == "AUTONOMO":
        for d in docs:
            if d.doc_type == "AUTONOMO_RECIBO":
                if _prl_doc_valid_on(d, event_date):
                    row["alta"] = {"ok": True, "doc": _prl_doc_json(d)}
                    break
                if not row["alta"]["doc"]:
                    row["alta"] = {"ok": False, "doc": _prl_doc_json(d)}
    elif wt == "PUNTUAL":
        for d in docs:
            if d.doc_type == "ALTA_SS":
                same_concert = concert is not None and d.concert_id == getattr(concert, "id", None)
                if (d.status or "") == "APPROVED" and (same_concert or _prl_doc_valid_on(d, event_date)):
                    row["alta"] = {"ok": True, "doc": _prl_doc_json(d)}
                    break
                if not row["alta"]["doc"]:
                    row["alta"] = {"ok": False, "doc": _prl_doc_json(d)}
    elif wt == "EMPRESA":
        # ITA de una empresa del grupo donde la persona está vinculada, o un ITA de su propia
        # empresa subido en su ficha / por el enlace público.
        for d in docs:
            if d.doc_type == "ITA":
                if _prl_doc_valid_on(d, event_date):
                    row["alta"] = {"ok": True, "doc": _prl_doc_json(d)}
                    break
                if not row["alta"]["doc"]:
                    row["alta"] = {"ok": False, "doc": _prl_doc_json(d)}
        pid = str(promoter.id)
        dni_norm = _prl_norm_dni(info["dni"])
        for d in ([] if row["alta"]["ok"] else (ita_docs if ita_docs is not None else _prl_company_ita_docs(session_db))):
            linked = [str(x) for x in (d.linked_person_ids or [])]
            by_link = f"PROMOTER:{pid}" in linked or pid in linked
            by_dni = bool(dni_norm) and any(_prl_norm_dni(w.get("ipf") or "") == dni_norm
                                            for w in ((d.detected_meta or {}).get("workers") or []))
            if (by_link or by_dni) and _prl_doc_valid_on(d, event_date):
                row["alta"] = {"ok": True, "doc": _prl_doc_json(d)}
                break
    return row


def _prl_rows_for_concert(session_db, kind, row_entity) -> list:
    payload = _roadmap_load(row_entity)
    event_date = getattr(row_entity, "date", None)
    ita_docs = _prl_company_ita_docs(session_db)
    concert = row_entity if kind == "concert" else None
    return [_prl_person_status(session_db, concert, p, event_date, ita_docs)
            for p in (payload.get("personnel") or [])]


def _travel_person_row(session_db, person: dict) -> dict:
    """Una persona del listado de VIAJE: sus datos + las necesidades de viaje de su ficha y,
    si se pide, la foto del documento (DNI o pasaporte) para enseñarla al comprar billetes."""
    kind = (person.get("kind") or "MANUAL").upper()
    ref = to_uuid(person.get("ref_id") or "") if person.get("ref_id") else None
    entity = None
    doc_row = None
    if kind == "PROMOTER" and ref:
        entity = session_db.get(Promoter, ref)
        owner_type = "PROMOTER"
    elif kind == "USER" and ref:
        entity = session_db.query(UserProfile).filter(UserProfile.user_id == ref).first()
        owner_type = "USER"
    else:
        owner_type = None
    if ref and owner_type:
        doc_row = (
            session_db.query(PersonDocument)
            .filter(PersonDocument.owner_type == owner_type, PersonDocument.owner_id == ref)
            .filter(PersonDocument.kind.in_(["DNI", "PASSPORT"]))
            .order_by(PersonDocument.created_at.desc())
            .first()
        )
    travel = _travel_summary(entity) if entity is not None else {
        "notes": "", "marks": [], "departure_flight": "", "departure_train": "", "has_any": False}
    return {
        "id": person.get("id") or "",
        "name": (person.get("name") or "").strip(),
        "role": (person.get("role") or "").strip(),
        "photo_url": (person.get("photo_url") or ""),
        "phone": (person.get("phone") or ""),
        "email": (person.get("email") or ""),
        "dni": ((getattr(entity, "tax_id", None) or getattr(entity, "dni", None) or "") if entity is not None else ""),
        "birth_date": (getattr(entity, "birth_date", None).isoformat() if getattr(entity, "birth_date", None) else ""),
        "travel": travel,
        "doc_kind": (getattr(doc_row, "kind", "") or ""),
        "doc_front": (getattr(doc_row, "front_url", "") or ""),
        "doc_back": (getattr(doc_row, "back_url", "") or ""),
        "doc_number": (getattr(doc_row, "doc_number", "") or ""),
        "doc_expiry": (getattr(doc_row, "expiry_date", None).isoformat() if getattr(doc_row, "expiry_date", None) else ""),
    }


