@app.get('/hoja-ruta/<entity_type>/<entity_id>/prl/pdf', endpoint='prl_export_pdf')
@admin_required
def prl_export_pdf(entity_type, entity_id):
    if not REPORTLAB_AVAILABLE:
        abort(503)
    session_db = db()
    try:
        kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        rows = _prl_rows_for_concert(session_db, kind, row)
        header = _roadmap_export_header(kind, row)
        buf = BytesIO()
        docpdf = SimpleDocTemplate(buf, pagesize=A4, leftMargin=32, rightMargin=32, topMargin=24, bottomMargin=24)
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle("PrlTitle", parent=styles["Title"], alignment=TA_CENTER, fontSize=16, leading=19)
        h_style = ParagraphStyle("PrlH", parent=styles["Normal"], fontSize=10, leading=12, fontName="Helvetica-Bold")
        small = ParagraphStyle("PrlS", parent=styles["Normal"], fontSize=8, leading=10)
        story = []
        logo = _fetch_image_reader(header["logo_url"])
        logo_cell = RLImage(logo, width=110, height=40, kind="proportional") if logo else ""
        lr = Table([["", logo_cell]], colWidths=[411, 120])
        lr.setStyle(TableStyle([("ALIGN", (1, 0), (1, 0), "RIGHT")]))
        story.append(lr)
        story.append(Paragraph("Listado de Alta y PRL", title_style))
        facts = " · ".join([x for x in [header["date"], header.get("venue") or "", header.get("city") or ""] if x])
        story.append(Paragraph(header["title"], h_style))
        if facts:
            story.append(Paragraph(facts, small))
        story.append(Spacer(1, 6))
        def _mark(slot):
            """SÍ / NO, o «—» si ese documento no se le pide a esta persona."""
            if not slot.get("required", True):
                return "—"
            return "SÍ" if slot.get("ok") else "NO"

        data = [["Nombre y apellidos", "DNI", "Función", "Tipo de alta", "Alta", "Baja",
                 "Información", "Formación", "EPIs", "Renuncia méd."]]
        for r in rows:
            data.append([
                Paragraph(escape(r["full_name"]), small), r["dni"], Paragraph(escape(r["role"]), small),
                r["worker_type_label"] or "—",
                "SÍ" if r["alta"]["ok"] else "NO",
                _mark(r.get("baja") or {}),
                "SÍ" if r["informacion"]["ok"] else "NO",
                "SÍ" if r["formacion"]["ok"] else "NO",
                _mark(r.get("epis") or {}),
                _mark(r.get("renuncia_medico") or {}),
            ])
        tbl = Table(data, colWidths=[128, 62, 74, 74, 38, 38, 58, 52, 34, 52], repeatRows=1)
        style_cmds = [
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E33D48")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
            ("FONTSIZE", (0, 0), (-1, -1), 8),
            ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#d8dee6")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#f7f8fa")]),
        ]
        for idx, r in enumerate(rows, start=1):
            for col, key in ((4, "alta"), (5, "baja"), (6, "informacion"), (7, "formacion"),
                             (8, "epis"), (9, "renuncia_medico")):
                slot = r.get(key) or {}
                if not slot.get("required", True):
                    color = colors.HexColor("#8a93a0")          # no se le pide: en gris
                else:
                    color = colors.HexColor("#1a7f37") if slot.get("ok") else colors.HexColor("#c62828")
                style_cmds.append(("TEXTCOLOR", (col, idx), (col, idx), color))
        tbl.setStyle(TableStyle(style_cmds))
        story.append(tbl)
        docpdf.build(story)
        buf.seek(0)
        return send_file(buf, mimetype="application/pdf", as_attachment=True, download_name="listado_prl.pdf")
    finally:
        session_db.close()


@app.get('/hoja-ruta/<entity_type>/<entity_id>/prl/xlsx', endpoint='prl_export_xlsx')
@admin_required
def prl_export_xlsx(entity_type, entity_id):
    session_db = db()
    try:
        kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        rows = _prl_rows_for_concert(session_db, kind, row)
        header = _roadmap_export_header(kind, row)
        from openpyxl import Workbook
        wb = Workbook()
        ws = wb.active
        ws.title = "PRL"
        ws.append([f"Listado de Alta y PRL · {header['title']} · {header['date']}"])
        ws.append([])
        ws.append(["Nombre y apellidos", "DNI", "Función", "Tipo de alta", "Alta OK", "Baja OK",
                   "Información OK", "Formación OK", "EPIs OK", "Renuncia médica OK",
                   "Doc alta", "Doc baja", "Doc información", "Doc formación", "Doc EPIs",
                   "Doc renuncia médica"])

        def _xmark(slot):
            """SÍ / NO, o vacío si ese documento no se le pide a esta persona."""
            if not slot.get("required", True):
                return ""
            return "SÍ" if slot.get("ok") else "NO"

        for r in rows:
            ws.append([
                r["full_name"], r["dni"], r["role"], r["worker_type_label"] or "",
                "SÍ" if r["alta"]["ok"] else "NO",
                _xmark(r.get("baja") or {}),
                "SÍ" if r["informacion"]["ok"] else "NO",
                "SÍ" if r["formacion"]["ok"] else "NO",
                _xmark(r.get("epis") or {}),
                _xmark(r.get("renuncia_medico") or {}),
                (r["alta"]["doc"] or {}).get("file_url", ""),
                ((r.get("baja") or {}).get("doc") or {}).get("file_url", ""),
                (r["informacion"]["doc"] or {}).get("file_url", ""),
                (r["formacion"]["doc"] or {}).get("file_url", ""),
                ((r.get("epis") or {}).get("doc") or {}).get("file_url", ""),
                ((r.get("renuncia_medico") or {}).get("doc") or {}).get("file_url", ""),
            ])
        buf = BytesIO()
        wb.save(buf)
        buf.seek(0)
        return send_file(buf, mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                         as_attachment=True, download_name="listado_prl.xlsx")
    finally:
        session_db.close()


def _prl_ita_link_people(session_db, workers: list) -> list:
    """Vincula los trabajadores detectados en un ITA con terceros/usuarios por DNI (o nombre)."""
    linked = []
    if not workers:
        return linked
    by_dni = {}
    for p in session_db.query(Promoter).filter(Promoter.tax_id.isnot(None)).all():
        norm = _prl_norm_dni(p.tax_id)
        if norm:
            by_dni[norm] = f"PROMOTER:{p.id}"
    try:
        _inactive = _inactive_user_ids(session_db)          # ni eliminados ni bloqueados
        for u in session_db.query(UserProfile).filter(UserProfile.dni.isnot(None)).all():
            if u.user_id in _inactive:
                continue
            norm = _prl_norm_dni(u.dni)
            if norm and norm not in by_dni:
                by_dni[norm] = f"USER:{u.user_id}"
    except Exception:
        pass
    for w in workers:
        ref = by_dni.get(_prl_norm_dni(w.get("ipf") or ""))
        if ref and ref not in linked:
            linked.append(ref)
    return linked


@app.post('/administracion/altas/subir', endpoint='admin_ita_upload')
@admin_required
def admin_ita_upload():
    """Sube el ITA mensual de una empresa del grupo: detecta la fecha (válido el mes en vigor)
    y vincula automáticamente a las personas que aparecen en el informe por su DNI."""
    session_db = db()
    try:
        company = session_db.get(GroupCompany, to_uuid(request.form.get("company_id") or "") or uuid.uuid4())
        f = request.files.get("file")
        if not company or not f or not f.filename:
            flash("Falta la empresa o el archivo del ITA", "danger")
            return redirect(safe_next_or(url_for("administracion_view", tab="altas")))
        data = f.read(); f.seek(0)
        is_pdf = (f.filename or "").lower().endswith(".pdf")
        url = upload_pdf(f, "documents") if is_pdf else upload_file(f, "documents")
        if not url:
            flash("No se pudo guardar el archivo", "danger")
            return redirect(safe_next_or(url_for("administracion_view", tab="altas")))
        det = _prl_detect("ITA", _pdf_extract_text_bytes(data) if is_pdf else "", None)
        linked = _prl_ita_link_people(session_db, (det["meta"].get("workers") or []))
        doc = PersonComplianceDoc(
            owner_type="COMPANY", owner_id=company.id, doc_type="ITA", company_id=company.id,
            file_url=url, original_name=(f.filename or "")[:200], mime_type=f.mimetype,
            valid_from=det["valid_from"], valid_until=det["valid_until"], status="APPROVED",
            linked_person_ids=linked, detected_meta=det["meta"], uploaded_via="ADMIN",
        )
        session_db.add(doc)
        session_db.commit()
        n = len((det["meta"].get("workers") or []))
        if det["meta"].get("detected"):
            flash(f"ITA de {company.name} subido: válido hasta {doc.valid_until.strftime('%d/%m/%Y')} · "
                  f"{n} trabajadores detectados ({len(linked)} vinculados)", "success")
        else:
            flash("ITA subido, pero no se pudo leer la fecha del informe: revísalo a mano", "warning")
        return redirect(safe_next_or(url_for("administracion_view", tab="altas")))
    except Exception:
        session_db.rollback()
        raise
    finally:
        session_db.close()


PARTY_DEBT_KINDS = [("ADELANTO", "Adelanto", "fa-hand-holding-dollar"),
                    ("DEUDA", "Deuda", "fa-file-invoice-dollar")]
PARTY_DEBT_LABELS = {k: l for k, l, _i in PARTY_DEBT_KINDS}


def _party_debt_rows(session_db, *, promoter_id=None, artist_id=None, only_open: bool = True) -> list[dict]:
    """ADELANTOS y DEUDAS de una persona/tercero (o de un artista) con las empresas del grupo.

    Es el aviso que pidió Dani antes de abonarle algo: si la casa le ha adelantado dinero o nos debe
    algo, se ve al ir a pagarle. `pending` es lo que queda por recuperar."""
    if not promoter_id and not artist_id:
        return []
    try:
        q = (session_db.query(PartyDebt)
             .options(joinedload(PartyDebt.company)))
        condiciones = []
        if promoter_id:
            condiciones.append(PartyDebt.promoter_id == to_uuid(str(promoter_id)))
        if artist_id:
            condiciones.append(PartyDebt.artist_id == to_uuid(str(artist_id)))
        q = q.filter(or_(*condiciones)) if len(condiciones) > 1 else q.filter(condiciones[0])
        if only_open:
            q = q.filter(func.upper(func.coalesce(PartyDebt.status, "ABIERTA")) == "ABIERTA")
        filas = []
        for d in q.order_by(PartyDebt.created_at.desc()).limit(50).all():
            importe = _money_or_zero(d.amount)
            recuperado = _money_or_zero(d.amount_recovered)
            pendiente = importe - recuperado
            if only_open and pendiente <= 0:
                continue
            filas.append({
                "id": str(d.id),
                "kind": (d.kind or "ADELANTO").upper(),
                "kind_label": PARTY_DEBT_LABELS.get((d.kind or "ADELANTO").upper(), "Adelanto"),
                "company_name": (getattr(d.company, "name", None) or "—"),
                "concept": (d.concept or ""),
                "amount": importe,
                "recovered": recuperado,
                "pending": pendiente,
                "date_label": (d.debt_date.strftime("%d/%m/%Y") if d.debt_date else ""),
                "due_label": (d.due_date.strftime("%d/%m/%Y") if d.due_date else ""),
                "document_url": (d.document_url or ""),
            })
        return filas
    except Exception:
        return []


# Datos que una factura tiene que traer para poder validarla y contabilizarla.
SUPPLIER_INVOICE_REQUIRED = [
    ("invoice_number", "el número de factura"),
    ("issue_date", "la fecha de emisión"),
    ("amount_net", "la base imponible"),
    ("amount_gross", "el importe total"),
]


def _supplier_invoice_missing_fields(inv) -> list[str]:
    """Qué DATOS le faltan a una factura (los que no se pudieron leer del documento).

    Es lo que hace que una factura no se pueda dar por buena. Se comprueba al subirla (para que quien
    la sube los escriba) y se avisa en la bandeja de administración, con enlace para corregirla a
    mano: así una que se haya colado se reincorpora a su proceso en vez de quedarse muerta.
    """
    if inv is None:
        return []
    faltan = []
    for campo, etiqueta in SUPPLIER_INVOICE_REQUIRED:
        valor = getattr(inv, campo, None)
        if campo in ("amount_net", "amount_gross"):
            if _money_or_zero(valor) <= 0:
                faltan.append(etiqueta)
        elif not valor:
            faltan.append(etiqueta)
    return faltan


def _invoice_required_data_check(form) -> tuple[bool, str]:
    """¿Trae el formulario los datos obligatorios de la factura? (comprobación del SERVIDOR).

    El navegador ya no deja enviar sin ellos, pero eso solo vale si el JS ha corrido: la última
    palabra la tiene el servidor.
    """
    dinero = _invoice_amount_fields_from_form(form)
    faltan = []
    if not (form.get("invoice_number") or "").strip():
        faltan.append("el número de factura")
    if not parse_optional_date(form.get("issue_date")):
        faltan.append("la fecha de emisión")
    # ⚠️ La BASE es obligatoria: es el número que se compara con lo que hay que facturar. Sin ella, una
    # factura con retención no se puede dar por buena (el total ya lleva la retención descontada).
    if _money_or_zero(dinero.get("amount_net")) <= 0:
        faltan.append("la base imponible")
    if _money_or_zero(dinero.get("amount_gross")) <= 0:
        faltan.append("el importe total")
    if faltan:
        return False, ("No hemos podido leer %s: escríbelo a mano antes de enviar la factura."
                       % _join_es(faltan))
    # ⚠️⚠️ UNA RETENCIÓN QUE LA FACTURA NO LLEVA DESCUADRA TODO: baja lo que se paga y mete la factura
    # en el listado fiscal de Retenciones. Si con los números escritos base + IVA YA es el total, la
    # retención no cabe ahí: se rechaza diciéndolo (el campo, además, solo se pide si la factura la
    # trae).
    base = _money_or_zero(dinero.get("amount_net"))
    iva = _money_or_zero(dinero.get("amount_vat"))
    ret = _money_or_zero(dinero.get("retention_amount"))
    total = _money_or_zero(dinero.get("amount_gross"))
    if ret > 0 and abs((base + iva) - total) <= Decimal("0.02") and abs(ret) > Decimal("0.02"):
        return False, ("Has puesto una retención de %s, pero la base y el IVA ya suman el total de la "
                       "factura (%s): si la factura no lleva retención, deja ese campo vacío."
                       % (format_eur(ret), format_eur(total)))
    return True, ""


def _join_es(items) -> str:
    """«a, b y c» (para los mensajes en claro)."""
    items = [x for x in (items or []) if x]
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    return ", ".join(items[:-1]) + " y " + items[-1]


def _orphan_supplier_invoices(session_db, *, limit: int = 100) -> list[dict]:
    """Facturas subidas que NO cuelgan de nada: ni de una liquidación, ni de una bolsa, ni de una
    persona. Son las que se quedaron en el limbo y nadie ve.

    Es la red de seguridad del enlace de royalties: si alguna se subió cuando el enlace caducado se
    comportaba como la landing genérica, aquí aparece y se puede vincular a su liquidación.
    """
    filas = []
    try:
        invoices = (session_db.query(SupplierInvoice)
                    .options(joinedload(SupplierInvoice.promoter))
                    .filter(func.upper(func.coalesce(SupplierInvoice.status, "")) == "PENDIENTE")
                    .filter(SupplierInvoice.royalty_liquidation_id.is_(None))
                    .filter(SupplierInvoice.bag_id.is_(None))
                    .filter(SupplierInvoice.bag_expense_id.is_(None))
                    .filter(SupplierInvoice.invoice_request_id.is_(None))
                    .filter(SupplierInvoice.target_user_id.is_(None))
                    .order_by(SupplierInvoice.created_at.desc()).limit(limit).all())
    except Exception:
        return filas
    for inv in invoices:
        promoter = inv.promoter
        filas.append({
            "invoice": inv,
            "id": str(inv.id),
            "name": (_promoter_display_name(promoter) or getattr(promoter, "nick", None) or "Proveedor"),
            "promoter_id": (str(promoter.id) if promoter is not None else ""),
            "number": (inv.invoice_number or ""),
            "concept": (inv.concept_text or ""),
            "amount": _money_or_zero(inv.amount_gross),
            "uploaded": (inv.created_at.strftime("%d/%m/%Y") if inv.created_at else ""),
            "file_url": (inv.file_url or ""),
            "missing": _supplier_invoice_missing_fields(inv),
            "edit_url": url_for("supplier_invoice_edit", invoice_id=inv.id),
        })
    return filas


def _royalty_liquidation_link_options(session_db, *, limit: int = 300) -> list[dict]:
    """Liquidaciones a las que se puede vincular una factura suelta (enviadas o ya facturadas)."""
    salida = []
    try:
        recs = (session_db.query(RoyaltyLiquidation)
                .filter(func.upper(func.coalesce(RoyaltyLiquidation.status, "")).in_(
                    ["SENT", "GENERATED", "INVOICED"]))
                .order_by(RoyaltyLiquidation.period_start.desc()).limit(limit).all())
    except Exception:
        return salida
    for rec in recs:
        congelada = _royalty_frozen_beneficiary(rec) or {}
        salida.append({
            "id": str(rec.id),
            "label": "%s · %s%s" % (
                (congelada.get("name") or "Beneficiario"),
                _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
                (" · ya tiene factura" if getattr(rec, "invoice_id", None) else "")),
        })
    return salida


@app.post("/administracion/facturas/<invoice_id>/vincular-royalties", endpoint="administration_invoice_link_royalty")
@admin_required
def administration_invoice_link_royalty(invoice_id):
    """Vincula una factura SUELTA a su liquidación de royalties, para reincorporarla al proceso."""
    if not (can_edit_invoices() or has_access_key("administracion", edit=True, include_descendants=True)):
        return forbid("Tu usuario no puede vincular facturas.")
    session_db = db()
    try:
        inv = session_db.get(SupplierInvoice, to_uuid(invoice_id) or uuid.uuid4())
        rec = session_db.get(RoyaltyLiquidation, to_uuid(request.form.get("liquidation_id") or "") or uuid.uuid4())
        if inv is None or rec is None:
            flash("No se ha encontrado la factura o la liquidación.", "warning")
            return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="liquidacion")))
        if getattr(rec, "invoice_id", None) and str(rec.invoice_id) != str(inv.id):
            anterior = session_db.get(SupplierInvoice, rec.invoice_id)
            if anterior is not None and (anterior.status or "").upper() == "VALIDADA":
                flash("Esa liquidación ya tiene una factura VALIDADA: revísala antes de cambiarla.", "warning")
                return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="liquidacion")))
        inv.royalty_liquidation_id = rec.id
        rec.invoice_id = inv.id
        rec.status = "INVOICED"
        rec.invoice_uploaded_at = rec.invoice_uploaded_at or (inv.created_at or _now_madrid())
        rec.updated_at = _now_madrid()
        _royalty_history_add(rec, "INVOICED", file_url=(inv.file_url or ""),
                             note="Vinculada a mano por administración")
        session_db.commit()
        flash("Factura vinculada a la liquidación: ya está pendiente de validar.", "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo vincular la factura: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="liquidacion")))


def _royalty_beneficiary_promoter(session_db, rec):
    """QUIÉN emite la factura de una liquidación: el tercero al que se le vincula.

    · Beneficiario TERCERO → él mismo.
    · Beneficiario ARTISTA → el tercero que le factura: primero sus INTEGRANTES
      (`ArtistPerson.promoter_id`, que es el caso de un solista o de quien cobra por el grupo) y, si
      no, el tercero VINCULADO al artista (mánager, sociedad que le factura…). Si hay más de un
      candidato no se elige por su cuenta: se devuelve la lista para preguntarlo.

    Devuelve `(promoter, candidatos)`: con `promoter` puesto ya se puede crear la factura; si viene
    None y hay `candidatos`, hay que elegir.

    ⚠️⚠️ **SI LA FACTURA YA ESTÁ SUBIDA, QUIEN LA EMITE ES SU PROVEEDOR**: al subirla por el enlace de
    ESA liquidación, quien la sube se identifica con su DNI/CIF y la factura se guarda con su
    `promoter_id` (que además es NOT NULL). Mirando solo el beneficiario, una liquidación de un
    artista sin integrantes ni terceros vinculados salía como «no se sabe quién emite esta factura»
    aunque la factura estuviera ahí con su emisor (bug real, ago 2026). Así que lo primero es la
    factura y el beneficiario es el respaldo (para cuando todavía no hay factura).
    """
    try:
        inv = (session_db.get(SupplierInvoice, rec.invoice_id)
               if getattr(rec, "invoice_id", None) else None)
        if inv is not None and getattr(inv, "promoter_id", None):
            emisor = session_db.get(Promoter, inv.promoter_id)
            if emisor is not None:
                return emisor, []
    except Exception:
        app.logger.exception("[royalties] no se pudo leer el emisor de la factura")
    kind = (getattr(rec, "beneficiary_kind", None) or "").upper()
    bid = getattr(rec, "beneficiary_id", None)
    if not bid:
        return None, []
    if kind == "PROMOTER":
        return session_db.get(Promoter, bid), []
    candidatos = []
    vistos = set()
    try:
        for pr in (session_db.query(Promoter)
                   .join(ArtistPerson, ArtistPerson.promoter_id == Promoter.id)
                   .filter(ArtistPerson.artist_id == bid).all()):
            if str(pr.id) not in vistos:
                vistos.add(str(pr.id))
                candidatos.append(pr)
    except Exception:
        pass
    if not candidatos:
        try:
            for link in (session_db.query(ThirdPartyLink)
                         .filter(ThirdPartyLink.is_active.is_(True))
                         .filter(or_(and_(ThirdPartyLink.source_type == "artist",
                                          ThirdPartyLink.source_id == bid,
                                          ThirdPartyLink.target_type == "promoter"),
                                     and_(ThirdPartyLink.target_type == "artist",
                                          ThirdPartyLink.target_id == bid,
                                          ThirdPartyLink.source_type == "promoter"))).all()):
                pid = (link.target_id if (link.source_type or "") == "artist" else link.source_id)
                pr = session_db.get(Promoter, pid) if pid else None
                if pr is not None and str(pr.id) not in vistos:
                    vistos.add(str(pr.id))
                    candidatos.append(pr)
        except Exception:
            pass
    if len(candidatos) == 1:
        return candidatos[0], candidatos
    return None, candidatos


def _royalty_invoice_pending_rows(session_db) -> list:
    """Facturas de liquidaciones de royalties recibidas y PENDIENTES de validar (tarea de
    administración). Incluye el aviso de EMBARGO vigente sobre el proveedor."""
    rows = []
    try:
        invoices = (session_db.query(SupplierInvoice)
                    .options(joinedload(SupplierInvoice.promoter))
                    .filter(SupplierInvoice.status == "PENDIENTE")
                    .filter(SupplierInvoice.royalty_liquidation_id.isnot(None))
                    .order_by(SupplierInvoice.created_at.desc()).all())
    except Exception:
        return rows
    for inv in invoices:
        rec = session_db.get(RoyaltyLiquidation, inv.royalty_liquidation_id) if inv.royalty_liquidation_id else None
        promoter = inv.promoter
        embargos = []
        if promoter is not None and "_active_embargo_orders_for_promoter" in globals():
            try:
                embargos = [_embargo_order_summary(o) for o in _active_embargo_orders_for_promoter(session_db, promoter)]
            except Exception:
                embargos = []
        rows.append({
            "invoice": inv,
            "liquidation": rec,
            "promoter": promoter,
            "name": (promoter.nick if promoter else "Proveedor"),
            # Datos que no se pudieron leer del documento: se avisa y se corrigen a mano.
            "missing": _supplier_invoice_missing_fields(inv),
            "edit_url": url_for("supplier_invoice_edit", invoice_id=inv.id),
            "period_label": (_royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end) if rec else ""),
            "embargos": embargos,
            "url": url_for("administration_royalty_invoice_review", invoice_id=inv.id),
        })
    return rows


@app.get('/administracion/royalties/factura/<invoice_id>', endpoint='administration_royalty_invoice_review')
@admin_required
def administration_royalty_invoice_review(invoice_id):
    """Validación de la factura de una liquidación: la liquidación a la IZQUIERDA y la factura
    (con la documentación exigida) a la DERECHA."""
    session_db = db()
    try:
        inv = session_db.get(SupplierInvoice, to_uuid(invoice_id) or uuid.uuid4())
        if not inv:
            abort(404)
        rec = session_db.get(RoyaltyLiquidation, inv.royalty_liquidation_id) if inv.royalty_liquidation_id else None
        promoter = session_db.get(Promoter, inv.promoter_id)
        # LO QUE SE ENVIÓ, no lo que saldría hoy (punto único `_royalty_effective_beneficiary`).
        beneficiary, congelada_ok = (None, False)
        if rec is not None:
            beneficiary, congelada_ok = _royalty_effective_beneficiary(
                session_db, rec, rec.beneficiary_kind, str(rec.beneficiary_id),
                rec.period_start.year, 1 if rec.period_start.month <= 6 else 2)
        embargos = []
        if promoter is not None and "_active_embargo_orders_for_promoter" in globals():
            try:
                embargos = [_embargo_order_summary(o) for o in _active_embargo_orders_for_promoter(session_db, promoter)]
            except Exception:
                embargos = []
        docs = _billing_docs_state(session_db, promoter, _billing_profile_payload(session_db, promoter)["kind"]) if promoter else []
        # ¿Le hemos adelantado dinero o nos debe algo? Se avisa antes de validar (y de pagar).
        deudas = _party_debt_rows(
            session_db,
            promoter_id=(inv.promoter_id or None),
            artist_id=(rec.beneficiary_id if (rec is not None and (rec.beneficiary_kind or "").upper() == "ARTIST") else None),
        )
        # La factura se enseña ABIERTA: hay que saber si es PDF o imagen para incrustarla.
        nombre = ((inv.original_name or "") + " " + (inv.file_url or "")).lower()
        es_pdf = ".pdf" in nombre
        es_imagen = (not es_pdf) and any(x in nombre for x in (".png", ".jpg", ".jpeg", ".webp", ".gif", ".heic"))
        # LO QUE SE LE PIDIÓ FACTURAR: la base de la liquidación MÁS el IVA. Es el número que tienen
        # que decir la liquidación, la factura y el pago; comparar contra la base sola hacía saltar el
        # aviso siempre.
        esperado = _royalty_invoice_totals(beneficiary)
        fac_bruto = _money_or_zero(getattr(inv, "amount_gross", None))
        fac_ret = (_money_or_zero(getattr(inv, "retention_amount", None))
                   or _money_or_zero((beneficiary or {}).get("retention_amount")))
        # Si la FACTURA trae su propio desglose (leído al subirla o corregido a mano), manda el de la
        # factura: es el documento con el que se paga. Si no, lo que se le pidió facturar.
        if fac_bruto > 0:
            # Si la factura no viene desglosada, el desglose que se enseña es el que se pidió
            # facturar (si no, la fila del IVA desaparecía aunque se sepa cuánto es).
            totales = {
                "net": (_money_or_zero(inv.amount_net) or esperado["net"]),
                "vat": (_money_or_zero(inv.amount_vat) or
                        (esperado["vat"] if _money_or_zero(inv.amount_net) <= 0 else Decimal("0"))),
                "vat_pct": (_money_or_zero(inv.vat_pct) or esperado["vat_pct"]),
                "gross": fac_bruto,
                "unknown": False,
            }
            # ⚠️ El total de la factura YA lleva la retención descontada (es «lo que se paga»):
            # volver a restarla aquí pagaría de menos.
            pago = fac_bruto
        else:
            totales = esperado
            pago = esperado["gross"] - fac_ret
        # Solo se avisa si la factura no cuadra con lo que se pidió facturar. Una RETENCIÓN no es un
        # descuadre: el total viene menguado a propósito. Y hay quien factura sin IVA.
        descuadra = bool(fac_bruto > 0
                         and abs(esperado["gross"] - (fac_bruto + fac_ret)) > Decimal("0.01")
                         and abs(esperado["gross"] - fac_bruto) > Decimal("0.01")
                         and abs(esperado["net"] - fac_bruto) > Decimal("0.01"))
        cuadre = _royalty_invoice_checks(inv, esperado, totales, fac_ret, pago)
        return render_template(
            "administration_royalty_invoice.html",
            inv=inv, liquidation=rec, promoter=promoter, beneficiary=beneficiary,
            invoice_totals=totales,
            # CUADRE concepto a concepto (base · IVA · retención · a pagar): verde lo que cuadra y
            # rojo lo que no, para verlo de un golpe antes de validar.
            checks=cuadre,
            # Retención (de la propia factura o del congelado) y lo que de verdad se abona.
            retention=fac_ret,
            retention_pct=_money_or_zero(getattr(inv, "retention_pct", None)),
            pay_total=pago,
            # Lo que se PIDIÓ facturar: es contra esto contra lo que se compara (y lo que necesita el
            # modal de corregir importes para ofrecer «la diferencia es una retención»).
            expected_gross=esperado["gross"],
            expected_net=esperado["net"],
            frozen=bool(congelada_ok),
            period_label=(_royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end) if rec else ""),
            embargos=embargos,
            debts=deudas,
            required_docs=[d for d in docs if d["key"] != "INVOICE"],
            invoice_is_pdf=es_pdf,
            invoice_is_image=es_imagen,
            amount_mismatch=descuadra,
        )
    finally:
        session_db.close()


def _royalty_invoice_checks(inv, esperado: dict, totales: dict, retencion, pago) -> dict:
    """¿CUADRA la factura con la liquidación? Concepto a concepto, para pintarlo verde o rojo.

    Lo que se comprueba, y por qué cada uno:
      · BASE     → tiene que ser la de la liquidación (es el número que se pidió facturar).
      · IVA      → el que sale de aplicar su % a la base (si la factura no lo desglosa, no se juzga).
      · RETENCIÓN→ solo si la factura la trae: que el % que dice cuadre con el importe.
      · A PAGAR  → base + IVA − retención. ⚠️ Con retención el importe a pagar es MENOR que lo que se
        liquida, y eso es correcto: lo que se comprueba es que el cálculo salga, no que sea igual.
    Cada entrada trae `ok` (True/False/None = no se puede juzgar) y una explicación."""
    cent = Decimal("0.01")

    def _cerca(a, b, tol=cent):
        return abs(_money_or_zero(a) - _money_or_zero(b)) <= tol

    base_esp = _money_or_zero(esperado.get("net"))
    base_fac = _money_or_zero(getattr(inv, "amount_net", None)) or _money_or_zero(totales.get("net"))
    iva_fac = _money_or_zero(getattr(inv, "amount_vat", None))
    pct_iva = _money_or_zero(getattr(inv, "vat_pct", None)) or _money_or_zero(esperado.get("vat_pct"))
    ret = _money_or_zero(retencion)
    pct_ret = _money_or_zero(getattr(inv, "retention_pct", None))
    total_fac = _money_or_zero(getattr(inv, "amount_gross", None))

    filas = {}
    # BASE
    if base_esp <= 0 or base_fac <= 0:
        filas["net"] = {"ok": None, "note": "No se puede comprobar: falta la base."}
    elif _cerca(base_fac, base_esp):
        filas["net"] = {"ok": True, "note": "Es la base de la liquidación."}
    else:
        filas["net"] = {"ok": False,
                        "note": "La liquidación dice %s y la factura %s." % (format_eur(base_esp), format_eur(base_fac))}
    # IVA
    if iva_fac <= 0:
        filas["vat"] = {"ok": None, "note": ("La factura no desglosa el IVA."
                                             if base_fac > 0 else "Sin datos.")}
    elif pct_iva > 0 and base_fac > 0:
        esperado_iva = (base_fac * pct_iva / Decimal("100")).quantize(cent)
        filas["vat"] = ({"ok": True, "note": "%g%% de la base." % float(pct_iva)}
                        if _cerca(iva_fac, esperado_iva, Decimal("0.02"))
                        else {"ok": False, "note": "El %g%% de %s serían %s."
                              % (float(pct_iva), format_eur(base_fac), format_eur(esperado_iva))})
    else:
        filas["vat"] = {"ok": None, "note": "Sin porcentaje no se puede comprobar."}
    # RETENCIÓN (solo si la hay)
    if ret <= 0:
        filas["retention"] = {"ok": None, "note": "La factura no lleva retención."}
    elif pct_ret > 0 and base_fac > 0:
        esperada_ret = (base_fac * pct_ret / Decimal("100")).quantize(cent)
        filas["retention"] = ({"ok": True, "note": "%g%% de la base." % float(pct_ret)}
                              if _cerca(ret, esperada_ret, Decimal("0.02"))
                              else {"ok": False, "note": "El %g%% de %s serían %s."
                                    % (float(pct_ret), format_eur(base_fac), format_eur(esperada_ret))})
    else:
        filas["retention"] = {"ok": True, "note": "Se descuenta de lo que se le paga."}
    # A PAGAR: base + IVA − retención
    calculado = (base_fac + iva_fac - ret) if base_fac > 0 else Decimal("0")
    a_pagar = total_fac if total_fac > 0 else _money_or_zero(pago)
    if base_fac <= 0 or a_pagar <= 0:
        filas["total"] = {"ok": None, "note": "No se puede comprobar."}
    elif _cerca(a_pagar, calculado, Decimal("0.02")):
        filas["total"] = {"ok": True,
                          "note": ("Base + IVA − retención." if ret > 0 else "Base + IVA.")}
    else:
        filas["total"] = {"ok": False, "note": "Base + IVA%s serían %s."
                          % ((" − retención" if ret > 0 else ""), format_eur(calculado))}
    filas["all_ok"] = all(v.get("ok") is not False for k, v in filas.items() if k != "all_ok")
    return filas


@app.post('/administracion/royalties/factura/<invoice_id>/validar', endpoint='administration_royalty_invoice_validate')
@admin_required
def administration_royalty_invoice_validate(invoice_id):
    """Acepta la factura (la liquidación queda pendiente de pago) o la rechaza con un motivo
    (se avisa al proveedor y la liquidación vuelve a «enviada», pendiente de facturar)."""
    session_db = db()
    try:
        inv = session_db.get(SupplierInvoice, to_uuid(invoice_id) or uuid.uuid4())
        if not inv:
            abort(404)
        rec = session_db.get(RoyaltyLiquidation, inv.royalty_liquidation_id) if inv.royalty_liquidation_id else None
        action = (request.form.get("action") or "").strip().lower()
        nick = _email_to_nick(_current_user_email() or "")
        if action == "reject":
            reason = (request.form.get("reason") or "").strip()
            inv.status = "RECHAZADA"
            inv.reject_reason = reason
            inv.validated_at = _now_madrid()
            inv.validated_by_nick = nick
            if rec is not None:
                # ⚠️ Además de volver a «enviada», hay que SOLTAR la factura: si la liquidación
                # sigue apuntando a una factura rechazada, para el resto de la app sigue facturada
                # (mismo fallo que ya se corrigió en la base de facturas).
                if str(getattr(rec, "invoice_id", "") or "") == str(inv.id):
                    rec.invoice_id = None
                rec.status = "SENT"          # vuelve a «enviada» = pendiente de facturar
                rec.updated_at = _now_madrid()
                _royalty_history_add(rec, "INVOICE_REJECTED", note=reason, file_url=(inv.file_url or ""))
            # ⚠️ El aviso lo compone `_supplier_invoice_reject_notify`, el MISMO de la base de
            # facturas: lleva el motivo y —lo que faltaba aquí— el ENLACE para subir la corregida.
            # Antes se mandaba un «vuelve a subirla» a secas, sin decir dónde, y además se decía
            # «aviso enviado» sin comprobar que hubiera salido.
            _mail_ok, _mail_info = _supplier_invoice_reject_notify(session_db, inv, reason)
            session_db.commit()
            if _mail_ok:
                flash("Factura rechazada y aviso enviado a %s." % _mail_info, "warning")
            else:
                flash("Factura rechazada, pero NO se ha podido avisar al proveedor: %s"
                      % (_mail_info or "correo no enviado"), "danger")
        else:
            inv.status = "VALIDADA"
            inv.validated_at = _now_madrid()
            inv.validated_by_nick = nick
            if rec is not None:
                rec.status = "INVOICED"      # facturada y validada = pendiente de pago
                rec.updated_at = _now_madrid()
                rec.invoice_id = inv.id
                if not getattr(rec, "invoice_uploaded_at", None):
                    rec.invoice_uploaded_at = getattr(inv, "created_at", None) or _now_madrid()
                _royalty_history_add(rec, "INVOICED", note="validada por administración",
                                     file_url=(inv.file_url or ""))
            session_db.commit()
            flash("Factura validada: la liquidación queda pendiente de pago.", "success")
        return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="liquidacion")))
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo procesar la factura: {exc}", "danger")
        return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="liquidacion")))
    finally:
        session_db.close()


def _afavor_admin_pending_rows(session_db) -> list:
    """Liquidaciones a favor con FACTURA PEDIDA (tarea de administración: emitirla y enviarla)."""
    rows = []
    try:
        recs = (session_db.query(AfavorLiquidation)
                .options(joinedload(AfavorLiquidation.company))
                .filter(AfavorLiquidation.status == "PENDING_INVOICE")
                .order_by(AfavorLiquidation.invoice_requested_at.desc()).all())
    except Exception:
        return rows
    for rec in recs:
        rows.append({
            "rec": rec,
            "company": rec.company,
            "name": (rec.company.nick if rec.company else "Compañía"),
            "period_label": _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            "url": url_for("administration_afavor_invoice", liq_id=rec.id),
        })
    return rows


def _afavor_liquidation_songs(session_db, rec) -> list:
    """Canciones (con sus datos) de la liquidación a favor de esa compañía y semestre."""
    payload = _build_afavor_groups(session_db, rec.period_start)
    out = []
    for g in payload.get("groups") or []:
        for block in g.get("companies") or []:
            if str(block.get("company_id")) == str(rec.company_id):
                out.extend(block.get("songs") or [])
    return out


@app.get('/administracion/royalties-afavor/<liq_id>', endpoint='administration_afavor_invoice')
@admin_required
def administration_afavor_invoice(liq_id):
    """Emitir la factura de una liquidación A FAVOR: la liquidación a la izquierda y, a la derecha,
    los datos de facturación (la empresa del grupo que factura es siempre PIES) y la subida."""
    session_db = db()
    try:
        rec = session_db.get(AfavorLiquidation, to_uuid(liq_id) or uuid.uuid4())
        if not rec:
            abort(404)
        company = session_db.get(Promoter, rec.company_id)
        billing_company = _afavor_pies_company(session_db)
        emails = _bag_provider_email_suggestions(
            session_db, SimpleNamespace(provider=company, provider_id=rec.company_id)) if company else []
        return render_template(
            "administration_afavor_invoice.html",
            rec=rec, company=company, billing_company=billing_company,
            songs=_afavor_liquidation_songs(session_db, rec),
            period_label=_royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            status=_afavor_status_meta(rec.status),
            recipients=emails,
        )
    finally:
        session_db.close()


@app.post('/administracion/royalties-afavor/<liq_id>/factura', endpoint='administration_afavor_invoice_upload')
@admin_required
def administration_afavor_invoice_upload(liq_id):
    """Sube la factura emitida (arrastrada o elegida). No la envía todavía."""
    session_db = db()
    try:
        rec = session_db.get(AfavorLiquidation, to_uuid(liq_id) or uuid.uuid4())
        if not rec:
            abort(404)
        f = request.files.get("file")
        if not f or not f.filename:
            flash("Falta el archivo de la factura.", "warning")
            return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
        filename = (f.filename or "factura").strip()
        is_pdf = filename.lower().endswith(".pdf") or (f.mimetype or "") == "application/pdf"
        url = upload_pdf(f, "invoices") if is_pdf else upload_file(f, "invoices")
        if not url:
            flash("No se pudo guardar la factura.", "danger")
            return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
        rec.invoice_url = url
        rec.invoice_name = filename[:200]
        rec.invoice_number = (request.form.get("invoice_number") or "").strip() or rec.invoice_number
        amount = (request.form.get("invoice_amount") or "").strip()
        if amount:
            rec.invoice_amount = _money_or_zero(amount)
        rec.updated_at = _now_madrid()
        session_db.commit()
        flash("Factura subida. Revísala y pulsa «Enviar factura».", "success")
        return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo subir la factura: {exc}", "danger")
        return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
    finally:
        session_db.close()


@app.post('/administracion/royalties-afavor/<liq_id>/enviar', endpoint='administration_afavor_invoice_send')
@admin_required
def administration_afavor_invoice_send(liq_id):
    """Envía la factura a la persona de la compañía: la liquidación pasa a FACTURADO y la factura
    queda pendiente de cobro."""
    session_db = db()
    try:
        rec = session_db.get(AfavorLiquidation, to_uuid(liq_id) or uuid.uuid4())
        if not rec:
            abort(404)
        if not (rec.invoice_url or "").strip():
            flash("Sube primero la factura.", "warning")
            return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
        company = session_db.get(Promoter, rec.company_id)
        recipients = [e for e in (request.form.getlist("recipients") or []) if _looks_like_email_address(e)]
        extra = (request.form.get("extra_emails") or "").strip()
        if extra:
            recipients += [x.strip() for x in re.split(r"[;,\n]+", extra) if _looks_like_email_address(x.strip())]
        if not recipients and company is not None:
            recipients = [e["email"] for e in _bag_provider_email_suggestions(
                session_db, SimpleNamespace(provider=company, provider_id=rec.company_id))][:2]
        recipients = _dedupe_valid_email_addresses(recipients)
        if not recipients:
            flash("No hay ningún correo válido al que enviar la factura.", "warning")
            return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
        pies = _afavor_pies_company(session_db)
        pies_logo = (getattr(pies, "logo_url", None) or _external_url_for("static", filename="img/logo.png"))
        period_label = _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end)
        body = f"""
        <div style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:640px;margin:0 auto;">
          <div style="text-align:right;margin-bottom:6px;"><img src="{escape(pies_logo)}" alt="PIES" style="max-height:48px;max-width:180px;object-fit:contain;"></div>
          <h2 style="text-align:center;font-size:20px;color:#111;margin:0 0 16px;">Factura de royalties</h2>
          <div style="border:1px solid #e5e7eb;border-radius:14px;padding:14px 16px;background:#f9fafb;margin:0 0 14px;">
            <div style="font-size:16px;font-weight:700;color:#111;">{escape(getattr(company, 'nick', '') or 'Compañía')}</div>
            <div style="font-size:13px;color:#6b7280;margin-top:2px;">Periodo: {escape(period_label)}</div>
          </div>
          <p style="font-size:14px;color:#374151;margin:0 0 14px;">Adjuntamos la factura correspondiente a la liquidación de royalties del periodo indicado.</p>
          <p style="text-align:center;margin:18px 0;">
            <a href="{escape(rec.invoice_url)}" style="background:#E33D48;color:#fff;text-decoration:none;padding:12px 26px;border-radius:8px;font-weight:600;display:inline-block;">Ver / descargar la factura</a>
          </p>
          <p style="font-size:13px;color:#6b7280;margin:0;">Cualquier duda, responda a este correo.</p>
        </div>
        """
        ok, err = _send_optional_email(recipients, f"Factura de royalties · {period_label}", body)
        if not ok:
            flash(f"No se pudo enviar la factura: {err or 'error'}", "danger")
            return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
        rec.status = "INVOICED"
        rec.invoice_sent_at = _now_madrid()
        rec.invoice_sent_to = recipients
        rec.updated_at = _now_madrid()
        session_db.commit()
        flash(f"Factura enviada a {', '.join(recipients)}. Queda pendiente de cobro.", "success")
        return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="facturacion")))
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo enviar la factura: {exc}", "danger")
        return redirect(url_for("administration_afavor_invoice", liq_id=liq_id))
    finally:
        session_db.close()


@app.get('/discografica/royalties/afavor/<liq_id>/pdf', endpoint='afavor_liquidation_pdf')
@admin_required
def afavor_liquidation_pdf(liq_id):
    """PDF de la liquidación A FAVOR: logo de PIES arriba a la derecha, título centrado, cabecera de
    la compañía, etiqueta del periodo y el listado de canciones (sin importes: van en Ingresos)."""
    if not REPORTLAB_AVAILABLE:
        abort(503)
    session_db = db()
    try:
        rec = session_db.get(AfavorLiquidation, to_uuid(liq_id) or uuid.uuid4())
        if not rec:
            abort(404)
        company = session_db.get(Promoter, rec.company_id)
        songs = _afavor_liquidation_songs(session_db, rec)
        period_label = _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end)
        pies = _afavor_pies_company(session_db)
        buf = BytesIO()
        doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=32, rightMargin=32, topMargin=24, bottomMargin=24)
        styles = getSampleStyleSheet()
        t_style = ParagraphStyle('AfT', parent=styles['Title'], alignment=TA_CENTER, fontSize=16, leading=19)
        h_style = ParagraphStyle('AfH', parent=styles['Normal'], fontSize=11, leading=13, fontName='Helvetica-Bold')
        s_style = ParagraphStyle('AfS', parent=styles['Normal'], fontSize=8, leading=10)
        story = []
        logo = _fetch_image_reader(getattr(pies, 'logo_url', None) or '')
        logo_cell = RLImage(logo, width=110, height=40, kind='proportional') if logo else ''
        lr = Table([['', logo_cell]], colWidths=[411, 120])
        lr.setStyle(TableStyle([('ALIGN', (1, 0), (1, 0), 'RIGHT')]))
        story.append(lr)
        story.append(Paragraph('Liquidación de Royalties · a favor', t_style))
        story.append(Spacer(1, 6))
        clogo = _fetch_image_reader(getattr(company, 'logo_url', None) or '')
        head = Table([[RLImage(clogo, width=46, height=46, kind='proportional') if clogo else '',
                       Paragraph(getattr(company, 'nick', '') or 'Compañía', h_style)]], colWidths=[56, 475])
        head.setStyle(TableStyle([
            ('BOX', (0, 0), (-1, -1), 0.7, colors.HexColor('#e5e7eb')),
            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor('#f9fafb')),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('LEFTPADDING', (0, 0), (-1, -1), 8), ('TOPPADDING', (0, 0), (-1, -1), 6),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
        ]))
        story.append(head)
        story.append(Spacer(1, 8))
        story.append(Paragraph(f"Periodo de liquidación: <b>{escape(period_label)}</b>", s_style))
        story.append(Spacer(1, 8))
        data = [[Paragraph(x, s_style) for x in ['Canción', 'Artista y colaboradores', 'Publicación', 'ISRC', 'A favor']]]
        for it in songs:
            who = it.get('artist_name') or ''
            if it.get('collaborators'):
                who += f" · {it['collaborators']}"
            data.append([
                Paragraph(escape(it.get('title') or ''), s_style),
                Paragraph(escape(who), s_style),
                Paragraph(it.get('release_date') or '—', s_style),
                Paragraph(it.get('isrc') or '—', s_style),
                Paragraph(f"{it.get('our_pct')}% {it.get('base_label') or ''}", s_style),
            ])
        tbl = Table(data, colWidths=[150, 175, 70, 80, 56], repeatRows=1)
        tbl.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#E33D48')),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
            ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#e5e7eb')),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#f8f9fb')]),
        ]))
        story.append(tbl)
        doc.build(story)
        buf.seek(0)
        name = (getattr(company, 'nick', '') or 'compania').replace(' ', '_')
        return send_file(buf, mimetype='application/pdf', as_attachment=True,
                         download_name=f"liquidacion_afavor_{name}.pdf")
    finally:
        session_db.close()


