def roadmap_templates_list(entity_type, entity_id):
    """Plantillas del artista disponibles para cargar en esta hoja de ruta."""
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        return jsonify({"ok": True, "templates": _roadmap_templates_for(session_db, row)})
    finally:
        session_db.close()


@app.post("/hoja-ruta/<entity_type>/<entity_id>/plantillas/<tid>/cargar", endpoint="roadmap_template_load")
@admin_required
def roadmap_template_load(entity_type, entity_id, tid):
    """Carga una plantilla en la hoja de ruta de la actividad.

    · PERSONAL: añade a la gente que no esté ya (no duplica).
    · ROOMING: trae los hoteles con su reparto de habitaciones. Quien esté en la plantilla y NO en el
      personal de la actividad se devuelve en `extras` para que se decida: añadirlo al personal o
      dejarlo fuera (`mode=add_missing` / `mode=skip_missing`). Quien esté en el personal y no en la
      plantilla se queda simplemente SIN habitación.
    · HOJA DE RUTA: copia los puntos de la agenda mapeando Día 1, 2, 3… a los días de la actividad.
    """
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        tpl = session_db.get(ArtistTemplate, to_uuid(tid))
        if not row or not tpl:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        modo = (request.form.get("mode") or (request.get_json(silent=True) or {}).get("mode") or "").strip().lower()
        payload = _roadmap_load(row)
        origen = _roadmap_load(tpl)
        resumen = {"ok": True, "kind": tpl.kind, "name": tpl.name}

        if tpl.kind == "PERSONNEL":
            res = _artist_template_copy_personnel(origen, payload)
            _roadmap_save(session_db, row, payload)
            resumen.update(added=res["added"], skipped=res["skipped"],
                           payload=payload, days=_roadmap_days(row, payload),
                           message=(f"{res['added']} persona(s) añadida(s)"
                                    + (f", {res['skipped']} ya estaba(n)" if res["skipped"] else "")))
            return jsonify(resumen)

        if tpl.kind == "ROOMING":
            # ¿Quién de la plantilla no está en el personal de la actividad?
            actuales = {_artist_template_person_key(p): p for p in (payload.get("personnel") or [])}
            faltan = [p for p in (origen.get("personnel") or [])
                      if _artist_template_person_key(p) not in actuales]
            if faltan and modo not in ("add_missing", "skip_missing"):
                # Se pregunta antes de tocar nada.
                return jsonify({"ok": True, "needs_decision": True, "kind": "ROOMING",
                                "name": tpl.name,
                                "missing": [{"name": (p.get("name") or "").strip() or "Sin nombre",
                                             "role": (p.get("role") or "")} for p in faltan]})
            id_map = {}
            if modo == "add_missing":
                res = _artist_template_copy_personnel(origen, payload)
                id_map = res["id_map"]
            else:
                # Solo se mapea a quien ya está; el resto se cae del reparto.
                for p in (origen.get("personnel") or []):
                    actual = actuales.get(_artist_template_person_key(p))
                    if actual:
                        id_map[str(p.get("id"))] = str(actual.get("id"))
            # ¿A qué días se aplica el reparto? La plantilla es de UNA NOCHE (solo guarda quién va
            # con quién); aquí se eligen los días de la actividad (por defecto, todos).
            dias_actividad = [d["date"] for d in _roadmap_days(row, payload)]
            pedidos = [x for x in (request.form.getlist("days")
                                   or ((request.get_json(silent=True) or {}).get("days") or []))
                       if str(x)[:10] in dias_actividad]
            dias = sorted({str(x)[:10] for x in pedidos}) or dias_actividad
            hoteles = payload.setdefault("hotels", [])
            copiados = 0
            for hotel in (origen.get("hotels") or []):
                nuevo = dict(hotel)
                nuevo["id"] = _roadmap_new_id()
                nuevo["attachments"] = []
                nuevo["days"] = list(dias)
                nuevo["assignee_ids"] = [id_map[x] for x in (hotel.get("assignee_ids") or []) if x in id_map]
                habitaciones = []
                for hab in (hotel.get("rooms") or []):
                    h = dict(hab)
                    h["id"] = _roadmap_new_id()
                    h["occupant_ids"] = [id_map[x] for x in (hab.get("occupant_ids") or []) if x in id_map]
                    # El mismo reparto para todos los días elegidos.
                    h["day_from"] = dias[0] if dias else ""
                    h["day_to"] = dias[-1] if dias else ""
                    habitaciones.append(h)
                nuevo["rooms"] = habitaciones
                hoteles.append(nuevo)
                copiados += 1
            _roadmap_save(session_db, row, payload)
            sin_habitacion = [p for p in (payload.get("personnel") or [])
                              if not any(str(p.get("id")) in (hab.get("occupant_ids") or [])
                                         for h in hoteles for hab in (h.get("rooms") or []))]
            _dias_txt = (f"{len(dias)} día{'s' if len(dias) != 1 else ''}"
                         if len(dias) != len(dias_actividad) else "todos los días")
            resumen.update(hotels=copiados, unassigned=len(sin_habitacion), days_applied=dias,
                           payload=payload, days=_roadmap_days(row, payload),
                           message=(f"{copiados} hotel(es) con su reparto · {_dias_txt}"
                                    + (f" · {len(sin_habitacion)} sin habitación" if sin_habitacion else "")))
            return jsonify(resumen)

        # HOJA DE RUTA (horarios)
        dias = _roadmap_days(row, payload)
        nuevos = _template_agenda_for_days(origen, dias)
        payload.setdefault("agenda", []).extend(nuevos)
        _roadmap_save(session_db, row, payload)
        resumen.update(items=len(nuevos), payload=payload, days=_roadmap_days(row, payload),
                       message=f"{len(nuevos)} punto(s) añadido(s) a la agenda")
        return jsonify(resumen)
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("roadmap_template_load")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post("/hoja-ruta/<entity_type>/<entity_id>/plantillas/guardar", endpoint="roadmap_template_save_from")
@admin_required
def roadmap_template_save_from(entity_type, entity_id):
    """Guarda lo que hay en esta hoja de ruta COMO plantilla del artista (personal / rooming / agenda)."""
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        data = request.get_json(silent=True) or request.form
        kind = (data.get("kind") or "").strip().upper()
        if kind not in ARTIST_TEMPLATE_LABELS:
            return jsonify({"ok": False, "error": "Tipo no válido."}), 400
        ids = [to_uuid(x) for x in _roadmap_artist_ids(row) if to_uuid(x)]
        if not ids:
            return jsonify({"ok": False, "error": "Esta actividad no tiene artista al que guardarle la plantilla."}), 400
        payload = _roadmap_load(row)
        dias = _roadmap_days(row, payload)
        nuevo = {"version": 2, "personnel": [], "hotels": [], "agenda": []}
        if kind in ("PERSONNEL", "ROOMING"):
            nuevo["personnel"] = [dict(p) for p in (payload.get("personnel") or [])]
        if kind == "ROOMING":
            # Se guarda el REPARTO, no las fechas: la plantilla es de una noche y los días se
            # eligen al cargarla.
            for hotel in (payload.get("hotels") or []):
                h = dict(hotel)
                h["attachments"] = []
                h["days"] = []
                habitaciones = []
                for r in (hotel.get("rooms") or []):
                    hr = dict(r)
                    hr.pop("day_from", None)
                    hr.pop("day_to", None)
                    habitaciones.append(hr)
                h["rooms"] = habitaciones
                nuevo["hotels"].append(h)
        if kind == "ROADMAP":
            # Los días reales se convierten en Día 1, 2, 3… (el anclaje de las plantillas).
            fechas = [d["date"] for d in dias]
            anclas = _template_day_list(max(1, len(fechas)))
            for it in (payload.get("agenda") or []):
                copia = dict(it)
                copia["attachments"] = []
                try:
                    idx = fechas.index(str(it.get("day"))[:10])
                except ValueError:
                    idx = 0
                copia["day"] = anclas[min(idx, len(anclas) - 1)]
                nuevo["agenda"].append(copia)
        st = _current_user_state()
        tpl = ArtistTemplate(
            artist_id=ids[0], kind=kind,
            name=((data.get("name") or "").strip() or f"{ARTIST_TEMPLATE_LABELS[kind]}")[:160],
            day_count=max(1, min(len(dias) or 1, TEMPLATE_MAX_DAYS)),
            roadmap_payload=nuevo,
            created_by_user_id=to_uuid(st.get("user_id")) if st.get("user_id") else None,
            created_by_nick=(st.get("nick") or "").strip() or None,
        )
        session_db.add(tpl)
        session_db.commit()
        return jsonify({"ok": True, "id": str(tpl.id), "name": tpl.name,
                        "url": url_for("artist_template_edit", tid=tpl.id)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("roadmap_template_save_from")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


ROADMAP_KINDS = [("GENERAL", "Hoja de ruta general", "fa-route"),
                 ("TECNICA", "Hoja de ruta técnica", "fa-sliders")]
ROADMAP_KIND_LABELS = {k: l for k, l, _i in ROADMAP_KINDS}


def _roadmap_kinds(row) -> dict:
    """Qué hojas de ruta tiene activas la actividad. Sin nada guardado, las DOS."""
    pay = getattr(row, "roadmap_payload", None)
    pay = pay if isinstance(pay, dict) else {}
    saved = pay.get("kinds")
    if not isinstance(saved, dict):
        return {k: True for k, _l, _i in ROADMAP_KINDS}
    return {k: bool(saved.get(k, True)) for k, _l, _i in ROADMAP_KINDS}


def _set_roadmap_kinds(row, kinds: dict) -> None:
    pay = dict(getattr(row, "roadmap_payload", None) or {})
    pay["kinds"] = {k: bool(kinds.get(k)) for k, _l, _i in ROADMAP_KINDS}
    row.roadmap_payload = pay


def _parse_roadmap_kinds_form(form) -> dict:
    """Etiquetas del formulario. Si el formulario no las trae (altas antiguas), las dos activas."""
    if not form.get("roadmap_kinds_present"):
        return {k: True for k, _l, _i in ROADMAP_KINDS}
    picked = {(v or "").strip().upper() for v in form.getlist("roadmap_kinds")}
    return {k: (k in picked) for k, _l, _i in ROADMAP_KINDS}


def _ensure_roadmap_token(session_db, row, kind: str = "GENERAL") -> str:
    """Devuelve el token público de la hoja de ruta pedida, creándolo si no existe."""
    if (kind or "GENERAL").upper() == "TECNICA":
        pay = dict(getattr(row, "roadmap_payload", None) or {})
        token = (pay.get("tech_token") or "").strip()
        if not token:
            token = _uuid_token()
            pay["tech_token"] = token
            row.roadmap_payload = pay
            session_db.flush()
        return token
    token = (getattr(row, "roadmap_public_token", None) or "").strip()
    if not token:
        token = _uuid_token()
        row.roadmap_public_token = token
        session_db.flush()
    return token


def _roadmap_by_token(session_db, token: str):
    """Busca la entidad (concert/action/promotion) por su token público de hoja de ruta.

    Devuelve (fila, tipo, clase) — la clase es GENERAL o TECNICA según con qué enlace se entra."""
    token = (token or "").strip()
    if not token:
        return None, None, "GENERAL"
    for model, kind, opts in (
        (Concert, "concert", (joinedload(Concert.artist), joinedload(Concert.venue))),
        (CompanyAction, "action", (joinedload(CompanyAction.venue),)),
        (Promotion, "promotion", (joinedload(Promotion.company),)),
    ):
        row = session_db.query(model).options(*opts).filter(model.roadmap_public_token == token).first()
        if row:
            return row, kind, "GENERAL"
        row = (
            session_db.query(model).options(*opts)
            .filter(model.roadmap_payload["tech_token"].astext == token)
            .first()
        )
        if row:
            return row, kind, "TECNICA"
    return None, None, "GENERAL"


@app.post('/hoja-ruta/<entity_type>/<entity_id>/enlace', endpoint='roadmap_public_link')
@admin_required
def roadmap_public_link(entity_type, entity_id):
    """Gestiona el enlace público (solo lectura) de la hoja de ruta.
    action: 'ensure' (por defecto, crea si falta) · 'regenerate' (nuevo token, el anterior deja
    de funcionar) · 'revoke' (anula el enlace)."""
    session_db = db()
    try:
        _kind, row = _roadmap_entity(session_db, entity_type, entity_id)
        if not row:
            abort(404)
        data = request.get_json(silent=True) or {}
        action = (data.get("action") or "ensure").strip().lower()
        kind = (data.get("kind") or "GENERAL").strip().upper()
        if kind not in ROADMAP_KIND_LABELS:
            kind = "GENERAL"
        is_tech = kind == "TECNICA"
        if action == "revoke":
            if is_tech:
                _pay = dict(getattr(row, "roadmap_payload", None) or {})
                _pay.pop("tech_token", None)
                row.roadmap_payload = _pay
            else:
                row.roadmap_public_token = None
            session_db.commit()
            return jsonify({"ok": True, "url": "", "token": "", "kind": kind})
        if action == "regenerate":
            if is_tech:
                _pay = dict(getattr(row, "roadmap_payload", None) or {})
                _pay["tech_token"] = _uuid_token()
                row.roadmap_payload = _pay
            else:
                row.roadmap_public_token = _uuid_token()
        token = _ensure_roadmap_token(session_db, row, kind)
        session_db.commit()
        return jsonify({"ok": True, "url": _external_url_for("public_roadmap_view", token=token), "token": token, "kind": kind})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.get('/hoja-ruta/ver/<token>', endpoint='public_roadmap_view')
def public_roadmap_view(token):
    """Vista pública de solo lectura de la hoja de ruta (sin login). Permite ver toda la
    información y descargar los adjuntos, sin poder editar nada."""
    session_db = db()
    try:
        row, entity_type, roadmap_kind = _roadmap_by_token(session_db, token)
        if not row:
            abort(404)
        # Si esa hoja de ruta se ha desactivado en la actividad, el enlace deja de servir.
        if not _roadmap_kinds(row).get(roadmap_kind, True):
            abort(404)
        ctx = _roadmap_context(session_db, entity_type, row)
        # Solo los puntos de la agenda marcados para ESTA hoja de ruta (etiquetas del punto), y los
        # días se recalculan con lo que queda para no enseñar días vacíos que no le tocan.
        ctx["payload"] = _roadmap_payload_for_kind(ctx.get("payload") or {}, roadmap_kind)
        ctx["days"] = _roadmap_days(row, ctx["payload"])
        ctx["readonly"] = True
        ctx["kind"] = roadmap_kind
        ctx["kind_label"] = ROADMAP_KIND_LABELS.get(roadmap_kind, "Hoja de ruta")
        artists = _artists_from_ids(session_db, _roadmap_artist_ids(row))
        title = ctx.get("title") or "Hoja de ruta"
        # Previsualización (og): cartel principal / foto del artista + 2ª fila con los detalles.
        if entity_type == "concert":
            card = _public_share_card(session_db, "CONCERT", row, artist_id=getattr(row, "artist_id", None))
            og_image = _public_share_og_image(session_db, row, card=card)
        else:
            _aids = _roadmap_artist_ids(row)
            card = _public_share_card(session_db, "ACTION", row, artist_id=(_aids[0] if _aids else None))
            og_image = ""
        if not og_image:
            og_image = _absolute_media_url(card.get("artist_photo") or (getattr(artists[0], "photo_url", "") if artists else ""))
        # 2ª fila: tipo de actividad · fecha · municipio. Si el título ya muestra el municipio
        # (evento sin nombre propio), en su lugar se pone el nombre del recinto.
        municipio = (card.get("city") or "").strip()
        location = municipio
        if municipio and municipio.casefold() in (title or "").casefold():
            venue_name = (getattr(getattr(row, "venue", None), "name", None) or "").strip()
            location = venue_name or municipio
        og_desc = " · ".join([x for x in [card.get("activity_label"), card.get("date_label"), location] if x])
        og_title = ""
        if entity_type == "promotion":
            # PROMOCIÓN: «Hoja de ruta Promoción» + el ARTISTA, y debajo el nombre de la promoción y
            # la fecha (sin nombre, solo la fecha). Si es UNA sola entrevista o un solo medio, se dice
            # de qué medio; con varios no, porque ya no identifica nada.
            _artista = (ctx.get("artist_label") or "").strip()
            og_title = " · ".join([x for x in ["Hoja de ruta Promoción", _artista] if x])
            _nombre = (getattr(row, "name", None) or "").strip()
            # ⚠️ `Promotion` NO tiene relación `activities`: sus entrevistas se consultan.
            _acts = (session_db.query(PromotionActivity)
                     .filter(PromotionActivity.promotion_id == row.id)
                     .order_by(PromotionActivity.activity_date.asc().nullslast()).all())
            _fecha = _promo_dates_label(_acts)
            _medio = _promo_single_media_label(session_db, _acts)
            og_desc = " · ".join([x for x in [_nombre, _fecha, _medio] if x])
        return render_template(
            'public_roadmap_view.html',
            rm=ctx,
            roadmap_kind=roadmap_kind,
            roadmap_kind_label=ROADMAP_KIND_LABELS.get(roadmap_kind, "Hoja de ruta"),
            og_title=og_title,
            title=title,
            artist_label=ctx.get("artist_label") or "",
            artist_photo=(getattr(artists[0], "photo_url", "") if artists else ""),
            og={"image": og_image, "description": og_desc},
        )
    finally:
        session_db.close()


def _tour_concerts_by_slug(session_db, slug: str) -> list[Concert]:
    rows = session_db.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue)).filter(or_(func.upper(func.coalesce(Concert.sale_type, '')) == 'GIRAS_COMPRADAS', func.upper(func.coalesce(Concert.activity_type, '')) == 'GIRA')).order_by(Concert.date.asc().nullslast(), Concert.created_at.desc()).all()
    return [row for row in rows if _tour_group_key(row)[0] == slug]


@app.get('/contratacion/giras-compradas/<slug>', endpoint='tour_detail_view')
@admin_required
def tour_detail_view(slug):
    tab = (request.args.get('tab') or 'info').strip().lower()
    if tab not in {'info', 'conciertos', 'onesheet'}:
        tab = 'info'
    session_db = db()
    try:
        concerts = _tour_concerts_by_slug(session_db, slug)
        if not concerts:
            flash('Gira no encontrada.', 'warning')
            return redirect(url_for('contracting_view', section='giras-compradas'))
        slug_key, title = _tour_group_key(concerts[0])
        artist_ids = []
        for c in concerts:
            for aid in _concert_primary_artist_ids(c):
                sid = str(aid)
                if sid not in artist_ids:
                    artist_ids.append(sid)
        tour = _get_or_create_tour_onesheet(session_db, slug_key, title, artist_ids)
        session_db.commit()
        available = session_db.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue)).filter(Concert.artist_id.in_(_as_uuid_list(artist_ids))).filter(~Concert.id.in_([c.id for c in concerts])).order_by(Concert.date.asc().nullslast()).limit(200).all() if artist_ids else []
        onesheet = _onesheet_context(session_db, tour=tour, concerts=concerts, public=False)
        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
        promoters = session_db.query(Promoter).options(selectinload(Promoter.companies)).order_by(Promoter.nick.asc()).all()
        companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        type_choices = [(k, CONCERT_SALE_TYPE_LABELS.get(k, k)) for k in CONCERTS_SECTION_ORDER]
        all_concert_tags = _collect_all_concert_tags(session_db)
        promoters_payload = [{
            "id": str(p.id),
            "nick": (p.nick or "").strip(),
            "logo_url": (p.logo_url or "").strip(),
            "companies": [_serialize_promoter_company(x) for x in (p.companies or [])],
        } for p in promoters]
        return render_template('tour_detail.html', slug=slug_key, title=title, tab=tab, concerts=concerts, available_concerts=available, tour=tour, onesheet=onesheet, artists=artists, promoters=promoters, promoters_payload=promoters_payload, companies=companies, type_choices=type_choices, all_concert_tags=all_concert_tags, CAN_EDIT_CONCERTS=can_edit_concerts())
    finally:
        session_db.close()


@app.post('/contratacion/giras-compradas/<slug>/conciertos/vincular', endpoint='tour_concert_link_existing')
@admin_required
def tour_concert_link_existing(slug):
    session_db = db()
    try:
        target_rows = _tour_concerts_by_slug(session_db, slug)
        title = _tour_group_key(target_rows[0])[1] if target_rows else slug.replace('-', ' ').title()
        tag = title
        ids = [to_uuid(x) for x in request.form.getlist('concert_ids[]') if (x or '').strip()]
        for cid in ids:
            row = session_db.get(Concert, cid)
            if not row:
                continue
            row.sale_type = 'GIRAS_COMPRADAS'
            tags = _concert_tags(row)
            if tag not in tags:
                tags.insert(0, tag)
            row.hashtags = tags
            row.updated_at = _now_madrid()
        session_db.commit()
        flash('Conciertos vinculados a la gira.', 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'Error vinculando conciertos: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(url_for('tour_detail_view', slug=slug, tab='conciertos'))


