def _resource_label_from_key(key: str) -> str:
    return (
        (key or "")
        .replace("_", " ")
        .replace(".", " · ")
        .strip()
        .title()
    ) or "Función"


def _now_madrid():
    return datetime.now(TZ_MADRID)


def _current_user_email() -> str:
    state = _current_user_state()
    return (state.get("email") or "").strip()


def _email_to_nick(email: str) -> str:
    local = (email or "usuario").split("@", 1)[0].strip()
    local = re.sub(r"[._-]+", " ", local).strip()
    return (local.title() or "Usuario")[:80]


def _normalize_departments(values) -> list[str]:
    aliases = {
        "administracion": "Administración",
        "administración": "Administración",
        "derechos": "Registros",
        "registro": "Registros",
        "registros": "Registros",
        "produccion": "Producción",
        "producción": "Producción",
        "promocion": "Marketing",
        "promoción": "Marketing",
        "marketing": "Marketing",
        "direccion": "Dirección",
        "dirección": "Dirección",
        "contratacion": "Contratación",
        "contratación": "Contratación",
    }
    allowed = {d.casefold(): d for d in PERSONNEL_DEPARTMENTS}
    out = []
    seen = set()
    for raw in _departments_iter(values):
        key = (raw or "").strip().casefold()
        val = aliases.get(key) or allowed.get(key)
        if not val:
            continue
        if val in seen:
            continue
        seen.add(val)
        out.append(val)
    return out


def _departments_iter(values) -> list[str]:
    """Los departamentos de un perfil, VENGAN COMO VENGAN.

    ⚠️ `UserProfile.departments` es una LISTA en JSONB, pero hay filas antiguas (y cualquier arreglo
    a mano en la BD) donde quedó guardado como TEXTO. Recorrer un texto con un `for` devuelve LETRAS,
    así que esa persona no casaba con ningún departamento y desaparecía de los selectores **sin dar
    ningún error** (bug real: al asignar producción no salían todas). Punto único para leerlos."""
    if values is None:
        return []
    if isinstance(values, (list, tuple, set)):
        return [str(v).strip() for v in values if str(v or "").strip()]
    if isinstance(values, str):
        texto = values.strip()
        if not texto:
            return []
        if texto[:1] in "[{":
            try:
                return _departments_iter(json.loads(texto))
            except Exception:
                pass
        return [x.strip() for x in re.split(r"[;,|/]+", texto) if x.strip()]
    if isinstance(values, dict):
        return [str(k).strip() for k, v in values.items() if v and str(k or "").strip()]
    return []


def _profile_departments(profile) -> list[str]:
    """Los departamentos de un perfil, ya normalizados al catálogo (`PERSONNEL_DEPARTMENTS`)."""
    return _normalize_departments(_departments_iter(getattr(profile, "departments", None)))


def _profile_in_department(profile, *names) -> bool:
    """¿Está esta persona en alguno de esos departamentos?

    Compara contra el catálogo (así da igual la caja, los acentos y los alias «produccion»/
    «Producción»), en vez de buscar una cadena exacta dentro de la lista."""
    buscados = set(_normalize_departments(names))
    if not buscados:
        return False
    return bool(buscados & set(_profile_departments(profile)))


def _normalize_admin_responsibilities(values) -> list[str]:
    """Limpia lo que llega del formulario contra el catálogo. Sin esto el JSONB acumula basura y
    los filtros dejan de casar."""
    allowed = {k.casefold(): k for k in ADMIN_RESPONSIBILITY_KEYS}
    out, seen = [], set()
    for raw in values or []:
        key = allowed.get((str(raw) or "").strip().casefold())
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(key)
    return out


def _admin_responsible_user_ids(session_db, responsibility: str) -> set:
    """UUIDs (en texto) de quienes son responsables de ese tipo de tarea. Vacío = no lo es nadie,
    y entonces la tarea la ven todos.

    Se exige que sigan estando en ADMINISTRACIÓN: si a alguien se le quita el departamento, deja de
    ser responsable aunque le queden marcas antiguas (si no, seguiría escondiéndole la tarea al
    resto). Y fuera los bloqueados y eliminados.
    """
    if not responsibility:
        return set()
    try:
        inactivos = _inactive_user_ids(session_db)
        out = set()
        for prof in session_db.query(UserProfile).all():
            uid = str(getattr(prof, "user_id", "") or "")
            if not uid or uid in inactivos:
                continue
            if "Administración" not in (getattr(prof, "departments", None) or []):
                continue
            if responsibility in (getattr(prof, "admin_responsibilities", None) or []):
                out.add(uid)
        return out
    except Exception:
        return set()


def _administration_people(session_db, responsibility: str | None = None) -> list[dict]:
    """Personal de ADMINISTRACIÓN (opcionalmente, solo los responsables de un tipo de tarea).
    ⚠️ `is_blocked`/`is_deleted` viven en UserSecurity, no en User: se filtran con
    `_inactive_user_ids` (un getattr sobre User siempre daría False y no filtraría nada)."""
    out = []
    try:
        inactivos = _inactive_user_ids(session_db)
        for prof in session_db.query(UserProfile).order_by(UserProfile.nick.asc()).all():
            uid = str(getattr(prof, "user_id", "") or "")
            if not uid or uid in inactivos:
                continue
            if "Administración" not in (getattr(prof, "departments", None) or []):
                continue
            duties = list(getattr(prof, "admin_responsibilities", None) or [])
            if responsibility and responsibility not in duties:
                continue
            out.append({"user_id": uid, "nick": (prof.nick or "").strip(),
                        "full_name": _profile_full_name(prof), "responsibilities": duties})
    except Exception:
        return []
    return out


def _current_user_admin_responsibilities() -> list[str]:
    """Responsabilidades de administración de quien está mirando (del estado cacheado, sin BD)."""
    try:
        prof = _current_user_state().get("profile")
        return list(getattr(prof, "admin_responsibilities", None) or [])
    except Exception:
        return []


def _admin_task_is_mine(session_db, responsibility: str | None) -> bool:
    """¿Le toca a quien está mirando? Sí si: es dirección · el tipo no tiene responsable asignado ·
    no tiene reparto propio · o es uno de sus responsables."""
    if not responsibility:
        return True
    try:
        if is_master():
            return True
        mias = _current_user_admin_responsibilities()
        if not mias:
            return True
        if responsibility in mias:
            return True
        return not _admin_responsible_user_ids(session_db, responsibility)
    except Exception:
        return True


def _normalize_assigned_artist_ids(values) -> list[str]:
    raw = []
    if isinstance(values, str):
        raw = [values]
    else:
        try:
            raw = list(values or [])
        except Exception:
            raw = []
    out = []
    seen = set()
    for value in raw:
        uid = _safe_uuid(value) if "_safe_uuid" in globals() else to_uuid(value)
        if not uid:
            continue
        sid = str(uid)
        if sid in seen:
            continue
        seen.add(sid)
        out.append(sid)
    return out


def _normalize_phone_rows(rows) -> list[dict]:
    out = []
    seen = set()
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        label = (row.get("label") or row.get("title") or "").strip()
        phone = (row.get("phone") or row.get("value") or "").strip()
        if not label and not phone:
            continue
        key = (label.casefold(), phone)
        if key in seen:
            continue
        seen.add(key)
        out.append({"label": label or "Móvil", "phone": phone})
    return out


def _parse_phone_rows_from_form(form, prefix: str = "phone") -> list[dict]:
    labels = form.getlist(f"{prefix}_label")
    numbers = form.getlist(f"{prefix}_value")
    rows = []
    for label, number in zip(labels or [], numbers or []):
        label = (label or "").strip()
        number = (number or "").strip()
        if not label and not number:
            continue
        rows.append({"label": label or "Móvil", "phone": number})
    return _normalize_phone_rows(rows)


def _profile_full_name(profile: UserProfile | None) -> str:
    if not profile:
        return ""
    return " ".join([x for x in [
        (getattr(profile, "first_name", None) or "").strip(),
        (getattr(profile, "last_name", None) or "").strip(),
    ] if x]).strip()


def _inactive_user_ids(session_db) -> set:
    """UUIDs del personal ELIMINADO o BLOQUEADO.

    Solo se ofrece/lista el personal ACTUAL: en los enlaces públicos (subida de facturas, PRL…),
    en los selectores de invitaciones y en los buscadores de vinculaciones. `is_blocked`/`is_deleted`
    viven en `UserSecurity` (no en `User`), así que hay que consultarlos aquí.
    """
    out = set()
    try:
        rows = (
            session_db.query(UserSecurity.user_id)
            .filter(or_(UserSecurity.is_deleted.is_(True), UserSecurity.is_blocked.is_(True)))
            .all()
        )
        for (uid,) in rows:
            if uid:
                out.add(uid)
    except Exception:
        return set()
    # ⚠️ Y los usuarios ESPEJO de un tercero con acceso externo a una producción: no son personal de
    # la casa, así que no salen en ningún listado ni selector de personal. Aquí se excluyen de golpe
    # en todos los sitios que ya usan este punto único.
    try:
        for (uid,) in (session_db.query(UserProfile.user_id)
                       .filter(UserProfile.is_external.is_(True)).all()):
            if uid:
                out.add(uid)
    except Exception:
        app.logger.exception("[personal] no se pudieron excluir los usuarios externos")
    return out


def _password_serializer() -> URLSafeTimedSerializer:
    return URLSafeTimedSerializer(app.secret_key, salt="backoffice-password")


def _make_password_token(user_id, purpose: str = "set") -> str:
    payload = {"user_id": str(user_id), "purpose": purpose}
    return _password_serializer().dumps(payload)


def _load_password_token(token: str, max_age: int = 60 * 60 * 24 * 7) -> dict | None:
    try:
        data = _password_serializer().loads(token, max_age=max_age)
        if not isinstance(data, dict):
            return None
        return data
    except (BadSignature, SignatureExpired):
        return None


