def _promotion_calendar_months(items, months_count=3):
    months = []
    today = today_local()
    month_cursor = date(today.year, today.month, 1)
    month_limit = _add_months(month_cursor, months_count)
    by_date = defaultdict(list)
    for item in items or []:
        dt = item.get("date")
        if not dt or dt < month_cursor or dt >= month_limit:
            continue
        by_date[dt].append(item)
    for month_idx in range(months_count):
        first_day = _add_months(month_cursor, month_idx)
        next_month = _add_months(first_day, 1)
        last_day = next_month - timedelta(days=1)
        start_day = first_day - timedelta(days=first_day.weekday())
        end_day = last_day + timedelta(days=(6 - last_day.weekday()))
        weeks = []
        cursor = start_day
        while cursor <= end_day:
            week = []
            for _ in range(7):
                week.append({
                    "date": cursor,
                    "in_month": cursor.month == first_day.month,
                    "items": list(by_date.get(cursor, [])),
                })
                cursor += timedelta(days=1)
            weeks.append(week)
        months.append({"key": first_day.strftime("%Y-%m"), "label": _month_label(first_day), "weeks": weeks})
    return months


def _promotion_creator_datasets(session_db):
    default_cover = url_for("static", filename="img/placeholder_photo.png")
    artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
    artist_items = [{"id": str(a.id), "name": a.name, "photo_url": (a.photo_url or default_cover)} for a in artists]

    song_rows = session_db.query(Song).options(selectinload(Song.artists)).order_by(Song.release_date.desc().nullslast(), Song.created_at.desc()).all()
    _annotate_song_display_fields(session_db, song_rows, persist=False)
    song_items = []
    for song in song_rows:
        song_items.append({
            "id": str(song.id),
            "artist_ids": [str(a.id) for a in (song.artists or []) if getattr(a, 'id', None)],
            "title": song.title,
            "subtitle": ", ".join([a.name for a in (song.artists or []) if getattr(a, 'name', None)]) or "—",
            "meta": (getattr(song, 'display_collaborator', None) or getattr(song, 'collaborator', None) or '').strip(),
            "cover_url": (song.cover_url or default_cover),
            "date": song.release_date.isoformat() if getattr(song, 'release_date', None) else "",
        })

    album_rows = session_db.query(Album).options(joinedload(Album.artist)).order_by(Album.release_date.desc().nullslast(), Album.created_at.desc()).all()
    album_items = []
    for album in album_rows:
        album_items.append({
            "id": str(album.id),
            "artist_ids": [str(album.artist_id)] if getattr(album, 'artist_id', None) else [],
            "title": album.title,
            "subtitle": (getattr(getattr(album, 'artist', None), 'name', None) or '—'),
            "meta": ("EP" if (getattr(album, 'album_type', None) or '').strip().upper() == 'EP' else 'Álbum'),
            "cover_url": (album.cover_url or default_cover),
            "date": album.release_date.isoformat() if getattr(album, 'release_date', None) else "",
        })

    concert_rows = session_db.query(Concert).options(joinedload(Concert.artist), joinedload(Concert.venue), joinedload(Concert.billing_company)).order_by(Concert.date.desc().nullslast(), Concert.created_at.desc()).all()
    concert_items = []
    for concert in concert_rows:
        concert_items.append({
            "id": str(concert.id),
            "artist_ids": [str(concert.artist_id)] if getattr(concert, 'artist_id', None) else [],
            "title": (getattr(getattr(concert, 'artist', None), 'name', None) or 'Concierto'),
            "subtitle": _concert_venue_name(concert) or 'Recinto pendiente',
            "meta": concert.date.strftime('%d/%m/%Y') if getattr(concert, 'date', None) else '',
            "cover_url": (getattr(getattr(concert, 'artist', None), 'photo_url', None) or default_cover),
            "date": concert.date.isoformat() if getattr(concert, 'date', None) else '',
            "default_company_id": str(concert.billing_company_id) if getattr(concert, 'billing_company_id', None) else '',
        })

    # Eventos propios (Bases de datos → Eventos): no cuelgan de ningún artista, así que se listan
    # siempre, sin filtrar por los artistas marcados.
    event_items = [{
        "id": str(ev.id),
        "artist_ids": [],
        "title": (ev.name or "Evento"),
        "subtitle": "Evento",
        "meta": "",
        "cover_url": (ev.logo_url or default_cover),
        "date": "",
        "any_artist": True,
    } for ev in session_db.query(AppEvent).order_by(AppEvent.name.asc()).all()]

    # Giras compradas y festivales/ciclos: se ELIGEN de las creadas en Contratación para que el
    # marketing quede colgado del contenedor y se vea en su ficha (antes la gira era texto libre y
    # la campaña se quedaba huérfana, sin aparecer en ningún sitio).
    tour_items = [{
        "id": str(t.id),
        "artist_ids": _promotion_normalized_artist_ids(
            ([str(t.artist_id)] if getattr(t, "artist_id", None) else []) + [str(x) for x in (getattr(t, "artist_ids", None) or [])]
        ),
        "title": (t.name or "Gira"),
        "subtitle": (getattr(getattr(t, "artist", None), "name", None) or "Gira comprada"),
        "meta": t.start_date.strftime('%d/%m/%Y') if getattr(t, "start_date", None) else "",
        "cover_url": ((t.logo_url or "").strip() or (getattr(getattr(t, "artist", None), "photo_url", None) or default_cover)),
        "date": t.start_date.isoformat() if getattr(t, "start_date", None) else "",
        "default_company_id": str(t.managing_company_id) if getattr(t, "managing_company_id", None) else "",
    } for t in (session_db.query(PurchasedTour)
                .options(joinedload(PurchasedTour.artist))
                .order_by(PurchasedTour.start_date.desc().nullslast(), PurchasedTour.created_at.desc()).all())]

    cycle_items = [{
        "id": str(cf.id),
        "artist_ids": [],
        "title": (cf.name or "Ciclo"),
        "subtitle": CYCLE_FESTIVAL_KIND_LABELS.get((cf.kind or "FESTIVAL").upper(), "Ciclo"),
        "meta": " · ".join([x for x in [(cf.edition or "").strip(), (cf.municipality or "").strip()] if x]),
        "cover_url": ((cf.logo_url or "").strip() or default_cover),
        "date": cf.start_date.isoformat() if getattr(cf, "start_date", None) else "",
        "default_company_id": str(cf.managing_company_id) if getattr(cf, "managing_company_id", None) else "",
        "any_artist": True,
    } for cf in session_db.query(CycleFestival).order_by(CycleFestival.start_date.desc().nullslast(), CycleFestival.created_at.desc()).all()]

    # Con su LOGO: los selectores de empresa del grupo se pintan con miniatura (select-with-thumbs).
    company_items = [{"id": str(c.id), "name": c.name, "logo_url": (c.logo_url or "").strip()}
                     for c in session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()]

    return {
        "artists": artist_items,
        "subjects": {
            "ARTIST": [{"id": x["id"], "artist_ids": [x["id"]], "title": x["name"], "subtitle": "Marketing general de artista", "meta": "Artista", "cover_url": x["photo_url"], "date": ""} for x in artist_items],
            "SONG": song_items,
            "ALBUM": album_items,
            "CONCERT": concert_items,
            "EVENT": event_items,
            "GIRA": tour_items,
            "CICLO": cycle_items,
        },
        "companies": company_items,
    }


