def _royalty_payment_pending_rows(session_db) -> list[dict]:
    """Liquidaciones de royalties con la factura VALIDADA y sin pagar: pendientes de pago.

    Se pagan a nombre de quien facturó (el `promoter_id` de la factura, que es de donde salen el IBAN
    y el BIC) y se agrupan bajo la empresa del grupo que factura los royalties (PIES). Llevan sus
    avisos: orden de embargo vigente y adelantos/deudas con la casa."""
    # ⚠️ Pendiente de pago = la factura está **VALIDADA**. `status='INVOICED'` solo dice que la
    # factura ha llegado (se pone al subirla por el enlace), así que filtrando por el estado a secas
    # se colaban liquidaciones sin factura o con la factura aún por validar: salían como filas vacías
    # («Beneficiario», sin datos) y sin importe. Se cruza con la factura.
    try:
        recs = (session_db.query(RoyaltyLiquidation)
                .join(SupplierInvoice, SupplierInvoice.id == RoyaltyLiquidation.invoice_id)
                .filter(func.upper(func.coalesce(RoyaltyLiquidation.status, "")) == "INVOICED")
                .filter(func.upper(func.coalesce(SupplierInvoice.status, "")) == "VALIDADA")
                .filter(RoyaltyLiquidation.paid_at.is_(None))
                .order_by(RoyaltyLiquidation.invoice_uploaded_at.asc().nullslast()).limit(400).all())
    except Exception:
        return []
    if not recs:
        return []
    try:
        company = _pies_group_company(session_db)
    except Exception:
        company = None
    company_id = str(getattr(company, "id", "") or "")
    filas = []
    for rec in recs:
        congelada = _royalty_frozen_beneficiary(rec) or {}
        inv = session_db.get(SupplierInvoice, rec.invoice_id) if getattr(rec, "invoice_id", None) else None
        promoter = session_db.get(Promoter, inv.promoter_id) if (inv is not None and inv.promoter_id) else None
        nombre = (_promoter_display_name(promoter)
                  or (getattr(promoter, "nick", None) or "").strip()
                  or (congelada.get("name") or "").strip())
        # LO QUE SE PAGA es lo que se le pidió facturar: la base de la liquidación MÁS el IVA. Así la
        # liquidación, la factura y la remesa dicen el mismo número.
        base = congelada
        if not base:
            try:
                base, _c = _royalty_effective_beneficiary(
                    session_db, rec, rec.beneficiary_kind, str(rec.beneficiary_id),
                    rec.period_start.year, 1 if rec.period_start.month <= 6 else 2)
            except Exception:
                base = None
            if base and not nombre:
                nombre = (base.get("name") or "").strip()
        totales = _royalty_invoice_totals(base or {})
        # LO QUE SE PAGA es lo que dice LA FACTURA (su total ya lleva descontada la retención, si la
        # hay); si la factura no trae importe, lo que se le pidió facturar menos la retención. Pagar
        # la base+IVA cuando la factura lleva retención sería pagar de más.
        ret_inv = (_money_or_zero(getattr(inv, "retention_amount", None))
                   or _money_or_zero((base or {}).get("retention_amount")))
        fac_inv = _money_or_zero(getattr(inv, "amount_gross", None)) if inv is not None else Decimal("0")
        importe = fac_inv if fac_inv > 0 else (totales["gross"] - ret_inv)
        # ¿El total de la factura CUADRA con lo que se le pidió facturar? Cuadra si es lo mismo, si lo
        # es al sumarle la retención (se la queda Hacienda) o si facturó sin IVA (la base). Si no
        # cuadra se avisa en la propia línea: se paga la factura, pero no a ciegas.
        descuadre = bool(fac_inv > 0 and totales["gross"] > 0
                         and abs(fac_inv - totales["gross"]) > Decimal("0.01")
                         and abs(fac_inv + ret_inv - totales["gross"]) > Decimal("0.01")
                         and abs(fac_inv - totales["net"]) > Decimal("0.01"))
        if not nombre:
            nombre = "Sin beneficiario"
        iban = (getattr(promoter, "bank_account", None) or "").strip()
        bic = (getattr(promoter, "bank_bic", None) or "").strip()
        faltan = sepa_check_payment({"name": nombre, "iban": iban, "bic": bic, "amount": importe})
        embargos = []
        if promoter is not None and "_active_embargo_orders_for_promoter" in globals():
            try:
                embargos = [_embargo_order_summary(o) for o in _active_embargo_orders_for_promoter(session_db, promoter)]
            except Exception:
                embargos = []
        deudas = _party_debt_rows(
            session_db,
            promoter_id=(getattr(promoter, "id", None)),
            artist_id=(rec.beneficiary_id if (rec.beneficiary_kind or "").upper() == "ARTIST" else None),
        )
        etiqueta, clase = _royalty_payment_state_meta(rec.status)
        filas.append({
            "id": str(rec.id),
            "kind": "royalty",
            "company_id": company_id,
            "name": nombre,
            "concept": "Royalties · " + _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            "period_label": _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end),
            "amount": importe,
            "net": (_money_or_zero(getattr(inv, "amount_net", None)) or totales["net"]),
            "vat": (_money_or_zero(getattr(inv, "amount_vat", None)) or totales["vat"]),
            "vat_pct": (_money_or_zero(getattr(inv, "vat_pct", None)) or totales["vat_pct"]),
            "retention": ret_inv,
            "retention_pct": _money_or_zero(getattr(inv, "retention_pct", None)),
            # Para poder CORREGIR A MANO los importes desde el pop-up de la factura.
            "invoice_id": (str(inv.id) if inv is not None else ""),
            "expected": totales["gross"],
            "mismatch": descuadre,
            "iban": iban,
            "iban_masked": (_iban_masked(iban) if iban else ""),
            "missing": faltan,
            # En español: la lista cruda de `sepa_check_payment` viene en inglés («amount», «iban»…)
            # y se estaba pintando tal cual.
            "missing_labels": [REMESA_MISSING_LABELS.get(x, x) for x in faltan],
            "status": (rec.status or "").upper(),
            "status_label": etiqueta,
            "status_badge": clase,
            "batch_id": str(getattr(rec, "payment_batch_id", "") or ""),
            "invoice_url": (getattr(inv, "file_url", None) or ""),
            "pdf_url": (rec.last_sent_pdf_url or rec.snapshot_pdf_url or ""),
            "review_url": (url_for("administration_royalty_invoice_review", invoice_id=inv.id) if inv is not None else ""),
            "embargos": embargos,
            "debts": deudas,
            "photo_url": (congelada.get("photo_url") or ""),
        })
    return filas


def _payment_batch_next_reference(session_db) -> str:
    """REM-aaaa-nnnn, correlativo por año."""
    year = today_local().year
    prefijo = f"REM-{year}-"
    ultimo = (session_db.query(PaymentBatch)
              .filter(PaymentBatch.reference.like(f"{prefijo}%"))
              .order_by(PaymentBatch.reference.desc()).first())
    siguiente = 1
    if ultimo is not None:
        try:
            siguiente = int((ultimo.reference or "").rsplit("-", 1)[-1]) + 1
        except Exception:
            siguiente = 1
    return f"{prefijo}{siguiente:04d}"


def _payment_batch_item_artists(session_db, items) -> dict:
    """De qué ARTISTA es cada pago de la remesa (para el PDF y la pantalla de aprobación).

    De un gasto de bolsa sale por su bolsa; de una liquidación de royalties, del beneficiario. Se
    resuelve de una tacada: una remesa puede llevar decenas de pagos."""
    salida = {}
    bag_por_item, art_ids = {}, set()
    exp_ids = [i.expense_id for i in items if getattr(i, "expense_id", None)]
    bags = {}
    if exp_ids:
        try:
            gastos = (session_db.query(BagExpense.id, BagExpense.bag_id)
                      .filter(BagExpense.id.in_(exp_ids)).all())
            bag_ids = [b for _e, b in gastos if b]
            if bag_ids:
                bags = {str(b.id): b for b in session_db.query(WorkflowBag)
                        .filter(WorkflowBag.id.in_(bag_ids)).all()}
            for eid, bid in gastos:
                bag = bags.get(str(bid or ""))
                if bag is not None:
                    bag_por_item[str(eid)] = bag
                    if getattr(bag, "artist_id", None):
                        art_ids.add(bag.artist_id)
        except Exception:
            bag_por_item = {}
    liq_ids = [i.royalty_liquidation_id for i in items if getattr(i, "royalty_liquidation_id", None)]
    liqs = {}
    if liq_ids:
        try:
            for rec in session_db.query(RoyaltyLiquidation).filter(RoyaltyLiquidation.id.in_(liq_ids)).all():
                liqs[str(rec.id)] = rec
                if (rec.beneficiary_kind or "").upper() == "ARTIST" and rec.beneficiary_id:
                    art_ids.add(rec.beneficiary_id)
        except Exception:
            liqs = {}
    artistas = {}
    if art_ids:
        try:
            artistas = {str(a.id): a for a in session_db.query(Artist)
                        .filter(Artist.id.in_(list(art_ids))).all()}
        except Exception:
            artistas = {}
    for item in items:
        nombre, foto, origen = "", "", ""
        bag = bag_por_item.get(str(getattr(item, "expense_id", "") or ""))
        if bag is not None:
            origen = (getattr(bag, "title", None) or "").strip()
            art = artistas.get(str(getattr(bag, "artist_id", "") or ""))
            if art is not None:
                nombre = (getattr(art, "name", None) or "").strip()
                foto = (getattr(art, "photo_url", None) or "")
        rec = liqs.get(str(getattr(item, "royalty_liquidation_id", "") or ""))
        if rec is not None:
            origen = origen or "Liquidación de royalties"
            art = artistas.get(str(getattr(rec, "beneficiary_id", "") or ""))
            if art is not None:
                nombre = nombre or (getattr(art, "name", None) or "").strip()
                foto = foto or (getattr(art, "photo_url", None) or "")
            if not nombre:
                congelada = _royalty_frozen_beneficiary(rec) or {}
                nombre = (congelada.get("name") or "").strip()
                foto = foto or (congelada.get("photo_url") or "")
        salida[str(item.id)] = {"artist_name": nombre, "artist_photo": foto, "source": origen}
    return salida


def _payment_batch_item_documents(session_db, items) -> dict:
    """La FACTURA de cada pago, para poder repasarla en la pantalla de aprobación."""
    salida = {}
    exp_ids = [i.expense_id for i in items if getattr(i, "expense_id", None)]
    gastos = {}
    if exp_ids:
        try:
            gastos = {str(e.id): e for e in session_db.query(BagExpense)
                      .filter(BagExpense.id.in_(exp_ids)).all()}
        except Exception:
            gastos = {}
    liq_ids = [i.royalty_liquidation_id for i in items if getattr(i, "royalty_liquidation_id", None)]
    facturas = {}
    if liq_ids:
        try:
            for rec in session_db.query(RoyaltyLiquidation).filter(RoyaltyLiquidation.id.in_(liq_ids)).all():
                inv = (session_db.get(SupplierInvoice, rec.invoice_id)
                       if getattr(rec, "invoice_id", None) else None)
                facturas[str(rec.id)] = inv
        except Exception:
            facturas = {}
    for item in items:
        url, numero = "", ""
        exp = gastos.get(str(getattr(item, "expense_id", "") or ""))
        if exp is not None:
            url = (getattr(exp, "attachment_url", None) or "")
            numero = (getattr(exp, "invoice_number", None) or "")
        inv = facturas.get(str(getattr(item, "royalty_liquidation_id", "") or ""))
        if inv is not None:
            url = url or (getattr(inv, "file_url", None) or "")
            numero = numero or (getattr(inv, "invoice_number", None) or "")
        bajo = url.lower()
        salida[str(item.id)] = {
            "doc_url": url,
            "invoice_number": numero,
            "doc_is_image": bool(re.search(r"\.(png|jpe?g|webp|gif|heic)(\?|$)", bajo)),
        }
    return salida


def _payment_batch_context(session_db, batch, *, with_documents: bool = False) -> dict:
    """Todo lo que enseña la ficha de una remesa: sus pagos, lo que falta y los totales."""
    items = (session_db.query(PaymentBatchItem)
             .options(joinedload(PaymentBatchItem.expense), joinedload(PaymentBatchItem.provider))
             .filter(PaymentBatchItem.batch_id == batch.id)
             .order_by(PaymentBatchItem.created_at.asc()).all())
    bank_slug = (getattr(getattr(batch, "bank", None), "file_format", None) or "SEPA_PAIN001")
    hoy = today_local()
    sujetos = _payment_batch_item_artists(session_db, items)
    docs = _payment_batch_item_documents(session_db, items) if with_documents else {}
    filas, total, incompletos, aprobados = [], Decimal("0"), 0, 0
    for item in items:
        importe = _money_or_zero(item.amount)
        faltan = sepa_check_payment({"name": item.beneficiary_name, "iban": item.beneficiary_iban,
                                     "bic": item.beneficiary_bic, "amount": importe},
                                    require_bic=bool(sepa_bank_profile(bank_slug).get("require_bic")))
        if faltan:
            incompletos += 1
        else:
            total += importe
        # FECHA DE PAGO: la del propio pago; los pagos de antes de que existiera este campo se quedan
        # con la de la remesa.
        fecha = getattr(item, "payment_date", None) or batch.execution_date or hoy
        if getattr(item, "approved_at", None):
            aprobados += 1
        filas.append({
            "id": str(item.id),
            "expense_id": str(item.expense_id or ""),
            "royalty_id": str(getattr(item, "royalty_liquidation_id", "") or ""),
            "provider_id": str(item.provider_id or ""),
            "name": (item.beneficiary_name or ""),
            "iban": (item.beneficiary_iban or ""),
            "iban_masked": _iban_masked(item.beneficiary_iban) if item.beneficiary_iban else "",
            "bic": (item.beneficiary_bic or ""),
            "concept": (item.concept or ""),
            "amount": importe,
            "missing": faltan,
            "missing_labels": [REMESA_MISSING_LABELS.get(x, x) for x in faltan],
            # Fecha en que se emite el pago (en el fichero del banco, la fecha de ejecución).
            "payment_date": fecha,
            "payment_date_iso": fecha.isoformat(),
            "payment_date_label": ("Hoy" if fecha == hoy else fecha.strftime("%d/%m/%Y")),
            "is_today": fecha == hoy,
            # Visto bueno de dirección a este pago.
            "approved": bool(getattr(item, "approved_at", None)),
            "approved_by": (getattr(item, "approved_by_nick", None) or ""),
            "approved_at_label": (item.approved_at.strftime("%d/%m/%Y %H:%M")
                                  if getattr(item, "approved_at", None) else ""),
            **(sujetos.get(str(item.id)) or {"artist_name": "", "artist_photo": "", "source": ""}),
            **(docs.get(str(item.id)) or {}),
        })
    etiqueta, clase = _payment_batch_status_meta(batch.status)
    return {
        "rows": filas,
        "total": total,
        "count_ready": len(filas) - incompletos,
        "count_incomplete": incompletos,
        "count_approved": aprobados,
        "count_pending_approval": len(filas) - aprobados,
        "approved": bool(getattr(batch, "approved_at", None)),
        "status_label": etiqueta,
        "status_badge": clase,
        "bank_slug": bank_slug,
        "bank_label": sepa_bank_profile(bank_slug).get("label"),
    }


def _payment_batch_refresh_total(session_db, batch) -> None:
    total = Decimal("0")
    for item in session_db.query(PaymentBatchItem).filter(PaymentBatchItem.batch_id == batch.id).all():
        total += _money_or_zero(item.amount)
    batch.total_amount = total
    batch.updated_at = _now_madrid()


def _payment_batch_add_expenses(session_db, batch, expense_ids) -> int:
    """Mete gastos en la remesa. Solo los de SU empresa: mezclar empresas en una remesa es pagar
    desde una cuenta lo que le toca a otra."""
    añadidos = 0
    ya = {str(i.expense_id) for i in session_db.query(PaymentBatchItem)
          .filter(PaymentBatchItem.batch_id == batch.id).all() if i.expense_id}
    for raw in expense_ids or []:
        try:
            eid = to_uuid(str(raw).strip())
        except Exception:
            continue
        if not eid or str(eid) in ya:
            continue
        expense = (session_db.query(BagExpense)
                   .options(joinedload(BagExpense.bag), joinedload(BagExpense.provider),
                            joinedload(BagExpense.provider_company))
                   .filter(BagExpense.id == eid).first())
        if expense is None:
            continue
        if (getattr(expense, "payment_status", None) or "").upper() == "PAGADO":
            continue
        bag_company = str(getattr(getattr(expense, "bag", None), "company_id", "") or "")
        if str(batch.company_id or "") and bag_company and bag_company != str(batch.company_id):
            continue
        ben = _expense_beneficiary(session_db, expense)
        session_db.add(PaymentBatchItem(
            batch_id=batch.id,
            expense_id=expense.id,
            provider_id=(to_uuid(ben["provider_id"]) if ben["provider_id"] else None),
            beneficiary_name=ben["name"] or None,
            beneficiary_iban=sepa_normalize_iban(ben["iban"]) or None,
            beneficiary_bic=(ben["bic"] or None),
            # El concepto del pago = el de la FACTURA que se paga (ver `_payment_concept_for_expense`).
            concept=_payment_concept_for_expense(session_db, expense),
            # LO QUE SE LE PAGA es el TOTAL DE LA FACTURA (con la retención ya descontada): es el
            # importe que va a recibir.
            amount=_expense_payment_amount(session_db, expense),
            # Por defecto se paga HOY; se puede cambiar pago a pago en la ficha de la remesa.
            payment_date=(batch.execution_date or today_local()),
        ))
        expense.payment_batch_id = batch.id
        ya.add(str(expense.id))
        añadidos += 1
    session_db.flush()
    _payment_batch_refresh_total(session_db, batch)
    return añadidos


def _payment_file_part(value: str) -> str:
    """Un trozo del nombre del fichero: sin acentos, sin separadores raros y sin espacios."""
    base = unicodedata.normalize("NFD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    base = re.sub(r"[^A-Za-z0-9]+", " ", base).strip()
    return re.sub(r"\s+", "", base.title())[:40]


def _payment_batch_file_name(session_db, batch) -> str:
    """Nombre del fichero de pagos, para reconocerlo de un vistazo en la carpeta y en el banco:

      · de UNA bolsa → `Remesa_<Artista>_<Festival o municipio>_<Fecha del evento>`
      · varios sueltos → `Remesa_Varios_<Fecha en que se genera>`

    Del evento se coge el nombre del FESTIVAL y, si no lo tiene, el MUNICIPIO."""
    bolsas, sueltos = set(), 0
    try:
        for item in (session_db.query(PaymentBatchItem)
                     .filter(PaymentBatchItem.batch_id == batch.id).all()):
            expense = session_db.get(BagExpense, item.expense_id) if item.expense_id else None
            bag_id = getattr(expense, "bag_id", None) if expense is not None else None
            if bag_id:
                bolsas.add(str(bag_id))
            else:
                sueltos += 1
    except Exception:
        bolsas, sueltos = set(), 1
    hoy = (batch.execution_date or today_local()).strftime("%d-%m-%Y")
    if len(bolsas) != 1 or sueltos:
        return "Remesa_Varios_%s" % hoy
    bag = session_db.get(WorkflowBag, to_uuid(next(iter(bolsas))))
    if bag is None:
        return "Remesa_Varios_%s" % hoy
    artista = _payment_file_part(getattr(getattr(bag, "artist", None), "name", "") or "")
    concert = None
    if (bag.linked_type or "").upper() == "CONCERT" and bag.linked_id:
        concert = session_db.get(Concert, bag.linked_id)
    festival = _payment_file_part(getattr(concert, "festival_name", None) or "")
    municipio = _payment_file_part(
        (getattr(getattr(concert, "venue", None), "municipality", None) or "")
        or (getattr(concert, "manual_municipality", None) or ""))
    fecha = (getattr(concert, "date", None) or bag.start_date or batch.execution_date or today_local())
    trozos = ["Remesa"]
    if artista:
        trozos.append(artista)
    trozos.append(festival or municipio or _payment_file_part(bag.title or "") or "Bolsa")
    trozos.append(fecha.strftime("%d-%m-%Y"))
    return "_".join(trozos)


def _payment_concept_for_expense(session_db, expense) -> str:
    """CONCEPTO del pago: se intenta que sea el de la FACTURA que se va a pagar.

    Es lo que ve el proveedor en su extracto, así que cuanto más se parezca a su factura, mejor lo
    reconoce. Orden: el concepto de la factura subida → el nº de factura → el concepto del gasto."""
    partes = []
    try:
        filas = (session_db.query(BagExpenseInvoice)
                 .filter(BagExpenseInvoice.bag_expense_id == expense.id)
                 .order_by(BagExpenseInvoice.created_at.desc()).all())
    except Exception:
        filas = []
    numero = ""
    for fila in filas:
        numero = numero or (fila.invoice_number or "").strip()
        inv = (session_db.get(SupplierInvoice, fila.supplier_invoice_id)
               if getattr(fila, "supplier_invoice_id", None) else None)
        if inv is not None:
            numero = numero or (inv.invoice_number or "").strip()
            texto = (inv.concept_text or "").strip()
            if texto:
                partes.append(texto)
                break
    numero = numero or (getattr(expense, "invoice_number", None) or "").strip()
    if not partes:
        # Sin factura con concepto, el del propio gasto (es lo que se le pidió facturar).
        propio = (getattr(expense, "concept", None) or "").strip()
        if propio:
            partes.append(propio)
    if numero:
        partes.append("Fra. " + numero)
    return " · ".join([x for x in partes if x])[:140] or "Pago"


def _payment_batch_add_royalties(session_db, batch, liquidation_ids) -> int:
    """Mete LIQUIDACIONES DE ROYALTIES validadas en la remesa. El beneficiario es quien facturó (de
    ahí salen el IBAN y el BIC) y se congela en el item, como el resto de los pagos."""
    añadidos = 0
    ya = {str(i.royalty_liquidation_id) for i in session_db.query(PaymentBatchItem)
          .filter(PaymentBatchItem.batch_id == batch.id).all() if getattr(i, "royalty_liquidation_id", None)}
    for raw in liquidation_ids or []:
        try:
            rid = to_uuid(str(raw).strip())
        except Exception:
            continue
        if not rid or str(rid) in ya:
            continue
        rec = session_db.get(RoyaltyLiquidation, rid)
        if rec is None or (rec.status or "").upper() != "INVOICED" or rec.paid_at is not None:
            continue
        congelada = _royalty_frozen_beneficiary(rec) or {}
        inv = session_db.get(SupplierInvoice, rec.invoice_id) if getattr(rec, "invoice_id", None) else None
        promoter = session_db.get(Promoter, inv.promoter_id) if (inv is not None and inv.promoter_id) else None
        # ⚠️ LO QUE VA AL BANCO es el TOTAL DE LA FACTURA (que ya lleva descontada la retención, si la
        # hay): es lo que va a recibir el beneficiario. Si la factura no trae importe, lo que se le
        # pidió facturar MENOS la retención. Antes se mandaba base + IVA y con retención se pagaba
        # de más. Es el mismo número que enseña «pendiente de pago».
        ret_inv = (_money_or_zero(getattr(inv, "retention_amount", None))
                   or _money_or_zero(congelada.get("retention_amount")))
        fac_inv = _money_or_zero(getattr(inv, "amount_gross", None)) if inv is not None else Decimal("0")
        importe = fac_inv if fac_inv > 0 else (_royalty_invoice_totals(congelada)["gross"] - ret_inv)
        if importe < 0:
            importe = Decimal("0")
        session_db.add(PaymentBatchItem(
            batch_id=batch.id,
            royalty_liquidation_id=rec.id,
            provider_id=(promoter.id if promoter is not None else None),
            beneficiary_name=(_promoter_display_name(promoter) or (congelada.get("name") or "") or None),
            beneficiary_iban=(sepa_normalize_iban(getattr(promoter, "bank_account", None) or "") or None),
            beneficiary_bic=((getattr(promoter, "bank_bic", None) or "").strip() or None),
            concept=("Royalties " + _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end))[:140],
            amount=importe,
            payment_date=(batch.execution_date or today_local()),
        ))
        rec.payment_batch_id = batch.id
        rec.updated_at = _now_madrid()
        ya.add(str(rec.id))
        añadidos += 1
    session_db.flush()
    _payment_batch_refresh_total(session_db, batch)
    return añadidos


def _payment_batch_expense_ids_from_form(session_db, form) -> list:
    """Ids de gasto que llegan del formulario: sueltos y/o todos los de las bolsas marcadas."""
    ids = [x for x in (form.getlist("expense_ids") or []) if (x or "").strip()]
    for bag_id in (form.getlist("bag_ids") or []):
        if not (bag_id or "").strip():
            continue
        try:
            bid = to_uuid(bag_id.strip())
        except Exception:
            continue
        for expense in _payment_pending_expenses(session_db):
            if str(getattr(expense, "bag_id", "")) == str(bid):
                ids.append(str(expense.id))
    # Sin duplicados y conservando el orden en que se eligieron.
    vistos, salida = set(), []
    for x in ids:
        if x in vistos:
            continue
        vistos.add(x)
        salida.append(x)
    return salida


def _bag_close_if_fully_paid(session_db, bag) -> bool:
    """Cuando en una bolsa ya no queda nada por pagar, se cierra y se archiva: a partir de ahí es
    cosa de contabilidad. Devuelve True si la ha archivado."""
    if bag is None:
        return False
    if _bag_has_pending_payments(session_db, bag):
        return False
    bag.liquidation_status = "CERRADA"
    bag.liquidation_paid_at = _now_madrid()
    bag.status = "ARCHIVADA"
    bag.is_archived = True
    bag.archived_at = _now_madrid()
    bag.updated_at = _now_madrid()
    _notify_resolve(session_db, "BAG", bag.id)
    # A partir de aquí es cosa de CONTABILIDAD: se avisa a quien lleva esa empresa del grupo (y si
    # nadie la lleva, a todo el departamento, para que no se quede sin contabilizar).
    try:
        _notify_users(session_db, _accounting_company_user_ids(session_db, getattr(bag, "company_id", None)),
                      "CONTABILIDAD", "Bolsa lista para contabilizar",
                      (getattr(bag, "title", None) or "Bolsa").strip(),
                      url=url_for("contabilidad_view", tab="pendiente", subtab="bolsas"),
                      ref_type="BAG_ACCOUNTING", ref_id=str(bag.id))
    except Exception:
        app.logger.exception("[contabilidad] no se pudo avisar de la bolsa lista para contabilizar")
    return True


