@app.post("/autorizacion-menores/validar/<token>/buscar", endpoint="public_minor_auth_check")
def public_minor_auth_check(token):
    """Busca una autorización por el DNI del menor, por el token del QR o por cualquier dato."""
    session_db = db()
    try:
        config = (session_db.query(MinorAuthConfig)
                  .filter(MinorAuthConfig.validate_token == (token or "").strip()).first())
        if config is None:
            return jsonify({"ok": False, "error": "Enlace no válido."}), 404
        payload = request.get_json(silent=True) or {}
        texto = (payload.get("q") or request.form.get("q") or "").strip()
        qr = (payload.get("qr") or request.form.get("qr") or "").strip()
        # Del QR puede llegar la URL entera: se queda con el último tramo, que es el token.
        if qr:
            qr = qr.rstrip("/").rsplit("/", 1)[-1]
        if not texto and not qr:
            return jsonify({"ok": False, "error": "Escanea el DNI o escribe un dato."}), 400

        auths = (session_db.query(MinorAuthorization)
                 .options(selectinload(MinorAuthorization.minors),
                          joinedload(MinorAuthorization.concert).joinedload(Concert.artist))
                 .filter(MinorAuthorization.config_id == config.id)
                 .filter(MinorAuthorization.status == "VALID").all())
        cabecera = _minor_concert_header(session_db, config.concert)
        buscado = mrz_normalize_doc_number(texto)
        clave = _norm_text_key(texto)
        salida = []
        for a in auths:
            if qr and (a.qr_token or "").strip() == qr:
                salida.append(_minor_auth_row(session_db, a, header=cabecera))
                continue
            if not texto:
                continue
            campos = [mrz_normalize_doc_number(a.guardian_doc_number),
                      mrz_normalize_doc_number(a.escort_doc_number)]
            nombres = [_norm_text_key(" ".join(filter(None, [a.guardian_first_name, a.guardian_last_name]))),
                       _norm_text_key(" ".join(filter(None, [a.escort_first_name, a.escort_last_name])))]
            for m in (a.minors or []):
                campos.append(mrz_normalize_doc_number(m.doc_number))
                nombres.append(_norm_text_key(" ".join(filter(None, [m.first_name, m.last_name]))))
            if (buscado and any(buscado == c for c in campos if c)) or \
               (clave and any(clave in n for n in nombres if n)):
                salida.append(_minor_auth_row(session_db, a, header=cabecera))
        return jsonify({"ok": True, "found": bool(salida), "count": len(salida), "matches": salida[:8]})
    finally:
        session_db.close()


def _production_type_label(value: str | None) -> str:
    key = (value or "GENERAL").strip().upper() or "GENERAL"
    return dict(PRODUCTION_ACTIVITY_TYPES).get(key) or dict(BAG_TYPES).get(key) or key.title()


def _production_artist_ids_from_any(raw) -> list[str]:
    out = []
    seen = set()
    if raw is None:
        raw_values = []
    elif isinstance(raw, str):
        raw_values = [raw]
    else:
        try:
            raw_values = list(raw)
        except Exception:
            raw_values = []
    for value in raw_values:
        try:
            uid = to_uuid(value)
        except Exception:
            uid = None
        if not uid:
            continue
        sid = str(uid)
        if sid in seen:
            continue
        seen.add(sid)
        out.append(sid)
    return out


def _production_artists_by_ids(session_db, ids: list[str]) -> list[Artist]:
    uuid_ids = []
    for value in ids or []:
        try:
            uuid_ids.append(to_uuid(value))
        except Exception:
            pass
    if not uuid_ids:
        return []
    rows = session_db.query(Artist).filter(Artist.id.in_(uuid_ids)).all()
    by_id = {str(row.id): row for row in rows}
    return [by_id[str(uid)] for uid in uuid_ids if str(uid) in by_id]


def _production_snapshot_value(snapshot, *keys) -> str:
    data = snapshot if isinstance(snapshot, dict) else {}
    for key in keys:
        val = data.get(key)
        if val:
            return str(val).strip()
    return ""


def _production_bag_row(session_db, bag: WorkflowBag, *, row_kind: str = "activity") -> dict:
    artists = _bag_artist_rows(session_db, bag) if "_bag_artist_rows" in globals() else []
    snapshot = getattr(bag, "linked_snapshot", None) or {}
    city = _production_snapshot_value(snapshot, "city", "municipality", "localidad")
    province = _production_snapshot_value(snapshot, "province", "provincia")
    activity_type = (getattr(bag, "bag_type", None) or getattr(bag, "linked_type", None) or "GENERAL").strip().upper()

    # Si la bolsa está vinculada a un concierto, enriquecemos ciudad/provincia y nombre.
    linked_type = (getattr(bag, "linked_type", None) or "").strip().upper()
    linked_id = getattr(bag, "linked_id", None)
    linked_concert = None
    if linked_type in {"CONCIERTO", "CONCERT"} and linked_id:
        try:
            linked_concert = session_db.get(Concert, linked_id)
        except Exception:
            linked_concert = None
    if linked_concert:
        city = city or _concert_city(linked_concert)
        province = province or _concert_province_value(linked_concert)
        linked_title = getattr(bag, "linked_title", None) or getattr(linked_concert, "festival_name", None) or _concert_venue_name(linked_concert)
        activity_date = getattr(linked_concert, "date", None) or getattr(bag, "start_date", None)
        detail_url = url_for("concert_detail_view", cid=linked_concert.id)
    else:
        linked_title = getattr(bag, "linked_title", None) or getattr(bag, "title", None) or "Actividad"
        activity_date = getattr(bag, "start_date", None) or getattr(bag, "end_date", None)
        detail_url = url_for("bag_detail_view", bag_id=bag.id)

    title = getattr(bag, "title", None) or linked_title or "Actividad"
    search_blob = " ".join([
        title or "",
        linked_title or "",
        _production_type_label(activity_type),
        city or "",
        province or "",
        " ".join([a.name for a in artists if getattr(a, "name", None)]),
        getattr(bag, "status", None) or "",
    ])
    return {
        "kind": row_kind,
        "id": str(bag.id),
        "title": title,
        "subtitle": linked_title if linked_title != title else (getattr(bag, "description", None) or ""),
        "activity_type": activity_type,
        "activity_label": _production_type_label(activity_type),
        "date": activity_date,
        "date_sort": activity_date or date.max,
        "artists": artists,
        "artist_ids": [str(a.id) for a in artists if getattr(a, "id", None)],
        "city": city,
        "province": province,
        "status": getattr(bag, "status", None) or "ACTIVA",
        "status_label": getattr(bag, "status", None) or "ACTIVA",
        "badge_class": "text-bg-secondary" if (getattr(bag, "status", "") or "").upper() in {"CERRADA", "LIQUIDADA", "ARCHIVADA"} else "text-bg-success",
        "detail_url": detail_url,
        "search_blob": search_blob,
        "is_bag": True,
        "bag": bag,
    }


def _production_request_row(session_db, req: ProductionRequest) -> dict:
    artist_ids = _production_artist_ids_from_any(getattr(req, "artist_ids", None) or [])
    artists = _production_artists_by_ids(session_db, artist_ids)
    activity_type = (getattr(req, "activity_type", None) or "GENERAL").strip().upper()
    title = (getattr(req, "activity_title", None) or "Solicitud de producción").strip()
    detail_url = url_for("bag_detail_view", bag_id=req.bag_id) if getattr(req, "bag_id", None) else "#productionRequestModal-" + str(req.id)
    search_blob = " ".join([
        title,
        _production_type_label(activity_type),
        getattr(req, "city", None) or "",
        getattr(req, "province", None) or "",
        " ".join([a.name for a in artists if getattr(a, "name", None)]),
        getattr(req, "notes", None) or "",
        getattr(req, "status", None) or "REQUESTED",
    ])
    return {
        "kind": "request",
        "id": str(req.id),
        "title": title,
        "subtitle": getattr(req, "notes", None) or "Solicitud pendiente de convertir en actividad / bolsa.",
        "activity_type": activity_type,
        "activity_label": _production_type_label(activity_type),
        "date": getattr(req, "activity_date", None),
        "date_sort": getattr(req, "activity_date", None) or date.max,
        "artists": artists,
        "artist_ids": [str(a.id) for a in artists if getattr(a, "id", None)],
        "city": getattr(req, "city", None) or "",
        "province": getattr(req, "province", None) or "",
        "status": getattr(req, "status", None) or "REQUESTED",
        "status_label": PRODUCTION_REQUEST_STATUS_LABELS.get((getattr(req, "status", None) or "REQUESTED").upper(), getattr(req, "status", None) or "REQUESTED"),
        "badge_class": "text-bg-warning text-dark",
        "detail_url": detail_url,
        "search_blob": search_blob,
        "is_request": True,
        "request": req,
    }


def _search_normalize(value: str | None) -> str:
    """Normaliza texto para búsquedas: sin acentos, alfanumérico y en minúsculas."""
    raw = unicodedata.normalize("NFD", str(value or ""))
    raw = "".join(ch for ch in raw if unicodedata.category(ch) != "Mn")
    raw = re.sub(r"[^a-zA-Z0-9]+", " ", raw)
    return raw.casefold().strip()


def _production_passes_filters(row: dict, *, q: str = "", artist_id: str = "", activity_type: str = "") -> bool:
    if activity_type and (row.get("activity_type") or "").upper() != activity_type.upper():
        return False
    if artist_id and artist_id not in set(row.get("artist_ids") or []):
        return False
    if q:
        haystack = _search_normalize(row.get("search_blob") or "")
        if _search_normalize(q) not in haystack:
            return False
    return True


def _production_group_archived(rows: list[dict]) -> list[dict]:
    grouped: dict[str, dict] = {}
    for row in rows:
        artists = row.get("artists") or []
        if artists:
            artist_items = artists
        else:
            artist_items = [SimpleNamespace(id="sin-artista", name="Sin artista", photo_url="")]
        for artist in artist_items:
            aid = str(getattr(artist, "id", "sin-artista") or "sin-artista")
            block = grouped.setdefault(aid, {"artist": artist, "types": {}})
            tkey = row.get("activity_type") or "GENERAL"
            tblock = block["types"].setdefault(tkey, {"label": row.get("activity_label") or _production_type_label(tkey), "rows": []})
            tblock["rows"].append(row)
    result = []
    for block in grouped.values():
        type_blocks = []
        for type_block in block["types"].values():
            type_block["rows"].sort(key=lambda item: item.get("date") or date.min, reverse=True)
            type_blocks.append(type_block)
        type_blocks.sort(key=lambda item: item["label"].casefold())
        result.append({"artist": block["artist"], "types": type_blocks})
    result.sort(key=lambda item: (getattr(item["artist"], "name", "") or "").casefold())
    return result


@app.route("/produccion", methods=["GET", "POST"], endpoint="produccion_view")
@admin_required
def produccion_view():
    session_db = db()
    try:
        if request.method == "POST":
            mode = (request.form.get("mode") or "create_request").strip().lower()
            if mode == "create_request":
                artist_ids = _production_artist_ids_from_any(request.form.getlist("artist_ids"))
                title = (request.form.get("activity_title") or "").strip()
                activity_type = (request.form.get("activity_type") or "GENERAL").strip().upper() or "GENERAL"
                if not title:
                    flash("El nombre de la actividad es obligatorio.", "warning")
                    return redirect(url_for("produccion_view", tab="solicitudes"))
                audit = _bag_current_user_audit() if "_bag_current_user_audit" in globals() else {"user_id": None, "nick": "Usuario"}
                req = ProductionRequest(
                    activity_type=activity_type,
                    activity_title=title,
                    artist_ids=artist_ids,
                    activity_date=parse_optional_date(request.form.get("activity_date")),
                    city=(request.form.get("city") or "").strip() or None,
                    province=(request.form.get("province") or "").strip() or None,
                    notes=(request.form.get("notes") or "").strip() or None,
                    status="REQUESTED",
                    requested_by_user_id=audit.get("user_id"),
                    requested_by_email=_current_user_email() or None,
                    requested_by_nick=audit.get("nick"),
                )
                session_db.add(req)
                session_db.commit()
                flash("Solicitud de producción creada.", "success")
                return redirect(url_for("produccion_view", tab="solicitudes"))

        tab = (request.args.get("tab") or "solicitudes").strip().lower()
        if tab not in {"solicitudes", "activas", "archivadas"}:
            tab = "solicitudes"
        f_q = (request.args.get("q") or "").strip()
        f_artist = (request.args.get("artist") or "").strip()
        f_type = (request.args.get("activity_type") or "").strip().upper()

        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
        artist_filter_ids = {str(a.id) for a in artists}
        if f_artist not in artist_filter_ids:
            f_artist = ""
        valid_types = {key for key, _label in PRODUCTION_ACTIVITY_TYPES}
        if f_type not in valid_types:
            f_type = ""

        request_rows_db = (
            session_db.query(ProductionRequest)
            .filter(ProductionRequest.status.in_(["REQUESTED", "APPROVED"]))
            .order_by(ProductionRequest.activity_date.asc().nullslast(), ProductionRequest.created_at.desc())
            .all()
        )
        # Las solicitudes de actividades del HISTÓRICO (antes del corte) no se procesan: se quedan
        # fuera del listado de Producción, que es lo que hay por hacer.
        request_rows = [_production_request_row(session_db, req) for req in request_rows_db
                        if not _is_legacy_activity_date(req.activity_date)]

        active_bags_db = (
            session_db.query(WorkflowBag)
            .options(joinedload(WorkflowBag.artist), joinedload(WorkflowBag.company))
            .filter(WorkflowBag.is_archived == False)  # noqa: E712
            .filter(~WorkflowBag.status.in_(["CERRADA", "LIQUIDADA", "ARCHIVADA"]))
            .order_by(WorkflowBag.start_date.asc().nullslast(), WorkflowBag.created_at.desc())
            .all()
        )
        active_rows = [_production_bag_row(session_db, bag, row_kind="activity") for bag in active_bags_db]

        production_concerts_db = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(Concert.status.in_(["RESERVADO", "CONFIRMADO"]))
            .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
            .limit(250)
            .all()
        )
        # Las fechas de una gira comprada que promueve un tercero (no una empresa del grupo) no las
        # producimos nosotros: fuera del listado de Producción.
        # ⚠️ Salvo que YA se esté trabajando en ellas (tienen bolsa): esconder trabajo empezado sería
        # peor que enseñar una fecha de más. La regla vale para lo nuevo, no para borrar lo que hay.
        _ids = [c.id for c in production_concerts_db]
        _con_bolsa = set()
        if _ids:
            try:
                _con_bolsa = {r[0] for r in session_db.query(WorkflowBag.linked_id).filter(
                    WorkflowBag.linked_type.in_(("CONCERT", "concert")),
                    WorkflowBag.linked_id.in_(_ids)).all()}
            except Exception:
                _con_bolsa = set()
        production_concerts_db = [c for c in production_concerts_db
                                  if _concert_needs_production(c, session_db) or c.id in _con_bolsa]
        active_rows.extend([_production_concert_row(session_db, concert) for concert in production_concerts_db])
        production_actions_db = []
        try:
            production_actions_db = (
                session_db.query(CompanyAction)
                .options(joinedload(CompanyAction.venue))
                .filter(CompanyAction.status.in_(["RESERVA", "CONFIRMADO"]))
                .order_by(CompanyAction.start_date.asc().nullslast(), CompanyAction.created_at.desc())
                .limit(250)
                .all()
            )
        except Exception:
            production_actions_db = []
        active_rows.extend([_production_action_row(session_db, action) for action in production_actions_db])

        archived_bags_db = (
            session_db.query(WorkflowBag)
            .options(joinedload(WorkflowBag.artist), joinedload(WorkflowBag.company))
            .filter(or_(WorkflowBag.is_archived == True, WorkflowBag.status.in_(["CERRADA", "LIQUIDADA", "ARCHIVADA"])))  # noqa: E712
            .order_by(WorkflowBag.start_date.desc().nullslast(), WorkflowBag.created_at.desc())
            .all()
        )
        archived_rows = [_production_bag_row(session_db, bag, row_kind="archived") for bag in archived_bags_db]

        request_rows = [row for row in request_rows if _production_passes_filters(row, q=f_q, artist_id=f_artist, activity_type=f_type)]
        active_rows = [row for row in active_rows if _production_passes_filters(row, q=f_q, artist_id=f_artist, activity_type=f_type)]
        archived_rows = [row for row in archived_rows if _production_passes_filters(row, q=f_q, artist_id=f_artist, activity_type=f_type)]

        request_rows.sort(key=lambda row: (row.get("date") or date.max, row.get("title") or ""))
        active_rows.sort(key=lambda row: (row.get("date") or date.max, row.get("title") or ""))
        archived_rows.sort(key=lambda row: (row.get("date") or date.min, row.get("title") or ""), reverse=True)
        archived_groups = _production_group_archived(archived_rows)

        counts = {
            "solicitudes": len(request_rows),
            "activas": len(active_rows),
            "archivadas": len(archived_rows),
        }
        # ACTIVAS: por SUJETO (artista o evento) y, al entrar, sus actividades con la estética de la
        # sección Actividades. Cada persona de producción ve solo lo suyo.
        activas = _production_active_context(session_db) if tab == "activas" else None
        if activas is not None:
            counts["activas"] = activas["total"]
        return render_template(
            "produccion.html",
            tab=tab,
            counts=counts,
            # Para el listado de «pendientes de asignar»: lo único que se hace desde ahí es elegir a la
            # persona de producción que se encarga.
            # ⚠️ SIEMPRE: el selector de «¿quién lleva la producción?» se abre también para cambiar
            # el responsable de una que ya lo tiene, y sin la lista salía vacío.
            production_people=_production_people(session_db),
            requests=request_rows,
            active_rows=active_rows,
            activas=activas,
            archived_rows=archived_rows,
            archived_groups=archived_groups,
            artists=artists,
            activity_types=PRODUCTION_ACTIVITY_TYPES,
            request_status_labels=PRODUCTION_REQUEST_STATUS_LABELS,
            filter_q=f_q,
            filter_artist=f_artist,
            filter_activity_type=f_type,
        )
    finally:
        # ⚠️ Se marca DESPUÉS de renderizar: si se hiciera antes, el destacado «Nueva actividad»
        # nunca se vería (la propia visita lo borraría).
        # Se marca «visto» solo en la REJILLA (sin artista concreto): así, al entrar en un artista, el
        # destacado de lo nuevo sigue estando donde hace falta verlo.
        if ((request.args.get("tab") or "").strip().lower() == "activas"
                and not (request.args.get("artist") or request.args.get("event"))):
            try:
                _production_mark_seen(session_db)
            except Exception:
                pass
        session_db.close()


@app.post("/produccion/solicitudes/<request_id>/convertir-bolsa", endpoint="production_request_convert_to_bag")
@admin_required
def production_request_convert_to_bag(request_id):
    session_db = db()
    try:
        req = session_db.get(ProductionRequest, to_uuid(request_id))
        if not req:
            flash("Solicitud de producción no encontrada.", "warning")
            return redirect(url_for("produccion_view", tab="solicitudes"))
        if getattr(req, "bag_id", None):
            flash("Esta solicitud ya está vinculada a una bolsa.", "info")
            return redirect(safe_next_or(url_for("bag_detail_view", bag_id=req.bag_id)))
        artist_ids = _production_artist_ids_from_any(getattr(req, "artist_ids", None) or [])
        primary_artist_id = to_uuid(artist_ids[0]) if artist_ids else None
        snapshot = {
            "source": "production_request",
            "request_id": str(req.id),
            "activity_type": req.activity_type,
            "activity_title": req.activity_title,
            "city": req.city,
            "province": req.province,
        }
        bag = WorkflowBag(
            title=(getattr(req, "activity_title", None) or "Actividad de producción").strip(),
            artist_id=primary_artist_id,
            artist_ids=artist_ids,
            bag_type=(getattr(req, "activity_type", None) or "GENERAL").strip().upper() or "GENERAL",
            linked_type="PRODUCTION_REQUEST",
            linked_id=req.id,
            linked_title=(getattr(req, "activity_title", None) or "Solicitud de producción").strip(),
            linked_snapshot=snapshot,
            start_date=getattr(req, "activity_date", None),
            description=getattr(req, "notes", None),
            status="ACTIVA",
            liquidation_status="NO_INICIADA",
            is_archived=False,
        )
        session_db.add(bag)
        session_db.flush()
        req.status = "CONVERTED"
        req.bag_id = bag.id
        req.updated_at = _now_madrid()
        session_db.commit()
        flash("Solicitud convertida en bolsa activa de producción.", "success")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo convertir la solicitud: {exc}", "danger")
        return redirect(url_for("produccion_view", tab="solicitudes"))
    finally:
        session_db.close()


@app.post("/produccion/solicitudes/<request_id>/rechazar", endpoint="production_request_reject")
@admin_required
def production_request_reject(request_id):
    session_db = db()
    try:
        req = session_db.get(ProductionRequest, to_uuid(request_id))
        if req:
            req.status = "REJECTED"
            req.updated_at = _now_madrid()
            session_db.commit()
            flash("Solicitud de producción rechazada.", "success")
    finally:
        session_db.close()
    return redirect(url_for("produccion_view", tab="solicitudes"))




def _pdf_text_from_filestorage(file_storage) -> str:
    """Extrae texto seleccionable de un PDF sin usar OCR externo."""
    if not file_storage or not getattr(file_storage, "filename", ""):
        return ""
    try:
        raw = file_storage.read()
        try:
            file_storage.stream.seek(0)
        except Exception:
            pass
        if not raw or not PYPDF_AVAILABLE or PdfReader is None:
            return ""
        reader = PdfReader(BytesIO(raw))
        chunks = []
        for page in getattr(reader, "pages", []) or []:
            try:
                chunks.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(chunks).strip()
    except Exception:
        try:
            file_storage.stream.seek(0)
        except Exception:
            pass
        return ""


def _embargo_norm_tax_id(value: str | None) -> str:
    return re.sub(r"[^A-Z0-9]", "", (value or "").upper())


def _embargo_tax_id_candidates(text_value: str | None) -> list[str]:
    raw = (text_value or "").upper().replace("-", " ").replace(".", " ")
    patterns = [
        r"\b[ABCDEFGHJKLMNPQRSUVW]\s?\d{7}\s?[0-9A-J]\b",  # CIF/NIF jurídico
        r"\b\d{8}\s?[A-Z]\b",                              # DNI
        r"\b[XYZ]\s?\d{7}\s?[A-Z]\b",                      # NIE
    ]
    out: list[str] = []
    seen: set[str] = set()
    for pattern in patterns:
        for m in re.finditer(pattern, raw):
            val = _embargo_norm_tax_id(m.group(0))
            if val and val not in seen:
                seen.add(val)
                out.append(val)
    return out


def _detect_embargo_order_type(text_value: str, filename: str | None = None) -> str:
    haystack = _norm_text_key(" ".join([text_value or "", filename or ""]))
    if any(word in haystack for word in [
        "levantamiento de embargo",
        "levantamiento embargo",
        "alzamiento de embargo",
        "alzamiento embargo",
        "cancelacion de embargo",
        "dejar sin efecto",
        "queda sin efecto la orden",
    ]):
        return "LEVANTAMIENTO"
    if "diligencia de embargo" in haystack or "orden de embargo" in haystack or "embargo" in haystack:
        return "EMBARGO"
    return "DESCONOCIDO"


def _embargo_parse_es_decimal(value: str | None) -> Decimal | None:
    value = (value or "").strip()
    if not value:
        return None
    cleaned = re.sub(r"[^0-9,.-]", "", value)
    if not cleaned:
        return None
    # Formato español habitual: 1.234,56
    cleaned = cleaned.replace(".", "").replace(",", ".")
    try:
        return Decimal(cleaned)
    except Exception:
        return None


def _embargo_parse_es_date(value: str | None):
    value = (value or "").strip()
    if not value:
        return None
    for fmt in ("%d-%m-%Y", "%d/%m/%Y", "%d-%m-%y", "%d/%m/%y", "%Y-%m-%d"):
        try:
            return datetime.strptime(value, fmt).date()
        except Exception:
            continue
    return None


def _embargo_first_match(pattern: str, text_value: str | None, flags: int = re.IGNORECASE | re.MULTILINE | re.DOTALL) -> str:
    m = re.search(pattern, text_value or "", flags)
    if not m:
        return ""
    return (m.group(1) if m.groups() else m.group(0)).strip()


def _embargo_target_section(text_value: str | None) -> str:
    text_value = text_value or ""
    m = re.search(
        r"IDENTIFICACI[ÓO]N\s+DEL\s+OBLIGADO\s+AL\s+PAGO(?P<section>.*?)(?:\n\s*ACUERDO\b|\n\s*BIENES\b|\n\s*INFORMACI[ÓO]N\b|$)",
        text_value,
        re.IGNORECASE | re.DOTALL,
    )
    if m:
        return m.group("section")
    return text_value[:4000]


def _extract_possible_tax_id(text_value: str) -> str:
    """Devuelve prioritariamente el NIF/CIF del embargado, no el del pagador."""
    section = _embargo_target_section(text_value)
    target_candidates = _embargo_tax_id_candidates(section)
    if target_candidates:
        return target_candidates[0]
    candidates = _embargo_tax_id_candidates(text_value)
    return candidates[0] if candidates else ""


def _extract_embargo_order_data(text_value: str, filename: str | None = None) -> dict:
    section = _embargo_target_section(text_value)
    detected_tax_id = _extract_possible_tax_id(text_value)
    detected_name = _embargo_first_match(r"NOMBRE\s+O\s+RAZ[ÓO]N\s+SOCIAL\s*:\s*([^\n]+)", section)
    if not detected_name:
        detected_name = _embargo_first_match(r"Apellidos\s+y\s+Nombre\s+o\s+Raz[óo]n\s+Social\s*\n\s*([^\n]+)", text_value)
    detected_address = _embargo_first_match(r"DOMICILIO\s*:\s*([^\n]+(?:\n\s*\d{5}\s+[^\n]+)?)", section)
    reference = _embargo_first_match(r"Referencia\s*:\s*([^\n]+)", text_value)
    diligence = _embargo_first_match(r"N[ºo]\s+de\s+la\s+diligencia\s*:\s*([^\n]+)", text_value)
    order_date_raw = _embargo_first_match(r"Fecha\s+de\s+la\s+diligencia\s*:\s*(\d{1,2}[-/]\d{1,2}[-/]\d{2,4})", text_value)
    amount_raw = _embargo_first_match(r"importe\s+total\s+(?:indicado\s+en\s+el\s+apartado\s+anterior\s+)?(?:de\s+)?([0-9\.]+,[0-9]{2})\s*euros", text_value)
    if not amount_raw:
        amount_raw = _embargo_first_match(r"Importe\s+total\s*:\s*([0-9\.]+,[0-9]{2})", text_value)
    return {
        "order_type": _detect_embargo_order_type(text_value, filename),
        "detected_tax_id": detected_tax_id,
        "detected_name": detected_name,
        "detected_address": " ".join((detected_address or "").split()),
        "reference": reference,
        "diligence_number": diligence,
        "order_date": _embargo_parse_es_date(order_date_raw),
        "amount_total": _embargo_parse_es_decimal(amount_raw),
    }


def _promoter_tax_ids(promoter: Promoter | None) -> list[str]:
    if not promoter:
        return []
    values = [getattr(promoter, "tax_id", None)]
    values.extend([getattr(c, "tax_id", None) for c in (getattr(promoter, "companies", None) or [])])
    out: list[str] = []
    seen: set[str] = set()
    for value in values:
        key = _embargo_norm_tax_id(value)
        if key and key not in seen:
            seen.add(key)
            out.append(key)
    return out


def _promoter_snapshot(promoter: Promoter | None) -> dict:
    if not promoter:
        return {}
    return {
        "id": str(promoter.id),
        "nick": (promoter.nick or "").strip(),
        "email": (promoter.contact_email or "").strip(),
        "phone": (promoter.contact_phone or "").strip(),
        "tax_id": (promoter.tax_id or "").strip(),
    }


def _embargo_promoter_index(session_db):
    """Terceros preparados para emparejar, UNA sola vez por petición.

    Antes se recargaba la tabla entera de terceros (hasta 5.000, con sus empresas) y se
    renormalizaban todas sus etiquetas **por cada PDF**. Subiendo una carpeta de órdenes eso
    multiplicaba el trabajo por el número de ficheros y dejaba el worker bloqueado; ahora la lista y
    sus claves se calculan una vez y se reutilizan para todos los PDF del mismo envío.
    """
    cache = getattr(g, "_embargo_promoter_index", None)
    if cache is not None:
        return cache
    filas = (session_db.query(Promoter).options(selectinload(Promoter.companies))
             .order_by(Promoter.nick.asc()).limit(5000).all())
    index = []
    for promoter in filas:
        etiquetas = [promoter.nick, promoter.first_name, promoter.last_name, promoter.contact_email]
        etiquetas.extend([getattr(c, "legal_name", None) for c in (promoter.companies or [])])
        normalizadas = []
        for etiqueta in etiquetas:
            clave = _norm_text_key(etiqueta or "")
            if clave and len(clave) >= 4:
                normalizadas.append((clave, etiqueta or ""))
        index.append((promoter, set(_promoter_tax_ids(promoter)), normalizadas))
    try:
        g._embargo_promoter_index = index
    except Exception:
        pass
    return index


def _match_embargo_promoter(session_db, text_value: str, tax_id: str | None = None, detected_name: str | None = None):
    """Busca tercero por DNI/CIF exacto y, si no existe, propone coincidencias de nombre."""
    tax_key = _embargo_norm_tax_id(tax_id)
    folded_text = _norm_text_key(text_value or "")
    detected_name_key = _norm_text_key(detected_name or "")
    index = _embargo_promoter_index(session_db)
    if tax_key:
        for promoter, tax_ids, _labels in index:
            if tax_key in tax_ids:
                return promoter, 1.0, tax_key, True

    best = (None, 0.0, "", False)
    for promoter, _tax_ids, labels in index:
        for label_norm, label in labels:
            score = 0.0
            if label_norm in folded_text:
                score = max(score, 0.86)
            if detected_name_key:
                score = max(score, SequenceMatcher(None, detected_name_key, label_norm).ratio())
            if score > best[1]:
                best = (promoter, score, label, False)
    return best


def _embargo_active_statuses() -> set[str]:
    return {"ACTIVA", "VINCULADA"}


def _embargo_visible_statuses() -> set[str]:
    return {"ACTIVA", "VINCULADA", "PENDIENTE", "REVISAR"}


def _active_embargo_orders_query(session_db):
    return session_db.query(EmbargoOrder).filter(
        EmbargoOrder.order_type == "EMBARGO",
        EmbargoOrder.status.in_(list(_embargo_visible_statuses())),
    )


def _active_embargo_orders_for_promoter(session_db, promoter: Promoter | None = None, promoter_id=None, tax_ids: list[str] | None = None) -> list[EmbargoOrder]:
    pid = getattr(promoter, "id", None) or promoter_id
    keys = set(tax_ids or [])
    if promoter is not None:
        keys.update(_promoter_tax_ids(promoter))
    keys = {_embargo_norm_tax_id(k) for k in keys if _embargo_norm_tax_id(k)}
    rows = _active_embargo_orders_query(session_db).order_by(EmbargoOrder.order_date.desc().nullslast(), EmbargoOrder.created_at.desc()).limit(500).all()
    out = []
    for row in rows:
        row_tax = _embargo_norm_tax_id(getattr(row, "detected_tax_id", None))
        if (pid and getattr(row, "promoter_id", None) and str(row.promoter_id) == str(pid)) or (row_tax and row_tax in keys):
            out.append(row)
    return out


def _embargo_order_summary(order: EmbargoOrder) -> dict:
    return {
        "id": str(order.id),
        "reference": order.reference or order.diligence_number or order.pdf_name or "Orden de embargo",
        "date": order.order_date.strftime("%d/%m/%Y") if order.order_date else (order.created_at.strftime("%d/%m/%Y") if order.created_at else ""),
        "amount": float(order.amount_total or 0) if getattr(order, "amount_total", None) is not None else None,
        "tax_id": order.detected_tax_id or "",
        "name": order.detected_name or "",
        "pdf_url": order.pdf_url or "",
    }


def _expense_active_embargo_alerts(session_db, expense: BagExpense) -> list[dict]:
    provider = getattr(expense, "provider", None)
    if not provider and getattr(expense, "provider_id", None):
        provider = session_db.query(Promoter).options(selectinload(Promoter.companies)).filter(Promoter.id == expense.provider_id).first()
    if not provider:
        return []
    bag = getattr(expense, "bag", None)
    if not bag and getattr(expense, "bag_id", None):
        bag = session_db.get(WorkflowBag, expense.bag_id)
    if bag:
        if (getattr(bag, "status", "") or "").upper() in {"CERRADA", "LIQUIDADA", "ARCHIVADA"}:
            return []
        if (getattr(bag, "liquidation_status", "") or "").upper() in {"CERRADA", "PAGADA", "ARCHIVADA"}:
            return []
    orders = _active_embargo_orders_for_promoter(session_db, provider)
    if not orders:
        return []
    # No se alerta sobre gastos ya pagados antes de la fecha de embargo.
    if (getattr(expense, "payment_status", "") or "").upper() == "PAGADO":
        paid_dates = []
        for ev in (getattr(expense, "payment_events", None) or []):
            if (getattr(ev, "kind", "") or "").upper() in {"PAGO_REGISTRADO", "PAGADO", "LIQUIDACION_PAGADA"} and getattr(ev, "created_at", None):
                paid_dates.append(ev.created_at.date())
        if not paid_dates and getattr(expense, "updated_at", None):
            paid_dates.append(expense.updated_at.date())
        paid_at = min(paid_dates) if paid_dates else None
        if paid_at:
            remaining = []
            for order in orders:
                order_dt = order.order_date or (order.created_at.date() if order.created_at else None)
                if not order_dt or paid_at >= order_dt:
                    remaining.append(order)
            orders = remaining
    return [_embargo_order_summary(order) for order in orders]


def _auto_link_embargo_orders_for_promoter(session_db, promoter: Promoter | None) -> int:
    """Vincula órdenes pendientes cuando se crea/actualiza un tercero con DNI/CIF coincidente."""
    if not promoter:
        return 0
    tax_ids = set(_promoter_tax_ids(promoter))
    if not tax_ids:
        return 0
    count = 0
    rows = session_db.query(EmbargoOrder).filter(
        EmbargoOrder.promoter_id.is_(None),
        EmbargoOrder.detected_tax_id.isnot(None),
        EmbargoOrder.status.in_(["PENDIENTE", "REVISAR", "ACTIVA", "VINCULADA"]),
    ).all()
    for row in rows:
        if _embargo_norm_tax_id(row.detected_tax_id) not in tax_ids:
            continue
        row.promoter_id = promoter.id
        row.provider_snapshot = _promoter_snapshot(promoter)
        row.match_score = Decimal("1.0")
        row.match_label = row.detected_tax_id
        if (row.order_type or "").upper() == "EMBARGO" and (row.status or "").upper() != "ARCHIVADA":
            row.status = "ACTIVA"
        elif (row.order_type or "").upper() == "LEVANTAMIENTO":
            row.status = "ARCHIVADA"
            row.archive_reason = row.archive_reason or "Levantamiento vinculado al crear/actualizar tercero."
            row.archived_at = row.archived_at or _now_madrid()
        row.updated_at = _now_madrid()
        count += 1
    return count


def _archive_matching_embargos_for_lift(session_db, lift_row: EmbargoOrder, audit: dict | None = None) -> int:
    audit = audit or {}
    filters = [EmbargoOrder.order_type == "EMBARGO", EmbargoOrder.status.in_(list(_embargo_visible_statuses()))]
    candidates = session_db.query(EmbargoOrder).filter(*filters).all()
    lift_tax = _embargo_norm_tax_id(getattr(lift_row, "detected_tax_id", None))
    lift_pid = getattr(lift_row, "promoter_id", None)
    lift_diligence = _norm_text_key(getattr(lift_row, "diligence_number", None) or "")
    lift_reference = _norm_text_key(getattr(lift_row, "reference", None) or "")
    changed = 0
    first_related = None
    for row in candidates:
        if str(row.id) == str(lift_row.id):
            continue
        same_promoter = bool(lift_pid and getattr(row, "promoter_id", None) and str(row.promoter_id) == str(lift_pid))
        same_tax = bool(lift_tax and _embargo_norm_tax_id(getattr(row, "detected_tax_id", None)) == lift_tax)
        row_diligence = _norm_text_key(getattr(row, "diligence_number", None) or "")
        row_reference = _norm_text_key(getattr(row, "reference", None) or "")
        same_diligence = bool(lift_diligence and row_diligence and (row_diligence == lift_diligence or lift_diligence in row_reference or row_diligence in lift_reference))
        if not (same_promoter or same_tax or same_diligence):
            continue
        row.status = "ARCHIVADA"
        row.archived_at = _now_madrid()
        row.archived_by_user_id = to_uuid(audit.get("user_id")) if audit.get("user_id") else None
        row.archived_by_nick = audit.get("nick") or "Administración"
        row.archive_reason = f"Levantamiento de embargo {lift_row.reference or lift_row.diligence_number or lift_row.pdf_name or ''}".strip()
        row.related_embargo_id = lift_row.id
        row.updated_at = _now_madrid()
        first_related = first_related or row.id
        changed += 1
    if first_related:
        lift_row.related_embargo_id = first_related
    return changed


def _embargo_order_email_suggestions(session_db, order: EmbargoOrder) -> list[dict]:
    out: list[dict] = []
    seen: set[str] = set()

    def add(label, email):
        email = (email or "").strip()
        if not email or not _looks_like_email_address(email):
            return
        key = email.lower()
        if key in seen:
            return
        seen.add(key)
        out.append({"label": label or email, "email": email})

    promoter = getattr(order, "promoter", None)
    if not promoter and getattr(order, "promoter_id", None):
        promoter = session_db.get(Promoter, order.promoter_id)
    if promoter:
        add(f"{promoter.nick} · principal", promoter.contact_email)
        for row in session_db.query(PromoterEmail).filter(PromoterEmail.promoter_id == promoter.id).order_by(PromoterEmail.concept.asc()).all():
            add(row.concept or "Email adicional", row.email)
        for contact in session_db.query(PromoterContact).filter(PromoterContact.promoter_id == promoter.id).order_by(PromoterContact.title.asc()).all():
            name = " ".join([x for x in [contact.first_name, contact.last_name] if x]).strip() or contact.title
            add(name, contact.email)
    return out


def _download_url_bytes(url: str | None, max_bytes: int = 12 * 1024 * 1024) -> bytes | None:
    url = (url or "").strip()
    if not url:
        return None
    try:
        req = Request(url, headers={"User-Agent": "App33/embargos"})
        with urlopen(req, timeout=20) as resp:
            data = resp.read(max_bytes + 1)
        if len(data) > max_bytes:
            return None
        return data
    except Exception:
        return None


def _embargo_share_email_body(order: EmbargoOrder) -> tuple[str, str, str]:
    subject = f"Orden de embargo recibida{(' - ' + order.detected_name) if order.detected_name else ''}"
    pdf_link = order.pdf_url or ""
    html_body = f"""
    <div style="font-family:Arial,sans-serif;color:#111;line-height:1.5;">
      <p>Le informamos que hemos recibido una orden de embargo a su nombre.</p>
      <p>Adjuntamos la orden en formato PDF para que pueda revisarla.</p>
      <table style="border-collapse:collapse;margin-top:12px;">
        <tr><td style="padding:4px 10px 4px 0;color:#666;">Nombre</td><td style="padding:4px 0;font-weight:600;">{html.escape(order.detected_name or 'No detectado')}</td></tr>
        <tr><td style="padding:4px 10px 4px 0;color:#666;">NIF/CIF</td><td style="padding:4px 0;">{html.escape(order.detected_tax_id or 'No detectado')}</td></tr>
        <tr><td style="padding:4px 10px 4px 0;color:#666;">Referencia</td><td style="padding:4px 0;">{html.escape(order.reference or order.diligence_number or 'Sin referencia')}</td></tr>
        <tr><td style="padding:4px 10px 4px 0;color:#666;">Fecha</td><td style="padding:4px 0;">{order.order_date.strftime('%d/%m/%Y') if order.order_date else ''}</td></tr>
      </table>
      {f'<p><a href="{html.escape(pdf_link)}" target="_blank" rel="noopener">Ver PDF</a></p>' if pdf_link else ''}
    </div>
    """
    text_body = "Le informamos que hemos recibido una orden de embargo a su nombre. Adjuntamos la orden en formato PDF para que pueda revisarla."
    return subject, html_body, text_body


@app.post("/administracion/embargos/upload", endpoint="administration_embargo_upload")
@admin_required
def administration_embargo_upload():
    session_db = db()
    try:
        # `files` es el campo que manda el modal con arrastre (archivos sueltos o carpetas enteras);
        # el resto se conservan por compatibilidad con formularios antiguos.
        wants_json = _is_xhr_request() or _wants_json_response()
        files = []
        for field in ("pdf", "order_pdf", "file", "pdfs", "orders", "files"):
            for candidate in request.files.getlist(field):
                if candidate and getattr(candidate, "filename", ""):
                    files.append(candidate)
        # dedupe Werkzeug objects while preserving order
        unique_files = []
        seen_ids = set()
        for file_obj in files:
            if id(file_obj) in seen_ids:
                continue
            seen_ids.add(id(file_obj))
            unique_files.append(file_obj)
        if not unique_files:
            if wants_json:
                return jsonify({"ok": False, "error": "No llegó ningún PDF."}), 400
            flash("Debes subir uno o varios PDF de órdenes de embargo o levantamiento.", "warning")
            return redirect(url_for("administracion_view", tab="embargos"))

        audit = _current_user_state()
        created_rows = []
        archived_count = 0
        errores = []
        for pdf in unique_files:
            # De una carpeta llega la RUTA completa («2026/enero/orden.pdf»): validar por el nombre.
            nombre = os.path.basename((pdf.filename or "").replace("\\", "/")) or "orden.pdf"
            if not nombre.lower().endswith(".pdf"):
                errores.append(f"{nombre}: la orden debe subirse en PDF.")
                if not wants_json:
                    flash(f"{nombre}: la orden debe subirse en PDF.", "warning")
                continue
            # Un PDF que falle no puede llevarse por delante a los demás de la misma carpeta.
            punto = session_db.begin_nested()
            try:
                extracted_text = _pdf_text_from_filestorage(pdf)
                data = _extract_embargo_order_data(extracted_text, nombre)
                promoter, score, label, exact_tax = _match_embargo_promoter(session_db, extracted_text, data.get("detected_tax_id"), data.get("detected_name"))
                linked_promoter = promoter if exact_tax else None
                suggested_promoter = promoter if (promoter and not exact_tax and score >= 0.78) else None
                order_type = data.get("order_type") or "DESCONOCIDO"
                if order_type == "EMBARGO":
                    status = "ACTIVA" if linked_promoter else ("REVISAR" if suggested_promoter else "PENDIENTE")
                elif order_type == "LEVANTAMIENTO":
                    status = "ARCHIVADA"
                else:
                    status = "REVISAR" if suggested_promoter else "PENDIENTE"
                try:
                    pdf.stream.seek(0)
                except Exception:
                    pass
                pdf_url = upload_pdf(pdf, "embargos")
                row = EmbargoOrder(
                    order_type=order_type,
                    status=status,
                    promoter_id=getattr(linked_promoter, "id", None),
                    provider_snapshot=_promoter_snapshot(linked_promoter),
                    detected_name=(data.get("detected_name") or label or "").strip() or None,
                    detected_tax_id=data.get("detected_tax_id") or None,
                    detected_address=data.get("detected_address") or None,
                    reference=data.get("reference") or None,
                    diligence_number=data.get("diligence_number") or None,
                    order_date=data.get("order_date"),
                    amount_total=data.get("amount_total"),
                    detected_text=(extracted_text or "")[:12000],
                    pdf_url=pdf_url,
                    pdf_name=nombre,
                    suggested_promoter_id=getattr(suggested_promoter, "id", None),
                    match_score=Decimal(str(round(float(score or 0), 4))) if score else None,
                    match_label=(label or "").strip() or None,
                    uploaded_by_user_id=to_uuid(audit.get("user_id")) if audit.get("user_id") else None,
                    uploaded_by_nick=audit.get("nick") or "Administración",
                    archived_at=_now_madrid() if status == "ARCHIVADA" else None,
                    archived_by_user_id=to_uuid(audit.get("user_id")) if status == "ARCHIVADA" and audit.get("user_id") else None,
                    archived_by_nick=(audit.get("nick") or "Administración") if status == "ARCHIVADA" else None,
                    archive_reason="Levantamiento de embargo subido." if order_type == "LEVANTAMIENTO" else None,
                )
                session_db.add(row)
                session_db.flush()
                archivados_aqui = 0
                if order_type == "LEVANTAMIENTO":
                    archivados_aqui = _archive_matching_embargos_for_lift(session_db, row, audit)
                punto.commit()
                # Se suma DESPUÉS de confirmar: si el savepoint se deshace, no se informa de
                # archivados que en realidad no llegaron a guardarse.
                archived_count += archivados_aqui
                created_rows.append(row)
            except Exception as exc_file:
                try:
                    punto.rollback()
                except Exception:
                    pass
                errores.append(f"{nombre}: {exc_file}")
                if not wants_json:
                    flash(f"{nombre}: no se pudo procesar ({exc_file}).", "warning")
        session_db.commit()
        pending_review = len([r for r in created_rows if (r.status or "").upper() in {"PENDIENTE", "REVISAR"}])

        if wants_json:
            return jsonify({
                "ok": True,
                "created": len(created_rows),
                "pending_review": pending_review,
                "archived": archived_count,
                "errores": errores,
            })

        if created_rows:
            flash(f"Se han procesado {len(created_rows)} PDF de embargo/levantamiento.", "success")
            if archived_count:
                flash(f"Se han archivado automáticamente {archived_count} embargo(s) activo(s) por levantamiento.", "success")
            if pending_review:
                flash(f"{pending_review} orden(es) quedan pendientes de revisar o vincular.", "warning")
        else:
            flash("No se procesó ningún PDF válido.", "warning")
    except Exception as exc:
        session_db.rollback()
        if _is_xhr_request():
            return jsonify({"ok": False, "error": str(exc)}), 500
        flash(f"No se pudo procesar la orden: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("administracion_view", tab="embargos", embargo_tab="activas"))


@app.post("/administracion/embargos/<order_id>/vincular", endpoint="administration_embargo_link")
@admin_required
def administration_embargo_link(order_id):
    session_db = db()
    try:
        row = session_db.get(EmbargoOrder, to_uuid(order_id))
        promoter_id = to_uuid((request.form.get("promoter_id") or "").strip() or None)
        promoter = session_db.get(Promoter, promoter_id) if promoter_id else None
        if not row or not promoter:
            flash("Selecciona una orden y un tercero válido.", "warning")
            return redirect(url_for("administracion_view", tab="embargos"))
        row.promoter_id = promoter.id
        row.provider_snapshot = _promoter_snapshot(promoter)
        row.suggested_promoter_id = None
        row.match_score = Decimal("1.0")
        row.match_label = row.detected_tax_id or promoter.tax_id or promoter.nick
        if (row.order_type or "").upper() == "EMBARGO":
            row.status = "ACTIVA"
            row.archived_at = None
            row.archive_reason = None
        elif (row.order_type or "").upper() == "LEVANTAMIENTO":
            row.status = "ARCHIVADA"
            row.archived_at = row.archived_at or _now_madrid()
            _archive_matching_embargos_for_lift(session_db, row, _current_user_state())
        else:
            row.status = "ACTIVA"
        row.updated_at = _now_madrid()
        session_db.commit()
        flash("Orden vinculada al tercero.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo vincular la orden: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("administracion_view", tab="embargos", embargo_tab="activas"))


