def _admin_altas_pending_count(session_db) -> int:
    """Empresas del grupo con el ITA caducado o sin subir. Se calcula con los documentos, sin
    resolver nombres de trabajadores uno a uno (eso es `_prl_admin_altas_context`, que es caro y
    solo hace falta cuando se abre la pestaña)."""
    try:
        empresas = [str(x[0]) for x in session_db.query(GroupCompany.id).all()]
        if not empresas:
            return 0
        hoy = date.today()
        # ⚠️ MISMA regla que la pestaña (`_prl_admin_altas_context`): manda el ITA **más reciente**
        # de cada empresa, no «cualquiera que esté en vigor». Si no, el número dice 0 con empresas
        # pintadas en rojo (p. ej. al subir por error uno viejo, que pasa a ser el actual).
        actual = {}
        for doc in _prl_company_ita_docs(session_db):        # vienen ordenados created_at desc
            clave = str(doc.company_id or doc.owner_id)
            actual.setdefault(clave, doc)
        pendientes = 0
        for cid in empresas:
            doc = actual.get(cid)
            if not doc or not _prl_doc_valid_on(doc, hoy):
                pendientes += 1
        return pendientes
    except Exception:
        try:
            session_db.rollback()
        except Exception:
            pass
        return 0


def _admin_pending_counts(session_db) -> dict:
    """Números de las pestañas y subpestañas de Administración: CONTAR, sin cargar las filas.

    Se calcula en cada carga (va siempre al día) y se pinta al lado de cada pestaña para poder ver
    lo que queda por hacer sin tener que entrar. Las listas las carga `administracion_view` solo de
    la pestaña activa.
    """
    def _n(query) -> int:
        """Cuenta, y si la consulta falla NO deja la sesión colgada.
        ⚠️ En Postgres, una sentencia que revienta aborta la transacción entera: sin este rollback,
        el primer contador que fallara haría fallar a todos los siguientes y a las consultas de la
        propia pantalla, y Administración se caía al completo."""
        try:
            return int(query.scalar() or 0)
        except Exception:
            try:
                session_db.rollback()
            except Exception:
                pass
            return 0

    vivos = BagExpense.status != "ELIMINADO"
    solicitudes = _n(session_db.query(func.count(BagExpense.id)).filter(
        vivos, BagExpense.immediate_payment_requested == True))  # noqa: E712
    sin_factura = _n(session_db.query(func.count(BagExpense.id)).filter(
        vivos, BagExpense.consolidation_status == "SIN_FACTURA_SOLICITADO"))
    pago = _n(session_db.query(func.count(BagExpense.id)).filter(
        vivos,
        BagExpense.covered_by == "BOLSA",
        BagExpense.consolidation_status.in_(list(BAG_CONSOLIDATED_STATUSES)),
        BagExpense.payment_status.in_(["NO_PAGADO", "PENDIENTE", "PARCIAL"])))
    # Las liquidaciones de royalties ya validadas también están pendientes de pago: si no se cuentan
    # aquí, el número de la subpestaña no cuadra con lo que se ve dentro.
    pago += _n(session_db.query(func.count(RoyaltyLiquidation.id))
               .join(SupplierInvoice, SupplierInvoice.id == RoyaltyLiquidation.invoice_id)
               .filter(func.upper(func.coalesce(RoyaltyLiquidation.status, "")) == "INVOICED",
                       func.upper(func.coalesce(SupplierInvoice.status, "")) == "VALIDADA",
                       RoyaltyLiquidation.paid_at.is_(None)))
    # Un pago no termina hasta que hay JUSTIFICANTE: los ya pagados sin él siguen contando.
    pago += _n(session_db.query(func.count(BagExpense.id)).filter(
        vivos, BagExpense.payment_status == "PAGADO",
        or_(BagExpense.payment_receipt_url.is_(None), BagExpense.payment_receipt_url == "")))

    bolsas_base = and_(
        WorkflowBag.is_archived == False,  # noqa: E712
        or_(WorkflowBag.status == "CERRADA",
            WorkflowBag.liquidation_status.in_(["PENDIENTE_ADMIN", "PENDIENTE_PAGO"])),
    )
    liquidacion = _n(session_db.query(func.count(WorkflowBag.id)).filter(
        bolsas_base, WorkflowBag.liquidation_status.in_(ADMIN_BAG_LIQUIDACION_STATUSES)))
    cierre = _n(session_db.query(func.count(WorkflowBag.id)).filter(
        bolsas_base, WorkflowBag.liquidation_status.in_(ADMIN_BAG_CIERRE_STATUSES)))
    bolsas_cerradas = _n(session_db.query(func.count(WorkflowBag.id)).filter(bolsas_base))

    cobros = _n(session_db.query(func.count(InvoiceRecord.id)).filter(
        InvoiceRecord.invoice_kind == "ISSUED",
        InvoiceRecord.status.notin_(["PAGADA", "ANULADA"])))
    facturacion = _n(session_db.query(func.count(InvoiceRecord.id)).filter(
        InvoiceRecord.invoice_kind == "ISSUED",
        InvoiceRecord.status.notin_(["PAGADA", "ANULADA"]),
        func.upper(func.coalesce(InvoiceRecord.status, "")).in_(
            ["PENDIENTE_FACTURA", "PENDIENTE_FACTURAR", "BORRADOR", "PENDIENTE"])))

    # Estos dos SÍ se cuentan siempre aunque sus filas solo se carguen en su subpestaña: antes el
    # número se quedaba corto porque la consulta solo corría estando ya dentro.
    facturas_royalties = _n(session_db.query(func.count(SupplierInvoice.id)).filter(
        SupplierInvoice.status == "PENDIENTE",
        SupplierInvoice.royalty_liquidation_id.isnot(None)))
    afavor = _n(session_db.query(func.count(AfavorLiquidation.id)).filter(
        AfavorLiquidation.status == "PENDING_INVOICE"))

    embargos_ordenes = _n(session_db.query(func.count(EmbargoOrder.id)).filter(
        func.upper(func.coalesce(EmbargoOrder.order_type, "")) != "LEVANTAMIENTO",
        func.upper(func.coalesce(EmbargoOrder.status, "")).in_(list(_embargo_visible_statuses()))))
    embargos_legacy = _n(session_db.query(func.count(InvoiceRecord.id)).filter(
        or_(_sa_contains_text(InvoiceRecord.notes, "embargo"),
            _sa_contains_text(InvoiceRecord.status, "embargo"))))

    # Gastos directos por validar (oficina / inversión de artista) + peticiones de «sin factura»
    # de gastos personales + los ya validados que quedan por pagar.
    oficina = _n(session_db.query(func.count(PersonalExpense.id)).filter(
        PersonalExpense.status == "VALIDATING",
        func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "PENDIENTE"))
    oficina += _n(session_db.query(func.count(PersonalExpense.id)).filter(
        func.upper(func.coalesce(PersonalExpense.no_invoice_status, "")) == "SOLICITADO"))
    oficina += _n(session_db.query(func.count(PersonalExpense.id)).filter(
        PersonalExpense.status == "DIRECT",
        func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "APROBADO",
        func.upper(func.coalesce(PersonalExpense.payment_status, "NO_PAGADO")) != "PAGADO",
        ~func.upper(func.coalesce(PersonalExpense.source, "")).in_(["PLEO", "CABIFY"])))

    pending_counts = {
        "solicitudes": solicitudes + sin_factura,
        "oficina": oficina,
        "pago": pago,
        "facturacion": facturacion + afavor,
        "liquidacion": liquidacion + facturas_royalties,
        "cierre": cierre,
    }
    counts = {
        "pendiente": sum(pending_counts.values()),
        "liquidaciones": bolsas_cerradas,
        "pagos": solicitudes + pago,
        "cobros": cobros,
        "embargos": embargos_legacy + embargos_ordenes,
        "altas": _admin_altas_pending_count(session_db),
    }
    return {"counts": counts, "pending_counts": pending_counts}


@app.route("/administracion", endpoint="administracion_view")
@admin_required
def administracion_view():
    session_db = db()
    try:
        tab = (request.args.get("tab") or "pendiente").strip().lower()
        valid_tabs = {key for key, _label in ADMINISTRATION_TABS}
        if tab not in valid_tabs:
            tab = "pendiente"
        pending_subtab = (request.args.get("subtab") or "solicitudes").strip().lower()
        if pending_subtab not in {key for key, _label, _icon in ADMINISTRATION_PENDING_TABS}:
            pending_subtab = "solicitudes"
        liq_subtab = (request.args.get("liq_tab") or request.args.get("subtab") or "bolsas").strip().lower()
        if liq_subtab not in {k for k, _l, _i in ADMINISTRATION_LIQ_TABS}:
            liq_subtab = "bolsas"
        # Liquidaciones enviadas de las que no ha llegado factura (solo se buscan en su subpestaña).
        sent_no_invoice = (_royalty_sent_without_invoice(session_db)
                           if (tab == "liquidaciones" and liq_subtab == "pendiente-factura") else [])
        embargo_subtab = (request.args.get("embargo_tab") or request.args.get("subtab") or "activas").strip().lower()
        if embargo_subtab not in {"activas", "archivadas"}:
            embargo_subtab = "activas"

        # Las LISTAS se cargan solo de la pestaña en la que estás (antes se cargaban las 8 siempre,
        # más un N+1 por bolsa). Los NÚMEROS de todas las pestañas los da `_admin_pending_counts`,
        # que solo cuenta, así que la barra sigue estando al día se mire desde donde se mire.
        pendiente = tab == "pendiente"
        quiere_solicitudes = pendiente and pending_subtab == "solicitudes"
        quiere_pago = pendiente and pending_subtab == "pago"
        quiere_facturacion = pendiente and pending_subtab == "facturacion"
        quiere_oficina = pendiente and pending_subtab == "oficina"
        quiere_bolsas = tab == "liquidaciones" or (pendiente and pending_subtab in ("liquidacion", "cierre"))

        pending_no_invoice = []
        if quiere_solicitudes:
            pending_no_invoice = session_db.query(BagExpense).options(joinedload(BagExpense.bag), joinedload(BagExpense.provider)).filter(
                BagExpense.status != "ELIMINADO",
                BagExpense.consolidation_status == "SIN_FACTURA_SOLICITADO",
            ).order_by(BagExpense.created_at.desc()).all()
        closed_bags = []
        if quiere_bolsas:
            closed_bags = session_db.query(WorkflowBag).options(joinedload(WorkflowBag.artist), joinedload(WorkflowBag.company)).filter(
                WorkflowBag.is_archived == False,  # noqa: E712
                or_(WorkflowBag.status == "CERRADA", WorkflowBag.liquidation_status.in_(["PENDIENTE_ADMIN", "PENDIENTE_PAGO"])),
            ).order_by(WorkflowBag.closed_at.desc().nullslast(), WorkflowBag.created_at.desc()).all()
        # Pestaña PAGOS = ARCHIVO de pagos realizados, con buscador por cualquier campo.
        payments_history, payments_q = [], ""
        if tab == "pagos":
            payments_q = (request.args.get("q") or "").strip()
            payments_history = _payments_history_rows(session_db, q=payments_q)
        # Pagados a los que les falta el JUSTIFICANTE: siguen siendo trabajo pendiente.
        paid_no_receipt = (_paid_without_receipt_expenses(session_db)
                           if (quiere_pago or tab == "pendiente") else [])
        payment_requests = []
        if quiere_solicitudes:
            payment_requests = session_db.query(BagExpense).options(joinedload(BagExpense.bag), joinedload(BagExpense.provider), selectinload(BagExpense.payment_events)).filter(
                BagExpense.status != "ELIMINADO",
                BagExpense.immediate_payment_requested == True,  # noqa: E712
            ).order_by(BagExpense.immediate_payment_requested_at.asc().nullslast(), BagExpense.created_at.asc()).all()
        payable_expenses = []
        if quiere_pago:
            payable_expenses = session_db.query(BagExpense).options(joinedload(BagExpense.bag), joinedload(BagExpense.provider)).filter(
                BagExpense.status != "ELIMINADO",
                BagExpense.covered_by == "BOLSA",
                BagExpense.consolidation_status.in_(list(BAG_CONSOLIDATED_STATUSES)),
                BagExpense.payment_status.in_(["NO_PAGADO", "PENDIENTE", "PARCIAL"]),
            ).order_by(BagExpense.created_at.desc()).limit(ADMIN_LIST_LIMIT).all()
        receivable_invoices = []
        if tab == "cobros" or quiere_facturacion:
            receivable_invoices = session_db.query(InvoiceRecord).options(joinedload(InvoiceRecord.artist), joinedload(InvoiceRecord.company), joinedload(InvoiceRecord.bag)).filter(
                InvoiceRecord.invoice_kind == "ISSUED",
                InvoiceRecord.status.notin_(["PAGADA", "ANULADA"]),
            ).order_by(InvoiceRecord.due_date.asc().nullslast(), InvoiceRecord.issue_date.desc()).all()
        billing_pending = [inv for inv in receivable_invoices if (getattr(inv, "status", "") or "").upper() in {"PENDIENTE_FACTURA", "PENDIENTE_FACTURAR", "BORRADOR", "PENDIENTE"}]

        embargo_rows, embargo_orders, embargo_promoters = [], [], []
        embargo_active_orders, embargo_archived_orders, embargo_email_map = [], [], {}
        if tab == "embargos":
            embargo_rows = session_db.query(InvoiceRecord).options(joinedload(InvoiceRecord.artist), joinedload(InvoiceRecord.company), joinedload(InvoiceRecord.bag)).filter(
                or_(_sa_contains_text(InvoiceRecord.notes, "embargo"), _sa_contains_text(InvoiceRecord.status, "embargo"))
            ).order_by(InvoiceRecord.issue_date.desc()).all()
            embargo_orders = session_db.query(EmbargoOrder).options(
                joinedload(EmbargoOrder.promoter),
                joinedload(EmbargoOrder.suggested_promoter),
            ).order_by(EmbargoOrder.created_at.desc()).limit(500).all()
            embargo_active_orders = [o for o in embargo_orders if (o.order_type or "").upper() != "LEVANTAMIENTO" and (o.status or "").upper() in _embargo_visible_statuses()]
            embargo_archived_orders = [o for o in embargo_orders if (o.status or "").upper() == "ARCHIVADA" or (o.order_type or "").upper() == "LEVANTAMIENTO"]
            embargo_promoters = session_db.query(Promoter).options(selectinload(Promoter.companies)).order_by(Promoter.nick.asc()).limit(1000).all()
            embargo_email_map = {str(order.id): _embargo_order_email_suggestions(session_db, order) for order in embargo_orders}

        direct_pending, direct_no_invoice, direct_payable = [], [], []
        if quiere_oficina:
            direct_pending = _personal_direct_expenses_pending(session_db)
            direct_no_invoice = _personal_no_invoice_pending(session_db)
            direct_payable = _personal_direct_expenses_payable(session_db)

        admin_expense_embargo_alerts = {}
        if "_expense_active_embargo_alerts" in globals():
            for expense in list(payment_requests or []) + list(payable_expenses or []) + list(pending_no_invoice or []):
                alerts = _expense_active_embargo_alerts(session_db, expense)
                if alerts:
                    admin_expense_embargo_alerts[str(expense.id)] = alerts

        bag_totals = {}
        for bag in closed_bags:
            exps = session_db.query(BagExpense).filter(BagExpense.bag_id == bag.id, BagExpense.status != "ELIMINADO").all()
            bag_totals[str(bag.id)] = _bag_totals(exps) if "_bag_totals" in globals() else {"bag": Decimal("0")}

        # Los números salen de un motor propio que solo CUENTA (sin cargar filas), así que valen
        # para todas las pestañas estés donde estés y no dependen de qué listas se hayan cargado.
        _admin_counts = _admin_pending_counts(session_db)
        counts = _admin_counts["counts"]
        pending_counts = _admin_counts["pending_counts"]
        # Qué pestañas son TUYAS (te han asignado esa responsabilidad). Se marcan con un punto, sin
        # esconder nada: el número que se ve sigue siendo el real de toda la casa.
        _mias = set(_current_user_admin_responsibilities())
        admin_my_tabs = {k for k, r in ADMIN_TAB_RESPONSIBILITY.items() if r and r in _mias}
        admin_my_pending_tabs = {k for k, r in ADMIN_PENDING_TAB_RESPONSIBILITY.items() if r and r in _mias}
        # Quien liquida las de PROMOCIÓN sin pagos pendientes trabaja en las mismas dos bandejas.
        if "LIQUIDACIONES_PROMO" in _mias:
            admin_my_pending_tabs |= {"liquidacion", "cierre"}
        # Marca por fila: qué bolsas son «de promoción sin pagos pendientes».
        admin_promo_bag_ids = (_admin_promo_bag_ids(session_db)
                               if (tab == "pendiente" and pending_subtab in {"liquidacion", "cierre"}) else set())
        altas_ctx = _prl_admin_altas_context(session_db) if tab == "altas" else {"altas_rows": [], "altas_today": date.today()}
        # Facturas SUELTAS (sin liquidación, bolsa ni persona): la red de seguridad del enlace de
        # royalties. Solo se buscan en su pestaña, que la consulta no es gratis.
        _en_liquidacion = (tab == "pendiente" and pending_subtab == "liquidacion")
        orphan_invoice_rows = _orphan_supplier_invoices(session_db) if _en_liquidacion else []
        royalty_link_options = (_royalty_liquidation_link_options(session_db)
                                if orphan_invoice_rows else [])
        royalty_invoice_rows = (_royalty_invoice_pending_rows(session_db)
                                if _en_liquidacion else [])
        afavor_invoice_rows = (_afavor_admin_pending_rows(session_db)
                               if (tab == "pendiente" and pending_subtab == "facturacion") else [])
        return render_template(
            "administracion.html",
            tab=tab,
            tabs=ADMINISTRATION_TABS,
            group_companies=session_db.query(GroupCompany).order_by(GroupCompany.name).all() if tab == "altas" else [],
            **altas_ctx,
            pending_subtab=pending_subtab,
            pending_tabs=ADMINISTRATION_PENDING_TABS,
            liq_tabs=ADMINISTRATION_LIQ_TABS,
            liq_subtab=liq_subtab,
            sent_no_invoice=sent_no_invoice,
            # Misma fuente de verdad que el contador: el número y las filas no pueden discrepar.
            ADMIN_BAG_LIQUIDACION_STATUSES=ADMIN_BAG_LIQUIDACION_STATUSES,
            ADMIN_BAG_CIERRE_STATUSES=ADMIN_BAG_CIERRE_STATUSES,
            admin_my_tabs=admin_my_tabs,
            admin_my_pending_tabs=admin_my_pending_tabs,
            admin_promo_bag_ids=admin_promo_bag_ids,
            # Pendiente de pago: agrupado por empresa del grupo, con sus remesas y sus cuentas.
            payment_groups=(_payment_pending_context(session_db)
                            if (tab == "pendiente" and pending_subtab == "pago") else []),
            iban_masked=_iban_masked,
            admin_list_limit=ADMIN_LIST_LIMIT,
            direct_pending=direct_pending,
            direct_no_invoice=direct_no_invoice,
            direct_payable=direct_payable,
            royalty_invoice_rows=royalty_invoice_rows,
            orphan_invoice_rows=orphan_invoice_rows,
            royalty_link_options=royalty_link_options,
            afavor_invoice_rows=afavor_invoice_rows,
            embargo_subtab=embargo_subtab,
            pending_counts=pending_counts,
            counts=counts,
            pending_no_invoice=pending_no_invoice,
            closed_bags=closed_bags,
            payment_requests=payment_requests,
            payable_expenses=payable_expenses,
            payments_history=payments_history,
            payments_q=payments_q,
            paid_no_receipt=paid_no_receipt,
            receivable_invoices=receivable_invoices,
            billing_pending=billing_pending,
            embargo_rows=embargo_rows,
            embargo_orders=embargo_orders,
            embargo_active_orders=embargo_active_orders,
            embargo_archived_orders=embargo_archived_orders,
            embargo_promoters=embargo_promoters,
            embargo_email_map=embargo_email_map,
            admin_expense_embargo_alerts=admin_expense_embargo_alerts,
            bag_totals=bag_totals,
            payment_methods=BAG_PAYMENT_METHODS,
            payment_status_labels=BAG_PAYMENT_STATUS_LABELS,
        )
    finally:
        session_db.close()


@app.post("/administracion/gastos/<expense_id>/sin-factura/<decision>", endpoint="administration_no_invoice_decision")
@admin_required
def administration_no_invoice_decision(expense_id, decision):
    session_db = db()
    try:
        expense = session_db.get(BagExpense, to_uuid(expense_id))
        if not expense:
            flash("Gasto no encontrado.", "warning")
            return redirect(url_for("administracion_view", tab="pendiente"))
        decision = (decision or "").strip().lower()
        audit = _bag_current_user_audit() if "_bag_current_user_audit" in globals() else {"user_id": None, "nick": "Administración"}
        if decision == "approve":
            expense.consolidation_status = "SIN_FACTURA_ACEPTADO"
            expense.no_invoice_rejection_reason = None
            session_db.add(BagPaymentInteraction(expense_id=expense.id, kind="SIN_FACTURA_ACEPTADO", description="Administración acepta consolidar sin factura/ticket.", created_by_user_id=audit["user_id"], created_by_nick=audit["nick"]))
            flash("Gasto consolidado sin factura/ticket.", "success")
        else:
            reason = (request.form.get("reason") or "").strip()
            expense.consolidation_status = "SIN_FACTURA_RECHAZADO"
            expense.no_invoice_rejection_reason = reason or "Solicitud rechazada por administración."
            session_db.add(BagPaymentInteraction(expense_id=expense.id, kind="SIN_FACTURA_RECHAZADO", description=expense.no_invoice_rejection_reason, created_by_user_id=audit["user_id"], created_by_nick=audit["nick"]))
            flash("Solicitud rechazada.", "warning")
        expense.updated_at = _now_madrid()
        session_db.commit()
    finally:
        session_db.close()
    return redirect(url_for("administracion_view", tab="pendiente"))


@app.post("/administracion/gastos/<expense_id>/pago", endpoint="administration_expense_mark_paid")
@admin_required
def administration_expense_mark_paid(expense_id):
    session_db = db()
    try:
        expense = session_db.get(BagExpense, to_uuid(expense_id))
        if not expense:
            flash("Gasto no encontrado.", "warning")
            return redirect(url_for("administracion_view", tab="pagos"))
        volver = safe_next_or(request.form.get("next") or url_for("administracion_view", tab="pendiente", subtab="pago"))
        # SOLO EL JUSTIFICANTE: el gasto ya está pagado y lo único que falta es la prueba. No se
        # tocan importes ni se apunta otro pago (si no, se registraría un cobro que no existe).
        if _truthy(request.form.get("only_receipt")):
            recibo = request.files.get("receipt")
            if not (recibo and getattr(recibo, "filename", "")):
                flash("Adjunta el justificante del pago.", "warning")
                return redirect(volver)
            url_recibo, nombre_recibo, _m = _bag_document_upload(recibo)
            expense.payment_receipt_url = url_recibo
            expense.payment_receipt_name = nombre_recibo
            expense.updated_at = _now_madrid()
            if getattr(expense, "bag_id", None):
                _bag_close_if_fully_paid(session_db, session_db.get(WorkflowBag, expense.bag_id))
            session_db.commit()
            flash("Justificante guardado: el pago queda cerrado y archivado en «Pagos».", "success")
            return redirect(volver)
        # ⚠️ LO QUE HAY QUE PAGARLE es el TOTAL DE LA FACTURA (bruto − retención): la retención no se
        # le abona (la ingresa la casa en Hacienda). Medir contra el bruto dejaba el gasto en PARCIAL
        # para siempre al pagar lo que decía la factura.
        gross = _expense_payable_gross(expense, _expense_retention(session_db, expense))
        ya_pagado = _money_or_zero(getattr(expense, "paid_amount", 0))
        pendiente = gross - ya_pagado
        if pendiente < 0:
            pendiente = Decimal("0")
        # El importe del formulario es lo que se paga AHORA (no el acumulado): así, si ya había un
        # pago parcial, lo natural es pagar la DIFERENCIA y no volver a teclear el total.
        ahora = _bag_money(request.form.get("paid_amount")) if "_bag_money" in globals() else Decimal("0")
        if ahora <= 0:
            ahora = pendiente if pendiente > 0 else gross
        parcial = _truthy(request.form.get("partial")) or ahora < pendiente
        # ⚠️ Un pago PARCIAL no cabe en una remesa: la remesa manda al banco el importe pendiente
        # entero. Si el gasto está metido en una que aún no se ha pagado, hay que sacarlo.
        batch = session_db.get(PaymentBatch, expense.payment_batch_id) if getattr(expense, "payment_batch_id", None) else None
        if parcial and batch is not None and (batch.status or "BORRADOR").upper() != "PAGADA":
            if not _truthy(request.form.get("salir_remesa")):
                flash(f"Este gasto está en la remesa {batch.reference}. Un pago parcial exige sacarlo de "
                      f"la remesa primero (puedes marcar «sacarlo de la remesa» en el propio pago).", "warning")
                return redirect(volver)
            for item in (session_db.query(PaymentBatchItem)
                         .filter(PaymentBatchItem.batch_id == batch.id,
                                 PaymentBatchItem.expense_id == expense.id).all()):
                session_db.delete(item)
            expense.payment_batch_id = None
            session_db.flush()
            _payment_batch_refresh_total(session_db, batch)

        total_pagado = ya_pagado + ahora
        if total_pagado > gross and gross > 0:
            total_pagado = gross
        expense.paid_amount = total_pagado
        expense.payment_status = "PAGADO" if (gross > 0 and total_pagado >= gross) else "PARCIAL"
        expense.payment_method = (request.form.get("payment_method") or expense.payment_method or "").strip() or None
        receipt = request.files.get("receipt") if hasattr(request, "files") else None
        if receipt and getattr(receipt, "filename", ""):
            receipt_url, receipt_name, _receipt_mime = _bag_document_upload(receipt)
            expense.payment_receipt_url = receipt_url
            expense.payment_receipt_name = receipt_name
        expense.immediate_payment_requested = False if expense.payment_status == "PAGADO" else expense.immediate_payment_requested
        if expense.payment_status == "PAGADO":
            _notify_resolve(session_db, "EXPENSE", expense.id)
        expense.updated_at = _now_madrid()
        audit = _bag_current_user_audit() if "_bag_current_user_audit" in globals() else {"user_id": None, "nick": "Administración"}
        queda = gross - total_pagado
        detalle = ("Pago parcial registrado desde administración."
                   if expense.payment_status == "PARCIAL" else "Pago registrado desde administración.")
        session_db.add(BagPaymentInteraction(expense_id=expense.id, kind="PAGO_REGISTRADO", description=detalle,
                                             amount=ahora, method=expense.payment_method,
                                             created_by_user_id=audit["user_id"], created_by_nick=audit["nick"]))
        session_db.flush()
        archivada = False
        if expense.payment_status == "PAGADO" and getattr(expense, "bag_id", None):
            archivada = _bag_close_if_fully_paid(session_db, session_db.get(WorkflowBag, expense.bag_id))
        session_db.commit()
        if expense.payment_status == "PARCIAL":
            flash(f"Pago parcial registrado. Quedan {format_eur(queda)} por pagar.", "success")
        else:
            flash("Pago registrado." + (" La bolsa se ha cerrado y archivado." if archivada else ""), "success")
        return redirect(volver)
    finally:
        session_db.close()


