# ===========================================================================
#  CONTABILIDAD · PENDIENTE DE CONTABILIZAR
#  ------------------------------------------------------------------------
#  Lo que llega aquí es lo que ADMINISTRACIÓN YA HA VALIDADO (gastos consolidados: con su factura, con
#  su ticket o con el «sin factura» aceptado) y todavía no está contabilizado. De cada gasto se sube a
#  Holded una compra nueva (los tickets, un gasto) y el estado contable se queda en el propio gasto,
#  así que la etiqueta «Contabilizado» se ve también en la bolsa y en cualquier pantalla donde salga.
#
#  Las pestañas son SERVIDAS (enlaces con ?tab=), como en Administración: la zona que se refresca sin
#  recargar (`#accZone`) va DENTRO, nunca es la pestaña (ver la nota de ajax_inline en CLAUDE.md).
# ===========================================================================

# ⚠️ NO hay pestaña «Facturas»: el registro de facturas vive en Bases de datos → Facturas y aquí
# solo repetía la misma información (se retiró en ago 2026).
ACCOUNTING_TABS = [
    ("pendiente", "Pendiente de contabilizar", "fa-hourglass-half"),
    ("contabilizado", "Contabilizado", "fa-circle-check"),
    ("retenciones", "Retenciones", "fa-percent"),
]
# Subpestañas de «Pendiente de contabilizar» (y las MISMAS en «Contabilizado», donde no llevan
# número: ahí no hay nada pendiente que contar).
ACCOUNTING_PENDING_TABS = [
    ("facturas", "Facturas", "fa-file-invoice"),
    ("bolsas", "Bolsas", "fa-sack-dollar"),
    ("tickets", "Tickets", "fa-receipt"),
    ("sin-ticket", "Sin ticket", "fa-ban"),
]
# Subpestaña → tipo de documento del gasto.
ACCOUNTING_SUBTAB_DOC = {"facturas": "FACTURA", "tickets": "TICKET", "sin-ticket": "SIN_DOCUMENTO"}
# Las pestañas que tienen permiso propio (`contabilidad.<clave>`): punto único para la vista y para
# la resolución de permisos, que si no se desincronizan.
ACCOUNTING_TAB_KEYS = {k for k, _l, _i in ACCOUNTING_TABS}
ACCOUNTING_DOC_META = {
    "FACTURA": ("Factura", "fa-file-invoice", "text-bg-primary"),
    "TICKET": ("Ticket", "fa-receipt", "text-bg-info text-dark"),
    "SIN_DOCUMENTO": ("Sin ticket", "fa-ban", "text-bg-light border text-dark"),
}


def _normalize_company_ids(values) -> list[str]:
    """Ids de empresa del grupo, limpios y sin repetir (lo que llega de un formulario múltiple)."""
    salida = []
    for raw in (values or []):
        cid = str(to_uuid(str(raw).strip()) or "")
        if cid and cid not in salida:
            salida.append(cid)
    return salida


def _accounting_company_scope(state: dict | None = None) -> list[str]:
    """Las EMPRESAS DEL GRUPO que lleva quien mira, en contabilidad. Vacío = las ve todas.

    Es un reparto de TRABAJO, no un permiso: quien no tenga empresas asignadas (y dirección) sigue
    viendo todo, y lo que no es de ninguna empresa lo ven todos (nada se pierde en silencio)."""
    try:
        state = state or _current_user_state()
        if int(state.get("role") or 0) == 10:
            return []                      # dirección no tiene reparto: lo ve todo
        prof = state.get("profile")
        return [str(x) for x in (getattr(prof, "accounting_company_ids", None) or []) if x]
    except Exception:
        return []


def _accounting_company_user_ids(session_db, company_id) -> list[str]:
    """Quién de CONTABILIDAD lleva esa empresa del grupo (para avisarle de lo que le toca).

    ⚠️ Si NADIE la tiene asignada se avisa a todo el departamento: mejor que se lo miren varios que
    dejar una bolsa sin que nadie sepa que hay que contabilizarla (mismo criterio que el resto de la
    app con los repartos sin dueño)."""
    cid = str(company_id or "")
    fuera = _inactive_user_ids(session_db)
    del_dpto, suyas = [], []
    try:
        for prof in session_db.query(UserProfile).all():
            uid = str(getattr(prof, "user_id", "") or "")
            if not uid or to_uuid(uid) in fuera:
                continue
            if not _profile_in_department(prof, "Contabilidad"):
                continue
            del_dpto.append(uid)
            if cid and cid in [str(x) for x in (getattr(prof, "accounting_company_ids", None) or [])]:
                suyas.append(uid)
    except Exception:
        return []
    return suyas or del_dpto


def can_edit_accounting() -> bool:
    """¿Puede esta persona contabilizar (subir a Holded, cambiar el estado, omitir)?"""
    return is_master() or has_access_key("contabilidad", edit=True, include_descendants=True)


def _accounting_doc_meta(document_type: str | None) -> tuple[str, str, str]:
    return ACCOUNTING_DOC_META.get((document_type or "FACTURA").strip().upper(),
                                   ACCOUNTING_DOC_META["FACTURA"])


def _accounting_base_query(session_db, *, doc_types=None, include_done: bool = False,
                           only_done: bool = False, company_ids=None):
    """Gastos que le tocan a contabilidad: validados por administración y de un tipo de documento.

    Con `company_ids` se limita a las EMPRESAS DEL GRUPO de quien mira (su reparto de trabajo).
    ⚠️ Se incluyen SIEMPRE los gastos cuya bolsa no tiene empresa puesta: no son de nadie y si se
    filtraran desaparecerían de la pantalla de todo el mundo."""
    q = (session_db.query(BagExpense)
         .options(joinedload(BagExpense.bag).joinedload(WorkflowBag.artist),
                  joinedload(BagExpense.provider),
                  joinedload(BagExpense.provider_company))
         .filter(BagExpense.status != "ELIMINADO"))
    if company_ids:
        ids = [to_uuid(str(x)) for x in company_ids if to_uuid(str(x))]
        if ids:
            _bag = aliased(WorkflowBag)
            q = (q.join(_bag, _bag.id == BagExpense.bag_id)
                 .filter(or_(_bag.company_id.in_(ids), _bag.company_id.is_(None))))
    # ⚠️ El cruce con «validado por administración» (`consolidation_status`) es para decidir qué está
    # PENDIENTE de contabilizar. En la pestaña de CONTABILIZADO no se aplica: lo que ya se marcó tiene
    # que aparecer ahí SIEMPRE, aunque su gasto haya cambiado de estado después — si no, desaparecía de
    # las dos pestañas y no había forma de encontrarlo (bug real).
    if not only_done:
        q = q.filter(BagExpense.consolidation_status.in_(list(BAG_CONSOLIDATED_STATUSES)))
    if doc_types:
        q = q.filter(func.upper(func.coalesce(BagExpense.document_type, "FACTURA")).in_(list(doc_types)))
    estado = func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE"))
    if only_done:
        q = q.filter(estado.in_(list(ACCOUNTING_DONE_STATUSES)))
    elif not include_done:
        q = q.filter(~estado.in_(list(ACCOUNTING_DONE_STATUSES)))
    return q


def _accounting_counts(session_db, company_ids=None) -> dict:
    """Números de las pestañas: solo cuentas (`func.count`), sin cargar filas.

    ⚠️ Se cuentan con el MISMO filtro de empresas que las filas: si no, el número de la pestaña no
    cuadraría con lo que se ve debajo."""
    # ⚠️ No hay número de «Contabilizado»: es un archivo que solo crece y un contador ahí no dice
    # nada (los números son de lo que está PENDIENTE).
    salida = {"facturas": 0, "tickets": 0, "sin-ticket": 0, "bolsas": 0, "pendiente": 0}
    try:
        filas = (_accounting_base_query(session_db, company_ids=company_ids)
                 .with_entities(func.upper(func.coalesce(BagExpense.document_type, "FACTURA")),
                                func.count(BagExpense.id))
                 .group_by(func.upper(func.coalesce(BagExpense.document_type, "FACTURA"))).all())
        por_tipo = {str(k or "FACTURA"): int(n or 0) for k, n in filas}
        for clave, tipo in ACCOUNTING_SUBTAB_DOC.items():
            salida[clave] = por_tipo.get(tipo, 0)
        # Las liquidaciones de ROYALTIES pendientes son facturas: cuentan en «Facturas» (y por tanto
        # en el total de pendiente), que es donde se listan.
        try:
            salida["facturas"] += len(_royalty_accounting_pending_rows(session_db, company_ids=company_ids))
        except Exception:
            app.logger.exception("[contabilidad] no se pudieron contar las liquidaciones pendientes")
        salida["pendiente"] = sum(salida[c] for c in ACCOUNTING_SUBTAB_DOC)
        # Bolsas: cuántas tienen algo pendiente (una bolsa con tres gastos cuenta UNA).
        salida["bolsas"] = (_accounting_base_query(session_db, company_ids=company_ids)
                            .with_entities(func.count(func.distinct(BagExpense.bag_id))).scalar()) or 0
    except Exception:
        pass
    return salida


def _retention_status_map(session_db, invoices) -> dict:
    """De cada factura con retención: si está PAGADA (cuándo y cómo) y si está CONTABILIZADA.

    Una retención se declara cuando la factura está validada y pagada, así que en esa pantalla los
    tres estados van juntos: validada → pagada → contabilizada. Todo en consultas EN BLOQUE (son
    cientos de filas: nada de una consulta por factura).
    """
    salida = {}
    if not invoices:
        return salida
    inv_ids = [i.id for i in invoices]
    # --- de qué cuelga cada factura: liquidación de royalties o gasto de bolsa ---
    liq_por_inv, exp_por_inv = {}, {}
    for inv in invoices:
        if getattr(inv, "royalty_liquidation_id", None):
            liq_por_inv[str(inv.id)] = inv.royalty_liquidation_id
        elif getattr(inv, "bag_expense_id", None):
            exp_por_inv[str(inv.id)] = inv.bag_expense_id
    try:
        for r in (session_db.query(BagExpenseInvoice.invoice_id, BagExpenseInvoice.bag_expense_id)
                  .filter(BagExpenseInvoice.invoice_id.in_(inv_ids)).all()):
            exp_por_inv.setdefault(str(r[0]), r[1])
    except Exception:
        pass
    # --- las liquidaciones y los gastos, de una vez ---
    liqs, gastos, lotes = {}, {}, {}
    if liq_por_inv:
        for rec in (session_db.query(RoyaltyLiquidation)
                    .filter(RoyaltyLiquidation.id.in_(list(liq_por_inv.values()))).all()):
            liqs[str(rec.id)] = rec
    if exp_por_inv:
        for e in (session_db.query(BagExpense)
                  .filter(BagExpense.id.in_(list(exp_por_inv.values()))).all()):
            gastos[str(e.id)] = e
    batch_ids = ([getattr(r, "payment_batch_id", None) for r in liqs.values()]
                 + [getattr(e, "payment_batch_id", None) for e in gastos.values()])
    batch_ids = [b for b in batch_ids if b]
    if batch_ids:
        for b in session_db.query(PaymentBatch).filter(PaymentBatch.id.in_(batch_ids)).all():
            lotes[str(b.id)] = b

    def _como(batch, metodo, fecha) -> str:
        """«Pagado el 12/08/2026 · Remesa REM-2026-0004» o «… · Pleo». Es el tooltip del euro."""
        partes = []
        if fecha:
            partes.append("Pagado el %s" % fecha.strftime("%d/%m/%Y"))
        else:
            partes.append("Pagado")
        if batch is not None and (getattr(batch, "reference", None) or "").strip():
            partes.append("Remesa %s" % batch.reference.strip())
        elif (metodo or "").strip():
            partes.append((metodo or "").strip())
        return " · ".join(partes)

    for inv in invoices:
        clave = str(inv.id)
        ficha = {"paid": False, "partial": False, "pay_title": "Sin pagar",
                 "accounted": False, "accounted_label": ""}
        rec = liqs.get(str(liq_por_inv.get(clave) or ""))
        exp = gastos.get(str(exp_por_inv.get(clave) or ""))
        if rec is not None:
            lote = lotes.get(str(getattr(rec, "payment_batch_id", "") or ""))
            pagada = bool(getattr(rec, "paid_at", None))
            fecha = (rec.paid_at.date() if getattr(rec, "paid_at", None) else None)
            ficha.update({
                "paid": pagada,
                "pay_title": (_como(lote, getattr(rec, "payment_method", None), fecha) if pagada
                              else "Sin pagar"),
                "accounted": bool(getattr(rec, "accounted_at", None)),
                "accounted_label": (rec.accounted_at.strftime("%d/%m/%Y")
                                    if getattr(rec, "accounted_at", None) else ""),
            })
        elif exp is not None:
            estado = (getattr(exp, "payment_status", None) or "NO_PAGADO").upper()
            lote = lotes.get(str(getattr(exp, "payment_batch_id", "") or ""))
            # ⚠️ Un gasto no tiene columna con la fecha de pago: la mejor que hay es la de la remesa
            # (la de verdad) y, si se pagó a mano, la última vez que se tocó el gasto.
            fecha = (getattr(lote, "execution_date", None)
                     or (lote.paid_at.date() if getattr(lote, "paid_at", None) else None)
                     or (exp.updated_at.date() if getattr(exp, "updated_at", None) else None))
            ficha.update({
                "paid": estado == "PAGADO",
                "partial": estado == "PARCIAL",
                "pay_title": (_como(lote, getattr(exp, "payment_method", None), fecha)
                              if estado == "PAGADO" else
                              ("Pagado en parte: %s de %s"
                               % (format_eur(getattr(exp, "paid_amount", 0)),
                                  format_eur(getattr(exp, "amount_gross", 0)))
                               if estado == "PARCIAL" else "Sin pagar")),
                "accounted": (getattr(exp, "accounting_status", None) or "PENDIENTE").upper()
                             in ACCOUNTING_DONE_STATUSES,
                "accounted_label": (exp.accounting_at.strftime("%d/%m/%Y")
                                    if getattr(exp, "accounting_at", None) else ""),
            })
        salida[clave] = ficha
    return salida


def _accounting_retention_rows(session_db, *, year: int | None = None, limit: int = 800) -> dict:
    """TODAS las facturas recibidas CON RETENCIÓN, con sus importes.

    ⚠️ La retención **no se descuenta del gasto**: el gasto es la base más su IVA. Lo retenido se le
    queda la casa para ingresarlo en Hacienda, así que se declara aparte —por eso esta pantalla— y por
    eso las filas llevan su TRIMESTRE (que es como se declara).
    """
    q = (session_db.query(SupplierInvoice)
         .options(joinedload(SupplierInvoice.promoter))
         .filter(SupplierInvoice.retention_amount.isnot(None))
         .filter(SupplierInvoice.retention_amount > 0)
         # ⚠️ Ni las RECHAZADAS ni las ANULADAS ni las RECTIFICADAS: no valen, así que su retención no
         # se declara (la de la rectificativa sí, que es la que vale).
         .filter(func.upper(func.coalesce(SupplierInvoice.status, ""))
                 .notin_(["RECHAZADA", "ANULADA", "RECTIFICADA"])))
    if year:
        q = q.filter(or_(
            and_(SupplierInvoice.issue_date.isnot(None),
                 func.extract("year", SupplierInvoice.issue_date) == year),
            and_(SupplierInvoice.issue_date.is_(None),
                 func.extract("year", SupplierInvoice.created_at) == year)))
    invoices = q.order_by(SupplierInvoice.issue_date.desc().nullslast(),
                          SupplierInvoice.created_at.desc()).limit(limit).all()
    # De qué es cada factura (para saber a qué gasto pertenece la retención), de golpe.
    liq_ids = [i.royalty_liquidation_id for i in invoices if getattr(i, "royalty_liquidation_id", None)]
    liquidaciones = {}
    if liq_ids:
        for rec in session_db.query(RoyaltyLiquidation).filter(RoyaltyLiquidation.id.in_(liq_ids)).all():
            liquidaciones[str(rec.id)] = rec
    bag_ids = [i.bag_id for i in invoices if getattr(i, "bag_id", None)]
    bolsas = {}
    if bag_ids:
        for b in session_db.query(WorkflowBag).filter(WorkflowBag.id.in_(bag_ids)).all():
            bolsas[str(b.id)] = b
    estados = _retention_status_map(session_db, invoices)
    filas, total_ret, total_base = [], Decimal("0"), Decimal("0")
    por_trimestre = {}
    for inv in invoices:
        fecha = inv.issue_date or (inv.created_at.date() if inv.created_at else None)
        ret = _money_or_zero(inv.retention_amount)
        base = _money_or_zero(inv.amount_net)
        iva = _money_or_zero(inv.amount_vat)
        bruto = _money_or_zero(inv.amount_gross)
        ret_pct = inv.retention_pct
        if ret_pct in (None, "") and base > 0 and ret > 0:
            ret_pct = _tax_pct_snap((ret / base * Decimal("100")).quantize(Decimal("0.01")), RETENTION_RATES)
        origen, origen_url = "", ""
        rec = liquidaciones.get(str(getattr(inv, "royalty_liquidation_id", "") or ""))
        bag = bolsas.get(str(getattr(inv, "bag_id", "") or ""))
        if rec is not None:
            origen = "Royalties · " + _royalty_liquidation_period_label_from_dates(
                rec.period_start, rec.period_end)
        elif bag is not None:
            origen = (bag.title or "Bolsa").strip()
            origen_url = url_for("bag_detail_view", bag_id=bag.id)
        elif getattr(inv, "target_user_id", None):
            origen = "Gasto de una persona"
        clave_trim = _quarter_key(fecha.year, _quarter_of(fecha)) if fecha else ""
        filas.append({
            "id": str(inv.id),
            "name": (_promoter_display_name(inv.promoter) or getattr(inv.promoter, "nick", None)
                     or "Proveedor"),
            "tax_id": (getattr(inv.promoter, "tax_id", None) or ""),
            "number": (inv.invoice_number or ""),
            "concept": (inv.concept_text or ""),
            "date": (fecha.strftime("%d/%m/%Y") if fecha else ""),
            "quarter_key": clave_trim,
            "quarter_label": (_quarter_label(fecha.year, _quarter_of(fecha)) if fecha else "Sin fecha"),
            "net": base, "vat": iva, "gross": bruto,
            "retention": ret, "retention_pct": ret_pct,
            "status": (inv.status or "PENDIENTE").upper(),
            # PAGADA (con su cuándo y su cómo, para el tooltip del euro) y CONTABILIZADA.
            **(estados.get(str(inv.id)) or {"paid": False, "partial": False,
                                            "pay_title": "Sin pagar", "accounted": False,
                                            "accounted_label": ""}),
            "origin": origen, "origin_url": origen_url,
            "file_url": (inv.file_url or ""),
            "edit_url": url_for("supplier_invoice_edit", invoice_id=inv.id),
            "missing": _supplier_invoice_missing_fields(inv),
        })
        total_ret += ret
        total_base += base
        grupo = por_trimestre.setdefault(clave_trim or "zz", {
            "label": (_quarter_label(fecha.year, _quarter_of(fecha)) if fecha else "Sin fecha"),
            "retention": Decimal("0"), "net": Decimal("0"), "n": 0})
        grupo["retention"] += ret
        grupo["net"] += base
        grupo["n"] += 1
    años = []
    try:
        años = [int(a) for (a,) in session_db.query(
            func.distinct(func.extract("year", func.coalesce(SupplierInvoice.issue_date,
                                                             SupplierInvoice.created_at))))
            .filter(SupplierInvoice.retention_amount.isnot(None),
                    SupplierInvoice.retention_amount > 0).all() if a]
        años.sort(reverse=True)
    except Exception:
        años = []
    return {"rows": filas, "total_retention": total_ret, "total_net": total_base,
            "quarters": [por_trimestre[k] for k in sorted(por_trimestre)], "years": años}


def _accounting_bag_label(session_db, bag, *, concert=None, promotion=None) -> str:
    """Cómo se llama la bolsa en el listado.

    El nombre de la bolsa; si no lo tiene, el del evento/actividad; y una promoción sin nombre se
    dice «Promoción» con su fecha, que es lo que la identifica.
    """
    titulo = (getattr(bag, "title", None) or "").strip()
    if titulo:
        return titulo
    if concert is not None:
        partes = [(getattr(concert, "festival_name", None) or "").strip(),
                  ((getattr(getattr(concert, "venue", None), "municipality", None) or "").strip()
                   or (getattr(concert, "manual_municipality", None) or "").strip())]
        fecha = getattr(concert, "date", None)
        etiqueta = " · ".join([x for x in partes if x])
        if fecha:
            etiqueta = (etiqueta + " · " if etiqueta else "") + fecha.strftime("%d/%m/%Y")
        if etiqueta:
            return etiqueta
    if promotion is not None:
        nombre = (getattr(promotion, "name", None) or "").strip()
        if nombre:
            return nombre
        fecha = (getattr(promotion, "starts_on", None) or getattr(promotion, "target_date", None)
                 or getattr(bag, "start_date", None))
        return "Promoción" + (" · " + fecha.strftime("%d/%m/%Y") if fecha else "")
    return (getattr(bag, "linked_title", None) or "Sin bolsa").strip()


def _accounting_prefetch(session_db, expenses) -> dict:
    """Todo lo que hacen falta las filas, cargado DE GOLPE (nada de una consulta por gasto)."""
    datos = {"concerts": {}, "promotions": {}, "invoices": {}, "files": {}, "batches": {},
             "companies": {}, "artists": {}, "payers": {}}
    if not expenses:
        return datos
    ids = [e.id for e in expenses]
    bags = {}
    for e in expenses:
        b = getattr(e, "bag", None)
        if b is not None:
            bags[str(b.id)] = b
    concert_ids = [b.linked_id for b in bags.values()
                   if (b.linked_type or "").upper() == "CONCERT" and b.linked_id]
    promo_ids = [b.linked_id for b in bags.values()
                 if (b.linked_type or "").upper() == "PROMOTION" and b.linked_id]
    if concert_ids:
        for c in (session_db.query(Concert)
                  .options(joinedload(Concert.venue), joinedload(Concert.artist))
                  .filter(Concert.id.in_(concert_ids)).all()):
            datos["concerts"][str(c.id)] = c
    if promo_ids:
        for p in session_db.query(Promotion).filter(Promotion.id.in_(promo_ids)).all():
            datos["promotions"][str(p.id)] = p
    # Facturas imputadas al gasto (de ahí salen los importes reales y el archivo que se adjunta).
    filas = (session_db.query(BagExpenseInvoice)
             .filter(BagExpenseInvoice.bag_expense_id.in_(ids))
             .order_by(BagExpenseInvoice.created_at.desc()).all())
    sup_ids = [r.supplier_invoice_id for r in filas if getattr(r, "supplier_invoice_id", None)]
    sups = {}
    if sup_ids:
        sups = {str(s.id): s for s in session_db.query(SupplierInvoice)
                .filter(SupplierInvoice.id.in_(sup_ids)).all()}
    pers_ids = [r.personal_expense_id for r in filas if getattr(r, "personal_expense_id", None)]
    for r in filas:
        clave = str(r.bag_expense_id)
        datos["files"].setdefault(clave, {"url": (r.file_url or ""), "name": (r.file_name or "")})
        if getattr(r, "supplier_invoice_id", None) and clave not in datos["invoices"]:
            inv = sups.get(str(r.supplier_invoice_id))
            if inv is not None:
                datos["invoices"][clave] = inv
    for s in (session_db.query(SupplierInvoice)
              .filter(SupplierInvoice.bag_expense_id.in_(ids)).all()):
        datos["invoices"].setdefault(str(s.bag_expense_id), s)
    # De quién era la tarjeta (Pleo/Cabify): para la nota de «cómo se pagó».
    personales = (session_db.query(PersonalExpense)
                  .filter(or_(PersonalExpense.bag_expense_id.in_(ids),
                              PersonalExpense.id.in_(pers_ids or [uuid.uuid4()]))).all())
    nicks = {}
    if personales:
        uids = [p.user_id for p in personales if p.user_id]
        if uids:
            nicks = {str(uid): (nick or "") for uid, nick in
                     session_db.query(UserProfile.user_id, UserProfile.nick)
                     .filter(UserProfile.user_id.in_(uids)).all()}
    por_personal = {str(p.id): p for p in personales}
    for p in personales:
        if p.bag_expense_id:
            datos["payers"][str(p.bag_expense_id)] = nicks.get(str(p.user_id), "")
    for r in filas:
        if getattr(r, "personal_expense_id", None) and str(r.bag_expense_id) not in datos["payers"]:
            p = por_personal.get(str(r.personal_expense_id))
            if p is not None:
                datos["payers"][str(r.bag_expense_id)] = nicks.get(str(p.user_id), "")
    batch_ids = [e.payment_batch_id for e in expenses if getattr(e, "payment_batch_id", None)]
    if batch_ids:
        for b in (session_db.query(PaymentBatch).options(joinedload(PaymentBatch.bank))
                  .filter(PaymentBatch.id.in_(batch_ids)).all()):
            datos["batches"][str(b.id)] = b
    comp_ids = [b.company_id for b in bags.values() if getattr(b, "company_id", None)]
    if comp_ids:
        for c in session_db.query(GroupCompany).filter(GroupCompany.id.in_(comp_ids)).all():
            datos["companies"][str(c.id)] = c
        # Qué empresas tienen cuenta de Holded activa (para avisar antes de intentar subir).
        for acc in (session_db.query(HoldedAccount)
                    .filter(HoldedAccount.group_company_id.in_(comp_ids)).all()):
            comp = datos["companies"].get(str(acc.group_company_id))
            if comp is not None:
                setattr(comp, "_holded_ready", bool(acc.is_active and (acc.api_key or "").strip()))
    # Artistas de la bolsa (el primero es el que se enseña con su foto).
    art_ids = []
    for b in bags.values():
        if getattr(b, "artist_id", None):
            art_ids.append(b.artist_id)
        for raw in (getattr(b, "artist_ids", None) or []):
            aid = to_uuid(str(raw))
            if aid:
                art_ids.append(aid)
    if art_ids:
        for a in session_db.query(Artist).filter(Artist.id.in_(art_ids)).all():
            datos["artists"][str(a.id)] = a
    return datos


def _money_edit_text(valor) -> str:
    """Un importe GUARDADO, tal como se escribe en España («1.234,56»), o VACÍO si no hay dato.

    ⚠️ **Un 0 sale vacío**, que es la convención de la casa en los formularios de importes
    (`_invoice_amount_fields_from_form` guarda el 0 como NULL: «no lo sé» no es «cero»). En un ticket
    la base y el IVA están a 0 porque no se desglosan, y enseñarlos como «0,00» hacía que un Guardar
    sin tocar nada AFIRMARA que la base es cero.
    """
    if valor is None:
        return ""
    try:
        dec = Decimal(valor)
    except (InvalidOperation, TypeError, ValueError):
        return ""
    if not dec.is_finite() or dec == 0:
        return ""
    return "{:,.2f}".format(dec).replace(",", "@").replace(".", ",").replace("@", ".")


def _accounting_stored_amounts(expense, invoice=None) -> dict:
    """Los importes de un gasto TAL COMO ESTÁN GUARDADOS (para rellenar el pop-up de editar).

    CAMPO A CAMPO: manda la FACTURA (es lo que se ve en la tabla y donde se escribe) y, si ese dato
    no está guardado ahí, el del GASTO. Lo que no está en ninguno de los dos sale VACÍO: en un ticket
    no hay base ni IVA, y rellenarlos con los números deducidos hacía que un Guardar sin tocar nada
    los diera por buenos.
    ⚠️ El IVA se llama `amount_tax` en el gasto y `amount_vat` en la factura.
    """
    def _dato(campo_factura: str, campo_gasto: str) -> str:
        # CAMPO A CAMPO: manda la factura (es lo que se ve en la tabla) y, si ESE dato no está
        # guardado ahí, el del gasto. Así el pop-up no sale vacío por una factura a la que solo le
        # falta el desglose, y sigue sin inventarse nada: los dos son datos guardados.
        texto = _money_edit_text(getattr(invoice, campo_factura, None)) if invoice is not None else ""
        return texto or _money_edit_text(getattr(expense, campo_gasto, None))

    return {"net": _dato("amount_net", "amount_net"),
            "vat": _dato("amount_vat", "amount_tax"),
            "retention": _dato("retention_amount", "retention_amount"),
            "total": _dato("amount_gross", "amount_gross")}


def _accounting_expense_row(session_db, expense, datos: dict) -> dict:
    """Una línea de contabilidad, con TODO lo que se ve en pantalla."""
    bag = getattr(expense, "bag", None)
    concert = promotion = None
    if bag is not None and bag.linked_id:
        tipo_enlace = (bag.linked_type or "").upper()
        if tipo_enlace == "CONCERT":
            concert = datos["concerts"].get(str(bag.linked_id))
        elif tipo_enlace == "PROMOTION":
            promotion = datos["promotions"].get(str(bag.linked_id))
    invoice = datos["invoices"].get(str(expense.id))
    importes = _accounting_amounts(session_db, expense, invoice=invoice)
    proveedor = _accounting_provider_info(session_db, expense)
    doc_label, doc_icon, doc_badge = _accounting_doc_meta(expense.document_type)
    estado_label, estado_badge, estado_icon = _accounting_status_meta(expense.accounting_status)
    archivo = datos["files"].get(str(expense.id)) or {}
    doc_url = (getattr(expense, "attachment_url", None) or archivo.get("url") or
               (getattr(invoice, "file_url", None) or "")).strip()
    doc_name = (getattr(expense, "attachment_name", None) or archivo.get("name") or
                (getattr(invoice, "original_name", None) or "") or "Documento")
    # Artista de la bolsa: el suyo o el primero de la lista.
    artista = None
    if bag is not None:
        if getattr(bag, "artist", None) is not None:
            artista = bag.artist
        elif getattr(bag, "artist_id", None):
            artista = datos["artists"].get(str(bag.artist_id))
        if artista is None:
            for raw in (getattr(bag, "artist_ids", None) or []):
                artista = datos["artists"].get(str(raw))
                if artista is not None:
                    break
    if artista is None and concert is not None:
        artista = getattr(concert, "artist", None)
    numero = ((getattr(expense, "invoice_number", None) or "").strip()
              or (getattr(invoice, "invoice_number", None) or "").strip())
    emision = getattr(expense, "issue_date", None) or getattr(invoice, "issue_date", None)
    # ⚠️⚠️ LO QUE SE EDITA SON LOS IMPORTES GUARDADOS, NO LOS DEDUCIDOS. En la tabla se ENSEÑAN
    # importes calculados (en un ticket, base = total e IVA = 0; en una factura sin base, la base
    # despejada), y rellenar el pop-up con ESO y darle a Guardar los escribía como si alguien los
    # hubiera leído del documento —y una retención «0» donde no había nada cambia lo que se paga en
    # la remesa (`_expense_retention` distingue el 0 del NULL)—. Un hueco vacío es «no lo sé», y
    # `_invoice_apply_manual_data` no toca lo que llega vacío.
    _edit = _accounting_stored_amounts(expense, invoice)
    company = datos["companies"].get(str(getattr(bag, "company_id", "") or "")) if bag is not None else None
    batch = datos["batches"].get(str(getattr(expense, "payment_batch_id", "") or ""))
    pagado_label = BAG_PAYMENT_STATUS_LABELS.get((expense.payment_status or "NO_PAGADO").upper(),
                                                 expense.payment_status or "")
    pago_badge = {"PAGADO": "text-bg-success", "PARCIAL": "text-bg-warning text-dark",
                  "PENDIENTE": "text-bg-warning text-dark"}.get(
        (expense.payment_status or "NO_PAGADO").upper(), "text-bg-secondary")
    metodo = (getattr(expense, "payment_method", None) or "").strip()
    pagador = datos["payers"].get(str(expense.id)) or ""
    if metodo and pagador:
        metodo_label = "%s · %s" % (metodo, pagador)
    else:
        metodo_label = metodo or ("Remesa %s" % batch.reference if batch is not None else "")
    return {
        "id": str(expense.id),
        "concept": (getattr(expense, "concept", None) or "Sin concepto").strip(),
        "document_type": (expense.document_type or "FACTURA").upper(),
        "doc_label": doc_label, "doc_icon": doc_icon, "doc_badge": doc_badge,
        "provider_name": (proveedor["name"] or "Sin proveedor"),
        "provider_tax_id": proveedor["tax_id"],
        "invoice_number": numero,
        "issue_date": (emision.strftime("%d/%m/%Y") if emision else ""),
        "payment_status": (expense.payment_status or "NO_PAGADO").upper(),
        "payment_label": pagado_label, "payment_badge": pago_badge,
        "payment_method": metodo_label,
        "batch_reference": (batch.reference if batch is not None else ""),
        "batch_url": (url_for("payment_batch_detail", batch_id=batch.id) if batch is not None else ""),
        "artist_name": (getattr(artista, "name", None) or ""),
        "artist_photo": (getattr(artista, "photo_url", None) or ""),
        "artist_id": (str(artista.id) if artista is not None else ""),
        "bag_id": (str(bag.id) if bag is not None else ""),
        "bag_label": _accounting_bag_label(session_db, bag, concert=concert, promotion=promotion),
        "bag_url": (url_for("bag_detail_view", bag_id=bag.id) if bag is not None else ""),
        "company_name": (getattr(company, "name", None) or ""),
        "company_id": (str(company.id) if company is not None else ""),
        "company_logo": (getattr(company, "logo_url", None) or ""),
        "holded_ready": bool(getattr(company, "_holded_ready", False)),
        "net": importes["net"], "vat": importes["vat"], "vat_pct": importes["vat_pct"],
        "retention": importes["retention"], "retention_pct": importes["retention_pct"],
        "total": importes["total"], "breakdown": importes["breakdown"],
        # Para el pop-up de editar: lo GUARDADO (vacío si no hay dato), no lo deducido.
        "edit_net": _edit["net"], "edit_vat": _edit["vat"],
        "edit_retention": _edit["retention"], "edit_total": _edit["total"],
        "accounting_status": (expense.accounting_status or "PENDIENTE").upper(),
        "status_label": estado_label, "status_badge": estado_badge, "status_icon": estado_icon,
        "accounting_at": (expense.accounting_at.strftime("%d/%m/%Y %H:%M")
                          if getattr(expense, "accounting_at", None) else ""),
        "accounting_by": (getattr(expense, "accounting_by_nick", None) or ""),
        "accounting_note": (getattr(expense, "accounting_note", None) or ""),
        "doc_url": doc_url, "doc_name": doc_name,
        # La FACTURA (si la hay): desde los tres puntitos se pueden corregir sus datos en la pantalla
        # partida de siempre (la factura a la izquierda y sus campos a la derecha).
        "invoice_id": (str(invoice.id) if invoice is not None else ""),
        "holded_doc_id": (getattr(expense, "holded_doc_id", None) or ""),
        "holded_doc_number": (getattr(expense, "holded_doc_number", None) or ""),
        "holded_uploaded_at": (expense.holded_uploaded_at.strftime("%d/%m/%Y %H:%M")
                               if getattr(expense, "holded_uploaded_at", None) else ""),
        "holded_error": (getattr(expense, "holded_error", None) or ""),
        "holded_warning": (getattr(expense, "holded_warning", None) or ""),
        "category_label": BAG_EXPENSE_CATEGORY_LABELS.get(
            _bag_expense_display_cat(expense.category), ""),
    }


def _accounting_expense_rows(session_db, expenses) -> list[dict]:
    datos = _accounting_prefetch(session_db, expenses)
    return [_accounting_expense_row(session_db, e, datos) for e in expenses]


def _accounting_bag_groups(session_db, *, limit: int = 400, only_done: bool = False,
                           company_ids=None) -> list[dict]:
    """Bolsas agrupadas para la subpestaña «Bolsas».

    Por defecto, las que tienen gastos PENDIENTES de contabilizar: una bolsa con todos sus gastos
    contabilizados u omitidos no sale (se cierra para contabilidad, `accounting_done_at`).
    Con `only_done` es al revés — las bolsas de lo YA contabilizado, para que la pestaña
    «Contabilizado» se lea igual que «Pendiente».
    """
    expenses = (_accounting_base_query(session_db, only_done=only_done, company_ids=company_ids)
                .order_by(BagExpense.created_at.desc()).limit(2000).all())
    if not expenses:
        return []
    datos = _accounting_prefetch(session_db, expenses)
    grupos = {}
    bolsas = {}
    for e in expenses:
        bag = getattr(e, "bag", None)
        if bag is None:
            continue
        clave = str(bag.id)
        bolsas[clave] = bag
        grupo = grupos.get(clave)
        if grupo is None:
            concert = promotion = None
            if bag.linked_id:
                tipo_enlace = (bag.linked_type or "").upper()
                concert = datos["concerts"].get(str(bag.linked_id)) if tipo_enlace == "CONCERT" else None
                promotion = datos["promotions"].get(str(bag.linked_id)) if tipo_enlace == "PROMOTION" else None
            company = datos["companies"].get(str(getattr(bag, "company_id", "") or ""))
            artista = (getattr(bag, "artist", None)
                       or datos["artists"].get(str(getattr(bag, "artist_id", "") or "")))
            if artista is None:
                for raw in (getattr(bag, "artist_ids", None) or []):
                    artista = datos["artists"].get(str(raw))
                    if artista is not None:
                        break
            fecha = (getattr(concert, "date", None) if concert is not None else None) or bag.start_date
            grupo = grupos[clave] = {
                "bag_id": clave,
                "title": _accounting_bag_label(session_db, bag, concert=concert, promotion=promotion),
                "url": url_for("bag_detail_view", bag_id=bag.id),
                "artist_name": (getattr(artista, "name", None) or ""),
                "artist_photo": (getattr(artista, "photo_url", None) or ""),
                "artist_id": (str(artista.id) if artista is not None else ""),
                "company_name": (getattr(company, "name", None) or ""),
                "holded_ready": bool(getattr(company, "_holded_ready", False)),
                "venue": ((getattr(getattr(concert, "venue", None), "name", None) or "")
                          if concert is not None else ""),
                "municipality": ((getattr(getattr(concert, "venue", None), "municipality", None)
                                  or getattr(concert, "manual_municipality", None) or "")
                                 if concert is not None else ""),
                "date": (fecha.strftime("%d/%m/%Y") if fecha else ""),
                "activity_type": (_activity_kind_label(getattr(concert, "activity_type", None))
                                  if concert is not None else
                                  ("Promoción" if promotion is not None else "")),
                "kind": (getattr(bag, "bag_type", None) or "GENERAL").upper(),
                "rows": [],
                "total": Decimal("0"),
                "tag": _accounting_bag_tag(session_db, bag),
            }
        fila = _accounting_expense_row(session_db, e, datos)
        grupo["rows"].append(fila)
        grupo["total"] += _money_or_zero(fila["total"])
    # AUTOCURADO: una bolsa que estaba cerrada para contabilidad y a la que le ha entrado un gasto
    # nuevo vuelve a tener trabajo, así que su «cerrada el …» ya no es verdad. Se limpia aquí (es
    # donde se sabe) en vez de dejar una fecha que engaña.
    reabiertas = ([] if only_done else
                  [bolsas[g["bag_id"]] for g in grupos.values()
                   if getattr(bolsas.get(g["bag_id"]), "accounting_done_at", None)])
    if reabiertas:
        try:
            for b in reabiertas:
                b.accounting_done_at = None
                b.updated_at = _now_madrid()
            session_db.commit()
        except Exception:
            session_db.rollback()
    salida = sorted(grupos.values(), key=lambda g: (g["artist_name"] or "").casefold())
    return salida[:limit]


def _accounting_expenses_from_request(session_db, form) -> list:
    """Los gastos sobre los que actúa una acción en bloque.

    ⚠️ El ÁMBITO manda sobre lo marcado: «Subir todo» va en el `value` del propio botón, así que si
    alguien tiene tres gastos marcados y pulsa «Subir todo», sube todo (que es lo que ha pedido).
    """
    ambito = (form.get("scope") or "").strip().lower()
    # ⚠️ «Subir todo» se ceñe a lo que se está VIENDO: si la pantalla está filtrada por las empresas
    # de esta persona, no se le suben a Holded los documentos de las demás.
    empresas = _accounting_company_scope_from_form(form)
    if ambito in ACCOUNTING_SUBTAB_DOC:
        return _accounting_base_query(session_db, doc_types=[ACCOUNTING_SUBTAB_DOC[ambito]],
                                      company_ids=empresas).all()
    if ambito == "todo":
        return _accounting_base_query(session_db, company_ids=empresas).all()
    bag_id = to_uuid(form.get("bag_id") or "")
    if bag_id:
        return _accounting_base_query(session_db).filter(BagExpense.bag_id == bag_id).all()
    ids = [to_uuid(x) for x in form.getlist("expense_ids") if to_uuid(x)]
    if ids:
        return (_accounting_base_query(session_db, include_done=True)
                .filter(BagExpense.id.in_(ids)).all())
    return []


def _accounting_company_scope_from_form(form) -> list[str]:
    """El reparto por empresas que tenía la pantalla desde la que se ha pulsado la acción.

    El formulario lleva `empresas=todas` cuando se está viendo el de todas las empresas; si no, la
    acción se limita a las de quien la pulsa (que es lo que tenía delante).
    ⚠️ Y si se ha pinchado UNA empresa en el filtro (`empresa`), manda esa: «Subir todo» no puede
    tocar lo de otra empresa que no se está viendo."""
    try:
        una = (form.get("empresa") or "").strip()
        if una and to_uuid(una):
            return [una]
        if (form.get("empresas") or "").strip().lower() == "todas":
            return []
    except Exception:
        return []
    return _accounting_company_scope()


def _accounting_royalties_from_request(session_db, form) -> list:
    """Las LIQUIDACIONES DE ROYALTIES sobre las que actúa una acción en bloque.

    Mismo criterio que con los gastos (el ÁMBITO manda sobre lo marcado): una liquidación es una
    factura más de la subpestaña «Facturas», así que «Subir todo» desde ahí también las incluye.
    Una bolsa no tiene liquidaciones, así que con `bag_id` no entra ninguna."""
    ambito = (form.get("scope") or "").strip().lower()
    if ambito in ("facturas", "todo"):
        return _royalty_accounting_pending(session_db,
                                           company_ids=_accounting_company_scope_from_form(form))
    if (form.get("bag_id") or "").strip():
        return []
    ids = [to_uuid(x) for x in form.getlist("royalty_ids") if to_uuid(x)]
    if not ids:
        return []
    try:
        return (session_db.query(RoyaltyLiquidation)
                .filter(RoyaltyLiquidation.id.in_(ids)).all())
    except Exception:
        return []


def _accounting_upload_many(session_db, expenses, *, nick: str, royalties=None) -> dict:
    """Sube varios gastos (y liquidaciones de royalties) a Holded.

    Cada uno en su savepoint: si uno falla, los demás siguen."""
    salida = {"ok": 0, "fail": 0, "warnings": 0, "skipped": 0, "pending": 0, "errors": []}
    # ⚠️ Cada gasto son VARIAS llamadas a Holded (contacto, documento, adjunto, relectura). «Subir
    # todo» con cientos de gastos se pasa del tiempo que el servidor da a una petición y se corta a
    # medias. Se sube durante un rato y se dice cuántos quedan: al volver a pulsar siguen los que
    # faltan (lo ya subido se salta solo por `holded_doc_id`).
    _t0, _presupuesto = time.monotonic(), 45.0
    for _i, expense in enumerate(expenses):
        if time.monotonic() - _t0 > _presupuesto:
            salida["pending"] = len(expenses) - _i
            break
        if _i and _i % 5 == 0:
            session_db.commit()
        if (expense.accounting_status or "PENDIENTE").upper() in ACCOUNTING_DONE_STATUSES:
            salida["skipped"] += 1
            continue
        if (expense.holded_doc_id or "").strip():
            # Ya está en Holded: no se sube dos veces (se duplicaría el documento).
            salida["skipped"] += 1
            salida["already"] = salida.get("already", 0) + 1
            continue
        try:
            with session_db.begin_nested():
                res = _holded_upload_expense(session_db, expense, nick=nick)
            if res["ok"]:
                salida["ok"] += 1
                if res.get("warning"):
                    salida["warnings"] += 1
                    salida["errors"].append("%s: %s" % (
                        (expense.concept or "Gasto")[:40], res["warning"]))
            else:
                salida["fail"] += 1
                salida["errors"].append("%s: %s" % ((expense.concept or "Gasto")[:40], res["message"]))
        except Exception as exc:
            salida["fail"] += 1
            salida["errors"].append("%s: %s" % ((expense.concept or "Gasto")[:40], str(exc)[:200]))
    # LIQUIDACIONES DE ROYALTIES: son facturas como las demás y comparten el mismo presupuesto de
    # tiempo, así que si se agota se dice cuántas quedan (al volver a pulsar siguen las que faltan).
    pendientes = list(royalties or [])
    for _j, rec in enumerate(pendientes):
        if time.monotonic() - _t0 > _presupuesto:
            salida["pending"] += len(pendientes) - _j
            break
        if getattr(rec, "accounted_at", None) or (getattr(rec, "holded_doc_id", None) or "").strip():
            salida["skipped"] += 1
            continue
        etiqueta = "Royalties %s" % _royalty_liquidation_period_label_from_dates(
            rec.period_start, rec.period_end)
        try:
            with session_db.begin_nested():
                res = _holded_upload_royalty(session_db, rec, nick=nick)
            if res["ok"]:
                salida["ok"] += 1
                if res.get("warning"):
                    salida["warnings"] += 1
                    salida["errors"].append("%s: %s" % (etiqueta, res["warning"]))
            else:
                salida["fail"] += 1
                salida["errors"].append("%s: %s" % (etiqueta, res["message"]))
        except Exception as exc:
            salida["fail"] += 1
            salida["errors"].append("%s: %s" % (etiqueta, str(exc)[:200]))
    session_db.commit()
    return salida


def _accounting_flash_result(res: dict, *, total: int) -> None:
    """Un solo aviso con lo que ha pasado: lo que ha entrado, lo que no y por qué."""
    saltados = int(res.get("skipped") or 0)
    if not total:
        flash("No había nada que subir.", "info")
        return
    if res["ok"] and not res["fail"]:
        flash("%d documento(s) subido(s) a Holded." % res["ok"], "success")
    elif res["ok"]:
        flash("%d subido(s) y %d con problemas." % (res["ok"], res["fail"]), "warning")
    elif res["fail"]:
        flash("No se ha podido subir nada a Holded.", "danger")
    elif saltados:
        # ⚠️ Ni un fallo: estaban YA en Holded (o contabilizados). Decir «no se ha podido» sería
        # mentir y dar un susto.
        flash("Ya estaba todo en Holded: %d documento(s) sin cambios." % saltados, "info")
    else:
        flash("No había nada que subir.", "info")
    if saltados and (res["ok"] or res["fail"]):
        flash("%d documento(s) ya estaban en Holded y no se han vuelto a subir." % saltados, "info")
    if int(res.get("pending") or 0):
        flash("Quedan %d por subir: se ha parado para no agotar el tiempo del servidor. Vuelve a "
              "pulsar «Subir todo a Holded» para seguir con esos." % int(res["pending"]), "info")
    for detalle in res["errors"][:8]:
        flash(detalle, "warning")
    if len(res["errors"]) > 8:
        flash("… y %d aviso(s) más (los verás en cada gasto)." % (len(res["errors"]) - 8), "info")


@app.post("/contabilidad/gastos/<expense_id>/holded", endpoint="accounting_expense_upload")
@admin_required
def accounting_expense_upload(expense_id):
    """Sube UN gasto a Holded."""
    if not can_edit_accounting():
        return forbid("No tienes permisos para contabilizar.")
    session_db = db()
    try:
        expense = session_db.get(BagExpense, to_uuid(expense_id) or uuid.uuid4())
        if expense is None:
            flash("Gasto no encontrado.", "warning")
            return redirect(safe_next_or(url_for("contabilidad_view")))
        if (expense.holded_doc_id or "").strip():
            # ⚠️ No se sube dos veces: en Holded quedaría un documento DUPLICADO.
            flash("Esta factura YA está subida a Holded (documento %s)%s: no se sube otra vez para "
                  "que no se duplique."
                  % ((expense.holded_doc_number or expense.holded_doc_id),
                     (" el %s" % expense.holded_uploaded_at.strftime("%d/%m/%Y %H:%M"))
                     if getattr(expense, "holded_uploaded_at", None) else ""), "danger")
            return redirect(safe_next_or(url_for("contabilidad_view")))
        res = _holded_upload_expense(session_db, expense, nick=((_current_user_state() or {}).get("nick") or ""))
        session_db.commit()
        if res["ok"]:
            flash(res["message"], "success")
            if res.get("warning"):
                flash(res["warning"], "warning")
        else:
            flash("No se ha subido a Holded: %s" % res["message"], "danger")
    except Exception as exc:
        session_db.rollback()
        flash("No se ha podido subir a Holded: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("contabilidad_view")))


