def _invoice_apply_manual_data(inv, form, *, concept_field: str = "concept") -> None:
    """Aplica a una FACTURA los datos escritos a mano (nº, fecha, concepto e importes).

    Punto ÚNICO de «corregir los datos de una factura» desde contabilidad: lo usan el gasto (que
    además escribe los suyos) y la liquidación de royalties, así que las dos se corrigen igual y con
    los MISMOS nombres de campo.
    ⚠️ Los PORCENTAJES se recalculan del importe corregido y se ajustan al tipo REAL (`_tax_pct_snap`):
    si no, se quedan diciendo el % de los números viejos —o un 20,99% por redondeo—.
    """
    if inv is None:
        return
    # ⚠️ El nº y la fecha SÍ se pueden vaciar (el gasto ya lo hacía y, si la factura los conservara,
    # la tabla los volvería a enseñar y parecería que no se ha guardado). Solo se tocan si el campo
    # venía en el formulario: así un formulario que no los traiga no borra nada.
    if form.get("invoice_number") is not None:
        inv.invoice_number = (form.get("invoice_number") or "").strip() or None
    fecha = parse_optional_date(form.get("issue_date"))
    if form.get("issue_date") is not None:
        inv.issue_date = fecha
    concepto = (form.get(concept_field) or "").strip()
    if concepto:
        inv.concept_text = concepto[:500]
    for campo, clave in (("amount_net", "amount_net"), ("amount_vat", "amount_tax"),
                         ("amount_gross", "amount_gross"), ("retention_amount", "retention_amount")):
        crudo = (form.get(clave) or "").strip()
        if crudo != "":
            setattr(inv, campo, _parse_money_decimal(crudo))
    base = _money_or_zero(inv.amount_net)
    if base > 0:
        if _money_or_zero(inv.amount_vat) > 0:
            inv.vat_pct = float(_tax_pct_snap(
                (_money_or_zero(inv.amount_vat) / base * Decimal("100")).quantize(Decimal("0.01")),
                VAT_RATES))
        if _money_or_zero(inv.retention_amount) > 0:
            inv.retention_pct = float(_tax_pct_snap(
                (_money_or_zero(inv.retention_amount) / base * Decimal("100")).quantize(Decimal("0.01")),
                RETENTION_RATES))


@app.post("/contabilidad/royalties/<liq_id>/factura", endpoint="accounting_royalty_invoice_edit")
@admin_required
def accounting_royalty_invoice_edit(liq_id):
    """Corrige los datos de la FACTURA de una liquidación de royalties desde contabilidad.

    Una liquidación ES una factura, así que se edita con el MISMO formulario que un gasto; lo que no
    tiene es un `BagExpense` que mantener al día, solo su `SupplierInvoice`."""
    if not can_edit_accounting():
        return forbid("No tienes permisos para contabilizar.")
    session_db = db()
    try:
        rec = session_db.get(RoyaltyLiquidation, to_uuid(liq_id) or uuid.uuid4())
        if rec is None:
            flash("Liquidación no encontrada.", "warning")
            return redirect(safe_next_or(url_for("contabilidad_view")))
        inv = (session_db.get(SupplierInvoice, rec.invoice_id)
               if getattr(rec, "invoice_id", None) else None)
        if inv is None:
            flash("Esta liquidación todavía no tiene factura subida: no hay datos que corregir.", "warning")
            return redirect(safe_next_or(url_for("contabilidad_view")))
        _invoice_apply_manual_data(inv, request.form)
        session_db.add(inv)
        rec.updated_at = _now_madrid()
        session_db.commit()
        flash("Datos de la factura actualizados.", "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudieron guardar los datos: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("contabilidad_view")))


@app.post("/contabilidad/gastos/<expense_id>/editar", endpoint="accounting_expense_edit")
@admin_required
def accounting_expense_edit(expense_id):
    """Corrige los datos contables de un gasto antes de subirlo (nº, fecha, concepto e importes)."""
    if not can_edit_accounting():
        return forbid("No tienes permisos para contabilizar.")
    session_db = db()
    try:
        expense = session_db.get(BagExpense, to_uuid(expense_id) or uuid.uuid4())
        if expense is None:
            flash("Gasto no encontrado.", "warning")
            return redirect(safe_next_or(url_for("contabilidad_view")))
        form = request.form
        if (form.get("concept") or "").strip():
            expense.concept = (form.get("concept") or "").strip()[:300]
        expense.invoice_number = (form.get("invoice_number") or "").strip() or None
        fecha = parse_optional_date(form.get("issue_date"))
        if fecha or not (form.get("issue_date") or "").strip():
            expense.issue_date = fecha
        for campo, clave in (("amount_net", "amount_net"), ("amount_tax", "amount_tax"),
                             ("amount_gross", "amount_gross"),
                             ("retention_amount", "retention_amount")):
            crudo = (form.get(clave) or "").strip()
            if crudo != "":
                setattr(expense, campo, _parse_money_decimal(crudo))
        expense.updated_at = _now_madrid()
        # ⚠️⚠️ Y LO MISMO EN SU FACTURA: en la tabla de contabilidad manda lo que dice la FACTURA
        # (`_accounting_amounts`), así que corregir solo el gasto no cambiaba nada de lo que se ve y
        # parecía que no se había guardado. Se corrigen las dos cosas, que es lo que se está mirando.
        inv = _accounting_expense_invoice(session_db, expense)
        tocadas = 0
        if inv is not None:
            _invoice_apply_manual_data(inv, form)
            session_db.add(inv)
            tocadas = 1
        session_db.commit()
        flash("Datos actualizados%s." % (" (el gasto y su factura)" if tocadas else ""), "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudieron guardar los datos: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("contabilidad_view")))


@app.post("/contabilidad/holded/sincronizar", endpoint="accounting_holded_sync")
@admin_required
def accounting_holded_sync():
    """Pregunta a Holded qué documentos ya están contabilizados y pone al día las etiquetas."""
    if not can_edit_accounting():
        return forbid("No tienes permisos para contabilizar.")
    session_db = db()
    try:
        out = _holded_refresh_accounted(session_db)
        aviso = "Holded: %d documento(s) comprobados, %d ya contabilizados." % (
            out.get("checked", 0), out.get("accounted", 0))
        flash(aviso, "success" if not out.get("errors") else "warning")
        for detalle in (out.get("errors") or [])[:4]:
            flash(detalle, "warning")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo consultar Holded: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("contabilidad_view")))


@app.route("/contabilidad", endpoint="contabilidad_view")
@admin_required
def contabilidad_view():
    """CONTABILIDAD: lo que administración ha validado y todavía no está contabilizado.

    Pestañas servidas (?tab=): Pendiente de contabilizar · Contabilizado · Retenciones. Las dos
    primeras se leen IGUAL, con las mismas subpestañas (Facturas · Bolsas · Tickets · Sin ticket);
    solo la de pendiente lleva números.
    ⚠️ Ya no hay pestaña «Facturas»: el registro de facturas está en Bases de datos → Facturas y aquí
    solo repetía lo mismo. Un `?tab=facturas` de un enlace antiguo cae en «Pendiente».
    """
    # Cada pestaña tiene su PERMISO propio: solo se ofrecen (y se abren) las que se pueden ver, y sin
    # pestaña pedida se entra en la primera que sí. Quien tenga la sección entera las tiene todas.
    visibles = [k for k, _l, _i in ACCOUNTING_TABS if has_access_key("contabilidad.%s" % k)]
    tab = (request.args.get("tab") or "").strip().lower()
    if tab not in dict((k, l) for k, l, _i in ACCOUNTING_TABS):
        tab = visibles[0] if visibles else "pendiente"
    if visibles and tab not in visibles:
        return redirect(url_for("contabilidad_view", tab=visibles[0]))
    subtab = (request.args.get("subtab") or "facturas").strip().lower()
    if subtab not in dict((k, l) for k, l, _i in ACCOUNTING_PENDING_TABS):
        subtab = "facturas"
    estado_filtro = (request.args.get("estado") or "").strip().upper()
    # REPARTO POR EMPRESAS: lo PENDIENTE es solo de las empresas del grupo que lleva esta persona, con
    # la opción de ver el de TODAS (`?empresas=todas`). Lo ya contabilizado y las retenciones se ven
    # siempre completos: ahí no hay trabajo que repartir y hace falta poder buscar.
    mis_empresas = _accounting_company_scope()
    ver_todas = (request.args.get("empresas") or "").strip().lower() == "todas"
    scope = [] if (ver_todas or tab != "pendiente") else list(mis_empresas)
    # FILTRO por UNA empresa del grupo (la rejilla con logos, como la de artistas en discográfica).
    # Manda sobre el reparto: se pincha una y solo se ve lo suyo, en cualquier pestaña.
    empresa_filtro = (request.args.get("empresa") or "").strip()
    if empresa_filtro and to_uuid(empresa_filtro):
        scope = [empresa_filtro]
    session_db = db()
    try:
        # DETECCIÓN AUTOMÁTICA: si hay documentos subidos y hace rato que no se pregunta, se consulta
        # a Holded EN SEGUNDO PLANO y la etiqueta se pone al día sola (en la siguiente carga).
        if tab == "pendiente" and _holded_autodetect_due(session_db):
            threading.Thread(target=_holded_autodetect_bg, daemon=True).start()
        counts = _accounting_counts(session_db, company_ids=scope)
        # Los nombres de mis empresas (para decir en pantalla qué se está viendo).
        empresas_label = ""
        if mis_empresas:
            try:
                _ids = [to_uuid(str(x)) for x in mis_empresas if to_uuid(str(x))]
                empresas_label = " · ".join(
                    [c.name for c in session_db.query(GroupCompany)
                     .filter(GroupCompany.id.in_(_ids)).order_by(GroupCompany.name.asc()).all()])
            except Exception:
                empresas_label = ""
        rows, bag_groups, done_rows, royalty_done = [], [], [], []
        retenciones, retention_year = None, None
        if tab == "pendiente":
            if subtab == "bolsas":
                bag_groups = _accounting_bag_groups(session_db, company_ids=scope)
                if estado_filtro == ACCOUNTING_FILTER_NO_HOLDED:
                    for g in bag_groups:
                        g["rows"] = [r for r in g["rows"] if not r.get("holded_doc_id")]
                    bag_groups = [g for g in bag_groups if g["rows"]]
                elif estado_filtro in ACCOUNTING_STATUS_LABELS:
                    for g in bag_groups:
                        g["rows"] = [r for r in g["rows"] if r["accounting_status"] == estado_filtro]
                    bag_groups = [g for g in bag_groups if g["rows"]]
            else:
                q = _accounting_base_query(session_db, doc_types=[ACCOUNTING_SUBTAB_DOC[subtab]],
                                           company_ids=scope)
                if estado_filtro == ACCOUNTING_FILTER_NO_HOLDED:
                    # LO QUE TODAVÍA NO ESTÁ EN HOLDED: es el trabajo que queda por hacer aquí.
                    q = q.filter(func.coalesce(BagExpense.holded_doc_id, "") == "")
                elif estado_filtro in ACCOUNTING_STATUS_LABELS:
                    q = q.filter(func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE"))
                                 == estado_filtro)
                rows = _accounting_expense_rows(
                    session_db, q.order_by(BagExpense.issue_date.desc().nullslast(),
                                           BagExpense.created_at.desc()).limit(600).all())
        elif tab == "retenciones":
            try:
                _anyo = int(request.args.get("anio") or 0) or None
            except (TypeError, ValueError):
                _anyo = None
            retenciones = _accounting_retention_rows(session_db, year=_anyo)
            retention_year = _anyo
        else:
            # CONTABILIZADO se lee IGUAL que pendiente: las mismas subpestañas (facturas, bolsas,
            # tickets y sin ticket) con sus iconos, pero sin contadores — ahí no hay trabajo que
            # contar. Cada una enseña lo YA contabilizado (u omitido) de su tipo.
            if subtab == "bolsas":
                bag_groups = _accounting_bag_groups(session_db, only_done=True)
            else:
                done_rows = _accounting_expense_rows(
                    session_db, _accounting_base_query(session_db, only_done=True,
                                                       doc_types=[ACCOUNTING_SUBTAB_DOC[subtab]])
                    .order_by(BagExpense.accounting_at.desc().nullslast()).limit(400).all())
            # Las liquidaciones de royalties son facturas: van en la subpestaña de FACTURAS, en la
            # misma tabla (igual que en pendiente).
            if subtab == "facturas":
                royalty_done = _royalty_accounting_done_rows(session_db)
        # Liquidaciones de royalties pagadas y validadas: son pendiente de contabilizar y una
        # liquidación ES una factura, así que van EN la subpestaña de FACTURAS (ya no tienen módulo
        # aparte al final de la pantalla).
        royalty_pending = (_royalty_accounting_pending_rows(session_db, company_ids=scope)
                           if (tab == "pendiente" and subtab == "facturas") else [])
        if royalty_pending and estado_filtro == ACCOUNTING_FILTER_NO_HOLDED:
            royalty_pending = [r for r in royalty_pending if not r.get("holded_doc_id")]
        return render_template(
            "contabilidad.html",
            title="Contabilidad",
            subtitle="Lo que administración ha validado y todavía no está contabilizado.",
            tab=tab, subtab=subtab, estado_filtro=estado_filtro,
            accounting_tabs=[t for t in ACCOUNTING_TABS if t[0] in visibles] or ACCOUNTING_TABS,
            accounting_pending_tabs=ACCOUNTING_PENDING_TABS,
            accounting_states=HOLDED_ACCOUNTING_STATES,
            counts=counts,
            rows=rows, bag_groups=bag_groups, done_rows=done_rows,
            retenciones=retenciones, retention_year=retention_year,
            royalty_pending=royalty_pending,
            royalty_done=royalty_done,
            holded_ready=_holded_configured_any(session_db),
            # ⚠️ El estado de las CONEXIONES no se pinta aquí (esta pantalla es para contabilizar):
            # se ve y se arregla en Integraciones → Holded, que es donde se toca. Lo único que queda
            # en la fila es su botón de subir desactivado cuando esa empresa no tiene Holded.
            # EL FILTRO POR EMPRESA: todas con su logo y lo que tienen pendiente; al pinchar una, solo
            # se ve lo suyo.
            company_filters=_accounting_company_filters(session_db, scope=(
                [] if (ver_todas or tab != "pendiente") else list(mis_empresas))),
            company_filter=empresa_filtro,
            # Reparto por empresas: si esta persona tiene empresas asignadas se le enseña el filtro
            # («Mis empresas» / «Todas»). Sin reparto propio no se pinta nada: ya lo ve todo.
            my_companies=mis_empresas,
            my_companies_label=empresas_label,
            showing_all_companies=bool(ver_todas or not mis_empresas),
            CAN_EDIT=can_edit_accounting(),
        )
    finally:
        session_db.close()


@app.route("/personal", methods=["GET", "POST"], endpoint="personnel_view")
@admin_required
def personnel_view():
    session_db = db()
    try:
        if request.method == "POST":
            email = (request.form.get("email") or "").strip().lower()
            nick = (request.form.get("nick") or "").strip()
            first_name = (request.form.get("first_name") or "").strip()
            last_name = (request.form.get("last_name") or "").strip()
            # Nick por defecto = nombre oficial (útil al dar de alta desde un DNI/pasaporte).
            if not nick:
                nick = " ".join([x for x in (first_name, last_name) if x]).strip()
            if not email or not nick:
                flash("El email es obligatorio, y el nick (o el nombre del documento).", "danger")
                return redirect(url_for("personnel_view"))
            if session_db.query(User).filter(func.lower(User.email) == email).first():
                flash("Ya existe un usuario con ese email.", "danger")
                return redirect(url_for("personnel_view"))
            photo = request.files.get("photo")
            photo_url = upload_image(photo, "users") if (photo and getattr(photo, "filename", "")) else None
            temp_password = _generate_temporary_password()
            user = User(email=email, password_hash=generate_password_hash(temp_password), role=1)
            session_db.add(user)
            session_db.flush()
            profile = _ensure_user_profile(
                session_db,
                user,
                legacy_full_seed=False,
                nick=nick,
                photo_url=photo_url,
                first_name=first_name or None,
                last_name=last_name or None,
                dni=(request.form.get("dni") or "").strip() or None,
                birth_date=parse_optional_date(request.form.get("birth_date")),
                address=(request.form.get("address") or "").strip() or None,
                mobile_phones=_parse_phone_rows_from_form(request.form),
                departments=_normalize_departments(request.form.getlist("departments")),
                assigned_artist_ids=_normalize_assigned_artist_ids(request.form.getlist("assigned_artist_ids")),
            )
            _ensure_user_security(session_db, user)
            _sync_user_access_grants(session_db, user, profile)
            _person_document_create_from_intake(session_db, "USER", user)
            token = _make_password_token(user.id, purpose="welcome")
            ok, err = _send_optional_email(
                user.email,
                "Bienvenido al Back Office",
                _welcome_email_html(user, profile, token),
                text_body="Te hemos dado de alta en el Back Office. Revisa el enlace para crear tu contraseña.",
            )
            session_db.commit()
            if ok:
                flash("Usuario creado y correo de bienvenida enviado.", "success")
            else:
                flash(f"Usuario creado. No se pudo enviar el correo de bienvenida: {err}", "warning")
            return redirect(url_for("personnel_view"))

        users = (
            session_db.query(User, UserProfile, UserSecurity)
            .outerjoin(UserProfile, UserProfile.user_id == User.id)
            .outerjoin(UserSecurity, UserSecurity.user_id == User.id)
            .filter(or_(UserSecurity.is_deleted == False, UserSecurity.is_deleted.is_(None)))  # noqa: E712
            .order_by(func.lower(func.coalesce(UserProfile.nick, User.email)).asc())
            .all()
        )
        access_rows = _build_personnel_access_rows()
        artists = session_db.query(Artist).order_by(Artist.name.asc()).all()
        assigned_artist_map = {}
        for _user, profile, _security in users:
            ids = list(getattr(profile, "assigned_artist_ids", None) or []) if profile else []
            assigned_artist_map[str(_user.id)] = [str(x) for x in ids]
        return render_template("personnel.html", users=users, access_rows=access_rows, artists=artists,
                               assigned_artist_map=assigned_artist_map,
                               # Parada GENERAL del plazo de gastos (todo el personal, solo dirección).
                               expense_pause_all=_expense_pause_global(),
                               can_pause_expense_deadline=is_master())
    finally:
        session_db.close()


