# =========================================================
# Acciones + ficha de contratación consolidada + producción/admin
# =========================================================

def _parse_money(value):
    """Alias seguro para formularios nuevos que usan importes en formato ES/EN."""
    try:
        return _parse_money_decimal(value)
    except Exception:
        return Decimal("0")


def _json_loads_safe(value, default=None):
    if default is None:
        default = {}
    if value is None:
        return default
    if isinstance(value, (dict, list)):
        return value
    try:
        parsed = json.loads(value)
        return parsed if parsed is not None else default
    except Exception:
        return default


def _money_or_zero(value):
    try:
        return _parse_money_decimal(value)
    except Exception:
        return Decimal("0")


def _as_uuid_list(raw_values):
    values = []
    if raw_values is None:
        raw_values = []
    if isinstance(raw_values, str):
        raw_values = [raw_values]
    for raw in raw_values:
        if raw is None:
            continue
        for chunk in str(raw).replace(";", ",").split(","):
            chunk = chunk.strip()
            if not chunk:
                continue
            try:
                uid = to_uuid(chunk)
            except Exception:
                continue
            if uid not in values:
                values.append(uid)
    return values


def _concert_primary_artist_ids(concert):
    ids = []
    for raw in (getattr(concert, "artist_ids", None) or []):
        try:
            uid = to_uuid(raw)
        except Exception:
            continue
        if uid not in ids:
            ids.append(uid)
    if getattr(concert, "artist_id", None) and concert.artist_id not in ids:
        ids.insert(0, concert.artist_id)
    return ids


def _artists_from_ids(session_db, artist_ids):
    ids = _as_uuid_list(artist_ids)
    if not ids:
        return []
    rows = session_db.query(Artist).filter(Artist.id.in_(ids)).all()
    order = {str(uid): idx for idx, uid in enumerate(ids)}
    rows.sort(key=lambda row: order.get(str(row.id), 9999))
    return rows


def _artist_label_from_rows(rows):
    return ", ".join([row.name for row in rows if getattr(row, "name", None)]) or "Sin artista"


def _venue_label(venue, fallback=None):
    if venue:
        parts = [getattr(venue, "name", None), getattr(venue, "municipality", None), getattr(venue, "province", None)]
        return " · ".join([str(x).strip() for x in parts if str(x or "").strip()])
    return (fallback or "").strip()


def _concert_contracting_general_rows(session_db, concert):
    rows = []

    def add(label, value, kind="text"):
        if value in (None, "", [], {}):
            return
        rows.append({"label": label, "value": value, "kind": kind})

    artists = _artists_from_ids(session_db, _concert_primary_artist_ids(concert))
    add("Artista/s", _artist_label_from_rows(artists))
    add("Tipo de actividad", (getattr(concert, "activity_type", None) or getattr(concert, "sale_type", None) or "").replace("_", " ").title())
    add("Subtipo", getattr(concert, "activity_subtype", None))
    add("Estado", getattr(concert, "status", None))
    if getattr(concert, "date", None):
        add("Fecha", concert.date.strftime("%d/%m/%Y"))
    add("Festival / evento", getattr(concert, "festival_name", None))
    if getattr(concert, "billing_company", None):
        add("Empresa que factura", concert.billing_company.name)
    if getattr(concert, "promoter", None):
        add("Promotor", concert.promoter.nick)
    if getattr(concert, "promoter_company", None):
        add("Sociedad promotor", getattr(concert.promoter_company, "legal_name", None) or getattr(concert.promoter_company, "name", None))
    if getattr(concert, "show_time_tbc", False):
        add("Hora de actuación", "TBC")
    else:
        add("Hora de actuación", getattr(concert, "show_time", None))
    if getattr(concert, "doors_time_tbc", False):
        add("Apertura de puertas", "TBC")
    else:
        add("Apertura de puertas", getattr(concert, "doors_time", None))
    if getattr(concert, "sale_start_tbc", False):
        add("Salida a la venta", "TBC")
    elif getattr(concert, "sale_start_date", None):
        add("Salida a la venta", concert.sale_start_date.strftime("%d/%m/%Y"))
    if not getattr(concert, "no_capacity", False) and getattr(concert, "capacity", None):
        add("Aforo", str(concert.capacity))
    elif getattr(concert, "no_capacity", False):
        ticketing_probe = _json_loads_safe(getattr(concert, "ticketing_payload", None), {})
        free_mode = isinstance(ticketing_probe, dict) and (ticketing_probe.get("entry_mode") or "").upper() == "FREE"
        add("Aforo", "Aforo libre" if free_mode else "Sin aforo")

    # --- Datos estructurados del asistente (con etiqueta legible) ---
    contracting = _json_loads_safe(getattr(concert, "contracting_payload", None), {})
    contracting = contracting if isinstance(contracting, dict) else {}
    add("En qué consiste", contracting.get("description"))
    _mg = contracting.get("meet_greet") if isinstance(contracting.get("meet_greet"), dict) else {}
    if _mg.get("enabled"):
        _mg_txt = "Sí"
        if (_mg.get("quantity") or "").strip():
            _mg_txt += f" · {_mg.get('quantity')} personas"
        if (_mg.get("moment") or "").strip():
            _mg_txt += f" · {_mg.get('moment')}"
        add("Meet & Greet", _mg_txt)
    elif _mg:
        add("Meet & Greet", "No")
    performance = contracting.get("performance") if isinstance(contracting.get("performance"), dict) else {}
    if performance.get("sings") is True:
        add("¿El artista canta?", "Sí")
        if performance.get("songs_count"):
            add("Nº de canciones", str(performance.get("songs_count")))
        songs = [(x.get("title") or "").strip() for x in (performance.get("songs") or []) if isinstance(x, dict)]
        songs = [x for x in songs if x]
        if songs:
            add("Canciones", ", ".join(songs))
    elif performance.get("sings") is False:
        add("¿El artista canta?", "No")
    add("Formación", contracting.get("formation"))
    if getattr(concert, "do_not_announce", False):
        add("Anuncio", "No anunciar")
    elif getattr(concert, "announcement_date", None):
        add("Anuncio", concert.announcement_date.strftime("%d/%m/%Y"))
    if contracting.get("announcement_note"):
        add("Nota del anuncio", contracting.get("announcement_note"))

    ticketing = _json_loads_safe(getattr(concert, "ticketing_payload", None), {})
    ticketing = ticketing if isinstance(ticketing, dict) else {}
    entry_mode = (ticketing.get("entry_mode") or "").upper()
    if entry_mode == "FREE":
        add("Entrada", "Evento gratuito")
    elif entry_mode == "SALE":
        add("Entrada", "Venta de entradas")
    seller = ticketing.get("sale_seller") if isinstance(ticketing.get("sale_seller"), dict) else None
    seller_kind_labels = {"US": "Nosotros", "PROMOTER": "El promotor", "VENUE": "El recinto", "THIRD": "Un tercero"}
    if seller:
        kind_label = seller_kind_labels.get((seller.get("kind") or "").upper(), "")
        label_txt = (seller.get("label") or "").strip()
        add("Saca las entradas a la venta", f"{kind_label} · {label_txt}".strip(" ·") if label_txt else kind_label)
    elif ticketing.get("sale_owner"):
        add("Saca las entradas a la venta", ticketing.get("sale_owner"))
    tt_rows = [x for x in (ticketing.get("ticket_types") or []) if isinstance(x, dict)]
    if tt_rows:
        parts = []
        for x in tt_rows:
            piece = (x.get("name") or "Entrada").strip()
            try:
                price = float(x.get("price") or 0)
            except Exception:
                price = 0.0
            if price:
                piece += f" · {('%.2f' % price).replace('.', ',')} €"
            parts.append(piece)
        add("Tipos de entrada", " | ".join(parts))
    inv_mode = (ticketing.get("invitations_mode") or "").upper()
    if inv_mode == "TOTAL" and ticketing.get("invitations_total"):
        add("Invitaciones pactadas", f"{ticketing.get('invitations_total')} por contrato")
    elif inv_mode == "BY_TYPE":
        inv_parts = [f"{(x.get('name') or 'Entrada').strip()}: {int(x.get('invites_total') or 0)}" for x in tt_rows if int(x.get("invites_total") or 0)]
        if inv_parts:
            add("Invitaciones pactadas", " | ".join(inv_parts))

    pc_rows = _promoter_costs_rows(getattr(concert, "promoter_costs_payload", None))
    if pc_rows:
        add("Promotor cubre otros gastos", ", ".join(r["label"] for r in pc_rows))

    # --- Resto de claves de los payloads (volcado genérico, sin las ya mostradas) ---
    shown_keys = {
        ("Datos de contratación", "description"), ("Datos de contratación", "performance"),
        ("Datos de contratación", "formation"), ("Datos de contratación", "announcement_note"),
        ("Datos de contratación", "activity_type"), ("Datos de contratación", "activity_subtype"),
        ("Datos de contratación", "artist_ids"), ("Datos de contratación", "carteleria"),
        ("Datos de contratación", "billing_plan"), ("Datos de contratación", "meet_greet"),
        # Trazas internas de por dónde vino la actividad: no son un dato de la ficha.
        ("Datos de contratación", "simulation_id"), ("Datos de contratación", "simulation_activity_id"),
        ("Datos de contratación", "simulation_name"), ("Datos de contratación", "source"),
        ("Datos de contratación", "booking_request_id"), ("Datos de contratación", "enterticket_event_id"),
        ("Ticketing", "entry_mode"), ("Ticketing", "sale_seller"), ("Ticketing", "sale_owner"),
        ("Ticketing", "ticket_types"), ("Ticketing", "invitations_mode"), ("Ticketing", "invitations_total"),
        ("Ticketing", "free_capacity_unlimited"), ("Ticketing", "invitations"), ("Ticketing", "channels"),
        ("Ticketing", "total_capacity"), ("Ticketing", "sale_capacity"),
        ("Gastos cubiertos por promotor", "enabled"), ("Gastos cubiertos por promotor", "items"),
    }
    payloads = [
        ("Datos de contratación", getattr(concert, "contracting_payload", None)),
        ("Ticketing", getattr(concert, "ticketing_payload", None)),
        ("Equipamiento", getattr(concert, "equipment_payload", None)),
        ("Gastos cubiertos por promotor", getattr(concert, "promoter_costs_payload", None)),
        ("Producción", getattr(concert, "production_payload", None)),
    ]
    for prefix, payload in payloads:
        data = _json_loads_safe(payload, {})
        if not isinstance(data, dict):
            continue
        for key, value in data.items():
            if value in (None, "", [], {}):
                continue
            if (prefix, key) in shown_keys:
                continue
            label = str(key).replace("_", " ").strip().title()
            if isinstance(value, (list, dict)):
                value = json.dumps(value, ensure_ascii=False)
            add(f"{prefix} · {label}", value)
    return rows


def _concert_promoter_email_suggestions(session_db, concert):
    suggestions = []
    seen = set()

    def add(email, label):
        email = (email or "").strip()
        if not email or email.lower() in seen:
            return
        seen.add(email.lower())
        suggestions.append({"email": email, "label": label or email})

    promoter = getattr(concert, "promoter", None)
    if promoter:
        add(getattr(promoter, "email", None), getattr(promoter, "nick", None))
        add(getattr(promoter, "contact_email", None), getattr(promoter, "nick", None))
        add(getattr(promoter, "billing_email", None), f"{promoter.nick} · facturación")
        for contact in getattr(promoter, "contacts", []) or []:
            label = _contact_display_name(contact) or getattr(promoter, "nick", None)
            add(getattr(contact, "email", None), label)
    return suggestions


def _concert_build_calc_data(s, concert):
    """ADAPTADOR Concierto→sim_calc: traduce los datos económicos del concierto al dict que
    consume `sim_calc.compute`. Best-effort y conservador (para no inflar ingresos):
    - Ticketing: cada ConcertTicketType = una categoría (zona PISTA; qty_for_sale ya es a la venta).
    - Cachés (ConcertCache): FIXED/OTHER→fijo; VARIABLE→ por entrada (TICKETS) o % (REVENUE).
    - Comisionistas (ConcertZoneAgent): AMOUNT→fijo; PERCENT→ % (sobre beneficio si base=PROFIT).
    - Producción: ConcertBudgetItem (amount_net = neto).
    Retención 24% si el artista es internacional. Barras solo si el recinto las permite."""
    def _ff(v):
        try:
            return float(_sim_d(v))
        except Exception:
            return 0.0
    categories = []
    # CONCIERTO SINCRONIZADO CON ENTERTICKET: los ingresos brutos REALES mandan. La recaudación
    # total de ET (ventas válidas, sin invitaciones) es el INGRESO AL 100%: una categoría única
    # con las entradas vendidas y su precio medio real, para que ingresos@100% == recaudación
    # exacta (los % de aforo del cuadro escalan sobre la venta real).
    try:
        _et_ev = (s.query(EnterticketEvent)
                  .filter(EnterticketEvent.concert_id == concert.id)
                  .order_by(EnterticketEvent.last_synced_at.desc().nullslast())
                  .first())
        if _et_ev is not None:
            _et_rev = _et_money(_et_valid_sales_filter(s.query(func.sum(EnterticketSale.price)), _et_ev)
                                .filter(EnterticketSale.is_invitation.is_(False)).scalar())
            _et_sold = int(_et_valid_sales_filter(s.query(func.count()), _et_ev)
                           .filter(EnterticketSale.is_invitation.is_(False)).scalar() or 0)
            if _et_rev and _et_sold > 0:
                categories.append({"zone": "PISTA", "quantity": _et_sold, "invitations": 0,
                                   "price_net": float(_et_rev) / _et_sold, "extras": []})
    except Exception:
        pass
    if not categories:
        for t in sorted((getattr(concert, "ticket_types", None) or []), key=lambda x: (x.name or "")):
            categories.append({"zone": "PISTA", "quantity": int(_ff(t.qty_for_sale)), "invitations": 0,
                               "price_net": _ff(t.price), "extras": []})
    if not categories and concert.capacity and not concert.no_capacity:
        categories.append({"zone": "PISTA", "quantity": int(concert.capacity or 0), "invitations": 0, "price_net": 0.0, "extras": []})
    caches = []
    for c in (getattr(concert, "caches", None) or []):
        kind = (c.kind or "FIXED").upper()
        if kind == "VARIABLE":
            if (c.variable_basis or "REVENUE").upper() == "TICKETS":
                caches.append({"mode": "VARIABLE", "var_type": "PER_TICKET", "var_value": _ff(c.amount),
                               "includes_iva": (c.amount_base or "").upper() == "GROSS"})
            else:
                caches.append({"mode": "VARIABLE", "var_type": "PERCENT", "var_value": _ff(c.pct),
                               "includes_iva": (c.pct_base or "").upper() == "GROSS"})
        else:
            caches.append({"mode": "FIXED", "amount": _ff(c.amount), "includes_iva": (c.amount_base or "").upper() == "GROSS"})
    commissions = []
    for a in sorted((getattr(concert, "zone_agents", None) or []), key=lambda x: (x.created_at or datetime.min)):
        if (a.commission_type or "PERCENT").upper() == "AMOUNT":
            commissions.append({"mode": "FIXED", "amount": _ff(a.commission_amount),
                                "includes_iva": (a.commission_amount_base or "").upper() == "GROSS",
                                "exempt_amount": _ff(a.exempt_amount)})
        else:
            vt = "PERCENT_PROFIT" if (a.commission_base or "").upper() == "PROFIT" else "PERCENT"
            commissions.append({"mode": "VARIABLE", "var_type": vt, "var_value": _ff(a.commission_pct),
                                "includes_iva": False, "exempt_amount": _ff(a.exempt_amount)})
    production = []
    for b in (s.query(ConcertBudgetItem).filter(ConcertBudgetItem.concert_id == concert.id, ConcertBudgetItem.status != "ELIMINADO").all()):
        production.append({"category": (b.category or "OTROS"), "amount_net": _ff(b.amount_net), "quantity": 1,
                           "iva_pct": 21, "includes_iva": False, "iva_exempt": False, "is_variable": False})
    return {
        "categories": categories, "caches": caches, "commissions": commissions, "production": production,
        "subventions": [], "sponsorships": [],
        "is_international": bool(getattr(concert.artist, "is_international", False)) if concert.artist else False,
        "allows_bars": bool(getattr(concert.venue, "allows_bars", False)) if concert.venue else False,
        "income_overrides": {},
    }


def _concert_result_module_payload(s, concert, calc, label=None):
    """Payload de UNA actividad para sim_partners.js (socios + comisionistas + serie 0–100%)."""
    fine = []
    for pt in (calc.get("series_fine") or []):
        fine.append({"pct": pt["pct"], "tickets": pt["tickets"], "ingresos": pt["ingresos"],
                     "gastos": pt["gastos"], "resultado": pt["resultado"],
                     "g": dict(pt.get("g") or {}), "com": list(pt.get("com") or [])})
    be_pct = be_tickets = None
    for pt in fine:
        if pt["resultado"] >= 0:
            be_pct = pt["pct"]; be_tickets = pt["tickets"]; break
    partners = []
    for sh in (getattr(concert, "company_shares", None) or []):
        if not sh.pct:
            continue
        partners.append({"name": (sh.company.name if sh.company else "Empresa"), "logo": ((sh.company.logo_url if sh.company else "") or ""),
                         "pct": float(_sim_d(sh.pct)), "company_id": (str(sh.company_id) if sh.company_id else ""), "promoter_id": "", "label": "", "no_loss": False})
    for sh in (getattr(concert, "promoter_shares", None) or []):
        if not sh.pct:
            continue
        partners.append({"name": (sh.promoter.nick if sh.promoter else "Socio"), "logo": ((sh.promoter.logo_url if sh.promoter else "") or ""),
                         "pct": float(_sim_d(sh.pct)), "company_id": "", "promoter_id": (str(sh.promoter_id) if sh.promoter_id else ""), "label": "", "no_loss": False})
    commissions_meta = []
    for a in sorted((getattr(concert, "zone_agents", None) or []), key=lambda x: (x.created_at or datetime.min)):
        name = (a.concept or "").strip() or (a.promoter.nick if a.promoter else "Comisionista")
        commissions_meta.append({"name": name, "logo": ((a.promoter.logo_url if a.promoter else "") or ""), "desc": ""})
    return {"label": label or "", "partners": partners, "commissions": commissions_meta, "series": fine,
            "sellable": (calc["ticketing"]["sellable"] if calc else 0), "break_even_pct": be_pct, "break_even_tickets": be_tickets}


def _concert_needs_production_owner(session_db, concert) -> bool:
    """¿Hay que decir A QUIÉN de producción le toca esta actividad?

    Cuando la actividad es de un artista de la casa, producción sale sola por el artista asignado.
    Pero si es un **EVENTO** (no es de ningún artista) o una fecha de **gira comprada promovida por
    una empresa del grupo**, no hay artista del que colgar el trabajo: hay que elegir responsable.

    ⚠️ Lo primero: si la actividad **no va a producción** (una fecha de gira comprada que promueve
    un tercero, o el histórico) no se le pide responsable a nadie — no hay trabajo que repartir.
    """
    if concert is None:
        return False
    if not _concert_needs_production(concert, session_db):
        return False
    if getattr(concert, "event_id", None):
        return True
    # Gira comprada cuyo promotor es una empresa NUESTRA.
    if getattr(concert, "purchased_tour_id", None) and _concert_is_group_promoted(session_db, concert):
        return True
    # Artista sin nadie de la oficina asignado (no es «de la casa»).
    aid = getattr(concert, "artist_id", None)
    if not aid:
        return True
    try:
        for (ids,) in session_db.query(UserProfile.assigned_artist_ids).filter(
                UserProfile.assigned_artist_ids.isnot(None)).all():
            if any(str(x) == str(aid) for x in (ids or [])):
                return False
        return True
    except Exception:
        return False


def _production_people(session_db) -> list:
    """TODO EL PERSONAL ACTUAL para elegir quién lleva la producción, **los de Producción primero**.

    Cada ficha lleva `in_production`, que es lo que usan los selectores para poner a los del
    departamento delante y el resto detrás («ver todo el personal»).

    ⚠️⚠️ ANTES devolvía **solo** a los del departamento y el resto era un respaldo que se usaba
    únicamente si NADIE lo tenía. Efecto real: a quien tenía el departamento mal escrito (o todavía
    sin poner) **no se le podía elegir**, porque los demás sí lo tenían y el respaldo no entraba. Y
    asignar una producción no puede depender de cómo esté escrito un departamento: **tiene que salir
    siempre todo el personal de la oficina**.
    ⚠️ Sin bloqueados ni eliminados (y sin los usuarios ESPEJO de producción externa, que
    `_inactive_user_ids` ya excluye: no son personal de la casa). El JOIN con el perfil es EXTERNO,
    así que quien todavía no tiene ficha de perfil tampoco desaparece."""
    fuera = _inactive_user_ids(session_db)
    filas = (session_db.query(User, UserProfile)
             .outerjoin(UserProfile, UserProfile.user_id == User.id)
             .order_by(func.lower(func.coalesce(UserProfile.nick, User.email)).asc()).all())
    produccion, resto = [], []
    for u, prof in filas:
        if u.id in fuera:
            continue
        ficha = {"id": str(u.id), "name": ((getattr(prof, "nick", None) or u.email or "").strip()),
                 "photo_url": (getattr(prof, "photo_url", "") or ""),
                 "in_production": _profile_in_department(prof, "Producción")}
        (produccion if ficha["in_production"] else resto).append(ficha)
    return produccion + resto


# ================= PRODUCCIÓN EXTERNA (el responsable es un TERCERO) =================
# El responsable de producción de una actividad puede ser un TERCERO (un productor de fuera). Se le
# da un enlace propio: entra con su CORREO y un NÚMERO DE VERIFICACIÓN que le llega por email, y
# desde ahí gestiona esa producción igual que alguien de la casa (personal, hoja de ruta, bolsa,
# gastos…) pero **SOLO esa actividad**.
#
# ⚠️ CÓMO FUNCIONA POR DENTRO: no hay un modo especial repartido por la app. Al tercero se le crea un
# USUARIO ESPEJO (`UserProfile.is_external`) y `Concert.production_owner_user_id` apunta a él, así
# que TODO lo que ya existía (tareas, listados de producción, avisos, quién cierra la bolsa) sigue
# funcionando sin casos particulares — el mismo patrón que el modo «Ver como». Lo único propio es la
# COMPUERTA (`_external_prod_gate`), que en una sesión externa deja pasar solo lo de su actividad.
EXTERNAL_PROD_ACCESS_KEYS = ("produccion", "databases.bags")
EXTERNAL_PROD_CODE_MINUTES = 20          # lo que vale el número de verificación
EXTERNAL_PROD_CODE_MAX_TRIES = 6
# Con la bolsa en estos estados el trabajo ya está entregado a administración: se acabó el acceso.
EXTERNAL_PROD_CLOSED_BAG = {"CERRADA", "LIQUIDADA", "ARCHIVADA"}


def _external_prod_shadow_email(promoter) -> str:
    """El correo del usuario ESPEJO. Es SINTÉTICO a propósito: si se usara el del tercero podría
    chocar con el de alguien de la casa (`users.email` es único) y, peor, se podría intentar entrar
    por el login normal con ese correo. El de verdad vive en el acceso, para el número de
    verificación."""
    return "produccion-externa+%s@33producciones.es" % str(getattr(promoter, "id", "") or "")


def _external_prod_shadow_user(session_db, promoter):
    """El USUARIO ESPEJO del tercero (se crea la primera vez), con lo justo para producir:
    producción y bolsas. No es personal de la casa y no sale en ningún listado."""
    correo = _external_prod_shadow_email(promoter)
    u = session_db.query(User).filter(func.lower(User.email) == correo.lower()).first()
    if u is None:
        u = User(email=correo,
                 # Contraseña IMPOSIBLE: no entra por el login normal, entra por su enlace.
                 password_hash=generate_password_hash(_uuid_token() + _uuid_token()),
                 role=1)
        session_db.add(u)
        session_db.flush()
    prof = session_db.query(UserProfile).filter(UserProfile.user_id == u.id).first()
    if prof is None:
        prof = UserProfile(user_id=u.id)
        session_db.add(prof)
    prof.nick = (_promoter_display_name(promoter) or "Productor externo").strip()
    prof.photo_url = (getattr(promoter, "logo_url", None) or getattr(promoter, "photo_url", None) or "")
    prof.departments = ["Producción"]
    prof.is_external = True
    session_db.flush()
    # Permisos: solo lo que hace falta para producir esa actividad. La compuerta hace el resto.
    for clave in EXTERNAL_PROD_ACCESS_KEYS:
        g = (session_db.query(UserAccessGrant)
             .filter(UserAccessGrant.user_id == u.id,
                     UserAccessGrant.resource_key == clave).first())
        if g is None:
            g = UserAccessGrant(user_id=u.id, resource_key=clave)
            session_db.add(g)
        g.can_view_basic = True
        g.can_edit = True
        # La bolsa ES dinero: sin económico no podría ni ver ni apuntar los gastos que gestiona.
        g.can_view_econ = (clave == "databases.bags")
    session_db.flush()
    return u


def _external_prod_contact_email(session_db, promoter) -> str:
    """El correo del tercero al que se le manda el enlace y el número de verificación."""
    correo = (getattr(promoter, "contact_email", None) or "").strip()
    if correo:
        return correo
    try:
        fila = (session_db.query(PromoterEmail)
                .filter(PromoterEmail.promoter_id == promoter.id)
                .order_by(PromoterEmail.created_at.asc().nullslast()).first())
        return (getattr(fila, "email", "") or "").strip()
    except Exception:
        return ""


def _external_prod_access(session_db, concert, promoter, *, created_by=None):
    """El acceso externo de ESE tercero a ESA actividad (se reutiliza si ya existía)."""
    fila = (session_db.query(ExternalProductionAccess)
            .filter(ExternalProductionAccess.concert_id == concert.id,
                    ExternalProductionAccess.promoter_id == promoter.id).first())
    if fila is None:
        fila = ExternalProductionAccess(concert_id=concert.id, promoter_id=promoter.id,
                                        token=_uuid_token(), status="ACTIVO",
                                        created_by_user_id=created_by)
        session_db.add(fila)
    fila.status = "ACTIVO"
    fila.email = _external_prod_contact_email(session_db, promoter) or fila.email
    session_db.flush()
    return fila


def _external_prod_url(access) -> str:
    return _external_url_for("public_external_production", token=access.token)


def _external_prod_bag(session_db, concert_id):
    """La bolsa de esa actividad (la que dice si el trabajo ya está entregado)."""
    try:
        return (session_db.query(WorkflowBag)
                .filter(WorkflowBag.linked_type.in_(("CONCERT", "concert")),
                        WorkflowBag.linked_id == to_uuid(str(concert_id))).first())
    except Exception:
        return None


def _external_prod_open(session_db, access) -> tuple[bool, str]:
    """¿Sigue teniendo acceso? Devuelve (sí/no, por qué no).

    ⚠️ No se guarda un estado que haya que sincronizar: se MIRA LA BOLSA. Al cerrarla y pasar a
    administración se acaba; si la bolsa vuelve a estar activa (se rechaza o hay algo que modificar),
    vuelve a poder entrar. Así no hay forma de que quede desincronizado (misma regla que
    `_notify_resolve`)."""
    if access is None:
        return False, "Ese enlace ya no vale."
    if (access.status or "").upper() != "ACTIVO":
        return False, "Este acceso se ha retirado."
    bolsa = _external_prod_bag(session_db, access.concert_id)
    if bolsa is not None and (bolsa.status or "").upper() in EXTERNAL_PROD_CLOSED_BAG:
        return False, ("La bolsa ya está cerrada y en administración, así que este acceso ha "
                       "terminado. Si hubiera algo que modificar se te volverá a abrir.")
    return True, ""


def _external_prod_notify(session_db, access, *, concert=None, code: str = "") -> tuple[bool, str]:
    """Le manda al tercero su enlace (y, si toca, el número de verificación).

    Estilo de la casa: el logo arriba a la DERECHA, el título centrado y la cabecera de la actividad,
    la misma que se ve en su ficha."""
    correo = (access.email or "").strip()
    if not correo:
        return False, "Ese tercero no tiene correo: ponlo en su ficha para poder darle acceso."
    c = concert or session_db.get(Concert, access.concert_id)
    logo = ""
    try:
        empresa = (session_db.get(GroupCompany, c.group_company_id)
                   if getattr(c, "group_company_id", None) else None)
        logo = (getattr(empresa, "logo_url", None) or "").strip()
    except Exception:
        logo = ""
    logo = logo or _treinta_y_tres_logo_url(session_db) or _external_url_for(
        "static", filename="img/logo_33_producciones.png")
    filas = ""
    try:
        filas = "".join(
            '<tr><td style="padding:3px 10px 3px 0;color:#6b7280;font-size:13px;white-space:nowrap;">%s</td>'
            '<td style="padding:3px 0;font-size:14px;">%s</td></tr>'
            % (str(escape(k)), str(escape(v)))
            for _ico, k, v in (_contract_sheet_hero_rows(c) or []) if (v or "")) if c is not None else ""
    except Exception:
        filas = ""
    enlace = _external_prod_url(access)
    partes = ['<div style="font-family:Arial,Helvetica,sans-serif;color:#212529;max-width:660px;margin:0 auto;">']
    partes.append('<div style="text-align:right;margin-bottom:6px;">'
                  '<img src="%s" alt="" style="max-height:54px;max-width:190px;"></div>' % str(escape(logo)))
    titulo = "Número de verificación" if code else "Producción de una actividad"
    partes.append('<h2 style="text-align:center;font-size:22px;margin:0 0 14px;">%s</h2>' % titulo)
    if code:
        partes.append('<div style="font-size:15px;line-height:1.7;margin:0 0 10px;">'
                      'Tu número para entrar:</div>')
        partes.append('<div style="text-align:center;font-size:34px;letter-spacing:6px;'
                      'font-weight:bold;margin:0 0 14px;">%s</div>' % str(escape(code)))
        partes.append('<div style="color:#6b7280;font-size:13px;margin:0 0 14px;">'
                      'Vale durante %d minutos. Si no lo has pedido tú, ignora este correo.</div>'
                      % EXTERNAL_PROD_CODE_MINUTES)
    else:
        partes.append('<div style="font-size:15px;line-height:1.7;margin:0 0 14px;">'
                      'Te encargamos la <strong>producción</strong> de esta actividad. Desde el botón '
                      'de abajo puedes gestionarla: el personal, la hoja de ruta y la bolsa de gastos.'
                      '</div>')
    if filas:
        partes.append('<table style="border-collapse:collapse;margin:0 0 16px;">%s</table>' % filas)
    partes.append('<div style="text-align:right;margin:0 0 16px;">'
                  '<a href="%s" style="background:#E33D48;color:#fff;text-decoration:none;'
                  'padding:11px 18px;border-radius:10px;font-weight:bold;display:inline-block;">'
                  'Gestionar la producción</a></div>' % str(escape(enlace)))
    partes.append('<div style="color:#6b7280;font-size:13px;">Se entra con tu correo y un número de '
                  'verificación que te llega por email. El acceso es solo para esta actividad.</div>')
    partes.append('<div style="color:#6b7280;font-size:13px;margin-top:10px;">33 Producciones</div></div>')
    asunto = ("Tu número de verificación" if code
              else "Producción · %s" % ((getattr(c, "festival_name", None) or "").strip()
                                        or _activity_kind_label(_activity_kind_key(
                                            getattr(c, "activity_type", None)))))
    return _send_optional_email([correo], asunto, "".join(partes))


def _external_prod_code_new(access) -> str:
    """Un número de verificación nuevo (6 cifras) con su caducidad."""
    code = "".join(secrets.choice("0123456789") for _ in range(6))
    access.code = generate_password_hash(code)
    access.code_expires_at = _now_madrid() + timedelta(minutes=EXTERNAL_PROD_CODE_MINUTES)
    access.code_sent_at = _now_madrid()
    access.code_attempts = 0
    return code


def _external_prod_session_access(session_db):
    """El acceso externo de ESTA sesión (o None si no es una sesión externa)."""
    aid = session.get("ext_prod_access")
    if not aid:
        return None
    try:
        return session_db.get(ExternalProductionAccess, to_uuid(str(aid)))
    except Exception:
        return None


def _external_prod_info() -> dict:
    """Lo que necesita la plantilla para pintar la franja de «estás gestionando solo esta actividad»."""
    cid = session.get("ext_prod_concert")
    if not cid:
        return {}
    return {"concert_id": str(cid), "name": (session.get("ext_prod_name") or ""),
            "url": url_for("concert_detail_view", cid=str(cid), tab="produccion")}


# ---------- La COMPUERTA: en una sesión externa, solo SU actividad ----------
# Lo que puede tocar un productor externo: la ficha de SU actividad, su hoja de ruta, su bolsa y sus
# gastos, más las búsquedas y las altas rápidas que necesitan esos formularios. Nada más.
EXTERNAL_PROD_FREE_ENDPOINTS = {
    "external_production_exit", "public_external_production", "public_external_production_code",
    "public_external_production_login", "healthz", "static", "notifications_list",
    "notifications_mark_read", "notifications_dismiss_strip",
    # Poder entrar como personal de la casa en el mismo navegador (y salir).
    "admin_login", "admin_logout",
}
# Prefijos de endpoint que sí puede usar (el objetivo se comprueba aparte).
EXTERNAL_PROD_PREFIXES = ("roadmap_", "bag_", "prl_", "person_doc_", "photo_", "fotos_",
                          "api_", "concert_")


def _external_prod_target_ok(session_db, endpoint: str, cid: str) -> bool:
    """¿Lo que se está tocando es SU actividad?

    ⚠️ Sin esta comprobación, el permiso de sección le dejaría abrir la bolsa o la hoja de ruta de
    CUALQUIER actividad: es lo único que separa «producir esto» de «entrar en todo»."""
    args = dict(request.view_args or {})
    # 1 · Por la actividad, que es lo más común (`cid`).
    for clave in ("cid", "concert_id"):
        if args.get(clave):
            return str(args.get(clave)) == str(cid)
    # 2 · Por la BOLSA: tiene que ser la de su actividad.
    if args.get("bag_id"):
        try:
            bolsa = session_db.get(WorkflowBag, to_uuid(str(args["bag_id"])))
        except Exception:
            bolsa = None
        if bolsa is None:
            return False
        return ((bolsa.linked_type or "").upper() == "CONCERT"
                and str(bolsa.linked_id or "") == str(cid))
    # 3 · Por la HOJA DE RUTA (entidad + id).
    if args.get("entity_type") or args.get("etype"):
        tipo = str(args.get("entity_type") or args.get("etype") or "").lower()
        eid = str(args.get("entity_id") or args.get("eid") or "")
        if tipo in ("concert", "concierto"):
            return eid == str(cid)
        return False
    # 4 · Sin objetivo en la URL (búsquedas, altas rápidas, listados de apoyo): pasa.
    return True


def _external_prod_gate():
    """En una sesión EXTERNA (un tercero que produce una actividad) deja pasar solo lo suyo.

    Devuelve una respuesta cuando hay que cortar, o None para seguir. Se llama al principio del
    enforcement: manda sobre cualquier otra resolución de permisos."""
    cid = session.get("ext_prod_concert")
    if not cid:
        return None
    endpoint = (request.endpoint or "")
    if endpoint in EXTERNAL_PROD_FREE_ENDPOINTS:
        return None
    session_db = db()
    try:
        acceso = _external_prod_session_access(session_db)
        abierto, motivo = _external_prod_open(session_db, acceso)
        if not abierto:
            # Se ha terminado su trabajo (o se le ha retirado el acceso): se cierra la sesión y se
            # le dice por qué, en su propia pantalla.
            token = (getattr(acceso, "token", "") or "")
            session.clear()
            flash(motivo or "Este acceso ha terminado.", "warning")
            if token:
                return redirect(url_for("public_external_production", token=token))
            return redirect(url_for("landing"))
        if endpoint in ("home", "landing"):
            return redirect(url_for("concert_detail_view", cid=str(cid), tab="produccion"))
        permitido = (endpoint in SUPPORT_READ_ENDPOINTS or endpoint in SUPPORT_ACTION_ENDPOINTS
                     or endpoint.startswith(EXTERNAL_PROD_PREFIXES))
        if not permitido or not _external_prod_target_ok(session_db, endpoint, str(cid)):
            flash("Con este acceso solo se puede gestionar la producción de esa actividad.", "warning")
            return redirect(url_for("concert_detail_view", cid=str(cid), tab="produccion"))
        return None
    finally:
        session_db.close()


@app.get("/produccion-externa/<token>", endpoint="public_external_production")
def public_external_production(token):
    """Entrada del productor EXTERNO: su correo y el número de verificación que le llega por email."""
    session_db = db()
    try:
        acceso = (session_db.query(ExternalProductionAccess)
                  .filter(ExternalProductionAccess.token == token).first())
        if acceso is None:
            return render_template("public_external_production.html", acceso=None, cerrado="",
                                   concierto=None, paso="no")
        abierto, motivo = _external_prod_open(session_db, acceso)
        c = session_db.get(Concert, acceso.concert_id)
        # Si ya está dentro con esta misma actividad, se le lleva a su producción.
        if abierto and str(session.get("ext_prod_concert") or "") == str(acceso.concert_id):
            return redirect(url_for("concert_detail_view", cid=str(acceso.concert_id), tab="produccion"))
        paso = "codigo" if (request.args.get("paso") == "codigo" and abierto) else "correo"
        return render_template("public_external_production.html", acceso=acceso,
                               cerrado=("" if abierto else (motivo or "Este acceso ha terminado.")),
                               concierto=c, paso=paso,
                               hero_rows=(_contract_sheet_hero_rows(c) if c is not None else []))
    finally:
        session_db.close()


@app.post("/produccion-externa/<token>/codigo", endpoint="public_external_production_code")
def public_external_production_code(token):
    """Manda el NÚMERO DE VERIFICACIÓN al correo del tercero (solo si es el suyo)."""
    session_db = db()
    try:
        acceso = (session_db.query(ExternalProductionAccess)
                  .filter(ExternalProductionAccess.token == token).first())
        if acceso is None:
            abort(404)
        abierto, motivo = _external_prod_open(session_db, acceso)
        if not abierto:
            flash(motivo, "warning")
            return redirect(url_for("public_external_production", token=token))
        escrito = (request.form.get("email") or "").strip().lower()
        # ⚠️ Tiene que ser SU correo: si no, cualquiera con el enlace pediría un código a otra
        # dirección. Y no se dice cuál es el bueno (no se filtra el correo de nadie).
        if not escrito or escrito != (acceso.email or "").strip().lower():
            flash("Ese correo no es el que tenemos para este acceso.", "danger")
            return redirect(url_for("public_external_production", token=token))
        code = _external_prod_code_new(acceso)
        session_db.commit()
        ok, err = _external_prod_notify(session_db, acceso, code=code)
        if not ok:
            flash("No se pudo mandar el número: %s" % (err or "el correo no salió"), "danger")
            return redirect(url_for("public_external_production", token=token))
        flash("Te hemos mandado un número de verificación al correo.", "success")
        return redirect(url_for("public_external_production", token=token, paso="codigo"))
    finally:
        session_db.close()


@app.post("/produccion-externa/<token>/entrar", endpoint="public_external_production_login")
def public_external_production_login(token):
    """Comprueba el número y abre la sesión EXTERNA (solo para esa actividad)."""
    session_db = db()
    try:
        acceso = (session_db.query(ExternalProductionAccess)
                  .filter(ExternalProductionAccess.token == token).first())
        if acceso is None:
            abort(404)
        abierto, motivo = _external_prod_open(session_db, acceso)
        if not abierto:
            flash(motivo, "warning")
            return redirect(url_for("public_external_production", token=token))
        code = "".join((request.form.get("code") or "").split())
        caducado = (not acceso.code or not acceso.code_expires_at
                    or _now_madrid() > acceso.code_expires_at)
        if caducado:
            flash("Ese número ya ha caducado: pide otro.", "warning")
            return redirect(url_for("public_external_production", token=token))
        if (acceso.code_attempts or 0) >= EXTERNAL_PROD_CODE_MAX_TRIES:
            acceso.code = None
            session_db.commit()
            flash("Demasiados intentos: pide un número nuevo.", "danger")
            return redirect(url_for("public_external_production", token=token))
        if not check_password_hash(acceso.code, code):
            acceso.code_attempts = (acceso.code_attempts or 0) + 1
            session_db.commit()
            flash("Ese número no es.", "danger")
            return redirect(url_for("public_external_production", token=token, paso="codigo"))
        promoter = session_db.get(Promoter, acceso.promoter_id)
        usuario = _external_prod_shadow_user(session_db, promoter)
        acceso.user_id = usuario.id
        acceso.code = None
        acceso.code_attempts = 0
        acceso.last_login_at = _now_madrid()
        session_db.commit()
        # Se entra con el usuario ESPEJO (así toda la app funciona igual) y se marca la sesión como
        # EXTERNA: la compuerta la deja solo en su actividad.
        session.clear()
        session["user_id"] = str(usuario.id)
        session["role"] = 1
        session["ext_prod_access"] = str(acceso.id)
        session["ext_prod_concert"] = str(acceso.concert_id)
        session["ext_prod_name"] = _promoter_display_name(promoter)
        return redirect(url_for("concert_detail_view", cid=str(acceso.concert_id), tab="produccion"))
    finally:
        session_db.close()


@app.get("/salir-produccion-externa", endpoint="external_production_exit")
def external_production_exit():
    """Cierra la sesión del productor externo."""
    token = ""
    session_db = db()
    try:
        acceso = _external_prod_session_access(session_db)
        token = (getattr(acceso, "token", "") or "")
    finally:
        session_db.close()
    session.clear()
    flash("Has salido.", "success")
    if token:
        return redirect(url_for("public_external_production", token=token))
    return redirect(url_for("landing"))


@app.post("/conciertos/<cid>/produccion-externa/reenviar", endpoint="concert_production_external_resend")
@admin_required
def concert_production_external_resend(cid):
    """Le vuelve a mandar al tercero su enlace de acceso (o lo devuelve para copiarlo)."""
    session_db = db()
    try:
        c = session_db.get(Concert, to_uuid(cid))
        if c is None or not c.production_owner_promoter_id:
            return jsonify({"ok": False, "error": "Esta actividad no la produce un tercero."}), 404
        if not (can_edit_concerts() or has_access_key("produccion", edit=True, include_descendants=True)):
            return jsonify({"ok": False, "error": "Sin permiso."}), 403
        promoter = session_db.get(Promoter, c.production_owner_promoter_id)
        acceso = _external_prod_access(session_db, c, promoter,
                                       created_by=to_uuid(str((_current_user_state() or {}).get("user_id") or "") or ""))
        session_db.commit()
        ok, err = _external_prod_notify(session_db, acceso, concert=c)
        return jsonify({"ok": bool(ok), "error": ("" if ok else (err or "El correo no salió.")),
                        "url": _external_prod_url(acceso)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[produccion externa] no se pudo reenviar el acceso")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


def _concert_production_pending(concert) -> bool:
    """¿Esta actividad está SIN PRODUCCIÓN ACTIVADA?

    Activar la producción = decir QUIÉN de producción se encarga. Mientras no haya responsable no hay
    nadie produciéndola, así que le sale como tarea pendiente a quien la creó."""
    if concert is None:
        return False
    if getattr(concert, "production_owner_user_id", None):
        return False
    return bool(_concert_needs_production(concert))


def _home_production_activation_pending(session_db, user_id, *, limit: int = 40) -> list[dict]:
    """Actividades a las que hay que ACTIVAR LA PRODUCCIÓN, para quien las creó.

    · Sin bolsa todavía → «Activar producción» (elegir quién se encarga).
    · Con bolsa (la producción ya estaba en marcha) pero sin responsable → «Asignar producción».
    Dirección ve además las antiguas, que no tienen creador apuntado (nadie las reclamaría)."""
    uid = to_uuid(str(user_id or ""))
    if not uid:
        return []
    hoy = today_local()
    consulta = (session_db.query(Concert)
                .options(joinedload(Concert.artist), joinedload(Concert.venue))
                .filter(Concert.production_owner_user_id.is_(None),
                        Concert.status.in_(["HABLADO", "RESERVADO", "CONFIRMADO"]),
                        or_(Concert.date.is_(None), Concert.date >= hoy)))
    if is_master():
        consulta = consulta.filter(or_(Concert.created_by_user_id == uid,
                                       Concert.created_by_user_id.is_(None)))
    else:
        consulta = consulta.filter(Concert.created_by_user_id == uid)
    filas = []
    for c in consulta.order_by(Concert.date.asc().nullslast()).limit(200).all():
        if not _concert_needs_production(c, session_db):
            continue
        tiene_bolsa = bool(session_db.query(WorkflowBag.id)
                           .filter(WorkflowBag.linked_type.in_(("CONCERT", "concert")),
                                   WorkflowBag.linked_id == c.id).first())
        kind = _activity_kind_key(c.activity_type) or "CONCIERTO"
        filas.append({
            "id": str(c.id),
            "url": url_for("concert_detail_view", cid=c.id),
            "icon": QUAD_ACTIVITY_ICONS.get(kind, "fa-guitar"),
            "type_label": _activity_kind_label(kind),
            "title": ((c.festival_name or "").strip()
                      or (c.artist.name if c.artist else "") or _activity_kind_label(kind)),
            "date_label": (c.date.strftime("%d/%m/%Y") if c.date else "Sin fecha"),
            "venue": (_concert_venue_name(c) or ""),
            "municipality": _concert_city(c),
            # Con bolsa ya se estaba produciendo: lo que falta es DECIR QUIÉN.
            "action_label": ("Asignar producción" if tiene_bolsa else "Activar producción"),
            "started": tiene_bolsa,
        })
        if len(filas) >= limit:
            break
    return filas


def _home_production_activation_wrap() -> list[dict]:
    """Envoltorio para el contexto de plantillas: abre su sesión y cierra siempre."""
    uid = (_current_user_state() or {}).get("user_id")
    if not uid:
        return []
    session_db = db()
    try:
        return _home_production_activation_pending(session_db, uid)
    except Exception:
        return []
    finally:
        session_db.close()


def _concert_production_owner_name(session_db, concert) -> str:
    uid = getattr(concert, "production_owner_user_id", None)
    if not uid:
        return ""
    prof = session_db.query(UserProfile).filter(UserProfile.user_id == uid).first()
    if prof and (prof.nick or "").strip():
        return prof.nick.strip()
    u = session_db.get(User, uid)
    return (u.email if u else "") or ""


def _concert_bag_expense_totals(session_db, concert):
    """Gastos de PRODUCCIÓN de la bolsa de esta actividad, por categoría: lo CONSOLIDADO (con su
    factura o con la falta de factura ya justificada) y el total metido en la bolsa. El punto de
    empate se recalcula solo según se van consolidando."""
    bag = (session_db.query(WorkflowBag)
           .filter(WorkflowBag.linked_type == "CONCERT", WorkflowBag.linked_id == concert.id)
           .order_by(WorkflowBag.created_at.desc()).first())
    if bag is None:
        return None
    filas = (session_db.query(BagExpense)
             .filter(BagExpense.bag_id == bag.id).all())
    por_categoria, consolidado, total = {}, Decimal("0"), Decimal("0")
    n_cons = 0
    for e in filas:
        neto = _money_or_zero(getattr(e, "amount_net", 0))
        total += neto
        if (getattr(e, "consolidation_status", "") or "").upper() == "CONSOLIDADO":
            consolidado += neto
            n_cons += 1
            cat = (e.category or "OTROS")
            por_categoria[cat] = por_categoria.get(cat, Decimal("0")) + neto
    return {"bag": bag, "by_category": por_categoria, "consolidated": consolidado,
            "total": total, "count": len(filas), "consolidated_count": n_cons}


def _concert_break_even_from(s, concert, production_rows):
    """Punto de empate (entradas y % de aforo) usando ESOS gastos de producción."""
    try:
        data = _concert_build_calc_data(s, concert)
        data["production"] = production_rows
        calc = sim_calc.compute(data)
        return {"tickets": calc.get("break_even_tickets"), "pct": calc.get("break_even_pct"),
                "sellable": (calc.get("ticketing") or {}).get("sellable")}
    except Exception:
        return None


def _concert_break_even_info(s, concert):
    """De dónde sale el PUNTO DE EMPATE de la actividad y cuánto da con cada base.

    Manda, por este orden:
      1. **Contratación**, si lo ha puesto a mano (`Concert.break_even_ticket`).
      2. Los gastos de la **bolsa** que ya están CONSOLIDADOS (se va actualizando solo según se
         consolidan).
      3. El **presupuesto** de gastos (el que trae la simulación o el del evento).
    Devuelve None si no hay con qué calcularlo (sin ticketing o sin previsión de ingresos).
    """
    presupuesto = [
        {"category": (b.category or "OTROS"), "amount_net": float(_money_or_zero(b.amount_net)),
         "quantity": 1, "iva_pct": 21, "includes_iva": False, "iva_exempt": False, "is_variable": False}
        for b in (s.query(ConcertBudgetItem)
                  .filter(ConcertBudgetItem.concert_id == concert.id,
                          ConcertBudgetItem.status != "ELIMINADO").all())
    ]
    bolsa = _concert_bag_expense_totals(s, concert)
    filas_bolsa = None
    if bolsa and bolsa["consolidated_count"]:
        filas_bolsa = [
            {"category": cat, "amount_net": float(imp), "quantity": 1, "iva_pct": 21,
             "includes_iva": False, "iva_exempt": False, "is_variable": False}
            for cat, imp in bolsa["by_category"].items()
        ]
    calc_pres = _concert_break_even_from(s, concert, presupuesto) if presupuesto else None
    calc_bolsa = _concert_break_even_from(s, concert, filas_bolsa) if filas_bolsa else None
    manual = getattr(concert, "break_even_ticket", None)
    sellable = ((calc_bolsa or calc_pres or {}) or {}).get("sellable") or 0

    if manual:
        fuente, tickets = "MANUAL", int(manual)
        pct = (round(tickets * 100.0 / sellable, 1) if sellable else None)
    elif calc_bolsa and calc_bolsa.get("tickets") is not None:
        fuente, tickets, pct = "BOLSA", calc_bolsa["tickets"], calc_bolsa["pct"]
    elif calc_pres and calc_pres.get("tickets") is not None:
        fuente, tickets, pct = "PRESUPUESTO", calc_pres["tickets"], calc_pres["pct"]
    else:
        return None
    # ¿Lo que puso contratación NO cuadra con lo calculado? Solo entonces hay que avisar.
    auto = (calc_bolsa or calc_pres or {}) or {}
    auto_tickets = auto.get("tickets")
    discrepa = bool(manual and auto_tickets is not None and int(manual) != int(auto_tickets))
    return {
        "source": fuente,
        "tickets": tickets,
        "pct": pct,
        "mismatch": discrepa,
        "auto_tickets": auto_tickets,
        "auto_pct": auto.get("pct"),
        "auto_source": ("BOLSA" if calc_bolsa else ("PRESUPUESTO" if calc_pres else "")),
        "sellable": sellable,
        "manual": (int(manual) if manual else None),
        "budget": calc_pres,
        "bag": calc_bolsa,
        "bag_consolidated": (float(bolsa["consolidated"]) if bolsa else 0.0),
        "bag_total": (float(bolsa["total"]) if bolsa else 0.0),
        "bag_pending": (int(bolsa["count"] - bolsa["consolidated_count"]) if bolsa else 0),
        "budget_total": float(sum((_money_or_zero(x["amount_net"]) for x in presupuesto), Decimal("0"))),
    }


def _concert_result_context(s, concert):
    """{calc, module} para la pestaña Resultado del concierto, o None si falla el cálculo."""
    try:
        calc = sim_calc.compute(_concert_build_calc_data(s, concert))
        module = {"mode": "activity", "labels": SIM_EXPENSE_CATEGORY_LABELS,
                  "activities": [_concert_result_module_payload(s, concert, calc)]}
        # ¿Los ingresos vienen de la venta REAL de Enterticket? (mismo criterio que el adaptador)
        et_income = False
        try:
            _ev = s.query(EnterticketEvent).filter(EnterticketEvent.concert_id == concert.id).first()
            if _ev is not None:
                et_income = bool(_et_valid_sales_filter(s.query(EnterticketSale.id), _ev)
                                 .filter(EnterticketSale.is_invitation.is_(False)).first())
        except Exception:
            et_income = False
        return {"calc": calc, "module": module, "et_income": et_income}
    except Exception:
        return None


def _concert_production_panel(session_db, concert):
    bag = (
        session_db.query(WorkflowBag)
        .filter(WorkflowBag.linked_type == "CONCERT")
        .filter(WorkflowBag.linked_id == concert.id)
        .order_by(WorkflowBag.created_at.desc())
        .first()
    )
    budget_items = (
        session_db.query(ConcertBudgetItem)
        .filter(ConcertBudgetItem.concert_id == concert.id)
        .filter(ConcertBudgetItem.status != "ELIMINADO")
        .order_by(ConcertBudgetItem.category.asc(), ConcertBudgetItem.sort_order.asc(), ConcertBudgetItem.created_at.asc())
        .all()
    )
    request_row = (
        session_db.query(ProductionRequest)
        .filter(ProductionRequest.linked_type == "CONCERT")
        .filter(ProductionRequest.linked_id == concert.id)
        .order_by(ProductionRequest.created_at.desc())
        .first()
    )
    net_total = sum([_money_or_zero(getattr(item, "amount_net", 0)) for item in budget_items], Decimal("0"))
    gross_total = sum([_money_or_zero(getattr(item, "amount_gross", 0)) for item in budget_items], Decimal("0"))
    roadmap = _json_loads_safe(getattr(concert, "roadmap_payload", None), {})
    # Plantillas de gastos del ARTISTA y del RECINTO (para cargarlas al abrir la bolsa o
    # como base del presupuesto; se pueden COMBINAR ambas).
    artist_templates = []
    venue_templates = []
    try:
        for t in _expense_templates_for(session_db, "ARTIST", concert.artist_id):
            artist_templates.append({"id": str(t.id), "name": (t.name or "Plantilla"), "count": len(t.items or [])})
    except Exception:
        artist_templates = []
    try:
        if getattr(concert, "venue_id", None):
            for t in _expense_templates_for(session_db, "VENUE", concert.venue_id):
                venue_templates.append({"id": str(t.id), "name": (t.name or "Plantilla"), "count": len(t.items or [])})
    except Exception:
        venue_templates = []
    # Presupuesto agrupado con las categorías de SIMULACIÓN (misma estética que sus gastos).
    budget_by_cat = {}
    for item in budget_items:
        budget_by_cat.setdefault(_bag_expense_display_cat(getattr(item, "category", "OTROS")), []).append(item)
    return {
        "bag": bag,
        "budget_items": budget_items,
        "budget_by_cat": budget_by_cat,
        "budget_net_total": net_total,
        "budget_gross_total": gross_total,
        "has_budget": bool(budget_items),
        "request": request_row,
        "roadmap": roadmap if isinstance(roadmap, dict) else {},
        "can_open_bag": bag is None,
        "artist_templates": artist_templates,
        "venue_templates": venue_templates,
    }


def _concert_linked_snapshot(concert):
    venue = getattr(concert, "venue", None)
    artist = getattr(concert, "artist", None)
    return {
        "type": getattr(concert, "activity_type", None) or "CONCERT",
        "title": getattr(concert, "festival_name", None) or (artist.name if artist else "Actividad"),
        "date": concert.date.isoformat() if getattr(concert, "date", None) else None,
        "artist": artist.name if artist else None,
        "venue": getattr(venue, "name", None) or getattr(concert, "manual_venue_name", None),
        "municipality": getattr(venue, "municipality", None) or getattr(concert, "manual_municipality", None),
        "province": getattr(venue, "province", None) or getattr(concert, "manual_province", None),
    }


def _create_bag_for_concert(session_db, concert, import_budget=False):
    existing = (
        session_db.query(WorkflowBag)
        .filter(WorkflowBag.linked_type == "CONCERT")
        .filter(WorkflowBag.linked_id == concert.id)
        .first()
    )
    if existing:
        return existing
    artists = _artists_from_ids(session_db, _concert_primary_artist_ids(concert))
    artist_label = _artist_label_from_rows(artists)
    title_bits = ["Bolsa", artist_label]
    if getattr(concert, "festival_name", None):
        title_bits.append(concert.festival_name)
    elif getattr(concert, "date", None):
        title_bits.append(concert.date.strftime("%d/%m/%Y"))
    bag = WorkflowBag(
        title=" · ".join([x for x in title_bits if x]),
        artist_id=artists[0].id if artists else getattr(concert, "artist_id", None),
        artist_ids=[str(a.id) for a in artists],
        company_id=getattr(concert, "billing_company_id", None) or getattr(concert, "group_company_id", None),
        bag_type=(getattr(concert, "activity_type", None) or "CONCERT"),
        linked_type="CONCERT",
        linked_id=concert.id,
        linked_title=getattr(concert, "festival_name", None) or artist_label,
        linked_snapshot=_concert_linked_snapshot(concert),
        start_date=getattr(concert, "date", None),
        end_date=getattr(concert, "date", None),
        status="ACTIVA",
        liquidation_status="NO_INICIADA",
    )
    session_db.add(bag)
    session_db.flush()
    if import_budget:
        budget_items = (
            session_db.query(ConcertBudgetItem)
            .filter(ConcertBudgetItem.concert_id == concert.id)
            .filter(ConcertBudgetItem.status != "ELIMINADO")
            .order_by(ConcertBudgetItem.sort_order.asc(), ConcertBudgetItem.created_at.asc())
            .all()
        )
        for idx, item in enumerate(budget_items, 1):
            gross = _money_or_zero(getattr(item, "amount_gross", 0))
            net = _money_or_zero(getattr(item, "amount_net", 0))
            tax = gross - net if gross and net and gross >= net else Decimal("0")
            session_db.add(BagExpense(
                bag_id=bag.id,
                category=getattr(item, "category", None) or "OTROS",
                sort_order=idx,
                concept=getattr(item, "concept", None),
                amount_net=net,
                amount_tax=tax,
                amount_gross=gross or net,
                document_type="SIN_DOCUMENTO",
                consolidation_status="PENDIENTE",
                payment_status="NO_PAGADO",
                created_by_nick=getattr(item, "created_by_nick", None),
            ))
    return bag


# FECHA DE CORTE DEL HISTÓRICO. Las actividades ANTERIORES a este día no se procesan: no generan
# aviso de producción, ni bolsa, ni tareas pendientes, ni salen para declarar en Registros. Siguen
# en el listado de actividades y en su ficha (el historial se conserva), simplemente no cuentan como
# trabajo por hacer. Para mover el corte basta cambiar esta fecha.
LEGACY_ACTIVITY_CUTOFF = date(2026, 7, 28)


def _is_legacy_activity_date(value) -> bool:
    """¿Esa fecha es anterior al corte del histórico?"""
    try:
        return bool(value) and value < LEGACY_ACTIVITY_CUTOFF
    except TypeError:
        return False


def _concert_is_legacy(concert) -> bool:
    """Actividad del histórico: se conserva, pero no genera trabajo (producción, bolsa, registros…)."""
    return concert is not None and _is_legacy_activity_date(getattr(concert, "date", None))


def _concert_needs_production(concert, session_db=None) -> bool:
    """¿Esta actividad tiene que aparecer en Producción?

    Dos motivos para que NO:
      · es del HISTÓRICO (anterior a `LEGACY_ACTIVITY_CUTOFF`): no se procesa nada de antes;
      · en una GIRA COMPRADA hay fechas que promovemos nosotros y otras que se le venden a un
        promotor de fuera: de esas últimas **no nos ocupamos de la producción**, así que ni salen en
        Producción ni hay que asignarles responsable.
    ⚠️ El criterio de una fecha de gira comprada es **que promueva una empresa del GRUPO**
    (`_concert_is_group_promoted`: `group_company_id` o participación vía `ConcertCompanyShare`), el
    mismo que usan la cartelería y las invitaciones. Antes se miraba solo «que no haya un tercero
    como promotor», que no es lo mismo: una fecha a la que nadie le había puesto promotor se colaba
    en Producción como si fuera nuestra, y pedía responsable a quien no le tocaba.
    """
    if concert is None:
        return False
    if _concert_is_legacy(concert):
        return False
    if not getattr(concert, "purchased_tour_id", None):
        return True
    sesion = session_db
    if sesion is None:
        try:
            from sqlalchemy.orm import object_session
            sesion = object_session(concert)
        except Exception:
            sesion = None
    if sesion is None:
        # Sin sesión no se puede mirar la participación del grupo: se queda con lo que trae la fila.
        return bool(getattr(concert, "group_company_id", None))
    return _concert_is_group_promoted(sesion, concert)


def _ensure_production_request_for_concert(session_db, concert):
    if not concert:
        return None
    if not _concert_needs_production(concert, session_db):
        return None
    existing = (
        session_db.query(ProductionRequest)
        .filter(ProductionRequest.linked_type == "CONCERT")
        .filter(ProductionRequest.linked_id == concert.id)
        .filter(ProductionRequest.status.in_(["REQUESTED", "ACTIVE", "PENDIENTE", "ACTIVA"]))
        .first()
    )
    if existing:
        if existing.status == "REQUESTED":
            existing.status = "ACTIVE"
        return existing
    snap = _concert_linked_snapshot(concert)
    row = ProductionRequest(
        activity_type=(getattr(concert, "activity_type", None) or "CONCERT"),
        activity_title=snap.get("title"),
        artist_ids=[str(x) for x in _concert_primary_artist_ids(concert)],
        activity_date=getattr(concert, "date", None),
        city=snap.get("municipality"),
        province=snap.get("province"),
        linked_type="CONCERT",
        linked_id=concert.id,
        status="ACTIVE",
        notes="Actividad marcada como reservada/confirmada desde Contratación.",
    )
    session_db.add(row)
    if hasattr(concert, "production_status"):
        concert.production_status = "ACTIVE"
    return row


def _production_concert_row(session_db, concert):
    artists = _artists_from_ids(session_db, _concert_primary_artist_ids(concert))
    venue = getattr(concert, "venue", None)
    # Actividad AÚN sin reservar/confirmar (borrador/hablada): fuera de Contratación/dirección se
    # muestra solo como «Reserva — consultar con Contratación», sin detalles ni enlace a la ficha.
    if (getattr(concert, "status", "") or "").upper() in _CONCERT_PRIVATE_STATUSES and not _user_sees_unconfirmed_activities():
        return {
            "kind": "CONCERT",
            "id": str(concert.id),
            "title": "Reserva",
            "type_label": "Consultar con Contratación",
            "artist_label": _artist_label_from_rows(artists),
            "artist_photo_url": (getattr(artists[0], "photo_url", None) if artists else None) or url_for("static", filename="img/placeholder_photo.png"),
            "date": getattr(concert, "date", None),
            "date_label": concert.date.strftime("%d/%m/%Y") if getattr(concert, "date", None) else "Sin fecha",
            "city": "",
            "province": "",
            "status": "",
            "detail_url": "#",
        }
    return {
        "kind": "CONCERT",
        "id": str(concert.id),
        "title": getattr(concert, "festival_name", None) or _artist_label_from_rows(artists),
        "type_label": (getattr(concert, "activity_type", None) or "Concierto").replace("_", " ").title(),
        "artist_label": _artist_label_from_rows(artists),
        "artist_photo_url": (getattr(artists[0], "photo_url", None) if artists else None) or url_for("static", filename="img/placeholder_photo.png"),
        "date": getattr(concert, "date", None),
        "date_label": concert.date.strftime("%d/%m/%Y") if getattr(concert, "date", None) else "Sin fecha",
        "city": getattr(venue, "municipality", None) or getattr(concert, "manual_municipality", None) or "",
        "province": getattr(venue, "province", None) or getattr(concert, "manual_province", None) or "",
        "status": getattr(concert, "status", None) or "",
        "detail_url": url_for("concert_detail_view", cid=concert.id, tab="produccion"),
    }


def _production_active_rows(session_db) -> list[dict]:
    """ACTIVAS de producción, en el mismo formato que la sección Actividades.

    Una fila por actividad, con el icono de SU TIPO, el sujeto (artista o evento), la fecha, el
    recinto y quién la produce. Es lo que se agrupa por artista en la pestaña «Activas»."""
    hoy = today_local()
    filas = []
    eventos = {}
    conciertos = (session_db.query(Concert)
                  .options(joinedload(Concert.artist), joinedload(Concert.venue))
                  .filter(Concert.status.in_(["RESERVADO", "CONFIRMADO"]))
                  .order_by(Concert.date.asc().nullslast())
                  .limit(600).all())
    ids = [c.id for c in conciertos]
    con_bolsa = set()
    if ids:
        try:
            con_bolsa = {r[0] for r in session_db.query(WorkflowBag.linked_id).filter(
                WorkflowBag.linked_type.in_(("CONCERT", "concert")),
                WorkflowBag.linked_id.in_(ids)).all()}
        except Exception:
            con_bolsa = set()
    ev_ids = [c.event_id for c in conciertos if getattr(c, "event_id", None)]
    if ev_ids:
        eventos = {str(e.id): e for e in session_db.query(AppEvent).filter(AppEvent.id.in_(ev_ids)).all()}
    duenos = {}
    dueno_ids = [c.production_owner_user_id for c in conciertos if getattr(c, "production_owner_user_id", None)]
    if dueno_ids:
        for u, prof in (session_db.query(User, UserProfile)
                        .join(UserProfile, UserProfile.user_id == User.id)
                        .filter(User.id.in_(dueno_ids)).all()):
            duenos[str(u.id)] = (prof.nick or u.email or "").strip()
    for c in conciertos:
        # Lo que ya se está trabajando (tiene bolsa) se conserva aunque hoy no cumpla el criterio.
        if not (_concert_needs_production(c, session_db) or c.id in con_bolsa):
            continue
        # Lo pasado sin bolsa no es trabajo activo.
        if c.date and c.date < hoy and c.id not in con_bolsa:
            continue
        kind = _activity_kind_key(c.activity_type) or "CONCIERTO"
        if getattr(c, "event_id", None):
            ev = eventos.get(str(c.event_id))
            sujeto = ("event", str(c.event_id), (getattr(ev, "name", "") or "Evento"),
                      (getattr(ev, "logo_url", "") or ""))
        else:
            art = getattr(c, "artist", None)
            sujeto = ("artist", (str(c.artist_id) if c.artist_id else ""),
                      (getattr(art, "name", "") or "Sin artista"),
                      (getattr(art, "photo_url", "") or ""))
        etiqueta, clase = _concert_status_meta(c.status)
        oid = str(getattr(c, "production_owner_user_id", "") or "")
        filas.append({
            "id": str(c.id),
            "url": url_for("concert_detail_view", cid=c.id, tab="produccion"),
            "subject_kind": sujeto[0], "subject_id": sujeto[1],
            "subject_name": sujeto[2], "subject_photo": sujeto[3],
            "icon": QUAD_ACTIVITY_ICONS.get(kind, "fa-guitar"),
            "type_key": kind,
            "type_label": _activity_kind_label(kind),
            "title": ((c.festival_name or "").strip() or _activity_kind_label(kind)),
            "date": c.date,
            "date_label": (c.date.strftime("%d/%m/%Y") if c.date else "Sin fecha"),
            "venue": (_concert_venue_name(c) or "Sin recinto"),
            "municipality": _concert_city(c), "province": _concert_province_value(c),
            "status_label": etiqueta, "status_badge": clase,
            "owner_id": oid, "owner_name": duenos.get(oid, ""),
            "created_at": getattr(c, "created_at", None),
            "has_bag": c.id in con_bolsa,
        })
    filas.sort(key=lambda f: (f["date"] or date.max))
    return filas


def _production_active_context(session_db) -> dict:
    """La pestaña «Activas» de Producción: rejilla por SUJETO y, al entrar, sus actividades.

    Cada persona de producción ve **solo lo que se le ha asignado**; dirección (y quien no es de
    producción) lo ve todo. Lo que NO tiene responsable no es de nadie: sale en su propio listado
    **debajo de la rejilla** (y solo ahí: dentro de un artista o evento no pinta nada), donde lo único
    que se puede hacer es **elegir a la persona de producción** que se encarga.

    Al entrar en un sujeto se enseña de quién son las actividades (foto, nombre y total) y, debajo,
    los FILTROS POR TIPO — solo los tipos que tienen actividades, igual que en la sección
    Actividades."""
    estado = _current_user_state() or {}
    uid = str(estado.get("user_id") or "")
    deps = [str(d).strip().lower() for d in (getattr(estado.get("profile"), "departments", None) or [])]
    # ⚠️ Dirección se decide por el ROL DE LA BD (`estado["role"]`), no con `is_master()`: ese lee el
    # rol de la SESIÓN y sin él cae a dirección, con lo que producción vería todo.
    es_direccion = int(estado.get("role") or 0) == 10
    soy_produccion = ("producción" in deps or "produccion" in deps) and not es_direccion
    filas = _production_active_rows(session_db)
    sin_dueno = [f for f in filas if not f["owner_id"]]
    if soy_produccion:
        filas = [f for f in filas if f["owner_id"] == uid]
    # NUEVAS desde la última vez que entró.
    visto = getattr(estado.get("profile"), "production_seen_at", None)
    for f in filas:
        f["is_new"] = bool(visto and f["created_at"] and f["created_at"] > visto)
    grupos = {}
    for f in filas:
        clave = (f["subject_kind"], f["subject_id"])
        g = grupos.setdefault(clave, {"kind": f["subject_kind"], "id": f["subject_id"],
                                      "name": f["subject_name"], "photo_url": f["subject_photo"],
                                      "count": 0, "new_count": 0})
        g["count"] += 1
        if f.get("is_new"):
            g["new_count"] += 1
    sujetos = sorted(grupos.values(), key=lambda g: (g["name"] or "").lower())
    drill_art = (request.args.get("artist") or "").strip()
    drill_ev = (request.args.get("event") or "").strip()
    sujeto = None
    if drill_ev:
        filas = [f for f in filas if f["subject_kind"] == "event" and f["subject_id"] == drill_ev]
        sujeto = next((g for g in sujetos if g["kind"] == "event" and g["id"] == drill_ev), None)
    elif drill_art:
        filas = [f for f in filas if f["subject_kind"] == "artist" and f["subject_id"] == drill_art]
        sujeto = next((g for g in sujetos if g["kind"] == "artist" and g["id"] == drill_art), None)
    for g in sujetos:
        g["url"] = url_for("produccion_view", tab="activas",
                           **({"event": g["id"]} if g["kind"] == "event" else {"artist": g["id"]}))
    # FILTROS POR TIPO dentro del sujeto: se cuentan sobre sus actividades (sin aplicar el propio
    # filtro) y solo se ofrecen los tipos que tienen algo.
    tipos_sel = set()
    for x in request.args.getlist("tipo"):
        k = (x or "").strip().upper()
        k = QUAD_ACTIVITY_ALIASES.get(k, k)
        if k:
            tipos_sel.add(k)
    cuenta_tipos = {}
    for f in filas:
        cuenta_tipos[f["type_key"]] = cuenta_tipos.get(f["type_key"], 0) + 1
    type_chips = []
    base_args = {"tab": "activas"}
    if sujeto is not None:
        base_args.update({"event": sujeto["id"]} if sujeto["kind"] == "event" else {"artist": sujeto["id"]})
        for k in ACTIVITIES_TYPE_KEYS:
            if not cuenta_tipos.get(k, 0) and k not in tipos_sel:
                continue
            otros = sorted(tipos_sel - {k}) if k in tipos_sel else sorted(tipos_sel | {k})
            type_chips.append({
                "key": k, "label": _activity_kind_label(k),
                "icon": QUAD_ACTIVITY_ICONS.get(k, "fa-calendar-day"),
                "count": cuenta_tipos.get(k, 0), "active": k in tipos_sel,
                "url": url_for("produccion_view", tipo=otros, **base_args),
            })
        if tipos_sel:
            filas = [f for f in filas if f["type_key"] in tipos_sel]
    return {
        "subjects": sujetos,
        "rows": filas,
        "subject": sujeto,
        # Pendientes de asignar: solo FUERA de un artista o evento (dentro de uno no vienen a cuento).
        "unassigned": ([] if (soy_produccion or sujeto is not None) else sin_dueno),
        "only_mine": soy_produccion,
        "type_chips": type_chips,
        "clear_types_url": (url_for("produccion_view", **base_args) if (sujeto is not None and tipos_sel) else ""),
        "total": sum(g["count"] for g in sujetos),
    }


def _production_mark_seen(session_db) -> None:
    """Apunta que esta persona ya ha visto sus Activas (para el destacado «Nueva actividad»)."""
    uid = to_uuid(str((_current_user_state() or {}).get("user_id") or ""))
    if not uid:
        return
    try:
        perfil = session_db.query(UserProfile).filter(UserProfile.user_id == uid).first()
        if perfil is not None:
            perfil.production_seen_at = _now_madrid()
            session_db.commit()
    except Exception:
        session_db.rollback()


def _norm_action_status(status):
    st = (status or "RESERVA").strip().upper()
    aliases = {
        "RESERVA_DE_CONFIRMAR": "RESERVA",
        "RESERVADO": "RESERVA",
        "ACTIVA": "CONFIRMADO",
        "ACTIVE": "CONFIRMADO",
        "ARCHIVED": "ARCHIVADA",
        "CLOSED": "CERRADA",
    }
    return aliases.get(st, st)


def _action_type_label(action_type, content_subtype=None):
    label = ACTION_TYPE_LABELS.get((action_type or "").strip().upper(), (action_type or "Acción").replace("_", " ").title())
    if (action_type or "").strip().upper() == "GENERACION_CONTENIDO" and content_subtype:
        label = f"{label} · {str(content_subtype).replace('_', ' ').title()}"
    return label


def _action_status_badge(status):
    st = _norm_action_status(status)
    if st == "CONFIRMADO":
        return {"label": "Confirmada", "class": "bg-success"}
    if st == "RESERVA":
        return {"label": "Reserva de confirmar", "class": "bg-warning text-dark"}
    if st == "CANCELADA":
        return {"label": "Cancelada", "class": "bg-danger"}
    if st in {"CERRADA", "ARCHIVADA"}:
        return {"label": "Cerrada", "class": "bg-secondary"}
    return {"label": ACTION_STATUS_LABELS.get(st, st.title()), "class": "bg-light text-dark border"}


def _action_location(action):
    venue = getattr(action, "venue", None)
    if venue:
        return _venue_label(venue)
    snap = _json_loads_safe(getattr(action, "location_snapshot", None), {})
    if isinstance(snap, dict):
        return " · ".join([str(snap.get(k) or "").strip() for k in ("venue", "city", "province") if str(snap.get(k) or "").strip()])
    return ""


def _action_display_row(session_db, action):
    artists = _artists_from_ids(session_db, getattr(action, "artist_ids", []) or [])
    return {
        "kind": "ACTION",
        "id": str(action.id),
        "title": getattr(action, "title", None) or "Acción",
        "type_label": _action_type_label(getattr(action, "action_type", None), getattr(action, "content_subtype", None)),
        "artist_label": _artist_label_from_rows(artists),
        "artist_photo_url": (getattr(artists[0], "photo_url", None) if artists else None) or url_for("static", filename="img/placeholder_photo.png"),
        "date": getattr(action, "start_date", None),
        "end_date": getattr(action, "end_date", None),
        "date_label": _action_period_label(getattr(action, "start_date", None), getattr(action, "end_date", None)),
        "location": _action_location(action),
        "status": _norm_action_status(getattr(action, "status", None)),
        "status_badge": _action_status_badge(getattr(action, "status", None)),
        "detail_url": url_for("action_detail_view", action_id=action.id),
    }


def _action_request_display_row(session_db, row):
    artists = _artists_from_ids(session_db, getattr(row, "artist_ids", []) or [])
    payload = _json_loads_safe(getattr(row, "payload", None), {})
    return {
        "kind": "ACTION_REQUEST",
        "id": str(row.id),
        "title": getattr(row, "title", None) or _action_type_label(getattr(row, "action_type", None), getattr(row, "content_subtype", None)),
        "type_label": _action_type_label(getattr(row, "action_type", None), getattr(row, "content_subtype", None)),
        "artist_label": _artist_label_from_rows(artists),
        "artist_photo_url": (getattr(artists[0], "photo_url", None) if artists else None) or url_for("static", filename="img/placeholder_photo.png"),
        "date": getattr(row, "due_date", None) or getattr(row, "requested_date", None),
        "date_label": ((getattr(row, "due_date", None) or getattr(row, "requested_date", None)).strftime("%d/%m/%Y") if (getattr(row, "due_date", None) or getattr(row, "requested_date", None)) else "Sin fecha"),
        "status": getattr(row, "status", None) or "REQUESTED",
        "requested_by": getattr(row, "requested_by_nick", None) or "",
        "payload": payload if isinstance(payload, dict) else {},
    }


def _action_period_label(start_date, end_date=None):
    if start_date and end_date and end_date != start_date:
        return f"{start_date.strftime('%d/%m/%Y')} - {end_date.strftime('%d/%m/%Y')}"
    if start_date:
        return start_date.strftime("%d/%m/%Y")
    return "Sin fecha"


def _activity_calendar_rows(items, days=30):
    today = today_local()
    limit = today + timedelta(days=days)
    grouped = defaultdict(list)
    for item in items or []:
        dt = item.get("date")
        if dt and today <= dt <= limit:
            grouped[dt].append(item)
    rows = []
    cursor = today
    while cursor <= limit:
        rows.append({"date": cursor, "items": list(grouped.get(cursor, [])), "is_today": cursor == today})
        cursor += timedelta(days=1)
    return rows


def _ensure_production_request_for_action(session_db, action):
    if not action:
        return None
    existing = (
        session_db.query(ProductionRequest)
        .filter(ProductionRequest.linked_type == "ACTION")
        .filter(ProductionRequest.linked_id == action.id)
        .filter(ProductionRequest.status.in_(["REQUESTED", "ACTIVE", "PENDIENTE", "ACTIVA"]))
        .first()
    )
    if existing:
        if existing.status == "REQUESTED":
            existing.status = "ACTIVE"
        return existing
    location = _action_location(action)
    city = None
    province = None
    snap = _json_loads_safe(getattr(action, "location_snapshot", None), {})
    if isinstance(snap, dict):
        city = snap.get("city")
        province = snap.get("province")
    row = ProductionRequest(
        activity_type=(getattr(action, "action_type", None) or "ACCION"),
        activity_title=getattr(action, "title", None) or _action_type_label(getattr(action, "action_type", None)),
        artist_ids=list(getattr(action, "artist_ids", None) or []),
        activity_date=getattr(action, "start_date", None),
        city=city,
        province=province,
        linked_type="ACTION",
        linked_id=action.id,
        bag_id=getattr(action, "bag_id", None),
        status="ACTIVE",
        notes=f"Acción enviada automáticamente a Producción. {location}".strip(),
    )
    session_db.add(row)
    return row


def _production_action_row(session_db, action):
    row = _action_display_row(session_db, action)
    row["detail_url"] = url_for("action_detail_view", action_id=action.id, tab="produccion")
    return row


def _create_bag_for_action(session_db, action):
    if getattr(action, "bag", None):
        return action.bag
    existing = None
    if getattr(action, "bag_id", None):
        existing = session_db.get(WorkflowBag, action.bag_id)
    if existing:
        return existing
    artists = _artists_from_ids(session_db, getattr(action, "artist_ids", []) or [])
    bag = WorkflowBag(
        title=f"Bolsa · {getattr(action, 'title', None) or 'Acción'}",
        artist_id=artists[0].id if artists else None,
        artist_ids=[str(a.id) for a in artists],
        bag_type="ACCION",
        linked_type="ACTION",
        linked_id=action.id,
        linked_title=getattr(action, "title", None) or "Acción",
        linked_snapshot={
            "type": getattr(action, "action_type", None),
            "title": getattr(action, "title", None),
            "date": action.start_date.isoformat() if getattr(action, "start_date", None) else None,
            "artist": _artist_label_from_rows(artists),
            "location": _action_location(action),
        },
        start_date=getattr(action, "start_date", None),
        end_date=getattr(action, "end_date", None) or getattr(action, "start_date", None),
        status="ACTIVA",
        liquidation_status="NO_INICIADA",
    )
    session_db.add(bag)
    session_db.flush()
    action.bag_id = bag.id
    return bag


def _contract_sheet_hero_rows(concert) -> list:
    """Los datos de la CABECERA de la actividad, en el orden en que se enseñan (ficha, correo y
    formulario del promotor los pintan igual: es la misma cabecera en los tres sitios)."""
    filas = []
    if getattr(concert, "date", None):
        filas.append(("fa-calendar-day", "Fecha", concert.date.strftime("%d/%m/%Y")))
    sitio = " · ".join([x for x in [
        (getattr(getattr(concert, "venue", None), "name", None) or getattr(concert, "manual_venue_name", None) or ""),
        (getattr(getattr(concert, "venue", None), "municipality", None) or getattr(concert, "manual_municipality", None) or ""),
        (getattr(getattr(concert, "venue", None), "province", None) or getattr(concert, "manual_province", None) or ""),
    ] if str(x or "").strip()])
    if sitio:
        filas.append(("fa-location-dot", "Recinto", sitio))
    if getattr(concert, "festival_name", None):
        filas.append(("fa-star", "Festival", concert.festival_name))
    if getattr(concert, "no_capacity", False):
        filas.append(("fa-people-group", "Aforo", "Libre"))
    elif getattr(concert, "capacity", None):
        filas.append(("fa-people-group", "Aforo", format_thousands(concert.capacity)))
    if getattr(concert, "show_time", None):
        filas.append(("fa-clock", "Hora", str(concert.show_time)[:5]))
    return filas


