@app.post("/integraciones/pleo/<company_id>/sincronizar", endpoint="pleo_account_sync")
@admin_required
def pleo_account_sync(company_id):
    """Sondea ahora una empresa. Con `full=1` usa el histórico configurado en vez de la ventana."""
    if not is_master():
        return forbid("Solo dirección puede configurar las integraciones.")
    session_db = db()
    try:
        comp, acc = _pleo_get_or_create_account(session_db, company_id)
        if comp is None:
            flash("Empresa no encontrada.", "warning")
            return _pleo_back()
        session_db.commit()
        full = (request.form.get("full") == "1")
        since = (acc.backfill_from if full else None)
        with _pleo_pg_lock("pleo:%s" % acc.id) as got:
            if not got:
                flash("Pleo · %s: ya se está sincronizando en este momento." % (comp.name or "empresa"), "info")
                return _pleo_back()
            stats = _pleo_sync_account(session_db, acc, since=since)
            acc.last_sync_at = _now_madrid()
            acc.last_sync_ok = True
            acc.last_error = None
            acc.last_stats = stats
            acc.updated_at = _now_madrid()
            session_db.commit()
        msg = ("%s gastos revisados · %s nuevos · %s actualizados · %s justificantes"
               % (stats.get("seen", 0), stats.get("created", 0), stats.get("updated", 0), stats.get("receipts", 0)))
        if stats.get("orphans"):
            msg += " · ⚠ %s sin dueño (vincula a esas personas más abajo)" % stats["orphans"]
        flash("Pleo · %s: %s" % (comp.name or "empresa", msg), "success")
    except Exception as exc:
        session_db.rollback()
        try:
            comp2, acc2 = _pleo_get_or_create_account(session_db, company_id)
            if acc2 is not None:
                acc2.last_sync_at = _now_madrid()
                acc2.last_sync_ok = False
                acc2.last_error = str(exc)[:500]
                session_db.commit()
        except Exception:
            session_db.rollback()
        flash("Pleo: %s" % exc, "danger")
    finally:
        session_db.close()
    return _pleo_back()


@app.post("/integraciones/pleo/empleado/<link_id>/vincular", endpoint="pleo_employee_link_save")
@admin_required
def pleo_employee_link_save(link_id):
    """Vincula a mano un empleado de Pleo con una persona de la app (o lo descarta).

    Al vincularlo se importan de inmediato SUS gastos, que hasta ahora quedaban sin dueño.
    """
    if not is_master():
        return forbid("Solo dirección puede configurar las integraciones.")
    session_db = db()
    try:
        link = session_db.get(PleoEmployeeLink, to_uuid(str(link_id)) or uuid.uuid4())
        if link is None:
            flash("Empleado de Pleo no encontrado.", "warning")
            return _pleo_back()
        action = (request.form.get("link_action") or "link").strip().lower()
        if action == "ignore":
            link.user_id = None
            link.match_mode = "IGNORED"
            link.updated_at = _now_madrid()
            session_db.commit()
            flash("Empleado de Pleo descartado: sus gastos no se importarán.", "info")
            return _pleo_back()
        uid = to_uuid((request.form.get("user_id") or "").strip())
        if not uid or session_db.get(User, uid) is None:
            flash("Elige a la persona con la que vincularlo.", "warning")
            return _pleo_back()
        link.user_id = uid
        link.match_mode = "MANUAL"
        link.updated_at = _now_madrid()
        session_db.commit()
        stats = {}
        try:
            stats = _pleo_import_for_link(session_db, link) or {}
            session_db.commit()
        except Exception as exc:
            session_db.rollback()
            app.logger.warning("[pleo] import tras vincular: %s", exc)
        created = int(stats.get("created") or 0)
        flash("Empleado vinculado.%s" % (" Se han importado %s gastos suyos." % created if created else ""), "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo vincular: %s" % exc, "danger")
    finally:
        session_db.close()
    return _pleo_back()


# ============================ INTEGRACIÓN CON CABIFY ============================
# Una cuenta por EMPRESA DEL GRUPO. La gente de la cuenta de empresa está en Cabify con su correo
# de esa empresa, así que el emparejamiento es por correo contra `User.email` y los «correos de
# integraciones» de la ficha — el mismo índice que ya usa Pleo (`_pleo_email_index`).
#
# La API de Cabify NO tiene webhooks de gastos ni permite filtrar por «modificado desde», así que
# se sondea con una ventana móvil de días, usuario por usuario (el listado global de ventas no dice
# de quién es cada una; el de usuario, sí).
#
# ⚠️ El esquema documentado de la API no expone un PDF por viaje: se importa el gasto con todo su
# detalle fiscal y, si algún día Cabify publica el documento, `CabifyClient.sale_receipt_url` lo
# recoge y se adjunta solo.
CABIFY_DEFAULT_WINDOW_DAYS = 45


def _cabify_client(acc):
    from cabify_utils import CabifyClient
    return CabifyClient(acc.client_id or "", acc.client_secret or "", acc.base_url or None)


def _cabify_person_name(session_db, link) -> str:
    """Nombre para el justificante: el de la ficha de la app y, si no hay, el que tiene en Cabify."""
    prof = None
    if getattr(link, "user_id", None):
        prof = (session_db.query(UserProfile)
                .filter(UserProfile.user_id == link.user_id).first())
    if prof:
        completo = " ".join([x for x in [(prof.first_name or "").strip(),
                                         (prof.last_name or "").strip()] if x]).strip()
        if completo:
            return completo
        if (prof.nick or "").strip():
            return prof.nick.strip()
    return " ".join([x for x in [(getattr(link, "first_name", "") or "").strip(),
                                 (getattr(link, "last_name", "") or "").strip()] if x]).strip()


CABIFY_FAKE_RECEIPTS_PURGE_KEY = "cabify_fake_receipts_purge_v1"
# Carpeta de Storage donde la app dejaba los PDF que se fabricaba. Todo lo que cuelgue de ahí es
# nuestro invento; una factura subida a mano vive en otra carpeta y NO se toca.
CABIFY_FAKE_RECEIPT_MARK = "/cabify/"


def _cabify_purge_fake_receipts(session_db, limit: int | None = None) -> dict:
    """Borra los PDF que la app se fabricaba y hacía pasar por justificante de Cabify.

    ⚠️ Aquellos documentos NO eran de Cabify: los generaba la propia app con los datos de la venta.
    Se quitan del gasto y se borran de Storage. Solo se tocan los `file_url` que apuntan a la
    carpeta `cabify/` de nuestro bucket: una factura que alguien subiera a mano vive en otra
    carpeta y se respeta.
    """
    out = {"revisados": 0, "borrados": 0, "storage": 0}
    q = (session_db.query(PersonalExpense)
         .filter(PersonalExpense.source == "CABIFY")
         .filter(PersonalExpense.file_url.isnot(None))
         .filter(PersonalExpense.file_url != ""))
    if limit:
        q = q.limit(int(limit))
    for row in q.all():
        url = (row.file_url or "").strip()
        out["revisados"] += 1
        if CABIFY_FAKE_RECEIPT_MARK not in url:
            continue                      # no es de los nuestros: se deja como está
        try:
            from supabase_utils import delete_object_by_url
            if delete_object_by_url(url):
                out["storage"] += 1
        except Exception:
            pass                          # que no se pueda borrar el fichero no impide desengancharlo
        row.file_url = None
        row.original_name = None
        if (row.document_type or "").upper() in ("JUSTIFICANTE", "FACTURA"):
            row.document_type = None
        out["borrados"] += 1
    session_db.commit()
    return out


def _cabify_purge_fake_receipts_bg():
    """Purga de los PDF inventados en el ARRANQUE, con marca (best-effort, una sola vez)."""
    if (_get_app_setting(CABIFY_FAKE_RECEIPTS_PURGE_KEY) or "").strip() == "done":
        return
    session_db = db()
    try:
        out = _cabify_purge_fake_receipts(session_db)
        app.logger.info("[cabify] justificantes inventados: %d revisados, %d desenganchados, "
                        "%d borrados de Storage", out["revisados"], out["borrados"], out["storage"])
        _set_app_setting(CABIFY_FAKE_RECEIPTS_PURGE_KEY, "done")
    except Exception:
        session_db.rollback()
        app.logger.exception("[cabify] no se pudieron quitar los justificantes inventados")
    finally:
        session_db.close()


def _cabify_sync_account(session_db, acc, since=None, user_ids=None) -> dict:
    """Trae los gastos de UNA cuenta de Cabify y los mete en «Mis gastos» de cada persona."""
    from cabify_utils import CabifyClient, CabifyError, parse_sale   # noqa: F401
    from sqlalchemy.exc import IntegrityError

    stats = {"users": 0, "linked": 0, "sales": 0, "created": 0, "skipped": 0, "unmatched": 0,
             "receipts": 0, "supplements": 0}
    if not acc or not acc.is_active:
        return stats
    client = _cabify_client(acc)
    hoy = today_local()
    desde = since or (hoy - timedelta(days=int(acc.sync_window_days or CABIFY_DEFAULT_WINDOW_DAYS)))
    email_index = _pleo_email_index(session_db)

    # 1) Empleados de la cuenta → filas de enlace, emparejando por correo.
    enlaces = {}
    for row in client.users(state="active"):
        cid = str(row.get("id") or "").strip()
        if not cid:
            continue
        stats["users"] += 1
        email = _pleo_norm_email(row.get("email"))
        link = (session_db.query(CabifyUserLink)
                .filter(CabifyUserLink.account_id == acc.id,
                        CabifyUserLink.cabify_user_id == cid).first())
        if link is None:
            link = CabifyUserLink(account_id=acc.id, cabify_user_id=cid)
            session_db.add(link)
        link.email = email or link.email
        link.first_name = (row.get("name") or "").strip() or link.first_name
        link.last_name = (row.get("surname") or "").strip() or link.last_name
        link.last_seen_at = datetime.now(TZ_MADRID)
        # Solo se auto-empareja lo que no se haya tocado a mano ni descartado.
        if (link.match_mode or "NONE").upper() in ("NONE", "AUTO_EMAIL"):
            uid = email_index.get(email) if email else None
            link.user_id = uid
            link.match_mode = "AUTO_EMAIL" if uid else "NONE"
        if link.user_id:
            stats["linked"] += 1
            enlaces[cid] = link
        elif (link.match_mode or "").upper() != "IGNORED":
            stats["unmatched"] += 1
    session_db.flush()

    # 2) Gastos de cada persona vinculada.
    objetivo = {k: v for k, v in enlaces.items() if not user_ids or k in set(user_ids)}
    empresa = getattr(acc, "company", None) or session_db.get(GroupCompany, acc.group_company_id)
    for cid, link in objetivo.items():
        quien = _cabify_person_name(session_db, link)
        # Un VIAJE puede generar VARIAS ventas (el trayecto y sus suplementos: espera, peaje,
        # limpieza…). Se agrupan por viaje para que en «Mis gastos» salga UNA línea con el total,
        # no cuatro sueltas. La venta «principal» es la que trae el trayecto.
        por_viaje: dict = {}
        for venta in client.user_sales(cid, desde, hoy, acc.currency or "EUR"):
            datos = parse_sale(venta)
            if not datos["code"]:
                continue
            stats["sales"] += 1
            clave = datos["journey_id"] or ("venta:" + datos["code"])
            grupo = por_viaje.setdefault(clave, {"principal": None, "ventas": []})
            grupo["ventas"].append(datos)
            if grupo["principal"] is None or (not datos["is_supplement"] and not datos["is_rectification"]
                                              and grupo["principal"]["is_supplement"]):
                if not datos["is_supplement"] or grupo["principal"] is None:
                    grupo["principal"] = datos

        for clave, grupo in por_viaje.items():
            principal = grupo["principal"] or grupo["ventas"][0]
            codigos = [v["code"] for v in grupo["ventas"]]
            journey = principal["journey_id"] or ""
            bruto = sum((v["amount_gross"] for v in grupo["ventas"]), Decimal("0"))
            neto = sum((v["amount_net"] for v in grupo["ventas"]), Decimal("0"))
            iva = sum((v["amount_tax"] for v in grupo["ventas"]), Decimal("0"))
            datos = dict(principal)
            datos.update({"amount_gross": bruto, "amount_net": neto, "amount_tax": iva,
                          "supplements": len([v for v in grupo["ventas"] if v["is_supplement"]])})

            # ¿Ya está? Se busca por VIAJE (para poder engancharle suplementos que lleguen después)
            # y, si no, por el código de la venta principal.
            existe = None
            if journey:
                existe = (session_db.query(PersonalExpense)
                          .filter(PersonalExpense.cabify_journey_id == journey).first())
            if existe is None:
                existe = (session_db.query(PersonalExpense)
                          .filter(PersonalExpense.cabify_sale_code.in_(codigos)).first())
            if existe is not None:
                stats["skipped"] += 1
                cambiado = False
                # Suplementos que aún no se habían sumado (la lista de códigos evita sumar dos veces).
                aplicados = set(getattr(existe, "cabify_sale_codes", None) or [])
                if not aplicados:
                    aplicados = {existe.cabify_sale_code} if existe.cabify_sale_code else set()
                nuevos = [v for v in grupo["ventas"] if v["code"] not in aplicados]
                if nuevos and existe.status in ("PENDING", "IN_BAG"):
                    existe.amount_gross = _money_or_zero(existe.amount_gross) + sum(
                        (v["amount_gross"] for v in nuevos), Decimal("0"))
                    existe.amount_net = _money_or_zero(existe.amount_net) + sum(
                        (v["amount_net"] for v in nuevos), Decimal("0"))
                    existe.amount_tax = _money_or_zero(existe.amount_tax) + sum(
                        (v["amount_tax"] for v in nuevos), Decimal("0"))
                    aplicados.update(v["code"] for v in nuevos)
                    existe.cabify_sale_codes = sorted(aplicados)
                    existe.concept = datos["concept"]
                    cambiado = True
                    stats["supplements"] += len(nuevos)
                elif nuevos:
                    existe.sync_warning = ("Este viaje tiene suplementos posteriores por "
                                           + format_eur(sum((v["amount_gross"] for v in nuevos), Decimal("0")))
                                           + " que no se han sumado porque el gasto ya estaba asignado.")
                    cambiado = True
                if journey and not (existe.cabify_journey_id or ""):
                    existe.cabify_journey_id = journey
                    cambiado = True
                # Los viajes que se importaron sin justificante (o cuyo PDF falló) lo reciben ahora:
                # así ningún gasto de Cabify se queda con el semáforo de factura en rojo.
                # Si Cabify llega a servir el recibo del viaje, se adjunta ESE. La app NO fabrica
                # ningún documento: un PDF hecho por nosotros no es el justificante de Cabify.
                if not (existe.file_url or "").strip() and (datos["receipt_url"] or "").strip():
                    existe.file_url = datos["receipt_url"].strip()
                    existe.document_type = "FACTURA"
                    stats["receipts"] += 1
                continue

            # Solo se adjunta el documento que dé CABIFY. Su API no lo expone hoy (verificado en el
            # índice completo de su referencia: no hay ningún endpoint de recibo en PDF), así que el
            # gasto entra SIN factura y quien lo tenga la sube desde «Mis gastos», o pide que se
            # acepte sin ella. Antes se fabricaba un PDF propio: eso no es un justificante.
            justificante = (datos["receipt_url"] or "").strip()
            if justificante:
                stats["receipts"] += 1
            fecha = hoy
            for candidata in (datos.get("trip_date"), datos.get("invoice_date")):
                try:
                    if candidata:
                        fecha = date.fromisoformat(str(candidata)[:10])
                        break
                except ValueError:
                    continue
            try:
                with session_db.begin_nested():
                    session_db.add(PersonalExpense(
                        user_id=link.user_id,
                        source="CABIFY",
                        cabify_sale_code=principal["code"],
                        cabify_journey_id=(journey or None),
                        cabify_sale_codes=sorted(set(codigos)),
                        concept=datos["concept"],
                        provider_name="Cabify",
                        expense_date=fecha,
                        amount_net=datos["amount_net"],
                        amount_gross=datos["amount_gross"],
                        amount_tax=datos["amount_tax"],
                        currency=datos["currency"],
                        invoice_number=principal["code"],
                        document_type=("FACTURA" if justificante else None),
                        file_url=(justificante or None),
                        # La etiqueta del viaje (charge code) se guarda como etiqueta del gasto:
                        # es lo que dice a qué actividad iba, y se pinta igual que las de Pleo.
                        pleo_tags=([{"group": "", "value": datos["charge_code"]}]
                                   if datos.get("charge_code") else []),
                        status="PENDING",
                    ))
                stats["created"] += 1
            except IntegrityError:
                # Ya existía (lo impide el UNIQUE). ⚠️ NO se llama a session_db.rollback(): el
                # savepoint lo deshace ya el `with begin_nested()`, y un rollback aquí tiraría la
                # transacción ENTERA (todo lo importado antes en este sondeo). Igual que en Pleo.
                stats["skipped"] += 1

    acc.last_sync_at = datetime.now(TZ_MADRID)
    acc.last_sync_ok = True
    acc.last_error = None
    acc.last_stats = stats
    if acc.backfill_from and (not acc.backfill_done_from or acc.backfill_done_from > desde):
        acc.backfill_done_from = desde
    session_db.commit()
    return stats


def _cabify_sync_all(window_days: int | None = None) -> dict:
    """Sondea TODAS las cuentas activas de Cabify. Cada empresa por su lado; si una falla, sigue."""
    out = {"accounts": 0, "created": 0, "errors": []}
    session_db = db()
    try:
        cuentas = session_db.query(CabifyAccount).filter(CabifyAccount.is_active.is_(True)).all()
        for acc in cuentas:
            with _pleo_pg_lock(f"cabify:{acc.id}") as libre:
                if not libre:
                    continue
                out["accounts"] += 1
                try:
                    desde = None
                    if window_days:
                        desde = today_local() - timedelta(days=int(window_days))
                    stats = _cabify_sync_account(session_db, acc, since=desde)
                    out["created"] += int(stats.get("created") or 0)
                except Exception as exc:
                    session_db.rollback()
                    acc.last_sync_at = datetime.now(TZ_MADRID)
                    acc.last_sync_ok = False
                    acc.last_error = str(exc)[:500]
                    session_db.commit()
                    out["errors"].append({"company_id": str(acc.group_company_id), "error": str(exc)[:200]})
        return out
    finally:
        session_db.close()


def _cabify_account_rows(session_db) -> list:
    """Una fila por EMPRESA DEL GRUPO para la pestaña Cabify de Integraciones."""
    from cabify_utils import SANDBOX_BASE_URL
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    accounts = {str(a.group_company_id): a for a in session_db.query(CabifyAccount).all()}
    people = {str(uid): nick for uid, nick in session_db.query(UserProfile.user_id, UserProfile.nick).all()}
    rows = []
    for comp in companies:
        acc = accounts.get(str(comp.id))
        usuarios, pendientes, total_gastos = [], 0, 0
        if acc is not None:
            for l in (session_db.query(CabifyUserLink)
                      .filter(CabifyUserLink.account_id == acc.id)
                      .order_by(CabifyUserLink.email.asc().nullslast()).all()):
                mode = (l.match_mode or "NONE").upper()
                if not l.user_id and mode != "IGNORED":
                    pendientes += 1
                usuarios.append({
                    "id": str(l.id), "email": (l.email or ""),
                    "name": " ".join([x for x in [(l.first_name or ""), (l.last_name or "")] if x]).strip(),
                    "user_id": (str(l.user_id) if l.user_id else ""),
                    "user_nick": people.get(str(l.user_id), "") if l.user_id else "",
                    "mode": mode,
                })
            total_gastos = (session_db.query(func.count(PersonalExpense.id))
                            .filter(PersonalExpense.source == "CABIFY",
                                    PersonalExpense.user_id.in_(
                                        [to_uuid(u["user_id"]) for u in usuarios if u["user_id"]] or [uuid.uuid4()]
                                    )).scalar()) or 0
        rows.append({
            "company": comp, "account": acc,
            "base_url": (getattr(acc, "base_url", None) or SANDBOX_BASE_URL),
            "users": usuarios, "pending_links": pendientes, "expenses": total_gastos,
        })
    return rows


@app.post('/integraciones/cabify/cuenta', endpoint='cabify_account_save')
@admin_required
def cabify_account_save():
    """Guarda la credencial de Cabify de UNA empresa del grupo."""
    if not is_master():
        flash("Solo dirección puede configurar las integraciones.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        cid = to_uuid(request.form.get("group_company_id") or "")
        comp = session_db.get(GroupCompany, cid) if cid else None
        if not comp:
            flash("Empresa no válida.", "warning")
            return redirect(url_for("integrations_view", tab="cabify"))
        acc = (session_db.query(CabifyAccount)
               .filter(CabifyAccount.group_company_id == comp.id).first())
        if acc is None:
            acc = CabifyAccount(group_company_id=comp.id)
            session_db.add(acc)
        acc.base_url = (request.form.get("base_url") or "").strip() or None
        acc.client_id = (request.form.get("client_id") or "").strip() or None
        # El secreto solo se pisa si escriben uno nuevo (en pantalla va enmascarado).
        nuevo_secreto = (request.form.get("client_secret") or "").strip()
        if nuevo_secreto and not nuevo_secreto.startswith("•"):
            acc.client_secret = nuevo_secreto
        acc.currency = (request.form.get("currency") or "EUR").strip().upper()[:3] or "EUR"
        acc.is_active = _truthy(request.form.get("is_active"))
        try:
            acc.sync_window_days = max(int(request.form.get("sync_window_days") or CABIFY_DEFAULT_WINDOW_DAYS), 1)
        except (TypeError, ValueError):
            acc.sync_window_days = CABIFY_DEFAULT_WINDOW_DAYS
        acc.backfill_from = parse_optional_date(request.form.get("backfill_from"))
        acc.updated_at = datetime.now(TZ_MADRID)
        session_db.commit()
        flash(f"Cuenta de Cabify de {comp.name} guardada.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo guardar la cuenta de Cabify: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.post('/integraciones/cabify/<company_id>/probar', endpoint='cabify_account_test')
@admin_required
def cabify_account_test(company_id):
    """Comprueba que las credenciales valen (pide la primera página de usuarios)."""
    if not is_master():
        return jsonify({"ok": False, "error": "Solo dirección."}), 403
    session_db = db()
    try:
        acc = (session_db.query(CabifyAccount)
               .filter(CabifyAccount.group_company_id == to_uuid(company_id)).first())
        if not acc:
            return jsonify({"ok": False, "error": "Esta empresa aún no tiene cuenta de Cabify."}), 404
        # La URL de producción no la publica Cabify: se prueba la configurada y, si no responde, las
        # candidatas conocidas. La que funcione se guarda, para que no haya que adivinarla.
        from cabify_utils import find_working_base_url
        try:
            base, info = find_working_base_url(acc.client_id or "", acc.client_secret or "", acc.base_url)
        except Exception as exc:
            return jsonify({"ok": False, "error": str(exc)})
        cambiada = (base or "").rstrip("/") != (acc.base_url or "").rstrip("/")
        if cambiada:
            acc.base_url = base
            acc.updated_at = datetime.now(TZ_MADRID)
            session_db.commit()
        return jsonify({"ok": True, "base_url": base, "base_url_changed": cambiada, **info})
    finally:
        session_db.close()


@app.post('/integraciones/cabify/<company_id>/sincronizar', endpoint='cabify_account_sync')
@admin_required
def cabify_account_sync(company_id):
    """Sondeo manual de una cuenta desde Integraciones."""
    if not is_master():
        flash("Solo dirección puede sincronizar.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        acc = (session_db.query(CabifyAccount)
               .filter(CabifyAccount.group_company_id == to_uuid(company_id)).first())
        if not acc:
            flash("Esta empresa aún no tiene cuenta de Cabify.", "warning")
            return redirect(url_for("integrations_view", tab="cabify"))
        stats = _cabify_sync_account(session_db, acc)
        aviso = (f"Cabify: {stats.get('created', 0)} gasto(s) nuevo(s) · "
                 f"{stats.get('receipts', 0)} justificante(s) adjuntado(s) · "
                 f"{stats.get('linked', 0)} persona(s) vinculada(s) · "
                 f"{stats.get('unmatched', 0)} sin emparejar.")
        if stats.get("supplements"):
            aviso += f" Se sumaron {stats['supplements']} suplemento(s) a su viaje."
        flash(aviso, "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo sincronizar con Cabify: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.post('/integraciones/cabify/justificantes', endpoint='cabify_purge_fake_receipts')
@admin_required
def cabify_purge_fake_receipts():
    """Quita los PDF que la app se fabricaba y hacía pasar por justificante de Cabify.

    Los borra de Storage y desengancha el gasto, para que el semáforo diga la verdad: ese viaje NO
    tiene todavía su factura. Solo toca los ficheros que generó la app; una factura subida a mano se
    respeta."""
    if not is_master():
        flash("Solo dirección puede hacerlo.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        out = _cabify_purge_fake_receipts(session_db)
        if out["borrados"]:
            flash(f"Cabify: se han quitado {out['borrados']} justificante(s) que generaba la app "
                  f"({out['storage']} borrado(s) también del almacenamiento). Esos viajes quedan "
                  "sin factura, que es lo que son.", "success")
        else:
            flash("Cabify: no queda ningún justificante generado por la app.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudieron quitar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.post('/integraciones/cabify/enlace/<link_id>', endpoint='cabify_user_link_save')
@admin_required
def cabify_user_link_save(link_id):
    """Vincula a mano un usuario de Cabify con una persona de la app (o lo descarta).

    Al vincularlo se importan sus gastos en el momento, sin esperar al siguiente sondeo.
    """
    if not is_master():
        flash("Solo dirección puede tocar los enlaces.", "warning")
        return redirect(url_for("integrations_view", tab="cabify"))
    session_db = db()
    try:
        link = session_db.get(CabifyUserLink, to_uuid(link_id) or uuid.uuid4())
        if not link:
            abort(404)
        accion = (request.form.get("action") or "link").strip().lower()
        if accion == "ignore":
            link.user_id = None
            link.match_mode = "IGNORED"
            session_db.commit()
            flash("Usuario de Cabify descartado: sus gastos no se importarán.", "success")
            return redirect(url_for("integrations_view", tab="cabify"))
        uid = to_uuid(request.form.get("user_id") or "")
        link.user_id = uid
        link.match_mode = "MANUAL" if uid else "NONE"
        session_db.commit()
        if uid:
            acc = session_db.get(CabifyAccount, link.account_id)
            dias = max(int(getattr(acc, "sync_window_days", 0) or CABIFY_DEFAULT_WINDOW_DAYS), 180)
            desde = (getattr(acc, "backfill_from", None) or (today_local() - timedelta(days=dias)))
            stats = _cabify_sync_account(session_db, acc, since=desde, user_ids=[link.cabify_user_id])
            flash(f"Vinculado. Se han importado {stats.get('created', 0)} gasto(s) suyos.", "success")
        else:
            flash("Enlace actualizado.", "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo actualizar el enlace: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view", tab="cabify"))


@app.get("/cron/cabify/refresh", endpoint="cron_cabify_refresh")
def cron_cabify_refresh():
    """Sondeo periódico de Cabify (tarea programada externa con ?key=). Sin sesión.

    Cabify no manda webhooks de gastos, así que este cron es lo que hace que la importación sea
    automática. Recomendado cada 1-2 horas."""
    expected = (getattr(settings, "CABIFY_CRON_KEY", "") or settings.PLEO_CRON_KEY
                or settings.CHARTMETRIC_CRON_KEY or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    try:
        window = int(request.args.get("dias") or 0) or None
    except (TypeError, ValueError):
        window = None
    try:
        out = _cabify_sync_all(window_days=window)
    except Exception as exc:
        app.logger.exception("[cabify] cron falló")
        return (jsonify({"ok": False, "error": str(exc)}), 500)
    return jsonify({"ok": True, **out})


@app.get("/cron/pleo/refresh", endpoint="cron_pleo_refresh")
def cron_pleo_refresh():
    """Sondeo periódico de Pleo (tarea programada externa con ?key=). Sin sesión.

    Pleo no manda webhooks de gastos, así que este cron es lo que hace que la importación sea
    AUTOMÁTICA. Recomendado cada 30-60 minutos.
    """
    expected = (settings.PLEO_CRON_KEY or settings.CHARTMETRIC_CRON_KEY or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    try:
        window = int(request.args.get("dias") or 0) or None
    except (TypeError, ValueError):
        window = None
    try:
        out = _pleo_sync_all(window_days=window)
    except Exception as exc:
        app.logger.exception("[pleo] cron falló")
        return (jsonify({"ok": False, "error": str(exc)}), 500)
    return jsonify({"ok": True, **out})


# ===========================================================================
#  HOLDED · CONTABILIDAD (integración)
#  ------------------------------------------------------------------------
#  Cada empresa del grupo lleva su contabilidad en SU cuenta de Holded, así que la API Key va por
#  empresa (`HoldedAccount`), igual que Pleo y Cabify. Lo que se sube es cada GASTO de una bolsa:
#  las facturas como COMPRA y los tickets / gastos sin ticket como GASTO (ticket), que en Holded no
#  llevan proveedor, ni número de documento, ni desglose de IVA.
#
#  El estado contable vive en el propio gasto (`BagExpense.accounting_status`), que es lo que permite
#  enseñar la etiqueta «Contabilizado» en la bolsa y en cualquier pantalla donde salga el gasto.
# ===========================================================================

# (clave, etiqueta, clase de la pastilla, icono) — el ORDEN es el del ciclo de vida.
HOLDED_ACCOUNTING_STATES = [
    ("PENDIENTE", "Pendiente", "text-bg-secondary", "fa-hourglass-half"),
    ("SUBIDO", "Subido a Holded", "text-bg-info text-dark", "fa-cloud-arrow-up"),
    ("CONTABILIZADO", "Contabilizado", "text-bg-success", "fa-circle-check"),
    ("OMITIDO", "Omitido", "text-bg-light border text-dark", "fa-ban"),
]
ACCOUNTING_STATUS_LABELS = {k: l for k, l, _c, _i in HOLDED_ACCOUNTING_STATES}
# ⚠️ FILTRO de la pantalla que NO es un estado contable: «lo que todavía no está en Holded». En
# «Pendiente de contabilizar» todo está pendiente, así que filtrar por «Pendiente» no dice nada; lo
# que hace falta saber es qué queda por SUBIR.
ACCOUNTING_FILTER_NO_HOLDED = "SIN_HOLDED"
# Estados que sacan al gasto de «pendiente de contabilizar»: ya no hay nada que hacer con él.
ACCOUNTING_DONE_STATUSES = {"CONTABILIZADO", "OMITIDO"}


def _accounting_status_meta(status: str | None) -> tuple[str, str, str]:
    """Etiqueta, clase y icono del estado contable de un gasto."""
    st = (status or "PENDIENTE").strip().upper()
    for clave, etiqueta, clase, icono in HOLDED_ACCOUNTING_STATES:
        if clave == st:
            return etiqueta, clase, icono
    return (st or "Pendiente"), "text-bg-secondary", "fa-hourglass-half"


# ------------------------------------------------------------------ Dirección fiscal en piezas

def _fiscal_address_parts(obj) -> dict:
    """Dirección fiscal de un tercero (o de su sociedad) EN PIEZAS.

    ⚠️ Holded exige el código postal, el municipio y la provincia SEPARADOS para dar de alta al
    proveedor: con la dirección en un único cuadro de texto no se puede crear el contacto. Por eso en
    la app se piden en campos distintos y este helper es el único sitio del que se leen.
    """
    if obj is None:
        return {"address": "", "postal_code": "", "city": "", "province": "", "country": ""}
    return {
        "address": (getattr(obj, "fiscal_address", None) or "").strip(),
        "postal_code": (getattr(obj, "fiscal_postal_code", None) or "").strip(),
        "city": (getattr(obj, "fiscal_city", None) or "").strip(),
        "province": (getattr(obj, "fiscal_province", None) or "").strip(),
        "country": (getattr(obj, "fiscal_country", None) or "").strip(),
    }


def _fiscal_address_text(obj) -> str:
    """La dirección fiscal JUNTA, para mostrarla como un solo campo (que es como se lee mejor).

    La compone `address_utils`, el único sitio que sabe cómo se escribe una dirección aquí."""
    return address_utils.format_parts(_fiscal_address_parts(obj))


def _address_text(value) -> str:
    """Una dirección cualquiera (un domicilio, la de un recinto, la de un medio…) en la forma de la
    casa: «Calle, CP Municipio, Provincia, País». Global de plantilla `address_text`."""
    return address_utils.normalize(value)


def _address_parts(value) -> dict:
    """Las PIEZAS de una dirección escrita de un tirón (calle, CP, municipio, provincia, país), para
    enseñarlas por separado donde haga falta. Global de plantilla `address_parts`."""
    return address_utils.parse(value)


def _split_fiscal_address(texto: str | None) -> dict:
    """Reparte en piezas una dirección escrita de un tirón. Lo hace `address_utils`, que es el ÚNICO
    sitio que sabe cómo se escribe una dirección en la casa (y el que la vuelve a juntar)."""
    return address_utils.parse(texto)


def _intake_fiscal_parts(promoter, company=None, *, masked: bool = False) -> dict:
    """Dirección fiscal en piezas para el formulario del enlace público de alta / facturación.

    Manda la de la SOCIEDAD si la tiene; si no, la del tercero. Cuando el enlace no es de esa persona
    (`masked`) se enmascara la calle, pero el código postal, el municipio y la provincia se ven tal
    cual: no son un dato sensible y así se comprueba de un vistazo que están bien.
    """
    fuente = company if (company is not None and (getattr(company, "fiscal_address", None)
                                                  or getattr(company, "fiscal_postal_code", None))) else promoter
    piezas = _fiscal_parts_for_form(fuente)
    if masked and piezas["address"]:
        piezas = {**piezas, "address": _mask_value(piezas["address"], 6)}
    return piezas


def _fiscal_parts_for_form(obj) -> dict:
    """Las piezas con las que se rellena un formulario.

    Si lo guardado es de antes (todo en el cuadro de la calle), se reparte al vuelo para que el
    formulario salga ya con el código postal y el municipio en su sitio y quien lo abra solo tenga
    que revisarlo. Lo repartido NO se guarda hasta que se envía el formulario.
    """
    piezas = _fiscal_address_parts(obj)
    if piezas["address"] and not (piezas["postal_code"] or piezas["city"] or piezas["province"]):
        repartida = _split_fiscal_address(piezas["address"])
        repartida["country"] = piezas["country"]
        return repartida
    return piezas


def _fiscal_form_values(form, prefix: str = "") -> dict:
    """Lee del formulario la dirección fiscal en piezas.

    Acepta también el campo antiguo de un solo cuadro (`fiscal_address` con todo junto): si llega sin
    las piezas, se reparte con `_split_fiscal_address` para no perder lo que escriba la gente en un
    formulario cacheado.
    """
    def _g(nombre):
        return (form.get(prefix + nombre) or "").strip()
    piezas = {
        "address": _g("fiscal_address"),
        "postal_code": _g("fiscal_postal_code"),
        "city": _g("fiscal_city"),
        "province": _g("fiscal_province"),
        "country": _g("fiscal_country"),
    }
    if piezas["address"] and not (piezas["postal_code"] or piezas["city"] or piezas["province"]):
        repartida = _split_fiscal_address(piezas["address"])
        if repartida.get("postal_code"):
            piezas.update({k: repartida.get(k) or piezas.get(k) for k in piezas})
    return piezas


def _apply_fiscal_address(target, piezas: dict, *, only_empty: bool = False) -> None:
    """Guarda la dirección fiscal en piezas en un tercero o en su sociedad."""
    if target is None or not isinstance(piezas, dict):
        return
    for campo, clave in (("fiscal_address", "address"), ("fiscal_postal_code", "postal_code"),
                         ("fiscal_city", "city"), ("fiscal_province", "province"),
                         ("fiscal_country", "country")):
        valor = (piezas.get(clave) or "").strip() or None
        if valor is None:
            continue
        if only_empty and (getattr(target, campo, None) or "").strip():
            continue
        setattr(target, campo, valor)


# ------------------------------------------------------------------ Cuenta de Holded

def _holded_account_for_company(session_db, company_id):
    if not company_id:
        return None
    try:
        cid = to_uuid(str(company_id))
    except Exception:
        return None
    if not cid:
        return None
    return (session_db.query(HoldedAccount)
            .filter(HoldedAccount.group_company_id == cid).first())


def _accounting_company_filters(session_db, *, scope=None) -> list[dict]:
    """Las EMPRESAS DEL GRUPO para el filtro de contabilidad, con su logo y lo que tienen pendiente.

    Mismo patrón que la rejilla de artistas de Discográfica: salen todas y al pinchar una se ve solo lo
    suyo. `scope` limita el recuento a las empresas que lleva quien mira (si tiene reparto)."""
    salida = []
    try:
        pendientes = {}
        q = (session_db.query(WorkflowBag.company_id, func.count(BagExpense.id))
             .join(BagExpense, BagExpense.bag_id == WorkflowBag.id)
             .filter(BagExpense.consolidation_status.in_(BAG_CONSOLIDATED_STATUSES))
             .filter(func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE")).in_(
                 ("PENDIENTE", "SUBIDO")))
             .group_by(WorkflowBag.company_id))
        for cid, n in q.all():
            if cid:
                pendientes[str(cid)] = int(n or 0)
        permitidas = {str(x) for x in (scope or [])}
        for emp in (session_db.query(GroupCompany)
                    .order_by(func.lower(GroupCompany.name).asc()).all()):
            if permitidas and str(emp.id) not in permitidas:
                continue
            salida.append({"id": str(emp.id), "name": (emp.name or "").strip(),
                           "logo_url": (getattr(emp, "logo_url", None) or ""),
                           "pending": pendientes.get(str(emp.id), 0)})
    except Exception:
        app.logger.exception("[contabilidad] no se pudieron leer las empresas del filtro")
    return salida


def _holded_accounts_status(session_db) -> list[dict]:
    """El estado de Holded **por empresa del grupo**: si tiene clave, si está activa y qué falló la
    última vez.

    ⚠️ Es lo que hay que ver ANTES de subir nada: cada documento se contabiliza en SU empresa (una
    liquidación de royalties en PIES, un gasto de bolsa en la que promueve), así que se puede tener
    una clave buena en una empresa y ninguna —o la equivocada— en la que toca."""
    salida = []
    try:
        cuentas = {}
        for fila in session_db.query(HoldedAccount).all():
            cuentas[str(fila.group_company_id)] = fila
        for emp in (session_db.query(GroupCompany)
                    .order_by(func.lower(GroupCompany.name).asc()).all()):
            acc = cuentas.get(str(emp.id))
            clave = ((getattr(acc, "api_key", None) or "").strip() if acc else "")
            salida.append({
                "company_id": str(emp.id),
                "name": (emp.name or "").strip(),
                "logo_url": (getattr(emp, "logo_url", None) or ""),
                "has_key": bool(clave),
                "key_len": len(clave),
                "active": bool(getattr(acc, "is_active", False)) if acc else False,
                "tested_ok": (bool(acc.last_test_ok) if (acc and acc.last_test_ok is not None) else None),
                "error": ((acc.last_error or "").strip() if acc else ""),
                "ready": bool(clave and getattr(acc, "is_active", False)
                              and not (getattr(acc, "last_error", None) or "").strip()),
            })
    except Exception:
        app.logger.exception("[holded] no se pudo leer el estado de las cuentas")
    return salida


def _holded_account_diagnosis(session_db, acc, motivo: str) -> str:
    """Le pega al error de Holded **de qué cuenta** es y las pistas para arreglarlo.

    ⚠️ El mensaje de Holded («la clave no vale») no dice **de qué empresa** es la cuenta que ha
    fallado, y es lo primero que hace falta saber: una liquidación de royalties se contabiliza en
    PIES y un gasto de una bolsa en la empresa que promueve, así que se puede estar mirando una
    pantalla y fallando la cuenta de OTRA empresa (pasó de verdad).
    Además se avisa de los dos despistes que ya han ocurrido: la clave pegada en la empresa
    equivocada y la MISMA clave en dos empresas (una API Key de Holded es de UNA empresa)."""
    texto = (motivo or "").strip()
    if acc is None:
        return texto
    partes = []
    try:
        empresa = (session_db.get(GroupCompany, acc.group_company_id)
                   if getattr(acc, "group_company_id", None) else None)
        nombre = (getattr(empresa, "name", None) or "").strip()
        clave = (getattr(acc, "api_key", None) or "").strip()
        partes.append("Es la cuenta de Holded de «%s»%s."
                      % (nombre or "una empresa del grupo",
                         (" (clave de %d caracteres)" % len(clave)) if clave else " (SIN clave)"))
        cabecera = (getattr(acc, "auth_header", None) or "AUTO").upper()
        if cabecera != "AUTO":
            partes.append("La cabecera está fijada a mano (%s) y tampoco han valido las otras: "
                          "déjala en «Automática» si no estás seguro." % cabecera)
        # ¿La misma clave en dos empresas? Una API Key de Holded es de UNA empresa.
        if clave:
            otras = []
            for fila in session_db.query(HoldedAccount).all():
                if str(fila.id) == str(acc.id):
                    continue
                if (fila.api_key or "").strip() == clave:
                    otra = (session_db.get(GroupCompany, fila.group_company_id)
                            if fila.group_company_id else None)
                    otras.append((getattr(otra, "name", None) or "otra empresa"))
            if otras:
                partes.append("⚠️ Esa MISMA clave está también en %s: una API Key de Holded es de UNA "
                              "empresa, así que una de las dos está mal." % ", ".join(otras))
        # ¿Hay otra empresa cuya clave SÍ ha funcionado? Entonces es que se pegó donde no toca.
        buenas = []
        for fila in session_db.query(HoldedAccount).all():
            if str(fila.id) == str(acc.id) or not (fila.api_key or "").strip():
                continue
            if (fila.endpoints or {}).get("auth_header") and not (fila.last_error or "").strip():
                otra = (session_db.get(GroupCompany, fila.group_company_id)
                        if fila.group_company_id else None)
                buenas.append((getattr(otra, "name", None) or "otra empresa"))
        if buenas:
            partes.append("En %s sí hay una clave que funciona: comprueba que no has pegado la de "
                          "esa empresa aquí (o la de aquí allí)." % ", ".join(buenas))
    except Exception:
        app.logger.exception("[holded] no se pudo montar el diagnóstico de la cuenta")
    return " ".join([texto] + partes).strip()


def _holded_remember_error(acc, motivo: str) -> None:
    """Apunta en la cuenta el último error (lo enseña Integraciones → Holded)."""
    if acc is None:
        return
    try:
        acc.last_error = (motivo or "")[:600] or None
        acc.updated_at = _now_madrid()
    except Exception:
        pass


def _holded_client_for_account(acc):
    """Cliente de Holded de una cuenta. Lanza HoldedError con el motivo si no se puede usar.

    Se REUTILIZA el mismo cliente en toda la petición (cacheado en `g`): así, al subir 50 gastos del
    mismo proveedor, el contacto se busca en Holded UNA vez y no cincuenta (el cliente guarda los
    contactos que ya ha resuelto).
    """
    from holded_utils import HoldedClient, HoldedError
    if acc is None:
        raise HoldedError("Esta empresa del grupo no tiene cuenta de Holded configurada.")
    if not (acc.api_key or "").strip():
        raise HoldedError("Falta la API Key de Holded de esta empresa (Integraciones → Holded).")
    if not acc.is_active:
        raise HoldedError("La integración con Holded de esta empresa está desactivada.")
    clave = str(getattr(acc, "id", "") or "")
    almacen = None
    try:
        almacen = getattr(g, "_holded_clients", None)
        if almacen is None:
            almacen = {}
            g._holded_clients = almacen
    except Exception:
        almacen = None          # fuera de contexto de petición (cron, scripts): sin caché
    if almacen is not None and clave and clave in almacen:
        return almacen[clave]
    client = HoldedClient(acc.api_key, endpoints=dict(acc.endpoints or {}),
                         auth_header=(getattr(acc, "auth_header", None) or "AUTO"),
                         base=((getattr(acc, "base_url", None) or "").strip() or None))
    if almacen is not None and clave:
        almacen[clave] = client
    return client


def _holded_persist_client_state(acc, client) -> None:
    """Guarda las rutas que el cliente ha descubierto (adjuntos, formas de pago)."""
    if acc is None or client is None:
        return
    if getattr(client, "endpoints_changed", False):
        acc.endpoints = dict(client.endpoints or {})
        acc.updated_at = _now_madrid()


def _holded_account_rows(session_db) -> list:
    """Una fila por EMPRESA DEL GRUPO para la pestaña Holded de Integraciones."""
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    accounts = {str(a.group_company_id): a for a in session_db.query(HoldedAccount).all()}
    # Cuántos gastos hay pendientes de subir por empresa (es el trabajo que tiene esa cuenta).
    pendientes = {}
    try:
        for cid, n in (session_db.query(WorkflowBag.company_id, func.count(BagExpense.id))
                       .join(BagExpense, BagExpense.bag_id == WorkflowBag.id)
                       .filter(BagExpense.status != "ELIMINADO",
                               BagExpense.consolidation_status.in_(list(BAG_CONSOLIDATED_STATUSES)),
                               func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE")) == "PENDIENTE")
                       .group_by(WorkflowBag.company_id).all()):
            pendientes[str(cid or "")] = int(n or 0)
    except Exception:
        pendientes = {}
    filas = []
    for comp in companies:
        acc = accounts.get(str(comp.id))
        clave = (acc.api_key or "") if acc is not None else ""
        filas.append({
            "company_id": str(comp.id),
            "company_name": comp.name,
            "company_logo": (getattr(comp, "logo_url", None) or ""),
            "slug": _company_slug(comp.name or "empresa"),
            "account": acc,
            "has_key": bool(clave.strip()),
            "key_hint": ("…" + clave.strip()[-4:]) if clave.strip() else "",
            "is_active": bool(getattr(acc, "is_active", False)),
            "invoice_doc_type": (getattr(acc, "invoice_doc_type", None) or "purchase"),
            "ticket_doc_type": (getattr(acc, "ticket_doc_type", None) or "dailyexpense"),
            "payment_methods": dict(getattr(acc, "payment_methods", None) or {}),
            "auth_header": (getattr(acc, "auth_header", None) or "AUTO"),
            "base_url": (getattr(acc, "base_url", None) or ""),
            # Con qué cabecera ha entrado de verdad (lo que aprendió el cliente) y si es un token nuevo.
            "auth_used": ((getattr(acc, "endpoints", None) or {}).get("auth_header") or ""),
            # Qué API de Holded se está usando (la v2 es la de los tokens Bearer).
            "api_version": ((getattr(acc, "endpoints", None) or {}).get("api_version") or ""),
            "is_token": bool(clave.strip() and clave.strip().startswith(("pat_", "sk_", "pt_"))),
            "last_test": (_et_fmt_dt(acc.last_test_at) if acc is not None and acc.last_test_at else ""),
            "last_test_ok": (getattr(acc, "last_test_ok", None) if acc is not None else None),
            "last_sync": (_et_fmt_dt(acc.last_sync_at) if acc is not None and acc.last_sync_at else ""),
            "last_error": (getattr(acc, "last_error", None) or "") if acc is not None else "",
            # Lo que se probó en el último diagnóstico (intento a intento).
            "diagnose": ((getattr(acc, "last_stats", None) or {}).get("diagnose") or {}) if acc is not None else {},
            "pending": pendientes.get(str(comp.id), 0),
        })
    return filas


def _holded_configured_any(session_db) -> bool:
    try:
        return bool(session_db.query(HoldedAccount)
                    .filter(HoldedAccount.is_active.is_(True),
                            HoldedAccount.api_key.isnot(None)).count())
    except Exception:
        return False


# ---------------------------------------------------------------------------------------------
# Integraciones · SMS (la pasarela de avisos por mensaje de texto)
# ---------------------------------------------------------------------------------------------
# ═════════════════════════════════════════════════════════════════════════════
# CORREO · por qué los avisos acaban en spam y cómo comprobarlo
#
# Un correo con el remitente «@33producciones.es» que sale por un servidor que ese dominio NO
# autoriza es, para Gmail y para Outlook, un correo falsificado: va a spam por definición. Lo que
# decide que llegue son TRES registros DNS del dominio, no el código:
#   · SPF    — «estos servidores pueden mandar en mi nombre».
#   · DKIM   — firma con una clave del dominio (la pone el proveedor de correo).
#   · DMARC  — qué hacer con lo que no cuadre, y a dónde mandar los informes.
# Esta pestaña enseña con qué está configurado, deja mandar una prueba y dice exactamente qué
# registros hay que añadir: lo único que la app puede hacer por su cuenta ya está hecho (un correo
# por persona, versión de texto de verdad, Date y Message-ID, y el nombre del remitente).
# ═════════════════════════════════════════════════════════════════════════════

def _smtp_settings() -> dict:
    """Lo que hay configurado para mandar correo (SIN la contraseña, que no se enseña nunca)."""
    host = (os.getenv("SMTP_HOST") or "").strip()
    usuario = (os.getenv("SMTP_USERNAME") or "").strip()
    remitente = (os.getenv("SMTP_FROM_EMAIL") or usuario or "").strip()
    dominio = remitente.split("@", 1)[1].strip().lower() if "@" in remitente else ""
    ssl = _truthy(os.getenv("SMTP_SSL"))
    return {
        "configured": bool(host),
        "host": host,
        "port": (os.getenv("SMTP_PORT") or "587").strip(),
        "user": usuario,
        "from_email": remitente,
        "from_name": (os.getenv("SMTP_FROM_NAME") or "33 Producciones").strip(),
        "from_domain": dominio,
        "security": ("SSL" if ssl else ("STARTTLS" if (os.getenv("SMTP_TLS") is None or _truthy(os.getenv("SMTP_TLS"))) else "sin cifrar")),
        "has_password": bool((os.getenv("SMTP_PASSWORD") or "").strip()),
        # ⚠️ La pista más útil: ¿el remitente es del MISMO dominio que la cuenta con la que se
        # autentica? Si no, SPF/DKIM no pueden cuadrar y el correo va a spam.
        "aligned": bool(dominio and "@" in usuario and usuario.split("@", 1)[1].strip().lower() == dominio),
    }


@app.post("/integraciones/correo/probar", endpoint="smtp_send_test")
@admin_required
def smtp_send_test():
    """Manda un correo de prueba (para ver si llega y, sobre todo, si llega a la bandeja o a spam)."""
    if not is_master():
        flash("Solo dirección puede configurar las integraciones.", "warning")
        return redirect(url_for("integrations_view") + "#tab-correo")
    destino = (request.form.get("email") or "").strip()
    if not destino or "@" not in destino:
        flash("Escribe el correo al que mandar la prueba.", "warning")
        return redirect(url_for("integrations_view") + "#tab-correo")
    cfg = _smtp_settings()
    html = (
        '<div style="font-family:Arial,Helvetica,sans-serif;color:#212529;max-width:560px;">'
        '<h2 style="text-align:center;">Correo de prueba</h2>'
        '<p>Si estás leyendo esto, los avisos de la app salen bien desde <strong>%s</strong>.</p>'
        '<p>Comprueba dos cosas: que ha llegado a la <strong>bandeja de entrada</strong> (no a spam) '
        'y que el remitente se ve como «%s».</p>'
        '<p style="color:#6b7280;font-size:13px;">Enviado desde %s.</p></div>'
    ) % (escape(cfg["from_email"] or "—"), escape(cfg["from_name"]), escape(cfg["host"] or "—"))
    ok, error = _send_optional_email([destino], "Correo de prueba · 33 Producciones", html)
    if ok:
        flash("Correo de prueba enviado a %s. Mira si ha llegado a la bandeja o a spam.%s"
              % (destino, (" ⚠️ " + error) if error else ""), "success")
    else:
        flash("No se pudo enviar: %s" % (error or "sin detalle"), "danger")
    return redirect(url_for("integrations_view") + "#tab-correo")


def _sms_admin_guard():
    """Configurar integraciones es de DIRECCIÓN. Devuelve la respuesta si no toca, o None."""
    if not is_master():
        flash("Solo dirección puede configurar las integraciones.", "warning")
        return redirect(url_for("integrations_view") + "#tab-sms")
    return None


@app.post("/integraciones/sms/guardar", endpoint="sms_account_save")
@admin_required
def sms_account_save():
    """Guarda la cuenta de la pasarela de SMS (una sola para toda la casa)."""
    fuera = _sms_admin_guard()
    if fuera is not None:
        return fuera
    session_db = db()
    try:
        acc = _sms_account(session_db, create=True)
        prov = (request.form.get("provider") or "").strip().upper()
        acc.provider = prov if prov in sms_utils.PROVIDER_KEYS else "LABSMOBILE"
        # ⚠️ La clave se limpia al guardarla: al copiarla se arrastran espacios, comillas o el propio
        # «token:» delante, y la pasarela contesta «credencial no válida» (pasó con Holded).
        usuario = sms_utils.clean_api_key(request.form.get("api_user"))
        token = sms_utils.clean_api_key(request.form.get("api_token"))
        if _truthy(request.form.get("clear_key")):
            acc.api_user, acc.api_token, acc.is_active = None, None, False
        else:
            if usuario:
                acc.api_user = usuario
            if token and not token.startswith("•"):
                acc.api_token = token
        acc.account_ref = sms_utils.clean_api_key(request.form.get("account_ref")) or None
        # ⚠️ EL REMITENTE SE PUEDE DEJAR VACÍO a propósito: en España los remitentes alfanuméricos
        # («33PROD») hay que registrarlos, y mientras no lo estén las operadoras BLOQUEAN el mensaje
        # (llega a la pasarela y sale como error). Sin remitente, la pasarela usa su número
        # compartido y el SMS sale: es la forma de comprobar si el problema era ese.
        if "sender" in request.form:
            remitente = (request.form.get("sender") or "").strip()
            if not remitente:
                acc.sender = None
            else:
                vale, motivo = sms_utils.sender_is_valid(remitente)
                if not vale:
                    flash(motivo, "warning")
                    return redirect(url_for("integrations_view") + "#tab-sms")
                acc.sender = remitente
        # DOMINIO CORTO de los enlaces: funciona en cuanto se guarda (nada de tocar Render). Se
        # admite pegarlo como sea y se queda el host; si lo pegado no es un dominio, se avisa.
        if "short_domain" in request.form:
            crudo = (request.form.get("short_domain") or "").strip()
            limpio = _short_domain_clean(crudo)
            if crudo and not limpio:
                flash("«%s» no parece un dominio (algo como «33p.es»)." % crudo[:40], "warning")
                return redirect(url_for("integrations_view") + "#tab-sms")
            acc.short_domain = limpio or None
        acc.avoid_accents = _truthy(request.form.get("avoid_accents"))
        try:
            acc.max_segments = max(0, min(6, int(request.form.get("max_segments") or 2)))
        except (TypeError, ValueError):
            acc.max_segments = 2
        try:
            acc.daily_cap = max(0, int(request.form.get("daily_cap") or 0))
        except (TypeError, ValueError):
            acc.daily_cap = 200
        acc.is_active = (_truthy(request.form.get("is_active"))
                         and bool((acc.api_user or "").strip()) and bool((acc.api_token or "").strip()))
        # Si se cambia la credencial, lo comprobado antes ya no vale.
        if token or usuario:
            acc.last_check_at, acc.last_check_ok, acc.last_check_info = None, None, None
        acc.updated_at = _now_madrid()
        session_db.commit()
        pista = ""
        if (acc.api_token or "").strip():
            pista = " Clave guardada: %d caracteres, termina en «%s»." % (
                len(acc.api_token), acc.api_token[-4:])
        flash("Cuenta de SMS guardada.%s" % pista, "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo guardar la cuenta de SMS: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view") + "#tab-sms")


