def _sms_panel_context(session_db) -> dict:
    """Lo que necesita la pestaña de SMS: la cuenta, su estado, los avisos y los últimos envíos."""
    acc = _sms_account(session_db)
    enviados_hoy = _sms_sent_today(session_db)
    filas = []
    try:
        for m in (session_db.query(SmsMessage)
                  .order_by(SmsMessage.created_at.desc()).limit(30).all()):
            filas.append({
                "when": (m.created_at.astimezone(TZ_MADRID).strftime("%d/%m/%Y %H:%M")
                         if m.created_at else ""),
                "phone": m.phone, "body": (m.body or ""), "segments": int(m.segments or 1),
                "status": (m.status or ""), "error": (m.error or ""),
                "ref": (m.provider_ref or ""),
                "kind": SMS_NOTICE_LABELS.get((m.kind or "").upper(), (m.kind or "")),
                "nick": (m.nick or ""),
            })
    except Exception:
        app.logger.exception("[sms] no se pudo leer el registro de envíos")
    ejemplo = ""
    try:
        ejemplo = "%s/l/aB3xY9" % _short_link_base().rstrip("/")
    except Exception:
        ejemplo = ""
    return {
        "sms_account": acc,
        "sms_short_example": ejemplo,
        "sms_status": _sms_status(session_db),
        "sms_configured": _sms_configured(session_db),
        "sms_providers": sms_utils.PROVIDERS,
        "sms_notice_kinds": SMS_NOTICE_KINDS,
        "sms_selected_kinds": [str(x).strip().upper() for x in (getattr(acc, "notice_kinds", None) or [])],
        "sms_sent_today": enviados_hoy,
        "sms_rows": filas,
    }


@app.post("/integraciones/holded/<company_id>/guardar", endpoint="holded_account_save")
@admin_required
def holded_account_save(company_id):
    """Guarda la API Key de Holded de UNA empresa del grupo."""
    if not is_master():
        flash("Solo dirección puede configurar las integraciones.", "warning")
        return redirect(url_for("integrations_view", tab="holded"))
    session_db = db()
    try:
        comp = session_db.get(GroupCompany, to_uuid(company_id) or uuid.uuid4())
        if comp is None:
            flash("Empresa no válida.", "warning")
            return redirect(url_for("integrations_view") + "#tab-holded")
        acc = _holded_account_for_company(session_db, comp.id)
        if acc is None:
            acc = HoldedAccount(group_company_id=comp.id)
            session_db.add(acc)
        # ⚠️ La clave se limpia al guardarla: al copiarla de Holded se arrastran espacios, saltos de
        # línea, comillas o el propio «key:» delante, y eso hace que Holded conteste «Invalid key».
        from holded_utils import clean_api_key
        nueva = clean_api_key(request.form.get("api_key"))
        if _truthy(request.form.get("clear_key")):
            acc.api_key = None
            acc.is_active = False
        elif nueva and not nueva.startswith("•"):
            acc.api_key = nueva
        acc.invoice_doc_type = (request.form.get("invoice_doc_type") or "purchase").strip() or "purchase"
        acc.ticket_doc_type = (request.form.get("ticket_doc_type") or "dailyexpense").strip() or "dailyexpense"
        # Cabecera con la que se manda la clave. AUTO = se prueban las tres y se guarda la que va;
        # se puede fijar a mano cuando Holded dice cuál usar (p. ej. «Authorization: Bearer»).
        _cab = (request.form.get("auth_header") or "AUTO").strip()
        acc.auth_header = _cab if _cab in ("AUTO", "key", "X-API-KEY", "Authorization") else "AUTO"
        # La URL base solo se toca si Holded pide otra para los tokens nuevos (vacío = la de siempre).
        _base = (request.form.get("base_url") or "").strip()
        acc.base_url = (_base.rstrip("/") if _base.lower().startswith("http") else None)
        acc.is_active = _truthy(request.form.get("is_active")) and bool((acc.api_key or "").strip())
        # Cada vez que se guarda una clave se empieza de cero: la cabecera que se hubiera «aprendido»
        # con la clave anterior no tiene por qué valer para esta (un token nuevo va con Bearer).
        if nueva and not nueva.startswith("•"):
            _eps = dict(acc.endpoints or {})
            _eps.pop("auth_header", None)
            acc.endpoints = _eps
            acc.last_error = None
            acc.last_test_ok = None
        acc.updated_at = _now_madrid()
        session_db.commit()
        pista = ""
        if (acc.api_key or "").strip():
            from holded_utils import looks_like_bearer_key
            pista = " Clave guardada: %d caracteres, termina en «%s»." % (
                len(acc.api_key), acc.api_key[-4:])
            if looks_like_bearer_key(acc.api_key):
                # Los tokens nuevos de Holded («pat_…») se mandan con Authorization: Bearer y solo
                # pueden hacer lo que se les marcó al crearlos.
                pista += (" Parece un TOKEN nuevo: se manda como «Authorization: Bearer», y en Holded "
                          "tiene que tener permiso de Contactos y de Facturas de compra / Gastos "
                          "(y Adjuntos si se sube el PDF).")
        flash("Cuenta de Holded de %s guardada.%s Pulsa «Probar conexión»." % (comp.name, pista),
              "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo guardar la cuenta de Holded: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view") + "#tab-holded")


@app.post("/integraciones/holded/<company_id>/probar", endpoint="holded_account_test")
@admin_required
def holded_account_test(company_id):
    """Comprueba la API Key, detecta el tipo de documento de los tickets y trae las formas de pago."""
    if not is_master():
        flash("Solo dirección puede configurar las integraciones.", "warning")
        return redirect(url_for("integrations_view") + "#tab-holded")
    from holded_utils import HoldedError
    session_db = db()
    try:
        acc = _holded_account_for_company(session_db, company_id)
        if acc is None or not (acc.api_key or "").strip():
            flash("Esta empresa todavía no tiene API Key de Holded.", "warning")
            return redirect(url_for("integrations_view") + "#tab-holded")
        from holded_utils import HoldedClient
        client = HoldedClient(acc.api_key, endpoints=dict(acc.endpoints or {}),
                              auth_header=(getattr(acc, "auth_header", None) or "AUTO"))
        try:
            client.test()
            # El tipo de documento de los TICKETS no se llama igual en todas las cuentas: se
            # comprueba con un GET (no crea nada) y se guarda el que la cuenta acepta.
            ticket_type = client.detect_ticket_doc_type()
            metodos = {}
            for m in client.payment_methods():
                mid = str(m.get("id") or "").strip()
                nombre = (m.get("name") or m.get("description") or "").strip()
                if mid and nombre:
                    metodos[mid] = nombre
            acc.ticket_doc_type = ticket_type
            acc.payment_methods = metodos
            acc.auth_header = getattr(client, "auth_header", None) or acc.auth_header
            acc.last_test_at = _now_madrid()
            acc.last_test_ok = True
            acc.last_error = None
            _holded_persist_client_state(acc, client)
            session_db.commit()
            aviso = ("Holded responde (clave aceptada en la cabecera «%s»). Documento de compra: "
                     "«%s» · tickets: «%s»."
                     % (getattr(client, "auth_header", "key"),
                        acc.invoice_doc_type or "purchase", ticket_type))
            if metodos:
                aviso += " %d forma(s) de pago leídas." % len(metodos)
            else:
                aviso += (" No se han podido leer las formas de pago: la forma de pago se dejará"
                          " escrita en la nota interna del documento.")
            flash(aviso, "success")
        except HoldedError as exc:
            # ⚠️ NO nos rendimos con un mensaje: se PRUEBA cada combinación (las tres cabeceras contra
            # varias rutas) y se enseña lo que ha contestado Holded en cada una. Así se ve de un golpe
            # si la credencial no vale (todo 401) o si es cuestión de PERMISOS del token (una ruta
            # responde y otra no).
            detalle = {}
            try:
                detalle = client.diagnose()
            except Exception:
                app.logger.exception("[holded] no se pudo diagnosticar la credencial")
            acc.last_test_at = _now_madrid()
            acc.last_test_ok = bool(detalle.get("ok"))
            acc.last_error = str(exc)[:500]
            acc.last_stats = dict(acc.last_stats or {}, diagnose=detalle)
            if detalle.get("ok"):
                # Alguna ruta SÍ responde: la credencial vale y se guarda la cabecera buena.
                acc.auth_header = detalle.get("header") or acc.auth_header
                acc.last_error = None
                _holded_persist_client_state(acc, client)
                session_db.commit()
                falta = ", ".join(detalle.get("scopes_missing") or [])
                flash(("Holded acepta la credencial con la cabecera «%s», pero le faltan permisos "
                       "para: %s. Edita el token en Holded y márcaselos."
                       % (detalle.get("header"), falta)) if falta else
                      ("Holded responde con la cabecera «%s». Vuelve a pulsar «Probar conexión»."
                       % detalle.get("header")), "warning")
            else:
                session_db.commit()
                resumen = " · ".join(
                    "%s→%s%s" % (f["header"], f["status"] or "sin respuesta",
                                 (" (%s)" % f["label"]))
                    for f in (detalle.get("attempts") or [])[:8])
                flash(Markup("Holded: %s<br><span class='small'>Lo probado: %s. Base: %s</span>"
                             % (escape(str(exc)), escape(resumen),
                                escape(detalle.get("base") or ""))), "danger")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo probar la conexión con Holded: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(url_for("integrations_view") + "#tab-holded")


# ------------------------------------------------------------------ Datos que se vuelcan a Holded

def _billing_name(entity, *, snapshot=None) -> str:
    """EL NOMBRE CON EL QUE FACTURA (el que sale en la factura), no nuestro nick. Punto único.

    ⚠️⚠️ Aquí llamamos a la gente por su NICK, pero a Holded (y a cualquier documento contable) hay
    que mandar el nombre de la **facturación**: la razón social de la sociedad, o el nombre y los
    apellidos de la persona. Con el nick, en Holded aparecería «Caco» en vez de «Juan Pérez García»
    y el contacto no cuadraría con su factura."""
    if entity is None:
        snapshot = snapshot or {}
        return ((snapshot.get("legal_name") or snapshot.get("company_name")
                 or snapshot.get("name") or snapshot.get("nick") or "").strip())
    # Una SOCIEDAD factura con su razón social.
    legal = (getattr(entity, "legal_name", None) or "").strip()
    if legal:
        return legal
    # Una PERSONA, con su nombre y apellidos (los datos oficiales, que llegan del DNI o de su ficha).
    partes = " ".join(x for x in ((getattr(entity, "first_name", None) or "").strip(),
                                  (getattr(entity, "last_name", None) or "").strip()) if x).strip()
    if partes:
        return partes
    # Y si no consta, lo que haya: el nombre social o, como último recurso, el nick.
    return ((getattr(entity, "name", None) or getattr(entity, "nick", None) or "").strip()
            or ((snapshot or {}).get("nick") or "").strip())


def _accounting_invoice_number(session_db, expense) -> str:
    """El NÚMERO DE FACTURA que se manda a Holded.

    ⚠️ Está en el gasto **o en su factura**: al subirla por el enlace del proveedor el número queda en
    la FACTURA, así que mirando solo el gasto se subía sin número (y en Holded una factura de compra
    sin número no vale)."""
    numero = (getattr(expense, "invoice_number", None) or "").strip()
    if numero:
        return numero
    inv = _accounting_expense_invoice(session_db, expense)
    return (getattr(inv, "invoice_number", None) or "").strip()


def _accounting_expense_promoter(session_db, expense):
    """El TERCERO (o su sociedad) que emite la factura de un gasto: es su ficha la que recuerda el
    contacto de Holded, para no volver a buscarlo ni duplicarlo."""
    company = getattr(expense, "provider_company", None)
    if company is not None:
        return company
    provider = getattr(expense, "provider", None)
    if provider is not None:
        return provider
    # Si el gasto no lo trae, se mira su FACTURA (que sí lleva el proveedor: es NOT NULL).
    try:
        inv = _accounting_expense_invoice(session_db, expense)
        if inv is not None and getattr(inv, "promoter_id", None):
            return session_db.get(Promoter, inv.promoter_id)
    except Exception:
        app.logger.exception("[holded] no se pudo resolver el tercero del gasto")
    return None


def _accounting_provider_info(session_db, expense) -> dict:
    """Datos del PROVEEDOR de un gasto, tal como hay que crearlo en Holded."""
    provider = getattr(expense, "provider", None)
    company = getattr(expense, "provider_company", None)
    snapshot = dict(getattr(expense, "provider_snapshot", None) or {})
    # ⚠️ A Holded va el nombre DE LA FACTURACIÓN (`_billing_name`), no el nick con el que lo
    # llamamos aquí.
    if company is not None:
        nombre = _billing_name(company, snapshot=snapshot)
        cif = (getattr(company, "tax_id", None) or "").strip()
        piezas = _fiscal_address_parts(company)
        es_persona = False
    else:
        nombre = _billing_name(provider, snapshot=snapshot)
        cif = (getattr(provider, "tax_id", None) or "").strip()
        piezas = _fiscal_address_parts(provider)
        es_persona = True
    if not nombre:
        nombre = (snapshot.get("company_name") or snapshot.get("nick") or "").strip()
    if not cif:
        cif = (snapshot.get("tax_id") or "").strip()
    # De lo guardado de antes (dirección en un solo cuadro) se reparte lo que se pueda.
    if piezas["address"] and not (piezas["postal_code"] or piezas["city"]):
        repartida = _split_fiscal_address(piezas["address"])
        for clave in ("address", "postal_code", "city", "province"):
            piezas[clave] = piezas[clave] or repartida.get(clave) or ""
    return {
        "name": nombre,
        "tax_id": cif,
        "email": (getattr(provider, "contact_email", None) or "").strip() if provider is not None else "",
        "phone": (getattr(provider, "contact_phone", None) or "").strip() if provider is not None else "",
        "is_person": es_persona,
        **piezas,
    }


def _accounting_bag_tag(session_db, bag) -> str:
    """ETIQUETA con la que se agrupan en Holded los gastos de una misma bolsa.

    ⚠️⚠️ **Es el NOMBRE DE LA BOLSA** (`_accounting_bag_label`, el mismo que se ve en la columna
    «Bolsa» de contabilidad): así la etiqueta de Holded y lo que se lee en la app dicen lo mismo. Si
    la bolsa no tiene nombre, esa función ya cae en lo que la identifica (la actividad y su fecha), y
    una liquidación de royalties —que no tiene bolsa— se etiqueta como lo que es.
    Antes era un código propio (`Artista_Municipio_Fecha`) que no se correspondía con nada de lo que
    se ve en la app.
    """
    etiqueta = _accounting_bag_label(session_db, bag) if bag is not None else ""
    if (etiqueta or "").strip():
        return etiqueta.strip()[:60]
    return _accounting_bag_tag_legacy(session_db, bag)


def _accounting_bag_tag_legacy(session_db, bag) -> str:
    """El código de antes (`Artista (o evento)_Actividad o municipio_Fecha`), como respaldo cuando la
    bolsa no tiene ni nombre ni nada que la identifique."""
    if bag is None:
        return ""
    artista = ""
    concert = None
    if (getattr(bag, "linked_type", None) or "").upper() == "CONCERT" and bag.linked_id:
        concert = session_db.get(Concert, bag.linked_id)
    if concert is not None and getattr(concert, "event_id", None):
        evento = session_db.get(AppEvent, concert.event_id)
        artista = (getattr(evento, "name", None) or "").strip()
    if not artista:
        artista = (getattr(getattr(bag, "artist", None), "name", None) or "").strip()
    if not artista and getattr(bag, "artist_id", None):
        art = session_db.get(Artist, bag.artist_id)
        artista = (getattr(art, "name", None) or "").strip()
    medio = ""
    fecha = None
    if concert is not None:
        medio = (getattr(concert, "festival_name", None) or "").strip()
        if not medio:
            medio = ((getattr(getattr(concert, "venue", None), "municipality", None) or "").strip()
                     or (getattr(concert, "manual_municipality", None) or "").strip())
        fecha = getattr(concert, "date", None)
    if not medio:
        medio = (getattr(bag, "linked_title", None) or getattr(bag, "title", None) or "").strip()
    fecha = fecha or getattr(bag, "start_date", None)
    trozos = [x for x in [artista, medio, (fecha.strftime("%d-%m-%Y") if fecha else "")] if x]
    return "_".join(trozos)[:120]


def _accounting_payment_person(session_db, expense) -> str:
    """De quién es la tarjeta con la que se pagó (Pleo / Cabify), para la nota interna.

    «Pagado con Pleo» a secas no dice nada en contabilidad: lo que hace falta es de quién era la
    tarjeta. Se saca del gasto importado que se imputó a este gasto de bolsa.
    """
    try:
        fila = (session_db.query(PersonalExpense)
                .filter(PersonalExpense.bag_expense_id == expense.id).first())
        if fila is None:
            imput = (session_db.query(BagExpenseInvoice)
                     .filter(BagExpenseInvoice.bag_expense_id == expense.id,
                             BagExpenseInvoice.personal_expense_id.isnot(None))
                     .order_by(BagExpenseInvoice.created_at.desc()).first())
            if imput is not None:
                fila = session_db.get(PersonalExpense, imput.personal_expense_id)
        if fila is None or not fila.user_id:
            return ""
        prof = (session_db.query(UserProfile)
                .filter(UserProfile.user_id == fila.user_id).first())
        return (getattr(prof, "nick", None) or "").strip()
    except Exception:
        return ""


def _accounting_internal_note(session_db, expense) -> str:
    """NOTA INTERNA del documento de Holded: cómo se ha pagado ese gasto.

    Si salió por una REMESA se dice cuál (con su referencia, banco y fecha); si no, con qué se pagó
    y de quién era la tarjeta (p. ej. «Pagado con Pleo · Caco»). Lo que no está pagado se dice
    también: en contabilidad no es lo mismo.
    """
    metodo = (getattr(expense, "payment_method", None) or "").strip()
    estado = (getattr(expense, "payment_status", None) or "NO_PAGADO").strip().upper()
    batch = None
    if getattr(expense, "payment_batch_id", None):
        batch = session_db.get(PaymentBatch, expense.payment_batch_id)
    if batch is not None and (batch.status or "").upper() == "PAGADA":
        partes = ["Pagado en remesa %s" % (batch.reference or "")]
        banco = (getattr(getattr(batch, "bank", None), "name", None) or "").strip()
        if banco:
            partes.append(banco)
        cuenta = getattr(batch, "account", None)
        alias = (getattr(cuenta, "alias", None) or "").strip() if cuenta is not None else ""
        if alias:
            partes.append(alias)
        if batch.paid_at:
            partes.append(batch.paid_at.strftime("%d/%m/%Y"))
        return " · ".join([x for x in partes if x])
    if estado == "PAGADO" or _money_or_zero(getattr(expense, "paid_amount", 0)) > 0:
        persona = _accounting_payment_person(session_db, expense)
        texto = "Pagado con %s" % (metodo or "método sin indicar")
        if persona:
            texto += " · " + persona
        if estado != "PAGADO":
            texto = "Pagado en parte (%s de %s) · %s" % (
                format_eur(_money_or_zero(getattr(expense, "paid_amount", 0))),
                format_eur(_money_or_zero(getattr(expense, "amount_gross", 0))), texto)
        return texto
    return "Pendiente de pago" + (" · %s previsto" % metodo if metodo else "")


# Los TIPOS que existen de verdad: el porcentaje de una factura no es un número cualquiera.
VAT_RATES = (Decimal("21"), Decimal("10"), Decimal("5"), Decimal("4"), Decimal("0"))
RETENTION_RATES = (Decimal("15"), Decimal("7"), Decimal("19"), Decimal("21"), Decimal("24"),
                   Decimal("20"), Decimal("9"), Decimal("2"), Decimal("1"))
# Cuánto se puede desviar el porcentaje despejado para darlo por ese tipo. Con dos importes
# redondeados a céntimos el error nunca pasa de unas centésimas; 0,30 va de sobra y no confunde dos
# tipos entre sí (el más cercano, 20 y 21, está a un punto).
TAX_PCT_SNAP = Decimal("0.30")


def _tax_pct_snap(pct, tipos=VAT_RATES):
    """⚠️⚠️ REDONDEA EL PORCENTAJE AL TIPO REAL cuando está pegadísimo a uno.

    Bug real: una factura del **21%** salía como **20,99%**. El porcentaje se despeja dividiendo dos
    importes que ya vienen **redondeados a céntimos** (IVA / base), así que el cociente casi nunca
    cae exacto: con base 100,05 e IVA 21,00 sale 20,99. Los tipos son LEGALES (21, 10, 5, 4, 0 · y
    15, 7, 19… en retenciones), así que si el número despejado está a menos de `TAX_PCT_SNAP` de uno
    de ellos, es ese — y si no, se deja tal cual (que igual es un desglose raro de verdad)."""
    if pct is None:
        return None
    try:
        valor = Decimal(str(pct))
    except (InvalidOperation, TypeError, ValueError):
        return pct
    for tipo in tipos:
        if abs(valor - tipo) <= TAX_PCT_SNAP:
            return tipo
    return valor


def _accounting_expense_invoice(session_db, expense):
    """LA FACTURA de un gasto (la imputada, o la que apunta a él). Punto único.

    En contabilidad, los importes que se ven salen de la FACTURA, así que cualquier corrección tiene
    que llegar aquí o la pantalla seguiría enseñando los de antes."""
    if expense is None:
        return None
    try:
        fila = (session_db.query(BagExpenseInvoice)
                .filter(BagExpenseInvoice.bag_expense_id == expense.id)
                .filter(BagExpenseInvoice.supplier_invoice_id.isnot(None))
                .order_by(BagExpenseInvoice.created_at.desc()).first())
        if fila is not None and fila.supplier_invoice_id:
            return session_db.get(SupplierInvoice, fila.supplier_invoice_id)
        return (session_db.query(SupplierInvoice)
                .filter(SupplierInvoice.bag_expense_id == expense.id)
                .order_by(SupplierInvoice.created_at.desc()).first())
    except Exception:
        app.logger.exception("[contabilidad] no se pudo resolver la factura del gasto")
        return None


def _accounting_amounts(session_db, expense, *, invoice=None) -> dict:
    """DESGLOSE del gasto para contabilidad: base, IVA (con su %), retención (con su %) y total.

    Manda lo que dice la FACTURA (se leyó del documento) y, si no hay, lo que tiene el gasto. Un
    TICKET no desglosa: el total es el total. Los porcentajes se despejan de los importes cuando no
    vienen dados, y un 0 no es «no lo sé»: si no hay dato, se devuelve None.
    """
    tipo = (getattr(expense, "document_type", None) or "FACTURA").strip().upper()
    total = _money_or_zero(getattr(expense, "amount_gross", 0))
    base = _money_or_zero(getattr(expense, "amount_net", 0))
    iva = _money_or_zero(getattr(expense, "amount_tax", 0))
    ret = _money_or_zero(getattr(expense, "retention_amount", 0))
    iva_pct = ret_pct = None
    if invoice is not None:
        if _money_or_zero(getattr(invoice, "amount_gross", None)) > 0:
            total = _money_or_zero(invoice.amount_gross)
        if _money_or_zero(getattr(invoice, "amount_net", None)) > 0:
            base = _money_or_zero(invoice.amount_net)
        if getattr(invoice, "amount_vat", None) is not None:
            iva = _money_or_zero(invoice.amount_vat)
        if getattr(invoice, "retention_amount", None) is not None:
            ret = _money_or_zero(invoice.retention_amount)
        # ⚠️ También lo GUARDADO se ajusta al tipo real: una factura de antes de esto pudo quedarse
        # con un 20,99 despejado, y lo que hay que enseñar es el 21 que dice el documento.
        if getattr(invoice, "vat_pct", None) is not None:
            iva_pct = _tax_pct_snap(_money_or_zero(invoice.vat_pct), VAT_RATES)
        if getattr(invoice, "retention_pct", None) is not None:
            ret_pct = _tax_pct_snap(_money_or_zero(invoice.retention_pct), RETENTION_RATES)
    if tipo in {"TICKET", "SIN_DOCUMENTO"}:
        # Un ticket no diferencia IVA: el total es el total y no se inventa ningún desglose.
        return {"net": total, "vat": Decimal("0"), "vat_pct": None,
                "retention": Decimal("0"), "retention_pct": None, "total": total,
                "breakdown": False}
    if base <= 0 and total > 0 and iva > 0:
        base = total - iva + ret
    if base <= 0 and total > 0:
        base = total
    # Con la base y el total, el IVA se despeja (es la diferencia, devolviéndole la retención). Sin
    # esto, un gasto del que solo se guardó base y total salía con «—» en IVA teniéndolo delante.
    if iva <= 0 and base > 0 and total > base:
        iva = total - base + ret
    if iva_pct is None and base > 0 and iva > 0:
        iva_pct = _tax_pct_snap((iva / base * Decimal("100")).quantize(Decimal("0.01")), VAT_RATES)
    if ret_pct is None and base > 0 and ret > 0:
        ret_pct = _tax_pct_snap((ret / base * Decimal("100")).quantize(Decimal("0.01")), RETENTION_RATES)
    return {"net": base, "vat": iva, "vat_pct": iva_pct,
            "retention": ret, "retention_pct": ret_pct, "total": total,
            "breakdown": True}


def _accounting_document_file(session_db, expense, *, invoice=None) -> dict:
    """El documento que se adjunta en Holded (la factura o el ticket) y su nombre."""
    url = (getattr(expense, "attachment_url", None) or "").strip()
    nombre = (getattr(expense, "attachment_name", None) or "").strip()
    if not url and invoice is not None:
        url = (getattr(invoice, "file_url", None) or "").strip()
        nombre = nombre or (getattr(invoice, "original_name", None) or "").strip()
    if not url:
        try:
            fila = (session_db.query(BagExpenseInvoice)
                    .filter(BagExpenseInvoice.bag_expense_id == expense.id)
                    .order_by(BagExpenseInvoice.created_at.desc()).first())
        except Exception:
            fila = None
        if fila is not None:
            url = (fila.file_url or "").strip()
            nombre = nombre or (fila.file_name or "").strip()
    return {"url": url, "name": (nombre or "documento.pdf")}


def _accounting_holded_payment_method_id(acc, metodo: str) -> str:
    """Forma de pago de Holded que se parece a la nuestra (por nombre). Sin coincidencia, vacío."""
    objetivo = (metodo or "").strip().casefold()
    if not objetivo:
        return ""
    catalogo = dict(getattr(acc, "payment_methods", None) or {})
    for mid, nombre in catalogo.items():
        if (nombre or "").strip().casefold() == objetivo:
            return str(mid)
    for mid, nombre in catalogo.items():
        limpio = (nombre or "").strip().casefold()
        if limpio and (limpio in objetivo or objetivo in limpio):
            return str(mid)
    return ""


def _holded_remembered_contact(promoter, company_id) -> str:
    """El id del contacto de Holded que YA se le resolvió a este tercero en esta empresa."""
    if promoter is None or not company_id:
        return ""
    try:
        return str((getattr(promoter, "holded_contact_ids", None) or {}).get(str(company_id)) or "").strip()
    except Exception:
        return ""


def _holded_remember_contact(session_db, promoter, company_id, contact_id: str) -> None:
    """Apunta en el TERCERO su contacto de Holded en esa empresa.

    ⚠️⚠️ Es lo que evita duplicar contactos: la próxima vez no se busca ni se crea, se usa el que ya
    existe. Por empresa, porque cada una es una cuenta de Holded distinta."""
    if promoter is None or not company_id or not (contact_id or "").strip():
        return
    try:
        mapa = dict(getattr(promoter, "holded_contact_ids", None) or {})
        if mapa.get(str(company_id)) == str(contact_id):
            return
        mapa[str(company_id)] = str(contact_id)
        promoter.holded_contact_ids = mapa
        session_db.add(promoter)
    except Exception:
        app.logger.exception("[holded] no se pudo recordar el contacto del tercero")


def _holded_contact_for_promoter(session_db, client, promoter, company_id, datos: dict,
                                 avisos: list) -> str:
    """El CONTACTO de Holded de un tercero: el recordado, el que ya existe allí o, si no, uno nuevo.

    ⚠️⚠️ Punto ÚNICO de «no dupliques contactos en Holded»: (1) el que ya se le apuntó a ese tercero
    en esa empresa, (2) el que haya en Holded buscándolo por **NIF/CIF** y, si no, por el **nombre de
    la FACTURACIÓN** (nunca el nick: en Holded está dado de alta con su nombre fiscal), y (3) solo
    entonces se crea. Lo que se resuelva se recuerda para la próxima."""
    ya = _holded_remembered_contact(promoter, company_id)
    if ya:
        return ya
    nombre = (datos.get("name") or "").strip()
    cif = (datos.get("tax_id") or "").strip()
    contact_id = ""
    # ⚠️ `raise_on_error`: si Holded no ha podido contestar (403, 429, red), NO se crea un contacto que
    # a lo mejor ya existe — la subida falla diciendo el motivo, que es lo correcto.
    encontrado = client.find_contact(cif, name=nombre, raise_on_error=True)
    if encontrado:
        contact_id = str(encontrado.get("id") or "").strip()
        if cif and not any((encontrado.get(k) or "").strip()
                           for k in ("code", "vatnumber", "vatNumber", "cif", "nif")):
            avisos.append("En Holded ese contacto no tiene NIF: se ha reutilizado igualmente para no "
                          "duplicarlo, pero conviene añadírselo allí.")
    if not contact_id:
        from holded_utils import contact_payload_for
        if not (datos.get("postal_code") and datos.get("city")):
            avisos.append("El proveedor se ha creado en Holded sin código postal o sin municipio: "
                          "complétalos en su ficha para que la dirección fiscal esté bien.")
        contact_id = client.create_contact(contact_payload_for(
            client, name=(nombre or ("Proveedor " + cif)), tax_id=cif,
            email=datos.get("email"), phone=datos.get("phone"),
            address=datos.get("address"), postal_code=datos.get("postal_code"),
            city=datos.get("city"), province=datos.get("province"),
            country=(datos.get("country") or "España"),
            # ⚠️ Persona o empresa lo dice el CIF (`_tax_id_kind`): con un CIF que empieza por letra es
            # una EMPRESA, aunque en nuestra base esté como tercero particular.
            is_person=(False if (cif and _tax_id_kind(cif) == "company")
                       else bool(datos.get("is_person"))),
        ))
    _holded_remember_contact(session_db, promoter, company_id, contact_id)
    return contact_id


def _holded_upload_expense(session_db, expense, *, nick: str = "") -> dict:
    """Sube UN gasto a Holded como compra nueva (o como ticket) y deja el resultado en el gasto.

    Devuelve `{"ok": bool, "message": str, "warning": str}`. Si algo falla NO se calla: el motivo se
    guarda en `holded_error` y se le enseña a quien lo ha intentado, que es lo que se pidió.
    """
    from holded_utils import (HoldedError, contact_payload_for, purchase_payload_for,
                              DOC_TYPE_INVOICE)
    # ⚠️⚠️ YA ESTÁ EN HOLDED: no se sube otra vez. Subirla dos veces crea un documento DUPLICADO en la
    # contabilidad, y eso no lo arregla nadie desde aquí. El candado va en este punto único, así que
    # vale para el botón de la fila, para «Subir todo» y para cualquier camino que venga después.
    if (getattr(expense, "holded_doc_id", None) or "").strip():
        numero = (getattr(expense, "holded_doc_number", None) or "").strip()
        cuando = (expense.holded_uploaded_at.strftime("%d/%m/%Y %H:%M")
                  if getattr(expense, "holded_uploaded_at", None) else "")
        return {"ok": False, "already": True, "warning": "",
                "message": ("Esta factura YA está subida a Holded%s%s: no se sube otra vez para que "
                            "no se duplique. Si hay que corregirla, se corrige en Holded."
                            % ((" (documento %s)" % numero) if numero else "",
                               (" el %s" % cuando) if cuando else ""))}
    bag = getattr(expense, "bag", None) or (session_db.get(WorkflowBag, expense.bag_id)
                                            if getattr(expense, "bag_id", None) else None)
    company_id = getattr(bag, "company_id", None)
    if not company_id:
        return _holded_upload_fail(expense, "El gasto no tiene empresa del grupo (la bolsa no la "
                                            "tiene puesta), así que no se sabe a qué cuenta de "
                                            "Holded va.")
    acc = _holded_account_for_company(session_db, company_id)
    try:
        client = _holded_client_for_account(acc)
    except HoldedError as exc:
        return _holded_upload_fail(expense, _holded_account_diagnosis(session_db, acc, str(exc)), acc)

    tipo = (getattr(expense, "document_type", None) or "FACTURA").strip().upper()
    es_factura = tipo == "FACTURA"
    factura = _accounting_expense_invoice(session_db, expense)
    importes = _accounting_amounts(session_db, expense, invoice=factura)
    if importes["total"] <= 0:
        return _holded_upload_fail(expense, "El gasto no tiene importe: en Holded no se puede crear "
                                            "una compra de 0 €.")
    concepto = (getattr(expense, "concept", None) or "Gasto").strip()
    avisos = []

    # 1) CONTACTO (solo las facturas): se busca por CIF/DNI/NIE y, si no está, se crea.
    contact_id = ""
    proveedor = _accounting_provider_info(session_db, expense)
    if es_factura:
        if not (proveedor["name"] or proveedor["tax_id"]):
            return _holded_upload_fail(expense, "La factura no tiene proveedor: en Holded hace falta "
                                                "el contacto para crear la compra.")
        try:
            contact_id = _holded_contact_for_promoter(
                session_db, client, _accounting_expense_promoter(session_db, expense),
                company_id, proveedor, avisos)
        except HoldedError as exc:
            return _holded_upload_fail(expense, _holded_account_diagnosis(
                session_db, acc, "No se ha podido preparar el proveedor en Holded: %s" % exc), acc)

    # 2) DOCUMENTO
    doc_type = ((acc.invoice_doc_type or DOC_TYPE_INVOICE) if es_factura
                else (acc.ticket_doc_type or "dailyexpense"))
    etiqueta = _accounting_bag_tag(session_db, bag)
    nota = _accounting_internal_note(session_db, expense)
    metodo_id = _accounting_holded_payment_method_id(acc, getattr(expense, "payment_method", None))
    payload = purchase_payload_for(client,
        concept=concepto,
        total=importes["total"],
        net=(importes["net"] if es_factura else importes["total"]),
        vat_pct=(importes["vat_pct"] if es_factura else 0),
        retention_pct=(importes["retention_pct"] if es_factura else 0),
        contact_id=(contact_id or None),
        contact_name=(proveedor["name"] if (es_factura and not contact_id) else None),
        # Un ticket no lleva número de documento ni fecha de emisión: no existen.
        # ⚠️ El número está en el gasto **o en su factura** (`_accounting_invoice_number`): al subirla
        # por el enlace del proveedor queda en la factura, y sin él Holded recibe una factura de
        # compra sin número.
        doc_number=(((getattr(expense, "invoice_number", None) or "").strip()
                      or (getattr(factura, "invoice_number", None) or "").strip()) or None)
                    if es_factura else None,
        issue_date=((getattr(expense, "issue_date", None)
                     or getattr(factura, "issue_date", None)) if es_factura else None),
        tags=([etiqueta] if etiqueta else None),
        # ⚠️ FACTURA o TICKET: en la v1 son dos documentos distintos de Holded (`purchase` /
        # `dailyexpense`) y en la v2, que no tiene el de gasto, el ticket va marcado como tal.
        is_ticket=(not es_factura),
        notes=nota,
        payment_method_id=(metodo_id or None),
    )
    try:
        creado = client.create_document(doc_type, payload)
    except HoldedError as exc:
        return _holded_upload_fail(expense, _holded_account_diagnosis(
            session_db, acc, "Holded no ha creado el documento: %s" % exc))

    # 3) COMPROBAR que el total que ha calculado Holded es el nuestro (red del mapeo de impuestos).
    try:
        cuadra, total_holded = client.verify_document_total(doc_type, creado["id"], importes["total"])
        if not cuadra:
            avisos.append("En Holded ha quedado por %s y aquí son %s: revisa el IVA o la retención."
                          % (format_eur(total_holded), format_eur(importes["total"])))
    except HoldedError:
        avisos.append("No se ha podido releer el documento en Holded para comprobar el total.")

    # 4) ADJUNTAR el documento (la factura o el ticket).
    doc = _accounting_document_file(session_db, expense, invoice=factura)
    if doc["url"]:
        datos = _download_url_bytes(doc["url"], max_bytes=20 * 1024 * 1024)
        if not datos:
            avisos.append("No se ha podido descargar el documento para adjuntarlo (¿se ha borrado "
                          "el archivo?).")
        else:
            try:
                client.attach_file(doc_type, creado["id"], filename=doc["name"], content=datos,
                                   mime=(getattr(expense, "attachment_mime", None) or None))
            except HoldedError as exc:
                avisos.append("El documento se ha creado pero el archivo NO se ha adjuntado: %s" % exc)
    elif (getattr(expense, "consolidation_status", "") or "").upper() != "SIN_FACTURA_ACEPTADO":
        avisos.append("Este gasto no tiene archivo que adjuntar.")

    expense.holded_company_id = to_uuid(str(company_id))
    expense.holded_doc_id = creado["id"]
    expense.holded_doc_type = doc_type
    expense.holded_doc_number = creado.get("number") or None
    expense.holded_contact_id = contact_id or None
    expense.holded_uploaded_at = _now_madrid()
    expense.holded_error = None
    expense.holded_warning = (" · ".join(avisos)[:800] or None)
    if (expense.accounting_status or "PENDIENTE").upper() not in ACCOUNTING_DONE_STATUSES:
        expense.accounting_status = "SUBIDO"
        expense.accounting_by_nick = (nick or "").strip() or expense.accounting_by_nick
    expense.updated_at = _now_madrid()
    _holded_persist_client_state(acc, client)
    mensaje = "«%s» subido a Holded como %s." % (concepto, "compra" if es_factura else "gasto")
    return {"ok": True, "message": mensaje, "warning": " · ".join(avisos)}


def _royalty_holded_company(session_db, rec):
    """A qué empresa del grupo se contabiliza una liquidación de royalties.

    La de la remesa con la que se pagó y, si no se pagó por remesa, PIES: las liquidaciones se
    facturan a nombre del sello (mismo criterio que el enlace del beneficiario)."""
    if rec is None:
        return None
    try:
        if getattr(rec, "payment_batch_id", None):
            batch = session_db.get(PaymentBatch, rec.payment_batch_id)
            company = (session_db.get(GroupCompany, batch.company_id)
                       if (batch is not None and getattr(batch, "company_id", None)) else None)
            if company is not None:
                return company
    except Exception:
        pass
    # ⚠️ Se cachea el ID, no el objeto: un objeto de una sesión ya cerrada revienta al leerlo, y
    # `session_db.get` con el id ya cargado no vuelve a la base de datos.
    try:
        try:
            pid = getattr(g, "_royalty_pies_company_id", None)
        except Exception:
            pid = None          # fuera de una petición (cron, hilo): sin caché y a buscarla
        if pid is None:
            pies = _pies_group_company(session_db)
            pid = str(getattr(pies, "id", "") or "")
            try:
                g._royalty_pies_company_id = pid
            except Exception:
                pass
            return pies
        return session_db.get(GroupCompany, to_uuid(pid)) if pid else None
    except Exception:
        return None


def _royalty_tag_subject(session_db, rec) -> str:
    """De quién es la liquidación, para la etiqueta de Holded (el artista y, si no, el beneficiario)."""
    try:
        congelada = _royalty_frozen_beneficiary(rec) or {}
        aid = congelada.get("artist_id") or ""
        if aid:
            art = session_db.get(Artist, to_uuid(str(aid)))
            if art is not None and (art.name or "").strip():
                return art.name.strip()
        return (congelada.get("artist_name") or congelada.get("name") or "").strip()
    except Exception:
        return ""


def _holded_upload_royalty(session_db, rec, *, nick: str = "") -> dict:
    """Sube a Holded la factura de UNA liquidación de royalties (una compra como cualquier otra).

    Mismo camino que un gasto de bolsa (`_holded_upload_expense`): contacto → documento → comprobar
    el total → adjuntar la factura. Lo que cambia es de dónde salen los datos: el beneficiario lo
    resuelve `_royalty_beneficiary_promoter` (quién emite la factura) y los importes,
    `_royalty_invoice_amounts` (los de SU factura).
    """
    from holded_utils import (HoldedError, contact_payload_for, purchase_payload_for,
                              DOC_TYPE_INVOICE)
    # ⚠️ Igual que un gasto: si YA está en Holded no se sube otra vez (se duplicaría el documento).
    if (getattr(rec, "holded_doc_id", None) or "").strip():
        numero = (getattr(rec, "holded_doc_number", None) or "").strip()
        return {"ok": False, "already": True, "warning": "",
                "message": ("Esta liquidación YA está subida a Holded%s: no se sube otra vez para que "
                            "no se duplique." % ((" (documento %s)" % numero) if numero else ""))}
    company = _royalty_holded_company(session_db, rec)
    if company is None:
        return _holded_royalty_fail(rec, "No hay empresa del grupo a la que contabilizar la "
                                         "liquidación.")
    acc = _holded_account_for_company(session_db, company.id)
    try:
        client = _holded_client_for_account(acc)
    except HoldedError as exc:
        return _holded_royalty_fail(rec, _holded_account_diagnosis(session_db, acc, str(exc)), acc)

    congelada = _royalty_frozen_beneficiary(rec) or {}
    inv = (session_db.get(SupplierInvoice, rec.invoice_id)
           if getattr(rec, "invoice_id", None) else None)
    importes = _royalty_invoice_amounts(congelada, inv)
    if importes["total"] <= 0:
        return _holded_royalty_fail(rec, "La liquidación no tiene importe: en Holded no se puede "
                                         "crear una compra de 0 €.")
    periodo = _royalty_liquidation_period_label_from_dates(rec.period_start, rec.period_end)
    concepto = "Royalties %s · %s" % (periodo, (congelada.get("name") or "Beneficiario"))
    avisos = []

    # 1) CONTACTO: quien EMITE la factura (el beneficiario o el tercero que le factura).
    promoter, _cands = _royalty_beneficiary_promoter(session_db, rec)
    # ⚠️ A Holded, el nombre DE LA FACTURACIÓN (no el nick con el que lo llamamos aquí).
    nombre = (_billing_name(promoter) if promoter is not None else "").strip()
    cif = (getattr(promoter, "tax_id", None) or "").strip()
    if not (nombre or cif):
        return _holded_royalty_fail(rec, "No se sabe quién emite esta factura: vincula al "
                                         "beneficiario con su tercero.")
    piezas = _fiscal_address_parts(promoter) if promoter is not None else {}
    contact_id = ""
    try:
        # El MISMO punto único que un gasto: el contacto recordado, el que ya está en Holded (por NIF
        # y, si no, por el nombre de la facturación) y solo entonces uno nuevo.
        correo, telefono = _promoter_email_phone(promoter)
        contact_id = _holded_contact_for_promoter(session_db, client, promoter, company.id, {
            "name": nombre, "tax_id": cif, "email": correo, "phone": telefono,
            "address": (piezas.get("address") or ""), "postal_code": (piezas.get("postal_code") or ""),
            "city": (piezas.get("city") or ""), "province": (piezas.get("province") or ""),
            "country": (piezas.get("country") or "España"), "is_person": True,
        }, avisos)
    except HoldedError as exc:
        return _holded_royalty_fail(rec, _holded_account_diagnosis(
            session_db, acc, "No se ha podido preparar el proveedor en Holded: %s" % exc), acc)

    # 2) DOCUMENTO (siempre una compra: una liquidación va con factura).
    doc_type = (acc.invoice_doc_type or DOC_TYPE_INVOICE)
    metodo_id = _accounting_holded_payment_method_id(acc, getattr(rec, "payment_method", None))
    nota = " · ".join([x for x in [
        ("Pagada el %s" % rec.paid_at.astimezone(TZ_MADRID).strftime("%d/%m/%Y")) if rec.paid_at else "",
        ("Forma de pago: %s" % (getattr(rec, "payment_method", None) or "")).strip(" :"),
    ] if x and x.strip()])
    payload = purchase_payload_for(client,
        concept=concepto,
        total=importes["total"], net=importes["net"],
        vat_pct=importes["vat_pct"], retention_pct=importes["retention_pct"],
        contact_id=(contact_id or None), contact_name=(nombre if not contact_id else None),
        doc_number=((getattr(inv, "invoice_number", None) or "").strip() or None),
        issue_date=getattr(inv, "issue_date", None),
        # ⚠️ El TAG dice lo que es: una liquidación no tiene bolsa, así que se etiqueta «Liquidación
        # de royalties» (con el artista si consta), igual que en la columna «Bolsa» de contabilidad.
        tags=[x for x in ["Liquidación de royalties",
                          (("%s · %s" % (_royalty_tag_subject(session_db, rec), periodo)).strip(" ·")
                           if periodo or _royalty_tag_subject(session_db, rec) else "")] if x],
        notes=(nota or None),
        payment_method_id=(metodo_id or None),
    )
    try:
        creado = client.create_document(doc_type, payload)
    except HoldedError as exc:
        return _holded_royalty_fail(rec, _holded_account_diagnosis(
            session_db, acc, "Holded no ha creado el documento: %s" % exc))

    # 3) COMPROBAR el total (red de seguridad del mapeo de impuestos).
    try:
        cuadra, total_holded = client.verify_document_total(doc_type, creado["id"], importes["total"])
        if not cuadra:
            avisos.append("En Holded ha quedado por %s y aquí son %s: revisa el IVA o la retención."
                          % (format_eur(total_holded), format_eur(importes["total"])))
    except HoldedError:
        avisos.append("No se ha podido releer el documento en Holded para comprobar el total.")

    # 4) ADJUNTAR la factura del beneficiario.
    url = (getattr(inv, "file_url", None) or "").strip()
    if url:
        datos = _download_url_bytes(url, max_bytes=20 * 1024 * 1024)
        if not datos:
            avisos.append("No se ha podido descargar la factura para adjuntarla.")
        else:
            try:
                client.attach_file(doc_type, creado["id"],
                                   filename=((getattr(inv, "original_name", None) or "factura.pdf")),
                                   content=datos)
            except HoldedError as exc:
                avisos.append("El documento se ha creado pero la factura NO se ha adjuntado: %s" % exc)
    else:
        avisos.append("Esta liquidación no tiene factura que adjuntar.")

    rec.holded_company_id = to_uuid(str(company.id))
    rec.holded_doc_id = creado["id"]
    rec.holded_doc_type = doc_type
    rec.holded_doc_number = creado.get("number") or None
    rec.holded_contact_id = contact_id or None
    rec.holded_uploaded_at = _now_madrid()
    rec.holded_error = None
    rec.holded_warning = (" · ".join(avisos)[:800] or None)
    rec.updated_at = _now_madrid()
    _royalty_history_add(rec, "HOLDED_UPLOADED", by=(nick or ""))
    _holded_persist_client_state(acc, client)
    return {"ok": True, "message": "«%s» subido a Holded." % concepto,
            "warning": " · ".join(avisos)}


def _holded_royalty_fail(rec, motivo: str, acc=None) -> dict:
    """Deja escrito en la liquidación por qué no se ha podido subir (y lo devuelve para enseñarlo)."""
    try:
        rec.holded_error = (motivo or "")[:800] or None
        rec.updated_at = _now_madrid()
    except Exception:
        pass
    # …y en la CUENTA, para que Integraciones → Holded diga qué pasó la última vez.
    _holded_remember_error(acc, motivo)
    return {"ok": False, "message": motivo, "warning": ""}


def _holded_upload_fail(expense, motivo: str, acc=None) -> dict:
    """Deja escrito en el gasto por qué no se ha podido subir (y lo devuelve para enseñarlo)."""
    try:
        expense.holded_error = (motivo or "")[:800] or None
        expense.updated_at = _now_madrid()
    except Exception:
        pass
    _holded_remember_error(acc, motivo)
    return {"ok": False, "message": motivo, "warning": ""}


def _accounting_set_status(session_db, expense, status: str, *, nick: str = "",
                           note: str = "") -> None:
    """Punto ÚNICO para cambiar el estado contable de un gasto."""
    st = (status or "").strip().upper()
    if st not in ACCOUNTING_STATUS_LABELS:
        return
    expense.accounting_status = st
    expense.accounting_by_nick = (nick or "").strip() or expense.accounting_by_nick
    expense.accounting_note = (note or "").strip() or (None if st != "OMITIDO" else expense.accounting_note)
    # `accounting_at` es la fecha que se enseña al pasar el ratón por la etiqueta: solo tiene sentido
    # cuando el gasto ya está resuelto.
    expense.accounting_at = _now_madrid() if st in ACCOUNTING_DONE_STATUSES else None
    expense.updated_at = _now_madrid()
    bag = getattr(expense, "bag", None) or (session_db.get(WorkflowBag, expense.bag_id)
                                            if getattr(expense, "bag_id", None) else None)
    _accounting_bag_close_if_done(session_db, bag)


def _accounting_bag_close_if_done(session_db, bag) -> bool:
    """Una bolsa con TODOS sus gastos contabilizados (u omitidos) sale de pendiente de contabilizar.

    Se marca `accounting_done_at` y, si además no queda nada por pagar, se archiva: a partir de ahí
    no hay nada que hacer con ella. Devuelve True si la ha cerrado ahora.
    """
    if bag is None:
        return False
    try:
        # ⚠️ La sesión de esta app es `autoflush=False`: sin este flush, la consulta de abajo NO ve
        # los estados que se acaban de cambiar en memoria y la bolsa nunca se daba por cerrada
        # (marcar los cuatro gastos de golpe dejaba `accounting_done_at` a null: bug real).
        session_db.flush()
        quedan = (session_db.query(func.count(BagExpense.id))
                  .filter(BagExpense.bag_id == bag.id,
                          BagExpense.status != "ELIMINADO",
                          BagExpense.consolidation_status.in_(list(BAG_CONSOLIDATED_STATUSES)),
                          ~func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE"))
                          .in_(list(ACCOUNTING_DONE_STATUSES)))
                  .scalar()) or 0
    except Exception:
        return False
    if quedan:
        if getattr(bag, "accounting_done_at", None):
            bag.accounting_done_at = None      # ha vuelto a haber trabajo (p. ej. un gasto nuevo)
        return False
    if getattr(bag, "accounting_done_at", None):
        return False
    bag.accounting_done_at = _now_madrid()
    bag.updated_at = _now_madrid()
    # El aviso de «bolsa lista para contabilizar» ya no espera a nadie: se cierra solo.
    _notify_resolve(session_db, "BAG_ACCOUNTING", str(bag.id))
    if not bag.is_archived:
        bag.status = "ARCHIVADA"
        bag.is_archived = True
        bag.archived_at = _now_madrid()
    return True


def _holded_refresh_accounted_royalties(session_db, *, limit: int = 200) -> dict:
    """Lo mismo que `_holded_refresh_accounted`, para las LIQUIDACIONES de royalties subidas.

    ⚠️ Una liquidación pasa a «contabilizada» cuando **Holded la tiene guardada** (su
    `accounting_date`/`approved_at`), no al subirla."""
    from holded_utils import HoldedError
    salida = {"roy_checked": 0, "roy_accounted": 0}
    filas = (session_db.query(RoyaltyLiquidation)
             .filter(RoyaltyLiquidation.holded_doc_id.isnot(None),
                     RoyaltyLiquidation.accounted_at.is_(None))
             .order_by(RoyaltyLiquidation.updated_at.asc().nullslast()).limit(limit).all())
    clientes = {}
    for rec in filas:
        company = _royalty_holded_company(session_db, rec)
        cid = str(getattr(company, "id", "") or "")
        if not cid:
            continue
        if cid not in clientes:
            acc = _holded_account_for_company(session_db, cid)
            try:
                clientes[cid] = (_holded_client_for_account(acc), acc)
            except HoldedError:
                clientes[cid] = (None, acc)
        client, acc = clientes[cid]
        if client is None:
            continue
        salida["roy_checked"] += 1
        try:
            guardada, _doc = client.document_is_accounted(
                getattr(rec, "holded_doc_type", None) or "purchase", rec.holded_doc_id)
        except HoldedError:
            continue
        if guardada:
            rec.accounted_at = _now_madrid()
            rec.accounted_by_nick = "Holded"
            rec.updated_at = _now_madrid()
            session_db.add(rec)
            salida["roy_accounted"] += 1
        _holded_persist_client_state(acc, client)
    return salida


def _holded_refresh_accounted(session_db, *, limit: int = 400) -> dict:
    """Pregunta a Holded por los documentos ya SUBIDOS y marca como contabilizados los que lo estén.

    Así la etiqueta se pone al día sola. Lo que Holded no diga NO se toca: preferimos no saberlo a
    inventarlo.
    """
    from holded_utils import HoldedError
    salida = {"checked": 0, "accounted": 0, "errors": []}
    filas = (session_db.query(BagExpense)
             .filter(BagExpense.holded_doc_id.isnot(None),
                     func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE")) == "SUBIDO")
             .order_by(BagExpense.holded_uploaded_at.asc().nullslast()).limit(limit).all())
    clientes = {}
    for expense in filas:
        cid = str(getattr(expense, "holded_company_id", "") or "")
        if not cid:
            bag = session_db.get(WorkflowBag, expense.bag_id) if expense.bag_id else None
            cid = str(getattr(bag, "company_id", "") or "")
        if not cid:
            continue
        if cid not in clientes:
            acc = _holded_account_for_company(session_db, cid)
            try:
                clientes[cid] = (_holded_client_for_account(acc), acc)
            except HoldedError as exc:
                clientes[cid] = (None, acc)
                salida["errors"].append(str(exc)[:200])
        client, acc = clientes[cid]
        if client is None:
            continue
        salida["checked"] += 1
        try:
            contabilizado, _doc = client.document_is_accounted(
                expense.holded_doc_type or "purchase", expense.holded_doc_id)
        except HoldedError as exc:
            salida["errors"].append(str(exc)[:200])
            continue
        if contabilizado:
            _accounting_set_status(session_db, expense, "CONTABILIZADO", nick="Holded")
            salida["accounted"] += 1
        _holded_persist_client_state(acc, client)
    # …y lo mismo con las LIQUIDACIONES de royalties, que también se suben a Holded: pasan a
    # contabilizadas cuando **Holded** las tiene guardadas, no al subirlas.
    try:
        salida.update(_holded_refresh_accounted_royalties(session_db, limit=limit))
    except Exception:
        app.logger.exception("[holded] no se pudo repasar el estado de las liquidaciones")
    session_db.commit()
    return salida


def _holded_autodetect_due(session_db, *, minutes: int = 15) -> bool:
    """¿Toca preguntar a Holded qué se ha contabilizado ya? (como mucho, cada 15 minutos)."""
    try:
        pendientes = (session_db.query(func.count(BagExpense.id))
                      .filter(BagExpense.holded_doc_id.isnot(None),
                              func.upper(func.coalesce(BagExpense.accounting_status, "PENDIENTE")) == "SUBIDO")
                      .scalar()) or 0
        # ⚠️ Las LIQUIDACIONES de royalties también se suben a Holded: si solo hay de esas, hay que
        # preguntar igual (si no, se quedarían en «subida» para siempre).
        pendientes += (session_db.query(func.count(RoyaltyLiquidation.id))
                       .filter(RoyaltyLiquidation.holded_doc_id.isnot(None),
                               RoyaltyLiquidation.accounted_at.is_(None))
                       .scalar()) or 0
        if not pendientes:
            return False
        cuentas = (session_db.query(HoldedAccount)
                   .filter(HoldedAccount.is_active.is_(True),
                           HoldedAccount.api_key.isnot(None)).all())
        if not cuentas:
            return False
        limite = _now_madrid() - timedelta(minutes=minutes)
        return any((c.last_sync_at is None or c.last_sync_at < limite) for c in cuentas)
    except Exception:
        return False


def _holded_autodetect_bg() -> None:
    """Sondeo en SEGUNDO PLANO al abrir Contabilidad: la etiqueta se pone al día sola.

    En primer plano no: preguntar por 40 documentos son 40 llamadas y la pantalla se quedaría
    colgada. Así se abre al momento y lo detectado se ve en la siguiente carga.
    """
    session_db = db()
    try:
        for acc in (session_db.query(HoldedAccount)
                    .filter(HoldedAccount.is_active.is_(True),
                            HoldedAccount.api_key.isnot(None)).all()):
            acc.last_sync_at = _now_madrid()
        session_db.commit()
        _holded_refresh_accounted(session_db, limit=120)
    except Exception:
        try:
            session_db.rollback()
        except Exception:
            pass
        app.logger.exception("[holded] sondeo en segundo plano falló")
    finally:
        session_db.close()


# ------------------------------------------------------------------ Buscador de direcciones
#  Autocompletar la dirección fiscal: se escribe la calle y se rellenan solos el código postal, el
#  municipio, la provincia y el país (que es lo que la contabilidad necesita separado).
#
#  ⚠️ La PROVINCIA no la pone el geocodificador: se deduce del código postal (`geo_utils`), porque
#  Photon devuelve la comunidad autónoma o la comarca y ninguna de las dos vale.
#  ⚠️ Lo buscado se GUARDA en `address_lookups`: la segunda vez que alguien escriba la misma calle
#  sale al instante y sin salir a Internet (el proveedor es gratis, pero no es nuestro).

# Vigencia de la caché: una calle no se mueve, pero un CP puede cambiar.
ADDRESS_CACHE_DAYS = 180
# Tope por IP y minuto: el endpoint es público (lo usan el enlace de alta y la landing de facturación).
_ADDRESS_RATE = defaultdict(deque)
ADDRESS_RATE_LIMIT = 40


def _address_rate_ok(ip: str) -> bool:
    """Freno sencillo por IP (en memoria): el endpoint es público y no debe poder abusarse."""
    ahora = time.time()
    cola = _ADDRESS_RATE[ip or "?"]
    while cola and ahora - cola[0] > 60:
        cola.popleft()
    if len(cola) >= ADDRESS_RATE_LIMIT:
        return False
    cola.append(ahora)
    return True


def _address_search_cached(session_db, query: str) -> list[dict]:
    """Sugerencias de dirección, mirando primero lo que ya se buscó otra vez."""
    import geo_utils
    clave = " ".join((query or "").split()).casefold()[:160]
    if len(clave) < 4:
        return []
    fila = session_db.get(AddressLookup, clave)
    if fila is not None and fila.updated_at and (
            _now_madrid() - fila.updated_at).days < ADDRESS_CACHE_DAYS:
        try:
            fila.hits = int(fila.hits or 0) + 1
            session_db.commit()
        except Exception:
            session_db.rollback()
        return list(fila.payload or [])
    filas = geo_utils.search_addresses(query)
    try:
        if fila is None:
            session_db.add(AddressLookup(query_key=clave, payload=filas))
        else:
            fila.payload = filas
            fila.hits = int(fila.hits or 0) + 1
            fila.updated_at = _now_madrid()
        session_db.commit()
    except Exception:
        session_db.rollback()
    return filas


@app.get("/api/direcciones", endpoint="api_address_search")
def api_address_search():
    """Sugerencias para autocompletar una dirección (calle → CP, municipio, provincia y país).

    Es un BUSCADOR: lo usa cualquiera con sesión y también los enlaces públicos (alta de terceros y
    landing de facturación), donde es justo donde más falta hace. Si el proveedor falla se devuelve
    una lista vacía con el motivo: el formulario se sigue rellenando a mano.
    """
    if not _address_rate_ok((request.headers.get("X-Forwarded-For") or request.remote_addr or "").split(",")[0].strip()):
        return jsonify({"ok": False, "error": "Demasiadas búsquedas seguidas: espera un momento.",
                        "results": []}), 429
    import geo_utils
    q = (request.args.get("q") or "").strip()
    # Solo el código postal: la provincia sale de la tabla, sin pedir nada a nadie.
    cp = geo_utils.normalize_postal_code(q)
    if cp and q.replace(" ", "").isdigit():
        session_db = db()
        try:
            filas = _address_search_cached(session_db, "%s España" % cp)
        except geo_utils.GeoError:
            filas = []
        finally:
            session_db.close()
        municipios, vistos = [], set()
        for f in filas:
            nombre = (f.get("city") or "").strip()
            if nombre and nombre.casefold() not in vistos and f.get("postal_code") == cp:
                vistos.add(nombre.casefold())
                municipios.append(nombre)
        return jsonify({"ok": True, "postal_code": cp,
                        "province": geo_utils.province_for_postal_code(cp),
                        "cities": municipios[:6], "results": []})
    if len(q) < 4:
        return jsonify({"ok": True, "results": []})
    session_db = db()
    try:
        filas = _address_search_cached(session_db, q)
        # Cada sugerencia lleva también la dirección ENTERA en el formato de la casa: así el campo
        # único (`data-addr="full"`) escribe exactamente lo mismo que se guardaría por piezas, y el
        # formato lo decide UN solo sitio (`address_utils`), no el JS.
        for f in filas:
            f["full"] = address_utils.format_parts(f)
        return jsonify({"ok": True, "results": filas})
    except geo_utils.GeoError as exc:
        return jsonify({"ok": False, "error": str(exc), "results": []})
    finally:
        session_db.close()


@app.get("/cron/holded/refresh", endpoint="cron_holded_refresh")
def cron_holded_refresh():
    """Sondeo periódico: mira en Holded qué documentos ya están contabilizados. Sin sesión (?key=)."""
    expected = (getattr(settings, "HOLDED_CRON_KEY", "") or settings.PLEO_CRON_KEY
                or settings.CHARTMETRIC_CRON_KEY or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    session_db = db()
    try:
        out = _holded_refresh_accounted(session_db)
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("[holded] cron falló")
        return (jsonify({"ok": False, "error": str(exc)}), 500)
    finally:
        session_db.close()
    return jsonify({"ok": True, **out})


@app.post('/mi-menu/orden', endpoint='nav_menu_order_save')
@admin_required
def nav_menu_order_save():
    """Guarda el ORDEN DEL MENÚ que ha puesto la persona arrastrando sus secciones.

    Es una preferencia suya (no un permiso): manda sobre el orden automático por uso, y vaciándolo se
    vuelve a ese automático."""
    uid = to_uuid(session.get("user_id") or "")
    if not uid:
        abort(403)
    session_db = db()
    try:
        claves = [str(x).strip() for x in request.form.getlist("keys") if str(x or "").strip()]
        if not claves:
            crudo = (request.form.get("order") or "").strip()
            claves = [x.strip() for x in crudo.split(",") if x.strip()]
        # Sin duplicados y sin «home» (siempre va primero).
        vistos, limpio = set(), []
        for k in claves:
            if k == "home" or k in vistos:
                continue
            vistos.add(k)
            limpio.append(k)
        perfil = (session_db.query(UserProfile).filter(UserProfile.user_id == uid).first())
        if perfil is None:
            abort(404)
        perfil.menu_order = limpio
        perfil.updated_at = _now_madrid()
        session_db.commit()
        if _wants_json_response():
            return jsonify({"ok": True, "order": limpio})
        flash("Menú ordenado." if limpio else "Se ha vuelto al orden automático.", "success")
    except Exception as exc:
        session_db.rollback()
        if _wants_json_response():
            return jsonify({"ok": False, "error": str(exc)}), 400
        flash("No se pudo guardar el orden: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(request.form.get("next") or url_for("home")))


@app.get('/mis-gastos', endpoint='my_expenses_view')
@admin_required
def my_expenses_view():
    """MIS GASTOS: facturas que me han enviado por el formulario y gastos de Pleo sin asignar."""
    session_db = db()
    try:
        uid = session.get("user_id")
        pending = _personal_expenses_for(session_db, uid, status=("PENDING",))
        in_bag = _personal_expenses_for(session_db, uid, status=("IN_BAG",))
        assigned = _personal_expenses_for(session_db, uid, status=("ASSIGNED",))
        # Los mandados a validar como gasto de oficina / inversión de artista siguen viéndose aquí,
        # con su etiqueta de «a la espera», hasta que administración diga algo.
        validating = _personal_expenses_for(session_db, uid, status=("VALIDATING",))
        direct = _personal_expenses_for(session_db, uid, status=("DIRECT",))
        return render_template(
            "my_expenses.html",
            pending=pending, in_bag=in_bag, assigned=assigned,
            validating=validating, direct=direct,
            assign_days=EXPENSE_ASSIGN_DAYS,
            expense_pause=_expense_pause_context(session_db, uid),
        )
    finally:
        session_db.close()


@app.get('/mis-gastos/asignar', endpoint='my_expenses_assign')
@admin_required
def my_expenses_assign():
    """Pantalla de asignación: gastos sin asignar a la izquierda y bolsas abiertas a la derecha."""
    session_db = db()
    try:
        uid = session.get("user_id")
        q = (request.args.get("q") or "").strip()
        # Artistas ACTIVOS para el desplegable de «inversión de artista»: primero los asignados a
        # esta persona (que son con los que trabaja) y, con «ver más», todos los demás.
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == to_uuid(str(uid))).first() if uid else None
        mios = {str(x) for x in ((getattr(prof, "assigned_artist_ids", None) or []) if prof else [])}
        artistas_todos = (session_db.query(Artist).filter(Artist.event_id.is_(None))
                          .order_by(Artist.name.asc()).all())
        artistas = [{"id": str(a.id), "name": a.name or "Artista",
                     "photo_url": (a.photo_url or ""), "mine": str(a.id) in mios}
                    for a in artistas_todos]
        return render_template(
            "my_expenses_assign.html",
            pending=_personal_expenses_for(session_db, uid, status=("PENDING",)),
            bag_groups=_open_bags_for_user(session_db, uid, artist_query=q),
            expense_pause=_expense_pause_context(session_db, uid),
            artistas=artistas,
            direct_targets=PERSONAL_DIRECT_TARGETS,
            q=q,
        )
    finally:
        session_db.close()


@app.post('/mis-gastos/<expense_id>/asignar', endpoint='my_expense_assign_bag')
@admin_required
def my_expense_assign_bag(expense_id):
    """Asigna un gasto a una BOLSA (queda pendiente de tipificar dentro de ella)."""
    session_db = db()
    try:
        row = session_db.get(PersonalExpense, to_uuid(expense_id) or uuid.uuid4())
        if not row:
            return jsonify({"ok": False, "error": "Gasto no encontrado"}), 404
        # Solo se pueden mover los gastos PROPIOS (dirección puede ayudar con los de cualquiera).
        if str(row.user_id) != str(session.get("user_id")) and not is_master():
            return jsonify({"ok": False, "error": "Ese gasto no es tuyo"}), 403
        bag = session_db.get(WorkflowBag, to_uuid(request.form.get("bag_id") or "") or uuid.uuid4())
        if not bag:
            return jsonify({"ok": False, "error": "Bolsa no encontrada"}), 404
        row.bag_id = bag.id
        row.status = "IN_BAG"
        row.assigned_at = _now_madrid()
        row.updated_at = _now_madrid()
        session_db.commit()
        if request.form.get("ajax"):
            return jsonify({"ok": True, "bag_title": bag.title or "Bolsa"})
        flash(f"Gasto asignado a «{bag.title or 'Bolsa'}».", "success")
        return redirect(safe_next_or(url_for("my_expenses_assign")))
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


def _my_expense_or_403(session_db, expense_id):
    """El gasto, si es MÍO (dirección puede ayudar con los de cualquiera). Devuelve (row, error)."""
    row = session_db.get(PersonalExpense, to_uuid(str(expense_id)) or uuid.uuid4())
    if not row:
        return None, (jsonify({"ok": False, "error": "Gasto no encontrado"}), 404)
    if str(row.user_id) != str(session.get("user_id")) and not is_master():
        return None, (jsonify({"ok": False, "error": "Ese gasto no es tuyo"}), 403)
    return row, None


@app.post('/mis-gastos/<expense_id>/factura', endpoint='my_expense_upload_invoice')
@admin_required
def my_expense_upload_invoice(expense_id):
    """Sube la factura o el ticket de un gasto propio (menú de los 3 puntitos de «Mis gastos»)."""
    session_db = db()
    try:
        row, err = _my_expense_or_403(session_db, expense_id)
        if err:
            return err
        fs = request.files.get("file")
        if not fs or not getattr(fs, "filename", ""):
            return jsonify({"ok": False, "error": "No llegó ningún archivo."}), 400
        row.file_url = upload_file(fs, "gastos-personales")
        row.original_name = os.path.basename((fs.filename or "").replace("\\", "/"))[:200] or None
        row.document_type = (request.form.get("document_type") or row.document_type or "FACTURA").upper()
        # Con justificante ya no hace falta el «sin factura» que hubiera pedido.
        if (row.no_invoice_status or "").upper() in ("SOLICITADO", "RECHAZADO"):
            row.no_invoice_status = None
            row.no_invoice_reason = None
        row.updated_at = _now_madrid()
        session_db.commit()
        return jsonify({"ok": True, "file_url": row.file_url})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/mis-gastos/<expense_id>/sin-factura', endpoint='my_expense_no_invoice')
@admin_required
def my_expense_no_invoice(expense_id):
    """Pide a administración que acepte el gasto SIN factura, diciendo por qué."""
    session_db = db()
    try:
        row, err = _my_expense_or_403(session_db, expense_id)
        if err:
            return err
        motivo = (request.form.get("reason") or "").strip()
        if not motivo:
            return jsonify({"ok": False, "error": "Hay que decir por qué no hay factura."}), 400
        row.no_invoice_reason = motivo[:500]
        row.no_invoice_status = "SOLICITADO"
        row.updated_at = _now_madrid()
        session_db.commit()
        return jsonify({"ok": True})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/mis-gastos/<expense_id>/directo', endpoint='my_expense_send_direct')
@admin_required
def my_expense_send_direct(expense_id):
    """Manda el gasto a validar como GASTO DE OFICINA o como INVERSIÓN DE ARTISTA (no va a bolsa)."""
    session_db = db()
    try:
        row, err = _my_expense_or_403(session_db, expense_id)
        if err:
            return err
        destino = (request.form.get("target") or "").strip().upper()
        if destino not in PERSONAL_DIRECT_TARGETS:
            return jsonify({"ok": False, "error": "Destino desconocido."}), 400
        # Como NO va contra ninguna bolsa, aquí es donde se exige el justificante.
        if not _personal_expense_has_justification(row):
            estado = (row.no_invoice_status or "").upper()
            if estado == "SOLICITADO":
                aviso = ("Este gasto está pendiente de que administración acepte que va sin factura. "
                         "En cuanto lo acepte podrás mandarlo.")
            else:
                aviso = ("Este gasto necesita su factura o su ticket. Súbelo desde los tres puntitos, "
                         "o pide que se acepte sin factura.")
            return jsonify({"ok": False, "needs_invoice": True, "error": aviso}), 400
        artista = None
        if destino == "ARTIST_INVESTMENT":
            artista = session_db.get(Artist, to_uuid(request.form.get("artist_id") or "") or uuid.uuid4())
            if not artista:
                return jsonify({"ok": False, "needs_artist": True,
                                "error": "Elige de qué artista es la inversión."}), 400
        row.direct_target = destino
        row.direct_artist_id = (artista.id if artista else None)
        row.bag_id = None
        row.status = "VALIDATING"
        row.validation_status = "PENDIENTE"
        row.validation_note = None
        row.validation_requested_at = _now_madrid()
        row.updated_at = _now_madrid()
        session_db.commit()
        etiqueta = PERSONAL_DIRECT_TARGETS[destino][0]
        return jsonify({"ok": True, "target_label": etiqueta,
                        "artist_name": (getattr(artista, "name", "") or "")})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/administracion/gastos-directos/<expense_id>/<decision>', endpoint='administration_direct_expense_decision')
@admin_required
def administration_direct_expense_decision(expense_id, decision):
    """Administración valida (o no) un gasto de oficina / inversión de artista.
    · Aceptado → sale de «Mis gastos» como gasto directo y, si no está pagado, queda pendiente de pago.
    · Rechazado → vuelve a estar pendiente de asignar, con el aviso de por qué no se aceptó."""
    session_db = db()
    try:
        row = session_db.get(PersonalExpense, to_uuid(str(expense_id)) or uuid.uuid4())
        if not row:
            flash("Gasto no encontrado.", "warning")
            return redirect(url_for("administracion_view", tab="pendiente", subtab="oficina"))
        estado = _current_user_state()
        if (decision or "").lower() in ("approve", "aceptar", "aprobar"):
            row.validation_status = "APROBADO"
            row.status = "DIRECT"
            row.validation_note = None
            if _personal_expense_is_prepaid(row):
                row.payment_status = "PAGADO"
                row.paid_at = row.paid_at or _now_madrid()
            else:
                row.payment_status = "NO_PAGADO"
            mensaje = "Gasto aceptado."
        else:
            row.validation_status = "RECHAZADO"
            row.status = "PENDING"
            row.direct_target = None
            row.direct_artist_id = None
            row.validation_note = (request.form.get("reason") or "").strip()[:500] or "Sin motivo indicado."
            mensaje = "Gasto devuelto a quien lo mandó."
        row.validated_at = _now_madrid()
        row.validated_by_user_id = to_uuid(estado.get("user_id")) if estado.get("user_id") else None
        row.validated_by_nick = estado.get("nick") or "Administración"
        row.updated_at = _now_madrid()
        session_db.commit()
        flash(mensaje, "success")
    except Exception as exc:
        session_db.rollback()
        flash(f"No se pudo procesar: {exc}", "danger")
    finally:
        session_db.close()
    return redirect(safe_next_or(url_for("administracion_view", tab="pendiente", subtab="oficina")))


