# ==================== FACTURAS IMPUTADAS A GASTOS DE LA BOLSA ====================
# Una factura puede cubrir VARIOS gastos y un gasto puede necesitar varias facturas. La relación
# vive en `bag_expense_invoices` con el importe imputado a cada gasto; las filas de la misma
# factura física comparten `group_key`.

def _bag_expense_invoice_apply(session_db, expense, *, file_url, file_name=None, file_mime=None,
                               invoice_number=None, amount=None, group_key=None,
                               supplier_invoice_id=None, personal_expense_id=None):
    """Imputa una factura a UN gasto. Devuelve la fila creada."""
    row = BagExpenseInvoice(
        bag_expense_id=expense.id,
        group_key=(group_key or uuid.uuid4().hex),
        supplier_invoice_id=supplier_invoice_id,
        personal_expense_id=personal_expense_id,
        file_url=file_url,
        file_name=(file_name or "")[:200] or None,
        file_mime=file_mime,
        invoice_number=(invoice_number or "")[:80] or None,
        amount=_money_or_zero(amount),
    )
    session_db.add(row)
    # El adjunto del gasto sigue apuntando a la factura, para que todo lo que ya lo lee (validación,
    # PDF de la bolsa, avisos) siga funcionando igual.
    expense.attachment_url = file_url
    expense.attachment_name = row.file_name
    expense.attachment_mime = file_mime
    if row.invoice_number:
        expense.invoice_number = row.invoice_number
    if (getattr(expense, "consolidation_status", "") or "").upper() not in BAG_CONSOLIDATED_STATUSES:
        expense.consolidation_status = "PENDIENTE_VALIDAR"
    return row


def _bag_expense_invoice_rows(session_db, expense_id) -> list[dict]:
    """Facturas imputadas a un gasto, para enseñarlas en la bolsa."""
    rows = (session_db.query(BagExpenseInvoice)
            .filter(BagExpenseInvoice.bag_expense_id == expense_id)
            .order_by(BagExpenseInvoice.created_at.asc()).all())
    out = []
    for r in rows:
        shared = (session_db.query(func.count(BagExpenseInvoice.id))
                  .filter(BagExpenseInvoice.group_key == r.group_key).scalar() or 1)
        out.append({
            "id": str(r.id), "url": r.file_url, "name": r.file_name or "Factura",
            "invoice_number": r.invoice_number or "", "amount": float(_money_or_zero(r.amount)),
            "shared_with": max(int(shared) - 1, 0),   # a cuántos gastos MÁS cubre esta misma factura
        })
    return out


def _personal_expense_allocated(session_db, personal_expense_id) -> Decimal:
    """Cuánto de un gasto importado ya se ha imputado a gastos de bolsa."""
    total = (session_db.query(func.coalesce(func.sum(BagExpenseInvoice.amount), 0))
             .filter(BagExpenseInvoice.personal_expense_id == personal_expense_id).scalar())
    return _money_or_zero(total)


@app.post('/bolsas/<bag_id>/gastos-importados/<expense_id>/vincular/<target_id>', endpoint='bag_imported_expense_link')
@admin_required
def bag_imported_expense_link(bag_id, expense_id, target_id):
    """Vincula un gasto importado (una factura que llegó a «Mis gastos») a un gasto YA EXISTENTE
    de la bolsa, en vez de crear uno nuevo.

    Si la factura vale MÁS que el gasto al que se suelta, no se decide por el usuario: se le
    devuelve la situación para que elija entre subir el importe del gasto o repartir la factura
    entre varios gastos. Con `mode`:
      - (vacío)        → solo pregunta si hace falta decidir; si cuadra, imputa y termina.
      - update_amount  → el gasto pasa a valer lo que la factura.
      - split          → imputa al gasto lo que le corresponde y deja el resto pendiente para
                         soltarlo en otro gasto, hasta repartirlo todo.
    """
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id) or uuid.uuid4())
        row = session_db.get(PersonalExpense, to_uuid(expense_id) or uuid.uuid4())
        target = session_db.get(BagExpense, to_uuid(target_id) or uuid.uuid4())
        if not bag or not row or not target or target.bag_id != bag.id:
            return jsonify({"ok": False, "error": "No encontrado"}), 404
        if not row.file_url:
            return jsonify({"ok": False, "error": "Este gasto no trae ninguna factura que vincular."}), 400

        total = _money_or_zero(row.amount_gross)
        ya = _personal_expense_allocated(session_db, row.id)
        pendiente = total - ya
        if pendiente <= 0:
            return jsonify({"ok": False, "error": "Esta factura ya está repartida del todo."}), 400
        hueco = _money_or_zero(target.amount_gross)
        mode = (request.form.get("mode") or "").strip().lower()

        # Si sobra factura para ese gasto y aún no se ha decidido qué hacer, se pregunta.
        if mode not in ("update_amount", "split") and hueco and pendiente > hueco:
            return jsonify({
                "ok": True, "needs_decision": True,
                "pending": float(pendiente), "expense_amount": float(hueco),
                "expense_concept": (target.concept or "Gasto"),
                "rest": float(pendiente - hueco),
            })

        if mode == "update_amount" or not hueco:
            # El gasto pasa a valer lo que queda de factura (o toda, si no tenía importe).
            imputado = pendiente
            target.amount_gross = pendiente
            if _money_or_zero(target.amount_net) == 0:
                target.amount_net = pendiente
        else:
            # Reparto: a este gasto le entra como mucho lo que vale.
            imputado = min(pendiente, hueco)

        group_key = None
        prev = (session_db.query(BagExpenseInvoice)
                .filter(BagExpenseInvoice.personal_expense_id == row.id).first())
        if prev:
            group_key = prev.group_key
        _bag_expense_invoice_apply(
            session_db, target, file_url=row.file_url, file_name=row.original_name,
            file_mime=getattr(row, "mime_type", None), invoice_number=row.invoice_number,
            amount=imputado, group_key=group_key,
            supplier_invoice_id=getattr(row, "supplier_invoice_id", None), personal_expense_id=row.id,
        )
        session_db.flush()
        restante = total - _personal_expense_allocated(session_db, row.id)
        if restante <= 0:
            row.status = "ASSIGNED"
            row.bag_expense_id = target.id
        session_db.commit()
        return jsonify({
            "ok": True, "needs_decision": False,
            "applied": float(imputado), "remaining": float(max(restante, Decimal("0"))),
            "done": restante <= 0, "expense_id": str(target.id),
        })
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("bag_imported_expense_link")
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.post('/bolsas/<bag_id>/gastos-importados/<expense_id>/tipificar', endpoint='bag_imported_expense_assign')
@admin_required
def bag_imported_expense_assign(bag_id, expense_id):
    """Tipifica un gasto importado dentro de la bolsa: crea su BagExpense en la categoría elegida."""
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id) or uuid.uuid4())
        row = session_db.get(PersonalExpense, to_uuid(expense_id) or uuid.uuid4())
        if not bag or not row:
            return jsonify({"ok": False, "error": "No encontrado"}), 404
        category = (request.form.get("category") or "").strip().upper()
        # ⚠️ Contra el CATÁLOGO (la unión), no contra las categorías de una actividad: si no, en una
        # bolsa de proyecto discográfico no se podría tipificar nada en «Producción audio».
        if category not in BAG_EXPENSE_CATEGORY_LABELS:
            return jsonify({"ok": False, "error": "Categoría no válida"}), 400
        gross = _money_or_zero(row.amount_gross)
        net = _money_or_zero(row.amount_net) or gross
        tax = _money_or_zero(getattr(row, "amount_tax", None))
        if not tax and gross and net and gross >= net:
            tax = gross - net
        # ⚠️ REPARTO: si esta factura ya se imputó en parte a otros gastos (se soltó encima de uno y
        # se eligió «repartir»), aquí solo entra lo que QUEDA. Si no se descontara, el importe se
        # contaría dos veces en la bolsa (una en el gasto al que se imputó y otra completa aquí).
        ya_imputado = _personal_expense_allocated(session_db, row.id)
        if ya_imputado > 0:
            resto = gross - ya_imputado
            if resto <= 0:
                return jsonify({"ok": False, "error": "Esta factura ya está repartida por completo "
                                                     "entre otros gastos de la bolsa."}), 400
            # El neto y el IVA se ajustan a la misma proporción que el importe que queda.
            proporcion = (resto / gross) if gross else Decimal("0")
            net = (net * proporcion).quantize(Decimal("0.01"))
            tax = (resto - net) if resto >= net else Decimal("0")
            gross = resto
        is_pleo = (row.source or "") == "PLEO"
        # El tipo de documento lo trae Pleo (FACTURA si tiene los datos fiscales del proveedor).
        doc_type = (getattr(row, "document_type", "") or "").upper()
        if doc_type not in {"FACTURA", "TICKET"}:
            doc_type = "FACTURA" if (row.source or "") == "INVOICE" else "TICKET"
        expense = BagExpense(
            bag_id=bag.id, category=category,
            concept=(row.concept or "Gasto importado"),
            document_type=doc_type,
            invoice_number=row.invoice_number,
            issue_date=row.expense_date,
            amount_net=net, amount_gross=gross,
            amount_tax=tax,
            attachment_url=row.file_url, attachment_name=row.original_name,
            consolidation_status=("PENDIENTE_VALIDAR" if row.file_url else "PENDIENTE"),
        )
        # Todo lo que viene de PLEO ya está pagado (con la tarjeta Pleo): entra marcado como PAGADO
        # y con «Pleo» como método de pago, para que no se reclame ni se vuelva a pagar.
        if is_pleo:
            expense.payment_status = "PAGADO"
            expense.paid_amount = gross
            expense.payment_method = "Pleo"
        session_db.add(expense)
        session_db.flush()
        # Se anota la imputación de esta factura a este gasto: así el «ya imputado» del reparto
        # sigue cuadrando si la misma factura se reparte entre más gastos.
        if row.file_url:
            _bag_expense_invoice_apply(
                session_db, expense, file_url=row.file_url, file_name=row.original_name,
                file_mime=getattr(row, "file_mime", None), invoice_number=row.invoice_number,
                amount=gross, personal_expense_id=row.id,
            )
        if is_pleo and gross:
            # Queda el rastro del pago para que en la bolsa se vea cuándo y cómo se pagó.
            session_db.add(BagPaymentInteraction(
                expense_id=expense.id, kind="PAGO_REGISTRADO",
                description="Pagado con la tarjeta Pleo (importado de Pleo).",
                amount=gross, method="Pleo",
            ))
        row.bag_id = bag.id
        row.bag_expense_id = expense.id
        row.status = "ASSIGNED"
        row.updated_at = _now_madrid()
        session_db.commit()
        if request.form.get("ajax"):
            return jsonify({"ok": True, "expense_id": str(expense.id), "category": category})
        flash("Gasto añadido a la bolsa.", "success")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/bolsas/<bag_id>/cargar-plantillas', endpoint='bag_load_templates')
@admin_required
def bag_load_templates(bag_id):
    """Carga una o VARIAS plantillas de gastos (del artista y/o del recinto) en la bolsa."""
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id))
        if not bag:
            flash("Bolsa no encontrada.", "warning")
            return redirect(url_for("bags_view"))
        ids = [x for x in request.form.getlist("expense_template_ids[]") if (x or "").strip()]
        if not ids:
            flash("Elige al menos una plantilla de gastos.", "warning")
            return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
        added = 0
        names = []
        for tid in ids:
            tpl = session_db.get(ExpenseTemplate, to_uuid(tid) or uuid.uuid4())
            if not tpl:
                continue
            added += _bag_load_expense_template(session_db, bag, tpl)
            names.append(tpl.name or "Plantilla")
        session_db.commit()
        if added:
            flash(f"Cargados {added} gastos de {', '.join(names)}.", "success")
        else:
            flash("Las plantillas elegidas no tenían gastos.", "warning")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
    except Exception as exc:
        session_db.rollback()
        flash(f"Error cargando plantillas: {exc}", "danger")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag_id)))
    finally:
        session_db.close()


# ---------------------------------------------------------------------------
#  MIS GASTOS · facturas recibidas por el formulario y gastos de Pleo que una
#  persona todavía no ha asignado a una bolsa. Plazo de 1 semana; a los 15 días
#  se escala a dirección (no aplica a dirección).
# ---------------------------------------------------------------------------

EXPENSE_ASSIGN_DAYS = 7          # plazo para asignar un gasto a una bolsa
EXPENSE_ESCALATE_DAYS = 15       # a partir de aquí se avisa a dirección

# --- PARAR EL PLAZO -------------------------------------------------------------------------
# El plazo se puede PARAR por persona (`UserProfile.expense_deadline_paused`) o para TODO el
# personal a la vez (ajuste global, mismas claves que el «modo trabajo»). Mientras está parado:
# no corre la cuenta atrás, no se reclama por correo y no se escala a dirección.
# Los tramos parados se guardan para DESCONTARLOS del plazo al reanudar; si no, al volver a
# activarlo todos los gastos aparecerían de golpe fuera de plazo.
EXPENSE_PAUSE_ALL_KEY = "expense_deadline_pause_all"
EXPENSE_PAUSE_ALL_SINCE_KEY = "expense_deadline_pause_all_since"
EXPENSE_PAUSE_ALL_LOG_KEY = "expense_deadline_pause_all_log"


def _expense_pause_parse_log(raw) -> list:
    """Tramos parados guardados: [{"from": "AAAA-MM-DD", "to": "AAAA-MM-DD"}] → [(desde, hasta)]."""
    if isinstance(raw, str):
        raw = _json_loads_safe(raw, [])
    out = []
    for item in (raw or []):
        if not isinstance(item, dict):
            continue
        try:
            desde = date.fromisoformat(str(item.get("from") or "")[:10])
        except ValueError:
            continue
        try:
            hasta = date.fromisoformat(str(item.get("to") or "")[:10])
        except ValueError:
            hasta = desde
        out.append((desde, max(hasta, desde)))
    return out


def _expense_pause_merge(tramos) -> list:
    """Une los tramos que se solapan y los corta a hoy (un tramo sin fin = sigue parado)."""
    hoy = today_local()
    limpio = []
    for desde, hasta in tramos:
        if not desde:
            continue
        fin = min(hasta or hoy, hoy)
        if fin >= desde:
            limpio.append((desde, fin))
    limpio.sort()
    out = []
    for desde, hasta in limpio:
        if out and desde <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], hasta))
        else:
            out.append((desde, hasta))
    return out


def _expense_paused_days(ref_date, ranges) -> int:
    """Días parados que caen DESPUÉS de recibirse el gasto: los que no cuentan para su plazo."""
    if not ref_date or not ranges:
        return 0
    hoy = today_local()
    total = 0
    for desde, hasta in ranges:
        ini, fin = max(desde, ref_date), min(hasta, hoy)
        if fin > ini:
            # Días COMPLETOS congelados: parar hoy no regala un día, pero parar hace 5 descuenta 5.
            total += (fin - ini).days
    return total


def _expense_pause_global() -> dict:
    """Parada GENERAL del plazo (todo el personal), guardada en los ajustes globales."""
    activa = str(_get_app_setting(EXPENSE_PAUSE_ALL_KEY, "0") or "0") == "1"
    try:
        desde = date.fromisoformat(str(_get_app_setting(EXPENSE_PAUSE_ALL_SINCE_KEY, "") or "")[:10])
    except ValueError:
        desde = None
    return {"paused": activa, "since": desde,
            "log": _expense_pause_parse_log(_get_app_setting(EXPENSE_PAUSE_ALL_LOG_KEY, "[]"))}


def _expense_pause_context(session_db, user_id, global_state=None, profile=None) -> dict:
    """Estado del plazo de UNA persona: su parada, la general, y los tramos a descontar."""
    g = global_state if global_state is not None else _expense_pause_global()
    prof = profile
    if prof is None and user_id:
        prof = (session_db.query(UserProfile)
                .filter(UserProfile.user_id == to_uuid(str(user_id))).first())
    propia = bool(getattr(prof, "expense_deadline_paused", False))
    desde_propia = getattr(prof, "expense_paused_since", None)
    tramos = list(g["log"]) + _expense_pause_parse_log(getattr(prof, "expense_pause_log", None))
    if g["paused"]:
        tramos.append((g["since"] or today_local(), None))
    if propia:
        tramos.append((desde_propia or today_local(), None))
    return {
        "paused": bool(propia or g["paused"]),
        "person_paused": propia,
        "all_paused": bool(g["paused"]),
        "since": (desde_propia if propia else None) or (g["since"] if g["paused"] else None),
        "ranges": _expense_pause_merge(tramos),
    }


def _expense_days_left(row, pause=None) -> int:
    """Días que quedan para asignarlo (negativo = ya pasado el plazo).

    Los días en los que el plazo estuvo PARADO no cuentan.
    """
    ref = getattr(row, "received_at", None) or getattr(row, "created_at", None)
    if not ref:
        return EXPENSE_ASSIGN_DAYS
    try:
        ref_date = ref.date() if hasattr(ref, "date") else ref
    except Exception:
        return EXPENSE_ASSIGN_DAYS
    transcurrido = (today_local() - ref_date).days
    transcurrido -= _expense_paused_days(ref_date, (pause or {}).get("ranges") or [])
    return EXPENSE_ASSIGN_DAYS - max(transcurrido, 0)


def _personal_expense_row(row, pause=None) -> dict:
    days = _expense_days_left(row, pause)
    parado = bool((pause or {}).get("paused"))
    # En Cabify el proveedor ES Cabify y el nº de venta no dice nada a quien asigna el gasto: la
    # línea de datos se queda en «Cabify · fecha» (+ trayecto en el concepto y la etiqueta del viaje).
    es_cabify = (row.source or "") == "CABIFY"
    is_pleo = (row.source or "") == "PLEO"
    # Etiquetas y nota de Pleo: NO clasifican nada, se muestran para que asignar el gasto a su
    # bolsa y tipificarlo sea más fácil (a menudo la nota dice el concierto o el artista).
    tags = []
    for t in (getattr(row, "pleo_tags", None) or []):
        if not isinstance(t, dict):
            continue
        value = (t.get("value") or "").strip()
        if not value:
            continue
        tags.append({"group": (t.get("group") or "").strip(), "value": value})
    files = [f for f in (getattr(row, "pleo_files", None) or []) if isinstance(f, dict) and f.get("url")]
    cat = (getattr(row, "suggested_category", "") or "").upper()
    return {
        "id": str(row.id),
        "source": (row.source or "INVOICE"),
        "source_label": {"PLEO": "Pleo", "INVOICE": "Factura recibida",
                         "CABIFY": "Cabify"}.get((row.source or ""), "Gasto"),
        "source_icon": {"PLEO": "fa-credit-card", "INVOICE": "fa-file-invoice-dollar",
                        "CABIFY": "fa-taxi"}.get((row.source or ""), "fa-receipt"),
        "concept": (row.concept or "Gasto"),
        "provider_name": ("" if es_cabify else (row.provider_name or "")),
        "invoice_number": ("" if es_cabify else (row.invoice_number or "")),
        "date_label": (row.expense_date.strftime("%d/%m/%Y") if row.expense_date else ""),
        "amount_gross": _money_or_zero(row.amount_gross),
        "file_url": (row.file_url or ""),
        "status": (row.status or "PENDING"),
        "bag_id": (str(row.bag_id) if row.bag_id else ""),
        "days_left": days,
        "overdue": days < 0 and not parado,
        "urgent": 0 <= days <= EXPENSE_ASSIGN_DAYS and not parado,
        # Plazo parado: no hay cuenta atrás ni «fuera de plazo» (se dice por qué).
        "deadline_paused": parado,
        "deadline_paused_label": ("Plazo parado para todos" if (pause or {}).get("all_paused")
                                 else "Plazo parado" if parado else ""),
        # --- Pleo ---
        "is_pleo": is_pleo,
        "note": (getattr(row, "pleo_note", "") or ""),
        "tags": tags,
        "files": files,
        "currency": (getattr(row, "currency", "") or "EUR"),
        "document_type": (getattr(row, "document_type", "") or ""),
        "needs_receipt": bool(getattr(row, "needs_receipt", False)) and is_pleo,
        "sync_warning": (getattr(row, "sync_warning", "") or ""),
        "is_cancelled": bool(getattr(row, "is_cancelled", False)),
        "suggested_category": cat,
        "suggested_label": BAG_EXPENSE_CATEGORY_LABELS.get(cat, ""),
        "suggested_icon": BAG_EXPENSE_CATEGORY_ICONS.get(cat, "fa-shapes"),
        "paid_label": ("Pagado con Pleo" if is_pleo else ""),
        # --- Justificante y gastos DIRECTOS (oficina / inversión de artista) ---
        "justification": _personal_expense_justification_state(row),
        "can_go_direct": _personal_expense_has_justification(row),
        "direct_target": ((getattr(row, "direct_target", "") or "").upper()),
        "direct_target_label": PERSONAL_DIRECT_TARGETS.get(
            (getattr(row, "direct_target", "") or "").upper(), ("", ""))[0],
        "direct_target_icon": PERSONAL_DIRECT_TARGETS.get(
            (getattr(row, "direct_target", "") or "").upper(), ("", "fa-receipt"))[1],
        "direct_artist_id": (str(row.direct_artist_id) if getattr(row, "direct_artist_id", None) else ""),
        "validation_status": ((getattr(row, "validation_status", "") or "").upper()),
        "validation_note": (getattr(row, "validation_note", "") or ""),
        "no_invoice_reason": (getattr(row, "no_invoice_reason", "") or ""),
        "no_invoice_status": ((getattr(row, "no_invoice_status", "") or "").upper()),
        "payment_status": ((getattr(row, "payment_status", "") or "NO_PAGADO").upper()),
        "prepaid": _personal_expense_is_prepaid(row),
    }


# ================== GASTOS DIRECTOS: de OFICINA o INVERSIÓN en un ARTISTA ==================
# Son gastos que NO van contra ninguna bolsa. Se mandan desde «Mis gastos» arrastrándolos a la
# primera tarjeta de la pantalla de asignar (partida en dos), y los tiene que VALIDAR
# administración. Requisito para mandarlos: llevar factura/ticket, o que administración haya
# aceptado que no lo lleva (mismo trato que el «sin ticket» de los gastos de bolsa).
PERSONAL_DIRECT_TARGETS = {
    "OFICINA": ("Gasto de oficina", "fa-building-columns"),
    "ARTIST_INVESTMENT": ("Inversión de artista", "fa-arrow-trend-up"),
}


def _personal_expense_has_justification(row) -> bool:
    """¿Se puede mandar a validar? Lleva factura/ticket o el «sin factura» está APROBADO."""
    if (getattr(row, "file_url", None) or "").strip():
        return True
    return (getattr(row, "no_invoice_status", None) or "").upper() == "APROBADO"


def _personal_expense_is_prepaid(row) -> bool:
    """Lo de Pleo y Cabify ya está pagado con la tarjeta de empresa: no genera pendiente de pago."""
    return (getattr(row, "source", "") or "").upper() in ("PLEO", "CABIFY")


def _personal_expense_justification_state(row) -> dict:
    """Semáforo del justificante, para pintar el icono en «Mis gastos» y en la pantalla de asignar."""
    if (getattr(row, "file_url", None) or "").strip():
        tipo = (getattr(row, "document_type", "") or "").upper()
        return {"ok": True, "key": "FILE", "icon": "fa-file-invoice",
                "label": ("Ticket adjunto" if tipo == "TICKET" else "Factura adjunta")}
    estado = (getattr(row, "no_invoice_status", None) or "").upper()
    if estado == "APROBADO":
        return {"ok": True, "key": "NO_INVOICE_OK", "icon": "fa-file-circle-check",
                "label": "Validado sin factura"}
    if estado == "SOLICITADO":
        return {"ok": False, "key": "NO_INVOICE_WAIT", "icon": "fa-file-circle-question",
                "label": "Sin factura, pendiente de que administración lo acepte"}
    if estado == "RECHAZADO":
        return {"ok": False, "key": "NO_INVOICE_KO", "icon": "fa-file-circle-xmark",
                "label": "Administración no aceptó que fuera sin factura"}
    return {"ok": False, "key": "NONE", "icon": "fa-file-circle-xmark",
            "label": "Sin factura ni ticket"}


def _personal_direct_expenses_pending(session_db) -> list[dict]:
    """Gastos directos PENDIENTES de validar por administración (oficina e inversión de artista)."""
    rows = (session_db.query(PersonalExpense)
            .filter(PersonalExpense.status == "VALIDATING")
            .filter(func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "PENDIENTE")
            .order_by(PersonalExpense.validation_requested_at.asc().nullslast()).all())
    out = []
    for r in rows:
        artista = session_db.get(Artist, r.direct_artist_id) if r.direct_artist_id else None
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        etiqueta, icono = PERSONAL_DIRECT_TARGETS.get((r.direct_target or "").upper(),
                                                      ("Gasto directo", "fa-receipt"))
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "amount_gross": _money_or_zero(r.amount_gross),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "file_url": (r.file_url or ""),
            "justification": _personal_expense_justification_state(r),
            "target": (r.direct_target or "").upper(), "target_label": etiqueta, "target_icon": icono,
            "artist_name": (getattr(artista, "name", "") or ""),
            "artist_photo": (getattr(artista, "photo_url", "") or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "Alguien",
            "prepaid": _personal_expense_is_prepaid(r),
        })
    return out


def _personal_no_invoice_pending(session_db) -> list[dict]:
    """Gastos personales cuyo dueño pide que se acepten SIN factura."""
    rows = (session_db.query(PersonalExpense)
            .filter(func.upper(func.coalesce(PersonalExpense.no_invoice_status, "")) == "SOLICITADO")
            .order_by(PersonalExpense.updated_at.desc().nullslast()).all())
    out = []
    for r in rows:
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "amount_gross": _money_or_zero(r.amount_gross),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "reason": (r.no_invoice_reason or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "Alguien",
        })
    return out


def _personal_direct_expenses_payable(session_db) -> list[dict]:
    """Gastos directos ya validados y sin pagar (los de Pleo/Cabify ya están pagados)."""
    rows = (session_db.query(PersonalExpense)
            .filter(PersonalExpense.status == "DIRECT")
            .filter(func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "APROBADO")
            .filter(func.upper(func.coalesce(PersonalExpense.payment_status, "NO_PAGADO")) != "PAGADO")
            .order_by(PersonalExpense.validated_at.asc().nullslast()).all())
    out = []
    for r in rows:
        if _personal_expense_is_prepaid(r):
            continue
        artista = session_db.get(Artist, r.direct_artist_id) if r.direct_artist_id else None
        etiqueta, icono = PERSONAL_DIRECT_TARGETS.get((r.direct_target or "").upper(),
                                                      ("Gasto directo", "fa-receipt"))
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "amount_gross": _money_or_zero(r.amount_gross),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "file_url": (r.file_url or ""),
            "target_label": etiqueta, "target_icon": icono,
            "artist_name": (getattr(artista, "name", "") or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "Alguien",
        })
    return out


def _artist_investment_rows(session_db, artist_id) -> dict:
    """Balance de gasto de INVERSIÓN de un artista: los gastos directos validados que se le han
    imputado. Es lo que se enseña en su ficha."""
    aid = to_uuid(str(artist_id)) if artist_id else None
    if not aid:
        return {"rows": [], "total": Decimal("0")}
    rows = (session_db.query(PersonalExpense)
            .filter(PersonalExpense.direct_artist_id == aid)
            .filter(PersonalExpense.status == "DIRECT")
            .filter(func.upper(func.coalesce(PersonalExpense.validation_status, "")) == "APROBADO")
            .order_by(PersonalExpense.expense_date.desc().nullslast()).all())
    out, total = [], Decimal("0")
    for r in rows:
        importe = _money_or_zero(r.amount_gross)
        total += importe
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == r.user_id).first()
        out.append({
            "id": str(r.id), "concept": (r.concept or "Gasto"),
            "provider_name": (r.provider_name or ""),
            "date_label": (r.expense_date.strftime("%d/%m/%Y") if r.expense_date else ""),
            "amount_gross": importe,
            "file_url": (r.file_url or ""),
            "person": ((prof.nick if prof else "") or "").strip() or "",
            "paid": (r.payment_status or "").upper() == "PAGADO" or _personal_expense_is_prepaid(r),
        })
    # Lo gastado en PROMOCIÓN también es inversión en el artista: todo lo que se le imputa aparece
    # aquí, aunque además se vea en la ficha del single o del disco que se promocionaba (allí es el
    # mismo dinero visto desde otro sitio; el total de cada pantalla cuenta cada gasto UNA vez).
    promo = _promo_spend_rows(session_db, artist_id=aid)
    for row in promo.get("rows") or []:
        total += row["amount_gross"]
        out.append({
            "id": row["id"],
            "concept": f"Promoción · {row['title']}" + (f" ({row['subject_label']})" if row.get("subject_label") else ""),
            "provider_name": "",
            "date_label": row["date_label"],
            "amount_gross": row["amount_gross"],
            "file_url": "",
            "person": "",
            "paid": True,
            "promo_url": row["detail_url"],
        })
    return {"rows": out, "total": total}


def _user_is_direccion(session_db, user_id) -> bool:
    """Dirección «pura»: role 10 (la regla de plazos no les aplica)."""
    try:
        u = session_db.get(User, to_uuid(str(user_id)))
        return bool(u) and int(getattr(u, "role", 0) or 0) == 10
    except Exception:
        return False


def _personal_expenses_for(session_db, user_id, status=("PENDING",)) -> list:
    uid = to_uuid(str(user_id)) if user_id else None
    if not uid:
        return []
    q = (session_db.query(PersonalExpense)
         .filter(PersonalExpense.user_id == uid))
    if status:
        q = q.filter(PersonalExpense.status.in_(list(status)))
    pause = _expense_pause_context(session_db, uid)
    return [_personal_expense_row(r, pause) for r in q.order_by(PersonalExpense.received_at.asc()).all()]


def _open_bags_for_user(session_db, user_id, artist_query: str = "") -> list:
    """Bolsas NO cerradas agrupadas por artista, ordenadas por proximidad de la actividad.
    Por defecto las del usuario (sus artistas asignados); con `artist_query` busca otras."""
    closed = {"CERRADA", "LIQUIDADA", "ARCHIVADA"}
    bags = (session_db.query(WorkflowBag)
            .filter(WorkflowBag.is_archived == False)     # noqa: E712
            .order_by(WorkflowBag.start_date.desc().nullslast())
            .all())
    assigned_ids = set()
    if user_id and not _user_is_direccion(session_db, user_id):
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == to_uuid(str(user_id))).first()
        assigned_ids = {str(x) for x in ((getattr(prof, "assigned_artist_ids", None) or []) if prof else [])}
    want = _norm_text_key(artist_query or "")
    groups = {}
    for bag in bags:
        if (bag.status or "").upper() in closed:
            continue
        artists = _bag_artist_rows(session_db, bag)
        art = artists[0] if artists else None
        aid = str(art.id) if art else ""
        art_name = (art.name if art else "Sin artista")
        if want:
            if want not in _norm_text_key(art_name):
                continue
        elif assigned_ids and aid and aid not in assigned_ids:
            continue
        g = groups.setdefault(aid or "sin", {
            "artist_id": aid, "artist_name": art_name,
            "artist_photo": ((getattr(art, "photo_url", "") or "") if art else ""),
            "bags": [],
        })
        g["bags"].append({
            "id": str(bag.id),
            "title": (bag.title or "Bolsa"),
            "date": bag.start_date,
            "date_label": (bag.start_date.strftime("%d/%m/%Y") if bag.start_date else ""),
            "linked_title": (bag.linked_title or ""),
            "status": (bag.status or ""),
        })
    out = list(groups.values())
    today = date.today()
    for g in out:
        g["bags"].sort(key=lambda b: abs((b["date"] - today).days) if b["date"] else 99999)
        g["next_date"] = g["bags"][0]["date"] if g["bags"] and g["bags"][0]["date"] else None
    out.sort(key=lambda g: abs((g["next_date"] - today).days) if g["next_date"] else 99999)
    return out


def _bag_expense_has_invoice(expense) -> bool:
    """¿Este gasto ya tiene su factura/justificante subido? (o está justificado sin factura)."""
    if (getattr(expense, "attachment_url", None) or "").strip():
        return True
    if (getattr(expense, "no_invoice_reason", None) or "").strip():
        return True
    return (getattr(expense, "consolidation_status", "") or "").upper() in BAG_CONSOLIDATED_STATUSES


def _bag_providers_pending_invoice(session_db, bag) -> list[dict]:
    """Proveedores de la bolsa con conceptos SIN factura subida, con sus importes."""
    expenses = (session_db.query(BagExpense)
                .options(joinedload(BagExpense.provider))
                .filter(BagExpense.bag_id == bag.id, BagExpense.status != "ELIMINADO")
                .order_by(BagExpense.category.asc(), BagExpense.sort_order.asc())
                .all())
    by_provider = {}
    for exp in expenses:
        if _bag_expense_has_invoice(exp):
            continue
        provider = getattr(exp, "provider", None)
        if not provider:
            continue
        row = by_provider.setdefault(str(provider.id), {
            "provider": provider,
            "provider_id": str(provider.id),
            "name": provider.nick or "Proveedor",
            "logo_url": (provider.logo_url or ""),
            "email": (provider.contact_email or ""),
            "items": [],
            "net": Decimal("0"),
            "gross": Decimal("0"),
        })
        net = _money_or_zero(getattr(exp, "amount_net", 0))
        gross = _money_or_zero(getattr(exp, "amount_gross", 0)) or net
        row["items"].append({
            "id": str(exp.id),
            "concept": (exp.concept or "Gasto"),
            "category": _bag_expense_display_cat(getattr(exp, "category", "OTROS")),
            "net": net,
            "gross": gross,
        })
        row["net"] += net
        row["gross"] += gross
    rows = list(by_provider.values())
    rows.sort(key=lambda r: r["name"].lower())
    return rows


def _bag_invoice_request_email_html(bag, concert, provider_row, link: str, required_docs: list) -> str:
    """Correo al proveedor con la cabecera del evento, sus conceptos con importes (con y sin IVA)
    y el botón para subir la factura de cada uno."""
    if concert is not None:
        header = _concert_email_header_html(concert, "Solicitud de factura")
    else:
        header = (f"<h2 style='text-align:center;color:#111;margin:0 0 12px;'>Solicitud de factura</h2>"
                  f"<p style='text-align:center;color:#64748b;margin:0 0 16px;'>{escape(bag.title or 'Bolsa')}</p>")
    rows = ""
    for it in provider_row["items"]:
        rows += (
            "<tr>"
            f"<td style='padding:7px 9px;border-bottom:1px solid #eceef1;font-size:13px;color:#111'>{escape(it['concept'])}</td>"
            f"<td style='padding:7px 9px;border-bottom:1px solid #eceef1;font-size:13px;text-align:right;white-space:nowrap'>{format_eur(it['net'])}</td>"
            f"<td style='padding:7px 9px;border-bottom:1px solid #eceef1;font-size:13px;text-align:right;white-space:nowrap'>{format_eur(it['gross'])}</td>"
            "</tr>"
        )
    th = "padding:7px 9px;border-bottom:2px solid #E33D48;font-size:12px;color:#6b7280;text-transform:uppercase;text-align:left"
    docs_html = ""
    if required_docs:
        labels = [PRL_DOC_LABELS.get(d, d) for d in required_docs]
        docs_html = ("<p style='margin:14px 0 0;color:#b45309;font-size:13px;'><strong>Además necesitamos:</strong> "
                     + escape(", ".join(labels)) + ". Podrás subirlo en la misma página.</p>")
    return f"""
    {header}
    <p style="margin:16px 0 6px;">Hola {escape(provider_row['name'])},</p>
    <p style="margin:0 0 12px;">Nos falta tu <strong>factura</strong> de {'estos conceptos' if len(provider_row['items']) > 1 else 'este concepto'}:</p>
    <table style="width:100%;border-collapse:collapse;margin:0 0 8px;">
      <thead><tr><th style="{th}">Concepto</th><th style="{th};text-align:right">Sin IVA</th><th style="{th};text-align:right">Con IVA</th></tr></thead>
      <tbody>{rows}</tbody>
      <tfoot><tr>
        <td style="padding:8px 9px;font-size:13px;font-weight:700;color:#111">Total</td>
        <td style="padding:8px 9px;font-size:13px;font-weight:700;text-align:right;white-space:nowrap">{format_eur(provider_row['net'])}</td>
        <td style="padding:8px 9px;font-size:13px;font-weight:700;text-align:right;white-space:nowrap">{format_eur(provider_row['gross'])}</td>
      </tr></tfoot>
    </table>
    {docs_html}
    <p style="text-align:center;margin:20px 0;">
      <a href="{link}" style="background:#E33D48;color:#fff;text-decoration:none;padding:12px 26px;border-radius:8px;font-weight:600;display:inline-block;">Subir mi factura</a>
    </p>
    <p style="margin:0;color:#64748b;font-size:13px;">Puedes arrastrar el archivo o hacer una foto: se sube directamente y nos llega al momento.</p>
    """


@app.post('/bolsas/<bag_id>/solicitar-facturas', endpoint='bag_request_invoices')
@admin_required
def bag_request_invoices(bag_id):
    """Pide la factura a TODOS los proveedores de la bolsa que aún no la han subido."""
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id))
        if not bag:
            flash("Bolsa no encontrada.", "warning")
            return redirect(url_for("bags_view"))
        concert = None
        if (bag.linked_type or "").upper() == "CONCERT" and bag.linked_id:
            concert = session_db.get(Concert, bag.linked_id)
        required_docs = [d for d in request.form.getlist("required_docs") if d in PRL_DOC_LABELS]
        only_provider = (request.form.get("provider_id") or "").strip()
        rows = _bag_providers_pending_invoice(session_db, bag)
        if only_provider:
            rows = [r for r in rows if r["provider_id"] == only_provider]
        sent, errors = 0, []
        for row in rows:
            req = (session_db.query(BagInvoiceRequest)
                   .filter(BagInvoiceRequest.bag_id == bag.id,
                           BagInvoiceRequest.provider_id == row["provider"].id,
                           BagInvoiceRequest.status == "ACTIVE")
                   .first())
            if not req:
                req = BagInvoiceRequest(public_token=uuid.uuid4().hex, bag_id=bag.id,
                                        provider_id=row["provider"].id, status="ACTIVE")
                session_db.add(req)
            req.expense_ids = [it["id"] for it in row["items"]]
            req.required_docs = required_docs
            session_db.flush()
            # Dominio NUEVO siempre (host canónico), nunca el de la petición: ver _public_base_url.
            link = _external_url_for("public_bag_invoice_upload", token=req.public_token)
            emails = [e["email"] for e in _bag_provider_email_suggestions(session_db, SimpleNamespace(provider=row["provider"], provider_id=row["provider"].id))]
            if not emails:
                errors.append(f"{row['name']}: sin correo")
                continue
            ok, err = _send_optional_email(
                emails[:3],
                f"Solicitud de factura · {(concert.artist.name + ' · ' if concert is not None and concert.artist else '')}{bag.title or 'Bolsa'}",
                _bag_invoice_request_email_html(bag, concert, row, link, required_docs),
            )
            if ok:
                sent += 1
                req.last_sent_at = _now_madrid()
                req.recipients_json = emails[:3]
            else:
                errors.append(f"{row['name']}: {err or 'error al enviar'}")
        session_db.commit()
        if sent:
            flash(f"Solicitud de factura enviada a {sent} proveedor{'es' if sent != 1 else ''}."
                  + (f" Incidencias: {'; '.join(errors)}" if errors else ""),
                  "warning" if errors else "success")
        elif errors:
            flash("No se pudo enviar: " + "; ".join(errors), "danger")
        else:
            flash("Todos los proveedores tienen ya su factura subida.", "info")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag.id)))
    except Exception as exc:
        session_db.rollback()
        flash(f"Error solicitando facturas: {exc}", "danger")
        return redirect(safe_next_or(url_for("bag_detail_view", bag_id=bag_id)))
    finally:
        session_db.close()


INVOICE_REQUEST_VAT_PCT = Decimal("21")   # IVA general: es el que se le pide salvo excepción


def _invoice_request_amounts(net, gross, *, vat_pct=None) -> dict:
    """Lo que hay que facturar de un concepto: **base + IVA**.

    En pantalla salían ceros porque se cogía el importe tal cual del gasto y no siempre están los dos
    (unos gastos se apuntan solo con el bruto y otros solo con la base). Aquí se completa el que
    falte: con la base se calcula el IVA, y con el bruto se despeja la base. El importe a facturar es
    SIEMPRE con IVA."""
    pct = _money_or_zero(vat_pct if vat_pct is not None else INVOICE_REQUEST_VAT_PCT)
    base = _money_or_zero(net)
    total = _money_or_zero(gross)
    factor = (Decimal("1") + (pct / Decimal("100"))) if pct > 0 else Decimal("1")
    if base > 0 and total <= base:
        total = (base * factor).quantize(Decimal("0.01"))
    elif total > 0 and base <= 0:
        base = (total / factor).quantize(Decimal("0.01")) if factor else total
    iva = total - base
    if iva < 0:
        iva = Decimal("0")
    return {
        "net": base,
        "vat": iva,
        "gross": total,
        "vat_pct": pct,
        # Sin importe no se puede pedir una cantidad concreta: se avisa en vez de enseñar 0,00 €.
        "unknown": bool(base <= 0 and total <= 0),
    }


def _expense_supplements(expense) -> list[dict]:
    """SUPLIDOS de un gasto, normalizados: `[{"concept": str, "amount": Decimal|None}]`.

    Son gastos que el mismo tercero factura ADEMÁS de su trabajo (la gasolina del músico). Sin
    importe = todavía no se sabe y se le pregunta al subir la factura."""
    salida = []
    for fila in (getattr(expense, "supplements", None) or []):
        if not isinstance(fila, dict):
            continue
        concepto = str(fila.get("concept") or "").strip()
        if not concepto:
            continue
        crudo = fila.get("amount")
        importe = None
        if crudo not in (None, ""):
            try:
                importe = _money_or_zero(crudo)
            except Exception:
                importe = None
            if importe is not None and importe <= 0:
                importe = None
        salida.append({"concept": concepto[:200], "amount": importe})
    return salida


def _expense_supplements_total(expense) -> Decimal:
    """Lo que suman los suplidos que YA tienen importe (sin IVA: los suplidos no lo llevan)."""
    return sum((s["amount"] for s in _expense_supplements(expense) if s["amount"] is not None),
               Decimal("0"))


def _expense_invoice_breakdown(expense) -> dict:
    """Lo que hay que FACTURAR de un gasto: su trabajo (base + IVA) MÁS los suplidos SIN IVA.

    ⚠️ `BagExpense.amount_gross` incluye los suplidos (es lo que hay que facturar y pagar), así que
    la parte con IVA es `amount_gross − suplidos`: por eso el desglose no se puede sacar del bruto a
    secas. Los suplidos no llevan IVA ni retención."""
    suplidos = _expense_supplements(expense)
    total_sup = sum((s["amount"] for s in suplidos if s["amount"] is not None), Decimal("0"))
    bruto = _money_or_zero(getattr(expense, "amount_gross", 0))
    gravable = bruto - total_sup
    if gravable < 0:
        gravable = Decimal("0")
    imp = _invoice_request_amounts(getattr(expense, "amount_net", 0), gravable)
    return {
        "net": imp["net"],
        "vat": imp["vat"],
        "vat_pct": imp["vat_pct"],
        "supplements": suplidos,
        "supplements_total": total_sup,
        "supplements_pending": [s for s in suplidos if s["amount"] is None],
        "gross": imp["gross"] + total_sup,
        "unknown": bool(imp["unknown"] and not total_sup),
    }


def _bag_invoice_request_context(session_db, req):
    """Contexto de la página pública de subida de facturas de un proveedor."""
    bag = session_db.get(WorkflowBag, req.bag_id)
    provider = session_db.get(Promoter, req.provider_id)
    concert = None
    if bag is not None and (bag.linked_type or "").upper() == "CONCERT" and bag.linked_id:
        concert = session_db.get(Concert, bag.linked_id)
    ids = [to_uuid(x) for x in (req.expense_ids or []) if to_uuid(x)]
    expenses = []
    if ids:
        expenses = (session_db.query(BagExpense)
                    .filter(BagExpense.id.in_(ids), BagExpense.status != "ELIMINADO")
                    .order_by(BagExpense.category.asc(), BagExpense.sort_order.asc())
                    .all())
    rows = []
    for exp in expenses:
        importes = _expense_invoice_breakdown(exp)
        rows.append({
            "id": str(exp.id),
            "concept": (exp.concept or "Gasto"),
            "category_label": dict(BAG_EXPENSE_CATEGORIES).get(_bag_expense_display_cat(exp.category), exp.category or ""),
            "net": importes["net"],
            "vat": importes["vat"],
            "vat_pct": importes["vat_pct"],
            "gross": importes["gross"],
            "unknown": importes["unknown"],
            # SUPLIDOS: se enseñan aparte (no llevan IVA) y los que no tienen importe se le
            # preguntan antes de subir la factura.
            "supplements": importes["supplements"],
            "supplements_total": importes["supplements_total"],
            "supplements_pending": importes["supplements_pending"],
            "has_invoice": _bag_expense_has_invoice(exp),
            "invoice_name": (getattr(exp, "attachment_name", None) or ""),
            "invoice_url": (getattr(exp, "attachment_url", None) or ""),
        })
    # Documentación adicional exigida y si ya está en vigor (se reutiliza el sistema de PRL).
    docs = []
    today = date.today()
    for key in (req.required_docs or []):
        existing = None
        if provider is not None:
            existing = (session_db.query(PersonComplianceDoc)
                        .filter(PersonComplianceDoc.owner_type == "PROMOTER",
                                PersonComplianceDoc.owner_id == provider.id,
                                PersonComplianceDoc.doc_type == key)
                        .order_by(PersonComplianceDoc.created_at.desc()).first())
        docs.append({
            "key": key,
            "label": PRL_DOC_LABELS.get(key, key),
            "ok": bool(existing and _prl_doc_valid_on(existing, today)),
            "url": (existing.file_url if existing else ""),
        })
    return {
        "req": req, "bag": bag, "provider": provider, "concert": concert,
        "artist": (session_db.get(Artist, concert.artist_id) if concert is not None and concert.artist_id else None),
        "venue": (session_db.get(Venue, concert.venue_id) if concert is not None and concert.venue_id else None),
        "rows": rows,
        "net_total": sum((r["net"] for r in rows), Decimal("0")),
        "gross_total": sum((r["gross"] for r in rows), Decimal("0")),
        "required_docs": docs,
        "all_done": bool(rows) and all(r["has_invoice"] for r in rows) and all(d["ok"] for d in docs),
    }


# ---------------------------------------------------------------------------
#  FACTURACIÓN · landing pública /facturacion (3 pasos) y su reutilización en
#  las peticiones de factura (bolsa / liquidación de royalties).
# ---------------------------------------------------------------------------

def _tax_id_kind(value: str) -> str:
    """EMPRESA si empieza por letra (CIF), PARTICULAR si termina en letra (DNI/NIE)."""
    v = re.sub(r"[^0-9A-Za-z]", "", (value or "")).upper()
    if not v:
        return ""
    if v[0].isalpha():
        return "EMPRESA"
    if v[-1].isalpha():
        return "PARTICULAR"
    return "PARTICULAR"


def _mask_value(value: str, keep: int = 4) -> str:
    """Enmascara un dato personal dejando solo los últimos caracteres a la vista: quien teclea un
    DNI ajeno NO puede leer el IBAN, el correo ni el teléfono completos del titular."""
    v = (value or "").strip()
    if not v:
        return ""
    if "@" in v:
        user, _, dom = v.partition("@")
        head = user[:2] if len(user) > 2 else user[:1]
        return f"{head}{'•' * max(3, len(user) - len(head))}@{dom}"
    if len(v) <= keep:
        return "•" * len(v)
    return "•" * (len(v) - keep) + v[-keep:]


def _cert_month_range(today=None):
    """Vigencia de los certificados mensuales: del 1 al último día del mes en vigor."""
    d = today or date.today()
    return date(d.year, d.month, 1), _prl_month_end(d.year, d.month)


# A un PARTICULAR hay que preguntarle CÓMO factura antes de pedirle papeles: si es autónomo basta el
# último recibo de autónomos; si se da de alta puntual hacen falta el alta y la baja, y valen si la
# factura está emitida DENTRO del periodo de alta (alta y baja incluidas).
BILLING_WORKER_TYPES = [
    ("AUTONOMO", "Soy autónomo", "fa-user-tie",
     "Tengo alta de autónomos y facturo con mi recibo al día."),
    ("PUNTUAL", "Alta puntual", "fa-calendar-check",
     "Me dan de alta solo para este trabajo y luego me dan de baja."),
]
BILLING_WORKER_LABELS = {k: l for k, l, _i, _d in BILLING_WORKER_TYPES}
# Papeles del alta según cómo facture (los del PRL, que ya sabe leer sus fechas).
BILLING_ALTA_DOCS = {
    "AUTONOMO": [("AUTONOMO_RECIBO", "Último recibo de autónomos", "fa-receipt")],
    "PUNTUAL": [("ALTA_SS", "Alta en la Seguridad Social", "fa-user-plus"),
                ("BAJA_SS", "Baja en la Seguridad Social", "fa-user-minus")],
}


def _billing_required_docs(kind: str, worker_type: str | None = None) -> list:
    """Documentos que se exigen para poder dejar la factura subida."""
    out = [{"key": "INVOICE", "label": "Factura", "icon": "fa-file-invoice-dollar", "link": ""}]
    # Particular: primero cómo factura y después SUS papeles del alta.
    wt = (worker_type or "").strip().upper()
    if kind != "EMPRESA" and wt in BILLING_ALTA_DOCS:
        for key, label, icon in BILLING_ALTA_DOCS[wt]:
            out.append({"key": key, "label": label, "icon": icon, "link": ""})
    for key, label, icon, who, link in INVOICE_CERT_DOCS:
        if who == "ambos" or (who == "empresa" and kind == "EMPRESA"):
            out.append({"key": key, "label": label, "icon": icon, "link": link})
    return out


def _billing_alta_doc_ok(session_db, promoter, worker_type: str, issue_date=None) -> dict:
    """¿Están en vigor los papeles del alta del particular para ESTA factura?

    · Autónomo: el recibo vale el mes que le toca (lo calcula `_prl_detect` al subirlo).
    · Alta puntual: el alta y la baja tienen que cubrir la FECHA DE EMISIÓN de la factura (alta
      incluida y baja inclusive). Sin fecha de emisión se comprueba a día de hoy."""
    wt = (worker_type or "").strip().upper()
    dia = issue_date or today_local()
    salida = {}
    for key, _label, _icon in BILLING_ALTA_DOCS.get(wt, []):
        docs = []
        if promoter is not None:
            docs = (session_db.query(PersonComplianceDoc)
                    .filter(PersonComplianceDoc.owner_type == "PROMOTER",
                            PersonComplianceDoc.owner_id == promoter.id,
                            PersonComplianceDoc.doc_type == key)
                    .order_by(PersonComplianceDoc.created_at.desc()).limit(12).all())
        bueno = next((d for d in docs if _prl_doc_valid_on(d, dia)), None)
        salida[key] = {"ok": bool(bueno), "url": (bueno.file_url if bueno else "")}
    return salida


def _billing_docs_state(session_db, promoter, kind: str, worker_type: str | None = None,
                        issue_date=None) -> list:
    """Estado de los documentos exigidos: los que ya están EN VIGOR no se vuelven a pedir."""
    rows = []
    valid_from, valid_until = _cert_month_range()
    wt = (worker_type or getattr(promoter, "prl_type", None) or "").strip().upper()
    alta = _billing_alta_doc_ok(session_db, promoter, wt, issue_date=issue_date) if kind != "EMPRESA" else {}
    for doc in _billing_required_docs(kind, wt):
        if doc["key"] == "INVOICE":
            rows.append({**doc, "ok": False, "existing_url": "", "note": ""})
            continue
        if doc["key"] in alta:
            estado = alta[doc["key"]]
            rows.append({
                **doc,
                "ok": bool(estado["ok"]),
                "existing_url": estado["url"],
                "note": ("Ya subido y en vigor" if estado["ok"] else
                         ("Tiene que cubrir la fecha de la factura" if wt == "PUNTUAL"
                          else "Tiene que ser el del último periodo")),
            })
            continue
        existing = None
        if promoter is not None:
            existing = (session_db.query(PersonComplianceDoc)
                        .filter(PersonComplianceDoc.owner_type == "PROMOTER",
                                PersonComplianceDoc.owner_id == promoter.id,
                                PersonComplianceDoc.doc_type == doc["key"],
                                PersonComplianceDoc.status == "APPROVED")
                        .order_by(PersonComplianceDoc.created_at.desc()).first())
        ok = bool(existing and (existing.valid_until or date.min) >= valid_until)
        rows.append({
            **doc,
            "ok": ok,
            "existing_url": (existing.file_url if (existing and ok) else ""),
            "note": ("Documento ya subido anteriormente y en vigor" if ok
                     else "Solo vale el del mes en vigor"),
        })
    return rows


def _promoter_artist_context(session_db, promoter) -> dict:
    """¿De qué ARTISTA forma parte este tercero? Se mira por partida doble:
    - es una PERSONA de un artista (`ArtistPerson.promoter_id`: miembro del grupo, el propio solista);
    - está VINCULADO a un artista por vinculaciones (mánager, técnico, la sociedad que le factura…).

    Sirve para que quien sube una factura se reconozca («Miembro de Los X») y para rellenar solo el
    ARTISTA de la factura, que es el dato que administración necesita para tramitarla.
    """
    if promoter is None:
        return {"names": [], "label": "", "is_member": False}
    nombres, es_miembro = [], False
    try:
        for (nombre,) in (session_db.query(Artist.name)
                          .join(ArtistPerson, ArtistPerson.artist_id == Artist.id)
                          .filter(ArtistPerson.promoter_id == promoter.id)
                          .order_by(Artist.name.asc()).all()):
            if nombre and nombre not in nombres:
                nombres.append(nombre)
                es_miembro = True
    except Exception:
        pass
    try:
        ids = set()
        for link in (session_db.query(ThirdPartyLink)
                     .filter(ThirdPartyLink.is_active.is_(True))
                     .filter(or_(and_(ThirdPartyLink.source_type == "promoter",
                                      ThirdPartyLink.source_id == promoter.id,
                                      ThirdPartyLink.target_type == "artist"),
                                 and_(ThirdPartyLink.target_type == "promoter",
                                      ThirdPartyLink.target_id == promoter.id,
                                      ThirdPartyLink.source_type == "artist"))).all()):
            ids.add(link.target_id if link.target_type == "artist" else link.source_id)
        if ids:
            for (nombre,) in (session_db.query(Artist.name)
                              .filter(Artist.id.in_(list(ids)))
                              .order_by(Artist.name.asc()).all()):
                if nombre and nombre not in nombres:
                    nombres.append(nombre)
    except Exception:
        pass
    return {"names": nombres, "label": " · ".join(nombres), "is_member": es_miembro}


def _billing_profile_payload(session_db, promoter) -> dict:
    """Datos de facturación del proveedor, con los personales ENMASCARADOS, y qué falta."""
    kind = "EMPRESA" if (promoter.kind or "").lower() == "empresa" else _tax_id_kind(promoter.tax_id or "")
    company = None
    if kind == "EMPRESA":
        company = (session_db.query(PromoterCompany)
                   .filter(PromoterCompany.promoter_id == promoter.id)
                   .order_by(PromoterCompany.created_at.asc()).first())
    contact = (session_db.query(PromoterContact)
               .filter(PromoterContact.promoter_id == promoter.id)
               .order_by(PromoterContact.created_at.asc()).first())
    full_name = " ".join([x for x in [(promoter.first_name or "").strip(), (promoter.last_name or "").strip()] if x]).strip()
    contact_name = " ".join([x for x in [(contact.first_name or "").strip() if contact else "",
                                         (contact.last_name or "").strip() if contact else ""] if x]).strip()
    # DIRECCIÓN FISCAL EN PIEZAS: la de la sociedad si la tiene y, si no, la del tercero. El texto
    # junto es solo para MOSTRARLO; lo que hace falta para contabilizar son las piezas.
    piezas = _fiscal_parts_for_form(company if (company is not None
                                                and (getattr(company, "fiscal_address", None)
                                                     or getattr(company, "fiscal_postal_code", None)))
                                    else promoter)
    fiscal = (_fiscal_address_text(company if company is not None else promoter)
              or piezas["address"] or (promoter.address or "").strip())
    missing = []
    if kind == "EMPRESA":
        if not (promoter.nick or "").strip():
            missing.append("company_name")
        if not contact_name:
            missing.append("contact_name")
    else:
        if not full_name:
            missing.append("full_name")
    if not piezas["address"] and not fiscal:
        missing.append("fiscal_address")
    # ⚠️ Sin código postal, municipio y provincia no se puede dar de alta al proveedor en la
    # contabilidad: se le piden aunque ya tuviera la dirección puesta de un tirón.
    if not piezas["postal_code"]:
        missing.append("fiscal_postal_code")
    if not piezas["city"]:
        missing.append("fiscal_city")
    if not piezas["province"]:
        missing.append("fiscal_province")
    if not (promoter.contact_email or "").strip():
        missing.append("email")
    if not (promoter.contact_phone or "").strip():
        missing.append("phone")
    if not (promoter.bank_account or "").strip():
        missing.append("bank_account")
    return {
        "id": str(promoter.id),
        "kind": kind,
        "tax_id": (promoter.tax_id or ""),
        "label": (promoter.nick or full_name or "Proveedor"),
        "full_name": full_name,
        "company_name": (promoter.nick or ""),
        "contact_name": contact_name,
        # Enmascarados: se ven lo justo para reconocerse, no para copiarlos.
        "fiscal_address_masked": _mask_value(fiscal, 6),
        "email_masked": _mask_value(promoter.contact_email or ""),
        "phone_masked": _mask_value(promoter.contact_phone or "", 3),
        "bank_masked": _mask_value(promoter.bank_account or ""),
        "has_fiscal": bool(fiscal),
        # Solo se le pide FOTO (o logo) si no tiene ninguna: si ya la tiene, ese hueco no aparece.
        "has_photo": bool((promoter.logo_url or "").strip()),
        # Lo que YA tenemos, campo por campo, para MOSTRARLO en el formulario (censurado) en vez de
        # dejarlo en blanco: así se ve el registro completo y solo se teclea lo que falta. El nombre
        # se ve tal cual (ya sale en la cabecera); el resto, enmascarado.
        "shown": {k: v for k, v in {
            "full_name": full_name,
            "company_name": ((promoter.nick or "").strip() if kind == "EMPRESA" else ""),
            "contact_name": contact_name,
            "fiscal_address": _mask_value(piezas["address"], 6),
            # El código postal, el municipio y la provincia se ven TAL CUAL: no son un dato sensible
            # y así se comprueba de un vistazo que están bien.
            "fiscal_postal_code": piezas["postal_code"],
            "fiscal_city": piezas["city"],
            "fiscal_province": piezas["province"],
            "email": _mask_value(promoter.contact_email or ""),
            "phone": _mask_value(promoter.contact_phone or "", 3),
            "bank_account": _mask_value(promoter.bank_account or ""),
        }.items() if v},
        "missing": missing,
        "complete": not missing,
        # CÓMO factura un particular (autónomo / alta puntual): de eso dependen los papeles del alta
        # que hay que pedirle. Si ya lo dijo alguna vez, no se le vuelve a preguntar.
        "worker_type": ((getattr(promoter, "prl_type", None) or "").strip().upper()
                        if kind != "EMPRESA" else ""),
        # Artista del que forma parte (miembro del grupo o vinculado): se muestra al identificarse y
        # rellena el artista de la factura.
        **{f"artist_{k}": v for k, v in _promoter_artist_context(session_db, promoter).items()},
    }


def _company_slug(name: str) -> str:
    """Slug de una empresa del grupo para la URL: sin acentos, minúsculas y sin separadores."""
    base = unicodedata.normalize("NFD", (name or "")).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"[^a-z0-9]", "", base.lower())


def _find_group_company_by_slug(session_db, slug: str):
    """Empresa del grupo cuyo nombre encaja con el slug de la URL (/facturacion_<empresa>)."""
    want = _company_slug(slug)
    if not want:
        return None
    companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    for co in companies:
        if _company_slug(co.name) == want:
            return co
    # Coincidencia parcial: /facturacion_pies encuentra «Pies Records SL».
    for co in companies:
        cs = _company_slug(co.name)
        if want and (want in cs or cs.startswith(want)):
            return co
    return None


def _invoice_target_people(session_db) -> list:
    """Personal al que se le puede dirigir una factura del enlace genérico: los que tienen algún
    DEPARTAMENTO. Se excluye a dirección… salvo que además tengan otro departamento asignado.
    Solo personal ACTUAL: los eliminados o bloqueados no se ofrecen."""
    rows = []
    try:
        _inactive = _inactive_user_ids(session_db)
        q = (session_db.query(User, UserProfile)
             .join(UserProfile, UserProfile.user_id == User.id)
             .order_by(UserProfile.nick.asc()))
        for user, profile in q.all():
            if user.id in _inactive:
                continue
            depts = [str(d).strip() for d in (getattr(profile, "departments", None) or []) if str(d).strip()]
            if not depts:
                continue                                  # sin departamento: no se ofrece
            others = [d for d in depts if d.lower() != "dirección" and d.lower() != "direccion"]
            if int(getattr(user, "role", 0) or 0) == 10 and not others:
                continue                                  # solo dirección: no se ofrece
            if not others:
                continue
            rows.append({
                "user_id": str(user.id),
                "nick": (profile.nick or user.email or "Usuario"),
                "photo_url": (profile.photo_url or ""),
                "departments": others,
            })
    except Exception:
        return rows
    return rows


_INV_NUM_RE = re.compile(
    r"(?:n[ºo°]?\s*(?:de\s*)?factura|factura\s*n[ºo°]?|invoice\s*(?:no|number|#)|factura|invoice)"
    r"\s*[:#nºo°\-]*\s*([A-Z0-9][A-Z0-9\-\/\._]{2,24})", re.IGNORECASE)
_INV_DATE_RES = [
    re.compile(r"(?:fecha(?:\s+de)?\s*(?:emisi[óo]n|factura)?|date)\s*[:\-]?\s*(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})", re.IGNORECASE),
    re.compile(r"\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})\b"),
]
_INV_DATE_ISO_RE = re.compile(r"\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b")

# ------------------- IMPORTES de la factura leídos del propio documento -------------------
# Un importe en formato español: 1.234,56 · 1234,56 · 1.234 · 1234.56 (con o sin €).
_INV_AMOUNT = r"(-?\s*\d{1,3}(?:[.\s]\d{3})*(?:,\d{1,2})?|-?\s*\d+(?:[.,]\d{1,2})?)\s*(?:€|EUR|EUROS)?"
_INV_PCT = r"(\d{1,2}(?:[.,]\d{1,2})?)\s*%"
# Cada concepto con sus sinónimos: se busca la etiqueta y el importe que va detrás (misma línea o la
# siguiente, que es como salen en las facturas maquetadas en columnas).
_INV_MONEY_RES = {
    "amount_net": [
        re.compile(r"base\s*imponible[^\d\-%]{0,40}" + _INV_AMOUNT, re.IGNORECASE),
        re.compile(r"\bbase\b[^\d\-%]{0,25}" + _INV_AMOUNT, re.IGNORECASE),
        re.compile(r"subtotal[^\d\-%]{0,25}" + _INV_AMOUNT, re.IGNORECASE),
        re.compile(r"total\s*(?:sin|antes\s*de)\s*iva[^\d\-%]{0,25}" + _INV_AMOUNT, re.IGNORECASE),
    ],
    "amount_vat": [
        re.compile(r"(?:i\.?\s*v\.?\s*a\.?|impuesto\s*sobre\s*el\s*valor)[^\d\-]{0,20}(?:" + _INV_PCT
                   + r")?[^\d\-]{0,20}" + _INV_AMOUNT, re.IGNORECASE),
        re.compile(r"cuota\s*(?:de\s*)?iva[^\d\-%]{0,25}" + _INV_AMOUNT, re.IGNORECASE),
    ],
    # ⚠️ La retención se busca en SU MISMA LÍNEA (nada de `\n` en los huecos): con la tolerancia de
    # los demás conceptos, un «Ret. IRPF 15 %» sin importe al lado se llevaba el número de la línea
    # siguiente (el TOTAL) como si fuera la retención. Si en la línea no hay importe, se calcula
    # después con el porcentaje sobre la base.
    "retention_amount": [
        # El `(?![\d.,]*[ \t]*%)` final es clave: sin él, en «Ret. IRPF 15 %» (sin importe al lado) el
        # 15 del porcentaje se tomaba como el importe de la retención (y, al acortarlo, el 1).
        re.compile(r"(?:retenci(?:[óo]n|ones)?|reten\.?|ret\.?|ir\.?p\.?f\.?)"
                   r"(?:[ \t]*(?:de[ \t]*)?(?:ir\.?p\.?f\.?|a[ \t]*cuenta))?[^\d\-\n]{0,20}(?:" + _INV_PCT
                   + r")?[^\d\-\n]{0,20}" + _INV_AMOUNT + r"(?![\d.,]*[ \t]*%)", re.IGNORECASE),
    ],
    "amount_gross": [
        re.compile(r"total\s*(?:a\s*)?(?:pagar|factura|de\s*la\s*factura)[^\d\-%]{0,25}" + _INV_AMOUNT, re.IGNORECASE),
        re.compile(r"importe\s*total[^\d\-%]{0,25}" + _INV_AMOUNT, re.IGNORECASE),
        re.compile(r"\btotal\b[^\d\-%]{0,20}" + _INV_AMOUNT, re.IGNORECASE),
    ],
}
# El % que acompaña a cada concepto (para poder decir «IVA 21%» o «Retención 15%»).
_INV_PCT_RES = {
    "vat_pct": re.compile(r"i\.?\s*v\.?\s*a\.?[^\d]{0,12}" + _INV_PCT, re.IGNORECASE),
    "retention_pct": re.compile(r"(?:retenci(?:[óo]n|ones)?|reten\.?|ret\.?|ir\.?p\.?f\.?)[^\d]{0,14}"
                               + _INV_PCT, re.IGNORECASE),
}
# Retenciones que existen de verdad en España (IRPF de profesionales 15% y 7% los primeros años,
# alquileres 19%, agrario 2%, 1% ganadería/engorde). Sirven para RECONOCER una retención que el
# documento no dice con palabras: si base + IVA − total es justo uno de estos porcentajes de la base,
# eso es una retención y no un descuadre (el caso típico de las facturas de profesionales).
_INV_RETENTION_RATES = [Decimal("15"), Decimal("7"), Decimal("19"), Decimal("21"), Decimal("2"),
                        Decimal("1"), Decimal("9"), Decimal("20"), Decimal("24")]


def _inv_money(texto: str) -> Decimal:
    """Un importe suelto del documento → Decimal (formato español, con o sin signo)."""
    limpio = re.sub(r"\s+", "", str(texto or "")).replace("€", "")
    return _parse_money_decimal(limpio)


def _detect_invoice_amounts(text: str) -> dict:
    """Lee del PROPIO documento la BASE, el IVA, la RETENCIÓN y el TOTAL.

    Es lo que permite que los números cuadren sin teclearlos: al subir la factura se leen y solo se
    pregunta lo que no se ha podido sacar. Mejor esfuerzo, y **coherente**: si falta una pieza y las
    otras la determinan, se completa; si el desglose no cuadra con el total, manda el total (es lo que
    se paga) y se avisa."""
    salida = {"amount_net": None, "amount_vat": None, "retention_amount": None,
              "amount_gross": None, "vat_pct": None, "retention_pct": None, "amounts_warn": "",
              "retention_guessed": False}
    if not text:
        return salida
    for clave, patrones in _INV_MONEY_RES.items():
        for rx in patrones:
            m = rx.search(text)
            if not m:
                continue
            valor = _inv_money(m.group(m.lastindex or 1))
            if valor != 0:
                salida[clave] = abs(valor) if clave == "retention_amount" else valor
                break
    for clave, rx in _INV_PCT_RES.items():
        m = rx.search(text)
        if m:
            try:
                salida[clave] = float(str(m.group(1)).replace(",", "."))
            except Exception:
                salida[clave] = None
    return _invoice_amounts_coherence(salida)


def _invoice_amounts_coherence(datos: dict) -> dict:
    """COMPLETA el desglose de una factura y comprueba que cuadre.

    Se aplica a lo que se haya leído (venga del motor `invoice_read` o de las expresiones de aquí):
    si falta una pieza y las otras la determinan, se calcula; si el desglose no cuadra con el total,
    manda el total (es lo que se paga) y se avisa. Y si al total le falta justo un porcentaje de
    retención de los que existen, se reconoce como retención en vez de darlo por descuadre."""
    salida = {"amount_net": datos.get("amount_net"), "amount_vat": datos.get("amount_vat"),
              "retention_amount": datos.get("retention_amount"),
              "amount_gross": datos.get("amount_gross"), "vat_pct": datos.get("vat_pct"),
              "retention_pct": datos.get("retention_pct"), "amounts_warn": "",
              "retention_guessed": False}
    base = salida["amount_net"]
    iva = salida["amount_vat"]
    ret = salida["retention_amount"] or Decimal("0")
    total = salida["amount_gross"]
    # Si la factura dice el PORCENTAJE de retención pero no su importe, se calcula sobre la base
    # (muchas facturas ponen «Retención IRPF 15 %» y el importe va en otra columna que no se lee).
    if ret == 0 and salida.get("retention_pct") and base:
        try:
            ret = (base * Decimal(str(salida["retention_pct"])) / Decimal("100")).quantize(Decimal("0.01"))
            salida["retention_amount"] = ret
        except Exception:
            ret = Decimal("0")
    # Completar lo que falte con lo que sí se ha leído.
    if base and iva is None and total is not None:
        iva = total + ret - base
        salida["amount_vat"] = iva if iva > 0 else None
    if base is None and iva is not None and total is not None:
        base = total + ret - iva
        salida["amount_net"] = base if base > 0 else None
    if total is None and base is not None:
        total = base + (iva or Decimal("0")) - ret
        salida["amount_gross"] = total if total > 0 else None
    # ¿Cuadra? base + IVA − retención = total (con un céntimo de margen).
    if base is not None and total is not None:
        diferencia = base + (iva or Decimal("0")) - ret - total
        if abs(diferencia) > Decimal("0.01"):
            # LA RETENCIÓN QUE NO SE DIJO CON PALABRAS. Si lo que falta es justo un porcentaje de
            # retención de los que existen, eso es una retención practicada y no un descuadre: es el
            # caso típico de la factura de un profesional (y el que hacía que el importe a pagar no
            # cuadrara con la liquidación).
            reconocida = None
            if ret == 0 and diferencia > 0 and base > 0:
                for pct in _INV_RETENTION_RATES:
                    if abs((base * pct / Decimal("100")).quantize(Decimal("0.01")) - diferencia) <= Decimal("0.02"):
                        reconocida = pct
                        break
            if reconocida is not None:
                salida["retention_amount"] = diferencia.quantize(Decimal("0.01"))
                salida["retention_pct"] = float(reconocida)
                salida["retention_guessed"] = True
                salida["amounts_warn"] = (
                    "La factura no nombra la retención, pero al total le falta justo el %g %% de la "
                    "base (%s): se ha tomado como retención. Compruébalo."
                    % (float(reconocida), format_eur(diferencia)))
            else:
                salida["amounts_warn"] = (
                    "El desglose leído (%s + %s%s) no cuadra con el total (%s): revísalo. La "
                    "diferencia es %s."
                    % (format_eur(base), format_eur(iva or 0),
                       (" − " + format_eur(ret)) if ret else "", format_eur(total),
                       format_eur(abs(diferencia))))
    return salida


def _detect_invoice_meta(data: bytes, is_pdf: bool) -> dict:
    """Detecta el NÚMERO de factura, la FECHA DE EMISIÓN y los IMPORTES del documento (mejor
    esfuerzo). Lo que salga se le muestra a la persona para que lo confirme o lo corrija antes de
    enviar.

    Manda el motor **`invoice_read`**, que reconstruye los renglones del PDF con las coordenadas de
    cada trozo y empareja rótulo → valor por columnas: es la única forma de leer bien las facturas
    maquetadas como TABLA (donde el texto plano saca los rótulos y los valores desordenados, y
    «número de factura» acaba pareciendo la fecha de vencimiento). Lo que ese motor no saque se
    intenta con las expresiones de aquí, y al final se completa el desglose con
    `_detect_invoice_amounts` (que también reconoce una retención que no se dijo con palabras)."""
    out = {"invoice_number": "", "issue_date": "", "concept": "", "detected": False,
           "amount_net": None, "amount_vat": None, "retention_amount": None, "amount_gross": None,
           "vat_pct": None, "retention_pct": None, "amounts_warn": "", "retention_guessed": False}
    if not is_pdf:
        return out
    text = _pdf_extract_text_bytes(data)
    leido = {}
    try:
        leido = invoice_read.read_fields(text=text, data=data)
    except Exception:
        leido = {}
    if not text and not leido:
        return out
    for clave in ("invoice_number", "issue_date", "concept"):
        if leido.get(clave):
            out[clave] = leido[clave]
    for clave in ("amount_net", "amount_vat", "retention_amount", "amount_gross",
                  "vat_pct", "retention_pct"):
        if leido.get(clave) is not None:
            out[clave] = leido[clave]
    if not text:
        return {**out, "detected": bool(out["invoice_number"] or out["issue_date"]
                                        or out["amount_gross"] is not None), "text": ""}
    m = _INV_NUM_RE.search(text) if not out["invoice_number"] else None
    if m:
        num = (m.group(1) or "").strip(" .:-")
        # Descartamos solo lo que sea claramente una FECHA o un IMPORTE (un número de factura como
        # «2026/0147» es perfectamente válido y antes se colaba en el filtro).
        looks_date = bool(re.fullmatch(r"\d{1,2}[/\-.]\d{1,2}[/\-.]\d{2,4}", num))
        looks_amount = bool(re.search(r"\d,\d{2}$", num)) or num.upper().endswith(("EUR", "€"))
        if num and not looks_date and not looks_amount:
            out["invoice_number"] = num[:40]
    # ⚠️ Los respaldos de aquí abajo SOLO rellenan lo que el motor no haya podido leer: si pisaran lo
    # leído, la fecha de emisión volvería a ser «la primera fecha que aparezca» (a menudo la de
    # vencimiento) y el número de factura, cualquier cosa.
    if not out["issue_date"]:
        for rx in _INV_DATE_RES:
            m = rx.search(text)
            if not m:
                continue
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if y < 100:
                y += 2000
            try:
                out["issue_date"] = date(y, mo, d).isoformat()
                break
            except ValueError:
                continue
    if not out["issue_date"]:
        m = _INV_DATE_ISO_RE.search(text)
        if m:
            try:
                out["issue_date"] = date(int(m.group(1)), int(m.group(2)), int(m.group(3))).isoformat()
            except ValueError:
                pass
    # CONCEPTO: la línea que venga tras «concepto» / «descripción» (mejor esfuerzo).
    if not out["concept"]:
        m = re.search(r"(?:concepto|descripci[oó]n|detalle)\s*[:\-]?\s*(.{3,90})", text, re.I)
        if m:
            linea = re.split(r"[\r\n]", (m.group(1) or ""))[0].strip(" .:-;|")
            if linea and not re.fullmatch(r"[\d\s.,€]+", linea):
                out["concept"] = linea[:120]
    # IMPORTES: lo que falte se busca con las expresiones de aquí y, sobre todo, se COMPLETA el
    # desglose (y se reconoce una retención que el documento no nombra).
    _viejos = _detect_invoice_amounts(text)
    for clave in ("amount_net", "amount_vat", "retention_amount", "amount_gross",
                  "vat_pct", "retention_pct"):
        if out.get(clave) is None and _viejos.get(clave) is not None:
            out[clave] = _viejos[clave]
    out["amounts_warn"] = _viejos.get("amounts_warn") or ""
    out["retention_guessed"] = bool(_viejos.get("retention_guessed"))
    # Con lo leído por el motor, el desglose se recompone y se comprueba que cuadre.
    out.update(_invoice_amounts_coherence(out))
    out["detected"] = bool(out["invoice_number"] or out["issue_date"] or out.get("concept")
                           or out.get("amount_gross") is not None)
    out["text"] = text[:20000]     # se reutiliza para buscar el ARTISTA (no se devuelve al cliente)
    return out


def _personal_expense_from_invoice(session_db, inv, target_user_id) -> None:
    """Crea el «gasto personal» de una factura dirigida a alguien (arranca el plazo de 1 semana)."""
    uid = to_uuid(str(target_user_id)) if target_user_id else None
    if not uid:
        return
    session_db.add(PersonalExpense(
        user_id=uid, source="INVOICE", supplier_invoice_id=inv.id,
        concept=(inv.concept_text or "Factura"),
        provider_name=(inv.promoter.nick if getattr(inv, "promoter", None) else None),
        expense_date=inv.issue_date,
        amount_gross=inv.amount_gross,
        invoice_number=inv.invoice_number,
        file_url=inv.file_url, original_name=inv.original_name,
        status="PENDING",
    ))


@app.get('/facturacion_<company_slug>', endpoint='public_invoice_landing_company')
def public_invoice_landing_company(company_slug):
    """Subenlace de facturación de UNA empresa del grupo: sin la cabecera del back office, con su
    logo arriba a la derecha y solo sus datos de facturación."""
    session_db = db()
    try:
        company = _find_group_company_by_slug(session_db, company_slug)
        if company is None:
            abort(404)
        return render_template(
            "public_invoice_landing.html",
            inv_mode="LANDING",
            brand_only=True,                 # logo de la empresa a la derecha, sin bañera
            hide_backoffice_nav=True,
            companies=[company],
            company=company,
            cert_docs=INVOICE_CERT_DOCS,
            request_row=None,
            request_rows=[],
            target_people=_invoice_target_people(session_db),
        )
    finally:
        session_db.close()


@app.get('/facturacion_<company_slug>/embed', endpoint='public_invoice_embed')
def public_invoice_embed(company_slug):
    """La MISMA subida de facturas, preparada para insertarla en la web de la empresa.

    Va dentro de un `<iframe>` (ver `_company_embed_snippet`), así que se sirve sin la cabecera del
    back office y **sin el logo de la empresa** (ya está en su web), con el fondo transparente: solo
    cada viñeta lleva el suyo, para que se diferencie sobre el fondo de la web. Al ser la landing de
    verdad, cualquier cambio que hagamos aquí sale allí sin tocar la web.
    """
    session_db = db()
    try:
        company = _find_group_company_by_slug(session_db, company_slug)
        if company is None:
            abort(404)
        return render_template(
            "public_invoice_landing.html",
            inv_mode="LANDING",
            brand_only=True,                 # una sola empresa: solo sus datos de facturación
            inv_embed=True,                  # sin logo, fondo transparente y alto autoajustable
            hide_backoffice_nav=True,
            embed_mode=True,
            companies=[company],
            company=company,
            cert_docs=INVOICE_CERT_DOCS,
            request_row=None,
            request_rows=[],
            target_people=_invoice_target_people(session_db),
        )
    finally:
        session_db.close()


@app.post('/facturacion/detectar', endpoint='public_invoice_detect')
def public_invoice_detect():
    """Lee el documento y devuelve el nº de factura y la fecha de emisión detectados."""
    f = request.files.get("file")
    if not f or not f.filename:
        return jsonify({"ok": False, "error": "Falta el archivo"}), 400
    data = f.read()
    is_pdf = (f.filename or "").lower().endswith(".pdf") or (f.mimetype or "") == "application/pdf"
    meta = _detect_invoice_meta(data, is_pdf)
    texto = meta.pop("text", "") or ""
    # ARTISTA: se busca por el NOMBRE de los artistas que tenemos, que es lo único fiable (una regex
    # sobre el texto se inventaría cualquier cosa).
    meta["artist"] = ""
    if texto:
        clave = _norm_text_key(texto)
        session_db = db()
        try:
            mejor = ""
            for (nombre,) in session_db.query(Artist.name).filter(Artist.name.isnot(None)).all():
                n = _norm_text_key(nombre or "")
                if len(n) >= 4 and n in clave and len(n) > len(_norm_text_key(mejor)):
                    mejor = nombre
            meta["artist"] = mejor
        except Exception:
            meta["artist"] = ""
        finally:
            session_db.close()
    meta["detected"] = bool(meta.get("invoice_number") or meta.get("issue_date")
                            or meta.get("concept") or meta.get("artist")
                            or meta.get("amount_gross") is not None)
    # Los importes viajan como TEXTO en formato español, que es lo que se pinta y lo que se reenvía.
    for clave in ("amount_net", "amount_vat", "retention_amount", "amount_gross"):
        valor = meta.get(clave)
        meta[clave] = ("" if valor in (None, "") else format_eur(valor).replace(" €", ""))
    for clave in ("vat_pct", "retention_pct"):
        valor = meta.get(clave)
        meta[clave] = ("" if valor in (None, "") else ("%g" % float(valor)))
    return jsonify({"ok": True, **meta})


@app.get('/facturacion', endpoint='public_invoice_landing')
def public_invoice_landing():
    """Landing pública de subida de facturas (3 pasos). Con `?liq=<token>` es la factura de una
    LIQUIDACIÓN DE ROYALTIES: se comporta como una petición (logo y datos de la empresa del grupo
    que corresponda + confirmación de que la factura está emitida a ellos)."""
    session_db = db()
    try:
        companies = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
        liq_token = (request.args.get("liq") or "").strip()
        payload = _parse_public_royalty_liquidation_token(liq_token) if liq_token else None
        if payload:
            kind = (payload.get("kind") or "").upper()
            parsed_sem = _parse_semester_key((payload.get("s") or "").strip())
            if parsed_sem:
                sem_year, sem_half = parsed_sem
                sem_start, sem_end = _semester_range(sem_year, sem_half)
                try:
                    beneficiary, _s, _e, beneficiary_uuid = _get_royalty_liquidation_beneficiary_data(
                        session_db, kind, (payload.get("bid") or ""), sem_year, sem_half)
                except Exception:
                    beneficiary, beneficiary_uuid = None, None
                provider = session_db.get(Promoter, beneficiary_uuid) if (kind == "PROMOTER" and beneficiary_uuid) else None
                # Royalties = sello: la factura va a nombre de PIES.
                company = _pies_group_company(session_db) or (companies[0] if companies else None)
                # LO QUE SE LE ENVIÓ manda (punto único): el congelado de la liquidación.
                rec_liq = (_royalty_liquidation_record(session_db, kind, beneficiary_uuid, sem_start)
                           if beneficiary_uuid else None)
                _efectivo, _cong = _royalty_effective_beneficiary(
                    session_db, rec_liq, kind, beneficiary_uuid, sem_year, sem_half)
                if _efectivo:
                    beneficiary = _efectivo
                rows = []
                if beneficiary:
                    # ⚠️ El total del beneficiario es `total_amount` (no `total`): leyendo `total`
                    # salía 0,00 € (bug real). Y lo que se factura es esa base MÁS el IVA.
                    _imp = _invoice_request_amounts(beneficiary.get("total_amount"), 0)
                    rows = [{
                        "id": "",
                        "concept": f"Liquidación de royalties · {_royalty_liquidation_period_label_from_dates(sem_start, sem_end)}",
                        "category_label": "Royalties",
                        "net": _imp["net"],
                        "vat": _imp["vat"],
                        "vat_pct": _imp["vat_pct"],
                        "gross": _imp["gross"],
                        "unknown": _imp["unknown"],
                        "has_invoice": False,
                    }]
                # ¿YA HAY FACTURA SUBIDA? Entonces no se empieza el proceso: se dice que ya hay una y
                # se ofrece reemplazarla, salvo que esté validada (ahí lo arregla administración).
                inv_previa = (session_db.get(SupplierInvoice, rec_liq.invoice_id)
                              if (rec_liq is not None and getattr(rec_liq, "invoice_id", None)) else None)
                # ¿La sube la OFICINA (los tres puntitos de la liquidación) en nombre del
                # beneficiario? Es la misma pantalla: solo se le presta quién emite la factura (para
                # no tener que teclear su DNI) y se permite forzar un importe que no cuadre.
                interno = bool(_truthy(request.args.get("interno")) and session.get("user_id"))
                if interno and provider is None and rec_liq is not None:
                    provider, _candidatos = _royalty_beneficiary_promoter(session_db, rec_liq)
                return render_template(
                    "public_invoice_landing.html",
                    inv_mode="REQUEST",
                    inv_internal=interno,
                    companies=[company] if company else companies,
                    company=company,
                    cert_docs=INVOICE_CERT_DOCS,
                    request_row=None,
                    request_rows=rows,
                    provider=provider,
                    provider_payload=(_billing_profile_payload(session_db, provider) if provider else None),
                    liq_token=liq_token,
                    **_invoice_existing_block(inv_previa),
                )
        # ⚠️ VIENE de un enlace de liquidación y NO se ha podido identificar: NO se sigue como landing
        # genérica. Si se siguiera, el proveedor subiría su factura, la app le diría que todo bien y la
        # factura quedaría SIN VINCULAR a la liquidación (no aparecería en «pendiente de liquidar» y
        # nadie se enteraría). Mejor decirlo y que nos avise.
        if liq_token:
            return render_template(
                "public_invoice_landing.html",
                inv_mode="REQUEST",
                companies=companies,
                company=_pies_group_company(session_db) or (companies[0] if companies else None),
                cert_docs=INVOICE_CERT_DOCS,
                request_row=None, request_rows=[], provider=None, provider_payload=None,
                liq_token="",
                liq_error=("No hemos podido identificar la liquidación de este enlace, así que no "
                           "podemos aceptar la factura por aquí (se quedaría sin vincular). "
                           "Escríbenos a %s y te mandamos un enlace nuevo."
                           % ADMIN_INVOICE_CONTACT_EMAIL),
                existing_invoice=None,
            )
        return render_template(
            "public_invoice_landing.html",
            inv_mode="LANDING",
            companies=companies,
            company=None,
            cert_docs=INVOICE_CERT_DOCS,
            request_row=None,
            request_rows=[],
            target_people=_invoice_target_people(session_db),
        )
    finally:
        session_db.close()


@app.post('/facturacion/identificar', endpoint='public_invoice_identify')
def public_invoice_identify():
    """Paso 2: busca el DNI/CIF en la base de datos y dice qué hacer."""
    session_db = db()
    try:
        raw = (request.form.get("tax_id") or "").strip()
        norm = _prl_norm_dni(raw)
        if not norm:
            return jsonify({"ok": False, "error": "Escribe tu DNI o CIF"}), 400
        kind = _tax_id_kind(raw)
        matches, vistos = [], set()

        def _añadir(p):
            if p is None or str(p.id) in vistos:
                return
            vistos.add(str(p.id))
            matches.append(_billing_profile_payload(session_db, p))

        # Se buscan TODAS las vías (sin cortar en la primera que acierte: si dos fichas comparten el
        # número, se ofrecen las dos y elige quien está facturando).
        for p in session_db.query(Promoter).filter(Promoter.tax_id.isnot(None)).all():
            if _prl_norm_dni(p.tax_id) == norm:
                _añadir(p)
        # También por CIF de una sociedad del tercero.
        for pc in session_db.query(PromoterCompany).filter(PromoterCompany.tax_id.isnot(None)).all():
            if _prl_norm_dni(pc.tax_id) == norm:
                _añadir(session_db.get(Promoter, pc.promoter_id))
        # Y por el número del DNI/pasaporte ESCANEADO: los artistas y las personas de los artistas
        # (que son terceros que forman parte de ellos) suelen tener el documento subido en su ficha
        # aunque nadie haya rellenado a mano el campo DNI/NIF. Sin esto se les pedía darse de alta
        # otra vez y salía un tercero duplicado.
        for doc in (session_db.query(PersonDocument)
                    .filter(PersonDocument.owner_type == "PROMOTER",
                            PersonDocument.kind.in_(("DNI", "PASSPORT")),
                            PersonDocument.doc_number.isnot(None)).all()):
            if _prl_norm_dni(doc.doc_number) == norm:
                _añadir(session_db.get(Promoter, doc.owner_id))
        return jsonify({"ok": True, "kind": kind, "tax_id": raw, "found": bool(matches), "matches": matches})
    finally:
        session_db.close()


@app.post('/facturacion/registrar', endpoint='public_invoice_register')
def public_invoice_register():
    """Crea (o completa) los datos de facturación del proveedor. Solo hay que hacerlo una vez."""
    session_db = db()
    try:
        raw_tax = (request.form.get("tax_id") or "").strip()
        if not raw_tax:
            return jsonify({"ok": False, "error": "Falta el DNI/CIF"}), 400
        kind = (request.form.get("kind") or _tax_id_kind(raw_tax) or "PARTICULAR").upper()
        if not _truthy(request.form.get("consent")):
            return jsonify({"ok": False, "error": "Debes aceptar las condiciones de protección de datos"}), 400
        existing_id = to_uuid(request.form.get("promoter_id") or "")
        promoter = session_db.get(Promoter, existing_id) if existing_id else None
        if promoter is None:
            norm = _prl_norm_dni(raw_tax)
            for p in session_db.query(Promoter).filter(Promoter.tax_id.isnot(None)).all():
                if _prl_norm_dni(p.tax_id) == norm:
                    promoter = p
                    break
        fields = {k: (request.form.get(k) or "").strip() for k in
                  ("full_name", "company_name", "contact_name", "fiscal_address", "email", "phone", "bank_account")}
        # DIRECCIÓN FISCAL EN PIEZAS: el código postal, el municipio y la provincia se piden aparte
        # porque son imprescindibles para dar de alta al proveedor en la contabilidad.
        piezas_fiscal = _fiscal_form_values(request.form)
        fields.update({"fiscal_postal_code": piezas_fiscal["postal_code"],
                       "fiscal_city": piezas_fiscal["city"],
                       "fiscal_province": piezas_fiscal["province"]})
        required = ["fiscal_address", "fiscal_postal_code", "fiscal_city", "fiscal_province",
                    "email", "phone", "bank_account"]
        required += ["company_name", "contact_name"] if kind == "EMPRESA" else ["full_name"]
        faltan = [f for f in required if not fields.get(f)]
        if faltan and promoter is None:
            return jsonify({"ok": False, "error": "Faltan datos obligatorios", "missing": faltan}), 400
        if promoter is None:
            nick = fields["company_name"] if kind == "EMPRESA" else fields["full_name"]
            promoter = Promoter(nick=nick[:120], kind=("empresa" if kind == "EMPRESA" else None), tax_id=raw_tax)
            session_db.add(promoter)
            session_db.flush()
        # Datos (solo se sobreescribe lo que llega relleno).
        if kind == "PARTICULAR" and fields["full_name"]:
            parts = fields["full_name"].split()
            promoter.first_name = parts[0]
            promoter.last_name = " ".join(parts[1:]) or None
            if not (promoter.nick or "").strip():
                promoter.nick = fields["full_name"][:120]
        if kind == "EMPRESA" and fields["company_name"]:
            promoter.nick = fields["company_name"][:120]
            promoter.kind = "empresa"
        promoter.tax_id = raw_tax
        for attr, key in (("contact_email", "email"), ("contact_phone", "phone"),
                          ("bank_account", "bank_account")):
            if fields[key]:
                setattr(promoter, attr, fields[key])
        _apply_fiscal_address(promoter, piezas_fiscal)
        if fields["fiscal_address"] and not (promoter.address or "").strip():
            promoter.address = _fiscal_address_text(promoter) or fields["fiscal_address"]
        promoter.data_consent_at = _now_madrid()
        promoter.billing_updated_at = _now_madrid()
        # Empresa: sociedad + contacto vinculado.
        if kind == "EMPRESA":
            company = (session_db.query(PromoterCompany)
                       .filter(PromoterCompany.promoter_id == promoter.id)
                       .order_by(PromoterCompany.created_at.asc()).first())
            if not company:
                company = PromoterCompany(promoter_id=promoter.id, legal_name=(fields["company_name"] or promoter.nick)[:200])
                session_db.add(company)
            company.tax_id = raw_tax
            _apply_fiscal_address(company, piezas_fiscal)
            if fields["contact_name"]:
                parts = fields["contact_name"].split()
                contact = (session_db.query(PromoterContact)
                           .filter(PromoterContact.promoter_id == promoter.id)
                           .order_by(PromoterContact.created_at.asc()).first())
                if not contact:
                    contact = PromoterContact(promoter_id=promoter.id, title="Contacto de facturación",
                                              first_name=parts[0], last_name=" ".join(parts[1:]) or None)
                    session_db.add(contact)
                else:
                    contact.first_name = parts[0]
                    contact.last_name = " ".join(parts[1:]) or None
                if fields["email"]:
                    contact.email = fields["email"]
                if fields["phone"]:
                    contact.phone = fields["phone"]
        # Foto / logo (opcional, cualquier formato).
        f = request.files.get("photo")
        if f and f.filename:
            url = upload_image(f, "providers") or upload_file(f, "providers")
            if url:
                promoter.logo_url = url
        session_db.commit()
        payload = _billing_profile_payload(session_db, promoter)
        return jsonify({"ok": True, "profile": payload,
                        "docs": _billing_docs_state(session_db, promoter, payload["kind"])})
    except Exception:
        session_db.rollback()
        app.logger.exception("public_invoice_register")
        return jsonify({"ok": False, "error": "No se pudieron guardar los datos"}), 500
    finally:
        session_db.close()


@app.post('/facturacion/suplidos', endpoint='public_invoice_supplements_save')
def public_invoice_supplements_save():
    """El proveedor detalla los SUPLIDOS que no tenían importe (antes de subir la factura).

    Lo que escriba actualiza el gasto: a partir de ese momento el total a facturar (y lo que se le
    pagará) incluye esos suplidos. Los suplidos NO llevan IVA."""
    session_db = db()
    try:
        token = (request.form.get("token") or "").strip()
        req = (session_db.query(BagInvoiceRequest)
               .filter(BagInvoiceRequest.public_token == token).first()) if token else None
        if req is None:
            return jsonify({"ok": False, "error": "Enlace no válido"}), 404
        permitidos = {str(x) for x in (req.expense_ids or [])}
        # Llegan como `sup_<expense_id>_<indice>` = importe.
        cambios = {}
        for clave, valor in request.form.items():
            if not clave.startswith("sup_"):
                continue
            trozos = clave[4:].rsplit("_", 1)
            if len(trozos) != 2:
                continue
            eid, idx = trozos[0], trozos[1]
            if eid not in permitidos or not idx.isdigit():
                continue
            cambios.setdefault(eid, {})[int(idx)] = valor
        total_nuevo = Decimal("0")
        for eid, valores in cambios.items():
            exp = session_db.get(BagExpense, to_uuid(eid) or uuid.uuid4())
            if exp is None:
                continue
            filas = []
            for i, sup in enumerate(_expense_supplements(exp)):
                importe = sup["amount"]
                if i in valores and (valores[i] or "").strip():
                    nuevo = _parse_money_decimal(valores[i])
                    if nuevo > 0:
                        importe = nuevo
                filas.append({"concept": sup["concept"], "amount": importe})
            total_nuevo += _expense_apply_supplements(exp, filas)
        session_db.commit()
        ctx = _bag_invoice_request_context(session_db, req)
        pend = [r for r in ctx["rows"] if not r["has_invoice"]]
        return jsonify({
            "ok": True,
            "total": str(sum((r["gross"] for r in pend), Decimal("0"))),
            "total_label": format_eur(sum((r["gross"] for r in pend), Decimal("0"))),
            "pending": sum(len(r["supplements_pending"]) for r in pend),
            # Importe nuevo de cada concepto: el navegador actualiza con esto lo que se va a facturar.
            "rows": {r["id"]: str(r["gross"]) for r in ctx["rows"]},
        })
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 400
    finally:
        session_db.close()


@app.post('/facturacion/documentos', endpoint='public_invoice_docs_state')
def public_invoice_docs_state():
    """Estado de los documentos exigidos a un proveedor ya identificado.

    Con `worker_type` se GUARDA en su ficha cómo factura (autónomo / alta puntual) y se le piden los
    papeles del alta que le tocan; con `issue_date` se comprueba que el alta y la baja cubran la fecha
    de la factura."""
    session_db = db()
    try:
        promoter = session_db.get(Promoter, to_uuid(request.form.get("promoter_id") or "") or uuid.uuid4())
        if not promoter:
            return jsonify({"ok": False, "error": "Proveedor no encontrado"}), 404
        wt = (request.form.get("worker_type") or "").strip().upper()
        if wt in BILLING_WORKER_LABELS and (promoter.prl_type or "").upper() != wt:
            promoter.prl_type = wt        # se queda grabado en su ficha
            session_db.commit()
        payload = _billing_profile_payload(session_db, promoter)
        wt = wt or payload.get("worker_type") or ""
        emision = _parse_date_soft(request.form.get("issue_date"))
        return jsonify({
            "ok": True,
            "profile": payload,
            "worker_type": wt,
            # Con un particular que no ha dicho cómo factura, primero se le pregunta.
            "ask_worker_type": bool(payload["kind"] != "EMPRESA" and wt not in BILLING_WORKER_LABELS),
            "worker_types": [{"key": k, "label": l, "icon": i, "hint": d} for k, l, i, d in BILLING_WORKER_TYPES],
            "docs": _billing_docs_state(session_db, promoter, payload["kind"], worker_type=wt,
                                        issue_date=emision),
        })
    finally:
        session_db.close()


def _billing_store_cert(session_db, promoter, doc_type: str, file_storage):
    """Guarda un certificado de facturación con vigencia del MES EN VIGOR."""
    filename = (file_storage.filename or "certificado").strip()
    is_pdf = filename.lower().endswith(".pdf") or (file_storage.mimetype or "") == "application/pdf"
    url = upload_pdf(file_storage, "documents") if is_pdf else upload_file(file_storage, "documents")
    if not url:
        return None
    valid_from, valid_until = _cert_month_range()
    doc = PersonComplianceDoc(
        owner_type="PROMOTER", owner_id=promoter.id, doc_type=doc_type,
        file_url=url, original_name=filename[:200], mime_type=file_storage.mimetype,
        valid_from=valid_from, valid_until=valid_until, status="APPROVED",
        detected_meta={"scope": "billing", "month": valid_from.strftime("%m/%Y")},
        uploaded_via="PUBLIC",
    )
    session_db.add(doc)
    session_db.flush()
    return doc


def _invoice_existing_block(invoice) -> dict:
    """Lo que hay que decirle a quien abre el enlace y YA tiene una factura subida.

    · Pendiente de validar → «ya hay una factura subida» + poder REEMPLAZARLA.
    · Validada → no se toca: que hable con administración.
    · ⚠️ RECHAZADA → NO bloquea: justamente se le ha pedido que la corrija y la vuelva a mandar. Antes
      cualquier estado distinto de VALIDADA se trataba como «ya hay una», así que a quien se le
      rechazaba una factura el enlace no le dejaba subir la nueva (bug real).
    """
    if invoice is None or not (getattr(invoice, "file_url", None) or "").strip():
        return {"existing_invoice": None}
    estado = (getattr(invoice, "status", None) or "PENDIENTE").upper()
    if estado == "RECHAZADA":
        # No bloquea, pero se le RECUERDA por qué se le devolvió: si no, vuelve a mandar lo mismo.
        return {"existing_invoice": None, "rejected_invoice": {
            "reason": (getattr(invoice, "reject_reason", None) or ""),
            "number": (getattr(invoice, "invoice_number", None) or ""),
        }}
    return {"existing_invoice": {
        "id": str(invoice.id),
        "status": estado,
        "validated": estado == "VALIDADA",
        "number": (getattr(invoice, "invoice_number", None) or ""),
        "file_url": (getattr(invoice, "file_url", None) or ""),
        "uploaded_label": (invoice.created_at.strftime("%d/%m/%Y") if getattr(invoice, "created_at", None) else ""),
        "amount": _money_or_zero(getattr(invoice, "amount_gross", None)),
        "message": (INVOICE_ALREADY_VALIDATED_MSG if estado == "VALIDADA" else INVOICE_ALREADY_UPLOADED_MSG),
        "contact_email": ADMIN_INVOICE_CONTACT_EMAIL,
    }}


def _supplier_invoice_mark_replaced(session_db, invoices, nota: str = "") -> int:
    """Marca facturas como REEMPLAZADAS por una nueva (no se borran: hay que poder ver qué pasó).

    Se les quita la imputación a los gastos, que si no el importe se contaría dos veces."""
    n = 0
    for inv in (invoices or []):
        if inv is None:
            continue
        inv.status = "RECHAZADA"
        inv.reject_reason = (nota or "Reemplazada por una factura nueva")[:500]
        try:
            for fila in (session_db.query(BagExpenseInvoice)
                         .filter(BagExpenseInvoice.supplier_invoice_id == inv.id).all()):
                session_db.delete(fila)
        except Exception:
            pass
        n += 1
    return n


def _invoice_amount_check(expected_gross, expected_net, total, retention=0, net=None,
                          vat=None) -> tuple[bool, str]:
    """¿El importe de la factura CUADRA con lo que hay que facturar?

    ⚠️ **LO QUE TIENE QUE COINCIDIR ES LA BASE** (y su IVA), no el total. La RETENCIÓN es la que
    diga la factura: baja el importe a pagar, pero no cambia lo que se ha facturado ni lo que cuesta
    el gasto (esa retención se la ingresa la casa a Hacienda). Antes se comparaba el TOTAL, así que
    una factura con retención cuya retención no se hubiera leído bien se rechazaba con «faltan X €» y
    el proveedor no podía enviarla (bug real).

    Cuadra si: la base es la esperada · base + IVA es el bruto esperado · el total más la retención es
    el bruto esperado · el total es el bruto esperado · o el total es la base (facturado sin IVA).
    """
    esperado = _money_or_zero(expected_gross)
    base_esperada = _money_or_zero(expected_net)
    fac = _money_or_zero(total)
    ret = _money_or_zero(retention)
    base = _money_or_zero(net)
    iva = _money_or_zero(vat)
    tol = Decimal("0.01")
    if esperado <= 0 and base_esperada <= 0:
        return True, ""                       # no sabemos qué pedir: no se puede exigir nada
    # 1) LA BASE, que es el criterio bueno.
    if base > 0 and base_esperada > 0 and abs(base - base_esperada) <= tol:
        return True, ""
    if base > 0 and esperado > 0 and abs(base + iva - esperado) <= tol:
        return True, ""
    if fac <= 0 and base <= 0:
        return False, ("Falta el importe de la factura. La base tiene que ser %s (%s con el IVA)."
                       % (format_eur(base_esperada), format_eur(esperado)))
    # 2) Por el total: con la retención sumada (es lo que se ha facturado) o sin ella.
    for candidato in (fac + ret, fac):
        if esperado > 0 and abs(candidato - esperado) <= tol:
            return True, ""
    # 3) Facturado sin IVA.
    if base_esperada > 0 and abs(fac - base_esperada) <= tol:
        return True, ""
    # El aviso se da en términos de BASE, que es lo que se compara.
    referencia = base if base > 0 else (fac + ret if ret > 0 else fac)
    diferencia = (base_esperada - referencia) if base_esperada > 0 else (esperado - referencia)
    objetivo = base_esperada if base_esperada > 0 else esperado
    return False, (
        "La base de la factura (%s) no coincide con lo que hay que facturar (%s): %s %s. "
        "La retención, si la hay, no importa para esto: solo tiene que cuadrar la base con su IVA. "
        "Corrige la factura y vuelve a subirla, o revisa los importes que has escrito."
        % (format_eur(referencia), format_eur(objetivo),
           ("faltan" if diferencia > 0 else "sobran"), format_eur(abs(diferencia))))


def _invoice_amount_fields_from_form(form) -> dict:
    """Los IMPORTES de la factura que llegan del formulario (leídos del documento al subirla, o
    corregidos a mano). Un cero se guarda como vacío: «no lo sé» no es «cero»."""
    def _num(clave):
        valor = (form.get(clave) or "").strip()
        if not valor:
            return None
        importe = _parse_money_decimal(valor)
        return importe if importe != 0 else None

    def _pct(clave):
        valor = (form.get(clave) or "").strip().replace("%", "").replace(",", ".")
        try:
            n = float(valor)
        except Exception:
            return None
        return n if n > 0 else None

    # ⚠️ Los porcentajes se ajustan al TIPO REAL (`_tax_pct_snap`): si se despejaron de dos importes
    # redondeados a céntimos, un 21% puede llegar como 20,99 (bug real).
    _iva = _pct("vat_pct")
    _ret = _pct("retention_pct")
    return {
        "amount_gross": _num("amount_gross"),
        "amount_net": _num("amount_net"),
        "amount_vat": _num("amount_vat"),
        "retention_amount": _num("retention_amount"),
        "vat_pct": (float(_tax_pct_snap(_iva, VAT_RATES)) if _iva is not None else None),
        "retention_pct": (float(_tax_pct_snap(_ret, RETENTION_RATES)) if _ret is not None else None),
    }


def _invoice_upload_can_force() -> bool:
    """¿Se puede enviar una factura cuyo importe NO cuadra?

    Solo cuando la sube la OFICINA desde dentro (hay sesión y lo pide expresamente con `force`):
    administración sabe si el descuadre es correcto. Al proveedor se le sigue avisando y no se le
    acepta, que es lo que evita que entren facturas con el importe equivocado."""
    return bool(session.get("user_id") and _truthy(request.form.get("force")))


@app.post('/facturacion/subir', endpoint='public_invoice_upload')
def public_invoice_upload():
    """Sube la factura o uno de los certificados exigidos.

    ⚠️ Es el ÚNICO sitio por el que entra una factura: el enlace del proveedor, la petición de un
    gasto, la liquidación de royalties y la subida DESDE DENTRO (`/facturacion?...&interno=1`) pasan
    todas por aquí, así que cualquier cambio vale para todas."""
    session_db = db()
    try:
        promoter = session_db.get(Promoter, to_uuid(request.form.get("promoter_id") or "") or uuid.uuid4())
        if not promoter:
            return jsonify({"ok": False, "error": "Identifícate primero"}), 400
        doc_key = (request.form.get("doc_key") or "").strip().upper()
        f = request.files.get("file")
        if not f or not f.filename:
            return jsonify({"ok": False, "error": "Falta el archivo"}), 400
        wt = (request.form.get("worker_type") or getattr(promoter, "prl_type", None) or "").strip().upper()
        emision = _parse_date_soft(request.form.get("issue_date"))
        if doc_key in INVOICE_MONTHLY_CERTS:
            doc = _billing_store_cert(session_db, promoter, doc_key, f)
            if not doc:
                return jsonify({"ok": False, "error": "No se pudo guardar el certificado"}), 400
            session_db.commit()
            payload = _billing_profile_payload(session_db, promoter)
            return jsonify({"ok": True, "kind": "cert", "doc_key": doc_key,
                            "docs": _billing_docs_state(session_db, promoter, payload["kind"],
                                                        worker_type=wt, issue_date=emision)})
        # PAPELES DEL ALTA del particular (recibo de autónomos, alta y baja): se guardan con el mismo
        # lector del PRL, que ya saca sus fechas de vigencia del propio documento.
        if doc_key in {k for lista in BILLING_ALTA_DOCS.values() for k, _l, _i in lista}:
            doc, aviso_prl = _prl_store_upload(session_db, promoter, doc_key, f, uploaded_via="BILLING")
            if not doc:
                return jsonify({"ok": False, "error": aviso_prl or "No se pudo guardar el documento"}), 400
            session_db.commit()
            payload = _billing_profile_payload(session_db, promoter)
            estados = _billing_docs_state(session_db, promoter, payload["kind"],
                                          worker_type=wt, issue_date=emision)
            mio = next((d for d in estados if d["key"] == doc_key), None)
            aviso = aviso_prl or ""
            if mio and not mio["ok"]:
                aviso = ("El alta y la baja tienen que cubrir la fecha de la factura."
                         if wt == "PUNTUAL" else "Ese recibo no está en vigor: sube el del último periodo.")
            return jsonify({"ok": True, "kind": "alta", "doc_key": doc_key, "docs": estados,
                            "warn": aviso})
        if doc_key != "INVOICE":
            return jsonify({"ok": False, "error": "Documento no válido"}), 400
        # ⚠️ LO PRIMERO: ¿el enlace de la liquidación vale? Si no, no se acepta la factura por aquí.
        # Antes se colaba por el ramal genérico y quedaba SIN VINCULAR a su liquidación: se aceptaba y
        # no aparecía en «pendiente de liquidar», así que nadie se enteraba (bug real). Se comprueba
        # antes que los certificados para no mandar a nadie a buscar papeles que no son el problema.
        if (request.form.get("liq_token") or "").strip() and not _parse_public_royalty_liquidation_token(
                (request.form.get("liq_token") or "").strip()):
            _invoice_attempt_log(session_db, promoter=promoter, origin="ROYALTY", code="LINK",
                                 form=request.form, filename=(getattr(f, "filename", "") or ""),
                                 reason="El enlace de la liquidación no es válido")
            return jsonify({"ok": False, "error": (
                "El enlace de esta liquidación no es válido, así que no podemos aceptar la factura "
                "por aquí: se quedaría sin vincular. Escríbenos a %s y te mandamos uno nuevo."
                % ADMIN_INVOICE_CONTACT_EMAIL)}), 400
        payload = _billing_profile_payload(session_db, promoter)
        pending = [d for d in _billing_docs_state(session_db, promoter, payload["kind"],
                                                  worker_type=wt, issue_date=emision)
                   if d["key"] != "INVOICE" and not d["ok"]]
        if pending:
            _falta_docs = ", ".join(d["label"] for d in pending)
            _invoice_attempt_log(session_db, promoter=promoter, code="DOCS", form=request.form,
                                 filename=(getattr(f, "filename", "") or ""),
                                 origin=("ROYALTY" if (request.form.get("liq_token") or "").strip()
                                         else ("REQUEST" if (request.form.get("token") or "").strip() else "LANDING")),
                                 reason="Le faltaba documentación: " + _falta_docs)
            return jsonify({"ok": False, "error": "Antes sube: " + _falta_docs}), 400
        filename = (f.filename or "factura").strip()
        is_pdf = filename.lower().endswith(".pdf") or (f.mimetype or "") == "application/pdf"
        url = upload_pdf(f, "invoices") if is_pdf else upload_file(f, "invoices")
        if not url:
            return jsonify({"ok": False, "error": "No se pudo guardar la factura"}), 400
        # Si es la factura de una LIQUIDACIÓN DE ROYALTIES: se vincula y pasa a «facturada».
        liq_token = (request.form.get("liq_token") or "").strip()
        liq_payload = _parse_public_royalty_liquidation_token(liq_token) if liq_token else None
        if liq_payload:
            # FACTURA DE UNA LIQUIDACIÓN DE ROYALTIES. Los royalties YA son una liquidación en sí
            # mismos: al subir la factura, la liquidación pasa directamente a «facturada» y, si
            # todavía no existía su registro (alguien facturó sin que se hubiera generado), se crea
            # al vuelo con los datos congelados para que aparezca como liquidación pendiente.
            kind = (liq_payload.get("kind") or "").upper()
            parsed_sem = _parse_semester_key((liq_payload.get("s") or "").strip())
            rec = None
            sem_start = sem_end = None
            bid = to_uuid(str(liq_payload.get("bid") or ""))
            if parsed_sem and bid:
                sem_start, sem_end = _semester_range(*parsed_sem)
                rec = _royalty_liquidation_record(session_db, kind, bid, sem_start)
                if rec is None:
                    rec = _ensure_royalty_liquidation_row(session_db, kind, bid, sem_start, sem_end)
                    session_db.flush()
                # Si nunca se generó, se congela lo que hay ahora para que la liquidación tenga sus
                # datos y no dependa de lo que cambien luego los ingresos.
                if not _royalty_frozen_beneficiary(rec):
                    try:
                        _benef, _s, _e, _b = _get_royalty_liquidation_beneficiary_data(
                            session_db, kind, bid, parsed_sem[0], parsed_sem[1], apply_frozen=False)
                        _royalty_freeze(session_db, rec, _benef)
                    except Exception:
                        pass
            if rec is None:
                # Sin liquidación identificada la factura quedaría huérfana: no se acepta a ciegas.
                _invoice_attempt_log(session_db, promoter=promoter, origin="ROYALTY", code="LINK",
                                     form=request.form, filename=(getattr(f, "filename", "") or ""),
                                     reason="No se pudo identificar la liquidación del enlace")
                return jsonify({"ok": False, "error": (
                    "No hemos podido identificar la liquidación de este enlace. Escríbenos a %s "
                    "antes de subir la factura, para que no se quede sin vincular."
                    % ADMIN_INVOICE_CONTACT_EMAIL)}), 400
            # ⚠️ YA HAY FACTURA: no se deja subir otra encima salvo que se pida REEMPLAZARLA, y eso
            # solo mientras no esté validada (una vez validada, lo arregla administración).
            anterior = (session_db.get(SupplierInvoice, rec.invoice_id)
                        if (rec is not None and getattr(rec, "invoice_id", None)) else None)
            reemplazar = _truthy(request.form.get("replace"))
            if (anterior is not None and (anterior.status or "").upper() == "RECHAZADA"):
                anterior = None          # se le pidió corregirla: la nueva entra sin más
            if anterior is not None and (anterior.file_url or "").strip():
                if (anterior.status or "").upper() == "VALIDADA":
                    _invoice_attempt_log(session_db, promoter=promoter, origin="ROYALTY", code="DUPLICATE",
                                         liquidation=rec, form=request.form,
                                         filename=(getattr(f, "filename", "") or ""),
                                         reason="Ya había una factura VALIDADA para esa liquidación")
                    return jsonify({"ok": False, "error": INVOICE_ALREADY_VALIDATED_MSG,
                                    "already": "VALIDADA"}), 409
                if not reemplazar:
                    _invoice_attempt_log(session_db, promoter=promoter, origin="ROYALTY", code="DUPLICATE",
                                         liquidation=rec, form=request.form,
                                         filename=(getattr(f, "filename", "") or ""),
                                         reason="Ya había una factura subida (no pidió reemplazarla)")
                    return jsonify({"ok": False, "error": INVOICE_ALREADY_UPLOADED_MSG,
                                    "already": "PENDIENTE", "can_replace": True}), 409
            # LOS DATOS DE LA FACTURA tienen que estar: si no se pudieron leer, se escriben a mano
            # ANTES de enviarla (el navegador ya lo pide; la última palabra la tiene el servidor).
            _ok_datos, _falta = _invoice_required_data_check(request.form)
            if not _ok_datos:
                _invoice_attempt_log(session_db, promoter=promoter, origin="ROYALTY", code="DATA",
                                     liquidation=rec, form=request.form,
                                     filename=(getattr(f, "filename", "") or ""), reason=_falta)
                return jsonify({"ok": False, "error": _falta, "needs_data": True}), 400
            # EL IMPORTE TIENE QUE CUADRAR con lo que se le pidió facturar.
            _dinero = _invoice_amount_fields_from_form(request.form)
            _esperado = _royalty_invoice_totals(_royalty_frozen_beneficiary(rec) or {}) if rec is not None else {}
            _ok, _motivo = _invoice_amount_check(
                _esperado.get("gross"), _esperado.get("net"),
                _dinero.get("amount_gross"), _dinero.get("retention_amount"),
                net=_dinero.get("amount_net"), vat=_dinero.get("amount_vat"))
            if not _ok and not _invoice_upload_can_force():
                _invoice_attempt_log(session_db, promoter=promoter, origin="ROYALTY", code="AMOUNT",
                                     liquidation=rec, form=request.form,
                                     filename=(getattr(f, "filename", "") or ""), reason=_motivo)
                return jsonify({"ok": False, "error": _motivo, "can_force": bool(session.get("user_id")),
                                "expected": str(_money_or_zero(_esperado.get("gross")))}), 400
            if anterior is not None and reemplazar:
                _supplier_invoice_mark_replaced(
                    session_db, [anterior],
                    "Reemplazada por la factura subida el %s" % today_local().strftime("%d/%m/%Y"))
            invoice = SupplierInvoice(
                promoter_id=promoter.id, source="REQUEST",
                royalty_liquidation_id=(rec.id if rec else None),
                artist_text=(request.form.get("artist_text") or "").strip() or None,
                concept_text=(request.form.get("concept_text") or "").strip() or "Liquidación de royalties",
                invoice_number=(request.form.get("invoice_number") or "").strip() or None,
                issue_date=parse_optional_date(request.form.get("issue_date")),
                group_company_id=to_uuid(request.form.get("group_company_id") or "") or None,
                file_url=url, original_name=filename[:200], mime_type=f.mimetype, status="PENDIENTE",
                **_invoice_amount_fields_from_form(request.form),
            )
            session_db.add(invoice)
            session_db.flush()
            if rec is not None:
                rec.status = "INVOICED"
                rec.updated_at = datetime.now(TZ_MADRID)
                rec.invoice_id = invoice.id
                rec.invoice_uploaded_at = _now_madrid()
                _royalty_history_add(rec, "INVOICED", file_url=(invoice.file_url or ""),
                                     note=(invoice.invoice_number or ""))
            session_db.commit()
            return jsonify({"ok": True, "kind": "invoice", "done": True})
        # Si viene de una PETICIÓN (bolsa), la factura se vincula a sus conceptos pendientes.
        token = (request.form.get("token") or "").strip()
        bag_req = (session_db.query(BagInvoiceRequest)
                   .filter(BagInvoiceRequest.public_token == token).first()) if token else None
        if bag_req is not None:
            # El proveedor puede marcar QUÉ conceptos cubre esta factura: uno, varios o todos. Si no
            # marca nada (o el formulario es antiguo), se aplica a todo lo que siga pendiente.
            permitidos = [str(x) for x in (bag_req.expense_ids or [])]
            marcados = [x for x in request.form.getlist("expense_ids") if x in permitidos]
            objetivo = marcados or permitidos
            # ⚠️ YA HAY FACTURA en esta petición: no se sube otra encima salvo que se pida
            # REEMPLAZARLA, y solo mientras ninguna esté validada.
            previas = (session_db.query(SupplierInvoice)
                       .filter(SupplierInvoice.invoice_request_id == bag_req.id)
                       .order_by(SupplierInvoice.created_at.desc()).all())
            # Una RECHAZADA no cuenta: se le pidió corregirla y volver a mandarla.
            previas = [x for x in previas if (x.file_url or "").strip()
                       and (x.status or "").upper() != "RECHAZADA"]
            if previas:
                if any((x.status or "").upper() == "VALIDADA" for x in previas):
                    _invoice_attempt_log(session_db, promoter=promoter, origin="REQUEST", code="DUPLICATE",
                                         bag_id=bag_req.bag_id, form=request.form,
                                         filename=(getattr(f, "filename", "") or ""),
                                         reason="Ya había una factura VALIDADA en esa petición")
                    return jsonify({"ok": False, "error": INVOICE_ALREADY_VALIDATED_MSG,
                                    "already": "VALIDADA"}), 409
                if not _truthy(request.form.get("replace")):
                    _invoice_attempt_log(session_db, promoter=promoter, origin="REQUEST", code="DUPLICATE",
                                         bag_id=bag_req.bag_id, form=request.form,
                                         filename=(getattr(f, "filename", "") or ""),
                                         reason="Ya había una factura subida (no pidió reemplazarla)")
                    return jsonify({"ok": False, "error": INVOICE_ALREADY_UPLOADED_MSG,
                                    "already": "PENDIENTE", "can_replace": True}), 409
            _ok_datos, _falta = _invoice_required_data_check(request.form)
            if not _ok_datos:
                _invoice_attempt_log(session_db, promoter=promoter, origin="REQUEST", code="DATA",
                                     bag_id=bag_req.bag_id, form=request.form,
                                     filename=(getattr(f, "filename", "") or ""), reason=_falta)
                return jsonify({"ok": False, "error": _falta, "needs_data": True}), 400
            # EL IMPORTE TIENE QUE CUADRAR con la suma de los conceptos que cubre esta factura.
            _dinero = _invoice_amount_fields_from_form(request.form)
            _esp_net = _esp_gross = Decimal("0")
            for _eid in objetivo:
                _exp = session_db.get(BagExpense, to_uuid(str(_eid)) or uuid.uuid4())
                if _exp is None:
                    continue
                # Incluye los SUPLIDOS (sin IVA): es lo que hay que facturar de verdad.
                _imp = _expense_invoice_breakdown(_exp)
                _esp_net += _imp["net"]
                _esp_gross += _imp["gross"]
            _ok, _motivo = _invoice_amount_check(_esp_gross, _esp_net, _dinero.get("amount_gross"),
                                                 _dinero.get("retention_amount"),
                                                 net=_dinero.get("amount_net"),
                                                 vat=_dinero.get("amount_vat"))
            if not _ok and not _invoice_upload_can_force():
                _invoice_attempt_log(session_db, promoter=promoter, origin="REQUEST", code="AMOUNT",
                                     bag_id=bag_req.bag_id, form=request.form,
                                     filename=(getattr(f, "filename", "") or ""), reason=_motivo)
                return jsonify({"ok": False, "error": _motivo, "can_force": bool(session.get("user_id")),
                                "expected": str(_esp_gross)}), 400
            if previas and _truthy(request.form.get("replace")):
                _supplier_invoice_mark_replaced(
                    session_db, previas,
                    "Reemplazada por la factura subida el %s" % today_local().strftime("%d/%m/%Y"))
            inv_num = (request.form.get("invoice_number") or "").strip() or None
            invoice = SupplierInvoice(
                promoter_id=promoter.id, source="REQUEST", bag_id=bag_req.bag_id,
                invoice_request_id=bag_req.id,
                artist_text=(request.form.get("artist_text") or "").strip() or None,
                concept_text=(request.form.get("concept_text") or "").strip() or None,
                invoice_number=inv_num,
                issue_date=parse_optional_date(request.form.get("issue_date")),
                group_company_id=to_uuid(request.form.get("group_company_id") or "") or None,
                file_url=url, original_name=filename[:200], mime_type=f.mimetype, status="PENDIENTE",
                **_invoice_amount_fields_from_form(request.form),
            )
            session_db.add(invoice)
            session_db.flush()
            gastos = []
            for exp_id in objetivo:
                expense = session_db.get(BagExpense, to_uuid(str(exp_id)) or uuid.uuid4())
                if expense is None:
                    continue
                # Si no se marcó nada, no se pisa lo que ya tiene factura.
                if not marcados and _bag_expense_has_invoice(expense):
                    continue
                gastos.append(expense)
            total = _money_or_zero(request.form.get("amount_gross"))
            previstos = [_money_or_zero(e.amount_gross) for e in gastos]
            suma_prev = sum(previstos, Decimal("0"))
            group_key = uuid.uuid4().hex
            for expense, prev in zip(gastos, previstos):
                if total and suma_prev:
                    trozo = (total * prev / suma_prev).quantize(Decimal("0.01"))
                elif total:
                    trozo = (total / Decimal(len(gastos))).quantize(Decimal("0.01"))
                else:
                    trozo = prev
                _bag_expense_invoice_apply(
                    session_db, expense, file_url=url, file_name=filename, file_mime=f.mimetype,
                    invoice_number=inv_num, amount=trozo, group_key=group_key,
                    supplier_invoice_id=invoice.id,
                )
            session_db.flush()
            # La petición solo se cierra cuando TODOS sus conceptos tienen factura.
            pendientes = [x for x in permitidos
                          if not _bag_expense_has_invoice(session_db.get(BagExpense, to_uuid(x) or uuid.uuid4()))]
            if not pendientes:
                bag_req.status = "DONE"
            bag_req.updated_at = datetime.utcnow()
            session_db.commit()
            return jsonify({"ok": True, "kind": "invoice", "done": not pendientes,
                            "linked": len(gastos), "pending": len(pendientes)})
        target_user_id = to_uuid(request.form.get("target_user_id") or "") or None
        inv = SupplierInvoice(
            promoter_id=promoter.id, source="LANDING",
            artist_text=(request.form.get("artist_text") or "").strip() or None,
            concept_text=(request.form.get("concept_text") or "").strip() or None,
            invoice_number=(request.form.get("invoice_number") or "").strip() or None,
            issue_date=parse_optional_date(request.form.get("issue_date")),
            target_user_id=target_user_id,
            group_company_id=to_uuid(request.form.get("group_company_id") or "") or None,
            file_url=url, original_name=filename[:200], mime_type=f.mimetype, status="PENDIENTE",
            **_invoice_amount_fields_from_form(request.form),
        )
        session_db.add(inv)
        session_db.flush()
        # La factura entra en «Mis gastos» de la persona elegida, con su plazo de una semana.
        if target_user_id:
            inv.promoter = promoter
            _personal_expense_from_invoice(session_db, inv, target_user_id)
        session_db.commit()
        return jsonify({"ok": True, "kind": "invoice", "done": True})
    except Exception:
        session_db.rollback()
        app.logger.exception("public_invoice_upload")
        return jsonify({"ok": False, "error": "Error al subir el archivo"}), 500
    finally:
        session_db.close()


# ---------------------------------------------------------------------------
#  ALTA / ACTUALIZACIÓN DE UN TERCERO POR ENLACE PÚBLICO  (/alta/<token>)
#  ------------------------------------------------------------------------
#  Se genera desde Terceros («Link de alta») o desde un tercero concreto
#  («Solicitar actualización») y se manda por correo, WhatsApp, SMS o copiando el enlace. El propio
#  tercero rellena sus datos por pasos y al terminar se crea o se actualiza su ficha.
#
#  Reutiliza lo que ya existe de la landing de facturación: `_tax_id_kind` (CIF→empresa,
#  DNI→particular), `_prl_norm_dni` para casar identificaciones, `_mask_value` para no destapar
#  datos ajenos, y los campos que el proveedor ya rellenaba una vez (fiscal_address, bank_account,
#  data_consent_at). Los documentos van a `PersonDocument` (DNI/pasaporte/carnet/fidelización) y el
#  certificado bancario a `PersonComplianceDoc` (CERT_BANK), donde ya viven los certificados.
# ---------------------------------------------------------------------------

INTAKE_TITLES = {"ALTA": "Alta nueva", "UPDATE": "Actualización de datos"}
INTAKE_PAGE_TITLES = {"ALTA": "Alta en base de datos", "UPDATE": "Actualizar datos"}
INTAKE_MAX_ROWS = 20          # tope de contactos / tarjetas por envío (anti-abuso)


# --------------------------------------------------------------- IBAN
def _iban_clean(value) -> str:
    return re.sub(r"[^0-9A-Za-z]", "", str(value or "")).upper()


def _iban_is_valid(value) -> bool:
    """Validación estándar mod-97 (ISO 13616). Evita dar por bueno un IBAN mal leído."""
    iban = _iban_clean(value)
    if not (15 <= len(iban) <= 34) or not iban[:2].isalpha() or not iban[2:4].isdigit():
        return False
    movido = iban[4:] + iban[:4]
    numero = ""
    for ch in movido:
        numero += ch if ch.isdigit() else str(ord(ch) - 55)
    try:
        return int(numero) % 97 == 1
    except ValueError:
        return False


def _iban_pretty(value) -> str:
    iban = _iban_clean(value)
    return " ".join(iban[i:i + 4] for i in range(0, len(iban), 4))


def _detect_iban_in_text(text: str) -> str:
    """Primer IBAN VÁLIDO que aparezca en el texto (con o sin espacios de por medio)."""
    limpio = re.sub(r"[   ]", " ", str(text or ""))
    for m in re.finditer(r"\b([A-Z]{2})\s?(\d{2})((?:\s?[A-Z0-9]){10,30})", limpio.upper()):
        cand = _iban_clean(m.group(0))
        # Se prueba recortando por la cola: el OCR/PDF suele pegar basura detrás.
        for fin in range(len(cand), 14, -1):
            if _iban_is_valid(cand[:fin]):
                return cand[:fin]
    return ""


def _intake_file_text(storage) -> str:
    """Texto de un PDF subido (pypdf). Si es una imagen o un PDF escaneado, devuelve ''."""
    try:
        nombre = (getattr(storage, "filename", "") or "").lower()
        tipo = (getattr(storage, "mimetype", "") or "").lower()
        if not (nombre.endswith(".pdf") or "pdf" in tipo):
            return ""
        from pypdf import PdfReader
        storage.stream.seek(0)
        datos = storage.stream.read()
        storage.stream.seek(0)
        lector = PdfReader(BytesIO(datos))
        return "\n".join((p.extract_text() or "") for p in lector.pages[:6])
    except Exception:
        return ""


# --------------------------------------------------------------- enlaces
def _intake_title(kind: str) -> str:
    return INTAKE_TITLES.get((kind or "ALTA").upper(), INTAKE_TITLES["ALTA"])


def _intake_person_label(promoter) -> str:
    if promoter is None:
        return ""
    nombre = " ".join([x for x in [(promoter.first_name or "").strip(),
                                   (promoter.last_name or "").strip()] if x]).strip()
    return (promoter.nick or "").strip() or nombre


def _intake_link_payload(session_db, link) -> dict:
    """Todo lo que necesita la pantalla para compartir el enlace (y la previsualización)."""
    promoter = link.promoter or (session_db.get(Promoter, link.promoter_id) if link.promoter_id else None)
    nombre = _intake_person_label(promoter)
    titulo = _intake_title(link.kind)
    url = _external_url_for("public_third_party_intake", token=link.public_token)
    # Asunto del correo / texto de WhatsApp y SMS: el mismo título, en una línea.
    asunto = titulo + (f" · {nombre}" if nombre else "")
    quien = (link.created_by_nick or "").strip()
    # ⚠️ El enlace va en su PROPIA línea (doble salto): es lo que hace que WhatsApp/SMS lo
    # detecten como clicable (misma convención que `shareTextWithClickableUrl`).
    if (link.kind or "").upper() == "UPDATE":
        cuerpo = (f"Hola{(' ' + nombre) if nombre else ''}: {quien or 'el equipo'} te pide que "
                  f"actualices tus datos en nuestro Back Office.\n\n{url}")
    else:
        cuerpo = (f"Hola{(' ' + nombre) if nombre else ''}: {quien or 'el equipo'} te pide que "
                  f"te des de alta en nuestro Back Office.\n\n{url}")
    # ⚠️ og:image SIEMPRE por nuestro endpoint (JPEG 1200×630): WhatsApp descarta las imágenes
    # grandes o sin dimensiones declaradas. La fuente es el logo/foto del tercero y, si no tiene
    # (un alta nueva no sabe todavía quién es), el símbolo de «sin foto», NO el logo de la casa.
    foto = _external_url_for("public_intake_og_image", token=link.public_token)
    tiene_foto = bool((getattr(promoter, "logo_url", "") or "").strip())
    return {
        "id": str(link.id),
        "token": link.public_token,
        "kind": (link.kind or "ALTA").upper(),
        "url": url,
        "title": titulo,
        "subject": asunto,
        "person": nombre,
        "photo": foto,
        "has_photo": tiene_foto,
        "photo_placeholder": _external_url_for("static", filename="img/placeholder_photo.png"),
        "text": cuerpo,
        "whatsapp": "https://wa.me/?text=" + quote(cuerpo),
        "sms": "sms:?&body=" + quote(cuerpo),
        "emails": ([e for e in [(getattr(promoter, "contact_email", "") or "").strip()] if e]
                   if promoter is not None else []),
        "phones": ([p for p in [(getattr(promoter, "contact_phone", "") or "").strip()] if p]
                   if promoter is not None else []),
        "sent_channel": (link.sent_channel or ""),
        "sent_to": (link.sent_to or ""),
        "status": (link.status or "ACTIVE"),
    }


def _intake_link_create(session_db, promoter=None, kind: str = "ALTA") -> ThirdPartyIntakeLink:
    """Crea el enlace. Si ya hay uno ACTIVO para ese tercero, se reutiliza (no se llenan de tokens)."""
    kind = "UPDATE" if promoter is not None else "ALTA"
    if promoter is not None:
        existente = (session_db.query(ThirdPartyIntakeLink)
                     .filter(ThirdPartyIntakeLink.promoter_id == promoter.id,
                             ThirdPartyIntakeLink.status == "ACTIVE")
                     .order_by(ThirdPartyIntakeLink.created_at.desc()).first())
        if existente is not None:
            return existente
    st = _current_user_state()
    link = ThirdPartyIntakeLink(
        public_token=_uuid_token(),
        promoter_id=(promoter.id if promoter is not None else None),
        kind=kind,
        status="ACTIVE",
        created_by_user_id=to_uuid(st.get("user_id")) if st.get("user_id") else None,
        created_by_nick=(st.get("nick") or st.get("email") or "").strip() or None,
    )
    session_db.add(link)
    session_db.flush()
    return link


# ---------------------------------------------------------------------------
#  PETICIONES DE DOCUMENTO: renovar uno CADUCADO (DNI, carnet o pasaporte) o pedir el carnet de
#  conducir expresamente. Se manda un enlace: la persona sube las dos caras, se leen el número y las
#  fechas, las confirma y el documento nuevo SUSTITUYE al anterior.
# ---------------------------------------------------------------------------
PERSON_DOC_RENEW_KINDS = {"DNI": "DNI", "LICENSE": "carnet de conducir", "PASSPORT": "pasaporte"}
# No se le vuelve a escribir a la misma persona por el mismo documento hasta pasados estos días.
PERSON_DOC_REMIND_DAYS = 30


def _person_doc_owner_contact(session_db, owner_type: str, owner_id):
    """(nombre, correo) de quien tiene el documento (personal de la casa o tercero)."""
    ot = (owner_type or "").upper()
    if ot == "USER":
        u = session_db.get(User, owner_id)
        prof = session_db.query(UserProfile).filter(UserProfile.user_id == owner_id).first() if u else None
        nombre = ((prof.nick if prof else "") or (u.email if u else "") or "").strip()
        return nombre, ((u.email if u else "") or "").strip()
    if ot == "PROMOTER":
        p = session_db.get(Promoter, owner_id)
        if p is None:
            return "", ""
        nombre = " ".join(x for x in [(p.first_name or "").strip(), (p.last_name or "").strip()] if x).strip()
        return (nombre or (p.nick or "").strip()), (p.contact_email or "").strip()
    return "", ""


def _person_doc_request_create(session_db, owner_type: str, owner_id, kind: str, doc=None,
                               reason: str = "REQUESTED"):
    """Crea (o reutiliza) la petición ACTIVA de ese documento para esa persona."""
    ot, k = (owner_type or "").upper(), (kind or "").upper()
    if k not in PERSON_DOC_RENEW_KINDS:
        return None
    fila = (session_db.query(PersonDocRequest)
            .filter(PersonDocRequest.owner_type == ot, PersonDocRequest.owner_id == owner_id,
                    PersonDocRequest.kind == k, PersonDocRequest.status == "ACTIVE").first())
    if fila is None:
        try:
            estado = _current_user_state()          # el cron corre sin usuario: no pasa nada
        except Exception:
            estado = {}
        fila = PersonDocRequest(token=uuid.uuid4().hex, owner_type=ot, owner_id=owner_id, kind=k,
                                document_id=(doc.id if doc is not None else None), reason=reason,
                                requested_by_user_id=to_uuid(estado.get("user_id")),
                                requested_by_nick=(estado.get("nick") or "").strip() or None)
        session_db.add(fila)
        session_db.flush()
    elif doc is not None and not fila.document_id:
        fila.document_id = doc.id
    return fila


def _person_doc_request_email_html(req, url: str, nombre: str, caducado_el=None) -> str:
    """Correo pidiendo el documento nuevo: cabecera del back office, qué documento y el botón."""
    etiqueta = PERSON_DOC_RENEW_KINDS.get((req.kind or "").upper(), "documento")
    banner = _external_url_for("static", filename="img/Banner.png")
    hola = "Hola" + (f", {escape(nombre)}" if nombre else "")
    if (req.reason or "").upper() == "EXPIRED":
        titulo = f"Tu {etiqueta} ha caducado"
        texto = (f"Nos consta que tu <strong>{escape(etiqueta)}</strong> "
                 + (f"caducó el <strong>{caducado_el.strftime('%d/%m/%Y')}</strong>. " if caducado_el else "está caducado. ")
                 + "Súbenos el nuevo para tenerlo al día.")
    else:
        titulo = f"Nos falta tu {etiqueta}"
        texto = f"Necesitamos una copia de tu <strong>{escape(etiqueta)}</strong>."
    dos_caras = (req.kind or "").upper() != "PASSPORT"
    detalle = ("Solo tienes que hacer una foto de las <strong>dos caras</strong>"
               if dos_caras else "Solo tienes que hacer una foto de la <strong>página de datos</strong>")
    return f"""
    <div style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:620px;margin:0 auto;padding:8px 4px;">
      <div style="margin-bottom:10px;">
        <img src="{escape(banner)}" alt="Back Office" style="max-height:44px;max-width:280px;object-fit:contain;">
      </div>
      <h2 style="text-align:center;font-size:20px;color:#111;margin:0 0 18px;">{escape(titulo)}</h2>
      <div style="border:1px solid #e5e7eb;border-radius:14px;padding:18px;background:#f9fafb;">
        <p style="font-size:15px;color:#111;margin:0 0 10px;">{hola}:</p>
        <p style="font-size:15px;color:#111;margin:0 0 16px;">{texto}</p>
        <p style="font-size:14px;color:#374151;margin:0 0 16px;">{detalle}: leemos solos el número y las fechas
          y te los enseñamos para que les des el visto bueno. El documento nuevo sustituye al anterior.</p>
        <p style="margin:0;">
          <a href="{escape(url)}" style="display:inline-block;background:#E33D48;color:#fff;text-decoration:none;
             font-weight:700;font-size:15px;padding:12px 22px;border-radius:10px;">Subir mi {escape(etiqueta)}</a>
        </p>
      </div>
      <p style="color:#6b7280;font-size:12px;margin:14px 0 0;">Si ya nos lo has mandado, no hace falta que hagas nada.</p>
    </div>
    """


def _person_doc_request_send(session_db, req, nombre: str = "", correo: str = "", caducado_el=None):
    """Manda (o reenvía) el correo con el enlace para subir el documento."""
    if not correo:
        nombre_c, correo = _person_doc_owner_contact(session_db, req.owner_type, req.owner_id)
        nombre = nombre or nombre_c
    if not correo:
        return False, "sin correo"
    url = _external_url_for("public_document_renew", token=req.token)
    etiqueta = PERSON_DOC_RENEW_KINDS.get((req.kind or "").upper(), "documento")
    asunto = (f"Tu {etiqueta} ha caducado" if (req.reason or "").upper() == "EXPIRED"
              else f"Nos falta tu {etiqueta}")
    ok, err = _send_optional_email(correo, asunto,
                                   _person_doc_request_email_html(req, url, nombre, caducado_el),
                                   text_body=f"Sube tu {etiqueta} aquí: {url}")
    if ok:
        req.sent_to = correo
        req.last_sent_at = _now_madrid()
    return ok, err


def _person_docs_expired_sweep(limit: int = 200) -> dict:
    """Repasa los DNI, carnets y pasaportes CADUCADOS y le escribe a cada persona para que suba el
    nuevo. No insiste: como mucho un correo por documento cada `PERSON_DOC_REMIND_DAYS` días."""
    session_db = db()
    enviados, saltados, errores = 0, 0, []
    try:
        hoy = today_local()
        docs = (session_db.query(PersonDocument)
                .filter(PersonDocument.kind.in_(tuple(PERSON_DOC_RENEW_KINDS)),
                        PersonDocument.expiry_date.isnot(None),
                        PersonDocument.expiry_date < hoy)
                .order_by(PersonDocument.expiry_date.asc()).limit(limit).all())
        for doc in docs:
            req = _person_doc_request_create(session_db, doc.owner_type, doc.owner_id, doc.kind,
                                             doc=doc, reason="EXPIRED")
            if req is None:
                continue
            if req.last_sent_at and (_now_madrid() - req.last_sent_at).days < PERSON_DOC_REMIND_DAYS:
                saltados += 1
                continue
            nombre, correo = _person_doc_owner_contact(session_db, doc.owner_type, doc.owner_id)
            ok, err = _person_doc_request_send(session_db, req, nombre, correo, doc.expiry_date)
            if ok:
                enviados += 1
            else:
                errores.append(f"{nombre or doc.owner_id}: {err}")
        session_db.commit()
    except Exception as exc:
        session_db.rollback()
        errores.append(str(exc))
    finally:
        session_db.close()
    return {"enviados": enviados, "saltados": saltados, "errores": errores[:10]}


def _song_delivery_reminders_sweep(limit: int = 100) -> dict:
    """Recuerda UNA VEZ AL DÍA las entregas de masters pedidas por correo que siguen sin llegar.

    Solo insiste con los enlaces ACTIVOS que se mandaron por correo (`reminders_enabled`), y como
    mucho un correo al día por enlace: en cuanto lo cumplimentan (SUBMITTED) o se anula, deja de
    insistir solo, sin que nadie lo pare a mano."""
    salida = {"recordadas": 0, "sin_correo": 0, "errores": 0}
    session_db = db()
    try:
        ahora = _now_madrid()
        filas = (session_db.query(SongMasterDeliveryLink)
                 .filter(SongMasterDeliveryLink.status == "ACTIVE",
                         SongMasterDeliveryLink.reminders_enabled == True)     # noqa: E712
                 .order_by(SongMasterDeliveryLink.reminder_last_at.asc().nullsfirst())
                 .limit(limit).all())
        for link in filas:
            ultimo = getattr(link, "reminder_last_at", None)
            if ultimo is not None:
                try:
                    if ultimo.tzinfo is None:
                        ultimo = ultimo.replace(tzinfo=TZ_MADRID)
                    if (ahora - ultimo.astimezone(TZ_MADRID)).total_seconds() < 20 * 3600:
                        continue                     # ya se le recordó hoy
                except Exception:
                    pass
            destinos = _dedupe_valid_email_addresses(
                [x.strip() for x in (link.target_email or "").split(",") if x.strip()])
            if not destinos:
                salida["sin_correo"] += 1
                link.reminders_enabled = False       # sin a quién escribir, no se insiste en balde
                continue
            song = session_db.get(Song, link.song_id)
            if song is None:
                link.reminders_enabled = False
                continue
            artista = _song_artist_names_str(song)
            colab = (getattr(song, "collaborator", None) or "").strip()
            titulo_artista = artista + (" (con %s)" % colab if colab else "")
            asunto = "Recordatorio · entrega de masters · %s · %s" % (titulo_artista, song.title or "")
            url_pub = _song_delivery_public_url(link)
            html = _song_delivery_email_html(song, titulo_artista, url_pub, (song.cover_url or "").strip(),
                                             recordatorio=True)
            ok, _err = _send_optional_email(destinos, asunto, html,
                                            text_body="Recordatorio de entrega de masters. Enlace: " + url_pub)
            link.reminder_last_at = ahora
            if ok:
                link.reminder_count = _safe_int(getattr(link, "reminder_count", 0)) + 1
                salida["recordadas"] += 1
            else:
                salida["errores"] += 1
            session_db.add(link)
            session_db.commit()
        session_db.commit()
    except Exception:
        session_db.rollback()
        app.logger.exception("[entrega-masters] recordatorios")
    finally:
        session_db.close()
    return salida


@app.get("/cron/entrega-masters", endpoint="cron_song_delivery_reminders")
def cron_song_delivery_reminders():
    """Cron diario: recuerda las entregas de masters que se pidieron por correo y no han llegado."""
    clave = (request.args.get("key") or "").strip()
    esperada = (os.getenv("DOCS_CRON_KEY") or os.getenv("EXPENSE_CRON_KEY")
                or os.getenv("CHARTMETRIC_CRON_KEY") or "").strip()
    if not esperada or clave != esperada:
        abort(404)
    return jsonify({"ok": True, **_song_delivery_reminders_sweep()})


@app.get("/cron/materiales-proyecto", endpoint="cron_disco_materials_reminders")
def cron_disco_materials_reminders():
    """Cron diario: recuerda el PLAZO DE ENTREGA de materiales de los proyectos discográficos.

    ⚠️ Insiste UNA sola vez (a `DISCO_MATERIALS_REMINDER_DAYS` días de la fecha máxima) y solo si los
    másters no están subidos. Va también dentro del cron diario de documentos, para no depender de
    otra tarea en el servidor."""
    clave = (request.args.get("key") or "").strip()
    esperada = (os.getenv("DOCS_CRON_KEY") or os.getenv("EXPENSE_CRON_KEY")
                or os.getenv("CHARTMETRIC_CRON_KEY") or "").strip()
    if not esperada or clave != esperada:
        abort(404)
    # …y de paso el aviso del PLAN al artista (para no depender de otra tarea en el servidor).
    return jsonify({"ok": True, **_disco_materials_reminder_sweep(),
                    "plan_notice": _disco_plan_notice_sweep()})


@app.get("/cron/documentos-caducados", endpoint="cron_expired_documents")
def cron_expired_documents():
    """Cron diario: avisa por correo a quien tenga el DNI, el carnet o el pasaporte caducado."""
    clave = (request.args.get("key") or "").strip()
    esperada = (os.getenv("DOCS_CRON_KEY") or os.getenv("EXPENSE_CRON_KEY")
                or os.getenv("CHARTMETRIC_CRON_KEY") or "").strip()
    if not esperada or clave != esperada:
        abort(404)
    # Se aprovecha el mismo paso diario para recordar las entregas de masters pendientes: así no
    # hace falta configurar otro cron en el servidor (el suyo propio existe igualmente).
    return jsonify({"ok": True, **_person_docs_expired_sweep(),
                    "entregas_masters": _song_delivery_reminders_sweep(),
                    # Y el recordatorio del PLAZO DE ENTREGA de materiales de un proyecto (a
                    # DISCO_MATERIALS_REMINDER_DAYS días de la fecha máxima, una sola vez).
                    "materiales_proyecto": _disco_materials_reminder_sweep()})


@app.post("/documentos/pedir", endpoint="person_doc_request_send")
@admin_required
def person_doc_request_send_view():
    """Pide un documento a una persona o tercero (p. ej. «Solicitar carnet de conducir» desde su
    ficha, o volver a pedir uno caducado). Devuelve el enlace por si se prefiere compartirlo a mano."""
    session_db = db()
    try:
        ot = (request.form.get("owner_type") or "").upper()
        oid = to_uuid((request.form.get("owner_id") or "").strip() or "")
        kind = (request.form.get("kind") or "").upper()
        if ot not in ("USER", "PROMOTER") or not oid or kind not in PERSON_DOC_RENEW_KINDS:
            return jsonify({"ok": False, "error": "Petición no válida."}), 400
        req = _person_doc_request_create(session_db, ot, oid, kind, reason="REQUESTED")
        nombre, correo = _person_doc_owner_contact(session_db, ot, oid)
        correo = (request.form.get("email") or "").strip() or correo
        ok, err = _person_doc_request_send(session_db, req, nombre, correo)
        session_db.commit()
        url = _external_url_for("public_document_renew", token=req.token)
        if not ok:
            return jsonify({"ok": True, "sent": False, "error": err, "url": url,
                            "message": f"No se pudo enviar el correo ({err}). Copia el enlace y mándaselo."})
        return jsonify({"ok": True, "sent": True, "url": url,
                        "message": f"Le hemos pedido el {PERSON_DOC_RENEW_KINDS[kind]} a {nombre or 'la persona'} ({correo})."})
    except Exception as exc:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        session_db.close()


@app.route("/documento/<token>", methods=["GET", "POST"], endpoint="public_document_renew")
def public_document_renew(token):
    """Página pública para subir el documento nuevo (las dos caras). Se leen el número y las fechas en
    el navegador, la persona las confirma y lo guardado SUSTITUYE al documento anterior."""
    session_db = db()
    try:
        req = (session_db.query(PersonDocRequest)
               .filter(PersonDocRequest.token == (token or "").strip()).first())
        if req is None:
            abort(404)
        nombre, _correo = _person_doc_owner_contact(session_db, req.owner_type, req.owner_id)
        etiqueta = PERSON_DOC_RENEW_KINDS.get((req.kind or "").upper(), "documento")
        if request.method == "POST":
            if (req.status or "ACTIVE").upper() != "ACTIVE":
                return jsonify({"ok": False, "error": "Este enlace ya se ha usado."}), 400
            front = _store_doc_image_from_dataurl(request.form.get("front_b64"))
            back = _store_doc_image_from_dataurl(request.form.get("back_b64"))
            if not (front or back):
                return jsonify({"ok": False, "error": "Sube al menos una cara del documento."}), 400
            owner, ot = _person_doc_owner(session_db, req.owner_type, req.owner_id)
            if owner is None:
                return jsonify({"ok": False, "error": "No encontramos tu ficha."}), 404
            antiguo = session_db.get(PersonDocument, req.document_id) if req.document_id else None
            doc = PersonDocument(
                owner_type=ot, owner_id=owner.id, kind=(req.kind or "DNI").upper(),
                doc_number=(request.form.get("doc_number") or "").strip() or None,
                full_name=(request.form.get("full_name") or "").strip() or None,
                birth_date=parse_optional_date(request.form.get("birth_date")),
                expiry_date=parse_optional_date(request.form.get("expiry_date")),
                issue_date=parse_optional_date(request.form.get("issue_date")),
                address=(request.form.get("address") or "").strip() or None,
                front_url=front, back_url=back,
                sort_order=(antiguo.sort_order if antiguo is not None else 0),
                created_by_nick="El propio interesado",
            )
            session_db.add(doc)
            session_db.flush()
            # El nuevo SUSTITUYE al anterior.
            if antiguo is not None:
                session_db.delete(antiguo)
            # Y sus datos oficiales pasan a la ficha (los ha confirmado la propia persona).
            try:
                _person_doc_apply_to_profile(session_db, ot, owner, doc,
                                             choices={k: "doc" for k in PERSON_DOC_OFFICIAL_LABELS})
            except Exception:
                pass
            req.status = "DONE"
            req.done_at = _now_madrid()
            session_db.commit()
            return jsonify({"ok": True})
        return render_template("public_document_renew.html", req=req, person_name=nombre,
                               kind_label=etiqueta, two_faces=((req.kind or "").upper() != "PASSPORT"),
                               done=((req.status or "ACTIVE").upper() != "ACTIVE"))
    finally:
        session_db.close()


def _intake_email_html(link, url: str, nombre: str, quien: str, nota: str = "") -> str:
    """Correo con la cabecera del back office, el título que toque, el texto y el botón."""
    es_update = (link.kind or "").upper() == "UPDATE"
    titulo = _intake_title(link.kind)
    banner = _external_url_for("static", filename="img/Banner.png")
    boton = "Actualizar datos" if es_update else "Darme de alta"
    texto = (f"<strong>{escape(quien or 'El equipo')}</strong> ha solicitado que "
             + ("actualices tus datos del Back Office."
                if es_update else "te des de alta en nuestro Back Office."))
    hola = "Hola" + (f", {escape(nombre)}" if nombre else "")
    extra = (f"<p style='font-size:14px;color:#374151;margin:0 0 14px;'>{escape(nota)}</p>"
             if (nota or "").strip() else "")
    return f"""
    <div style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;max-width:620px;margin:0 auto;padding:8px 4px;">
      <div style="margin-bottom:10px;">
        <img src="{escape(banner)}" alt="Back Office" style="max-height:44px;max-width:280px;object-fit:contain;">
      </div>
      <h2 style="text-align:center;font-size:20px;color:#111;margin:0 0 18px;">{escape(titulo)}</h2>
      <div style="border:1px solid #e5e7eb;border-radius:14px;padding:18px;background:#f9fafb;">
        <p style="font-size:15px;color:#111;margin:0 0 10px;">{hola}:</p>
        <p style="font-size:15px;color:#111;margin:0 0 16px;">{texto}</p>
        {extra}
        <p style="margin:0;">
          <a href="{escape(url)}" style="display:inline-block;background:#E33D48;color:#fff;text-decoration:none;
             font-weight:700;font-size:15px;padding:12px 22px;border-radius:10px;">{escape(boton)}</a>
        </p>
      </div>
      <p style="font-size:12px;color:#6b7280;margin:14px 0 0;">Si el botón no funciona, copia este enlace:<br>
        <a href="{escape(url)}" style="color:#007CA2;">{escape(url)}</a></p>
    </div>
    """


# --------------------------------------------------------------- datos actuales
def _intake_promoter_payload(session_db, promoter, masked: bool) -> dict:
    """Datos actuales del tercero para pintar el formulario ya rellenado.

    `masked=True` cuando quien mira NO es el dueño del enlace (en un alta nueva alguien teclea un
    CIF/DNI que ya existe): se le dice que ya está creado y se le deja actualizar, pero sin
    destaparle el correo, el teléfono ni la cuenta de otro.
    """
    if promoter is None:
        return {}
    kind = "EMPRESA" if (promoter.kind or "").lower() == "empresa" else _tax_id_kind(promoter.tax_id or "")
    company = (session_db.query(PromoterCompany)
               .filter(PromoterCompany.promoter_id == promoter.id)
               .order_by(PromoterCompany.created_at.asc()).first()) if kind == "EMPRESA" else None
    nombre = " ".join([x for x in [(promoter.first_name or "").strip(),
                                   (promoter.last_name or "").strip()] if x]).strip()

    def _v(value):
        value = (value or "").strip()
        return _mask_value(value) if (masked and value) else value

    contactos = []
    for c in (session_db.query(PromoterContact)
              .filter(PromoterContact.promoter_id == promoter.id)
              .order_by(PromoterContact.created_at.asc()).all()):
        contactos.append({
            "name": " ".join([x for x in [(c.first_name or "").strip(), (c.last_name or "").strip()] if x]).strip(),
            "title": (c.title or ""),
            "email": _v(c.email),
            "phone": _v(c.phone or c.mobile),
        })
    tarjetas = []
    for d in (session_db.query(PersonDocument)
              .filter(PersonDocument.owner_type == "PROMOTER", PersonDocument.owner_id == promoter.id,
                      PersonDocument.kind == "LOYALTY")
              .order_by(PersonDocument.sort_order.asc(), PersonDocument.created_at.asc()).all()):
        tarjetas.append({"company": (d.company or ""), "number": _v(d.doc_number)})
    return {
        "id": str(promoter.id),
        "kind": kind or "PARTICULAR",
        "masked": bool(masked),
        "label": _intake_person_label(promoter),
        "tax_id": (promoter.tax_id or ""),
        "full_name": nombre,
        "company_name": (promoter.nick or "") if kind == "EMPRESA" else "",
        # Dirección fiscal: junta para MOSTRARLA y en piezas para el formulario (la contabilidad
        # necesita el código postal, el municipio y la provincia por separado).
        "fiscal_address": (_fiscal_address_text(company if company is not None else promoter)
                           or promoter.address or ""),
        "fiscal": _intake_fiscal_parts(promoter, company, masked=masked),
        "email": _v(promoter.contact_email),
        "phone": _v(promoter.contact_phone),
        "bank_account": (_mask_value(promoter.bank_account or "") if masked
                         else _iban_pretty(promoter.bank_account or "")),
        "has_bank": bool((promoter.bank_account or "").strip()),
        "logo_url": (promoter.logo_url or ""),
        "travel_departure_flight": (promoter.travel_departure_flight or ""),
        "travel_departure_train": (promoter.travel_departure_train or ""),
        "contacts": contactos,
        "loyalty": tarjetas,
        "docs": [d["kind"] for d in _person_documents_for(session_db, "PROMOTER", promoter.id)],
    }


def _intake_store_file(storage, carpeta: str):
    """Sube un archivo del formulario público (imagen o PDF) y devuelve su URL."""
    if not storage or not getattr(storage, "filename", ""):
        return ""
    nombre = (storage.filename or "").lower()
    es_pdf = nombre.endswith(".pdf") or (getattr(storage, "mimetype", "") or "") == "application/pdf"
    try:
        return (upload_pdf(storage, carpeta) if es_pdf else
                (upload_image(storage, carpeta) or upload_file(storage, carpeta))) or ""
    except Exception:
        app.logger.exception("intake upload")
        return ""


def _intake_save_document(session_db, promoter, kind: str, front_url, back_url=None, extra: dict | None = None):
    """Guarda (o completa) un documento de identidad del tercero con lo que ya se subió.

    `front_url`/`back_url` son las URLs que devolvió `public_intake_upload`: si una cara no se ha
    subido, se deja la que hubiera (así actualizar solo el reverso no borra el anverso).
    """
    front_url = (front_url or "").strip()
    back_url = (back_url or "").strip()
    if not (front_url or back_url):
        return None
    doc = (session_db.query(PersonDocument)
           .filter(PersonDocument.owner_type == "PROMOTER", PersonDocument.owner_id == promoter.id,
                   PersonDocument.kind == kind)
           .order_by(PersonDocument.created_at.desc()).first())
    if doc is None:
        doc = PersonDocument(owner_type="PROMOTER", owner_id=promoter.id, kind=kind, sort_order=0)
        session_db.add(doc)
    if front_url:
        doc.front_url = front_url
    if back_url:
        doc.back_url = back_url
    for campo, valor in (extra or {}).items():
        if valor:
            setattr(doc, campo, valor)
    return doc


def _intake_unique_nick(session_db, base: str, exclude_id=None) -> str:
    """`Promoter.nick` es ÚNICO y aquí el nombre lo escribe gente de fuera: si ya está cogido se le
    añade un sufijo en vez de reventar la inserción."""
    base = (base or "Tercero").strip()[:120] or "Tercero"
    intento, n = base, 1
    while True:
        q = session_db.query(Promoter.id).filter(func.lower(Promoter.nick) == intento.lower())
        if exclude_id is not None:
            q = q.filter(Promoter.id != exclude_id)
        if q.first() is None:
            return intento
        n += 1
        sufijo = f" ({n})"
        intento = base[:120 - len(sufijo)] + sufijo


def _intake_by_token(session_db, token: str):
    return (session_db.query(ThirdPartyIntakeLink)
            .filter(ThirdPartyIntakeLink.public_token == (token or "").strip()).first())


