@app.post('/alta/<token>/identificar', endpoint='public_intake_identify')
def public_intake_identify(token):
    """Paso 1: ¿existe ya este CIF/DNI? Si existe, se avisa y se ofrece ACTUALIZAR sus datos."""
    session_db = db()
    try:
        link = _intake_by_token(session_db, token)
        if not link or (link.status or "") == "CANCELLED":
            return jsonify({"ok": False, "error": "Enlace no válido"}), 404
        raw = (request.form.get("tax_id") or "").strip()
        norm = _prl_norm_dni(raw)
        if not norm:
            return jsonify({"ok": False, "error": "Escribe el CIF o el DNI"}), 400
        encontrado = None
        for p in session_db.query(Promoter).filter(Promoter.tax_id.isnot(None)).all():
            if _prl_norm_dni(p.tax_id) == norm:
                encontrado = p
                break
        if encontrado is None:
            for pc in session_db.query(PromoterCompany).filter(PromoterCompany.tax_id.isnot(None)).all():
                if _prl_norm_dni(pc.tax_id) == norm:
                    encontrado = session_db.get(Promoter, pc.promoter_id)
                    break
        if encontrado is None:
            return jsonify({"ok": True, "found": False, "kind": _tax_id_kind(raw), "tax_id": raw})
        # Si el enlace ya es de ESA persona, ve sus datos completos; si no, enmascarados.
        propio = bool(link.promoter_id) and str(link.promoter_id) == str(encontrado.id)
        return jsonify({"ok": True, "found": True, "kind": _tax_id_kind(raw), "tax_id": raw,
                        "profile": _intake_promoter_payload(session_db, encontrado, masked=not propio)})
    finally:
        session_db.close()


INTAKE_UPLOAD_SLOTS = {
    "dni_front": "documents", "dni_back": "documents",
    "passport": "documents", "license_front": "documents", "license_back": "documents",
    "bank_cert": "documents", "photo": "providers",
}


@app.post('/alta/<token>/subir', endpoint='public_intake_upload')
def public_intake_upload(token):
    """Sube UN archivo del formulario (cada hueco por su cuenta, con su barra de progreso).

    Devuelve la URL, que el formulario guarda en un oculto: así el envío final es ligero y en el
    móvil se ve subir cada documento en vez de esperar a un POST enorme al final. Del certificado
    bancario se intenta LEER el IBAN para que la persona lo confirme.
    """
    session_db = db()
    try:
        link = _intake_by_token(session_db, token)
        if not link or (link.status or "") == "CANCELLED":
            return jsonify({"ok": False, "error": "Enlace no válido"}), 404
        slot = (request.form.get("slot") or "").strip().lower()
        if slot not in INTAKE_UPLOAD_SLOTS:
            return jsonify({"ok": False, "error": "Hueco no válido"}), 400
        f = request.files.get("file")
        if not f or not f.filename:
            return jsonify({"ok": False, "error": "Falta el archivo"}), 400
        # Formato: imágenes siempre; PDF solo donde tiene sentido (certificado bancario).
        nombre = (f.filename or "").lower()
        ext = ("." + nombre.rsplit(".", 1)[-1]) if "." in nombre else ""
        admitidas = {".jpg", ".jpeg", ".png", ".webp", ".heic", ".heif"} | ({".pdf"} if slot == "bank_cert" else set())
        if ext not in admitidas:
            return jsonify({"ok": False, "error": ("Formato no admitido: manda una foto (JPG o PNG)"
                                                   + (" o un PDF" if slot == "bank_cert" else ""))}), 400
        iban = _detect_iban_in_text(_intake_file_text(f)) if slot == "bank_cert" else ""
        try:
            url = _intake_store_file(f, INTAKE_UPLOAD_SLOTS[slot])
        except StorageObjectTooLargeError as exc:
            return jsonify({"ok": False, "error": str(exc)}), 400
        if not url:
            # El formato ya está comprobado: si falla aquí es el almacenamiento, no la persona.
            return jsonify({"ok": False, "error": "No hemos podido guardar el archivo. "
                                                  "Inténtalo otra vez en un momento."}), 400
        return jsonify({"ok": True, "slot": slot, "file_url": url, "iban": iban,
                        "iban_pretty": _iban_pretty(iban), "detected": bool(iban),
                        "note": ("" if (iban or slot != "bank_cert")
                                 else "No hemos podido leer el IBAN del documento: escríbelo tú.")})
    except Exception:
        app.logger.exception("public_intake_upload")
        return jsonify({"ok": False, "error": "No se pudo subir el archivo"}), 500
    finally:
        session_db.close()


@app.get('/alta/<token>/og.jpg', endpoint='public_intake_og_image')
def public_intake_og_image(token):
    """Miniatura de la previsualización (WhatsApp/SMS): logo de la empresa o foto de la persona y,
    si no tiene, el logo de 33 Producciones. Servida desde nuestro dominio y a 1200×630."""
    session_db = db()
    try:
        link = _intake_by_token(session_db, token)
        if not link:
            abort(404)
        promoter = link.promoter or (session_db.get(Promoter, link.promoter_id) if link.promoter_id else None)
        src = _absolute_media_url((getattr(promoter, "logo_url", "") or "").strip()) or ""
    finally:
        session_db.close()
    # Sin foto ni logo (alta nueva): el símbolo de «sin foto», no el logo de 33 Producciones.
    if not src:
        src = "/static/img/placeholder_photo.png"
    data = _og_image_jpeg_bytes(src) or _og_image_jpeg_bytes("/static/img/placeholder_photo.png")
    if not data:
        return redirect(src)
    resp = send_file(BytesIO(data), mimetype="image/jpeg")
    resp.headers["Cache-Control"] = "public, max-age=3600"
    return resp


@app.post('/alta/<token>/guardar', endpoint='public_intake_submit')
def public_intake_submit(token):
    """Crea o actualiza el tercero con TODO lo que ha rellenado en los pasos."""
    session_db = db()
    try:
        link = _intake_by_token(session_db, token)
        if not link or (link.status or "") == "CANCELLED":
            abort(404)
        f = request.form
        if not _truthy(f.get("consent")):
            return jsonify({"ok": False, "error": "Hay que aceptar las condiciones de tratamiento de datos"}), 400
        raw_tax = (f.get("tax_id") or "").strip()
        if not raw_tax:
            return jsonify({"ok": False, "error": "Falta el CIF o el DNI"}), 400
        kind = (f.get("entity_kind") or _tax_id_kind(raw_tax) or "PARTICULAR").upper()
        es_empresa = kind == "EMPRESA"

        # ¿A quién actualizamos? El del enlace, el que diga el formulario o el que case por CIF/DNI.
        promoter = session_db.get(Promoter, link.promoter_id) if link.promoter_id else None
        if promoter is None:
            pid = to_uuid((f.get("promoter_id") or "").strip())
            promoter = session_db.get(Promoter, pid) if pid else None
        if promoter is None:
            norm = _prl_norm_dni(raw_tax)
            for p in session_db.query(Promoter).filter(Promoter.tax_id.isnot(None)).all():
                if _prl_norm_dni(p.tax_id) == norm:
                    promoter = p
                    break
        nombre = (f.get("company_name") if es_empresa else f.get("full_name")) or ""
        nombre = nombre.strip()
        nuevo = promoter is None
        if nuevo:
            if not nombre:
                return jsonify({"ok": False, "error": "Falta el nombre"}), 400
            promoter = Promoter(nick=_intake_unique_nick(session_db, nombre[:120]),
                               kind=("empresa" if es_empresa else None), tax_id=raw_tax)
            session_db.add(promoter)
            session_db.flush()
        promoter.tax_id = raw_tax
        if es_empresa:
            promoter.kind = "empresa"
            if nombre:
                promoter.nick = _intake_unique_nick(session_db, nombre[:120], promoter.id)
        elif nombre:
            partes = nombre.split()
            promoter.first_name = partes[0]
            promoter.last_name = " ".join(partes[1:]) or None
            if not (promoter.nick or "").strip():
                promoter.nick = _intake_unique_nick(session_db, nombre[:120], promoter.id)
        for attr, campo in (("contact_email", "email"), ("contact_phone", "phone")):
            valor = (f.get(campo) or "").strip()
            if valor:
                setattr(promoter, attr, valor)
        # Dirección fiscal EN PIEZAS (CP, municipio y provincia aparte: la contabilidad los exige).
        piezas_fiscal = _fiscal_form_values(f)
        _apply_fiscal_address(promoter, piezas_fiscal)
        if (f.get("fiscal_address") or "").strip() and not (promoter.address or "").strip():
            promoter.address = _fiscal_address_text(promoter) or (f.get("fiscal_address") or "").strip()

        # --- Cuenta bancaria + certificado de titularidad (ya subido en su paso) ---
        iban = _iban_clean(f.get("bank_account"))
        if iban:
            if not _iban_is_valid(iban):
                return jsonify({"ok": False, "error": "El IBAN no parece correcto: revísalo"}), 400
            promoter.bank_account = _iban_pretty(iban)
        cert_url = (f.get("bank_cert_url") or "").strip()
        if cert_url:
            doc = PersonComplianceDoc(
                owner_type="PROMOTER", owner_id=promoter.id, doc_type="CERT_BANK",
                file_url=cert_url, original_name="Certificado de titularidad bancaria",
                status="APPROVED", detected_meta=({"iban": _iban_pretty(iban)} if iban else {}),
            )
            session_db.add(doc)

        # --- Empresa: sociedad + personas de contacto / departamentos ---
        if es_empresa:
            company = (session_db.query(PromoterCompany)
                       .filter(PromoterCompany.promoter_id == promoter.id)
                       .order_by(PromoterCompany.created_at.asc()).first())
            if company is None:
                company = PromoterCompany(promoter_id=promoter.id,
                                          legal_name=(nombre or promoter.nick or "")[:200])
                session_db.add(company)
            company.tax_id = raw_tax
            _apply_fiscal_address(company, piezas_fiscal)
            nombres = f.getlist("contact_name")[:INTAKE_MAX_ROWS]
            funciones = f.getlist("contact_title")[:INTAKE_MAX_ROWS]
            correos = f.getlist("contact_email")[:INTAKE_MAX_ROWS]
            telefonos = f.getlist("contact_phone")[:INTAKE_MAX_ROWS]
            for i, nom in enumerate(nombres):
                nom = (nom or "").strip()
                if not nom:
                    continue
                partes = nom.split()
                titulo = (funciones[i] if i < len(funciones) else "").strip() or "Contacto"
                correo = (correos[i] if i < len(correos) else "").strip()
                tel = (telefonos[i] if i < len(telefonos) else "").strip()
                # No duplicar: se busca por nombre + función.
                existente = None
                for c in (session_db.query(PromoterContact)
                          .filter(PromoterContact.promoter_id == promoter.id).all()):
                    actual = " ".join([x for x in [(c.first_name or ""), (c.last_name or "")] if x]).strip()
                    if _norm_text_key(actual) == _norm_text_key(nom):
                        existente = c
                        break
                if existente is None:
                    existente = PromoterContact(promoter_id=promoter.id, title=titulo[:120],
                                                first_name=partes[0], last_name=" ".join(partes[1:]) or None)
                    session_db.add(existente)
                else:
                    existente.title = titulo[:120]
                if correo:
                    existente.email = correo
                if tel:
                    existente.phone = tel

        # --- Particular: documentos, tarjetas de fidelización y datos de viaje ---
        if not es_empresa:
            _intake_save_document(session_db, promoter, "DNI",
                                  f.get("dni_front_url"), f.get("dni_back_url"),
                                  extra={"full_name": nombre or None, "doc_number": raw_tax})
            _intake_save_document(session_db, promoter, "PASSPORT",
                                  f.get("passport_url"), None,
                                  extra={"full_name": nombre or None})
            if _truthy(f.get("has_license")):
                _intake_save_document(session_db, promoter, "LICENSE",
                                      f.get("license_front_url"), f.get("license_back_url"),
                                      extra={"full_name": nombre or None})
            marcas = f.getlist("loyalty_company")[:INTAKE_MAX_ROWS]
            numeros = f.getlist("loyalty_number")[:INTAKE_MAX_ROWS]
            for i, marca in enumerate(marcas):
                marca = (marca or "").strip()
                numero = (numeros[i] if i < len(numeros) else "").strip()
                if not (marca or numero):
                    continue
                ya = None
                for d in (session_db.query(PersonDocument)
                          .filter(PersonDocument.owner_type == "PROMOTER",
                                  PersonDocument.owner_id == promoter.id,
                                  PersonDocument.kind == "LOYALTY").all()):
                    if _norm_text_key(d.company or "") == _norm_text_key(marca):
                        ya = d
                        break
                if ya is None:
                    session_db.add(PersonDocument(owner_type="PROMOTER", owner_id=promoter.id,
                                                  kind="LOYALTY", company=marca[:120],
                                                  doc_number=numero[:60] or None, sort_order=i))
                elif numero:
                    ya.doc_number = numero[:60]
            for attr, campo in (("travel_departure_flight", "travel_departure_flight"),
                                ("travel_departure_train", "travel_departure_train")):
                valor = (f.get(campo) or "").strip()
                if valor:
                    setattr(promoter, attr, valor)

        # --- Foto o logo ---
        if (f.get("photo_url") or "").strip():
            promoter.logo_url = (f.get("photo_url") or "").strip()

        promoter.data_consent_at = _now_madrid()
        promoter.billing_updated_at = _now_madrid()
        link.promoter_id = promoter.id
        link.kind = "ALTA" if nuevo else "UPDATE"
        link.status = "DONE"
        link.submitted_at = _now_madrid()
        link.data = {
            "entity_kind": kind,
            "tax_id": raw_tax,
            "name": nombre,
            "email": (f.get("email") or "").strip(),
            "phone": (f.get("phone") or "").strip(),
            "created": bool(nuevo),
            "at": _now_madrid().isoformat(),
        }
        session_db.commit()
        return jsonify({"ok": True, "created": bool(nuevo), "name": _intake_person_label(promoter)})
    except Exception as exc:
        session_db.rollback()
        app.logger.exception("public_intake_submit")
        return jsonify({"ok": False, "error": f"No se pudieron guardar los datos: {exc}"}), 500
    finally:
        session_db.close()


@app.get('/factura/<token>', endpoint='public_bag_invoice_upload')
def public_bag_invoice_upload(token):
    """Petición de factura de una bolsa: MISMO proceso que la landing (/facturacion), pero con el
    logo de la empresa del grupo que corresponda arriba a la derecha, solo sus datos de facturación
    y confirmación de que la factura está emitida a ellos."""
    session_db = db()
    try:
        req = session_db.query(BagInvoiceRequest).filter(BagInvoiceRequest.public_token == token).first()
        if not req:
            abort(404)
        ctx = _bag_invoice_request_context(session_db, req)
        if not ctx["bag"] or not ctx["provider"]:
            abort(404)
        concert = ctx.get("concert")
        company = None
        if concert is not None:
            company = getattr(concert, "billing_company", None) or getattr(concert, "group_company", None)
        if company is None and ctx["bag"] is not None:
            company = getattr(ctx["bag"], "company", None)
        provider = ctx["provider"]
        # ¿YA HAY FACTURA SUBIDA en esta petición? No se empieza otra vez: se avisa y se ofrece
        # reemplazarla (y si ya está validada, que hable con administración).
        _previa = (session_db.query(SupplierInvoice)
                   .filter(SupplierInvoice.invoice_request_id == req.id,
                           SupplierInvoice.file_url != "")
                   .order_by(func.upper(func.coalesce(SupplierInvoice.status, "")).desc(),
                             SupplierInvoice.created_at.desc()).first())
        return render_template(
            "public_invoice_landing.html",
            inv_mode="REQUEST",
            company=company,
            companies=[company] if company else session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all(),
            cert_docs=INVOICE_CERT_DOCS,
            request_row=req,
            request_rows=ctx["rows"],
            provider=provider,
            provider_payload=_billing_profile_payload(session_db, provider),
            concert=concert,
            artist=ctx.get("artist"),
            venue=ctx.get("venue"),
            **_invoice_existing_block(_previa),
        )
    finally:
        session_db.close()


@app.post('/factura/<token>/subir', endpoint='public_bag_invoice_upload_post')
def public_bag_invoice_upload_post(token):
    """Sube la factura de UN concepto (o un documento adicional) desde el enlace público."""
    session_db = db()
    try:
        req = session_db.query(BagInvoiceRequest).filter(BagInvoiceRequest.public_token == token).first()
        if not req:
            return jsonify({"ok": False, "error": "Enlace no válido"}), 404
        provider = session_db.get(Promoter, req.provider_id)
        f = request.files.get("file")
        if not f or not f.filename:
            return jsonify({"ok": False, "error": "Falta el archivo"}), 400
        doc_type = (request.form.get("doc_type") or "").strip().upper()
        if doc_type:
            # Documentación adicional (alta, recibo de autónomos…): reutiliza el sistema de PRL.
            if doc_type not in PRL_DOC_LABELS or not provider:
                return jsonify({"ok": False, "error": "Tipo de documento no válido"}), 400
            concert = None
            if (session_db.get(WorkflowBag, req.bag_id).linked_type or "").upper() == "CONCERT":
                concert = session_db.get(Concert, session_db.get(WorkflowBag, req.bag_id).linked_id)
            doc, warning = _prl_store_upload(session_db, provider, doc_type, f, concert=concert, uploaded_via="PUBLIC")
            if not doc:
                return jsonify({"ok": False, "error": warning or "No se pudo guardar"}), 400
            session_db.commit()
            ctx = _bag_invoice_request_context(session_db, req)
            return jsonify({"ok": True, "warning": warning, "kind": "doc", "doc_type": doc_type,
                            "all_done": ctx["all_done"]})
        # Factura de UNO o VARIOS conceptos de la bolsa: el proveedor puede marcar varios y subir
        # una sola factura que los englobe. El importe se reparte a prorrata de lo previsto.
        allowed = {str(x) for x in (req.expense_ids or [])}
        raw_ids = request.form.getlist("expense_id") or []
        exp_ids = [to_uuid(x) for x in raw_ids if x and str(to_uuid(x) or "") in allowed]
        exp_ids = [x for x in exp_ids if x]
        if not exp_ids:
            return jsonify({"ok": False, "error": "Concepto no válido"}), 400
        expenses = [e for e in (session_db.get(BagExpense, x) for x in exp_ids) if e]
        if not expenses:
            return jsonify({"ok": False, "error": "Concepto no encontrado"}), 404
        filename = (f.filename or "factura").strip()
        is_pdf = filename.lower().endswith(".pdf") or (f.mimetype or "") == "application/pdf"
        url = upload_pdf(f, "invoices") if is_pdf else upload_file(f, "invoices")
        if not url:
            return jsonify({"ok": False, "error": "No se pudo guardar el archivo"}), 400
        inv_num = (request.form.get("invoice_number") or "").strip() or None
        total = _money_or_zero(request.form.get("amount_gross") or 0)
        previstos = [_money_or_zero(e.amount_gross) for e in expenses]
        suma_prev = sum(previstos, Decimal("0"))
        group_key = uuid.uuid4().hex
        for e, prev in zip(expenses, previstos):
            if total and suma_prev:
                trozo = (total * prev / suma_prev).quantize(Decimal("0.01"))
            elif total:
                trozo = (total / Decimal(len(expenses))).quantize(Decimal("0.01"))
            else:
                trozo = prev
            _bag_expense_invoice_apply(
                session_db, e, file_url=url, file_name=filename, file_mime=f.mimetype,
                invoice_number=inv_num, amount=trozo, group_key=group_key,
            )
        req.updated_at = datetime.utcnow()
        session_db.commit()
        ctx = _bag_invoice_request_context(session_db, req)
        if ctx["all_done"]:
            req.status = "DONE"
            session_db.commit()
        return jsonify({"ok": True, "kind": "invoice",
                        "expense_id": str(expenses[0].id),
                        "expense_ids": [str(e.id) for e in expenses],
                        "name": filename, "url": url, "all_done": ctx["all_done"]})
    except Exception:
        session_db.rollback()
        app.logger.exception("public_bag_invoice_upload_post")
        return jsonify({"ok": False, "error": "Error al subir el archivo"}), 500
    finally:
        session_db.close()


@app.post('/conciertos/<cid>/produccion/presupuesto', endpoint='concert_budget_item_create')
@admin_required
def concert_budget_item_create(cid):
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(cid))
        if not concert:
            abort(404)
        category = (request.form.get('category') or 'OTROS').strip().upper() or 'OTROS'
        concept = (request.form.get('concept') or '').strip()
        if not concept:
            flash('Indica al menos el concepto del presupuesto.', 'warning')
            return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
        # Mismo cálculo que los gastos de las simulaciones: importe UNITARIO × cantidad + IVA
        # (o exento). Si llega el bruto a mano, manda ese.
        unit = _sim_d(request.form.get('amount_net') or 0)
        qty = _sim_d(request.form.get('quantity') or 1)
        if qty <= 0:
            qty = Decimal('1')
        iva_exempt = _truthy(request.form.get('iva_exempt'))
        iva = Decimal('0') if iva_exempt else _sim_d(request.form.get('iva_pct') or 21)
        net = (unit * qty).quantize(Decimal('0.01'))
        gross_form = request.form.get('amount_gross')
        gross = (_money_or_zero(gross_form) if (gross_form or '').strip()
                 else (net * (Decimal('1') + iva / Decimal('100'))).quantize(Decimal('0.01')))
        item = ConcertBudgetItem(
            concert_id=concert.id,
            category=category,
            concept=concept,
            amount_net=net,
            amount_gross=gross,
            quantity=qty,
            iva_pct=iva,
            iva_exempt=iva_exempt,
            created_by_user_id=_safe_uuid(session.get('user_id')) if session.get('user_id') else None,
            created_by_nick=_email_to_nick(_current_user_email() or ''),
        )
        session_db.add(item)
        session_db.commit()
        flash('Partida añadida al presupuesto.', 'success')
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
    except Exception as exc:
        session_db.rollback()
        flash(f'Error guardando presupuesto: {exc}', 'danger')
        return redirect(url_for('concert_detail_view', cid=cid, tab='produccion'))
    finally:
        session_db.close()


CONCERT_BUDGET_CATEGORY_MAP = {
    "SONIDO_LUCES": "SONIDO_LUCES", "RIDER": "SONIDO_LUCES",
    "MUSICOS": "MUSICOS", "PERSONAL": "PERSONAL",
    "LOGISTICA": "TRANSPORTE", "TRANSPORTE": "TRANSPORTE",
    "ALOJAMIENTO": "HOTELES", "HOTELES": "HOTELES",
    "MARKETING": "MARKETING", "PROMOCION": "MARKETING",
}


@app.post('/conciertos/<cid>/produccion/presupuesto/cargar-plantilla', endpoint='concert_budget_load_template')
@admin_required
def concert_budget_load_template(cid):
    """Carga un presupuesto guardado del ARTISTA (ExpenseTemplate) como partidas del presupuesto
    del concierto (ConcertBudgetItem), igual que en los simuladores."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(cid))
        if not concert:
            abort(404)
        # Acepta VARIAS plantillas (del artista y/o del recinto), igual que la bolsa.
        ids = [x for x in request.form.getlist('expense_template_ids[]') if (x or '').strip()]
        single = (request.form.get('template_id') or '').strip()
        if single:
            ids.append(single)
        tpls = []
        for tid in ids:
            tpl = (session_db.query(ExpenseTemplate).options(selectinload(ExpenseTemplate.items))
                   .filter(ExpenseTemplate.id == to_uuid(tid)).first()) if to_uuid(tid) else None
            if tpl:
                tpls.append(tpl)
        if not tpls:
            flash('Elige al menos una plantilla de gastos.', 'warning')
            return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
        uid = _safe_uuid(session.get('user_id')) if session.get('user_id') else None
        nick = _email_to_nick(_current_user_email() or '')
        n = 0
        for tpl in tpls:
            for it in sorted(tpl.items or [], key=lambda x: x.sort_order or 0):
                cat = _bag_expense_display_cat((it.category or 'OTROS').upper())
                qty = _money_or_zero(getattr(it, 'quantity', 1) or 1)
                if qty <= 0:
                    qty = Decimal('1')
                unit = _money_or_zero(it.amount_net)
                iva_exempt = bool(getattr(it, 'iva_exempt', False))
                iva_pct = Decimal('0') if iva_exempt else _money_or_zero(getattr(it, 'iva_pct', 21))
                iva_rate = iva_pct / Decimal('100')
                divisor = (Decimal('1') + iva_rate) if (getattr(it, 'includes_iva', False) and iva_rate > 0) else Decimal('1')
                net = ((unit * qty) / divisor).quantize(Decimal('0.01'))
                gross = (net * (Decimal('1') + iva_rate)).quantize(Decimal('0.01'))
                session_db.add(ConcertBudgetItem(
                    concert_id=concert.id, category=cat, concept=(it.concept or 'Gasto'),
                    amount_net=net, amount_gross=gross, quantity=qty, iva_pct=iva_pct,
                    iva_exempt=iva_exempt, sort_order=n,
                    created_by_user_id=uid, created_by_nick=nick,
                ))
                n += 1
        session_db.commit()
        flash(f"Cargadas {n} partida{'s' if n != 1 else ''} de {', '.join(t.name or 'plantilla' for t in tpls)}.", 'success')
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo cargar el presupuesto: {exc}', 'danger')
        return redirect(safe_next_or(url_for('concert_detail_view', cid=cid, tab='produccion', ptab='presupuesto')))
    finally:
        session_db.close()


