    sent = _send_web_push(session.get("user_id"), "Prueba de notificación",
                          "Si ves esto, las notificaciones de la app funcionan ✅", url=url_for("home"))
    return jsonify({"ok": True, "enabled": push_enabled(), "sent": sent})


