@app.post("/fotos/album/<album_id>/delete", endpoint="photo_album_delete")
@admin_required
def photo_album_delete(album_id):
    payload = request.get_json(silent=True) or request.form
    mode = (payload.get("mode") or "keep").strip().lower()  # keep | with_photos
    session_db = db()
    try:
        album = session_db.get(PhotoAlbum, to_uuid(album_id))
        if not album:
            return jsonify({"ok": False, "error": "Álbum no encontrado."}), 404
        if mode == "with_photos":
            photo_ids = [it.photo_id for it in session_db.query(PhotoAlbumItem).filter(PhotoAlbumItem.album_id == album.id).all()]
            for pid in photo_ids:
                ph = session_db.get(Photo, pid)
                if ph:
                    session_db.delete(ph)
        # los items se borran en cascada al eliminar el álbum
        session_db.delete(album)
        session_db.commit()
        return jsonify({"ok": True})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


# ============================================================ aprobaciones
def _photo_count_label(photos):
    n_img = sum(1 for p in photos if (p.kind or "IMAGE").upper() != "VIDEO")
    n_vid = len(photos) - n_img
    parts = []
    if n_img:
        parts.append("%d fotografía%s" % (n_img, "" if n_img == 1 else "s"))
    if n_vid:
        parts.append("%d vídeo%s" % (n_vid, "" if n_vid == 1 else "s"))
    return " y ".join(parts) if parts else "0 elementos"


def _photo_owner_group_company_id(session_db, ot, owner):
    """Empresa del grupo (GroupCompany) que gestiona el concierto/actividad; su logo se usa en los
    correos de aprobación/supervisión. En conciertos = group_company_id; en acciones no hay empresa
    asociada -> None (se usa el logo por defecto)."""
    if owner and ot == "CONCERT":
        return getattr(owner, "group_company_id", None)
    return None


def _concert_poster_url(concert) -> str:
    """URL del cartel PRINCIPAL del concierto si hay cartelería subida (imagen no archivada;
    se prioriza la etiqueta que contenga «principal»/«cartel»/«vertical»). Vacío si no hay."""
    if not concert:
        return ""
    req = getattr(concert, "artwork_request", None)
    assets = [a for a in (getattr(req, "assets", None) or []) if not bool(getattr(a, "is_archived", False))]

    # ⚠️ Aquí hace falta una IMAGEN de verdad (es la cabecera de las invitaciones y de los enlaces):
    # un cartel en VÍDEO no vale, ni siquiera con su miniatura. De qué es cada cartel lo dice el
    # punto único `_artwork_kind_of`.
    images = [a for a in assets
              if _artwork_kind_of(a) == "IMAGE" and (getattr(a, "file_url", None) or "").strip()]
    if not images:
        return ""
    # 1) El marcado como principal manualmente. 2) Si solo hay uno, ese. 3) Fallback: el más reciente.
    for a in images:
        if bool(getattr(a, "is_primary", False)):
            return (getattr(a, "file_url", "") or "").strip()
    if len(images) == 1:
        return (getattr(images[0], "file_url", "") or "").strip()
    images.sort(key=lambda a: getattr(a, "created_at", None) or datetime.min, reverse=True)
    return (getattr(images[0], "file_url", "") or "").strip()


def _public_share_card(session_db, owner_type, owner, artist_id=None) -> dict:
    """Datos para la composición visual de las páginas públicas (enlaces de WhatsApp/SMS):
    tipo de actividad + icono, nombre del evento (o municipio), fecha y artista con foto.
    Si el concierto tiene cartel subido, la imagen (artist_photo) es el cartel principal."""
    card = {"activity_label": "", "activity_icon": "fa-calendar-day", "event_name": "",
            "city": "", "date_label": "", "artist_name": "", "artist_photo": ""}
    if not owner:
        return card
    if owner_type == "CONCERT":
        card["activity_label"] = _invitation_event_type_label(owner)
        card["activity_icon"] = _concert_activity_icon(owner)
        card["event_name"] = (getattr(owner, "festival_name", None) or "").strip()
        card["city"] = _concert_city(owner)
        d = getattr(owner, "date", None)
        card["date_label"] = d.strftime("%d/%m/%Y") if d else ""
    else:
        akey = (getattr(owner, "action_type", None) or "").strip().upper()
        card["activity_label"] = ACTION_TYPE_LABELS.get(akey, akey.replace("_", " ").title() or "Acción")
        card["activity_icon"] = ACTION_TYPE_ICONS.get(akey, "fa-bullhorn")
        card["event_name"] = (getattr(owner, "title", None) or "").strip()
        _snap = _json_loads_safe(getattr(owner, "location_snapshot", None), {}) or {}
        _venue = getattr(owner, "venue", None)
        card["city"] = (getattr(_venue, "municipality", None) or _snap.get("city") or "").strip()
        d = getattr(owner, "start_date", None)
        card["date_label"] = d.strftime("%d/%m/%Y") if d else ""
    art = session_db.get(Artist, artist_id) if artist_id else None
    if art:
        card["artist_name"] = art.name or ""
        card["artist_photo"] = getattr(art, "photo_url", "") or ""
    # Si hay cartel de concierto subido, se muestra el cartel principal en vez del avatar.
    if owner_type == "CONCERT":
        _poster = _concert_poster_url(owner)
        if _poster:
            card["artist_photo"] = _poster
    return card


def _public_share_og_image(session_db, concert, event_payload=None, card=None, logo=None) -> str:
    """URL de og:image para los enlaces públicos de un concierto: si hay imagen (cartel / foto del
    artista / logo), devuelve la versión PROCESADA servida por `public_concert_og_image` (JPEG
    1200×630 desde nuestro dominio: WhatsApp descarta imágenes grandes, sin content-type de imagen
    o sin dimensiones y la previsualización salía sin foto). Sin imagen, cadena vacía."""
    src = _public_share_og_source(session_db, concert, event_payload=event_payload, card=card, logo=logo)
    if not src:
        return ""
    _cid = getattr(concert, "id", None)
    if _cid is None:
        return src
    return _external_url_for("public_concert_og_image", cid=str(_cid))


def _public_share_og_source(session_db, concert, event_payload=None, card=None, logo=None) -> str:
    """Imagen ORIGEN de previsualización para enlaces públicos de un concierto/evento.
    Orden (SIEMPRE, sin depender de lo que llegue en card/event_payload): cartel principal del
    concierto → foto del artista principal → foto de CUALQUIER artista del evento → logo. Devuelve
    una URL ABSOLUTA (si no, WhatsApp/SMS no la previsualizan)."""
    ev = event_payload
    if ev is None:
        try:
            ev = _invitation_event_payload(session_db, concert) if concert else {}
        except Exception:
            ev = {}
    candidates = []
    # 1) Cartel principal (imagen) del concierto, recalculado directamente (no solo desde el payload).
    try:
        if concert is not None:
            candidates.append(_concert_poster_url(concert))
    except Exception:
        pass
    candidates.append((ev or {}).get("poster_url"))
    # 2) Foto del artista principal del concierto (directa) + la del card.
    try:
        _aid = getattr(concert, "artist_id", None)
        if _aid:
            _art = session_db.get(Artist, _aid)
            if _art:
                candidates.append(getattr(_art, "photo_url", "") or "")
    except Exception:
        pass
    if card:
        candidates.append(card.get("artist_photo"))
    # 3) Foto de cualquier artista del evento (festivales, co-artistas) + logo.
    for a in ((ev or {}).get("artists") or []):
        candidates.append(a.get("photo_url"))
    candidates.append(logo)
    for c in candidates:
        c = (c or "").strip()
        # El placeholder (silueta genérica) no aporta como previsualización: se salta para caer al logo.
        if c and "placeholder" not in c.lower():
            return _absolute_media_url(c)
    return ""


def _photo_approval_options(session_db, ot, owner):
    artists = []
    artist_ids = []
    primary_id = None
    if ot == "CONCERT":
        primary_id = getattr(owner, "artist_id", None)
        artist_ids = [primary_id] + [to_uuid(x) for x in (getattr(owner, "artist_ids", None) or [])]
    else:
        artist_ids = [to_uuid(x) for x in (getattr(owner, "artist_ids", None) or [])]
        primary_id = artist_ids[0] if artist_ids else None
    seen = set()
    for aid in artist_ids:
        if not aid or aid in seen:
            continue
        seen.add(aid)
        art = session_db.get(Artist, aid)
        if not art:
            continue
        members = [
            (" ".join(filter(None, [m.first_name, m.last_name])).strip())
            for m in session_db.query(ArtistPerson).filter(ArtistPerson.artist_id == art.id).all()
        ]
        artists.append({
            "id": str(art.id),
            "name": art.name,
            "photo_url": (getattr(art, "photo_url", None) or ""),
            "email": (getattr(art, "email", None) or ""),
            "is_primary": (aid == primary_id),
            "members": [m for m in members if m],
        })
    promoter = None
    if ot == "CONCERT" and getattr(owner, "promoter_id", None):
        pr = session_db.get(Promoter, owner.promoter_id)
        if pr:
            promoter = {
                "name": (pr.nick or "").strip() or "Promotor",
                "photo_url": (getattr(pr, "logo_url", None) or ""),
                "email": (getattr(pr, "contact_email", None) or ""),
            }
    companies = [
        {"id": str(c.id), "name": c.name, "logo_url": (c.logo_url or "")}
        for c in session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    ]
    default_company_id = str(owner.group_company_id) if (ot == "CONCERT" and getattr(owner, "group_company_id", None)) else ""
    show_responsible = (ot == "CONCERT" and (getattr(owner, "sale_type", "") or "") in ("GIRAS_COMPRADAS", "VENDIDO"))
    return {
        "artists": artists,
        "promoter": promoter,
        "companies": companies,
        "default_company_id": default_company_id,
        "show_responsible": show_responsible,
    }


