def _apply_photo_approval_state(session_db, photo, state, user_state):
    """Aplica un cambio MANUAL de estado de aprobación a un contenido: actualiza todas sus
    decisiones y recalcula el estado de cada aprobador (cierra o reabre su enlace). Si nunca
    tuvo solicitud, crea una mínima «cambio manual» para que quede registrado quién lo hizo."""
    rows = session_db.query(PhotoApproval).filter(PhotoApproval.photo_id == photo.id).all()
    if rows:
        now_dt = _now_madrid()
        touched_approvers = set()
        for ap in rows:
            ap.decision = state
            ap.decided_at = now_dt if state != "PENDING" else None
            touched_approvers.add(ap.approver_id)
        for aid in touched_approvers:
            n_pend = (
                session_db.query(func.count(PhotoApproval.id))
                .filter(PhotoApproval.approver_id == aid, PhotoApproval.decision == "PENDING")
                .scalar() or 0
            )
            approver = session_db.get(PhotoApprover, aid)
            if approver:
                approver.status = "PENDING" if n_pend else "SUBMITTED"
                approver.submitted_at = None if n_pend else _now_madrid()
    else:
        # Sin ninguna solicitud previa: se crea una mínima «cambio manual» para que el estado quede
        # registrado (también cuando se pone PENDIENTE: antes esta rama solo entraba con aprobado o
        # rechazado, así que «volver a pendiente» decía OK y no cambiaba nada).
        req = PhotoApprovalRequest(
            owner_type=photo.owner_type, owner_id=photo.owner_id,
            photo_ids=[str(photo.id)], status="ACTIVE",
            requested_by_user_id=to_uuid(user_state.get("user_id")),
            requested_by_nick=((user_state.get("nick") or "").strip() or "Equipo") + " (cambio manual)",
        )
        session_db.add(req)
        session_db.flush()
        pendiente = state == "PENDING"
        approver = PhotoApprover(
            request_id=req.id, token=uuid.uuid4().hex, kind="CUSTOM",
            name=((user_state.get("nick") or "").strip() or "Equipo") + " (manual)",
            status=("PENDING" if pendiente else "SUBMITTED"),
            submitted_at=(None if pendiente else _now_madrid()),
        )
        session_db.add(approver)
        session_db.flush()
        session_db.add(PhotoApproval(approver_id=approver.id, photo_id=photo.id, decision=state,
                                     decided_at=(None if pendiente else _now_madrid())))


@app.post("/fotos/photo/<photo_id>/estado-aprobacion", endpoint="foto_set_approval_state")
@admin_required
def foto_set_approval_state(photo_id):
    """Cambio manual del estado de aprobación de UN contenido (menú «Estado» de la foto)."""
    pid = to_uuid(photo_id)
    state = ((request.get_json(silent=True) or {}).get("state") or "").strip().upper()
    if not pid or state not in ("APPROVED", "REJECTED", "PENDING"):
        return jsonify({"ok": False, "error": "Estado no válido."}), 400
    user_state = _current_user_state()
    session_db = db()
    try:
        photo = session_db.get(Photo, pid)
        if not photo:
            return jsonify({"ok": False, "error": "Contenido no encontrado."}), 404
        _apply_photo_approval_state(session_db, photo, state, user_state)
        session_db.commit()
        appr_map = _photo_approval_map(session_db, [photo.id])
        promo_map = _photo_promoter_map(session_db, [photo])
        return jsonify({"ok": True, "photo": _photo_payload(photo, promo_map.get(photo.photographer_promoter_id), appr_map.get(str(photo.id)))})
    except Exception as e:
        session_db.rollback()
        app.logger.exception("foto_set_approval_state")
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


@app.post("/fotos/<owner_type>/<owner_id>/aprobacion-estado-bulk", endpoint="fotos_bulk_approval_state")
@admin_required
def fotos_bulk_approval_state(owner_type, owner_id):
    """Cambio manual EN GRUPO del estado de aprobación (menú ⋮ de la selección múltiple):
    marcar la selección como aprobada, rechazada o volver a pendiente."""
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    state = (payload.get("state") or "").strip().upper()
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or []) if to_uuid(x)]
    if not ids or state not in ("APPROVED", "REJECTED", "PENDING"):
        return jsonify({"ok": False, "error": "Estado o selección no válidos."}), 400
    user_state = _current_user_state()
    session_db = db()
    try:
        photos = session_db.query(Photo).filter(Photo.id.in_(ids)).all()
        for photo in photos:
            _apply_photo_approval_state(session_db, photo, state, user_state)
        session_db.commit()
        return jsonify({"ok": True, "changed": len(photos), "state": state})
    except Exception as e:
        session_db.rollback()
        app.logger.exception("fotos_bulk_approval_state")
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


def _photo_event_header_email_html(card, owner_title):
    """Cabecera-galleta del EVENTO para correos de fotos/vídeos (mismo estilo que el resto de
    correos de la app): foto del artista/cartel en círculo + nombre + Evento/Ciudad/Fecha."""
    def esc(x):
        return escape(str(x or ""))
    meta_rows = [(k, v) for k, v in [
        ("Actividad", card.get("activity_label")),
        ("Evento", card.get("event_name")),
        ("Ciudad", card.get("city")),
        ("Fecha", card.get("date_label")),
    ] if v]
    meta_html = "".join(f'<div style="font-size:13px;color:#444"><b>{esc(k)}:</b> {esc(v)}</div>' for k, v in meta_rows)
    photo = _absolute_media_url(card.get("artist_photo") or "") if card.get("artist_photo") else ""
    photo_cell = (
        f'<td style="vertical-align:middle;padding-right:12px">'
        f'<img src="{esc(photo)}" width="52" height="52" alt="" style="width:52px;height:52px;border-radius:50%;object-fit:cover;display:block;border:1px solid #eceef1"></td>'
    ) if photo else ''
    return (
        '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;background:#f6f7f9;border:1px solid #eceef1;border-radius:14px;margin:8px 0 18px">'
        '<tr><td style="padding:14px 16px"><table role="presentation" cellpadding="0" cellspacing="0"><tr>'
        f'{photo_cell}'
        f'<td style="vertical-align:top"><div style="font-size:17px;font-weight:700;color:#111">{esc(card.get("artist_name") or owner_title or "Evento")}</div>{meta_html}</td>'
        '</tr></table></td></tr></table>'
    )


def _photo_approval_email_html(session_db, request_row, approver, photos, owner_title):
    """Correo de solicitud de aprobación: logo de la empresa a la derecha, cabecera del evento,
    botón «Supervisar contenidos» al PRINCIPIO y al FINAL, y el listado de contenidos con
    miniatura — cada contenido enlaza a su punto exacto dentro de la página de supervisión."""
    company = session_db.get(GroupCompany, request_row.brand_company_id) if request_row.brand_company_id else None
    logo = (company.logo_url if company and company.logo_url else _external_url_for("static", filename="img/logo.png"))
    url_pub = _external_url_for("public_photo_approval", token=approver.token)
    who = (request_row.requested_by_nick or "El equipo").strip()
    count = _photo_count_label(photos)
    owner, _aid, _tt = _photo_resolve_owner(session_db, request_row.owner_type, request_row.owner_id)
    card = _public_share_card(session_db, request_row.owner_type, owner, artist_id=_aid)
    header_html = _photo_event_header_email_html(card, owner_title)
    btn = ('<p style="margin:16px 0"><a href="%s" style="background:#E33D48;color:#fff;padding:11px 22px;'
           'border-radius:10px;text-decoration:none;font-weight:700;display:inline-block">Supervisar contenidos</a></p>' % url_pub)
    items = []
    for p in photos:
        thumb_url = _absolute_media_url(p.file_url or "")
        anchor = url_pub + "#c-" + str(p.id)
        is_video = (p.kind or "").upper() == "VIDEO"
        if is_video:
            media = ('<span style="display:inline-block;width:64px;height:64px;border-radius:8px;background:#111;color:#fff;'
                     'text-align:center;line-height:64px;font-size:22px">&#9654;</span>')
        else:
            media = f'<img src="{escape(thumb_url)}" width="64" height="64" alt="" style="width:64px;height:64px;border-radius:8px;object-fit:cover;display:block">'
        label = escape(p.title or p.file_name or ("Vídeo" if is_video else "Foto"))
        kind_txt = "Vídeo" if is_video else "Foto"
        items.append(
            '<tr>'
            f'<td style="padding:6px 10px 6px 0;width:64px"><a href="{escape(anchor)}" style="text-decoration:none">{media}</a></td>'
            f'<td style="vertical-align:middle"><a href="{escape(anchor)}" style="color:#111;text-decoration:none"><b>{label}</b>'
            f'<div style="font-size:12px;color:#888">{kind_txt} · pendiente de aprobar &rarr; revisar</div></a></td>'
            '</tr>'
        )
    items_html = ('<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%%;margin:6px 0 2px">%s</table>' % "".join(items)) if items else ""
    return (
        '<div style="font-family:Arial,sans-serif;color:#111;line-height:1.45;max-width:640px;margin:auto">'
        '<div style="text-align:right;margin-bottom:6px"><img src="%s" alt="" style="max-height:58px;max-width:200px"></div>' % logo
        + '<p><b>%s</b> solicita aprobación de los siguientes contenidos (%s):</p>' % (escape(who), escape(count))
        + header_html
        + btn
        + items_html
        + btn
        + '<p style="color:#888;font-size:12px;margin-top:14px">Si el botón no funciona, copia este enlace: %s</p>' % url_pub
        + '</div>'
    )


@app.post("/fotos/<owner_type>/<owner_id>/approval/create", endpoint="fotos_approval_create")
@admin_required
def fotos_approval_create(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    photo_ids = [to_uuid(x) for x in (payload.get("photo_ids") or []) if to_uuid(x)]
    approvers_in = payload.get("approvers") or []
    supervision_emails = [(e or "").strip() for e in (payload.get("supervision_emails") or []) if (e or "").strip()]
    if not photo_ids:
        return jsonify({"ok": False, "error": "Sin fotos seleccionadas."}), 400
    if not approvers_in and not supervision_emails:
        return jsonify({"ok": False, "error": "Selecciona a quién pedir aprobación o indica un correo de supervisión."}), 400
    send_email = _truthy(payload.get("send_email"))
    message = (payload.get("message") or "").strip() or None
    state = _current_user_state()

    session_db = db()
    try:
        owner, _artist_id, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        photos = session_db.query(Photo).filter(Photo.id.in_(photo_ids)).all()
        # Logo del correo = empresa del grupo que gestiona el concierto/actividad (automático).
        brand_company_id = _photo_owner_group_company_id(session_db, ot, owner)

        result = {"ok": True, "emailed": 0, "approvers": [], "supervision_url": "", "supervision_emailed": 0}

        # Los correos de SUPERVISIÓN funcionan IGUAL que los de aprobación (mismo correo con la
        # cabecera del evento y mismo enlace de supervisión con pulgares): se convierten en
        # aprobadores más. Antes mandaban un enlace de solo-descarga, que confundía.
        for e_mail in supervision_emails:
            approvers_in.append({"kind": "CUSTOM", "name": e_mail.split("@")[0], "email": e_mail, "_force_email": True})

        if approvers_in:
            req = PhotoApprovalRequest(
                owner_type=ot, owner_id=owner.id, brand_company_id=brand_company_id,
                photo_ids=[str(x) for x in photo_ids], message=message, status="ACTIVE",
                requested_by_user_id=to_uuid(state.get("user_id")),
                requested_by_nick=(state.get("nick") or "").strip() or None,
                requested_by_photo_url=(state.get("photo_url") or "").strip() or None,
            )
            session_db.add(req)
            session_db.flush()
            for a in approvers_in:
                name = (a.get("name") or "").strip()
                if not name:
                    continue
                approver = PhotoApprover(
                    request_id=req.id, token=uuid.uuid4().hex,
                    kind=(a.get("kind") or "CUSTOM").strip().upper(),
                    name=name, role=(a.get("role") or "").strip() or None,
                    email=(a.get("email") or "").strip() or None,
                    photo_url=(a.get("photo_url") or "").strip() or None,
                    artist_id=to_uuid(a.get("artist_id")),
                )
                session_db.add(approver)
                session_db.flush()
                for pid in photo_ids:
                    session_db.add(PhotoApproval(approver_id=approver.id, photo_id=pid, decision="PENDING"))
                emailed_this = False
                if (send_email or a.get("_force_email")) and approver.email:
                    ok, _err = _send_optional_email(
                        approver.email,
                        "Supervisión de contenidos — %s" % (owner_title or "Materiales"),
                        _photo_approval_email_html(session_db, req, approver, photos, owner_title),
                        reply_to=_current_user_email(),
                    )
                    if ok:
                        emailed_this = True
                        result["emailed"] += 1
                        if a.get("_force_email"):
                            result["supervision_emailed"] += 1
                result["approvers"].append({
                    "name": name,
                    "email": approver.email or "",
                    "url": _external_url_for("public_photo_approval", token=approver.token),
                    "emailed": emailed_this,
                })

        session_db.commit()
        return jsonify(result)
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


@app.route("/aprobacion-fotos/<token>", methods=["GET", "POST"], endpoint="public_photo_approval")
def photo_approval_public(token):
    session_db = db()
    try:
        approver = session_db.query(PhotoApprover).filter(PhotoApprover.token == token).first()
        if not approver:
            abort(404)
        req = session_db.get(PhotoApprovalRequest, approver.request_id)
        if not req:
            abort(404)
        approvals = {
            ap.photo_id: ap
            for ap in session_db.query(PhotoApproval).filter(PhotoApproval.approver_id == approver.id).all()
        }
        photos = (
            session_db.query(Photo)
            .filter(Photo.id.in_(list(approvals.keys())))
            .order_by(Photo.sort_order.asc(), Photo.created_at.asc())
            .all()
        ) if approvals else []
        owner, _artist_id, owner_title = _photo_resolve_owner(session_db, req.owner_type, req.owner_id)
        company = session_db.get(GroupCompany, req.brand_company_id) if req.brand_company_id else None
        logo = (company.logo_url if company and company.logo_url else url_for("static", filename="img/logo.png"))

        if request.method == "POST":
            for p in photos:
                dec = (request.form.get("decision_" + str(p.id)) or "").strip().upper()
                note = (request.form.get("note_" + str(p.id)) or "").strip()
                ap = approvals.get(p.id)
                if ap and dec in ("APPROVED", "REJECTED"):
                    ap.decision = dec
                    ap.decided_at = _now_madrid()
                if note:
                    session_db.add(PhotoNote(
                        photo_id=p.id, body=note, source="APPROVAL",
                        created_by_nick=approver.name,
                        created_by_photo_url=approver.photo_url,
                    ))
            approver.status = "SUBMITTED"
            approver.submitted_at = _now_madrid()
            session_db.commit()
            approved_photos = [p for p in photos if approvals.get(p.id) and approvals[p.id].decision == "APPROVED"]
            return render_template(
                "public_photo_approval.html", done=True, logo=logo,
                approved_photos=approved_photos, owner_title=owner_title, approver=approver,
            )

        photo_rows = []
        for p in photos:
            ap = approvals.get(p.id)
            photo_rows.append({
                "id": str(p.id), "title": p.title or p.file_name or "", "file_url": p.file_url,
                "is_video": (p.kind or "IMAGE").upper() == "VIDEO",
                "decision": (ap.decision if ap else "PENDING"),
            })
        counts = _photo_approval_counts_for(photo_rows)
        card = _public_share_card(session_db, req.owner_type, owner, artist_id=_artist_id)
        # El enlace deja de estar activo cuando no queda nada pendiente; al volver a entrar
        # solo se ve (y se navega) el contenido pendiente de aprobar.
        no_pending = not any(r["decision"] == "PENDING" for r in photo_rows)
        return render_template(
            "public_photo_approval.html", done=no_pending, logo=logo,
            photos=photo_rows, owner_title=owner_title, approver=approver, req=req,
            requested_by=(req.requested_by_nick or "El equipo"), requested_by_photo=(req.requested_by_photo_url or ""),
            count_label=_photo_count_label(photos), card=card, counts=counts,
            decide_url=url_for("public_photo_approval_decide", token=approver.token),
        )
    finally:
        session_db.close()


def _photo_approval_counts_for(rows):
    """Recuentos por tipo y decisión para la página de supervisión (y sus respuestas AJAX)."""
    out = {"photos": {"pending": 0, "approved": 0, "rejected": 0},
           "videos": {"pending": 0, "approved": 0, "rejected": 0}}
    for r in rows:
        bucket = out["videos"] if r.get("is_video") else out["photos"]
        d = (r.get("decision") or "PENDING").upper()
        if d == "APPROVED":
            bucket["approved"] += 1
        elif d == "REJECTED":
            bucket["rejected"] += 1
        else:
            bucket["pending"] += 1
    return out


@app.post("/aprobacion-fotos/<token>/decidir", endpoint="public_photo_approval_decide")
def photo_approval_public_decide(token):
    """Decisión EN VIVO de un contenido desde la página de supervisión (pulgares del popup):
    guarda la aprobación/rechazo, recalcula recuentos y cierra la solicitud del aprobador
    cuando ya no le queda nada pendiente."""
    payload = request.get_json(silent=True) or {}
    photo_id = to_uuid(payload.get("photo_id"))
    decision = (payload.get("decision") or "").strip().upper()
    note = (payload.get("note") or "").strip()
    if not photo_id or decision not in ("APPROVED", "REJECTED"):
        return jsonify({"ok": False, "error": "Decisión no válida."}), 400
    session_db = db()
    try:
        approver = session_db.query(PhotoApprover).filter(PhotoApprover.token == token).first()
        if not approver:
            return jsonify({"ok": False, "error": "Enlace no válido."}), 404
        ap = (
            session_db.query(PhotoApproval)
            .filter(PhotoApproval.approver_id == approver.id, PhotoApproval.photo_id == photo_id)
            .first()
        )
        if not ap:
            return jsonify({"ok": False, "error": "Contenido no encontrado."}), 404
        # Se puede CAMBIAR una decisión ya tomada (antes el pulgar no respondía si ya estaba votada).
        ap.decision = decision
        ap.decided_at = _now_madrid()
        if note:
            session_db.add(PhotoNote(
                photo_id=photo_id, body=note, source="APPROVAL",
                created_by_nick=approver.name,
                created_by_photo_url=approver.photo_url,
            ))
        rows = (
            session_db.query(PhotoApproval, Photo.kind)
            .join(Photo, Photo.id == PhotoApproval.photo_id)
            .filter(PhotoApproval.approver_id == approver.id)
            .all()
        )
        payload_rows = [{"is_video": (k or "IMAGE").upper() == "VIDEO", "decision": a.decision} for a, k in rows]
        counts = _photo_approval_counts_for(payload_rows)
        pending_left = counts["photos"]["pending"] + counts["videos"]["pending"]
        if pending_left == 0:
            approver.status = "SUBMITTED"
            approver.submitted_at = _now_madrid()
        else:
            approver.status = "PENDING"
            approver.submitted_at = None
        session_db.commit()
        return jsonify({"ok": True, "decision": decision, "pending": pending_left, "counts": counts})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


# ====================================================== descargar / compartir
def _photo_safe_filename(title, fallback="foto"):
    base = (title or fallback).strip() or fallback
    return re.sub(r"[^\w\-. áéíóúñÁÉÍÓÚÑ]", "_", base).strip() or fallback


def _photo_download_bytes(p, fmt):
    """Devuelve (bytes, mimetype, filename) de una foto, opcionalmente convertida a JPG o PNG."""
    content, ctype = _download_remote_content(p.file_url)
    title = _photo_safe_filename(p.title or p.file_name)
    is_image = (p.kind or "IMAGE").upper() != "VIDEO"
    if fmt in ("jpg", "png") and is_image:
        try:
            img = PILImage.open(BytesIO(content))
            img = ImageOps.exif_transpose(img)
            out = BytesIO()
            if fmt == "jpg":
                if img.mode not in ("RGB", "L"):
                    img = img.convert("RGB")
                img.save(out, format="JPEG", quality=90)
                return out.getvalue(), "image/jpeg", title + ".jpg"
            else:  # png
                if img.mode not in ("RGB", "RGBA", "L", "LA", "P"):
                    img = img.convert("RGBA")
                img.save(out, format="PNG")
                return out.getvalue(), "image/png", title + ".png"
        except Exception:
            pass
    ext = os.path.splitext(p.file_name or "")[1] or ".bin"
    return content, (ctype or "application/octet-stream"), title + ext


def _photos_zip_bytes(photos, fmt, label):
    buf = BytesIO()
    used = set()
    with zipfile.ZipFile(buf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for idx, p in enumerate(photos, start=1):
            try:
                data, _ct, fname = _photo_download_bytes(p, fmt)
            except Exception:
                continue
            member = _safe_zip_member_name(fname, used, "foto_%d" % idx)
            zf.writestr(member, data)
    root = ("fotografías_" + _photo_safe_filename(label, "galeria")).replace("/", "-")
    return buf.getvalue(), root + ".zip"


@app.get("/fotos/photo/<photo_id>/download", endpoint="foto_download")
@admin_required
def foto_download(photo_id):
    fmt = (request.args.get("fmt") or "original").strip().lower()
    session_db = db()
    try:
        p = session_db.get(Photo, to_uuid(photo_id))
        if not p:
            abort(404)
        data, mimetype, fname = _photo_download_bytes(p, fmt)
        return send_file(BytesIO(data), mimetype=mimetype, as_attachment=True, download_name=fname)
    finally:
        session_db.close()


@app.post("/fotos/<owner_type>/<owner_id>/zip", endpoint="fotos_zip")
@admin_required
def fotos_zip(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or []) if to_uuid(x)]
    fmt = (payload.get("fmt") or "original").strip().lower()
    session_db = db()
    try:
        owner, _aid, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        photos = session_db.query(Photo).filter(Photo.id.in_(ids)).all() if ids else []
        if not photos:
            return jsonify({"ok": False, "error": "Sin fotos."}), 400
        data, fname = _photos_zip_bytes(photos, fmt, owner_title)
        return send_file(BytesIO(data), mimetype="application/zip", as_attachment=True, download_name=fname)
    finally:
        session_db.close()


def _photo_share_urls(token):
    return {
        "public_url": _external_url_for("public_photo_share", token=token),
        "zip_url": _external_url_for("public_photo_share_zip", token=token),
    }


def _create_photo_share(session_db, ot, owner, photo_ids, brand_company_id, title, state):
    share = PhotoShare(
        owner_type=ot, owner_id=owner.id, token=uuid.uuid4().hex,
        photo_ids=[str(x) for x in photo_ids], brand_company_id=brand_company_id, title=title,
        created_by_user_id=to_uuid(state.get("user_id")),
        created_by_nick=(state.get("nick") or "").strip() or None,
    )
    session_db.add(share)
    session_db.flush()
    return share


@app.post("/fotos/<owner_type>/<owner_id>/share/create", endpoint="fotos_share_create")
@admin_required
def fotos_share_create(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or []) if to_uuid(x)]
    if not ids:
        return jsonify({"ok": False, "error": "Sin fotos."}), 400
    state = _current_user_state()
    session_db = db()
    try:
        owner, artist_id, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        artist = session_db.get(Artist, artist_id) if artist_id else None
        share = _create_photo_share(session_db, ot, owner, ids, _photo_owner_group_company_id(session_db, ot, owner), owner_title, state)
        session_db.commit()
        urls = _photo_share_urls(share.token)
        # Mensaje para WhatsApp/SMS
        artist_name = (artist.name if artist else "")
        msg = "Te comparto estos materiales" + (' de "' + artist_name + '"' if artist_name else "") + (' de "' + owner_title + '"' if owner_title else "") + ": " + urls["public_url"]
        urls["ok"] = True
        urls["message"] = msg
        urls["single"] = (len(ids) == 1)
        return jsonify(urls)
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


@app.get("/fotos/<owner_type>/<owner_id>/emails", endpoint="api_fotos_owner_emails")
@admin_required
def api_fotos_owner_emails(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    session_db = db()
    try:
        owner, artist_id, _t = _photo_resolve_owner(session_db, ot, owner_id)
        out = []
        seen = set()
        def _add(email, label):
            e = (email or "").strip()
            if e and e.lower() not in seen:
                seen.add(e.lower()); out.append({"email": e, "label": label})
        artist = session_db.get(Artist, artist_id) if artist_id else None
        if artist:
            _add(getattr(artist, "email", None), artist.name)
            for ae in session_db.query(ArtistEmail).filter(ArtistEmail.artist_id == artist.id).all():
                _add(getattr(ae, "email", None), getattr(ae, "label", None) or artist.name)
        if ot == "CONCERT" and getattr(owner, "promoter_id", None):
            pr = session_db.get(Promoter, owner.promoter_id)
            if pr:
                _add(getattr(pr, "contact_email", None), (pr.nick or "Promotor"))
        return jsonify({"ok": True, "emails": out})
    finally:
        session_db.close()


def _photo_share_email_html(session_db, share, photos, owner_title, note):
    """Correo de envío de materiales con el estilo de las comunicaciones de la app (como
    invitaciones): logo de la empresa a la derecha, «Hola,» + nota, cabecera del evento en
    galleta, botón principal para VER Y DESCARGAR, listado con miniaturas y botón ZIP."""
    company = session_db.get(GroupCompany, share.brand_company_id) if share.brand_company_id else None
    logo = (company.logo_url if company and company.logo_url else _external_url_for("static", filename="img/logo.png"))
    urls = _photo_share_urls(share.token)
    owner, _aid, _tt = _photo_resolve_owner(session_db, share.owner_type, share.owner_id)
    card = _public_share_card(session_db, share.owner_type, owner, artist_id=_aid)
    header_html = _photo_event_header_email_html(card, owner_title)
    intro = '<p>Hola,</p>'
    if note:
        intro += "".join(f'<p>{escape(line)}</p>' for line in note.splitlines() if line.strip())
    else:
        intro += '<p>aquí tienes los materiales. Puedes verlos en grande y descargarlos, todos o uno a uno.</p>'
    main_btn = ('<p style="margin:14px 0"><a href="%s" style="background:#e83b4b;color:#fff;padding:11px 22px;'
                'border-radius:10px;text-decoration:none;font-weight:700;display:inline-block">Ver y descargar los contenidos</a></p>'
                % urls["public_url"])
    rows = ""
    for p in photos:
        is_video = (p.kind or "IMAGE").upper() == "VIDEO"
        dl = _external_url_for("public_photo_share_item", token=share.token, photo_id=str(p.id))
        if is_video:
            media = ('<span style="display:inline-block;width:64px;height:64px;border-radius:8px;background:#111;color:#fff;'
                     'text-align:center;line-height:64px;font-size:22px">&#9654;</span>')
        else:
            media = '<img src="%s" style="width:64px;height:64px;object-fit:cover;border-radius:8px;display:block">' % escape(_absolute_media_url(p.file_url or ""))
        rows += ('<tr><td style="padding:6px 10px 6px 0;width:64px">%s</td>'
                 '<td style="padding:6px;font-size:14px;vertical-align:middle"><b>%s</b><div style="font-size:12px;color:#888">%s</div></td>'
                 '<td style="padding:6px;vertical-align:middle"><a href="%s" style="color:#007CA2">&#11015; Descargar</a></td></tr>'
                 ) % (media, escape(p.title or p.file_name or ""), ("Vídeo" if is_video else "Foto"), dl)
    return (
        '<div style="font-family:Arial,sans-serif;color:#111;line-height:1.45;max-width:640px;margin:auto">'
        '<div style="text-align:right;margin-bottom:6px"><img src="%s" alt="" style="max-height:58px;max-width:200px"></div>' % logo
        + intro
        + header_html
        + '<h2 style="text-align:center;margin:6px 0 10px">Envío de materiales</h2>'
        + main_btn
        + '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse">' + rows + '</table>'
        + '<p style="margin-top:18px"><a href="%s" style="background:#007CA2;color:#fff;padding:10px 18px;border-radius:10px;text-decoration:none;font-weight:700;display:inline-block">Descargar todo (ZIP)</a></p>' % urls["zip_url"]
        + '<p style="color:#888;font-size:12px;margin-top:14px">Si los botones no funcionan, copia este enlace: %s</p>' % urls["public_url"]
        + '</div>'
    )


@app.post("/fotos/<owner_type>/<owner_id>/share/email/preview", endpoint="fotos_share_email_preview")
@admin_required
def fotos_share_email_preview(owner_type, owner_id):
    """Vista previa del correo de materiales (misma estética que el envío, sin crear nada)."""
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or [])]
    ids = [x for x in ids if x]
    session_db = db()
    try:
        owner, _aid, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        photos = (
            session_db.query(Photo).filter(Photo.id.in_(ids)).order_by(Photo.sort_order.asc()).all()
        ) if ids else []
        share = PhotoShare(
            owner_type=ot, owner_id=owner.id, token="previsualizacion",
            photo_ids=[str(x) for x in ids],
            brand_company_id=to_uuid(payload.get("brand_company_id")) or _photo_owner_group_company_id(session_db, ot, owner),
        )
        html_body = _photo_share_email_html(session_db, share, photos, owner_title, (payload.get("note") or "").strip())
        return jsonify({"ok": True, "html": html_body})
    finally:
        session_db.close()


@app.post("/fotos/<owner_type>/<owner_id>/share/email", endpoint="fotos_share_email")
@admin_required
def fotos_share_email(owner_type, owner_id):
    ot = _photo_owner_type_norm(owner_type)
    if not ot:
        return jsonify({"ok": False, "error": "Tipo no válido."}), 400
    payload = request.get_json(silent=True) or {}
    ids = [to_uuid(x) for x in (payload.get("photo_ids") or []) if to_uuid(x)]
    recipients = payload.get("recipients") or []
    note = (payload.get("note") or "").strip() or None
    brand_company_id = to_uuid(payload.get("brand_company_id"))
    if not ids:
        return jsonify({"ok": False, "error": "Sin fotos."}), 400
    if not recipients:
        return jsonify({"ok": False, "error": "Indica al menos un destinatario."}), 400
    state = _current_user_state()
    session_db = db()
    try:
        owner, _aid, owner_title = _photo_resolve_owner(session_db, ot, owner_id)
        if not owner:
            return jsonify({"ok": False, "error": "No encontrado."}), 404
        photos = session_db.query(Photo).filter(Photo.id.in_(ids)).all()
        share = _create_photo_share(session_db, ot, owner, ids, brand_company_id, owner_title, state)
        session_db.commit()
        subject = (payload.get("subject") or ("Fotografías — " + (owner_title or ""))).strip()
        html = _photo_share_email_html(session_db, share, photos, owner_title, note)
        ok, err = _send_optional_email(recipients, subject, html, reply_to=_current_user_email())
        if not ok:
            return jsonify({"ok": False, "error": err or "No se pudo enviar."}), 500
        return jsonify({"ok": True})
    except Exception as e:
        session_db.rollback()
        return jsonify({"ok": False, "error": str(e)}), 500
    finally:
        session_db.close()


def _photo_share_load(session_db, token):
    share = session_db.query(PhotoShare).filter(PhotoShare.token == token).first()
    if not share:
        return None, []
    ids = [to_uuid(x) for x in (share.photo_ids or []) if to_uuid(x)]
    photos = session_db.query(Photo).filter(Photo.id.in_(ids)).all() if ids else []
    order = {pid: i for i, pid in enumerate(ids)}
    photos.sort(key=lambda p: order.get(p.id, 0))
    return share, photos


@app.get("/fotos-compartir/<token>", endpoint="public_photo_share")
def public_photo_share(token):
    session_db = db()
    try:
        share, photos = _photo_share_load(session_db, token)
        if not share:
            abort(404)
        owner, _aid, owner_title = _photo_resolve_owner(session_db, share.owner_type, share.owner_id)
        company = session_db.get(GroupCompany, share.brand_company_id) if share.brand_company_id else None
        logo = (company.logo_url if company and company.logo_url else url_for("static", filename="img/logo.png"))
        rows = [{
            "id": str(p.id), "title": p.title or p.file_name or "", "file_url": p.file_url,
            "is_video": (p.kind or "IMAGE").upper() == "VIDEO",
            "download_url": url_for("public_photo_share_item", token=token, photo_id=str(p.id)),
        } for p in photos]
        card = _public_share_card(session_db, share.owner_type, owner, _aid)
        _card_bits = [x for x in [card["activity_label"], card["event_name"], card["city"], card["date_label"]] if x]
        og = {
            "title": ("Fotos / Vídeos" + (" · " + (card["artist_name"] or card["event_name"] or owner_title) if (card["artist_name"] or card["event_name"] or owner_title) else "")),
            "description": " · ".join(_card_bits),
            # SIEMPRE absoluta y sin el «?» final de storage3: si no, WhatsApp/SMS no previsualizan.
            "image": _absolute_media_url(card["artist_photo"] or (rows[0]["file_url"] if rows and not rows[0]["is_video"] else "") or (logo or "")),
        }
        return render_template("public_photo_share.html", logo=logo, owner_title=owner_title, photos=rows,
                               zip_url=url_for("public_photo_share_zip", token=token), count_label=_photo_count_label(photos),
                               kind_title="Fotos / Vídeos", card=card, og=og)
    finally:
        session_db.close()


@app.get("/fotos-compartir/<token>/zip", endpoint="public_photo_share_zip")
def public_photo_share_zip(token):
    fmt = (request.args.get("fmt") or "original").strip().lower()
    session_db = db()
    try:
        share, photos = _photo_share_load(session_db, token)
        if not share or not photos:
            abort(404)
        _owner, _aid, owner_title = _photo_resolve_owner(session_db, share.owner_type, share.owner_id)
        data, fname = _photos_zip_bytes(photos, fmt, share.title or owner_title)
        return send_file(BytesIO(data), mimetype="application/zip", as_attachment=True, download_name=fname)
    finally:
        session_db.close()


@app.get("/fotos-compartir/<token>/<photo_id>", endpoint="public_photo_share_item")
def public_photo_share_item(token, photo_id):
    fmt = (request.args.get("fmt") or "original").strip().lower()
    session_db = db()
    try:
        share, photos = _photo_share_load(session_db, token)
        if not share:
            abort(404)
        p = next((x for x in photos if str(x.id) == str(photo_id)), None)
        if not p:
            abort(404)
        data, mimetype, fname = _photo_download_bytes(p, fmt)
        return send_file(BytesIO(data), mimetype=mimetype, as_attachment=True, download_name=fname)
    finally:
        session_db.close()


@app.post('/administracion/gastos/<expense_id>/solicitud-pago/<decision>', endpoint='administration_payment_request_decision')
@admin_required
def administration_payment_request_decision(expense_id, decision):
    session_db = db()
    try:
        expense = session_db.get(BagExpense, to_uuid(expense_id))
        if not expense:
            abort(404)
        decision = (decision or '').strip().upper()
        note = (request.form.get('note') or '').strip()
        if decision == 'ACCEPT':
            expense.immediate_payment_requested = False
            expense.payment_status = 'PENDIENTE'
            expense.admin_review_status = 'PAGO_ACEPTADO'
            expense.admin_review_note = note or None
            expense.admin_reviewed_at = _now_madrid()
            session_db.add(BagPaymentInteraction(expense_id=expense.id, kind='PAGO_ACEPTADO', description=note or 'Solicitud aceptada por administración.', amount=expense.immediate_payment_amount or expense.amount_gross, created_by_nick=_email_to_nick(_current_user_email() or '')))
            flash('Solicitud aceptada y enviada a pendiente de pago.', 'success')
        else:
            expense.immediate_payment_requested = False
            expense.payment_status = 'NO_PAGADO'
            expense.admin_review_status = 'PAGO_RECHAZADO'
            expense.admin_review_note = note or 'Solicitud rechazada por administración.'
            expense.admin_reviewed_at = _now_madrid()
            session_db.add(BagPaymentInteraction(expense_id=expense.id, kind='PAGO_RECHAZADO', description=expense.admin_review_note, amount=Decimal('0'), created_by_nick=_email_to_nick(_current_user_email() or '')))
            flash('Solicitud rechazada y devuelta con nota.', 'warning')
        session_db.commit()
        return redirect(url_for('administracion_view', tab='pendiente', subtab='solicitudes'))
    except Exception as exc:
        session_db.rollback()
        flash(f'Error revisando solicitud: {exc}', 'danger')
        return redirect(url_for('administracion_view', tab='pendiente', subtab='solicitudes'))
    finally:
        session_db.close()


@app.post('/administracion/bolsas/<bag_id>/cierre-liquidacion', endpoint='administration_bag_close_liquidation')
@admin_required
def administration_bag_close_liquidation(bag_id):
    session_db = db()
    try:
        bag = session_db.get(WorkflowBag, to_uuid(bag_id))
        if not bag:
            abort(404)
        mode = (request.form.get('mode') or 'CERRAR').strip().upper()
        note = (request.form.get('note') or '').strip()
        if mode == 'VALIDAR':
            bag.liquidation_status = 'PENDIENTE_CIERRE'
            bag.liquidation_reviewed_at = _now_madrid()
            flash('Liquidación validada y enviada a cierre.', 'success')
        elif mode == 'PAGO':
            bag.liquidation_status = 'PENDIENTE_PAGO'
            flash('Liquidación cerrada y enviada a pagos.', 'success')
        elif mode == 'ARCHIVAR':
            bag.liquidation_status = 'ARCHIVADA'
            bag.is_archived = True
            bag.archived_at = _now_madrid()
            _notify_resolve(session_db, "BAG", bag.id)
            flash('Liquidación archivada.', 'success')
        else:
            bag.liquidation_status = 'CERRADA'
            bag.is_archived = True
            bag.archived_at = _now_madrid()
            _notify_resolve(session_db, "BAG", bag.id)
            flash('Liquidación cerrada.', 'success')
        adjustments = list(getattr(bag, 'liquidation_adjustments', None) or [])
        if note:
            adjustments.append({'at': _now_madrid().isoformat(), 'by': _current_user_email(), 'note': note, 'mode': mode})
        bag.liquidation_adjustments = adjustments
        session_db.commit()
        return redirect(url_for('administracion_view', tab='pendiente', subtab='cierre'))
    except Exception as exc:
        session_db.rollback()
        flash(f'Error cerrando liquidación: {exc}', 'danger')
        return redirect(url_for('administracion_view', tab='pendiente', subtab='cierre'))
    finally:
        session_db.close()


