@app.get('/invitaciones/solicitudes/<request_id>/editar', endpoint='invitation_request_edit_form')
@admin_required
def invitation_request_edit_form(request_id):
    """Devuelve el formulario COMPLETO de edición de una solicitud, precargado con sus datos, para
    cargarlo dentro del modal. Quien gestiona ve además, por categoría, las entradas asignadas
    (marcar cuáles se quedan) y cuántas añadir; el peticionario solo edita mientras no esté asignada."""
    session_db = db()
    try:
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not row:
            abort(404)
        _state = _current_user_state()
        is_owner = str(getattr(row, 'requester_user_id', '') or '') == str(_state.get('user_id') or '')
        can_manage = _user_can_manage_invitations(row.concert, session_db=session_db) if row.concert else False
        if not is_owner and not can_manage:
            abort(403)
        concert = row.concert or (session_db.get(Concert, row.concert_id) if row.concert_id else None)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else []
        all_tickets = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all()
        tickets_by_cat = defaultdict(list)
        for t in all_tickets:
            tickets_by_cat[str(t.category_id)].append(_invitation_ticket_payload(t))
        is_assigned = bool(all_tickets) or (row.status or '') in {'ASIGNADAS', 'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        can_edit = bool(can_manage or not is_assigned)
        quantities = _json_dict(row.quantities_json)
        # Conteos por categoría en UNA sola consulta (helper compartido): disponibles reales
        # (subidas - asignadas/enviadas) y subidas, para mostrar el disponible correcto.
        _tk_counts = _invitation_ticket_counts_by_category(session_db, concert) if concert else {}
        avail_by_cat = {cid: max(_safe_int(v.get('uploaded')) - _safe_int(v.get('assigned')), 0) for cid, v in _tk_counts.items()}
        uploaded_by_cat = {cid: _safe_int(v.get('uploaded')) for cid, v in _tk_counts.items()}
        _excluded = _invitation_request_excluded_category_ids(session_db, concert, categories) if concert else set()
        cat_rows = []
        for _i, cat in enumerate(categories):
            cid = str(cat.id)
            # Palcos comprometidos o COMPLETOS (asignados/enviados): fuera del formulario de
            # edición, salvo que ESTA solicitud ya los tenga (pedidos o con entradas asignadas).
            if cid in _excluded and _safe_int(quantities.get(cid)) <= 0 and not tickets_by_cat.get(cid):
                continue
            available = avail_by_cat.get(cid, 0)
            cat_rows.append({
                'id': cid,
                'name': cat.name,
                'kind': cat.ticket_kind or '',
                'qty': _safe_int(quantities.get(cid)),
                'assigned': tickets_by_cat.get(cid, []),
                'available': int(available),
                'zone': _invitation_category_zone(cat),
                # Mismo color por orden y aforo del palco que en el asistente de crear (estética común).
                'color': INVITATION_ASSIGNEE_COLORS[_i % len(INVITATION_ASSIGNEE_COLORS)],
                'configured': _safe_int(getattr(cat, 'qty_contract', 0)) + _safe_int(getattr(cat, 'qty_extra', 0)),
                # Disponible REAL: con entradas subidas manda eso; sin subidas, lo configurado.
                'available_real': int(available) if uploaded_by_cat.get(cid, 0) > 0 else (_safe_int(getattr(cat, 'qty_contract', 0)) + _safe_int(getattr(cat, 'qty_extra', 0))),
            })
        # Para poder CAMBIAR de receptor sin salir del formulario: la lista de personal (con foto) y
        # el tercero que ya estuviera puesto, para que la barra de búsqueda nazca con él elegido.
        _rp = _json_dict(row.receiver_payload)
        return render_template(
            '_invitation_edit_form.html',
            row=_invitation_request_payload(row, categories),
            personnel=_invitation_personnel_options(session_db),
            receiver_payload=_rp,
            cat_rows=cat_rows,
            total_qty=_safe_int(quantities.get('TOTAL')),
            can_manage=can_manage,
            can_edit=can_edit,
            assign_mode=bool(can_manage and is_assigned),
            guest_is_linked=bool(row.guest_promoter_id or row.guest_artist_id or row.guest_user_id),
            action_url=url_for('invitation_request_update', request_id=row.id),
        )
    finally:
        session_db.close()


@app.post('/invitaciones/solicitudes/<request_id>/editar', endpoint='invitation_request_update')
@admin_required
def invitation_request_update(request_id):
    """Edita una solicitud con el formulario completo. El peticionario solo puede editar mientras NO
    esté asignada; quien gestiona puede editar siempre y reconcilia las entradas: las desmarcadas se
    recuperan (o se BLOQUEAN como LOST si ya se enviaron/descargaron y no se podrán reutilizar) y las
    AÑADIDAS quedan pendientes: la solicitud vuelve a «pendiente de asignar» (APROBADAS) aunque
    estuviera asignada o enviada, para continuar el proceso (asignar → enviar). Cambiar de categoría
    = desmarcar en una y añadir en otra."""
    session_db = db()
    try:
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not row:
            abort(404)
        _state = _current_user_state()
        _is_owner = str(getattr(row, 'requester_user_id', '') or '') == str(_state.get('user_id') or '')
        can_manage = _user_can_manage_invitations(row.concert, session_db=session_db) if row.concert else False
        if not _is_owner and not can_manage:
            abort(403)
        concert = row.concert or (session_db.get(Concert, row.concert_id) if row.concert_id else None)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False) if concert else []
        all_tickets = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all()
        sent_statuses = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        is_assigned = bool(all_tickets) or (row.status or '') in sent_statuses or (row.status or '') == 'ASIGNADAS'
        # Modo "gestionar asignación": solo quien gestiona y sobre una solicitud ya asignada.
        assign_mode = bool(can_manage and is_assigned)
        _prior_total = _invitation_total_qty(_json_dict(row.quantities_json))
        _fb = request.referrer if (request.referrer or '').startswith(request.host_url) else None
        # El peticionario NO puede editar una solicitud ya asignada (solo quien gestiona).
        if is_assigned and not can_manage:
            flash('Esta solicitud ya está asignada; solo puede editarla quien gestiona las invitaciones.', 'warning')
            return redirect(_fb or url_for('invitations_view', tab='pedir'))

        # Datos del invitado / entrega / nota.
        guest_name = (request.form.get('guest_name') or '').strip()
        if guest_name:
            row.guest_name = guest_name
        row.guest_email = (request.form.get('guest_email') or '').strip()
        row.guest_phone = (request.form.get('guest_phone') or '').strip()
        # "Cargo / empresa" es un único campo (name=guest_title) que se refleja en guest_title y
        # guest_company. Debe poder VACIARSE (p. ej. para no duplicar con la vinculación): si llega
        # vacío, se borran ambos (antes se conservaba el guest_company anterior y "reaparecía").
        guest_title = (request.form.get('guest_title') or '').strip()
        row.guest_title = guest_title or None
        row.guest_company = guest_title or None
        row.note = (request.form.get('note') or '').strip()
        # A QUIÉN se le mandan: mismo motor que al crearla, así cambiar de receptor al editar guarda
        # también SUS datos (la persona de la empresa o el tercero elegido), no solo el modo. «A mí»
        # es quien PIDIÓ la petición, no quien la está editando.
        rmode = (request.form.get('receiver_mode') or '').strip().upper()
        if rmode in {'GUEST', 'ME', 'BOX_OFFICE', 'EMPLOYEE', 'OTHER'}:
            _req_info = {
                'user_id': str(row.requester_user_id or ''),
                'nick': row.requester_nick or '',
                'email': row.requester_email or '',
                'photo_url': row.requester_photo_url or '',
                'phone': '',
            }
            try:
                row.receiver_mode, row.receiver_payload, _ = _invitation_receiver_from_form(
                    session_db, request.form, _req_info,
                    guest_name=row.guest_name or '', guest_email=row.guest_email or '',
                    guest_phone=row.guest_phone or '')
            except ValueError as exc:
                session_db.rollback()
                flash(str(exc), 'warning')
                return redirect(_fb or url_for('invitations_view', tab='pedir'))

        has_cat_fields = any(k.startswith('cat_') or k == 'keep_ticket' for k in request.form.keys())
        if has_cat_fields:
            keep_ids = {str(x) for x in request.form.getlist('keep_ticket')}
            prior_quantities = _json_dict(row.quantities_json)
            tickets_by_cat = defaultdict(list)
            for t in all_tickets:
                tickets_by_cat[str(t.category_id)].append(t)
            req_downloaded = bool(row.downloaded_at) or _safe_int(row.downloaded_count) > 0
            new_quantities = {}
            for cat in categories:
                cid = str(cat.id)
                assigned = tickets_by_cat.get(cid, [])
                if assign_mode and (cat.ticket_kind or '').upper() != 'GUEST_LIST':
                    kept = [t for t in assigned if str(t.id) in keep_ids]
                    for t in assigned:
                        if str(t.id) in keep_ids:
                            t.assigned_label = row.guest_name
                            continue
                        # Desmarcada → recuperar si se puede reutilizar; si ya se envió/descargó, bloquear.
                        t_sent = (t.status or '') in {'SENT', 'DELIVERED', 'PICKED_UP'} or bool(getattr(t, 'sent_at', None)) or bool(row.sent_at) or (row.status or '') in sent_statuses
                        if t_sent or req_downloaded:
                            t.previous_assignment_warning = f"Bloqueada al editar la solicitud de {row.guest_name} (ya enviada/descargada, no reutilizable)."
                            t.status = 'LOST'
                        else:
                            t.previous_assignment_warning = f"Recuperada al editar la solicitud de {row.guest_name}."
                            t.status = 'AVAILABLE'
                        t.assigned_request_id = None
                        t.assigned_commitment_id = None
                        t.assigned_label = None
                        t.sent_at = None
                        t.added_after_send = False
                        t.updated_at = _now_madrid()
                    add_n = _safe_int(request.form.get(f'cat_{cid}_add'))
                    # Las AÑADIDAS ya NO se asignan aquí en automático: quedan PENDIENTES y la
                    # solicitud vuelve a «pendiente de asignar» (APROBADAS, la recalcula el sync de
                    # abajo) para continuar el proceso normal: asignar en el asignador → enviar.
                    # Preserva lo que ya estaba pedido pero sin asignar (no se pierde ni se asigna solo).
                    pending_kept = max(0, _safe_int(prior_quantities.get(cid)) - len(assigned))
                    qty = len(kept) + add_n + pending_kept
                else:
                    qty = _safe_int(request.form.get(f'cat_{cid}_qty'))
                if qty > 0:
                    new_quantities[cid] = qty
            total_input = request.form.get('cat_TOTAL_qty')
            if total_input is not None and _safe_int(total_input) > 0:
                new_quantities['TOTAL'] = _safe_int(total_input)
            # «No aceptar por encima del cupo» (flag por categoría): al modificar se acredita lo que
            # esta misma solicitud ya ocupaba; sin el flag se puede modificar libremente.
            _oq_cats = [c for c in categories if getattr(c, 'requests_over_quota_blocked', False)]
            if _oq_cats and concert is not None:
                _avail_by_cat = _invitation_event_available_by_category(session_db, concert, categories)
                for _pcid, _pq in prior_quantities.items():
                    if str(_pcid).upper() != 'TOTAL':
                        _avail_by_cat[str(_pcid)] = _safe_int(_avail_by_cat.get(str(_pcid), 0)) + _safe_int(_pq)
                _over = [f"{c.name} (quedan {max(_safe_int(_avail_by_cat.get(str(c.id), 0)), 0)})"
                         for c in _oq_cats
                         if _safe_int(new_quantities.get(str(c.id))) > max(_safe_int(_avail_by_cat.get(str(c.id), 0)), 0)]
                if _over:
                    raise ValueError('No se aceptan peticiones por encima del cupo en: ' + ', '.join(_over) + '.')
            row.quantities_json = new_quantities
        else:
            new_total = _safe_int(request.form.get('qty_total'))
            if new_total > 0:
                quantities = _json_dict(row.quantities_json)
                positive = {k: _safe_int(v) for k, v in quantities.items() if _safe_int(v) > 0}
                if len(positive) == 1:
                    quantities[next(iter(positive))] = new_total
                    row.quantities_json = quantities
                elif not positive:
                    row.quantities_json = {'TOTAL': new_total}

        # Recalcular estado desde entradas + nuevo cupo: si al ampliar quedan invitaciones por asignar,
        # vuelve a PENDIENTE (aparece en el asignador) aunque hubiera enviadas; las enviadas/asignadas
        # se conservan como tales. Luego «enviar» preguntará todas / solo las nuevas.
        session_db.flush()
        _invitation_sync_request_status(session_db, row)
        # Ampliación sobre estados de ENTREGA manual (en mano / taquilla): el sync no los toca, pero
        # si el total CRECE también deben volver a «pendiente de asignar» para seguir el proceso.
        _new_total = _invitation_total_qty(_json_dict(row.quantities_json))
        if _new_total > _prior_total and (row.status or '') in {'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}:
            row.status = 'APROBADAS'
        row.updated_at = _now_madrid()
        session_db.commit()
        flash('Solicitud actualizada.', 'success')
        return redirect(_fb or url_for('invitations_view', tab='pedir'))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo actualizar la solicitud: {exc}', 'danger')
        _fb = request.referrer if (request.referrer or '').startswith(request.host_url) else None
        return redirect(_fb or url_for('invitations_view', tab='pedir'))
    finally:
        session_db.close()


@app.post('/invitaciones/solicitudes/<request_id>/eliminar', endpoint='invitation_request_delete')
@admin_required
def invitation_request_delete(request_id):
    """Elimina una solicitud propia (o gestionable), gestionando sus entradas asignadas:

    - Sin entradas o con entradas asignadas pero NO enviadas → se liberan (vuelven a disponibles) y
      se borra la solicitud directamente.
    - Con entradas YA enviadas → requiere una decisión explícita (`mode`), porque el invitado pudo
      recibirlas o descargarlas. Sin `mode` válido devolvemos `needs_confirm` para que el front
      muestre la advertencia con las opciones:
        · `recover` → recuperar/cancelar envío: las entradas vuelven a estar disponibles (con aviso).
        · `lost`    → darlas por perdidas: las entradas quedan en estado LOST y NO vuelven al pool.
    """
    _ajax = _truthy(request.form.get('ajax'))
    fallback = request.referrer if (request.referrer or '').startswith(request.host_url) else None
    session_db = db()
    try:
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not row:
            abort(404)
        _state = _current_user_state()
        _is_owner = str(getattr(row, 'requester_user_id', '') or '') == str(_state.get('user_id') or '')
        if not _is_owner:
            _ensure_can_manage_invitations(session_db, row.concert)
        tickets = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all()
        sent_statuses = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
        was_sent = bool(row.sent_at) or (row.status or '') in sent_statuses \
            or any((t.status or '') in _INVITATION_TICKET_SENTISH for t in tickets)
        was_printed = any((t.status or '') == 'PRINTED' for t in tickets)
        was_downloaded = bool(row.downloaded_at) or _safe_int(row.downloaded_count) > 0
        mode = (request.form.get('mode') or '').strip().lower()

        # Entradas enviadas/descargadas/impresas sin decisión → no borrar a ciegas: pedir
        # confirmación (el front muestra la alerta con Recuperar/Descartar).
        if tickets and was_sent and mode not in {'recover', 'lost'}:
            info = {
                'ok': False, 'needs_confirm': True, 'sent': True, 'printed': was_printed,
                'downloaded': bool(was_downloaded), 'ticket_count': len(tickets),
                'guest_name': row.guest_name or '',
            }
            if _ajax:
                return jsonify(info)
            flash('Estas invitaciones ya fueron enviadas. Usa el menú para recuperarlas o descartarlas antes de eliminar.', 'warning')
            return redirect(fallback or (url_for('invitation_event_detail', concert_id=row.concert_id) if not _is_owner else url_for('invitations_view', tab='pedir')))

        recovered, discarded = _invitation_release_apply(tickets, mode=mode, entity_label=f'la solicitud de {row.guest_name}')
        session_db.delete(row)
        session_db.commit()
        msg = 'Solicitud eliminada.' + ((' ' + _invitation_release_summary(recovered, discarded)) if tickets else '')
        if _ajax:
            return jsonify({'ok': True, 'message': msg})
        flash(msg, 'success')
        return redirect(fallback or url_for('invitations_view', tab='pedir'))
    except Exception as exc:
        session_db.rollback()
        if _ajax:
            return jsonify({'ok': False, 'error': str(exc)}), 400
        flash(f'No se pudo eliminar la solicitud: {exc}', 'danger')
        return redirect(fallback or url_for('invitations_view', tab='pedir'))
    finally:
        session_db.close()


def _invitation_seat_int(ticket) -> int | None:
    """Número de asiento como entero (para ordenar/medir contigüidad); None si no es numérico."""
    s = (getattr(ticket, "seat_number", None) or "").strip()
    m = re.match(r"\d+", s)
    return int(m.group(0)) if m else None


def _invitation_pick_grouped_seats(available: list, qty: int, category=None, concert=None) -> list:
    """Elige `qty` butacas de `available` (entradas AVAILABLE ya ordenadas por sector/fila/asiento)
    intentando que el grupo quede JUNTO, sin dividirlo:
      1) Un tramo CONTIGUO (asientos seguidos, sin huecos) dentro de una misma fila.
      2) Si no cabe en ninguna fila, se llenan filas CONSECUTIVAS (una detrás de otra) hasta completar.
    Una ESCALERA configurada (layout del sector) corta el tramo aunque las butacas sean seguidas, para
    no repartir el grupo a ambos lados de la escalera.
    Devuelve la lista elegida (puede ser < qty si no hay suficientes disponibles)."""
    if qty <= 0 or not available:
        return []
    # Agrupa por (sector, fila) preservando el orden de aparición (que ya viene sector→fila→asiento).
    rows: dict = {}
    for t in available:
        key = ((getattr(t, "sector", None) or ""), (getattr(t, "row_label", None) or ""))
        rows.setdefault(key, []).append(t)
    _cfg_by_sector: dict = {}

    def _stairs_for(sector_name: str, row_label: str) -> set:
        if category is None:
            return set()
        if sector_name not in _cfg_by_sector:
            _cfg_by_sector[sector_name] = _invitation_sector_layout(category, sector_name or "General", concert=concert)
        return _invitation_row_layout(_cfg_by_sector[sector_name], row_label)["stairs"]
    # Parte cada fila en TRAMOS contiguos: dos asientos son contiguos si su diferencia == paso de la
    # fila (el menor salto entre asientos disponibles: 1 si van 1,2,3…; 2 si van 1,3,5…). Un salto
    # mayor = hay una butaca ocupada en medio → se corta el tramo (para no dejar hueco en el grupo).
    # Una ESCALERA de esa fila también corta el tramo.
    runs: list = []  # [ [tickets_contiguos], ... ] en orden
    for (sector_name, _row), seats in rows.items():
        stairs_after = _stairs_for(sector_name, _row)
        seats_sorted = sorted(seats, key=lambda t: (_invitation_seat_int(t) if _invitation_seat_int(t) is not None else 10 ** 9))
        nums = [_invitation_seat_int(t) for t in seats_sorted]
        diffs = [b - a for a, b in zip(nums, nums[1:]) if a is not None and b is not None and b > a]
        step = min(diffs) if diffs else 1
        run = [seats_sorted[0]]
        for prev, cur in zip(seats_sorted, seats_sorted[1:]):
            pn, cn = _invitation_seat_int(prev), _invitation_seat_int(cur)
            _stair_between = bool(stairs_after and pn is not None and cn is not None and any(pn <= sa < cn for sa in stairs_after))
            if pn is not None and cn is not None and (cn - pn) == step and not _stair_between:
                run.append(cur)
            else:
                runs.append(run)
                run = [cur]
        runs.append(run)
    # 1) Primer tramo contiguo que quepa ENTERO (grupo sin partir, mismas butacas seguidas). Se toma
    # el PRIMERO en orden (sector→fila→asiento): se llena de delante hacia atrás, como es natural.
    for run in runs:
        if len(run) >= qty:
            return run[:qty]
    # 2) No cabe junto: filas consecutivas, una detrás de otra, hasta completar.
    chosen: list = []
    for run in runs:
        for t in run:
            chosen.append(t)
            if len(chosen) >= qty:
                return chosen[:qty]
    return chosen[:qty]


@app.post('/invitaciones/solicitudes/<request_id>/asignar-auto', endpoint='invitation_request_auto_assign')
@admin_required
def invitation_request_auto_assign(request_id):
    cid = None
    session_db = db()
    try:
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not row:
            abort(404)
        cid = str(row.concert_id)
        _ensure_can_manage_invitations(session_db, row.concert)
        concert = row.concert or session_db.get(Concert, row.concert_id)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=True)
        cat_map = {str(c.id): c for c in categories}
        quantities = _json_dict(row.quantities_json)
        assigned_count = 0
        # Ya asignadas por categoría de ESTA solicitud: solo se asigna el RESTO (clave en las
        # AMPLIACIONES de una solicitud ya asignada/enviada; antes asignaba el total otra vez).
        _asg_by_cat = {}
        for _tcid, _tn in (session_db.query(InvitationTicket.category_id, func.count(InvitationTicket.id))
                           .filter(InvitationTicket.assigned_request_id == row.id)
                           .group_by(InvitationTicket.category_id).all()):
            _asg_by_cat[str(_tcid)] = int(_tn or 0)
        # OJO: NO reutilizar `cid` aquí — es el id del CONCIERTO para el redirect de error. Antes el
        # bucle lo machacaba con ids de categoría y, al faltar disponibilidad, el redirect iba a una
        # URL inválida (404) y el aviso de «no hay invitaciones suficientes» se perdía en silencio.
        for cat_key, qty in quantities.items():
            qty = _safe_int(qty) - _asg_by_cat.get(str(cat_key), 0)
            if qty <= 0 or cat_key == 'TOTAL':
                continue
            cat = cat_map.get(str(cat_key))
            if not cat:
                continue
            if (cat.ticket_kind or '').upper() == 'GUEST_LIST':
                assigned_count += qty
                continue
            available_all = (
                session_db.query(InvitationTicket)
                .filter(InvitationTicket.category_id == cat.id)
                .filter(InvitationTicket.status == 'AVAILABLE')
                .order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc())
                .all()
            )
            if len(available_all) < qty:
                raise ValueError(f'No se ha podido realizar la asignación por falta de invitaciones disponibles en «{cat.name}» (faltan {qty - len(available_all)}). Todo queda como estaba.')
            # Butacas contiguas para no dividir al grupo (mismo tramo de fila; si no, filas seguidas).
            available = _invitation_pick_grouped_seats(available_all, qty, category=cat, concert=concert)
            # AMPLIACIÓN: si la solicitud ya tuvo un envío, lo asignado ahora nace marcado «Nueva».
            _dest_sent = _invitation_dest_already_sent(session_db, request_row=row)
            for ticket in available:
                if ticket.previous_assignment_warning and not _truthy(request.form.get('accept_warnings')):
                    raise ValueError(f'La entrada {ticket.ticket_code or ticket.pdf_name} ya había sido enviada/asignada antes. Acepta la advertencia para reasignarla.')
                ticket.assigned_request_id = row.id
                ticket.assigned_label = row.guest_name
                ticket.status = 'ASSIGNED'
                ticket.assigned_at = _now_madrid()
                ticket.sent_at = None            # butaca reutilizada: esta asignación aún no se envió
                ticket.added_after_send = _dest_sent
                assigned_count += 1
        if assigned_count > 0:
            # No degradar una ENVIADAS/entregada AMPLIADA: conserva su estado (la etiqueta partida
            # y el asignador ya reflejan lo pendiente/sin enviar por métricas).
            if (row.status or '') not in {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}:
                row.status = 'ASIGNADAS'
            row.assigned_at = _now_madrid()
        if assigned_count <= 0:
            raise ValueError('No se ha podido realizar la asignación por falta de invitaciones disponibles (no hay invitaciones subidas y disponibles en la categoría). Todo queda como estaba.')
        session_db.commit()
        flash('Invitaciones asignadas.', 'success')
        return redirect(url_for('invitation_event_detail', concert_id=row.concert_id))
    except Exception as exc:
        session_db.rollback()
        # Los ValueError ya traen el mensaje pensado para el usuario (falta de disponibles, etc.).
        flash(str(exc) if isinstance(exc, ValueError) else f'No se pudieron asignar automáticamente: {exc}', 'danger')
        # Volver al mismo evento para que el aviso se vea (con envío inline la zona existe ahí).
        return redirect(url_for('invitation_event_detail', concert_id=cid) if cid else url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


def _invitation_send_tickets_query(session_db, row, send_scope):
    """Entradas a marcar como enviadas: todas las asignadas, o solo las AÚN NO enviadas
    (send_scope='unsent') cuando el usuario elige «enviar solo las nuevas»."""
    q = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id)
    if (send_scope or 'all') == 'unsent':
        q = q.filter(InvitationTicket.status == 'ASSIGNED')
    return q.all()


def _invitation_tag_new_tickets(all_tickets, sending):
    """Etiqueta «Nueva» (added_after_send) SOLO cuando el envío MEZCLA entradas ya enviadas con
    añadidas nuevas (reenvío de TODO tras una ampliación): así el invitado distingue visualmente
    las nuevas respecto al ÚLTIMO envío, tanto en el correo como en la página del enlace. Si solo
    se mandan las nuevas no hay mezcla y no se etiqueta nada. Limpia siempre las marcas del envío
    anterior. Compartido por solicitudes y compromisos."""
    for t in all_tickets:
        if getattr(t, 'added_after_send', False):
            t.added_after_send = False

    def _was_sent(t):
        return ((t.status or '').upper() in _INVITATION_TICKET_SENT_STATUSES) or bool(t.sent_at)

    mixed = any(_was_sent(t) for t in sending) and any(not _was_sent(t) for t in sending)
    if not mixed:
        return
    for t in sending:
        if not _was_sent(t):
            t.added_after_send = True


def _invitation_dest_already_sent(session_db, request_row=None, commitment_row=None) -> bool:
    """¿La solicitud/compromiso YA tuvo un envío/entrega? Si sí, lo que se asigne AHORA es una
    AMPLIACIÓN: la entrada nace marcada added_after_send para que el asignador, el correo y el
    enlace la distingan como «Nueva» aunque el camino de envío no re-derive la etiqueta.
    (El propio _invitation_tag_new_tickets la limpia cuando deja de haber mezcla, p. ej. al
    reubicar la petición completa o en el reenvío siguiente.)"""
    row = request_row if request_row is not None else commitment_row
    if row is None:
        return False
    if getattr(row, 'sent_at', None):
        return True
    if (getattr(row, 'status', '') or '').upper() in {'ENVIADAS', 'ENTREGADAS_MANO', 'RECOGIDAS_TAQUILLA', 'DISPONIBLES_TAQUILLA'}:
        return True
    fld = InvitationTicket.assigned_request_id if request_row is not None else InvitationTicket.assigned_commitment_id
    hit = (session_db.query(InvitationTicket.id)
           .filter(fld == row.id)
           .filter(or_(InvitationTicket.status.in_(list(_INVITATION_TICKET_SENT_STATUSES)),
                       InvitationTicket.sent_at.isnot(None)))
           .first())
    return bool(hit)


def _invitation_mark_sent_tickets(session_db, row, send_scope, sent_at):
    """Marca SENT las entradas del envío de una SOLICITUD, etiquetando antes las «Nueva» que
    procedan (ver _invitation_tag_new_tickets)."""
    all_tk = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id).all()
    sending = _invitation_send_tickets_query(session_db, row, send_scope)
    _invitation_tag_new_tickets(all_tk, sending)
    for ticket in sending:
        ticket.status = 'SENT'
        ticket.sent_at = sent_at
        ticket.updated_at = sent_at


def _invitation_send_request(session_db, row, channel, *, custom_text=None, extra_recipients=None, send_scope='all'):
    """Envía una SOLICITUD ya asignada por email/WhatsApp/SMS y la marca ENVIADAS (+ entradas SENT).
    ÚNICA lógica de envío, reutilizada por el envío individual y por el envío de una selección de
    entradas del plano. WhatsApp/SMS marca siempre y devuelve la URL a abrir; email solo marca si el
    correo se manda de verdad. send_scope='unsent' marca solo las entradas aún no enviadas.
    Devuelve dict {ok, channel, url?/recipients?, error?}."""
    channel = (channel or 'email').strip().lower()
    concert = row.concert or session_db.get(Concert, row.concert_id)
    categories = _invitation_get_categories(session_db, concert, ensure_defaults=False) if row.concert_id else []
    flags = _invitation_request_kind_flags(session_db, row, categories)
    if not flags.get('can_send'):
        raise ValueError('Solo se pueden enviar invitaciones cuando ya tienen entradas asignadas o cuando son de tipo listado.')
    row.delivery_token = row.delivery_token or _invitation_token()
    if channel in ('whatsapp', 'sms'):
        # WhatsApp/SMS NO adjuntan archivos: el mensaje lleva el enlace que descarga las invitaciones
        # en un único PDF (directo, sin descomprimir). Se abre en el cliente.
        has_pdfs = not flags.get('uses_guest_list')
        link = _external_url_for('public_invitation_delivery', kind='r', token=row.delivery_token) if has_pdfs else ''
        msg = _invitation_share_text(session_db, concert, row.guest_name, link)
        phone = _normalize_phone_intl(_invitation_guest_live_phone(session_db, row))
        if channel == 'whatsapp':
            url = ('https://wa.me/' + phone + '?text=' + quote_plus(msg)) if phone else ('https://wa.me/?text=' + quote_plus(msg))
        else:
            url = ('sms:' + ('+' + phone if phone else '') + '?&body=' + quote_plus(msg))
        row.status = 'ENVIADAS'
        row.sent_at = _now_madrid()
        row.sent_via = 'WhatsApp' if channel == 'whatsapp' else 'SMS'
        row.sent_to = ('+' + phone) if phone else ''
        _invitation_mark_sent_tickets(session_db, row, send_scope, row.sent_at)
        session_db.commit()
        return {'ok': True, 'url': url, 'channel': channel}
    # Email — las marcas «Nueva» y el estado SENT se ponen ANTES de componer el correo (así el
    # listado del email ya distingue las nuevas); si el SMTP falla, el rollback lo deshace todo.
    _sent_at = _now_madrid()
    _scope_ids = {t.id for t in _invitation_send_tickets_query(session_db, row, send_scope)}
    _invitation_mark_sent_tickets(session_db, row, send_scope, _sent_at)
    # «Enviar solo las nuevas»: el correo lista únicamente las de este envío (sin mezcla no hay
    # etiqueta); al enviar TODAS se listan todas y las nuevas van con su etiqueta «Nueva».
    subject, html_body, text_body = _invitation_email_body(
        session_db, row, None, custom_text=custom_text,
        only_ticket_ids=(_scope_ids if (send_scope or 'all') == 'unsent' else None))
    recipients = _dedupe_valid_email_addresses(list(extra_recipients or []) + _invitation_delivery_recipients(session_db, row))
    # Sin ninguna dirección de destino NO se envía ni se marca: hay que escribir un correo
    # (el destinatario no tiene email configurado y no se ha añadido ninguno).
    if not recipients:
        session_db.rollback()
        return {'ok': False, 'channel': 'email', 'error': 'No hay ningún correo al que enviar. Escribe la dirección de destino del invitado antes de continuar.', 'recipients': []}
    # Reply-To: el peticionario de la oficina (no quien gestiona el envío).
    reply_to = _invitation_request_reply_to(session_db, row) or _current_user_email()
    ok, err = _send_optional_email(recipients, subject, html_body, text_body=text_body, reply_to=reply_to)
    if ok:
        row.status = 'ENVIADAS'
        row.sent_at = _sent_at
        row.sent_via = 'Email'
        row.sent_to = ', '.join(recipients or [])
        session_db.commit()
        return {'ok': True, 'channel': 'email', 'recipients': recipients}
    session_db.rollback()
    return {'ok': False, 'channel': 'email', 'error': err or 'SMTP no configurado', 'recipients': recipients}


@app.post('/invitaciones/solicitudes/<request_id>/enviar', endpoint='invitation_request_send')
@admin_required
def invitation_request_send(request_id):
    session_db = db()
    try:
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not row:
            abort(404)
        # Quien gestiona O el PROPIO peticionario (desde «Mis solicitudes» el envío funciona
        # exactamente igual: mismo correo, mismos enlaces y estado → ENVIADAS en toda la app).
        _state_o = _current_user_state()
        _is_owner = str(getattr(row, 'requester_user_id', '') or '') == str(_state_o.get('user_id') or '')
        if not _is_owner:
            _ensure_can_manage_invitations(session_db, row.concert)
        # Blindaje servidor: solo se envía con el cupo COMPLETO asignado (la UI ya oculta la opción,
        # esto protege ante pestañas desactualizadas o dobles clics).
        _flags = _invitation_request_kind_flags(session_db, row, _invitation_get_categories(session_db, row.concert, ensure_defaults=False))
        if not _flags.get('can_send'):
            raise ValueError('Faltan invitaciones por asignar: el envío requiere el cupo completo.')
        channel = (request.form.get('channel') or 'email').strip().lower()
        wants_json = (request.form.get('as_json') == '1') or (request.headers.get('X-Requested-With') == 'XMLHttpRequest')
        extra = request.form.getlist('recipients') + request.form.getlist('extra_emails')
        send_scope = (request.form.get('send_scope') or 'all').strip().lower()
        res = _invitation_send_request(session_db, row, channel, custom_text=(request.form.get('custom_text') or None), extra_recipients=extra, send_scope=send_scope)
        if channel in ('whatsapp', 'sms'):
            if wants_json:
                return jsonify({'ok': True, 'url': res.get('url'), 'channel': channel})
            return redirect(res.get('url'))
        if res.get('ok'):
            flash('Invitaciones enviadas por email a: ' + (', '.join(res.get('recipients') or []) or '—') + '.', 'success')
        else:
            flash(f'No se pudo enviar el email (no se marca como enviada): {res.get("error")}', 'warning')
        return redirect(url_for('invitation_event_detail', concert_id=row.concert_id))
    except Exception as exc:
        session_db.rollback()
        if (request.form.get('as_json') == '1') or (request.headers.get('X-Requested-With') == 'XMLHttpRequest'):
            return jsonify({'ok': False, 'error': str(exc)}), 400
        flash(f'No se pudo enviar: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/solicitudes/<request_id>/marcar-enviadas', endpoint='invitation_request_mark_sent')
@admin_required
def invitation_request_mark_sent(request_id):
    """Marca una solicitud como ENVIADAS SIN enviar correo. Sirve también de forma DIRECTA aunque
    la solicitud no tenga entradas asignadas (cuando las invitaciones se entregaron por fuera del
    sistema): solo cambia el estado. Si tiene entradas asignadas, también las pasa a SENT."""
    session_db = db()
    try:
        row = session_db.get(InvitationRequest, to_uuid(request_id))
        if not row:
            abort(404)
        _ensure_can_manage_invitations(session_db, row.concert)
        if (row.status or '').upper() in {'RECHAZADAS', 'ANULADAS'}:
            raise ValueError('No se puede marcar como enviada una solicitud rechazada o anulada.')
        # ⚠️ Sin entradas asignadas no hay nada que se haya podido entregar: marcarla como enviada
        # es justo lo que confundía (una petición «Enviada» que no tenía ni una invitación).
        # La LISTA DE INVITADOS es la excepción: no lleva entradas, se entrega en la puerta.
        # ⚠️ Hay que pasarle las CATEGORÍAS: sin ellas no puede saber que es una lista de invitados
        # (el mapa sale vacío) y bloquearía justo el caso que se quiere permitir.
        _cats = _invitation_get_categories(session_db, row.concert, ensure_defaults=False) if row.concert else []
        _flags = _invitation_request_kind_flags(session_db, row, _cats)
        _asignadas = _safe_int(_flags.get('assigned_total'))
        if not _asignadas and not _flags.get('uses_guest_list'):
            raise ValueError('Esta petición no tiene invitaciones asignadas: asígnalas antes de '
                             'marcarlas como enviadas.')
        now = _now_madrid()
        row.status = 'ENVIADAS'
        row.sent_at = now
        row.sent_via = 'Manual'
        row.sent_to = 'Marcada como enviada'
        row.delivery_token = row.delivery_token or _invitation_token()
        _invitation_mark_sent_tickets(session_db, row, 'all', now)
        session_db.commit()
        flash('Invitaciones marcadas como enviadas.', 'success')
        return redirect(url_for('invitation_event_detail', concert_id=row.concert_id))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo marcar como enviadas: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/categoria/<category_id>/asignar-todas', endpoint='invitation_category_auto_assign')
@admin_required
def invitation_category_auto_assign(concert_id, category_id):
    """Asigna automáticamente TODAS las pendientes de UNA categoría (solicitudes y compromisos con
    cantidad por asignar; las ya asignadas/enviadas no se tocan), agrupando butacas contiguas.
    Si no llegan las disponibles, asigna lo posible y avisa de lo que faltó."""
    session_db = db()
    _cid = None
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        _cid = str(concert.id)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
        cat = next((c for c in categories if str(c.id) == str(_safe_uuid(category_id))), None)
        if not cat:
            abort(404)
        if (cat.ticket_kind or '').upper() == 'GUEST_LIST':
            raise ValueError('Las categorías de listado no requieren asignación de PDFs.')
        pend = [x for x in _invitation_pending_assignment_payloads(session_db, concert, categories).get(str(cat.id), [])
                if _safe_int(x.get('qty')) > 0]
        if not pend:
            flash(f'No hay nada pendiente de asignar en «{cat.name}».', 'info')
            return redirect(url_for('invitation_event_detail', concert_id=_cid))
        remaining = (
            session_db.query(InvitationTicket)
            .filter(InvitationTicket.category_id == cat.id, InvitationTicket.status == 'AVAILABLE')
            .order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc())
            .all()
        )
        now = _now_madrid()
        assigned_total = 0
        short = 0
        skipped = 0
        for src in pend:
            need = _safe_int(src.get('qty'))
            if need <= 0:
                continue
            # TODO-O-NADA por invitado: si no hay disponibles para su cupo COMPLETO, se deja
            # exactamente como estaba (sin asignación parcial) y se avisa al final.
            if need > len(remaining):
                short += need
                skipped += 1
                continue
            request_row = None
            commitment_row = None
            if src.get('source_type') == 'request':
                request_row = session_db.get(InvitationRequest, _safe_uuid(src.get('source_id')))
                if not request_row:
                    continue
                label = request_row.guest_name or 'Invitado'
            else:
                commitment_row = session_db.get(InvitationCommitment, _safe_uuid(src.get('source_id')))
                if not commitment_row:
                    continue
                label = commitment_row.name or 'Compromiso'
            picked = _invitation_pick_grouped_seats(remaining, need, category=cat, concert=concert)
            # AMPLIACIÓN: si el destino ya tuvo un envío, lo asignado ahora nace marcado «Nueva».
            _dest_sent = _invitation_dest_already_sent(session_db, request_row=request_row, commitment_row=commitment_row)
            for ticket in picked:
                ticket.assigned_request_id = request_row.id if request_row else None
                ticket.assigned_commitment_id = commitment_row.id if commitment_row else None
                ticket.assigned_label = label
                ticket.status = 'ASSIGNED'
                ticket.assigned_at = now
                ticket.updated_at = now
                ticket.sent_at = None            # butaca reutilizada: esta asignación aún no se envió
                ticket.added_after_send = _dest_sent
            _picked_ids = {t.id for t in picked}
            remaining = [t for t in remaining if t.id not in _picked_ids]
            assigned_total += len(picked)
            # No degradar una ENVIADAS/entregada AMPLIADA (el resto pendiente ya se refleja aparte).
            _sent_ish_keep = {'ENVIADAS', 'ENTREGADAS_MANO', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA'}
            if request_row:
                if (request_row.status or '') not in _sent_ish_keep:
                    request_row.status = 'ASIGNADAS'
                request_row.assigned_at = now
                request_row.updated_at = now
            if commitment_row:
                if (commitment_row.status or '') not in _sent_ish_keep:
                    commitment_row.status = 'ASIGNADAS'
                commitment_row.updated_at = now
        if assigned_total <= 0 and skipped:
            raise ValueError(f'No se ha podido realizar la asignación por falta de invitaciones disponibles en «{cat.name}» (faltaban {short}). Todo queda como estaba.')
        session_db.commit()
        msg = f'{assigned_total} invitación(es) de «{cat.name}» asignadas automáticamente.'
        if skipped:
            msg += f' {skipped} invitado(s) se han quedado SIN asignar por falta de invitaciones disponibles (faltaban {short}); quedan como estaban.'
        flash(msg, 'warning' if skipped else 'success')
        return redirect(url_for('invitation_event_detail', concert_id=_cid))
    except Exception as exc:
        session_db.rollback()
        flash(str(exc) if isinstance(exc, ValueError) else f'No se pudo asignar automáticamente: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=_cid) if _cid else url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


def _invitation_mass_contact(session_db, row, recipients) -> dict:
    """Por dónde le llega la invitación a este invitado en un envío MASIVO (sin preguntar nada).

    Manda el canal que tenga configurado en su ficha (`Promoter.notify_channel`) y, si no ha dicho
    nada, el correo. Quien solo tiene teléfono recibe el SMS con el enlace de descarga: antes se
    quedaba «sin email» y no le llegaba nada."""
    return _notify_apply_prefs(session_db, [{
        "name": (getattr(row, "guest_name", None) or ""),
        "email": ((recipients or [""])[0] or ""),
        "phone": _invitation_guest_live_phone(session_db, row),
    }])[0]


def _invitation_mass_send_one(session_db, concert, row, recipients, contacto, *,
                              uses_guest_list=False, link_kind="r",
                              body=None, reply_to=None) -> tuple[bool, str, str, str]:
    """Manda UNA invitación de un envío masivo por el canal de `contacto`.

    Devuelve `(ok, error, via, destino)`. `link_kind` es «r» para una solicitud y «c» para un
    compromiso (su enlace de descarga), y `body` el compositor del correo de ese tipo.
    ⚠️ Si toca SMS y el SMS no sale (pasarela sin configurar, sin saldo…) **no se pierde el envío**:
    se manda el correo, que es el canal de siempre."""
    if (contacto or {}).get("channel") == "SMS" and (contacto or {}).get("phone"):
        enlace = ("" if uses_guest_list else
                  _external_url_for("public_invitation_delivery", kind=link_kind,
                                    token=row.delivery_token))
        ok, err = _send_optional_sms(
            session_db, contacto["phone"],
            _invitation_share_text(session_db, concert, getattr(row, "guest_name", ""), enlace),
            kind="INVITACIONES", nick=(getattr(row, "guest_name", None) or ""))
        if ok or not recipients:
            return ok, err, "SMS", contacto["phone"]
    if not recipients:
        return False, "Sin correo ni teléfono al que enviar.", "Email", ""
    subject, html_body, text_body = (body() if body else _invitation_email_body(session_db, row, None))
    # ⚠️ El Reply-To de un COMPROMISO lo resuelve su propio helper: el de las solicitudes no vale.
    destino_respuesta = (reply_to if reply_to is not None
                         else _invitation_request_reply_to(session_db, row)) or _current_user_email()
    ok, err = _send_optional_email(recipients, subject, html_body, text_body=text_body,
                                   reply_to=destino_respuesta)
    return ok, err, "Email", ", ".join(recipients or [])


@app.post('/invitaciones/evento/<concert_id>/categoria/<category_id>/enviar-todas', endpoint='invitation_category_send_all')
@admin_required
def invitation_category_send_all(concert_id, category_id):
    """Envía por email todas las ASIGNADAS y no enviadas de UNA categoría: solicitudes (completas,
    con la regla de cupo completo) y compromisos (solo las categorías completas, filtrando el correo
    a esta categoría). Recogida en taquilla y sin email se saltan con aviso."""
    session_db = db()
    _cid = None
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        _cid = str(concert.id)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
        cat = next((c for c in categories if str(c.id) == str(_safe_uuid(category_id))), None)
        if not cat:
            abort(404)
        now = _now_madrid()
        sent_n = 0
        skipped_box = 0
        no_email = 0
        failed = 0
        not_complete = 0
        # Mismo tope de tiempo que en el envío de todo el evento: componer y mandar cada correo es
        # lento, y una petición cortada a la mitad deja al usuario sin saber qué salió.
        _t0, _presupuesto, _quedan = time.monotonic(), 45.0, 0
        # --- SOLICITUDES con entradas ASIGNADAS (sin enviar) en esta categoría ---
        _req_ids = {t.assigned_request_id for t in session_db.query(InvitationTicket).filter(
            InvitationTicket.category_id == cat.id, InvitationTicket.status == 'ASSIGNED',
            InvitationTicket.assigned_request_id.isnot(None)).all()}
        _reqs = (session_db.query(InvitationRequest).filter(InvitationRequest.id.in_(list(_req_ids))).all() if _req_ids else [])
        for _i, row in enumerate(_reqs):
            if time.monotonic() - _t0 > _presupuesto:
                _quedan += len(_reqs) - _i
                break
            if (row.status or '') != 'ASIGNADAS':
                continue
            if (row.receiver_mode or '').strip().upper() == 'BOX_OFFICE':
                skipped_box += 1
                continue
            flags = _invitation_request_kind_flags(session_db, row, categories)
            if not flags.get('can_send'):
                not_complete += 1
                continue
            recipients = _dedupe_valid_email_addresses(_invitation_delivery_recipients(session_db, row))
            # Mismo criterio que en el envío de todo el evento: el canal que tenga cada uno.
            _canal = _invitation_mass_contact(session_db, row, recipients)
            if not _canal.get('channel'):
                no_email += 1
                continue
            row.delivery_token = row.delivery_token or _invitation_token()
            # Etiquetas «Nueva» + SENT ANTES de componer (el correo ya sale con las etiquetas).
            # ⚠️ En un SAVEPOINT: si el envío no sale, se deshace SOLO esto. Con un rollback de
            # toda la sesión, cualquier cambio pendiente de otra fila se iba por delante y —lo
            # grave— un fallo a medias podía dejar entradas marcadas como enviadas sin enviarse.
            punto = session_db.begin_nested()
            _via, _destino = 'Email', ', '.join(recipients or [])
            try:
                _invitation_mark_sent_tickets(session_db, row, 'all', now)
                ok, err, _via, _destino = _invitation_mass_send_one(
                    session_db, concert, row, recipients, _canal,
                    uses_guest_list=bool(flags.get('uses_guest_list')))
            except Exception:
                ok = False
            if ok:
                row.status = 'ENVIADAS'
                row.sent_at = now
                row.sent_via = _via
                row.sent_to = _destino
                punto.commit()
                session_db.commit()
                sent_n += 1
            else:
                punto.rollback()
                failed += 1
        # --- COMPROMISOS con entradas ASIGNADAS (sin enviar) en esta categoría, categoría COMPLETA ---
        _cmt_rows = session_db.query(InvitationCommitment).join(
            InvitationTicket, InvitationTicket.assigned_commitment_id == InvitationCommitment.id).filter(
            InvitationTicket.category_id == cat.id, InvitationTicket.status == 'ASSIGNED').distinct().all()
        for _j, row in enumerate(_cmt_rows):
            if time.monotonic() - _t0 > _presupuesto:
                _quedan += len(_cmt_rows) - _j
                break
            _q = _safe_int(_json_dict(row.quantities_json).get(str(cat.id)))
            _tks = session_db.query(InvitationTicket).filter(
                InvitationTicket.assigned_commitment_id == row.id,
                InvitationTicket.category_id == cat.id).all()
            _unsent = [t for t in _tks if (t.status or '') == 'ASSIGNED']
            if not _unsent:
                continue
            if _q > 0 and len(_tks) < _q:
                not_complete += 1
                continue
            recipients = _dedupe_valid_email_addresses(_invitation_guest_live_emails(session_db, row))
            _canal = _invitation_mass_contact(session_db, row, recipients)
            if not _canal.get('channel'):
                no_email += 1
                continue
            row.delivery_token = row.delivery_token or _invitation_token()
            # Etiquetas «Nueva» (ampliación reenviada: el correo lista viejas+nuevas de la categoría)
            # + SENT ANTES de componer, todo en un SAVEPOINT: si el correo no sale, se deshace solo
            # esto y NADA queda marcado como enviado.
            punto = session_db.begin_nested()
            try:
                _invitation_tag_new_tickets(_tks, _tks)
                for t in _unsent:
                    t.status = 'SENT'
                    t.sent_at = now
                    t.updated_at = now
                # Mismo criterio que las solicitudes: el canal que tenga configurado cada uno. El
                # correo de un COMPROMISO lo compone su propio constructor (y su enlace es «c»).
                ok, err, _via, _destino = _invitation_mass_send_one(
                    session_db, concert, row, recipients, _canal, link_kind='c',
                    body=lambda: (_invitation_commitment_email_body(session_db, row, category_id=cat.id)),
                    reply_to=_invitation_commitment_reply_to(session_db, row))
            except Exception:
                ok = False
            if ok:
                punto.commit()
                session_db.commit()
                sent_n += 1
            else:
                punto.rollback()
                failed += 1
        parts = [f'{sent_n} envío(s) realizados de «{cat.name}»']
        if skipped_box:
            parts.append(f'{skipped_box} de taquilla (no se envían)')
        if not_complete:
            parts.append(f'{not_complete} sin el cupo completo (no se envían)')
        if no_email:
            parts.append(f'{no_email} sin correo ni teléfono')
        if failed:
            parts.append(f'{failed} fallidos')
        if _quedan:
            parts.append(f'{_quedan} sin intentar (se paró por tiempo: vuelve a pulsar para seguir)')
        flash(' · '.join(parts) + '.', 'success' if sent_n and not failed else 'warning')
        return redirect(url_for('invitation_event_detail', concert_id=_cid))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo enviar: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=_cid) if _cid else url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/enviar-asignadas', endpoint='invitation_event_send_all')
@admin_required
def invitation_event_send_all(concert_id):
    """Envía por email, de una vez, todas las peticiones del evento que tienen entradas asignadas
    (estado ASIGNADAS). Las de recogida en taquilla (receiver_mode=BOX_OFFICE) NO se envían."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
        rows = (
            session_db.query(InvitationRequest)
            .filter(InvitationRequest.concert_id == concert.id, InvitationRequest.status == 'ASIGNADAS')
            .all()
        )
        sent = 0
        skipped_box = 0
        no_email = 0
        failed = 0
        # ⚠️ Cada envío compone su PDF y sale por SMTP: en un evento con muchas peticiones esto se
        # come el tiempo que el servidor da a una petición y la corta a medias. Se trabaja con TOPE
        # DE TIEMPO (lo enviado ya está commiteado fila a fila) y, si quedan, se dice cuántas para
        # volver a pulsar: al segundo pase solo salen las que faltan.
        _t0, _presupuesto, _quedan = time.monotonic(), 45.0, 0
        for _i, row in enumerate(rows):
            if time.monotonic() - _t0 > _presupuesto:
                _quedan = len(rows) - _i
                break
            if (row.receiver_mode or '').strip().upper() == 'BOX_OFFICE':
                skipped_box += 1
                continue
            flags = _invitation_request_kind_flags(session_db, row, categories)
            if not flags.get('can_send'):
                continue
            recipients = _dedupe_valid_email_addresses(_invitation_delivery_recipients(session_db, row))
            # ⚠️ ENVÍO MASIVO: aquí no se pregunta nada, se usa el canal que tenga configurado CADA
            # UNO (punto único `_invitation_mass_contact` / `_invitation_mass_send_one`).
            _canal = _invitation_mass_contact(session_db, row, recipients)
            if not _canal.get('channel'):
                no_email += 1
                continue
            row.delivery_token = row.delivery_token or _invitation_token()
            # Etiquetas «Nueva» + SENT ANTES de componer (el correo sale con las etiquetas), todo
            # en un SAVEPOINT: si el envío no sale, se deshace solo esto y nada queda marcado.
            _sent_at_r = _now_madrid()
            punto = session_db.begin_nested()
            _via, _destino = 'Email', ', '.join(recipients or [])
            try:
                _invitation_mark_sent_tickets(session_db, row, 'all', _sent_at_r)
                ok, err, _via, _destino = _invitation_mass_send_one(
                    session_db, concert, row, recipients, _canal,
                    uses_guest_list=bool(flags.get('uses_guest_list')))
            except Exception:
                ok = False
            if ok:
                row.status = 'ENVIADAS'
                row.sent_at = _sent_at_r
                row.sent_via = _via
                row.sent_to = _destino
                # Commit por fila: un fallo posterior no revierte las que ya se enviaron de verdad.
                try:
                    punto.commit()
                    session_db.commit()
                    sent += 1
                except Exception:
                    session_db.rollback()
                    failed += 1
            else:
                punto.rollback()
                failed += 1
        session_db.commit()
        parts = []
        if sent:
            parts.append(f'{sent} enviadas')
        if skipped_box:
            parts.append(f'{skipped_box} de taquilla (no se envían)')
        if no_email:
            parts.append(f'{no_email} sin correo ni teléfono')
        if failed:
            parts.append(f'{failed} con error de envío')
        if _quedan:
            parts.append(f'{_quedan} sin llegar a intentarse (se paró para no agotar el tiempo del '
                         f'servidor: vuelve a pulsar «Enviar todas las asignadas» para seguir)')
        if sent:
            flash('Envío masivo: ' + ', '.join(parts) + '.', 'success')
        elif parts:
            flash('No se envió ninguna invitación: ' + ', '.join(parts) + '.', 'warning')
        else:
            flash('No hay invitaciones asignadas pendientes de enviar.', 'info')
        return redirect(url_for('invitation_event_detail', concert_id=concert_id) + '#inv-tab-guests')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo completar el envío masivo: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=concert_id))
    finally:
        session_db.close()


@app.get('/invitaciones/descarga/<token>.pdf', endpoint='invitation_request_download')
def invitation_request_download(token):
    """Descarga las invitaciones REALES de una solicitud en un ÚNICO PDF (todas las entradas, cada una
    con sus páginas), listo para usarse directamente sin descomprimir. Público por token."""
    session_db = db()
    try:
        row = session_db.query(InvitationRequest).filter(InvitationRequest.delivery_token == token).first()
        if not row or (row.status or '') in {'RECHAZADAS', 'ANULADAS'}:
            return _invitation_download_unavailable()
        cat_id = _safe_uuid(request.args.get('category'))
        q = session_db.query(InvitationTicket).filter(InvitationTicket.assigned_request_id == row.id)
        if cat_id:
            q = q.filter(InvitationTicket.category_id == cat_id)
        tickets = q.order_by(InvitationTicket.sector.asc().nullslast(), InvitationTicket.row_label.asc().nullslast(), InvitationTicket.seat_number.asc().nullslast(), InvitationTicket.uploaded_at.asc()).all()
        if not tickets:
            return _invitation_download_unavailable()
        data, added = _invitation_tickets_to_merged_pdf(tickets)
        if not data or added == 0:
            return _invitation_download_unavailable("retry")
        row.downloaded_at = row.downloaded_at or _now_madrid()
        row.downloaded_count = _safe_int(row.downloaded_count) + 1
        _invitation_mark_downloaded(row, cat_id, tickets)
        session_db.commit()
        return send_file(BytesIO(data), mimetype='application/pdf', as_attachment=True, download_name=f'invitaciones_{row.guest_name or "invitado"}.pdf')
    finally:
        session_db.close()


