@app.post('/invitaciones/tickets/<ticket_id>/bloquear', endpoint='invitation_ticket_block')
@admin_required
def invitation_ticket_block(ticket_id):
    """Bloquea/desbloquea UNA entrada (toggle). Una BLOQUEADA no cuenta como aforo disponible y no
    se puede asignar, enviar ni imprimir hasta desbloquearla (vuelve a AVAILABLE). Solo se puede
    bloquear una entrada DISPONIBLE: si está asignada/enviada hay que recuperarla primero."""
    session_db = db()
    try:
        ticket = session_db.get(InvitationTicket, to_uuid(ticket_id))
        if not ticket:
            abort(404)
        _ensure_can_manage_invitations(session_db, ticket.concert)
        cid = ticket.concert_id
        status = (ticket.status or 'AVAILABLE').upper()
        if status == 'BLOCKED':
            ticket.status = 'AVAILABLE'
            msg = 'Invitación desbloqueada: vuelve a estar disponible.'
        elif status == 'AVAILABLE':
            ticket.status = 'BLOCKED'
            msg = 'Invitación bloqueada: no cuenta como disponible ni se puede usar hasta desbloquearla.'
        else:
            raise ValueError('Solo se pueden bloquear invitaciones disponibles: recupérala primero si está asignada, enviada o impresa.')
        ticket.updated_at = _now_madrid()
        session_db.commit()
        flash(msg, 'success')
        return redirect(url_for('invitation_event_detail', concert_id=cid) + '#inv-tab-tickets')
    except Exception as exc:
        session_db.rollback()
        flash(str(exc) if isinstance(exc, ValueError) else f'No se pudo bloquear/desbloquear la entrada: {exc}', 'danger')
        return redirect(url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/tickets/bloquear', endpoint='invitation_tickets_bulk_block')
@admin_required
def invitation_tickets_bulk_block(concert_id):
    """Bloquea (action=block) o desbloquea (action=unblock) en bloque las entradas seleccionadas.
    Solo se bloquean las DISPONIBLES y solo se desbloquean las BLOQUEADAS; el resto de la selección
    queda igual y se informa de cuántas se saltaron."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        tickets = _invitation_bulk_selected_tickets(session_db, concert)
        action = (request.form.get('action') or 'block').strip().lower()
        now = _now_madrid()
        changed = 0
        skipped = 0
        for t in tickets:
            st = (t.status or 'AVAILABLE').upper()
            if action == 'unblock':
                if st == 'BLOCKED':
                    t.status = 'AVAILABLE'
                    t.updated_at = now
                    changed += 1
                else:
                    skipped += 1
            else:
                if st == 'AVAILABLE':
                    t.status = 'BLOCKED'
                    t.updated_at = now
                    changed += 1
                else:
                    skipped += 1
        session_db.commit()
        return jsonify({'ok': True, 'action': action, 'changed': changed, 'skipped': skipped})
    except Exception as exc:
        session_db.rollback()
        return jsonify({'ok': False, 'error': str(exc)}), 400
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/tickets/enviar-seleccion', endpoint='invitation_tickets_bulk_send')
@admin_required
def invitation_tickets_bulk_send(concert_id):
    """Envía por email/WhatsApp/SMS las entradas seleccionadas del plano. Crea una solicitud con «para
    quién son» (guest_*) y «a quién se le mandan» (receiver_*) —mismo componente que las peticiones—,
    le asigna EXACTAMENTE esas entradas y la envía como una solicitud asignada (queda en la lista de
    invitados y las entradas se marcan como enviadas)."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        tickets = _invitation_bulk_selected_tickets(session_db, concert)
        accept_warnings = _truthy(request.form.get('accept_warnings'))
        # No se pueden enviar entradas de un listado (sin PDF) por esta vía.
        _blocked = [t for t in tickets if (t.status or '').upper() == 'BLOCKED']
        if _blocked:
            raise ValueError(f'La selección incluye {len(_blocked)} entrada(s) BLOQUEADA(s): desbloquéalas antes de poder enviarlas.')
        for t in tickets:
            if t.previous_assignment_warning and not accept_warnings:
                raise ValueError(f'La entrada {t.ticket_code or t.pdf_name or ""} ya había sido enviada/asignada antes. Confirma para reutilizarla.')
        per_cat: dict = {}
        for t in tickets:
            per_cat[str(t.category_id)] = per_cat.get(str(t.category_id), 0) + 1
        state = _current_user_state()
        requester_info = {
            'user_id': session.get('user_id'),
            'nick': state.get('nick') or _email_to_nick(state.get('email') or ''),
            'email': state.get('email'),
            'photo_url': state.get('photo_url'),
            'phone': state.get('phone') or '',
        }
        _rfields, requester_info, _no_contact = _invitation_parse_guest_receiver(session_db, request.form, state, requester_info)
        now = _now_madrid()
        row = InvitationRequest(
            concert_id=concert.id,
            request_source='INTERNAL',
            requester_type='USER',
            requester_user_id=_safe_uuid(requester_info.get('user_id')),
            requester_nick=requester_info.get('nick'),
            requester_email=requester_info.get('email'),
            requester_photo_url=requester_info.get('photo_url'),
            created_by_user_id=_safe_uuid(session.get('user_id')),
            created_by_nick=state.get('nick') or _email_to_nick(state.get('email') or ''),
            guest_note=(request.form.get('guest_note') or '').strip(),
            quantities_json=per_cat,
            status='ASIGNADAS',
            assigned_at=now,
            delivery_token=_invitation_token(),
            **_rfields,
        )
        session_db.add(row)
        session_db.flush()
        for t in tickets:
            t.assigned_request_id = row.id
            t.assigned_commitment_id = None
            t.assigned_label = row.guest_name
            t.status = 'ASSIGNED'
            t.assigned_at = now
            t.sent_at = None
            t.updated_at = now
        session_db.commit()  # persistimos solicitud + asignación antes de enviar (si el email falla, se conservan)
        channel = (request.form.get('channel') or 'email').strip().lower()
        extra = request.form.getlist('recipients') + request.form.getlist('extra_emails')
        res = _invitation_send_request(session_db, row, channel, custom_text=(request.form.get('custom_text') or None), extra_recipients=extra)
        return jsonify({
            'ok': bool(res.get('ok')), 'channel': channel, 'url': res.get('url'),
            'request_id': str(row.id), 'recipients': res.get('recipients'), 'error': res.get('error'),
        })
    except Exception as exc:
        session_db.rollback()
        return jsonify({'ok': False, 'error': str(exc)}), 400
    finally:
        session_db.close()


@app.post('/invitaciones/compromisos/<commitment_id>/categoria', endpoint='invitation_commitment_set_category')
@admin_required
def invitation_commitment_set_category(commitment_id):
    """Añade o edita UNA «petición» (categoría) de un compromiso sin tocar las demás: fija la
    cantidad de esa categoría en quantities_json (qty<=0 la elimina)."""
    session_db = db()
    _cid_concert = None
    try:
        row = session_db.get(InvitationCommitment, to_uuid(commitment_id))
        if not row:
            abort(404)
        _ensure_can_manage_invitations(session_db, row.concert)
        _cid_concert = row.concert_id
        cat_id = _safe_uuid(request.form.get('category_id'))
        cat = session_db.get(InvitationCategory, cat_id) if cat_id else None
        if not cat or cat.concert_id != row.concert_id:
            raise ValueError('Selecciona una categoría válida.')
        qty = _safe_int(request.form.get('qty'))
        mode = (request.form.get('mode') or 'add').strip().lower()
        q = _json_dict(row.quantities_json)
        existing = _safe_int(q.get(str(cat.id)))
        if mode == 'add':
            # Añadir petición = ADICIONAL a lo que ya hubiera de esa categoría (aunque ya hubiera
            # peticiones o envíos en ella): se suma al cupo de la categoría.
            if qty > 0:
                q[str(cat.id)] = existing + qty
        else:  # edición: fija el número (0 la elimina)
            if qty > 0:
                q[str(cat.id)] = qty
            else:
                q.pop(str(cat.id), None)
        q.pop('TOTAL', None)
        row.quantities_json = q
        # Recalcular estado desde entradas + nuevo cupo (si al ampliar quedan por asignar → parcial).
        session_db.flush()
        _invitation_sync_commitment_status(session_db, row)
        row.updated_at = _now_madrid()
        session_db.commit()
        flash(('Petición de «' + cat.name + '» guardada en el compromiso «' + (row.name or '') + '».') if qty > 0
              else ('Petición de «' + cat.name + '» eliminada del compromiso.'), 'success')
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo guardar la petición del compromiso: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(url_for('invitation_event_detail', concert_id=_cid_concert) if _cid_concert else url_for('invitations_view', tab='gestionar'))


@app.post('/invitaciones/compromisos/<commitment_id>/categoria/eliminar', endpoint='invitation_commitment_category_delete')
@admin_required
def invitation_commitment_category_delete(commitment_id):
    """Elimina UNA «petición» (categoría) de un compromiso: libera sus entradas ASIGNADAS (vuelven
    a disponibles automáticamente) y quita la categoría de quantities_json. Si hay entradas ya
    enviadas/descargadas/impresas en esa categoría, exige decidir con `mode` (recover|lost); sin él
    responde needs_confirm para la alerta Recuperar/Descartar. No afecta al resto de categorías."""
    _ajax = _truthy(request.form.get('ajax'))
    session_db = db()
    _cid_concert = None
    try:
        row = session_db.get(InvitationCommitment, to_uuid(commitment_id))
        if not row:
            abort(404)
        _ensure_can_manage_invitations(session_db, row.concert)
        _cid_concert = row.concert_id
        cat_id = _safe_uuid(request.form.get('category_id'))
        cat = session_db.get(InvitationCategory, cat_id) if cat_id else None
        if not cat or cat.concert_id != row.concert_id:
            raise ValueError('Categoría no válida.')
        tickets = session_db.query(InvitationTicket).filter(
            InvitationTicket.assigned_commitment_id == row.id,
            InvitationTicket.category_id == cat.id).all()
        mode = (request.form.get('mode') or '').strip().lower()
        _dl = _json_dict(getattr(row, 'downloaded_categories_json', None))
        sent_f = any((t.status or '') in {'SENT', 'DELIVERED', 'PICKED_UP', 'DISPONIBLES_TAQUILLA'} for t in tickets)
        printed_f = any((t.status or '') == 'PRINTED' for t in tickets)
        downloaded_f = bool(_dl.get(str(cat.id)))
        if tickets and (sent_f or printed_f or downloaded_f) and mode not in {'recover', 'lost'}:
            info = {'ok': False, 'needs_confirm': True, 'sent': sent_f, 'downloaded': bool(downloaded_f),
                    'printed': printed_f, 'ticket_count': len(tickets)}
            if _ajax:
                return jsonify(info)
            flash('Estas invitaciones ya se enviaron, descargaron o imprimieron: confirma en el menú si recuperarlas o descartarlas.', 'warning')
            return redirect(url_for('invitation_event_detail', concert_id=_cid_concert))
        recovered, discarded = _invitation_release_apply(tickets, mode=mode, entity_label=f'la petición de {cat.name} del compromiso «{row.name}»')
        q = _json_dict(row.quantities_json)
        q.pop(str(cat.id), None)
        q.pop('TOTAL', None)
        row.quantities_json = q
        if _dl.pop(str(cat.id), None) is not None:
            row.downloaded_categories_json = _dl
        row.updated_at = _now_madrid()
        session_db.commit()
        msg = f'Petición de «{cat.name}» eliminada del compromiso «{row.name or ""}».' + ((' ' + _invitation_release_summary(recovered, discarded)) if tickets else '')
        if _ajax:
            return jsonify({'ok': True, 'message': msg})
        flash(msg, 'success')
    except Exception as exc:
        session_db.rollback()
        if _ajax:
            return jsonify({'ok': False, 'error': str(exc)}), 400
        flash(f'No se pudo eliminar la petición: {exc}', 'danger')
    finally:
        session_db.close()
    return redirect(url_for('invitation_event_detail', concert_id=_cid_concert) if _cid_concert else url_for('invitations_view', tab='gestionar'))


def _plan_pdf_image(url: str, _cache: dict = {}):
    """ImageReader de una URL (con caché y timeout); None si no carga (el PDF sigue sin la foto)."""
    if not url or not str(url).startswith('http'):
        return None
    if url in _cache:
        return _cache[url]
    img = None
    try:
        import urllib.request as _ur
        from reportlab.lib.utils import ImageReader
        data = _ur.urlopen(url, timeout=4).read()
        img = ImageReader(io.BytesIO(data))
        img.getSize()
    except Exception:
        img = None
    _cache[url] = img
    return img


def _invitation_plan_pdf_build(*, logo_url: str, header_title: str, header_meta: str,
                               sector_title: str, sector: dict, cards: list) -> bytes:
    """PDF A3 APAISADO del plano de un sector: logo de la empresa arriba-izquierda, cabecera del
    evento, título «Reparto Invitados <sector>», el plano completo (lo más grande posible sin
    cortarse) y, abajo, tarjetas con los pendientes de asignar (una fila; el resto pasa a páginas
    siguientes empezando arriba). Función PURA sobre payloads (testeable sin BD)."""
    from reportlab.lib.pagesizes import A3, landscape
    from reportlab.pdfgen import canvas as _canvas
    from reportlab.lib.colors import HexColor

    PAGE_W, PAGE_H = landscape(A3)
    M = 26.0
    buf = io.BytesIO()
    c = _canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H))

    def _tx(t):
        return '' if t is None else str(t)

    def _trunc(text, font, size, max_w):
        text = _tx(text)
        if c.stringWidth(text, font, size) <= max_w:
            return text
        while text and c.stringWidth(text + '…', font, size) > max_w:
            text = text[:-1]
        return (text + '…') if text else ''

    def _circle_img(img, x, y, d):
        c.saveState()
        pth = c.beginPath()
        pth.circle(x + d / 2.0, y + d / 2.0, d / 2.0)
        c.clipPath(pth, stroke=0, fill=0)
        c.drawImage(img, x, y, d, d, preserveAspectRatio=True, anchor='c', mask='auto')
        c.restoreState()

    GREY = HexColor('#6b7280')
    INK = HexColor('#1f2430')
    LINE = HexColor('#e1e6ed')
    GREEN = HexColor('#16803a')
    GREEN_BG = HexColor('#eef7f0')
    RED = HexColor('#b3261e')
    RED_BG = HexColor('#fdecea')
    MISS_BG = HexColor('#e5e8ee')
    OFF_BG = HexColor('#cdd3dd')
    AMBER = HexColor('#ffc107')

    # ---------- cabecera (página 1) ----------
    top = PAGE_H - M
    logo = _plan_pdf_image(logo_url)
    lx = M
    if logo:
        try:
            iw, ih = logo.getSize()
            lh = 40.0
            lw = lh * (iw / float(ih or 1))
            lw = min(lw, 170.0)
            c.drawImage(logo, M, top - lh, lw, lh, preserveAspectRatio=True, anchor='sw', mask='auto')
            lx = M + lw + 16
        except Exception:
            pass
    c.setFillColor(INK)
    c.setFont('Helvetica-Bold', 15)
    c.drawString(lx, top - 18, _trunc(header_title, 'Helvetica-Bold', 15, PAGE_W - lx - M))
    c.setFillColor(GREY)
    c.setFont('Helvetica', 10)
    c.drawString(lx, top - 34, _trunc(header_meta, 'Helvetica', 10, PAGE_W - lx - M))
    y = top - 52
    c.setStrokeColor(LINE)
    c.setLineWidth(0.8)
    c.line(M, y, PAGE_W - M, y)

    # ---------- título ----------
    y -= 24
    c.setFillColor(INK)
    c.setFont('Helvetica-Bold', 17)
    c.drawCentredString(PAGE_W / 2.0, y, _tx(sector_title))
    y -= 12

    # ---------- geometría de tarjetas ----------
    CARD_H, CARD_GAP = 108.0, 8.0
    content_w = PAGE_W - 2 * M
    per_row = max(int((content_w + CARD_GAP) // (150.0 + CARD_GAP)), 1)
    card_w = (content_w - (per_row - 1) * CARD_GAP) / per_row
    cards = list(cards or [])
    first_row = cards[:per_row]
    rest = cards[per_row:]
    cards_band = (CARD_H + 14.0) if first_row else 0.0

    # ---------- plano ----------
    rows = list((sector or {}).get('rows') or [])
    plan_top = y - 6
    plan_bottom = M + cards_band
    plan_h = max(plan_top - plan_bottom, 60.0)
    LABEL_W = 52.0
    STRIP_H = 13.0
    ROW_GAP = 5.0

    def _units(cell):
        t = cell.get('type')
        if t == 'stair':
            return 0.6
        if t == 'block':
            return float(len(cell.get('seats') or []))
        return 1.0

    max_units = 1.0
    for r in rows:
        u = sum(_units(cl) for cl in (r.get('layout') or []))
        max_units = max(max_units, u)
    n_rows = max(len(rows), 1)
    # Lo MÁS GRANDE posible sin cortarse: la celda solo la limitan el ancho y el alto disponibles
    # (tope 52pt para que un sector pequeño no salga desproporcionado).
    cell = min(52.0, (content_w - LABEL_W) / max_units,
               (plan_h - n_rows * (STRIP_H + ROW_GAP)) / n_rows)
    cell = max(cell, 7.0)
    row_h = cell + STRIP_H + ROW_GAP
    plan_w_real = LABEL_W + max_units * cell
    x0 = M + max((content_w - plan_w_real) / 2.0, 0)
    yy = plan_top

    def _seat_colors(status, color_hex):
        st = (status or '').upper()
        if st == 'AVAILABLE':
            return GREEN, GREEN_BG, GREEN
        if st == 'BLOCKED':
            # Bloqueada: gris relleno — no disponible, sin invitado.
            return GREY, HexColor('#e5e7eb'), INK
        if st in ('SENT', 'DELIVERED', 'PICKED_UP', 'PRINTED', 'DISPONIBLES_TAQUILLA', 'RECOGIDAS_TAQUILLA', 'ENTREGADAS_MANO', 'LOST'):
            base = HexColor(color_hex) if color_hex else RED
            return base, RED_BG, RED
        base = HexColor(color_hex) if color_hex else GREY
        return base, HexColor('#ffffff'), INK

    num_size = max(min(cell * 0.34, 8.0), 4.5)
    for r in rows:
        yy -= row_h
        c.setFillColor(GREY)
        c.setFont('Helvetica-Bold', 8)
        c.drawString(x0, yy + cell / 2.0 - 3, _trunc('Fila ' + _tx(r.get('row_label')), 'Helvetica-Bold', 8, LABEL_W - 6))
        xx = x0 + LABEL_W
        for cl in (r.get('layout') or []):
            t = cl.get('type')
            if t == 'block':
                seats = cl.get('seats') or []
                bw = len(seats) * cell
                col = cl.get('color') or '#999999'
                try:
                    bcol = HexColor(col)
                except Exception:
                    bcol = GREY
                name = _tx(cl.get('name') or 'Asignada')
                if cl.get('link'):
                    name += ' · ' + _tx(cl.get('link'))
                c.setFillColor(bcol)
                c.setFont('Helvetica-Bold', 6.5)
                c.drawCentredString(xx + bw / 2.0, yy + cell + 5.5, _trunc(name, 'Helvetica-Bold', 6.5, bw + 26))
                c.setStrokeColor(bcol)
                c.setLineWidth(1.6)
                c.line(xx + 1, yy + cell + 2.2, xx + bw - 1, yy + cell + 2.2)
                for st_ in seats:
                    stroke, fill, numcol = _seat_colors(st_.get('status'), col)
                    c.setStrokeColor(stroke)
                    c.setFillColor(fill)
                    c.setLineWidth(1.1)
                    c.roundRect(xx + 1, yy + 1, cell - 2, cell - 2, 2.5, stroke=1, fill=1)
                    c.setFillColor(numcol)
                    c.setFont('Helvetica-Bold', num_size)
                    c.drawCentredString(xx + cell / 2.0, yy + cell / 2.0 - num_size / 2.8, _tx(st_.get('seat_number') or st_.get('location') or ''))
                    xx += cell
            elif t == 'seat':
                st_ = cl.get('seat') or {}
                stroke, fill, numcol = _seat_colors(st_.get('status'), st_.get('assignee_color'))
                c.setStrokeColor(stroke)
                c.setFillColor(fill)
                c.setLineWidth(1.1)
                c.roundRect(xx + 1, yy + 1, cell - 2, cell - 2, 2.5, stroke=1, fill=1)
                c.setFillColor(numcol)
                c.setFont('Helvetica-Bold', num_size)
                c.drawCentredString(xx + cell / 2.0, yy + cell / 2.0 - num_size / 2.8, _tx(st_.get('seat_number') or st_.get('location') or ''))
                xx += cell
            elif t in ('missing',):
                c.setFillColor(OFF_BG if cl.get('off') else MISS_BG)
                c.roundRect(xx + 1, yy + 1, cell - 2, cell - 2, 2.5, stroke=0, fill=1)
                xx += cell
            elif t == 'gap':
                c.setStrokeColor(LINE)
                c.setLineWidth(0.8)
                c.setDash(2, 2)
                c.roundRect(xx + 1, yy + 1, cell - 2, cell - 2, 2.5, stroke=1, fill=0)
                c.setDash()
                xx += cell
            elif t == 'stair':
                sw = 0.6 * cell
                c.setStrokeColor(HexColor('#007ca2'))
                c.setLineWidth(0.9)
                c.setDash(2, 2)
                c.line(xx + 1.5, yy + 1, xx + 1.5, yy + cell - 1)
                c.line(xx + sw - 1.5, yy + 1, xx + sw - 1.5, yy + cell - 1)
                c.setDash()
                step = (cell - 6) / 3.0
                for i_ in range(3):
                    sy = yy + 3 + i_ * step
                    c.line(xx + 3, sy, xx + sw - 3, sy)
                xx += sw
            else:   # spacer
                xx += cell

    # ---------- tarjetas de pendientes ----------
    def _draw_card(x, y_, it):
        c.setStrokeColor(LINE)
        c.setFillColor(HexColor('#ffffff'))
        c.setLineWidth(1)
        c.roundRect(x, y_, card_w, CARD_H, 7, stroke=1, fill=1)
        pad = 7.0
        ph = 26.0
        img = _plan_pdf_image(_tx(it.get('guest_photo')))
        tx0 = x + pad
        if img:
            _circle_img(img, x + pad, y_ + CARD_H - pad - ph, ph)
            tx0 = x + pad + ph + 6
        c.setFillColor(INK)
        c.setFont('Helvetica-Bold', 8.5)
        c.drawString(tx0, y_ + CARD_H - pad - 10, _trunc(it.get('name'), 'Helvetica-Bold', 8.5, x + card_w - pad - tx0))
        yline = y_ + CARD_H - pad - 24
        if it.get('guest_link_text'):
            lx2 = x + pad
            limg = _plan_pdf_image(_tx(it.get('guest_link_logo')))
            if limg:
                try:
                    iw, ih = limg.getSize()
                    lw2 = min(10.0 * (iw / float(ih or 1)), 22.0)
                    c.drawImage(limg, lx2, yline - 2, lw2, 10, preserveAspectRatio=True, anchor='sw', mask='auto')
                    lx2 += lw2 + 4
                except Exception:
                    pass
            c.setFillColor(GREY)
            c.setFont('Helvetica', 7)
            c.drawString(lx2, yline, _trunc(it.get('guest_link_text'), 'Helvetica', 7, x + card_w - pad - lx2))
            yline -= 13
        if it.get('requester_name'):
            lx2 = x + pad
            c.setFillColor(GREY)
            c.setFont('Helvetica', 7)
            c.drawString(lx2, yline, 'Pedido por:')
            lx2 += c.stringWidth('Pedido por:', 'Helvetica', 7) + 4
            rimg = _plan_pdf_image(_tx(it.get('requester_photo')))
            if rimg:
                _circle_img(rimg, lx2, yline - 2, 10)
                lx2 += 14
            c.drawString(lx2, yline, _trunc(it.get('requester_name'), 'Helvetica', 7, x + card_w - pad - lx2))
        asg = _safe_int(it.get('assigned'))
        tot = _safe_int(it.get('qty_total'))
        if asg <= 0:
            bbg, bfg = HexColor('#eef0f3'), GREY
        elif asg < tot:
            bbg, bfg = AMBER, HexColor('#3a2f00')
        else:
            bbg, bfg = HexColor('#d7f2df'), HexColor('#116330')
        btxt = f'Asignadas {asg}/{tot}'
        bw2 = c.stringWidth(btxt, 'Helvetica-Bold', 7.5) + 12
        c.setFillColor(bbg)
        c.roundRect(x + pad, y_ + pad, bw2, 14, 7, stroke=0, fill=1)
        c.setFillColor(bfg)
        c.setFont('Helvetica-Bold', 7.5)
        c.drawString(x + pad + 6, y_ + pad + 4, btxt)

    if first_row:
        cx = M
        for it in first_row:
            _draw_card(cx, M, it)
            cx += card_w + CARD_GAP
    # páginas siguientes: filas desde ARRIBA
    while rest:
        c.showPage()
        yy2 = PAGE_H - M - CARD_H
        while rest and yy2 >= M:
            cx = M
            for it in rest[:per_row]:
                _draw_card(cx, yy2, it)
                cx += card_w + CARD_GAP
            rest = rest[per_row:]
            yy2 -= CARD_H + CARD_GAP
    c.showPage()
    c.save()
    return buf.getvalue()


def _invitation_plan_share_token(concert_id, category_id, sector_name) -> str:
    from itsdangerous import URLSafeSerializer
    return URLSafeSerializer(app.secret_key, salt='inv-plan-share').dumps([str(concert_id), str(category_id), str(sector_name or '')])


app.jinja_env.globals['invitation_plan_share_url'] = (
    lambda concert_id, category_id, sector: _external_url_for(
        'public_invitation_plan_pdf', token=_invitation_plan_share_token(concert_id, category_id, sector)))


def _plan_share_ensure(session_db, category, sector_name) -> str:
    """Devuelve (creándolo si hace falta) el token del enlace de «reparto en vivo» del sector."""
    data = dict(_json_dict(getattr(category, 'plan_share_json', None)))
    key = str(sector_name or '')
    ent = dict(data.get(key) or {})
    if not ent.get('token'):
        ent = {'token': _invitation_token(), 'created_at': _now_madrid().isoformat()}
        data[key] = ent
        category.plan_share_json = data
        category.updated_at = _now_madrid()
        session_db.commit()
    return ent['token']


def _plan_share_revoke(session_db, category, sector_name) -> bool:
    data = dict(_json_dict(getattr(category, 'plan_share_json', None)))
    key = str(sector_name or '')
    if key in data:
        data.pop(key, None)
        category.plan_share_json = data
        category.updated_at = _now_madrid()
        session_db.commit()
        return True
    return False


def _plan_share_find(session_db, token):
    """(category, sector) del token de reparto, o (None, None). El token vive en plan_share_json."""
    if not token:
        return None, None
    from sqlalchemy import String
    for cat in session_db.query(InvitationCategory).filter(
            InvitationCategory.plan_share_json.cast(String).contains(str(token))).all():
        for sector_name, ent in _json_dict(cat.plan_share_json).items():
            if (ent or {}).get('token') == token:
                return cat, sector_name
    return None, None


def _invitation_plan_view_context(session_db, concert, category, sector_name) -> dict:
    """Datos comunes del reparto de un sector (los usan el PDF y la página en vivo)."""
    ctx = _invitation_assign_context(session_db, concert, _invitation_get_categories(session_db, concert, ensure_defaults=False))
    groups = ctx['ticket_groups_by_category'].get(str(category.id), [])
    sector = next((g for g in groups if str(g.get('sector')) == str(sector_name)), None) or (groups[0] if groups else {'rows': [], 'sector': sector_name})
    cards = [x for x in ctx['pending_assignments'].get(str(category.id), []) if _safe_int(x.get('qty')) > 0]
    event = _invitation_event_payload(session_db, concert)
    header_title = ' · '.join([x for x in [(event.get('artist_names') or '').strip(), ((getattr(concert, 'festival_name', None) or '') or '').strip()] if x]) or 'Invitaciones'
    header_meta = ' · '.join([x for x in [
        (event.get('city') or '').strip(),
        (event.get('venue') or '').strip(),
        (event.get('date_label') or '').strip(),
        (('Hora: ' + event.get('show_time')) if (event.get('show_time') or '').strip() else ''),
    ] if x])
    arts = event.get('artists') or []
    return {
        'sector': sector,
        'cards': cards,
        'header_title': header_title,
        'header_meta': header_meta,
        'logo_url': _invitation_event_logo_url(session_db, concert, external=True),
        'sector_title': f"Reparto Invitados {sector.get('sector') or ''}".strip(),
        'sector_name': str(sector.get('sector') or sector_name or ''),
        # Foto para el bocadillo de cabecera de la página en vivo: cartel del evento o foto del artista.
        'event_photo': (event.get('poster_url') or '').strip() or ((arts[0].get('photo_url') or '').strip() if arts else ''),
    }


def _invitation_plan_email_body(session_db, concert, category, sector_name, url, custom_text=None) -> tuple:
    """(subject, html, text) del correo de compartir el reparto EN VIVO: misma cabecera que los
    correos de invitaciones + botón al enlace (la página se actualiza sola con cada cambio)."""
    event = _invitation_event_payload(session_db, concert)
    esc = lambda x: html.escape(str(x or ''))
    artist_name = (event.get('artist_names') or '').strip()
    event_name = ((getattr(concert, 'festival_name', None) or '') or '').strip()
    subject = 'Visionado plano asientos · Sector ' + str(sector_name or '') + (' · ' + artist_name if artist_name else '')
    logo = _invitation_event_logo_url(session_db, concert, external=True)
    meta_rows = [(k, v) for k, v in [('Evento', event_name), ('Ciudad', (event.get('city') or '').strip()),
                                     ('Recinto', (event.get('venue') or '').strip()),
                                     ('Fecha', (event.get('date_label') or '').strip()),
                                     ('Hora', (event.get('show_time') or '').strip())] if v]
    meta_html = ''.join(f'<tr><td style="padding:2px 10px 2px 0;color:#6b7280">{esc(k)}</td><td style="padding:2px 0;color:#111"><strong>{esc(v)}</strong></td></tr>' for k, v in meta_rows)
    if custom_text and custom_text.strip():
        body_paras = ''.join(f'<p style="margin:0 0 10px;text-align:justify">{esc(pp.strip())}</p>' for pp in custom_text.split('\n') if pp.strip())
    else:
        body_paras = '<p style="margin:0 0 10px;text-align:justify">Aquí tienes el reparto de invitados actualizado. El enlace muestra siempre la última versión con los cambios que se vayan haciendo.</p>'
    html_body = f"""
    <div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#111">
      {f'<div style="text-align:right;margin-bottom:6px"><img src="{esc(logo)}" style="max-height:58px;max-width:200px" alt="Logo"></div>' if logo else ''}
      <h2 style="margin:0 0 4px">{esc(artist_name or 'Invitaciones')}</h2>
      <div style="font-size:15px;font-weight:bold;margin:0 0 10px;color:#333">Visionado plano asientos · Sector {esc(sector_name)}</div>
      <table style="border-collapse:collapse;font-size:13px;margin:0 0 14px">{meta_html}</table>
      {body_paras}
      <div style="margin:18px 0"><a href="{esc(url)}" style="background:#E33D48;color:#fff;text-decoration:none;padding:12px 22px;border-radius:10px;font-weight:bold;display:inline-block">Ver el reparto actualizado</a></div>
      <p style="color:#6b7280;font-size:12px">Si el botón no funciona, copia este enlace: {esc(url)}</p>
    </div>
    """
    text_body = f"Visionado plano asientos · Sector {sector_name}\n\nEnlace (siempre actualizado): {url}"
    return subject, html_body, text_body


@app.post('/invitaciones/evento/<concert_id>/plano/<category_id>/compartir', endpoint='invitation_plan_share_link')
@admin_required
def invitation_plan_share_link(concert_id, category_id):
    """Crea (o reutiliza) el enlace del reparto EN VIVO y devuelve la URL para WhatsApp/SMS."""
    session_db = db()
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
        cat = next((c for c in categories if str(c.id) == str(_safe_uuid(category_id))), None)
        if not cat:
            abort(404)
        sector = (request.args.get('sector') or request.form.get('sector') or '').strip()
        token = _plan_share_ensure(session_db, cat, sector)
        link = _external_url_for('public_invitation_plan', token=token)
        channel = (request.form.get('channel') or '').strip().lower()
        event = _invitation_event_payload(session_db, concert)
        artist_name = (event.get('artist_names') or '').strip()
        msg = f"Visionado plano asientos · Sector {sector}" + (f" · {artist_name}" if artist_name else '') + "\n\n" + link
        if channel == 'whatsapp':
            url = 'https://wa.me/?text=' + quote_plus(msg)
        elif channel == 'sms':
            url = 'sms:?&body=' + quote_plus(msg)
        else:
            url = link
        return jsonify({'ok': True, 'url': url, 'channel': channel or 'link'})
    except Exception as exc:
        session_db.rollback()
        return jsonify({'ok': False, 'error': str(exc)}), 400
    finally:
        session_db.close()


@app.post('/invitaciones/evento/<concert_id>/plano/<category_id>/enviar', endpoint='invitation_plan_share_send')
@admin_required
def invitation_plan_share_send(concert_id, category_id):
    """Envía por email el enlace del reparto EN VIVO (modal de envío con vista previa, como el
    envío de invitaciones). El campo category_id del modal transporta aquí el SECTOR."""
    session_db = db()
    _cid = None
    try:
        concert = session_db.get(Concert, to_uuid(concert_id))
        if not concert:
            abort(404)
        _ensure_can_manage_invitations(session_db, concert)
        _cid = str(concert.id)
        categories = _invitation_get_categories(session_db, concert, ensure_defaults=False)
        cat = next((c for c in categories if str(c.id) == str(_safe_uuid(category_id))), None)
        if not cat:
            abort(404)
        sector = (request.form.get('sector') or request.form.get('category_id') or '').strip()
        recipients = _dedupe_valid_email_addresses(request.form.getlist('recipients') + request.form.getlist('extra_emails'))
        if not recipients:
            raise ValueError('Añade al menos un correo de destino.')
        token = _plan_share_ensure(session_db, cat, sector)
        link = _external_url_for('public_invitation_plan', token=token)
        subject, html_body, text_body = _invitation_plan_email_body(session_db, concert, cat, sector, link, custom_text=(request.form.get('custom_text') or None))
        ok, err = _send_optional_email(recipients, subject, html_body, text_body=text_body, reply_to=_current_user_email())
        if ok:
            flash('Reparto compartido por email a: ' + ', '.join(recipients) + '.', 'success')
        else:
            flash(f'No se pudo enviar el email: {err or "SMTP no configurado"}', 'warning')
        return redirect(url_for('invitation_event_detail', concert_id=_cid))
    except Exception as exc:
        session_db.rollback()
        flash(f'No se pudo compartir el reparto: {exc}', 'danger')
        return redirect(url_for('invitation_event_detail', concert_id=_cid) if _cid else url_for('invitations_view', tab='gestionar'))
    finally:
        session_db.close()


