def _home_design_tasks(limit: int = 12) -> list[dict]:
    """LO QUE DISEÑO TIENE PENDIENTE, agrupado POR PROYECTO discográfico (módulo de Inicio).

    Una fila por proyecto y, dentro, **una subtarea por cosa**: la portada y cada creatividad que se
    le haya pedido. Cada una con **los días que faltan** para entregarla, que es lo que hay que
    mirar. Así todo lo de diseño de un lanzamiento se ve junto y no repartido."""
    estado = _current_user_state() or {}
    yo = str(estado.get("user_id") or "")
    if not yo:
        return []
    session_db = db()
    try:
        de_diseno = yo in [str(x) for x in _department_user_ids(session_db, "Diseño")]
        if not (de_diseno or int(estado.get("role") or 0) == 10):
            return []
        filas = []
        proyectos = (session_db.query(DiscoProject)
                     .options(joinedload(DiscoProject.artist))
                     .filter(func.upper(func.coalesce(DiscoProject.status, "ACTIVO")) == "ACTIVO")
                     .order_by(DiscoProject.release_date.asc().nullslast()).limit(200).all())
        for p in proyectos:
            subtareas = []
            # La PORTADA, si nos toca a nosotros y todavía no está entregada.
            try:
                art = _disco_artwork_state(session_db, p)
                if (art.get("who") or "").upper() == "US" and art.get("requested") and not art.get("delivered"):
                    subtareas.append({"label": "Portada", "icon": "fa-image",
                                      "due_label": art.get("due_label") or "",
                                      "days": _disco_days_left_label(art.get("due_date")),
                                      "late": bool(art.get("due_date") and art["due_date"] < today_local())})
            except Exception:
                app.logger.exception("[diseño] no se pudo leer la portada del proyecto")
            # Y cada CREATIVIDAD solicitada que aún no se ha subido.
            try:
                cre = _disco_creatives_state(session_db, p)
                vence = cre.get("due_date")
                for fila in (cre.get("rows") or []):
                    if (fila.get("status") or "").upper() != "SOLICITADA":
                        continue
                    subtareas.append({"label": fila["label"], "icon": fila.get("icon") or "fa-shapes",
                                      "due_label": cre.get("due_label") or "",
                                      "days": _disco_days_left_label(vence),
                                      "late": bool(vence and vence < today_local())})
            except Exception:
                app.logger.exception("[diseño] no se pudieron leer las creatividades del proyecto")
            if not subtareas:
                continue
            artista = getattr(p, "artist", None)
            filas.append({
                "id": str(p.id),
                "title": _disco_project_title(p),
                "artist_name": (getattr(artista, "name", "") or ""),
                "artist_photo": (getattr(artista, "photo_url", "") or ""),
                "release_label": (p.release_date.strftime("%d/%m/%Y") if getattr(p, "release_date", None) else ""),
                "tasks": subtareas,
                "late": any(t["late"] for t in subtareas),
                "url": url_for("disco_project_detail", project_id=p.id, tab="calendario"),
            })
            if len(filas) >= limit:
                break
        return filas
    except Exception:
        app.logger.exception("[diseño] no se pudieron montar las tareas de diseño")
        return []
    finally:
        session_db.close()


def _home_press_tasks(limit: int = 12) -> list[dict]:
    """NOTAS DE PRENSA pendientes (módulo de Inicio de **promoción** y de **diseño**).

    A cada uno lo suyo: promoción **redactarla** y después **enviarla**; diseño **el gráfico**. Con el
    plazo (el lunes previo al lanzamiento) y en rojo si ya se pasó."""
    estado = _current_user_state() or {}
    yo = str(estado.get("user_id") or "")
    if not yo:
        return []
    session_db = db()
    try:
        de_promo = yo in _disco_press_people(session_db, "text")
        de_diseno = yo in _disco_press_people(session_db, "design")
        if not (de_promo or de_diseno or int(estado.get("role") or 0) == 10):
            return []
        if int(estado.get("role") or 0) == 10:
            de_promo = de_diseno = True
        filas = []
        proyectos = (session_db.query(DiscoProject)
                     .options(joinedload(DiscoProject.artist))
                     .filter(func.upper(func.coalesce(DiscoProject.status, "ACTIVO")) == "ACTIVO")
                     .order_by(DiscoProject.release_date.asc().nullslast()).limit(200).all())
        for p in proyectos:
            pr = _disco_press_state(session_db, p)
            plan_pedido = False
            if de_promo:
                _pl = _disco_plan_state(session_db, p)
                plan_pedido = bool(_pl.get("promo_asked") and not _pl.get("promo_done"))
            # Entra si hay nota de prensa por hacer O un plan de promoción pedido.
            if (not pr["requested"] or pr["sent"]) and not plan_pedido:
                continue
            tareas = []
            if de_promo and not pr["text_done"]:
                tareas.append({"key": "text", "label": "Redactar la nota de prensa",
                               "icon": "fa-file-lines"})
            # …y el PLAN DE PROMOCIÓN que les haya pedido el sello (es de promoción, como la nota).
            if de_promo:
                plan_st = _disco_plan_state(session_db, p)
                if plan_st.get("promo_asked") and not plan_st.get("promo_done"):
                    tareas.append({"key": "promo_plan", "label": "Preparar el plan de promoción",
                                   "icon": "fa-bullhorn"})
            if de_diseno and not pr["design_done"]:
                tareas.append({"key": "design", "label": "Diseño de la nota de prensa",
                               "icon": "fa-palette"})
            if de_promo and pr["text_done"]:
                tareas.append({"key": "send", "label": "Enviar la nota de prensa",
                               "icon": "fa-paper-plane"})
            if not tareas:
                continue
            artista = getattr(p, "artist", None)
            filas.append({
                "id": str(p.id),
                "title": _disco_project_title(p),
                "artist_name": (getattr(artista, "name", "") or ""),
                "artist_photo": (getattr(artista, "photo_url", "") or ""),
                "release_label": (p.release_date.strftime("%d/%m/%Y")
                                  if getattr(p, "release_date", None) else ""),
                "due_label": pr["due_label"],
                "late": pr["late"],
                "note": pr["note"],
                "requested_by": pr["requested_by"],
                "tasks": tareas,
                "url": url_for("disco_project_detail", project_id=p.id, tab="calendario"),
            })
            if len(filas) >= limit:
                break
        return filas
    except Exception:
        app.logger.exception("[inicio] no se pudieron leer las notas de prensa")
        return []
    finally:
        session_db.close()


def _home_disco_logistics(limit: int = 12) -> list[dict]:
    """LA LOGÍSTICA QUE ME HAN PEDIDO de un proyecto discográfico (módulo de Inicio).

    Es de la PERSONA (se le pide a alguien de producción por su nombre), así que no depende de ningún
    permiso de sección: sale a quien se le ha pedido y desaparece en cuanto la marca montada."""
    yo = str((_current_user_state() or {}).get("user_id") or "")
    if not yo:
        return []
    session_db = db()
    try:
        filas = []
        proyectos = (session_db.query(DiscoProject)
                     .options(joinedload(DiscoProject.artist))
                     .filter(func.upper(func.coalesce(DiscoProject.status, "ACTIVO")) == "ACTIVO")
                     .order_by(DiscoProject.release_date.asc().nullslast()).limit(200).all())
        cerradas = False
        for p in proyectos:
            estado = _disco_logistics_state(session_db, p)
            if not (estado["yes"] and estado["requested"]) or estado["done"]:
                continue
            if estado["user_id"] != yo:
                continue
            # Red de seguridad: si ya está SUBIDA a la hoja de ruta, la tarea se cierra sola aquí
            # (la subió por otro camino y nadie tiene que acordarse de marcarla).
            if _disco_logistics_autoclose(session_db, p):
                cerradas = True
                continue
            artista = getattr(p, "artist", None)
            filas.append({
                "id": str(p.id),
                "title": _disco_project_title(p),
                "artist_name": (getattr(artista, "name", "") or ""),
                "artist_photo": (getattr(artista, "photo_url", "") or ""),
                "kind_label": _disco_project_kind_meta(getattr(p, "kind", None))[0],
                "release_label": (p.release_date.strftime("%d/%m/%Y") if getattr(p, "release_date", None) else ""),
                "requested_label": estado["requested_label"],
                "requested_by": estado["requested_by"],
                "notes": estado["notes_filled"],
                "url": url_for("disco_project_detail", project_id=p.id, tab="calendario"),
                "bag_url": url_for("disco_project_detail", project_id=p.id, tab="bolsa"),
                "roadmap_url": url_for("disco_project_detail", project_id=p.id, tab="hoja-ruta"),
                "done_url": url_for("disco_project_logistics_done", project_id=p.id),
            })
            if len(filas) >= limit:
                break
        if cerradas:
            session_db.commit()
        return filas
    except Exception:
        app.logger.exception("[inicio] no se pudo leer la logística pedida")
        return []
    finally:
        session_db.close()


def _home_invitations_to_manage(limit: int = 24) -> list[dict]:
    """Conciertos/actividades futuros que el usuario actual puede GESTIONAR y que tienen
    solicitudes de invitaciones. Alimenta el módulo del inicio 'Invitaciones pendientes de
    gestionar': tarjeta con artista(s)+foto, datos del evento y nº de solicitudes pendientes.
    Si todo está enviado o en taquilla, se marca como 'ya gestionadas' (etiqueta verde)."""
    state = _current_user_state()
    if int(state.get("role") or 0) != 10 and not _state_has_access(state, "invitaciones.gestionar", include_descendants=True):
        return []
    session_db = db()
    try:
        query_start = _invitation_event_query_start_date()
        now_value = _now_madrid()
        concerts = (
            session_db.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(or_(Concert.date == None, Concert.date >= query_start))  # noqa: E711
            .order_by(Concert.date.asc().nullslast(), Concert.created_at.desc())
            .limit(300)
            .all()
        )
        active = [c for c in concerts if _invitation_event_is_active_for_requests(c, now_value=now_value)]
        manageable = _filter_manageable_concerts(session_db, active, state=state)
        if not manageable:
            return []
        # Mismo estado (pendiente/taquilla/enviadas) que la lista de gestión, en consultas agregadas.
        status_map = _invitation_manage_status_map(session_db, manageable)
        rows = []
        for c in manageable:
            ms = status_map.get(str(c.id), {"pending": 0, "box_office": 0, "managed": False})
            if not (ms["pending"] or ms["box_office"] or ms["managed"]):
                continue  # sin solicitudes/compromisos reales (ignora rechazadas/anuladas)
            payload = _invitation_event_payload(session_db, c)
            payload["manage_status"] = ms
            payload["detail_url"] = url_for("invitation_event_detail", concert_id=c.id, **{"from": "gestionar"})
            rows.append(payload)
        # Orden por urgencia: pendientes -> taquilla -> enviadas (estable, respeta cronología).
        rows.sort(key=lambda r: 0 if r["manage_status"]["pending"] else 1 if r["manage_status"]["box_office"] else 2)
        return rows[:limit]
    except Exception:
        return []
    finally:
        session_db.close()


def _home_invitation_requests_for_current_user(limit: int = 12) -> list[dict]:
    uid = _safe_uuid(session.get('user_id'))
    if not uid:
        return []
    session_db = db()
    try:
        rows = (
            session_db.query(InvitationRequest)
            .options(joinedload(InvitationRequest.concert))
            .filter(InvitationRequest.requester_user_id == uid)
            .filter(InvitationRequest.status.notin_(['RECHAZADAS', 'ANULADAS']))
            .order_by(InvitationRequest.created_at.desc())
            .limit(max(limit * 3, 30))
            .all()
        )
        out = []
        for row in rows:
            if not _invitation_request_visible_for_user(row):
                continue
            cats = _invitation_get_categories(session_db, row.concert, ensure_defaults=False) if row.concert else []
            item = _invitation_request_payload(row, cats)
            item['event'] = _invitation_event_payload(session_db, row.concert) if row.concert else {}
            out.append(item)
            if len(out) >= limit:
                break
        return out
    except Exception:
        return []
    finally:
        session_db.close()



