# ---------------------------------------------------------------------------
# Chartmetric — motor de refresco (Fase 1): resuelve el ID de Chartmetric de cada artista, trae
# métricas (oyentes/seguidores) y playlists y lo cachea en BD. Todo dormido si no hay token.
# ---------------------------------------------------------------------------
def _chartmetric_extract_spotify_artist_id(artist) -> str | None:
    """Busca un id de artista de Spotify en social_links (open.spotify.com/artist/<id>)."""
    links = getattr(artist, "social_links", None) or {}
    if isinstance(links, dict):
        values = list(links.values())
    elif isinstance(links, (list, tuple)):
        values = list(links)
    else:
        values = []
    for v in values:
        if isinstance(v, str):
            m = re.search(r"open\.spotify\.com/artist/([A-Za-z0-9]+)", v)
            if m:
                return m.group(1)
    return None


def _chartmetric_pick_cmid(payload):
    """Extrae el Chartmetric ID de la respuesta de get-ids (defensivo; CONFIRMAR forma exacta)."""
    if isinstance(payload, list) and payload:
        return _chartmetric_pick_cmid(payload[0])
    if isinstance(payload, dict):
        for key in ("chartmetric", "cm_artist", "chartmetric_id", "id"):
            v = payload.get(key)
            if isinstance(v, list) and v:
                v = v[0]
            if isinstance(v, dict):
                v = v.get("id") or v.get("cm_artist")
            if v:
                return v
    return None


def _chartmetric_norm_name(s: str) -> str:
    """Normaliza un nombre para comparar: minúsculas, sin acentos, sin espacios extra."""
    s = unicodedata.normalize("NFKD", s or "")
    s = "".join(c for c in s if not unicodedata.combining(c))
    return " ".join(s.lower().split())


def _chartmetric_norm_isrc(s) -> str:
    """Normaliza un ISRC para comparar: solo alfanumérico, en mayúsculas (ignora guiones/espacios)."""
    return "".join(ch for ch in (s or "") if ch.isalnum()).upper()


def _chartmetric_track_image(d) -> str:
    """Portada (album art) de un track a partir de un dict de Chartmetric (track o item de playlist),
    probando las claves habituales. '' si no hay."""
    if not isinstance(d, dict):
        return ""
    for k in ("image_url", "album_image_url", "cover_url", "track_image_url", "artwork_url", "image"):
        v = d.get(k)
        if isinstance(v, str) and v.strip():
            return v.strip()
    alb = d.get("album")
    if isinstance(alb, dict):
        for k in ("image_url", "cover_url", "image"):
            v = alb.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip()
    return ""


def _chartmetric_search_best(name: str):
    """Mejor artista en Chartmetric por nombre: coincidencia EXACTA normalizada, el de mayor score.
    Devuelve el dict {id, name, image_url, sp_monthly_listeners...} o None (así no vinculamos un
    artista equivocado en nombres ambiguos)."""
    import chartmetric_utils as cm
    if not (name or "").strip():
        return None
    try:
        results = cm.search_artists(name, limit=10) or []
    except Exception:
        return None
    target = _chartmetric_norm_name(name)
    matches = [
        a for a in results
        if isinstance(a, dict) and a.get("id") and _chartmetric_norm_name(a.get("name", "")) == target
    ]
    if not matches:
        return None
    matches.sort(key=lambda a: (a.get("cm_artist_score") or 0), reverse=True)
    return matches[0]


def _chartmetric_fetch_artist_meta(cmid):
    """Nombre e imagen del artista en Chartmetric por CMID (para validar un ID puesto a mano)."""
    import chartmetric_utils as cm
    try:
        data = cm.get_artist(cmid)
        a = data.get("obj", data) if isinstance(data, dict) else data
        if isinstance(a, dict):
            return (a.get("name"), a.get("image_url") or a.get("cover_url"))
    except Exception:
        pass
    return (None, None)


def _chartmetric_resolve_cmid(session_db, artist) -> str | None:
    """Resuelve y persiste el Chartmetric ID del artista (no toca lo ya vinculado)."""
    import chartmetric_utils as cm
    link = session_db.get(ChartmetricArtist, artist.id)
    if link and link.chartmetric_id:
        return link.chartmetric_id
    if not link:
        link = ChartmetricArtist(artist_id=artist.id)
        session_db.add(link)
    try:
        cmid = cm_name = cm_img = source = None
        spotify_id = _chartmetric_extract_spotify_artist_id(artist)
        if spotify_id:
            data = cm.get_chartmetric_id_from_spotify(spotify_id)
            payload = data.get("obj", data) if isinstance(data, dict) else data
            cmid = _chartmetric_pick_cmid(payload)
            if cmid:
                source = "spotify"
                first = payload[0] if isinstance(payload, list) and payload else (payload if isinstance(payload, dict) else {})
                cm_name = first.get("artist_name") if isinstance(first, dict) else None
        if not cmid:
            hit = _chartmetric_search_best(artist.name)
            if hit:
                cmid, cm_name, cm_img, source = hit.get("id"), hit.get("name"), hit.get("image_url"), "name"
        if cmid:
            link.chartmetric_id = str(cmid)
            link.chartmetric_name = cm_name
            link.chartmetric_image_url = cm_img
            link.match_source = source
            link.status = "LINKED"
            link.last_error = None
        else:
            link.status = "NOT_FOUND"
            link.last_error = "No se encontró en Chartmetric (ni por Spotify ni por nombre exacto)."
    except Exception as e:
        link.status = "ERROR"
        link.last_error = str(e)[:500]
    link.updated_at = _now_madrid()
    return link.chartmetric_id


def _chartmetric_review_rows(session_db):
    """Una fila por artista con el ID de Chartmetric elegido (para revisión y corrección manual)."""
    rows = (
        session_db.query(Artist, ChartmetricArtist)
        .outerjoin(ChartmetricArtist, ChartmetricArtist.artist_id == Artist.id)
        .order_by(Artist.name.asc())
        .all()
    )
    out = []
    for art, link in rows:
        out.append({
            "artist_id": str(art.id),
            "artist_name": art.name,
            "artist_photo": art.photo_url,
            "cmid": (link.chartmetric_id if link else None),
            "cm_name": (getattr(link, "chartmetric_name", None) if link else None),
            "cm_image": (getattr(link, "chartmetric_image_url", None) if link else None),
            "source": (getattr(link, "match_source", None) if link else None),
            "status": (link.status if link else None),
        })
    return out


def _chartmetric_clear_artist_cache(session_db, artist_id):
    """Borra métricas y playlists cacheadas de un artista (al corregir/desvincular su ID)."""
    session_db.query(ChartmetricMetricPoint).filter_by(artist_id=artist_id).delete()
    session_db.query(ChartmetricPlaylistEntry).filter_by(artist_id=artist_id).delete()


def _chartmetric_upsert_metric_points(session_db, artist_id, source, field, series, keep_days=120):
    for pt in (series or [])[-keep_days:]:
        if not isinstance(pt, dict):
            continue
        ts = (pt.get("timestp") or "")[:10]
        if not ts:
            continue
        try:
            d = date.fromisoformat(ts)
        except (ValueError, TypeError):
            continue
        existing = (
            session_db.query(ChartmetricMetricPoint)
            .filter_by(artist_id=artist_id, source=source, field=field, date=d)
            .first()
        )
        if existing:
            existing.value = pt.get("value")
            existing.fetched_at = _now_madrid()
        else:
            session_db.add(ChartmetricMetricPoint(
                artist_id=artist_id, source=source, field=field, date=d, value=pt.get("value"),
            ))


def _chartmetric_replace_current_playlists(session_db, artist_id, platform, items, track_map=None, song_by_isrc=None, song_by_title=None, status="current"):
    """Reemplaza las playlists del artista en esa plataforma y estado (current/past) con el snapshot.

    track_map: cm_track -> {name, isrc}. Las playlists de Apple/Amazon NO traen el nombre de la
    canción, así que lo sacamos de aquí; y casamos con nuestra Song por ISRC (normalizado) o, si no
    cuadra, por título normalizado, para enlazar la ficha de la canción.
    """
    track_map = track_map or {}
    song_by_isrc = song_by_isrc or {}
    song_by_title = song_by_title or {}
    session_db.query(ChartmetricPlaylistEntry).filter_by(
        artist_id=artist_id, platform=platform, status=status
    ).delete()
    seen = set()
    official_owners = {"spotify", "apple music", "apple", "applemusic", "amazon", "amazon music"}
    for it in (items or []):
        pl = it.get("playlist", it) if isinstance(it, dict) else None
        if not isinstance(pl, dict):
            continue
        playlist_id = str(pl.get("playlist_id") or pl.get("id") or "").strip()
        cm_track = str(pl.get("cm_track") or pl.get("track_id") or "").strip()
        if not playlist_id:
            continue
        key = (playlist_id, cm_track)
        if key in seen:
            continue
        seen.add(key)
        # El track puede venir referenciado con distintos ids según plataforma; probamos todos
        # contra el track_map (que indexa por cm_track + ids de cada plataforma + ISRC).
        cand_keys = []
        for k in ("cm_track", "track_id", "id", "spotify_track_id", "itunes_track_id",
                  "apple_track_id", "amazon_track_id", "isrc"):
            v = str(pl.get(k) or "").strip()
            if v:
                cand_keys.append(v)
        owner = pl.get("owner_name") or pl.get("curator_name")
        is_official = bool(pl.get("editorial")) or (str(owner or "").strip().lower() in official_owners)
        added_d = None
        added = (pl.get("added_at") or "")[:10]
        if added:
            try:
                added_d = date.fromisoformat(added)
            except (ValueError, TypeError):
                added_d = None
        track_name = pl.get("track")
        info = {}
        for ck in cand_keys:
            hit = track_map.get(ck)
            if hit:
                info = hit
                break
        if not track_name:
            track_name = info.get("name")
        # Portada de la CANCIÓN (del mapa de tracks; NO la de la playlist).
        track_img = info.get("image") or None
        song_id = None
        isrc = info.get("isrc")
        # El propio item de playlist puede traer ISRC directamente (algunas plataformas).
        if not isrc:
            isrc = (pl.get("isrc") or "").strip() or None
        if isrc:
            song_id = song_by_isrc.get(_chartmetric_norm_isrc(isrc))
        if not song_id and track_name:
            song_id = song_by_title.get(_chartmetric_norm_name(track_name))
        session_db.add(ChartmetricPlaylistEntry(
            artist_id=artist_id, platform=platform, status=status,
            cm_track=cm_track or None, track_name=track_name, song_id=song_id,
            playlist_id=playlist_id, playlist_name=pl.get("name"),
            owner_name=owner, is_official=is_official,
            position=pl.get("position"), peak_position=pl.get("peak_position"),
            days_in_list=pl.get("period"), added_at=added_d,
            followers=pl.get("followers"), image_url=pl.get("image_url") or pl.get("playlist_image_url"),
            track_image_url=track_img,
        ))


def _chartmetric_crossfill_entries(session_db, artist_id) -> None:
    """Rellena, entre las playlists de un artista, el nombre/canción/portada que falten en una entrada
    copiándolos de otra entrada del MISMO track (mismo cm_track) que sí los tenga. Así, si una canción
    está bien resuelta en Spotify pero llega sin datos en Amazon, la de Amazon hereda nombre, ficha y
    portada. Solo lee/escribe en BD (sin API)."""
    rows = session_db.query(ChartmetricPlaylistEntry).filter(
        ChartmetricPlaylistEntry.artist_id == artist_id
    ).all()
    best = {}
    for e in rows:
        if not e.cm_track:
            continue
        b = best.setdefault(e.cm_track, {"name": None, "song_id": None, "image": None})
        if e.track_name and not b["name"]:
            b["name"] = e.track_name
        if e.song_id and not b["song_id"]:
            b["song_id"] = e.song_id
        if getattr(e, "track_image_url", None) and not b["image"]:
            b["image"] = e.track_image_url
    for e in rows:
        if not e.cm_track:
            continue
        b = best.get(e.cm_track) or {}
        if not e.track_name and b.get("name"):
            e.track_name = b["name"]
        if not e.song_id and b.get("song_id"):
            e.song_id = b["song_id"]
        if not getattr(e, "track_image_url", None) and b.get("image"):
            e.track_image_url = b["image"]


def _chartmetric_refresh_artist(session_db, artist) -> dict:
    """Refresca métricas + playlists de un artista. Dormant si no configurado. No lanza."""
    import chartmetric_utils as cm
    if not cm.chartmetric_configured():
        return {"ok": False, "message": "Chartmetric no configurado."}
    cmid = _chartmetric_resolve_cmid(session_db, artist)
    if not cmid:
        session_db.commit()
        return {"ok": False, "message": "Sin Chartmetric ID (no se pudo vincular el artista)."}
    link = session_db.get(ChartmetricArtist, artist.id)
    errors = []
    for source, fields in (("spotify", ["listeners", "followers"]), ("instagram", ["followers"]), ("tiktok", ["followers"])):
        try:
            data = cm.get_artist_stat(cmid, source)
            payload = data.get("obj", data) if isinstance(data, dict) else data
            for field in fields:
                _chartmetric_upsert_metric_points(session_db, artist.id, source, field, (payload or {}).get(field))
        except Exception as e:
            errors.append(f"stat:{source}:{str(e)[:80]}")
    # Enlaces a las redes/plataformas del artista (Instagram, TikTok, YouTube, Bandsintown, Facebook,
    # X, Spotify, Apple Music, Amazon Music). Se cachean para pintarlos en el hero de la ficha; se
    # refrescan en cada actualización (la automática es diaria/semanal y la manual desde Integraciones).
    try:
        link.social_urls = _chartmetric_extract_social_urls(cm.get_artist_urls(cmid))
    except Exception as e:
        errors.append(f"urls:{str(e)[:80]}")
    # Mapa de tracks (id_track -> nombre + ISRC) para nombrar canciones en TODAS las plataformas
    # (Apple/Amazon no traen el nombre) y enlazarlas con nuestra ficha por ISRC. Las playlists de
    # cada plataforma referencian el track con un id distinto (cm_track universal, pero también el
    # id propio de Spotify/Apple/Amazon), así que registramos el track bajo TODOS sus identificadores
    # para casarlo venga como venga. (Antes solo se indexaba por cm_track -> Amazon salía sin nombre.)
    track_map = {}
    track_objs = []  # objetos crudos de get_artist_tracks (para resolver enlaces de NUESTRAS Song)

    def _track_reg(idval, name, isrc, image=None):
        k = str(idval or "").strip()
        if not k:
            return
        if isinstance(isrc, (list, tuple)):   # algunos endpoints devuelven varios ISRC
            isrc = next((x for x in isrc if x), None)
        if isinstance(name, (list, tuple)):
            name = next((x for x in name if x), None)
        cur = track_map.get(k) or {}
        if name and not cur.get("name"):
            cur["name"] = name
        if isrc and not cur.get("isrc"):
            cur["isrc"] = isrc
        if image and not cur.get("image"):
            cur["image"] = image
        track_map[k] = cur

    try:
        for t in (cm.get_artist_tracks(cmid, limit=500) or []):
            if not isinstance(t, dict):
                continue
            track_objs.append(t)
            nm = t.get("name")
            isrc = t.get("isrc")
            img = _chartmetric_track_image(t)
            for key in ("cm_track", "id", "isrc", "spotify_track_id", "spotify_id",
                        "itunes_track_id", "itunes_id", "apple_track_id",
                        "amazon_track_id", "amazon_id", "deezer_track_id"):
                _track_reg(t.get(key), nm, isrc, img)
            # Cualquier otro identificador de track que traiga el item (claves *track*id* / ids de tienda).
            for k, v in t.items():
                kl = str(k).lower()
                if isinstance(v, (str, int)) and (("track" in kl and "id" in kl) or kl in ("asin", "amazon", "isrc")):
                    _track_reg(v, nm, isrc, img)
    except Exception as e:
        errors.append(f"tracks:{str(e)[:80]}")
    # Casar las canciones de las playlists con NUESTRAS Song: por ISRC (normalizado) y, de respaldo,
    # por título normalizado. Usamos las canciones del propio artista (más fiable que buscar por ISRC
    # global, y permite el respaldo por título cuando el ISRC no coincide o falta).
    song_by_isrc = {}
    song_by_title = {}
    try:
        for sg in (getattr(artist, "songs", None) or []):
            if getattr(sg, "isrc", None):
                song_by_isrc[_chartmetric_norm_isrc(sg.isrc)] = sg.id
            if getattr(sg, "title", None):
                song_by_title[_chartmetric_norm_name(sg.title)] = sg.id
    except Exception:
        pass
    # --- Fase 1: descargar TODAS las playlists y recopilar los cm_track vistos, enriqueciendo el mapa
    # de nombres con lo que traigan los propios items (Spotify SÍ incluye el nombre de la canción). ---
    fetched = {}
    seen_cmts = set()
    for platform in ("spotify", "applemusic", "amazon"):
        for st in ("current", "past"):
            try:
                items = cm.get_artist_playlists(cmid, platform=platform, status=st) or []
            except Exception as e:
                errors.append(f"pl:{platform}:{st}:{str(e)[:80]}")
                items = []
            fetched[(platform, st)] = items
            for it in items:
                pl = it.get("playlist", it) if isinstance(it, dict) else None
                if not isinstance(pl, dict):
                    continue
                cmt = str(pl.get("cm_track") or pl.get("track_id") or "").strip()
                if cmt:
                    seen_cmts.add(cmt)
                nm = pl.get("track")
                if cmt and nm and not (track_map.get(cmt) or {}).get("name"):
                    track_map.setdefault(cmt, {})["name"] = nm
    # --- Fase 2: para los tracks que AÚN no tienen nombre o ISRC (típico de Amazon/Apple, cuyas
    # playlists no traen el nombre y cuyo id no siempre está en el endpoint de tracks), pedir su
    # metadata por cm_track: así conseguimos nombre + ISRC + portada y podemos casar la canción. ---
    _lookups = 0
    for cmt in seen_cmts:
        info = track_map.get(cmt) or {}
        if info.get("name") and info.get("isrc"):
            continue
        if _lookups >= 150:  # tope de seguridad para no gastar créditos de golpe
            errors.append("track:tope-de-consultas")
            break
        _lookups += 1
        try:
            td = cm.get_track(cmt)
        except Exception as e:
            errors.append(f"track:{cmt}:{str(e)[:60]}")
            continue
        if isinstance(td, dict) and td:
            _track_reg(cmt, td.get("name"), td.get("isrc"), _chartmetric_track_image(td))
    # --- Fase 3: guardar las playlists ya enriquecidas. ---
    for platform in ("spotify", "applemusic", "amazon"):
        for st in ("current", "past"):
            try:
                _chartmetric_replace_current_playlists(session_db, artist.id, platform, fetched.get((platform, st)) or [], track_map, song_by_isrc, song_by_title, status=st)
            except Exception as e:
                errors.append(f"save:{platform}:{st}:{str(e)[:80]}")
    # --- Fase 4 (red de seguridad): rellenar nombre/canción/portada que falten copiándolos de otra
    # entrada del MISMO track (mismo cm_track) en otra plataforma que sí los tenga. ---
    try:
        _chartmetric_crossfill_entries(session_db, artist.id)
    except Exception as e:
        errors.append(f"crossfill:{str(e)[:60]}")
    # Enlaces de plataforma de NUESTRAS canciones (rellena solo huecos vacíos; sin llamadas extra).
    try:
        _cm_resolve_artist_song_links(session_db, artist, track_objs)
    except Exception as e:
        errors.append(f"songlinks:{str(e)[:60]}")
    link.last_refreshed_at = _now_madrid()
    link.last_error = "; ".join(errors)[:500] if errors else None
    link.status = "LINKED" if not errors else "ERROR"
    session_db.commit()
    return {"ok": not errors, "message": "Actualizado." if not errors else "; ".join(errors)[:200]}


def _social_url_for(artist, *needles):
    """Primera URL de social_links que contenga alguno de los 'needles' (dominio). None si no hay."""
    links = getattr(artist, "social_links", None) or {}
    if isinstance(links, dict):
        values = list(links.values())
    elif isinstance(links, (list, tuple)):
        values = list(links)
    else:
        values = []
    for v in values:
        if isinstance(v, str) and any(n in v.lower() for n in needles):
            return v
    return None


def _chartmetric_header_metrics(session_db, artist):
    """Métricas de cabecera (oyentes Spotify, seguidores IG/TikTok) con variación mensual.

    Lee SOLO de la caché (chartmetric_metric_point); devuelve [] si no hay datos (no llama a la API).
    Defensivo: ante cualquier error devuelve [] para no romper la ficha del artista.
    """
    plan = [
        ("spotify", "listeners", "Oyentes Spotify", "fa-brands fa-spotify", ("open.spotify.com", "spotify.com")),
        ("instagram", "followers", "Seguidores Instagram", "fa-brands fa-instagram", ("instagram.com",)),
        ("tiktok", "followers", "Seguidores TikTok", "fa-brands fa-tiktok", ("tiktok.com",)),
    ]
    out = []
    try:
        for source, field, label, icon, needles in plan:
            rows = (
                session_db.query(ChartmetricMetricPoint)
                .filter_by(artist_id=artist.id, source=source, field=field)
                .order_by(ChartmetricMetricPoint.date.desc())
                .limit(45)
                .all()
            )
            rows = [r for r in rows if r.value is not None]
            if not rows:
                continue
            cur = float(rows[0].value)
            target = rows[0].date - timedelta(days=30)
            prev = next((r for r in rows if r.date <= target), None)
            delta = (cur - float(prev.value)) if prev is not None else None
            out.append({
                "label": label,
                "icon": icon,
                "value_fmt": f"{int(cur):,}".replace(",", "."),
                "up": delta is not None and delta > 0,
                "down": delta is not None and delta < 0,
                "url": _social_url_for(artist, *needles),
            })
    except Exception:
        return []
    return out


@app.route("/integraciones", methods=["GET", "POST"], endpoint="integrations_view")
@admin_required
def integrations_view():
    # Solo dirección: gestiona credenciales sensibles de servicios externos.
    if not is_master():
        return forbid("Solo dirección puede acceder a las integraciones.")
    # Import perezoso: si por lo que sea un módulo de integración fallara, no afecta al arranque.
    import chartmetric_utils
    if request.method == "POST":
        action = (request.form.get("action") or "").strip()
        # Pleo va por empresa del grupo y tiene sus propios endpoints (pleo_account_*).
        if action == "save_chartmetric_token":
            crudo = request.form.get("refresh_token") or ""
            limpio = _chartmetric_set_token(crudo)
            if not limpio:
                _chartmetric_record_status(False, "Sin refresh token.")
                flash("Chartmetric: se ha borrado el refresh token guardado.", "info")
            else:
                # Se prueba al momento: guardar una clave sin saber si vale no sirve de nada.
                ok, msg = chartmetric_utils.chartmetric_ping()
                _chartmetric_record_status(ok, msg)
                flash(f"Chartmetric ({len(limpio)} caracteres guardados): {msg}",
                      "success" if ok else "danger")
        elif action == "ping_chartmetric":
            ok, msg = chartmetric_utils.chartmetric_ping()
            _chartmetric_record_status(ok, msg)
            flash(f"Chartmetric: {msg}", "success" if ok else "danger")
        elif action == "refresh_chartmetric_test":
            s = db()
            try:
                results = []
                for a in s.query(Artist).order_by(Artist.created_at.desc()).limit(3).all():
                    r = _chartmetric_refresh_artist(s, a)
                    results.append(f"{a.name}: {r['message']}")
                flash("Prueba Chartmetric · " + (" | ".join(results) or "no hay artistas"), "info")
            except Exception as e:
                try:
                    s.rollback()
                except Exception:
                    pass
                flash(f"Error en la prueba de Chartmetric: {e}", "danger")
            finally:
                s.close()
        elif action == "resolve_all_chartmetric":
            s = db()
            try:
                linked = nf = 0
                for a in s.query(Artist).order_by(Artist.name.asc()).all():
                    existing = s.get(ChartmetricArtist, a.id)
                    if existing and existing.chartmetric_id:
                        continue  # ya vinculado (no re-resolver: no gastar ni pisar lo manual)
                    if _chartmetric_resolve_cmid(s, a):
                        linked += 1
                    else:
                        nf += 1
                s.commit()
                flash(f"Vinculación automática: {linked} vinculados, {nf} sin encontrar. Revisa la tabla y corrige a mano lo que haga falta.", "info")
            except Exception as e:
                try:
                    s.rollback()
                except Exception:
                    pass
                flash(f"Error al vincular: {e}", "danger")
            finally:
                s.close()
        elif action == "link_chartmetric":
            aid = (request.form.get("artist_id") or "").strip()
            new_cmid = (request.form.get("chartmetric_id") or "").strip()
            s = db()
            try:
                art = s.get(Artist, to_uuid(aid)) if aid else None
                if not art:
                    flash("Artista no encontrado.", "warning")
                elif not new_cmid.isdigit():
                    flash("El ID de Chartmetric debe ser numérico.", "warning")
                else:
                    name, image = _chartmetric_fetch_artist_meta(new_cmid)
                    link = s.get(ChartmetricArtist, art.id)
                    if not link:
                        link = ChartmetricArtist(artist_id=art.id)
                        s.add(link)
                    link.chartmetric_id = new_cmid
                    link.chartmetric_name = name
                    link.chartmetric_image_url = image
                    link.match_source = "manual"
                    link.status = "LINKED"
                    link.last_error = None
                    link.updated_at = _now_madrid()
                    _chartmetric_clear_artist_cache(s, art.id)  # fuera datos viejos; se recogen al refrescar
                    s.commit()
                    flash(f"{art.name} → Chartmetric ID {new_cmid}" + (f" ({name})" if name else "") + ". Datos antiguos limpiados.", "success")
            except Exception as e:
                try:
                    s.rollback()
                except Exception:
                    pass
                flash(f"Error al vincular: {e}", "danger")
            finally:
                s.close()
        elif action == "unlink_chartmetric":
            aid = (request.form.get("artist_id") or "").strip()
            s = db()
            try:
                art = s.get(Artist, to_uuid(aid)) if aid else None
                if art:
                    link = s.get(ChartmetricArtist, art.id)
                    if link:
                        s.delete(link)
                    _chartmetric_clear_artist_cache(s, art.id)
                    s.commit()
                    flash(f"{art.name} desvinculado y datos limpiados.", "info")
            except Exception as e:
                try:
                    s.rollback()
                except Exception:
                    pass
                flash(f"Error al desvincular: {e}", "danger")
            finally:
                s.close()
        elif action == "refresh_all_chartmetric":
            s = db()
            try:
                n = s.query(ChartmetricArtist).filter(ChartmetricArtist.chartmetric_id.isnot(None)).count()
            finally:
                s.close()
            threading.Thread(target=_chartmetric_refresh_all_bg, daemon=True).start()
            flash(f"Refresco de {n} artista(s) en marcha en segundo plano. Vuelve en unos minutos y recarga la página.", "info")
        elif action == "autolink_chartmetric":
            # Vincular por ISRC, EN PRIMER PLANO: son pocas llamadas y así se dice al momento
            # cuántas han entrado y cuántas quedan (en 2º plano no habría forma de saberlo).
            s = db()
            try:
                res = _cm_autolink_songs_by_isrc(s, force=True)
            finally:
                s.close()
            if res.get("error"):
                flash("Chartmetric ha fallado al buscar por ISRC: %s" % res["error"], "danger")
            if res.get("linked"):
                flash("%s canción(es) vinculadas por su ISRC: %s%s."
                      % (res["linked"], ", ".join(res["names"]),
                         "…" if res["linked"] > len(res["names"]) else ""), "success")
            elif not res.get("error"):
                flash("Ninguna canción nueva se ha podido vincular por su ISRC "
                      "(se han buscado %s)." % res.get("checked", 0), "info")
            if res.get("pending"):
                flash("Quedan %s canción(es) por buscar (se hacen por tandas para no gastar los "
                      "créditos de golpe): vuelve a pulsarlo." % res["pending"], "info")
        elif action == "refresh_songs_chartmetric":
            threading.Thread(target=lambda: _cm_refresh_songs_due_bg(force_all=True), daemon=True).start()
            flash("Actualizando reproducciones de canciones en segundo plano. Recarga en unos minutos.", "info")
        elif action == "ping_enterticket":
            ok, msg, token, expire = et_api.ping()
            if ok and token:
                # El ping renueva el token ÚNICO de la cuenta: hay que persistirlo para el resto.
                s = db()
                try:
                    row = _et_meta_row(s)
                    row.token = token
                    row.token_expires_at = expire
                    s.commit()
                    _ET_TOKEN_LOCAL.update(token=token, read_at=time.time())
                finally:
                    s.close()
            flash(f"Enterticket: {msg}", "success" if ok else "danger")
        elif action == "et_sync_catalog":
            s = db()
            try:
                total, nuevos = _et_sync_catalog(s)
                flash(f"Enterticket: catálogo sincronizado ({total} eventos, {nuevos} nuevos).", "success")
            except Exception as e:
                try:
                    s.rollback()
                except Exception:
                    pass
                flash(f"Enterticket: error al sincronizar el catálogo: {e}", "danger")
            finally:
                s.close()
        elif action == "et_sync_all":
            threading.Thread(target=_et_sync_all_bg, daemon=True).start()
            flash("Enterticket: sincronización completa en marcha en segundo plano (catálogo + ventas de los eventos vinculados). Recarga en unos minutos.", "info")
        elif action in {"et_link", "et_unlink", "et_ignore", "et_unignore", "et_request", "et_sync_event"}:
            s = db()
            try:
                ev = s.get(EnterticketEvent, to_uuid(request.form.get("et_event_pk") or ""))
                if not ev:
                    flash("Evento de Enterticket no encontrado.", "danger")
                elif action == "et_link":
                    c = s.get(Concert, to_uuid(request.form.get("concert_id") or ""))
                    if not c:
                        flash("Selecciona el concierto al que vincular.", "warning")
                    else:
                        _et_link_event(s, ev, c)
                        s.commit()
                        threading.Thread(target=_et_sync_event_bg, args=(str(ev.id),), daemon=True).start()
                        flash(f"«{ev.name}» vinculado al concierto. Sincronizando ventas en segundo plano…", "success")
                        if _et_concert_has_legacy_sales(s, c.id):
                            flash("Aviso: este concierto llevaba la venta en modo básico (histórico manual antiguo). Al integrarse con Enterticket, el reporte pasa a usar el desglose por ticketeras y ese histórico básico deja de sumarse.", "warning")
                elif action == "et_unlink":
                    _et_unlink_event(s, ev)
                    s.commit()
                    flash(f"«{ev.name}» desvinculado.", "info")
                elif action == "et_ignore":
                    ev.link_status = "IGNORED"
                    s.commit()
                    flash(f"«{ev.name}» ignorado (no se volverá a proponer).", "info")
                elif action == "et_unignore":
                    ev.link_status = "PENDING"
                    s.commit()
                    flash(f"«{ev.name}» vuelve a estar pendiente de vincular.", "info")
                elif action == "et_request":
                    _et_create_booking_request(s, ev)
                    s.commit()
                    flash(f"Petición enviada a Contratación para crear «{ev.name}» con los datos de Enterticket.", "success")
                elif action == "et_sync_event":
                    threading.Thread(target=_et_sync_event_bg, args=(str(ev.id),), daemon=True).start()
                    flash(f"Sincronizando «{ev.name}» en segundo plano…", "info")
            except Exception as e:
                try:
                    s.rollback()
                except Exception:
                    pass
                flash(f"Enterticket: {e}", "danger")
            finally:
                s.close()
        if action == "ping_enterticket" or action.startswith("et_"):
            return redirect(url_for("integrations_view") + "#tab-enterticket")
        return redirect(url_for("integrations_view"))
    # Resumen de la caché + tabla de revisión (artista -> ID de Chartmetric elegido).
    cm_linked = cm_points = cm_playlists = 0
    # Cuántas canciones y álbumes están vinculados: es el número que tiene que cambiar al vincular
    # uno (antes solo se contaban los artistas y el resumen parecía no enterarse de nada).
    cm_songs_linked = cm_songs_total = cm_albums_linked = cm_albums_total = 0
    review_rows = []
    cm_song_rows = []
    cm_album_rows = []
    cm_last_refresh = None
    cm_credit_warning = False
    if chartmetric_utils.chartmetric_configured():
        s = db()
        try:
            cm_linked = s.query(ChartmetricArtist).filter(ChartmetricArtist.chartmetric_id.isnot(None)).count()
            cm_points = s.query(ChartmetricMetricPoint).count()
            cm_playlists = s.query(ChartmetricPlaylistEntry).filter_by(status="current").count()
            cm_songs_total = s.query(func.count(Song.id)).scalar() or 0
            cm_songs_linked = (s.query(func.count(Song.id))
                               .filter(func.coalesce(Song.cm_track, '') != '').scalar() or 0)
            cm_albums_total = s.query(func.count(Album.id)).scalar() or 0
            cm_albums_linked = (s.query(func.count(Album.id))
                                .filter(func.coalesce(Album.cm_track, '') != '').scalar() or 0)
            review_rows = _chartmetric_review_rows(s)
            cm_song_rows = _cm_song_review_rows(s)
            cm_album_rows = _cm_album_review_rows(s)
            cm_last_refresh = s.query(func.max(ChartmetricArtist.last_refreshed_at)).scalar()
            cm_credit_warning = bool(
                s.query(ChartmetricArtist.artist_id)
                .filter(
                    ChartmetricArtist.last_error.ilike("%crédit%")
                    | ChartmetricArtist.last_error.ilike("%credit%")
                    | ChartmetricArtist.last_error.ilike("%402%")
                )
                .first()
            )
        except Exception:
            pass
        finally:
            s.close()
    # --- Enterticket: estado + catálogo de eventos con su vínculo ---
    et_configured = et_api.enterticket_configured()
    et_meta = None
    et_events = []
    et_concert_options = []
    et_past_count = 0          # eventos ya celebrados: no se listan (siguen vinculados)
    et_counts = {"total": 0, "linked": 0, "pending": 0, "requested": 0, "ignored": 0}
    if et_configured:
        s = db()
        try:
            et_meta = s.get(EnterticketMeta, 1)
            today = date.today()
            # SOLO EVENTOS FUTUROS. Un evento pasado no hay que vincularlo ni pedirlo: lo que ya
            # estuviera vinculado sigue vinculado y sus datos se ven en la ficha de su actividad
            # (pestaña Ticketing), pero aquí no pinta nada y solo ensucia la lista. Los que NO tienen
            # fecha se conservan: no se puede afirmar que hayan pasado.
            # La fecha de fin manda cuando la hay (un festival de varios días sigue vivo el último).
            rows_all = (s.query(EnterticketEvent)
                        .options(joinedload(EnterticketEvent.concert).joinedload(Concert.artist),
                                 joinedload(EnterticketEvent.concert).joinedload(Concert.venue))
                        .order_by(EnterticketEvent.event_date.asc().nullsfirst()).all())
            rows = [r for r in rows_all
                    if (r.event_end_date or r.event_date) is None
                    or (r.event_end_date or r.event_date) >= today]
            et_past_count = len(rows_all) - len(rows)
            for ev in rows:
                st = (ev.link_status or "PENDING").upper()
                et_counts["total"] += 1
                et_counts[{"LINKED": "linked", "REQUESTED": "requested", "IGNORED": "ignored"}.get(st, "pending")] += 1
                concert_label = ""
                if ev.concert:
                    c = ev.concert
                    vn = (c.venue.name if c.venue else "") or (c.manual_venue_name or "") or (c.manual_municipality or "")
                    concert_label = f"{c.artist.name if c.artist else '¿?'} · {c.date.strftime('%d/%m/%Y') if c.date else '—'}" + (f" · {vn}" if vn else "")
                candidates = []
                # La consulta de candidatos ya va acotada por la fecha del evento (± margen), así
                # que no hace falta ningún corte adicional por antigüedad.
                if st == "PENDING" and ev.event_date:
                    for score, c in _et_automatch_candidates(s, ev, day_margin=3)[:6]:
                        vn = (c.venue.name if c.venue else "") or (c.manual_venue_name or "") or (c.manual_municipality or "")
                        candidates.append({
                            "id": str(c.id), "score": score,
                            "label": f"{c.artist.name if c.artist else '¿?'} · {c.date.strftime('%d/%m/%Y') if c.date else '—'}" + (f" · {vn}" if vn else ""),
                        })
                et_events.append({
                    "pk": str(ev.id), "et_event_id": ev.et_event_id, "name": ev.name,
                    "date": (ev.event_date.strftime("%d/%m/%Y") if ev.event_date else "—"),
                    "is_past": bool(ev.event_date and ev.event_date < today),
                    "venue": ev.venue_name or "", "town": ev.venue_town or "",
                    "artists": ev.artist_names or "", "image": ev.artist_image or ev.image_url or "",
                    "status": st, "active": bool(ev.active),
                    "concert_id": (str(ev.concert_id) if ev.concert_id else ""),
                    "concert_label": concert_label, "url": ev.url_enterticket or "",
                    "last_synced": _et_fmt_dt(ev.last_synced_at),
                    "last_error": ev.last_error or "", "candidates": candidates,
                    "capacity": ev.capacity_on_sale,
                })
            # Selector del modal «Vincular con otro concierto»: TODAS las actividades (buscable con
            # Select2 por artista/fecha/recinto), porque la fecha del evento en Enterticket y la
            # nuestra no siempre coinciden y hay que poder corregirlo. Se ordenan por fecha
            # descendente y se acota el número de filas, no la fecha.
            # ⚠️ Los ya vinculados se descartan mirando TODOS los eventos (`rows_all`), no solo los
            # futuros: si no, una actividad enlazada a un evento pasado volvería a ofrecerse y se
            # podría vincular dos veces.
            if any(e["status"] == "PENDING" for e in et_events):
                linked_ids = [r.concert_id for r in rows_all if r.concert_id]
                copts_q = (s.query(Concert)
                           .options(joinedload(Concert.artist), joinedload(Concert.venue)))
                if linked_ids:
                    copts_q = copts_q.filter(~Concert.id.in_(linked_ids))  # ya tienen su evento ET
                copts = copts_q.order_by(Concert.date.desc().nullslast()).limit(3000).all()
                for c in copts:
                    vn = (c.venue.name if c.venue else "") or (c.manual_venue_name or "") or (c.manual_municipality or "")
                    et_concert_options.append({
                        "id": str(c.id),
                        "label": f"{c.artist.name if c.artist else '¿?'} · {c.date.strftime('%d/%m/%Y') if c.date else '—'}" + (f" · {vn}" if vn else ""),
                    })
        except Exception:
            pass
        finally:
            s.close()
    # --- Pleo: una subpestaña por EMPRESA del grupo (credencial, estado y empleados) ---
    pleo_rows, pleo_people, pleo_any = [], [], False
    s = db()
    try:
        pleo_rows = _pleo_account_rows(s)
        pleo_any = _pleo_configured_any(s)
        # Selector para vincular a mano un empleado de Pleo con una persona (solo personal actual).
        _inactive = _inactive_user_ids(s)
        for prof in (s.query(UserProfile).order_by(UserProfile.nick.asc()).all()):
            if not prof.user_id or prof.user_id in _inactive:
                continue
            u = s.get(User, prof.user_id)
            pleo_people.append({
                "id": str(prof.user_id),
                "label": "%s%s" % ((prof.nick or "Usuario"), (" · " + u.email) if u and u.email else ""),
            })
    except Exception:
        pass
    finally:
        s.close()
    # Cabify: mismas subpestañas por empresa del grupo (best-effort, no debe tumbar la pantalla).
    cabify_rows, cabify_any = [], False
    s2 = db()
    try:
        cabify_rows = _cabify_account_rows(s2)
        cabify_any = any((r.get("account") is not None and r["account"].is_active) for r in cabify_rows)
    except Exception:
        cabify_rows, cabify_any = [], False
    finally:
        s2.close()
    # Holded: una subpestaña por empresa del grupo (cada una lleva su contabilidad en su cuenta).
    holded_rows, holded_any = [], False
    s3 = db()
    try:
        holded_rows = _holded_account_rows(s3)
        holded_any = _holded_configured_any(s3)
    except Exception:
        holded_rows, holded_any = [], False
    finally:
        s3.close()
    # SMS: una sola cuenta para toda la casa (su pestaña trae la guía, el estado y el registro).
    sms_ctx = {}
    s4 = db()
    try:
        sms_ctx = _sms_panel_context(s4)
    except Exception:
        app.logger.exception("[sms] no se pudo montar el panel")
        sms_ctx = {}
    finally:
        s4.close()
    return render_template(
        "integraciones.html",
        title="Integraciones",
        smtp=_smtp_settings(),
        pleo_configured=pleo_any,
        pleo_rows=pleo_rows,
        pleo_people=pleo_people,
        cabify_configured=cabify_any,
        cabify_rows=cabify_rows,
        holded_configured=holded_any,
        holded_rows=holded_rows,
        personnel_options=[{"id": p["id"], "nick": p["label"]} for p in pleo_people],
        pleo_default_window=PLEO_DEFAULT_WINDOW_DAYS,
        chartmetric_configured=chartmetric_utils.chartmetric_configured(),
        cm_status=_chartmetric_status(),
        enterticket_configured=et_configured,
        et_meta=et_meta,
        et_last_catalog_sync=(_et_fmt_dt(et_meta.last_catalog_sync_at) if et_meta else ""),
        et_events=et_events,
        et_concert_options=et_concert_options,
        et_counts=et_counts,
        et_past_count=et_past_count,
        cm_linked=cm_linked,
        cm_songs_linked=cm_songs_linked,
        cm_songs_total=cm_songs_total,
        cm_albums_linked=cm_albums_linked,
        cm_albums_total=cm_albums_total,
        cm_points=cm_points,
        cm_playlists=cm_playlists,
        review_rows=review_rows,
        cm_song_rows=cm_song_rows,
        cm_album_rows=cm_album_rows,
        cm_platform_labels=[("spotify", "Spotify"), ("apple_music", "Apple Music"), ("amazon_music", "Amazon Music"), ("tiktok", "TikTok"), ("youtube", "YouTube")],
        cm_last_refresh=cm_last_refresh,
        cm_credit_warning=cm_credit_warning,
        **sms_ctx,
    )


# ---------------------------------------------------------------------------
# CHARTMETRIC · el refresh token se guarda en la app (no solo en el entorno)
# ---------------------------------------------------------------------------
# Los tokens de Chartmetric caducan y se rotan: hay que poder cambiarlos desde Integraciones sin
# tocar Render. Se guardan en `AppSetting` (como el resto de ajustes globales) y `chartmetric_utils`
# los lee por un proveedor; lo del entorno queda de respaldo.
CM_TOKEN_SETTING = "chartmetric_refresh_token"
CM_STATUS_SETTING = "chartmetric_last_status"      # OK | ERROR
CM_ERROR_SETTING = "chartmetric_last_error"
CM_CHECKED_SETTING = "chartmetric_last_check"
# Caché corto del token: `_get_app_setting` abre una sesión de BD y esto se consulta en CADA
# llamada a la API. 60 s basta para que un cambio se note enseguida sin machacar la BD.
_CM_TOKEN_CACHE = {"value": None, "at": 0.0}


def _chartmetric_stored_token() -> str:
    ahora = time.time()
    if _CM_TOKEN_CACHE["value"] is None or (ahora - _CM_TOKEN_CACHE["at"]) > 60:
        try:
            _CM_TOKEN_CACHE["value"] = (_get_app_setting(CM_TOKEN_SETTING) or "").strip()
        except Exception:
            _CM_TOKEN_CACHE["value"] = ""
        _CM_TOKEN_CACHE["at"] = ahora
    return _CM_TOKEN_CACHE["value"] or ""


def _chartmetric_set_token(raw: str) -> str:
    """Guarda el refresh token limpio y tira lo cacheado (token guardado y access token del proceso)."""
    import chartmetric_utils as cm
    limpio = cm.clean_api_key(raw)
    _set_app_setting(CM_TOKEN_SETTING, limpio)
    _CM_TOKEN_CACHE["value"], _CM_TOKEN_CACHE["at"] = limpio, time.time()
    cm.reset_access_token()
    return limpio


def _chartmetric_record_status(ok: bool, mensaje: str) -> None:
    """Deja apuntado el resultado de la última comprobación, para que la etiqueta de estado de
    Integraciones diga la verdad y no un «Configurada» genérico."""
    try:
        _set_app_setting(CM_STATUS_SETTING, "OK" if ok else "ERROR")
        _set_app_setting(CM_ERROR_SETTING, "" if ok else (mensaje or "")[:500])
        _set_app_setting(CM_CHECKED_SETTING, datetime.now(TZ_MADRID).isoformat(timespec="seconds"))
    except Exception:
        pass


def _chartmetric_status() -> dict:
    """Estado de la integración para la pantalla: si hay clave, qué dijo la última prueba y cuándo."""
    import chartmetric_utils as cm
    token = cm.refresh_token_value()
    estado = (_get_app_setting(CM_STATUS_SETTING) or "").strip().upper()
    cuando = (_get_app_setting(CM_CHECKED_SETTING) or "").strip()
    try:
        cuando_dt = datetime.fromisoformat(cuando) if cuando else None
    except Exception:
        cuando_dt = None
    if not token:
        clase, etiqueta = "text-bg-secondary", "Desactivada"
    elif estado == "ERROR":
        clase, etiqueta = "text-bg-danger", "Con error"
    elif estado == "OK":
        clase, etiqueta = "text-bg-success", "Conectada"
    else:
        clase, etiqueta = "text-bg-warning text-dark", "Sin comprobar"
    return {
        "has_token": bool(token),
        "masked": (token[:4] + "…" + token[-4:]) if len(token) > 10 else ("•" * len(token)),
        "length": len(token),
        # De dónde sale la clave: importa saber si la está mandando el entorno de Render.
        "from_env": bool(token) and not _chartmetric_stored_token(),
        "state": estado or "UNKNOWN",
        "badge_class": clase,
        "badge_label": etiqueta,
        "error": (_get_app_setting(CM_ERROR_SETTING) or "").strip(),
        "checked_at": cuando_dt,
    }


# ===========================================================================
# Chartmetric a nivel CANCIÓN/ÁLBUM: enlaces de plataforma automáticos + reproducciones
# ===========================================================================
_CM_TRACK_SONG_FIELDS = {
    "spotify": "spotify_url",
    "apple_music": "apple_music_url",
    "amazon_music": "amazon_music_url",
    "tiktok": "tiktok_url",
    "youtube": "youtube_url",
}


def _cm_first(d, *keys):
    """Primer valor no vacío entre varias claves (aplana listas)."""
    if not isinstance(d, dict):
        return None
    for k in keys:
        v = d.get(k)
        if isinstance(v, (list, tuple)):
            v = next((x for x in v if x), None)
        if v not in (None, "", 0, "0"):
            return v
    return None


# Tienda de Apple/Amazon para los enlaces que se construyen desde un id (somos de España).
CM_STOREFRONT = "es"
# Cuántas veces, como mucho, se le piden los IDS DE PLATAFORMA a Chartmetric en el refresco de UN
# artista: cada llamada gasta créditos, así que el resto de canciones los rellena su «Actualizar».
CM_GET_IDS_PER_ARTIST = 25


def _cm_scan_id(d: dict, needles: tuple, exclude: tuple = ()) -> str | None:
    """Busca un id dentro del track/álbum de Chartmetric SIN depender del nombre exacto del campo:
    vale cualquier clave que contenga TODAS las palabras de `needles` y ninguna de `exclude`.

    ⚠️ Antes se enumeraban los nombres a mano (`spotify_track_id`, `spotify_id`, `spotify_track_ids`)
    y bastaba que la API devolviera uno con otra forma —o dentro de un objeto anidado— para que no se
    sacara ningún enlace: la canción se quedaba VINCULADA (que solo mira `cm_track`) pero con todos
    los botones vacíos, que es justo el fallo que se veía."""
    if not isinstance(d, dict):
        return None
    for clave, valor in d.items():
        k = str(clave).lower()
        if not all(n in k for n in needles) or any(x in k for x in exclude):
            continue
        if isinstance(valor, (list, tuple)):
            valor = next((x for x in valor if x), None)
        if isinstance(valor, dict):
            valor = valor.get("id") or valor.get("value")
        if valor in (None, "", 0, "0"):
            continue
        return str(valor)
    return None


def _cm_explicit_url(d: dict, *needles) -> str | None:
    """Una URL que venga ya hecha en la respuesta (cualquier clave que la contenga)."""
    if not isinstance(d, dict):
        return None
    for clave, valor in d.items():
        k = str(clave).lower()
        if "url" not in k or not any(n in k for n in needles):
            continue
        if isinstance(valor, (list, tuple)):
            valor = next((x for x in valor if x), None)
        if isinstance(valor, str) and valor.startswith("http"):
            return valor
    return None


# Cómo se escribe el enlace de cada plataforma a partir de su ID. `{id}` es el id de la plataforma y
# `{store}` la tienda (España) donde hace falta.
_CM_URL_TEMPLATES = {
    "track": {
        "spotify": "https://open.spotify.com/track/{id}",
        "youtube": "https://www.youtube.com/watch?v={id}",
        "apple_music": "https://music.apple.com/{store}/song/{id}",
        "amazon_music": "https://music.amazon.{store}/tracks/{id}",
        "deezer": "https://www.deezer.com/track/{id}",
    },
    "album": {
        "spotify": "https://open.spotify.com/album/{id}",
        "youtube": "https://www.youtube.com/playlist?list={id}",
        "apple_music": "https://music.apple.com/{store}/album/{id}",
        "amazon_music": "https://music.amazon.{store}/albums/{id}",
        "deezer": "https://www.deezer.com/album/{id}",
    },
}
# Qué clave de `…/get-ids` alimenta cada plataforma nuestra.
_CM_GET_IDS_KEYS = {
    "spotify": "spotify_ids",
    "youtube": "youtube_ids",
    "apple_music": "itunes_ids",
    "amazon_music": "amazon_ids",
    "deezer": "deezer_ids",
}


def _cm_urls_from_get_ids(payload: dict, kind: str = "track") -> dict:
    """Los enlaces de plataforma a partir de la respuesta de `…/get-ids`.

    ⚠️⚠️ AQUÍ es donde Chartmetric tiene los ids de las demás plataformas: el metadato de un track
    (`/api/track/{id}`) **no los trae** (nombre, ISRC, portada, artistas, álbumes y `cm_statistics`, y
    nada más), así que rascándolo salían siempre CERO enlaces por muy bien vinculada que estuviera la
    canción. Cada clave (`spotify_ids`, `itunes_ids`, `amazon_ids`, `youtube_ids`, `deezer_ids`) es una
    LISTA o `null`: se coge el primero que venga.
    """
    plantillas = _CM_URL_TEMPLATES.get((kind or "track").strip().lower()) or {}
    salida = {}
    if not isinstance(payload, dict):
        return salida
    for plataforma, clave in _CM_GET_IDS_KEYS.items():
        plantilla = plantillas.get(plataforma)
        if not plantilla:
            continue
        crudo = payload.get(clave)
        if isinstance(crudo, (list, tuple)):
            crudo = next((x for x in crudo if x), None)
        if isinstance(crudo, dict):
            crudo = crudo.get("id") or crudo.get("value")
        valor = str(crudo or "").strip()
        if not valor:
            continue
        if valor.startswith("http"):
            salida[plataforma] = valor
        else:
            salida[plataforma] = plantilla.format(id=valor, store=CM_STOREFRONT)
    return salida


def _cm_track_platform_urls(t: dict) -> dict:
    """URLs de plataforma de un TRACK de Chartmetric. Manda la URL explícita si viene; si no, se
    construye desde el id. No hay enlace de TikTok a nivel de canción."""
    out = {}
    if not isinstance(t, dict):
        return out

    sp = _cm_scan_id(t, ("spotify", "track", "id")) or \
         _cm_scan_id(t, ("spotify", "id"), exclude=("album", "artist", "duration", "popularity", "preview"))
    u = _cm_explicit_url(t, "spotify")
    if u:
        out["spotify"] = u
    elif sp:
        out["spotify"] = f"https://open.spotify.com/track/{sp}"

    yt = _cm_scan_id(t, ("youtube", "video", "id")) or \
         _cm_scan_id(t, ("youtube", "id"), exclude=("channel", "artist", "playlist"))
    u = _cm_explicit_url(t, "youtube")
    if u:
        out["youtube"] = u
    elif yt:
        out["youtube"] = f"https://www.youtube.com/watch?v={yt}"

    # Apple Music: `music.apple.com/<tienda>/song/<id>` con el id de iTunes es un enlace válido
    # (redirige al canónico). Antes se exigía una URL explícita, que Chartmetric casi nunca manda,
    # así que el botón de Apple estaba SIEMPRE vacío.
    u = _cm_explicit_url(t, "itunes", "apple")
    ap = _cm_scan_id(t, ("itunes", "track", "id")) or _cm_scan_id(t, ("apple", "track", "id"))
    if u:
        out["apple_music"] = u
    elif ap:
        out["apple_music"] = f"https://music.apple.com/{CM_STOREFRONT}/song/{ap}"

    u = _cm_explicit_url(t, "amazon")
    am = _cm_scan_id(t, ("amazon", "track", "id"))
    if u:
        out["amazon_music"] = u
    elif am:
        out["amazon_music"] = f"https://music.amazon.{CM_STOREFRONT}/tracks/{am}"
    return out


def _cm_album_platform_urls(a: dict) -> dict:
    """Igual que la de un track pero con los ids de ÁLBUM (el deep link de Spotify es /album/…)."""
    out = {}
    if not isinstance(a, dict):
        return out

    sp = _cm_scan_id(a, ("spotify", "album", "id")) or \
         _cm_scan_id(a, ("spotify", "id"), exclude=("track", "artist"))
    u = _cm_explicit_url(a, "spotify")
    if u:
        out["spotify"] = u
    elif sp:
        out["spotify"] = f"https://open.spotify.com/album/{sp}"

    u = _cm_explicit_url(a, "itunes", "apple")
    ap = _cm_scan_id(a, ("itunes", "album", "id")) or _cm_scan_id(a, ("apple", "album", "id"))
    if u:
        out["apple_music"] = u
    elif ap:
        out["apple_music"] = f"https://music.apple.com/{CM_STOREFRONT}/album/{ap}"

    u = _cm_explicit_url(a, "amazon")
    am = _cm_scan_id(a, ("amazon", "album", "id"))
    if u:
        out["amazon_music"] = u
    elif am:
        out["amazon_music"] = f"https://music.amazon.{CM_STOREFRONT}/albums/{am}"
    return out


# Enlace de Chartmetric pegado a mano: se acepta la URL de la app (…/track/123, …/album/456, con o sin
# cola de parámetros) y también el id a pelo, que es lo que la gente copia a veces.
_CM_URL_RE = re.compile(r"/(track|album|song|release)s?/(\d+)", re.I)


def _cm_id_from_url(value: str) -> tuple[str, str]:
    """Devuelve (tipo, id) de un enlace de Chartmetric: ('track'|'album', '12345').
    Con un número a secas devuelve ('', '12345') —el tipo lo pone quien llama— y ('', '') si no hay
    nada reconocible."""
    txt = (value or "").strip()
    if not txt:
        return "", ""
    if txt.isdigit():
        return "", txt
    m = _CM_URL_RE.search(txt)
    if m:
        tipo = m.group(1).lower()
        return ("album" if tipo == "album" else "track"), m.group(2)
    # Un último intento: el último número largo del texto (URLs raras o pegadas a medias).
    nums = re.findall(r"(\d{3,})", txt)
    return "", (nums[-1] if nums else "")


def _cm_recompute_link_status(row) -> None:
    """El estado del enlace de una fila: PENDIENTE · VINCULADA · COMPLETA.

    ⚠️ Antes solo había PENDING/COMPLETE y COMPLETE exigía las CINCO plataformas, que Chartmetric no
    da nunca (de un track saca Spotify y YouTube, de un álbum tres): el estado se quedaba en
    «Pendiente» para siempre aunque la canción estuviera perfectamente vinculada. Ahora, en cuanto hay
    `cm_track`, la fila está VINCULADA (LINKED) y solo pasa a COMPLETE con los cinco enlaces."""
    if row is None:
        return
    tiene = sum(1 for f in _CM_TRACK_SONG_FIELDS.values() if (getattr(row, f, None) or "").strip())
    if tiene >= len(_CM_TRACK_SONG_FIELDS):
        row.cm_link_status = "COMPLETE"
    elif (getattr(row, "cm_track", None) or "").strip():
        row.cm_link_status = "LINKED"
    else:
        row.cm_link_status = "PENDING"


def _cm_apply_song_links(row, cm_track, urls: dict, force: bool = False) -> bool:
    """Rellena los *_url vacíos y no bloqueados; guarda cm_track; recalcula cm_link_status.

    Sirve para Song y Album (ambos tienen los mismos campos). Con `force` (vinculación A MANO) PISA
    los enlaces que hubiera: si se estaba apuntando a otra obra, corregir el vínculo tiene que
    cambiar también los enlaces — si no, los botones se quedan como estaban. Lo BLOQUEADO a mano
    (`cm_links_locked`) no se toca nunca, ni con force."""
    changed = False
    nuevo = str(cm_track or "").strip()
    if nuevo and nuevo != (getattr(row, "cm_track", None) or "").strip():
        if force or not (getattr(row, "cm_track", None) or "").strip():
            row.cm_track = nuevo
            changed = True
    locked = set(_json_list(getattr(row, "cm_links_locked", None)))
    for platform, field in _CM_TRACK_SONG_FIELDS.items():
        if platform in locked:
            continue
        actual = (getattr(row, field, None) or "").strip()
        if actual and not force:
            continue
        u = (urls or {}).get(platform)
        if u and u != actual:
            setattr(row, field, u)
            changed = True
    _cm_recompute_link_status(row)
    return changed


def _cm_resolve_artist_song_links(session_db, artist, track_objs) -> None:
    """Casa cada Song del artista con un track de Chartmetric (por ISRC/nombre) y rellena enlaces.
    Barato: reutiliza los tracks ya descargados en el refresco del artista (sin llamadas extra)."""
    if not track_objs:
        return
    by_isrc, by_name = {}, {}
    for t in track_objs:
        if not isinstance(t, dict):
            continue
        isrc = t.get("isrc")
        if isinstance(isrc, (list, tuple)):
            isrc = next((x for x in isrc if x), None)
        if isrc:
            by_isrc.setdefault(_chartmetric_norm_isrc(isrc), t)
        nm = t.get("name")
        if nm:
            by_name.setdefault(_chartmetric_norm_name(nm), t)
    # ⚠️ El ISRC de la canción no está solo en `Song.isrc`: la mayoría lo tienen en la pestaña de
    # códigos (`SongISRCCode`), y mirando solo el campo el casado automático no encontraba nada.
    # Se cargan TODOS los códigos de estas canciones de una vez (no una consulta por canción).
    canciones = list(getattr(artist, "songs", None) or [])
    otros_isrc = {}
    try:
        ids = [sg.id for sg in canciones if getattr(sg, "id", None)]
        if ids:
            for fila in (session_db.query(SongISRCCode)
                         .filter(SongISRCCode.song_id.in_(ids)).all()):
                otros_isrc.setdefault(str(fila.song_id), []).append(getattr(fila, "code", None))
    except Exception:
        otros_isrc = {}
    pendientes_get_ids = CM_GET_IDS_PER_ARTIST
    for sg in canciones:
        t = None
        candidatos = [getattr(sg, "isrc", None)] + list(otros_isrc.get(str(getattr(sg, "id", "")), []))
        for code in candidatos:
            if not code:
                continue
            t = by_isrc.get(_chartmetric_norm_isrc(code))
            if t:
                break
        if not t and getattr(sg, "title", None):
            t = by_name.get(_chartmetric_norm_name(sg.title))
        if not t:
            continue
        cm_track = _cm_first(t, "cm_track", "id")
        urls = _cm_track_platform_urls(t)
        # ⚠️ Los ids de plataforma NO vienen en los tracks del artista (ni en el metadato de un
        # track): están en `…/get-ids`. Se piden SOLO para las canciones que se quedan sin ningún
        # enlace y con un TOPE (cada llamada gasta créditos): el resto lo rellena el «Actualizar» de
        # esa canción. Sin esto, el casado automático vinculaba pero no dejaba ningún botón.
        if not urls and cm_track and pendientes_get_ids > 0:
            import chartmetric_utils as cm
            urls = _cm_urls_from_get_ids(cm.get_track_platform_ids(cm_track) or {}, "track")
            pendientes_get_ids -= 1
        _cm_apply_song_links(sg, cm_track, urls)


# Cuántas canciones se buscan por ISRC en cada pasada (cada una gasta 1-2 llamadas a Chartmetric) y
# cada cuánto se reintenta una que no apareció (un lanzamiento reciente entra en su catálogo días
# después, así que no se descarta para siempre).
CM_AUTOLINK_PER_RUN = 60
CM_AUTOLINK_RETRY_DAYS = 7


def _cm_autolink_songs_by_isrc(session_db, *, limit: int = CM_AUTOLINK_PER_RUN,
                               force: bool = False, artist_id=None) -> dict:
    """Vincula solas las canciones SIN track de Chartmetric **buscando su ISRC** en la API.

    ⚠️ Esto es lo que `_cm_resolve_artist_song_links` NO puede hacer: ese casa contra los tracks que
    Chartmetric ya devolvió para el artista, así que una canción que no esté en esa lista no se
    vinculaba nunca. Aquí se PREGUNTA por el ISRC (`get_track_ids_from_isrc`, que lo manda **en
    seco**: `cm.norm_isrc` le quita los guiones, porque con ellos Chartmetric no encuentra nada).

    · Se prueban **todos** los ISRC de la canción (el del campo y los de la pestaña de códigos).
    · Al vincularla se rellenan también sus enlaces de plataforma (`…/get-ids`), que es lo que deja
      los botones puestos.
    · Lo que NO aparece se apunta en `cm_isrc_checked_at` y no se vuelve a preguntar hasta pasados
      `CM_AUTOLINK_RETRY_DAYS` días: si no, cada refresco gastaría las mismas llamadas inútiles.
    ⚠️ Si la API FALLA (sin créditos, 429, red) se **para y no se marca nada**: «no he podido
    preguntar» no es «no está» (la regla de la casa; si no, se descartarían canciones buenas).
    """
    import chartmetric_utils as cm
    salida = {"linked": 0, "checked": 0, "pending": 0, "error": None, "names": []}
    if not cm.chartmetric_configured():
        salida["error"] = "Chartmetric no está configurado."
        return salida

    corte = _now_madrid() - timedelta(days=CM_AUTOLINK_RETRY_DAYS)
    query = session_db.query(Song).filter(or_(Song.cm_track.is_(None), Song.cm_track == ""))
    if artist_id is not None:
        query = query.join(SongArtist, SongArtist.song_id == Song.id).filter(SongArtist.artist_id == artist_id)
    if not force:
        query = query.filter(or_(Song.cm_isrc_checked_at.is_(None), Song.cm_isrc_checked_at < corte))
    candidatas = query.order_by(Song.release_date.desc().nullslast()).all()

    # Los ISRC de todas ellas, de UNA consulta (no una por canción).
    codigos = {}
    ids = [sg.id for sg in candidatas]
    if ids:
        for fila in session_db.query(SongISRCCode).filter(SongISRCCode.song_id.in_(ids)).all():
            codigos.setdefault(str(fila.song_id), []).append(getattr(fila, "code", None))

    for sg in candidatas:
        # ⚠️ Sin dedupe se pregunta DOS VECES por el mismo código (está en `Song.isrc` y en
        # `SongISRCCode`), y con el respaldo son cuatro llamadas donde basta una.
        posibles = _norm_isrc_list([getattr(sg, "isrc", None)] + codigos.get(str(sg.id), []))
        if not posibles:
            continue                      # sin ISRC no hay nada que buscar (no gasta llamada)
        if salida["checked"] >= limit:
            salida["pending"] += 1
            continue
        salida["checked"] += 1
        cm_track = ""
        try:
            for code in posibles:
                res = cm.get_track_ids_from_isrc(code, raise_on_error=True) or {}
                cm_track = str(_cm_first(res, "cm_track", "id", "chartmetric_id", "chartmetric_ids") or "")
                if not cm_track:
                    # ⚠️ RESPALDO: lo que no resuelve `get-ids` se busca con el MISMO camino que
                    # funciona a mano (buscar el ISRC en `/api/search`). Se acepta solo si el
                    # resultado trae ESE ISRC: por texto pueden salir homónimos de otros artistas.
                    try:
                        for fila in (cm.search_tracks(code, limit=5) or []):
                            if not isinstance(fila, dict):
                                continue
                            # ⚠️ El ISRC tiene que COINCIDIR. En `/api/search` el campo `isrc` es
                            # opcional, así que con `if suyo and …` un resultado SIN ISRC pasaba el
                            # filtro y se vinculaba a ciegas: enganchar la canción al track de otro
                            # es mucho peor que no vincularla.
                            suyo = cm.norm_isrc(_cm_first(fila, "isrc", "isrc_code") or "")
                            if suyo != cm.norm_isrc(code):
                                continue
                            posible = str(_cm_first(fila, "cm_track", "id", "chartmetric_id",
                                                    "chartmetric_ids") or "")
                            if posible:
                                cm_track = posible
                                break
                    except Exception:
                        app.logger.exception("Chartmetric: fallo buscando el ISRC %s", code)
                if cm_track:
                    break
        except Exception as exc:
            # No se ha podido preguntar: se deja para la próxima SIN marcar nada.
            salida["error"] = str(exc)[:200]
            break
        if not cm_track:
            sg.cm_isrc_checked_at = _now_madrid()
            continue
        urls = {}
        try:
            urls = _cm_urls_from_get_ids(cm.get_track_platform_ids(cm_track) or {}, "track")
        except Exception:
            app.logger.exception("[chartmetric] no se pudieron leer los ids de plataforma de %s", cm_track)
        _cm_apply_song_links(sg, cm_track, urls)
        sg.cm_isrc_checked_at = None       # ya está vinculada: la marca deja de tener sentido
        salida["linked"] += 1
        if len(salida["names"]) < 12:
            salida["names"].append((sg.title or "").strip() or str(sg.id))
    try:
        session_db.commit()
    except Exception:
        session_db.rollback()
        app.logger.exception("[chartmetric] no se pudo guardar el casado por ISRC")
    return salida


def _cm_es_punto(x) -> bool:
    """¿Es un punto de una serie? (lleva fecha y valor)"""
    return isinstance(x, dict) and (("timestp" in x) or ("date" in x)) and ("value" in x or "count" in x)


def _cm_extract_series(data, field=None) -> list:
    """Extrae una serie temporal [{timestp,value}] de una respuesta de stats de Chartmetric.

    ⚠️⚠️ La de un TRACK viene envuelta DOS veces: `{obj: [{domain, track_domain_id, type, data:
    [{timestp, value}]}]}` — o sea, `obj` es una LISTA de series y los puntos están DENTRO de `data`.
    Devolviendo `obj` tal cual (que es lo que se hacía) cada «punto» era una serie sin `timestp`, así
    que se descartaban todos y la canción se quedaba con **0 reproducciones** sin dar ningún error
    (bug real, ago 2026). Cuando hay varias series se prefiere la del `type` pedido.
    Se conservan las formas antiguas: sirve igual para el stat de un ARTISTA (`{obj: {...}}`).
    """
    if not data:
        return []
    obj = data.get("obj", data) if isinstance(data, dict) else data
    if isinstance(obj, list):
        if obj and _cm_es_punto(obj[0]):
            return obj
        # Lista de SERIES: se coge la del `type` pedido y, si no, la primera que traiga puntos.
        elegida = None
        for serie in obj:
            if not isinstance(serie, dict):
                continue
            puntos = serie.get("data")
            if not (isinstance(puntos, list) and puntos and _cm_es_punto(puntos[0])):
                continue
            if field and str(serie.get("type") or "").strip().lower() == str(field).strip().lower():
                return puntos
            if elegida is None:
                elegida = puntos
        return elegida or []
    if isinstance(obj, dict):
        if field and isinstance(obj.get(field), list):
            return obj[field]
        if isinstance(obj.get("data"), list) and obj["data"] and _cm_es_punto(obj["data"][0]):
            return obj["data"]
        for v in obj.values():
            if isinstance(v, list) and v and _cm_es_punto(v[0]):
                return v
    return []


def _cm_point_value(pt: dict):
    """El valor de un punto de Chartmetric, siempre como NÚMERO.

    ⚠️ Su propio OpenAPI avisa de que el valor «may arrive as numeric or string for large counters»
    (un contador grande puede venir entre comillas): guardándolo tal cual se mete texto en una columna
    numérica."""
    crudo = pt.get("value")
    if crudo is None:
        crudo = pt.get("count")
    if isinstance(crudo, str):
        limpio = crudo.strip().replace(",", "")
        try:
            return float(limpio) if "." in limpio else int(limpio)
        except ValueError:
            return None
    return crudo


def _cm_upsert_track_points(session_db, song_id, source, field, series, keep_days=120):
    """Igual que _chartmetric_upsert_metric_points pero sobre ChartmetricTrackMetricPoint (canción)."""
    for pt in (series or [])[-keep_days:]:
        if not isinstance(pt, dict):
            continue
        ts = (pt.get("timestp") or pt.get("date") or "")[:10]
        if not ts:
            continue
        try:
            d = date.fromisoformat(ts)
        except (ValueError, TypeError):
            continue
        existing = (
            session_db.query(ChartmetricTrackMetricPoint)
            .filter_by(song_id=song_id, source=source, field=field, date=d)
            .first()
        )
        if existing:
            existing.value = _cm_point_value(pt)
            existing.fetched_at = _now_madrid()
        else:
            session_db.add(ChartmetricTrackMetricPoint(
                song_id=song_id, source=source, field=field, date=d, value=_cm_point_value(pt),
            ))


def _cm_refresh_song_streams(session_db, song, raise_on_error: bool = False) -> dict:
    """Reproducciones de una canción por su cm_track (Spotify streams; YouTube views).

    Devuelve {'points': n, 'error': str|None} para poder DECIR lo que ha pasado: antes se tragaba
    cualquier fallo y la canción quedaba vinculada y sin datos, sin ninguna pista de por qué."""
    import chartmetric_utils as cm
    resumen = {"points": 0, "error": None}
    if not (getattr(song, "cm_track", None) or "").strip():
        return resumen
    # ⚠️ En SPOTIFY hay que pedir `type=streams` a mano: su valor por defecto es `popularity`, que no
    # son reproducciones. En YOUTUBE **no se manda `type`**: su OpenAPI no declara valores para esa
    # plataforma y se deja su defecto (mandar uno inventado es pedir un 400).
    for source, field, platform, params in (
        ("spotify", "streams", "spotify", {"type": "streams"}),
        ("youtube", "views", "youtube", None),
    ):
        try:
            data = cm.get_track_stat(song.cm_track, platform, params, raise_on_error=raise_on_error)
        except Exception as e:
            resumen["error"] = resumen["error"] or str(e)
            data = {}
        series = _cm_extract_series(data, field)
        if series:
            _cm_upsert_track_points(session_db, song.id, source, field, series)
            resumen["points"] += len(series)
    song.cm_refreshed_at = _now_madrid()
    return resumen


def _cm_songs_due(session_db, limit=200):
    """Canciones con cm_track que toca refrescar hoy según antigüedad del release:
    <1 mes diaria, 1–6 meses semanal, >6 meses mensual. Prioriza las más recientes."""
    today = _now_madrid().date()
    rows = (
        session_db.query(Song)
        .filter(Song.cm_track.isnot(None))
        .filter(Song.cm_track != "")
        .all()
    )
    due = []
    for s in rows:
        age = (today - s.release_date).days if getattr(s, "release_date", None) else 9999
        interval = 1 if age < 31 else (7 if age < 186 else 30)
        last = s.cm_refreshed_at.date() if getattr(s, "cm_refreshed_at", None) else None
        if last is None or (today - last).days >= interval:
            due.append((age, s))
    due.sort(key=lambda x: x[0])
    return [s for _a, s in due[:limit]]


def _cm_refresh_songs_due_bg(force_all=False):
    """Refresca las reproducciones de las canciones vencidas (o todas si force_all). En segundo plano."""
    import chartmetric_utils as cm
    if not cm.chartmetric_configured():
        return
    s = db()
    try:
        if force_all:
            songs = s.query(Song).filter(Song.cm_track.isnot(None)).filter(Song.cm_track != "").all()
        else:
            songs = _cm_songs_due(s, limit=200)
        for song in songs:
            try:
                _cm_refresh_song_streams(s, song)
                s.commit()
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
    finally:
        s.close()


def _cm_value_on_or_before(rows, target):
    """rows ordenadas por fecha desc; primer valor con date <= target (float) o None."""
    for r in rows:
        if r.date <= target and r.value is not None:
            return float(r.value)
    return None


def _cm_song_header(session_db, song):
    """Reproducciones de cabecera de la ficha de canción: Spotify/Apple/Amazon (los 3 huecos siempre),
    total acumulado + flecha semanal (delta últimos 7 días vs 7 previos). arrow: up|down|flat|none."""
    plan = [
        ("spotify", "Spotify", "spotify", "spotify_url"),
        ("apple_music", "Apple Music", "apple_music", "apple_music_url"),
        ("amazon_music", "Amazon Music", "amazon_music", "amazon_music_url"),
    ]
    out = []
    for source, label, key, url_field in plan:
        entry = {"platform": key, "label": label, "url": (getattr(song, url_field, None) or ""), "value_fmt": None, "arrow": "none"}
        try:
            rows = (
                session_db.query(ChartmetricTrackMetricPoint)
                .filter_by(song_id=song.id, source=source, field="streams")
                .order_by(ChartmetricTrackMetricPoint.date.desc())
                .limit(30)
                .all()
            )
            rows = [r for r in rows if r.value is not None]
            if rows:
                cur = float(rows[0].value)
                entry["value_fmt"] = f"{int(cur):,}".replace(",", ".")
                v7 = _cm_value_on_or_before(rows, rows[0].date - timedelta(days=7))
                v14 = _cm_value_on_or_before(rows, rows[0].date - timedelta(days=14))
                if v7 is not None and v14 is not None:
                    last_week, prev_week = cur - v7, v7 - v14
                    base = abs(prev_week) or 1.0
                    ratio = (last_week - prev_week) / base
                    entry["arrow"] = "up" if ratio > 0.03 else ("down" if ratio < -0.03 else "flat")
        except Exception:
            pass
        out.append(entry)
    return out


def _cm_song_review_rows(session_db, limit=400):
    """Filas para la subpestaña Canciones de Integraciones (estado de enlaces + reproducciones)."""
    rows = session_db.query(Song).order_by(Song.release_date.desc().nullslast()).limit(limit).all()
    out = []
    for s in rows:
        links = {p: bool((getattr(s, f, None) or "").strip()) for p, f in _CM_TRACK_SONG_FIELDS.items()}
        sp = (
            session_db.query(ChartmetricTrackMetricPoint)
            .filter_by(song_id=s.id, source="spotify", field="streams")
            .order_by(ChartmetricTrackMetricPoint.date.desc())
            .first()
        )
        out.append({
            "id": str(s.id),
            "title": s.title or "—",
            "artists": ", ".join([a.name for a in (getattr(s, "artists", None) or [])]) or "—",
            "isrc": _norm_isrc(s.isrc),
            "cm_track": s.cm_track or "",
            "status": s.cm_link_status or "PENDING",
            "links": links,
            "missing": [p for p, ok in links.items() if not ok],
            "detail_url": url_for("discografica_song_detail", song_id=s.id),
            "spotify_plays": (f"{int(float(sp.value)):,}".replace(",", ".") if sp and sp.value is not None else None),
        })
    return out


def _cm_album_review_rows(session_db, limit=400):
    """Filas para la subpestaña Álbumes de Integraciones (estado de enlaces; sin reproducciones)."""
    rows = session_db.query(Album).order_by(Album.release_date.desc().nullslast()).limit(limit).all()
    out = []
    for a in rows:
        links = {p: bool((getattr(a, f, None) or "").strip()) for p, f in _CM_TRACK_SONG_FIELDS.items()}
        art = getattr(a, "artist", None)
        if art is None and getattr(a, "artist_id", None):
            art = session_db.get(Artist, a.artist_id)
        out.append({
            "id": str(a.id),
            "title": a.title or "—",
            "artists": getattr(art, "name", "") or "—",
            "cm_track": a.cm_track or "",
            "upc": (getattr(a, "upc_code", None) or ""),
            "status": a.cm_link_status or "PENDING",
            "links": links,
            "missing": [p for p, ok in links.items() if not ok],
            "detail_url": url_for("discografica_album_detail", album_id=a.id, tab="informacion"),
        })
    return out


def _chartmetric_refresh_all_bg():
    """Refresca métricas + playlists de TODOS los artistas vinculados (en segundo plano)."""
    s = db()
    try:
        arts = (
            s.query(Artist)
            .join(ChartmetricArtist, ChartmetricArtist.artist_id == Artist.id)
            .filter(ChartmetricArtist.chartmetric_id.isnot(None))
            .all()
        )
        for a in arts:
            try:
                _chartmetric_refresh_artist(s, a)
            except Exception:
                try:
                    s.rollback()
                except Exception:
                    pass
    except Exception:
        pass
    finally:
        s.close()
    # Tras los artistas, VINCULAR SOLAS las canciones que sigan sin track buscando su ISRC en
    # Chartmetric: el casado del artista solo mira los tracks que la API devuelve para él, así que
    # sin esto una canción que no esté en esa lista no se vinculaba nunca.
    s2 = db()
    try:
        res = _cm_autolink_songs_by_isrc(s2)
        if res.get("linked"):
            app.logger.info("[chartmetric] %s canción(es) vinculadas por su ISRC.", res["linked"])
        if res.get("pending"):
            app.logger.info("[chartmetric] quedan %s canción(es) por buscar (tope por pasada).",
                            res["pending"])
        if res.get("error"):
            app.logger.warning("[chartmetric] el casado por ISRC se ha parado: %s", res["error"])
    except Exception:
        app.logger.exception("[chartmetric] casado por ISRC")
    finally:
        s2.close()
    # Y por último las reproducciones de las canciones vencidas por cadencia (diario/semanal/
    # mensual), que ya incluyen las que se acaban de vincular.
    try:
        _cm_refresh_songs_due_bg()
    except Exception:
        pass


_chartmetric_daily_check_date = None


def _chartmetric_maybe_daily_refresh():
    """Refresco diario automático SIN configurar nada: una vez al día, el primer proceso que entra lo
    reclama de forma atómica en BD (chartmetric_meta) y lanza el refresco de todos en segundo plano.
    Se llama desde home(); barato (throttle en memoria por worker). No lanza."""
    global _chartmetric_daily_check_date
    try:
        import chartmetric_utils as cm
        if not cm.chartmetric_configured():
            return
        today = _now_madrid().date()
        if _chartmetric_daily_check_date == today:
            return  # este worker ya lo comprobó hoy (evita consultar la BD en cada visita)
        _chartmetric_daily_check_date = today
        claimed = False
        s = db()
        try:
            res = s.execute(text(
                "UPDATE chartmetric_meta SET last_auto_refresh = CURRENT_DATE "
                "WHERE id = 1 AND (last_auto_refresh IS NULL OR last_auto_refresh < CURRENT_DATE)"
            ))
            s.commit()
            claimed = (res.rowcount or 0) > 0
        except Exception:
            try:
                s.rollback()
            except Exception:
                pass
        finally:
            s.close()
        if claimed:
            threading.Thread(target=_chartmetric_refresh_all_bg, daemon=True).start()
    except Exception:
        pass


@app.post("/integraciones/chartmetric/cancion/<song_id>/reresolver", endpoint="cm_song_reresolve")
@admin_required
def cm_song_reresolve(song_id):
    """Re-resuelve enlaces + reproducciones de UNA canción vía Chartmetric (por cm_track o ISRC).
    Rellena solo los huecos vacíos no bloqueados (para corregir uno, límpialo antes)."""
    if not (is_master() or can_edit_discografica()):
        return forbid("Sin permisos.")
    import chartmetric_utils as cm
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            abort(404)
        cm_track = (song.cm_track or "").strip()
        if not cm_track:
            # ⚠️ El ISRC se busca SIEMPRE en seco (sin guiones: lo hace `cm.norm_isrc`), y se prueban
            # todos los que tenga la canción —el del campo y los de la pestaña de códigos—, no solo
            # `Song.isrc`, que en muchas está vacío.
            # ⚠️ `raise_on_error`: si Chartmetric falla (sin créditos, 429, red), se dice ESO. Sin
            # eso el fallo de la API era indistinguible de «ese ISRC no está» y el aviso mandaba a
            # revisar un ISRC que estaba bien.
            for code in (_current_song_isrcs(session_db, song.id, include_song_field=True) or []):
                ids = cm.get_track_ids_from_isrc(code, raise_on_error=True)
                cm_track = str(_cm_first(ids, "cm_track", "id", "chartmetric_id", "chartmetric_ids") or "")
                if cm_track:
                    break
        if cm_track:
            # ⚠️ Los enlaces están en `…/get-ids`, NO en el metadato del track (que no trae ningún id
            # de plataforma). El metadato se sigue mirando como RESPALDO por si algún día los añade.
            ids = cm.get_track_platform_ids(cm_track, raise_on_error=True) or {}
            urls = _cm_urls_from_get_ids(ids, "track")
            td = cm.get_track(cm_track) or {}
            td.setdefault("cm_track", cm_track)
            for plataforma, enlace in (_cm_track_platform_urls(td) or {}).items():
                urls.setdefault(plataforma, enlace)
            # Re-resolver a mano es para ARREGLAR lo que está mal: si lo que dice Chartmetric hoy no
            # coincide con lo guardado, manda Chartmetric (salvo lo bloqueado a mano).
            _cm_apply_song_links(song, cm_track, urls, force=True)
            stats = _cm_refresh_song_streams(session_db, song, raise_on_error=True)
            session_db.commit()
            partes = [f"{len(urls)} enlace{'' if len(urls) == 1 else 's'}"]
            if stats["points"]:
                partes.append(f"{stats['points']} punto{'' if stats['points'] == 1 else 's'} de reproducciones")
            flash("Canción re-resuelta con Chartmetric: " + " y ".join(partes) + ".", "success")
            # Vinculada pero sin nada que enseñar: se DICE, en vez de dejarla en verde y vacía.
            if not urls:
                flash("Chartmetric no ha devuelto ningún enlace de plataforma para este track. "
                      "Mételos a mano en la ficha de la canción.", "warning")
            if stats["error"]:
                flash(f"No se pudieron traer las reproducciones: {stats['error']}", "warning")
            elif not stats["points"]:
                flash("Chartmetric todavía no tiene reproducciones de este track.", "info")
        else:
            flash("No se encontró el track en Chartmetric. Revisa el ISRC o mete los enlaces a mano.", "warning")
    except Exception as e:
        session_db.rollback()
        flash(f"Error al re-resolver: {e}", "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or url_for("integrations_view"))


@app.post("/integraciones/chartmetric/album/<album_id>/reresolver", endpoint="cm_album_reresolve")
@admin_required
def cm_album_reresolve(album_id):
    """Re-resuelve los enlaces de UN álbum vía Chartmetric (por su id o por el UPC/EAN, en seco)."""
    if not (is_master() or can_edit_discografica()):
        return forbid("Sin permisos.")
    import chartmetric_utils as cm
    session_db = db()
    try:
        album = session_db.get(Album, to_uuid(album_id))
        if not album:
            abort(404)
        cm_album = (getattr(album, "cm_track", None) or "").strip()
        if not cm_album:
            # El UPC del álbum y, si no lo tiene, los códigos de producto de sus formatos.
            # ⚠️ Las REFERENCIAS que genera la casa (REF00001) NO son un código de barras: se
            # descartan (`generated_sequence` las delata) y además se exige forma de UPC/EAN, o se
            # acabaría preguntando a Chartmetric por «00001» y vinculando el disco de otro.
            codigos = [getattr(album, "upc_code", None)]
            codigos += [r.code for r in (session_db.query(AlbumProductCode)
                                         .filter(AlbumProductCode.album_id == album.id,
                                                 AlbumProductCode.generated_sequence.is_(None))
                                         .order_by(AlbumProductCode.created_at.asc()).all())]
            for code in codigos:
                code_n = cm.norm_code(code)
                ids = cm.get_album_ids_from_upc(code_n) if len(code_n) >= 8 else {}
                cm_album = str(_cm_first(ids, "cm_album", "id", "chartmetric_id") or "")
                if cm_album:
                    break
        if cm_album:
            ok, mensaje = _cm_link_row_manual(session_db, album, "album", cm_album)
            if ok:
                session_db.commit()
                flash("Álbum re-resuelto con Chartmetric.", "success")
            else:
                flash(mensaje, "warning")
        else:
            flash("No se encontró el álbum en Chartmetric. Pega su enlace para vincularlo a mano.", "warning")
    except Exception as e:
        session_db.rollback()
        flash(f"Error al re-resolver: {e}", "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or url_for("integrations_view"))


def _cm_link_row_manual(session_db, row, kind: str, cm_id: str) -> tuple[bool, str]:
    """Vincula NUESTRA canción o álbum con un id de Chartmetric y rellena los enlaces que falten.

    Devuelve (ok, mensaje). No confía en el id: primero se lo pide a Chartmetric, y si ese id no
    existe no se guarda nada (así un enlace mal pegado no deja la ficha apuntando a otra obra)."""
    import chartmetric_utils as cm
    cm_id = (cm_id or "").strip()
    if not cm_id:
        return False, "No he encontrado el id en lo que has pegado. Copia el enlace de Chartmetric de la canción o del álbum."
    # ⚠️ Los enlaces de plataforma salen de `…/get-ids`; el metadato (que es lo que confirma que ese
    # id existe) NO trae ninguno. Se piden las dos cosas y el metadato queda como respaldo.
    if kind == "album":
        datos = cm.get_album(cm_id) or {}
        urls = _cm_urls_from_get_ids(cm.get_album_platform_ids(cm_id) or {}, "album")
        for plataforma, enlace in (_cm_album_platform_urls(datos) or {}).items():
            urls.setdefault(plataforma, enlace)
    else:
        datos = cm.get_track(cm_id) or {}
        urls = _cm_urls_from_get_ids(cm.get_track_platform_ids(cm_id) or {}, "track")
        for plataforma, enlace in (_cm_track_platform_urls(datos) or {}).items():
            urls.setdefault(plataforma, enlace)
    if not datos:
        return False, ("En Chartmetric no hay ningún %s con el id %s. Comprueba el enlace."
                       % ("álbum" if kind == "album" else "track", cm_id))
    datos.setdefault("cm_track", cm_id)
    # `cm_track` puede venir ya puesto de un vínculo anterior equivocado: al hacerlo a mano manda lo
    # que dice quien vincula, y con él los ENLACES (force=True) — si no, los botones se quedarían
    # apuntando a la obra equivocada.
    row.cm_track = str(cm_id)
    _cm_apply_song_links(row, cm_id, urls, force=True)
    nombre = (_cm_first(datos, "name", "title") or "").strip()
    return True, ("Vinculado con «%s» (id %s)." % (nombre, cm_id) if nombre else "Vinculado (id %s)." % cm_id)


@app.post("/integraciones/chartmetric/vincular", endpoint="cm_link_manual")
@admin_required
def cm_link_manual():
    """Vincula A MANO una canción o un álbum con Chartmetric, pegando su ENLACE (o eligiéndolo en el
    buscador). Es la salida para cuando no se encuentra solo por el ISRC."""
    if not (is_master() or can_edit_discografica()):
        return forbid("Sin permisos.")
    kind = (request.form.get("kind") or "song").strip().lower()
    obj_id = (request.form.get("id") or "").strip()
    pegado = (request.form.get("cm_url") or request.form.get("cm_id") or "").strip()
    nxt = request.form.get("next") or url_for("integrations_view")
    tipo_url, cm_id = _cm_id_from_url(pegado)
    if tipo_url and ((tipo_url == "album") != (kind == "album")):
        flash("Ese enlace es de un %s y lo estás vinculando a %s. Revísalo."
              % ("álbum" if tipo_url == "album" else "track",
                 "un álbum" if kind == "album" else "una canción"), "warning")
        return redirect(nxt)
    session_db = db()
    try:
        row = session_db.get(Album if kind == "album" else Song, to_uuid(obj_id))
        if not row:
            abort(404)
        ok, mensaje = _cm_link_row_manual(session_db, row, kind, cm_id)
        if not ok:
            flash(mensaje, "warning")
            return redirect(nxt)
        if kind != "album":
            _cm_refresh_song_streams(session_db, row)
        session_db.commit()
        flash(mensaje, "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo vincular: {e}", "danger")
    finally:
        session_db.close()
    return redirect(nxt)


@app.get("/api/chartmetric/buscar", endpoint="api_cm_search")
@admin_required
def api_cm_search():
    """Buscador de Chartmetric para vincular a mano: canciones o álbumes por nombre.
    Acepta también un ISRC/UPC o un enlace pegado, que es lo que uno tiene a mano."""
    if not (is_master() or can_edit_discografica()):
        return jsonify({"ok": False, "message": "Sin permisos."}), 403
    import chartmetric_utils as cm
    if not cm.chartmetric_configured():
        return jsonify({"ok": False, "message": "Chartmetric no está configurada."}), 400
    kind = (request.args.get("kind") or "song").strip().lower()
    q = (request.args.get("q") or "").strip()
    if len(q) < 2:
        return jsonify({"ok": True, "results": []})
    salida = []
    try:
        # 1) ¿Es un enlace o un id? Se resuelve directo, que es más fiable que buscar por nombre.
        # ⚠️ Un UPC/EAN es TODO dígitos (12-13) y se estaba probando primero como id de Chartmetric,
        # que es otra cosa: si por casualidad existía ese id, el resultado era de otra obra. Con
        # pinta de código de barras se va al paso 2 (buscar por UPC).
        tipo_url, cm_id = _cm_id_from_url(q)
        parece_codigo = q.isdigit() and len(q) >= 8
        if cm_id and (tipo_url or (q.isdigit() and not parece_codigo)):
            datos = (cm.get_album(cm_id) if kind == "album" else cm.get_track(cm_id)) or {}
            if datos:
                salida.append(_cm_search_result(datos, kind, cm_id))
        # 2) ¿Es un ISRC (canción) o un UPC (álbum)?
        if not salida:
            if kind == "album":
                code = cm.norm_code(q)
                ids = cm.get_album_ids_from_upc(code) if len(code) >= 8 else {}
            else:
                code = cm.norm_isrc(q)
                ids = cm.get_track_ids_from_isrc(code) if len(code) == 12 else {}
            # ⚠️ `chartmetric_ids` es la clave que get-ids devuelve para un TRACK (la de álbum sí
            # estaba, por eso los discos sí resolvían por aquí): sin ella la búsqueda manual de una
            # canción nunca usaba el camino barato y siempre caía en /api/search.
            ref = str(_cm_first(ids, "cm_track", "cm_album", "id", "chartmetric_id", "chartmetric_ids") or "")
            if ref:
                datos = (cm.get_album(ref) if kind == "album" else cm.get_track(ref)) or {}
                salida.append(_cm_search_result(datos or ids, kind, ref))
        # 3) Por nombre.
        if not salida:
            filas = cm.search_albums(q, limit=12) if kind == "album" else cm.search_tracks(q, limit=12)
            for it in (filas or []):
                if not isinstance(it, dict):
                    continue
                ref = str(_cm_first(it, "cm_track", "cm_album", "id") or "")
                if not ref:
                    continue
                salida.append(_cm_search_result(it, kind, ref))
    except Exception as e:
        return jsonify({"ok": False, "message": str(e)}), 400
    return jsonify({"ok": True, "results": salida})


def _cm_search_result(d: dict, kind: str, cm_id: str) -> dict:
    """Un resultado del buscador de Chartmetric, con lo justo para reconocerlo de un vistazo."""
    d = d if isinstance(d, dict) else {}
    artistas = d.get("artists") or d.get("artist_names") or d.get("artist")
    if isinstance(artistas, (list, tuple)):
        nombres = []
        for a in artistas:
            if isinstance(a, dict):
                nombres.append((a.get("name") or "").strip())
            elif a:
                nombres.append(str(a).strip())
        artistas = ", ".join([x for x in nombres if x])
    return {
        "cm_id": str(cm_id),
        "name": (_cm_first(d, "name", "title") or "—"),
        "artists": (artistas or ""),
        "code": (_cm_first(d, "isrc", "upc", "ean") or ""),
        "release_date": (str(_cm_first(d, "release_date", "releaseDate") or "")[:10]),
        "image_url": _chartmetric_track_image(d),
        "url": ("https://app.chartmetric.com/%s/%s" % ("album" if kind == "album" else "track", cm_id)),
    }


@app.post("/integraciones/chartmetric/limpiar-enlace", endpoint="cm_link_clear")
@admin_required
def cm_link_clear():
    """Limpia un enlace de plataforma de una canción/álbum y lo desbloquea (para re-resolver o rehacer)."""
    if not (is_master() or can_edit_discografica()):
        return forbid("Sin permisos.")
    kind = (request.form.get("kind") or "song").strip().lower()
    platform = (request.form.get("platform") or "").strip().lower()
    obj_id = (request.form.get("id") or "").strip()
    field = _CM_TRACK_SONG_FIELDS.get(platform)
    if not field:
        flash("Plataforma no soportada.", "warning")
        return redirect(request.form.get("next") or url_for("integrations_view"))
    session_db = db()
    try:
        row = session_db.get(Album if kind == "album" else Song, to_uuid(obj_id))
        if not row:
            abort(404)
        setattr(row, field, None)
        try:
            locked = set(_json_list(getattr(row, "cm_links_locked", None)))
            locked.discard(platform)
            row.cm_links_locked = sorted(locked)
        except Exception:
            pass
        session_db.commit()
        flash("Enlace limpiado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"Error al limpiar: {e}", "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or url_for("integrations_view"))


@app.post("/integraciones/chartmetric/cancion/<song_id>/comprobar-rutas", endpoint="cm_song_diagnose")
@admin_required
def cm_song_diagnose(song_id):
    """COMPROBAR RUTAS: pregunta a Chartmetric por este track y enseña qué contesta cada una.

    Cuando algo no llega, lo primero es saber si la ruta existe, si falta un permiso o si la cuenta
    está sin créditos, y eso solo lo dice la propia API (el mismo patrón que el diagnóstico de
    Holded). Así se ve en pantalla en vez de tener que leer el log."""
    if not (is_master() or can_edit_discografica()):
        return forbid("Sin permisos.")
    import chartmetric_utils as cm
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if not song:
            abort(404)
        cm_track = (song.cm_track or "").strip()
        if not cm_track:
            flash("Esta canción todavía no está vinculada con Chartmetric: no hay nada que comprobar.",
                  "warning")
        else:
            filas = cm.diagnose_track(cm_track)
            if not filas:
                flash("No se ha podido preguntar a Chartmetric.", "warning")
            for fila in filas:
                flash("%s %s → %s · %s" % ("✅" if fila["ok"] else "❌", fila["para"],
                                           fila["ruta"], fila["detalle"]),
                      "success" if fila["ok"] else "warning")
    except Exception as e:
        flash("No se pudo comprobar: %s" % e, "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or url_for("integrations_view"))


def _chartmetric_playlists_grouped(session_db, artist_id=None, cm_track=None, song_id=None, status="current", only_official=True):
    """Playlists agrupadas por plataforma (Spotify/Apple/Amazon), ordenadas por oyentes desc.
    Marca is_new si la canción entró en la lista en los últimos 7 días."""
    q = session_db.query(ChartmetricPlaylistEntry).filter(ChartmetricPlaylistEntry.status == status)
    if artist_id is not None:
        q = q.filter(ChartmetricPlaylistEntry.artist_id == artist_id)
    if song_id is not None:
        q = q.filter(ChartmetricPlaylistEntry.song_id == song_id)
    if cm_track:
        q = q.filter(ChartmetricPlaylistEntry.cm_track == str(cm_track))
    if only_official:
        q = q.filter(ChartmetricPlaylistEntry.is_official.is_(True))
    entries = q.all()
    # Portada principal y título de NUESTRAS canciones enlazadas (en bloque, sin N+1).
    song_ids = {e.song_id for e in entries if e.song_id}
    song_map = {}
    if song_ids:
        for sg in session_db.query(Song.id, Song.title, Song.cover_url).filter(Song.id.in_(song_ids)).all():
            song_map[sg.id] = {"title": sg.title, "cover_url": sg.cover_url}
    platform_logos = {"spotify": "spotify.png", "applemusic": "apple_music.png", "amazon": "amazon_music.png"}
    today = _now_madrid().date()
    groups = []
    for key, label in (("spotify", "Spotify"), ("applemusic", "Apple Music"), ("amazon", "Amazon Music")):
        items = [e for e in entries if e.platform == key]
        items.sort(key=lambda e: float(e.followers or 0), reverse=True)
        rows = []
        for e in items:
            sinfo = song_map.get(e.song_id) if e.song_id else None
            rows.append({
                "track_name": e.track_name,
                "song_id": (str(e.song_id) if e.song_id else None),
                "song_title": (sinfo or {}).get("title"),
                # Portada: la de NUESTRA canción enlazada; si no hay, la de Chartmetric (portada del track).
                "song_cover": (sinfo or {}).get("cover_url") or getattr(e, "track_image_url", None),
                "playlist_name": e.playlist_name,
                "position": e.position,
                "days": e.days_in_list,
                "added_at": e.added_at,
                "is_new": bool(e.added_at and (today - e.added_at).days <= 7),
                "followers": int(e.followers) if e.followers is not None else None,
                "image_url": e.image_url,
                "owner_name": e.owner_name,
            })
        if rows:
            groups.append({"key": key, "label": label, "logo": platform_logos.get(key), "count": len(rows), "rows": rows})
    return groups


def _chartmetric_playlist_counts(session_db, song_id):
    """Recuento de playlists oficiales por plataforma (actuales/anteriores/total) de una canción."""
    rows = (
        session_db.query(
            ChartmetricPlaylistEntry.platform,
            ChartmetricPlaylistEntry.status,
            func.count().label("n"),
        )
        .filter(ChartmetricPlaylistEntry.song_id == song_id)
        .filter(ChartmetricPlaylistEntry.is_official.is_(True))
        .group_by(ChartmetricPlaylistEntry.platform, ChartmetricPlaylistEntry.status)
        .all()
    )
    labels = {"spotify": "Spotify", "applemusic": "Apple Music", "amazon": "Amazon Music"}
    logos = {"spotify": "spotify.png", "applemusic": "apple_music.png", "amazon": "amazon_music.png"}
    by = {k: {"key": k, "label": v, "logo": logos.get(k), "current": 0, "past": 0, "total": 0} for k, v in labels.items()}
    for platform, status, n in rows:
        if platform not in by:
            continue
        if status == "past":
            by[platform]["past"] += int(n)
        else:
            by[platform]["current"] += int(n)
        by[platform]["total"] += int(n)
    out = [by[k] for k in ("spotify", "applemusic", "amazon") if by[k]["total"] > 0]
    totals = {
        "current": sum(x["current"] for x in out),
        "past": sum(x["past"] for x in out),
        "total": sum(x["total"] for x in out),
    }
    return {"platforms": out, "totals": totals}


def _chartmetric_playlisting_overview(session_db):
    """Sección Playlisting: artistas sincronizados con sus playlists oficiales ACTUALES, agrupadas.
    Marca has_past si el artista tiene además playlists anteriores (para el filtro 'con anteriores')."""
    arts = (
        session_db.query(Artist)
        .join(ChartmetricArtist, ChartmetricArtist.artist_id == Artist.id)
        .filter(ChartmetricArtist.chartmetric_id.isnot(None))
        .order_by(Artist.name.asc())
        .all()
    )
    past_ids = {
        r[0] for r in session_db.query(ChartmetricPlaylistEntry.artist_id)
        .filter(ChartmetricPlaylistEntry.status == "past")
        .filter(ChartmetricPlaylistEntry.is_official.is_(True))
        .distinct().all()
    }
    out = []
    for a in arts:
        groups = _chartmetric_playlists_grouped(session_db, artist_id=a.id)
        total = sum(g["count"] for g in groups)
        has_past = a.id in past_ids
        if total or has_past:
            out.append({
                "artist_id": str(a.id),
                "artist_name": a.name,
                "artist_photo": a.photo_url,
                "total": total,
                "has_past": has_past,
                "groups": groups,
            })
    return out


@app.get("/playlisting", endpoint="playlisting_view")
@admin_required
def playlisting_view():
    """Sección Playlisting: artistas y en qué playlists oficiales están sus canciones ahora mismo."""
    s = db()
    try:
        overview = _chartmetric_playlisting_overview(s)
        last_refresh = s.query(func.max(ChartmetricArtist.last_refreshed_at)).scalar()
    finally:
        s.close()
    return render_template("playlisting.html", title="Playlisting", overview=overview, last_refresh=last_refresh)


@app.get("/cron/chartmetric/refresh", endpoint="cron_chartmetric_refresh")
def cron_chartmetric_refresh():
    """Refresco diario automático de Chartmetric (lo llama una tarea programada de Render con ?key=).
    Protegido por CHARTMETRIC_CRON_KEY; no requiere sesión. Lanza el refresco en segundo plano."""
    expected = (os.getenv("CHARTMETRIC_CRON_KEY") or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    import chartmetric_utils as cm
    if not cm.chartmetric_configured():
        return ("chartmetric no configurado", 200)
    threading.Thread(target=_chartmetric_refresh_all_bg, daemon=True).start()
    return ("refresco en marcha", 200)


# =========================================================
# ENTERTICKET — integración con la ticketera del grupo (venta en tiempo casi real)
# =========================================================
# Diseño (probado contra la API en vivo; ver enterticket_utils.py):
# - El token es ÚNICO para toda la cuenta (renovarlo invalida el anterior) → se comparte en BD
#   (enterticket_meta) entre todos los workers; caché local de 60 s por proceso.
# - Espejo local: enterticket_events (catálogo + vínculo a concierto), enterticket_ticket_types
#   (estado por tipo), enterticket_sales (cada entrada, para histórico diario / compradores /
#   invitaciones / plano) y buyers/buyer_events (compradores deduplicados por email).
# - Sincronización incremental: ventas nuevas con `desde_id` y cambios (anulaciones/devoluciones)
#   con `updated`; se dispara al abrir la pestaña Ticketing (si han pasado >10 min), desde los
#   botones «Actualizar», el polling de la pestaña y el cron externo /cron/enterticket/refresh.
import enterticket_utils as et_api
from models import engine as _et_engine
from sqlalchemy.dialects.postgresql import insert as _et_pg_insert

_ET_TOKEN_LOCAL = {"token": None, "read_at": 0.0}
_ET_SYNC_ACTIVE: set = set()          # ids (str) de eventos sincronizándose en este proceso
_ET_SYNC_GUARD = threading.Lock()
_ET_SALES_PAGE = 500


@contextmanager
def _et_pg_lock(key: str, wait: bool = False):
    """Exclusión ENTRE workers/procesos vía advisory lock de Postgres (conexión dedicada, se
    libera al salir). `wait=False` → yields False si otro proceso lo tiene (saltarse el trabajo);
    `wait=True` → bloquea hasta obtenerlo (para secciones cortas como renovar el token único).
    Si la BD no responde, yields True (best-effort: mejor sincronizar sin lock que no hacerlo)."""
    conn = None
    got = True
    try:
        conn = _et_engine.connect()
        if wait:
            conn.exec_driver_sql("SELECT pg_advisory_lock(hashtext(%s))", (key,))
            got = True
        else:
            got = bool(conn.exec_driver_sql("SELECT pg_try_advisory_lock(hashtext(%s))", (key,)).scalar())
    except Exception:
        got = True
    try:
        yield got
    finally:
        if conn is not None:
            try:
                if got:
                    conn.exec_driver_sql("SELECT pg_advisory_unlock(hashtext(%s))", (key,))
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass


def _et_fmt_dt(dt) -> str:
    """Formatea una marca de tiempo para la UI en hora española (las timestamptz vuelven de BD
    en UTC: sin convertir se mostrarían 1-2 h atrasadas)."""
    if not dt:
        return ""
    try:
        if dt.tzinfo is not None:
            dt = dt.astimezone(TZ_MADRID)
        return dt.strftime("%d/%m/%Y %H:%M")
    except Exception:
        return ""


def _et_meta_row(s):
    row = s.get(EnterticketMeta, 1)
    if not row:
        try:
            row = EnterticketMeta(id=1)
            s.add(row)
            s.commit()
        except Exception:
            # Otro worker la creó a la vez (PK única): recuperar la suya.
            s.rollback()
            row = s.get(EnterticketMeta, 1)
    return row


def _et_get_token(s, force_refresh: bool = False, bad_token: str | None = None) -> str:
    """Token compartido en BD (la API solo admite UNO activo). Caché local 60 s por worker.
    La RENOVACIÓN va serializada con un advisory lock: si dos procesos re-autenticaran a la vez,
    cada auth() invalida el token del otro y podría quedar persistido uno ya inválido."""
    now = time.time()
    if not force_refresh and _ET_TOKEN_LOCAL["token"] and now - _ET_TOKEN_LOCAL["read_at"] < 60:
        return _ET_TOKEN_LOCAL["token"]
    row = _et_meta_row(s)
    if row.token and not force_refresh:
        _ET_TOKEN_LOCAL.update(token=row.token, read_at=now)
        return row.token
    with _et_pg_lock("et_token", wait=True):
        try:
            s.refresh(row)
        except Exception:
            pass
        # Con el lock cogido: si otro proceso YA renovó (token distinto del que falló), usarlo.
        if row.token and row.token != (bad_token or ""):
            _ET_TOKEN_LOCAL.update(token=row.token, read_at=time.time())
            return row.token
        token, expire = et_api.auth()
        row.token = token
        row.token_expires_at = expire
        s.commit()
    _ET_TOKEN_LOCAL.update(token=token, read_at=time.time())
    return token


def _et_call(s, fn, *args, **kwargs):
    """Llama `fn(token, ...)` renovando el token único de forma segura entre workers:
    si caduca, primero RELEE la BD (otro worker pudo renovarlo ya) y solo si sigue sin valer
    se re-autentica bajo lock (guardando el token nuevo para el resto)."""
    token = _et_get_token(s)
    try:
        return fn(token, *args, **kwargs)
    except et_api.EnterticketAuthError:
        pass
    _ET_TOKEN_LOCAL["token"] = None
    fresh = _et_get_token(s, force_refresh=True, bad_token=token)
    return fn(fresh, *args, **kwargs)


def _et_parse_date(v):
    try:
        return datetime.strptime((v or "").strip()[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def _et_parse_dt(v):
    try:
        return datetime.strptime((v or "").strip()[:19], "%Y-%m-%d %H:%M:%S")
    except Exception:
        return None


def _et_money(v) -> Decimal:
    try:
        return Decimal(str(v if v is not None else 0)).quantize(Decimal("0.01"))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal("0")


def _et_apply_event_info(row: EnterticketEvent, info: dict) -> None:
    """Vuelca `info` de /eventos sobre la fila espejo (solo campos presentes)."""
    if info.get("nombre"):
        row.name = str(info.get("nombre")).strip()
    if info.get("id_cliente") is not None:
        row.et_client_id = int(info.get("id_cliente") or 0) or None
    d = _et_parse_date(info.get("fecha_inicio"))
    if d:
        row.event_date = d
    d = _et_parse_date(info.get("fecha_fin"))
    if d:
        row.event_end_date = d
    if info.get("hora_inicio"):
        row.start_time = str(info.get("hora_inicio"))[:8]
    if info.get("recinto_nombre") is not None:
        row.venue_name = (info.get("recinto_nombre") or "").strip().rstrip(".")
    if info.get("recinto_direccion_poblacion") is not None:
        row.venue_town = (info.get("recinto_direccion_poblacion") or "").strip()
    if info.get("recinto_direccion_provincia") is not None:
        row.venue_province = (info.get("recinto_direccion_provincia") or "").strip()
    if info.get("url_enterticket"):
        row.url_enterticket = info.get("url_enterticket")
    img = info.get("url_imagen_poster") or info.get("url_imagen_cabecera")
    if img:
        row.image_url = img
    if info.get("activo") is not None:
        row.active = bool(info.get("activo"))
    if info.get("mapping") is not None:
        row.has_seat_mapping = bool(info.get("mapping"))
    if info.get("numero_entradas") is not None:
        try:
            row.capacity_on_sale = int(info.get("numero_entradas") or 0) or None
        except Exception:
            pass
    row.updated_at = datetime.now(TZ_MADRID)


def _et_apply_ticket_types(s, ev: EnterticketEvent, entradas: list) -> None:
    """Refresca los tipos de entrada (vendidas/disponibles/precio) desde el detalle del evento."""
    existing = {t.et_entrada_id: t for t in (ev.ticket_types or [])}
    seen = set()
    for idx, e in enumerate(entradas or []):
        try:
            eid = int(e.get("id") or 0)
        except Exception:
            continue
        if not eid or eid in seen:
            continue
        seen.add(eid)
        t = existing.get(eid)
        if not t:
            t = EnterticketTicketType(event_id=ev.id, et_entrada_id=eid, name="")
            s.add(t)
        t.name = (e.get("nombre") or f"Entrada {eid}").strip()
        t.price = _et_money((e.get("precio") or {}).get("precio") if isinstance(e.get("precio"), dict) else e.get("precio"))
        t.qty_sold = int(e.get("cantidad_vendidas") or 0)
        t.qty_available = int(e.get("cantidad_disponible") or 0)
        t.is_numbered = bool(e.get("entrada_numerada"))
        t.color = e.get("color_icono") or None
        t.accesses = int(e.get("accesos_registrados") or 0)
        t.sort_order = idx
        t.updated_at = datetime.now(TZ_MADRID)
    # tipos que ya no existen en ET: se eliminan del espejo (las ventas guardan el nombre)
    for eid, t in existing.items():
        if eid not in seen:
            s.delete(t)


def _et_upsert_sales_page(s, ev: EnterticketEvent, page: list) -> tuple[int, int]:
    """Inserta/actualiza una página de /ventas. Devuelve (max_id, max_updated) vistos."""
    ids = [int(r.get("id") or 0) for r in page if r.get("id")]
    existing = {}
    if ids:
        for row in s.query(EnterticketSale).filter(
                EnterticketSale.event_id == ev.id, EnterticketSale.et_sale_id.in_(ids)).all():
            existing[int(row.et_sale_id)] = row
    max_id, max_upd = 0, 0
    for r in page:
        try:
            sid = int(r.get("id") or 0)
        except Exception:
            continue
        if not sid:
            continue
        max_id = max(max_id, sid)
        try:
            max_upd = max(max_upd, int(r.get("updated_at") or 0))
        except Exception:
            pass
        row = existing.get(sid)
        if not row:
            row = EnterticketSale(event_id=ev.id, et_sale_id=sid)
            s.add(row)
            existing[sid] = row
        try:
            row.et_entrada_id = int(r.get("id_entrada") or 0) or None
        except Exception:
            row.et_entrada_id = None
        row.entrada_name = (r.get("nombre_entrada") or "").strip() or None
        row.purchase_at = _et_parse_dt(r.get("fecha_compra"))
        row.price = _et_money(r.get("precio"))
        row.fees = _et_money(r.get("gastos_distribucion"))
        row.total = _et_money(r.get("precio_total"))
        row.mode = (r.get("modo_venta") or "").strip() or None
        row.is_invitation = bool(r.get("id_invitacion_tipo")) or bool((r.get("invitacion_concepto") or "").strip())
        row.invitation_concept = (r.get("invitacion_concepto") or "").strip() or None
        try:
            row.cancelled = bool(float(r.get("anulada") or 0))
        except Exception:
            row.cancelled = bool(r.get("anulada"))
        row.refunded = bool(r.get("devuelta"))
        row.sector = (r.get("sector") or "").strip() or None
        row.seat = (str(r.get("asiento")) if r.get("asiento") is not None else "").strip() or None
        row.buyer_name = (r.get("nombre") or "").strip() or None
        row.buyer_email = ((r.get("email") or "").strip().lower()) or None
        row.buyer_phone = (str(r.get("telf_movil")) if r.get("telf_movil") else "").strip() or None
        row.buyer_postal_code = (str(r.get("direccion_cod_postal")) if r.get("direccion_cod_postal") else "").strip() or None
        row.accepts_marketing = bool(r.get("acepta_recibir_publicidad"))
        try:
            row.updated_at_unix = int(r.get("updated_at") or 0)
        except Exception:
            pass
    return max_id, max_upd


def _et_recompute_buyers_for_event(s, ev: EnterticketEvent) -> None:
    """Reconstruye la base de COMPRADORES de este evento: dedupe por email (ventas válidas,
    ni anuladas ni devueltas) y agregados globales por comprador."""
    q = (s.query(
            func.lower(EnterticketSale.buyer_email).label("email"),
            func.count().label("n"),
            func.sum(EnterticketSale.price).label("amt"),
            func.min(EnterticketSale.purchase_at).label("first_at"),
            func.max(EnterticketSale.purchase_at).label("last_at"),
            func.bool_or(EnterticketSale.accepts_marketing).label("mkt"),
            func.max(EnterticketSale.buyer_name).label("name"),
            func.max(EnterticketSale.buyer_phone).label("phone"),
        )
        .filter(EnterticketSale.event_id == ev.id,
                EnterticketSale.cancelled.is_(False),
                EnterticketSale.refunded.is_(False),
                EnterticketSale.buyer_email.isnot(None),
                EnterticketSale.buyer_email != "")
        .group_by(func.lower(EnterticketSale.buyer_email)).all())
    # CATEGORÍAS de entrada compradas por cada uno («Pista», «Grada»…): con esto se filtra y se
    # ordena el listado de compradores y se elige a quién va un envío. Una sola consulta agrupada.
    cats: dict[str, list[str]] = {}
    for fila in (s.query(func.lower(EnterticketSale.buyer_email).label("email"),
                         EnterticketSale.entrada_name.label("cat"))
                 .filter(EnterticketSale.event_id == ev.id,
                         EnterticketSale.cancelled.is_(False),
                         EnterticketSale.refunded.is_(False),
                         EnterticketSale.buyer_email.isnot(None),
                         EnterticketSale.buyer_email != "",
                         EnterticketSale.entrada_name.isnot(None),
                         EnterticketSale.entrada_name != "")
                 .group_by(func.lower(EnterticketSale.buyer_email),
                           EnterticketSale.entrada_name).all()):
        cats.setdefault(fila.email, []).append(fila.cat)
    for clave in cats:
        cats[clave] = sorted(set(cats[clave]))
    emails = [r.email for r in q]
    buyers = {}
    if emails:
        buyers = {b.email: b for b in s.query(Buyer).filter(Buyer.email.in_(emails)).all()}
    # Altas nuevas con UPSERT (carrera-safe: dos eventos con un comprador común pueden
    # sincronizarse a la vez en workers distintos) y relectura de los que faltaban.
    missing = [r for r in q if r.email not in buyers]
    if missing:
        # ⚠️ Este INSERT es «a pelo» (Core), así que NO pasa por el normalizador de teléfonos del
        # guardado: hay que ponerle el prefijo aquí. Enterticket manda «34600111222» (sin el «+»),
        # que no vale para mandar un SMS ni un WhatsApp.
        s.execute(_et_pg_insert(Buyer.__table__).values([
            {"email": r.email, "name": r.name or None,
             "phone": _normalize_phone_value(r.phone) or None,
             "accepts_marketing": bool(r.mkt)} for r in missing
        ]).on_conflict_do_nothing(index_elements=["email"]))
        for b in s.query(Buyer).filter(Buyer.email.in_([r.email for r in missing])).all():
            buyers[b.email] = b
    be_rows = {be.buyer_id: be for be in s.query(BuyerEvent).filter(BuyerEvent.event_id == ev.id).all()}
    valid_buyer_ids = set()
    dirty = False
    for r in q:
        b = buyers.get(r.email)
        if not b:
            continue
        if r.name and b.name != r.name:
            b.name = r.name
        telefono = _normalize_phone_value(r.phone)
        if telefono and b.phone != telefono:
            b.phone = telefono
        if r.mkt and not b.accepts_marketing:
            b.accepts_marketing = True
        valid_buyer_ids.add(b.id)
        be = be_rows.get(b.id)
        if not be:
            be = BuyerEvent(buyer_id=b.id, event_id=ev.id)
            s.add(be)
            be_rows[b.id] = be
        # Solo tocar la fila si algo cambió de verdad (evita miles de UPDATEs por sync).
        for field, value in (("concert_id", ev.concert_id), ("tickets_count", int(r.n or 0)),
                             ("amount_total", _et_money(r.amt)), ("first_purchase_at", r.first_at),
                             ("last_purchase_at", r.last_at),
                             ("categories", cats.get(r.email) or [])):
            if getattr(be, field) != value:
                setattr(be, field, value)
                dirty = True
    # compradores que se quedaron sin ventas válidas en este evento (todo anulado/devuelto)
    affected = set(valid_buyer_ids)
    for be in list(be_rows.values()):
        if be.buyer_id not in valid_buyer_ids:
            affected.add(be.buyer_id)
            s.delete(be)
            dirty = True
    s.flush()
    if not affected:
        return
    if not dirty and not missing:
        return  # nada cambió: no reescribimos agregados
    # Agregados globales de los afectados en UNA sola sentencia (con miles de compradores, un
    # SELECT por comprador saturaba la BD en cada sync) + limpieza de los que quedan a cero.
    ids = list(affected)
    s.execute(text("""
        UPDATE buyers b SET
            events_count = COALESCE(agg.n, 0),
            tickets_count = COALESCE(agg.t, 0),
            amount_total = COALESCE(agg.a, 0),
            first_purchase_at = agg.f,
            last_purchase_at = agg.l,
            updated_at = now()
        FROM (
            SELECT b2.id AS bid, count(be.id) AS n, sum(be.tickets_count) AS t,
                   sum(be.amount_total) AS a, min(be.first_purchase_at) AS f,
                   max(be.last_purchase_at) AS l
            FROM buyers b2 LEFT JOIN buyer_events be ON be.buyer_id = b2.id
            WHERE b2.id IN :ids GROUP BY b2.id
        ) agg
        WHERE b.id = agg.bid
    """).bindparams(bindparam("ids", expanding=True)), {"ids": ids})
    drop_candidates = list(affected - valid_buyer_ids)  # solo los que perdieron ESTE evento
    if drop_candidates:
        s.execute(text("DELETE FROM buyers WHERE id IN :ids AND events_count = 0")
                  .bindparams(bindparam("ids", expanding=True)), {"ids": drop_candidates})
    s.expire_all()


def _et_ensure_concert_ticketer(s, ev: EnterticketEvent):
    """Al vincular/sincronizar: crea/actualiza la ticketera «Enterticket» del concierto con el
    enlace de venta y el aforo a la venta (ET manda sobre su propia ticketera). Devuelve la fila."""
    if not ev.concert_id:
        return None
    tk = s.query(Ticketer).filter(func.lower(Ticketer.name) == "enterticket").first()
    if not tk:
        tk = Ticketer(name="Enterticket", link_url="https://www.enterticket.es")
        s.add(tk)
        s.flush()
    ct = (s.query(ConcertTicketer)
          .filter(ConcertTicketer.concert_id == ev.concert_id,
                  ConcertTicketer.ticketer_id == tk.id).first())
    if not ct:
        ct = ConcertTicketer(concert_id=ev.concert_id, ticketer_id=tk.id)
        s.add(ct)
        s.flush()
    if ev.url_enterticket:
        ct.sale_url = ev.url_enterticket
    if ev.capacity_on_sale and int(ct.capacity_for_sale or 0) != int(ev.capacity_on_sale):
        ct.capacity_for_sale = int(ev.capacity_on_sale)
    return ct


def _et_mirror_to_sales(s, ev: EnterticketEvent) -> None:
    """Vuelca la venta de ET al módulo de VENTAS para que el reporte, los gráficos y el Resultado
    incluyan estos conciertos SIEMPRE al día, sumándose a las demás ticketeras (manuales):
    - tipos de entrada → ConcertTicketType (por nombre) con su cupo (vendidas+disponibles) y precio;
    - cupos/precios por ticketera×tipo → ConcertTicketerTicketType (ticketera Enterticket);
    - ventas diarias → TicketSaleDetail (rejilla completa recalculada en cada sync: las
      anulaciones/devoluciones restan; SOLO se tocan las filas de la ticketera Enterticket).
    Excluye invitaciones (no son venta)."""
    if not ev.concert_id:
        return
    ct = _et_ensure_concert_ticketer(s, ev)
    if not ct:
        return
    concert_id = ev.concert_id
    tk_id = ct.ticketer_id
    # 1) Tipos de entrada (upsert por nombre). SOLO se sobrescriben cupo/precio de los tipos
    #    CREADOS por el espejo (et_managed): en los configurados a mano el cupo del tipo es el
    #    TOTAL entre ticketeras y pisarlo con el valor de ET rompería la conciliación del módulo
    #    manual; para esos, ET solo actualiza SU asignación (paso 2).
    existing_types = {(t.name or "").strip().lower(): t
                      for t in s.query(ConcertTicketType).filter(ConcertTicketType.concert_id == concert_id).all()}
    type_by_et_id = {}
    for t in sorted(ev.ticket_types or [], key=lambda x: (x.sort_order or 0)):
        name = (t.name or "").strip() or f"Entrada {t.et_entrada_id}"
        row = existing_types.get(name.lower())
        on_sale = int(t.qty_sold or 0) + int(t.qty_available or 0)
        if not row:
            row = ConcertTicketType(concert_id=concert_id, name=name, qty_for_sale=on_sale,
                                    price=t.price, et_managed=True)
            s.add(row)
            s.flush()
            existing_types[name.lower()] = row
        elif getattr(row, "et_managed", False):
            if int(row.qty_for_sale or 0) != on_sale:
                row.qty_for_sale = on_sale
            if (row.price or 0) != (t.price or 0):
                row.price = t.price
        type_by_et_id[t.et_entrada_id] = row
    # 2) Asignación ticketera×tipo (cupo + precio bruto de cada tipo en Enterticket).
    existing_alloc = {a.ticket_type_id: a for a in s.query(ConcertTicketerTicketType)
                      .filter(ConcertTicketerTicketType.concert_id == concert_id,
                              ConcertTicketerTicketType.ticketer_id == tk_id).all()}
    for t in (ev.ticket_types or []):
        row = type_by_et_id.get(t.et_entrada_id)
        if not row:
            continue
        on_sale = int(t.qty_sold or 0) + int(t.qty_available or 0)
        a = existing_alloc.get(row.id)
        if not a:
            a = ConcertTicketerTicketType(concert_id=concert_id, ticketer_id=tk_id,
                                          ticket_type_id=row.id, qty_for_sale=on_sale, price_gross=t.price)
            s.add(a)
        else:
            if int(a.qty_for_sale or 0) != on_sale:
                a.qty_for_sale = on_sale
            if (a.price_gross or 0) != (t.price or 0):
                a.price_gross = t.price
    s.flush()
    # 3) Rejilla diaria de ventas (día × tipo) desde las ventas crudas válidas, sin invitaciones.
    day_rows = (_et_valid_sales_filter(s.query(
            func.date(EnterticketSale.purchase_at).label("day"),
            EnterticketSale.et_entrada_id.label("etid"),
            func.count().label("n"),
            func.sum(EnterticketSale.price).label("amt")), ev)
        .filter(EnterticketSale.is_invitation.is_(False))
        .filter(EnterticketSale.purchase_at.isnot(None))
        .group_by(func.date(EnterticketSale.purchase_at), EnterticketSale.et_entrada_id).all())
    catchall = None

    def _type_for(etid):
        nonlocal catchall
        row = type_by_et_id.get(etid)
        if row is not None:
            return row
        # Ventas de tipos retirados en ET o sin id: cajón «Enterticket · otros» (cupo 0).
        if catchall is None:
            catchall = existing_types.get("enterticket · otros")
            if catchall is None:
                catchall = ConcertTicketType(concert_id=concert_id, name="Enterticket · otros",
                                             qty_for_sale=0, price=0, et_managed=True)
                s.add(catchall)
                s.flush()
                existing_types["enterticket · otros"] = catchall
        return catchall

    wanted = {}
    for r in day_rows:
        tt = _type_for(r.etid)
        key = (r.day, tt.id)
        qty = int(r.n or 0)
        amt = _et_money(r.amt)
        if key in wanted:  # dos ids de ET caídos al mismo cajón el mismo día
            qty += wanted[key][0]
            amt += wanted[key][1]
        wanted[key] = (qty, amt)
    existing_details = {(d.day, d.ticket_type_id): d
                        for d in s.query(TicketSaleDetail)
                        .filter(TicketSaleDetail.concert_id == concert_id,
                                TicketSaleDetail.ticketer_id == tk_id).all()}
    for key, (qty, amt) in wanted.items():
        day_v, type_id = key
        unit = (amt / qty).quantize(Decimal("0.000001")) if qty else Decimal("0")
        d = existing_details.get(key)
        if not d:
            s.add(TicketSaleDetail(concert_id=concert_id, ticketer_id=tk_id, ticket_type_id=type_id,
                                   day=day_v, qty=qty, unit_price_gross=unit))
        else:
            if int(d.qty or 0) != qty:
                d.qty = qty
            if (d.unit_price_gross or 0) != unit:
                d.unit_price_gross = unit
    for key, d in existing_details.items():
        if key not in wanted:
            s.delete(d)  # ese día se quedó sin ventas válidas (anulaciones)
    s.flush()
    # 4) Aforo a la venta del concierto = suma de cupos por tipo (igual que el módulo manual).
    _sync_concert_capacity_from_ticket_types(s, concert_id)


def _et_link_event(s, ev: EnterticketEvent, concert: Concert) -> None:
    # Un concierto solo puede tener UN evento de ET: el espejo de ventas (ticketera Enterticket)
    # es por concierto y dos eventos se pisarían mutuamente la rejilla diaria.
    other = (s.query(EnterticketEvent)
             .filter(EnterticketEvent.concert_id == concert.id, EnterticketEvent.id != ev.id).first())
    if other:
        raise ValueError(f"Ese concierto ya está vinculado al evento «{other.name}» de Enterticket. Desvincúlalo primero.")
    ev.concert_id = concert.id
    ev.link_status = "LINKED"
    ev.last_error = None
    _et_ensure_concert_ticketer(s, ev)
    for be in s.query(BuyerEvent).filter(BuyerEvent.event_id == ev.id).all():
        be.concert_id = concert.id


def _et_unlink_event(s, ev: EnterticketEvent) -> None:
    """Desvincula y LIMPIA lo volcado al módulo de ventas: si el vínculo era erróneo, el reporte no
    debe conservar ventas/cupos de otro evento. Se borran la rejilla diaria y las asignaciones de la
    ticketera Enterticket y los tipos CREADOS por el espejo (et_managed) que queden sin uso; la fila
    ConcertTicketer se CONSERVA (puede llevar rebate/aforo configurados a mano) limpiando solo el
    enlace de venta. Al final se recalcula el aforo del concierto."""
    concert_id = ev.concert_id
    ev.concert_id = None
    ev.link_status = "PENDING"
    for be in s.query(BuyerEvent).filter(BuyerEvent.event_id == ev.id).all():
        be.concert_id = None
    if not concert_id:
        return
    tk = s.query(Ticketer).filter(func.lower(Ticketer.name) == "enterticket").first()
    if tk:
        (s.query(TicketSaleDetail)
         .filter(TicketSaleDetail.concert_id == concert_id, TicketSaleDetail.ticketer_id == tk.id)
         .delete(synchronize_session=False))
        (s.query(ConcertTicketerTicketType)
         .filter(ConcertTicketerTicketType.concert_id == concert_id,
                 ConcertTicketerTicketType.ticketer_id == tk.id)
         .delete(synchronize_session=False))
        ct = (s.query(ConcertTicketer)
              .filter(ConcertTicketer.concert_id == concert_id, ConcertTicketer.ticketer_id == tk.id)
              .first())
        if ct:
            if ct.rebate_mode or (ct.capacity_for_sale and not ev.capacity_on_sale):
                ct.sale_url = None  # conservar la fila: lleva configuración manual (rebate/aforo)
            else:
                s.delete(ct)
        s.flush()
    # Tipos creados por el espejo que ya no usa nadie (sin ventas ni asignaciones de ninguna ticketera).
    for tt in (s.query(ConcertTicketType)
               .filter(ConcertTicketType.concert_id == concert_id,
                       ConcertTicketType.et_managed.is_(True)).all()):
        in_use = (s.query(TicketSaleDetail.concert_id)
                  .filter(TicketSaleDetail.ticket_type_id == tt.id).first()
                  or s.query(ConcertTicketerTicketType.concert_id)
                  .filter(ConcertTicketerTicketType.ticket_type_id == tt.id).first())
        if not in_use:
            s.delete(tt)
    s.flush()
    _sync_concert_capacity_from_ticket_types(s, concert_id)


def _et_concert_has_legacy_sales(s, concert_id) -> bool:
    """¿El concierto lleva su venta en modo BÁSICO (tabla legacy ticket_sales)? Al volcar ET en
    V2, sales_maps_unified deja de sumar el legacy: hay que avisar al vincular."""
    try:
        has_legacy = bool(s.query(TicketSale.id).filter(TicketSale.concert_id == concert_id).first())
        has_v2 = bool(s.query(TicketSaleDetail.concert_id)
                      .filter(TicketSaleDetail.concert_id == concert_id).first())
        return has_legacy and not has_v2
    except Exception:
        return False


def _et_automatch_candidates(s, ev: EnterticketEvent, day_margin: int = 1) -> list:
    """Conciertos candidatos para un evento ET: misma fecha (± margen), puntuando por
    artista (nombre dentro del título/artistas de ET) y recinto/municipio. [(score, Concert)]."""
    if not ev.event_date:
        return []
    d0 = ev.event_date - timedelta(days=day_margin)
    d1 = ev.event_date + timedelta(days=day_margin)
    linked_sq = (s.query(EnterticketEvent.concert_id)
                 .filter(EnterticketEvent.concert_id.isnot(None), EnterticketEvent.id != ev.id))
    rows = (s.query(Concert)
            .options(joinedload(Concert.artist), joinedload(Concert.venue))
            .filter(Concert.date >= d0, Concert.date <= d1)
            .filter(~Concert.id.in_(linked_sq)).all())
    ev_name = _norm_text_key(ev.name)
    ev_art = _norm_text_key(ev.artist_names or "")
    ev_venue = _norm_text_key(ev.venue_name or "")
    ev_town = _norm_text_key(ev.venue_town or "")
    out = []
    for c in rows:
        score = 0
        if c.date == ev.event_date:
            score += 1
        a = _norm_text_key(c.artist.name if c.artist else "")
        if a and (a in ev_name or (ev_art and (a in ev_art or ev_art in a))):
            score += 3
        vname = _norm_text_key((c.venue.name if c.venue else "") or (c.manual_venue_name or ""))
        town = _norm_text_key((c.venue.municipality if c.venue else "") or (c.manual_municipality or ""))
        if ev_venue and vname and (ev_venue in vname or vname in ev_venue):
            score += 2
        elif ev_town and town and ev_town == town:
            score += 1
        if score >= 2:
            out.append((score, c))
    out.sort(key=lambda t: (-t[0], t[1].date))
    return out


def _et_try_automatch(s, ev: EnterticketEvent) -> bool:
    """Vincula automáticamente SOLO si hay un candidato claro: artista + fecha exacta (score ≥ 4)
    y sin empate. En caso de duda queda PENDIENTE y se decide a mano en Integraciones."""
    cands = _et_automatch_candidates(s, ev, day_margin=0)
    if not cands:
        return False
    top_score, top = cands[0]
    if top_score < 4:
        return False
    if len(cands) > 1 and cands[1][0] == top_score:
        return False
    _et_link_event(s, ev, top)
    return True


def _et_sync_catalog(s) -> tuple[int, int]:
    """Espejo del catálogo /eventos (paginado) + artistas de los nuevos + automatch pendientes.
    Devuelve (eventos_totales, nuevos). Serializado entre workers (cron + botón manual)."""
    if not et_api.enterticket_configured():
        return (0, 0)
    with _et_pg_lock("et_catalog") as got:
        if not got:
            return (0, 0)
        return _et_sync_catalog_locked(s)


def _et_sync_catalog_locked(s) -> tuple[int, int]:
    known = {r.et_event_id: r for r in s.query(EnterticketEvent).all()}
    desde = int(time.time()) - 730 * 86400
    offset, total, nuevos = 0, 0, 0
    while True:
        page = _et_call(s, et_api.fetch_events, limite=100, offset=offset, desde=desde, light=True)
        if not page:
            break
        for item in page:
            info = (item or {}).get("info") or {}
            try:
                eid = int(info.get("id") or 0)
            except Exception:
                continue
            if not eid:
                continue
            total += 1
            row = known.get(eid)
            if not row:
                row = EnterticketEvent(et_event_id=eid, name=(info.get("nombre") or f"Evento {eid}"))
                s.add(row)
                known[eid] = row
                nuevos += 1
            _et_apply_event_info(row, info)
        s.commit()
        if len(page) < 100:
            break
        offset += 100
    # Artistas (para matching) de los eventos que aún no los tienen: 1 llamada por evento, acotado.
    pending_art = [r for r in known.values() if not (r.artist_names or "").strip()][:40]
    for r in pending_art:
        try:
            arts = _et_call(s, et_api.fetch_event_artists, r.et_event_id)
            names = ", ".join([(a.get("nombre") or "").strip() for a in arts if (a.get("nombre") or "").strip()])
            r.artist_names = names or None
            img = next((a.get("imagen") for a in arts if a.get("imagen")), None)
            if img:
                r.artist_image = img
        except Exception:
            continue
    s.commit()
    for r in known.values():
        if r.link_status == "PENDING" and not r.concert_id:
            try:
                _et_try_automatch(s, r)
            except Exception:
                continue
    meta = _et_meta_row(s)
    meta.last_catalog_sync_at = datetime.now(TZ_MADRID)
    meta.last_error = None
    s.commit()
    return (total, nuevos)


def _et_sync_event(s, ev: EnterticketEvent, full: bool = False) -> bool:
    """Sincroniza UN evento: detalle (tipos/aforo), ventas nuevas (desde_id), cambios (updated),
    bloqueos y base de compradores. `full=True` re-trae todas las ventas (reconciliación).
    Serializado ENTRE workers con advisory lock; devuelve False si otro proceso ya lo estaba
    sincronizando (se salta el trabajo, no es un error)."""
    with _et_pg_lock(f"et_ev_{ev.et_event_id}") as got:
        if not got:
            return False
        _et_sync_event_locked(s, ev, full=full)
        return True


def _et_sync_event_locked(s, ev: EnterticketEvent, full: bool = False) -> None:
    sync_started = int(time.time())
    detail = _et_call(s, et_api.fetch_event, ev.et_event_id)
    if detail:
        info = detail.get("info") or {}
        _et_apply_event_info(ev, info)
        entradas = list(detail.get("entradas") or [])
        if not entradas:
            for ses in (detail.get("sesiones") or []):
                entradas.extend(ses.get("entradas") or [])
        _et_apply_ticket_types(s, ev, entradas)
        s.commit()
    prev_sync_unix = int(ev.sales_last_sync_unix or 0)
    if full:
        ev.sales_last_id = 0
    max_id = int(ev.sales_last_id or 0)
    max_upd_seen = 0
    # 1) Ventas NUEVAS: avanzamos desde_id página a página (sin offset: el cursor ya avanza).
    while True:
        page = _et_call(s, et_api.fetch_sales, ev.et_event_id,
                        limite=_ET_SALES_PAGE, desde_id=(max_id or None))
        if not page:
            break
        page_max_id, page_max_upd = _et_upsert_sales_page(s, ev, page)
        s.commit()
        max_upd_seen = max(max_upd_seen, page_max_upd)
        if page_max_id <= max_id:
            break  # sin avance: evita bucles si la API ignora desde_id
        max_id = page_max_id
        if len(page) < _ET_SALES_PAGE:
            break
    # 2) CAMBIOS sobre ventas ya conocidas (anulaciones/devoluciones/nominaciones): updated_at.
    #    Con guard de progreso y tope de páginas (la combinación updated+offset no está garantizada
    #    por la API); si se corta por tope, NO avanzamos el cursor para reintentarlo después.
    changes_complete = True
    if prev_sync_unix and not full:
        offset = 0
        pages = 0
        seen_ids: set = set()
        while True:
            page = _et_call(s, et_api.fetch_sales, ev.et_event_id,
                            limite=_ET_SALES_PAGE, offset=offset, updated=max(0, prev_sync_unix - 900))
            if not page:
                break
            page_ids = {int(r.get("id") or 0) for r in page if r.get("id")}
            _, page_max_upd = _et_upsert_sales_page(s, ev, page)
            s.commit()
            max_upd_seen = max(max_upd_seen, page_max_upd)
            if len(page) < _ET_SALES_PAGE:
                break
            if page_ids and page_ids <= seen_ids:
                break  # la API no avanza con offset: cortamos sin marcar incompleto (ya visto)
            seen_ids |= page_ids
            offset += _ET_SALES_PAGE
            pages += 1
            if pages >= 100:
                changes_complete = False  # tope de seguridad: reintentar en el siguiente sync
                break
    # 3) Bloqueos (asientos/entradas bloqueadas del evento).
    try:
        blq = _et_call(s, et_api.fetch_bloqueos, ev.et_event_id) or []
        activos = [b for b in blq if (b or {}).get("activo")]
        ev.blocked_count = len(activos)
        ev.blocked_json = [{
            "concepto": (b.get("concepto") or ""), "nombre": (b.get("nombre") or ""),
            "codigo": (b.get("codigo") or ""), "reserva": bool(b.get("reserva")),
        } for b in activos[:2000]]
    except Exception:
        pass
    ev.sales_last_id = max_id
    # Cursor de cambios en el dominio del RELOJ DE ET (watermark de updated_at visto), no del
    # nuestro: un desfase de relojes >15 min perdería anulaciones en silencio. Si no hemos visto
    # ningún updated_at (evento sin ventas), caemos al reloj local. Si el barrido de cambios quedó
    # incompleto, no avanzamos.
    if changes_complete:
        ev.sales_last_sync_unix = max(prev_sync_unix, max_upd_seen) or sync_started
    ev.last_synced_at = datetime.now(TZ_MADRID)
    ev.last_error = None
    if ev.concert_id:
        _et_ensure_concert_ticketer(s, ev)
    s.commit()
    _et_recompute_buyers_for_event(s, ev)
    s.commit()
    if ev.concert_id:
        _et_mirror_to_sales(s, ev)
        s.commit()


def _et_sync_event_bg(event_pk: str, full: bool = False) -> None:
    """Sincroniza un evento en un hilo (sesión propia). El guard evita duplicar trabajo por proceso."""
    key = str(event_pk)
    with _ET_SYNC_GUARD:
        if key in _ET_SYNC_ACTIVE:
            return
        _ET_SYNC_ACTIVE.add(key)
    s = db()
    try:
        ev = s.get(EnterticketEvent, to_uuid(event_pk))
        if ev:
            _et_sync_event(s, ev, full=full)
    except Exception as exc:
        try:
            s.rollback()
            ev = s.get(EnterticketEvent, to_uuid(event_pk))
            if ev:
                ev.last_error = str(exc)[:500]
                s.commit()
        except Exception:
            pass
    finally:
        s.close()
        with _ET_SYNC_GUARD:
            _ET_SYNC_ACTIVE.discard(key)


def _et_maybe_sync_event(ev: EnterticketEvent, max_age_min: int = 10) -> bool:
    """Lanza una sincronización en segundo plano si los datos están «viejos». True si se lanzó."""
    if not et_api.enterticket_configured():
        return False
    if ev.last_synced_at:
        age = datetime.now(TZ_MADRID) - ev.last_synced_at
        if age.total_seconds() < max_age_min * 60:
            return False
    threading.Thread(target=_et_sync_event_bg, args=(str(ev.id),), daemon=True).start()
    return True


def _et_sync_all_bg() -> None:
    """Catálogo + todos los eventos vinculados aún «vivos» (fin hace <30 días). Para el cron."""
    s = db()
    try:
        try:
            _et_sync_catalog(s)
        except Exception as exc:
            try:
                s.rollback()
                meta = _et_meta_row(s)
                meta.last_error = str(exc)[:500]
                s.commit()
            except Exception:
                pass
        cutoff = date.today() - timedelta(days=30)
        ids = [str(r.id) for r in s.query(EnterticketEvent)
               .filter(EnterticketEvent.concert_id.isnot(None))
               .filter(or_(EnterticketEvent.event_end_date.is_(None), EnterticketEvent.event_end_date >= cutoff))
               .all()]
    finally:
        s.close()
    for pk in ids:
        try:
            _et_sync_event_bg(pk)
        except Exception:
            continue


def _et_concert_event(s, concert_id):
    return (s.query(EnterticketEvent)
            .options(selectinload(EnterticketEvent.ticket_types))
            .filter(EnterticketEvent.concert_id == concert_id).first())


def _et_valid_sales_filter(q, ev):
    return q.filter(EnterticketSale.event_id == ev.id,
                    EnterticketSale.cancelled.is_(False),
                    EnterticketSale.refunded.is_(False))


def _et_ticketing_context(s, ev: EnterticketEvent) -> dict:
    """Informe de venta del evento para la pestaña Ticketing: KPIs, tipos con barra de estado,
    vendidas hoy, recaudación, invitaciones por concepto y serie diaria."""
    today = datetime.now(TZ_MADRID).date()
    # Recaudación y unidades reales por tipo desde las ventas crudas (soporta cambios de precio).
    rev_rows = (_et_valid_sales_filter(s.query(
            EnterticketSale.et_entrada_id,
            func.count().label("n"),
            func.sum(EnterticketSale.price).label("amt")), ev)
        .filter(EnterticketSale.is_invitation.is_(False))
        .group_by(EnterticketSale.et_entrada_id).all())
    rev_by_type = {r.et_entrada_id: r for r in rev_rows}
    types = []
    total_sold = total_on_sale = 0
    for t in sorted(ev.ticket_types or [], key=lambda x: (x.sort_order or 0)):
        sold = int(t.qty_sold or 0)
        avail = int(t.qty_available or 0)
        on_sale = sold + avail
        rr = rev_by_type.get(t.et_entrada_id)
        revenue = _et_money(rr.amt) if rr else (_et_money(t.price) * sold)
        pct = round(sold * 100.0 / on_sale, 1) if on_sale else 0.0
        types.append({
            "et_entrada_id": t.et_entrada_id, "name": t.name, "price": t.price,
            "sold": sold, "available": avail, "on_sale": on_sale, "pct": pct,
            "revenue": revenue, "is_numbered": bool(t.is_numbered),
        })
        total_sold += sold
        total_on_sale += on_sale
    # Recaudación TOTAL directamente de las ventas válidas (incluye ventas de tipos ya retirados
    # en ET o con id de tipo desconocido, que no aparecen en el desglose por tipo).
    total_revenue = _et_money(
        _et_valid_sales_filter(s.query(func.sum(EnterticketSale.price)), ev)
        .filter(EnterticketSale.is_invitation.is_(False)).scalar())
    sold_today = (_et_valid_sales_filter(s.query(func.count()), ev)
                  .filter(EnterticketSale.is_invitation.is_(False))
                  .filter(func.date(EnterticketSale.purchase_at) == today).scalar() or 0)
    inv_rows = (_et_valid_sales_filter(s.query(
            func.coalesce(EnterticketSale.invitation_concept, "Invitación").label("concept"),
            func.count().label("n")), ev)
        .filter(EnterticketSale.is_invitation.is_(True))
        .group_by(func.coalesce(EnterticketSale.invitation_concept, "Invitación"))
        .order_by(func.count().desc()).all())
    invitations = [{"concept": r.concept, "count": int(r.n or 0)} for r in inv_rows]
    inv_total = sum(x["count"] for x in invitations)
    day_rows = (_et_valid_sales_filter(s.query(
            func.date(EnterticketSale.purchase_at).label("day"),
            func.count().label("n"),
            func.sum(EnterticketSale.price).label("amt")), ev)
        .filter(EnterticketSale.is_invitation.is_(False))
        .filter(EnterticketSale.purchase_at.isnot(None))
        .group_by(func.date(EnterticketSale.purchase_at))
        .order_by(func.date(EnterticketSale.purchase_at)).all())
    series = [{"day": r.day.strftime("%d/%m/%Y"), "n": int(r.n or 0), "amt": float(r.amt or 0)} for r in day_rows]
    pct_total = round(total_sold * 100.0 / total_on_sale, 1) if total_on_sale else 0.0
    return {
        "types": types, "total_sold": total_sold, "total_on_sale": total_on_sale,
        "total_available": max(total_on_sale - total_sold, 0), "pct_total": pct_total,
        "total_revenue": total_revenue, "sold_today": int(sold_today),
        "invitations": invitations, "invitations_total": inv_total,
        "blocked_count": int(ev.blocked_count or 0),
        "capacity_on_sale": ev.capacity_on_sale or total_on_sale,
        "series": series,
        "last_synced_label": _et_fmt_dt(ev.last_synced_at),
    }


def _et_create_booking_request(s, ev: EnterticketEvent) -> BookingRequest:
    """Petición a CONTRATACIÓN para crear el evento que existe en Enterticket pero no aquí,
    con los datos ya proporcionados por ET (artista, fecha, recinto, enlace)."""
    venue = None
    if (ev.venue_name or "").strip():
        venue = s.query(Venue).filter(_sa_contains_text(Venue.name, ev.venue_name)).first()
    artist = None
    art_names = [a.strip() for a in (ev.artist_names or "").split(",") if a.strip()]
    if art_names:
        artist = s.query(Artist).filter(_sa_folded_text(Artist.name) == _norm_text_key(art_names[0])).first()
    notes = (f"Evento detectado en Enterticket (id {ev.et_event_id}).\n"
             f"Artista(s): {ev.artist_names or '—'}\nRecinto: {ev.venue_name or '—'}"
             f" ({ev.venue_town or '—'}, {ev.venue_province or '—'})\n"
             f"Enlace de venta: {ev.url_enterticket or '—'}")
    r = BookingRequest(
        status="NUEVA",
        subject=f"Enterticket · {ev.name}",
        requested_date=ev.event_date,
        artist_id=(artist.id if artist else None),
        artist_ids=([str(artist.id)] if artist else []),
        venue_id=(venue.id if venue else None),
        municipality=ev.venue_town or None,
        province=ev.venue_province or None,
        source="OTRO",
        notes=notes,
        received_at=datetime.now(TZ_MADRID),
        created_by_user_id=session.get("user_id"),
        created_by_nick=session.get("nick"),
        payload={
            "activity_type": "CONCIERTO", "no_cache": False, "departments": ["CONTRATACION"],
            "date_kind": "EXACT", "source_integration": "ENTERTICKET",
            "et_event_id": ev.et_event_id, "description": notes,
        },
    )
    s.add(r)
    s.flush()
    ev.booking_request_id = r.id
    ev.link_status = "REQUESTED"
    return r


def _et_split_seat(sector: str, seat: str) -> tuple[str, str]:
    """Separa el texto de asiento de ET en (fila, número). ET manda `sector` y `asiento` como
    texto libre («Fila 5 - Asiento 12», «5-12», «12»…): heurística tolerante; lo que no case
    se contabiliza como «sin casar» (igual que las entradas de invitación subidas por PDF)."""
    raw = (seat or "").strip()
    row = ""
    m = re.search(r"fila\s*[:\.]?\s*([A-Za-z0-9]+)", raw, re.I) or re.search(r"fila\s*[:\.]?\s*([A-Za-z0-9]+)", sector or "", re.I)
    if m:
        row = m.group(1)
    m2 = re.search(r"(?:asiento|butaca|seat)\s*[:\.]?\s*([A-Za-z0-9]+)", raw, re.I)
    num = m2.group(1) if m2 else ""
    if not num:
        m3 = re.match(r"^\s*([A-Za-z]?\d+)\s*[-/|·]\s*([A-Za-z]?\d+)\s*$", raw)
        if m3:
            row = row or m3.group(1)
            num = m3.group(2)
        else:
            num = raw
    return row, num


def _et_venue_map_payload(s, concert: Concert, ev: EnterticketEvent) -> dict | None:
    """Plano del recinto EN TIEMPO REAL con la venta de Enterticket: butacas vendidas (rojo),
    invitaciones (naranja) y las INVITACIONES SUBIDAS con su estado, casadas por sector/fila/asiento
    contra el mapa del recinto (seatmap_calc, mismo casado que las invitaciones). Lo que sigue LIBRE
    se pinta con el color de SU CATEGORÍA a la venta (las del propio mapa del recinto), así que de un
    vistazo se ve qué queda por vender de cada categoría.
    Devuelve {payload, matched, unmatched, legend, on_sale, blocked_count} o None si no hay mapa o
    nada numerado."""
    if not concert.venue_id:
        return None
    sm = _concert_seatmap(s, concert)
    if not sm:
        return None
    layout = sm.layout_json or {}
    if not (layout.get("sections") or []):
        return None
    lookup = seatmap_calc.seat_lookup(layout)
    # Categorías sintéticas del plano en vivo: la venta de ET (vendida / invitación emitida en ET)
    # + las INVITACIONES SUBIDAS en la app con su ESTADO (disponible/asignada/enviada/impresa/
    # bloqueada). Las nuestras van PRIMERO (mandan sobre el eco que ET pueda tener de esa butaca).
    cats = {
        "et_vendida": {"id": "et_vendida", "name": "Vendida", "color": "#E33D48", "kind": "venta"},
        "et_inv": {"id": "et_inv", "name": "Invitación ET", "color": "#f59e0b", "kind": "invitaciones"},
        "inv_disp": {"id": "inv_disp", "name": "Inv. disponible", "color": "#16a34a", "kind": "invitaciones"},
        "inv_asig": {"id": "inv_asig", "name": "Inv. asignada", "color": "#e0a800", "kind": "invitaciones"},
        "inv_env": {"id": "inv_env", "name": "Inv. enviada", "color": "#007ca2", "kind": "invitaciones"},
        "inv_imp": {"id": "inv_imp", "name": "Inv. impresa", "color": "#6f42c1", "kind": "invitaciones"},
        "inv_bloq": {"id": "inv_bloq", "name": "Inv. bloqueada", "color": "#6b7280", "kind": "bloqueo"},
    }
    counts = {k: 0 for k in cats}
    # A LA VENTA POR CATEGORÍA: se arranca del reparto del propio mapa del recinto y encima se
    # pintan las vendidas/invitadas. ⚠️ El orden importa: dentro de una fila, un rango posterior pisa
    # al anterior (así lo monta `venue_map.js`), y por eso las sintéticas se APILAN al final.
    # ⚠️ Copia PROFUNDA: `assignments_json` es del objeto ORM y apilar los rangos sintéticos encima
    # ensuciaría el mapa guardado del recinto en cuanto la sesión hiciera flush.
    base_assign = json.loads(json.dumps(sm.assignments_json or {}))
    seat_cat = seatmap_calc.seat_categories(layout, sm.assignments_json or {})
    on_sale = {}   # catId -> cuántas quedan libres
    for cid in seat_cat.values():
        on_sale[cid] = on_sale.get(cid, 0) + 1
    assignments: dict = base_assign
    seen = set()
    matched = unmatched = 0

    def _put(key, ckey):
        nonlocal matched
        seen.add(key)
        matched += 1
        counts[ckey] += 1
        # Esta butaca ya no está a la venta: se descuenta de su categoría.
        cid_base = seat_cat.get(key)
        if cid_base and on_sale.get(cid_base):
            on_sale[cid_base] -= 1
        sec, rowi, slot = key.split("|")
        assignments.setdefault(sec, {}).setdefault(rowi, []).append([int(slot), int(slot), ckey])

    def _inv_state_cat(status):
        st = (status or "").upper()
        if st == "AVAILABLE":
            return "inv_disp"
        if st == "ASSIGNED":
            return "inv_asig"
        if st == "PRINTED":
            return "inv_imp"
        if st == "BLOCKED":
            return "inv_bloq"
        if st in ("SENT", "DELIVERED", "PICKED_UP", "DISPONIBLES_TAQUILLA", "RECOGIDAS_TAQUILLA", "ENTREGADAS_MANO"):
            return "inv_env"
        return None   # LOST y demás: fuera del plano
    inv_rows = (s.query(InvitationTicket.sector, InvitationTicket.row_label, InvitationTicket.seat_number, InvitationTicket.status)
                .filter(InvitationTicket.concert_id == concert.id)
                .filter(InvitationTicket.seat_number.isnot(None), InvitationTicket.seat_number != "").all())
    for sector, row_label, seat_num, status in inv_rows:
        ckey = _inv_state_cat(status)
        if not ckey:
            continue
        key = seatmap_calc.match_ticket(lookup, sector, row_label, seat_num)
        if not key:
            unmatched += 1
            continue
        if key in seen:
            continue
        _put(key, ckey)
    rows = (s.query(EnterticketSale.sector, EnterticketSale.seat, EnterticketSale.is_invitation)
            .filter(EnterticketSale.event_id == ev.id,
                    EnterticketSale.cancelled.is_(False),
                    EnterticketSale.refunded.is_(False))
            .filter(EnterticketSale.seat.isnot(None), EnterticketSale.seat != "").all())
    for sector, seat, is_inv in rows:
        row_label, seat_num = _et_split_seat(sector or "", seat or "")
        key = seatmap_calc.match_ticket(lookup, sector, row_label, seat_num)
        if not key:
            unmatched += 1
            continue
        if key in seen:
            continue
        _put(key, "et_inv" if is_inv else "et_vendida")
    if not matched:
        return None
    # Las categorías del mapa (lo que está a la venta) + las sintéticas. Las del mapa van DELANTE
    # para que el visor las conserve; las butacas repintadas ganan por el orden de los rangos.
    venue_cats = [c for c in (layout.get("categories") or []) if isinstance(c, dict) and c.get("id")]
    view_layout = dict(layout)
    view_layout["categories"] = venue_cats + list(cats.values())
    on_sale_rows = [{
        "id": c.get("id"),
        "name": (c.get("name") or c.get("id") or "").strip(),
        "color": c.get("color") or "",
        "count": int(on_sale.get(c.get("id"), 0) or 0),
    } for c in venue_cats]
    on_sale_rows = [r for r in on_sale_rows if r["count"] > 0]
    return {
        "payload": {"id": str(sm.id), "name": sm.name or "", "version": int(sm.version or 0),
                    "layout": view_layout, "assignments": assignments},
        "matched": matched,
        "unmatched": unmatched,
        "legend": [{"id": k, "name": c["name"], "color": c["color"], "count": counts[k]} for k, c in cats.items()],
        # Lo que QUEDA a la venta de cada categoría del mapa (el resto ya está vendido o invitado).
        "on_sale": on_sale_rows,
        # ⚠️ Bloqueadas: Enterticket da los bloqueos como CONTADOR (concepto/nombre/código), sin decir
        # QUÉ butacas son, así que no se pueden pintar. Se enseña el número y se dice por qué.
        "blocked_count": int(getattr(ev, "blocked_count", 0) or 0),
    }


def _et_event_buyers(s, ev: EnterticketEvent, limit: int = 400) -> list:
    """Compradores del evento (pestaña Compradores del ticketing), ordenados por nº de entradas."""
    rows = (s.query(BuyerEvent, Buyer)
            .join(Buyer, Buyer.id == BuyerEvent.buyer_id)
            .filter(BuyerEvent.event_id == ev.id)
            .order_by(BuyerEvent.tickets_count.desc(), Buyer.email.asc())
            .limit(limit).all())
    return [{
        "name": b.name or "", "email": b.email, "phone": b.phone or "",
        "tickets": int(be.tickets_count or 0), "amount": be.amount_total,
        "last": be.last_purchase_at, "marketing": bool(b.accepts_marketing),
        "events": int(b.events_count or 0),
    } for be, b in rows]


def _et_concert_link_candidates(s, c: Concert, day_margin: int = 0) -> list:
    """Eventos de ET que se ofrecen para vincular con este concierto. Solo los que NO están ya
    enlazados a ninguna actividad y son del MISMO DÍA (los descartados con «no volver a
    sugerirlo» quedan en link_status IGNORED y no vuelven a salir)."""
    if not c.date:
        return []
    rows = (s.query(EnterticketEvent)
            .filter(EnterticketEvent.concert_id.is_(None))
            .filter(EnterticketEvent.link_status != "IGNORED")
            .filter(EnterticketEvent.event_date >= c.date - timedelta(days=day_margin),
                    EnterticketEvent.event_date <= c.date + timedelta(days=day_margin))
            .order_by(EnterticketEvent.event_date.asc()).all())
    a = _norm_text_key(c.artist.name if c.artist else "")
    out = []
    for ev in rows:
        score = 1 if ev.event_date == c.date else 0
        if a and a in _norm_text_key(f"{ev.name} {ev.artist_names or ''}"):
            score += 3
        out.append({
            "pk": str(ev.id), "score": score, "name": ev.name,
            "date": (ev.event_date.strftime("%d/%m/%Y") if ev.event_date else "—"),
            "venue": ev.venue_name or "", "town": ev.venue_town or "",
            "artists": ev.artist_names or "", "image": ev.artist_image or ev.image_url or "",
        })
    out.sort(key=lambda x: -x["score"])
    return out[:8]


def _et_ctx_json(ctx: dict) -> dict:
    """Serializa el contexto de ticketing (Decimals/fechas) para el polling JSON de la pestaña."""
    return {
        "total_sold": ctx["total_sold"], "total_on_sale": ctx["total_on_sale"],
        "total_available": ctx["total_available"], "pct_total": ctx["pct_total"],
        "total_revenue": float(ctx["total_revenue"] or 0), "sold_today": ctx["sold_today"],
        "invitations_total": ctx["invitations_total"], "blocked_count": ctx["blocked_count"],
        "capacity_on_sale": ctx["capacity_on_sale"],
        "last_synced": ctx["last_synced_label"],
        "types": [{**t, "price": float(t["price"] or 0), "revenue": float(t["revenue"] or 0)} for t in ctx["types"]],
        "invitations": ctx["invitations"],
    }


@app.get("/conciertos/<cid>/ticketing/et/estado", endpoint="concert_et_status")
@admin_required
def concert_et_status(cid):
    """Estado de venta en JSON (polling de la pestaña Ticketing). ?sync=1 fuerza refresco si viejo."""
    s = db()
    try:
        ev = _et_concert_event(s, to_uuid(cid))
        if not ev:
            return jsonify({"ok": True, "linked": False})
        syncing = False
        if (request.args.get("sync") or "") == "1":
            syncing = _et_maybe_sync_event(ev, max_age_min=3)
        payload = _et_ctx_json(_et_ticketing_context(s, ev))
        payload.update({"ok": True, "linked": True, "syncing": syncing})
        return jsonify(payload)
    finally:
        s.close()


@app.get("/conciertos/<cid>/ticketing/et/series", endpoint="concert_et_series")
@admin_required
def concert_et_series(cid):
    """Serie diaria de ventas (unidades e importe) del evento o de un tipo (?tt=<id_entrada>)."""
    s = db()
    try:
        ev = _et_concert_event(s, to_uuid(cid))
        if not ev:
            return jsonify({"labels": [], "values": [], "amounts": []})
        q = (_et_valid_sales_filter(s.query(
                func.date(EnterticketSale.purchase_at).label("day"),
                func.count().label("n"),
                func.sum(EnterticketSale.price).label("amt")), ev)
             .filter(EnterticketSale.is_invitation.is_(False))
             .filter(EnterticketSale.purchase_at.isnot(None)))
        tt = (request.args.get("tt") or "").strip()
        if tt:
            try:
                q = q.filter(EnterticketSale.et_entrada_id == int(tt))
            except ValueError:
                pass
        rows = q.group_by(func.date(EnterticketSale.purchase_at)).order_by(func.date(EnterticketSale.purchase_at)).all()
        return jsonify({
            "labels": [r.day.strftime("%d/%m/%Y") for r in rows],
            "values": [int(r.n or 0) for r in rows],
            "amounts": [float(r.amt or 0) for r in rows],
        })
    finally:
        s.close()


@app.post("/conciertos/<cid>/ticketing/et/vincular", endpoint="concert_et_link")
@admin_required
def concert_et_link(cid):
    s = db()
    try:
        c = s.get(Concert, to_uuid(cid))
        ev = s.get(EnterticketEvent, to_uuid(request.form.get("et_event_pk") or ""))
        if not c or not ev:
            flash("No se pudo vincular: evento no encontrado.", "danger")
        elif ev.concert_id and ev.concert_id != c.id:
            flash("Ese evento de Enterticket ya está vinculado a otro concierto.", "warning")
        else:
            _et_link_event(s, ev, c)
            s.commit()
            threading.Thread(target=_et_sync_event_bg, args=(str(ev.id),), daemon=True).start()
            flash(f"Vinculado con «{ev.name}». Sincronizando ventas en segundo plano…", "success")
            if _et_concert_has_legacy_sales(s, c.id):
                flash("Aviso: este concierto llevaba la venta en modo básico (histórico manual antiguo). Al integrarse con Enterticket, el reporte pasa a usar el desglose por ticketeras y ese histórico básico deja de sumarse.", "warning")
    except Exception as e:
        try:
            s.rollback()
        except Exception:
            pass
        flash(f"Error al vincular: {e}", "danger")
    finally:
        s.close()
    return redirect(url_for("concert_detail_view", cid=cid, tab="ticketing"))


@app.post("/conciertos/<cid>/ticketing/et/descartar", endpoint="concert_et_dismiss")
@admin_required
def concert_et_dismiss(cid):
    """Descarta una sugerencia de vinculación: el evento de ET queda IGNORED y no se vuelve a
    sugerir (ni aquí ni en otras actividades). Se puede recuperar en Integraciones."""
    s = db()
    try:
        ev = s.get(EnterticketEvent, to_uuid(request.form.get("et_event_pk") or "") or uuid.uuid4())
        if not ev:
            flash("Evento de Enterticket no encontrado.", "warning")
        else:
            ev.link_status = "IGNORED"
            s.commit()
            flash(f"«{ev.name or 'Evento'}» ya no se sugerirá para vincular.", "success")
        return redirect(safe_next_or(url_for("concert_detail_view", cid=cid, tab="ticketing")))
    except Exception as exc:
        s.rollback()
        flash(f"No se pudo descartar: {exc}", "danger")
        return redirect(safe_next_or(url_for("concert_detail_view", cid=cid, tab="ticketing")))
    finally:
        s.close()


@app.post("/conciertos/<cid>/ticketing/et/desvincular", endpoint="concert_et_unlink")
@admin_required
def concert_et_unlink(cid):
    s = db()
    try:
        ev = _et_concert_event(s, to_uuid(cid))
        if ev:
            _et_unlink_event(s, ev)
            s.commit()
            flash("Evento de Enterticket desvinculado.", "info")
    finally:
        s.close()
    return redirect(url_for("concert_detail_view", cid=cid, tab="ticketing"))


@app.post("/conciertos/<cid>/ticketing/et/sync", endpoint="concert_et_sync")
@admin_required
def concert_et_sync(cid):
    """«Actualizar ahora»: sincroniza EN LÍNEA (al recargar ya se ven los datos nuevos)."""
    s = db()
    try:
        ev = _et_concert_event(s, to_uuid(cid))
        if not ev:
            flash("Este concierto no tiene evento de Enterticket vinculado.", "warning")
        elif _et_sync_event(s, ev):
            flash("Ventas de Enterticket actualizadas.", "success")
        else:
            flash("Ya hay una sincronización de este evento en curso; recarga en unos segundos.", "info")
    except Exception as e:
        try:
            s.rollback()
        except Exception:
            pass
        flash(f"No se pudo actualizar desde Enterticket: {e}", "danger")
    finally:
        s.close()
    return redirect(url_for("concert_detail_view", cid=cid, tab="ticketing"))


@app.get("/ventas/et/estado", endpoint="sales_et_status")
@admin_required
def sales_et_status():
    """Marca de frescura de Enterticket (máx. last_synced_at), ACOTADA a los conciertos que se
    pasan en ?cids= (los del reporte abierto): el reporte la vigila y se recarga una vez cuando
    terminan los syncs lanzados al abrirlo. Sin acotar, cualquier sync ajeno provocaría recargas."""
    cids = []
    for raw in (request.args.get("cids") or "").split(",")[:300]:
        try:
            u = to_uuid(raw.strip())
            if u:
                cids.append(u)
        except Exception:
            continue
    s = db()
    try:
        q = s.query(func.max(EnterticketEvent.last_synced_at)).filter(EnterticketEvent.concert_id.isnot(None))
        if cids:
            q = q.filter(EnterticketEvent.concert_id.in_(cids))
        mx = q.scalar()
        return jsonify({"stamp": int(mx.timestamp()) if mx else 0})
    finally:
        s.close()


@app.get("/cron/enterticket/refresh", endpoint="cron_enterticket_refresh")
def cron_enterticket_refresh():
    """Refresco periódico de Enterticket (tarea programada externa con ?key=). Sin sesión."""
    expected = (settings.ENTERTICKET_CRON_KEY or "").strip()
    key = (request.args.get("key") or "").strip()
    if not expected or key != expected:
        return ("forbidden", 403)
    # Aprovechamos este cron para los recordatorios semanales de LINKS DE VENTA al promotor
    # (best-effort; el gating semanal por last_sent_at lo hace la propia función).
    try:
        _s = db()
        try:
            _process_sale_channel_reminders(_s)
        finally:
            _s.close()
    except Exception:
        app.logger.exception('[canales-venta] recordatorios semanales fallaron')
    if not et_api.enterticket_configured():
        return ("enterticket no configurado", 200)
    threading.Thread(target=_et_sync_all_bg, daemon=True).start()
    return ("refresco en marcha", 200)


def _et_event_display_label(ev: EnterticketEvent) -> str:
    """Etiqueta de un evento para la sección Compradores: el concierto vinculado si lo hay."""
    if ev.concert:
        c = ev.concert
        vn = (c.venue.name if c.venue else "") or (c.manual_venue_name or "") or (c.manual_municipality or "")
        base = f"{c.artist.name if c.artist else ev.name}"
        return base + (f" · {vn}" if vn else "")
    return ev.name


# ═════════════════════════════════════════════════════════════════════════════
# COMPRADORES · listados, filtros, importación a mano y envíos
#
# La base de compradores nació de Enterticket (deduplicada por email). Ahora tiene dos orígenes:
#   · un EVENTO de Enterticket (se alimenta solo de sus ventas), y
#   · un LISTADO subido a mano (`BuyerList`), vinculado a una actividad nuestra, para lo que se
#     vende por otro sitio o para una base que llega en un Excel.
# Los dos se ven y se trabajan IGUAL: la pantalla habla de «listados» y `_buyer_source` resuelve
# cualquiera de los dos a la misma forma.
#
# ⚠️ A propósito un listado a mano NO se guarda como un evento de Enterticket: ese espejo es el que
# alimenta la pestaña Ticketing y el Resultado de la actividad, y meterle filas que no son de ET
# haría que la app diera por real una venta que no existe.
# ═════════════════════════════════════════════════════════════════════════════

# Icono de una categoría de entrada, por lo que dice su nombre (pista, grada, palco…). Es solo
# estética, pero es lo que hace que un listado con seis categorías se lea de un vistazo.
BUYER_CATEGORY_ICONS = [
    (("pista", "general", "campo"), "fa-people-group"),
    (("grada", "asiento", "silla", "butaca", "numerad"), "fa-chair"),
    (("palco", "vip", "premium", "golden", "oro"), "fa-crown"),
    (("abono", "bono", "pase", "pass"), "fa-id-card"),
    (("invitacion", "invitación", "cortesia", "cortesía"), "fa-gift"),
    (("anticipada", "early", "promo", "descuento", "reducid"), "fa-tags"),
    (("mesa", "reservado", "zona"), "fa-champagne-glasses"),
    (("parking", "aparcamiento"), "fa-car"),
    (("camping", "acampada"), "fa-campground"),
]


def _buyer_category_icon(name: str) -> str:
    clave = _norm_text_key(name or "")
    for palabras, icono in BUYER_CATEGORY_ICONS:
        if any(p in clave for p in palabras):
            return icono
    return "fa-ticket"


# Filtros del listado (y de los envíos). Cada uno es un interruptor: se acumulan.
# (clave, etiqueta, icono, qué hace)
BUYER_FILTER_DEFS = [
    ("mail", "Con email", "fa-at"),
    ("tel", "Con teléfono", "fa-mobile-screen-button"),
    ("pub", "Aceptan publicidad", "fa-envelope-open-text"),
    ("rec", "Repiten (más de un evento)", "fa-repeat"),
    ("multi", "Más de una entrada", "fa-users"),
]
# ⚠️ NO hay orden por importe: esta pantalla es de personas y aquí no se enseñan recaudaciones.
BUYER_ORDER_DEFS = [
    ("entradas", "Más entradas", "fa-arrow-down-wide-short"),
    ("reciente", "Compra más reciente", "fa-clock"),
    ("nombre", "Nombre (A-Z)", "fa-arrow-down-a-z"),
    ("categoria", "Categoría", "fa-tags"),
]
BUYER_ROWS_LIMIT = 1000          # lo que se pinta; los totales y los envíos van sobre TODO


def _buyer_filters_from_request(args=None) -> dict:
    """Los filtros tal como vienen de la URL o de un formulario de envío."""
    args = args if args is not None else request.args
    getlist = getattr(args, "getlist", None)
    cats = [c.strip() for c in (getlist("cat") if getlist else []) if (c or "").strip()]
    return {
        "q": (args.get("q") or "").strip(),
        "cat": cats,
        "flags": [k for k, _l, _i in BUYER_FILTER_DEFS if (args.get(k) or "") in ("1", "on", "true")],
        "orden": (args.get("orden") or "entradas").strip(),
    }


def _buyer_source(session_db, *, event_pk: str = "", list_pk: str = "") -> dict | None:
    """Un LISTADO de compradores (un evento de Enterticket o uno subido a mano), en la misma forma.

    {"kind": ET|MANUAL, "pk", "key" (para la URL), "label", "date", "venue", "town", "image",
     "concert_id", "company", "manual"}
    """
    if event_pk:
        try:
            ev = session_db.get(EnterticketEvent, to_uuid(event_pk))
        except Exception:
            ev = None
        if ev is None:
            return None
        return {
            "kind": "ET", "pk": str(ev.id), "manual": False,
            "label": _et_event_display_label(ev), "name": ev.name,
            "date": (ev.event_date.strftime("%d/%m/%Y") if ev.event_date else "—"),
            "venue": ev.venue_name or "", "town": ev.venue_town or "",
            "image": ev.artist_image or ev.image_url or "",
            "concert_id": (str(ev.concert_id) if ev.concert_id else ""),
            "row": ev,
        }
    if list_pk:
        try:
            bl = session_db.get(BuyerList, to_uuid(list_pk))
        except Exception:
            bl = None
        if bl is None:
            return None
        c = bl.concert
        artista = (c.artist.name if (c is not None and c.artist) else "")
        recinto = ""
        if c is not None:
            recinto = ((c.venue.name if c.venue else "") or (c.manual_venue_name or "")
                       or (c.manual_municipality or ""))
        return {
            "kind": "MANUAL", "pk": str(bl.id), "manual": True,
            "label": bl.name or (artista or "Listado de compradores"), "name": bl.name or "",
            "date": (c.date.strftime("%d/%m/%Y") if (c is not None and c.date) else "—"),
            "venue": recinto, "town": (getattr(c, "manual_municipality", "") or "") if c is not None else "",
            "image": ((c.artist.photo_url or "") if (c is not None and c.artist) else ""),
            "concert_id": (str(bl.concert_id) if bl.concert_id else ""),
            "row": bl,
        }
    return None


def _buyer_source_company(session_db, source: dict | None):
    """La EMPRESA DEL GRUPO que promueve la actividad de este listado: su logo firma el correo y su
    nombre abreviado sale como remitente del SMS. Si no se puede resolver, None (se elige a mano)."""
    if not source or not source.get("concert_id"):
        return None
    try:
        c = session_db.get(Concert, to_uuid(source["concert_id"]))
    except Exception:
        return None
    if c is None:
        return None
    for cid in (c.group_company_id, c.billing_company_id):
        if cid:
            co = session_db.get(GroupCompany, cid)
            if co is not None:
                return co
    fila = (session_db.query(ConcertCompanyShare)
            .filter(ConcertCompanyShare.concert_id == c.id).first())
    if fila is not None and fila.company_id:
        return session_db.get(GroupCompany, fila.company_id)
    return None


def _buyer_sources_list(session_db) -> list[dict]:
    """Todos los listados con compradores (eventos de ET + listados a mano) y sus contadores.

    Los agregados van aparte del `joinedload` a propósito: mezclar `group_by` con un eager-load
    rompe el GROUP BY en Postgres."""
    # ⚠️ En la rejilla NO se enseña recaudación ni entradas: lo que interesa aquí es **a cuántos se
    # les puede mandar** algo (email y SMS), con el mismo criterio que los envíos.
    agg_ev = {r.event_id: r for r in
              (session_db.query(BuyerEvent.event_id,
                                func.count(BuyerEvent.id).label("buyers"),
                                func.count(case((_buyer_has_email_cond(), 1))).label("emails"),
                                func.count(case((_buyer_has_phone_cond(), 1))).label("sms"))
               .join(Buyer, Buyer.id == BuyerEvent.buyer_id)
               .filter(BuyerEvent.event_id.isnot(None))
               .group_by(BuyerEvent.event_id).all())}
    agg_li = {r.list_id: r for r in
              (session_db.query(BuyerEvent.list_id,
                                func.count(BuyerEvent.id).label("buyers"),
                                func.count(case((_buyer_has_email_cond(), 1))).label("emails"),
                                func.count(case((_buyer_has_phone_cond(), 1))).label("sms"))
               .join(Buyer, Buyer.id == BuyerEvent.buyer_id)
               .filter(BuyerEvent.list_id.isnot(None))
               .group_by(BuyerEvent.list_id).all())}
    salida = []
    if agg_ev:
        for ev in (session_db.query(EnterticketEvent)
                   .options(joinedload(EnterticketEvent.concert).joinedload(Concert.artist),
                            joinedload(EnterticketEvent.concert).joinedload(Concert.venue))
                   .filter(EnterticketEvent.id.in_(list(agg_ev.keys())))
                   .order_by(EnterticketEvent.event_date.desc().nullslast()).all()):
            r = agg_ev[ev.id]
            salida.append({
                "kind": "ET", "pk": str(ev.id), "manual": False,
                "label": _et_event_display_label(ev),
                "date": (ev.event_date.strftime("%d/%m/%Y") if ev.event_date else "—"),
                "sort": ev.event_date or date(1900, 1, 1),
                "venue": ev.venue_name or "", "town": ev.venue_town or "",
                "image": ev.artist_image or ev.image_url or "",
                "concert_id": (str(ev.concert_id) if ev.concert_id else ""),
                "buyers": int(r.buyers or 0), "emails": int(r.emails or 0),
                "sms": int(r.sms or 0),
            })
    # Los listados a mano salen SIEMPRE, aunque estén vacíos: se crean antes de subir el fichero y
    # tienen que poder verse para completarlos.
    for bl in (session_db.query(BuyerList)
               .options(joinedload(BuyerList.concert).joinedload(Concert.artist),
                        joinedload(BuyerList.concert).joinedload(Concert.venue))
               .order_by(BuyerList.created_at.desc()).all()):
        r = agg_li.get(bl.id)
        c = bl.concert
        recinto = ""
        if c is not None:
            recinto = ((c.venue.name if c.venue else "") or (c.manual_venue_name or "")
                       or (c.manual_municipality or ""))
        salida.append({
            "kind": "MANUAL", "pk": str(bl.id), "manual": True,
            "label": bl.name or ((c.artist.name if (c is not None and c.artist) else "")
                                 or "Listado de compradores"),
            "date": (c.date.strftime("%d/%m/%Y") if (c is not None and c.date) else "—"),
            "sort": (c.date if (c is not None and c.date) else date(1900, 1, 1)),
            "venue": recinto,
            "town": (getattr(c, "manual_municipality", "") or "") if c is not None else "",
            "image": ((c.artist.photo_url or "") if (c is not None and c.artist) else ""),
            "concert_id": (str(bl.concert_id) if bl.concert_id else ""),
            "buyers": int(getattr(r, "buyers", 0) or 0),
            "emails": int(getattr(r, "emails", 0) or 0),
            "sms": int(getattr(r, "sms", 0) or 0),
        })
    salida.sort(key=lambda x: x["sort"], reverse=True)
    return salida


def _buyers_base_query(session_db, source: dict):
    """Los compradores de un listado: (BuyerEvent, Buyer)."""
    q = (session_db.query(BuyerEvent, Buyer).join(Buyer, Buyer.id == BuyerEvent.buyer_id))
    if source["kind"] == "ET":
        return q.filter(BuyerEvent.event_id == to_uuid(source["pk"]))
    return q.filter(BuyerEvent.list_id == to_uuid(source["pk"]))


def _buyer_has_email_cond():
    """¿Se le puede mandar un correo? (el MISMO criterio en el contador, en el total del envío y en
    el envío: si no, el número de la pantalla no cuadraría con lo que sale)."""
    return and_(Buyer.email.isnot(None), Buyer.email != "")


def _buyer_has_phone_cond():
    """¿Se le puede mandar un SMS? Hace falta el número en formato internacional: desde que el
    prefijo se pone al guardar, lo que no empieza por «+» es que no es un teléfono."""
    return and_(Buyer.phone.isnot(None), Buyer.phone != "", Buyer.phone.like("+%"))


def _buyers_apply_filters(q, filtros: dict, *, channel: str = ""):
    """Aplica al listado los filtros elegidos (texto, categorías e interruptores).

    Es el punto ÚNICO: lo usan la pantalla, el contador de un envío y el propio envío, así que el
    número que se ve antes de mandar es exactamente a quién se le manda. `channel` añade lo que ese
    canal necesita (un SMS sin teléfono no se puede mandar)."""
    texto = (filtros.get("q") or "").strip()
    if texto:
        q = q.filter(or_(_sa_contains_text(Buyer.name, texto),
                         _sa_contains_text(Buyer.email, texto),
                         _sa_contains_text(Buyer.phone, texto)))
    cats = [c for c in (filtros.get("cat") or []) if c]
    if cats:
        # `categories` es un JSONB con los nombres: se pide que tenga ALGUNA de las elegidas.
        q = q.filter(or_(*[BuyerEvent.categories.contains([c]) for c in cats]))
    flags = set(filtros.get("flags") or [])
    if channel == "EMAIL":
        flags.add("mail")
    if channel == "SMS":
        flags.add("tel")
    if "mail" in flags:
        q = q.filter(_buyer_has_email_cond())
    if "tel" in flags:
        q = q.filter(_buyer_has_phone_cond())
    if "pub" in flags:
        q = q.filter(Buyer.accepts_marketing.is_(True))
    if "rec" in flags:
        q = q.filter(Buyer.events_count > 1)
    if "multi" in flags:
        q = q.filter(BuyerEvent.tickets_count > 1)
    return q


def _buyers_order(q, orden: str):
    if orden == "reciente":
        return q.order_by(BuyerEvent.last_purchase_at.desc().nullslast(), Buyer.name.asc())
    if orden == "nombre":
        return q.order_by(Buyer.name.asc().nullslast(), Buyer.email.asc())
    if orden == "categoria":
        return q.order_by(BuyerEvent.categories.asc(), BuyerEvent.tickets_count.desc())
    return q.order_by(BuyerEvent.tickets_count.desc(), Buyer.email.asc().nullslast())


def _buyer_categories_for_source(session_db, source: dict) -> list[dict]:
    """Las categorías de entrada que hay EN ESTE LISTADO, con cuántos compradores tiene cada una.

    Solo se ofrecen las que existen: un filtro que no puede devolver nada solo hace ruido (la misma
    regla que los tipos del calendario de agenda)."""
    filas = _buyers_base_query(session_db, source).with_entities(BuyerEvent.categories).all()
    cuenta: dict[str, int] = {}
    for (cats,) in filas:
        for c in (cats or []):
            nombre = (c or "").strip()
            if nombre:
                cuenta[nombre] = cuenta.get(nombre, 0) + 1
    return [{"name": n, "n": cuenta[n], "icon": _buyer_category_icon(n)}
            for n in sorted(cuenta, key=lambda x: (-cuenta[x], x.casefold()))]


def _buyer_chip_url(base_args: dict, **cambios) -> str:
    """La URL de la pantalla con un filtro puesto o quitado (los chips son enlaces normales)."""
    args = {k: v for k, v in base_args.items() if v not in (None, "", [])}
    for k, v in cambios.items():
        if v in (None, "", []):
            args.pop(k, None)
        else:
            args[k] = v
    return url_for("buyers_view", **args)


def _buyer_filter_chips(source: dict | None, filtros: dict, categorias: list[dict],
                        vista: str) -> dict:
    """Los filtros como CHIPS con su icono: categorías de entrada, interruptores y orden.

    Solo se ofrecen las categorías que de verdad hay en el listado (un filtro que no puede devolver
    nada solo hace ruido) y cada chip es un enlace que se enciende o se apaga."""
    base = {"vista": vista}
    if source:
        base["event" if source["kind"] == "ET" else "lista"] = source["pk"]
    if filtros.get("q"):
        base["q"] = filtros["q"]
    if (filtros.get("orden") or "entradas") != "entradas":
        base["orden"] = filtros["orden"]
    activos = set(filtros.get("flags") or [])
    base_flags = {k: "1" for k in activos}
    cats = list(filtros.get("cat") or [])

    # Las categorías NO son chips-enlace: van en un único filtro con una casilla por categoría, y
    # **marcada = se ve**. Sin filtro puesto están todas marcadas.
    chips_cat = []
    for c in categorias:
        chips_cat.append({**c, "on": (c["name"] in cats),
                          "checked": (not cats) or (c["name"] in cats)})
    chips_flag = []
    for clave, etiqueta, icono in BUYER_FILTER_DEFS:
        encendido = clave in activos
        flags = {k: "1" for k in activos if k != clave} if encendido else             {**base_flags, clave: "1"}
        chips_flag.append({"key": clave, "label": etiqueta, "icon": icono, "on": encendido,
                           "url": _buyer_chip_url({**base, **flags}, cat=cats)})
    ordenes = []
    for clave, etiqueta, icono in BUYER_ORDER_DEFS:
        ordenes.append({"key": clave, "label": etiqueta, "icon": icono,
                        "on": (filtros.get("orden") or "entradas") == clave,
                        "url": _buyer_chip_url({**base, **base_flags},
                                               cat=cats, orden=(None if clave == "entradas" else clave))})
    limpio = bool(cats or activos or filtros.get("q") or
                  (filtros.get("orden") or "entradas") != "entradas")
    return {"cats": chips_cat, "flags": chips_flag, "orders": ordenes,
            "any": limpio,
            "clear_url": _buyer_chip_url({"vista": vista, **({"event": source["pk"]}
                                                             if (source and source["kind"] == "ET")
                                                             else ({"lista": source["pk"]}
                                                                   if source else {}))})}


def _buyer_row_payload(be: BuyerEvent, b: Buyer) -> dict:
    return {
        "id": str(b.id), "name": b.name or "", "email": b.email or "", "phone": b.phone or "",
        "tickets": int(be.tickets_count or 0),
        "events": int(b.events_count or 0), "marketing": bool(b.accepts_marketing),
        "last": be.last_purchase_at,
        "cats": [{"name": c, "icon": _buyer_category_icon(c)} for c in (be.categories or [])],
    }


def _buyers_recompute_aggregates(session_db, buyer_ids) -> None:
    """Agregados globales (eventos, entradas, importe) de unos compradores, en UNA sentencia, y
    limpieza de los que se han quedado sin ningún listado.

    Con miles de compradores, un SELECT por comprador saturaba la base en cada sincronización."""
    ids = [i for i in (buyer_ids or []) if i]
    if not ids:
        return
    session_db.execute(text("""
        UPDATE buyers b SET
            events_count = COALESCE(agg.n, 0),
            tickets_count = COALESCE(agg.t, 0),
            amount_total = COALESCE(agg.a, 0),
            first_purchase_at = agg.f,
            last_purchase_at = agg.l,
            updated_at = now()
        FROM (
            SELECT b2.id AS bid, count(be.id) AS n, sum(be.tickets_count) AS t,
                   sum(be.amount_total) AS a, min(be.first_purchase_at) AS f,
                   max(be.last_purchase_at) AS l
            FROM buyers b2 LEFT JOIN buyer_events be ON be.buyer_id = b2.id
            WHERE b2.id IN :ids GROUP BY b2.id
        ) agg
        WHERE b.id = agg.bid
    """).bindparams(bindparam("ids", expanding=True)), {"ids": ids})


# ── AÑADIR COMPRADORES A MANO (desde un fichero) ─────────────────────────────────────────────────
# El fichero se lee con el MISMO motor que la importación de terceros (`buyer_import.py`), que
# reconoce las columnas solo y enseña un ejemplo de cada una para confirmar a qué corresponde.
#
# ⚠️ NO SE DUPLICAN COMPRADORES: se identifican por su email y, si no lo traen, por su teléfono.
#    A quien ya está solo se le COMPLETA lo que le falte (si no tenía teléfono, se le pone; lo que
#    ya tiene escrito no se pisa).
# ⚠️ Un fichero de ticketera trae **una fila por entrada**: las filas del mismo comprador se agrupan
#    sumando entradas e importe y juntando sus categorías.
# ⚠️ Reimportar el mismo fichero deja lo mismo (las entradas de un comprador en un listado se
#    ESCRIBEN, no se suman a lo que ya había), así que no infla los números.

def _buyer_import_dt(value: str):
    """La fecha de compra del fichero («21/08/2026 19:30») como datetime, o None."""
    txt = (value or "").strip()
    if not txt:
        return None
    for formato in ("%d/%m/%Y %H:%M", "%d/%m/%Y"):
        try:
            return datetime.strptime(txt, formato)
        except Exception:
            continue
    return None


def _buyer_import_group(rows: list[dict]) -> tuple[list[dict], int]:
    """Agrupa las filas del fichero por comprador. Devuelve (grupos, filas sin contacto)."""
    grupos: dict[str, dict] = {}
    orden: list[str] = []
    sin_contacto = 0
    for r in (rows or []):
        if (r.get("_sin_contacto") or "") == "1":
            sin_contacto += 1
            continue
        email = (r.get("email") or "").strip().lower()
        telefono = _normalize_phone_value((r.get("phone") or "").strip()) or ""
        if not email and not telefono:
            sin_contacto += 1
            continue
        clave = ("e:" + email) if email else ("t:" + telefono)
        g = grupos.get(clave)
        if g is None:
            g = {"key": clave, "email": email, "phone": telefono, "name": "",
                 "tickets": 0, "amount": Decimal("0"), "cats": [], "marketing": False,
                 "first": None, "last": None, "rows": 0}
            grupos[clave] = g
            orden.append(clave)
        g["rows"] += 1
        if not g["name"] and (r.get("name") or "").strip():
            g["name"] = (r.get("name") or "").strip()
        if not g["phone"] and telefono:
            g["phone"] = telefono
        if not g["email"] and email:
            g["email"] = email
        try:
            g["tickets"] += int(r.get("tickets") or 1)
        except Exception:
            g["tickets"] += 1
        try:
            g["amount"] += Decimal(str(r.get("amount") or "0") or "0")
        except Exception:
            pass
        cat = (r.get("category") or "").strip()
        if cat and cat not in g["cats"]:
            g["cats"].append(cat)
        if (r.get("marketing") or "") == "1":
            g["marketing"] = True
        cuando = _buyer_import_dt(r.get("purchase_at") or "")
        if cuando:
            g["first"] = cuando if (g["first"] is None or cuando < g["first"]) else g["first"]
            g["last"] = cuando if (g["last"] is None or cuando > g["last"]) else g["last"]
    return [grupos[k] for k in orden], sin_contacto


def _buyer_import_match(session_db, grupos: list[dict]) -> dict:
    """A qué comprador ya existente corresponde cada grupo (por email y, si no, por teléfono)."""
    emails = [g["email"] for g in grupos if g["email"]]
    telefonos = [g["phone"] for g in grupos if g["phone"]]
    por_email, por_telefono = {}, {}
    if emails:
        for b in session_db.query(Buyer).filter(func.lower(Buyer.email).in_(emails)).all():
            por_email[(b.email or "").lower()] = b
    if telefonos:
        for b in session_db.query(Buyer).filter(Buyer.phone.in_(telefonos)).all():
            if b.phone:
                por_telefono[b.phone] = b
    salida = {}
    for g in grupos:
        b = por_email.get(g["email"]) if g["email"] else None
        if b is None and g["phone"]:
            b = por_telefono.get(g["phone"])
        if b is not None:
            salida[g["key"]] = b
    return salida


def _buyer_import_missing_labels(b: Buyer, g: dict) -> list[str]:
    """Qué dato se le va a COMPLETAR a alguien que ya está (solo lo que tiene vacío)."""
    falta = []
    if g["email"] and not (b.email or "").strip():
        falta.append("email")
    if g["phone"] and not (b.phone or "").strip():
        falta.append("teléfono")
    if g["name"] and not (b.name or "").strip():
        falta.append("nombre")
    return falta


def _buyer_import_summary(session_db, grupos: list[dict], sin_contacto: int, source: dict) -> dict:
    """Lo que va a pasar al importar, para enseñarlo ANTES de tocar nada."""
    existentes = _buyer_import_match(session_db, grupos)
    ya_en_listado = set()
    if existentes and source.get("pk"):
        q = session_db.query(BuyerEvent.buyer_id)
        if source["kind"] == "ET":
            q = q.filter(BuyerEvent.event_id == to_uuid(source["pk"]))
        else:
            q = q.filter(BuyerEvent.list_id == to_uuid(source["pk"]))
        ya_en_listado = {r[0] for r in q.filter(
            BuyerEvent.buyer_id.in_([b.id for b in existentes.values()])).all()}
    nuevos, completar, iguales = [], [], 0
    for g in grupos:
        b = existentes.get(g["key"])
        if b is None:
            nuevos.append({"name": g["name"], "email": g["email"], "phone": g["phone"],
                           "tickets": g["tickets"], "cats": g["cats"]})
            continue
        falta = _buyer_import_missing_labels(b, g)
        if falta or b.id not in ya_en_listado:
            completar.append({"name": (b.name or g["name"]), "email": (b.email or g["email"]),
                              "phone": (b.phone or g["phone"]), "falta": falta,
                              "nuevo_en_listado": b.id not in ya_en_listado,
                              "tickets": g["tickets"], "cats": g["cats"]})
        else:
            iguales += 1
    return {
        "total": len(grupos), "nuevos": len(nuevos), "existentes": len(completar) + iguales,
        "sin_contacto": sin_contacto, "iguales": iguales,
        "nuevos_muestra": nuevos[:25], "existentes_muestra": completar[:25],
        "completar": len([c for c in completar if c["falta"]]),
    }


def _buyer_import_apply(session_db, grupos: list[dict], source: dict) -> dict:
    """Da de alta / completa los compradores y los mete en el listado. Devuelve el recuento."""
    existentes = _buyer_import_match(session_db, grupos)
    creados, completados, actualizados = 0, 0, 0
    afectados = set()
    es_et = source["kind"] == "ET"
    origen_pk = to_uuid(source["pk"])
    concert_id = to_uuid(source["concert_id"]) if source.get("concert_id") else None
    # Las filas que ya tiene el listado, de una vez (nada de una consulta por comprador).
    q_be = session_db.query(BuyerEvent)
    q_be = q_be.filter(BuyerEvent.event_id == origen_pk) if es_et else \
        q_be.filter(BuyerEvent.list_id == origen_pk)
    por_comprador = {be.buyer_id: be for be in q_be.all()}
    for g in grupos:
        b = existentes.get(g["key"])
        if b is None:
            b = Buyer(email=(g["email"] or None), name=(g["name"] or None),
                      phone=(g["phone"] or None), accepts_marketing=bool(g["marketing"]))
            session_db.add(b)
            try:
                session_db.flush()
            except Exception:
                # Choque con el índice único (alguien lo ha dado de alta a la vez): se relee.
                session_db.rollback()
                b = (session_db.query(Buyer)
                     .filter(func.lower(Buyer.email) == (g["email"] or "").lower()).first()
                     if g["email"] else
                     session_db.query(Buyer).filter(Buyer.phone == g["phone"]).first())
                if b is None:
                    continue
                por_comprador = {be.buyer_id: be for be in q_be.all()}
            else:
                creados += 1
        else:
            # ⚠️ Solo se COMPLETA lo que está vacío: lo que ya está escrito no se pisa.
            toco = False
            if g["email"] and not (b.email or "").strip():
                # El email es único: si ya lo tiene otro, no se toca (son dos fichas distintas).
                otro = session_db.query(Buyer.id).filter(
                    func.lower(Buyer.email) == g["email"]).first()
                if not otro:
                    b.email = g["email"]
                    toco = True
            if g["phone"] and not (b.phone or "").strip():
                b.phone = g["phone"]
                toco = True
            if g["name"] and not (b.name or "").strip():
                b.name = g["name"]
                toco = True
            if g["marketing"] and not b.accepts_marketing:
                b.accepts_marketing = True
                toco = True
            if toco:
                completados += 1
        afectados.add(b.id)
        be = por_comprador.get(b.id)
        if be is None:
            be = BuyerEvent(buyer_id=b.id,
                            event_id=(origen_pk if es_et else None),
                            list_id=(None if es_et else origen_pk))
            session_db.add(be)
            por_comprador[b.id] = be
        else:
            actualizados += 1
        be.concert_id = concert_id
        be.tickets_count = int(g["tickets"] or 0)
        be.amount_total = g["amount"]
        be.categories = list(g["cats"])
        if g["first"]:
            be.first_purchase_at = g["first"]
        if g["last"]:
            be.last_purchase_at = g["last"]
    session_db.flush()
    _buyers_recompute_aggregates(session_db, list(afectados))
    session_db.commit()
    return {"creados": creados, "completados": completados, "actualizados": actualizados,
            "total": len(grupos)}


def _buyer_subject_options(session_db) -> list[dict]:
    """Artistas y EVENTOS para decir de quién es la actividad de un listado nuevo.

    «Activo» = tiene alguna actividad del último año o por venir; los demás salen tras «Ver más»."""
    desde = date.today() - timedelta(days=365)
    activos_art, activos_ev = set(), set()
    try:
        for aid, eid in (session_db.query(Concert.artist_id, Concert.event_id)
                         .filter(or_(Concert.date.is_(None), Concert.date >= desde)).all()):
            if eid:
                activos_ev.add(eid)
            elif aid:
                activos_art.add(aid)
    except Exception:
        app.logger.exception("[compradores] no se pudo calcular qué artistas están activos")
    salida = []
    for a in (session_db.query(Artist).filter(Artist.event_id.is_(None))
              .order_by(Artist.name.asc()).all()):
        salida.append({"kind": "ARTIST", "id": str(a.id), "name": a.name or "",
                       "photo_url": (a.photo_url or ""), "active": a.id in activos_art})
    for e in session_db.query(AppEvent).order_by(AppEvent.name.asc()).all():
        salida.append({"kind": "EVENT", "id": str(e.id), "name": e.name or "",
                       "photo_url": (e.logo_url or ""), "active": e.id in activos_ev})
    salida.sort(key=lambda x: (not x["active"], (x["name"] or "").casefold()))
    return salida


@app.get("/compradores/actividades", endpoint="buyers_subject_activities")
@admin_required
def buyers_subject_activities():
    """Las actividades de un artista o de un evento, para elegir a cuál se vincula el listado."""
    kind = (request.args.get("kind") or "ARTIST").strip().upper()
    try:
        pk = to_uuid((request.args.get("id") or "").strip())
    except Exception:
        return jsonify({"ok": False, "error": "Falta el artista o el evento."}), 400
    s = db()
    try:
        q = (s.query(Concert)
             .options(joinedload(Concert.artist), joinedload(Concert.venue))
             .order_by(Concert.date.desc().nullslast()))
        q = q.filter(Concert.event_id == pk) if kind == "EVENT" else \
            q.filter(Concert.artist_id == pk, Concert.event_id.is_(None))
        filas = q.limit(300).all()
        con_listado = {r[0] for r in s.query(BuyerList.concert_id)
                       .filter(BuyerList.concert_id.in_([c.id for c in filas] or [None])).all()}
        con_et = {r[0] for r in s.query(EnterticketEvent.concert_id)
                  .filter(EnterticketEvent.concert_id.in_([c.id for c in filas] or [None])).all()}
        salida = []
        for c in filas:
            recinto = ((c.venue.name if c.venue else "") or (c.manual_venue_name or "")
                       or (c.manual_municipality or ""))
            salida.append({
                "id": str(c.id),
                "label": ((c.festival_name or "").strip()
                          or _activity_kind_label(c.activity_type) or "Actividad"),
                "date": (c.date.strftime("%d/%m/%Y") if c.date else "Sin fecha"),
                "venue": recinto, "town": (c.manual_municipality or ""),
                "icon": QUAD_ACTIVITY_ICONS.get(_activity_kind_key(c.activity_type), "fa-calendar-day"),
                "has_list": c.id in con_listado, "has_et": c.id in con_et,
            })
        return jsonify({"ok": True, "activities": salida})
    finally:
        s.close()


def can_edit_buyers() -> bool:
    """¿Puede esta persona TOCAR la base de compradores (importar listados, mandar envíos)?"""
    return is_master() or has_access_key("databases.buyers", edit=True, include_descendants=True)


@app.get("/compradores", endpoint="buyers_view")
@admin_required
def buyers_view():
    """Base de datos de COMPRADORES: por listados (un evento de Enterticket o uno subido a mano) o
    el listado global de todos. Dentro de un listado se filtra por categoría de entrada y se manda
    un SMS o un correo a los que queden."""
    filtros = _buyer_filters_from_request()
    event_pk = (request.args.get("event") or "").strip()
    list_pk = (request.args.get("lista") or "").strip()
    vista = (request.args.get("vista") or
             ("listado" if (event_pk or list_pk) else "listados")).strip()
    s = db()
    try:
        source = _buyer_source(s, event_pk=event_pk, list_pk=list_pk) if (event_pk or list_pk) else None
        if source is None and vista == "listado":
            vista = "listados"
        sources = _buyer_sources_list(s) if vista == "listados" else []
        buyers, categorias = [], []
        totals = {"buyers": 0, "tickets": 0, "emails": 0, "sms": 0}
        company = None
        if vista == "listado" and source:
            categorias = _buyer_categories_for_source(s, source)
            # ⚠️ El filtro de categorías se maneja QUITANDO las que no se quieren ver, así que
            # tenerlas TODAS marcadas es no filtrar. Si no se hiciera esto, un comprador sin
            # ninguna categoría desaparecería del listado por estar «todas» seleccionadas.
            nombres = {c["name"] for c in categorias}
            if filtros["cat"] and nombres and set(filtros["cat"]) >= nombres:
                filtros["cat"] = []
            company = _buyer_source_company(s, source)
            q = _buyers_apply_filters(_buyers_base_query(s, source), filtros)
            # Totales sobre TODO lo filtrado (no solo lo que se pinta), y **a cuántos se les puede
            # mandar** cada cosa: es lo que se va a poder enviar con esos filtros puestos.
            t_count, t_tickets, t_mail, t_sms = (
                q.with_entities(
                    func.count(BuyerEvent.id),
                    func.sum(BuyerEvent.tickets_count),
                    func.count(case((_buyer_has_email_cond(), 1))),
                    func.count(case((_buyer_has_phone_cond(), 1)))).one())
            totals = {"buyers": int(t_count or 0), "tickets": int(t_tickets or 0),
                      "emails": int(t_mail or 0), "sms": int(t_sms or 0)}
            for be, b in _buyers_order(q, filtros["orden"]).limit(BUYER_ROWS_LIMIT).all():
                buyers.append(_buyer_row_payload(be, b))
        elif vista == "todos":
            q = s.query(Buyer)
            if filtros["q"]:
                q = q.filter(or_(_sa_contains_text(Buyer.name, filtros["q"]),
                                 _sa_contains_text(Buyer.email, filtros["q"]),
                                 _sa_contains_text(Buyer.phone, filtros["q"])))
            flags = set(filtros["flags"])
            if "mail" in flags:
                q = q.filter(_buyer_has_email_cond())
            if "tel" in flags:
                q = q.filter(_buyer_has_phone_cond())
            if "pub" in flags:
                q = q.filter(Buyer.accepts_marketing.is_(True))
            if "rec" in flags:
                q = q.filter(Buyer.events_count > 1)
            t_count, t_tickets, t_mail, t_sms = q.with_entities(
                func.count(Buyer.id), func.sum(Buyer.tickets_count),
                func.count(case((_buyer_has_email_cond(), 1))),
                func.count(case((_buyer_has_phone_cond(), 1)))).one()
            totals = {"buyers": int(t_count or 0), "tickets": int(t_tickets or 0),
                      "emails": int(t_mail or 0), "sms": int(t_sms or 0)}
            orden = filtros["orden"]
            if orden == "reciente":
                q = q.order_by(Buyer.last_purchase_at.desc().nullslast())
            elif orden == "nombre":
                q = q.order_by(Buyer.name.asc().nullslast())
            else:
                q = q.order_by(Buyer.tickets_count.desc(), Buyer.email.asc().nullslast())
            for b in q.limit(BUYER_ROWS_LIMIT).all():
                buyers.append({"id": str(b.id), "name": b.name or "", "email": b.email or "",
                               "phone": b.phone or "", "tickets": int(b.tickets_count or 0),
                               "events": int(b.events_count or 0),
                               "marketing": bool(b.accepts_marketing),
                               "last": b.last_purchase_at, "cats": []})
        ciclo = _buyer_source_cycle(s, source) if (vista == "listado" and source) else None
        return render_template(
            "compradores.html", title="Compradores",
            sources=sources, buyers=buyers, totals=totals, vista=vista,
            source=source, company=company, categorias=categorias, filtros=filtros,
            cycle=ciclo,
            # ⚠️ La empresa que firma NO se pregunta si la actividad ya la tiene configurada: se pone
            # la que corresponde. Solo se pregunta cuando la actividad es de un CICLO o FESTIVAL
            # propio (ahí sí hay dos respuestas posibles: el ciclo o la empresa que lo organiza).
            sender_company=((s.get(GroupCompany, ciclo.managing_company_id)
                             if (ciclo is not None and ciclo.managing_company_id) else None)
                            or company),
            cycle_kind_labels=CYCLE_FESTIVAL_KIND_LABELS,
            chips=_buyer_filter_chips(source, filtros, categorias, vista),
            # Los filtros puestos, para que «exportar» baje EXACTAMENTE lo que se está viendo.
            filtros_url={**({"q": filtros["q"]} if filtros["q"] else {}),
                         **({"cat": filtros["cat"]} if filtros["cat"] else {}),
                         **{k: "1" for k in filtros["flags"]},
                         **({"orden": filtros["orden"]} if filtros["orden"] != "entradas" else {})},
            filter_defs=BUYER_FILTER_DEFS, order_defs=BUYER_ORDER_DEFS,
            can_edit=can_edit_buyers(), rows_limit=BUYER_ROWS_LIMIT,
            subjects=(_buyer_subject_options(s) if can_edit_buyers() else []),
            companies=s.query(GroupCompany).order_by(GroupCompany.name.asc()).all(),
            sms_ready=_sms_available(),
            et_configured=et_api.enterticket_configured(),
            q=filtros["q"],
        )
    finally:
        s.close()


# ── Importar un fichero de compradores ───────────────────────────────────────────────────────────
@app.post("/compradores/importar/analizar", endpoint="buyers_import_analyze")
@admin_required
def buyers_import_analyze():
    """Lee el fichero y devuelve sus columnas con el campo reconocido y un ejemplo de cada una."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para importar compradores."}), 403
    fichero = request.files.get("file")
    if not fichero or not (fichero.filename or "").strip():
        return jsonify({"ok": False, "error": "Elige un fichero (Excel o CSV)."}), 400
    try:
        datos = fichero.read()
        analisis = buyer_import.parse_file(datos, fichero.filename or "")
    except Exception as exc:
        app.logger.exception("[compradores] no se pudo leer el fichero")
        return jsonify({"ok": False, "error": "No se pudo leer el fichero: %s" % exc}), 400
    if not analisis.get("rows"):
        return jsonify({"ok": False, "error": "El fichero no tiene ninguna fila con datos."}), 400
    return jsonify({
        "ok": True,
        "columns": analisis["columns"],
        "rows": analisis["rows"],
        "sheet_rows": analisis["sheet_rows"],
        "fields": [{"key": k, "label": buyer_import.FIELD_LABELS[k]} for k in buyer_import.FIELD_KEYS],
        "ignore": buyer_import.TARGET_IGNORE,
        "filename": (fichero.filename or ""),
    })


def _buyers_import_payload():
    """Filas y mapeo tal como los manda la pantalla (van por JSON: el fichero se lee UNA vez)."""
    datos = request.get_json(silent=True) or {}
    filas = datos.get("rows") or []
    mapeo = datos.get("mapping") or {}
    return datos, filas, mapeo


@app.post("/compradores/importar/preparar", endpoint="buyers_import_prepare")
@admin_required
def buyers_import_prepare():
    """Qué va a pasar al importar: cuántos son nuevos, a cuántos se les completa un dato y cuántas
    filas se descartan por no traer ni email ni teléfono."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para importar compradores."}), 403
    datos, filas, mapeo = _buyers_import_payload()
    s = db()
    try:
        source = _buyer_source(s, event_pk=(datos.get("event") or ""),
                               list_pk=(datos.get("lista") or ""))
        if source is None:
            concert_pk = (datos.get("concert_id") or "").strip()
            if not concert_pk:
                return jsonify({"ok": False, "error": "Falta el listado o la actividad."}), 400
            # Todavía NO se crea nada: el resumen se hace contra un listado que no existe
            # (sin `pk`, así que nadie está «ya en el listado»).
            source = {"kind": "MANUAL", "pk": "", "concert_id": concert_pk, "manual": True,
                      "label": ""}
        grupos, sin_contacto = _buyer_import_group(buyer_import.apply_mapping(filas, mapeo))
        if not grupos:
            return jsonify({"ok": False,
                            "error": ("Ninguna fila trae email ni teléfono: sin uno de los dos no se "
                                      "puede dar de alta a un comprador.")}), 400
        resumen = _buyer_import_summary(s, grupos, sin_contacto, source)
        return jsonify({"ok": True, "resumen": resumen})
    finally:
        s.close()


@app.post("/compradores/importar/crear", endpoint="buyers_import_create")
@admin_required
def buyers_import_create():
    """Importa de verdad: da de alta a los nuevos, completa lo que falte y los mete en el listado."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para importar compradores."}), 403
    datos, filas, mapeo = _buyers_import_payload()
    s = db()
    try:
        source = _buyer_source(s, event_pk=(datos.get("event") or ""),
                              list_pk=(datos.get("lista") or ""))
        if source is None:
            concert_pk = (datos.get("concert_id") or "").strip()
            if not concert_pk:
                return jsonify({"ok": False, "error": "Falta el listado o la actividad."}), 400
            try:
                c = s.get(Concert, to_uuid(concert_pk))
            except Exception:
                c = None
            if c is None:
                return jsonify({"ok": False, "error": "Esa actividad no existe."}), 404
            bl = (s.query(BuyerList).filter(BuyerList.concert_id == c.id)
                  .order_by(BuyerList.created_at.asc()).first())
            if bl is None:
                estado = _current_user_state() or {}
                nombre = (datos.get("nombre") or "").strip()
                if not nombre:
                    artista = (c.artist.name if c.artist else "") or "Actividad"
                    nombre = "%s%s" % (artista, (" · " + c.date.strftime("%d/%m/%Y")) if c.date else "")
                bl = BuyerList(name=nombre[:200], concert_id=c.id, source="MANUAL",
                               created_by_user_id=_safe_uuid(estado.get("user_id")),
                               created_by_nick=(estado.get("nick") or ""))
                s.add(bl)
                s.commit()
            source = _buyer_source(s, list_pk=str(bl.id))
        grupos, _sin = _buyer_import_group(buyer_import.apply_mapping(filas, mapeo))
        if not grupos:
            return jsonify({"ok": False, "error": "No hay ninguna fila que se pueda importar."}), 400
        resultado = _buyer_import_apply(s, grupos, source)
        url = url_for("buyers_view", **({"event": source["pk"]} if source["kind"] == "ET"
                                        else {"lista": source["pk"]}), vista="listado")
        return jsonify({"ok": True, "resultado": resultado, "url": url,
                        "label": source.get("label") or ""})
    except Exception as exc:
        s.rollback()
        app.logger.exception("[compradores] la importación ha fallado")
        return jsonify({"ok": False, "error": "No se pudo importar: %s" % exc}), 500
    finally:
        s.close()


@app.post("/compradores/listas/<lid>/eliminar", endpoint="buyers_list_delete")
@admin_required
def buyers_list_delete(lid):
    """Borra un listado subido a mano (y sus filas de comprador×listado; los compradores en sí se
    conservan si están en otro listado)."""
    if not can_edit_buyers():
        flash("No tienes permiso para eliminar listados de compradores.", "danger")
        return redirect(url_for("buyers_view"))
    s = db()
    try:
        bl = s.get(BuyerList, to_uuid(lid))
        if bl is None:
            flash("Ese listado ya no existe.", "warning")
            return redirect(url_for("buyers_view"))
        afectados = [r[0] for r in s.query(BuyerEvent.buyer_id)
                     .filter(BuyerEvent.list_id == bl.id).all()]
        nombre = bl.name or "listado"
        s.delete(bl)
        s.flush()
        _buyers_recompute_aggregates(s, afectados)
        # Los compradores que se queden sin ningún listado dejan de existir (igual que en ET).
        if afectados:
            s.execute(text("DELETE FROM buyers WHERE id IN :ids AND events_count = 0")
                      .bindparams(bindparam("ids", expanding=True)), {"ids": afectados})
        s.commit()
        flash("Listado «%s» eliminado." % nombre, "success")
    except Exception as exc:
        s.rollback()
        flash("No se pudo eliminar: %s" % exc, "danger")
    finally:
        s.close()
    return redirect(url_for("buyers_view"))


# ═════════════════════════════════════════════════════════════════════════════
# ENVÍOS A COMPRADORES (SMS y correo)
#
# Desde el listado de compradores de un evento se manda un SMS o un correo a los que se elijan (los
# del listado entero o los que dejen los filtros: categoría de entrada, publicidad, con teléfono…).
# La pantalla enseña **el total de envíos** y **cómo va a quedar el mensaje** antes de mandar nada.
#
# Reglas de la casa que se aplican aquí:
# · El correo lo firma la EMPRESA DEL GRUPO que promueve: su logo arriba a la derecha, el título
#   centrado debajo y el texto debajo. El botón, si se pone, va justo debajo del texto a la derecha,
#   y los adjuntos al final.
# · En el SMS el remitente ES esa empresa (su «nombre abreviado para SMS», que se pone en su ficha).
# · Los enlaces de un SMS se ACORTAN solos (`_shorten_links_in_text`), y los adjuntos se suben a una
#   página nuestra cuyo enlace también se acorta: en un SMS no se puede adjuntar nada.
# · UN envío a miles de personas NO cabe en una petición: se guarda la campaña con sus
#   destinatarios y se manda por tandas con presupuesto de tiempo, diciendo cuántos quedan.
# ═════════════════════════════════════════════════════════════════════════════

CAMPAIGN_BUDGET_SECONDS = 45.0          # lo mismo que el resto de acciones «para todos»
CAMPAIGN_FILE_FOLDER = "campaigns"
CAMPAIGN_IMAGE_EXTS = {".jpg", ".jpeg", ".png", ".gif", ".webp", ".heic", ".heif"}


def _campaign_file_is_image(nombre: str, mimetype: str = "") -> bool:
    if (mimetype or "").lower().startswith("image/"):
        return True
    return Path((nombre or "").lower()).suffix in CAMPAIGN_IMAGE_EXTS


def _campaign_files_clean(files) -> list[dict]:
    """Los adjuntos tal como los manda la pantalla, quedándose solo con lo que hace falta."""
    salida = []
    for f in (files or [])[:12]:
        if not isinstance(f, dict):
            continue
        url = (f.get("url") or "").strip()
        if not url:
            continue
        nombre = (f.get("name") or "adjunto").strip()[:180]
        salida.append({"url": url, "name": nombre,
                       "mimetype": (f.get("mimetype") or "").strip()[:120],
                       "image": _campaign_file_is_image(nombre, f.get("mimetype") or "")})
    return salida


def _campaign_files_url(session_db, camp) -> str:
    """La página pública con los adjuntos de un envío (la que se manda en el SMS)."""
    if not (camp.files_json or []):
        return ""
    if not camp.files_token:
        camp.files_token = _uuid_token()
        session_db.flush()
    return _external_url_for("public_campaign_files", token=camp.files_token)


def _campaign_sms_text(session_db, camp, *, files_url: str = "") -> str:
    """El SMS tal como va a salir: el texto y, al final, los enlaces (ya acortados).

    ⚠️ El enlace va AL FINAL a propósito: es donde los móviles pintan la previsualización."""
    partes = [(camp.body or "").strip()]
    if (camp.link_url or "").strip():
        partes.append((camp.link_url or "").strip())
    if files_url:
        partes.append(files_url)
    texto = "\n".join([p for p in partes if p])
    return _shorten_links_in_text(session_db, texto, kind="CAMPAIGN")


def _campaign_sms_preview(session_db, body: str, link_url: str, files: list[dict]) -> dict:
    """Lo que se enseña mientras se escribe un SMS: el texto final, los caracteres y los trozos.

    ⚠️ El enlace que se escribe se cuenta **ya acortado si es nuestro** y con su longitud REAL si es
    de fuera (el acortador solo acorta lo de casa): contar siempre 38 caracteres haría que el
    contador mintiera justo con el enlace de una ticketera. El de los adjuntos sí es siempre nuestro,
    así que se cuenta con la longitud exacta de un enlace corto (todos miden igual) aunque todavía no
    exista: se crea al enviar."""
    partes = [(body or "").strip()]
    if (link_url or "").strip():
        partes.append((link_url or "").strip())
    crudo = "\n".join([p for p in partes if p])
    texto = _shorten_links_in_text(session_db, crudo, kind="CAMPAIGN")
    if files:
        texto = (texto + "\n" + "%s/l/%s" % (_short_link_base().rstrip("/"), "-" * 6)).strip()
    acc = _sms_account(session_db)
    limpio = sms_utils.clean_text(texto, avoid_accents=bool(getattr(acc, "avoid_accents", True)))
    trozos = sms_utils.segments(limpio)
    return {"chars": len(limpio), "segments": trozos,
            "limit": (160 if sms_utils.is_gsm7(limpio) else 70),
            "gsm7": sms_utils.is_gsm7(limpio),
            "files_link": bool(files),
            "text": limpio}


def _campaign_email_html(session_db, camp, *, files_url: str = "") -> str:
    """El correo del envío. Es el MISMO HTML que se enseña en la previsualización y el que sale."""
    marca = _campaign_brand(session_db, camp)
    # ⚠️ Este correo SALE DE CASA, así que si quien lo manda todavía no tiene logo se cae al de la
    # casa (en las pantallas de dentro se enseña el icono de empresa, pero aquí hay que enseñar una
    # marca).
    logo_url = _absolute_media_url(marca["logo_url"]) or \
        _external_url_for("static", filename="img/logo_33_producciones.png")
    logo_html = (
        '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" '
        'style="border-collapse:collapse;"><tr><td align="right">'
        f'<img src="{html.escape(logo_url)}" '
        f'alt="{html.escape(marca["name"] or "33 Producciones")}" '
        'style="display:inline-block;max-width:180px;max-height:64px;object-fit:contain;">'
        '</td></tr></table>')
    titulo_html = ""
    if (camp.title or "").strip():
        titulo_html = ('<div style="margin-top:14px;font-size:28px;line-height:1.2;font-weight:700;'
                       f'color:#111827;text-align:center;">{html.escape(camp.title.strip())}</div>')
    cuerpo_html = ""
    for parrafo in re.split(r"\n\s*\n", (camp.body or "").strip()):
        if not parrafo.strip():
            continue
        cuerpo_html += ('<p style="margin:0 0 14px;font-size:15px;line-height:1.75;color:#111827;">'
                        + html.escape(parrafo.strip()).replace("\n", "<br/>") + "</p>")
    boton_html = ""
    if (camp.button_label or "").strip() and (camp.button_url or "").strip():
        boton_html = (
            '<div style="text-align:right;margin:18px 0 0;">'
            f'<a href="{html.escape(camp.button_url.strip())}" '
            'style="display:inline-block;padding:12px 22px;border-radius:999px;background:#E33D48;'
            'color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">'
            f'{html.escape(camp.button_label.strip())}</a></div>')
    adjuntos_html = ""
    ficheros = camp.files_json or []
    if ficheros:
        piezas = []
        for f in ficheros:
            url = html.escape(_absolute_media_url(f.get("url") or ""))
            nombre = html.escape(f.get("name") or "Adjunto")
            if f.get("image"):
                piezas.append(f'<div style="margin:0 0 12px;"><img src="{url}" alt="{nombre}" '
                              'style="display:block;max-width:100%;border-radius:14px;'
                              'border:1px solid #e5e7eb;"></div>')
            else:
                piezas.append(
                    f'<div style="margin:0 0 10px;"><a href="{url}" '
                    'style="display:inline-block;padding:10px 16px;border-radius:12px;'
                    'background:#f3f4f6;border:1px solid #e5e7eb;color:#111827;font-size:14px;'
                    f'text-decoration:none;">&#128206; {nombre}</a></div>')
        adjuntos_html = ('<div style="margin-top:22px;padding-top:18px;border-top:1px solid #e5e7eb;">'
                         + "".join(piezas) + "</div>")
    return f'''
    <div style="margin:0;padding:24px;background:#f5f7fb;font-family:Arial,Helvetica,sans-serif;color:#111827;">
      <div style="max-width:760px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:20px;overflow:hidden;">
        <div style="padding:24px 30px 8px;">
          {logo_html}
          {titulo_html}
        </div>
        <div style="padding:18px 30px 28px;">
          {cuerpo_html}
          {boton_html}
          {adjuntos_html}
        </div>
      </div>
    </div>'''


def _buyer_source_cycle(session_db, source: dict | None):
    """El CICLO o FESTIVAL propio del que es la actividad de este listado (o None).

    Si la base de compradores es de un ciclo, lo normal es que el envío salga **en nombre del
    ciclo** y no en el de la empresa que lo promueve: es el nombre que la gente reconoce."""
    if not source or not source.get("concert_id"):
        return None
    try:
        c = session_db.get(Concert, to_uuid(source["concert_id"]))
    except Exception:
        return None
    if c is None or not getattr(c, "cycle_festival_id", None):
        return None
    return session_db.get(CycleFestival, c.cycle_festival_id)


def _campaign_brand(session_db, camp) -> dict:
    """EN NOMBRE DE QUIÉN sale el envío: el logo del correo, el nombre y el remitente del SMS.

    Punto único de las dos cosas (el correo y el SMS), para que no puedan decir cosas distintas.
    `sender_kind`: COMPANY (la empresa del grupo que promueve) o CYCLE (el ciclo o festival propio).
    """
    company = session_db.get(GroupCompany, camp.company_id) if camp.company_id else None
    cycle = session_db.get(CycleFestival, camp.cycle_id) if camp.cycle_id else None
    es_ciclo = (camp.sender_kind or "COMPANY").upper() == "CYCLE" and cycle is not None
    if es_ciclo:
        nombre = (cycle.name or "").strip()
        # Si el ciclo no tiene logo se cae al de la empresa que lo promueve antes que al de la casa.
        logo = ((cycle.logo_url or "").strip()
                or (getattr(company, "logo_url", "") or "").strip())
        remitente = (cycle.sms_sender or "").strip()
    else:
        nombre = (getattr(company, "name", "") or "").strip()
        logo = (getattr(company, "logo_url", "") or "").strip()
        remitente = (getattr(company, "sms_sender", "") or "").strip()
    return {"kind": ("CYCLE" if es_ciclo else "COMPANY"), "name": nombre, "logo_url": logo,
            "sms_sender": remitente, "company": company, "cycle": cycle}


def _campaign_sms_sender(session_db, camp) -> str:
    """El remitente del SMS: el nombre abreviado de quien manda el envío (la empresa del grupo que
    promueve o el ciclo, según lo que se haya marcado).

    Si no lo tiene puesto se usa el general de Integraciones → SMS (y si tampoco hay, sale el número
    de la pasarela: en España un remitente con letras hay que registrarlo)."""
    if (camp.sms_sender or "").strip():
        return camp.sms_sender.strip()
    remitente = (_campaign_brand(session_db, camp).get("sms_sender") or "").strip()
    if remitente:
        return remitente
    acc = _sms_account(session_db)
    return (getattr(acc, "sender", "") or "").strip()


def _campaign_build_recipients(session_db, camp, source: dict, filtros: dict) -> int:
    """Crea los destinatarios de la campaña a partir de los filtros. Devuelve cuántos son.

    Es el MISMO filtrado que la pantalla (`_buyers_apply_filters`), con lo que el canal exige (un
    SMS necesita teléfono y un correo necesita email), así que el total que se ve antes de mandar es
    exactamente a quién se le manda."""
    q = _buyers_apply_filters(_buyers_base_query(session_db, source), filtros,
                              channel=camp.channel)
    vistos, filas = set(), []
    for be, b in q.all():
        destino = (b.email or "") if camp.channel == "EMAIL" else (b.phone or "")
        destino = destino.strip()
        if not destino or destino.lower() in vistos:
            continue
        vistos.add(destino.lower())
        filas.append(BuyerCampaignRecipient(campaign_id=camp.id, buyer_id=b.id,
                                            name=(b.name or ""), target=destino))
    for fila in filas:
        session_db.add(fila)
    camp.total = len(filas)
    session_db.flush()
    return len(filas)


def _campaign_send_pending(session_db, camp) -> dict:
    """Manda la campaña a los que quedan, durante ~45 s. Devuelve lo hecho y lo que queda.

    ⚠️ Cada envío se guarda AL MOMENTO: si el servidor corta la petición, lo mandado está mandado y
    al volver a pulsar salen solo los que faltan (nadie recibe dos veces)."""
    pendientes = (session_db.query(BuyerCampaignRecipient)
                  .filter(BuyerCampaignRecipient.campaign_id == camp.id,
                          BuyerCampaignRecipient.status == "PENDIENTE")
                  .order_by(BuyerCampaignRecipient.id.asc()).all())
    if not pendientes:
        camp.status = "SENT"
        camp.sent_at = camp.sent_at or datetime.now(TZ_MADRID)
        session_db.commit()
        return {"enviados": 0, "fallos": 0, "quedan": 0, "terminado": True}
    camp.status = "SENDING"
    files_url = _campaign_files_url(session_db, camp)
    enviados, fallos = 0, 0
    tope_alcanzado = False
    hoy, tope = 0, 0
    if camp.channel == "EMAIL":
        cuerpo_html = _campaign_email_html(session_db, camp, files_url=files_url)
        asunto = (camp.subject or camp.title or "").strip() or "Información importante"
    else:
        texto = _campaign_sms_text(session_db, camp, files_url=files_url)
        remitente = _campaign_sms_sender(session_db, camp)
        # ⚠️ El TOPE DIARIO de SMS se respeta (es la red de seguridad del saldo), pero no se puede
        # marcar a nadie como «no le llegó» por eso: se para y se dice cuántos quedan.
        acc = _sms_account(session_db)
        tope = int(getattr(acc, "daily_cap", 0) or 0)
        hoy = _sms_sent_today(session_db) if tope > 0 else 0
    t0 = time.monotonic()
    for r in pendientes:
        if time.monotonic() - t0 > CAMPAIGN_BUDGET_SECONDS:
            break
        if camp.channel == "SMS" and tope > 0 and hoy >= tope:
            tope_alcanzado = True
            break
        try:
            if camp.channel == "EMAIL":
                # ⚠️ Los adjuntos van como IMÁGENES y ENLACES dentro del correo, no como
                # ficheros pegados: mandar el mismo PDF a miles de direcciones es la forma más
                # rápida de acabar en spam (y de que el envío tarde una eternidad).
                ok, error = _send_optional_email([r.target], asunto, cuerpo_html)
            else:
                # `max_segments=0` = no se recorta: los trozos de más ya se han avisado y aceptado.
                ok, error = _send_optional_sms(session_db, r.target, texto, kind="CAMPAIGN",
                                               sender=remitente, max_segments=0, force=True)
                hoy += 1
        except Exception as exc:
            ok, error = False, str(exc)
            app.logger.exception("[envios] fallo inesperado mandando a %s", (r.target or "")[:80])
        if ok:
            r.status, r.error, r.sent_at = "ENVIADO", None, datetime.now(TZ_MADRID)
            enviados += 1
        else:
            r.status, r.error = "ERROR", (error or "no se pudo enviar")[:400]
            fallos += 1
        session_db.commit()
    camp.sent_ok = int(camp.sent_ok or 0) + enviados
    camp.sent_fail = int(camp.sent_fail or 0) + fallos
    quedan = (session_db.query(func.count(BuyerCampaignRecipient.id))
              .filter(BuyerCampaignRecipient.campaign_id == camp.id,
                      BuyerCampaignRecipient.status == "PENDIENTE").scalar() or 0)
    if not quedan:
        camp.status = "SENT"
        camp.sent_at = camp.sent_at or datetime.now(TZ_MADRID)
    if tope_alcanzado:
        camp.last_error = ("Se ha llegado al tope de %d SMS al día (Integraciones → SMS): quedan %d "
                           "por mandar." % (tope, int(quedan)))
    session_db.commit()
    return {"enviados": enviados, "fallos": fallos, "quedan": int(quedan),
            "terminado": not quedan, "tope": tope_alcanzado,
            "aviso": (camp.last_error or "") if tope_alcanzado else ""}


# Envíos que ya están mandándose en ESTE proceso (para no ponerse a mandar dos veces lo mismo).
_CAMPAIGN_BG_ACTIVE: set = set()
_CAMPAIGN_BG_GUARD = threading.Lock()


def _campaign_send_bg(campaign_pk: str) -> None:
    """Sigue mandando la campaña en un HILO hasta que no queden.

    ⚠️ Con dos mil destinatarios, mandar «por tandas de 45 s» a base de clics sería inaceptable: la
    primera tanda va en la petición (para que se vean al momento los errores de verdad) y el resto
    en segundo plano. Es seguro porque cada destinatario queda marcado en cuanto se le manda: si el
    hilo muere (un despliegue, por ejemplo), se sigue con el botón «Seguir enviando» y nadie recibe
    dos veces."""
    clave = str(campaign_pk)
    with _CAMPAIGN_BG_GUARD:
        if clave in _CAMPAIGN_BG_ACTIVE:
            return
        _CAMPAIGN_BG_ACTIVE.add(clave)
    try:
        for _ronda in range(400):                     # tope de seguridad (400 × 45 s)
            s = db()
            try:
                camp = s.get(BuyerCampaign, to_uuid(campaign_pk))
                if camp is None:
                    return
                datos = _campaign_send_pending(s, camp)
            except Exception:
                app.logger.exception("[envios] fallo mandando en segundo plano")
                return
            finally:
                s.close()
            if datos.get("terminado") or datos.get("tope"):
                return
    finally:
        with _CAMPAIGN_BG_GUARD:
            _CAMPAIGN_BG_ACTIVE.discard(clave)


def _campaign_send_bg_start(campaign_pk: str) -> None:
    threading.Thread(target=_campaign_send_bg, args=(str(campaign_pk),), daemon=True).start()


def _campaign_status(session_db, camp) -> dict:
    """Cómo va un envío (lo que consulta la pantalla mientras se manda)."""
    filas = dict(session_db.query(BuyerCampaignRecipient.status,
                                  func.count(BuyerCampaignRecipient.id))
                 .filter(BuyerCampaignRecipient.campaign_id == camp.id)
                 .group_by(BuyerCampaignRecipient.status).all())
    quedan = int(filas.get("PENDIENTE", 0) or 0)
    return {"ok": True, "campaign_id": str(camp.id), "total": int(camp.total or 0),
            "enviados": int(filas.get("ENVIADO", 0) or 0),
            "fallos": int(filas.get("ERROR", 0) or 0),
            "quedan": quedan, "terminado": not quedan,
            "enviando": str(camp.id) in _CAMPAIGN_BG_ACTIVE,
            "aviso": (camp.last_error or "")}


@app.get("/compradores/envio/<cid>/estado", endpoint="buyers_campaign_status")
@admin_required
def buyers_campaign_status(cid):
    """Cómo va el envío (la pantalla lo pregunta mientras se manda en segundo plano)."""
    s = db()
    try:
        camp = s.get(BuyerCampaign, to_uuid(cid))
        if camp is None:
            return jsonify({"ok": False, "error": "Ese envío ya no existe."}), 404
        return jsonify(_campaign_status(s, camp))
    finally:
        s.close()


def _campaign_sender_from_payload(session_db, source: dict, datos: dict):
    """En nombre de quién sale el envío, tal como lo manda la pantalla: (company_id, cycle_id, kind).

    ⚠️ El CICLO se comprueba contra el de la actividad del listado, no se acepta a ciegas: el
    formulario no puede firmar un envío en nombre de un ciclo que no es el suyo."""
    company_id = None
    if (datos.get("company_id") or "").strip():
        try:
            company_id = to_uuid(datos["company_id"].strip())
        except Exception:
            company_id = None
    kind = (datos.get("sender_kind") or "COMPANY").strip().upper()
    ciclo = _buyer_source_cycle(session_db, source)
    if company_id is None:
        # Sin empresa dicha: la que ORGANIZA el ciclo si lo hay, y si no la que promueve la
        # actividad (es el respaldo del logo cuando el ciclo no tiene el suyo).
        if kind == "CYCLE" and ciclo is not None and ciclo.managing_company_id:
            company_id = ciclo.managing_company_id
        else:
            company_id = getattr(_buyer_source_company(session_db, source), "id", None)
    if kind != "CYCLE" or ciclo is None:
        return company_id, (ciclo.id if ciclo is not None else None), "COMPANY"
    return company_id, ciclo.id, "CYCLE"


@app.post("/compradores/envio/remitente", endpoint="buyers_campaign_sender_save")
@admin_required
def buyers_campaign_sender_save():
    """Guarda el NOMBRE ABREVIADO PARA SMS de quien va a mandar el envío (la empresa del grupo o el
    ciclo), sin salir del pop-up. Se valida con el mismo límite que el remitente general."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso."}), 403
    datos = request.get_json(silent=True) or {}
    kind = (datos.get("kind") or "").strip().upper()
    remitente = (datos.get("sender") or "").strip()
    valido, motivo = sms_utils.sender_is_valid(remitente)
    if not valido:
        return jsonify({"ok": False, "error": motivo}), 400
    s = db()
    try:
        try:
            pk = to_uuid((datos.get("id") or "").strip())
        except Exception:
            return jsonify({"ok": False, "error": "Falta a quién se le pone."}), 400
        fila = s.get(CycleFestival, pk) if kind == "CYCLE" else s.get(GroupCompany, pk)
        if fila is None:
            return jsonify({"ok": False, "error": "Eso ya no existe."}), 404
        fila.sms_sender = remitente
        s.commit()
        return jsonify({"ok": True, "sender": remitente,
                        "name": (getattr(fila, "name", "") or "")})
    except Exception as exc:
        s.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        s.close()


def _campaign_source_from_payload(session_db, datos: dict):
    return _buyer_source(session_db, event_pk=(datos.get("event") or ""),
                         list_pk=(datos.get("lista") or ""))


def _campaign_filters_from_payload(datos: dict) -> dict:
    """Los filtros que manda el pop-up de envío (mismo formato que los de la pantalla)."""
    if (datos.get("todos") or "") in ("1", True, "true"):
        return {"q": "", "cat": [], "flags": [], "orden": "entradas"}
    return {"q": (datos.get("q") or "").strip(),
            "cat": [c for c in (datos.get("cat") or []) if (c or "").strip()],
            "flags": [k for k, _l, _i in BUYER_FILTER_DEFS if k in (datos.get("flags") or [])],
            "orden": "entradas"}


@app.post("/compradores/envio/adjuntar", endpoint="buyers_campaign_attach")
@admin_required
def buyers_campaign_attach():
    """Sube un adjunto de un envío y devuelve su enlace (imagen o documento)."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para mandar envíos."}), 403
    fichero = request.files.get("file")
    if not fichero or not (fichero.filename or "").strip():
        return jsonify({"ok": False, "error": "No ha llegado ningún archivo."}), 400
    try:
        url = upload_file(fichero, CAMPAIGN_FILE_FOLDER)
    except Exception as exc:
        app.logger.exception("[envios] no se pudo subir el adjunto")
        return jsonify({"ok": False, "error": "No se pudo subir: %s" % exc}), 400
    if not url:
        return jsonify({"ok": False, "error": "No se pudo subir el archivo."}), 400
    nombre = (fichero.filename or "adjunto").strip()
    return jsonify({"ok": True, "file": {
        "url": url, "name": nombre, "mimetype": (fichero.mimetype or ""),
        "image": _campaign_file_is_image(nombre, fichero.mimetype or ""),
    }})


@app.post("/compradores/envio/previsualizar", endpoint="buyers_campaign_preview")
@admin_required
def buyers_campaign_preview():
    """Cuántos envíos van a salir y cómo queda el mensaje (el MISMO HTML que se manda)."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para mandar envíos."}), 403
    datos = request.get_json(silent=True) or {}
    canal = (datos.get("channel") or "EMAIL").strip().upper()
    if canal not in ("EMAIL", "SMS"):
        return jsonify({"ok": False, "error": "Canal desconocido."}), 400
    s = db()
    try:
        source = _campaign_source_from_payload(s, datos)
        if source is None:
            return jsonify({"ok": False, "error": "Falta el listado de compradores."}), 400
        filtros = _campaign_filters_from_payload(datos)
        q = _buyers_apply_filters(_buyers_base_query(s, source), filtros, channel=canal)
        total = q.with_entities(func.count(BuyerEvent.id)).scalar() or 0
        # Los que se quedan fuera por no tener el dato de ese canal (se dice, no se esconde).
        sin_dato = ((_buyers_apply_filters(_buyers_base_query(s, source), filtros)
                     .with_entities(func.count(BuyerEvent.id)).scalar() or 0) - total)
        ficheros = _campaign_files_clean(datos.get("files"))
        company_id, cycle_id, sender_kind = _campaign_sender_from_payload(s, source, datos)
        # Campaña de PEGA (no se guarda): solo para componer con el mismo código que el envío.
        borrador = BuyerCampaign(
            channel=canal, company_id=company_id, cycle_id=cycle_id, sender_kind=sender_kind,
            subject=(datos.get("subject") or "").strip(),
            title=(datos.get("title") or "").strip(),
            body=(datos.get("body") or ""),
            button_label=(datos.get("button_label") or "").strip(),
            button_url=(datos.get("button_url") or "").strip(),
            link_url=(datos.get("link_url") or "").strip(),
            files_json=ficheros)
        salida = {"ok": True, "total": int(total), "sin_dato": max(0, int(sin_dato))}
        marca = _campaign_brand(s, borrador)
        salida["sender_kind"] = marca["kind"]
        salida["sender_name"] = marca["name"]
        salida["sender_short"] = marca["sms_sender"]
        if canal == "EMAIL":
            salida["html"] = _campaign_email_html(s, borrador)
            salida["subject"] = (borrador.subject or borrador.title or "").strip()
        else:
            sms = _campaign_sms_preview(s, borrador.body, borrador.link_url, ficheros)
            salida.update(sms)
            salida["sender"] = _campaign_sms_sender(s, borrador)
            salida["sms_ready"] = _sms_available()
        return jsonify(salida)
    finally:
        s.close()


@app.get("/compradores/envio/contactos", endpoint="buyers_campaign_contacts")
@admin_required
def buyers_campaign_contacts():
    """A quién mandar la PRUEBA: busca en TODA la base —terceros, personal de la oficina y artistas—
    y devuelve **con qué se le puede contactar** (correo y teléfono), que es lo que hace falta aquí.

    Un artista no tiene correo propio, así que se abre en las personas que reciben sus avisos y en
    sus integrantes: es a quien de verdad se le puede mandar."""
    q = (request.args.get("q") or "").strip()
    canal = (request.args.get("channel") or "EMAIL").strip().upper()
    if len(q) < 2:
        return jsonify({"ok": True, "rows": []})
    s = db()
    try:
        filas, vistos = [], set()

        def añade(kind, kind_label, nombre, email, telefono, foto="", extra=""):
            email = (email or "").strip().lower()
            telefono = _normalize_phone_value(telefono) or ""
            if not email and not telefono:
                return
            clave = (email or "") + "|" + (telefono or "")
            if clave in vistos:
                return
            vistos.add(clave)
            filas.append({"kind": kind, "kind_label": kind_label, "name": (nombre or "—"),
                          "email": email, "phone": telefono, "photo_url": foto, "extra": extra})

        # TERCEROS (con el mismo criterio de búsqueda que el resto de la app).
        consulta = s.query(Promoter)
        clausula = _promoter_search_clause(s, q)
        if clausula is not None:
            consulta = consulta.filter(clausula)
        for p in consulta.order_by(Promoter.nick.asc()).limit(12).all():
            añade("promoter", "Tercero", _promoter_display_name(p) or (p.nick or "—"),
                  p.contact_email, p.contact_phone, (p.logo_url or ""))
        # PERSONAL de la oficina (sin bloqueados ni eliminados).
        fuera = _inactive_user_ids(s)
        for u, prof in (s.query(User, UserProfile)
                        .outerjoin(UserProfile, UserProfile.user_id == User.id)
                        .filter(or_(_sa_contains_text(UserProfile.nick, q),
                                    _sa_contains_text(UserProfile.first_name, q),
                                    _sa_contains_text(UserProfile.last_name, q),
                                    _sa_contains_text(User.email, q)))
                        .order_by(func.lower(func.coalesce(UserProfile.nick, User.email)).asc())
                        .limit(12).all()):
            if u.id in fuera:
                continue
            añade("user", "Personal", ((getattr(prof, "nick", None) or u.email or "—").strip()),
                  u.email, _user_sms_phone(s, u.id), (getattr(prof, "photo_url", "") or ""))
        # ARTISTAS: sus contactos de avisos y sus integrantes (el artista en sí no tiene correo).
        for a in (s.query(Artist).filter(Artist.event_id.is_(None))
                  .filter(_sa_contains_text(Artist.name, q))
                  .order_by(Artist.name.asc()).limit(6).all()):
            for c in (s.query(ArtistNotificationContact)
                      .filter(ArtistNotificationContact.artist_id == a.id).all()):
                nombre = (getattr(c, "name", "") or "").strip()
                correo = (getattr(c, "email", "") or "")
                tel = (getattr(c, "phone", "") or "")
                tercero = (s.get(Promoter, c.promoter_id) if getattr(c, "promoter_id", None) else None)
                if tercero is not None:
                    nombre = nombre or (_promoter_display_name(tercero) or tercero.nick or "")
                    correo = correo or (tercero.contact_email or "")
                    tel = tel or (tercero.contact_phone or "")
                añade("artist", "Artista", nombre or a.name, correo, tel,
                      (a.photo_url or ""), extra=a.name)
            for per in (s.query(ArtistPerson)
                        .filter(ArtistPerson.artist_id == a.id).all()):
                tercero = (s.get(Promoter, per.promoter_id) if getattr(per, "promoter_id", None) else None)
                if tercero is None:
                    continue
                añade("artist", "Artista", _artist_person_full_name(per) or tercero.nick or a.name,
                      tercero.contact_email, tercero.contact_phone,
                      (getattr(tercero, "logo_url", "") or (a.photo_url or "")), extra=a.name)
        # Para el canal que toca, primero los que se pueden usar.
        clave_canal = "email" if canal == "EMAIL" else "phone"
        filas.sort(key=lambda r: (not bool(r.get(clave_canal)),))
        return jsonify({"ok": True, "rows": filas[:30]})
    finally:
        s.close()


@app.post("/compradores/envio/prueba", endpoint="buyers_campaign_test")
@admin_required
def buyers_campaign_test():
    """Manda una PRUEBA del envío a los correos o teléfonos que se digan.

    ⚠️ No toca la campaña de verdad: no crea destinatarios ni marca a nadie. Se guarda como envío de
    **PRUEBA** (`status='PRUEBA'`) porque hace falta una fila para la página de los adjuntos… y
    porque un envío que sale de la casa no puede ser invisible."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para mandar envíos."}), 403
    datos = request.get_json(silent=True) or {}
    canal = (datos.get("channel") or "EMAIL").strip().upper()
    destinos = [str(x or "").strip() for x in (datos.get("targets") or []) if str(x or "").strip()]
    if not destinos:
        return jsonify({"ok": False, "error": "Dime a quién le mando la prueba."}), 400
    if not (datos.get("body") or "").strip():
        return jsonify({"ok": False, "error": "Escribe el mensaje antes de probarlo."}), 400
    if canal == "SMS" and not _sms_available():
        return jsonify({"ok": False, "error": ("La pasarela de SMS está sin configurar o apagada "
                                               "(Integraciones → SMS).")}), 400
    s = db()
    try:
        source = _campaign_source_from_payload(s, datos)
        if source is None:
            return jsonify({"ok": False, "error": "Falta el listado de compradores."}), 400
        estado = _current_user_state() or {}
        company_id, cycle_id, sender_kind = _campaign_sender_from_payload(s, source, datos)
        camp = BuyerCampaign(
            channel=canal,
            event_id=(to_uuid(source["pk"]) if source["kind"] == "ET" else None),
            list_id=(to_uuid(source["pk"]) if source["kind"] == "MANUAL" else None),
            company_id=company_id, cycle_id=cycle_id, sender_kind=sender_kind,
            subject=(datos.get("subject") or "").strip()[:300],
            title=(datos.get("title") or "").strip()[:300],
            body=(datos.get("body") or ""),
            button_label=(datos.get("button_label") or "").strip()[:80],
            button_url=(datos.get("button_url") or "").strip()[:900],
            link_url=(datos.get("link_url") or "").strip()[:900],
            files_json=_campaign_files_clean(datos.get("files")),
            created_by_user_id=_safe_uuid(estado.get("user_id")),
            created_by_nick=(estado.get("nick") or ""),
            status="PRUEBA")
        s.add(camp)
        s.flush()
        files_url = _campaign_files_url(s, camp)
        ok_n, fallos = 0, []
        if canal == "EMAIL":
            cuerpo = _campaign_email_html(s, camp, files_url=files_url)
            asunto = "[PRUEBA] " + ((camp.subject or camp.title or "").strip() or "Envío de prueba")
            for destino in destinos[:20]:
                if "@" not in destino:
                    fallos.append("%s: no es un correo" % destino)
                    continue
                ok, error = _send_optional_email([destino], asunto, cuerpo)
                if ok:
                    ok_n += 1
                else:
                    fallos.append("%s: %s" % (destino, error or "no salió"))
        else:
            texto = _campaign_sms_text(s, camp, files_url=files_url)
            remitente = _campaign_sms_sender(s, camp)
            for destino in destinos[:20]:
                numero = _normalize_phone_value(destino)
                if not numero or not numero.startswith("+"):
                    fallos.append("%s: no es un teléfono" % destino)
                    continue
                ok, error = _send_optional_sms(s, numero, texto, kind="CAMPAIGN_TEST",
                                               sender=remitente, max_segments=0, force=True)
                if ok:
                    ok_n += 1
                else:
                    fallos.append("%s: %s" % (numero, error or "no salió"))
        camp.sent_ok, camp.sent_fail = ok_n, len(fallos)
        camp.sent_at = datetime.now(TZ_MADRID)
        if fallos:
            camp.last_error = "; ".join(fallos)[:500]
        s.commit()
        return jsonify({"ok": True, "enviados": ok_n, "fallos": len(fallos),
                        "errores": fallos[:10]})
    except Exception as exc:
        s.rollback()
        app.logger.exception("[envios] la prueba ha fallado")
        return jsonify({"ok": False, "error": "No se pudo mandar la prueba: %s" % exc}), 500
    finally:
        s.close()


@app.post("/compradores/envio/enviar", endpoint="buyers_campaign_send")
@admin_required
def buyers_campaign_send():
    """Crea el envío con sus destinatarios y manda la primera tanda."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para mandar envíos."}), 403
    datos = request.get_json(silent=True) or {}
    canal = (datos.get("channel") or "EMAIL").strip().upper()
    if canal not in ("EMAIL", "SMS"):
        return jsonify({"ok": False, "error": "Canal desconocido."}), 400
    cuerpo = (datos.get("body") or "").strip()
    if not cuerpo:
        return jsonify({"ok": False, "error": "Escribe el mensaje."}), 400
    if canal == "EMAIL" and not (datos.get("subject") or "").strip():
        return jsonify({"ok": False, "error": "Pon el asunto del correo."}), 400
    if canal == "SMS" and not _sms_available():
        return jsonify({"ok": False,
                        "error": ("La pasarela de SMS está sin configurar o apagada "
                                  "(Integraciones → SMS).")}), 400
    s = db()
    try:
        source = _campaign_source_from_payload(s, datos)
        if source is None:
            return jsonify({"ok": False, "error": "Falta el listado de compradores."}), 400
        filtros = _campaign_filters_from_payload(datos)
        estado = _current_user_state() or {}
        company_id, cycle_id, sender_kind = _campaign_sender_from_payload(s, source, datos)
        camp = BuyerCampaign(
            channel=canal,
            event_id=(to_uuid(source["pk"]) if source["kind"] == "ET" else None),
            list_id=(to_uuid(source["pk"]) if source["kind"] == "MANUAL" else None),
            company_id=company_id, cycle_id=cycle_id, sender_kind=sender_kind,
            subject=(datos.get("subject") or "").strip()[:300],
            title=(datos.get("title") or "").strip()[:300],
            body=cuerpo,
            button_label=(datos.get("button_label") or "").strip()[:80],
            button_url=(datos.get("button_url") or "").strip()[:900],
            link_url=(datos.get("link_url") or "").strip()[:900],
            files_json=_campaign_files_clean(datos.get("files")),
            filters_json=filtros,
            created_by_user_id=_safe_uuid(estado.get("user_id")),
            created_by_nick=(estado.get("nick") or ""),
            status="DRAFT")
        if canal == "SMS":
            camp.sms_sender = _campaign_sms_sender(s, camp)[:11] or None
        s.add(camp)
        s.flush()
        total = _campaign_build_recipients(s, camp, source, filtros)
        if not total:
            s.rollback()
            return jsonify({"ok": False, "error": (
                "No hay nadie a quien mandarlo: de los compradores elegidos, ninguno tiene %s."
                % ("email" if canal == "EMAIL" else "teléfono"))}), 400
        if canal == "SMS":
            files_url = _campaign_files_url(s, camp)
            camp.segments = sms_utils.segments(_campaign_sms_text(s, camp, files_url=files_url))
        s.commit()
        resultado = _campaign_send_pending(s, camp)
        if resultado.get("quedan") and not resultado.get("tope"):
            _campaign_send_bg_start(str(camp.id))
            resultado["enviando"] = True
        resultado.update({"ok": True, "campaign_id": str(camp.id), "total": total})
        return jsonify(resultado)
    except Exception as exc:
        s.rollback()
        app.logger.exception("[envios] no se pudo mandar el envío a compradores")
        return jsonify({"ok": False, "error": "No se pudo mandar: %s" % exc}), 500
    finally:
        s.close()


@app.post("/compradores/envio/<cid>/continuar", endpoint="buyers_campaign_continue")
@admin_required
def buyers_campaign_continue(cid):
    """Sigue mandando los que quedaron (el servidor corta la petición a los ~45 s)."""
    if not can_edit_buyers():
        return jsonify({"ok": False, "error": "No tienes permiso para mandar envíos."}), 403
    s = db()
    try:
        camp = s.get(BuyerCampaign, to_uuid(cid))
        if camp is None:
            return jsonify({"ok": False, "error": "Ese envío ya no existe."}), 404
        resultado = _campaign_send_pending(s, camp)
        if resultado.get("quedan") and not resultado.get("tope"):
            _campaign_send_bg_start(str(camp.id))
            resultado["enviando"] = True
        resultado.update({"ok": True, "campaign_id": str(camp.id), "total": int(camp.total or 0)})
        return jsonify(resultado)
    except Exception as exc:
        s.rollback()
        return jsonify({"ok": False, "error": str(exc)}), 500
    finally:
        s.close()


@app.get("/envio/<token>", endpoint="public_campaign_files")
def public_campaign_files(token):
    """Página pública con los adjuntos de un envío: es lo que se manda por SMS, donde no se puede
    adjuntar nada. Solo enseña los archivos de ESE envío."""
    s = db()
    try:
        camp = (s.query(BuyerCampaign)
                .filter(BuyerCampaign.files_token == (token or "").strip()).first())
        if camp is None or not (camp.files_json or []):
            abort(404)
        company = s.get(GroupCompany, camp.company_id) if camp.company_id else None
        return render_template("public_campaign_files.html",
                               camp=camp, files=(camp.files_json or []), company=company,
                               og_image=_external_url_for("public_campaign_og_image", token=token))
    finally:
        s.close()


@app.get("/envio/<token>/imagen.jpg", endpoint="public_campaign_og_image")
def public_campaign_og_image(token):
    """La miniatura de la previsualización del enlace: la primera imagen adjunta y, si no hay, el
    logo de la empresa que lo manda."""
    s = db()
    try:
        camp = (s.query(BuyerCampaign)
                .filter(BuyerCampaign.files_token == (token or "").strip()).first())
        if camp is None:
            abort(404)
        origen = ""
        for f in (camp.files_json or []):
            if f.get("image") and (f.get("url") or ""):
                origen = f["url"]
                break
        if not origen and camp.company_id:
            company = s.get(GroupCompany, camp.company_id)
            origen = (getattr(company, "logo_url", "") or "")
        datos = _og_image_jpeg_bytes(origen)
        if not datos:
            abort(404)
        return Response(datos, mimetype="image/jpeg",
                        headers={"Cache-Control": "public, max-age=86400"})
    finally:
        s.close()


def _csv_guard(v) -> str:
    """Neutraliza inyección de fórmulas en CSV (los datos vienen de compradores externos):
    Excel ejecuta celdas que empiezan por = + - @ o tab; se prefijan con apóstrofo."""
    text_v = str(v or "")
    if text_v[:1] in ("=", "+", "-", "@", "\t", "\r"):
        return "'" + text_v
    return text_v


@app.get("/compradores/export.csv", endpoint="buyers_export_csv")
@admin_required
def buyers_export_csv():
    """Exporta a CSV **lo que se está viendo**: el listado (evento de ET o subido a mano) con sus
    filtros aplicados, o todos los compradores. Pensado para campañas y cruces externos."""
    filtros = _buyer_filters_from_request()
    s = db()
    try:
        source = _buyer_source(s, event_pk=(request.args.get("event") or "").strip(),
                               list_pk=(request.args.get("lista") or "").strip())
        out = io.StringIO()
        w = csv.writer(out, delimiter=";")
        w.writerow(["email", "nombre", "telefono", "entradas", "importe", "categorias",
                    "acepta_publicidad", "eventos"])
        fname = "compradores"
        if source:
            fname = "compradores_" + re.sub(r"[^\w\-]+", "_", (source.get("label") or "listado"))[:60]
            q = _buyers_apply_filters(_buyers_base_query(s, source), filtros)
            for be, b in _buyers_order(q, filtros["orden"]).all():
                w.writerow([_csv_guard(b.email), _csv_guard(b.name), _csv_guard(b.phone),
                            int(be.tickets_count or 0),
                            str(be.amount_total or 0).replace(".", ","),
                            _csv_guard(", ".join(be.categories or [])),
                            "si" if b.accepts_marketing else "no", int(b.events_count or 0)])
        else:
            for b in s.query(Buyer).order_by(Buyer.email.asc().nullslast()).all():
                w.writerow([_csv_guard(b.email), _csv_guard(b.name), _csv_guard(b.phone),
                            int(b.tickets_count or 0),
                            str(b.amount_total or 0).replace(".", ","), "",
                            "si" if b.accepts_marketing else "no", int(b.events_count or 0)])
        data = "\ufeff" + out.getvalue()  # BOM para que Excel abra bien los acentos
        resp = Response(data, mimetype="text/csv; charset=utf-8")
        resp.headers["Content-Disposition"] = f"attachment; filename={fname}.csv"
        return resp
    finally:
        s.close()


# Siembra de accesos/personal EN SEGUNDO PLANO, al FINAL del módulo (todas las rutas ya están
# registradas, así la introspección del catálogo es completa). Cerrojo de fichero = un solo
# ejecutor por contenedor; el resto de workers sirven peticiones de inmediato usando los caches
# en memoria (_ensure_access_caches) y el estado que ya hay en BD. Antes esta siembra corría en
# la PRIMERA PETICIÓN de cada worker (~10 s con la BD real): encolaba las peticiones y el escáner
# de puertos de Render acababa matando la instancia por probes lentas ("No open ports") -> web
# caída/en blanco aunque el código estaba bien.
def _bootstrap_personnel_bg():
    import tempfile
    lock_path = os.path.join(tempfile.gettempdir(), "app33_personnel_bootstrap.lock")
    try:
        os.close(os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY))
    except FileExistsError:
        return  # otro worker de este contenedor ya la está ejecutando
    except Exception:
        pass
    try:
        _ensure_access_caches()
        _bootstrap_access_and_personnel()
        app.logger.info("[accesos] siembra de accesos/personal completada en segundo plano")
    except Exception:
        app.logger.exception("[accesos] la siembra en segundo plano falló; la web sigue con el estado ya existente en BD (se aplicará en el próximo arranque)")


if not CALDAV_ONLY:  # el host «solo CalDAV» no siembra permisos/personal (no sirve el back office)
    threading.Thread(target=_bootstrap_personnel_bg, daemon=True).start()


# =====================================================================================
# FUSIÓN DE DUPLICADOS (bases de datos): dos elementos de la misma categoría (dos
# terceros, dos recintos…) se funden en uno. Se re-apuntan TODAS las referencias del
# perdedor al ganador —cualquier FK de cualquier tabla (descubiertas por metadatos) más
# las referencias polimórficas registradas (vinculaciones y plantillas de gastos)—, se
# aplican los campos elegidos y se elimina el perdedor: nada de lo que colgaba de un
# duplicado se pierde. Las rutas van bajo el prefijo de su sección para heredar sus
# permisos (leer = ver la sección; fusionar = POST, exige edición de la sección).
# Campos que NO se comparan al fusionar canciones: sellos de cuándo/quién y datos técnicos que no
# describen la canción (el token del enlace público, lo que apunta a Chartmetric). Comparar eso solo
# haría la tabla ilegible.
