def _merge_fields(model, cfg=None):
    """Columnas simples comparables del modelo (sin ids, FKs, JSON ni timestamps).

    `cfg['skip']` deja fuera además lo que no describe al elemento (sellos de cuándo/quién, tokens)."""
    fuera = set((cfg or {}).get("skip") or ())
    out = []
    for col in model.__table__.columns:
        if col.name in ("id", "created_at", "updated_at") or col.foreign_keys:
            continue
        if col.name in fuera:
            continue
        if "JSON" in col.type.__class__.__name__.upper():
            continue
        out.append(col.name)
    return out


def _merge_display(cfg, row):
    return (getattr(row, cfg["display"], None) or getattr(row, "name", None) or "—")


def _merge_fmt(v):
    if v is None or v == "":
        return ""
    if v is True:
        return "Sí"
    if v is False:
        return "No"
    return str(v)


def _merge_repoint_references(s, model, keep_id, drop_id):
    """Re-apunta al ganador TODAS las FKs (de cualquier tabla) que señalen al perdedor.
    Conflictos de unicidad (filas que quedarían duplicadas, p. ej. el mismo email vinculado
    a ambos) se resuelven fila a fila eliminando la del perdedor. Devuelve filas tocadas."""
    from sqlalchemy import select as _sel
    from sqlalchemy.exc import IntegrityError as _IE
    s.flush()
    target = model.__table__
    total = 0
    for tbl in target.metadata.sorted_tables:
        for col in list(tbl.columns):
            if not col.foreign_keys:
                continue
            if not any(fk.column.table is target and fk.column.name == "id" for fk in col.foreign_keys):
                continue
            try:
                with s.begin_nested():
                    res = s.execute(tbl.update().where(col == drop_id).values(**{col.name: keep_id}))
                total += res.rowcount or 0
            except _IE:
                pks = list(tbl.primary_key.columns)
                if not pks:
                    with s.begin_nested():
                        s.execute(tbl.delete().where(col == drop_id))
                    continue
                rows = s.execute(_sel(*pks).where(col == drop_id)).all()
                for row in rows:
                    cond = and_(*[pk == v for pk, v in zip(pks, row)])
                    try:
                        with s.begin_nested():
                            s.execute(tbl.update().where(cond).values(**{col.name: keep_id}))
                        total += 1
                    except _IE:
                        # La fila re-apuntada ya existe para el ganador: era un duplicado puro.
                        with s.begin_nested():
                            s.execute(tbl.delete().where(cond))
    return total


def _merge_repoint_polymorphic(s, cfg, keep_id, drop_id):
    """Referencias SIN FK: vinculaciones (third_party_links, por tipo) y plantillas de
    gastos por dueño (expense_templates.owner_type/owner_id para VENUE/EVENT)."""
    from sqlalchemy.exc import IntegrityError as _IE
    md = cfg["model"].__table__.metadata
    total = 0
    lts = cfg.get("link_types") or []
    if lts and "third_party_links" in md.tables:
        t = md.tables["third_party_links"]
        for type_col, id_col in ((t.c.source_type, t.c.source_id), (t.c.target_type, t.c.target_id)):
            with s.begin_nested():
                res = s.execute(t.update().where(type_col.in_(lts), id_col == drop_id).values(**{id_col.name: keep_id}))
            total += res.rowcount or 0
        # Auto-vinculaciones resultantes (el elemento consigo mismo): fuera.
        with s.begin_nested():
            s.execute(t.delete().where(t.c.source_type.in_(lts), t.c.target_type.in_(lts), t.c.source_id == t.c.target_id))
    owner = cfg.get("tpl_owner")
    if owner and "expense_templates" in md.tables:
        t2 = md.tables["expense_templates"]
        try:
            with s.begin_nested():
                res2 = s.execute(t2.update().where(t2.c.owner_type == owner, t2.c.owner_id == drop_id).values(owner_id=keep_id))
            total += res2.rowcount or 0
        except _IE:
            with s.begin_nested():
                s.execute(t2.delete().where(t2.c.owner_type == owner, t2.c.owner_id == drop_id))
    return total


def _merge_cfg_or_404(kind):
    cfg = MERGE_KINDS.get(kind)
    if not cfg:
        abort(404)
    return cfg


def _merge_search_view(kind):
    """Candidatos de la MISMA categoría para fusionar (búsqueda acento-insensible)."""
    cfg = _merge_cfg_or_404(kind)
    q = (request.args.get("q") or "").strip()
    exclude = _safe_uuid(request.args.get("exclude"))
    s = db()
    try:
        model = cfg["model"]
        query = s.query(model)
        if q:
            conds = []
            for attr in {cfg["display"], "name", "nick", "first_name", "last_name"}:
                if hasattr(model, attr):
                    conds.append(_sa_contains_text(getattr(model, attr), q))
            if conds:
                query = query.filter(or_(*conds))
        # ⚠️ El elemento de partida se excluye EN LA CONSULTA, no después: excluyéndolo al final se
        # gastaba uno de los 25 resultados y, con muchos homónimos, el duplicado que se busca podía
        # quedarse fuera del listado.
        if exclude:
            query = query.filter(model.id != exclude)
        rows = query.limit(25).all()
        out = []
        for r in rows:
            out.append({
                "id": str(r.id),
                "name": _merge_display(cfg, r),
                "photo": getattr(r, cfg["photo"], None) or "",
            })
        out.sort(key=lambda x: (x["name"] or "").lower())
        return jsonify(out[:20])
    finally:
        s.close()


def _song_projects_map(session_db, song_ids) -> dict:
    """Canción → PROYECTO discográfico que la tiene como lanzamiento (o como tema del videoclip).

    Punto único: lo usan el aviso de duplicados y la fusión, que tienen que decir lo mismo. Se
    resuelve en UNA consulta para todas las canciones."""
    ids = [x for x in {_safe_uuid(i) for i in (song_ids or [])} if x]
    if not ids:
        return {}
    out = {}
    try:
        filas = (session_db.query(DiscoProject)
                 .filter(or_(DiscoProject.release_song_id.in_(ids), DiscoProject.song_id.in_(ids)))
                 .all())
        for p in filas:
            for sid in (getattr(p, "release_song_id", None), getattr(p, "song_id", None)):
                if not sid or sid not in ids or str(sid) in out:
                    continue
                out[str(sid)] = {
                    "id": str(p.id),
                    "title": (p.title or "").strip() or "Proyecto",
                    "kind": (p.kind or ""),
                    "kind_label": DISCO_PROJECT_LABELS.get((p.kind or "").upper(), p.kind or ""),
                    "closed": bool(getattr(p, "closed_at", None)),
                    "url": _safe_url_for("disco_project_detail", project_id=str(p.id)),
                }
    except Exception:
        app.logger.exception("[canciones] no se pudieron leer los proyectos de las canciones")
    return out


def _song_duplicate_rows(session_db, title, artist_ids, exclude_song_id=None) -> list[dict]:
    """Canciones que YA existen con ESE título y de ALGUNO de esos artistas.

    Punto único del aviso de duplicados: lo usan el alta de una canción, el asistente de proyecto
    discográfico y sus dos comprobaciones en el servidor, así que los tres dicen lo mismo.
    ⚠️ Solo cuenta el MISMO ARTISTA: dos artistas distintos pueden tener una canción que se llame
    igual y eso no es un duplicado. El título se compara **sin acentos ni mayúsculas**
    (`_norm_text_key`), que es como lo escribe cada uno."""
    clave = _norm_text_key(title or "")
    ids = [x for x in {_safe_uuid(a) for a in (artist_ids or [])} if x]
    if not clave or not ids:
        return []
    fuera = _safe_uuid(exclude_song_id)
    try:
        filas = (session_db.query(Song, Artist)
                 .join(SongArtist, SongArtist.song_id == Song.id)
                 .join(Artist, Artist.id == SongArtist.artist_id)
                 .filter(SongArtist.artist_id.in_(ids))
                 .all())
    except Exception:
        app.logger.exception("[canciones] no se pudo buscar el duplicado de «%s»", title)
        return []
    vistas, out = set(), []
    for sg, art in filas:
        if fuera and sg.id == fuera:
            continue
        if _norm_text_key(sg.title or "") != clave or str(sg.id) in vistas:
            continue
        vistas.add(str(sg.id))
        out.append({
            "id": str(sg.id),
            "title": sg.title or "",
            "artist_id": str(art.id),
            "artist_name": (art.name or "").strip(),
            "artist_photo": (getattr(art, "photo_url", None) or ""),
            "cover_url": (sg.cover_url or ""),
            "is_provisional": bool(getattr(sg, "is_provisional", False)),
            "release_label": (sg.release_date.strftime("%d/%m/%Y") if sg.release_date else ""),
            "url": _safe_url_for("discografica_song_detail", song_id=str(sg.id)),
        })
    proyectos = _song_projects_map(session_db, [r["id"] for r in out])
    for r in out:
        r["project"] = proyectos.get(r["id"]) or None
    out.sort(key=lambda r: (r["release_label"] or ""), reverse=True)
    return out


def _song_duplicate_flash(dups, que: str = "canción") -> None:
    """El aviso de duplicado cuando salta en el SERVIDOR: se dice cuál es y dónde está, para poder
    trabajar sobre ella en vez de crear otra a ciegas."""
    if not dups:
        return
    partes = []
    for d in dups[:3]:
        txt = "«%s» (%s%s)" % (d["title"], d["artist_name"],
                               (" · " + d["release_label"]) if d["release_label"] else "")
        if d.get("url"):
            txt = '<a href="%s" class="alert-link">%s</a>' % (html.escape(d["url"]), html.escape(txt))
        else:
            txt = html.escape(txt)
        if d.get("project"):
            txt += " — la está preparando el proyecto «%s»" % html.escape(d["project"]["title"])
        partes.append(txt)
    flash(Markup(
        "Ya existe una %s con ese nombre de ese artista: %s. Ábrela para trabajar sobre ella, o "
        "vuelve a darle a crear marcando «crear otra de todas formas»." % (que, " · ".join(partes))
    ), "warning")


@app.get("/api/canciones/duplicadas", endpoint="api_song_duplicates")
@admin_required
def api_song_duplicates():
    """¿Ya hay una canción con ese nombre de ese artista? (aviso al crear una o un proyecto)."""
    session_db = db()
    try:
        artistas = request.args.getlist("artist_id") or ([request.args.get("artist_id")] if request.args.get("artist_id") else [])
        filas = _song_duplicate_rows(session_db, request.args.get("title") or "", artistas,
                                     exclude_song_id=request.args.get("exclude"))
        return jsonify({"rows": filas})
    except Exception:
        app.logger.exception("[canciones] fallo buscando duplicados")
        return jsonify({"rows": []})
    finally:
        session_db.close()


def _safe_url_for(endpoint, **kw) -> str:
    """`url_for` que no revienta fuera de una petición (crons e hilos) ni con un endpoint que no
    existe: devuelve cadena vacía. Mismo apaño que ya usan `_disco_pitch_url` y compañía."""
    try:
        return url_for(endpoint, **kw)
    except Exception:
        return ""


def _merge_notes(kind, session_db, a, b) -> list:
    """Avisos propios de esa categoría, para decirlos ANTES de fusionar."""
    if kind != "song":
        return []
    notas = []
    proyectos = _song_projects_map(session_db, [a.id, b.id])
    if proyectos:
        cuales = ", ".join(sorted({("«%s»" % p["title"]) for p in proyectos.values()}))
        notas.append("El PROYECTO discográfico %s se mantiene: pasa a la canción que se conserve y "
                     "sigue su curso hasta que se cierre." % cuales)
    return notas


def _merge_compare_view(kind):
    """Datos de los dos elementos, campo a campo, para elegir con cuál quedarse."""
    cfg = _merge_cfg_or_404(kind)
    s = db()
    try:
        model = cfg["model"]
        a = s.get(model, _safe_uuid(request.args.get("a")))
        b = s.get(model, _safe_uuid(request.args.get("b")))
        if not a or not b or a.id == b.id:
            abort(404)
        fields = []
        for f in _merge_fields(model, cfg):
            va = _merge_fmt(getattr(a, f, None))
            vb = _merge_fmt(getattr(b, f, None))
            if va == "" and vb == "":
                continue
            fields.append({"key": f, "label": _MERGE_FIELD_LABELS.get(f, f.replace("_", " ").capitalize()), "a": va, "b": vb})
        payload = lambda r: {"id": str(r.id), "name": _merge_display(cfg, r), "photo": getattr(r, cfg["photo"], None) or ""}
        return jsonify({"a": payload(a), "b": payload(b), "fields": fields,
                        "notes": _merge_notes(kind, s, a, b)})
    finally:
        s.close()


def _merge_execute_view(kind):
    cfg = _merge_cfg_or_404(kind)
    s = db()
    back = request.form.get("next") or request.referrer or ("/" + cfg["path"])
    try:
        model = cfg["model"]
        keep_id = _safe_uuid(request.form.get("keep_id"))
        drop_id = _safe_uuid(request.form.get("drop_id"))
        if not keep_id or not drop_id or keep_id == drop_id:
            raise ValueError("Elige dos elementos distintos para fusionar.")
        keep = s.get(model, keep_id)
        drop = s.get(model, drop_id)
        if not keep or not drop:
            abort(404)
        try:
            choices = json.loads(request.form.get("choices_json") or "{}")
        except Exception:
            choices = {}
        valid = set(_merge_fields(model, cfg))
        # Valores del PERDEDOR elegidos por el usuario: se capturan antes de borrarlo y se
        # aplican al ganador DESPUÉS (evita choques de unicidad, p. ej. name único).
        chosen_vals = {f: getattr(drop, f) for f, side in (choices or {}).items() if side == "drop" and f in valid}
        keep_name = _merge_display(cfg, keep)
        drop_name = _merge_display(cfg, drop)
        moved = _merge_repoint_references(s, model, keep.id, drop.id)
        moved += _merge_repoint_polymorphic(s, cfg, keep.id, drop.id)
        s.delete(drop)
        s.flush()
        for f, v in chosen_vals.items():
            setattr(keep, f, v)
        s.commit()
        flash(f"{cfg['label']} fusionado: «{drop_name}» se ha fundido en «{keep_name}» ({moved} referencia(s) re-apuntadas; no se pierde nada).", "success")
        return redirect(back)
    except Exception as exc:
        s.rollback()
        flash(str(exc) if isinstance(exc, ValueError) else f"No se pudo fusionar: {exc}", "danger")
        return redirect(back)
    finally:
        s.close()


# =============================================================================
# VACACIONES Y DÍAS LIBRES · del personal de la oficina
# =============================================================================
# Reglas de la casa (ago 2026):
#   · A cada persona le corresponden VACATION_DAYS_PER_YEAR (23) días HÁBILES
#     POR AÑO TRABAJADO. En el año de alta se PRORRATEAN desde la fecha de
#     comienzo del contrato (`UserContract.start_date`, pestaña «Contrato»).
#     ⚠️ El MÍNIMO LEGAL (art. 38 del Estatuto de los Trabajadores) son «treinta
#     días naturales», que en días de trabajo son unos 22 (30 naturales ≈ 21,7
#     laborables). La ley permite mejorarlo, y la casa da 23 HÁBILES: es lo que
#     hay que contar aquí, no 30. Si algún día cambia, se cambia este número (y
#     cada persona puede tener los suyos en su ficha).
#   · Se cuentan LABORABLES: un sábado, un domingo o un festivo de Madrid no
#     consume saldo. El día se guarda igual (así el calendario enseña el tramo
#     entero de principio a fin) pero con `counts=False`.
#   · Quien gestiona: DIRECCIÓN y quien tenga la responsabilidad de
#     administración «VACACIONES» (se reparte en la ficha de cada persona).
VACATION_DAYS_PER_YEAR = 23
VACATION_REGION = "Madrid"
VACATION_ACCESS_KEY = "vacaciones"
VACATION_RESPONSIBILITY = "VACACIONES"
VACATION_RULES_SETTING = "vacation_rules_text"
VACATION_RULES_DEFAULT = (
    "· Las vacaciones se piden con al menos 15 días de antelación.\n"
    "· Solo se pueden pedir los días que te queden de saldo: el contador te lo va diciendo.\n"
    "· Los sábados, domingos y festivos de Madrid NO consumen días: puedes marcarlos dentro de un "
    "tramo y no te restan nada.\n"
    "· Los días pedidos quedan a la espera del visto bueno de dirección; hasta entonces no están "
    "confirmados.\n"
    "· Procura no solaparte con compañeros de tu mismo departamento: al elegir se te avisa de quién "
    "ya tiene esos días."
)

# Los DOS tipos de petición. Comparten calendario, flujo y pantalla; lo único que cambia es de qué
# bolsa salen los días: un DÍA LIBRE no toca el saldo de vacaciones, lleva su propia cuenta.
VACATION_KINDS = {
    "VACACIONES": {"label": "Vacaciones", "singular": "día de vacaciones", "plural": "días de vacaciones",
                   "icon": "fa-umbrella-beach", "color": "#2e7d32", "needs_reason": False},
    "DIA_LIBRE": {"label": "Día libre", "singular": "día libre", "plural": "días libres",
                  "icon": "fa-mug-hot", "color": "#6A1B9A", "needs_reason": True},
}
VACATION_DEFAULT_KIND = "VACACIONES"


def _vacation_kind(value) -> str:
    """Normaliza el tipo de petición (lo que no se reconozca son vacaciones)."""
    k = (value or "").strip().upper()
    return k if k in VACATION_KINDS else VACATION_DEFAULT_KIND


VACATION_STATUS_META = {
    "PENDING":   {"label": "Pendiente de aprobar", "short": "Pendiente", "class": "text-bg-warning text-dark", "icon": "fa-hourglass-half"},
    "APPROVED":  {"label": "Aprobadas",  "short": "Aprobadas",  "class": "text-bg-success",   "icon": "fa-circle-check"},
    "REJECTED":  {"label": "Rechazadas", "short": "Rechazadas", "class": "text-bg-danger",    "icon": "fa-circle-xmark"},
    "CANCELLED": {"label": "Anuladas",   "short": "Anuladas",   "class": "text-bg-secondary", "icon": "fa-ban"},
}
# Estados que OCUPAN días (para el saldo y para avisar de solapes).
VACATION_LIVE_STATUSES = ("PENDING", "APPROVED")

# Un día NO LABORABLE de la empresa es, a efectos de contar, exactamente lo mismo que un festivo
# (no se trabaja y no consume vacaciones), así que se guarda en la misma tabla con su propio ámbito.
# Así hereda gratis el calendario, el cómputo y el cálculo del saldo.
VACATION_HOLIDAY_SCOPES = {
    "NACIONAL": "Nacional",
    "AUTONOMICO": "Comunidad de Madrid",
    "LOCAL": "Madrid capital",
    "EMPRESA": "No laborable (oficina)",
}


def _easter_sunday(year: int) -> date:
    """Domingo de Pascua (algoritmo anónimo gregoriano). Del él salen Jueves y Viernes Santo,
    que son los dos únicos festivos móviles que hacen falta en Madrid."""
    a = year % 19
    b, c = divmod(year, 100)
    d, e = divmod(b, 4)
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = divmod(c, 4)
    ell = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * ell) // 451
    month, day = divmod(h + ell - 7 * m + 114, 31)
    return date(year, month, day + 1)


# El calendario laboral de Madrid: los 14 festivos son 9 nacionales de fecha fija + Viernes Santo +
# 2 de la Comunidad (Jueves Santo y el 2 de mayo) + 2 de Madrid capital (San Isidro y la Almudena).
# `moves` = si cae en DOMINGO su descanso se traslada al LUNES siguiente (art. 37.2 del Estatuto de
# los Trabajadores para los nacionales; la Comunidad y el Ayuntamiento hacen lo mismo con los suyos:
# 2 de mayo de 2021 → lunes 3, 15 de agosto de 2021 → lunes 16, San Isidro de 2022 → lunes 16).
# Jueves y Viernes Santo nunca caen en domingo, así que no se trasladan nunca.
MADRID_HOLIDAY_RULES = [
    ("fixed", (1, 1),   "Año Nuevo", "NACIONAL", True),
    ("fixed", (1, 6),   "Epifanía del Señor (Reyes)", "NACIONAL", True),
    ("easter", -3,      "Jueves Santo", "AUTONOMICO", False),
    ("easter", -2,      "Viernes Santo", "NACIONAL", False),
    ("fixed", (5, 1),   "Fiesta del Trabajo", "NACIONAL", True),
    ("fixed", (5, 2),   "Fiesta de la Comunidad de Madrid", "AUTONOMICO", True),
    ("fixed", (5, 15),  "San Isidro", "LOCAL", True),
    ("fixed", (8, 15),  "Asunción de la Virgen", "NACIONAL", True),
    ("fixed", (10, 12), "Fiesta Nacional de España", "NACIONAL", True),
    ("fixed", (11, 1),  "Todos los Santos", "NACIONAL", True),
    ("fixed", (11, 9),  "Nuestra Señora de la Almudena", "LOCAL", True),
    ("fixed", (12, 6),  "Día de la Constitución Española", "NACIONAL", True),
    ("fixed", (12, 8),  "Inmaculada Concepción", "NACIONAL", True),
    ("fixed", (12, 25), "Natividad del Señor", "NACIONAL", True),
]

# ⚠️ El calendario de cada año lo publican el BOE (nacionales), el BOCM (Comunidad) y el
# Ayuntamiento (los dos de Madrid capital), y algún año pueden resolver un traslado de otra manera
# (sustituir un festivo que cae en SÁBADO, o llevarse un local a otro día). Cuando pase, se apunta
# aquí el año y sus festivos añadidos/quitados, y manda esto sobre la regla general. Los festivos
# también se pueden corregir a mano en Vacaciones → «Festivos y normas».
#   {año: {"add": [((mes, día), "Nombre", "ÁMBITO")], "remove": [(mes, día)]}}
MADRID_HOLIDAY_OVERRIDES: dict[int, dict] = {}


def _madrid_holidays_full(year: int) -> list[dict]:
    """Los festivos de Madrid de un año, con el TRASLADO al lunes ya resuelto.

    Devuelve dicts {day, name, scope, moved}. El festivo que cae en domingo se conserva (ese día ES
    la festividad, y así se ve en el calendario) y ADEMÁS se añade el lunes al que se traslada el
    descanso, con el nombre diciéndolo. `moved` marca cuál de los dos es el traslado."""
    easter = _easter_sunday(year)
    filas: list[dict] = []

    def anota(day, name, scope, moved=False):
        for f in filas:
            if f["day"] == day:
                # Dos festividades el mismo día (un traslado que cae encima de otro festivo): se
                # dicen las dos, en vez de perder una.
                if name not in f["name"]:
                    f["name"] = f"{f['name']} · {name}"
                return
        filas.append({"day": day, "name": name, "scope": scope, "moved": bool(moved)})

    for tipo, ref, nombre, ambito, mueve in MADRID_HOLIDAY_RULES:
        if tipo == "easter":
            dia = easter + timedelta(days=int(ref))
        else:
            dia = date(year, ref[0], ref[1])
        anota(dia, nombre, ambito)
        if mueve and dia.weekday() == 6:      # 6 = domingo
            anota(dia + timedelta(days=1),
                  f"{nombre} (trasladado del domingo {dia.day} de {VACATION_MONTH_LOWER[dia.month - 1]})",
                  ambito, moved=True)

    ajustes = MADRID_HOLIDAY_OVERRIDES.get(int(year)) or {}
    quitar = {date(year, m, d) for m, d in (ajustes.get("remove") or [])}
    if quitar:
        filas = [f for f in filas if f["day"] not in quitar]
    for (m, d), nombre, ambito in (ajustes.get("add") or []):
        anota(date(year, m, d), nombre, ambito)
    return sorted(filas, key=lambda f: f["day"])


def _madrid_holidays(year: int) -> list[tuple]:
    """Los festivos de Madrid de un año como (día, nombre, ámbito) — lo que siembra la BD."""
    return [(f["day"], f["name"], f["scope"]) for f in _madrid_holidays_full(year)]


def _ensure_holidays_for_year(session_db, year: int) -> None:
    """Siembra los festivos de un año si no se han sembrado nunca.

    ⚠️ La marca es lo que permite BORRAR o corregir un festivo a mano sin que la siembra lo vuelva
    a meter en el siguiente arranque."""
    try:
        year = int(year)
    except Exception:
        return
    if year < 2000 or year > 2100:
        return
    marca = f"holidays_seeded_{VACATION_REGION.lower()}_{year}"
    # Los años que se sembraron ANTES de que existieran los traslados al lunes se quedaron sin ellos
    # (y la marca de arriba impide volver a sembrarlos). Este arreglo puntual añade SOLO los
    # traslados que falten: nada de lo que se haya corregido o borrado a mano se resucita.
    marca_traslados = f"holidays_transfers_{VACATION_REGION.lower()}_{year}"
    try:
        sembrado = bool(_get_app_setting(marca))
        traslados_ok = bool(_get_app_setting(marca_traslados))
        if sembrado and traslados_ok:
            return
        existentes = {
            row.day for row in session_db.query(Holiday.day)
            .filter(Holiday.region == VACATION_REGION)
            .filter(Holiday.day >= date(year, 1, 1))
            .filter(Holiday.day <= date(year, 12, 31)).all()
        }
        nuevos = 0
        for fila in _madrid_holidays_full(year):
            # Ya sembrado: solo se completan los traslados que faltan.
            if sembrado and not fila["moved"]:
                continue
            if fila["day"] in existentes:
                continue
            session_db.add(Holiday(day=fila["day"], name=fila["name"], scope=fila["scope"],
                                   region=VACATION_REGION))
            nuevos += 1
        if nuevos:
            session_db.flush()
        session_db.commit()
        _set_app_setting(marca, "1")
        _set_app_setting(marca_traslados, "1")
    except Exception:
        try:
            session_db.rollback()
        except Exception:
            pass


def _holiday_applies_to(row, user_id=None) -> bool:
    """¿Este festivo cuenta PARA ESA PERSONA?

    Los festivos oficiales son de todo el mundo. Un día NO LABORABLE de la oficina (scope EMPRESA)
    puede ser de toda la oficina (`user_ids` vacío, que es como eran todos hasta ago 2026) o solo de
    unas personas: al resto no le afecta ni le sale en su calendario."""
    if user_id is None:
        return True
    asignados = [str(x) for x in (getattr(row, "user_ids", None) or []) if str(x or "").strip()]
    if not asignados:
        return True
    return str(user_id) in asignados


def _vacation_holidays(session_db, year_from: int, year_to: int | None = None, *, user_id=None) -> dict:
    """{fecha: {name, scope, ...}} de los festivos del rango de años (sembrando los que falten).

    Con `user_id` se dejan fuera los días no laborables que NO son de esa persona: es lo que hay que
    pasar siempre que se esté calculando el saldo, pintando su calendario o guardándole días."""
    year_to = year_to or year_from
    for y in range(int(year_from), int(year_to) + 1):
        _ensure_holidays_for_year(session_db, y)
    try:
        rows = (session_db.query(Holiday)
                .filter(Holiday.region == VACATION_REGION)
                .filter(Holiday.day >= date(int(year_from), 1, 1))
                .filter(Holiday.day <= date(int(year_to), 12, 31))
                .order_by(Holiday.day.asc()).all())
    except Exception:
        return {}
    uid = str(_safe_uuid(user_id) or "") or None
    return {r.day: {"name": r.name, "scope": (r.scope or "NACIONAL").upper(),
                    "user_ids": [str(x) for x in (getattr(r, "user_ids", None) or [])]}
            for r in rows if _holiday_applies_to(r, uid)}


def _vacation_day_counts(day: date, holidays: dict) -> bool:
    """¿Ese día CONSUME saldo? Solo de lunes a viernes y si no es festivo."""
    if not day:
        return False
    if day.weekday() >= 5:          # 5 sábado, 6 domingo
        return False
    return day not in (holidays or {})


def _user_contract_rows(session_db, user_id) -> list:
    uid = _safe_uuid(user_id)
    if not uid:
        return []
    try:
        return (session_db.query(UserContract)
                .filter(UserContract.user_id == uid)
                .order_by(UserContract.start_date.asc()).all())
    except Exception:
        return []


def _user_contract_start(session_db, user_id, rows=None) -> date | None:
    """La ANTIGÜEDAD: la fecha de comienzo más antigua de sus contratos."""
    rows = rows if rows is not None else _user_contract_rows(session_db, user_id)
    fechas = [r.start_date for r in rows if getattr(r, "start_date", None)]
    return min(fechas) if fechas else None


def _vacation_base_days(profile) -> int:
    """Días al año de esa persona: los suyos si se los han puesto, si no los de la casa."""
    try:
        val = getattr(profile, "vacation_days_per_year", None)
        if val is not None and int(val) >= 0:
            return int(val)
    except Exception:
        pass
    return VACATION_DAYS_PER_YEAR


def _vacation_adjustment(profile, year: int) -> int:
    try:
        return int((getattr(profile, "vacation_adjustments", None) or {}).get(str(year), 0) or 0)
    except Exception:
        return 0


# ---------------------------------------------------------------------------
# EXTRAS de vacaciones (luna de miel y los que se añadan)
# ---------------------------------------------------------------------------
# Son días ADICIONALES de UNA persona, con su motivo y su número, y cada uno es su **propia bolsa**:
# no salen de los días de vacaciones normales ni se mezclan con ellos.
# ⚠️ `natural=True` = el permiso se cuenta en días NATURALES, así que dentro de él los fines de semana
# y los festivos TAMBIÉN consumen (una luna de miel de 15 días naturales son 15 días seguidos, no 15
# laborables). Es lo único que cambia respecto a unas vacaciones normales, y se decide por extra.
VACATION_EXTRA_PRESETS = [
    {"id": "LUNA_MIEL", "label": "Luna de miel", "days": 15, "natural": True,
     "hint": "Lo habitual en convenio son 15 días naturales."},
]
VACATION_EXTRA_PRESET_IDS = {p["id"] for p in VACATION_EXTRA_PRESETS}


def _vacation_extras(profile) -> list[dict]:
    """Los extras de esa persona, normalizados: [{id, label, days, natural}]."""
    salida, vistos = [], set()
    for raw in (getattr(profile, "vacation_extras", None) or []):
        if not isinstance(raw, dict):
            continue
        label = re.sub(r"\s+", " ", str(raw.get("label") or "")).strip()
        try:
            dias = max(0, min(365, int(raw.get("days") or 0)))
        except Exception:
            dias = 0
        clave = (str(raw.get("id") or "").strip() or _norm_text_key(label).upper().replace(" ", "_"))[:40]
        if not clave or not dias or clave in vistos:
            continue
        vistos.add(clave)
        preset = next((p for p in VACATION_EXTRA_PRESETS if p["id"] == clave), None)
        salida.append({
            "id": clave,
            "label": label or (preset["label"] if preset else "Extra"),
            "days": dias,
            "natural": bool(raw.get("natural")),
        })
    return salida


def _vacation_extra(profile, extra_id) -> dict | None:
    """Un extra concreto de esa persona (o None si no lo tiene)."""
    clave = str(extra_id or "").strip()
    if not clave:
        return None
    return next((e for e in _vacation_extras(profile) if e["id"] == clave), None)


def _parse_vacation_extras_form(form) -> list[dict]:
    """Lee los extras del formulario de configuración.

    Llegan en filas paralelas `extra_id[]` / `extra_label[]` / `extra_days[]` / `extra_natural[]`
    (la casilla de «naturales» viaja con su índice porque un checkbox sin marcar no se envía)."""
    ids = form.getlist("extra_id[]")
    labels = form.getlist("extra_label[]")
    dias = form.getlist("extra_days[]")
    naturales = {str(x) for x in form.getlist("extra_natural[]")}
    filas = []
    for i, clave in enumerate(ids):
        clave = str(clave or "").strip()
        etiqueta = labels[i] if i < len(labels) else ""
        numero = dias[i] if i < len(dias) else ""
        try:
            numero = int(str(numero).strip() or 0)
        except Exception:
            numero = 0
        if numero <= 0:
            continue          # sin días no hay extra (es la forma de quitarlo)
        filas.append({"id": clave, "label": etiqueta, "days": numero,
                      "natural": (str(i) in naturales or clave in naturales)})
    return _vacation_extras(SimpleNamespace(vacation_extras=filas))


def _vacation_entitlement(base_days: int, year: int, start: date | None, end: date | None = None) -> dict:
    """Los días que le corresponden ESE año. En el año de alta (o de baja) se prorratean por los
    días de contrato: los días hábiles de un año trabajado, no los de asomarse en diciembre."""
    ini_year, fin_year = date(year, 1, 1), date(year, 12, 31)
    total_dias = (fin_year - ini_year).days + 1
    desde = max(start, ini_year) if start else ini_year
    hasta = min(end, fin_year) if end else fin_year
    if desde > fin_year or hasta < ini_year or desde > hasta:
        return {"days": 0, "prorated": True, "from": None, "to": None, "worked_days": 0, "year_days": total_dias}
    trabajados = (hasta - desde).days + 1
    prorrateado = trabajados < total_dias
    dias = base_days if not prorrateado else int(round(base_days * trabajados / total_dias))
    return {"days": max(0, dias), "prorated": prorrateado, "from": desde, "to": hasta,
            "worked_days": trabajados, "year_days": total_dias}


def _vacation_balance(session_db, user_id, year: int, profile=None, contracts=None) -> dict:
    """El saldo de una persona en un año: lo que le corresponde, lo aprobado, lo pendiente de
    aprobar y lo que le queda. Punto ÚNICO: lo usan su pantalla, el panel de gestión y el
    control de que una petición no se pase del saldo."""
    uid = _safe_uuid(user_id)
    year = int(year)
    if profile is None and uid:
        profile = session_db.get(UserProfile, uid)
    base = _vacation_base_days(profile)
    contratos = contracts if contracts is not None else _user_contract_rows(session_db, uid)
    inicio = _user_contract_start(session_db, uid, rows=contratos)
    # Fin: si TODOS sus contratos tienen fecha de fin, el último manda; si alguno sigue abierto, no.
    fines = [r.end_date for r in contratos if getattr(r, "end_date", None)]
    fin = max(fines) if (contratos and fines and len(fines) == len(contratos)) else None
    ent = _vacation_entitlement(base, year, inicio, fin)
    ajuste = _vacation_adjustment(profile, year)
    total = max(0, ent["days"] + ajuste)

    usados = pendientes = disfrutados = 0
    libres_usados = libres_pendientes = libres_disfrutados = 0
    # Cada EXTRA (luna de miel…) lleva su propia cuenta: {extra_id: [usados, pendientes, disfrutados]}
    extras_cuenta: dict = {}
    hoy = today_local()
    try:
        filas = (session_db.query(VacationDay.day, VacationRequest.status, VacationRequest.kind,
                                  VacationRequest.extra_id)
                 .join(VacationRequest, VacationDay.request_id == VacationRequest.id)
                 .filter(VacationDay.user_id == uid)
                 .filter(VacationDay.counts.is_(True))
                 .filter(VacationRequest.status.in_(VACATION_LIVE_STATUSES))
                 .filter(VacationDay.day >= date(year, 1, 1))
                 .filter(VacationDay.day <= date(year, 12, 31)).all())
        for day, estado, tipo, extra_id in filas:
            aprobado = (estado or "").upper() == "APPROVED"
            # ⚠️ Los días de un EXTRA no tocan el saldo de vacaciones: su bolsa es aparte.
            if (extra_id or "").strip():
                cuenta = extras_cuenta.setdefault(extra_id.strip(), [0, 0, 0])
                if aprobado:
                    cuenta[0] += 1
                    if day and day <= hoy:
                        cuenta[2] += 1
                else:
                    cuenta[1] += 1
                continue
            # ⚠️ Un DÍA LIBRE tampoco: va a su propia cuenta.
            if _vacation_kind(tipo) == "DIA_LIBRE":
                if aprobado:
                    libres_usados += 1
                    if day and day <= hoy:
                        libres_disfrutados += 1
                else:
                    libres_pendientes += 1
            elif aprobado:
                usados += 1
                if day and day <= hoy:
                    disfrutados += 1
            else:
                pendientes += 1
    except Exception:
        pass

    extras = []
    for extra in _vacation_extras(profile):
        u, p, d = extras_cuenta.get(extra["id"], [0, 0, 0])
        extras.append({**extra, "used": u, "pending": p, "enjoyed": d,
                       "remaining": max(0, extra["days"] - u - p)})

    return {
        "year": year, "base": base, "entitled": ent["days"], "prorated": ent["prorated"],
        "adjustment": ajuste, "total": total,
        "used": usados,            # aprobados del año (los haya disfrutado o no)
        "enjoyed": disfrutados,    # aprobados que ya han pasado
        "pending": pendientes,     # pedidos y aún sin aprobar
        "remaining": max(0, total - usados - pendientes),
        # DÍAS LIBRES: cuenta aparte, sin tope (no se descuentan de las vacaciones).
        "free_used": libres_usados,
        "free_enjoyed": libres_disfrutados,
        "free_pending": libres_pendientes,
        # EXTRAS de esa persona (luna de miel…), cada uno con su bolsa.
        "extras": extras,
        "start_date": inicio, "end_date": fin,
        "has_contract": bool(inicio),
        # Sin fecha de comienzo NO se sabe lo que le corresponde: los días se pueden seguir
        # apuntando y pidiendo, pero el «le quedan» no significa nada y hay que advertirlo.
        "unknown_entitlement": not bool(inicio),
    }


def _vacation_office_user_ids(session_db) -> list[str]:
    """Personal de la oficina VIVO (sin bloqueados ni eliminados). Es a quien se le llevan las
    vacaciones. ⚠️ is_blocked/is_deleted viven en UserSecurity, no en User."""
    try:
        fuera = _inactive_user_ids(session_db)
        out = []
        for prof in session_db.query(UserProfile).order_by(UserProfile.nick.asc()).all():
            uid = str(getattr(prof, "user_id", "") or "")
            if uid and to_uuid(uid) not in fuera:
                out.append(uid)
        return out
    except Exception:
        return []


def _vacation_person_row(session_db, profile, year: int, contracts=None) -> dict:
    saldo = _vacation_balance(session_db, profile.user_id, year, profile=profile, contracts=contracts)
    return {
        "user_id": str(profile.user_id),
        "nick": (profile.nick or "").strip(),
        "full_name": _profile_full_name(profile) or (profile.nick or "").strip(),
        "photo_url": (getattr(profile, "photo_url", None) or "").strip(),
        "departments": list(getattr(profile, "departments", None) or []),
        "balance": saldo,
    }


def _vacation_color_for(index: int) -> str:
    """Un color estable por persona para el calendario general (mismo criterio que la agenda)."""
    paleta = ["#E33D48", "#007CA2", "#2E7D32", "#7B1FA2", "#EF6C00", "#00838F",
              "#5D4037", "#C2185B", "#455A64", "#9E9D24", "#1565C0", "#6A1B9A"]
    return paleta[index % len(paleta)]


def _vacation_request_rows(session_db, *, user_id=None, statuses=None, year=None, limit=None,
                           kind=None) -> list[dict]:
    """Peticiones con sus días, listas para pintar."""
    q = session_db.query(VacationRequest)
    if user_id:
        uid = _safe_uuid(user_id)
        if not uid:
            return []
        q = q.filter(VacationRequest.user_id == uid)
    if statuses:
        q = q.filter(VacationRequest.status.in_([s.upper() for s in statuses]))
    if year:
        q = q.filter(VacationRequest.year == int(year))
    if kind:
        q = q.filter(VacationRequest.kind == _vacation_kind(kind))
    q = q.order_by(VacationRequest.created_at.desc())
    if limit:
        q = q.limit(int(limit))
    peticiones = q.all()
    if not peticiones:
        return []

    ids = [p.id for p in peticiones]
    dias_por_peticion: dict = {}
    try:
        for d in (session_db.query(VacationDay)
                  .filter(VacationDay.request_id.in_(ids))
                  .order_by(VacationDay.day.asc()).all()):
            dias_por_peticion.setdefault(str(d.request_id), []).append(d)
    except Exception:
        pass

    perfiles = {}
    try:
        uids = list({p.user_id for p in peticiones} | {p.decided_by_user_id for p in peticiones if p.decided_by_user_id})
        for prof in session_db.query(UserProfile).filter(UserProfile.user_id.in_(uids)).all():
            perfiles[str(prof.user_id)] = prof
    except Exception:
        pass

    out = []
    for p in peticiones:
        dias = dias_por_peticion.get(str(p.id), [])
        fechas = [d.day for d in dias if d.day]
        prof = perfiles.get(str(p.user_id))
        decisor = perfiles.get(str(p.decided_by_user_id)) if p.decided_by_user_id else None
        estado = (p.status or "PENDING").upper()
        tipo = _vacation_kind(getattr(p, "kind", None))
        out.append({
            "id": str(p.id),
            "user_id": str(p.user_id),
            "kind": tipo,
            "kind_meta": VACATION_KINDS[tipo],
            # De qué bolsa salen: vacío = vacaciones normales; si no, el extra (luna de miel…).
            "extra_id": (getattr(p, "extra_id", None) or ""),
            "extra_label": ((_vacation_extra(prof, getattr(p, "extra_id", None)) or {}).get("label")
                            if (getattr(p, "extra_id", None) or "") else ""),
            "extra_natural": bool((_vacation_extra(prof, getattr(p, "extra_id", None)) or {}).get("natural")
                                  if (getattr(p, "extra_id", None) or "") else False),
            "nick": (getattr(prof, "nick", None) or "").strip() or "—",
            "full_name": (_profile_full_name(prof) if prof else "") or (getattr(prof, "nick", None) or ""),
            "photo_url": (getattr(prof, "photo_url", None) or "").strip(),
            "status": estado,
            "status_meta": VACATION_STATUS_META.get(estado, VACATION_STATUS_META["PENDING"]),
            "year": p.year,
            "days_count": int(p.days_count or 0),
            "days": [d.day for d in dias],
            "days_iso": [d.day.isoformat() for d in dias if d.day],
            "counting_days": [d.day for d in dias if d.counts],
            "first_day": min(fechas) if fechas else None,
            "last_day": max(fechas) if fechas else None,
            "range_label": _vacation_range_label(fechas),
            "note": (p.note or "").strip(),
            "decision_note": (p.decision_note or "").strip(),
            "decided_by": (getattr(decisor, "nick", None) or "").strip(),
            "decided_at": p.decided_at,
            "created_at": p.created_at,
        })
    return out


def _vacation_runs(fechas: list) -> list[list]:
    """Parte unos días en **TRAMOS DE DÍAS SEGUIDOS**. Punto único de toda la app.

    ⚠️⚠️ Una petición de vacaciones puede tener días que NO van seguidos (uno el 24 de agosto y el
    resto en octubre): pintarla como UNA franja del primero al último dice que esa persona está de
    vacaciones agosto, septiembre y octubre enteros — que es justo lo que confundía en el calendario
    (bug real). Cada racha se pinta por separado, y así se ve **solo los días que de verdad libra**.
    Devuelve una lista de tramos, cada uno con sus días ordenados."""
    fechas = sorted({f for f in (fechas or []) if f})
    if not fechas:
        return []
    tramos, actual = [], [fechas[0]]
    for anterior, siguiente in zip(fechas, fechas[1:]):
        if (siguiente - anterior).days == 1:
            actual.append(siguiente)
        else:
            tramos.append(actual)
            actual = [siguiente]
    tramos.append(actual)
    return tramos


def _vacation_run_label(tramo: list) -> str:
    """Un tramo, en corto: «12/08/2026» · «12 – 20/08/2026» · «28/07 – 04/08/2026»."""
    if not tramo:
        return ""
    if len(tramo) == 1:
        return tramo[0].strftime("%d/%m/%Y")
    if tramo[0].month == tramo[-1].month and tramo[0].year == tramo[-1].year:
        return f"{tramo[0].strftime('%d')} – {tramo[-1].strftime('%d/%m/%Y')}"
    return f"{tramo[0].strftime('%d/%m')} – {tramo[-1].strftime('%d/%m/%Y')}"


def _vacation_range_label(fechas: list, *, max_runs: int = 3) -> str:
    """Los días de una petición, **por tramos seguidos**: «24/08/2026 · 13 – 15/10/2026».

    ⚠️ Antes solo se decía el PRIMER tramo y «(y 2 tramos más)», así que no se veía cuándo eran los
    demás. Se enseñan hasta `max_runs` y, si hay más, se dice cuántos quedan."""
    tramos = _vacation_runs(fechas)
    if not tramos:
        return "—"
    texto = " · ".join(_vacation_run_label(t) for t in tramos[:max_runs])
    sobran = len(tramos) - max_runs
    if sobran > 0:
        texto += f" (y {sobran} tramo{'' if sobran == 1 else 's'} más)"
    return texto


def _parse_vacation_days(raw) -> list:
    """Los días que llegan del calendario: «2026-08-03,2026-08-04,…». Sin repetidos y ordenados."""
    out, vistos = [], set()
    for trozo in (raw or "").replace(";", ",").split(","):
        trozo = trozo.strip()
        if not trozo or trozo in vistos:
            continue
        vistos.add(trozo)
        try:
            out.append(date.fromisoformat(trozo))
        except Exception:
            continue
    return sorted(out)


def _vacation_taken_days(session_db, user_id, days: list, exclude_request_id=None) -> set:
    """Días que esa persona YA tiene pedidos o aprobados (para no pisarlos)."""
    uid = _safe_uuid(user_id)
    if not uid or not days:
        return set()
    try:
        q = (session_db.query(VacationDay.day)
             .join(VacationRequest, VacationDay.request_id == VacationRequest.id)
             .filter(VacationDay.user_id == uid)
             .filter(VacationRequest.status.in_(VACATION_LIVE_STATUSES))
             .filter(VacationDay.day.in_(days)))
        if exclude_request_id:
            q = q.filter(VacationRequest.id != _safe_uuid(exclude_request_id))
        return {r[0] for r in q.all()}
    except Exception:
        return set()


def _vacation_overlaps(session_db, user_id, days: list) -> list[dict]:
    """Quién MÁS tiene esos días (aviso, no bloqueo: lo decide quien aprueba)."""
    if not days:
        return []
    uid = _safe_uuid(user_id)
    try:
        filas = (session_db.query(VacationDay.user_id, VacationDay.day)
                 .join(VacationRequest, VacationDay.request_id == VacationRequest.id)
                 .filter(VacationRequest.status.in_(VACATION_LIVE_STATUSES))
                 .filter(VacationDay.day.in_(days))
                 .filter(VacationDay.counts.is_(True)).all())
    except Exception:
        return []
    por_persona: dict = {}
    for otro_uid, day in filas:
        if uid and str(otro_uid) == str(uid):
            continue
        por_persona.setdefault(str(otro_uid), []).append(day)
    if not por_persona:
        return []
    perfiles = {}
    try:
        for prof in session_db.query(UserProfile).filter(UserProfile.user_id.in_(list(por_persona.keys()))).all():
            perfiles[str(prof.user_id)] = prof
    except Exception:
        pass
    out = []
    for otro_uid, dias in por_persona.items():
        prof = perfiles.get(otro_uid)
        out.append({
            "user_id": otro_uid,
            "nick": (getattr(prof, "nick", None) or "").strip() or "—",
            "photo_url": (getattr(prof, "photo_url", None) or "").strip(),
            "days": sorted(dias),
            "count": len(dias),
        })
    out.sort(key=lambda r: -r["count"])
    return out


def _vacation_rules_text() -> str:
    return (_get_app_setting(VACATION_RULES_SETTING) or VACATION_RULES_DEFAULT).strip()


def _can_manage_vacations() -> bool:
    """Quién gestiona las vacaciones: DIRECCIÓN, quien tenga la responsabilidad «VACACIONES» y
    **ADMINISTRACIÓN**.

    ⚠️ Antes solo valía la responsabilidad, que es un ajuste fino que hay que acordarse de dar: la
    gente de administración se comía un 403 al apuntar días o configurar a alguien (bug real). La
    responsabilidad sigue sirviendo para FILTRAR de quién es la tarea en su Inicio, que es para lo
    que está: no para conceder el acceso."""
    try:
        if is_master():
            return True
        if VACATION_RESPONSIBILITY in _current_user_admin_responsibilities():
            return True
        prof = (_current_user_state() or {}).get("profile")
        return "Administración" in (getattr(prof, "departments", None) or [])
    except Exception:
        return False


def _can_view_person_contract() -> bool:
    """El contrato de una persona SOLO lo ven administración y dirección."""
    try:
        if is_master():
            return True
        prof = (_current_user_state() or {}).get("profile")
        return "Administración" in (getattr(prof, "departments", None) or [])
    except Exception:
        return False


def _vacation_manager_user_ids(session_db) -> list[str]:
    """A quién hay que avisar de una petición: dirección + los responsables de «VACACIONES».
    Si no hay nadie con la responsabilidad, a todo Administración (nada se queda sin dueño)."""
    ids = set()
    try:
        for user in session_db.query(User).filter(User.role == 10).all():
            ids.add(str(user.id))
    except Exception:
        pass
    responsables = _admin_responsible_user_ids(session_db, VACATION_RESPONSIBILITY)
    if responsables:
        ids |= set(responsables)
    else:
        ids |= set(_department_user_ids(session_db, "Administración"))
    fuera = {str(x) for x in _inactive_user_ids(session_db)}
    return [i for i in ids if i not in fuera]


def _sync_vacation_access_grant(session_db, user_id, tiene_responsabilidad: bool) -> None:
    """Quien gestiona las vacaciones necesita ENTRAR en la sección. El permiso se concede (y se
    retira) solo, al asignar la responsabilidad: así no hay que acordarse de darlo aparte y sigue
    viéndose en la pantalla de Accesos, que es la fuente de verdad."""
    uid = _safe_uuid(user_id)
    if not uid:
        return
    try:
        grant = (session_db.query(UserAccessGrant)
                 .filter(UserAccessGrant.user_id == uid)
                 .filter(UserAccessGrant.resource_key == VACATION_ACCESS_KEY).first())
        if not grant:
            if not tiene_responsabilidad:
                return
            grant = UserAccessGrant(user_id=uid, resource_key=VACATION_ACCESS_KEY)
            session_db.add(grant)
        grant.can_view_basic = bool(tiene_responsabilidad)
        grant.can_edit = bool(tiene_responsabilidad)
        grant.can_view_econ = False
    except Exception:
        pass


def _vacation_month_matrix(year: int, month: int) -> list[list]:
    """Las semanas del mes (lunes a domingo), con None en los huecos."""
    cal = _cal.Calendar(firstweekday=0)
    return [list(week) for week in cal.monthdatescalendar(year, month)]


VACATION_MONTH_NAMES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
                        "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"]


def _vacation_calendar_payload(session_db, year: int, user_ids: list[str] | None = None,
                               include_pending: bool = True) -> dict:
    """Lo que necesita el calendario en el navegador: festivos y días de cada persona.
    Un solo formato para las dos pantallas (la mía y la de toda la oficina)."""
    # De UNA persona: se dejan fuera los no laborables que no son suyos. De toda la oficina: todos.
    _solo = user_ids[0] if (user_ids and len(user_ids) == 1) else None
    holidays = _vacation_holidays(session_db, year, user_id=_solo)
    estados = list(VACATION_LIVE_STATUSES) if include_pending else ["APPROVED"]
    q = (session_db.query(VacationDay.user_id, VacationDay.day, VacationDay.counts,
                          VacationRequest.status, VacationRequest.id, VacationRequest.kind,
                          VacationRequest.note, VacationRequest.extra_id)
         .join(VacationRequest, VacationDay.request_id == VacationRequest.id)
         .filter(VacationRequest.status.in_(estados))
         .filter(VacationDay.day >= date(int(year), 1, 1))
         .filter(VacationDay.day <= date(int(year), 12, 31)))
    if user_ids:
        q = q.filter(VacationDay.user_id.in_([_safe_uuid(u) for u in user_ids if _safe_uuid(u)]))
    dias = []
    try:
        for uid, day, counts, estado, rid, tipo, nota, extra_id in q.all():
            dias.append({"user_id": str(uid), "day": day.isoformat(),
                         "counts": bool(counts), "status": (estado or "").upper(),
                         "request_id": str(rid), "kind": _vacation_kind(tipo),
                         # Para el tooltip de las rayitas del cuadrante: qué es, el motivo y de quién.
                         "note": (nota or "").strip(),
                         "extra_id": (extra_id or "")})
    except Exception:
        pass
    return {
        "year": int(year),
        # `partial` = día no laborable que solo es de unas personas (en el calendario de toda la
        # oficina hay que decirlo: no es de todo el mundo).
        "holidays": [{"day": d.isoformat(), "name": meta["name"],
                      "scope": meta["scope"], "scope_label": VACATION_HOLIDAY_SCOPES.get(meta["scope"], ""),
                      "partial": bool(meta.get("user_ids"))}
                     for d, meta in sorted(holidays.items())],
        "days": dias,
        "month_names": VACATION_MONTH_NAMES,
        "kinds": {k: {"label": v["label"], "color": v["color"]} for k, v in VACATION_KINDS.items()},
    }


# ---------------------------------------------------------------------------
# AVISOS de vacaciones / días libres / días no laborables
# ---------------------------------------------------------------------------
# UN SOLO MOTOR para los dos canales: `_vacation_notice_html` genera el HTML con estilos EN LÍNEA y
# ese mismo HTML es el del CORREO y el de la PÁGINA que se abre al pinchar el aviso de la app. Si se
# toca el diseño, se tocan los dos a la vez.
#
# Contenido, en orden: logo de la EMPRESA DEL GRUPO con la que la persona tiene contrato (arriba a
# la derecha), título centrado, el texto (de enhorabuena o sobrio si es un «no»), el calendario con
# los días marcados —solo los meses afectados— y, al final, las etiquetas con los totales del año.
VACATION_NOTICE_TYPES = {
    "VACACIONES_OK": {
        "title": "Vacaciones", "tone": "ok", "icon": "🏖️",
        "lead": "¡Enhorabuena! Tus vacaciones han sido aprobadas.",
    },
    "VACACIONES_NO": {
        "title": "Vacaciones", "tone": "bad", "icon": "",
        "lead": "Lo sentimos, tus vacaciones no han sido aprobadas. "
                "Por favor, consulta con Administración los motivos.",
    },
    "DIA_LIBRE_OK": {
        "title": "Día libre", "tone": "ok", "icon": "☕",
        "lead": "¡Enhorabuena! Tu día libre ha sido aprobado.",
    },
    "DIA_LIBRE_NO": {
        "title": "Día libre", "tone": "bad", "icon": "",
        "lead": "Lo sentimos, tu día libre no ha sido aprobado. "
                "Por favor, consulta con Administración los motivos.",
    },
    "DIA_LIBRE_REGALO": {
        "title": "Día libre", "tone": "ok", "icon": "🎁",
        "lead": "¡Enhorabuena! La empresa te ha concedido un día libre.",
    },
    "NO_LABORABLE": {
        "title": "Día no laborable", "tone": "ok", "icon": "🎉",
        "lead": "",   # se compone con la fecha completa
    },
}

VACATION_WEEKDAY_NAMES = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"]
VACATION_MONTH_LOWER = [m.lower() for m in VACATION_MONTH_NAMES]


def _vacation_long_date(day) -> str:
    """«lunes 3 de junio de 2026» — la fecha como se dice, para el texto del aviso."""
    if not day:
        return ""
    return (f"{VACATION_WEEKDAY_NAMES[day.weekday()]} {day.day} de "
            f"{VACATION_MONTH_LOWER[day.month - 1]} de {day.year}")


def _user_contract_company(session_db, user_id, contracts=None):
    """La empresa del grupo con la que esta persona tiene contrato (la del contrato en vigor y, si
    no hay ninguno abierto, la del más reciente). Es su logo el que va en sus avisos."""
    filas = contracts if contracts is not None else _user_contract_rows(session_db, user_id)
    if not filas:
        return None
    abiertos = [c for c in filas if not getattr(c, "end_date", None) and getattr(c, "company_id", None)]
    candidato = (abiertos[-1] if abiertos else None)
    if candidato is None:
        con_empresa = [c for c in filas if getattr(c, "company_id", None)]
        candidato = con_empresa[-1] if con_empresa else None
    if candidato is None:
        return None
    try:
        return session_db.get(GroupCompany, candidato.company_id)
    except Exception:
        return None


def _vacation_notice_brand(session_db, user_id, contracts=None) -> dict:
    """Logo y nombre para la cabecera del aviso: la empresa del contrato y, si no consta, la casa."""
    empresa = _user_contract_company(session_db, user_id, contracts=contracts)
    logo = (getattr(empresa, "logo_url", None) or "").strip().rstrip("?") if empresa else ""
    nombre = (getattr(empresa, "name", None) or "").strip() if empresa else ""
    if not logo:
        respaldo = _treinta_y_tres_brand_assets(session_db)
        logo = (respaldo.get("logo_url") or "").strip()
        nombre = nombre or (respaldo.get("company_name") or "")
    return {"logo_url": _absolute_media_url(logo) if logo else "", "company_name": nombre}


def _vacation_notice_calendar_html(days: list, holidays: dict, color: str) -> str:
    """El calendario del aviso: SOLO los meses afectados, con los días marcados.

    Se dibuja con <table> y estilos en línea porque va dentro de un correo: ni rejillas CSS ni
    clases (la mitad de los clientes las tiran)."""
    marcados = sorted({d for d in (days or []) if d})
    if not marcados:
        return ""
    meses = []
    vistos = set()
    for d in marcados:
        if (d.year, d.month) not in vistos:
            vistos.add((d.year, d.month))
            meses.append((d.year, d.month))

    bloques = []
    for year, month in meses:
        celdas = []
        primero = date(year, month, 1)
        for _ in range((primero.weekday()) % 7):
            celdas.append('<td style="padding:0;"></td>')
        ultimo = _cal.monthrange(year, month)[1]
        for num in range(1, ultimo + 1):
            dia = date(year, month, num)
            marcado = dia in marcados
            finde = dia.weekday() >= 5
            festivo = dia in (holidays or {})
            if marcado:
                estilo = (f"background:{color};color:#ffffff;font-weight:700;"
                          "border-radius:8px;")
            elif festivo:
                estilo = "background:#fdeaec;color:#a01f29;border-radius:8px;"
            elif finde:
                estilo = "background:#eef2f6;color:#7b8794;border-radius:8px;"
            else:
                estilo = "color:#111827;"
            celdas.append(
                '<td align="center" style="padding:0;">'
                f'<div style="width:30px;height:30px;line-height:30px;margin:2px auto;'
                f'font-size:13px;font-family:Arial,Helvetica,sans-serif;{estilo}">{num}</div></td>')
        filas = []
        for i in range(0, len(celdas), 7):
            trozo = celdas[i:i + 7]
            trozo += ['<td style="padding:0;"></td>'] * (7 - len(trozo))
            filas.append("<tr>" + "".join(trozo) + "</tr>")
        cabecera = "".join(
            f'<th style="padding:0 0 6px;font-size:11px;color:#8a94a3;'
            f'font-family:Arial,Helvetica,sans-serif;font-weight:700;">{d}</th>'
            for d in ["L", "M", "X", "J", "V", "S", "D"])
        bloques.append(
            '<td valign="top" style="padding:8px 10px;">'
            f'<div style="font-size:14px;font-weight:700;margin-bottom:8px;text-align:center;'
            f'font-family:Arial,Helvetica,sans-serif;color:#111827;">'
            f'{VACATION_MONTH_NAMES[month - 1]} {year}</div>'
            '<table role="presentation" cellpadding="0" cellspacing="0" border="0" '
            'style="border-collapse:collapse;">'
            f"<tr>{cabecera}</tr>{''.join(filas)}</table></td>")

    # Los meses, de dos en dos, para que no se salga en el móvil.
    filas_meses = []
    for i in range(0, len(bloques), 2):
        filas_meses.append("<tr>" + "".join(bloques[i:i + 2]) + "</tr>")
    return ('<table role="presentation" cellpadding="0" cellspacing="0" border="0" '
            'align="center" style="margin:22px auto 0;border-collapse:collapse;">'
            + "".join(filas_meses) + "</table>")


def _vacation_nonworking_text(days: list, *, html: bool = False) -> str:
    """El texto ESTÁNDAR con el que se comunica un día no laborable.

    «Como cortesía, la empresa ha decidido que el próximo martes 27 de junio de 2026, no se trabaje.
      Gracias por el buen trabajo y a disfrutar.»
    Se puede cambiar al comunicarlo; si no se escribe nada, va este."""
    dias = sorted({d for d in (days or []) if d})
    if not dias:
        return ""
    if len(dias) == 1:
        cuando = "el próximo <b>%s</b>" % _vacation_long_date(dias[0])
    else:
        etiquetas = [_vacation_long_date(d) for d in dias]
        cuando = ("los próximos <b>" + ", ".join(etiquetas[:-1]) + "</b> y <b>" + etiquetas[-1] + "</b>")
    texto = ("Como cortesía, la empresa ha decidido que %s, no se trabaje.\n\n"
             "Gracias por el buen trabajo y a disfrutar." % cuando)
    if html:
        return texto.replace("\n\n", "<br/><br/>").replace("\n", "<br/>")
    return texto.replace("<b>", "").replace("</b>", "")


def _vacation_notice_context(session_db, notice_type: str, user_id, days: list,
                             note: str = "", year: int | None = None) -> dict:
    """Todo lo que necesita el aviso (correo, página y título de la notificación)."""
    tipo = notice_type if notice_type in VACATION_NOTICE_TYPES else "VACACIONES_OK"
    meta = VACATION_NOTICE_TYPES[tipo]
    dias = sorted({d for d in (days or []) if d})
    year = int(year or (dias[0].year if dias else today_local().year))
    contratos = _user_contract_rows(session_db, user_id)
    saldo = _vacation_balance(session_db, user_id, year, contracts=contratos)
    prof = session_db.get(UserProfile, _safe_uuid(user_id))

    if tipo == "NO_LABORABLE":
        # El texto se puede cambiar al comunicarlo; si no se escribe nada, va el ESTÁNDAR.
        escrito = (note or "").strip()
        lead = (escape(escrito).replace("\n", "<br/>") if escrito
                else _vacation_nonworking_text(dias, html=True))
        color = "#6A1B9A"
    else:
        lead = meta["lead"]
        color = ("#6A1B9A" if meta["title"] == "Día libre"
                 else ("#9aa3af" if meta["tone"] == "bad" else "#E33D48"))

    return {
        "type": tipo,
        "tone": meta["tone"],
        "icon": meta["icon"],
        "title": meta["title"],
        "lead": lead,
        "color": color,
        "days": dias,
        "range_label": _vacation_range_label(dias),
        "note": (note or "").strip(),
        "year": year,
        "nick": (getattr(prof, "nick", None) or "").strip(),
        "balance": saldo,
        "brand": _vacation_notice_brand(session_db, user_id, contracts=contratos),
        "holidays": _vacation_holidays(session_db, year, user_id=user_id),
        # En un «no laborable» no se enseñan los saldos: no es de nadie en particular.
        "show_totals": tipo != "NO_LABORABLE",
    }


def _vacation_notice_html(ctx: dict) -> str:
    """El HTML del aviso. Estilos EN LÍNEA (va por correo) y la animación en un <style> aparte:
    el cliente que la tire enseña el icono quieto, que es una degradación limpia."""
    esc = lambda v: escape(str(v or ""))
    brand = ctx.get("brand") or {}
    color = ctx.get("color") or "#E33D48"
    alegre = ctx.get("tone") == "ok"

    cabecera = ""
    if brand.get("logo_url"):
        cabecera = (f'<tr><td align="right" style="padding:0 0 10px;">'
                    f'<img src="{esc(brand["logo_url"])}" alt="{esc(brand.get("company_name"))}" '
                    'style="max-height:54px;max-width:180px;"></td></tr>')

    # Iconitos en los colores corporativos. La animación es un extra: sin ella se ven igual.
    adornos = ""
    if alegre and ctx.get("icon"):
        adornos = (
            '<div style="text-align:center;margin:6px 0 14px;">'
            + "".join(
                f'<span class="vn-pop" style="display:inline-block;font-size:30px;margin:0 6px;'
                f'animation-delay:{i * 0.15}s;">{ctx["icon"]}</span>' for i in range(3))
            + "</div>")

    totales = ""
    if ctx.get("show_totals"):
        b = ctx["balance"] or {}
        if ctx["title"] == "Día libre":
            pastillas = [("Días libres disfrutados en " + str(ctx["year"]), b.get("free_used", 0), "#6A1B9A")]
        else:
            pastillas = [
                ("Días de vacaciones disfrutados", b.get("used", 0), "#2e7d32"),
                (f"Días restantes en {ctx['year']}", b.get("remaining", 0), "#E33D48"),
            ]
        celdas = "".join(
            '<td align="center" style="padding:6px 10px;">'
            f'<div style="display:inline-block;border:2px solid {c};border-radius:14px;'
            'padding:12px 22px;font-family:Arial,Helvetica,sans-serif;">'
            f'<div style="font-size:30px;font-weight:800;color:{c};line-height:1;">{n}</div>'
            f'<div style="font-size:12px;color:#4b5563;margin-top:6px;">{esc(t)}</div>'
            "</div></td>" for t, n, c in pastillas)
        totales = ('<table role="presentation" cellpadding="0" cellspacing="0" border="0" '
                   f'align="center" style="margin:26px auto 0;"><tr>{celdas}</tr></table>')

    nota = ""
    # ⚠️ En un DÍA NO LABORABLE la nota ES el mensaje (ya va arriba, en `lead`): no se repite abajo.
    if ctx.get("note") and ctx.get("type") != "NO_LABORABLE":
        nota = ('<p style="margin:14px 0 0;font-size:14px;color:#4b5563;text-align:center;'
                f'font-family:Arial,Helvetica,sans-serif;">{esc(ctx["note"])}</p>')

    # El correo de un día no laborable es lo que se pidió y nada más: el logo arriba a la derecha y
    # debajo el mensaje (ni calendario ni totales; para eso está el calendario de la app).
    calendario = ("" if ctx.get("type") == "NO_LABORABLE"
                  else _vacation_notice_calendar_html(ctx.get("days"), ctx.get("holidays"), color))

    animacion = ("""<style>
  @keyframes vnPop { 0%,100% { transform: translateY(0) scale(1); } 50% { transform: translateY(-8px) scale(1.12); } }
  .vn-pop { animation: vnPop 1.6s ease-in-out infinite; }
  @media (prefers-reduced-motion: reduce) { .vn-pop { animation: none; } }
</style>""" if adornos else "")

    return f"""<!doctype html>
<html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
{animacion}</head>
<body style="margin:0;background:#f5f7fb;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f5f7fb;padding:26px 12px;">
<tr><td align="center">
  <table role="presentation" width="640" cellpadding="0" cellspacing="0" border="0"
         style="width:640px;max-width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:20px;padding:26px 28px 32px;">
    {cabecera}
    <tr><td>
      <h1 style="margin:6px 0 4px;text-align:center;font-size:28px;color:#111827;
                 font-family:Arial,Helvetica,sans-serif;">{esc(ctx['title'])}</h1>
      <div style="text-align:center;font-size:14px;color:#6b7280;
                  font-family:Arial,Helvetica,sans-serif;">{esc(ctx['range_label'])}</div>
      {adornos}
      <p style="margin:16px 0 0;text-align:center;font-size:17px;line-height:1.6;color:#111827;
                font-family:Arial,Helvetica,sans-serif;">{ctx['lead']}</p>
      {nota}
      {calendario}
      {totales}
    </td></tr>
  </table>
</td></tr></table>
</body></html>"""


def _vacation_notice_send(session_db, notice_type: str, user_id, days: list, note: str = "",
                          year: int | None = None, ref_id=None) -> None:
    """Avisa a la persona por los DOS canales: la campanita de la app y el correo, con el mismo
    contenido. Best-effort: si el correo falla, el aviso de la app ya está puesto."""
    ctx = _vacation_notice_context(session_db, notice_type, user_id, days, note=note, year=year)
    titulo = f"{ctx['title']} · {ctx['range_label']}"
    cuerpo = re.sub(r"<[^>]+>", "", ctx["lead"] or "").strip()
    url = url_for("vacation_notice_view", kind=notice_type.lower(), ref_id=str(ref_id or "0"))
    _notify_user(session_db, user_id, "VACACIONES", titulo, cuerpo, url,
                 ref_type="vacation_notice", ref_id=str(ref_id or ""))
    try:
        user = session_db.get(User, _safe_uuid(user_id))
        correo = (getattr(user, "email", None) or "").strip()
        if correo:
            _send_optional_email(correo, titulo, _vacation_notice_html(ctx))
    except Exception:
        app.logger.exception("[vacaciones] no se pudo mandar el correo del aviso")


def _vacation_apply_days(session_db, req, days: list, holidays: dict, *, natural: bool = False) -> int:
    """Escribe los días de una petición y devuelve cuántos CONSUMEN saldo.
    Punto único: lo usan pedir, editar y el alta a mano de administración.

    ⚠️ Con `natural=True` (un extra que se cuenta en días NATURALES, como una luna de miel de 15 días)
    **TODOS** los días consumen: también los sábados, los domingos y los festivos."""
    try:
        session_db.query(VacationDay).filter(VacationDay.request_id == req.id).delete(synchronize_session=False)
    except Exception:
        pass
    cuentan = 0
    for day in sorted(set(days or [])):
        counts = True if natural else _vacation_day_counts(day, holidays)
        session_db.add(VacationDay(request_id=req.id, user_id=req.user_id, day=day, counts=counts))
        if counts:
            cuentan += 1
    req.days_count = cuentan
    return cuentan


def _vacation_check_request(session_db, user_id, days: list, *, exclude_request_id=None,
                            ignore_balance: bool = False, kind: str = VACATION_DEFAULT_KIND,
                            extra_id=None, profile=None) -> tuple:
    """Comprueba una petición contra las NORMAS que se aplican solas.
    Devuelve (error, info): `error` = no se puede seguir; `info` = avisos (solapes).

    ⚠️ El tope de SALDO solo se aplica a las VACACIONES: un día libre no sale de esa bolsa.
    Lo que sí vale para los dos es no pisar días ya pedidos y no marcar findes ni festivos.
    ⚠️ Con `extra_id` los días salen de la bolsa de ESE EXTRA (luna de miel…), no de las vacaciones,
    y si el extra se cuenta en días NATURALES todos los días consumen (findes y festivos incluidos)."""
    kind = _vacation_kind(kind)
    if not days:
        return "No has marcado ningún día.", None
    year = days[0].year
    if any(d.year != year for d in days):
        return "Los días tienen que ser del mismo año: pide un tramo por año.", None

    if profile is None:
        profile = session_db.get(UserProfile, _safe_uuid(user_id))
    extra = _vacation_extra(profile, extra_id) if extra_id else None
    if extra_id and not extra:
        return "Ese permiso especial no está configurado para esta persona.", None
    natural = bool(extra and extra["natural"])

    holidays = _vacation_holidays(session_db, year, user_id=user_id)
    # En un extra de días NATURALES cuenta todo; en el resto, solo los laborables.
    cuentan = list(days) if natural else [d for d in days if _vacation_day_counts(d, holidays)]
    if not cuentan:
        return "Los días marcados son todos fines de semana o festivos: no hay nada que pedir.", None

    pisados = _vacation_taken_days(session_db, user_id, days, exclude_request_id=exclude_request_id)
    pisados_utiles = sorted(pisados) if natural else sorted([d for d in pisados if _vacation_day_counts(d, holidays)])
    if pisados_utiles:
        muestra = ", ".join(d.strftime("%d/%m") for d in pisados_utiles[:5])
        resto = f" y {len(pisados_utiles) - 5} más" if len(pisados_utiles) > 5 else ""
        return f"Ya tienes pedidos o aprobados estos días: {muestra}{resto}.", None

    # ⚠️ SIN CONTRATO no se BLOQUEA: no se sabe cuántos días le corresponden, así que no se puede
    # aplicar el tope, pero apuntar y pedir días tiene que seguir funcionando (si no, no se podía
    # meter en el sistema lo ya disfrutado). La advertencia la dan las pantallas.
    # Un EXTRA tiene su propio tope: sus días, y ya está (no depende del contrato).
    if extra:
        if not ignore_balance:
            saldo_extra = next((e for e in _vacation_balance(session_db, user_id, year, profile=profile)["extras"]
                                if e["id"] == extra["id"]), None)
            disponibles_extra = (saldo_extra or {}).get("remaining", extra["days"])
            if exclude_request_id:
                try:
                    previa = session_db.get(VacationRequest, _safe_uuid(exclude_request_id))
                    if previa and (previa.status or "").upper() in VACATION_LIVE_STATUSES and previa.year == year \
                            and (previa.extra_id or "") == extra["id"]:
                        disponibles_extra += int(previa.days_count or 0)
                except Exception:
                    pass
            if len(cuentan) > disponibles_extra:
                return (f"«{extra['label']}» son {extra['days']} día{'' if extra['days'] == 1 else 's'}"
                        f"{' naturales' if natural else ''} y ya solo queda{'' if disponibles_extra == 1 else 'n'} "
                        f"{disponibles_extra}: has marcado {len(cuentan)}."), None
        return None, {"solapes": _vacation_overlaps(session_db, user_id, cuentan),
                      "cuentan": len(cuentan), "sin_contrato": False, "extra": extra}

    saldo_previo = _vacation_balance(session_db, user_id, year, profile=profile) if kind == "VACACIONES" else None
    if not ignore_balance and kind == "VACACIONES" and saldo_previo["has_contract"]:
        saldo = saldo_previo
        disponibles = saldo["remaining"]
        if exclude_request_id:
            # Al EDITAR, los días de la propia petición vuelven al saldo.
            try:
                previa = session_db.get(VacationRequest, _safe_uuid(exclude_request_id))
                if previa and (previa.status or "").upper() in VACATION_LIVE_STATUSES and previa.year == year:
                    disponibles += int(previa.days_count or 0)
            except Exception:
                pass
        if len(cuentan) > disponibles:
            return (f"Has marcado {len(cuentan)} día{'' if len(cuentan) == 1 else 's'} y solo te "
                    f"queda{'' if disponibles == 1 else 'n'} {disponibles}."), None

    return None, {"solapes": _vacation_overlaps(session_db, user_id, cuentan), "cuentan": len(cuentan),
                  "sin_contrato": bool(saldo_previo and not saldo_previo["has_contract"])}


def _vacation_notify_managers(session_db, req) -> None:
    """Aviso a dirección y a quien gestione las vacaciones de que hay una petición nueva."""
    try:
        prof = session_db.get(UserProfile, req.user_id)
        quien = (getattr(prof, "nick", None) or "Alguien").strip()
        meta = VACATION_KINDS[_vacation_kind(getattr(req, "kind", None))]
        dias = [d.day for d in (req.days or []) if d.day] or []
        n = int(req.days_count or 0)
        cuerpo = f"{n} {meta['singular'] if n == 1 else meta['plural']} · {_vacation_range_label(dias)}"
        if (req.note or "").strip():
            cuerpo += f" · {(req.note or '').strip()}"
        _notify_users(session_db, _vacation_manager_user_ids(session_db), "VACACIONES",
                      f"{quien} pide {meta['label'].lower()}", cuerpo,
                      url_for("vacaciones_view", tab="peticiones"),
                      ref_type="vacation_request", ref_id=str(req.id))
    except Exception:
        app.logger.exception("[vacaciones] no se pudo avisar de la petición a quien la aprueba")


