@app.get("/mis-vacaciones", endpoint="mis_vacaciones_view")
@admin_required
def mis_vacaciones_view():
    estado = _current_user_state() or {}
    uid = estado.get("user_id")
    if not uid:
        return redirect(url_for("admin_login"))
    try:
        year = int(request.args.get("anio") or today_local().year)
    except Exception:
        year = today_local().year

    session_db = db()
    try:
        profile = session_db.get(UserProfile, _safe_uuid(uid))
        contratos = _user_contract_rows(session_db, uid)
        saldo = _vacation_balance(session_db, uid, year, profile=profile, contracts=contratos)
        peticiones = _vacation_request_rows(session_db, user_id=uid)
        payload = _vacation_calendar_payload(session_db, year, user_ids=[str(uid)])
        años = sorted({p["year"] for p in peticiones} | {year, today_local().year}, reverse=True)
        return render_template(
            "mis_vacaciones.html",
            year=year, years=años, balance=saldo, requests=peticiones,
            calendar_payload=payload, rules_text=_vacation_rules_text(),
            month_names=VACATION_MONTH_NAMES,
            can_manage=_can_manage_vacations(),
            status_meta=VACATION_STATUS_META,
            vacation_kinds=VACATION_KINDS,
        )
    finally:
        session_db.close()


@app.post("/mis-vacaciones/solicitar", endpoint="mis_vacaciones_request")
@admin_required
def mis_vacaciones_request():
    estado = _current_user_state() or {}
    uid = estado.get("user_id")
    if not uid:
        return redirect(url_for("admin_login"))
    kind = _vacation_kind(request.form.get("kind"))
    meta = VACATION_KINDS[kind]
    dias = _parse_vacation_days(request.form.get("days"))
    nota = (request.form.get("note") or "").strip() or None
    destino = url_for("mis_vacaciones_view", anio=(dias[0].year if dias else today_local().year))

    # Un DÍA LIBRE se pide diciendo POR QUÉ: es lo que mira quien lo aprueba.
    if meta["needs_reason"] and not nota:
        flash("Para pedir un día libre hay que decir el motivo.", "warning")
        return redirect(destino)

    # ¿Sale de un EXTRA (luna de miel…)? Entonces no toca el saldo de vacaciones y, si el extra es de
    # días NATURALES, cuentan también findes y festivos.
    extra_id = (request.form.get("extra_id") or "").strip() or None

    session_db = db()
    try:
        profile = session_db.get(UserProfile, _safe_uuid(uid))
        error, _info = _vacation_check_request(session_db, uid, dias, kind=kind, extra_id=extra_id,
                                              profile=profile)
        if error:
            flash(error, "warning")
            return redirect(destino)
        extra = _vacation_extra(profile, extra_id) if extra_id else None
        holidays = _vacation_holidays(session_db, dias[0].year, user_id=uid)
        req = VacationRequest(user_id=_safe_uuid(uid), status="PENDING", year=dias[0].year,
                              kind=kind, note=nota, created_by_user_id=_safe_uuid(uid),
                              extra_id=(extra["id"] if extra else None))
        session_db.add(req)
        session_db.flush()
        n = _vacation_apply_days(session_db, req, dias, holidays,
                                 natural=bool(extra and extra["natural"]))
        session_db.commit()
        _vacation_notify_managers(session_db, req)
        session_db.commit()
        flash(f"Pedido{'' if n == 1 else 's'} {n} {meta['singular'] if n == 1 else meta['plural']}. "
              "Queda a la espera del visto bueno.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudieron pedir las vacaciones: {e}", "danger")
    finally:
        session_db.close()
    return redirect(destino)


@app.post("/mis-vacaciones/<request_id>/anular", endpoint="mis_vacaciones_cancel")
@admin_required
def mis_vacaciones_cancel(request_id):
    """Anular una petición de días.

    ⚠️ **NADIE toca sus propios días**: ni los anula ni los edita ni los borra. Eso solo lo hace quien
    GESTIONA las vacaciones (la responsabilidad «VACACIONES», administración) y DIRECCIÓN
    —`_can_manage_vacations`—, que además pueden editarlas y eliminarlas desde el cuadrante. Aquí se
    comprueba en el SERVIDOR, no solo escondiendo el botón."""
    estado = _current_user_state() or {}
    uid = estado.get("user_id")
    if not _can_manage_vacations():
        flash("Tus días no los puedes anular tú: pídeselo a quien lleva las vacaciones.", "warning")
        return redirect(url_for("mis_vacaciones_view"))
    session_db = db()
    try:
        req = session_db.get(VacationRequest, to_uuid(request_id))
        if not req:
            flash("Petición no encontrada.", "warning")
            return redirect(url_for("mis_vacaciones_view"))
        if (req.status or "").upper() == "APPROVED":
            flash("Ya está aprobada: quítala desde el cuadrante de Vacaciones.", "warning")
            return redirect(url_for("mis_vacaciones_view", anio=req.year))
        req.status = "CANCELLED"
        req.updated_at = datetime.now(TZ_MADRID)
        session_db.commit()
        flash("Petición anulada.", "info")
        return redirect(url_for("mis_vacaciones_view", anio=req.year))
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo anular: {e}", "danger")
        return redirect(url_for("mis_vacaciones_view"))
    finally:
        session_db.close()


@app.post("/mis-vacaciones/comprobar", endpoint="mis_vacaciones_check")
@admin_required
def mis_vacaciones_check():
    """Comprobación EN VIVO mientras se marcan días en el calendario (contador y solapes)."""
    estado = _current_user_state() or {}
    uid = estado.get("user_id")
    cuerpo = request.get_json(silent=True) or {}
    dias = _parse_vacation_days(cuerpo.get("days") or request.form.get("days"))
    kind = _vacation_kind(cuerpo.get("kind") or request.form.get("kind"))
    session_db = db()
    try:
        error, info = _vacation_check_request(session_db, uid, dias, kind=kind)
        saldo = _vacation_balance(session_db, uid, dias[0].year if dias else today_local().year)
        return jsonify({
            "ok": not error, "error": error,
            "counting": (info or {}).get("cuentan", 0),
            "remaining": saldo["remaining"],
            "overlaps": [{"nick": o["nick"], "photo_url": o["photo_url"], "count": o["count"]}
                         for o in ((info or {}).get("solapes") or [])],
        })
    finally:
        session_db.close()


# ---------------------------------------------------------------------------
# VACACIONES · la sección de gestión (dirección + quien la lleve)
# ---------------------------------------------------------------------------

@app.get("/vacaciones", endpoint="vacaciones_view")
@admin_required
def vacaciones_view():
    if not _can_manage_vacations():
        return forbid("No tienes acceso a la gestión de vacaciones.")
    hoy = today_local()
    try:
        year = int(request.args.get("anio") or hoy.year)
    except Exception:
        year = hoy.year
    try:
        month = max(1, min(12, int(request.args.get("mes") or hoy.month)))
    except Exception:
        month = hoy.month
    tab = (request.args.get("tab") or "calendario").strip().lower()
    # ⚠️ Una pestaña nueva hay que añadirla a esta lista blanca: si no, cae en «calendario» y sale
    # marcada pero se pinta otra cosa (el mismo tropiezo que en Discográfica).
    if tab not in {"calendario", "peticiones", "festivos", "cuadrante"}:
        tab = "calendario"
    filtro_uid = (request.args.get("persona") or "").strip()

    session_db = db()
    try:
        uids = _vacation_office_user_ids(session_db)
        perfiles = {}
        if uids:
            for prof in (session_db.query(UserProfile)
                         .filter(UserProfile.user_id.in_([to_uuid(u) for u in uids]))
                         .order_by(UserProfile.nick.asc()).all()):
                perfiles[str(prof.user_id)] = prof
        contratos_por_uid = {}
        try:
            for c in session_db.query(UserContract).all():
                contratos_por_uid.setdefault(str(c.user_id), []).append(c)
        except Exception:
            pass

        personas = []
        for i, uid in enumerate(uids):
            prof = perfiles.get(uid)
            if not prof:
                continue
            fila = _vacation_person_row(session_db, prof, year, contracts=contratos_por_uid.get(uid, []))
            fila["color"] = _vacation_color_for(i)
            personas.append(fila)
        personas.sort(key=lambda p: (p["nick"] or "").casefold())

        pendientes = _vacation_request_rows(session_db, statuses=["PENDING"])
        historico = _vacation_request_rows(session_db, statuses=["APPROVED", "REJECTED", "CANCELLED"],
                                           year=year, limit=200)
        seleccion = [filtro_uid] if (filtro_uid and filtro_uid in {p["user_id"] for p in personas}) else None
        payload = _vacation_calendar_payload(session_db, year, user_ids=seleccion)
        payload["people"] = [{"user_id": p["user_id"], "nick": p["nick"], "photo_url": p["photo_url"],
                              "color": p["color"]} for p in personas]

        festivos = []
        _nick_por_uid = {p["user_id"]: p["nick"] for p in personas}
        for d, meta in sorted(_vacation_holidays(session_db, year).items()):
            # A quién se le aplica: solo los NO LABORABLES pueden ser de unas personas concretas.
            _suyos = [str(x) for x in (meta.get("user_ids") or []) if str(x or "").strip()]
            festivos.append({"day": d, "name": meta["name"], "scope": meta["scope"],
                             "scope_label": VACATION_HOLIDAY_SCOPES.get(meta["scope"], ""),
                             "people_label": (", ".join([_nick_por_uid.get(u, "?") for u in _suyos])
                                              if _suyos else ""),
                             "people_count": len(_suyos)})
        festivo_ids = {}
        try:
            for row in (session_db.query(Holiday)
                        .filter(Holiday.region == VACATION_REGION)
                        .filter(Holiday.day >= date(year, 1, 1))
                        .filter(Holiday.day <= date(year, 12, 31)).all()):
                festivo_ids[row.day] = str(row.id)
        except Exception:
            pass
        for f in festivos:
            f["id"] = festivo_ids.get(f["day"], "")

        # CUADRANTE: el listado de TODAS las vacaciones y días libres que ocupan días (a la izquierda)
        # y el calendario (a la derecha). Con `?persona=`, solo los de esa persona.
        cuadrante = []
        if tab == "cuadrante":
            cuadrante = _vacation_request_rows(
                session_db, user_id=(seleccion[0] if seleccion else None),
                statuses=list(VACATION_LIVE_STATUSES), year=year)
            cuadrante.sort(key=lambda r: (r["first_day"] or date(year, 12, 31)))

        # COMUNICAR un día no laborable recién marcado: se ofrece al volver del alta (`?comunicar=`),
        # con los afectados ya puestos y el texto estándar (que se puede cambiar).
        comunicar = None
        crudo = (request.args.get("comunicar") or "").strip()
        if crudo:
            dias_com = _parse_vacation_days(crudo)
            if dias_com:
                afectados = set()
                todos = False
                for fila in (session_db.query(Holiday)
                             .filter(Holiday.region == VACATION_REGION)
                             .filter(Holiday.day.in_(dias_com)).all()):
                    suyos = [str(x) for x in (getattr(fila, "user_ids", None) or []) if str(x or "").strip()]
                    if suyos:
                        afectados.update(suyos)
                    else:
                        todos = True          # sin lista = a toda la oficina
                if todos:
                    afectados = {str(u) for u in _vacation_office_user_ids(session_db)}
                comunicar = {
                    "days": ",".join(d.isoformat() for d in dias_com),
                    "days_label": _vacation_range_label(dias_com),
                    "user_ids": sorted(afectados),
                    "text": _vacation_nonworking_text(dias_com),
                }

        años = sorted({year, hoy.year, hoy.year + 1, hoy.year - 1}, reverse=True)
        return render_template(
            "vacaciones.html",
            tab=tab, year=year, month=month, years=años, people=personas,
            comunicar=comunicar,
            quadrant=cuadrante,
            quadrant_person=next((p for p in personas if seleccion and p["user_id"] == seleccion[0]), None),
            pending=pendientes, history=historico, calendar_payload=payload,
            holidays=festivos, holiday_scopes=VACATION_HOLIDAY_SCOPES,
            rules_text=_vacation_rules_text(), month_names=VACATION_MONTH_NAMES,
            filter_user_id=filtro_uid, status_meta=VACATION_STATUS_META,
            days_per_year_default=VACATION_DAYS_PER_YEAR,
            vacation_kinds=VACATION_KINDS,
            vacation_extra_presets=VACATION_EXTRA_PRESETS,
        )
    finally:
        session_db.close()


@app.post("/vacaciones/peticion/<request_id>/decidir", endpoint="vacation_request_decide")
@admin_required
def vacation_request_decide(request_id):
    if not _can_manage_vacations():
        return forbid("No puedes aprobar ni rechazar vacaciones.")
    decision = (request.form.get("decision") or "").strip().upper()
    if decision not in {"APPROVED", "REJECTED"}:
        flash("Decisión no válida.", "warning")
        return redirect(url_for("vacaciones_view", tab="peticiones"))
    nota = (request.form.get("decision_note") or "").strip() or None

    session_db = db()
    try:
        req = session_db.get(VacationRequest, to_uuid(request_id))
        if not req:
            flash("Petición no encontrada.", "warning")
            return redirect(url_for("vacaciones_view", tab="peticiones"))
        # Al APROBAR se vuelve a mirar el saldo: entre que se pidió y ahora puede haber cambiado.
        # (Un DÍA LIBRE no sale de esa bolsa, así que ahí no hay nada que comprobar.)
        # ⚠️ Los días de un EXTRA (luna de miel…) tienen su propia bolsa, ya comprobada al pedirlos:
        # medirlos contra el saldo de vacaciones lo dejaría sin poder aprobar.
        if decision == "APPROVED" and _vacation_kind(req.kind) == "VACACIONES" and not (req.extra_id or ""):
            saldo = _vacation_balance(session_db, req.user_id, req.year)
            # Los días de ESTA petición ya están contados como «pendientes»: no se descuentan dos veces.
            libres = saldo["remaining"] + int(req.days_count or 0)
            if int(req.days_count or 0) > libres:
                flash(f"No se puede aprobar: pide {req.days_count} días y solo le quedan {libres}.", "warning")
                return redirect(url_for("vacaciones_view", tab="peticiones"))
        req.status = decision
        req.decision_note = nota
        req.decided_by_user_id = _safe_uuid((_current_user_state() or {}).get("user_id"))
        req.decided_at = datetime.now(TZ_MADRID)
        req.updated_at = req.decided_at
        # Decidida: el aviso de «tienes una petición por aprobar» deja de esperar a nadie (también
        # a los DEMÁS que gestionan vacaciones, que si no seguirían viéndolo pendiente).
        _notify_resolve(session_db, "vacation_request", req.id)
        session_db.commit()

        # Aviso a quien lo pidió, por los DOS canales y con el mismo diseño (ver
        # `_vacation_notice_send`). Solo se avisa al APROBAR o al RECHAZAR.
        dias = [d.day for d in (req.days or []) if d.day]
        es_libre = _vacation_kind(req.kind) == "DIA_LIBRE"
        if decision == "APPROVED":
            tipo_aviso = "DIA_LIBRE_OK" if es_libre else "VACACIONES_OK"
        else:
            tipo_aviso = "DIA_LIBRE_NO" if es_libre else "VACACIONES_NO"
        _vacation_notice_send(session_db, tipo_aviso, req.user_id, dias,
                              note=(nota or ""), year=req.year, ref_id=req.id)
        session_db.commit()
        flash("Vacaciones aprobadas." if decision == "APPROVED" else "Vacaciones rechazadas.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo guardar la decisión: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("vacaciones_view", tab="peticiones"))


@app.post("/vacaciones/persona/<user_id>/configurar", endpoint="vacation_person_config")
@admin_required
def vacation_person_config(user_id):
    if not _can_manage_vacations():
        return forbid("No puedes configurar las vacaciones de nadie.")
    try:
        year = int(request.form.get("anio") or today_local().year)
    except Exception:
        year = today_local().year
    session_db = db()
    try:
        prof = session_db.get(UserProfile, to_uuid(user_id))
        if not prof:
            flash("Persona no encontrada.", "warning")
            return redirect(url_for("vacaciones_view", anio=year))
        crudo = (request.form.get("days_per_year") or "").strip()
        if crudo == "":
            prof.vacation_days_per_year = None      # vuelve a los días de la casa
        else:
            try:
                prof.vacation_days_per_year = max(0, min(365, int(crudo)))
            except Exception:
                flash("Los días al año tienen que ser un número.", "warning")
                return redirect(url_for("vacaciones_view", anio=year))
        ajuste_crudo = (request.form.get("adjustment") or "").strip()
        ajustes = dict(getattr(prof, "vacation_adjustments", None) or {})
        if ajuste_crudo in ("", "0"):
            ajustes.pop(str(year), None)
        else:
            try:
                ajustes[str(year)] = int(ajuste_crudo)
            except Exception:
                flash("El ajuste tiene que ser un número (puede ser negativo).", "warning")
                return redirect(url_for("vacaciones_view", anio=year))
        prof.vacation_adjustments = ajustes
        # EXTRAS (luna de miel y los que se hayan añadido): solo de esta persona.
        if request.form.get("extras_present"):
            prof.vacation_extras = _parse_vacation_extras_form(request.form)
        session_db.commit()
        flash("Vacaciones actualizadas.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo guardar: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("vacaciones_view", anio=year))


@app.post("/vacaciones/persona/<user_id>/dias", endpoint="vacation_person_days")
@admin_required
def vacation_person_days(user_id):
    """Administración/dirección apunta días directamente (ya aprobados): correcciones, días
    acordados de palabra, arrastres… No pasa por el visto bueno porque LO ESTÁ DANDO quien lo mete."""
    if not _can_manage_vacations():
        return forbid("No puedes apuntar vacaciones de nadie.")
    kind = _vacation_kind(request.form.get("kind"))
    meta = VACATION_KINDS[kind]
    dias = _parse_vacation_days(request.form.get("days"))
    nota = (request.form.get("note") or "").strip() or None
    year = dias[0].year if dias else today_local().year
    extra_id = (request.form.get("extra_id") or "").strip() or None
    session_db = db()
    try:
        prof = session_db.get(UserProfile, to_uuid(user_id))
        error, _info = _vacation_check_request(session_db, user_id, dias, kind=kind,
                                               ignore_balance=bool(request.form.get("force")),
                                               extra_id=extra_id, profile=prof)
        if error:
            flash(error, "warning")
            return redirect(url_for("vacaciones_view", anio=year))
        extra = _vacation_extra(prof, extra_id) if extra_id else None
        holidays = _vacation_holidays(session_db, year, user_id=user_id)
        ahora = datetime.now(TZ_MADRID)
        actor = _safe_uuid((_current_user_state() or {}).get("user_id"))
        req = VacationRequest(user_id=to_uuid(user_id), status="APPROVED", year=year, kind=kind,
                              note=nota, created_by_user_id=actor, decided_by_user_id=actor,
                              decided_at=ahora, extra_id=(extra["id"] if extra else None))
        session_db.add(req)
        session_db.flush()
        n = _vacation_apply_days(session_db, req, dias, holidays,
                                 natural=bool(extra and extra["natural"]))
        session_db.commit()
        # ⚠️ Apuntar días es meter en el sistema lo que YA se disfrutó (o lo acordado de palabra):
        # no se avisa. Para conceder un día libre y que la persona se entere está
        # `vacation_grant_free_day`.
        flash(f"Apuntado{'' if n == 1 else 's'} {n} {meta['singular'] if n == 1 else meta['plural']}.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo apuntar: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("vacaciones_view", anio=year))


@app.post("/vacaciones/peticion/<request_id>/eliminar", endpoint="vacation_request_delete")
@admin_required
def vacation_request_delete(request_id):
    if not _can_manage_vacations():
        return forbid("No puedes eliminar vacaciones.")
    session_db = db()
    year = today_local().year
    try:
        req = session_db.get(VacationRequest, to_uuid(request_id))
        if not req:
            flash("Petición no encontrada.", "warning")
            return redirect(url_for("vacaciones_view"))
        year = req.year
        uid, dias = req.user_id, [d.day for d in (req.days or []) if d.day]
        session_db.delete(req)
        session_db.commit()
        _notify_user(session_db, uid, "VACACIONES", "Vacaciones eliminadas",
                     _vacation_range_label(dias), url_for("mis_vacaciones_view", anio=year),
                     ref_type="vacation_request", ref_id=str(request_id))
        session_db.commit()
        flash("Días eliminados.", "info")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo eliminar: {e}", "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or url_for("vacaciones_view", anio=year))


@app.post("/vacaciones/peticion/<request_id>/dias", endpoint="vacation_request_days_edit")
@admin_required
def vacation_request_days_edit(request_id):
    """EDITAR los días de unas vacaciones o de un día libre ya apuntados (desde el cuadrante).

    Se vuelven a elegir sobre el calendario y se reemplazan: `_vacation_apply_days` borra los de antes
    y recalcula cuáles CUENTAN (findes y festivos de esa persona no restan). Las normas se comprueban
    igual que al pedirlos, pero **sin contarse a sí misma** (`exclude_request_id`): si no, cualquier
    edición chocaría con sus propios días."""
    if not _can_manage_vacations():
        return forbid("No puedes editar vacaciones.")
    dias = _parse_vacation_days(request.form.get("days"))
    destino = request.form.get("next") or url_for("vacaciones_view", tab="cuadrante")
    session_db = db()
    try:
        req = session_db.get(VacationRequest, to_uuid(request_id))
        if not req:
            flash("Petición no encontrada.", "warning")
            return redirect(destino)
        if not dias:
            flash("No has marcado ningún día: si lo que quieres es quitarlos, usa «Eliminar».", "warning")
            return redirect(destino)
        prof = session_db.get(UserProfile, req.user_id)
        error, _info = _vacation_check_request(session_db, req.user_id, dias, kind=req.kind,
                                              exclude_request_id=req.id,
                                              ignore_balance=bool(request.form.get("force")),
                                              extra_id=(req.extra_id or None), profile=prof)
        if error:
            flash(error, "warning")
            return redirect(destino)
        # Si los días salen de un EXTRA, se sigue contando como ese extra (naturales si lo es).
        extra = _vacation_extra(prof, req.extra_id) if (req.extra_id or "") else None
        holidays = _vacation_holidays(session_db, dias[0].year, user_id=req.user_id)
        req.year = dias[0].year
        n = _vacation_apply_days(session_db, req, dias, holidays,
                                 natural=bool(extra and extra["natural"]))
        uid = req.user_id
        session_db.commit()
        _notify_user(session_db, uid, "VACACIONES", "Días cambiados",
                     _vacation_range_label(dias), url_for("mis_vacaciones_view", anio=req.year),
                     ref_type="vacation_request", ref_id=str(request_id))
        session_db.commit()
        flash(f"Días actualizados: {n} {'día' if n == 1 else 'días'} que cuentan.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudieron cambiar los días: {e}", "danger")
    finally:
        session_db.close()
    return redirect(destino)


@app.post("/vacaciones/peticion/<request_id>/a-no-laborable", endpoint="vacation_request_to_nonworking")
@admin_required
def vacation_request_to_nonworking(request_id):
    """Pasar unos días apuntados a **día libre NO LABORABLE** de esa persona.

    Deja de ser un día suyo (le vuelve al saldo: se borra la petición) y pasa a ser un día en el que
    no se trabaja, apuntado en `Holiday` con ámbito EMPRESA y **solo para ella** (`user_ids`), que es
    exactamente lo que hace «marcar días no laborables» pero para una persona.
    ⚠️ Los días que YA eran festivos no se tocan (no vamos a renombrar el 25 de diciembre)."""
    if not _can_manage_vacations():
        return forbid("No puedes marcar días no laborables.")
    destino = request.form.get("next") or url_for("vacaciones_view", tab="cuadrante")
    nombre = (request.form.get("name") or "").strip() or "No laborable"
    session_db = db()
    try:
        req = session_db.get(VacationRequest, to_uuid(request_id))
        if not req:
            flash("Petición no encontrada.", "warning")
            return redirect(destino)
        uid = req.user_id
        year = req.year
        dias = sorted({d.day for d in (req.days or []) if d.day})
        if not dias:
            flash("Esa petición no tiene días.", "warning")
            return redirect(destino)
        nuevos = pisados = 0
        for day in dias:
            fila = (session_db.query(Holiday)
                    .filter(Holiday.day == day)
                    .filter(Holiday.region == VACATION_REGION).first())
            if fila:
                pisados += 1
                continue
            session_db.add(Holiday(day=day, name=nombre, scope="EMPRESA", region=VACATION_REGION,
                                   user_ids=[str(uid)]))
            nuevos += 1
        # La petición desaparece: esos días ya no salen de su saldo.
        session_db.delete(req)
        session_db.commit()
        _vacation_notice_send(session_db, "NO_LABORABLE", str(uid), dias,
                              note=nombre if nombre != "No laborable" else "",
                              year=year, ref_id=dias[0].isoformat())
        session_db.commit()
        flash(f"{nuevos} día{'' if nuevos == 1 else 's'} pasado{'' if nuevos == 1 else 's'} a no "
              "laborable" + ("" if nuevos == 1 else "s") + " y avisada la persona." +
              (f" {pisados} ya eran festivos." if pisados else ""), "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo pasar a no laborable: {e}", "danger")
    finally:
        session_db.close()
    return redirect(destino)


@app.post("/vacaciones/normas", endpoint="vacation_rules_save")
@admin_required
def vacation_rules_save():
    if not _can_manage_vacations():
        return forbid("No puedes cambiar las normas de vacaciones.")
    texto = (request.form.get("rules_text") or "").strip()
    _set_app_setting(VACATION_RULES_SETTING, texto)
    flash("Normas guardadas.", "success")
    return redirect(url_for("vacaciones_view", tab="festivos"))


@app.post("/vacaciones/festivos", endpoint="vacation_holiday_save")
@admin_required
def vacation_holiday_save():
    if not _can_manage_vacations():
        return forbid("No puedes tocar el calendario de festivos.")
    day = parse_optional_date(request.form.get("day"))
    nombre = (request.form.get("name") or "").strip()
    scope = (request.form.get("scope") or "NACIONAL").strip().upper()
    if scope not in VACATION_HOLIDAY_SCOPES:
        scope = "NACIONAL"
    year = day.year if day else today_local().year
    if not day or not nombre:
        flash("Hacen falta la fecha y el nombre del festivo.", "warning")
        return redirect(url_for("vacaciones_view", tab="festivos", anio=year))
    session_db = db()
    try:
        fila = (session_db.query(Holiday)
                .filter(Holiday.day == day)
                .filter(Holiday.region == VACATION_REGION).first())
        if fila:
            fila.name, fila.scope = nombre, scope
        else:
            session_db.add(Holiday(day=day, name=nombre, scope=scope, region=VACATION_REGION))
        session_db.commit()
        flash("Festivo guardado.", "success")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo guardar el festivo: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("vacaciones_view", tab="festivos", anio=year))


@app.get("/vacaciones/aviso/<kind>/<path:ref_id>", endpoint="vacation_notice_view")
@admin_required
def vacation_notice_view(kind, ref_id):
    """La página que se abre al pinchar el aviso: EXACTAMENTE el mismo HTML que se mandó por correo.

    Se reconstruye con los datos de hoy (no se congela) porque lo que enseña —las fechas y los
    totales del año— es justo lo que la persona quiere ver al día."""
    tipo = (kind or "").strip().upper()
    if tipo not in VACATION_NOTICE_TYPES:
        abort(404)
    estado = _current_user_state() or {}
    yo = estado.get("user_id")

    session_db = db()
    try:
        if tipo == "NO_LABORABLE":
            try:
                dia = date.fromisoformat((ref_id or "").strip())
            except Exception:
                abort(404)
            ctx = _vacation_notice_context(session_db, tipo, yo, [dia], year=dia.year)
        else:
            req = session_db.get(VacationRequest, _safe_uuid(ref_id))
            if not req:
                abort(404)
            # Los días de otra persona solo los ve ella (y quien gestiona / dirección).
            if str(req.user_id) != str(yo) and not _can_manage_vacations():
                return forbid("Este aviso no es tuyo.")
            dias = [d.day for d in (req.days or []) if d.day]
            ctx = _vacation_notice_context(session_db, tipo, req.user_id, dias,
                                           note=(req.decision_note or req.note or ""), year=req.year)
        return _vacation_notice_html(ctx)
    finally:
        session_db.close()


@app.post("/vacaciones/conceder-dia-libre", endpoint="vacation_grant_free_day")
@admin_required
def vacation_grant_free_day():
    """CONCEDER un día libre: la empresa se lo regala a una o varias personas.

    A diferencia de «apuntar días» (que es meter en el sistema lo ya disfrutado), esto SÍ se
    comunica: se les manda el aviso de enhorabuena por correo y por la app."""
    if not _can_manage_vacations():
        return forbid("No puedes conceder días libres.")
    dias = _parse_vacation_days(request.form.get("days"))
    uids = [u for u in (request.form.getlist("user_ids") or []) if _safe_uuid(u)]
    nota = (request.form.get("note") or "").strip() or None
    year = dias[0].year if dias else today_local().year
    if not dias or not uids:
        flash("Hay que elegir a quién se le concede y qué días.", "warning")
        return redirect(url_for("vacaciones_view", anio=year))

    session_db = db()
    try:
        ahora = datetime.now(TZ_MADRID)
        actor = _safe_uuid((_current_user_state() or {}).get("user_id"))
        concedidos, saltados = 0, []
        for uid in uids:
            # Los festivos son POR PERSONA (un no laborable puede ser solo de unas cuantas), así que
            # lo que «cuenta» se decide con los suyos.
            holidays = _vacation_holidays(session_db, year, user_id=uid)
            # Si ya tiene esos días pedidos o aprobados, se le salta (no se duplican).
            pisados = _vacation_taken_days(session_db, uid, dias)
            libres = [d for d in dias if d not in pisados]
            if not libres:
                prof = session_db.get(UserProfile, _safe_uuid(uid))
                saltados.append((getattr(prof, "nick", None) or "?").strip())
                continue
            req = VacationRequest(user_id=_safe_uuid(uid), status="APPROVED", year=year,
                                  kind="DIA_LIBRE", note=nota, created_by_user_id=actor,
                                  decided_by_user_id=actor, decided_at=ahora)
            session_db.add(req)
            session_db.flush()
            _vacation_apply_days(session_db, req, libres, holidays)
            session_db.commit()
            _vacation_notice_send(session_db, "DIA_LIBRE_REGALO", uid, libres,
                                  note=nota or "", year=year, ref_id=req.id)
            session_db.commit()
            concedidos += 1
        if concedidos:
            flash(f"Día libre concedido a {concedidos} persona{'' if concedidos == 1 else 's'} "
                  "y avisada" + ("" if concedidos == 1 else "s") + ".", "success")
        if saltados:
            flash("Ya tenían esos días: " + ", ".join(saltados) + ".", "info")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo conceder: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("vacaciones_view", anio=year))


@app.post("/vacaciones/no-laborables", endpoint="vacation_nonworking_save")
@admin_required
def vacation_nonworking_save():
    """Marca UNO O VARIOS días como NO LABORABLES de la oficina (puente, cierre por mudanza…).

    No consumen vacaciones y no se trabaja: a efectos de contar es exactamente lo mismo que un
    festivo, así que se guardan en la misma tabla con el ámbito EMPRESA y heredan gratis el
    calendario, el cómputo del saldo y el «no cuenta» de `_vacation_day_counts`."""
    if not _can_manage_vacations():
        return forbid("No puedes marcar días no laborables.")
    dias = _parse_vacation_days(request.form.get("days"))
    nombre = (request.form.get("name") or "").strip() or "No laborable"
    year = dias[0].year if dias else today_local().year
    if not dias:
        flash("No has marcado ningún día.", "warning")
        return redirect(url_for("vacaciones_view", tab="festivos", anio=year))

    session_db = db()
    try:
        # A QUIÉN SE LE APLICA: a toda la oficina o solo a las personas elegidas. Con una selección,
        # el día solo les afecta y solo les sale a ellas (`Holiday.user_ids`); vacío = a todos.
        solo_algunos = (request.form.get("who") or "ALL").strip().upper() == "SOME"
        elegidos = []
        if solo_algunos:
            # Se guardan en su forma canónica (la misma con la que se comparan después) y solo si
            # son personal vivo de la oficina.
            validos = {str(v) for v in _vacation_office_user_ids(session_db)}
            elegidos = [str(_safe_uuid(u)) for u in request.form.getlist("user_ids")
                        if _safe_uuid(u) and str(_safe_uuid(u)) in validos]
            if not elegidos:
                flash("Has dicho que es solo para algunas personas pero no has elegido a nadie.", "warning")
                return redirect(url_for("vacaciones_view", tab="festivos", anio=year))
        nuevos = pisados = 0
        for day in dias:
            fila = (session_db.query(Holiday)
                    .filter(Holiday.day == day)
                    .filter(Holiday.region == VACATION_REGION).first())
            if fila:
                # Ya era festivo: no se toca (no vamos a renombrar el 25 de diciembre).
                pisados += 1
                continue
            session_db.add(Holiday(day=day, name=nombre, scope="EMPRESA", region=VACATION_REGION,
                                   user_ids=elegidos))
            nuevos += 1
        session_db.commit()
        marcados = [d for d in dias if d]
        if nuevos:
            flash(f"Marcado{'' if nuevos == 1 else 's'} {nuevos} día{'' if nuevos == 1 else 's'} "
                  "como no laborable" + ("" if nuevos == 1 else "s") + ".", "success")
        if pisados:
            flash(f"{pisados} de los días marcados ya eran festivos y se han dejado como estaban.", "info")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudieron marcar: {e}", "danger")
        return redirect(url_for("vacaciones_view", tab="festivos", anio=year))
    finally:
        session_db.close()
    # ⚠️ Al guardar YA NO se avisa a nadie: se ofrece COMUNICARLO (el pop-up sale solo con este
    # parámetro), con los afectados ya puestos y el texto estándar, que se puede cambiar.
    if nuevos:
        return redirect(url_for("vacaciones_view", tab="festivos", anio=year,
                                comunicar=",".join(d.isoformat() for d in marcados)))
    return redirect(url_for("vacaciones_view", tab="festivos", anio=year))


@app.post("/vacaciones/no-laborables/comunicar", endpoint="vacation_nonworking_notify")
@admin_required
def vacation_nonworking_notify():
    """COMUNICA un día no laborable: manda el correo (y el aviso de la app) a quien se diga.

    Los destinatarios vienen marcados —los que tienen ese día— y se puede añadir o quitar a quien
    sea. El texto se puede cambiar; si no se escribe nada, va el estándar."""
    if not _can_manage_vacations():
        return forbid("No puedes comunicar días no laborables.")
    dias = _parse_vacation_days(request.form.get("days"))
    year = dias[0].year if dias else today_local().year
    destino = url_for("vacaciones_view", tab="festivos", anio=year)
    if not dias:
        flash("No hay ningún día que comunicar.", "warning")
        return redirect(destino)
    texto = (request.form.get("message") or "").strip()
    session_db = db()
    try:
        validos = {str(v) for v in _vacation_office_user_ids(session_db)}
        elegidos = [str(_safe_uuid(u)) for u in request.form.getlist("user_ids")
                    if _safe_uuid(u) and str(_safe_uuid(u)) in validos]
        if not elegidos:
            flash("No has dejado a nadie a quien comunicárselo.", "warning")
            return redirect(destino)
        for uid in elegidos:
            _vacation_notice_send(session_db, "NO_LABORABLE", uid, dias, note=texto,
                                  year=year, ref_id=dias[0].isoformat())
        session_db.commit()
        flash("Comunicado a %d persona%s." % (len(elegidos), "" if len(elegidos) == 1 else "s"), "success")
    except Exception as e:
        session_db.rollback()
        flash("No se pudo comunicar: %s" % e, "danger")
    finally:
        session_db.close()
    return redirect(destino)


@app.post("/vacaciones/festivos/<holiday_id>/eliminar", endpoint="vacation_holiday_delete")
@admin_required
def vacation_holiday_delete(holiday_id):
    if not _can_manage_vacations():
        return forbid("No puedes tocar el calendario de festivos.")
    session_db = db()
    year = today_local().year
    try:
        fila = session_db.get(Holiday, to_uuid(holiday_id))
        if fila:
            year = fila.day.year
            session_db.delete(fila)
            session_db.commit()
            flash("Festivo eliminado.", "info")
    except Exception as e:
        session_db.rollback()
        flash(f"No se pudo eliminar: {e}", "danger")
    finally:
        session_db.close()
    return redirect(url_for("vacaciones_view", tab="festivos", anio=year))


