# ============================================================================
# SYNCROS · SUPERVISORES DE SINCRONIZACIÓN
#
# ⚠️ Un supervisor **ES un tercero** (`Promoter`): su nombre, su email, su teléfono, su foto y sus
# documentos viven en su ficha de siempre y aquí NO se duplican. `SyncSupervisor` solo añade la
# FACETA de sincronizaciones (qué tipo de agente es, dónde opera y en qué idiomas), así que el mismo
# tercero se ve en Bases de datos → Terceros y en Syncros → Supervisors, y al darlo de alta aquí se
# reutiliza el que ya exista en vez de crear uno nuevo.
# ============================================================================

SYNC_SUPERVISOR_TYPES = sync_import.SUPERVISOR_TYPES
SYNC_TYPE_LABELS = sync_import.TYPE_LABELS
SYNC_REGION_KINDS = sync_import.REGION_KINDS
SYNC_LANGUAGES = sync_import.LANGUAGES
SYNC_LANGUAGE_LABELS = sync_import.LANGUAGE_LABELS
SYNC_DEFAULT_LANGUAGES = sync_import.DEFAULT_LANGUAGES

# Icono de cada tipo, para la etiqueta del listado.
SYNC_TYPE_ICONS = {
    "MUSIC_SUPERVISOR": "fa-headphones",
    "AD_AGENCY": "fa-lightbulb",
    "AD_PRODUCER": "fa-clapperboard",
}
SYNC_REGION_ICONS = {"GLOBAL": "fa-earth-americas", "LATAM": "fa-globe", "COUNTRY": "fa-flag"}

# Nombre del país (como se escribe aquí o como llega en una importación) -> ISO-3166 alfa-2, para
# poder pintar su BANDERA. Es una ayuda visual: lo que no se reconozca sale con el nombre y su icono.
COUNTRY_ISO2 = {
    "espana": "ES", "spain": "ES", "estados unidos": "US", "eeuu": "US", "usa": "US",
    "united states": "US", "us": "US", "reino unido": "GB", "uk": "GB", "united kingdom": "GB",
    "inglaterra": "GB", "england": "GB", "francia": "FR", "france": "FR", "alemania": "DE",
    "germany": "DE", "italia": "IT", "italy": "IT", "portugal": "PT", "mexico": "MX",
    "argentina": "AR", "colombia": "CO", "chile": "CL", "peru": "PE", "brasil": "BR",
    "brazil": "BR", "uruguay": "UY", "paraguay": "PY", "bolivia": "BO", "ecuador": "EC",
    "venezuela": "VE", "panama": "PA", "costa rica": "CR", "guatemala": "GT", "honduras": "HN",
    "el salvador": "SV", "nicaragua": "NI", "republica dominicana": "DO", "puerto rico": "PR",
    "cuba": "CU", "canada": "CA", "australia": "AU", "nueva zelanda": "NZ", "japon": "JP",
    "japan": "JP", "china": "CN", "corea del sur": "KR", "india": "IN", "irlanda": "IE",
    "paises bajos": "NL", "holanda": "NL", "netherlands": "NL", "belgica": "BE", "suiza": "CH",
    "austria": "AT", "suecia": "SE", "noruega": "NO", "dinamarca": "DK", "finlandia": "FI",
    "polonia": "PL", "grecia": "GR", "turquia": "TR", "marruecos": "MA", "sudafrica": "ZA",
    "israel": "IL", "emiratos arabes unidos": "AE", "rusia": "RU", "ucrania": "UA",
}


def _country_iso2(nombre) -> str:
    """ISO-3166 alfa-2 de un país escrito a mano («España», «USA», «uk»…). '' si no se reconoce."""
    clave = _norm_text_key(re.sub(r"\s+", " ", str(nombre or "").strip()))
    if not clave:
        return ""
    if clave in COUNTRY_ISO2:
        return COUNTRY_ISO2[clave]
    # Ya viene como código de dos letras.
    bruto = str(nombre or "").strip().upper()
    return bruto if (len(bruto) == 2 and bruto.isalpha()) else ""


def _country_flag(nombre) -> str:
    """La BANDERA del país como emoji (los «regional indicator symbols» de su ISO2). '' si no se sabe."""
    iso = _country_iso2(nombre)
    if len(iso) != 2:
        return ""
    return "".join(chr(0x1F1E6 + (ord(c) - 65)) for c in iso)

# Las secciones de la pantalla (Supervisors es la primera).
# ⚠️ «Repertorio» = el repertorio para SYNCRO (antes se llamaba «One-stop», que es solo uno de sus
# filtros: aquí se ve TODO lo que se puede presentar, marcando lo que además es one-stop).
SYNCROS_SECTIONS = [("repertorio", "Repertorio", "fa-compact-disc"),
                    ("supervisors", "Supervisors", "fa-user-tie")]


def can_edit_syncros() -> bool:
    """Quién puede tocar Syncros: su sección, el sello (es material discográfico) o dirección."""
    return (has_access_key("syncros", edit=True, include_descendants=True)
            or can_edit_discografica() or is_master())


def _sync_type_label(value: str) -> str:
    return SYNC_TYPE_LABELS.get((value or "").strip().upper(), "Sin tipo")


def _sync_region_label(kind: str, country: str = "") -> str:
    """Punto único de cómo se escribe una región: «Global» · «Latinoamérica» · el país."""
    k = (kind or "").strip().upper()
    if k == "COUNTRY":
        return (country or "").strip() or "Un país (sin decir cuál)"
    return dict(SYNC_REGION_KINDS).get(k, "Global")


def _sync_languages_clean(values) -> list[str]:
    """Los idiomas que se guardan: del catálogo, sin repetir y en el orden del catálogo."""
    pedidos = set()
    for v in (values or []):
        code = (str(v) or "").strip().upper()
        if code in SYNC_LANGUAGE_LABELS:
            pedidos.add(code)
    return [code for code, _l in SYNC_LANGUAGES if code in pedidos]


def _sync_languages_labels(values) -> list[str]:
    return [SYNC_LANGUAGE_LABELS[c] for c in _sync_languages_clean(values)]


def _sync_supervisor_for_promoter(session_db, promoter_id):
    """La ficha de Syncro de un tercero (o None): es lo que decide si sale en Syncros."""
    pid = to_uuid(str(promoter_id or "")) or None
    if not pid:
        return None
    return (session_db.query(SyncSupervisor)
            .filter(SyncSupervisor.promoter_id == pid).first())


def _sync_supervisor_row(sup, promoter=None, submissions: int = 0) -> dict:
    """Una fila del listado de Supervisors (y la cabecera de su ficha)."""
    p = promoter if promoter is not None else getattr(sup, "promoter", None)
    nombre = _promoter_display_name(p) if p is not None else "Sin nombre"
    correo, telefono = _promoter_email_phone(p) if p is not None else ("", "")
    tipo = (getattr(sup, "sup_type", "") or "").strip().upper()
    return {
        "id": str(sup.id),
        "promoter_id": str(sup.promoter_id),
        "name": nombre,
        "photo": (getattr(p, "logo_url", "") or "").strip() or _default_avatar_url(),
        "email": correo,
        "phone": telefono,
        "type": tipo,
        "type_label": _sync_type_label(tipo),
        "type_icon": SYNC_TYPE_ICONS.get(tipo, "fa-user-tie"),
        "region_kind": (getattr(sup, "region_kind", "") or "GLOBAL").strip().upper(),
        "region_country": (getattr(sup, "region_country", "") or "").strip(),
        "region_flag": _country_flag(getattr(sup, "region_country", "")),
        "region_label": _sync_region_label(getattr(sup, "region_kind", ""), getattr(sup, "region_country", "")),
        "region_icon": SYNC_REGION_ICONS.get((getattr(sup, "region_kind", "") or "GLOBAL").strip().upper(), "fa-flag"),
        "languages": _sync_languages_clean(getattr(sup, "languages", None)),
        "language_labels": _sync_languages_labels(getattr(sup, "languages", None)),
        # En qué idioma se le escribe: «Habla inglés» sale como etiqueta en el listado.
        "comm_lang": ("EN" if (getattr(sup, "comm_lang", "") or "ES").strip().upper() == "EN" else "ES"),
        "notes": (getattr(sup, "notes", "") or "").strip(),
        "submissions": int(submissions or 0),
        "url": url_for("promoter_detail_view", pid=str(sup.promoter_id), tab="syncro"),
    }


# ── ICONOS DE LA CASA EN UN CORREO ────────────────────────────────────────────────────────────
# En un correo NO se pueden usar iconos de fuente (ningún cliente carga Font Awesome), así que el
# MISMO icono sólido se sirve como PNG, renderizado desde la propia fuente de la app
# (`fa-solid-900.ttf`) y en el color de marca. Así el correo y la web enseñan exactamente lo mismo
# y no hacen falta emojis.
_FA_CODEPOINTS: dict[str, str] = {}
_FA_ICON_CACHE: dict[tuple, bytes] = {}


# ── LOGOS SIN FONDO BLANCO ────────────────────────────────────────────────────────────────────
# Muchos logos se suben en PNG con el fondo BLANCO horneado y en la app se ven como un rectángulo
# blanco sobre el fondo gris. `logo_clean_png` los sirve con ese fondo en TRANSPARENTE: solo el
# blanco CONECTADO A LOS BORDES (un relleno desde las cuatro esquinas), así que lo blanco de dentro
# del propio logo —una letra, un hueco— no se toca.
_LOGO_CLEAN_CACHE: dict[str, bytes] = {}
_LOGO_CLEAN_MARK = (255, 0, 254)          # color improbable que marca lo que hay que hacer transparente


def _is_own_media_url(url: str) -> bool:
    """¿Esa imagen es NUESTRA? (nuestro Storage de Supabase o nuestro propio dominio).

    ⚠️ Sin esto, `logo_clean_png` sería un **proxy de imágenes abierto**: cualquiera podría hacer que
    el servidor se descargue lo que quisiera."""
    try:
        destino = urlsplit((url or "").strip())
    except ValueError:
        return False
    if destino.scheme.lower() not in ("http", "https") or not destino.netloc:
        return False
    host = destino.netloc.lower()
    propios = set()
    for candidato in (os.getenv("SUPABASE_URL", "") or "", _public_base_url(),
                      (os.getenv("EXTERNAL_BASE_URL", "") or "")):
        try:
            neto = urlsplit(candidato).netloc.lower()
            if neto:
                propios.add(neto)
        except ValueError:
            pass
    if _CANONICAL_HOST:
        propios.add(_CANONICAL_HOST.lower())
    return host in propios


def _logo_clean_bytes(url: str) -> bytes:
    """El logo de esa URL en PNG con el fondo blanco de los bordes en transparente. b'' si no se puede."""
    clave = (url or "").strip()
    if not clave:
        return b""
    if clave in _LOGO_CLEAN_CACHE:
        return _LOGO_CLEAN_CACHE[clave]
    datos = b""
    try:
        from PIL import Image, ImageDraw
        req = Request(clave, headers={"User-Agent": "Mozilla/5.0"})
        with urlopen(req, timeout=20) as resp:
            crudo = resp.read()
        img = Image.open(BytesIO(crudo)).convert("RGBA")
        rgb = img.convert("RGB")
        w, h = rgb.size
        esquinas = [(0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)]
        tocado = False
        for xy in esquinas:
            px = rgb.getpixel(xy)
            if min(px) < 230:             # esa esquina no es blanca: ahí no hay fondo que quitar
                continue
            ImageDraw.floodfill(rgb, xy, _LOGO_CLEAN_MARK, thresh=28)
            tocado = True
        if tocado:
            alfa = img.getchannel("A")
            marca = rgb.point(lambda v: 0)      # placeholder para no romper si algo falla
            datos_rgb = rgb.load()
            datos_a = alfa.load()
            for y in range(h):
                for x in range(w):
                    if datos_rgb[x, y] == _LOGO_CLEAN_MARK:
                        datos_a[x, y] = 0
            img.putalpha(alfa)
            del marca
        buf = BytesIO()
        img.save(buf, "PNG")
        datos = buf.getvalue()
    except Exception:
        app.logger.exception("[logos] no se pudo limpiar el fondo de %s", clave[:120])
        datos = b""
    _LOGO_CLEAN_CACHE[clave] = datos
    return datos


def _logo_clean_url(url: str) -> str:
    """La URL con la que se pinta un logo de empresa: la nuestra, que le quita el fondo blanco."""
    limpia = (url or "").strip()
    if not limpia:
        return ""
    try:
        return url_for("logo_clean_png", u=limpia)
    except Exception:
        return limpia                     # fuera de una petición (un correo compuesto en un hilo)


@app.get("/logo-limpio.png", endpoint="logo_clean_png")
def logo_clean_png():
    """Sirve un logo con el fondo blanco de los bordes en TRANSPARENTE. Público (va en `<img>`).

    ⚠️ Solo se admiten URLs de NUESTRO almacenamiento o de nuestro dominio: si no, esto sería un
    proxy de imágenes abierto (cualquiera podría hacer que el servidor descargue lo que quisiera)."""
    url = (request.args.get("u") or "").strip()
    if not url:
        abort(404)
    # ⚠️⚠️ Si la imagen NO es nuestra, o no se puede limpiar, se REDIRIGE al original en vez de dar
    # 404: un 404 aquí deja el logo ROTO (el cuadradito con interrogación), y eso es peor que
    # enseñarlo con su fondo. No se descarga nada ajeno, así que sigue sin ser un proxy abierto.
    if not _is_own_media_url(url):
        return redirect(url)
    datos = _logo_clean_bytes(url)
    if not datos:
        return redirect(url)
    resp = make_response(datos)
    resp.headers["Content-Type"] = "image/png"
    resp.headers["Cache-Control"] = "public, max-age=604800"
    return resp


def _fa_codepoints() -> dict:
    """Mapa `nombre de icono -> carácter` leído UNA vez del CSS de Font Awesome."""
    global _FA_CODEPOINTS
    if _FA_CODEPOINTS:
        return _FA_CODEPOINTS
    salida = {}
    try:
        ruta = os.path.join(app.static_folder, "vendor", "fontawesome", "css", "all.min.css")
        with open(ruta, "r", encoding="utf-8", errors="ignore") as fh:
            css = fh.read()
        # ⚠️ Font Awesome AGRUPA los alias en un solo selector
        # (`.fa-bolt:before,.fa-zap:before{content:"\\f0e7"}`): hay que leer el GRUPO entero, o esos
        # iconos se quedan sin codepoint y su PNG sale VACÍO en los correos.
        for selectores, code in re.findall(r'((?:\.fa-[a-z0-9-]+:before,?)+)\{content:"\\([0-9a-f]{4,5})"', css):
            for nombre in re.findall(r'\.fa-([a-z0-9-]+):before', selectores):
                salida.setdefault(nombre, chr(int(code, 16)))
    except Exception:
        app.logger.exception("[iconos] no se pudo leer el CSS de Font Awesome")
    _FA_CODEPOINTS = salida
    return salida


def _fa_icon_png(nombre: str, color: str = "007CA2", size: int = 40) -> bytes:
    """El icono SÓLIDO `nombre` como PNG transparente, en el color pedido (cacheado en memoria)."""
    clave = (nombre, color, size)
    if clave in _FA_ICON_CACHE:
        return _FA_ICON_CACHE[clave]
    from PIL import Image, ImageDraw, ImageFont
    car = _fa_codepoints().get((nombre or "").strip().lower().replace("fa-", ""))
    if not car:
        return b""
    try:
        fuente = ImageFont.truetype(
            os.path.join(app.static_folder, "vendor", "fontawesome", "webfonts", "fa-solid-900.ttf"),
            int(size * 0.82))
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        d = ImageDraw.Draw(img)
        rgb = tuple(int((color or "007CA2").lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
        caja = d.textbbox((0, 0), car, font=fuente)
        d.text(((size - (caja[2] - caja[0])) / 2 - caja[0], (size - (caja[3] - caja[1])) / 2 - caja[1]),
               car, font=fuente, fill=rgb + (255,))
        buf = BytesIO()
        img.save(buf, "PNG")
        datos = buf.getvalue()
    except Exception:
        app.logger.exception("[iconos] no se pudo dibujar %s", nombre)
        datos = b""
    _FA_ICON_CACHE[clave] = datos
    return datos


@app.get("/icono/<nombre>.png", endpoint="brand_icon_png")
def brand_icon_png(nombre):
    """El icono sólido de la casa como PNG (para los correos). Público: va dentro de un `<img>`."""
    color = re.sub(r"[^0-9a-fA-F]", "", (request.args.get("c") or "007CA2"))[:6] or "007CA2"
    try:
        tam = max(16, min(int(request.args.get("s") or 40), 128))
    except (TypeError, ValueError):
        tam = 40
    datos = _fa_icon_png(nombre, color, tam)
    if not datos:
        abort(404)
    resp = make_response(datos)
    resp.headers["Content-Type"] = "image/png"
    resp.headers["Cache-Control"] = "public, max-age=604800"
    return resp


