# Las empresas del grupo cuyo logo va en la cabecera de todo lo de Syncros, en este orden.
SYNC_BRAND_COMPANIES = ("PIES", "PLATAFORMA")

# Cuántos días es «novedad» un lanzamiento (en el repertorio abierto sale su etiqueta).
SYNC_NEW_DAYS = 15


def _sync_brand_logos(session_db) -> list[tuple[str, str]]:
    """(logo, nombre) de PIES y de Plataforma Musical, **de la ficha de la EMPRESA DEL GRUPO**.

    ⚠️ Ahí es donde están subidos los logos, no en la editorial: es el punto único que usan el envío,
    su vista previa y la landing del repertorio."""
    salida = []
    try:
        empresas = session_db.query(GroupCompany).order_by(GroupCompany.name.asc()).all()
    except Exception:
        return salida
    for clave in SYNC_BRAND_COMPANIES:
        for co in empresas:
            if clave in (co.name or "").upper():
                url = _absolute_media_url((getattr(co, "logo_url", None) or "").strip())
                if url:
                    # ⚠️ SIN el fondo blanco horneado del PNG: se integra con el fondo de la página
                    # y del correo. Absoluta, porque el mismo HTML va por correo.
                    salida.append((_external_url_for("logo_clean_png", u=url), (co.name or "").strip()))
                break
    return salida


def _sync_artist_photo(song) -> str:
    """La foto del artista de la canción (para enseñarlo con su cara, sin rótulo)."""
    try:
        for a in (getattr(song, "artists", None) or []):
            url = _absolute_media_url((getattr(a, "photo_url", None) or "").strip())
            if url:
                return url
    except Exception:
        pass
    return ""


def _sync_subject(t: dict, titulo: str, *, one_stop: bool, artista: str = "") -> str:
    """El ASUNTO del correo: «Nuevo tema para Syncro, <canción>, <artista> (One-Stop)».

    ⚠️ «(One-Stop)» solo si el tema LO ES: es lo que primero mira un supervisor, y decirlo de un tema
    que no lo es sería mentir. El nombre de la canción y el del artista NO se traducen."""
    base = "%s, %s" % (t["subject_lead"], titulo or "—")
    artista = (artista or "").strip()
    if artista and artista != "—":
        base += ", %s" % artista
    return "%s (%s)" % (base, t["one_stop"].title()) if one_stop else base


def _sync_lang(value) -> str:
    """El idioma de un envío, normalizado: solo ES o EN."""
    return "EN" if (str(value or "").strip().upper() == "EN") else "ES"


def _sync_certifications(session_db, song) -> list[dict]:
    """Las CERTIFICACIONES de la canción para la ficha de Syncro: su icono y cuántas son.

    Se agrupan con el MISMO motor que la pestaña Certificaciones (`_group_certifications`), así que
    se cuentan igual en los dos sitios. Aquí solo hace falta la imagen, el número y el texto para el
    tooltip: ni países ni equivalencias, que en una ficha de syncro no vienen a cuento.
    ⚠️ La imagen va en ABSOLUTO: esto se pinta también en el correo y en la página pública."""
    try:
        filas = (session_db.query(SongCertification)
                 .filter(SongCertification.song_id == song.id)
                 .order_by(SongCertification.created_at.asc()).all())
    except Exception:
        app.logger.exception("[syncro] no se pudieron leer las certificaciones")
        return []
    # Se juntan por TIPO (los países se suman): lo que se enseña es «2 discos de oro», no uno por país.
    por_tipo = {}
    for g in _group_certifications(filas, media_kind="SONG"):
        fila = por_tipo.setdefault(g["certification_type"], {
            "type": g["certification_type"], "image_url": g["image_url"],
            "title": g["title"], "plural_title": g["plural_title"],
            "count": 0, "order": g["sort_order"][0],
        })
        fila["count"] += int(g.get("count") or 0)
    salida = sorted(por_tipo.values(), key=lambda x: x["order"])
    for f in salida:
        f["label"] = ("%d %s" % (f["count"], f["plural_title"])) if f["count"] > 1 else f["title"]
    return salida


def _sync_song_context(session_db, song, *, lang: str = "ES") -> dict:
    """Todo lo que necesita el envío de un tema para sincronización (correo, enlace y vista previa).

    ⚠️ Punto ÚNICO: lo usan el correo a los supervisores, la página pública y la previsualización,
    así que las tres cosas dicen exactamente lo mismo. El idioma solo cambia los RÓTULOS: el nombre
    de la canción y del artista no se traducen nunca."""
    lang = _sync_lang(lang)
    t = SYNC_TEXTS[lang]
    artistas = _song_artist_name_list(song=song)
    autores = []
    for sh in (session_db.query(SongEditorialShare)
               .options(joinedload(SongEditorialShare.promoter).joinedload(Promoter.publishing_company),
                        joinedload(SongEditorialShare.publishing_company))
               .filter(SongEditorialShare.song_id == song.id)
               .order_by(SongEditorialShare.pct.desc(), SongEditorialShare.created_at.asc()).all()):
        rol = (getattr(sh, "role", "") or "").strip().upper()
        autores.append({
            "name": _promoter_display_name(getattr(sh, "promoter", None)) or "—",
            "role": t["roles"].get(rol, rol.title() if rol else "—"),
            "pct": _fmt_pct_es(getattr(sh, "pct", 0)),
            "publisher": (getattr(_share_publisher(sh), "name", "") or "").strip() or "—",
        })
    sello = _pies_group_company(session_db)
    # ⚠️ Los DOS logos (PIES y Plataforma Musical) salen de la ficha de la EMPRESA DEL GRUPO, que es
    # donde están subidos: `_sync_brand_logos` es el punto único (lo usan el envío y la landing).
    logos = _sync_brand_logos(session_db)
    letra = (getattr(song, "lyrics_text", None) or "").strip()
    return {
        "lang": lang, "t": t, "song": song,
        "title": (song.title or "").strip(),
        "artist_name": ", ".join(artistas) or "—",
        "cover_url": _absolute_media_url(getattr(song, "cover_url", None) or "") or "",
        "release_date": (song.release_date.strftime("%d/%m/%Y") if lang == "ES" else song.release_date.strftime("%Y-%m-%d")) if getattr(song, "release_date", None) else "",
        "genres": _song_genre_names(session_db, song.id),
        # CONTENIDO EXPLÍCITO: se dice detrás de los géneros (solo si lo es). Igual en el correo, en
        # el enlace y en la vista previa, porque los tres salen de aquí.
        "explicit": _song_is_explicit(song),
        # CERTIFICACIONES obtenidas (2 discos de oro…): SOLO el icono con su número, como en la
        # pestaña Certificaciones. Van arriba a la DERECHA, a la altura del artista.
        "certifications": _sync_certifications(session_db, song),
        "label_name": (getattr(sello, "name", "") or "").strip(),
        "label_logo": _absolute_media_url(getattr(sello, "logo_url", None) or "") or "",
        "brand_logos": logos,
        "artist_photo": _sync_artist_photo(song),
        "authors": autores,
        "lyrics": letra,
        "has_lyrics": bool(letra),
        "contact": {"name": SYNC_CONTACT_NAME,
                    "role": (SYNC_CONTACT_ROLE_ES if lang == "ES" else SYNC_CONTACT_ROLE_EN),
                    "email": SYNC_CONTACT_EMAIL, "phone": SYNC_CONTACT_PHONE},
        # El ASUNTO del correo: «Nuevo tema para Syncro, <canción> (One-Stop)». El nombre de la
        # canción no se traduce; lo de «(One-Stop)» solo si el tema LO ES (lo pone `_sync_subject`).
        "subject": _sync_subject(t, (song.title or "").strip(), one_stop=False,
                                 artista=", ".join(artistas)),
    }


def _sync_icon(nombre: str, *, email: bool, size: int = 16, color: str = "007CA2") -> str:
    """Un icono SÓLIDO de la casa, en el color de marca.

    ⚠️ En un CORREO no se puede usar la fuente de iconos (ningún cliente carga Font Awesome), así que
    ahí va el MISMO icono como PNG renderizado desde `fa-solid-900.ttf` (`brand_icon_png`). En la web
    va como `<i class="fa-solid …">` de siempre. Nada de emojis: el icono es el mismo en los dos sitios.
    """
    if email:
        url = _external_url_for("brand_icon_png", nombre=nombre, c=color, s=max(32, size * 2))
        return ('<img src="%s" width="%d" height="%d" alt="" '
                'style="width:%dpx;height:%dpx;vertical-align:-2px;">'
                % (escape(url), size, size, size, size))
    return '<i class="fa-solid fa-%s" style="color:#%s;"></i>' % (escape(nombre), escape(color))


def _sync_url_with(url: str, **params) -> str:
    """Añade parámetros a un enlace de Syncros (que ya puede llevar `?lang=en`).

    ⚠️ En un correo no corre JavaScript, así que lo que la página tiene que HACER al abrirse
    —reproducir el tema, abrir la letra, empezar la descarga— se le dice por la URL."""
    if not url:
        return ""
    extra = "&".join("%s=%s" % (k, quote(str(v))) for k, v in params.items() if v not in (None, ""))
    if not extra:
        return url
    return url + ("&" if "?" in url else "?") + extra


def _sync_pitch_html(ctx: dict, *, with_intro: bool = True, email: bool = False,
                     play_url: str = "", download_url: str = "", lyrics_url: str = "",
                     repertoire_url: str = "", one_stop: bool = True,
                     player_html: str = "") -> str:
    """El CUERPO del envío de un tema para sincronización, con estilos EN LÍNEA (va por correo).

    ⚠️ Punto ÚNICO: el correo, la página del enlace y la vista previa pintan ESTO, así que no puede
    haber dos versiones que se desparejen. `with_intro=False` quita el texto de presentación (en el
    enlace no va) y `email=True` cambia los iconos de fuente por su PNG.
    ⚠️ Los datos van con su ICONO y sin rótulo (el icono ya dice qué es), y el ARTISTA con su foto.
    """
    t = ctx["t"]
    esc = lambda v: escape(str(v or ""))
    ico = lambda n, size=16: _sync_icon(n, email=email, size=size)

    # ── Los DOS logos del grupo (PIES y Plataforma Musical), arriba a la derecha ──
    # ⚠️ Los logos van en una FILA DE TABLA con `vertical-align:middle` y la MISMA altura: sueltos
    # en un div, cada PNG se apoyaba a una altura distinta según su proporción.
    celdas = ""
    for url, nombre in ctx.get("brand_logos") or []:
        if url:
            celdas += ('<td style="vertical-align:middle;padding:0 0 0 14px;text-align:center;">'
                       '<img src="%s" alt="%s" style="height:30px;width:auto;display:block;'
                       'margin:0 auto;"></td>' % (esc(url), esc(nombre)))
    if celdas:
        logos = ('<table class="sync-logos" style="border-collapse:collapse;margin-left:auto;'
                 'display:inline-table;"><tr>%s</tr></table>' % celdas)
    else:
        logos = '<span style="font-size:13px;color:#6b7280;">%s</span>' % esc(ctx.get("label_name"))

    generos = "".join(
        '<span style="display:inline-block;background:#eef6f9;color:#00637f;border:1px solid #cfe6ee;'
        'border-radius:999px;padding:2px 10px;font-size:12px;margin:0 6px 4px 0;">%s</span>' % esc(g)
        for g in (ctx.get("genres") or []))
    # CONTENIDO EXPLÍCITO: DETRÁS de los géneros y de otro color (gris oscuro), para que no parezca
    # un género más. Solo si lo es; si no, no se dice nada.
    if ctx.get("explicit"):
        generos += ('<span style="display:inline-block;background:#212529;color:#fff;'
                    'border:1px solid #212529;border-radius:999px;padding:2px 10px;font-size:12px;'
                    'font-weight:700;margin:0 6px 4px 0;">%s&nbsp; %s</span>'
                    % (_sync_icon("e", email=email, size=11, color="ffffff"), esc(EXPLICIT_LABEL)))

    filas_autores = "".join(
        '<tr>'
        '<td style="padding:5px 8px;border-bottom:1px solid #eef1f4;font-size:12px;">%s</td>'
        '<td style="padding:5px 8px;border-bottom:1px solid #eef1f4;font-size:12px;color:#6b7280;">%s</td>'
        '<td style="padding:5px 8px;border-bottom:1px solid #eef1f4;font-size:12px;text-align:right;'
        'white-space:nowrap;">%s%%</td>'
        '<td style="padding:5px 8px;border-bottom:1px solid #eef1f4;font-size:12px;color:#6b7280;">%s</td>'
        '</tr>' % (esc(a["name"]), esc(a["role"]), esc(a["pct"]), esc(a["publisher"]))
        for a in (ctx.get("authors") or []))
    tabla_autores = ""
    if filas_autores:
        cab = ('<th style="text-align:%s;padding:0 8px 4px;font-size:11px;color:#9aa4ae;'
               'text-transform:uppercase;letter-spacing:.03em;font-weight:700;">%s</th>')
        tabla_autores = (
            '<div class="sync-authors" style="margin-top:12px;">'
            '<div style="font-size:12px;font-weight:700;color:#111827;margin-bottom:4px;">%s&nbsp; %s</div>'
            '<table class="sync-authors__table" style="width:100%%;border-collapse:collapse;">'
            '<tr>%s%s%s%s</tr>%s</table></div>'
            % (ico("pen-nib", 13), esc(t["authors"]),
               cab % ("left", esc(t["author"])), cab % ("left", esc(t["role"])),
               cab % ("right", esc(t["pct"])), cab % ("left", esc(t["publisher"])), filas_autores))

    # ── La etiqueta ONE-STOP: pastilla del azul de marca con su icono sólido (sin emojis) ──
    etiqueta_os = ""
    if one_stop:
        etiqueta_os = ('<span title="%s" style="display:inline-block;background:#007CA2;color:#fff;'
                       'border-radius:999px;padding:4px 12px 4px 10px;font-size:11px;font-weight:800;'
                       'letter-spacing:.06em;white-space:nowrap;">%s&nbsp; %s</span>'
                       % (esc(t["one_stop_help"]),
                          _sync_icon("clapperboard", email=email, size=12, color="ffffff"),
                          esc(t["one_stop"])))

    if ctx.get("cover_url"):
        # ⚠️ En la WEB, pinchar la portada también reproduce (`data-sync-cover` lo cablea la página).
        # ⚠️⚠️ `object-fit: CONTAIN`, no `cover`: la portada se ve ENTERA. Con `cover` se recortaba
        # la que no fuera cuadrada (el hueco lo es), que es justo lo que no puede pasar con una
        # portada. El TAMAÑO no cambia: el hueco sigue midiendo 220×220 y lo que sobra va en gris.
        portada = ('<img src="%s" alt="" width="220" class="sync-cover"%s style="width:220px;'
                   'height:220px;object-fit:contain;background:#f1f3f5;border-radius:12px;'
                   'border:1px solid #e6e9ec;display:block;">'
                   % (esc(ctx["cover_url"]), "" if email else ' data-sync-cover="1"'))
    else:
        portada = ('<div class="sync-cover-ph" style="width:220px;height:220px;border-radius:12px;background:#f1f3f5;'
                   'border:1px solid #e6e9ec;"></div>')

    def dato(icono, valor, extra=""):
        """Un dato: SOLO su icono y el valor (el icono ya dice qué es: nada de rótulos)."""
        return ('<div style="margin-top:7px;font-size:13.5px;color:#374151;line-height:1.35;">'
                '%s&nbsp; %s%s</div>' % (icono, valor, extra))

    # El ARTISTA, con su FOTO.
    foto = ctx.get("artist_photo")
    artista = ""
    if foto:
        artista += ('<img src="%s" alt="" width="26" height="26" style="width:26px;height:26px;'
                    'border-radius:50%%;object-fit:cover;vertical-align:middle;margin-right:6px;">'
                    % esc(foto))
    artista += '<strong style="vertical-align:middle;">%s</strong>' % esc(ctx.get("artist_name"))
    # ── Las CERTIFICACIONES, a la MISMA ALTURA que el artista pero a la DERECHA: solo el icono de lo
    # que se ha conseguido y, si es más de uno, su número (igual que en la pestaña Certificaciones).
    # Va en una tabla de dos celdas porque esto se pinta también en un CORREO (nada de flex).
    certis = ""
    for cert in (ctx.get("certifications") or []):
        n = int(cert.get("count") or 1)
        certis += ('<span title="%s" style="display:inline-block;margin-left:8px;white-space:nowrap;'
                   'vertical-align:middle;">'
                   '<img src="%s" alt="%s" height="30" style="height:30px;width:auto;'
                   'vertical-align:middle;">%s</span>'
                   % (esc(cert.get("label")), esc(cert.get("image_url")), esc(cert.get("label")),
                      ('<strong style="font-size:13px;color:#374151;vertical-align:middle;'
                       'margin-left:3px;">×%d</strong>' % n) if n > 1 else ""))
    linea_artista = ('<div style="margin-top:10px;font-size:15px;color:#111827;">%s</div>' % artista
                     if foto else dato(ico("user"), "<strong>%s</strong>" % esc(ctx.get("artist_name"))))
    if certis:
        bloque_artista = ('<table style="width:100%%;border-collapse:collapse;"><tr>'
                          '<td style="vertical-align:middle;">%s</td>'
                          '<td style="vertical-align:middle;text-align:right;white-space:nowrap;">%s</td>'
                          '</tr></table>' % (linea_artista, certis))
    else:
        bloque_artista = linea_artista

    sello = ""
    if ctx.get("label_logo"):
        sello = ('<div style="margin-top:9px;">%s&nbsp; '
                 '<img src="%s" alt="%s" style="height:20px;width:auto;vertical-align:middle;"></div>'
                 % (ico("compact-disc"), esc(ctx["label_logo"]), esc(ctx.get("label_name"))))
    elif ctx.get("label_name"):
        sello = dato(ico("compact-disc"), "<strong>%s</strong>" % esc(ctx["label_name"]))

    # ── Los BOTONES van DEBAJO DE LOS DATOS, dentro de la misma tarjeta ──
    # ⚠️ En la PÁGINA, el play y la descarga son el reproductor de verdad (el MISMO de las demos,
    # que llega hecho en `player_html`); en el CORREO no hay JavaScript, así que ahí son enlaces.
    botones = player_html or ""
    if play_url:
        botones += ('<a href="%s" style="display:inline-block;background:#007CA2;color:#fff;'
                    'text-decoration:none;border-radius:8px;padding:9px 16px;font-size:13.5px;'
                    'font-weight:700;margin:0 8px 8px 0;">%s&nbsp; %s</a>'
                    % (esc(play_url), _sync_icon("play", email=email, size=13, color="ffffff"),
                       esc(t["play"])))
    if download_url:
        botones += ('<a href="%s" title="%s" style="display:inline-block;background:#fff;color:#111827;'
                    'text-decoration:none;border:1px solid #d6dbe0;border-radius:8px;padding:9px 14px;'
                    'font-size:13.5px;font-weight:700;margin:0 8px 8px 0;">%s&nbsp; MP3</a>'
                    % (esc(download_url), esc(t["download"]), ico("download", 13)))
    # ⚠️ «Ver letra» SOLO si la canción tiene letra subida.
    if lyrics_url and ctx.get("has_lyrics"):
        botones += ('<a href="%s" style="display:inline-block;background:#fff;color:#111827;'
                    'text-decoration:none;border:1px solid #d6dbe0;border-radius:8px;padding:9px 14px;'
                    'font-size:13.5px;font-weight:700;margin:0 8px 8px 0;">%s&nbsp; %s</a>'
                    % (esc(lyrics_url), ico("align-justify", 13), esc(t["lyrics"])))

    # ── El CONTACTO, en su propia galleta ──
    c = ctx["contact"]
    asunto = quote("%s %s" % (t["subject"], ctx.get("title") or ""))
    mas_repertorio = ""
    if repertoire_url:
        mas_repertorio = ('<div style="margin-top:16px;padding-top:14px;'
                          'border-top:1px solid #eef1f4;"><a href="%s" style="display:inline-block;'
                          'background:#fff;color:#111827;text-decoration:none;border:1px solid #d6dbe0;'
                          'border-radius:8px;padding:10px 16px;font-size:14px;font-weight:700;">'
                          '%s&nbsp; %s</a></div>'
                          % (esc(repertoire_url), ico("compact-disc", 13), esc(t["more_repertoire"])))
    contacto = (
        '<table class="sync-contact" style="width:100%%;border-collapse:collapse;background:#fbfcfd;'
        'border:1px solid #e6e9ec;border-radius:14px;margin-top:14px;"><tr><td style="padding:16px 18px;">'
        '<div style="font-size:11px;font-weight:800;color:#9aa4ae;text-transform:uppercase;'
        'letter-spacing:.06em;margin-bottom:8px;">%s</div>'
        '<div style="font-size:15.5px;font-weight:700;color:#111827;">%s</div>'
        '<div class="sync-contact__role" style="font-size:13.5px;color:#6b7280;margin-bottom:8px;'
        'white-space:nowrap;">%s</div>'
        '<div class="sync-contact__line" style="margin-top:6px;"><a href="mailto:%s?subject=%s" '
        'style="color:#00637f;text-decoration:none;font-size:14.5px;white-space:nowrap;">%s&nbsp; %s</a></div>'
        '<div class="sync-contact__line" style="margin-top:6px;"><a href="tel:%s" '
        'style="color:#00637f;text-decoration:none;font-size:14.5px;white-space:nowrap;">%s&nbsp; %s</a></div>'
        '%s</td></tr></table>'
        % (esc(t["contact"]), esc(c["name"]), esc(c["role"]),
           esc(c["email"]), asunto, ico("envelope"), esc(c["email"]),
           esc(c["phone"]), ico("phone"), esc(c["phone"]), mas_repertorio))

    intro = ""
    if with_intro:
        # El texto lleva el ARTISTA, y si el tema es ONE-STOP se dice en una segunda línea.
        try:
            texto = t["intro"] % esc(ctx.get("artist_name") or "")
        except (TypeError, ValueError):
            texto = esc(t["intro"])
        intro = ('<p style="margin:0 0 6px;font-size:15px;line-height:1.55;color:#374151;'
                 'text-align:left;">%s</p>' % texto)
        if one_stop and t.get("intro_one_stop"):
            intro += ('<p style="margin:0 0 18px;font-size:15px;line-height:1.55;color:#374151;'
                      'text-align:left;">%s</p>' % esc(t["intro_one_stop"]))
        else:
            intro = intro.replace("margin:0 0 6px;", "margin:0 0 18px;", 1)

    return (
        # ⚠️⚠️ ADAPTADO AL ANCHO DE LA PANTALLA. La portada tenía 236 px FIJOS con
        # `table-layout:fixed`, así que en un móvil a los datos les quedaban ~110 px: el nombre del
        # artista y la fecha se partían en dos líneas y la tabla de autores se salía por la derecha
        # (bug real, con captura). Por debajo de 520 px la portada y los datos se APILAN, cada uno a
        # todo el ancho, y los dos módulos —la canción y el contacto— miden lo mismo.
        # Un correo no admite hojas externas, así que el `<style>` va aquí dentro; el cliente que no
        # entienda media queries (los hay) sigue viendo la maqueta de escritorio, que es la de antes.
        '<style>'
        '.sync-body{max-width:680px;margin:0 auto;padding:22px;background:#fff;}'
        '@media only screen and (max-width:520px){'
        '.sync-body{padding:14px !important;}'
        # ⚠️ Con `table-layout:fixed` la columna sigue mandando aunque la celda sea `display:block`:
        # se quedaban a 193 px de los 331 disponibles. La tabla pasa a `auto` y la FILA también a
        # bloque, y así cada celda ocupa todo el ancho.
        '.sync-card{table-layout:auto !important;}'
        '.sync-card tr{display:block !important;width:100%% !important;}'
        '.sync-card .sync-cell{display:block !important;width:100%% !important;}'
        '.sync-card .sync-cell--cover{padding:14px 14px 0 !important;text-align:center !important;}'
        '.sync-card .sync-cell--data{padding:12px 14px 14px !important;}'
        '.sync-cover,.sync-cover-ph{width:100%% !important;max-width:260px !important;'
        'height:auto !important;aspect-ratio:1/1;margin:0 auto !important;}'
        '.sync-authors__table{table-layout:auto !important;}'
        '.sync-authors__table th,.sync-authors__table td{font-size:11px !important;'
        'padding:4px 5px !important;}'
        '.sync-logos img{height:24px !important;}'
        '}'
        '</style>'
        '<div class="sync-body" style="max-width:680px;margin:0 auto;padding:22px;'
        'font-family:-apple-system,'
        'BlinkMacSystemFont,\'Segoe UI\',Roboto,Helvetica,Arial,sans-serif;background:#fff;">'
        '<div style="text-align:right;margin-bottom:6px;">%s</div>'
        '<h1 style="margin:8px 0 14px;font-size:23px;line-height:1.25;text-align:center;'
        'color:#111827;">%s</h1>'
        '%s'
        '<table class="sync-card" style="width:100%%;border-collapse:collapse;table-layout:fixed;'
        'background:#fff;border:1px solid #e6e9ec;border-radius:14px;"><tr>'
        '<td class="sync-cell sync-cell--cover" style="padding:16px;vertical-align:top;width:236px;">%s</td>'
        '<td class="sync-cell sync-cell--data" style="padding:16px 16px 16px 0;vertical-align:top;">'
        '<table class="sync-titlerow" style="width:100%%;border-collapse:collapse;"><tr>'
        '<td class="sync-title" style="font-size:20px;font-weight:800;color:#111827;line-height:1.2;padding:0;">%s</td>'
        '<td class="sync-badge" style="text-align:right;padding:0 0 0 10px;white-space:nowrap;">%s</td>'
        '</tr></table>'
        '%s%s%s%s%s'
        '</td></tr>'
        '%s</table>'
        '%s</div>'
        % (logos, esc(t["title"]), intro, portada,
           esc(ctx.get("title")), etiqueta_os,
           bloque_artista,
           (dato(ico("calendar-day"), esc(ctx.get("release_date"))) if ctx.get("release_date") else ""),
           (dato(ico("tags"), generos) if generos else ""),
           sello, tabla_autores,
           # Los botones, DEBAJO de los datos y a todo el ancho de la tarjeta.
           ('<tr><td colspan="2" style="padding:0 16px 16px;">%s</td></tr>' % botones) if botones else "",
           contacto))


# Un icono para cada familia de géneros (sólidos de la casa: la galleta se lee de un vistazo).
SYNC_GENRE_ICONS = [
    (("flamenc", "rumba", "copla", "sevillan", "bolero"), "fa-guitar"),
    (("rock", "punk", "metal", "hardcore", "garage"), "fa-bolt"),
    (("pop", "indie"), "fa-star"),
    (("electr", "house", "techno", "dance", "ambient", "drill"), "fa-sliders"),
    (("hip hop", "trap", "rap", "r&b", "soul", "funk"), "fa-microphone-lines"),
    (("jazz", "blues", "gospel"), "fa-music"),
    (("clasic", "clásic", "banda sonora", "instrumental"), "fa-music"),
    (("latin", "salsa", "bachata", "cumbia", "reggaeton", "reggaetón", "afrobeat"), "fa-drum"),
    (("country", "folk", "cantautor"), "fa-guitar"),
    (("infantil", "navidad"), "fa-gift"),
]


def _sync_genre_icon(nombre: str) -> str:
    """El icono sólido de un género (el genérico si no casa con ninguna familia)."""
    clave = _norm_text_key(nombre)
    for palabras, icono in SYNC_GENRE_ICONS:
        if any(p in clave for p in palabras):
            return icono
    return "fa-music"


def _sync_song_rows(session_db, canciones, *, one_stop_map=None) -> list[dict]:
    """Las filas de un listado de temas para SYNCRO (la sección y la landing pública).

    Punto único: la etiqueta de género, el estado one-stop, el enlace de escucha y el de descarga
    salen de aquí, así que dentro y fuera se ve lo mismo. Todo **en bloque** (nada de N+1)."""
    canciones = list(canciones or [])
    if not canciones:
        return []
    ids = [c.id for c in canciones]
    mapa = one_stop_map if one_stop_map is not None else _song_one_stop_map(session_db, canciones)
    generos = _song_genres_map(session_db, ids)
    enviados = _sync_sent_state(session_db, ids)
    # El audio de todas, de UNA consulta (el máster; la maqueta solo para las que no lo tengan).
    masters, orden = {}, {"MASTER_48": 0, "MASTER_24": 1, "MASTER_16": 2}
    try:
        for m in (session_db.query(SongMaterial)
                  .filter(SongMaterial.song_id.in_(ids),
                          func.upper(func.coalesce(SongMaterial.category, "")) == "MASTER").all()):
            if not (getattr(m, "file_url", None) or "").strip():
                continue
            peso = orden.get((getattr(m, "slot_key", "") or "").strip().upper(), 5)
            sid = str(m.song_id)
            if sid not in masters or peso < masters[sid][0]:
                masters[sid] = (peso, m.file_url.strip())
    except Exception:
        app.logger.exception("[syncro] no se pudieron leer los másters del listado")
    demos = {}
    faltan = [c.id for c in canciones if str(c.id) not in masters]
    if faltan:
        try:
            for d in (session_db.query(SongDemo).filter(SongDemo.song_id.in_(faltan))
                      .order_by(SongDemo.created_at.desc()).all()):
                demos.setdefault(str(d.song_id), (getattr(d, "audio_url", None) or "").strip())
        except Exception:
            app.logger.exception("[syncro] no se pudieron leer las maquetas del listado")
    filas = []
    for c in canciones:
        sid = str(c.id)
        env = enviados.get(sid) or {}
        token = _sync_song_token(session_db, c)
        tiene_audio = bool(masters.get(sid) or demos.get(sid))
        artistas = _song_artist_name_list(song=c)
        filas.append({
            "id": sid,
            "title": (c.title or "").strip(),
            "artist_name": ", ".join(artistas) or "—",
            "artist_photo": (_sync_artist_photo(c) or ""),
            "artist_ids": [str(getattr(a, "id", "")) for a in (getattr(c, "artists", None) or [])],
            "cover_url": (getattr(c, "cover_url", None) or "").strip(),
            "release_label": (c.release_date.strftime("%d/%m/%Y") if getattr(c, "release_date", None) else ""),
            # NOVEDAD: menos de `SYNC_NEW_DAYS` días desde que salió (la etiqueta se cae sola).
            "is_new": bool(getattr(c, "release_date", None)
                           and 0 <= (today_local() - c.release_date).days < SYNC_NEW_DAYS),
            "genres": generos.get(sid, []),
            # CONTENIDO EXPLÍCITO: su etiqueta va detrás de las de género (solo si lo es).
            "explicit": _song_is_explicit(c),
            "one_stop": bool((mapa.get(sid) or {}).get("ok")),
            "has_lyrics": bool((getattr(c, "lyrics_text", None) or "").strip()),
            "lyrics": (getattr(c, "lyrics_text", None) or "").strip(),
            "has_audio": tiene_audio,
            "detail_url": url_for("discografica_song_detail", song_id=sid),
            "share_url": _external_url_for("public_sync_song", token=token) if token else "",
            "audio_url": (url_for("public_sync_song_audio", token=token) if (token and tiene_audio) else ""),
            "download_url": (url_for("public_sync_song_download", token=token) if (token and tiene_audio) else ""),
            "sent": bool(env),
            "sent_count": int(env.get("count") or 0),
            "sent_tooltip": env.get("tooltip") or "",
        })
    return filas


def _sync_repertoire_songs(session_db):
    """Las canciones que están EN el repertorio de Syncro: las **habilitadas a mano** y las
    **ONE-STOP** (que entran solas por serlo).

    ⚠️ Punto único: lo usan la sección de Syncros y la landing pública, así que dentro y fuera se ve
    el mismo repertorio."""
    canciones = (session_db.query(Song)
                 .options(selectinload(Song.artists))
                 .filter(Song.is_provisional.is_(False))
                 .order_by(Song.release_date.desc().nullslast(), Song.title.asc()).all())
    mapa = _song_one_stop_map(session_db, canciones)
    elegidas = [c for c in canciones
                if bool(getattr(c, "sync_enabled", False)) or (mapa.get(str(c.id)) or {}).get("ok")]
    # ⚠️ SIN MÁSTER no entra en el repertorio: a un supervisor se le presenta un tema que se pueda
    # ESCUCHAR. (Una consulta para todas, no una por canción.)
    if elegidas:
        try:
            con_master = {str(r[0]) for r in
                          session_db.query(SongMaterial.song_id)
                          .filter(SongMaterial.song_id.in_([c.id for c in elegidas]),
                                  func.upper(func.coalesce(SongMaterial.category, "")) == "MASTER",
                                  func.length(func.coalesce(SongMaterial.file_url, "")) > 0)
                          .distinct().all()}
            elegidas = [c for c in elegidas if str(c.id) in con_master]
        except Exception:
            app.logger.exception("[syncro] no se pudo comprobar el máster del repertorio")
    # ⚠️ EL ORDEN es el del LANZAMIENTO: arriba lo más reciente (y a igualdad de fecha, por título).
    # Se ordena aquí, en el punto único, para que la sección, sus filtros y la landing pública lo
    # hereden sin depender de que cada pantalla se acuerde.
    elegidas.sort(key=lambda c: (-(c.release_date.toordinal() if getattr(c, "release_date", None) else 0),
                                 _norm_text_key(getattr(c, "title", "") or "")))
    return elegidas, mapa


def _sync_repertoire_filtered(session_db, *, artista_id=None, q: str = "", solo_os: bool = False):
    """El listado de Syncro ya FILTRADO. Devuelve `(filas, filas_sin_filtro_de_artista, mapa_art)`.

    ⚠️ Punto único de «qué se ve y en qué orden»: lo usan la pantalla y las FLECHAS de anterior/
    siguiente de la ficha, así que la siguiente canción es la que está debajo en la lista."""
    canciones, mapa_os = _sync_repertoire_songs(session_db)
    filas = _sync_song_rows(session_db, canciones, one_stop_map=mapa_os)
    mapa_art = {}
    for c in canciones:
        for a in (getattr(c, "artists", None) or []):
            mapa_art[str(a.id)] = a
    base = [f for f in filas if (f["one_stop"] or not solo_os)]
    salida = base
    if artista_id:
        salida = [f for f in salida if str(artista_id) in f["artist_ids"]]
    q = (q or "").strip()
    if q:
        clave = _norm_text_key(q)
        salida = [f for f in salida
                  if clave in _norm_text_key(" ".join([f["title"], f["artist_name"]] + f["genres"]))]
    return salida, base, mapa_art


def _sync_repertoire_context(session_db) -> dict:
    """El REPERTORIO para Syncro: **el LISTADO** de lo que se puede presentar, con sus filtros.

    ⚠️ Aquí se ve la LISTA directamente (los artistas son un filtro, no una pantalla previa): la
    agrupación por géneros o por artistas es solo del **repertorio abierto** que consultan los
    supervisores (`public_sync_repertoire`)."""
    q = (request.args.get("q") or "").strip()
    solo_os = _truthy(request.args.get("onestop"))
    artista_id = _safe_uuid((request.args.get("artista") or "").strip())

    base, sin_artista, mapa_art = _sync_repertoire_filtered(
        session_db, artista_id=artista_id, q=q, solo_os=solo_os)

    artistas = {}
    for f in sin_artista:
        for aid in f["artist_ids"]:
            d = artistas.setdefault(aid, {"id": aid, "name": "", "photo": "", "count": 0})
            d["count"] += 1
    for aid, d in artistas.items():
        a = mapa_art.get(aid)
        d["name"] = (getattr(a, "name", "") or "").strip() or "—"
        d["photo"] = (getattr(a, "photo_url", "") or "").strip()
    rejilla = sorted(artistas.values(), key=lambda d: _norm_text_key(d["name"]))

    # Las FLECHAS de la ficha necesitan saber de qué listado se viene (y con qué filtros).
    nav_args = {"nav": "syncros"}
    if artista_id:
        nav_args["nav_artista"] = str(artista_id)
    if q:
        nav_args["nav_q"] = q
    if solo_os:
        nav_args["nav_onestop"] = "1"
    for f in base:
        f["detail_url"] = url_for("discografica_song_detail", song_id=f["id"], **nav_args)

    elegido = mapa_art.get(str(artista_id)) if artista_id else None
    return {
        "rep_rows": base,
        "rep_total": len(base),
        "rep_q": q,
        "rep_only_onestop": solo_os,
        "rep_artists": rejilla,
        "rep_artist_id": str(artista_id) if artista_id else "",
        "rep_artist": ({"id": str(artista_id), "name": (getattr(elegido, "name", "") or ""),
                        "photo": (getattr(elegido, "photo_url", "") or "")} if elegido is not None else None),
        "rep_onestop_total": len([f for f in sin_artista if f["one_stop"]]),
    }


def _sync_song_audio_url(session_db, song) -> str:
    """El audio con el que se escucha el tema: su MÁSTER (48 antes que 24 y 16) o, si no, su maqueta."""
    orden = {"MASTER_48": 0, "MASTER_24": 1, "MASTER_16": 2}
    mejor, mejor_peso = "", 99
    try:
        for m in (session_db.query(SongMaterial)
                  .filter(SongMaterial.song_id == song.id,
                          func.upper(func.coalesce(SongMaterial.category, "")) == "MASTER").all()):
            peso = orden.get((getattr(m, "slot_key", "") or "").strip().upper(), 5)
            if (getattr(m, "file_url", None) or "").strip() and peso < mejor_peso:
                mejor, mejor_peso = m.file_url.strip(), peso
    except Exception:
        app.logger.exception("[syncro] no se pudo leer el máster de la canción")
    if mejor:
        return mejor
    try:
        demo = (session_db.query(SongDemo).filter(SongDemo.song_id == song.id)
                .order_by(SongDemo.created_at.desc()).first())
        return (getattr(demo, "audio_url", None) or "").strip()
    except Exception:
        return ""


def _sync_song_token(session_db, song) -> str:
    """Token OPACO del enlace público de un tema para sincronización (se crea la primera vez).

    ⚠️ Con COMMIT: creándolo con un flush sin commit se perdería al cerrar la sesión y en la carga
    siguiente saldría otro, o sea que un enlace ya compartido dejaría de valer (bug real de las demos)."""
    token = (getattr(song, "sync_share_token", None) or "").strip()
    if token:
        return token
    token = _uuid_token()
    song.sync_share_token = token
    try:
        session_db.commit()
    except Exception:
        session_db.rollback()
        app.logger.exception("[syncro] no se pudo guardar el token del enlace")
        return ""
    return token


def _sync_song_share_url(session_db, song, *, lang: str = "ES") -> str:
    """El enlace público del tema (con su idioma: a un supervisor anglo se le manda en inglés)."""
    token = _sync_song_token(session_db, song)
    if not token:
        return ""
    args = {"token": token}
    if _sync_lang(lang) == "EN":
        args["lang"] = "en"
    return _external_url_for("public_sync_song", **args)


def _sync_sent_state(session_db, song_ids) -> dict[str, dict]:
    """¿A qué supervisores se les ha mandado ya cada tema, y cuándo? (UNA consulta para el listado).

    Devuelve `{song_id: {count, last, last_label, names, tooltip}}` — lo que se enseña al pasar el
    ratón por el icono de «enviada a Supervisors»."""
    ids = [to_uuid(str(x)) for x in (song_ids or []) if to_uuid(str(x))]
    if not ids:
        return {}
    salida: dict[str, dict] = {}
    try:
        # ⚠️ SOLO los envíos a SUPERVISORES: un correo suelto (o un WhatsApp) no es haber presentado
        # el tema a los supervisores, así que no marca la fila ni cierra la tarea pendiente.
        filas = (session_db.query(SyncSubmission)
                 .filter(SyncSubmission.song_id.in_(ids),
                         SyncSubmission.supervisor_id.isnot(None))
                 .order_by(SyncSubmission.sent_at.desc()).all())
    except Exception:
        app.logger.exception("[syncro] no se pudieron leer los envíos")
        return {}
    # ⚠️ `SyncSubmission` NO tiene relación `promoter` (solo la columna): los nombres se resuelven
    # con UNA consulta en bloque. Con un joinedload esto reventaba dentro del try y la marca de
    # «enviada a Supervisors» no aparecía NUNCA (bug real, lo sacó la prueba).
    nombres = {}
    pids = [f.promoter_id for f in filas if getattr(f, "promoter_id", None)]
    if pids:
        try:
            for p in session_db.query(Promoter).filter(Promoter.id.in_(pids)).all():
                nombres[str(p.id)] = _promoter_display_name(p)
        except Exception:
            app.logger.exception("[syncro] no se pudieron leer los destinatarios")
    for f in filas:
        sid = str(f.song_id)
        d = salida.setdefault(sid, {"count": 0, "last": None, "last_label": "", "names": [],
                                    "channels": set()})
        d["count"] += 1
        if d["last"] is None and getattr(f, "sent_at", None):
            d["last"] = f.sent_at
            d["last_label"] = f.sent_at.strftime("%d/%m/%Y %H:%M")
        nombre = nombres.get(str(getattr(f, "promoter_id", "") or "")) or (getattr(f, "notes", "") or "").strip()
        if nombre and nombre not in d["names"]:
            d["names"].append(nombre)
        d["channels"].add((getattr(f, "channel", "") or "EMAIL").upper())
    for d in salida.values():
        d["channels"] = sorted(d["channels"])
        muchos = len(d["names"]) > 8
        d["tooltip"] = "Enviada el %s a %s%s" % (
            d["last_label"] or "—", ", ".join(d["names"][:8]) or "—",
            " y %d más" % (len(d["names"]) - 8) if muchos else "")
    return salida


def _sync_send_targets_context(session_db) -> dict:
    """Los SUPERVISORES a los que se puede mandar un tema, con sus MISMOS filtros que el listado.

    ⚠️ En el envío los filtros nacen **todos activados** y al desactivar uno se quitan del envío
    (justo al revés que en el listado, donde no filtrar es ver todo)."""
    filas = []
    for sup in (session_db.query(SyncSupervisor)
                .options(joinedload(SyncSupervisor.promoter))
                .filter(SyncSupervisor.is_archived.is_(False)).all()):
        fila = _sync_supervisor_row(sup)
        correo, _tel = _promoter_email_phone(getattr(sup, "promoter", None))
        fila["email"] = (correo or "").strip()
        filas.append(fila)
    filas.sort(key=lambda f: _norm_text_key(f["name"]))
    tipos = {f["type"] for f in filas}
    paises = {}
    for f in filas:
        if f["region_kind"] == "COUNTRY" and f.get("region_country"):
            paises.setdefault(f["region_country"].strip().lower(), f["region_country"].strip())
    return {
        "send_rows": filas,
        "send_total": len([f for f in filas if f["email"]]),
        "send_no_email": len([f for f in filas if not f["email"]]),
        "send_types": [(k, l, SYNC_TYPE_ICONS.get(k, "fa-user-tie")) for k, l in SYNC_SUPERVISOR_TYPES
                       if k in tipos],
        "send_regions": [(k, l, SYNC_REGION_ICONS.get(k, "fa-flag")) for k, l in SYNC_REGION_KINDS
                         if k != "COUNTRY" and k in {f["region_kind"] for f in filas}],
        "send_countries": [{"value": nombre, "name": nombre, "flag": _country_flag(nombre)}
                           for _k, nombre in sorted(paises.items(), key=lambda kv: _norm_text_key(kv[1]))],
        "send_langs": [("ES", "Español"), ("EN", "Habla inglés")],
    }


def _sync_supervisors_context(session_db) -> dict:
    """El listado de Supervisors con sus filtros (tipo, región, idioma y texto libre)."""
    filtro_tipo = [t for t in request.args.getlist("tipo") if (t or "").strip().upper() in SYNC_TYPE_LABELS]
    # ⚠️ El filtro de región no puede decir «Un país» a secas (no filtra nada útil): ofrece GLOBAL,
    # LATAM y **cada país concreto** que haya, como `country:<nombre>` y pintado con su BANDERA.
    filtro_region = []
    filtro_paises = []
    for bruto in request.args.getlist("region"):
        valor = (bruto or "").strip()
        if valor.lower().startswith("country:"):
            pais = valor.split(":", 1)[1].strip()
            if pais:
                filtro_paises.append(pais)
        elif valor.upper() in dict(SYNC_REGION_KINDS):
            filtro_region.append(valor.upper())
    filtro_idioma = [l for l in request.args.getlist("idioma") if (l or "").strip().upper() in SYNC_LANGUAGE_LABELS]
    q = (request.args.get("q") or "").strip()

    query = (session_db.query(SyncSupervisor)
             .options(joinedload(SyncSupervisor.promoter))
             .filter(SyncSupervisor.is_archived.is_(False)))
    if filtro_tipo:
        query = query.filter(SyncSupervisor.sup_type.in_([t.upper() for t in filtro_tipo]))
    if filtro_region or filtro_paises:
        condiciones = []
        if filtro_region:
            condiciones.append(SyncSupervisor.region_kind.in_([r.upper() for r in filtro_region]))
        for pais in filtro_paises:
            condiciones.append(and_(SyncSupervisor.region_kind == "COUNTRY",
                                    func.lower(func.coalesce(SyncSupervisor.region_country, "")) == pais.lower()))
        query = query.filter(or_(*condiciones))
    todos = query.all()

    # Cuántas sincronizaciones se le han enviado a cada uno: UNA consulta agrupada (con cientos de
    # supervisores, una por fila sería inaceptable).
    enviados = {}
    if todos:
        for sid, n in (session_db.query(SyncSubmission.supervisor_id, func.count(SyncSubmission.id))
                       .filter(SyncSubmission.supervisor_id.in_([s.id for s in todos]))
                       .group_by(SyncSubmission.supervisor_id).all()):
            enviados[str(sid)] = int(n or 0)

    filas = [_sync_supervisor_row(s, submissions=enviados.get(str(s.id), 0)) for s in todos]
    # El idioma y el texto se filtran en Python: el idioma vive en un JSONB y el nombre se compone
    # del tercero (no es una columna de esta tabla).
    if filtro_idioma:
        pedidos = {l.upper() for l in filtro_idioma}
        filas = [f for f in filas if pedidos & set(f["languages"])]
    if q:
        clave = _norm_text_key(q)
        filas = [f for f in filas
                 if clave in _norm_text_key(" ".join([f["name"], f["email"], f["phone"],
                                                      f["type_label"], f["region_label"]]))]
    filas.sort(key=lambda f: _norm_text_key(f["name"]))

    # Solo se ofrecen los filtros que de verdad pueden devolver algo (misma regla que los tipos del
    # calendario de agenda: un filtro vacío solo hace ruido).
    tipos_con_algo = {f["type"] for f in filas} | {t.upper() for t in filtro_tipo}
    regiones_con_algo = {f["region_kind"] for f in filas} | {r.upper() for r in filtro_region}
    idiomas_con_algo = {c for f in filas for c in f["languages"]} | {l.upper() for l in filtro_idioma}
    # Los PAÍSES que de verdad hay (los del listado más los que se estén filtrando), con su bandera.
    paises = {}
    for f in filas:
        if f["region_kind"] == "COUNTRY" and (f.get("region_country") or "").strip():
            paises.setdefault(f["region_country"].strip().lower(), f["region_country"].strip())
    for pais in filtro_paises:
        paises.setdefault(pais.strip().lower(), pais.strip())
    filtro_pais_vals = ["country:%s" % p for p in filtro_paises]
    sup_countries = [{"value": "country:%s" % nombre, "name": nombre,
                      "flag": _country_flag(nombre), "iso": _country_iso2(nombre)}
                     for _k, nombre in sorted(paises.items(), key=lambda kv: _norm_text_key(kv[1]))]
    return {
        "sup_rows": filas,
        "sup_total": len(filas),
        "sup_q": q,
        "sup_filter_type": [t.upper() for t in filtro_tipo],
        "sup_filter_region": [r.upper() for r in filtro_region] + filtro_pais_vals,
        "sup_countries": sup_countries,
        "sup_filter_lang": [l.upper() for l in filtro_idioma],
        "sup_types": [(k, l, SYNC_TYPE_ICONS.get(k, "fa-user-tie")) for k, l in SYNC_SUPERVISOR_TYPES
                      if k in tipos_con_algo],
        # ⚠️ «COUNTRY» ya NO se ofrece como chip: decía «Un país» y no filtraba nada útil. Sus
        # países salen uno a uno en `sup_countries`, con su bandera.
        "sup_regions": [(k, l, SYNC_REGION_ICONS.get(k, "fa-flag")) for k, l in SYNC_REGION_KINDS
                        if k in regiones_con_algo and k != "COUNTRY"],
        "sup_langs": [(k, l) for k, l in SYNC_LANGUAGES if k in idiomas_con_algo],
    }


# ══ TEMA PARA SINCRONIZACIÓN · página pública, audio y miniatura ══════════════════════════════
def _sync_song_by_token(session_db, token: str):
    """La canción de un enlace público de sincronización (token opaco). None si no vale."""
    t = (token or "").strip()
    if not t:
        return None
    return session_db.query(Song).filter(Song.sync_share_token == t).first()


@app.get("/syncros/destinatarios", endpoint="sync_send_targets")
@admin_required
def sync_send_targets():
    """Los supervisores a los que mandar un tema, **al abrir el pop-up**.

    ⚠️ Antes esta lista se pintaba dentro del HTML de la pantalla (y de la ficha de la canción): con
    cientos de supervisores —cada uno con su foto— la página pesaba muchísimo, tardaba y se llegaba
    a ver un instante **sin estilos** (bug real). Ahora se pide cuando de verdad se necesita."""
    if not can_edit_syncros():
        return jsonify({"ok": False, "error": "Sin permiso."}), 403
    session_db = db()
    try:
        return jsonify({"ok": True,
                        "html": render_template("_sync_send_targets.html",
                                                **_sync_send_targets_context(session_db))})
    finally:
        session_db.close()


@app.get("/syncros/tema/<song_id>/previsualizar", endpoint="sync_song_preview_html")
@admin_required
def sync_song_preview_html(song_id):
    """El cuerpo del envío tal como va a salir (para la vista previa del pop-up), en su idioma."""
    if not can_edit_syncros():
        return jsonify({"ok": False, "error": "Sin permiso."}), 403
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if song is None:
            return jsonify({"ok": False, "error": "Canción no encontrada."}), 404
        lang = _sync_lang(request.args.get("lang"))
        ctx = _sync_song_context(session_db, song, lang=lang)
        enlace = _sync_song_share_url(session_db, song, lang=lang)
        fila = (_sync_song_rows(session_db, [song]) or [{}])[0]
        cuerpo = _sync_pitch_html(
            ctx, with_intro=True, email=True, play_url=_sync_url_with(enlace, play=1),
            # ⚠️ La descarga va a la FICHA con `?descargar=1`, no al archivo: preparar el MP3 tarda
            # y el enlace directo dejaba al navegador en blanco todo ese rato.
            download_url=(_sync_url_with(enlace, descargar=1) if fila.get("download_url") else ""),
            lyrics_url=(_sync_url_with(enlace, letra=1) if ctx["has_lyrics"] else ""),
            repertoire_url=_external_url_for("public_sync_repertoire",
                                             **({"lang": "en"} if lang == "EN" else {})),
            one_stop=bool(fila.get("one_stop")))
        return jsonify({"ok": True, "html": cuerpo, "subject": ctx["subject"], "lang": lang})
    finally:
        session_db.close()


@app.post("/syncros/tema/<song_id>/habilitar", endpoint="sync_song_enable")
@admin_required
def sync_song_enable(song_id):
    """Habilita (o deshabilita) un tema para SYNCRO desde su ficha.

    ⚠️ El repertorio de Syncros enseña las **habilitadas** y las **ONE-STOP**: un tema que no es
    one-stop se puede presentar igualmente si alguien decide que sí, y uno que lo es entra solo."""
    if not (can_edit_syncros() or can_edit_discografica()):
        return forbid("No tienes permiso para habilitar temas para Syncro.")
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if song is None:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("discografica_view", section="canciones"))
        quitar = _truthy(request.form.get("undo")) or _truthy(request.args.get("undo"))
        song.sync_enabled = not quitar
        if song.sync_enabled:
            song.sync_enabled_at = _now_madrid()
            song.sync_enabled_by_nick = (_current_user_state().get("nick") or "").strip() or None
        session_db.commit()
        flash("Tema habilitado para Syncro." if song.sync_enabled
              else "Tema retirado del repertorio de Syncro.", "success")
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo cambiar: %s" % exc, "danger")
    finally:
        session_db.close()
    return redirect(request.form.get("next") or request.referrer
                    or url_for("discografica_song_detail", song_id=song_id))


@app.post("/syncros/tema/<song_id>/enviar", endpoint="sync_song_send")
@admin_required
def sync_song_send(song_id):
    """Manda el tema a los SUPERVISORES elegidos (y a los correos añadidos a mano).

    ⚠️ Cada uno lo recibe **en SU idioma** (`SyncSupervisor.comm_lang`): a un supervisor anglo le
    llega todo traducido menos el nombre de la canción y del artista. El cuerpo es el MISMO
    `_sync_pitch_html` que la vista previa y que el enlace público.
    ⚠️ Un envío queda registrado en `SyncSubmission` (a quién, cuándo, por qué canal), que es de
    donde sale la marca de «enviada a Supervisors» del listado y de la ficha.
    """
    if not can_edit_syncros():
        return forbid("No tienes permiso para mandar temas a Syncros.")
    session_db = db()
    try:
        song = session_db.get(Song, to_uuid(song_id))
        if song is None:
            flash("Canción no encontrada.", "warning")
            return redirect(url_for("syncros_view"))
        # Esconder el botón no basta: solo se presenta lo que está EN el repertorio de Syncro.
        if not (bool(getattr(song, "sync_enabled", False)) or _song_one_stop(session_db, song)["ok"]):
            flash("Ese tema no está en el repertorio de Syncro: habilítalo en su ficha o compruébalo.",
                  "warning")
            return redirect(request.referrer or url_for("syncros_view"))

        ids = [i for i in request.form.getlist("supervisor_ids") if (i or "").strip()]
        extras = [e.strip() for e in re.split(r"[,;\s]+", (request.form.get("extra_emails") or "")) if e.strip()]
        extras = [e for e in extras if "@" in e]
        estado = _current_user_state()
        nick = (estado.get("nick") or "").strip() or None

        destinos = []
        if ids:
            for sup in (session_db.query(SyncSupervisor)
                        .options(joinedload(SyncSupervisor.promoter))
                        .filter(SyncSupervisor.id.in_([to_uuid(i) for i in ids if to_uuid(i)])).all()):
                correo, _t = _promoter_email_phone(getattr(sup, "promoter", None))
                if not (correo or "").strip():
                    continue
                destinos.append({"sup": sup, "email": correo.strip(),
                                 "name": _promoter_display_name(getattr(sup, "promoter", None)),
                                 "lang": _sync_lang(getattr(sup, "comm_lang", "ES"))})
        for correo in extras:
            destinos.append({"sup": None, "email": correo, "name": correo,
                             "lang": _sync_lang(request.form.get("extra_lang"))})
        if not destinos:
            flash("Elige al menos un supervisor (o escribe un correo).", "warning")
            return redirect(request.referrer or url_for("syncros_view"))

        # El cuerpo se compone UNA vez por idioma (son dos), no uno por destinatario.
        cuerpos, asuntos = {}, {}
        for lang in {d["lang"] for d in destinos}:
            ctx = _sync_song_context(session_db, song, lang=lang)
            enlace = _sync_song_share_url(session_db, song, lang=lang)
            fila = (_sync_song_rows(session_db, [song]) or [{}])[0]
            cuerpos[lang] = _sync_pitch_html(
                ctx, with_intro=True, email=True, play_url=_sync_url_with(enlace, play=1),
                download_url=(_sync_url_with(enlace, descargar=1) if fila.get("download_url") else ""),
                lyrics_url=(_sync_url_with(enlace, letra=1) if ctx["has_lyrics"] else ""),
                repertoire_url=_external_url_for("public_sync_repertoire",
                                                 **({"lang": "en"} if lang == "EN" else {})),
                one_stop=bool(fila.get("one_stop")))
            asuntos[lang] = _sync_subject(ctx["t"], ctx.get("title") or "",
                                          one_stop=bool(fila.get("one_stop")),
                                          artista=ctx.get("artist_name") or "")

        enviados, fallidos = 0, []
        nota = (request.form.get("note") or "").strip()
        for d in destinos:
            cuerpo = cuerpos[d["lang"]]
            if nota:
                cuerpo = ('<div style="max-width:680px;margin:0 auto;padding:0 22px;font-size:14px;'
                          'color:#374151;">%s</div>' % escape(nota)) + cuerpo
            ok, _err = _send_optional_email(d["email"], asuntos[d["lang"]], cuerpo)
            if not ok:
                fallidos.append(d["name"] or d["email"])
                continue
            enviados += 1
            # ⚠️ El CANAL distingue lo que va a un SUPERVISOR de un correo suelto: la marca de
            # «enviada a Supervisors» solo cuenta lo primero (mandárselo a un tercero por correo,
            # WhatsApp o SMS no es haberlo presentado a los supervisores).
            session_db.add(SyncSubmission(
                supervisor_id=(getattr(d["sup"], "id", None) if d["sup"] is not None else None),
                promoter_id=(getattr(d["sup"], "promoter_id", None) if d["sup"] is not None else None),
                title=(song.title or "").strip() or "—", song_id=song.id,
                language=d["lang"], channel=("SUPERVISOR" if d["sup"] is not None else "EMAIL"),
                sent_by_nick=nick,
                notes=(None if d["sup"] is not None else d["email"]),
                payload={"email": d["email"], "name": d["name"]}))
        session_db.commit()
        if enviados:
            flash("Tema enviado a %d supervisor(es)." % enviados, "success")
        # ⚠️ Lo que NO ha salido se dice: un envío que falla no puede ser invisible.
        if fallidos:
            flash("No se pudo enviar a: %s." % ", ".join(fallidos[:8]), "warning")
        return redirect(request.referrer or url_for("syncros_view"))
    except Exception as exc:
        session_db.rollback()
        flash("No se pudo enviar: %s" % exc, "danger")
        return redirect(url_for("syncros_view"))
    finally:
        session_db.close()


def _sync_public_nav(session_db, song):
    """Las FLECHAS de la ficha pública de un tema: anterior y siguiente DEL REPERTORIO abierto.

    Solo salen cuando se ha llegado desde él (`?nav=rep`, que es lo que lleva el enlace de cada fila
    del listado): un enlace suelto que llega por correo no tiene listado que recorrer."""
    if (request.args.get("nav") or "").strip().lower() != "rep":
        return None
    try:
        vista = (request.args.get("ver") or "genero").strip().lower()
        if vista not in ("genero", "artista"):
            vista = "genero"
        genero = (request.args.get("genero") or "").strip()
        artista = _safe_uuid((request.args.get("artista") or "").strip())
        filas = _sync_public_repertoire_filtered(session_db, vista=vista, genero=genero,
                                                 artista=artista)[0]
        sid = str(song.id)
        idx = next((n for n, f in enumerate(filas) if f["id"] == sid), None)
        if idx is None:
            return None
        params = {"nav": "rep", "ver": vista}
        if genero:
            params["genero"] = genero
        if artista:
            params["artista"] = str(artista)
        if (request.args.get("lang") or "").strip().lower() in ("en", "eng"):
            params["lang"] = "en"
        prev_f = filas[idx - 1] if idx > 0 else None
        next_f = filas[idx + 1] if (idx + 1) < len(filas) else None
        volver = _external_url_for("public_sync_repertoire",
                                   **{k: v for k, v in params.items() if k != "nav"})
        return {
            "prev_url": (_sync_url_with(prev_f["share_url"], **params) if prev_f and prev_f.get("share_url") else ""),
            "prev_title": (prev_f or {}).get("title") or "",
            "next_url": (_sync_url_with(next_f["share_url"], **params) if next_f and next_f.get("share_url") else ""),
            "next_title": (next_f or {}).get("title") or "",
            "back_url": volver,
            "index": idx + 1,
            "total": len(filas),
        }
    except Exception:
        app.logger.exception("[syncro] no se pudo montar la navegación del repertorio")
        return None


@app.get("/syncro", endpoint="public_sync_song")
def public_sync_song():
    """Lo que ve quien recibe el enlace de un tema para sincronización.

    ⚠️ Mismo CUERPO que el correo (`_sync_pitch_html`) pero **sin el texto de presentación**, como
    pidió Dani. El idioma va en la URL (`?lang=en`) porque a un supervisor anglo se le manda el
    enlace en inglés."""
    session_db = db()
    try:
        song = _sync_song_by_token(session_db, request.args.get("token"))
        if song is None:
            abort(404)
        lang = _sync_lang("EN" if (request.args.get("lang") or "").strip().lower() in ("en", "eng") else "ES")
        ctx = _sync_song_context(session_db, song, lang=lang)
        token = (song.sync_share_token or "").strip()
        # El REPRODUCTOR de verdad: la MISMA fila que las demos y las playlists, empotrada debajo
        # de los datos (`player_html`). Así se escucha igual en toda la app.
        fila = (_sync_song_rows(session_db, [song]) or [{}])[0]
        # ⚠️ Abajo va SOLO el reproductor (play + barra + letra + descarga): la portada, el título y
        # el artista ya están arriba en la tarjeta y con la fila entera se DUPLICABAN.
        reproductor = (render_template("_sync_song_player.html", row=fila,
                                       play_label=ctx["t"]["play"], lyrics_label=ctx["t"]["lyrics"],
                                       download_label=ctx["t"]["download"])
                       if fila.get("audio_url") else "")
        cuerpo = _sync_pitch_html(
            ctx, with_intro=False,                      # en el enlace NO va el texto de presentación
            player_html=reproductor,
            # Con reproductor, la letra y la descarga ya van en él (solo icono).
            download_url=("" if reproductor else (fila.get("download_url") or "")),
            lyrics_url=("" if reproductor else ("#letra" if ctx["has_lyrics"] else "")),
            repertoire_url=_external_url_for("public_sync_repertoire",
                                             **({"lang": "en"} if ctx["lang"] == "EN" else {})),
            one_stop=bool(fila.get("one_stop")))
        return render_template(
            "public_sync_song.html", ctx=ctx, body_html=cuerpo,
            # Anterior/siguiente DEL REPERTORIO (solo si se ha llegado desde él).
            sync_nav=_sync_public_nav(session_db, song),
            og_title=_sync_og_title(ctx),
            og_description=_sync_og_description(ctx, one_stop=bool(fila.get("one_stop"))),
            og_image_url=_external_url_for("public_sync_song_og_image", token=token))
    finally:
        session_db.close()


def _sync_public_repertoire_filtered(session_db, *, vista: str = "genero", genero: str = "",
                                     artista=None):
    """El repertorio ABIERTO ya filtrado: `(filas, generos, artistas, elegido, titulo)`.

    ⚠️ Punto único: lo usan la landing y las FLECHAS de anterior/siguiente de la ficha pública, así
    que «el siguiente» es el que está debajo en la lista que se está mirando."""
    canciones, mapa_os = _sync_repertoire_songs(session_db)
    filas = _sync_song_rows(session_db, canciones, one_stop_map=mapa_os)

    # Galletas por GÉNERO (con su número) y rejilla de ARTISTAS (con su foto).
    generos, artistas = {}, {}
    mapa_art = {str(a.id): a for c in canciones for a in (getattr(c, "artists", None) or [])}
    for f in filas:
        for g in f["genres"]:
            d = generos.setdefault(_norm_text_key(g), {"name": g, "count": 0,
                                                       "icon": _sync_genre_icon(g)})
            d["count"] += 1
        for aid in f["artist_ids"]:
            d = artistas.setdefault(aid, {"id": aid, "count": 0,
                                          "name": (getattr(mapa_art.get(aid), "name", "") or "").strip(),
                                          "photo": (getattr(mapa_art.get(aid), "photo_url", "") or "").strip()})
            d["count"] += 1

    elegido, titulo_sel = None, ""
    if vista == "artista" and artista:
        filas = [f for f in filas if str(artista) in f["artist_ids"]]
        elegido = mapa_art.get(str(artista))
        titulo_sel = (getattr(elegido, "name", "") or "").strip()
    elif genero:
        clave = _norm_text_key(genero)
        filas = [f for f in filas if clave in {_norm_text_key(g) for g in f["genres"]}]
        titulo_sel = genero
    return filas, generos, artistas, elegido, titulo_sel


@app.get("/repertorio-sincronizaciones", endpoint="public_sync_repertoire")
def public_sync_repertoire():
    """LANDING pública con TODO el repertorio para sincronizaciones.

    Se llega desde la viñeta de contacto de cualquier tema. Se ve por GÉNEROS (galletas con su icono
    y cuántos temas hay) o por ARTISTAS (con su foto), y cada tema lleva su botón de escuchar, su
    letra y su descarga; al pinchar el tema se abre SU página de syncro (la misma que se comparte).
    """
    session_db = db()
    try:
        lang = _sync_lang("EN" if (request.args.get("lang") or "").strip().lower() in ("en", "eng") else "ES")
        t = SYNC_TEXTS[lang]
        vista = (request.args.get("ver") or "genero").strip().lower()
        if vista not in ("genero", "artista"):
            vista = "genero"
        genero = (request.args.get("genero") or "").strip()
        artista = _safe_uuid((request.args.get("artista") or "").strip())

        filas, generos_d, artistas_d, elegido, titulo_sel = _sync_public_repertoire_filtered(
            session_db, vista=vista, genero=genero, artista=artista)
        generos, artistas = generos_d, artistas_d

        # Las FLECHAS de la ficha pública recorren ESTE listado: el enlace de cada tema se lleva
        # consigo desde dónde se ha abierto (`nav=rep` + los filtros de la pantalla).
        nav_pub = {"nav": "rep", "ver": vista}
        if genero:
            nav_pub["genero"] = genero
        if artista:
            nav_pub["artista"] = str(artista)
        if lang == "EN":
            nav_pub["lang"] = "en"
        for f in filas:
            if f.get("share_url"):
                f["share_url"] = _sync_url_with(f["share_url"], **nav_pub)

        return render_template(
            "public_sync_repertoire.html", lang=lang, t=t,
            brand_logos=_sync_brand_logos(session_db),
            rows=(filas if (titulo_sel or request.args.get("todos")) else []),
            genres=sorted(generos.values(), key=lambda d: (-d["count"], _norm_text_key(d["name"]))),
            artists=sorted(artistas.values(), key=lambda d: _norm_text_key(d["name"])),
            view=vista, selected=titulo_sel, selected_photo=(getattr(elegido, "photo_url", "") or ""),
            total=len(filas),
            og_title=t["repertoire_title"],
            og_image_url=_external_url_for("og_default_image"))
    finally:
        session_db.close()


